(25, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.Link', 'Link', 1, 3, 18, 0, 0, 0, '', 'link.js', '', '', '[\n  {\n    "name": "title",\n    "type": "text",\n    "importance": "high",\n    "label": "Title"\n  },\n  {\n    "name": "linkWidget",\n    "type": "group",\n    "importance": "high",\n    "widget": "linkWidget",\n    "fields": [\n      {\n        "name": "protocol",\n        "type": "select",\n        "importance": "high",\n        "label": "Protocol",\n        "options": [\n          {\n            "value": "http://",\n            "label": "http://"\n          },\n          {\n            "value": "https://",\n            "label": "https://"\n          },\n          {\n            "value": "/",\n            "label": "(root relative)"\n          },\n          {\n            "value": "other",\n            "label": "other"\n          }\n        ],\n        "optional": true,\n        "default": "https://"\n      },\n      {\n        "name": "url",\n        "type": "text",\n        "importance": "high",\n        "label": "URL"\n      }\n    ]\n  }\n]', '', 0, '{"disable":true,"disableExtraTitleField":true}', NULL),
(26, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.MarkTheWords', 'Mark the Words', 1, 11, 9, 1, 0, 0, 'iframe', 'scripts/keyboard-nav.js, scripts/xAPI-generator.js, scripts/word.js, scripts/mark-the-words.js', 'styles/mark-the-words.css', '', '[\n  {\n    "name": "media",\n    "type": "group",\n    "label": "Media",\n    "importance": "medium",\n    "fields": [\n      {\n        "name": "type",\n        "type": "library",\n        "label": "Type",\n        "importance": "medium",\n        "options": [\n          "H5P.Image 1.1",\n          "H5P.Video 1.6",\n          "H5P.Audio 1.5"\n        ],\n        "optional": true,\n        "description": "Optional media to display above the question."\n      },\n      {\n        "name": "disableImageZooming",\n        "type": "boolean",\n        "label": "Disable image zooming",\n        "importance": "low",\n        "default": false,\n        "optional": true,\n        "widget": "showWhen",\n        "showWhen": {\n          "rules": [\n            {\n              "field": "type",\n              "equals": "H5P.Image 1.1"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    "label": "Task description",\n    "importance": "high",\n    "name": "taskDescription",\n    "type": "text",\n    "widget": "html",\n    "description": "Describe how the user should solve the task.",\n    "placeholder": "Click on all the verbs in the text that follows.",\n    "enterMode": "p",\n    "tags": [\n      "strong",\n      "em",\n      "u",\n      "a",\n      "ul",\n      "ol",\n      "h2",\n      "h3",\n      "hr",\n      "pre",\n      "code"\n    ]\n  },\n  {\n    "label": "Textfield",\n    "importance": "high",\n    "name": "textField",\n    "type": "text",\n    "widget": "html",\n    "tags": [\n      "p",\n      "br",\n      "strong",\n      "em",\n      "code"\n    ],\n    "placeholder": "This is an answer: *answer*.",\n    "description": "",\n    "important": {\n      "description": "<ul><li>Correct words are marked with asterisks (*) before and after the word.</li><li>Asterisks can be added within marked words by adding another asterisk, *correctword*** =&gt; correctword*.</li><li>Only words may be marked as correct. Not phrases.</li></ul>",\n      "example": "The correct words are marked like this: *correctword*, an asterisk is written like this: *correctword***."\n    }\n  },\n  {\n    "name": "overallFeedback",\n    "type": "group",\n    "label": "Overall Feedback",\n    "importance": "low",\n    "expanded": true,\n    "fields": [\n      {\n        "name": "overallFeedback",\n        "type": "list",\n        "widgets": [\n          {\n            "name": "RangeList",\n            "label": "Default"\n          }\n        ],\n        "importance": "high",\n        "label": "Define custom feedback for any score range",\n        "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n        "entity": "range",\n        "min": 1,\n        "defaultNum": 1,\n        "optional": true,\n        "field": {\n          "name": "overallFeedback",\n          "type": "group",\n          "importance": "low",\n          "fields": [\n            {\n              "name": "from",\n              "type": "number",\n              "label": "Score Range",\n              "min": 0,\n              "max": 100,\n              "default": 0,\n              "unit": "%"\n            },\n            {\n              "name": "to",\n              "type": "number",\n              "min": 0,\n              "max": 100,\n              "default": 100,\n              "unit": "%"\n            },\n            {\n              "name": "feedback",\n              "type": "text",\n              "label": "Feedback for defined score range",\n              "importance": "low",\n              "placeholder": "Fill in the feedback",\n              "optional": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    "label": "Text for \\"Check\\" button",\n    "importance": "low",\n    "name": "checkAnswerButton",\n    "type": "text",\n    "default": "Check",\n    "common": true\n  },\n  {\n    "label": "Text for \\"Submit\\" button",\n    "importance": "low",\n    "name": "submitAnswerButton",\n    "type": "text",\n    "default": "Submit",\n    "common": true\n  },\n  {\n    "label": "Text for \\"Retry\\" button",\n    "importance": "low",\n    "name": "tryAgainButton",\n    "type": "text",\n    "default": "Retry",\n    "common": true\n  },\n  {\n    "label": "Text for \\"Show solution\\" button",\n    "importance": "low",\n    "name": "showSolutionButton",\n    "type": "text",\n    "default": "Show solution",\n    "common": true\n  },\n  {\n    "name": "behaviour",\n    "importance": "low",\n    "type": "group",\n    "label": "Behavioural settings.",\n    "description": "These options will let you control how the task behaves.",\n    "optional": true,\n    "fields": [\n      {\n        "name": "enableRetry",\n        "type": "boolean",\n        "label": "Enable \\"Retry\\"",\n        "importance": "low",\n        "default": true\n      },\n      {\n        "name": "enableSolutionsButton",\n        "type": "boolean",\n        "label": "Enable \\"Show solution\\" button",\n        "importance": "low",\n        "default": true\n      },\n      {\n        "name": "enableCheckButton",\n        "type": "boolean",\n        "label": "Enable \\"Check\\" button",\n        "widget": "none",\n        "importance": "low",\n        "default": true,\n        "optional": true\n      },\n      {\n        "name": "showScorePoints",\n        "type": "boolean",\n        "label": "Show score points",\n        "description": "Show points earned for each answer.",\n        "importance": "low",\n        "default": true\n      }\n    ]\n  },\n  {\n    "label": "Correct answer text",\n    "importance": "low",\n    "name": "correctAnswer",\n    "type": "text",\n    "default": "Correct!",\n    "description": "Text used to indicate that an answer is correct",\n    "common": true\n  },\n  {\n    "label": "Incorrect answer text",\n    "importance": "low",\n    "name": "incorrectAnswer",\n    "type": "text",\n    "default": "Incorrect!",\n    "description": "Text used to indicate that an answer is incorrect",\n    "common": true\n  },\n  {\n    "label": "Missed answer text",\n    "importance": "low",\n    "name": "missedAnswer",\n    "type": "text",\n    "default": "Answer not found!",\n    "description": "Text used to indicate that an answer is missing",\n    "common": true\n  },\n  {\n    "label": "Description for Display Solution",\n    "importance": "low",\n    "name": "displaySolutionDescription",\n    "type": "text",\n    "default": "Task is updated to contain the solution.",\n    "description": "This text tells the user that the tasks has been updated with the solution.",\n    "common": true\n  },\n  {\n    "name": "scoreBarLabel",\n    "type": "text",\n    "label": "Textual representation of the score bar for those using a readspeaker",\n    "default": "You got :num out of :total points",\n    "importance": "low",\n    "common": true\n  },\n  {\n    "name": "a11yFullTextLabel",\n    "type": "text",\n    "label": "Label for the full readable text for assistive technologies",\n    "default": "Full readable text",\n    "importance": "low",\n    "common": true\n  },\n  {\n    "name": "a11yClickableTextLabel",\n    "type": "text",\n    "label": "Label for the text where words can be marked for assistive technologies",\n    "default": "Full text where words can be marked",\n    "importance": "low",\n    "common": true\n  },\n  {\n    "name": "a11ySolutionModeHeader",\n    "type": "text",\n    "label": "Solution mode header for assistive technologies",\n    "default": "Solution mode",\n    "importance": "low",\n    "common": true\n  },\n  {\n    "name": "a11yCheckingHeader",\n    "type": "text",\n    "label": "Checking mode header for assistive technologies",\n    "default": "Checking mode",\n    "importance": "low",\n    "common": true\n  },\n  {\n    "name": "a11yCheck",\n    "type": "text",\n    "label": "Assistive technology description for \\"Check\\" button",\n    "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered.",\n    "importance": "low",\n    "common": true\n  },\n  {\n    "name": "a11yShowSolution",\n    "type": "text",\n    "label": "Assistive technology description for \\"Show Solution\\" button",\n    "default": "Show the solution. The task will be marked with its correct solution.",\n    "importance": "low",\n    "common": true\n  },\n  {\n    "name": "a11yRetry",\n    "type": "text",\n    "label": "Assistive technology description for \\"Retry\\" button",\n    "default": "Retry the task. Reset all responses and start the task over again.",\n    "importance": "low",\n    "common": true\n  }\n]', '', 1, NULL, NULL),
(27, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.MaterialDesignIcons', 'Material Design Icons', 1, 0, 0, 0, 0, 0, '', '', 'h5p-material-icons.css', '', '', '', 0, NULL, NULL),
(28, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.MultiMediaChoice', 'Multimedia Choice', 0, 3, 44, 1, 0, 0, 'iframe', 'dist/h5p-multi-media-choice.js', 'dist/h5p-multi-media-choice.css', '', '[\n  {\n    "name": "media",\n    "type": "group",\n    "label": "Media",\n    "importance": "medium",\n    "fields": [\n      {\n        "name": "type",\n        "type": "library",\n        "label": "Type",\n        "importance": "medium",\n        "options": [\n          "H5P.Image 1.1",\n          "H5P.Video 1.6",\n          "H5P.Audio 1.5"\n        ],\n        "optional": true,\n        "description": "Optional media to display above the question."\n      },\n      {\n        "name": "disableImageZooming",\n        "type": "boolean",\n        "label": "Disable image zooming",\n        "importance": "low",\n        "default": false,\n        "optional": true,\n        "widget": "showWhen",\n        "showWhen": {\n          "rules": [\n            {\n              "field": "type",\n              "equals": "H5P.Image 1.1"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    "name": "question",\n    "type": "text",\n    "importance": "high",\n    "widget": "html",\n    "label": "Question",\n    "enterMode": "p",\n    "tags": [\n      "strong",\n      "em",\n      "sub",\n      "sup",\n      "h2",\n      "h3",\n      "pre",\n      "code"\n    ]\n  },\n  {\n    "name": "options",\n    "type": "list",\n    "importance": "high",\n    "label": "Available options",\n    "entity": "option",\n    "min": 2,\n    "max": 20,\n    "defaultNum": 2,\n    "field": {\n      "name": "option",\n      "type": "group",\n      "label": "Option",\n      "importance": "high",\n      "fields": [\n        {\n          "name": "media",\n          "type": "library",\n          "label": "Media",\n          "optional": false,\n          "description": "Media to display as a choice.",\n          "options": [\n            "H5P.Image 1.1",\n            "H5P.Video 1.6",\n            "H5P.Audio 1.5"\n          ]\n        },\n        {\n          "name": "poster",\n          "type": "image",\n          "label": "Poster image",\n          "importance": "low",\n          "widget": "showWhen",\n          "showWhen": {\n            "rules": [\n              {\n                "field": "media",\n                "equals": "H5P.Audio 1.5"\n              }\n            ]\n          }\n        },\n        {\n          "name": "correct",\n          "type": "boolean",\n          "label": "Correct",\n          "importance": "low"\n        }\n      ]\n    }\n  },\n  {\n    "name": "overallFeedback",\n    "type": "group",\n    "label": "Overall Feedback",\n    "importance": "low",\n    "expanded": true,\n    "fields": [\n      {\n        "name": "overallFeedback",\n        "type": "list",\n        "widgets": [\n          {\n            "name": "RangeList",\n            "label": "Default"\n          }\n        ],\n        "importance": "high",\n        "label": "Define custom feedback for any score range",\n        "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n        "entity": "range",\n        "min": 1,\n        "defaultNum": 1,\n        "optional": true,\n        "field": {\n          "name": "overallFeedback",\n          "type": "group",\n          "importance": "low",\n          "fields": [\n            {\n              "name": "from",\n              "type": "number",\n              "label": "Score Range",\n              "min": 0,\n              "max": 100,\n              "default": 0,\n              "unit": "%"\n            },\n            {\n              "name": "to",\n              "type": "number",\n              "min": 0,\n              "max": 100,\n              "default": 100,\n              "unit": "%"\n            },\n            {\n              "name": "feedback",\n              "type": "text",\n              "label": "Feedback for defined score range",\n              "importance": "low",\n              "placeholder": "Fill in the feedback",\n              "optional": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    "name": "behaviour",\n    "type": "group",\n    "label": "Behavioural settings",\n    "importance": "low",\n    "description": "These options will let you control how the task behaves.",\n    "fields": [\n      {\n        "name": "enableRetry",\n        "label": "Enable \\"Retry\\" button",\n        "type": "boolean",\n        "importance": "low",\n        "default": true,\n        "optional": true\n      },\n      {\n        "name": "enableSolutionsButton",\n        "label": "Enable \\"Show Solution\\" button",\n        "type": "boolean",\n        "importance": "low",\n        "default": true,\n        "optional": true\n      },\n      {\n        "name": "confirmCheckDialog",\n        "label": "Show confirmation dialog on \\"Check\\"",\n        "importance": "low",\n        "type": "boolean",\n        "default": false,\n        "optional": true\n      },\n      {\n        "name": "confirmRetryDialog",\n        "label": "Show confirmation dialog on \\"Retry\\"",\n        "importance": "low",\n        "type": "boolean",\n        "default": false,\n        "optional": true\n      },\n      {\n        "name": "singlePoint",\n        "type": "boolean",\n        "label": "Give one point for the whole question",\n        "importance": "low",\n        "description": "Awards one point to the question if the percentage score is higher than the pass percentage",\n        "default": false\n      },\n      {\n        "label": "Require answer before the solution can be viewed",\n        "importance": "low",\n        "name": "showSolutionsRequiresInput",\n        "type": "boolean",\n        "default": true,\n        "optional": true\n      },\n      {\n        "name": "questionType",\n        "type": "select",\n        "label": "Question Type",\n        "importance": "low",\