(39, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.Video', 'Video', 1, 6, 66, 0, 0, 0, '', 'scripts/vimeo.js, scripts/youtube.js, scripts/panopto.js, scripts/echo360.js, scripts/html5.js, scripts/video.js', 'styles/video.css', '', '[\n  {\n    "name": "sources",\n    "type": "video",\n    "label": "Video sources",\n    "importance": "high",\n    "description": "To ensure that the video works in all browsers you should add both WebM and MP4 formatted sources.",\n    "disableCopyright": true\n  },\n  {\n    "name": "visuals",\n    "type": "group",\n    "label": "Visuals",\n    "importance": "medium",\n    "fields": [\n      {\n        "name": "poster",\n        "type": "image",\n        "label": "Poster image",\n        "importance": "low"\n      },\n      {\n        "name": "fit",\n        "type": "boolean",\n        "label": "Fit video player to use all available space",\n        "importance": "low",\n        "default": true,\n        "description": "If not set the video player will have the same aspect ratio as the video."\n      },\n      {\n        "name": "controls",\n        "type": "boolean",\n        "label": "Show video player controls",\n        "importance": "low",\n        "default": true,\n        "description": "Add controls to the video player. This allows users to play, pause, etc."\n      }\n    ]\n  },\n  {\n    "name": "playback",\n    "type": "group",\n    "label": "Playback",\n    "importance": "medium",\n    "fields": [\n      {\n        "name": "autoplay",\n        "type": "boolean",\n        "label": "Auto-play video",\n        "importance": "low",\n        "default": false,\n        "description": "Start playing the video automatically. May not work on mobile devices."\n      },\n      {\n        "name": "loop",\n        "type": "boolean",\n        "label": "Loop video",\n        "importance": "low",\n        "default": false,\n        "description": "Automatically start the video over again when it ends."\n      }\n    ]\n  },\n  {\n    "name": "l10n",\n    "type": "group",\n    "label": "Video localization",\n    "importance": "low",\n    "common": true,\n    "fields": [\n      {\n        "name": "name",\n        "type": "text",\n        "label": "Name",\n        "importance": "low",\n        "default": "Video",\n        "description": "Helps identify content of this type."\n      },\n      {\n        "name": "loading",\n        "type": "text",\n        "label": "Loading",\n        "importance": "low",\n        "default": "Video player loading..."\n      },\n      {\n        "name": "noPlayers",\n        "type": "text",\n        "label": "No players found",\n        "importance": "low",\n        "default": "Found no video players that supports the given video format."\n      },\n      {\n        "name": "noSources",\n        "type": "text",\n        "label": "No sources",\n        "importance": "low",\n        "default": "Video is missing sources."\n      },\n      {\n        "name": "aborted",\n        "type": "text",\n        "label": "Aborted",\n        "importance": "low",\n        "default": "Media playback has been aborted."\n      },\n      {\n        "name": "networkFailure",\n        "type": "text",\n        "label": "Network failure",\n        "importance": "low",\n        "default": "Network failure."\n      },\n      {\n        "name": "cannotDecode",\n        "type": "text",\n        "label": "Cannot decode video source",\n        "importance": "low",\n        "default": "Unable to decode media."\n      },\n      {\n        "name": "formatNotSupported",\n        "type": "text",\n        "label": "Format not supported",\n        "importance": "low",\n        "default": "Video format not supported."\n      },\n      {\n        "name": "mediaEncrypted",\n        "type": "text",\n        "label": "Media encrypted",\n        "importance": "low",\n        "default": "Media encrypted."\n      },\n      {\n        "name": "unknownError",\n        "type": "text",\n        "label": "Unknown error",\n        "importance": "low",\n        "default": "Unknown error."\n      },\n      {\n        "name": "invalidYtId",\n        "type": "text",\n        "label": "Invalid YouTube ID",\n        "importance": "low",\n        "default": "Invalid YouTube ID."\n      },\n      {\n        "name": "unknownYtId",\n        "type": "text",\n        "label": "Unknown YouTube ID",\n        "importance": "low",\n        "default": "Unable to find video with the given YouTube ID."\n      },\n      {\n        "name": "restrictedYt",\n        "type": "text",\n        "label": "Restricted YouTube video",\n        "importance": "low",\n        "default": "The owner of this video does not allow it to be embedded."\n      }\n    ]\n  },\n  {\n    "name": "a11y",\n    "type": "group",\n    "label": "Accessibility",\n    "importance": "medium",\n    "fields": [\n      {\n        "name": "videoTrack",\n        "type": "list",\n        "label": "Add video track",\n        "importance": "low",\n        "optional": true,\n        "entity": "Track",\n        "min": 0,\n        "field": {\n          "name": "track",\n          "type": "group",\n          "label": "Track",\n          "importance": "low",\n          "expanded": false,\n          "fields": [\n            {\n              "name": "label",\n              "type": "text",\n              "label": "Track label",\n              "importance": "low",\n              "optional": true\n            },\n            {\n              "name": "kind",\n              "type": "select",\n              "label": "Type kind, refer to <a target=\\"_blank\\" href=\\"https://html.spec.whatwg.org/multipage/embedded-content.html#the-track-element\\">HTML living standard</a>",\n              "importance": "low",\n              "default": "descriptions",\n              "options": [\n                {\n                  "value": "subtitles",\n                  "label": "Subtitles"\n                },\n                {\n                  "value": "captions",\n                  "label": "Captions"\n                },\n                {\n                  "value": "descriptions",\n                  "label": "Descriptions"\n                },\n                {\n                  "value": "chapters",\n                  "label": "Chapters"\n                }\n              ]\n            },\n            {\n              "name": "srcLang",\n              "type": "text",\n              "label": "Source language, must be defined for subtitles",\n              "importance": "low",\n              "default": "en",\n              "description": "Must be a valid BCP 47 language tag. If the kind attribute is set to subtitles, then srclang must be defined."\n            },\n            {\n              "name": "track",\n              "type": "file",\n              "label": "Track file (WebVTT)",\n              "importance": "low"\n            }\n          ]\n        }\n      }\n    ]\n  }\n]\n', '', 1, NULL, NULL),
