(54, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.AudioRecorder', 'Audio Recorder', 1, 0, 33, 1, 0, 0, 'iframe', 'dist/h5p-audio-recorder.js', 'fonts/h5p-audio-recorder-font-open-sans.css', '', '[\n  {\n    "label": "Task Description",\n    "importance": "high",\n    "name": "title",\n    "type": "text",\n    "widget": "textarea",\n    "description": "Optional text to display above the audio recorder",\n    "optional": true\n  },\n  {\n    "label": "Localization",\n    "name": "l10n",\n    "type": "group",\n    "common": true,\n    "fields": [\n      {\n        "name": "recordAnswer",\n        "label": "Record button text",\n        "type": "text",\n        "default": "Record"\n      },\n      {\n        "name": "pause",\n        "label": "Pause button text",\n        "type": "text",\n        "default": "Pause"\n      },\n      {\n        "name": "continue",\n        "label": "Continue button text",\n        "type": "text",\n        "default": "Continue"\n      },\n      {\n        "name": "download",\n        "label": "Download button text",\n        "type": "text",\n        "default": "Download"\n      },\n      {\n        "name": "done",\n        "label": "Done button text",\n        "type": "text",\n        "default": "Done"\n      },\n      {\n        "name": "retry",\n        "label": "Retry button text",\n        "type": "text",\n        "default": "Retry"\n      },\n      {\n        "name": "microphoneNotSupported",\n        "label": "Microphone not supported error message",\n        "type": "text",\n        "default": "Microphone not supported. Make sure you are using a browser that allows microphone recording."\n      },\n      {\n        "name": "microphoneInaccessible",\n        "label": "Microphone inaccessible error message",\n        "type": "text",\n        "default": "Microphone is not accessible. Make sure that the browser microphone is enabled."\n      },\n      {\n        "name": "insecureNotAllowed",\n        "type": "text",\n        "label": "Message displayed when insecure access is not allowed",\n        "description": "Some browsers do not allow using the microphone when the page is served using HTTP. This message will be displayed if that is the case",\n        "default": "Access to microphone is not allowed in your browser since this page is not served using HTTPS. Please contact the author, and ask him to make this available using HTTPS"\n      },\n      {\n        "name": "statusReadyToRecord",\n        "label": "Ready to record status message",\n        "type": "text",\n        "default": "Press a button below to record your answer."\n      },\n      {\n        "name": "statusRecording",\n        "label": "Recording status message",\n        "type": "text",\n        "default": "Recording..."\n      },\n      {\n        "name": "statusPaused",\n        "label": "Paused status message",\n        "type": "text",\n        "default": "Recording paused. Press a button to continue recording."\n      },\n      {\n        "name": "statusFinishedRecording",\n        "label": "Finished recording status message",\n        "type": "text",\n        "default": "You have successfully recorded your answer! Listen to the recording below."\n      },\n      {\n        "name": "downloadRecording",\n        "label": "Download recording message",\n        "type": "text",\n        "default": "Download this recording or retry."\n      },\n      {\n        "name": "retryDialogHeaderText",\n        "label": "Retry dialog header text",\n        "type": "text",\n        "default": "Retry recording?"\n      },\n      {\n        "name": "retryDialogBodyText",\n        "label": "Retry dialog body text",\n        "type": "text",\n        "default": "By pressing \\"Retry\\" you will lose your current recording."\n      },\n      {\n        "name": "retryDialogConfirmText",\n        "label": "Retry dialog confirm text",\n        "type": "text",\n        "default": "Retry"\n      },\n      {\n        "name": "retryDialogCancelText",\n        "label": "Retry dialog cancel text",\n        "type": "text",\n        "default": "Cancel"\n      },\n      {\n        "name": "statusCantCreateTheAudioFile",\n        "label": "Can''t create audio file status message",\n        "type": "text",\n        "default": "Can''t create the audio file."\n      }\n    ]\n  }\n]\n', '', 1, NULL, NULL),
(55, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.ContinuousText', 'Continuous Text', 1, 2, 16, 0, 0, 0, '', 'scripts/ct.js', '', '', '[\n  {\n    "name": "text",\n    "type": "text",\n    "importance": "high",\n    "widget": "html",\n    "label": "Text",\n    "tags": [\n      "strong",\n      "em",\n      "del",\n      "br",\n      "p",\n      "a",\n      "h2",\n      "h3",\n      "pre",\n      "code"\n    ]\n  }\n]\n', '', 0, NULL, NULL),
(56, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.CoursePresentation', 'Course Presentation', 1, 26, 3, 1, 0, 1, 'iframe', 'dist/h5p-course-presentation.js', 'dist/h5p-course-presentation.css', '', '[\n  {\n    "name": "presentation",\n    "type": "group",\n    "importance": "high",\n    "widget": "coursepresentation",\n    "fields": [\n      {\n        "name": "slides",\n        "importance": "high",\n        "type": "list",\n        "field": {\n          "name": "slide",\n          "importance": "high",\n          "type": "group",\n          "fields": [\n            {\n              "name": "elements",\n              "importance": "high",\n              "type": "list",\n              "field": {\n                "name": "element",\n                "importance": "high",\n                "type": "group",\n                "fields": [\n                  {\n                    "name": "x",\n                    "importance": "low",\n                    "type": "number",\n                    "widget": "none"\n                  },\n                  {\n                    "name": "y",\n                    "importance": "low",\n                    "type": "number",\n                    "widget": "none"\n                  },\n                  {\n                    "name": "width",\n                    "importance": "low",\n                    "type": "number",\n                    "widget": "none",\n                    "optional": true\n                  },\n                  {\n                    "name": "height",\n                    "importance": "low",\n                    "type": "number",\n                    "widget": "none",\n                    "optional": true\n                  },\n                  {\n                    "name": "action",\n                    "type": "library",\n                    "importance": "high",\n                    "options": [\n                      "H5P.AdvancedText 1.1",\n                      "H5P.Link 1.3",\n                      "H5P.Image 1.1",\n                      "H5P.Shape 1.0",\n                      "H5P.Video 1.6",\n                      "H5P.Audio 1.5",\n                      "H5P.Blanks 1.14",\n                      "H5P.SingleChoiceSet 1.11",\n                      "H5P.MultiChoice 1.16",\n                      "H5P.TrueFalse 1.8",\n                      "H5P.DragQuestion 1.14",\n                      "H5P.Summary 1.10",\n                      "H5P.DragText 1.10",\n                      "H5P.MarkTheWords 1.11",\n                      "H5P.Dialogcards 1.9",\n                      "H5P.ContinuousText 1.2",\n                      "H5P.ExportableTextArea 1.3",\n                      "H5P.Table 1.2",\n                      "H5P.InteractiveVideo 1.27",\n                      "H5P.TwitterUserFeed 1.0",\n                      "H5P.AudioRecorder 1.0",\n                      "H5P.MultiMediaChoice 0.3"\n                    ],\n                    "optional": true\n                  },\n                  {\n                    "name": "solution",\n                    "type": "text",\n                    "widget": "html",\n                    "optional": true,\n                    "label": "Comments",\n                    "importance": "low",\n                    "description": "The comments are shown when the user displays the suggested answers for all slides.",\n                    "enterMode": "p",\n                    "tags": [\n                      "strong",\n                      "em",\n                      "del",\n                      "a",\n                      "ul",\n                      "ol",\n                      "h2",\n                      "h3",\n                      "hr",\n                      "pre",\n                      "code"\n                    ]\n                  },\n                  {\n                    "name": "alwaysDisplayComments",\n                    "type": "boolean",\n                    "label": "Always display comments",\n                    "importance": "low",\n                    "optional": true\n                  },\n                  {\n                    "name": "backgroundOpacity",\n                    "type": "number",\n                    "label": "Background Opacity",\n                    "importance": "low",\n                    "min": 0,\n                    "max": 100,\n                    "step": 5,\n                    "default": 0,\n                    "optional": true\n                  },\n                  {\n                    "name": "displayAsButton",\n                    "type": "boolean",\n                    "label": "Display as button",\n                    "importance": "medium",\n                    "default": false,\n                    "optional": true\n                  },\n                  {\n                    "name": "buttonSize",\n                    "type": "select",\n                    "label": "Button size",\n                    "importance": "low",\n                    "optional": false,\n                    "default": "big",\n                    "options": [\n                      {\n                        "value": "small",\n                        "label": "Small"\n                      },\n                      {\n                        "value": "big",\n                        "label": "Big"\n                      }\n                    ]\n                  },\n                  {\n                    "name": "title",\n                    "type": "text",\n                    "optional": true,\n                    "label": "Title",\n                    "importance": "medium"\n                  },\n                  {\n                    "name": "goToSlideType",\n                    "type": "select",\n                    "label": "Go to",\n                    "importance": "medium",\n                    "optional": false,\n                    "options": [\n                      {\n                        "value": "specified",\n                        "label": "Specific slide number"\n                      },\n                      {\n                        "value": "next",\n                        "label": "Next slide"\n                      },\n                      {\n                        "value": "previous",\n                        "label": "Previous slide"\n                      }\n                    ],\n                    "default": "specified"\n                  },\n                  {\n                    "name": "goToSlide",\n                    "type": "number",\n                    "label": "Specific slide number",\n                    "description": "Only applicable when ''Specific slide number'' is selected",\n                    "importance": "low",\n                    "min": 1,\n                    "optional": true\n                  },\n                  {\n                    "name": "invisible",\n                    "type": "boolean",\n                    "label": "Invisible",\n                    "importance": "low",\n                    "description": "Default cursor, no title and no tab index. Warning: Users with disabilities or keyboard only users will have trouble using this element.",\n                    "default": false\n                  }\n                ]\n              }\n            },\n            {\n              "name": "keywords",\n              "importance": "low",\n              "type": "list",\n              "optional": true,\n              "field": {\n                "name": "keyword",\n                "importance": "low",\n                "type": "group",\n                "optional": true,\n                "fields": [\n                  {\n                    "name": "main",\n                    "importance": "low",\n                    "type": "text",\n                    "optional": true\n                  },\n                  {\n                    "name": "subs",\n                    "importance": "low",\n                    "type": "list",\n                    "optional": true,\n                    "field": {\n                      "name": "keyword",\n                      "importance": "low",\n                      "type": "text"\n                    }\n                  }\n                ]\n              }\n            },\n            {\n              "name": "slideBackgroundSelector",\n              "importance": "medium",\n              "type": "group",\n              "widget": "radioSelector",\n              "fields": [\n                {\n                  "name": "imageSlideBackground",\n                  "type": "image",\n                  "label": "Image",\n                  "importance": "medium",\n                  "optional": true,\n                  "description": "Image background should have a 2:1 width to height ratio to avoid stretching. High resolution images will display better on larger screens."\n                },\n                {\n                  "name": "fillSlideBackground",\n                  "importance": "medium",\n                  "type": "text",\n                  "widget": "colorSelector",\n                  "label": "Pick a color",\n                  "spectrum": {\n                    "flat": true,\n                    "showInput": true,\n                    "allowEmpty": true,\n                    "showButtons": false\n                  },\n                  "default": null,\n                  "optional": true\n                }\n              ]\n            }\n          ]\n        }\n      },\n      {\n        "name": "ct",\n        "importance": "low",\n        "type": "text",\n        "widget": "none",\n        "optional": true,\n        "tags": [\n          "strong",\n          "em",\n          "del",\n          "br",\n          "p",\n          "a",\n          "h2",\n          "h3",\n          "pre",\n          "code"\n        ]\n      },\n      {\n        "name": "keywordListEnabled",\n        "type": "boolean",\n        "label": "Keyword list",\n        "importance": "low",\n    