(58, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.ExportableTextArea', 'Exportable Text Area', 1, 3, 18, 0, 0, 0, '', 'dist/h5p-exportable-text-area.js', '', '', '[\n  {\n    "name": "label",\n    "type": "text",\n    "widget": "html",\n    "label": "Label",\n    "importance": "high",\n    "description": "Label/heading for answer when user exports all answers",\n    "enterMode": "p",\n    "tags": [\n      "strong",\n      "em",\n      "a",\n      "ul",\n      "ol",\n      "h2",\n      "h3",\n      "hr",\n      "pre",\n      "code"\n    ]\n  },\n  {\n    "name": "index",\n    "type": "number",\n    "widget": "none"\n  },\n  {\n    "name": "exportNotSupported",\n    "type": "text",\n    "importance": "low",\n    "label": "Export not supported label",\n    "default": "Export not supported on your device",\n    "common": true\n  },\n  {\n    "name": "exportComments",\n    "type": "boolean",\n    "importance": "low",\n    "label": "Include comments in the exported document",\n    "optional": true,\n    "default": false\n  }\n]\n', '', 0, '{"disable":false,"disableExtraTitleField":true}', NULL),
(59, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.Shape', 'Shapes', 1, 0, 5, 0, 0, 0, '', 'js/h5p-shape.js', 'css/h5p-shape.css', '', '[\n  {\n    "name": "type",\n    "type": "select",\n    "label": "Type",\n    "importance": "low",\n    "widget": "radioGroup",\n    "alignment": "horizontal",\n    "options": [\n      {\n        "value": "rectangle",\n        "label": "Rectangle"\n      },\n      {\n        "value": "circle",\n        "label": "Circle"\n      },\n      {\n        "value": "vertical-line",\n        "label": "Vertical line"\n      },\n      {\n        "value": "horizontal-line",\n        "label": "Horizontal line"\n      }\n    ],\n    "default": "rectangle"\n  },\n  {\n    "type": "group",\n    "name": "shape",\n    "widget": "showWhen",\n    "expanded": true,\n    "showWhen": {\n      "rules": [\n        {\n          "field": "type",\n          "equals": [\n            "rectangle",\n            "circle"\n          ]\n        }\n      ]\n    },\n    "fields": [\n      {\n        "name": "fillColor",\n        "type": "text",\n        "label": "Fill color",\n        "importance": "medium",\n        "optional": true,\n        "default": "#ffffff",\n        "widget": "colorSelector",\n        "showAplha": true,\n        "spectrum": {\n          "showInput": true,\n          "showAlpha": true,\n          "preferredFormat": "rgb"\n        },\n        "optional": true\n      },\n      {\n        "name": "borderColor",\n        "type": "text",\n        "label": "Border color",\n        "importance": "medium",\n        "optional": true,\n        "default": "#000000",\n        "widget": "colorSelector",\n        "spectrum": {\n          "showInput": true,\n          "showAlpha": true,\n          "preferredFormat": "rgb"\n        },\n        "optional": true\n      },\n      {\n        "name": "borderWidth",\n        "type": "select",\n        "label": "Border width",\n        "importance": "low",\n        "default": "0",\n        "optional": false,\n        "options": [\n          {\n            "value": "0",\n            "label": "0"\n          },\n          {\n            "value": "1",\n            "label": "1"\n          },\n          {\n            "value": "2",\n            "label": "2"\n          },\n          {\n            "value": "3",\n            "label": "3"\n          },\n          {\n            "value": "4",\n            "label": "4"\n          },\n          {\n            "value": "5",\n            "label": "5"\n          },\n          {\n            "value": "6",\n            "label": "6"\n          },\n          {\n            "value": "7",\n            "label": "7"\n          },\n          {\n            "value": "8",\n            "label": "8"\n          },\n          {\n            "value": "9",\n            "label": "9"\n          },\n          {\n            "value": "10",\n            "label": "10"\n          },\n          {\n            "value": "11",\n            "label": "11"\n          },\n          {\n            "value": "12",\n            "label": "12"\n          },\n          {\n            "value": "13",\n            "label": "13"\n          },\n          {\n            "value": "14",\n            "label": "14"\n          },\n          {\n            "value": "15",\n            "label": "15"\n          },\n          {\n            "value": "16",\n            "label": "16"\n          },\n          {\n            "value": "17",\n            "label": "17"\n          },\n          {\n            "value": "18",\n            "label": "18"\n          },\n          {\n            "value": "19",\n            "label": "19"\n          },\n          {\n            "value": "20",\n            "label": "20"\n          },\n          {\n            "value": "21",\n            "label": "21"\n          },\n          {\n            "value": "22",\n            "label": "22"\n          },\n          {\n            "value": "23",\n            "label": "23"\n          },\n          {\n            "value": "24",\n            "label": "24"\n          }\n        ]\n      },\n      {\n        "name": "borderStyle",\n        "type": "select",\n        "label": "Border style",\n        "importance": "low",\n        "default": "solid",\n        "optional": false,\n        "options": [\n          {\n            "value": "solid",\n            "label": "Solid"\n          },\n          {\n            "value": "dotted",\n            "label": "Dotted"\n          },\n          {\n            "value": "dashed",\n            "label": "Dashed"\n          },\n          {\n            "value": "double",\n            "label": "Double"\n          },\n          {\n            "value": "inset",\n            "label": "Inset"\n          },\n          {\n            "value": "outset",\n            "label": "Outset"\n          }\n        ]\n      },\n      {\n        "name": "borderRadius",\n        "type": "select",\n        "label": "Border radius",\n        "importance": "low",\n        "default": "0",\n        "optional": false,\n        "options": [\n          {\n            "value": "0",\n            "label": "0"\n          },\n          {\n            "value": "1",\n            "label": "1"\n          },\n          {\n            "value": "2",\n            "label": "2"\n          },\n          {\n            "value": "3",\n            "label": "3"\n          },\n          {\n            "value": "4",\n            "label": "4"\n          },\n          {\n            "value": "5",\n            "label": "5"\n          },\n          {\n            "value": "6",\n            "label": "6"\n          },\n          {\n            "value": "7",\n            "label": "7"\n          },\n          {\n            "value": "8",\n            "label": "8"\n          },\n          {\n            "value": "9",\n            "label": "9"\n          },\n          {\n            "value": "10",\n            "label": "10"\n          },\n          {\n            "value": "11",\n            "label": "11"\n          },\n          {\n            "value": "12",\n            "label": "12"\n          },\n          {\n            "value": "13",\n            "label": "13"\n          },\n          {\n            "value": "14",\n            "label": "14"\n          },\n          {\n            "value": "15",\n            "label": "15"\n          },\n          {\n            "value": "16",\n            "label": "16"\n          },\n          {\n            "value": "17",\n            "label": "17"\n          },\n          {\n            "value": "18",\n            "label": "18"\n          },\n          {\n            "value": "19",\n            "label": "19"\n          },\n          {\n            "value": "20",\n            "label": "20"\n          }\n        ],\n        "widget": "showWhen",\n        "showWhen": {\n          "rules": [\n            {\n              "field": "../type",\n              "equals": "rectangle"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    "type": "group",\n    "name": "line",\n    "widget": "showWhen",\n    "expanded": true,\n    "showWhen": {\n      "rules": [\n        {\n          "field": "type",\n          "equals": [\n            "vertical-line",\n            "horizontal-line"\n          ]\n        }\n      ]\n    },\n    "fields": [\n      {\n        "name": "borderColor",\n        "type": "text",\n        "label": "Line color",\n        "importance": "medium",\n        "optional": true,\n        "default": "#000000",\n        "widget": "colorSelector",\n        "optional": true,\n        "spectrum": {\n          "showInput": true,\n          "showAlpha": true,\n          "preferredFormat": "rgb"\n        }\n      },\n      {\n        "name": "borderWidth",\n        "type": "select",\n        "label": "Line width",\n        "importance": "low",\n        "default": "1",\n        "optional": false,\n        "options": [\n          {\n            "value": "1",\n            "label": "1"\n          },\n          {\n            "value": "2",\n            "label": "2"\n          },\n          {\n            "value": "3",\n            "label": "3"\n          },\n          {\n            "value": "4",\n            "label": "4"\n          },\n          {\n            "value": "5",\n            "label": "5"\n          },\n          {\n            "value": "6",\n            "label": "6"\n          },\n          {\n            "value": "7",\n            "label": "7"\n          },\n          {\n            "value": "8",\n            "label": "8"\n          },\n          {\n            "value": "9",\n            "label": "9"\n          },\n          {\n            "value": "10",\n            "label": "10"\n          },\n          {\n            "value": "11",\n            "label": "11"\n          },\n          {\n            "value": "12",\n            "label": "12"\n          },\n          {\n            "value": "13",\n            "label": "13"\n          },\n          {\n            "value": "14",\n            "label": "14"\n          },\n          {\n            "value": "15",\n            "label": "15"\n          },\n          {\n            "value": "16",\n            "label": "16"\n          },\n          {\n            "value": "17",\n            "label": "17"\n          },\n          {\n            "value": "18",\n            "label": "18"\n          },\n          {\n            "value": "19",\n            "label": "19"\n          },\n          {\n            "value": "20",\n            "label": "20"\n          },\n          {\n            "value": "21",\n            "label": "21"\n          },\n          {\n            "value": "22",\n            "label": "22"\n          },\n          {\n            "value": "23",\n            "label": "23"\n          },\n          {\n            "value": "24",\n            "label": "24"\n          }\n        ]\n      },\n      {\n        "name": "borderStyle",\n        "type": "select",\n        "label": "Line style",\n        "importance": "low",\n        "default": "solid",\n        "optional": false,\n        "options": [\n          {\n            "value": "solid",\n            "label": "Solid"\n          },\n          {\n            "value": "dotted",\n            "label": "Dotted"\n          },\n          {\n            "value": "dashed",\n            "label": "Dashed"\n          },\n          {\n            "value": "double",\n            "label": "Double"\n          }\n        ]\n      }\n    ]\n  }\n]\n', '', 0, '{"disable":true,"disableExtraTitleField":true}', NULL),
(60, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.TwitterUserFeed', 'Twitter User Feed', 1, 0, 21, 1, 0, 0, '', 'twitter-user-feed.js', 'twitter-user-feed.css', '', '[\n  {\n    "label": "Username on Twitter",\n    "importance": "high",\n    "name": "userName",\n    "type": "text",\n    "description": "The username we''ll be fetching tweets from"\n  },\n  {\n    "label": "Show replies",\n    "importance": "low",\n    "name": "showReplies",\n    "type": "boolean"\n  },\n  {\n    "label": "Number of tweets",\n    "importance": "medium",\n    "name": "numTweets",\n    "type": "number",\n    "default": 5,\n    "min": 1,\n    "max": 20\n  }\n]\n', '', 1, '{"disable":true,"disableExtraTitleField":true}', NULL),
