(66, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.Accordion', 'Accordion', 1, 0, 33, 1, 0, 0, 'iframe', 'h5p-accordion.js', 'h5p-accordion.css', '', '[\n  {\n    "name": "panels",\n    "type": "list",\n    "label": "Panels",\n    "entity": "panel",\n    "max": 100,\n    "min": 1,\n    "field": {\n      "name": "content",\n      "type": "group",\n      "label": "Content",\n      "importance": "high",\n      "entity": "content",\n      "fields": [\n        {\n          "name": "title",\n          "type": "text",\n          "label": "Title",\n          "importance": "high"\n        },\n        {\n          "name": "content",\n          "type": "library",\n          "label": "Content type",\n          "importance": "medium",\n          "entity": "content",\n          "options": [\n            "H5P.AdvancedText 1.1"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    "name": "hTag",\n    "type": "select",\n    "label": "H tags for labels (does not affect the size of the label)",\n    "importance": "low",\n    "description": "The h tag used on the labels. Normally H2 but if this belongs under an H2 heading use H3. Does not affect the size of the labels, only used for semantical purposes.",\n    "options": [\n      {\n        "value": "h2",\n        "label": "H2"\n      },\n      {\n        "value": "h3",\n        "label": "H3"\n      },\n      {\n        "value": "h4",\n        "label": "H4"\n      }\n    ],\n    "default": "h2"\n  }\n]\n', '', 1, NULL, NULL),
(67, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.Collage', 'Collage', 0, 3, 25, 1, 0, 0, '', 'collage.js, template.js, clip.js', 'collage.css', '', '[\n  {\n    "name": "collage",\n    "label": "Preview",\n    "importance": "high",\n    "type": "group",\n    "widget": "collage",\n    "description": "You can move(pan) the images around by dragging them. You can also select an image and then use the + or - keys on your keyboard to zoom or simply hold down the Z key while moving your mouse wheel.",\n    "fields": [\n      {\n        "name": "template",\n        "label": "Layout",\n        "importance": "high",\n        "type": "select",\n        "options": [\n          {\n            "value": "1",\n            "label": "1"\n          },\n          {\n            "value": "1-1",\n            "label": "1-1"\n          },\n          {\n            "value": "2",\n            "label": "2"\n          },\n          {\n            "value": "2-1",\n            "label": "2-1"\n          },\n          {\n            "value": "1-2",\n            "label": "1-2"\n          },\n          {\n            "value": "2-2",\n            "label": "2-2"\n          },\n          {\n            "value": "3-1",\n            "label": "3-1"\n          },\n          {\n            "value": "1-3",\n            "label": "1-3"\n          },\n          {\n            "value": "2-3",\n            "label": "2-3"\n          },\n          {\n            "value": "3-2",\n            "label": "3-2"\n          },\n          {\n            "value": "3-3",\n            "label": "3-3"\n          }\n        ],\n        "default": "2-1"\n      },\n      {\n        "name": "options",\n        "label": "Display options",\n        "importance": "low",\n        "type": "group",\n        "fields": [\n          {\n            "name": "heightRatio",\n            "label": "Height",\n            "importance": "low",\n            "type": "number",\n            "decimals": 2,\n            "min": 0.1,\n            "max": 2,\n            "default": 0.75\n          },\n          {\n            "name": "spacing",\n            "label": "Spacing",\n            "importance": "low",\n            "type": "number",\n            "decimals": 2,\n            "min": 0,\n            "max": 2,\n            "default": 0.5\n          },\n          {\n            "name": "frame",\n            "label": "Frame",\n            "importance": "low",\n            "type": "boolean",\n            "default": true\n          }\n        ]\n      },\n      {\n        "name": "clips",\n        "label": "Clips",\n        "importance": "low",\n        "type": "list",\n        "min": 1,\n        "entity": "clip",\n        "field": {\n          "name": "clip",\n          "label": "Clip",\n          "importance": "low",\n          "type": "group",\n          "fields": [\n            {\n              "name": "image",\n              "type": "image",\n              "label": "Image",\n              "importance": "low"\n            },\n            {\n              "name": "offset",\n              "label": "Offset",\n              "importance": "low",\n              "type": "group",\n              "fields": [\n                {\n                  "name": "top",\n                  "label": "Top",\n                  "importance": "low",\n                  "type": "number",\n                  "default": 0\n                },\n                {\n                  "name": "left",\n                  "label": "Left",\n                  "importance": "low",\n                  "type": "number",\n                  "default": 0\n                }\n              ]\n            },\n            {\n              "name": "alt",\n              "type": "text",\n              "label": "Alternative text",\n              "importance": "high",\n              "description": "Required. If the browser can''t load the image this text will be displayed instead. Also used by readspeakers."\n            },\n            {\n              "name": "title",\n              "type": "text",\n              "label": "Hover text",\n              "importance": "low",\n              "description": "Optional. This text is displayed when the user hovers his pointing device over the image.",\n              "optional": true\n            },\n            {\n              "name": "scale",\n              "label": "Scale",\n              "importance": "low",\n              "type": "number",\n              "decimals": 2,\n              "min": 0.01,\n              "default": 1\n            }\n          ]\n        }\n      }\n    ]\n  }\n]\n', '', 1, NULL, NULL),
(68, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.Column', 'Page', 1, 18, 8, 1, 0, 0, 'iframe', 'scripts/h5p-column.js', 'styles/h5p-column.css', '', '[\n  {\n    "name": "content",\n    "label": "List of Column Content",\n    "importance": "high",\n    "type": "list",\n    "min": 1,\n    "entity": "content",\n    "field": {\n      "name": "content",\n      "type": "group",\n      "fields": [\n        {\n          "name": "content",\n          "type": "library",\n          "importance": "high",\n          "label": "Content",\n          "options": [\n            "H5P.Accordion 1.0",\n            "H5P.Agamotto 1.6",\n            "H5P.Audio 1.5",\n            "H5P.AudioRecorder 1.0",\n            "H5P.Blanks 1.14",\n            "H5P.Chart 1.2",\n            "H5P.Collage 0.3",\n            "H5P.CoursePresentation 1.26",\n            "H5P.Dialogcards 1.9",\n            "H5P.DocumentationTool 1.8",\n            "H5P.DragQuestion 1.14",\n            "H5P.DragText 1.10",\n            "H5P.Essay 1.5",\n            "H5P.GuessTheAnswer 1.5",\n            "H5P.Table 1.2",\n            "H5P.AdvancedText 1.1",\n            "H5P.IFrameEmbed 1.0",\n            "H5P.Image 1.1",\n            "H5P.ImageHotspots 1.10",\n            "H5P.ImageHotspotQuestion 1.8",\n            "H5P.ImageSlider 1.1",\n            "H5P.InteractiveVideo 1.27",\n            "H5P.Link 1.3",\n            "H5P.MarkTheWords 1.11",\n            "H5P.MemoryGame 1.3",\n            "H5P.MultiChoice 1.16",\n            "H5P.Questionnaire 1.3",\n            "H5P.QuestionSet 1.20",\n            "H5P.Row 1.0",\n            "H5P.SingleChoiceSet 1.11",\n            "H5P.Summary 1.10",\n            "H5P.Timeline 1.1",\n            "H5P.TrueFalse 1.8",\n            "H5P.Video 1.6",\n            "H5P.MultiMediaChoice 0.3"\n          ]\n        },\n        {\n          "name": "useSeparator",\n          "type": "select",\n          "importance": "low",\n          "label": "Separate content with a horizontal ruler",\n          "default": "auto",\n          "options": [\n            {\n              "value": "auto",\n              "label": "Automatic (default)"\n            },\n            {\n              "value": "disabled",\n              "label": "Never use ruler above"\n            },\n            {\n              "value": "enabled",\n              "label": "Always use ruler above"\n            }\n          ]\n        }\n      ]\n    }\n  }\n]\n', '', 1, NULL, NULL),
(69, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.DocumentExportPage', 'Document Export Page', 1, 5, 19, 0, 0, 0, '', 'dist/h5p-document-export-page.js', 'dist/h5p-document-export-page.css', '', '[\n  {\n    "name": "description",\n    "label": "Description",\n    "importance": "medium",\n    "type": "text",\n    "widget": "html",\n    "description": "Description of the export page.",\n    "default": "On this page you can choose to export your text, goals and goals assessments.",\n    "enterMode": "p",\n    "tags": [\n      "strong",\n      "em",\n      "u",\n      "a",\n      "ul",\n      "ol",\n      "h2",\n      "h3",\n      "hr",\n      "pre",\n      "code"\n    ],\n    "optional": true\n  },\n  {\n    "name": "createDocumentLabel",\n    "label": "Create document button label",\n    "importance": "low",\n    "type": "text",\n    "description": "Text that will be displayed on the \\"Create document\\"-button.",\n    "default": "Create document"\n  },\n  {\n    "name": "submitTextLabel",\n    "label": "Submit text button",\n    "importance": "low",\n    "type": "text",\n    "description": "Text that will be displayed on the \\"Submit\\"-button.",\n    "default": "Submit"\n  },\n  {\n    "name": "submitSuccessTextLabel",\n    "type": "text",\n    "label": "Submit success label",\n    "optional": false,\n    "default": "Your report was submitted successfully!"\n  },\n  {\n    "name": "selectAllTextLabel",\n    "label": "Select all exportable text button label",\n    "importance": "low",\n    "type": "text",\n    "description": "Text that will be displayed on the \\"Select all text\\"-button.",\n    "default": "Select"\n  },\n  {\n    "name": "exportTextLabel",\n    "label": "Export text button label",\n    "importance": "low",\n    "type": "text",\n    "description": "Text that will be displayed on the \\"Export text\\"-button.",\n    "default": "Export"\n  },\n  {\n    "name": "helpTextLabel",\n    "label": "Label for help text",\n    "importance": "low",\n    "type": "text",\n    "description": "Label for showing additional helpful information to the user.",\n    "default": "More information"\n  },\n  {\n    "name": "helpText",\n    "label": "Fill in additional help information",\n    "importance": "low",\n    "type": "text",\n    "widget": "html",\n    "description": "Here you can fill in additional helpful information for the user.",\n    "enterMode": "p",\n    "optional": true,\n    "tags": [\n      "strong",\n      "em",\n      "u",\n      "a",\n      "ul",\n      "ol",\n      "h2",\n      "h3",\n      "hr",\n      "pre",\n      "code"\n    ]\n  },\n  {\n    "name": "requiresInputErrorMessage",\n    "label": "Required input missing text",\n    "importance": "low",\n    "type": "text",\n    "description": "An error message which will be displayed if one or more required input fields have not been filled. @pages will be replaced with the titles of affected pages.",\n    "default": "The following pages contain required fields that need to be filled in order to review or submit this document: @pages"\n  }\n]\n', '', 0, NULL, NULL),
(70, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.DocumentationTool', 'Documentation Tool', 1, 8, 27, 1, 0, 0, 'iframe', 'navigation-menu.js, documentation-tool.js', 'navigation-menu.css, documentation-tool.css', '', '[\n  {\n    "name": "taskDescription",\n    "label": "Heading",\n    "importance": "high",\n    "type": "text",\n    "default": "Documentation tool",\n    "description": "Title for the documentation tool.",\n    "optional": true\n  },\n  {\n    "name": "pagesList",\n    "label": "Elements",\n    "importance": "high",\n    "type": "list",\n    "widgets": [\n      {\n        "name": "VerticalTabs",\n        "label": "Default"\n      }\n    ],\n    "min": 1,\n    "entity": "page",\n    "field": {\n      "name": "page",\n      "type": "library",\n      "label": "Page type",\n      "importance": "high",\n      "description": "Library for this slide.",\n      "options": [\n        "H5P.StandardPage 1.5",\n        "H5P.GoalsPage 1.5",\n        "H5P.GoalsAssessmentPage 1.4",\n        "H5P.DocumentExportPage 1.5"\n      ]\n    }\n  },\n  {\n    "label": "Localize documentation tool buttons",\n    "name": "i10n",\n    "type": "group",\n    "common": true,\n    "collapsed": true,\n    "importance": "low",\n    "fields": [\n      {\n        "label": "Previous button label",\n        "name": "previousLabel",\n        "type": "text",\n        "default": "Previous documentation step",\n        "importance": "low"\n      },\n      {\n        "label": "Next button label",\n        "name": "nextLabel",\n        "type": "text",\n        "default": "Next documentation step",\n        "importance": "low"\n      },\n      {\n        "label": "Close button label",\n        "name": "closeLabel",\n        "type": "text",\n        "default": "Close",\n        "importance": "low"\n      }\n    ]\n  }\n]\n', '', 1, NULL, NULL),
(71, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.GoalsAssessmentPage', 'Goals assessment page', 1, 4, 17, 0, 0, 0, '', 'goals-assessment-page.js', 'goals-assessment-page.css', '', '[\n  {\n    "name": "description",\n    "label": "Description",\n    "importance": "medium",\n    "type": "text",\n    "widget": "html",\n    "description": "Description of the goals assessment page.",\n    "default": "Rate the goals that you have chosen in the goals page.",\n    "enterMode": "p",\n    "tags": [\n      "strong",\n      "em",\n      "u",\n      "a",\n      "ul",\n      "ol",\n      "h2",\n      "h3",\n      "hr",\n      "pre",\n      "code"\n    ],\n    "optional": true\n  },\n  {\n    "name": "lowRating",\n    "label": "Low rating text",\n    "importance": "low",\n    "type": "text",\n    "description": "Text for worst rating.",\n    "default": "Learned little"\n  },\n  {\n    "name": "midRating",\n    "label": "Medium rating text",\n    "importance": "low",\n    "type": "text",\n    "description": "Text for middle rating.",\n    "default": "Learned something"\n  },\n  {\n    "name": "highRating",\n    "label": "High rating text",\n    "importance": "low",\n    "type": "text",\n    "description": "Text for great rating.",\n    "default": "Learned a lot"\n  },\n  {\n    "name": "noGoalsText",\n    "label": "No goals text",\n    "importance": "low",\n    "type": "text",\n    "description": "Feedback text when no goals have been created.",\n    "default": "You have not chosen any goals yet."\n  },\n  {\n    "name": "helpTextLabel",\n    "label": "Label for help text",\n    "importance": "low",\n    "type": "text",\n    "description": "Label for showing additional helpful information to the user.",\n    "default": "More information"\n  },\n  {\n    "name": "helpText",\n    "label": "Fill in additional help information",\n    "importance": "low",\n    "type": "text",\n    "widget": "html",\n    "description": "Here you can fill in additional helpful information for the user.",\n    "enterMode": "p",\n    "optional": true,\n    "tags": [\n      "strong",\n      "em",\n      "u",\n      "a",\n      "ul",\n      "ol",\n      "h2",\n      "h3",\n      "hr",\n      "pre",\n      "code"\n    ]\n  },\n  {\n    "name": "legendHeader",\n    "label": "Legend header",\n    "importance": "low",\n    "type": "text",\n    "default": "Possible ratings:"\n  },\n  {\n    "name": "goalHeader",\n    "label": "Goal header",\n    "importance": "low",\n    "type": "text",\n    "default": "Goals"\n  },\n  {\n    "name": "ratingHeader",\n    "label": "Rating header",\n    "importance": "low",\n    "type": "text",\n    "default": "Rating"\n  }\n]', '', 0, NULL, NULL),
(72, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.GoalsPage', 'Goals page', 1, 5, 21, 0, 0, 0, '', 'goals-page.js, goal-instance.js', 'goals-page.css', '', '[\n  {\n    "name": "description",\n    "label": "Description",\n    "importance": "medium",\n    "type": "text",\n    "widget": "html",\n    "description": "Description of the goals page.",\n    "default": "Insert the goals that you have chosen to work with.",\n    "enterMode": "p",\n    "tags": [\n      "strong",\n      "em",\n      "u",\n      "a",\n      "ul",\n      "ol",\n      "h2",\n      "h3",\n      "hr",\n      "pre",\n      "code"\n    ],\n    "optional": true\n  },\n  {\n    "name": "defineGoalText",\n    "label": "Define goal link text",\n    "importance": "low",\n    "type": "text",\n    "description": "Text that will be displayed on the button for creating a new goal.",\n    "default": "Create a new goal"\n  },\n  {\n    "name": "definedGoalLabel",\n    "label": "Label for a user defined goal",\n    "importance": "low",\n    "type": "text",\n    "description": "Text that will be displayed as label on a user created goal.",\n    "default": "User defined goal"\n  },\n  {\n    "name": "defineGoalPlaceholder",\n    "label": "Define goal placeholder",\n    "importance": "low",\n    "type": "text",\n    "description": "Text that will be displayed as a placeholder when creating a new goal.",\n    "default": "Write here..."\n  },\n  {\n    "name": "goalsAddedText",\n    "label": "Text indicating how many goals has been added",\n    "importance": "low",\n    "type": "text",\n    "default": "Goals added:",\n    "description": "This text will follow after the amount of goals that is currently created, example: ''Goals added: 5'' where ''Goals added:'' is this text."\n  },\n  {\n    "name": "specifyGoalText",\n    "label": "Text for \\"Specify goal\\"-button",\n    "importance": "low",\n    "type": "text",\n    "default": "Specification"\n  },\n  {\n    "name": "removeGoalText",\n    "label": "Text for \\"Remove goal\\"-button",\n    "importance": "low",\n    "type": "text",\n    "default": "Remove Goal"\n  },\n  {\n    "name": "helpTextLabel",\n    "label": "Label for help text",\n    "importance": "low",\n    "type": "text",\n    "description": "Label for showing additional helpful information to the user.",\n    "default": "More information"\n  },\n  {\n    "name": "helpText",\n    "label": "Fill in additional help information",\n    "importance": "low",\n    "type": "text",\n    "widget": "html",\n    "description": "Here you can fill in additional helpful information for the user.",\n    "enterMode": "p",\n    "optional": true,\n    "tags": [\n      "strong",\n      "em",\n      "u",\n      "a",\n      "ul",\n      "ol",\n      "h2",\n      "h3",\n      "hr",\n      "pre",\n      "code"\n    ]\n  },\n  {\n    "name": "goalDeletionConfirmation",\n    "type": "group",\n    "common": true,\n    "importance": "low",\n    "label": "Localize goal deletion confirmation",\n    "fields": [\n      {\n        "name": "header",\n        "type": "text",\n        "label": "Header",\n        "optional": false,\n        "default": "Confirm deletion"\n      },\n      {\n        "name": "message",\n        "type": "text",\n        "label": "Message",\n        "optional": false,\n        "default": "Are you sure you want to delete this goal?"\n      },\n      {\n        "name": "cancelLabel",\n        "type": "text",\n        "label": "Cancel button label",\n        "optional": false,\n        "default": "Cancel"\n      },\n      {\n        "name": "confirmLabel",\n        "type": "text",\n        "label": "Confirm button label",\n        "optional": false,\n        "default": "Confirm"\n      }\n    ]\n  }\n]\n', '', 0, NULL, NULL),
(73, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.IFrameEmbed', 'Iframe Embedder', 1, 0, 29, 1, 0, 1, '', 'iframe-embed.js', '', '', '[\n  {\n    "label": "Width",\n    "importance": "high",\n    "name": "width",\n    "type": "text",\n    "description": "Width of iFrame in CSS compliant format. Default: \\"500px\\""\n  },\n  {\n    "label": "Minimum width",\n    "importance": "high",\n    "name": "minWidth",\n    "type": "text",\n    "description": "Minimum width of iFrame in CSS compliant format. Default: \\"300px\\""\n  },\n  {\n    "label": "Height",\n    "name": "height",\n    "type": "text",\n    "description": "Height of iFrame in CSS compliant format. Default: \\"500px\\""\n  },\n  {\n    "label": "Source",\n    "importance": "high",\n    "name": "source",\n    "type": "text",\n    "description": "URI to external document, or path to document found inside H5P (under /content)"\n  },\n  {\n    "name": "resizeSupported",\n    "type": "boolean",\n    "label": "Resize supported",\n    "importance": "medium",\n    "description": "If enabled, fullscreen button will be displayed, and H5P will be resized to fit its surroundings",\n    "default": true\n  }\n]\n', '', 1, NULL, NULL),
(74, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.ImageHotspotQuestion', 'Find the Hotspot', 1, 8, 22, 1, 0, 0, '', 'image-hotspot-question.js', 'image-hotspot-question.css', '', '[\n  {\n    "name": "imageHotspotQuestion",\n    "type": "group",\n    "widget": "wizard",\n    "label": "Image Hotspot Question Editor",\n    "importance": "high",\n    "fields": [\n      {\n        "name": "backgroundImageSettings",\n        "type": "group",\n        "label": "Background image",\n        "importance": "high",\n        "fields": [\n          {\n            "name": "backgroundImage",\n            "type": "image",\n            "label": "Background image",\n            "importance": "high",\n            "description": "Select an image to use as background for the image hotspot question."\n          }\n        ]\n      },\n      {\n        "name": "hotspotSettings",\n        "type": "group",\n        "label": "Hotspots",\n        "importance": "high",\n        "widget": "imageHotspotQuestion",\n        "description": "Drag and drop the desired figure from the toolbar to create a new hotspot. Double-click to edit an existing hotspot. Drag the hotspot to move it. Pull the resize handler in the lower right corner to resize.",\n        "fields": [\n          {\n            "name": "taskDescription",\n            "type": "text",\n            "label": "Task description",\n            "importance": "high",\n            "description": "Instructions to the user.",\n            "optional": true\n          },\n          {\n            "name": "hotspot",\n            "type": "list",\n            "label": "Hotspot",\n            "importance": "high",\n            "entity": "Hotspot",\n            "field": {\n              "type": "group",\n              "label": "Hotspot",\n              "importance": "high",\n              "fields": [\n                {\n                  "name": "userSettings",\n                  "type": "group",\n                  "label": "userSettings",\n                  "importance": "low",\n                  "fields": [\n                    {\n                      "name": "correct",\n                      "type": "boolean",\n                      "label": "Correct",\n                      "importance": "low",\n                      "description": "There can be multiple correct hotspots. However, the user gets correct/incorrect feedback immediately after first click."\n                    },\n                    {\n                      "name": "feedbackText",\n                      "type": "text",\n                      "label": "Feedback",\n                      "importance": "low",\n                      "optional": true\n                    }\n                  ]\n                },\n                {\n                  "name": "computedSettings",\n                  "type": "group",\n                  "label": "computedSettings",\n                  "importance": "low",\n                  "fields": [\n                    {\n                      "name": "x",\n                      "type": "number",\n                      "optional": true\n                    },\n                    {\n                      "name": "y",\n                      "type": "number",\n                      "optional": true\n                    },\n                    {\n                      "name": "width",\n                      "type": "number",\n                      "optional": true\n                    },\n                    {\n                      "name": "height",\n                      "type": "number",\n                      "optional": true\n                    },\n                    {\n                      "name": "figure",\n                      "type": "text",\n                      "optional": true\n                    }\n                  ]\n                }\n              ]\n            }\n          },\n          {\n            "name": "noneSelectedFeedback",\n            "type": "text",\n            "label": "Feedback if the user selects an empty spot:",\n            "importance": "low",\n            "placeholder": "You didn''t locate any hotspots, try again!",\n            "optional": true\n          },\n          {\n            "name": "showFeedbackAsPopup",\n            "type": "boolean",\n            "label": "Show feedback as a popup",\n            "importance": "low",\n            "default": true,\n            "optional": true\n          },\n          {\n            "label": "Localization",\n            "name": "l10n",\n            "type": "group",\n            "fields": [\n              {\n                "name": "retryText",\n                "label": "Retry button text",\n                "type": "text",\n                "default": "Retry",\n                "optional": true\n              },\n              {\n                "name": "closeText",\n                "label": "Close button text",\n                "type": "text",\n                "default": "Close",\n                "optional": true\n              }\n            ]\n          }\n        ]\n      }\n    ]\n  },\n  {\n    "name": "scoreBarLabel",\n    "type": "text",\n    "label": "Textual representation of the score bar for those using a readspeaker",\n    "default": "You got :num out of :total points",\n    "importance": "low",\n    "common": true\n  },\n  {\n    "name": "a11yRetry",\n    "type": "text",\n    "label": "Assistive technology description for \\"Retry\\" button",\n    "default": "Retry the task. Reset all responses and start the task over again.",\n    "importance": "low",\n    "common": true\n  }\n]', '', 1, NULL, NULL);
INSERT INTO `wpcu_h5p_libraries` VALUES
(75, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.ImageHotspots', 'Image Hotspots', 1, 10, 18, 1, 0, 1, 'iframe', 'scripts/image-hotspots.js, scripts/hotspot.js, scripts/popup.js', 'styles/image-hotspots.css', '', '[\n  {\n    "label": "Background image",\n    "importance": "high",\n    "name": "image",\n    "type": "image",\n    "description": "Image shown on background."\n  },\n  {\n    "name": "backgroundImageAltText",\n    "type": "text",\n    "label": "Alternative text for background image",\n    "description": "If the browser can''t load the image this text will be displayed instead. Also used by assistive technologies.",\n    "optional": true\n  },\n  {\n    "name": "iconType",\n    "type": "select",\n    "label": "Hotspot Icon",\n    "options": [\n      {\n        "value": "icon",\n        "label": "Predefined icon"\n      },\n      {\n        "value": "image",\n        "label": "Uploaded image"\n      }\n    ],\n    "default": "icon"\n  },\n  {\n    "name": "icon",\n    "type": "select",\n    "label": "Predefined icon",\n    "importance": "medium",\n    "description": "Using a predefined icon for the hotspot.",\n    "widget": "showWhen",\n    "showWhen": {\n      "rules": [\n        {\n          "field": "iconType",\n          "equals": [\n            "icon"\n          ]\n        }\n      ]\n    },\n    "options": [\n      {\n        "value": "plus",\n        "label": "Plus"\n      },\n      {\n        "value": "minus",\n        "label": "Minus"\n      },\n      {\n        "value": "times",\n        "label": "Times"\n      },\n      {\n        "value": "check",\n        "label": "Check"\n      },\n      {\n        "value": "question",\n        "label": "Question"\n      },\n      {\n        "value": "info",\n        "label": "Info"\n      },\n      {\n        "value": "exclamation",\n        "label": "Exclamation"\n      }\n    ],\n    "default": "plus"\n  },\n  {\n    "name": "iconImage",\n    "type": "image",\n    "label": "Uploaded image",\n    "optional": false,\n    "description": "Use your own image for the hotspot icon.<br />75px by 75px is recommended for your image.",\n    "widget": "showWhen",\n    "showWhen": {\n      "rules": [\n        {\n          "field": "iconType",\n          "equals": [\n            "image"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    "name": "color",\n    "type": "text",\n    "label": "Hotspot color",\n    "importance": "medium",\n    "description": "The color of the hotspots",\n    "optional": true,\n    "default": "#981d99",\n    "widget": "showWhen",\n    "spectrum": {\n      "showInput": true\n    },\n    "showWhen": {\n      "widget": "colorSelector",\n      "rules": [\n        {\n          "field": "iconType",\n          "equals": [\n            "icon"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    "name": "hotspots",\n    "type": "list",\n    "entity": "hotspot",\n    "label": "Hotspots",\n    "importance": "high",\n    "min": 1,\n    "defaultNum": 1,\n    "field": {\n      "name": "hotspot",\n      "type": "group",\n      "label": "Hotspot",\n      "importance": "high",\n      "fields": [\n        {\n          "name": "position",\n          "type": "group",\n          "widget": "imageCoordinateSelector",\n          "imageFieldPath": "../../image",\n          "label": "Hotspot position",\n          "importance": "high",\n          "description": "Click on the thumbnail image to place the hotspot",\n          "fields": [\n            {\n              "name": "x",\n              "type": "number"\n            },\n            {\n              "name": "y",\n              "type": "number"\n            },\n            {\n              "name": "legacyPositioning",\n              "type": "boolean"\n            }\n          ]\n        },\n        {\n          "name": "alwaysFullscreen",\n          "type": "boolean",\n          "label": "Cover entire background image",\n          "importance": "low",\n          "description": "When the user clicks the hotspot the popup will cover the entire background image"\n        },\n        {\n          "name": "header",\n          "type": "text",\n          "label": "Header",\n          "importance": "low",\n          "description": "Optional header for the popup. This is used by assistive technologies.",\n          "optional": true\n        },\n        {\n          "name": "content",\n          "type": "list",\n          "label": "Popup content",\n          "importance": "medium",\n          "field": {\n            "name": "action",\n            "type": "library",\n            "label": "Content Item",\n            "options": [\n              "H5P.Text 1.1",\n              "H5P.Video 1.6",\n              "H5P.Image 1.1",\n              "H5P.Audio 1.5"\n            ]\n          }\n        }\n      ]\n    }\n  },\n  {\n    "name": "hotspotNumberLabel",\n    "type": "text",\n    "label": "Hotspot label for assistive technologies",\n    "default": "Hotspot #num",\n    "description": "Will help announce what hotspot element has been navigated to if there is no header specified for a hotspot. #num can be used to replace the hotspot number.",\n    "common": true\n  },\n  {\n    "name": "closeButtonLabel",\n    "type": "text",\n    "label": "Close button label for assistive technologies",\n    "default": "Close",\n    "common": true\n  },\n  {\n    "name": "containsAudioVideoLabel",\n    "type": "text",\n    "label": "Label for assistive technologies denoting that hotspot contains Audio/Video",\n    "default": "Contains Audio/Video",\n    "common": true\n  }\n]\n', '', 1, NULL, NULL),
(76, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.MemoryGame', 'Memory Game', 1, 3, 29, 1, 0, 0, '', 'memory-game.js, card.js, counter.js, popup.js, timer.js, aria-live-region.js', 'memory-game.css', '', '[\n  {\n    "name": "cards",\n    "type": "list",\n    "widgets": [\n      {\n        "name": "VerticalTabs",\n        "label": "Default"\n      }\n    ],\n    "label": "Cards",\n    "importance": "high",\n    "entity": "card",\n    "min": 2,\n    "max": 100,\n    "field": {\n      "type": "group",\n      "name": "card",\n      "label": "Card",\n      "importance": "high",\n      "fields": [\n        {\n          "name": "image",\n          "type": "image",\n          "label": "Image",\n          "importance": "high",\n          "ratio": 1\n        },\n        {\n          "name": "imageAlt",\n          "type": "text",\n          "label": "Alternative text for Image",\n          "importance": "high",\n          "description": "Describe what can be seen in the photo. The text is read by text-to-speech tools needed by visually impaired users."\n        },\n        {\n          "name": "audio",\n          "type": "audio",\n          "importance": "high",\n          "label": "Audio Track",\n          "description": "An optional sound that plays when the card is turned.",\n          "optional": true,\n          "widgetExtensions": [\n            "AudioRecorder"\n          ]\n        },\n        {\n          "name": "match",\n          "type": "image",\n          "label": "Matching Image",\n          "importance": "low",\n          "optional": true,\n          "description": "An optional image to match against instead of using two cards with the same image.",\n          "ratio": 1\n        },\n        {\n          "name": "matchAlt",\n          "type": "text",\n          "label": "Alternative text for Matching Image",\n          "importance": "low",\n          "optional": true,\n          "description": "Describe what can be seen in the photo. The text is read by text-to-speech tools needed by visually impaired users."\n        },\n        {\n          "name": "matchAudio",\n          "type": "audio",\n          "importance": "low",\n          "label": "Matching Audio Track",\n          "description": "An optional sound that plays when the second card is turned.",\n          "optional": true,\n          "widgetExtensions": [\n            "AudioRecorder"\n          ]\n        },\n        {\n          "name": "description",\n          "type": "text",\n          "label": "Description",\n          "importance": "low",\n          "maxLength": 150,\n          "optional": true,\n          "description": "An optional short text that will pop up once the two matching cards are found."\n        }\n      ]\n    }\n  },\n  {\n    "name": "behaviour",\n    "type": "group",\n    "label": "Behavioural settings",\n    "importance": "low",\n    "description": "These options will let you control how the game behaves.",\n    "optional": true,\n    "fields": [\n      {\n        "name": "useGrid",\n        "type": "boolean",\n        "label": "Position the cards in a square",\n        "description": "Will try to match the number of columns and rows when laying out the cards. Afterward, the cards will be scaled to fit the container.",\n        "importance": "low",\n        "default": true\n      },\n      {\n        "name": "numCardsToUse",\n        "type": "number",\n        "label": "Number of cards to use",\n        "description": "Setting this to a number greater than 2 will make the game pick random cards from the list of cards.",\n        "importance": "low",\n        "optional": true,\n        "min": 2\n      },\n      {\n        "name": "allowRetry",\n        "type": "boolean",\n        "label": "Add button for retrying when the game is over",\n        "importance": "low",\n        "default": true\n      }\n    ]\n  },\n  {\n    "name": "lookNFeel",\n    "type": "group",\n    "label": "Look and feel",\n    "importance": "low",\n    "description": "Control the visuals of the game.",\n    "optional": true,\n    "fields": [\n      {\n        "name": "themeColor",\n        "type": "text",\n        "label": "Theme Color",\n        "importance": "low",\n        "description": "Choose a color to create a theme for your card game.",\n        "optional": true,\n        "default": "#707070",\n        "widget": "colorSelector",\n        "spectrum": {\n          "showInput": true\n        }\n      },\n      {\n        "name": "cardBack",\n        "type": "image",\n        "label": "Card Back",\n        "importance": "low",\n        "optional": true,\n        "description": "Use a custom back for your cards.",\n        "ratio": 1\n      }\n    ]\n  },\n  {\n    "label": "Localization",\n    "importance": "low",\n    "name": "l10n",\n    "type": "group",\n    "common": true,\n    "fields": [\n      {\n        "label": "Card turns text",\n        "importance": "low",\n        "name": "cardTurns",\n        "type": "text",\n        "default": "Card turns"\n      },\n      {\n        "label": "Time spent text",\n        "importance": "low",\n        "name": "timeSpent",\n        "type": "text",\n        "default": "Time spent"\n      },\n      {\n        "label": "Feedback text",\n        "importance": "low",\n        "name": "feedback",\n        "type": "text",\n        "default": "Good work!"\n      },\n      {\n        "label": "Try again button text",\n        "importance": "low",\n        "name": "tryAgain",\n        "type": "text",\n        "default": "Reset"\n      },\n      {\n        "label": "Close button label",\n        "importance": "low",\n        "name": "closeLabel",\n        "type": "text",\n        "default": "Close"\n      },\n      {\n        "label": "Game label",\n        "importance": "low",\n        "name": "label",\n        "type": "text",\n        "default": "Memory Game. Find the matching cards."\n      },\n      {\n        "label": "Game instructions",\n        "importance": "low",\n        "name": "label",\n        "type": "text",\n        "default": "Use arrow keys left and right to navigate cards. Use space or enter key to turn card."\n      },\n      {\n        "label": "Game finished label",\n        "importance": "low",\n        "name": "done",\n        "type": "text",\n        "default": "All of the cards have been found."\n      },\n      {\n        "label": "Card indexing label",\n        "description": "%num and %total are placeholders and will be replaced with the respective values for the card.",\n        "importance": "low",\n        "name": "cardPrefix",\n        "type": "text",\n        "default": "Card %num of %total:"\n      },\n      {\n        "label": "Card unturned label",\n        "importance": "low",\n        "name": "cardUnturned",\n        "type": "text",\n        "default": "Unturned. Click to turn."\n      },\n      {\n        "label": "Card turned label",\n        "importance": "low",\n        "name": "cardTurned",\n        "type": "text",\n        "default": "Turned."\n      },\n      {\n        "label": "Card matched label",\n        "importance": "low",\n        "name": "cardMatched",\n        "type": "text",\n        "default": "Match found."\n      },\n      {\n        "label": "Card matched announcement",\n        "importance": "low",\n        "name": "cardMatchedA11y",\n        "type": "text",\n        "default": "Your cards match!"\n      },\n      {\n        "label": "Card not matched announcement",\n        "importance": "low",\n        "name": "cardNotMatchedA11y",\n        "type": "text",\n        "default": "Your chosen cards do not match. Turn other cards to try again."\n      }\n    ]\n  }\n]\n', '', 1, NULL, NULL),
