(80, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.TextInputField', 'Text input field editor element', 1, 2, 17, 0, 0, 0, '', 'text-input-field.js, xapi-generator.js', 'text-input-field.css', '', '[\n  {\n    "name": "taskDescription",\n    "label": "Description of inputfield",\n    "type": "text",\n    "widget": "html",\n    "importance": "high",\n    "description": "Description of what the user should input.",\n    "enterMode": "div",\n    "tags": [\n      "strong",\n      "em",\n      "u",\n      "a",\n      "ul",\n      "ol",\n      "h2",\n      "h3",\n      "hr",\n      "pre",\n      "code"\n    ],\n    "optional": true\n  },\n  {\n    "name": "placeholderText",\n    "label": "Placeholder text",\n    "type": "text",\n    "description": "Example value or other placeholder text. Should not be used to replace the description of input-field, this value may not be available for screen-readers and also disappears when users start typing.",\n    "importance": "low",\n    "optional": true\n  },\n  {\n    "name": "maximumLength",\n    "label": "Maximum text length",\n    "type": "number",\n    "description": "Maximum number of characters for the text.",\n    "importance": "low",\n    "optional": true,\n    "min": "0"\n  },\n  {\n    "name": "inputFieldSize",\n    "label": "Input field size",\n    "type": "select",\n    "importance": "low",\n    "description": "The size of the input field in amount of lines it will cover.",\n    "options": [\n      {\n        "value": "1",\n        "label": "1 line"\n      },\n      {\n        "value": "3",\n        "label": "3 lines"\n      },\n      {\n        "value": "10",\n        "label": "10 lines"\n      }\n    ],\n    "default": "1"\n  },\n  {\n    "name": "requiredField",\n    "label": "Required field",\n    "type": "boolean",\n    "importance": "low",\n    "default": false,\n    "optional": true,\n    "description": "Check to make this field required, the user must answer all required fields to be able to export a document."\n  },\n  {\n    "name": "remainingChars",\n    "type": "text",\n    "label": "Remaining characters",\n    "importance": "low",\n    "common": true,\n    "default": "Remaining characters: @chars",\n    "description": "Message for remaining characters. You can use @chars which will be replaced by the corresponding number."\n  }\n]', '', 0, '{"disable":true,"disableExtraTitleField":true}', NULL),
(81, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.Timeline', 'Timeline', 1, 1, 25, 1, 0, 1, 'iframe', 'timeline.js', 'timeline.css', '', '[\n  {\n    "name": "timeline",\n    "label": "Timeline",\n    "importance": "high",\n    "type": "group",\n    "expanded": true,\n    "fields": [\n      {\n        "name": "headline",\n        "type": "text",\n        "label": "Headline",\n        "importance": "high",\n        "description": "Main timeline heading goes here (first page)"\n      },\n      {\n        "name": "text",\n        "type": "text",\n        "label": "Body Text",\n        "importance": "medium",\n        "widget": "html",\n        "description": "The main timeline body goes here (first page).",\n        "optional": true,\n        "tags": [\n          "strong",\n          "em",\n          "del",\n          "a",\n          "ul",\n          "ol",\n          "hr",\n          "code"\n        ]\n      },\n      {\n        "name": "defaultZoomLevel",\n        "type": "text",\n        "label": "Default zoom level",\n        "importance": "low",\n        "default": "0",\n        "optional": true,\n        "description": "This will tweak the default zoom level. Equivilent to pressing the zoom in or zoom out button the specified number of times. Negative numbers zoom out. default is 0"\n      },\n      {\n        "name": "backgroundImage",\n        "type": "image",\n        "label": "Background image",\n        "importance": "low",\n        "optional": true,\n        "description": "An image to display as background."\n      },\n      {\n        "name": "height",\n        "type": "number",\n        "label": "Height",\n        "importance": "low",\n        "description": "The height in pixels",\n        "default": 600\n      },\n      {\n        "name": "asset",\n        "type": "group",\n        "label": "Asset",\n        "importance": "low",\n        "description": "Here you can add an asset to your timeline \\"front page\\"",\n        "optional": true,\n        "fields": [\n          {\n            "name": "media",\n            "type": "text",\n            "label": "Media",\n            "importance": "low",\n            "description": "Link to media URL (Twitter, YouTube, Flickr, Vimeo, Google Maps and SoundCloud are currently supported)",\n            "optional": true\n          },\n          {\n            "name": "credit",\n            "type": "text",\n            "label": "Credits",\n            "importance": "low",\n            "description": "Credits to the media",\n            "optional": true\n          },\n          {\n            "name": "caption",\n            "type": "text",\n            "label": "Caption",\n            "importance": "low",\n            "description": "Caption description goes here",\n            "optional": true\n          }\n        ]\n      },\n      {\n        "name": "date",\n        "type": "list",\n        "label": "Dates",\n        "importance": "medium",\n        "min": 1,\n        "description": "Add some dates to your timeline!",\n        "field": {\n          "name": "adate",\n          "type": "group",\n          "label": "Date",\n          "importance": "medium",\n          "description": "Date",\n          "fields": [\n            {\n              "name": "startDate",\n              "type": "text",\n              "label": "Start date",\n              "importance": "medium",\n              "description": "YYYY,MM,DD (Minimum YYYY required)",\n              "regexp": {\n                "pattern": "^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$"\n              }\n            },\n            {\n              "name": "endDate",\n              "type": "text",\n              "label": "End date",\n              "importance": "medium",\n              "description": "YYYY,MM,DD (Minimum YYYY required)",\n              "optional": true,\n              "regexp": {\n                "pattern": "^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$"\n              }\n            },\n            {\n              "name": "headline",\n              "type": "text",\n              "label": "Headline",\n              "importance": "medium",\n              "description": "Headline for the date entry"\n            },\n            {\n              "name": "text",\n              "type": "text",\n              "label": "Body text",\n              "importance": "medium",\n              "widget": "html",\n              "optional": true,\n              "description": "Body for the date entry",\n              "tags": [\n                "strong",\n                "em",\n                "del",\n                "a",\n                "ul",\n                "ol",\n                "h2",\n                "h3",\n                "hr",\n                "pre",\n                "code"\n              ]\n            },\n            {\n              "name": "tag",\n              "type": "text",\n              "label": "Tags",\n              "importance": "medium",\n              "description": "Enter Tags (categories)",\n              "optional": true\n            },\n            {\n              "name": "asset",\n              "type": "group",\n              "label": "Asset",\n              "importance": "low",\n              "description": "",\n              "optional": true,\n              "fields": [\n                {\n                  "name": "media",\n                  "type": "text",\n                  "label": "Media",\n                  "importance": "low",\n                  "description": "URL to the media (Twitter, YouTube, Flickr, Vimeo, Wikipedia, Google Maps and SoundCloud are currently supported).",\n                  "optional": true\n                },\n                {\n                  "name": "thumbnail",\n                  "type": "image",\n                  "label": "Thumbnail",\n                  "importance": "low",\n                  "description": "Add a thumbnail if needed, 32x32",\n                  "optional": true\