(92, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.SpeakTheWords', 'Speak the Words', 1, 5, 7, 1, 0, 0, 'iframe', 'dist/h5p-speak-the-words.js', 'dist/h5p-speak-the-words.css', '', '[\n  {\n    "name": "media",\n    "type": "group",\n    "label": "Media",\n    "importance": "medium",\n    "fields": [\n      {\n        "name": "type",\n        "type": "library",\n        "label": "Type",\n        "importance": "medium",\n        "options": [\n          "H5P.Image 1.1",\n          "H5P.Video 1.6",\n          "H5P.Audio 1.5"\n        ],\n        "optional": true,\n        "description": "Optional media to display above the question."\n      },\n      {\n        "name": "disableImageZooming",\n        "type": "boolean",\n        "label": "Disable image zooming",\n        "importance": "low",\n        "default": false,\n        "optional": true,\n        "widget": "showWhen",\n        "showWhen": {\n          "rules": [\n            {\n              "field": "type",\n              "equals": "H5P.Image 1.1"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    "name": "question",\n    "label": "Describe task",\n    "type": "text",\n    "placeholder": "How do you say ''Yes'' in Spanish?"\n  },\n  {\n    "name": "acceptedAnswers",\n    "label": "Accepted answers",\n    "type": "list",\n    "min": 1,\n    "field": {\n      "name": "acceptedAnswer",\n      "label": "Accepted answer",\n      "type": "text"\n    }\n  },\n  {\n    "name": "incorrectAnswerText",\n    "label": "Incorrect answer text",\n    "type": "text",\n    "default": "Incorrect answer"\n  },\n  {\n    "name": "correctAnswerText",\n    "label": "Correct answer text",\n    "type": "text",\n    "default": "Correct answer"\n  },\n  {\n    "name": "inputLanguage",\n    "label": "Language of speech input",\n    "type": "select",\n    "options": [\n      {\n        "label": "Afrikaans",\n        "value": "af-ZA"\n      },\n      {\n        "label": "Amharic",\n        "value": "am-ET"\n      },\