(93, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.SpeakTheWordsSet', 'Speak the Words Set', 1, 3, 4, 1, 0, 0, 'iframe', 'dist/dist.js', '', '', '[\n  {\n    "name": "introduction",\n    "label": "Introduction",\n    "type": "group",\n    "fields": [\n      {\n        "name": "showIntroPage",\n        "type": "boolean",\n        "optional": true,\n        "default": false,\n        "label": "Display introduction",\n        "importance": "low"\n      },\n      {\n        "name": "introductionImage",\n        "type": "image",\n        "label": "Introduction image",\n        "optional": true,\n        "widget": "showWhen",\n        "showWhen": {\n          "rules": [\n            {\n              "field": "showIntroPage",\n              "equals": true\n            }\n          ]\n        }\n      },\n      {\n        "name": "introductionImageAltText",\n        "type": "text",\n        "label": "Alternative text for introduction image",\n        "optional": true,\n        "widget": "showWhen",\n        "showWhen": {\n          "rules": [\n            {\n              "field": "showIntroPage",\n              "equals": true\n            }\n          ]\n        }\n      },\n      {\n        "name": "introductionTitle",\n        "type": "text",\n        "label": "Title",\n        "optional": true,\n        "widget": "showWhen",\n        "showWhen": {\n          "rules": [\n            {\n              "field": "showIntroPage",\n              "equals": true\n            }\n          ]\n        }\n      },\n      {\n        "name": "introductionText",\n        "type": "text",\n        "label": "Introduction text",\n        "optional": true,\n        "description": "This title will be displayed above the introduction text.",\n        "widget": "showWhen",\n        "showWhen": {\n          "widget": "html",\n          "rules": [\n            {\n              "field": "showIntroPage",\n              "equals": true\n            }\n          ]\n        },\n        "tags": [\