(101, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.PersonalityQuiz', 'Personality Quiz', 1, 0, 8, 1, 0, 0, 'iframe', 'js/personalityQuiz.js, js/wheelAnimation.js', 'css/personalityQuiz.css', '', '[\n    {\n        "name": "titleScreen",\n        "type": "group",\n        "label": "Title Screen",\n        "expanded": true,\n        "fields": [\n            {\n                "name": "title",\n                "type": "group",\n                "label": "Title",\n                "expanded": true,\n                "fields": [\n                    {\n                        "name": "text",\n                        "type": "text",\n                        "label": "Title"\n                    },\n                    {\n                        "name": "display",\n                        "type": "boolean",\n                        "label": "Display Title",\n                        "description": "Wether or not to show the title as a headline at the start of the personality quiz.",\n                        "default": true\n                    }\n                ]\n            },\n            {\n                "name": "image",\n                "type": "group",\n                "label": "Optional: Image",\n                "optional": true,\n                "fields": [\n                    {\n                        "name": "file",\n                        "type": "image",\n                        "label": "File"\n                    },\n                    {\n                        "name": "alt",\n                        "type": "text",\n                        "label": "Alt text",\n                        "description": "Alternative text if the browser is unable to load the image."\n                    }\n                ]\n            },\n            {\n                "name": "skip",\n                "label": "Skip",\n                "type": "boolean",\n                "description": "Select if you want the quiz to start on the first question instead of the title screen.",\n                "default": false\n            }\n        ]\n    },\n    {\n        "name": "resultScreen",\n        "type": "group",\n        "label": "Result screen",\n        "fields": [\n            {\n                "name": "animation",\n                "type": "select",\n                "label": "Animation",\n                "description": "The Wheel of Fortune animation will only use the images associated with personalities if ALL personalities has an image associated with them.",\n                "default": "none",\n                "options": [\n                    {\n                        "label": "None",\n                        "value": "none"\n                    },\n                    {\n                        "label": "Fade in",\n                        "value": "fade-in"\n                    },\n                    {\n                        "label": "Wheel of Fortune",\n                        "value": "wheel"\n                    }\n                ]\n            },\n            {\n                "name": "displayTitle",\n                "type": "boolean",\n                "label": "Display personality title?",\n                "default": true\n            },\n            {\n                "name": "displayDescription",\n                "type": "boolean",\n                "label": "Display description?",\n                "default": true\n            },\n            {\n                "name": "imagePosition",\n                "type": "select",\n                "label": "Personality Image Position",\n                "description": "Choose how to display the image, if there is any, of the result personality. Background will fill the entire H5P container and center the image. Inline will put the image as an image element between the result personality name and description.",\n                "default": "background",\n                "options": [\n                    {\n                        "value": "background",\n                        "label": "Background"\n                    },\n                    {\n                        "value": "inline",\n                        "label": "Inline"\n                    }\n                ]\n            }\n        ]\n    },\n    {\n        "name": "personalities",\n        "type": "list",\n        "label": "Personality",\n        "entity": "personality",\n        "min": 2,\n        "max": 10,\n        "field": {\n            "name": "personality",\n            "type": "group",\n            "label": "Personality",\n            "fields": [\n                {\n                    "name": "name",\n                    "type": "text",\n                    "label": "Personality name",\n                    "description": "The personality name will be used to associate answers with their respective personalities."\n                },\n                {\n                    "name": "description",\n                    "type": "text",\n                    "label": "Description",\n                    "maxLength": 450,\n                    "widget": "textarea"\n                },\n                {\n                    "name": "image",\n                    "type": "group",\n                    "label": "Optional: Image",\n                    "optional": true,\n                    "fields": [\n                        {\n                            "name": "file",\n                            "type": "image",\n                            "label": "Image",\n                            "description": "An image to display on the result screen."\n                        },\n                        {\n                            "name": "alt",\n                            "type": "text",\n                            "label": "Alt text",\n                            "description": "Alternative text if the browser is unable to load the image."\n                        }\n                    ]\n                }\n            ]\n        }\n    },\n    {\n        "name": "questions",\n        "type": "list",\n        "label": "Questions",\n        "entity": "question",\n        "field": {\n            "name": "question",\n            "type": "group",\n            "label": "Question",\n            "fields": [\n                {\n                    "name": "text",\n                    "type": "text",\n                    "label": "Question"\n                },\n                {\n                    "name": "image",\n                    "type": "group",\n                    "label": "Optional: Image",\n                    "description": "Image displayed at the top of the screen above or below the question text.",\n                    "optional": true,\n                    "fields": [\n                        {\n                            "name": "file",\n                            "type": "image",\n                            "label": "File"\n                        },\n                        {\n                            "name": "alt",\n                            "type": "text",\n                            "label": "Alt text",\n                            "description": "Alternative text if the browser is unable to load the image."\n                        }\n                    ]\n                },\n                {\n                    "name": "answers",\n                    "type": "list",\n                    "label": "Answers",\n                    "entity": "answer",\n                    "min": 2,\n                    "max": 6,\n                    "field": {\n                        "name": "answer",\n                        "type": "group",\n                        "label": "Answer",\n                        "fields": [\n                            {\n                                "name": "text",\n                                "type": "text",\n                                "label": "text"\n                            },\n                            {\n                                "name": "personality",\n                                "type": "text",\n                                "label": "Personalities",\n                                "description": "A comma separated list of personality names associated with this answer."\n                            },\n                            {\n                                "name": "image",\n                                "type": "group",\n                                "description": "Images associated with answers will not show up unless all answers associated with a question has an image attached.",\n                                "label": "Optional: Image",\n                                "optional": true,\n                                "fields": [\n                                    {\n                                        "name": "file",\n                                        "type": "image",\n                                        "label": "File"\n                                    },\n                                    {\n                                        "name": "alt",\n                                        "type": "text",\n                                        "label": "Alt text",\n                                        "description": "Alternative text if the browser is unable to load the image."\n                                    }\n                                ]\n                            }\n                        ]\n                    }\n                }\n            ]\n        }\n    },\n    {\n        "label": "Start",\n        "name": "startText",\n        "type": "text",\n        "default": "Start",\n        "description": "Text displayed on the start quiz button on the title card."\n    },\n    {\n        "label": "Progress text",\n        "name": "progressText",\n        "type": "text",\n        "default": "@question of @total",\n        "description": "Progress text, variables available: @question and @total. Example: ''@question of @total''"\n    },\n    {\n        "name": "retakeText",\n        "label": "Retake",\n        "type": "text",\n        "default": "Retake the quiz",\n        "description": "Retake text"\n    },\n    {\n        "name": "animation",\n        "type": "boolean",\n        "label": "Animation",\n        "default": true,\n        "description": "Uncheck to turn off all animation"\n    },\n    {\n        "name": "buttonColor",\n        "type": "text",\n        "label": "Button Accent",\n        "description": "Change the color of the button borders and the animation color fill",\n        "default": "4D5DAA",\n        "widget": "colorSelector"\n    },\n    {\n        "name": "progressbarColor",\n        "type": "text",\n        "label": "Progressbar Color",\n        "description": "Determines the color of the progress bar",\n        "default": "38B755",\n        "widget": "colorSelector"\n    }\n]\n', '', 0, NULL, NULL),
(102, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5PEditor.ColorSelector', 'H5PEditor.ColorSelector', 1, 0, 3, 0, 0, 0, '', 'scripts/spectrum.js, scripts/color-selector.js', 'styles/spectrum.css, styles/color-selector.css', '', '', '', 0, NULL, NULL),
(103, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.GoToScene', 'Go To Scene', 0, 1, 0, 0, 0, 0, '', 'scripts/go-to-scene.js', '', '', '[\n  {\n    "name": "nextSceneId",\n    "type": "number",\n    "label": "Go to scene with ID",\n    "importance": "high",\n    "description": "ID of the scene that we will jump to"\n  }\n]', '', 0, NULL, NULL),
(104, '0000-00-00 00:00:00', '0000-00-00 00:00:00', 'H5P.ThreeImage', 'Virtual Tour (360)', 0, 5, 8, 1, 0, 1, 'iframe', 'dist/h5p-three-image.js', 'dist/h5p-three-image.css', '', '[\n  {\n    "name": "threeImage",\n    "type": "group",\n    "widget": "threeImage",\n    "label": "Three Image Editor",\n    "importance": "high",\n    "fields": [\n      {\n        "name": "scenes",\n        "type": "list",\n        "label": "Scenes",\n        "entity": "Scene",\n        "min": 0,\n        "field": {\n          "name": "scene",\n          "type": "group",\n          "fields": [\n            {\n              "name": "sceneType",\n              "type": "select",\n              "label": "Scene type",\n              "widget": "radioGroup",\n              "alignment": "horizontal",\n              "options": [\n                {\n                  "value": "360",\n                  "label": "360 image"\n                },\n                {\n                  "value": "static",\n                  "label": "Static image"\n                }\n              ],\n              "default": "360"\n            },\n            {\n              "name": "showBackButton",\n              "type": "boolean",\n              "label": "Display \\"Back\\" button",\n              "description": "Display button for navigating back to your previous scene",\n              "default": true,\n              "widget": "showWhen",\n              "showWhen": {\n                "rules": [\n                  {\n                    "field": "sceneType",\n                    "equals": "static"\n                  }\n                ]\n              }\n            },\n            {\n              "name": "sceneId",\n              "type": "number"\n            },\n            {\n              "name": "scenename",\n              "type": "text",\n              "label": "Scene Title",\n              "description": "Used to identify the scene"\n            },\n            {\n              "name": "scenesrc",\n              "type": "image",\n              "label": "Scene Background"\n            },\n            {\n              "name": "scenedescription",\n              "type": "text",\n              "widget": "html",\n              "label": "Scene Description",\n              "description": "A text that can describe the scene for the end-user",\n              "optional": true,\n              "tags": [\n                "p",\n                "br",\n                "strong",\n                "em",\n                "code"\n              ]\n            },\n            {\n              "name": "cameraStartPosition",\n              "type": "text"\n            },\n            {\n              "name": "interactions",\n              "type": "list",\n              "min": 0,\n              "field": {\n                "name": "interaction",\n                "type": "group",\n                "fields": [\n                  {\n                    "name": "labelText",\n                    "type": "text",\n                    "label": "Label",\n                    "optional": true,\n                    "description": "If left blank no label will be displayed and we''ll try to use the title field for screen readers"\n                  },\n                  {\n                    "name": "label",\n                    "type": "group",\n                    "label": "Label Settings",\n                    "importance": "low",\n                    "fields": [\n                      {\n                        "name": "labelPosition",\n                        "type": "select",\n                        "label": "Label position",\n                        "description": "Choose where the label should appear",\n                        "options": [\n                          {\n                            "value": "inherit",\n                            "label": "Use behavioral setting"\n                          },\n                          {\n                            "value": "right",\n                            "label": "Right aligned"\n                          },\n                          {\n                            "value": "left",\n                            "label": "Left aligned"\n                          },\n                          {\n                            "value": "top",\n                            "label": "Top aligned"\n                          },\n                          {\n                            "value": "bottom",\n                            "label": "Bottom aligned"\n                          }\n                        ],\n                        "default": "inherit"\n                      },\n                      {\n                        "name": "showLabel",\n                        "type": "select",\n                        "label": "Display Label",\n                        "description": "If hidden - labels will show only on mouse over",\n                        "options": [\n                          {\n                            "value": "inherit",\n                            "label": "Use behavioral setting"\n                          },\n                          {\n                            "value": "show",\n                            "label": "Show"\n                          },\n                          {\n                            "value": "hide",\n                            "label": "Hide"\n                          }\n                        ],\n                        "default": "inherit"\n                      }\n                    ]\n                  },\n                  {\n                    "name": "action",\n                    "type": "library",\n                    "options": [\n                      "H5P.GoToScene 0.1",\n                      "H5P.AdvancedText 1.1",\n                      "H5P.Image 1.1",\n                      "H5P.Audio 1.5",\n                      "H5P.Video 1.6",\n                      "H5P.Summary 1.10",\n                      "H5P.SingleChoiceSet 1.11"\n                    ]\n                  },\n                  {\n                    "name": "interactionpos",\n                    "type": "text"\n                  }\n                ]\n              }\n            },\n            {\n              "name": "iconType",\n              "type": "select",\n              "label": "Button style",\n              "description": "Decide how buttons pointing to this scene should look. For scenes that are static and does not lead to new scenes, we recommend the \\"More information\\" button.",\n              "widget": "radioGroup",\n              "alignment": "horizontal",\n              "options": [\n                {\n                  "value": "arrow",\n                  "label": "New scene (arrow)"\n                },\n                {\n                  "value": "plus",\n                  "label": "More information (plus)"\n                }\n              ],\n              "default": "arrow"\n            },\n            {\n              "name": "audio",\n              "type": "audio",\n              "label": "Audio Track",\n              "description": "Add an audio track that''s specific for this scene.",\n              "optional": true,\n              "widgetExtensions": [\n                "AudioRecorder"\n              ]\n            }\n          ]\n        }\n      },\n      {\n        "name": "startSceneId",\n        "type": "number",\n        "default": 0\n      },\n      {\n        "name": "audio",\n        "type": "audio",\n        "label": "Audio track",\n        "optional": true\n      }\n    ]\n  },\n  {\n    "name": "behaviour",\n    "type": "group",\n    "label": "Behavioral settings",\n    "importance": "low",\n    "description": "These options will let you control how the world behaves.",\n    "fields": [\n      {\n        "name": "audio",\n        "type": "audio",\n        "label": "Global Audio",\n        "description": "Add an audio track that''s available for all of the scenes by default.",\n        "optional": true,\n        "widgetExtensions": [\n          "AudioRecorder"\n        ]\n      },\n      {\n        "name": "sceneRenderingQuality",\n        "type": "select",\n        "label": "Scene rendering quality",\n        "description": "Choose the amount of width and height segments used to render a scene. This directly affects the quality level of the scene, try increasing the quality if a scene looks \\"blocky\\" or \\"waves\\" are seen within the scenes. Note that higher quality rendering takes more time to load.",\n        "options": [\n          {\n            "value": "high",\n            "label": "High Quality (128x128)"\n          },\n          {\n            "value": "medium",\n            "label": "Medium Quality (64x64)"\n          },\n          {\n            "value": "low",\n            "label": "Low Quality (16x16)"\n          }\n        ],\n        "default": "high"\n      },\n      {\n        "name": "label",\n        "type": "group",\n        "label": "Label settings",\n        "importance": "low",\n        "expanded": true,\n        "fields": [\n          {\n            "name": "labelPosition",\n            "type": "select",\n            "label": "Label position",\n            "description": "The default label position. The position may be overriden per interaction",\n            "options": [\n              {\n                "value": "right",\n                "label": "Right aligned"\n              },\n              {\n                "value": "left",\n                "label": "Left aligned"\n              },\n              {\n                "value": "top",\n                "label": "Top aligned"\n              },\n              {\n                "value": "bottom",\n                "label": "Bottom aligned"\n              }\n            ],\n            "default": "right"\n          },\n          {\n            "name": "showLabel",\n            "type": "boolean",\n            "label": "Display Labels",\n            "description": "If unchecked - labels will show only on mouse over",\n            "default": true\n          }\n        ]\n      }\n    ]\n  },\n  {\n    "name": "l10n",\n    "type": "group",\n    "common": true,\n    "label": "Localize",\n    "fields": [\n      {\n        "name": "title",\n        "type": "text",\n        "label": "Aria label for content type",\n        "default": "Virtual Tour"\n      },\n      {\n        "name": "playAudioTrack",\n        "type": "text",\n        "label": "Label for to play audio",\n        "default": "Play Audio Track"\n      },\n      {\n        "name": "pauseAudioTrack",\n        "type": "text",\n        "label": "Label to pause audio",\n        "default": "Pause Audio Track"\n      },\n      {\n        "name": "sceneDescription",\n        "type": "text",\n        "label": "Title to scene dialog",\n        "default": "Scene Description"\n      },\n      {\n        "name": "resetCamera",\n        "type": "text",\n        "label": "Label for button to reset camera",\n        "default": "Reset Camera"\n      },\n      {\n        "name": "submitDialog",\n        "type": "text",\n        "label": "Label for the submit dialog button",\n        "default": "Submit Dialog"\n      },\n      {\n        "name": "closeDialog",\n        "type": "text",\n        "label": "Label for the close dialog button",\n        "default": "Close Dialog"\n      },\n      {\n        "name": "expandButtonAriaLabel",\n        "type": "text",\n        "label": "Aria label for the expand label button",\n        "default": "Expand the visual label"\n      },\n      {\n        "name": "backgroundLoading",\n        "type": "text",\n        "label": "Label for when background image is loading in 360 scene",\n        "default": "Loading background image..."\n      },\n      {\n        "name": "noContent",\n        "type": "text",\n        "label": "Label for when there is no content",\n        "default": "No content"\n      }\n    ]\n  }\n]', '', 1, NULL, NULL);
