(12, 'fa', '{\n  "semantics": [\n    {\n      "label": "فایل‌های منبع"\n    },\n    {\n      "label": "حالت پخش‌کننده",\n      "description": "طرح پخش‌کننده را انتخاب کنید.",\n      "options": [\n        {\n          "label": "مینیمالیستی"\n        },\n        {\n          "label": "پر"\n        },\n        {\n          "label": "شفاف"\n        }\n      ]\n    },\n    {\n      "label": "به اندازه کادر پوشش"\n    },\n    {\n      "label": "فعال‌سازی کنترل‌ها",\n      "description": "کنترل‌ها به کاربر اجازه می‌دهند تا به عنوان مثال صدا را متوقف کند"\n    },\n    {\n      "label": "فعال‌سازی پخش خودکار",\n      "description": "با فعال‌سازی پخش خودکار، صدا بلافاصله پخش می‌شود. در صورت غیرفعال‌سازی، برای شروع صدا کاربر یک دکمه پخش را می‌فشارد."\n    },\n    {\n      "label": "پخش صدا (مبدل متن به گفتار)",\n      "default": "پخش صدا"\n    },\n    {\n      "label": "مکث صدا (مبدل متن به گفتار)",\n      "default": "مکث صدا"\n    },\n    {\n      "label": "نام محتوای صوتی",\n      "default": "صدا"\n    },\n    {\n      "label": "پیام صوت پشتیبانی نمی‌شود",\n      "default": "مرورگر شما از این صوت پشتیبانی نمی‌کند"\n    }\n  ]\n}\n'),
