(18, 'smj', '{\n  "semantics": [\n    {\n      "label": "Check answer button",\n      "default": "Check"\n    },\n    {\n      "label": "Submit answer button",\n      "default": "Submit"\n    },\n    {\n      "label": "Retry button",\n      "default": "Retry"\n    },\n    {\n      "label": "Score explanation text",\n      "default": "Correct answers give +1 point. Incorrect answers give -1 point. The lowest possible score is 0."\n    },\n    {\n      "fields": [\n        {\n          "label": "Settings",\n          "fields": [\n            {\n              "label": "Background image",\n              "description": "Optional. Select an image to use as background for your drag and drop task."\n            },\n            {\n              "label": "Task size",\n              "description": "Specify how large (in px) the play area should be."\n            }\n          ]\n        },\n        {\n          "label": "Task",\n          "description": "Start by placing your drop zones.<br />Next, place your droppable elements and check off the appropriate drop zones.<br />Last, edit your drop zone again and check off the correct answers.",\n          "fields": [\n            {\n              "label": "Elements",\n              "entity": "element",\n              "field": {\n                "label": "Element",\n                "fields": [\n                  {\n                    "description": "Choose the type of content you would like to add."\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Select drop zones"\n                  },\n                  {\n                    "label": "Background Opacity",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Infinite number of element instances",\n                    "description": "Clones this element so that it can be dragged to multiple drop zones."\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Drop Zones",\n              "entity": "Drop Zone",\n              "field": {\n                "label": "Drop Zone",\n                "fields": [\n                  {\n                    "label": "Label",\n                    "description": "The label is used by assistive technologies."\n                  },\n                  {\n                    "label": "Show label"\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Select correct elements"\n                  },\n                  {\n                    "label": "Background Opacity",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Tips and feedback",\n                    "fields": [\n                      {\n                        "label": "Tip text"\n                      },\n                      {\n                        "label": "Message displayed on correct match",\n                        "description": "Message will appear below the task on \\"check\\" if correct droppable is matched."\n                      },\n                      {\n                        "label": "Message displayed on incorrect match",\n                        "description": "Message will appear below the task on \\"check\\" if the match is incorrect."\n                      }\n                    ]\n                  },\n                  {\n                    "label": "This drop zone can only contain one element",\n                    "description": "Make sure there is only one correct answer for this dropzone"\n                  },\n                  {\n                    "label": "Enable Auto-Align",\n                    "description": "Will auto-align all draggables dropped in this zone."\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Default"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Behavioural settings",\n      "description": "These options will let you control how the task behaves.",\n      "fields": [\n        {\n          "label": "Enable \\"Retry\\""\n        },\n        {\n          "label": "Enable \\"Check\\" button"\n        },\n        {\n          "label": "Give one point for the whole task",\n          "description": "Disable to give one point for each draggable that is placed correctly."\n        },\n        {\n          "label": "Apply penalties",\n          "description": "Apply penalties for elements dropped in the wrong drop zones. This must be enabled when the same element(s) are able to be dropped into multiple drop zones, or if there is only one drop-zone. If this is not enabled, learners may match all items to all drop-zones and always receive a full score."\n        },\n        {\n          "label": "Enable score explanation",\n          "description": "Display a score explanation to user when checking their answers (if the ''Apply penalties'' option has been selected)."\n        },\n        {\n          "label": "Background opacity for draggables",\n          "description": "If this field is set, it will override opacity set on all draggable elements. This should be a number between 0 and 100, where 0 means full transparency and 100 means no transparency"\n        },\n        {\n          "label": "Drop Zone Highlighting",\n          "description": "Choose when to highlight drop zones.",\n          "options": [\n            {\n              "label": "When dragging"\n            },\n            {\n              "label": "Always"\n            },\n            {\n              "label": "Never"\n            }\n          ]\n        },\n        {\n          "label": "Spacing for Auto-Align (in px)"\n        },\n        {\n          "label": "Enable FullScreen",\n          "description": "Check this option to enable the full screen button."\n        },\n        {\n          "label": "Show score points",\n          "description": "Show points earned for each answer. Not available when the ''Give one point for the whole task'' option is enabled."\n        },\n        {\n          "label": "Show Title",\n          "description": "Uncheck this option if you do not want this title to be displayed. The title will only be displayed in summaries, statistics etc."\n        }\n      ]\n    },\n    {\n      "label": "Localize",\n      "fields": [\n        {\n          "label": "Fullscreen label",\n          "default": "Fullscreen"\n        },\n        {\n          "label": "Exit fullscreen label",\n          "default": "Exit fullscreen"\n        }\n      ]\n    },\n    {\n      "label": "Grabbable prefix",\n      "default": "Grabbable {num} of {total}."\n    },\n    {\n      "label": "Grabbable suffix",\n      "default": "Placed in dropzone {num}."\n    },\n    {\n      "label": "Dropzone prefix",\n      "default": "Dropzone {num} of {total}."\n    },\n    {\n      "label": "No dropzone selection label",\n      "default": "No dropzone."\n    },\n    {\n      "label": "Label for show tip button",\n      "default": "Show tip."\n    },\n    {\n      "label": "Label for tip available",\n      "default": "Tip available"\n    },\n    {\n      "label": "Label for correct answer",\n      "default": "Correct answer"\n    },\n    {\n      "label": "Label for incorrect answer",\n      "default": "Wrong answer"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "Feedback"\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Textual representation of the score explanation button",\n      "default": "Show score explanation"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(18, 'sr', '{\n  "semantics": [\n    {\n      "label": "Проверите дугме за одговор",\n      "default": "Провери"\n    },\n    {\n      "label": "Submit answer button",\n      "default": "Submit"\n    },\n    {\n      "label": "Дугме за поновни покушај",\n      "default": "Врати"\n    },\n    {\n      "label": "Текст објашњења резултата",\n      "default": "Тачни одговори дају +1 поен. Нетачни одговори дају -1 поен. Најнижа могућа оцена је 0."\n    },\n    {\n      "fields": [\n        {\n          "label": "Подешавања",\n          "fields": [\n            {\n              "label": "Позадинска слика",\n              "description": "Опционо. Изаберите слику коју ћете користити као позадину за задатак превлачења и испуштања."\n            },\n            {\n              "label": "Величина",\n              "description": "Наведите колико велико (у пикселима) треба да буде подручје за игру."\n            }\n          ]\n        },\n        {\n          "label": "Задатак",\n          "description": "Започните постављањем зона испуштања.<br />Затим поставите елементе који се могу испустити и означите одговарајуће зоне испуштања.<br />На крају, поново уредите своју зону испуштања и означите тачне одговоре.",\n          "fields": [\n            {\n              "label": "Елементи",\n              "entity": "element",\n              "field": {\n                "label": "Елемент",\n                "fields": [\n                  {\n                    "description": "Изаберите врсту садржаја који желите да додате."\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Изаберите зоне испуштања"\n                  },\n                  {\n                    "label": "Непрозирност позадине",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Бесконачан број инстанци елемената",\n                    "description": "Клонира овај елемент тако да се може повући у више зона испуштања."\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Зоне испуштања",\n              "entity": "Drop Zone",\n              "field": {\n                "label": "Зона испуштања",\n                "fields": [\n                  {\n                    "label": "Ознака",\n                    "description": "The label is used by assistive technologies."\n                  },\n                  {\n                    "label": "Прикажи ознаку"\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Изаберите тачне елементе"\n                  },\n                  {\n                    "label": "Непрозирност позадине",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Савети и повратне информације",\n                    "fields": [\n                      {\n                        "label": "Текст савета"\n                      },\n                      {\n                        "label": "Порука приказана на тачном подударању",\n                        "description": "Порука ће се појавити испод задатка на \\"провери\\" ако се подудара тачно испуштање."\n                      },\n                      {\n                        "label": "Порука приказана на нетачном подударању",\n                        "description": "Порука ће се појавити испод задатка на \\"провери\\" ако је подударање нетачно."\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Ова зона испуштања може садржати само један елементt",\n                    "description": "Уверите се да постоји само један тачан одговор за ову зону испуштања"\n                  },\n                  {\n                    "label": "Омогући аутоматско поравнање",\n                    "description": "Да ли ће аутоматски поравнати сви елементи испуштене у овој зони."\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Укупне повратне информације",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Уобичајено"\n            }\n          ],\n          "label": "Дефинишите прилагођене повратне информације за било који опсег резултата",\n          "description": "Кликните на \\"Додај опсег\\" дугме за додавање онолико опсега колико вам је потребно. Пример: 0-20% Лош резултат, 21-91% Просечан резултат, 91-100% Одличан резултат!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Повратне информације за дефинисани опсег резултата",\n                "placeholder": "Попуните повратне информације"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Поставке понашања",\n      "description": "Ове опције ће вам омогућити да контролишете понашање задатка.",\n      "fields": [\n        {\n          "label": "Омогући \\"Врати\\""\n        },\n        {\n          "label": "Омогући \\"Провери\\" дугме"\n        },\n        {\n          "label": "Дајте један поен за цео задатак",\n          "description": "Онемогућите да бисте дали један поен за сваки повучени елемент који је правилно постављен."\n        },\n        {\n          "label": "Применити казне",\n          "description": "Примените казне за елементе који су пали у погрешним зонама испуштања. Ово мора бити омогућено када исти елементи могу да се испуштају у више зона испуштања или ако постоји само једна зона испуштања. Ако ово није омогућено, ученици могу да подударају све ставке са свим падним зонама и увек добију пуну оцену."\n        },\n        {\n          "label": "Омогући објашњење резултата",\n          "description": "Прикажите објашњење резултата кориснику приликом провере њихових одговора (ако је изабрана опција „Примени казне“)."\n        },\n        {\n          "label": "Непрозирност позадине за повлачење",\n          "description": "Ако је ово поље постављено, оно ће заменити непрозирност постављену на свим елементима који се могу повући. Ово би требало да буде број између 0 и 100, где 0 значи потпуну транспарентност, а 100 значи да нема транспарентности"\n        },\n        {\n          "label": "Истицање зоне пада",\n          "description": "Изаберите када желите да истакнете зоне испуштања.",\n          "options": [\n            {\n              "label": "При вучењу"\n            },\n            {\n              "label": "Увек"\n            },\n            {\n              "label": "Никад"\n            }\n          ]\n        },\n        {\n          "label": "Размак за аутоматско поравнање (у пикселима)"\n        },\n        {\n          "label": "Омогући цели екран",\n          "description": "Означите ову опцију да бисте омогућили дугме за цели екран."\n        },\n        {\n          "label": "Покажи бодове",\n          "description": "Покажите бодове за сваки одговор. Није доступно када је омогућена опција Дај један бод за цео задатак"\n        },\n        {\n          "label": "Прикажи наслов",\n          "description": "Опозовите избор ове опције ако не желите да се приказује овај наслов. Наслов ће бити приказан само у резимеима, статистикама итд."\n        }\n      ]\n    },\n    {\n      "label": "Локализовати",\n      "fields": [\n        {\n          "label": "Ознака целог екрана",\n          "default": "Цео екран"\n        },\n        {\n          "label": "Изађите из Целог екрана",\n          "default": "Изађи из целог екрана"\n        }\n      ]\n    },\n    {\n      "label": "Префикс за грабирање",\n      "default": "Grabbable {num} од {total}."\n    },\n    {\n      "label": "Суфикс за грабирање",\n      "default": "Смештено у зони испуштања {num}."\n    },\n    {\n      "label": "Префикс зоне испуштања",\n      "default": "Зона испуштања {num} од {total}."\n    },\n    {\n      "label": "Нема ознаке за одабир зоне испуштања",\n      "default": "Нема зоне испуштања."\n    },\n    {\n      "label": "Ознака за дугме савета",\n      "default": "Прикажи савет."\n    },\n    {\n      "label": "Ознака за доступност савета",\n      "default": "Савет доступан"\n    },\n    {\n      "label": "Ознака за тачан одговор",\n      "default": "Тачан одговор"\n    },\n    {\n      "label": "Ознака за нетачан одговор",\n      "default": "Погрешан одговор"\n    },\n    {\n      "label": "Заглавље панела који садржи повратне информације за тачне / нетачне одговоре",\n      "default": "Повратна информација"\n    },\n    {\n      "label": "Текстуални приказ бодовне траке за оне који користе читач звука",\n      "default": "Освојили сте :num од :total поена"\n    },\n    {\n      "label": "Текстуални приказ дугмета за објашњење резултата",\n      "default": "Прикажи објашњење резултата"\n    },\n    {\n      "label": "Ознака помоћне технологије за \\"Провери\\" дугме",\n      "default": "Проверите одговоре. Одговори ће бити означени као тачни, нетачни или без одговора."\n    },\n    {\n      "label": "Ознака помоћне технологије за \\"Врати\\" дугме",\n      "default": "Покушајте поново са задатком. Ресетујте све одговоре и покрените задатак поново."\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(18, 'sv', '{\n  "semantics": [\n    {\n      "label": "Svara-knappen",\n      "default": "Svara"\n    },\n    {\n      "label": "Knapp för att skicka in svar",\n      "default": "Submit"\n    },\n    {\n      "label": "\\"Försök igen\\"-knapp",\n      "default": "Försök på nytt"\n    },\n    {\n      "label": "Poängförklaringstext",\n      "default": "Korrekta svar ger +1 poäng. Felaktiga svar ger -1 poäng. Lägsta möjliga poäng är 0."\n    },\n    {\n      "fields": [\n        {\n          "label": "Inställningar",\n          "fields": [\n            {\n              "label": "Bakgrundsbild",\n              "description": "Valfritt. Välj en bild att använda som bakgrund till din drag-och-släpp-uppgift."\n            },\n            {\n              "label": "Storlek på uppgift",\n              "description": "Ange hur stor (i px) ytan ska vara."\n            }\n          ]\n        },\n        {\n          "label": "Uppgift",\n          "description": "Börja med att placera dina målområden.<br />Placera sen dina drag-och-släppbara element, och markera vilka målområden de ska kunna dras till.<br />Till sist, redigera målområdena igen för att ange de korrekta svaren.",\n          "fields": [\n            {\n              "label": "Element",\n              "entity": "element",\n              "field": {\n                "label": "Element",\n                "fields": [\n                  {\n                    "description": "Välj typ av innehåll som du vill lägga till."\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Välj målområden"\n                  },\n                  {\n                    "label": "Bakgrunds-opacitet",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Oändligt antal instanser av elementet",\n                    "description": "Klonar detta element så att det kan dras till flera målområden."\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Målområden",\n              "entity": "Målområde",\n              "field": {\n                "label": "Målområde",\n                "fields": [\n                  {\n                    "label": "Etikett",\n                    "description": "The label is used by assistive technologies."\n                  },\n                  {\n                    "label": "Visa etikett"\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Välj korrekta element"\n                  },\n                  {\n                    "label": "Bakgrunds-opacitet",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Tips och feedback",\n                    "fields": [\n                      {\n                        "label": "Tipstext"\n                      },\n                      {\n                        "label": "Meddelande som visas vid korrekt matchning",\n                        "description": "Meddelande kommer att visas under uppgiften när knappen \\"svara\\" klickas, om korrekt matchning är gjord."\n                      },\n                      {\n                        "label": "Meddelande kommer att visas när matchningen är felaktig",\n                        "description": "Meddelande kommer att visas under uppgiften när knappen \\"svara\\" klickas, om matchning är felaktig."\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Detta målområde kan bara innehålla ett element",\n                    "description": "Säkerställ att det bara finns ett korrekt svar för detta målområde"\n                  },\n                  {\n                    "label": "Aktivera automatisk linjering",\n                    "description": "Kommer att automatiskt linjera alla drag-och-släppbara element i detta område."\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Generell feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Standard"\n            }\n          ],\n          "label": "Ange anpassad feedback för valfritt poängintervall",\n          "description": "Klicka på knappen \\"Lägg till intervall\\" för att lägga till så många intervall du behöver. Exempel: 0-20% Inte så bra, 21-91% Medel, 91-100% Jättebra!",\n          "entity": "intervall",\n          "field": {\n            "fields": [\n              {\n                "label": "Poängintervall"\n              },\n              {},\n              {\n                "label": "Feedback för definierad poängintervall",\n                "placeholder": "Fyll i feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Beteende-inställningar",\n      "description": "Dessa val låter dig kontrollera hur uppgiften beter sig.",\n      "fields": [\n        {\n          "label": "Aktivera \\"Försök igen\\""\n        },\n        {\n          "label": "Aktivera \\"Svara\\"-knappen"\n        },\n        {\n          "label": "Ge ett poäng för hela uppgiften",\n          "description": "Inaktivera för att ge ett poäng för varje dragbart element som är korrekt placerat."\n        },\n        {\n          "label": "Tillämpa straff",\n          "description": "Tillämpa straff för element som släpps i felaktiga målområden. Detta måste vara aktiverat när samma element kan släppas i flera målområden, eller om det bara finns ett målområde. Om detta inte är aktiverat, så kan deltagare placera ut alla element i alla målområden och därmed alltid få full poäng."\n        },\n        {\n          "label": "Aktivera poängförklaring",\n          "description": "Visa en poängförklaring för användaren när denne klickar \\"svara\\" (om inställningen \\"Tillämpa straff\\" har valts)."\n        },\n        {\n          "label": "Backgrunds-opacitet för drag-och-släppbara element",\n          "description": "Om värde anges här, så kommer det att användas som opacitet på alla dragbara element. Värdet ska vara mellan 0 och 100, där 0 innebär helt genomskinligt och 100 innebär ingen genomskinlighet."\n        },\n        {\n          "label": "Framhävning av målområde",\n          "description": "Välj detta för att framhäva målområden.",\n          "options": [\n            {\n              "label": "När man drar"\n            },\n            {\n              "label": "Alltid"\n            },\n            {\n              "label": "Aldrig"\n            }\n          ]\n        },\n        {\n          "label": "Mellanrum för automatisk justering (i pixlar)"\n        },\n        {\n          "label": "Aktivera fullskärm",\n          "description": "Välj denna inställning för att aktivera fullskärmsknappen."\n        },\n        {\n          "label": "Visa poäng",\n          "description": "Visa poäng utifrån varje svar. Inte tillgängligt när inställningen \\"Ge ett poäng för hela uppgiften\\" är vald."\n        },\n        {\n          "label": "Visa titel",\n          "description": "Bocka ur detta om du vill att din titel inte ska visas. Titeln kommer bara visas i sammanfattningar, statistik, etc."\n        }\n      ]\n    },\n    {\n      "label": "Lokalisera",\n      "fields": [\n        {\n          "label": "Etikett för knappen \\"fullskärm\\"",\n          "default": "Fullskärm"\n        },\n        {\n          "label": "Etikett för knappen \\"Avsluta fullskärm\\"",\n          "default": "Avsluta fullskärm"\n        }\n      ]\n    },\n    {\n      "label": "Prefix för dragbar",\n      "default": "Dragbar {num} av {total}."\n    },\n    {\n      "label": "Suffix för dragbar",\n      "default": "Placerad i målområde {num}."\n    },\n    {\n      "label": "Prefix för målområde",\n      "default": "Målområde {num} av {total}."\n    },\n    {\n      "label": "Etikett för inget målområde valt",\n      "default": "Inget målområde."\n    },\n    {\n      "label": "Etikett för knappen \\"Visa tips\\"",\n      "default": "Visa tips."\n    },\n    {\n      "label": "Etikett för tillgängligt tips",\n      "default": "Tips tillgängligt"\n    },\n    {\n      "label": "Etikett för korrekt svar",\n      "default": "Korrekt svar"\n    },\n    {\n      "label": "Etikett för felaktigt svar",\n      "default": "Felaktigt svar"\n    },\n    {\n      "label": "Rubrik för panel som visar feedback avseende korrekta/felaktiga svar",\n      "default": "Feedback"\n    },\n    {\n      "label": "Textuell visning av poängindikator för de som använder skärmläsare",\n      "default": "Du fick :num av :total poäng"\n    },\n    {\n      "label": "Textuell visning av knappen som förklarar poäng",\n      "default": "Visa förklaring till poäng"\n    },\n    {\n      "label": "Etikett för knappen \\"Svara\\" som används av tillgänglighetshjälpmedel",\n      "default": "Rätta mina svar. Svaren kommer att markeras som korrekta, felaktiga eller ej besvarade."\n    },\n    {\n      "label": "Etikett för knappen \\"Försök igen\\" som används av tillgänglighetshjälpmedel",\n      "default": "Starta ett nytt försök. Nollställer alla svar och startar om uppgiften."\n    }\n  ]\n}\n'),
(18, 'sw', '{\n  "semantics": [\n    {\n      "label": "Angalia kitufe cha jibu",\n      "default": "Weka alama"\n    },\n    {\n      "label": "Wasilisha kitufe cha jibu",\n      "default": "Wasilisha"\n    },\n    {\n      "label": "Kitufe cha Jaribu tena",\n      "default": "Jaribu tena"\n    },\n    {\n      "label": "Maandishi ya ufafanuzi wa alama",\n      "default": "Majibu sahihi toa pointi +1. Majibu yasiyo sahihi toa pointi -1. Alama ya chini kabisa inayowezekana ni 0."\n    },\n    {\n      "fields": [\n        {\n          "label": "Mipangilio",\n          "fields": [\n            {\n              "label": "Picha ya mandharinyuma",\n              "description": "Ya hiari. Chagua picha ya kutumia kama mandharinyuma ya kazi yako ya kuburuta na kuacha."\n            },\n            {\n              "label": "Ukubwa wa kazi",\n              "description": "Taja jinsi kubwa (katika pikseli) eneo la kucheza linapaswa kuwa kubwa."\n            }\n          ]\n        },\n        {\n          "label": "Kazi",\n          "description": "Anza kwa kuweka maeneo yako ya kushuka.<br />Ifuatayo, weka vipengele vyako vinavyoweza kushuka na utekeleze maeneo yanayofaa ya kushuka.<br />Mwisho, hariri eneo lako la kushuka tena na utekeleze majibu sahihi.",\n          "fields": [\n            {\n              "label": "Vipengele",\n              "entity": "kipengele",\n              "field": {\n                "label": "Kipengele",\n                "fields": [\n                  {\n                    "description": "Chagua aina ya maudhui ambayo ungependa kuongeza."\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Chagua maeneo ya kushuka"\n                  },\n                  {\n                    "label": "Uangavu wa mandharinyuma",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Idadi isiyo na mwisho ya matukio ya vipengele",\n                    "description": "Huongeza maradufu kipengele hiki ili kiweze kuburutwa kwenye maeneo mengi ya kushuka."\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Maeneo ya Kushuka",\n              "entity": "Eneo la Kushuka",\n              "field": {\n                "label": "Eneo la Kushuka",\n                "fields": [\n                  {\n                    "label": "Lebo",\n                    "description": "The label is used by assistive technologies."\n                  },\n                  {\n                    "label": "Onyesha lebo"\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Chagua vipengele sahihi"\n                  },\n                  {\n                    "label": "Uangavu wa mandharinyuma",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Vidokezo na maoni",\n                    "fields": [\n                      {\n                        "label": "Maandishi ya kidokezo"\n                      },\n                      {\n                        "label": "Ujumbe ulioonyeshwa kwenye mechi sahihi",\n                        "description": "Ujumbe utaonekana chini ya kazi kwenye \\"weka alama\\" ikiwa kushuka sahihi kunalingana."\n                      },\n                      {\n                        "label": "Ujumbe ulioonyeshwa kwenye kulingana siyo sahihi",\n                        "description": "Ujumbe utaonekana chini ya kazi kwenye \\"weka alama\\" ikiwa kulingana huko siyo sahihi."\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Eneo hili la kushuka linaweza kuwa na kipengele kimoja tu",\n                    "description": "Hakikisha kuna jibu moja tu sahihi kwa eneo hili la kushuka"\n                  },\n                  {\n                    "label": "Washa mpangilio wa kiotomatiki",\n                    "description": "Itaunganisha kiotomatiki vitu vya kuburuta vyote viilivyoshuka katika eneo hili."\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Maoni ya Jumla",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Chaguo-msingi"\n            }\n          ],\n          "label": "Bainisha maoni maalum kwa masafa yoyote ya alama",\n          "description": "Bofya kitufe cha \\"Ongeza masafa\\" ili kuongeza masafa mengi unavyohitaji. Mfano: 0-20% Alama mbaya, 21-91% Alama ya Wastani, 91-100% Alama Nzuri!",\n          "entity": "masafa",\n          "field": {\n            "fields": [\n              {\n                "label": "Masafa ya Alama"\n              },\n              {},\n              {\n                "label": "Maoni kwa masafa ya alama yaliyofafanuliwa",\n                "placeholder": "Jaza maoni"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Mipangilio ya tabia",\n      "description": "Chaguzi hizi zitakuwezesha kudhibiti jinsi kazi inavyofanya.",\n      "fields": [\n        {\n          "label": "Wezesha \\"Jaribu tena\\""\n        },\n        {\n          "label": "Wezesha kitufe cha \\"Weka alama\\""\n        },\n        {\n          "label": "Toa pointi moja kwa kazi nzima",\n          "description": "Zima kutoa pointi moja kwa kila kitu kinachoweza kuburutwa ambacho kimewekwa kwa usahihi."\n        },\n        {\n          "label": "Tumia adhabu",\n          "description": "Tumia adhabu kwa vipengele vilivyoshushwa katika maeneo ya kushuka vibaya. Hii lazima iwashwe wakati elementi zilizo sawa zinaweza kushushwa katika maeneo mengi ya kushuka, au ikiwa kuna eneo moja tu la kushuka. Ikiwa hii haijawashwa, wanafunzi wanaweza kufananisha vitu vyote kwa maeneo yote ya kushuka na daima kupokea alama kamili."\n        },\n        {\n          "label": "Washa ufafanuzi wa alama",\n          "description": "Onyesha maelezo ya alama kwa mtumiaji wakati wa kuangalia majibu yao (ikiwa chaguo la ''Tumia adhabu'' limechaguliwa)."\n        },\n        {\n          "label": "Uangavu wa mandharinyuma kwa vitu vinavyoweza kuburutwa",\n          "description": "Ikiwa eneo hili litapangwa, itabatilisha uangavu uliowekwa kwenye vipengele vyote vinavyoweza kuburutwa. Hii inapaswa kuwa namba kati ya 0 na 100, ambapo 0 inamaanisha uwazi kamili na 100 inamaanisha hakuna uwazi"\n        },\n        {\n          "label": "Eneo la Kushuka Linaloangazia",\n          "description": "Chagua wakati wa kuonyesha maeneo ya kushuka.",\n          "options": [\n            {\n              "label": "Wakati wa kuburuta"\n            },\n            {\n              "label": "Daima"\n            },\n            {\n              "label": "Kamwe"\n            }\n          ]\n        },\n        {\n          "label": "Nafasi ya Kupanga kiotomatiki (katika pikseli)"\n        },\n        {\n          "label": "Washa Skrini Kamili",\n          "description": "Weka alama chaguo hili ili kuwasha kitufe cha skrini kamili."\n        },\n        {\n          "label": "Onyesha pointi za alama",\n          "description": "Onyesha pointi zilizopatikana kwa kila jibu. Haipatikani wakati chaguo la ''Toa pointi moja kwa kazi nzima'' limewashwa."\n        },\n        {\n          "label": "Onyesha Mada",\n          "description": "Futa chaguo hili ikiwa hutaki mada hii ionyeshwe. Mada itaonyeshwa tu katika muhtasari, takwimu na kadhalika."\n        }\n      ]\n    },\n    {\n      "label": "Janibisha",\n      "fields": [\n        {\n          "label": "Lebo kamili ya skrini",\n          "default": "Skrini nzima"\n        },\n        {\n          "label": "Toka lebo ya skrini kamili",\n          "default": "Toka skrini kamili"\n        }\n      ]\n    },\n    {\n      "label": "Kiambishi awali kinachoweza kunyakuliwa",\n      "default": "Kinachoweza kunyakuliwa {num} kati ya {total}."\n    },\n    {\n      "label": "kiambishi tamati kinachoweza kunyakuliwa",\n      "default": "Kimewekwa katika eneo la kushuka{num}."\n    },\n    {\n      "label": "Kiambishi awali cha Eneo la kushuka",\n      "default": "Eneo la kushuka {num} kati ya {total}."\n    },\n    {\n      "label": "Hakuna lebo ya uteuzi wa eneo la kushuka",\n      "default": "Hakuna eneo la kushuka."\n    },\n    {\n      "label": "Lebo kwa kitufe cha kidokezo cha onyesho",\n      "default": "Kidokezo cha onyesho."\n    },\n    {\n      "label": "Lebo kwa kidokezo inapatikana",\n      "default": "Kidokezo kinapatikana"\n    },\n    {\n      "label": "Lebo kwa jibu sahihi",\n      "default": "Jibu sahihi"\n    },\n    {\n      "label": "Lebo kwa jibu lisilo sahihi",\n      "default": "Jibu lisilo sahihi"\n    },\n    {\n      "label": "Kichwa cha upau wenye maoni kwa majibu sahihi/ yasiyo sahihi",\n      "default": "Maoni"\n    },\n    {\n      "label": "Uwakilishi wa maandishi wa upau wa alama kwa wale wanaotumia kisoma maandishi",\n      "default": "Umepata :num kati ya alama:total"\n    },\n    {\n      "label": "Uwakilishi wa maandishi wa kitufe cha maelezo ya alama",\n      "default": "Maandishi ya ufafanuzi wa alama"\n    },\n    {\n      "label": "Lebo ya teknolojia ya usaidizi kwa kitufe cha \\"Weka alama\\"",\n      "default": "Weka alama majibu. Majibu yatatiwa alama kuwa sahihi, siyo sahihi au haijajibiwa."\n    },\n    {\n      "label": "Lebo ya teknolojia ya usaidizi kwa kitufe cha \\"Jaribu tena\\"",\n      "default": "Jaribu tena kazi hiyo. Weka upya majibu yote na uanze kazi tena."\n    }\n  ]\n}\n'),
(18, 'th', '{\n  "semantics": [\n    {\n      "label": "Check answer button",\n      "default": "ตรวจสอบ"\n    },\n    {\n      "label": "Submit answer button",\n      "default": "ส่งคำตอบ"\n    },\n    {\n      "label": "Retry button",\n      "default": "ลองใหม่"\n    },\n    {\n      "label": "Score explanation text",\n      "default": "คำตอบที่ถูกต้องได้รับคะแนน +1 คะแนน คำตอบที่ผิดได้รับคะแนน -1 คะแนน คะแนนที่ต่ำที่สุดคือ 0"\n    },\n    {\n      "fields": [\n        {\n          "label": "Settings",\n          "fields": [\n            {\n              "label": "Background image",\n              "description": "ไม่บังคับ สามารถเลือกรูปภาพที่ใช้เป็นพื้นหลังสำหรับงานลากและวางของคุณ"\n            },\n            {\n              "label": "Task size",\n              "description": "ระบุขนาด (ในพิกเซล) ของพื้นที่เล่น"\n            }\n          ]\n        },\n        {\n          "label": "Task",\n          "description": "เริ่มโดยวางโซนการวาง<br />จากนั้นวางองค์ประกอบที่สามารถวางได้และทำเครื่องหมายโซนการวางที่เหมาะสม<br />สุดท้าย แก้ไขโซนการวางอีกครั้งและทำเครื่องหมายคำตอบที่ถูกต้อง",\n          "fields": [\n            {\n              "label": "องค์ประกอบ",\n              "entity": "element",\n              "field": {\n                "label": "องค์ประกอบ",\n                "fields": [\n                  {\n                    "description": "เลือกประเภทของเนื้อหาที่คุณต้องการเพิ่ม"\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "เลือกโซนการวาง"\n                  },\n                  {\n                    "label": "ความทึบพื้นหลัง",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "จำนวนองค์ประกอบที่ไม่จำกัด",\n                    "description": "คลอนองค์ประกอบนี้เพื่อให้สามารถลากไปวางในโซนการวางหลายๆ โซนได้"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "โซนการวาง",\n              "entity": "Drop Zone",\n              "field": {\n                "label": "โซนการวาง",\n                "fields": [\n                  {\n                    "label": "ป้ายชื่อ",\n                    "description": "The label is used by assistive technologies."\n                  },\n                  {\n                    "label": "แสดงป้ายชื่อ"\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "เลือกองค์ประกอบที่ถูกต้อง"\n                  },\n                  {\n                    "label": "ความทึบพื้นหลัง",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "เคล็ดลับและคำแนะนำ",\n                    "fields": [\n                      {\n                        "label": "ข้อความเคล็ดลับ"\n                      },\n                      {\n                        "label": "ข้อความที่แสดงเมื่อตอบถูกต้อง",\n                        "description": "ข้อความจะปรากฏด้านล่างงานเมื่อ \\"ตรวจสอบ\\" หากมีการจับคู่องค์ประกอบที่ถูกต้อง"\n                      },\n                      {\n                        "label": "ข้อความที่แสดงเมื่อตอบไม่ถูกต้อง",\n                        "description": "ข้อความจะปรากฏด้านล่างงานเมื่อ \\"ตรวจสอบ\\" หากการจับคู่ไม่ถูกต้อง"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "โซนการวางนี้สามารถมีองค์ประกอบเพียงหนึ่งตัวเท่านั้น",\n                    "description": "ตรวจสอบให้แน่ใจว่ามีคำตอบที่ถูกต้องเพียงหนึ่งคำสำหรับโซนการวางนี้"\n                  },\n                  {\n                    "label": "เปิดใช้งานการจัดตำแหน่งอัตโนมัติ",\n                    "description": "จะจัดตำแหน่งอัตโนมัติสำหรับรายการที่ลากไปวางในโซนนี้ทั้งหมด"\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "ค่าเริ่มต้น"\n            }\n          ],\n          "label": "กำหนดคำตอบกำหนดเองสำหรับช่วงคะแนนใดๆ",\n          "description": "คลิกปุ่ม \\"เพิ่มช่วง\\" เพื่อเพิ่มช่วงตามที่คุณต้องการ ตัวอย่าง: 0-20% คะแนนต่ำ, 21-91% คะแนนปานกลาง, 91-100% คะแนนดี!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "ช่วงคะแนน"\n              },\n              {},\n              {\n                "label": "คำตอบสำหรับช่วงคะแนนที่กำหนด",\n                "placeholder": "ใส่คำตอบ"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "การตั้งค่าพฤติกรรม",\n      "description": "ตัวเลือกเหล่านี้จะช่วยคุณควบคุมพฤติกรรมของงาน",\n      "fields": [\n        {\n          "label": "เปิดใช้งาน \\"ลองอีกครั้ง\\""\n        },\n        {\n          "label": "เปิดใช้งานปุ่ม \\"ตรวจสอบ\\""\n        },\n        {\n          "label": "ให้คะแนน 1 คะแนนสำหรับงานทั้งหมด",\n          "description": "ปิดใช้งานเพื่อให้คะแนนหนึ่งคะแนนสำหรับรายการที่ลากไปวางในตำแหน่งที่ถูกต้องทุกตัว"\n        },\n        {\n          "label": "ใช้การลงโทษ",\n          "description": "ใช้การลงโทษสำหรับองค์ประกอบที่ลากไปวางในตำแหน่งที่ไม่ถูกต้อง ต้องเปิดใช้เมื่อองค์ประกอบเดียวกันสามารถลากไปวางในโซนการวางหลายโซนได้หรือหากมีโซนการวางเพียงโซนเดียวหากไม่เปิดใช้งานนี้ ผู้เรียนอาจจับคู่รายการทั้งหมดกับโซนการวางทั้งหมดและได้รับคะแนนเต็มเสมอ"\n        },\n        {\n          "label": "เปิดใช้คำอธิบายคะแนน",\n          "description": "แสดงคำอธิบายคะแนนให้ผู้เรียนเห็นหลังจากคำตอบถูกต้องหรือไม่ถูกต้อง"\n        },\n        {\n          "label": "Background opacity for draggables",\n          "description": "If this field is set, it will override opacity set on all draggable elements. This should be a number between 0 and 100, where 0 means full transparency and 100 means no transparency"\n        },\n        {\n          "label": "Drop Zone Highlighting",\n          "description": "Choose when to highlight drop zones.",\n          "options": [\n            {\n              "label": "When dragging"\n            },\n            {\n              "label": "Always"\n            },\n            {\n              "label": "Never"\n            }\n          ]\n        },\n        {\n          "label": "Spacing for Auto-Align (in px)"\n        },\n        {\n          "label": "Enable FullScreen",\n          "description": "Check this option to enable the full screen button."\n        },\n        {\n          "label": "Show score points",\n          "description": "Show points earned for each answer. Not available when the ''Give one point for the whole task'' option is enabled."\n        },\n        {\n          "label": "Show Title",\n          "description": "Uncheck this option if you do not want this title to be displayed. The title will only be displayed in summaries, statistics etc."\n        }\n      ]\n    },\n    {\n      "label": "Localize",\n      "fields": [\n        {\n          "label": "Fullscreen label",\n          "default": "Fullscreen"\n        },\n        {\n          "label": "Exit fullscreen label",\n          "default": "Exit fullscreen"\n        }\n      ]\n    },\n    {\n      "label": "Grabbable prefix",\n      "default": "Grabbable {num} of {total}."\n    },\n    {\n      "label": "Grabbable suffix",\n      "default": "Placed in dropzone {num}."\n    },\n    {\n      "label": "Dropzone prefix",\n      "default": "Dropzone {num} of {total}."\n    },\n    {\n      "label": "No dropzone selection label",\n      "default": "No dropzone."\n    },\n    {\n      "label": "Label for show tip button",\n      "default": "Show tip."\n    },\n    {\n      "label": "Label for tip available",\n      "default": "Tip available"\n    },\n    {\n      "label": "Label for correct answer",\n      "default": "Correct answer"\n    },\n    {\n      "label": "Label for incorrect answer",\n      "default": "Wrong answer"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "Feedback"\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Textual representation of the score explanation button",\n      "default": "Show score explanation"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(18, 'tr', '{\n  "semantics": [\n    {\n      "label": "Cevapla düğmesini kontrol et",\n      "default": "Kontrol et"\n    },\n    {\n      "label": "Cevabı gönder düğmesi",\n      "default": "Gönder"\n    },\n    {\n      "label": "Tekrar dene düğmesi",\n      "default": "Yeniden dene"\n    },\n    {\n      "label": "Puan açıklama metni",\n      "default": "Doğru cevaplar+1 puan verir. Yanlış cevaplar -1 puan verir. Mümkün olan en düşük puan 0''dir."\n    },\n    {\n      "fields": [\n        {\n          "label": "Ayarlar",\n          "fields": [\n            {\n              "label": "Arkaplan görüntüsü",\n              "description": "İsteğe bağlı. Sürükle ve bırak göreviniz için arka plan olarak kullanmak üzere bir resim seçin."\n            },\n            {\n              "label": "Görev boyutu",\n              "description": "Oyun alanının ne kadar büyük (px cinsinden) olması gerektiğini belirtin."\n            }\n          ]\n        },\n        {\n          "label": "Görev",\n          "description": "Bırakma bölgelerinizi yerleştirerek başlayın. <br /> İleri, atlayabilecek öğelerinizi yerleştirin ve uygun bırakma bölgelerini kontrol edin. <br /> Son, bırakma bölgenizi tekrar düzenleyin ve doğru yanıtları kontrol edin.",\n          "fields": [\n            {\n              "label": "Ögeler",\n              "entity": "öğe",\n              "field": {\n                "label": "Öge",\n                "fields": [\n                  {\n                    "description": "Eklemek istediğiniz içerik türünü seçiniz."\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Bırakma alanı seç"\n                  },\n                  {\n                    "label": "Arkaplan Şeffaflığı",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Sonsuz sayıda öğe örneği",\n                    "description": "Birden çok bırakma bölgesine sürüklenebilmesi için bu ögeyi klonlar."\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Bırakma Alanları",\n              "entity": "Bırakma Alanı",\n              "field": {\n                "label": "Bırakma Alanı",\n                "fields": [\n                  {\n                    "label": "Etiket",\n                    "description": "The label is used by assistive technologies."\n                  },\n                  {\n                    "label": "Etiketi göster"\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Doğru öğeleri seçin"\n                  },\n                  {\n                    "label": "Arkaplan Şeffaflığı",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "İpuçları ve geri bildirim",\n                    "fields": [\n                      {\n                        "label": "İpucu metni"\n                      },\n                      {\n                        "label": "Doğru cevapta gösterilecek ileti",\n                        "description": "Doğru bırakılabilir öğe eşleşirse ''kontrol et'' seçeneğindeki görevin altında mesaj görünür."\n                      },\n                      {\n                        "label": "Yanlış cevapta gösterilecek ileti",\n                        "description": "Eşleşme yanlışsa, görevin altında \\"kontrol et\\" mesajı görünecektir."\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Bu bırakma bölgesi yalnızca bir öğe içerebilir",\n                    "description": "Make sure there is only one correct answer for this dropzone"\n                  },\n                  {\n                    "label": "Enable Auto-Align",\n                    "description": "Will auto-align all draggables dropped in this zone."\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Varsayılan"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "İstediğiniz kadar aralık eklemek için \\"Aralık ekle\\" düğmesini tıklayın. Örnek: %0-20 Kötü puan, %21-91 Ortalama Puan, %91-100 Büyük Puan!",\n          "entity": "aralık",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Davranış ayarları",\n      "description": "Bu seçenekler aktivitenin çalışma şeklini denetlemenize izin verir.",\n      "fields": [\n        {\n          "label": "Enable \\"Retry\\""\n        },\n        {\n          "label": "Enable \\"Check\\" button"\n        },\n        {\n          "label": "Bütün aktivite için bir puan verin",\n          "description": "Disable to give one point for each draggable that is placed correctly."\n        },\n        {\n          "label": "Apply penalties",\n          "description": "Apply penalties for elements dropped in the wrong drop zones. This must be enabled when the same element(s) are able to be dropped into multiple drop zones, or if there is only one drop-zone. If this is not enabled, learners may match all items to all drop-zones and always receive a full score."\n        },\n        {\n          "label": "Enable score explanation",\n          "description": "Display a score explanation to user when checking their answers (if the ''Apply penalties'' option has been selected)."\n        },\n        {\n          "label": "Background opacity for draggables",\n          "description": "If this field is set, it will override opacity set on all draggable elements. This should be a number between 0 and 100, where 0 means full transparency and 100 means no transparency"\n        },\n        {\n          "label": "Drop Zone Highlighting",\n          "description": "Choose when to highlight drop zones.",\n          "options": [\n            {\n              "label": "When dragging"\n            },\n            {\n              "label": "Daima"\n            },\n            {\n              "label": "Asla"\n            }\n          ]\n        },\n        {\n          "label": "Spacing for Auto-Align (in px)"\n        },\n        {\n          "label": "Tam ekranı etkinleştir",\n          "description": "Tam ekran düğmesini etkinleştirmek için bu seçeneği işaretleyiniz."\n        },\n        {\n          "label": "Show score points",\n          "description": "Show points earned for each answer. Not available when the ''Give one point for the whole task'' option is enabled."\n        },\n        {\n          "label": "Başlığı göster",\n          "description": "Başlığın gösterilmesini istemiyorsanız bu seçenekteki işareti kaldırınız. Başlık sadece özetlerde,istatistiklerde vb. yerlerde gösterilecektir."\n        }\n      ]\n    },\n    {\n      "label": "Localize",\n      "fields": [\n        {\n          "label": "Tam ekran etiketi",\n          "default": "Tam ekran"\n        },\n        {\n          "label": "Tam ekrandan çık etiketi",\n          "default": "Tam ekrandan çık"\n        }\n      ]\n    },\n    {\n      "label": "Grabbable prefix",\n      "default": "Grabbable {num} of {total}."\n    },\n    {\n      "label": "Grabbable suffix",\n      "default": "Placed in dropzone {num}."\n    },\n    {\n      "label": "Dropzone prefix",\n      "default": "Dropzone {num} of {total}."\n    },\n    {\n      "label": "No dropzone selection label",\n      "default": "No dropzone."\n    },\n    {\n      "label": "Label for show tip button",\n      "default": "Show tip."\n    },\n    {\n      "label": "Label for tip available",\n      "default": "Mevcut ipucu"\n    },\n    {\n      "label": "Label for correct answer",\n      "default": "Doğru cevap"\n    },\n    {\n      "label": "Yanlış cevap için etiket",\n      "default": "Yanlış cevap"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "Feedback"\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Textual representation of the score explanation button",\n      "default": "Show score explanation"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Görevi yeniden deneyin. Tüm cevapları sıfırlayın ve görevi yeniden başlatın."\n    }\n  ]\n}\n'),
(18, 'uk', '{\n  "semantics": [\n    {\n      "label": "Кнопка перевірки відповіді",\n      "default": "Перевірити"\n    },\n    {\n      "label": "Кнопка для відправки відповіді",\n      "default": "Submit"\n    },\n    {\n      "label": "Кнопка повтора",\n      "default": "Повторити"\n    },\n    {\n      "label": "Текст пояснення оцінки",\n      "default": "Правильні відповіді додають 1 бал. Неправильні відповіді віднімають 1 бал. Найменьша можлива оцінка - 0."\n    },\n    {\n      "fields": [\n        {\n          "label": "Настройки",\n          "fields": [\n            {\n              "label": "Зображення тла",\n              "description": "По бажанню. Оберіть зображення для використання в якості тла для завдання з перетягуванням."\n            },\n            {\n              "label": "Размір завдання",\n              "description": "Вкажіть, наскільки великою (в пікселях) має бути ігрова зона."\n            }\n          ]\n        },\n        {\n          "label": "Завдання",\n          "description": "Почніть з розміщення зон скидання.<br />Далі, розмістіть елементи, що скидають, і перевірте відповідні зони скидання.<br />Нарешті, відредагуйте зону скидання ще раз і перевірте правильні відповіді.",\n          "fields": [\n            {\n              "label": "Елементи",\n              "entity": "елемент",\n              "field": {\n                "label": "Елемент",\n                "fields": [\n                  {\n                    "description": "Оберіть тип контенту, який ви хочете додати."\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Оберіть область розміщення"\n                  },\n                  {\n                    "label": "Непрозорість тла",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Нескінченна кількість екземплярів елемента",\n                    "description": "Клонує цей елемент, щоб його можна було перетягнути в декілька областей розміщення."\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Області розміщення",\n              "entity": "Область розміщення",\n              "field": {\n                "label": "Область розміщення",\n                "fields": [\n                  {\n                    "label": "Надпис",\n                    "description": "The label is used by assistive technologies."\n                  },\n                  {\n                    "label": "Показати надпис"\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Оберіть правильні елементи"\n                  },\n                  {\n                    "label": "Непрозорість тла",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Підказки і зворотній зв''язок",\n                    "fields": [\n                      {\n                        "label": "Текст підказки"\n                      },\n                      {\n                        "label": "Повідомлення, яке буде відображатися при правильній відповідності",\n                        "description": "Повідомлення з''явиться під завданням на \\"перевірити\\", якщо буде скинуто правильний елемент."\n                      },\n                      {\n                        "label": "Повідомлення, яке буде відображатися при неправильній відповідності",\n                        "description": "Повідомлення з''явиться під завданням на \\"перевірити\\", якщо буде скинуто неправильний елемент."\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Ця область розміщення може містити тільки один елемент",\n                    "description": "Впевніться, що є тільки одна правильна відповідь для цієї області розміщення"\n                  },\n                  {\n                    "label": "Включити авто-вирівнювання",\n                    "description": "Автоматично вирівнює всі перетягувані об''єкти в цій зоні."\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Загальний зворотній зв''язок",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "По умовчанню"\n            }\n          ],\n          "label": "Визначення довільного зворотнього зв''язку для кожного діапазону оцінок",\n          "description": "Натисніть на кнопку \\"Додати діапазон\\" для додавання необхідної кількості діапазонів. Наприклад: 0-20% Погана оцінака, 21-91% Середня оцінка, 91-100% Відмінна оцінка!",\n          "entity": "діпазон",\n          "field": {\n            "fields": [\n              {\n                "label": "Діапазон оцінок"\n              },\n              {},\n              {\n                "label": "Зворотній зв''язок для певного діапазону оцінок",\n                "placeholder": "Заповніть зворотній зв''язок"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Настройки поведінки",\n      "description": "Ці параметри дозволять вам контролювати поведінку завдання.",\n      "fields": [\n        {\n          "label": "Включити кнопку \\"Повторити\\""\n        },\n        {\n          "label": "Включити кнопку \\"Перевірити\\""\n        },\n        {\n          "label": "Додавати один бал за все завдання",\n          "description": "Вимкнути, щоб вказати одну точку за кожен правильно розміщений перетягуваний елемент."\n        },\n        {\n          "label": "Застососвувати штраф",\n          "description": "Застосування штрафів за елементы, скинуті в неправильних областях розміщення. Це повинно бути включено, коли той самий елемент (елементи) может бути скинутим в декількох областях розміщення або якщо є тільки одна область розміщення. Якщо це не включено, учні можуть співставити всі елементи зі всіма областями розміщення і завжди отримувати повну оцінку."\n        },\n        {\n          "label": "Включити пояснення оцінки",\n          "description": "Покажіть користувачеві пояснення щодо оцінки, перевіряючи його відповіді (якщо вибрано варіант (Застосувати штрафні санкції))."\n        },\n        {\n          "label": "Непрозорість тла при перетягуванні",\n          "description": "Якщо це відмічено зміниться прозорість, встановлена для всіх перетягуваних елементів. Це має бути число від 0 до 100, де 0 означає повну прозорість, а 100 - відсутність прозорості"\n        },\n        {\n          "label": "Підсвітка області розміщення",\n          "description": "Виберіть, коли виділити зони скидання.",\n          "options": [\n            {\n              "label": "При перетягуванні"\n            },\n            {\n              "label": "Завжди"\n            },\n            {\n              "label": "Ніколи"\n            }\n          ]\n        },\n        {\n          "label": "Відступи при авто-вирівнюванні (в пікселях)"\n        },\n        {\n          "label": "Включити повноекранний режим",\n          "description": "Відьмітьте цей параметр, для включення кнопки повноекранного режиму."\n        },\n        {\n          "label": "Показувати набрані бали",\n          "description": "Показати зароблені бали за кожну відповідь. Недоступно, коли ввімкнено опцію (Надати один бал за все завдання)."\n        },\n        {\n          "label": "Показати заголовок",\n          "description": "Зніміть цей прапорець, якщо ви не хочете, щоб ця назва відображалася. Заголовок відображатиметься лише у резюме, статистиці тощо."\n        }\n      ]\n    },\n    {\n      "label": "Локалізація",\n      "fields": [\n        {\n          "label": "Надпис повноекранного режиму",\n          "default": "Повноекранний режим"\n        },\n        {\n          "label": "Надпис виходу із повноекранного режиму",\n          "default": "Вийти із повноекранного режиму"\n        }\n      ]\n    },\n    {\n      "label": "Префікс для захоплених об''єктів",\n      "default": "Захоплено {num} із {total}."\n    },\n    {\n      "label": "Суфікс для захоплених об''єктів",\n      "default": "Розміщено в область розміщення {num}."\n    },\n    {\n      "label": "Префікс для області розміщення",\n      "default": "Розміщено {num} із {total}."\n    },\n    {\n      "label": "Надпис, якщо область розміщення не вибрана",\n      "default": "Нема області розміщення."\n    },\n    {\n      "label": "Надпис для кнопки показу підказки",\n      "default": "Показати підказку."\n    },\n    {\n      "label": "Надпис для доступної підказки",\n      "default": "Підказка доступна"\n    },\n    {\n      "label": "Надпис для правильної відповіді",\n      "default": "Правильна відповідь"\n    },\n    {\n      "label": "Надпис для неправильної відповіді",\n      "default": "Неправильна відповідь"\n    },\n    {\n      "label": "Заголовок панелі зворотнього зв''язку для правильних/неправильних відповідей",\n      "default": "Зворотній зв''язок"\n    },\n    {\n      "label": "Текстове відображення шкали балів для тих, хто використовує озвучку тексту",\n      "default": "Ви набрали :num із :total балів"\n    },\n    {\n      "label": "Текстове відображення на кнопці пояснення оцінки",\n      "default": "Показати пояснення оцінки"\n    },\n    {\n      "label": "Позначка допоміжних технологій для кнопки «Перевірити».",\n      "default": "Перевірити відповіді. Відповіді будуть позначені як правильні, неправильні або без відповіді."\n    },\n    {\n      "label": "Позначка допоміжних технологій для кнопки «Повторити».",\n      "default": "Повторіть завдання. Скиньте всі відповіді та почніть завдання знову."\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(18, 'vi', '{\n  "semantics": [\n    {\n      "label": "Check answer button",\n      "default": "Check"\n    },\n    {\n      "label": "Submit answer button",\n      "default": "Submit"\n    },\n    {\n      "label": "Retry button",\n      "default": "Retry"\n    },\n    {\n      "label": "Score explanation text",\n      "default": "Correct answers give +1 point. Incorrect answers give -1 point. The lowest possible score is 0."\n    },\n    {\n      "fields": [\n        {\n          "label": "Settings",\n          "fields": [\n            {\n              "label": "Background image",\n              "description": "Optional. Select an image to use as background for your drag and drop task."\n            },\n            {\n              "label": "Task size",\n              "description": "Specify how large (in px) the play area should be."\n            }\n          ]\n        },\n        {\n          "label": "Task",\n          "description": "Start by placing your drop zones.<br />Next, place your droppable elements and check off the appropriate drop zones.<br />Last, edit your drop zone again and check off the correct answers.",\n          "fields": [\n            {\n              "label": "Elements",\n              "entity": "element",\n              "field": {\n                "label": "Element",\n                "fields": [\n                  {\n                    "description": "Choose the type of content you would like to add."\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Select drop zones"\n                  },\n                  {\n                    "label": "Background Opacity",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Infinite number of element instances",\n                    "description": "Clones this element so that it can be dragged to multiple drop zones."\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Drop Zones",\n              "entity": "Drop Zone",\n              "field": {\n                "label": "Drop Zone",\n                "fields": [\n                  {\n                    "label": "Label",\n                    "description": "The label is used by assistive technologies."\n                  },\n                  {\n                    "label": "Show label"\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Select correct elements"\n                  },\n                  {\n                    "label": "Background Opacity",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "Tips and feedback",\n                    "fields": [\n                      {\n                        "label": "Tip text"\n                      },\n                      {\n                        "label": "Message displayed on correct match",\n                        "description": "Message will appear below the task on \\"check\\" if correct droppable is matched."\n                      },\n                      {\n                        "label": "Message displayed on incorrect match",\n                        "description": "Message will appear below the task on \\"check\\" if the match is incorrect."\n                      }\n                    ]\n                  },\n                  {\n                    "label": "This drop zone can only contain one element",\n                    "description": "Make sure there is only one correct answer for this dropzone"\n                  },\n                  {\n                    "label": "Enable Auto-Align",\n                    "description": "Will auto-align all draggables dropped in this zone."\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Default"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Behavioural settings",\n      "description": "These options will let you control how the task behaves.",\n      "fields": [\n        {\n          "label": "Enable \\"Retry\\""\n        },\n        {\n          "label": "Enable \\"Check\\" button"\n        },\n        {\n          "label": "Give one point for the whole task",\n          "description": "Disable to give one point for each draggable that is placed correctly."\n        },\n        {\n          "label": "Apply penalties",\n          "description": "Apply penalties for elements dropped in the wrong drop zones. This must be enabled when the same element(s) are able to be dropped into multiple drop zones, or if there is only one drop-zone. If this is not enabled, learners may match all items to all drop-zones and always receive a full score."\n        },\n        {\n          "label": "Enable score explanation",\n          "description": "Display a score explanation to user when checking their answers (if the ''Apply penalties'' option has been selected)."\n        },\n        {\n          "label": "Background opacity for draggables",\n          "description": "If this field is set, it will override opacity set on all draggable elements. This should be a number between 0 and 100, where 0 means full transparency and 100 means no transparency"\n        },\n        {\n          "label": "Drop Zone Highlighting",\n          "description": "Choose when to highlight drop zones.",\n          "options": [\n            {\n              "label": "When dragging"\n            },\n            {\n              "label": "Always"\n            },\n            {\n              "label": "Never"\n            }\n          ]\n        },\n        {\n          "label": "Spacing for Auto-Align (in px)"\n        },\n        {\n          "label": "Enable FullScreen",\n          "description": "Check this option to enable the full screen button."\n        },\n        {\n          "label": "Show score points",\n          "description": "Show points earned for each answer. Not available when the ''Give one point for the whole task'' option is enabled."\n        },\n        {\n          "label": "Show Title",\n          "description": "Uncheck this option if you do not want this title to be displayed. The title will only be displayed in summaries, statistics etc."\n        }\n      ]\n    },\n    {\n      "label": "Localize",\n      "fields": [\n        {\n          "label": "Fullscreen label",\n          "default": "Fullscreen"\n        },\n        {\n          "label": "Exit fullscreen label",\n          "default": "Exit fullscreen"\n        }\n      ]\n    },\n    {\n      "label": "Grabbable prefix",\n      "default": "Grabbable {num} of {total}."\n    },\n    {\n      "label": "Grabbable suffix",\n      "default": "Placed in dropzone {num}."\n    },\n    {\n      "label": "Dropzone prefix",\n      "default": "Dropzone {num} of {total}."\n    },\n    {\n      "label": "No dropzone selection label",\n      "default": "No dropzone."\n    },\n    {\n      "label": "Label for show tip button",\n      "default": "Show tip."\n    },\n    {\n      "label": "Label for tip available",\n      "default": "Tip available"\n    },\n    {\n      "label": "Label for correct answer",\n      "default": "Correct answer"\n    },\n    {\n      "label": "Label for incorrect answer",\n      "default": "Wrong answer"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "Feedback"\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Textual representation of the score explanation button",\n      "default": "Show score explanation"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(18, 'zh-hans', '{\n  "semantics": [\n    {\n      "label": "检查答案功能钮",\n      "default": "检查"\n    },\n    {\n      "label": "Submit answer button",\n      "default": "Submit"\n    },\n    {\n      "label": "重试功能钮",\n      "default": "重试"\n    },\n    {\n      "label": "得分说明",\n      "default": "正确答案将给1分，答错扣1分。最低分数为0."\n    },\n    {\n      "fields": [\n        {\n          "label": "设定",\n          "fields": [\n            {\n              "label": "背景图示",\n              "description": "选填，请挑选一张照片作为拖曳式图像任务的背景图."\n            },\n            {\n              "label": "任务大小",\n              "description": "指定任务区域大小(单位为px)."\n            }\n          ]\n        },\n        {\n          "label": "任务",\n          "description": "请先设定任务区域.<br />接着，设定拖曳元素及相容之任务区域.<br />最后，编辑任务区域之正确答案.",\n          "fields": [\n            {\n              "label": "元素",\n              "entity": "元素",\n              "field": {\n                "label": "元素",\n                "fields": [\n                  {\n                    "description": "选择您欲新增的内容类型."\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "选择任务区域"\n                  },\n                  {\n                    "label": "背景不透明度",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "元素无限化",\n                    "description": "勾选后可使元素能拖曳至多个任务区域."\n                  }\n                ]\n              }\n            },\n            {\n              "label": "任务区域",\n              "entity": "任务区域",\n              "field": {\n                "label": "任务区域",\n                "fields": [\n                  {\n                    "label": "标记名称",\n                    "description": "The label is used by assistive technologies."\n                  },\n                  {\n                    "label": "显示标记名称"\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "选择正确的元素"\n                  },\n                  {\n                    "label": "背景不透明度",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "提示及回馈",\n                    "fields": [\n                      {\n                        "label": "提示文字"\n                      },\n                      {\n                        "label": "正确选出答案时所显示的文字讯息",\n                        "description": "当正确选出答案时，讯息内容将显示在＂检查＂功能钮下方."\n                      },\n                      {\n                        "label": "未正确选出答案时所显示的文字讯息",\n                        "description": "当未正确选出答案时，讯息内容将显示在＂检查＂功能钮下方."\n                      }\n                    ]\n                  },\n                  {\n                    "label": "任务区域仅能存放单一元素",\n                    "description": "确认任务区域只能有一个正确答案"\n                  },\n                  {\n                    "label": "启用自动对齐功能",\n                    "description": "将自动对齐任务区域之任一拖曳元素."\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "整体回馈",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "预设"\n            }\n          ],\n          "label": "定义任意分数范围的回馈",\n          "description": "点击＂新增范围＂功能钮以添加您所需要的范围. 例如: 0-20% 低分, 21-91% 平均得分, 91-100% 高分!",\n          "entity": "范围",\n          "field": {\n            "fields": [\n              {\n                "label": "得分范围"\n              },\n              {},\n              {\n                "label": "回馈定义的得分范围",\n                "placeholder": "填写回馈"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "行为设定",\n      "description": "这些选项将可让您控制任务的行为.",\n      "fields": [\n        {\n          "label": "启用＂重试＂功能"\n        },\n        {\n          "label": "启用 ＂检查＂功能钮"\n        },\n        {\n          "label": "给予整个任务1分",\n          "description": "勾选后将取消任一作答皆给1分机制."\n        },\n        {\n          "label": "处罚",\n          "description": "答错时给予处罚。当相同元素能被对应到多任务区域时，或是只有单一对应任务区域时，必须启用此功能。如果没有启用此功能时，使用者能将所有元素对应至所有任务区域，且无论作答状况皆能获得完整的分数."\n        },\n        {\n          "label": "启用分数说明",\n          "description": "在检查答案时，能向使用者显示分数说明(当有启用”处罚”功能时)."\n        },\n        {\n          "label": "背景不透明化设定",\n          "description": "设定不透明度将涵盖所有可拖曳元素。设定数值为0至100之间的数字，其中0表示完全透明，100表示完全不透明。"\n        },\n        {\n          "label": "任务区域显著标记",\n          "description": "选择何时强调任务区域.",\n          "options": [\n            {\n              "label": "拖曳时"\n            },\n            {\n              "label": "永远"\n            },\n            {\n              "label": "永不"\n            }\n          ]\n        },\n        {\n          "label": "自动对齐间距(单位为px)"\n        },\n        {\n          "label": "启用全屏",\n          "description": "勾选启用全屏显示切换功能钮."\n        },\n        {\n          "label": "显示得分",\n          "description": "显示每个答案所获得的积分。不适用于启用＂给予整个任务1分＂."\n        },\n        {\n          "label": "显示标题",\n          "description": "如果不希望显示标题时，请取消勾选此选项。标题将只显示在总结、统计等."\n        }\n      ]\n    },\n    {\n      "label": "在地化",\n      "fields": [\n        {\n          "label": "全屏标题",\n          "default": "全屏"\n        },\n        {\n          "label": "关闭全屏标题",\n          "default": "退出全屏"\n        }\n      ]\n    },\n    {\n      "label": "可抓取的 前述",\n      "default": "可抓取的 {total} 的 {num}."\n    },\n    {\n      "label": "可抓取的 末尾附加",\n      "default": "放置于任务区域 {num}."\n    },\n    {\n      "label": "任务区域前述",\n      "default": "任务区域 {total} 的 {num}."\n    },\n    {\n      "label": "未选择任务区域时显示名称",\n      "default": "未选择任务区域."\n    },\n    {\n      "label": "显示提示功能钮名称",\n      "default": "显示提示."\n    },\n    {\n      "label": "显示可用提示名称",\n      "default": "可用提示"\n    },\n    {\n      "label": "显示正确答案名称",\n      "default": "正确答案"\n    },\n    {\n      "label": "显示错误答案名称",\n      "default": "错误答案"\n    },\n    {\n      "label": "正确或错误回馈讯息之标题名称",\n      "default": "回馈"\n    },\n    {\n      "label": "阅读器导读文字-评分栏",\n      "default": "您得到了:num分，总分:total"\n    },\n    {\n      "label": "评分说明功能钮名称",\n      "default": "显示评分说明"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(18, 'zh-tw', '{\n  "semantics": [\n    {\n      "label": "檢查答案功能鈕",\n      "default": "檢查"\n    },\n    {\n      "label": "Submit answer button",\n      "default": "Submit"\n    },\n    {\n      "label": "重試功能鈕",\n      "default": "重試"\n    },\n    {\n      "label": "得分說明",\n      "default": "正確答案將給1分，答錯扣1分。最低分數為0."\n    },\n    {\n      "fields": [\n        {\n          "label": "設定",\n          "fields": [\n            {\n              "label": "背景圖示",\n              "description": "選填，請挑選一張照片做為拖曳式圖像任務的背景圖."\n            },\n            {\n              "label": "任務大小",\n              "description": "指定任務區域大小(單位為px)."\n            }\n          ]\n        },\n        {\n          "label": "任務",\n          "description": "請先設定任務區域.<br />接著，設定拖曳元素及相容之任務區域.<br />最後，編輯任務區域之正確答案.",\n          "fields": [\n            {\n              "label": "元素",\n              "entity": "元素",\n              "field": {\n                "label": "元素",\n                "fields": [\n                  {\n                    "description": "選擇您欲新增的內容類型."\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "選擇任務區域"\n                  },\n                  {\n                    "label": "背景不透明度",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "元素無限化",\n                    "description": "勾選後可使元素能拖曳至多個任務區域."\n                  }\n                ]\n              }\n            },\n            {\n              "label": "任務區域",\n              "entity": "任務區域",\n              "field": {\n                "label": "任務區域",\n                "fields": [\n                  {\n                    "label": "標記名稱",\n                    "description": "The label is used by assistive technologies."\n                  },\n                  {\n                    "label": "顯示標記名稱"\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "選擇正確的元素"\n                  },\n                  {\n                    "label": "背景不透明度",\n                    "description": "Reducing the opacity may result in an insufficient contrast and make the content not accessible."\n                  },\n                  {\n                    "label": "提示及回饋",\n                    "fields": [\n                      {\n                        "label": "提示文字"\n                      },\n                      {\n                        "label": "正確選出答案時所顯示的文字訊息",\n                        "description": "當正確選出答案時，訊息內容將顯示在＂檢查＂功能鈕下方."\n                      },\n                      {\n                        "label": "未正確選出答案時所顯示的文字訊息",\n                        "description": "當未正確選出答案時，訊息內容將顯示在＂檢查＂功能鈕下方."\n                      }\n                    ]\n                  },\n                  {\n                    "label": "任務區域僅能存放單一元素",\n                    "description": "確認任務區域只能有一個正確答案"\n                  },\n                  {\n                    "label": "啟用自動對齊功能",\n                    "description": "將自動對齊任務區域之任一拖曳元素."\n                  }\n                ]\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "整體回饋",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "預設"\n            }\n          ],\n          "label": "定義任意分數範圍的回饋",\n          "description": "點擊＂新增範圍＂功能鈕以添加您所需要的範圍. 例如: 0-20% 低分, 21-91% 平均得分, 91-100% 高分!",\n          "entity": "範圍",\n          "field": {\n            "fields": [\n              {\n                "label": "得分範圍"\n              },\n              {},\n              {\n                "label": "回饋定義的得分範圍",\n                "placeholder": "填寫回饋"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "行為設定",\n      "description": "這些選項將可讓您控制任務的行為.",\n      "fields": [\n        {\n          "label": "啟用＂重試＂功能"\n        },\n        {\n          "label": "啟用 ＂檢查＂功能鈕"\n        },\n        {\n          "label": "給予整個任務1分",\n          "description": "勾選後將取消任一作答皆給1分機制."\n        },\n        {\n          "label": "處罰",\n          "description": "答錯時給予處罰。當相同元素能被對應到多任務區域時，或是只有單一對應任務區域時，必須啟用此功能。如果沒有啟用此功能時，使用者能將所有元素對應至所有任務區域，且無論作答狀況皆能獲得完整的分數."\n        },\n        {\n          "label": "啟用分數說明",\n          "description": "在檢查答案時，能向使用者顯示分數說明(當有啟用”處罰”功能時)."\n        },\n        {\n          "label": "背景不透明化設定",\n          "description": "設定不透明度將涵蓋所有可拖曳元素。設定數值為0至100之間的數字，其中0表示完全透明，100表示完全不透明。"\n        },\n        {\n          "label": "任務區域顯著標記",\n          "description": "選擇何時強調任務區域.",\n          "options": [\n            {\n              "label": "拖曳時"\n            },\n            {\n              "label": "永遠"\n            },\n            {\n              "label": "永不"\n            }\n          ]\n        },\n        {\n          "label": "自動對齊間距(單位為px)"\n        },\n        {\n          "label": "啟用全螢幕",\n          "description": "勾選啟用全螢幕顯示切換功能鈕."\n        },\n        {\n          "label": "顯示得分",\n          "description": "顯示每個答案所獲得的積分。不適用於啟用＂給予整個任務1分＂."\n        },\n        {\n          "label": "顯示標題",\n          "description": "如果不希望顯示標題時，請取消勾選此選項。標題將只顯示在總結、統計等."\n        }\n      ]\n    },\n    {\n      "label": "在地化",\n      "fields": [\n        {\n          "label": "全螢幕標題",\n          "default": "全螢幕"\n        },\n        {\n          "label": "關閉全螢幕標題",\n          "default": "退出全螢幕"\n        }\n      ]\n    },\n    {\n      "label": "Grabbable 前述",\n      "default": "Grabbable {total} 的 {num}."\n    },\n    {\n      "label": "Grabbable 末尾附加",\n      "default": "放置於任務區域 {num}."\n    },\n    {\n      "label": "任務區域前述",\n      "default": "任務區域 {total} 的 {num}."\n    },\n    {\n      "label": "未選擇任務區域時顯示名稱",\n      "default": "未選擇任務區域."\n    },\n    {\n      "label": "顯示提示功能鈕名稱",\n      "default": "顯示提示."\n    },\n    {\n      "label": "顯示可用提示名稱",\n      "default": "可用提示"\n    },\n    {\n      "label": "顯示正確答案名稱",\n      "default": "正確答案"\n    },\n    {\n      "label": "顯示錯誤答案名稱",\n      "default": "不正確答案"\n    },\n    {\n      "label": "正確或錯誤回饋訊息之標題名稱",\n      "default": "回饋"\n    },\n    {\n      "label": "閱讀器導讀文字-評分欄",\n      "default": "您得到了:num分，總分:total"\n    },\n    {\n      "label": "評分說明功能鈕名稱",\n      "default": "顯示評分說明"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'af', '{\n  "semantics": [\n    {\n      "label": "Media",\n      "fields": [\n        {\n          "label": "Type",\n          "description": "Optional media to display above the question."\n        },\n        {\n          "label": "Disable image zooming"\n        }\n      ]\n    },\n    {\n      "label": "Taak beskrywing",\n      "description": "Beskryf hoe die gebruiker die taak moet oplos.",\n      "default": "Trek die woorde in die regte boksie in"\n    },\n    {\n      "label": "Teks",\n      "placeholder": "*Oslo* is die hoofstad van Noorweë, *Stockholm* is die hoofstad van Swede en *Kopenhagen* is die hoofstad van Denemarke. Alle stede is geleë in die *Skandinawiese: Noordelike deel van Europa* skiereiland.",\n      "important": {\n        "description": "<ul><li>Valbare woorde word bygevoeg met ''n sterretjie (*) voor en agter die korrekte woord/frase.</li><li>Jy kan ''n tekswenk byvoeg deur middel van ''n dubbelpunt (:) voor die wenk.</li><li>Vir elke leë area is daar net een regte woord.</li><li>Jy kan terugvoer byvoeg wat vertoon moet word wanneer ''n taak voltooi is. Gebruik ''\\\\+'' vir reg en ''\\\\-'' verkeerd vir verkeerde terugvoer.</li></ul>",\n        "example": "H5P inhoud kan geredigeer word deur middel van ''n *blaaier:Watter tipe program is Chrome?*. <br /> H5P inhoud is *interaktief\\\\+Reg! \\\\-Verkeerd, probeer weer!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Algemene terugvoer",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Verstek"\n            }\n          ],\n          "label": "Bepaal verstekterugvoer vir enige reeks tellings",\n          "description": "Kliek op die \\"Voeg reeks by\\" knoppie om so veel as moontlik reekse by te voeg. Byvoorbeeld: 0-20% Swak Punt, 21-91% Gemiddelde Punt, 91-100% Uitstekende Punt!",\n          "entity": "reeks",\n          "field": {\n            "fields": [\n              {\n                "label": "Telling reeks"\n              },\n              {},\n              {\n                "label": "Terugvoer vir gedefinieerde telling reeks",\n                "placeholder": "Vul die terugvoer in"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Teks vir \\"Toets\\" knoppie",\n      "default": "Toets"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Teks vir \\"Probeer weer\\" knoppie",\n      "default": "Probeer weer"\n    },\n    {\n      "label": "Teks vir \\"Wys antwoord\\" knoppie",\n      "default": "Wys antwoord"\n    },\n    {\n      "label": "Genommerde valsone etiket",\n      "default": "Valsone @index.",\n      "description": "Etiket gebruik vir toeganklikheid, waar die spreekleser die indeks van ''n valsone sal voorlees. Veranderlike beskikbaar: @index"\n    },\n    {\n      "label": "Leë valsone etiket",\n      "default": "Valsone @index is leeg.",\n      "description": "Etiket gebruik vir toeganklikheid, waar die spreekleser sal lees dat die valsone leeg is"\n    },\n    {\n      "label": "Bevat valsone etiket",\n      "default": "Valsone @index bevat sleepbare @draggable.",\n      "description": "Etiket gebruik vir toeganklikheid, waar die spreekleser sal lees dat die valsone ''n sleepbare bevat"\n    },\n    {\n      "label": "Sleepbare element etiket",\n      "default": "@index van @count sleepbares.",\n      "description": "Etiket gebruik vir toeganklikheid, waar die spreekleser lees dat dit ''n sleepbare element is. Veranderlike beskikbaar: @index, @count"\n    },\n    {\n      "label": "Etiket vir die wys wenk knopppie",\n      "default": "Wys wenk",\n      "description": "Etiket wat gebruik word vir toeganklikheid, waar die spreekleser dit lees voordat die wenk uitgelees word"\n    },\n    {\n      "label": "Spreekleserteks vir regte antwoord",\n      "default": "Reg!"\n    },\n    {\n      "label": "Spreekleserteks vir verkeerde antwoord",\n      "default": "Verkeerd!"\n    },\n    {\n      "label": "Bevestigings dialoog titel dat gebruiker ''n valbare wil herstel",\n      "default": "Stel valbare terug"\n    },\n    {\n      "label": "Bevestigingsdialoog beskrywing dat ''n gebruiker ''n valbare wil herstel",\n      "default": "Is jy seker jy wil hierdie valsone herstel?"\n    },\n    {\n      "label": "Etiket vir toeganklikheid, waar die spreekleser aandui dat sleping begin het",\n      "default": "Valbare is gegryp."\n    },\n    {\n      "label": "Etiket vir toeganklikheid, waar die spreekleser aandui dat sleep gestaak word",\n      "default": "Sleep is gestaak."\n    },\n    {\n      "label": "Etiket vir toeganklikheid, waar die spreekleser aandui dat ''n teks die regte antwoord bevat",\n      "default": "Regte antwoord:"\n    },\n    {\n      "label": "Opskrif vir paneel met terugvoer vir regte/verkeerde antwoorde",\n      "default": "Terugvoer"\n    },\n    {\n      "label": "Gedragsinstellings.",\n      "description": "Hierdie keuses laat jou beheer hoe die onderskeie take uitgevoer moet word.",\n      "fields": [\n        {\n          "label": "Aktiveer \\"Probeer weer\\""\n        },\n        {\n          "label": "Aktiveer \\"Wys antwoord\\" knoppie"\n        },\n        {\n          "label": "Aktiveer \\"Toets\\" knoppie"\n        },\n        {\n          "label": "Onmiddelike terugvoer"\n        }\n      ]\n    },\n    {\n      "label": "Tekstuele tentoonstelling van die telkaart vir diegene wat ''n spreekleser gebruik",\n      "default": "Jy het :num uit :total punte gekry"\n    },\n    {\n      "label": "Hulptegnologieetiket vir \\"Toets\\" knoppie",\n      "default": "Toets die antwoorde. Die antwoorde sal as reg gemerk, verkeerd of onbeantwoord gemerk word."\n    },\n    {\n      "label": "Hulptegnologie beskrywing vir \\"Wys Oplossing\\" knoppie",\n      "default": "Wys die oplossing. Die taak sal gemerk word met die regte antwoord."\n    },\n    {\n      "label": "Hulptegnologieetiket vir \\"Probeer weer\\" knoppie",\n      "default": "Probeer die taak weer. Herstel alle antwoorde en begin die taak van nuuts af."\n    }\n  ]\n}\n'),
(19, 'ar', '{\n  "semantics": [\n    {\n      "label": "وسائط",\n      "fields": [\n        {\n          "label": "النوع",\n          "description": "وسائط إضافية اختيارية تُعرض أعلى السؤال."\n        },\n        {\n          "label": "إيقاف ميزة تكبير الصور"\n        }\n      ]\n    },\n    {\n      "label": "وصف النشاط",\n      "description": "وصف الكيفية التي ينبغي للمستخدم حل النشاط",\n      "default": "سحب الكلمات إلى المربعات الصحيحة"\n    },\n    {\n      "label": "نص",\n      "placeholder": "*أوسلو* هي عاصمة النرويج، و*ستوكهولم* هي عاصمة السويد، و*كوبنغاهن* هي عاصمة الدنمارك. وتقع جميع المدن في شبه الجزيرة *الإسكندنافية: الجزء الشمالي من أوروبا*.",\n      "important": {\n        "description": "<ul><li>تُضاف الكلمات القابلة للإسقاط مع وضع علامة نجمة (*) قبل الكلمة/العبارة الصحيحة وبعدها*.</li><li>يمكنك إضافة تلميح نصي باستخدام علامة النقطتان (:) قبل التلميح.</li><li>وهناك كلمة واحدة صحيحة فحسب لكل مساحة فارغة.</li><li>يمكنك إضافة ملاحظات ليجري عرضها عند إكمال مهمة. استخدم ’/+‘ لملاحظات الإجابة الصحيحة و’/-‘ لملاحظات الإجابة غير الصحيحة.</li></ul>",\n        "example": "يمكن تحرير محتوى H5P باستخدام *متصفح: أي نوع من البرامج هو ”كروم“؟*. <br /> محتوى H5P *تفاعلي/+إجابة صحيحة! /-إجابة غير صحيحة، فحاول مجدداً!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "شفافية خلفية العناصر",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "الافتراضي"\n            }\n          ],\n          "label": "تحديد الملاحظات المخصصة لأي نطاق درجة",\n          "description": "انقر على زر \\"إضافة نطاق\\" لإضافة ما ترغب به من نطاقات، ومثال على ذلك: 0-20٪ نتيجة سيئة، 21-91٪ نتيجة متوسطة، 91-100٪ نتيجة رائعة!",\n          "entity": "النطاق",\n          "field": {\n            "fields": [\n              {\n                "label": "نطاق الدرجة"\n              },\n              {},\n              {\n                "label": "ملاحظات لنطاق درجة محدد",\n                "placeholder": "أدخل الملاحظات"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "النص ل \\"تحقق \\" الزر",\n      "default": "Check"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "النص ل \\"إعادة المحاولة \\" الزر",\n      "default": "إعادة المحاولة"\n    },\n    {\n      "label": "النص  \\"مشاهدة الحل \\" الزر",\n      "default": "مشاهدة الحل"\n    },\n    {\n      "label": "Numbered Drop zone label",\n      "default": "Drop Zone @index.",\n      "description": "Label used for accessibility, where the Read speaker will read the index of a drop zone. Variable available: @index"\n    },\n    {\n      "label": "Empty Drop Zone label",\n      "default": "Drop Zone @index is empty.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone is empty"\n    },\n    {\n      "label": "Contains Drop Zone label",\n      "default": "Drop Zone @index contains draggable @draggable.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone contains a draggable"\n    },\n    {\n      "label": "Draggable elements label",\n      "default": "@index of @count draggables.",\n      "description": "تسمية مستخدمة لإمكانية الوصول، حيث يقرأ برنامج read speaker أن هذا عنصر قابل للسحب. المتغير متاح: @index، @count"\n    },\n    {\n      "label": "Label for show tip button",\n      "default": "Show tip",\n      "description": "تسمية مستخدمة لإمكانية الوصول، حيث يقرأ برنامج read speaker هذه العبارة قبل قراءة التلميح"\n    },\n    {\n      "label": "النص Readspeaker عن الإجابة الصحيحة",\n      "default": "صحيح!"\n    },\n    {\n      "label": "النص Readspeaker للإجابة غير صحيحة",\n      "default": "غير صحيح!"\n    },\n    {\n      "label": "Confirmation dialog title that user wants to reset a droppable",\n      "default": "Reset drop"\n    },\n    {\n      "label": "Confirmation dialog description that user wants to reset a droppable",\n      "default": "Are you sure you want to reset this drop?"\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is initiated",\n      "default": "Draggable is grabbed."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is canceled",\n      "default": "Cancelled dragging."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that a text is the correct answer",\n      "default": "الإجابة الصحيحة:"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "ملاحظات"\n    },\n    {\n      "label": "إعدادت النشاط",\n      "description": "وهذه الخيارات تمكنك من التحكم في كيفية سلوك هذا النشاط",\n      "fields": [\n        {\n          "label": "تمكين \\"إعادة المحاولة \\""\n        },\n        {\n          "label": "تمكين \\"مشاهدة الحل \\" الزر"\n        },\n        {\n          "label": "تمكين زر \\"التحقق\\""\n        },\n        {\n          "label": "تلميح"\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "تسمية التكنولوجيا المساعدة لزر ”إظهار الحلول“",\n      "default": "اعرض الحل. ستتحدد المهمة بحلها الصحيح."\n    },\n    {\n      "label": "تسمية التكنولوجيا المساعدة لزر ”إعادة المحاولة“",\n      "default": "إعادة المحاولة للمهمة. إعادة ضبط جميع الردود والبدء بالمهمة مرة أخرى."\n    }\n  ]\n}\n'),
(19, 'bg', '{\n  "semantics": [\n    {\n      "label": "Медия",\n      "fields": [\n        {\n          "label": "Тип",\n          "description": "Незадължителна медия, която да се показва над въпроса."\n        },\n        {\n          "label": "Деактивиране мащабирането на изображения"\n        }\n      ]\n    },\n    {\n      "label": "Описание на задачата",\n      "description": "Опишете как потребителят трябва да реши задачата.",\n      "default": "Плъзнете думите в правилните полета"\n    },\n    {\n      "label": "Текст",\n      "placeholder": "*Осло* е столицата на Норвегия, *Стокхолм* е столицата на Швеция и *Копенхаген* на Дания.",\n      "important": {\n        "description": "<ul><li>Думите, които трябва да бъдат плъзнати в празното поле се въвеждат чрез знака звезда (*) пред и зад съответната дума или фраза.</li><li>Можете да въведете текстова подсказда чрез знака (:) пред съответната подсказка.</li><li>За всяко празна клетка има само една коректна дума.</li><li>Можете да добавите обратна връзка да се показва след изпълнение на задачата. Използвайте ''\\\\+'' при вярно решение и ''\\\\-'' при грешно.</li></ul>",\n        "example": "Съдържанието на H5P може да се редактира с *browser:какъв тип програма е Chrome?*. <br /> Съдържанието на H5P е *интерактивно\\\\+Правилно! \\\\-Неправилно, опитай отново!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Обобщена обратна връзка",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "По подразбиране"\n            }\n          ],\n          "label": "Определете персонализирани отзиви за всеки диапазон от резултати",\n          "description": "Кликнете върху бутона \\"Добави диапазон\\" , за да добавите колкото диапазона искате. пример: 0-20% Лош резултат, 21-91% Среден резултат, 91-100% Отличен резултат!",\n          "entity": "диапазон",\n          "field": {\n            "fields": [\n              {\n                "label": "Диапазон на резултата"\n              },\n              {},\n              {\n                "label": "Обратна връзка за дефиниран диапазон на резултата",\n                "placeholder": "Попълване"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Текст за бутона \\"провери\\"",\n      "default": "Провери"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Текст за бутона \\"Опитай пак\\"",\n      "default": "Опитай пак"\n    },\n    {\n      "label": "Текст за бутона \\"Покажи решението\\"",\n      "default": "Покажи решението"\n    },\n    {\n      "label": "Етикет за номер на зоната за пускане",\n      "default": "Зона за пускане @index.",\n      "description": "Етикет, използван за обозначаване на достъпност, където екранният четец ще прочете номера на дадена зона. Налична променлива: @index"\n    },\n    {\n      "label": "Етикет за празна зона за пускане на текст",\n      "default": "Зоната за пускане на текст @index е празна.",\n      "description": "Етикет, използван за обозначаване на достъпност, при който екранният четец ще прочете, че зоната за пускане на текст е празна."\n    },\n    {\n      "label": "Етикет за зона за пускане на текст",\n      "default": "Зоната за пускане на текст @index съдържа елемента за влачене @draggable.",\n      "description": "Етикет, използван за достъпност, чрез който екранният четец ще прочете, че зоната на пускане съдържа елемент за плъзгане"\n    },\n    {\n      "label": "Етикет на елемент за влачене",\n      "default": "Текст за влачене @text. @index от @count елементи за плъзгане.",\n      "description": "Етикет, използван за достъпност, чрез който екранният четец ще прочете, че това е елемент за плъзгане. Достъпни променливи: @index, @count"\n    },\n    {\n      "label": "етикет, който показва бутона за подсказка",\n      "default": "Показване на подсказка",\n      "description": "Етикет, използван за достъпност, който екранният четец ще прочете преди да прочете подсказката"\n    },\n    {\n      "label": "Етикет за екранния четец за коректен отговор",\n      "default": "Вярно!"\n    },\n    {\n      "label": "Етикет за екранния четец за неверен отговор",\n      "default": "Грешно!"\n    },\n    {\n      "label": "Заглавие на диалоговия прозорец за потвърждение, което потребителят иска да нулира",\n      "default": "Нулиране"\n    },\n    {\n      "label": "Описание на диалоговия прозорец за потвърждение, което потребителят иска да нулира",\n      "default": "Сигурен ли сте, че искате да нулирате тази зона?"\n    },\n    {\n      "label": "Етикет, използван за достъпност, който показва, че е започнало плъзгане",\n      "default": "Плъзгането е започнало"\n    },\n    {\n      "label": "Етикет, използван за достъпност, който показва, че плъзгането е отменено",\n      "default": "Плъзгането е отменено."\n    },\n    {\n      "label": "Етикет, използван за достъпност, който показва, че текстът е правилният отговор",\n      "default": "Правилен отговор:"\n    },\n    {\n      "label": "Заглавие за панел, съдържащо обратна връзка за правилни / неправилни отговори",\n      "default": "Обратна връзка"\n    },\n    {\n      "label": "Настройки на поведението.",\n      "description": "Тези настройки ще ви позволят да определите как да се изпълняват задачите.",\n      "fields": [\n        {\n          "label": "Позволяване на бутон \\"Опитай пак\\""\n        },\n        {\n          "label": "Позволяване на бутон \\"Покажи решението\\""\n        },\n        {\n          "label": "Позволяване на бутон \\"Провери\\""\n        },\n        {\n          "label": "Незабавна обратна връзка"\n        }\n      ]\n    },\n    {\n      "label": "Текстово представяне на оценката за тези, които използват екранен четец",\n      "default": "Вие имате :num от общо :total точки"\n    },\n    {\n      "label": "Етикет за помощните технологии \\"Провери\\" бутон",\n      "default": "Проверяване на отговорите. Те ще бъдат маркирани като правилни, неправилни или без отговор."\n    },\n    {\n      "label": "Етикет за помощните технологии \\"Покажи решение\\" бутон",\n      "default": "Показване на решението. Задача ще бъде показана с вярното решение."\n    },\n    {\n      "label": "Етикет за помощните технологии \\"Опитай пак\\" бутон",\n      "default": "Опитайте отново да решите задачата. Нулирайте всички отговори и започнете задачата отначало."\n    }\n  ]\n}\n'),
(19, 'bs', '{\n  "semantics": [\n    {\n      "label": "Media",\n      "fields": [\n        {\n          "label": "Tip",\n          "description": "Opcionalni medij da se prikaže iznad pitanja."\n        },\n        {\n          "label": "Onemogući zumiranje slike"\n        }\n      ]\n    },\n    {\n      "label": "Opis zadatka",\n      "description": "Opiši kako korisnik treba riješiti problem.",\n      "default": "Prevucite riječi u odgovarajuća polja"\n    },\n    {\n      "label": "Tekst",\n      "placeholder": "*Oslo* je glavni grad Norveške, *Stockholm* je glavni grad Švedske i *Copenhagen* je glavni grad Danske. Svi gradovi su locirani u *Skandinavija:Sjeverni dio Europe* poluotok.",\n      "important": {\n        "description": "<ul><li>Droppable words are added with an asterisk (*) in front and behind the correct word/phrase.</li><li>You may add a textual tip, using a colon (:) in front of the tip.</li><li>For every empty spot there is only one correct word.</li><li>You may add feedback to be displayed when a task is completed. Use ''\\\\+'' for correct and ''\\\\-'' for incorrect feedback.</li></ul>",\n        "example": "H5P content may be edited using a *browser:What type of program is Chrome?*. <br /> H5P content is *interactive\\\\+Correct! \\\\-Incorrect, try again!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Pozadinska zamućenost za elemente za uzimanje",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Standard"\n            }\n          ],\n          "label": "Definiraj standardnu pvratnu informaciju za bilo koji raspon rezultata",\n          "description": "Klikni na dugme \\"Dodaj raspon\\" i dodaj raspon rezultata koliko je potrebno. Primjer: 0-20% Loše, 21-91% Dobro, 91-100% Odlično!",\n          "entity": "raspon",\n          "field": {\n            "fields": [\n              {\n                "label": "Raspon rezultata"\n              },\n              {},\n              {\n                "label": "Povratna informacija za definirani raspon rezultata",\n                "placeholder": "Popuni povratnu informaciju"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Oznaka za dugme \\"Provjeri\\"",\n      "default": "Provjeri"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Oznaka za dugme \\"Ponovi\\"",\n      "default": "Ponovi"\n    },\n    {\n      "label": "Tekst za dugme \\"Prikaži rješenje\\"",\n      "default": "Prikaži rješenje"\n    },\n    {\n      "label": "Oznaka numerisane zone za ostavljanje riječi",\n      "default": "Zona ispustanja @index.",\n      "description": "Label used for accessibility, where the Read speaker will read the index of a drop zone. Variable available: @index"\n    },\n    {\n      "label": "Oznaka prazne zone ostavljanja riječi",\n      "default": "Zona ispustanja @index je prazna.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone is empty"\n    },\n    {\n      "label": "Sadrži oznaku Zone za ostavljanje riječi",\n      "default": "Zona ispustanja @index sadrži @draggable.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone contains a draggable"\n    },\n    {\n      "label": "Oznaka elemenata za prenošenje",\n      "default": "@index od @count prenosivih riječi.",\n      "description": "Label used for accessibility, where the Read speaker reads that this is a draggable element. Variable available: @index, @count"\n    },\n    {\n      "label": "Oznaka za dugme prikaži tip",\n      "default": "Prikaži tip",\n      "description": "Label used for accessibility, where the Read speaker reads it before the tip is read out"\n    },\n    {\n      "label": "\\"Readspeaker\\" tekst za tačan odgovor",\n      "default": "Tačno!!"\n    },\n    {\n      "label": "\\"Readspeaker\\" tekst za netačan odgovor",\n      "default": "Netačno!!"\n    },\n    {\n      "label": "Confirmation dialog title that user wants to reset a droppable",\n      "default": "Resetiraj ostavljanje"\n    },\n    {\n      "label": "Confirmation dialog description that user wants to reset a droppable",\n      "default": "Jeste li sigurno da želite resetirati zonu ispustanja?"\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is initiated",\n      "default": "Riječ za prenošenje je uzeta."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is canceled",\n      "default": "Otkaži prenošenje."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that a text is the correct answer",\n      "default": "Tačan odgovor:"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "Povratna informacija"\n    },\n    {\n      "label": "Podešavanje ponašanja.",\n      "description": "Diese Optionen kontrollieren, wie sich die Aufgabe verhält.",\n      "fields": [\n        {\n          "label": "Omogući dugme \\"Ponovi\\""\n        },\n        {\n          "label": "Omogući \\"Prikaži rješenje\\""\n        },\n        {\n          "label": "Omogući dugme \\"Provjeri\\""\n        },\n        {\n          "label": "Instantna povratna informacija"\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "Postigli ste :num od :total bodova"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(19, 'ca', '{\n  "semantics": [\n    {\n      "label": "Recurs",\n      "fields": [\n        {\n          "label": "Tipus",\n          "description": "Recursos opcionals per mostrar al damunt de la pregunta."\n        },\n        {\n          "label": "Deshabilita el zoom de les imatges"\n        }\n      ]\n    },\n    {\n      "label": "Descripció de la tasca",\n      "description": "Descriu com l’usuari ha de resoldre la tasca.",\n      "default": "Arrossegueu les paraules a les caselles corresponents"\n    },\n    {\n      "label": "Text",\n      "placeholder": "*Oslo* és la capital de Noruega, *Estocolm* és la capital de Suècia i *Copenhaguen* és la capital de Dinamarca. Totes les ciutats estan situades a la península de *Scandinava: Part nord d’Europa*.",\n      "important": {\n        "description": "<ul><li>Les paraules que es poden deixar anar s’afegeixen amb un asterisc (*) davant i darrere de la paraula o frase correcta.</li><li>Podeu afegir una pista textual amb dos punts (:) davant de la pista.</li><li>Per cada espai buit, només hi ha una paraula correcta.</li><li>Podeu afegir suggeriments perquè es mostrin en completar una tasca. Utilitzeu ''\\\\+'' per als suggeriments correctes i ''\\\\-'' per als incorrectes.</li></ul>",\n        "example": "El contingut d’H5P es pot editar utilitzant un *navegador:Quin tipus de programa és Chrome?*. <br /> El contingut d’H5P és *interactiu\\\\+Correcte \\\\-Incorrecte; torna-ho a provar.*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Suggeriment general",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Opció predeterminada"\n            }\n          ],\n          "label": "Defineix una valoració per cada rang de puntuació",\n          "description": "Feu clic al botó \\"Afegeix un rang\\" per afegir tants rangs com necessiteu. Exemple: 0-20 % per a puntuació baixa, 21-91 % per a puntuació mitjana, 91-100 % per a puntuació excel·lent",\n          "entity": "rang",\n          "field": {\n            "fields": [\n              {\n                "label": "Rang de puntuació"\n              },\n              {},\n              {\n                "label": "Retroacció per al rang de puntuació definit",\n                "placeholder": "Introduïu el suggeriment"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text del botó \\"Verifica\\"",\n      "default": "Verifica"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Text del botó \\"Torna-ho a provar\\"",\n      "default": "Torna-ho a provar"\n    },\n    {\n      "label": "Text del botó \\"Mostra la solució\\"",\n      "default": "Mostra la solució"\n    },\n    {\n      "label": "Etiqueta per a Zona on deixar anar numerada",\n      "default": "Zona on deixar anar @index.",\n      "description": "Etiqueta utilitzada per a funcions d’accessibilitat, en què l’altaveu de lectura llegirà l’índex d’una zona on deixar anar. Variable disponible: @index"\n    },\n    {\n      "label": "Etiqueta per a una zona on deixar anar buida",\n      "default": "La zona on deixar anar @index està buida.",\n      "description": "Etiqueta utilitzada per a funcions d’accessibilitat, en què l’altaveu de lectura llegirà que la zona on deixar anar és buida"\n    },\n    {\n      "label": "Etiqueta de Conté una zona on deixar anar",\n      "default": "La zona on deixar anar @index conté @draggable que es pot arrossegar.",\n      "description": "Etiqueta utilitzada per a funcions d’accessibilitat, en què l’altaveu de lectura llegirà que la zona on deixar anar conté un element que es pot arrossegar"\n    },\n    {\n      "label": "Etiqueta dels elements que es poden arrossegar",\n      "default": "@index de @count draggables.",\n      "description": "Etiqueta utilitzada per a funcions d’accessibilitat, en què l’altaveu de lectura llegeix que és un element que es pot arrossegar. Variable disponible: @index, @count"\n    },\n    {\n      "label": "Etiqueta del botó de mostra de la pista",\n      "default": "Mostra la pista",\n      "description": "Etiqueta utilitzada per a funcions d’accessibilitat, en què l’altaveu de lectura llegeix el contingut abans de llegir la pista"\n    },\n    {\n      "label": "Text de l’altaveu de lectura per a una resposta correcta",\n      "default": "Correcte!"\n    },\n    {\n      "label": "Text de l’altaveu de lectura per a una resposta incorrecta",\n      "default": "Incorrecte!"\n    },\n    {\n      "label": "Títol del quadre de diàleg per confirmar que l’usuari vol restablir un element que es pot arrossegar",\n      "default": "Restableix l’element per deixar anar"\n    },\n    {\n      "label": "Descripció del quadre de diàleg per confirmar que l’usuari vol restablir un element que es pot arrossegar",\n      "default": "Confirmeu que voleu restablir aquesta zona on deixar anar?"\n    },\n    {\n      "label": "Etiqueta utilitzada per a funcions d’accessibilitat, en què l’altaveu de lectura indica que la funció d’arrossegar s’ha iniciat",\n      "default": "S’ha agafat un element que es pot arrossegar."\n    },\n    {\n      "label": "Etiqueta utilitzada per a funcions d’accessibilitat, en què l’altaveu de lectura indica que la funció d’arrossegar s’ha cancel·lat",\n      "default": "S’ha cancel·lat l’opció de deixar anar."\n    },\n    {\n      "label": "Etiqueta utilitzada per a funcions d’accessibilitat, en què l’altaveu de lectura indica que un text és la resposta correcta",\n      "default": "Resposta correcta:"\n    },\n    {\n      "label": "Encapçalament per al tauler que conté retroacció per a les respostes correctes/incorrectes",\n      "default": "Retroacció"\n    },\n    {\n      "label": "Opcions de comportament.",\n      "description": "Aquestes opcions et permetran controlar com es comporta la tasca.",\n      "fields": [\n        {\n          "label": "Activa \\"Torna-ho a provar\\""\n        },\n        {\n          "label": "Activa el botó \\"Mostra la solució\\""\n        },\n        {\n          "label": "Activa el botó \\"Comprova\\""\n        },\n        {\n          "label": "Suggeriments instantanis"\n        }\n      ]\n    },\n    {\n      "label": "Representació textual de la barra de puntuació pera als que utilitzen un altaveu de lectura",\n      "default": "Heu fet :num de :total punts"\n    },\n    {\n      "label": "Etiqueta de la tecnologia d’assistència per al botó \\"Comprova\\"",\n      "default": "Comprova les respostes. Les respostes es marcaran com a correctes, incorrectes o sense resposta."\n    },\n    {\n      "label": "Etiqueta de la tecnologia d’assistència per al botó \\"Mostra la solució\\"",\n      "default": "Mostra la solució. La tasca es marcarà amb la seva solució correcta."\n    },\n    {\n      "label": "Etiqueta de la tecnologia d’assistència per a l’etiqueta \\"Torna-ho a provar\\"",\n      "default": "Intenta de nou la tasca. Reajusta totes les respostes i comença la tasca de nou."\n    }\n  ]\n}\n'),
(19, 'cs', '{\n  "semantics": [\n    {\n      "label": "Média",\n      "fields": [\n        {\n          "label": "Typ",\n          "description": "Volitelná média zobrazená nad otázkou."\n        },\n        {\n          "label": "Zakázat zvětšení obrazu"\n        }\n      ]\n    },\n    {\n      "label": "Popis úlohy",\n      "description": "Popište, jak by měl uživatel úlohu vyřešit.",\n      "default": "Přetáhněte slova do správných polí"\n    },\n    {\n      "label": "Text",\n      "placeholder": "*Oslo* je hlavním městem Norska, *Stockholm* je hlavním městem Švédska a *Copenhagen* je hlavním městem Dánska. Všechna města se nacházejí na poloostrově *Skandinávie: Severní část Evropy* .",\n      "important": {\n        "description": "<ul><li>Přetahovatelná slova jsou přidána s hvězdičkou (*) před a za správným slovem/frází.</li><li>Můžete přidat textovou nápovědu pomocí dvojtečky (:) před nápovědou.</li><li>Pro každé prázdné místo je pouze jedno správné slovo.</li><li>Můžete přidat zpětnou vazbu, která se zobrazí po dokončení úlohy. Použijte ''\\\\+'' pro správnou a ''\\\\-'' pro nesprávnou zpětnou vazbu.</li></ul>",\n        "example": "Obsah H5P lze upravovat pomocí *prohlížeče:Jaký typ programu je Chrome?*. <br /> H5P obsah je *interaktivní\\\\+Správně! \\\\-Nesprávně, zkuste znovu!*"\n      }\n    },\n    {\n      "label": "Distraktory",\n      "placeholder": "*Reykjavík* *Helsinky*",\n      "description": "Zadejte další řešení, která jsou chybná jako distraktory. Použijte stejné schéma hvězdičky (*) jako pro text."\n    },\n    {\n      "label": "Celková zpětná vazba",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Výchozí"\n            }\n          ],\n          "label": "Definujte vlastní zpětnou vazbu pro jakýkoli rozsah skóre",\n          "description": "Klepnutím na tlačítko \\"Přidat rozsah\\" přidáte libovolný počet rozsahů. Příklad: 0-20% špatné skóre, 21-91% průměrné skóre, 91-100% výborné skóre!",\n          "entity": "rozsah",\n          "field": {\n            "fields": [\n              {\n                "label": "Rozsah skóre"\n              },\n              {},\n              {\n                "label": "Zpětná vazba pro definovaný rozsah skóre",\n                "placeholder": "Vyplňte zpětnou vazbu"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Popisek tlačítka \\"Zkontrolovat\\"",\n      "default": "Zkontrolovat"\n    },\n    {\n      "label": "Text pro tlačítko „Odeslat“",\n      "default": "Submit"\n    },\n    {\n      "label": "Popisek tlačítka \\"Opakovat\\"",\n      "default": "Opakovat"\n    },\n    {\n      "label": "Popisek tlačítka \\"Zobrazit řešení\\"",\n      "default": "Zobrazit řešení"\n    },\n    {\n      "label": "Popisek číslované zóna přetažení",\n      "default": "Zóna přetažení @index.",\n      "description": "Popisek používaný pro usnadnění přístupu, kde čtecí zařízení přečte index zóny přetažení. K dispozici je proměnná : @index"\n    },\n    {\n      "label": "Popisek Zóna přetažení je prázdná",\n      "default": "Zóna přetažení @index je prázdná.",\n      "description": "Popisek používaný pro usnadnění přístupu, kde čtecí zařízení přečte, že zóna přetažení je prázdná"\n    },\n    {\n      "label": "Popisek Obsah zóny přetažení",\n      "default": "Zóna přetažení @index obsahuje přetahovatelné @draggable.",\n      "description": "Štítek používaný pro usnadnění přístupu, kde čtecí zařízení přečte, že zóna přetažení obsahuje přetahovatelné prvky"\n    },\n    {\n      "label": "Popisek tahatelných prvků",\n      "default": "@index z @count přetahovatelných.",\n      "description": "Popisek používaný pro usnadnění přístupu, kde čtecí zařízení přečte, že se jedná o přetahovatelný prvek. Dostupná proměnná: @index, @count"\n    },\n    {\n      "label": "Popisek tlačítka pro zobrazení nápovědy",\n      "default": "Zobrazit nápovědu",\n      "description": "Štítek používaný pro usnadnění přístupu, kde čtecí zařízení přečte nápovědu"\n    },\n    {\n      "label": "Text čtecího zařízení pro správnou odpověď",\n      "default": "Správně!"\n    },\n    {\n      "label": "Text čtecího zařízení pro nesprávnou odpověď",\n      "default": "Nesprávně!"\n    },\n    {\n      "label": "Název dialogového okna s potvrzením, že uživatel chce resetovat přetažení",\n      "default": "Reset přetažení"\n    },\n    {\n      "label": "Popis dialogového okna s potvrzením, že uživatel chce resetovat přetažení",\n      "default": "Opravdu chcete resetovat tuto zónu přetažení?"\n    },\n    {\n      "label": "Popisek používaný pro usnadnění přístupu, kde čtecí zařízení indikuje zahájení přetažení",\n      "default": "Přetažení je zahájeno."\n    },\n    {\n      "label": "Popisek používaný pro usnadnění přístupu, kde čtecí zařízení indikuje, že přetažení je zrušeno",\n      "default": "Zrušené přetažení."\n    },\n    {\n      "label": "Popisek používaný pro usnadnění přístupu, kde řečený zařízení indikuje, že text je správná odpověď",\n      "default": "Správná odpověď:"\n    },\n    {\n      "label": "Záhlaví panelu obsahující zpětnou vazbu pro správné/nesprávné odpovědi",\n      "default": "Zpětná vazba"\n    },\n    {\n      "label": "Nastavení chování.",\n      "description": "Tyto možnosti vám umožní řídit, jak se úloha bude chovat.",\n      "fields": [\n        {\n          "label": "Povolit \\"Opakovat\\""\n        },\n        {\n          "label": "Povolit tlačítko \\"Zobrazit řešení\\""\n        },\n        {\n          "label": "Povolit tlačítko \\"Zkontrolovat\\""\n        },\n        {\n          "label": "Okamžitá zpětná vazba"\n        }\n      ]\n    },\n    {\n      "label": "Textové znázornění výsledkové lišty pro ty, kteří používají čtecí zařízení",\n      "default": "Získal jste :num z :total bodů"\n    },\n    {\n      "label": "Popisek podpůrné technologie pro tlačítko „Zkontrolovat“",\n      "default": "Zkontrolovat odpovědi. Odpovědi budou označeny jako správné, nesprávné nebo nezodpovězené."\n    },\n    {\n      "label": "Popisek podpůrné technologie pro tlačítko „Zobrazit řešení“",\n      "default": "Zobrazit řešení. Úkol bude zobrazen se správným řešením."\n    },\n    {\n      "label": "Popisek podpůrné technologie pro tlačítko „Opakovat“",\n      "default": "Zopakovat úkol. Resetovat všechny odpovědi a spustit úlohu znovu."\n    }\n  ]\n}\n'),
(19, 'da', '{\n  "semantics": [\n    {\n      "label": "Medie",\n      "fields": [\n        {\n          "label": "Type",\n          "description": "Vis valgfrit medie over spørgsmålet."\n        },\n        {\n          "label": "Deaktiver zoom af billede"\n        }\n      ]\n    },\n    {\n      "label": "Task description",\n      "description": "Describe how the user should solve the task.",\n      "default": "Drag the words into the correct boxes"\n    },\n    {\n      "label": "Text",\n      "placeholder": "*Oslo* is the capital of Norway, *Stockholm* is the capital of Sweden and *Copenhagen* is the capital of Denmark. All cities are located in the *Scandinavian:Northern Part of Europe* peninsula.",\n      "important": {\n        "description": "<ul><li>Droppable words are added with an asterisk (*) in front and behind the correct word/phrase.</li><li>You may add a textual tip, using a colon (:) in front of the tip.</li><li>For every empty spot there is only one correct word.</li><li>You may add feedback to be displayed when a task is completed. Use ''\\\\+'' for correct and ''\\\\-'' for incorrect feedback.</li></ul>",\n        "example": "H5P content may be edited using a *browser:What type of program is Chrome?*. <br /> H5P content is *interactive\\\\+Correct! \\\\-Incorrect, try again!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Default"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text for \\"Check\\" button",\n      "default": "Check"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Text for \\"Retry\\" button",\n      "default": "Retry"\n    },\n    {\n      "label": "Text for \\"Show Solution\\" button",\n      "default": "Show solution"\n    },\n    {\n      "label": "Numbered Drop zone label",\n      "default": "Drop Zone @index.",\n      "description": "Label used for accessibility, where the Read speaker will read the index of a drop zone. Variable available: @index"\n    },\n    {\n      "label": "Empty Drop Zone label",\n      "default": "Drop Zone @index is empty.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone is empty"\n    },\n    {\n      "label": "Contains Drop Zone label",\n      "default": "Drop Zone @index contains draggable @draggable.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone contains a draggable"\n    },\n    {\n      "label": "Draggable elements label",\n      "default": "@index of @count draggables.",\n      "description": "Label used for accessibility, where the Read speaker reads that this is a draggable element. Variable available: @index, @count"\n    },\n    {\n      "label": "Label for show tip button",\n      "default": "Show tip",\n      "description": "Label used for accessibility, where the Read speaker reads it before the tip is read out"\n    },\n    {\n      "label": "Readspeaker text for correct answer",\n      "default": "Correct!"\n    },\n    {\n      "label": "Readspeaker text for incorrect answer",\n      "default": "Incorrect!"\n    },\n    {\n      "label": "Confirmation dialog title that user wants to reset a droppable",\n      "default": "Reset drop"\n    },\n    {\n      "label": "Confirmation dialog description that user wants to reset a droppable",\n      "default": "Are you sure you want to reset this drop zone?"\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is initiated",\n      "default": "Draggable is grabbed."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is canceled",\n      "default": "Cancelled dragging."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that a text is the correct answer",\n      "default": "Correct answer:"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "Feedback"\n    },\n    {\n      "label": "Behavioural settings.",\n      "description": "These options will let you control how the task behaves.",\n      "fields": [\n        {\n          "label": "Enable \\"Retry\\""\n        },\n        {\n          "label": "Enable \\"Show Solution\\" button"\n        },\n        {\n          "label": "Enable \\"Check\\" button"\n        },\n        {\n          "label": "Instant feedback"\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'de', '{\n  "semantics": [\n    {\n      "label": "Medien",\n      "fields": [\n        {\n          "label": "Typ",\n          "description": "Medium, das wahlweise oberhalb der Aufgabe angezeigt wird."\n        },\n        {\n          "label": "Bild-Zoom deaktivieren"\n        }\n      ]\n    },\n    {\n      "label": "Aufgabenbeschreibung",\n      "description": "Beschreibung, wie die Lernenden die Aufgabe lösen sollten. Wird über dem Medium angezeigt.",\n      "default": "Ziehe die Wörter in die richtigen Felder!"\n    },\n    {\n      "label": "Text",\n      "placeholder": "*Oslo* ist die Hauptstadt von Norwegen, *Stockholm* ist die Hauptstadt von Schweden und *Kopenhagen* ist die Hauptstadt von Dänemark. Alle Städte befinden sich auf der *skandinavischen: nördlicher Teil von Europa* Halbinsel.",\n      "important": {\n        "description": "<ul><li>Ziehbare Wörter werden mit einem Sternchen (*) vor und hinter dem jeweiligen Wort bzw. Satzteil markiert.</li> <li>Du kannst einen Tipp mit einem Doppelpunkt (:) vor der dem Tipp hinzufügen.</li> <li>Pro Lücke gibt es nur genau eine richtige Antwort.</li> <li>Du kannst auch eine Rückmeldung hinzufügen, die angezeigt wird, wenn eine Aufgabe abgeschlossen wurde. Verwende \\"\\\\+\\" für positive und \\" \\\\-\\" für negative Rückmeldungen.</li></ul>",\n        "example": "H5P-Inhalt kann mit einem *Browser:Was für eine Art von Programm ist Chrome?* bearbeitet werden.<br />H5P-Inhalt ist *interaktiv\\\\+Richtig!\\\\-Falsch. Probiere es nochmal!*."\n      }\n    },\n    {\n      "label": "Distraktoren",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Gib zusätzlich falsche Lösungsoptionen an. Benutze dasselbe Sternchen-(*)-Schema wie für den Text."\n    },\n    {\n      "label": "Gesamtrückmeldung",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Eingabemaske"\n            }\n          ],\n          "label": "Lege Rückmeldungen für einzelne Punktebereiche fest",\n          "description": "Klicke auf den \\"Bereich hinzufügen\\"-Button, um so viele Bereiche hinzuzufügen, wie du brauchst. Beispiel: 0-20% Schlechte Punktzahl, 21-91% Durchschnittliche Punktzahl, 91-100% Großartige Punktzahl!",\n          "entity": "Bereich",\n          "field": {\n            "fields": [\n              {\n                "label": "Punktebereich"\n              },\n              {},\n              {\n                "label": "Rückmeldung für jeweiligen Punktebereich",\n                "placeholder": "Trage die Rückmeldung ein"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Beschriftung des \\"Überprüfen\\"-Buttons",\n      "default": "Überprüfen"\n    },\n    {\n      "label": "Beschriftung des \\"Absenden\\"-Buttons",\n      "default": "Absenden"\n    },\n    {\n      "label": "Beschriftung des \\"Wiederholen\\"-Buttons",\n      "default": "Wiederholen"\n    },\n    {\n      "label": "Beschriftung für den \\"Lösung anzeigen\\"-Button",\n      "default": "Lösung anzeigen"\n    },\n    {\n      "label": "Beschriftung: Nummer des Ablagefelds",\n      "default": "Ablagefeld @index.",\n      "description": "Die Beschriftung wird für Barrierefreiheit genutzt. Ein Readspeaker liest die Nummer des Ablagefeldes vor. Verfügbare Variable: @index"\n    },\n    {\n      "label": "Beschriftung: Leeres Ablagefeld",\n      "default": "Ablagefeld @index ist leer.",\n      "description": "Die Beschriftung wird für Barrierefreiheit genutzt. Ein Vorlesewerkzeug liest vor, dass das Ablagefeld leer ist."\n    },\n    {\n      "label": "Beschriftung: Ablagefeld enthält ziehbaren Text",\n      "default": "Ablagefeld @index enthält ziehbaren Text @draggable.",\n      "description": "Die Beschriftung wird für Barrierefreiheit genutzt. Ein Vorlesewerkzeug liest vor, dass das Ablagefeld ziehbaren Text enthält."\n    },\n    {\n      "label": "Beschriftung: Ziehbarer Text",\n      "default": "@index von @count ziehbaren Texten.",\n      "description": "Die Beschriftung wird für Barrierefreiheit genutzt. Ein Readspeaker liest vor, dass es sich um ziehbaren Text handelt. Verfügbare Variablen: @index, @count"\n    },\n    {\n      "label": "Beschriftung: Tipp anzeigen",\n      "default": "Tipp anzeigen",\n      "description": "Die Beschriftung wird für Barrierefreiheit genutzt. Ein Vorlesewerkzeug liest dies vor, bevor der Tipp vorgelesen wird."\n    },\n    {\n      "label": "Readspeaker-Text für eine richtige Antwort",\n      "default": "Richtig!"\n    },\n    {\n      "label": "Readspeaker-Text für eine falsche Antwort",\n      "default": "Falsch!"\n    },\n    {\n      "label": "Titel des Bestätigungsdialogs, wenn die Lernenden ziehbaren Text zurücksetzen möchten",\n      "default": "Ablagefelder zurücksetzen"\n    },\n    {\n      "label": "Text des Bestätigungsdialogs, wenn die Lernenden ziehbaren Text zurücksetzen möchten",\n      "default": "Bist du sicher, dass du dieses Ablagefeld zurücksetzen möchtest?"\n    },\n    {\n      "label": "Die Beschriftung wird für Barrierefreiheit genutzt. Ziehen-Modus hat begonnen",\n      "default": "Ziehbarer Text wurde aufgenommen."\n    },\n    {\n      "label": "Die Beschriftung wird für Barrierefreiheit genutzt. Ziehen-Modus abgebrochen",\n      "default": "Ziehen abgebrochen."\n    },\n    {\n      "label": "Die Beschriftung wird für Barrierefreiheit genutzt. Ein Readspeaker liest vor, dass die Antwort richtig war",\n      "default": "Korrekte Antwort:"\n    },\n    {\n      "label": "Überschrift für den Abschnitt, der die Rückmeldungen für richtige/falsche Antworten enthält",\n      "default": "Rückmeldung"\n    },\n    {\n      "label": "Verhaltenseinstellungen",\n      "description": "Diese Optionen legen fest, wie die Aufgabe auf Eingaben reagiert.",\n      "fields": [\n        {\n          "label": "\\"Wiederholen\\" zulassen"\n        },\n        {\n          "label": "\\"Lösung zeigen\\"-Button anzeigen"\n        },\n        {\n          "label": "\\"Überprüfen\\"-Button anzeigen"\n        },\n        {\n          "label": "Sofortige Rückmeldung"\n        }\n      ]\n    },\n    {\n      "label": "Anzeigetext der Punkteleiste für Readspeaker (Barrierefreiheit)",\n      "default": "Du hast :num von :total Punkten erreicht."\n    },\n    {\n      "label": "Beschreibung des \\"Überprüfen\\"-Buttons (für Hilfsmittel zur Barrierefreiheit)",\n      "default": "Die Antworten überprüfen. Die Eingaben werden als richtig, falsch oder unbeantwortet markiert."\n    },\n    {\n      "label": "Beschreibung des \\"Lösung anzeigen\\"-Buttons (für Hilfsmittel zur Barrierefreiheit)",\n      "default": "Die Lösung anzeigen. Die richtigen Lösungen werden in der Aufgabe angezeigt."\n    },\n    {\n      "label": "Beschreibung des \\"Wiederholen\\"-Buttons (für Hilfsmittel zur Barrierefreiheit)",\n      "default": "Die Aufgabe wiederholen. Alle Eingaben werden zurückgesetzt und die Aufgabe wird erneut gestartet."\n    }\n  ]\n}\n'),
(19, 'el', '{\n  "semantics": [\n    {\n      "label": "Μέσο",\n      "fields": [\n        {\n          "label": "Τύπος",\n          "description": "Προσθήκη μέσου προς εμφάνιση πάνω από την ερώτηση (προαιρετικά)."\n        },\n        {\n          "label": "Απενεργοποίηση της επιλογής zoom για την εικόνα της ερώτησης"\n        }\n      ]\n    },\n   {\n      "label": "Περιγραφή άσκησης",\n      "description": "Περιγράψτε τον τρόπο με τον οποίο ο χρήστης θα λύσει την άσκηση.",\n      "default": "Σύρετε τις λέξεις και αποθέστε τις στα κουτάκια"\n    },\n    {\n      "label": "Κείμενο",\n      "placeholder": "Το *Όσλο* είναι η πρωτεύουσα της Νορβηγίας, η *Στοκχόλμη* είναι η πρωτεύουσα της Σουηδίας και η *Κοπεγχάγη* είναι η πρωτεύουσα της Δανίας. Όλες οι περιοχές βρίσκονται στη *Σκανδιναβική* χερσόνησο.",\n      "important": {\n        "description": "<ul><li>Ορίστε τα συρόμενα στοιχεία - λέξεις χρησιμοποιώντας κάθε φορά έναν αστερίσκο (*) πριν και μετά τη λέξη.</li><li>Μπορείτε να ορίσετε επεξηγηματικό κείμενο προσθέτοντας μία άνω και κάτω τελεία (:) πριν την επεξήγηση.</li><li>Για κάθε κενό κουτάκι υπάρχει μόνο μια σωστή απάντηση.</li><li>Μπορείτε να προσθέσετε ανατροφοδότηση, η οποία θα εμφανίζεται μετά την ολοκλήρωση της άσκησης. Για ανατροφοδότηση σε σωστή απάντηση χρησιμοποιήστε ''\\\\+''. για ανατροφοδότηση σε λάθος απάντηση χρησιμοποιήστε ''\\\\-''.</li></ul>",\n        "example": "Μπορεί να γίνει επεξεργασία των αντικειμένων του e-me content με τη χρήση ενός *φυλλομετρητή: Τι είδους πρόγραμμα είναι ο Chrome;*.<br />Τα αντικείμενα του e-me content  είναι *διαδραστικά\\\\+Σωστό! \\\\-Λάθος, προσπάθησε ξανά!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Συνολική ανατροφοδότηση ",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Βασικό"\n            }\n          ],\n          "label": "Χαρακτηρισμός κάθε κλίμακας βαθμολογίας",\n          "description": "Κάντε κλικ στο κουμπί \\"Προσθήκη κλίμακας\\" για να προσθέσετε όσες  κλίμακες ή διαβαθμίσεις επιθυμείτε. Παράδειγμα: 0-20% Χαμηλή βαθμολογία, 21-91% Μέτρια βαθμολογία, 91-100% Εξαιρετική βαθμολογία!",\n          "entity": "κλιμακας",\n          "field": {\n            "fields": [\n              {\n                "label": "Βαθμολογία"\n              },\n              {},\n              {\n                "label": "Χαρακτηρισμός",\n                "placeholder": "Συμπληρώστε τον χαρακτηρισμό"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Ετικέτα κουμπιού ελέγχου απάντησης",\n      "default": "Έλεγχος"\n    },\n    {\n      "label": "Ετικέτα κουμπιού υποβολής απάντησης",\n      "default": "Υποβολή"\n    },\n    {\n      "label": "Ετικέτα κουμπιού νέας προσπάθειας",\n      "default": "Επανάληψη"\n    },\n    {\n      "label": "Ετικέτα κουμπιού εμφάνισης λύσης",\n      "default": "Λύση"\n    },\n    {\n      "label": "Ετικέτα για περιοχή απόθεσης",\n      "default": "Κουτάκι @index.",\n      "description": "Η ετικέτα χρησιμοποιείται για λόγους προσβασιμότητας, ώστε η εφαρμογή ακουστικής υποβοήθησης να δηλώσει την εκάστοτε περιοχή απόθεσης. Διαθέσιμη μεταβλητή: @index"\n    },\n    {\n      "label": "Ετικέτα για κενή περιοχή απόθεσης",\n      "default": "Το κουτάκι @index είναι κενό.",\n      "description": "Η ετικέτα χρησιμοποιείται για λόγους προσβασιμότητας, ώστε να διαβαστεί από την εφαρμογή ακουστικής υποβοήθησης και να δηλώσει ότι η περιοχή απόθεσης είναι κενή"\n    },\n    {\n      "label": "Ετικέτα περιεχομένου περιοχής απόθεσης",\n      "default": "Το κουτάκι @index περιέχει το συρόμενο στοιχείο - λέξη @draggable.",\n      "description": "Η ετικέτα χρησιμοποιείται για λόγους προσβασιμότητας, ώστε η εφαρμογή ακουστικής υποβοήθησης να δηλώσει ότι η περιοχή απόθεσης περιέχει ένα συρόμενο στοιχείο - λέξη"\n    },\n    {\n      "label": "Ετικέτα συρόμενων στοιχείων",\n      "default": "@index από @count συρόμενα στοιχεία - λέξεις.",\n      "description": "Η ετικέτα χρησιμοποιείται για λόγους προσβασιμότητας, ώστε η εφαρμογή ακουστικής υποβοήθησης να δηλώσει ότι πρόκειται για συρόμενο στοιχείο. Διαθέσιμες μεταβλητές: @index, @count"\n    },\n    {\n      "label": "Ετικέτα κουμπιού εμφάνισης επεξηγηματικού κειμένου",\n      "default": "Επεξηγηματικό κείμενο",\n      "description": "Η ετικέτα χρησιμοποιείται για λόγους προσβασιμότητας, ώστε να διαβαστεί από την εφαρμογή ακουστικής υποβοήθησης πριν την ανάγνωση του επεξηγηματικού κειμένου"\n    },\n    {\n      "label": "Ετικέτα σωστής απάντησης για υποστηρικτικές τεχνολογίες",\n      "default": "Σωστό!"\n    },\n    {\n      "label": "Ετικέτα λάθος απάντησης για υποστηρικτικές τεχνολογίες",\n      "default": "Λάθος!"\n    },\n    {\n      "label": "Τίτλος παραθύρου επιβεβαίωσης: Επαναφορά απόθεσης",\n      "default": "Επαναφορά"\n    },\n    {\n      "label": "Κυρίως κείμενο παραθύρου επιβεβαίωσης: Επαναφορά απόθεσης",\n      "default": "Είσαι σίγουρος/η ότι θέλεις να αδειάσεις το κουτάκι;"\n    },\n    {\n      "label": "Η ετικέτα χρησιμοποιείται για λόγους προσβασιμότητας, ώστε η εφαρμογή ακουστικής υποβοήθησης να δηλώσει ότι το σύρσιμο του στοιχείου - λέξης έχει ξεκινήσει",\n      "default": "To συρόμενo στοιχείο - λέξη έχει επιλεγεί."\n    },\n    {\n      "label": "Η ετικέτα χρησιμοποιείται για λόγους προσβασιμότητας, ώστε η εφαρμογή ακουστικής υποβοήθησης να δηλώσει ότι το σύρσιμο του στοιχείου - λέξης έχει ακυρωθεί",\n      "default": "Ακύρωση συρσίματος."\n    },\n    {\n      "label": "Η ετικέτα χρησιμοποιείται για λόγους προσβασιμότητας, ώστε η εφαρμογή ακουστικής υποβοήθησης να δηλώσει ότι το κείμενο αντιστοιχεί στη σωστή απάντηση",\n      "default": "Σωστή απάντηση:"\n    },\n    {\n      "label": "Επικεφαλίδα πλαισίου ανατροφοδότησης για σωστές/λάθος απαντήσεις",\n      "default": "Ανατροφοδότηση"\n    },\n    {\n      "label": "Ρυθμίσεις άσκησης",\n      "description": "Αυτές οι ρυθμίσεις σας επιτρέπουν να καθορίσετε τον τρόπο λειτουργίας της άσκησης.",\n      "fields": [\n        {\n          "label": "Ενεργοποίηση κουμπιού \\"Επανάληψη\\""\n        },\n        {\n          "label": "Ενεργοποίηση κουμπιού \\"Λύση\\""\n        },\n        {\n          "label": "Ενεργοποίηση κουμπιού \\"Έλεγχος\\""\n        },\n        {\n          "label": "Άμεση ανατροφοδότηση"\n        }\n      ]\n    },\n    {\n      "label": "Κειμενική απόδοση της μπάρας βαθμολογίας για όσους χρησιμοποιούν ακουστική υποβοήθηση",\n      "default": "Έχεις :num από :total βαθμούς"\n    },\n    {\n      "label": "Περιγραφή υποστηρικτικών τεχνολογιών για το πλήκτρο \\"Έλεγχος\\"",\n      "default": "Έλεγχος απαντήσεων. Οι απαντήσεις θα μαρκαριστούν ως σωστές, λάθος και μη απαντημένες."\n    },\n    {\n      "label": "Περιγραφή υποστηρικτικών τεχνολογιών για το πλήκτρο \\"Λύση\\"",\n      "default": "Προβολή της λύσης. Η άσκηση θα επισημανθεί με την σωστή απάντση."\n    },\n    {\n      "label": "Περιγραφή υποστηρικτικών τεχνολογιών για το πλήκτρο \\"Επανάληψη\\"",\n      "default": "Επανάληψη της εργασίας. Επαναφορά όλων των απαντήσεων και έναρξη από την αρχή."\n    }\n  ]\n}\n'),
(19, 'es', '{\n  "semantics": [\n    {\n      "label": "Medios",\n      "fields": [\n        {\n          "label": "Tipo",\n          "description": "Medios opcionales mostrados encima de la pregunta."\n        },\n        {\n          "label": "Deshabilitar acercamiento de imagen"\n        }\n      ]\n    },\n    {\n      "label": "Descripción de la tarea",\n      "description": "Describe cómo debería resolver la tarea el usuario.",\n      "default": "Arrastra las palabras a las cajas correctas"\n    },\n    {\n      "label": "Texto",\n      "placeholder": "*Oslo* es la capital de Noruega, *Estocolmo* es la capital de Suecia y *Copenhague* es la capital de Dinamarca. Todas las ciudades están ubicadas en la península *Escandinava:Parte norte de Europa*.",\n      "important": {\n        "description": "<ul><li>Las palabras que se podrán arrastrar se agregan con un asterisco (*) al frente y detrás de la palabra / frase correcta.</li><li>Puedes agregar una sugerencia textual, usando dos puntos (:) antes de la sugerencia.</li><li>Por cada hueco vacío solo hay una palabra correcta.</li><li>Puedes agregar retroalimentación que se mostrarán cuando se complete la tarea. Utiliza ''\\\\+'' para retroalimentación en caso de respuesta correcta ''\\\\-'' para retroalimentación para las incorrectas.</li></ul>",\n        "example": "El contenido de H5P se puede editar utilizando un *navegador:¿Qué tipo de programa es Chrome?*. <br /> El contenido de H5P es *interactivo\\\\+Correcto! \\\\-Incorrecto, prueba de nuevo!*"\n      }\n    },\n    {\n      "label": "Distractores",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Escriba soluciones incorrectas extra como distractores. Use el mismo esquema con asterisco (*) como para el texto."\n    },\n    {\n      "label": "Retroalimentación Global",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Predeterminado"\n            }\n          ],\n          "label": "Definir retroalimentación personalizada para cualquier rango de puntaje",\n          "description": "Haga clic en el botón \\"Añadir rango\\" para añadir cuantos rangos necesite. Ejemplo: 0-20% Mal puntaje, 21-91% Puntaje Promedio, 91-100% ¡Magnífico Puntaje!",\n          "entity": "rango",\n          "field": {\n            "fields": [\n              {\n                "label": "Rango del Puntaje"\n              },\n              {},\n              {\n                "label": "Retroalimentación para rango de puntaje definido",\n                "placeholder": "Completa la retroalimentación"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texto para botón \\"Comprobar\\"",\n      "default": "Comprobar"\n    },\n    {\n      "label": "Texto para botón \\"Enviar\\"",\n      "default": "Enviar"\n    },\n    {\n      "label": "Texto para el botón \\"Intentar de nuevo\\"",\n      "default": "Reintentar"\n    },\n    {\n      "label": "Texto para botón \\"Mostrar solución\\"",\n      "default": "Mostrar solución"\n    },\n    {\n      "label": "Etiqueta de zona de colocación numerada",\n      "default": "Zona de colocación @index.",\n      "description": "Etiqueta utilizada para accesibilidad, donde el lector de pantalla leerá el índice de una zona de colocación. Variable disponible: @index"\n    },\n    {\n      "label": "Etiqueta para Zona de Colocación vacía",\n      "default": "La zona de Colocación @index está vacía.",\n      "description": "Etiqueta utilizada para la accesibilidad, donde el lector de pantalla leerá que la zona de colocación está vacía"\n    },\n    {\n      "label": "Contiene etiqueta de Zona de Colocación",\n      "default": "la zona de Colocación @index contiene elemento @draggable.",\n      "description": "Etiqueta utilizada para accesibilidad, donde el lector de pantalla leerá que la zona de colocación contiene un elemento que se puede colocar"\n    },\n    {\n      "label": "Etiqueta de elementos que se pueden colocar",\n      "default": "@index de @count elementos que se pueden colocar.",\n      "description": "Etiqueta utilizada para la accesibilidad, donde el lector de pantalla lee que se trata de un elemento que se puede colocar. Variable disponible: @index, @count"\n    },\n    {\n      "label": "Etiqueta para el botón de pista",\n      "default": "Mostrar pista",\n      "description": "Etiqueta utilizada para accesibilidad que el lector de pantalla lee antes de leer la pista"\n    },\n    {\n      "label": "Texto para lector de pantalla para respuesta correcta",\n      "default": "¡Correcto!"\n    },\n    {\n      "label": "Texto para lector de pantalla para respuesta incorrecta",\n      "default": "¡Incorrecto!"\n    },\n    {\n      "label": "Título del diálogo de confirmación cuando el usuario quiere deshacer una colocación",\n      "default": "Restablecer colocación"\n    },\n    {\n      "label": "Descripción del diálogo de confirmación cuando el usuario quiere deshacer una colocación",\n      "default": "¿Seguro que quieres restablecer esta zona de colocación?"\n    },\n    {\n      "label": "Etiqueta utilizada para accesibilidad, donde el lector de pantalla indica que se inició el arrastre",\n      "default": "Has cogido el elemento a arrastrar."\n    },\n    {\n      "label": "Etiqueta utilizada para accesibilidad, donde el lector de pantalla indica que el arrastre está cancelado",\n      "default": "Arrastre cancelado."\n    },\n    {\n      "label": "Etiqueta utilizada para accesibilidad, donde el lector de pantalla indica que el texto es la respuesta correcta",\n      "default": "Respuesta correcta:"\n    },\n    {\n      "label": "Encabezado para el panel que contiene retroalimentación para respuestas correctas/incorrectas",\n      "default": "Retroalimentación"\n    },\n    {\n      "label": "Configuración del comportamiento.",\n      "description": "Estas opciones le permitirán controlar cómo se comporta la tarea.",\n      "fields": [\n        {\n          "label": "Habilitar \\"Intentar de nuevo\\""\n        },\n        {\n          "label": "Habilitar botón \\"Mostrar Solución\\""\n        },\n        {\n          "label": "Habilitar botón \\"Comprobar\\""\n        },\n        {\n          "label": "Retroalimentación instantánea"\n        }\n      ]\n    },\n    {\n      "label": "Representación textual de la barra de puntuación cuando se usa un lector de pantalla",\n      "default": "Has obtenido :num de un total de :total puntos"\n    },\n    {\n      "label": "Etiqueta para las tecnologías de asistencia para el botón \\"Comprobar\\"",\n      "default": "Comprueba las respuestas. Las respuestas se marcarán como correctas, incorrectas o sin respuesta."\n    },\n    {\n      "label": "Descripción para las tecnologías de asistencia del botón \\"Mostrar solución\\"",\n      "default": "Mostrar la solución. El trabajo será calificado con su solución correcta."\n    },\n    {\n      "label": "Descripción para las tecnologías de asistencia del botón \\"Intentar de nuevo\\"",\n      "default": "Vuelve a intentar la tarea. Borra todas tus respuestas y empieza de nuevo."\n    }\n  ]\n}\n'),
(19, 'es-mx', '{\n  "semantics": [\n    {\n      "label": "Medios",\n      "fields": [\n        {\n          "label": "Tipo",\n          "description": "Medios opcionales mostrados encima de la pregunta."\n        },\n        {\n          "label": "Deshabilitar acercamiento de imagen"\n        }\n      ]\n    },\n    {\n      "label": "Descripción del trabajo",\n      "description": "Describe como el usuario debería resolver el trabajo.",\n      "default": "Arrastrar las palabras a las cajas correctas"\n    },\n    {\n      "label": "Texto",\n      "placeholder": "*Oslo* es la capital de Noruega, *Estocolmo* es la capital de Suecia y *Copenhague* es la capital de Dinamarca. Todas las ciudades están ubicadas en la península *Escandinava:Parte norte de Europa*.",\n      "important": {\n        "description": "<ul><li>Las palabras desplegables se agregan con un asterisco (*) al frente y detrás de la palabra / frase correcta.</li><li>Puede agregar una sugerencia textual, usando dos puntos (:) en frente de la sugerencia.</li><li>Por cada punto vacío solo hay una palabra correcta.</li><li>Puede agregar comentarios que se mostrarán cuando se complete una tarea. Utilizar ''\\\\+'' para los correctos ''\\\\-'' para comentarios incorrectos.</li></ul>",\n        "example": "El contenido de H5P se puede editar utilizando un *navegador:¿Qué tipo de programa es Chrome?*. <br /> El contenido H5P es *interactivo\\\\+¡Correcto! \\\\-¡Incorrecto, prueba de nuevo!*"\n      }\n    },\n    {\n      "label": "Distractores",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Escriba soluciones incorrectas extra como distractores. Use el mismo esquema con asterisco (*) como para el texto."\n    },\n    {\n      "label": "Retroalimentación Global",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Predeterminado"\n            }\n          ],\n          "label": "Definir retroalimentación personalizada para cualquier rango de puntaje",\n          "description": "Haga clic en el botón \\"Añadir rango\\" para añadir cuantos rangos necesite. Ejemplo: 0-20% Mal puntaje, 21-91% Puntaje Promedio, 91-100% ¡Magnífico Puntaje!",\n          "entity": "rango",\n          "field": {\n            "fields": [\n              {\n                "label": "Rango del Puntaje"\n              },\n              {},\n              {\n                "label": "Retroalimentación para rango de puntaje definido",\n                "placeholder": "Complete la retroalimentación"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texto para botón \\"Comprobar\\"",\n      "default": "Comprobar"\n    },\n    {\n      "label": "Texto para botón \\"Enviar\\"",\n      "default": "Enviar"\n    },\n    {\n      "label": "Texto para el botón \\"Reintentar\\"",\n      "default": "Reintentar"\n    },\n    {\n      "label": "Texto para botón \\"Mostrar solución\\"",\n      "default": "Mostrar solución"\n    },\n    {\n      "label": "Etiqueta de zona de colocación numerada",\n      "default": "Zona de colocación @index.",\n      "description": "Etiqueta utilizada para accesibilidad, donde el lector de pantalla leerá el índice de una zona de colocación. Variable disponible: @index"\n    },\n    {\n      "label": "Etiqueta para Zona de Colocación vacía",\n      "default": "La zona de Colocación @index está vacía.",\n      "description": "Etiqueta utilizada para la accesibilidad, donde el lector de pantalla leerá que la zona de colocación está vacía"\n    },\n    {\n      "label": "Contiene etiqueta de Zona de Colocación",\n      "default": "La zona de Colocación @index contiene elemento @draggable.",\n      "description": "Etiqueta utilizada para accesibilidad, donde el lector de pantalla leerá que la zona de colocación contiene un elemento que se puede colocar"\n    },\n    {\n      "label": "Etiqueta de elementos que se pueden colocar",\n      "default": "@index de @count elementos que se pueden colocar.",\n      "description": "Etiqueta utilizada para la accesibilidad, donde el lector de pantalla lee que se trata de un elemento que se puede colocar. Variable disponible: @index, @count"\n    },\n    {\n      "label": "Etiqueta para mostrar el botón de pista",\n      "default": "Mostrar pista",\n      "description": "Etiqueta utilizada para accesibilidad, donde el Lector de texto en voz alta la lee antes de leer la pista"\n    },\n    {\n      "label": "Texto de Lector en voz alta para respuesta correcta",\n      "default": "¡Correcto!"\n    },\n    {\n      "label": "Texto del Lector en voz alta para respuesta incorrecta",\n      "default": "¡Incorrecto!"\n    },\n    {\n      "label": "Título del diálogo de confirmación cuando el usuario quiere deshacer una colocación",\n      "default": "Restablecer colocación"\n    },\n    {\n      "label": "Descripción del diálogo de confirmación cuando el usuario quiere deshacer una colocación",\n      "default": "¿Seguro que quieres restablecer esta zona de colocación?"\n    },\n    {\n      "label": "Etiqueta utilizada para accesibilidad, donde el lector de pantalla indica que se inició el arrastre",\n      "default": "El arrastrable está agarrado."\n    },\n    {\n      "label": "Etiqueta utilizada para accesibilidad, donde el Lector de texto en voz alta indica que el arrastre está cancelado",\n      "default": "Arrastre cancelado."\n    },\n    {\n      "label": "Etiqueta utilizada para accesibilidad, donde el Lector de texto en voz alta indica que un texto es la respuesta correcta",\n      "default": "Respuesta correcta:"\n    },\n    {\n      "label": "Encabezado para el panel que contiene retroalimentación para respuestas correctas/incorrectas",\n      "default": "Retroalimentación"\n    },\n    {\n      "label": "Configuraciones del comportamiento.",\n      "description": "Estas opciones le permitirán controlar como se comporta el trabajo.",\n      "fields": [\n        {\n          "label": "Habilitar \\"Reintentar\\""\n        },\n        {\n          "label": "Habilitar botón \\"Mostrar Solución\\""\n        },\n        {\n          "label": "Habilitar botón \\"Comprobar\\""\n        },\n        {\n          "label": "Retroalimentación instantánea"\n        }\n      ]\n    },\n    {\n      "label": "Representación textual de la barra de puntaje para aquellos que usan un lector de texto en voz alta",\n      "default": "Obtuvo :num de un total de :total puntos"\n    },\n    {\n      "label": "Etiqueta para las tecnologías de asistencia para el botón \\"Comprobar\\"",\n      "default": "Comprobar las respuestas. Las respuestas serán marcadas como correcta, incorrecta o sin contestar."\n    },\n    {\n      "label": "Descripción para las tecnologías de asistencia del botón \\"Mostrar solución\\"",\n      "default": "Mostrar la solución. El trabajo será calificado con su solución correcta."\n    },\n    {\n      "label": "Descripción para las tecnologías de asistencia del botón \\"Reintentar\\"",\n      "default": "Reintentar el trabajo. Reiniciar todas las respuestas e iniciar el trabajo de nuevo."\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(19, 'et', '{\n  "semantics": [\n    {\n      "label": "Pilt või video",\n      "fields": [\n        {\n          "label": "Tüüp",\n          "description": "Pilt või video, mida kuvatakse küsimuse juures (mittekohustuslik element)."\n        },\n        {\n          "label": "Keela pildi suuruse muutmine"\n        }\n      ]\n    },\n    {\n      "label": "Ülesande kirjeldus",\n      "description": "Kirjelda, kuidas kasutaja peaks ülesande lahendama.",\n      "default": "Lohista sõnad õigetesse kastidesse"\n    },\n    {\n      "label": "Tekst",\n      "placeholder": "*Oslo* on Norra pealinn, *Stockholm* on Rootsi pealinn ja *Kopenhaagen* on Taani pealinn. Kõik need linnad asuvad *Skandinaavia:Euroopa põhjaosa* poolsaarel.",\n      "important": {\n        "description": "<ul><li>Lohistatavad sõnade või fraaside loomiseks märgitakse nende ette ja järele tärn (*).</li><li>Samuti saad lisada tekstivihje, kasutades koolonit (:) vihje ees.</li><li>Igale tühjale kohale sobib vaid üks õige sõna.</li><li>Saad lisada peale ülesande täitmist näidatava tagasiside. Kasuta ''\\\\+'' õige ja ''\\\\-'' vale vastuse tagasisideks.</li></ul>",\n        "example": "H5P sisu töötlemiseks sobib *brauser:Mis tüüpi programm on Chrome?*. <br /> H5P sisu on *interaktiivne\\\\+Õige! \\\\-Vale, proovi uuesti!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Üldine tagasiside",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Vaikimisi"\n            }\n          ],\n          "label": "Määra kohandatud tagasiside punktisummade vahemikele",\n          "description": "Lisa nii palju vahemikke, kui vaja, klikkides \\"Lisa vahemik\\" nupule. Näiteks: 0-20% halb tulemus, 21-91% keskmine tulemus, 91-100% suurepärane tulemus!",\n          "entity": "vahemik",\n          "field": {\n            "fields": [\n              {\n                "label": "Punktisummade vahemik"\n              },\n              {},\n              {\n                "label": "Määratud punktisumma vahemiku tagasiside",\n                "placeholder": "Täida tagasiside"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "\\"Kontrolli\\" nupu tekst",\n      "default": "Kontrolli"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "\\"Proovi uuesti\\" nupu tekst",\n      "default": "Proovi uuesti"\n    },\n    {\n      "label": "\\"Õige vastus\\" nupu tekst",\n      "default": "Õige vastus"\n    },\n    {\n      "label": "Nummerdatud sihtkoha silt",\n      "default": "Sihtkoht @index.",\n      "description": "Puudega kasutajale mõeldud silt, millelt tekstiluger loeb sihtkoha indeksi. Kasutatav muutuja: @index"\n    },\n    {\n      "label": "Tühja sihtkoha silt",\n      "default": "Sihtkoht @index on tühi.",\n      "description": "Puudega kasutajale mõeldud silt, millelt tekstiluger loeb, et sihtkoht on tühi"\n    },\n    {\n      "label": "Täidetud sihtkoha silt",\n      "default": "Sihtkoht @index sisaldab lohistatavat elementi @draggable.",\n      "description": "Puudega kasutajale mõeldud silt, millelt tekstiluger loeb, et sihtkohas on lohistatav element"\n    },\n    {\n      "label": "Lohistatava elemendi silt",\n      "default": "@index / @count elemendist.",\n      "description": "Puudega kasutajale mõeldud silt, millelt tekstiluger loeb, et see on lohistatav element. Kasutatav muutuja: @index, @count"\n    },\n    {\n      "label": "Näita vihjet nupu silt",\n      "default": "Vihje",\n      "description": "Puudega kasutajale mõeldud silt, mida tekstiluger loeb enne vihje ette lugemist"\n    },\n    {\n      "label": "tekstilugeri tekst õigele vastusele",\n      "default": "Õige!"\n    },\n    {\n      "label": "tekstilugeri tekst valele vastusele",\n      "default": "Vale!"\n    },\n    {\n      "label": "Kinnitusdialoogi tiitel juhuks, kui kasutaja tahab lohistatavat lähtestada",\n      "default": "Lohistuse lähtestamine"\n    },\n    {\n      "label": "Kinnitusdialoogi kirjeldus juhuks, kui kasutaja tahab lohistatavat lähtestada",\n      "default": "Kas oled kindel, et soovid selle sihtkoha lähtestada?"\n    },\n    {\n      "label": "Puudega kasutajale mõeldud silt, millelt tekstiluger osutab, et lohistamist alustati",\n      "default": "Lohistatav on haaratud."\n    },\n    {\n      "label": "Puudega kasutajale mõeldud silt, millelt tekstiluger osutab, et lohistamine on tühistatud",\n      "default": "Lohistamine tühistati."\n    },\n    {\n      "label": "Puudega kasutajale mõeldud silt, millelt tekstiluger osutab, et tekst on õige vastus",\n      "default": "Õige vastus:"\n    },\n    {\n      "label": "Õigete/valede vastuste tagasiside paneeli pealkiri",\n      "default": "Tagasiside"\n    },\n    {\n      "label": "Käitumisseaded.",\n      "description": "Nende valikutega saad määrata ülesande käitumise.",\n      "fields": [\n        {\n          "label": "Luba \\"Proovi uuesti\\""\n        },\n        {\n          "label": "Luba \\"Näita lahendust\\" nupp"\n        },\n        {\n          "label": "Luba \\"Kontrolli\\" nupp"\n        },\n        {\n          "label": "Kohene tagasiside"\n        }\n      ]\n    },\n    {\n      "label": "Tekstilugeri kasutajale määratud punktisumma rea tekstiline esitus",\n      "default": "Sa said :num punkti :total punktist"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'eu', '{\n  "semantics": [\n    {\n      "label": "Multimedia",\n      "fields": [\n        {\n          "label": "Mota",\n          "description": "Galderaren gainean bistaratzeko aukerako multimedia."\n        },\n        {\n          "label": "Desgaitu irudien zooma"\n        }\n      ]\n    },\n    {\n      "label": "Atazaren deskribapena",\n      "description": "Deskribatu zereginaren irtenbidea aurkitzeko modua.",\n      "default": "Arrastatu hitzak dagozkien kutxetara"\n    },\n    {\n      "label": "Testua",\n      "placeholder": "*Oslo* Norvegiako hiruburua da, *Stockholm* Suediako hiriburua da eta *Kopenhagen* Danimarkako hiriburua da. Hiru hiri *Eskandinavia:Europako iparraldeko* penintsulan daude.",\n      "important": {\n        "description": "<ul><li>Jaregin daitezkeen hitzak edo esaldiak gehitu dira izartxo (*) bat aurretik eta beste bat atzetik dutela bere kokaleku egokian.</li><li>Gehitzen ahal dituzu laguntzak, horien aurretik bi puntu (:) jarrita.</li><li>Hutsune bakoitzak hitz/esaldi zuzen bakarra dago.</li><li>Gehitzen ahal duzu ataza burutu ondoren ikusiko diren feedbackak. Erabili ''\\\\+'' erantzun zuzenen feedbackerako eta ''\\\\-'' erantzun okerretarako.</li></ul>",\n        "example": "H5P edukia editatu daiteke *nabigatzailez:Zer aplikazio mota da Chrome?*. <br /> H5P edukia *interaktiboa\\\\+Asmatu duzu! \\\\-Ez da zuzena, saiatu berriro!* da"\n      }\n    },\n    {\n      "label": "Distraitzaileak",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Sartu distraitzaile gisa okerrak diren irtenbide gehigarriak. Erabili testurako izartxo (*) eskema bera."\n    },\n    {\n      "label": "Feedback Orokorra",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Lehenetsitakoa"\n            }\n          ],\n          "label": "Zehaztu ezazu edozein puntuazio-tarterako feedback pertsonalizatua",\n          "description": "Egin klik \\"Gehitu tartea\\" botoian behar dituzun tarte guztiak gehitzeko. Adibidez: 0-20% Puntuazio eskasa, 21-91% Batez besteko puntuazioa, 91-100% Puntuazio bikaina!",\n          "entity": "tartea",\n          "field": {\n            "fields": [\n              {\n                "label": "Puntazio-tartea"\n              },\n              {},\n              {\n                "label": "Zehaztutako tartearentzako feedbacka",\n                "placeholder": "Idatzi ezazu feedbacka"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "\\"Egiaztatu\\" botoiarentzako testua",\n      "default": "Egiaztatu"\n    },\n    {\n      "label": "\\"Bidali\\" botoiarentzako botoia",\n      "default": "Submit"\n    },\n    {\n      "label": "\\"Saiatu berriro\\" botoiaren testua",\n      "default": "Saiatu berriro"\n    },\n    {\n      "label": "\\"Erakutsi emaitza\\" botoiaren testua",\n      "default": "Erakutsi erantzuna"\n    },\n    {\n      "label": "Jaregiteko zona numeratuaren etiketa",\n      "default": "Jaregiteko zona @index.",\n      "description": "Erabilgarritasunerako etiketa, non testu irakurgailuak irakurriko du jaregin zonen aurkibidea. Erabiltzen den aldagaia: @index"\n    },\n    {\n      "label": "Hutsik dagoen jJaregin zonaren etiketa",\n      "default": "@index jaregin zona hutsik dago.",\n      "description": "Erabilgarritasunerako etiketa, non testu irakurgailuak irakurriko du jaregin zona hutsik dagoela"\n    },\n    {\n      "label": "Jaregin zona dauka etiketa",\n      "default": "@index jaregin zonak @draggable arrastagarria dauka.",\n      "description": "Erabilgarritasunerako etiketa, non testu irakurgailuak irakurriko du jaregin zonak arrastagarri bat daukala"\n    },\n    {\n      "label": "Elementu arrastagarrien etiketa",\n      "default": "@count etik @index garren arrastagarria.",\n      "description": "Erabilgarritasunerako etiketa, non testu irakurgailuak irakurriko du hori elementu arrastagarri bat dela. Erabiltzen dituen aldagaiak: @index, @count"\n    },\n    {\n      "label": "Erakutsi argibidea botoiaren etiketa",\n      "default": "Erakutsi argibidea",\n      "description": "Erabilgarritasunerako etiketa, non testu irakurgailuak irakurtzen du testua laguntza irakurri aurretik"\n    },\n    {\n      "label": "Erantzun zuzenetarako irakurgailuaren testua",\n      "default": "Zuzena!"\n    },\n    {\n      "label": "Erantzun okerretarako irakurgailuaren testua",\n      "default": "Erantzun okerra!"\n    },\n    {\n      "label": "Erabiltzaileak jaregiteko elementua berrezartzeko egiaztapena",\n      "default": "Berrezarri jaregiteko elementua"\n    },\n    {\n      "label": "Erabiltzaileak jaregiteko elementua berrezartzeko egiaztapenaren deskripzioa",\n      "default": "Ziur zaude jaregin zona hau berrezarri nahi duzula?"\n    },\n    {\n      "label": "Erabilgarritasunerako etiketa, non testu irakurgailuak adierazten du arrastea hasi dela",\n      "default": "Arrastagarria helduta."\n    },\n    {\n      "label": "Erabilgarritasunerako etiketa, non testu irakurgailuak adierazten du arrastea bertan behera geratu dela",\n      "default": "Arrastea bertan behera geratu da."\n    },\n    {\n      "label": "Erabilgarritasunerako etiketa, non testu irakurgailuak adierazten du testua erantzun zuzena dela",\n      "default": "Erantzun zuzena:"\n    },\n    {\n      "label": "Erantzun zuzen eta okerren feedbacka duen panelaren goiburua",\n      "default": "Feedbacka"\n    },\n    {\n      "label": "Portaeraren ezarpenak.",\n      "description": "Aukera hauek lanaren portaera kontrolatzea ahalbidetzen dizute.",\n      "fields": [\n        {\n          "label": "Aktibatu \\"Saiatu berriro\\""\n        },\n        {\n          "label": "Aktibatu \\"Erakutsi erantzuna\\" botoia"\n        },\n        {\n          "label": "Aktibatu \\"Egiaztatu\\" botoia"\n        },\n        {\n          "label": "Berehalako feedbacka"\n        }\n      ]\n    },\n    {\n      "label": "Puntuazio barraren testu adierazpena irakurgailua erabiltzen dutenentzat",\n      "default": ":total puntutik :num puntu lortu duzu"\n    },\n    {\n      "label": "\\"Egiaztatu\\" botoiaren laguntza-teknologientzako etiketa",\n      "default": "Egiaztatu erantzunak. Erantzunak zuzen, oker edo erantzun gabe gisa markatuko dira."\n    },\n    {\n      "label": "\\"Erakutsi erantzun zuzena\\" botoiaren laguntza-teknologientzako etiketa",\n      "default": "Erakutsi erantzun zuzena. Zereginaren erantzun zuzena markatuko da."\n    },\n    {\n      "label": "\\"Berriz saiatu\\" botoiaren laguntza-teknologientzako etiketa",\n      "default": "Zeregina berriz egiten saiatu. Berrabiarazi erantzun guztiak eta hasi zeregina berriz."\n    }\n  ]\n}\n'),
(19, 'fa', '{\n  "semantics": [\n    {\n      "label": "رسانه",\n      "fields": [\n        {\n          "label": "نوع",\n          "description": "رسانه اختیاری برای نمایش در بالای سؤال."\n        },\n        {\n          "label": "غیرفعال‌سازی بزرگنمایی تصویر"\n        }\n      ]\n    },\n    {\n      "label": "توصیف تکلیف",\n      "description": "توضیح دهید کاربر چگونه باید تکلیف را انجام دهد.",\n      "default": "کلمات را به داخل باکس‌های صحیح بکشید"\n    },\n    {\n      "label": "متن",\n      "placeholder": "*اسلو* پایتخت نروژ است، *استکهلم* پایتخت سوئد است و *کپنهاگ* پایتخت دانمارک است. همه این شهرها در شبه جزیره *اسکاندیناوی:قسمت شمالی اروپا* واقع شده‌اند.",\n      "important": {\n        "description": "<ul><li>کلمات قابل کشیده شدن با یک ستاره (*) در جلو یا پشت کلمه/عبارت صحیح افزوده می‌شوند.</li><li>شما می‌توانید با قرار دادن یک دونقطه (:) جلوی راهنما، یک راهنمای متنی اضافه کنید. </li><li>برای هر جای خالی فقط یک کلمه صحیح وجود دارد. </li><li>شما می‌توانید برای وقتی که تکلیف کامل شد بازخورد اضافه کنید تا نمایش داده شود. برای بازخورد صحیح از ''\\\\+'' و برای بازخورد غلط از ''\\\\-'' استفاده کنید.</li></ul>",\n        "example": "محتوای H5P را می‌توان با استفاده از یک *مرورگر:کروم چه نوع برنامه‌ای است؟* ویرایش کرد. <br />محتوای H5P *تعاملی\\\\+صحیح! \\\\-غلط، دوباره تلاش کنید!* است"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "بازخورد کلی",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "پیش‌فرض"\n            }\n          ],\n          "label": "تعریف بازخورد سفارشی برای هر بازه نمره",\n          "description": "برای افزودن هر تعداد بازه که می‌خواهید، رو دکمه \\"افزودن بازه\\" کلیک کنید. مثال: ۰-۲۰٪ نمره بد، ۲۱-۹۱٪ نمره متوسط، ۹۱-۱۰۰٪ نمره عالی!",\n          "entity": "بازه",\n          "field": {\n            "fields": [\n              {\n                "label": "بازه نمره"\n              },\n              {},\n              {\n                "label": "بازخورد بازه نمره تعریف شده",\n                "placeholder": "بازخورد را پر کنید"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "متن برای دکمه بررسی",\n      "default": "بررسی"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "متن برای دکمه تلاش مجدد",\n      "default": "تلاش مجدد"\n    },\n    {\n      "label": "متن برای دکمه نمایش پاسخ صحیح",\n      "default": "نمایش پاسخ صحیح"\n    },\n    {\n      "label": "برچسب شماره‌دار کادر بارگیری",\n      "default": "کادر بارگیری @index.",\n      "description": "برچسب مورد استفاده برای دسترس‌پذیری، که به واسطه آن مبدل متن به گفتار شاخص کادر بارگیری را اعلام خواهد کرد. متغیر در دسترس: @index"\n    },\n    {\n      "label": "برچسب خالی بودن کادر بارگیری",\n      "default": "کادر بارگیری @index خالی است.",\n      "description": "برچسب مورد استفاده برای دسترس‌پذیری، که با خواندن آن مبدل متن به گفتار خالی بودن کادر بارگیری را اعلام خواهد کرد"\n    },\n    {\n      "label": "برچسب شمول کادر بارگیری",\n      "default": "کادر بارگیری @index شیء قابل کشیده شدن @draggable را شامل می‌شود.",\n      "description": "برچسب مورد استفاده برای دسترس‌پذیری، که با خواندن آن مبدل متن به گفتار اعلام خواهد کرد که کادر بارگیری شامل یک شیء قابل کشیده شدن است"\n    },\n    {\n      "label": "برچسب مؤلفه‌های شیء قابل کشیده شدن",\n      "default": "@index از کل @count شیء قابل کشیده شدن.",\n      "description": "برچسب مورد استفاده برای دسترس‌پذیری، که با خواندن آن مبدل متن به گفتار اعلام خواهد کرد که این یک مؤلفه قابل کشیده شدن است. متغیر در دسترس: @index، @count"\n    },\n    {\n      "label": "برچسب دکمه نمایش راهنمایی",\n      "default": "نمایش راهنمایی",\n      "description": "برچسب مورد استفاده برای دسترس‌پذیری، که مبدل متن به گفتار آن را قبل از خواندن راهنمایی می‌خواند"\n    },\n    {\n      "label": "متن مبدل متن به گفتار برای پاسخ صحیح",\n      "default": "صحیح!"\n    },\n    {\n      "label": "متن مبدل متن به گفتار برای پاسخ غلط",\n      "default": "غلط!"\n    },\n    {\n      "label": "عنوان دیالوگ تأیید اینکه کاربر می‌خواهد یک شیء قابل کشیده شدن را بازنشانی کند",\n      "default": "بازنشانی کشیدن"\n    },\n    {\n      "label": "توصیف دیالوگ تأیید اینکه کاربر می‌خواهد یک شیء قابل کشیده شدن را بازنشانی کند",\n      "default": "آیا مطمئن هستید که می‌خواهید این کادر بارگیری را بازنشانی کنید؟"\n    },\n    {\n      "label": "برچسب مورد استفاده برای دسترس‌پذیری، که با خواندن آن مبدل متن به گفتار اعلام می‌کند که کشیدن آغاز شده است",\n      "default": "شیء قابل کشیده شدن برداشته شد."\n    },\n    {\n      "label": "برچسب مورد استفاده برای دسترس‌پذیری، که با خواندن آن مبدل متن به گفتار اعلام می‌کند که کشیدن لغو شد",\n      "default": "کشیدن لغو شد."\n    },\n    {\n      "label": "برچسب مورد استفاده برای دسترس‌پذیری، که با خواندن آن مبدل متن به گفتار اعلام می‌کند که یک متن پاسخ صحیح است",\n      "default": "پاسخ صحیح:"\n    },\n    {\n      "label": "سرصفحه برای پنل شامل بازخورد برای پاسخ‌های صحیح/غلط",\n      "default": "بازخورد"\n    },\n    {\n      "label": "تنظیمات عملکرد.",\n      "description": "این گزینه‌ها به شما اجازه خواهد داد که چگونگی عملکرد تکلیف را کنترل کنید.",\n      "fields": [\n        {\n          "label": "فعال‌سازی تلاش مجدد"\n        },\n        {\n          "label": "فعال‌سازی دکمه نمایش پاسخ صحیح"\n        },\n        {\n          "label": "فعال‌سازی دکمه بررسی"\n        },\n        {\n          "label": "بازخورد فوری"\n        }\n      ]\n    },\n    {\n      "label": "بازنمایی متنی نوار نمره برای آن‌هایی که از مبدل متن به گفتار استفاده می‌کنند",\n      "default": "شما از کل :total امتیاز، :num امتیاز دریافت کردید"\n    },\n    {\n      "label": "برچسب فناوری کمکی برای دکمه بررسی",\n      "default": "بررسی پاسخ‌ها. پاسخ‌ها صحیح، غلط یا بی‌پاسخ علامت‌گذاری خواهند شد."\n    },\n    {\n      "label": "برچسب فناوری کمکی برای دکمه نمایش پاسخ صحیح",\n      "default": "نمایش پاسخ صحیح. تکلیف با پاسخ صحیح آن علامت‌گذاری می‌شود."\n    },\n    {\n      "label": "برچسب فناوری کمکی برای دکمه تلاش مجدد",\n      "default": "تلاش مجدد. بازنشانی همه پاسخ‌ها و شروع مجدد تکلیف."\n    }\n  ]\n}\n'),
(19, 'fi', '{\n  "semantics": [\n    {\n      "label": "Media",\n      "fields": [\n        {\n          "label": "Tyyppi",\n          "description": "Valinnainen kuva tai video, joka näkyy kysymyksen yläpuolella."\n        },\n        {\n          "label": "Älä salli kuvan suurentamista"\n        }\n      ]\n    },\n    {\n      "label": "Tehtävän kuvaus",\n      "description": "Kuvaile, mitä käyttäjän pitää tehdä.",\n      "default": "Raahaa sanat oikeisiin laatikoihin."\n    },\n    {\n      "label": "Teksti",\n      "placeholder": "*Helsinki* on Suomessa, *Tukholma* on Ruotsissa. Kumpikin on maansa *pääkaupunki:hallinnollinen keskus*.",\n      "important": {\n        "description": "<ul><li>Merkitse raahattavat sanat tähtien (*) väliin, esimerkiksi *Helsinki*.</li><li>Jos haluat lisätä vihjeen, kirjoita raahattavan sanan perään kaksoispiste ja vihje, esimerkiksi *pääkaupunki:hallinnollinen keskus*.</li><li>Jokaista tyhjää kohtaa vastaa yksi oikea sana.</li><li>Voit lisätä palautteen näytettäväksi kun tehtävä on suoritettu. Käytä ''\\\\+'' oikein ja ''\\\\-'' väärin palautteelle.</li></ul>",\n        "example": "H5P content may be edited using a *browser:What type of program is Chrome?*. <br /> H5P content is *interactive\\\\+Correct! \\\\-Incorrect, try again!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Yleispalaute",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Oletus"\n            }\n          ],\n          "label": "Määritä palaute pistealueiden mukaan.",\n          "description": "Klikkaa \\"Lisää alue\\" painiketta lisätäksesi niin monta pistealuetta kuin tarvit. Esimerkiksi: 0-20% Huono tulos, 21-91% Kelpo tulos, 91-100% Mahtava tulos!",\n          "entity": "alue",\n          "field": {\n            "fields": [\n              {\n                "label": "Pistealue"\n              },\n              {},\n              {\n                "label": "Palaute määritellylle pistealueelle",\n                "placeholder": "Kirjoita palaute"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Painikkeen \\"Tarkista\\" nimi",\n      "default": "Tarkista"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Painikkeen \\"Yritä uudelleen\\" nimi",\n      "default": "Yritä uudelleen"\n    },\n    {\n      "label": "Painikkeen \\"Katso vastaus\\" nimi",\n      "default": "Katso vastaus"\n    },\n    {\n      "label": "Pudotuskohteen numerointi",\n      "default": "Pudotuskohde @index.",\n      "description": "Esteettömyystoiminto. Ruudunlukija lukee pudotuskohteen järjestysnumeron. Käytettävissä muuttuja: @index"\n    },\n    {\n      "label": "Tyhjän pudotuskohteen numerointi",\n      "default": "Pudotuskohde @index on tyhjä.",\n      "description": "Esteettömyystoiminto. Ruudunlukija lukee tyhjän pudotuskohteen järjestysnumeron."\n    },\n    {\n      "label": "Pudotuskohde sisältää raahattavan",\n      "default": "Pudotuskohde @index sisältää raahattavan @draggable.",\n      "description": "Esteettömyystoiminto. Ruudunlukija lukee, että pudotuskohteessa on jo jokin raahattava."\n    },\n    {\n      "label": "Raahattavan elementin selite",\n      "default": "@index/@count raahattavista.",\n      "description": "Esteettömyystoiminto. Ruuudunlukija lukee, että tämä on raahattava elementti. Käytettävissä muuttujat: @index, @count"\n    },\n    {\n      "label": "Vihjepainikkeen teksti",\n      "default": "Näytä vihje",\n      "description": "Esteettömyystoiminto. Ruudunlukija lukee tämän ennen vihjeen lukemista."\n    },\n    {\n      "label": "Ruudunlukijan teksti oikealle vastaukselle",\n      "default": "Oikein!"\n    },\n    {\n      "label": "Ruudunlukijan teksti väärälle vastaukselle",\n      "default": "Väärin!"\n    },\n    {\n      "label": "Varmistusdialogi kun käyttäjä haluaa palauttaa pudotuksen",\n      "default": "Palauta pudotus"\n    },\n    {\n      "label": "Selite varmistusdialogille kun käyttäjä haluaa palauttaa pudotuksen",\n      "default": "Haluatko varmasti palauttaa pudotuskohteen?"\n    },\n    {\n      "label": "Ruudunlukijan teksti raahauksen aloittamiselle",\n      "default": "Raahattavasta on otettu kiinni."\n    },\n    {\n      "label": "Ruudunlukijan teksti raahauksen keskeyttämiselle",\n      "default": "Raahaus keskeytetty."\n    },\n    {\n      "label": "Ruudunlukijan teksti ilmaisemaan mikä oli oikea vastaus",\n      "default": "Oikea vastaus:"\n    },\n    {\n      "label": "Oikeiden ja väärien vastauksien palautteen sisältävän paneelin otsikko",\n      "default": "Palaute"\n    },\n    {\n      "label": "Yleisasetukset",\n      "description": "Näillä valinnoilla voit ohjailla tehtävän toimintoja.",\n      "fields": [\n        {\n          "label": "Salli painike \\"Yritä uudelleen\\""\n        },\n        {\n          "label": "Salli painike \\"Katso vastaus\\""\n        },\n        {\n          "label": "Enable \\"Check\\" button"\n        },\n        {\n          "label": "Pikapalaute"\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'fr', '{\n  "semantics": [\n    {\n      "label": "Média",\n      "fields": [\n        {\n          "label": "Type",\n          "description": "Média à afficher au-dessus de la question (facultatif)."\n        },\n        {\n          "label": "Désactiver le zoom sur image pour l''image de la question"\n        }\n      ]\n    },\n    {\n      "label": "Description de la tâche",\n      "description": "La consigne indique ce que l''utilisateur doit faire.",\n      "default": "Déplacez les textes dans les emplacements qui leur correspondent."\n    },\n    {\n      "label": "Question",\n      "placeholder": "Paris est la capitale de la *France*",\n      "important": {\n        "description": "<ul><li>Les textes déplaçables s''ajoutent avec un astérisque (*) devant et derrière chaque texte.</li><li>Vous pouvez ajouter un indice en plaçant 2 points (:) avant cet indice.</li><li>Il ne peut y avoir qu''un seul texte correct pour chaque espace à remplir.</li><li>Vous pouvez ajouter un feedback qui apparaîtra une fois l''exercice terminé. Utilisez ''\\\\+'' pour créer le feedback en cas de réponse correcte et ''\\\\-'' pour le feedback en cas de mauvaise réponse.</li></ul>",\n        "example": "Les contenus H5P peuvent être édités en utilisant un *navigateur:Quel type de programme utilisez vous pour consulter des sites Internet ?*. <br /> Un contenu H5P est *interactif\\\\+Correct ! \\\\-Incorrect, Recommencez !*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Feedback général",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Par défaut"\n            }\n          ],\n          "label": "Définissez le feedback pour chaque intervalle de scores",\n          "description": "Cliquez sur le bouton \\"Ajouter Intervalle\\" pour ajouter autant d''intervalles que vous le souhaitez. Exemple: 0-20% Mauvais score, 21-91% Score moyen, 91-100% Score excellent !",\n          "entity": "intervalle",\n          "field": {\n            "fields": [\n              {\n                "label": "Intervalle de score"\n              },\n              {},\n              {\n                "label": "Feedback pour un intervalle de score défini",\n                "placeholder": "Remplir le feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texte du bouton \\"Vérifier\\"",\n      "default": "Vérifier"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Vérifier"\n    },\n    {\n      "label": "Texte du bouton \\"Recommencer\\"",\n      "default": "Recommencer"\n    },\n    {\n      "label": "Texte pour le bouton \\"Voir la correction\\"",\n      "default": "Voir la correction"\n    },\n    {\n      "label": "Etiquette de la zone de dépôt numérotée",\n      "default": "Zone de dépôt @index.",\n      "description": "Etiquette utilisée pour l''accessibilité quand la synthèse vocale annonce le numéro de la zone de dépôt. Variable disponible : @index"\n    },\n    {\n      "label": "Etiquette zone de dépôt vide",\n      "default": "La zone de dépôt @index est vide.",\n      "description": "Etiquette utilisée pour l''accessibilité quand la syntèse vocale annonce que la zone de dépôt est vide"\n    },\n    {\n      "label": "Etiquette pour la zone de dépôt contient",\n      "default": "La zone de dépôt @index contient un élément déplaçable @draggable.",\n      "description": "Etiquette utilisée pour l''accessibilité quand la syntèse vocale annonce que la zone de dépôt contient un élément déplaçable"\n    },\n    {\n      "label": "Etiquette pour les éléments à déplacer",\n      "default": "@index sur @count éléments déplaçables.",\n      "description": "Etiquette utilisée pour l''accessibilité quand la syntèse vocale annonce que c''est un élément déplaçable. Variables disponibles : @index, @count"\n    },\n    {\n      "label": "Etiquette pour le bouton d''indice",\n      "default": "Montrer l''indice",\n      "description": "Etiquette utilisée pour l''accessibilité quand la syntèse vocale annonce l''indice"\n    },\n    {\n      "label": "Texte exprimé par la synthèse vocale en cas de réponse correcte",\n      "default": "Correct !"\n    },\n    {\n      "label": "Texte exprimé par la synthèse vocale en cas de réponse incorrecte",\n      "default": "Incorrect !"\n    },\n    {\n      "label": "Intitulé de dialogue pour confirmer que l''utilisateur souhaite reparamétrer l''élément déplaçable",\n      "default": "Reparamétrer le déplacement"\n    },\n    {\n      "label": "Description du dialogue de confirmation pour reparamétrer un élément déplaçable",\n      "default": "Etes-vous certain de vouloir reparamétrer cet élément déplaçable ?"\n    },\n    {\n      "label": "Etiquette utilisée pour l''accessibilité quand la synthèse vocale annonce que le déplacement d''un élément est initié",\n      "default": "L''élément déplaçable est saisi."\n    },\n    {\n      "label": "Etiquette utilisée pour l''accessibilité quand la synthèse vocale annonce que le déplacement de l''élément est annulé",\n      "default": "Annuler le déplacement."\n    },\n    {\n      "label": "Etiquette utilisée pour l''accessibilité quand la bonne réponse est annoncée par la synthèse vocale",\n      "default": "Réponse correcte :"\n    },\n    {\n      "label": "Intitulé de l''espace contenant des feedbacks pour des réponses correctes/incorrectes",\n      "default": "Commentaire de retour"\n    },\n    {\n      "label": "Options générales.",\n      "description": "Ces options vous permettent de contrôler le déroulement de vos activités.",\n      "fields": [\n        {\n          "label": "Activer le bouton \\"Recommencer\\""\n        },\n        {\n          "label": "Activer le bouton \\"Voir la solution\\""\n        },\n        {\n          "label": "Activer le bouton \\"Vérifier\\""\n        },\n        {\n          "label": "Correction instantanée"\n        }\n      ]\n    },\n    {\n      "label": "Représentation textuelle du panneau du score pour les utilisateurs des outils de la vocalisation (comme ReadSpeaker)",\n      "default": "Vous avez obtenu :num sur un total de :points"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Vignette de technologie fonctionnelle pour la touche « Montrer la solution »",\n      "default": "Afficher la solution. La tâche sera notée avec sa solution correcte."\n    },\n    {\n      "label": "Vignette de technologie fonctionnelle pour la touche « Réessayer »",\n      "default": "Réessayer la tâche. Réinitialiser toutes les réponses et recommencer la tâche."\n    }\n  ]\n}\n'),
(19, 'ga', '{\n  "semantics": [\n    {\n      "label": "Media",\n      "fields": [\n        {\n          "label": "Type",\n          "description": "Optional media to display above the question."\n        },\n        {\n          "label": "Disable image zooming"\n        }\n      ]\n    },\n    {\n      "label": "Task description",\n      "description": "Describe how the user should solve the task.",\n      "default": "Drag the words into the correct boxes"\n    },\n    {\n      "label": "Text",\n      "placeholder": "*Oslo* is the capital of Norway, *Stockholm* is the capital of Sweden and *Copenhagen* is the capital of Denmark. All cities are located in the *Scandinavian:Northern Part of Europe* peninsula.",\n      "important": {\n        "description": "<ul><li>Droppable words are added with an asterisk (*) in front and behind the correct word/phrase.</li><li>You may add a textual tip, using a colon (:) in front of the tip.</li><li>For every empty spot there is only one correct word.</li><li>You may add feedback to be displayed when a task is completed. Use ''\\\\+'' for correct and ''\\\\-'' for incorrect feedback.</li></ul>",\n        "example": "H5P content may be edited using a *browser:What type of program is Chrome?*. <br /> H5P content is *interactive\\\\+Correct! \\\\-Incorrect, try again!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Default"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text for \\"Seiceáil\\" button",\n      "default": "Seiceáil"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Text for \\"Triail arís\\" button",\n      "default": "Triail arís"\n    },\n    {\n      "label": "Text for \\"Taispeáin an freagra\\" button",\n      "default": "Taispeáin an freagra"\n    },\n    {\n      "label": "Numbered Drop zone label",\n      "default": "Drop Zone @index.",\n      "description": "Label used for accessibility, where the Read speaker will read the index of a drop zone. Variable available: @index"\n    },\n    {\n      "label": "Empty Drop Zone label",\n      "default": "Drop Zone @index is empty.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone is empty"\n    },\n    {\n      "label": "Contains Drop Zone label",\n      "default": "Drop Zone @index contains draggable @draggable.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone contains a draggable"\n    },\n    {\n      "label": "Draggable elements label",\n      "default": "@index as @count draggables.",\n      "description": "Label used for accessibility, where the Read speaker reads that this is a draggable element. Variable available: @index, @count"\n    },\n    {\n      "label": "Label for show tip button",\n      "default": "Taispeáin nod",\n      "description": "Label used for accessibility, where the Read speaker reads it before the tip is read out"\n    },\n    {\n      "label": "Readspeaker text for correct answer",\n      "default": "Ceart!"\n    },\n    {\n      "label": "Readspeaker text for incorrect answer",\n      "default": "Mícheart!"\n    },\n    {\n      "label": "Confirmation dialog title that user wants to reset a droppable",\n      "default": "Athshocraigh é"\n    },\n    {\n      "label": "Confirmation dialog description that user wants to reset a droppable",\n      "default": "Ar mhaith leat an rud seo a athshocrú?"\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is initiated",\n      "default": "Draggable is grabbed."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is canceled",\n      "default": "Cancelled dragging."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that a text is the correct answer",\n      "default": "Freagra ceart:"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "Aiseolas"\n    },\n    {\n      "label": "Behavioural settings.",\n      "description": "These options will let you control how the task behaves.",\n      "fields": [\n        {\n          "label": "Enable \\"Triail arís\\""\n        },\n        {\n          "label": "Enable \\"Taispeáin an freagra\\" button"\n        },\n        {\n          "label": "Enable \\"Seiceáil\\" button"\n        },\n        {\n          "label": "Instant feedback"\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "Scóráil tú :num as :total phointe"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'gl', '{\n  "semantics": [\n    {\n      "label": "Medios",\n      "fields": [\n        {\n          "label": "Tipo",\n          "description": "Medios adicionais amosados enriba da pregunta."\n        },\n        {\n          "label": "Desactivar zoom da imaxe"\n        }\n      ]\n    },\n    {\n      "label": "Descrición da tarefa",\n      "description": "Describe como debe resolver a tarefa o usuario.",\n      "default": "Arrastra as palabas ás caixas correctas"\n    },\n    {\n      "label": "Texto",\n      "placeholder": "*Oslo* é a capital de Noruega, *Estocolmo* é a capital de Suecia e *Copenhage* é a capital de Dinamarca. Todas as cidades están situadas na península *Escandinava:Parte norte de Europa*.",\n      "important": {\n        "description": "<ul><li>As palabras que se poden arrastrar indícanse cun asterisco (*) diante e detrás da palabra ou frase correcta.</li><li>Pódese engadir unha axuda contextual usando dous puntos (:) diante da axuda.</li><li>Por cada oco baleiro só hai unha palabra correcta.</li><li>Pódese engadir retroalimentación para que se amose cando a tarefa estea completa. Usa ''\\\\+'' para engadir retroalimentación para respostas correctas e ''\\\\-'' para as incorrectas.</li></ul>",\n        "example": "O contido H5P pódese editar cun *navegador:Que clase de programa é Chrome?*. <br /> O contido H5P é *interactivo\\\\+Correcto! \\\\-Incorrecto, proba outra vez!*"\n      }\n    },\n    {\n      "label": "Distractores",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Introduza solucións adicionais incorrectas como distractores. Use o mesmo esquema de asterisco (*) que para o texto."\n    },\n    {\n      "label": "Retroalimentación xeral",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Por defecto"\n            }\n          ],\n          "label": "Define a retroalimentación por defecto para calquera rango de puntuación",\n          "description": "Preme o botón \\"Engadir rango\\" para engadir tantos rangos como precises. Exemplo: 0-20% Mala Puntuación, 21-91% Puntuación Media, 91-100% Puntuación Xenial!",\n          "entity": "rango",\n          "field": {\n            "fields": [\n              {\n                "label": "Rango de Puntuación"\n              },\n              {},\n              {\n                "label": "Retroalimentación para rango de puntuación definido",\n                "placeholder": "Escribe a retroalimentación"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texto para o botón \\"Comprobar\\"",\n      "default": "Comprobar"\n    },\n    {\n      "label": "Texto para o botón \\"Enviar\\"",\n      "default": "Submit"\n    },\n    {\n      "label": "Texto para o botón \\"Tentar de novo\\"",\n      "default": "Tentar de novo"\n    },\n    {\n      "label": "Texto para o botón \\"Amosar Solución\\"",\n      "default": "Amosar Solución"\n    },\n    {\n      "label": "Etiqueta para a zona de solta numerada",\n      "default": "Zona de solta @index.",\n      "description": "Etiqueta usada por accesibilidade, para que o lector de pantalla lea o índice dunha zona de solta. Variable dispoñible: @index"\n    },\n    {\n      "label": "Etiqueta de zona de solta baleira",\n      "default": "O @index de zonas de solta está baleiro.",\n      "description": "Etiqueta usada por accesibilidade. O lector de pantalla dirá que a zona de solta está baleira"\n    },\n    {\n      "label": "Etiqueta Contén Zona de Solta",\n      "default": "O @index de zonas de solta contén @draggable elementos arrastrables.",\n      "description": "Etiqueta usada por accesibilidade. O lector de pantalla dirá que a zona de solta contén un elemento arrastrable"\n    },\n    {\n      "label": "Etiqueta de elementos arrastrables",\n      "default": "@index de @count elementos arrastrables.",\n      "description": "Etiqueta usada por accesibilidade. O lector dirá que este é un elemento arrastrable. Variables dispoñibles: @index, @count"\n    },\n    {\n      "label": "Etiqueta para o botón amosar pista",\n      "default": "Amosar pista",\n      "description": "Etiqueta usada por accesibilidade. O lector de pantalla lerá esta etiqueta antes de ler a pista"\n    },\n    {\n      "label": "Texto do lector de pantalla para resposta correcta",\n      "default": "Correcto!"\n    },\n    {\n      "label": "Texto do lector de pantalla para resposta incorrecta",\n      "default": "Incorrecto!"\n    },\n    {\n      "label": "Título do cadro de diálogo que aparece cando o usuario quere cambiar un elemento arrastrable",\n      "default": "Cambiar solta"\n    },\n    {\n      "label": "Descrición do cadro de diálogo que aparece cando o usuario quere cambiar un elemento arrastrable",\n      "default": "Seguro que queres cambiar esta zona de solta?"\n    },\n    {\n      "label": "Etiqueta usada por accesibilidade. O lector de pantalla indicará que se iniciou o arrastre",\n      "default": "Colleuse o elemento arrastrable."\n    },\n    {\n      "label": "Etiqueta usada por accesibilidade. O lector de pantalla dirá que se cancelou o arrastre",\n      "default": "Arrastre cancelado."\n    },\n    {\n      "label": "Etiqueta usada por accesibilidade. O lector de pantalla dirá que un texto é a respota correcta",\n      "default": "Resposta correcta:"\n    },\n    {\n      "label": "Cabeceira do panel que contén a retroalimentación para respostas correctas/incorrectas",\n      "default": "Retroalimentación"\n    },\n    {\n      "label": "Configuración de comportamento.",\n      "description": "Estas opcións permiten controlar o comportamento da tarefa.",\n      "fields": [\n        {\n          "label": "Activar \\"Reintentar\\""\n        },\n        {\n          "label": "Activar botón \\"Amosar solución\\""\n        },\n        {\n          "label": "Activar botón \\"Comprobar\\""\n        },\n        {\n          "label": "Retroalimentación instantánea"\n        }\n      ]\n    },\n    {\n      "label": "Representación textual da barra de puntuación cando se usa un lector de pantalla",\n      "default": "Conseguiches :num puntos dun total de :total"\n    },\n    {\n      "label": "Etiqueta de tecnoloxía asistencial para o botón \\"Comprobar\\"",\n      "default": "Comproba as respostas. As respostas marcaranse como correctas, incorrectas ou non respondidas."\n    },\n    {\n      "label": "Etiqueta de tecnoloxía asistencial para o botón \\"Amosar Solución\\"",\n      "default": "Amosa a solución. A tarefa puntuarase coa súa solución correcta."\n    },\n    {\n      "label": "Etiqueta de tecnoloxía asistencial para o botón \\"Reintentar\\"",\n      "default": "Reintenta a tarefa. Borra todas as respostas e volver a empezar a tarefa de novo."\n    }\n  ]\n}\n'),
(19, 'he', '{\n  "semantics": [\n    {\n      "label": "מדיה",\n      "fields": [\n        {\n          "label": "סוג",\n          "description": "ניתן להוסיף תמונה אשר תוצג מעל השאלה."\n        },\n        {\n          "label": "ביטול האפשרות להגדלת תמונה"\n        }\n      ]\n    },\n    {\n      "label": "תיאור משימה",\n      "description": "תארו כיצד על המשתמש לפתור את המשימה.",\n      "default": "גררו את המילים לתיבות המתאימות"\n    },\n    {\n      "label": "תוכן",\n      "placeholder": "*אוסלו* היא בירת נורווגיה, *שטוקהולם* היא בירת שוודיה ו*קופנהגן* היא בירת דנמרק. כל הערים ממוקמות בחצי האי *הסקנדינבי: בחלק הצפוני של אירופה*.",\n      "important": {\n        "description": "<ul><li>מילים שניתנות לשחרור מתווספות עם כוכבית (*) לפני המילה/הביטוי הנכון ומאחוריה.</li><li>ניתן להוסיף טיפ טקסטואלי, באמצעות נקודתיים (:) לפני הקצה .</li><li>עבור כל נקודה ריקה יש רק מילה אחת נכונה.</li><li>תוכל להוסיף משוב שיוצג לאחר השלמת משימה. השתמש ב-''\\\\+'' למשוב נכון וב-''\\\\-'' למשוב שגוי.</li></ul>",\n        "example": "ניתן לערוך תוכן H5P באמצעות *דפדפן:איזה סוג תוכנית הוא Chrome?*. <br /> תוכן H5P הוא *אינטראקטיבי\\\\+נכון! \\\\-שגוי. נסה שוב!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "משוב כללי",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "ברירת מחדל"\n            }\n          ],\n          "label": "הגדירו משוב מותאם אישית לכל טווח ציונים",\n          "description": "לחצו על כפתור \\"הוסף טווח\\" כדי להוסיף כמה טווחים לפי הצורך. דוגמה: 0-20% ציון רע, 21-91% ציון ממוצע, 91-100% ציון מעולה!",\n          "entity": "טווח",\n          "field": {\n            "fields": [\n              {\n                "label": "טווח ציונים"\n              },\n              {},\n              {\n                "label": "משוב לטווח ציונים מוגדר",\n                "placeholder": "מלאו את המשוב"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "טקסט לכפתור \\"בדוק\\"",\n      "default": "בדוק"\n    },\n    {\n      "label": "תוכן לכפתור \\"הגשה\\"",\n      "default": "הגשה"\n    },\n    {\n      "label": "טקסט לכפתור \\"נסה שוב\\"",\n      "default": "נסה שוב"\n    },\n    {\n      "label": "מלל לכפתור \\"הצג פתרון\\"",\n      "default": "הצג פתרון"\n    },\n    {\n      "label": "תווית ממוספרת של אזור יעד",\n      "default": "@index אזור יעד.",\n      "description": "תווית משמשת עבור נגישות, היכן שקורא-המסך יקרא את האינדקס של אזור היעד. משתנה זמין: @index"\n    },\n    {\n      "label": "תווית אזור יעד ריקה",\n      "default": "@index אזור יעד ריק.",\n      "description": "תווית משמשת עבור נגישות, היכן שקורא-המסך יקרא שאזור היעד ריק"\n    },\n    {\n      "label": "מכיל תווית אזור יעד",\n      "default": "אזור יעד @index מכיל את אובייקט הגרירה @draggable.",\n      "description": "תווית משמשת עבור נגישות, היכן שקורא-המסך יקרא שאזור היעד מכיל אובייקט גרירה"\n    },\n    {\n      "label": "תווית רכיב גרירה",\n      "default": "@index של @count אובייקטי גרירה.",\n      "description": "תווית משמשת עבור נגישות, היכן שקורא-המסך יקרא שזה רכיב גרירה. משתנים זמינים: index, @count@"\n    },\n    {\n      "label": "תווית לכפתור הצגת רמז",\n      "default": "הצגת עצה",\n      "description": "תווית משמשת עבור נגישות, היכן שקורא-המסך יקרא אותה לפני קריאת הרמז"\n    },\n    {\n      "label": "טקסט קורא-מסך לתשובה נכונה",\n      "default": "נכון!"\n    },\n    {\n      "label": "טקסט קורא-מסך עבור תשובה לא נכונה",\n      "default": "לא נכון!"\n    },\n    {\n      "label": "כותרת תיבת הדו-שיח לאישור שהמשתמש רוצה לאפס קובץ שניתן לשחרר",\n      "default": "איפוס גרירה"\n    },\n    {\n      "label": "תיאור תיבת הדו-שיח לאישור שהמשתמש רוצה לאפס קובץ שניתן לשחרר",\n      "default": "האם אתה בטוח שברצונך לאפס את אזור הגרירה הזה?"\n    },\n    {\n      "label": "תווית משמשת עבור נגישות, היכן שקורא-המסך יציין שגרירה מתבצעת",\n      "default": "גרירה נתפסת."\n    },\n    {\n      "label": "תווית משמשת עבור נגישות, היכן שקורא-המסך מציין שהגרירה התבטלה",\n      "default": "התבטלה הגרירה."\n    },\n    {\n      "label": "תווית משמשת עבור נגישות, היכן שקורא-המסך יציין שהטקסט הוא התשובה הנכונה",\n      "default": "תשובה נכונה:"\n    },\n    {\n      "label": "כותרת עבור משבצת המכילה משוב עבור תשובות נכונות/לא נכונות",\n      "default": "משוב"\n    },\n    {\n      "label": "הגדרות התנהגות הרכיב.",\n      "description": "אפשרויות אלה יאפשרו לך לשלוט בהתנהגות המשימה.",\n      "fields": [\n        {\n          "label": "הפעלת \\"ניסיון חוזר\\""\n        },\n        {\n          "label": "אפשר כפתור \\"הצגת פתרון\\""\n        },\n        {\n          "label": "הצגת כפתור \\"בדיקה\\""\n        },\n        {\n          "label": "משוב מיידי"\n        }\n      ]\n    },\n    {\n      "label": "ייצוג מילולי של סרגל הניקוד לאלה שמשתמשים בקורא-מסך",\n      "default": "קיבלת :num מתוך :total נקודות"\n    },\n    {\n      "label": "תווית טכנולוגיה מסייעת עבור כפתור \\"בדיקה\\"",\n      "default": "בדקו את התשובות. המענים יסומנו כנכון, לא נכון, או ריק."\n    },\n    {\n      "label": "תווית טכנולוגיה מסייעת עבור כפתור \\"הצגת פתרון\\"",\n      "default": "הצגת הפתרון. המשימה תסומן עם התשובה הנכונה."\n    },\n    {\n      "label": "תווית טכנולוגיה מסייעת עבור כפתור \\"ניסיון חוזר\\"",\n      "default": "ניסיון חדש של המשימה. איפוס כל ניסיונות המענה והתחלה מחדש."\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(19, 'hu', '{\n  "semantics": [\n    {\n      "label": "Média",\n      "fields": [\n        {\n          "label": "Típus",\n          "description": "Lehetséges Média ami a kérdés felett jelenik meg."\n        },\n        {\n          "label": "Kép ráközelítés tiltása"\n        }\n      ]\n    },\n    {\n      "label": "Task description",\n      "description": "Describe how the user should solve the task.",\n      "default": "Drag the words into the correct boxes"\n    },\n    {\n      "label": "Text",\n      "placeholder": "*Oslo* is the capital of Norway, *Stockholm* is the capital of Sweden and *Copenhagen* is the capital of Denmark. All cities are located in the *Scandinavian:Northern Part of Europe* peninsula.",\n      "important": {\n        "description": "<ul><li>Droppable words are added with an asterisk (*) in front and behind the correct word/phrase.</li><li>You may add a textual tip, using a colon (:) in front of the tip.</li><li>For every empty spot there is only one correct word.</li><li>You may add feedback to be displayed when a task is completed. Use ''\\\\+'' for correct and ''\\\\-'' for incorrect feedback.</li></ul>",\n        "example": "H5P content may be edited using a *browser:What type of program is Chrome?*. <br /> H5P content is *interactive\\\\+Correct! \\\\-Incorrect, try again!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Default"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text for \\"Check\\" button",\n      "default": "Check"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Text for \\"Retry\\" button",\n      "default": "Retry"\n    },\n    {\n      "label": "Text for \\"Show Solution\\" button",\n      "default": "Show solution"\n    },\n    {\n      "label": "Numbered Drop zone label",\n      "default": "Drop Zone @index.",\n      "description": "Label used for accessibility, where the Read speaker will read the index of a drop zone. Variable available: @index"\n    },\n    {\n      "label": "Empty Drop Zone label",\n      "default": "Drop Zone @index is empty.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone is empty"\n    },\n    {\n      "label": "Contains Drop Zone label",\n      "default": "Drop Zone @index contains draggable @draggable.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone contains a draggable"\n    },\n    {\n      "label": "Draggable elements label",\n      "default": "@index of @count draggables.",\n      "description": "Label used for accessibility, where the Read speaker reads that this is a draggable element. Variable available: @index, @count"\n    },\n    {\n      "label": "Label for show tip button",\n      "default": "Show tip",\n      "description": "Label used for accessibility, where the Read speaker reads it before the tip is read out"\n    },\n    {\n      "label": "Readspeaker text for correct answer",\n      "default": "Correct!"\n    },\n    {\n      "label": "Readspeaker text for incorrect answer",\n      "default": "Incorrect!"\n    },\n    {\n      "label": "Confirmation dialog title that user wants to reset a droppable",\n      "default": "Reset drop"\n    },\n    {\n      "label": "Confirmation dialog description that user wants to reset a droppable",\n      "default": "Are you sure you want to reset this drop zone?"\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is initiated",\n      "default": "Draggable is grabbed."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is canceled",\n      "default": "Cancelled dragging."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that a text is the correct answer",\n      "default": "Correct answer:"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "Feedback"\n    },\n    {\n      "label": "Behavioural settings.",\n      "description": "These options will let you control how the task behaves.",\n      "fields": [\n        {\n          "label": "Enable \\"Retry\\""\n        },\n        {\n          "label": "Enable \\"Show Solution\\" button"\n        },\n        {\n          "label": "Enable \\"Check\\" button"\n        },\n        {\n          "label": "Instant feedback"\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'it', '{\n  "semantics": [\n    {\n      "label": "Media",\n      "fields": [\n        {\n          "label": "Tipo",\n          "description": "Media facoltativo da mostrare sopra la domanda"\n        },\n        {\n          "label": "Disabilita lo zoom dell''immagine"\n        }\n      ]\n    },\n    {\n      "label": "Descrizione del compito",\n      "description": "Descrivi come l''apprendente deve risolvere il compito",\n      "default": "Trascina le parole negli spazi giusti"\n    },\n    {\n      "label": "Testo",\n      "placeholder": "*Oslo* è la capitale della Norvegia, *Stoccolma* è la capitale della Svezia e *Copenaghen* è la capitale della Danimarca. Tutte queste città si trovano nella penisola della *Scandinavia:Parte a nord dell''Europa*",\n      "important": {\n        "description": "<ul><li>Per rendere una parola - o una frase - rilasciabile le si deve aggiungere un asterisco (*) all''inizio e uno alla fine.</li><li>Puoi aggiungere un suggerimento usando i due punti (:) prima del suggerimento stesso.</li><li>Per ogni spazio vuoto c''è un''unica parola corretta.</li><li>Puoi anche aggiungere un feedback da mostrare quando l''attività è completata; usa ''\\\\+'' per giusto e ''\\\\-'' per sbagliato</li></ul>",\n        "example": "I contenuti H5P possono essere modificati usando un *browser:Che tipo di software è Chrome?*.<br />Il contenuto H5P è *interattivo\\\\+Giusto! \\\\-Sbagliato. Riprova!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Feedback generale",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Predefinito"\n            }\n          ],\n          "label": "Definisci un feedback personalizzato per ogni intervallo di punteggio",\n          "description": "Clicca sul pulsante \\"Aggiungi intervallo\\" per aggiungere gli intervalli che ti servono. Per esempio: 0-20%, Punteggio scarso; 21-90%, Punteggio medio; 91-100% Punteggio ottimo!",\n          "entity": "intervallo",\n          "field": {\n            "fields": [\n              {\n                "label": "Intervallo di punteggio"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Testo per il pulsante \\"Verifica\\"",\n      "default": "Verifica"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Testo per il pulsante \\"Riprova\\"",\n      "default": "Riprova"\n    },\n    {\n      "label": "Testo per il pulsante \\"Mostra Soluzione\\"",\n      "default": "Mostra soluzione"\n    },\n    {\n      "label": "Etichetta per zona di rilascio numerata",\n      "default": "Zona di rilascio @index",\n      "description": "Etichetta usata per l''accessibilità, dove il lettore vocale legge l''indice di una zona di rilascio. Variabile disponibile: @index"\n    },\n    {\n      "label": "Etichetta per zona di rilascio vuota",\n      "default": "Zona di rilascio @index è vuota",\n      "description": "Etichetta usata per l''accessibilità, dove il lettore vocale legge che la zona di rilascio è vuota"\n    },\n    {\n      "label": "Contiene etichetta per zona di rilascio",\n      "default": "La zona di rilascio @index contiene @draggable trascinabile",\n      "description": "Etichetta usata per l''accessibilità, dove il lettore vocale legge che la zona di rilascio contiene un elemento trascinabile"\n    },\n    {\n      "label": "Etichetta per elementi trascinabili",\n      "default": "@index di @count trascinabili",\n      "description": "Etichetta usata per l''accessibilità, dove il lettore vocale legge che questo è un elemento trascinabile. Variabili disponibili: @index, @count"\n    },\n    {\n      "label": "Etichetta per il pulsante \\"Mostra suggerimento\\"",\n      "default": "Mostra suggerimento",\n      "description": "Etichetta usata per l''accessibilità, che il lettore vocale legge prima del suggerimento"\n    },\n    {\n      "label": "Testo del lettore vocale per risposta corretta",\n      "default": "Giusto!"\n    },\n    {\n      "label": "Testo del lettore vocale per risposta sbagliata",\n      "default": "Sbagliato!"\n    },\n    {\n      "label": "Titolo della finestra di dialogo per confermare all''utente il reset di un elemento trascinabile",\n      "default": "Resetta elemento trascinabile"\n    },\n    {\n      "label": "Descrizione della finestra di dialogo per confermare all''utente il reset di un elemento trascinabile",\n      "default": "Sei sicuro di voler resettare questo elemento trascinabile?"\n    },\n    {\n      "label": "Etichetta usata per l''accessibilità, dove il lettore vocale indica che il trascinamento è iniziato",\n      "default": "L''elemento trascinabile è stato afferrato"\n    },\n    {\n      "label": "Etichetta usata per l''accessibilità, dove il lettore vocale indica che il trascinamento è stato cancellato",\n      "default": "Trascinamento cancellato"\n    },\n    {\n      "label": "Etichetta usata per l''accessibilità, dove il lettore vocale indica che un testo è la risposta giusta",\n      "default": "Risposta giusta:"\n    },\n    {\n      "label": "Intestazione del pannello contenente i feedback per risposte corrette/errate",\n      "default": "Feedback"\n    },\n    {\n      "label": "Impostazioni di esecuzione",\n      "description": "Queste opzioni ti permettono di controllare il comportamento dell''attività",\n      "fields": [\n        {\n          "label": "Attiva \\"Riprova\\""\n        },\n        {\n          "label": "Attiva pulsante \\"Mostra soluzione\\""\n        },\n        {\n          "label": "Attiva pulsante \\"Verifica\\""\n        },\n        {\n          "label": "Feedback istantaneo"\n        }\n      ]\n    },\n    {\n      "label": "Rappresentazione testuale sulla barra del punteggio per chi usa un lettore vocale",\n      "default": "Il tuo punteggio è :num su :total"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'ja', '{\n  "semantics": [\n    {\n      "label": "メディア",\n      "fields": [\n        {\n          "label": "タイプ",\n          "description": "設問の上に表示するオプションのメディア。"\n        },\n        {\n          "label": "画像のズーム機能を無効化"\n        }\n      ]\n    },\n    {\n      "label": "タスクの説明",\n      "description": "ユーザーがタスクを解決する方法について説明してください。",\n      "default": "適切なボックスに単語をドラッグしてください"\n    },\n    {\n      "label": "テキスト",\n      "placeholder": "*オスロ*はノルウェーの首都です。*ストックホルム*はスウェーデンの首都で、*コペンハーゲン*はデンマークの首都です。すべての都市は*スカンジナビア:ヨーロッパの北部*半島に位置しています。",\n      "important": {\n        "description": "<ul><li>ドロップできる語句は、アスタリスク (*) を適切な語句の前後に付けて追加します。</li><li>コロン (:) をヒントの前に付けて、テキストのヒントを追加できます。</li><li>各空欄には、一つだけ適切な語句を置けます。</li><li>タスクが完了したときに表示されるフィードバックを追加できます。正解のフィードバックには ''\\\\+''、不正解のフィードバックには ''\\\\-''を使います。</li></ul>",\n        "example": "H5P content may be edited using a *browser:What type of program is Chrome?*. <br /> H5P content is *interactive\\\\+Correct! \\\\-Incorrect, try again!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "全体のフィードバック",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "デフォルト"\n            }\n          ],\n          "label": "ある得点範囲に対して、カスタムフィードバックを定義します。",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "範囲",\n          "field": {\n            "fields": [\n              {\n                "label": "得点範囲"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "「チェック」ボタンのテキスト",\n      "default": "チェック"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "「リトライ」ボタンのテキスト",\n      "default": "リトライ"\n    },\n    {\n      "label": "「解を表示」ボタンのテキスト",\n      "default": "解を表示"\n    },\n    {\n      "label": "番号付きのドロップゾーンラベル",\n      "default": "ドロップゾーン @index 。",\n      "description": "アクセシビリティのためのラベルで、リードスピーカーがドロップゾーンのインデックスを読み上げる。利用可能な変数: @index"\n    },\n    {\n      "label": "空のドロップゾーンのラベル",\n      "default": "ドロップゾーン @index は空です。",\n      "description": "アクセシビリティのためのラベルで、リードスピーカーが「ドロップゾーンが空である」ことを読み上げる"\n    },\n    {\n      "label": "ドロップゾーンのラベルが含まれる",\n      "default": "ドロップゾーン @index にはドロップ要素が @draggable 含まれる。",\n      "description": "アクセシビリティのためのラベルで、リードスピーカーが「ドロップゾーンにドラッグ要素が含まれる」ことを読み上げる"\n    },\n    {\n      "label": "ドラッグ要素のラベル",\n      "default": "@index / @ count ドラッグ",\n      "description": "アクセシビリティのためのラベルで、音声読み上げソフトがこれがドラッグ可能な要素であることを読み上げる。利用可能な変数: @index, @count"\n    },\n    {\n      "label": "ヒント表示ボタンのラベル",\n      "default": "ヒントを表示",\n      "description": "アクセシビリティのためのラベルで、ヒントが読まれる前に音声読み上げソフトが読み上げる。"\n    },\n    {\n      "label": "正解のためのリードスピーカー用テキスト",\n      "default": "正解 !"\n    },\n    {\n      "label": "不正解ためのリードスピーカー用テキスト",\n      "default": "不正解 !"\n    },\n    {\n      "label": "ユーザーがドロップ可能なようにリセットする際の確認ダイアログのタイトル",\n      "default": "ドロップをリセット"\n    },\n    {\n      "label": "ユーザーがドロップ可能なようにリセットする際の確認ダイアログの説明",\n      "default": "このドロップゾーンを本当にリセットしますか ?"\n    },\n    {\n      "label": "アクセシビリティのためのラベルで、音声読み上げソフトがドロップが始まったことを示す。",\n      "default": "ドラッグ要素をつかんだ。"\n    },\n    {\n      "label": "アクセシビリティのためのラベルで、音声読み上げソフトがドラッグがキャンセルされたことを示す。",\n      "default": "ドラッグがキャンセルされました。"\n    },\n    {\n      "label": "アクセシビリティのためのラベルで、音声読み上げソフトがテキストが正しい答えであることを示す。",\n      "default": "正解 :"\n    },\n    {\n      "label": "正解/不正解のフィードバックを含むパネルのヘッダー",\n      "default": "フィードバック"\n    },\n    {\n      "label": "動作設定",\n      "description": "これらのオプションでタスクがどのように動作するかを制御できます。",\n      "fields": [\n        {\n          "label": "「リトライ」を有効化"\n        },\n        {\n          "label": "「解を表示」ボタンを有効化"\n        },\n        {\n          "label": "Enable \\"Check\\" button"\n        },\n        {\n          "label": "即時フィードバック"\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'ka', '{\n  "semantics": [\n    {\n      "label": "მედია",\n      "fields": [\n        {\n          "label": "ტიპი",\n          "description": "არასავალდებულო მედია, რომელიც კითხვის თავზე გამოჩნდება."\n        },\n        {\n          "label": "გამორთეთ გამოსახულების მასშტაბირება"\n        }\n      ]\n    },\n    {\n      "label": "ამოცანის აღწერა",\n      "description": "აღწერეთ, როგორ უნდა ამოხსნას ამოცანა მომხმარებელმა.",\n      "default": "გადაიტანეთ სიტყვები სწორ უჯრებში"\n    },\n    {\n      "label": "ტექსტი",\n      "placeholder": "*ოსლო* არის ნორვეგიის დედაქალაქი, *სტოკჰოლმი* არის შვედეთის დედაქალაქი და *კოპენჰაგენი* არის დანიის დედაქალაქი. ყველა ქალაქი მდებარეობს *სკანდინავიაში:ევროპის ჩრდილოეთ ნაწილში* ნახევარკუნძულზე.",\n      "important": {\n        "description": "<ul><li>ჩასაშლელი სიტყვები ემატება ვარსკვლავით (*) სწორი სიტყვის/ფრაზის წინ და უკან. .</li><li>შეგიძლიათ დაამატოთ ტექსტური მინიშნება, (:)-ის დამატებით მინიშნების წინ</li><li>ყველა ცარიელი ადგილისთვის არის მხოლოდ ერთი სწორი სიტყვა.</li><li>შეგიძლიათ დაამატოთ გამოხმაურება, რომელიც გამოჩნდება დავალების დასრულებისას. გამოიყენეთ ''\\\\+'' სწორი გამოხმაურებისთვის და ''\\\\-'' არასწორი გამოხმაურებისთვის.</li></ul>",\n        "example": "H5P კონტენტის რედაქტირება შესაძლებელია *ბრაუზერის: რა ტიპის პროგრამაა Chrome?*. <br /> H5P კონტენტი *ინტერაქტიული\\\\+სწორია! \\\\-არასწორია, სცადეთ ხელახლა!*"\n      }\n    },\n    {\n      "label": "ყურადღების გამფანტველები",\n      "placeholder": "*რეიკიავიკი* *ჰელსინკი*",\n      "description": "შეიყვანეთ დამატებითი გადაწყვეტილებები, რომლებიც არასწორია, როგორც ყურადღების გამფანტველი. გამოიყენეთ იგივე ვარსკვლავი (*) სქემა, როგორც ტექსტისთვის."\n    },\n    {\n      "label": "საერთო გამოხმაურება",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "სტანდარტული"\n            }\n          ],\n          "label": "ქულების ნებისმიერი დიაპაზონისთვის ინდივიდუალური შეტყობინების დაყენება",\n          "description": "დააჭირეთ ღილაკს \\"დიაპაზონის დამატება\\" დიაპაზონების საჭირო რაოდენობების დასამატებლად. მაგალითი: 0-20% ცუდი შედეგი, 21-91% საშუალო შედეგი, 91-100% კარგი შედეგი!",\n          "entity": "დიაპაზონი",\n          "field": {\n            "fields": [\n              {\n                "label": "ქულების დიაპაზონი"\n              },\n              {},\n              {\n                "label": "უკუკავშირი განსაზღვრული შეფასების დიაპაზონისთვის",\n                "placeholder": "შეავსეთ უკუკავშირი"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "ტექსტი \\"შემოწმების\\" ღილაკისთვის",\n      "default": "შემოწმება"\n    },\n    {\n      "label": "ტექსტი \\"წარდგენის\\" ღილაკისთვის",\n      "default": "წარდგენა"\n    },\n    {\n      "label": "ტექსტი \\"თავიდან ცდის\\" ღილაკისთვის",\n      "default": "თავიდან ცდა"\n    },\n    {\n      "label": "ტექსტი \\"ამოხსნის ჩვენება\\" ღილაკისთვის",\n      "default": "ამოხსნის ჩვენება"\n    },\n    {\n      "label": "დანომრილი ჩამოშვების ზონის წარწერა",\n      "default": "ჩამოშლის ზონა @index.",\n      "description": "წარწერა, რომელიც გამოიყენება ხელმისაწვდომობისთვის, სადაც წამკითხველი წაიკითხავს ვარდნის ზონის ინდექსს. ცვლადი ხელმისაწვდომია: @index"\n    },\n    {\n      "label": "ცარიელი Drop Zone წარწერა",\n      "default": "Drop Zone @index ცარიელია.",\n      "description": "წარწერა გამოიყენება ხელმისაწვდომობისთვის, სადაც ტექსტის გამხმოვანებელი წაიკითხავს, რომ ჩამოშვების ზონა ცარიელია"\n    },\n    {\n      "label": "შეიცავს Drop Zone წარწერას",\n      "default": "Drop Zone @index შეიცავს გადატანად @draggable.",\n      "description": "წარწერა გამოიყენება ხელმისაწვდომობისთვის, სადაც ტექსტის გამხმოვენებელი წაიკითხავს, რომ ჩამოსაშლელი ზონა შეიცავს გადასატან ელემენტს"\n    },\n    {\n      "label": "გადასატანი ელემენტების წარწერა",\n      "default": "@count გადატანადის @index.",\n      "description": "წარწერა გამოიყენება ხელმისაწვდომობისთვის, სადაც ტექსტის გამხმოვენებელი კითხულობს, რომ ეს არის გადასატანი ელემენტი. ცვლადი ხელმისაწვდომია: @index, @count"\n    },\n    {\n      "label": "წარწერა ღილაკისთვის მინიშნების ჩვენება",\n      "default": "მინიშნების ჩვენება",\n      "description": "წარწერა გამოიყენება ხელმისაწვდომობისთვის, სადაც ტექსტის გამხმოვანებელი კითხულობს მას მინიშნების წაკითხვამდე"\n    },\n    {\n      "label": "ტექსტის გამხმოვენებლის ტექსტი სწორი პასუხისთვის",\n      "default": "სწორია!"\n    },\n    {\n      "label": "ტექსტის გამხმოვანებლის ტექსტი არასწორი პასუხისთვის",\n      "default": "არასწორია!"\n    },\n    {\n      "label": "დამადასტურებელი დიალოგის სათაური, სადაც მომხმარებელს სურს ჩამოსასვლელის გადატვირთვა",\n      "default": "ვარდნის გადატვირთვა"\n    },\n    {\n      "label": "დადასტურების დიალოგური აღწერილობა, რომლის მიხედვითაც მომხმარებელს სურს ჩამოსასვლელის გადატვირთვა",\n      "default": "დარწმუნებული ხართ, რომ გსურთ ამ ჩამოშვების ზონის გადატვირთვა?"\n    },\n    {\n      "label": "წარწერა გამოიყენება ხელმისაწვდომობისთვის, სადაც ტექსტის გამხმოვანებელი მიუთითებს, რომ ჩატვირთვა დაწყებულია",\n      "default": "გადასატანი მონიშნულია."\n    },\n    {\n      "default": "გაუქმებული გადატანა.",\n      "label": "წარწერა, რომელიც გამოიყენება ხელმისაწვდომობისთვის, სადაც ტექსტის გამხმოვანებელი მიუთითებს, რომ გადატანა გაუქმებულია"\n    },\n    {\n      "label": "წარწერა გამოიყენება ხელმისაწვდომობისთვის, სადაც ტექსტის გამხმოვანებელი მიუთითებს, რომ ტექსტი არის სწორი პასუხი",\n      "default": "სწორი პასუხი:"\n    },\n    {\n      "label": "უკუკავშირის პანელის სათაური სწორი/არასწორი პასუხებისთვის",\n      "default": "უკუკავშირი"\n    },\n    {\n      "label": "ქცევის პარამეტრები.",\n      "description": "ეს პარამეტრები არეგულირებს დავალების ქცევას.",\n      "fields": [\n        {\n          "label": "\\"გამეორების\\" დაშვება"\n        },\n        {\n          "label": "\\"ამოხსნის ჩვენების\\" ღილაკის გააქტიურება"\n        },\n        {\n          "label": "\\"შემოწმების\\" ღილაკის გააქტიურება"\n        },\n        {\n          "label": "მყისიერი გამოხმაურება"\n        }\n      ]\n    },\n    {\n      "label": "ქულების სკალის ტექსტურად გამოსახვა მათთვის, ვინც ტექსტის გახმოვანებას იყენებს",\n      "default": "თქვენ დააგროვეთ :num ქულა :total-დან"\n    },\n    {\n      "label": "\\"შემოწმების\\" ღილაკის წარწერა დამხმარე ტექნოლოგიისთვის",\n      "default": "შეამოწმე პასუხები. პასუხები მოინიშნება როგორც სწორი, არასწორი და პასუხგაუცემელი."\n    },\n    {\n      "label": "დამხმარე ტექნოლოგიის წარწერა \\"ამოხსნის ჩვენების\\" ღილაკისთვის",\n      "default": "აჩვენე ამოხსნა. დავალება მონიშნული იქნება მისი სწორი ამოხსნით."\n    },\n    {\n      "label": "\\"თავიდან ცდის\\" ღილაკის წარწერა დამხმარე ტექნოლოგიისთვის",\n      "default": "დავალების გამეორება. ყველა პასუხის გაუქმება და ამოცანის თავიდან დაწყება."\n    }\n  ]\n}\n'),
(19, 'km', '{\n  "semantics": [\n    {\n      "label": "Media",\n      "fields": [\n        {\n          "label": "Type",\n          "description": "Optional media to display above the question."\n        },\n        {\n          "label": "Disable image zooming"\n        }\n      ]\n    },\n    {\n      "label": "សេចក្តីពណ៌នាពីកិច្ចការ",\n      "description": "ពន្យល់ថាគេត្រូវធ្វើអ្វីខ្លះដើម្បីបំពេញកិច្ចការ",\n      "default": "អូសពាក្យទៅកាន់ប្រអប់ដែលត្រឹមត្រូវ"\n    },\n    {\n      "label": "អត្ថបទ",\n      "placeholder": "*ភ្នំពេញ*ជារាជធានីនៃប្រទេសកម្ពុជា, *បាងកក* ជារាជធានីនៃប្រទេសថៃ ហើយ *ហាណូយ* ជារាជធានីនៃប្រទេសវៀតណាម។ រាជធានីទាំងនេះស្ថិតក្នុង*តំបន់អាស៊ីអាគ្នេហ៍:ទីតាំងមួយក្នុងទ្វីប* ។",\n      "important": {\n        "description": "<ul><li>ពាក្យសម្រាប់អូសត្រូវដាក់ក្នុងចន្លោះសញ្ញាផ្កាយពីរ (*)</li><li>អ្នកក៏អាចផ្តល់ជាគន្លឹះជំនួយជាអត្ថបទ ដោយប្រើសញ្ញា (:) នៅខាងមុខគន្លឹះនោះ។</li><li>ចន្លោះនីមួយៗមានពាក្យត្រឹមត្រូវតែមួយគត់។</li><li>អ្នកក៏អាចផ្តល់នូវមូលវិចារណ៍ដែលនឹងត្រូវបង្ហាញនៅពេលបញ្ចប់កិច្ចការផងដែរ។ ប្រើ ''\\\\+'' សម្រាប់មូលវិចារណ៍លើចម្លើយត្រូវ និង ''\\\\-'' សម្រាប់មូលវិចារណ៍លើចម្លើយខុស។</li></ul>",\n        "example": "គោត្រូវបានចាត់ទុកជាប្រភេទ*ថនិកសត្វ:សត្វដែលចិញ្ចឹមកូនដោយទឹកដោះ\\\\+ត្រឹមត្រូវ! \\\\-មិនត្រឹមត្រូវទេ សូមសាកម្តងទៀត!*។"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "មូលវិចារណ៍ទូទៅ",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "លំនាំដើម"\n            }\n          ],\n          "label": "កំណត់មូលវិចារណ៍តាមបំណងសម្រាប់ចន្លោះពិន្ទុ",\n          "description": "ចុចប៊ូតុង \\"បន្ថែមចន្លោះ\\" ដើម្បីបន្ថែមចន្លោះពិន្ទុតាមដែលអ្នកចង់បាន។ ឧទា: 0-20% ពិន្ទុខ្សោយ, 21-91% ពិន្ទុមធ្យម, 91-100% ពិន្ទុល្អប្រសើរ!",\n          "entity": "ចន្លោះ",\n          "field": {\n            "fields": [\n              {\n                "label": "ចន្លោះពិន្ទុ"\n              },\n              {},\n              {\n                "label": "មូលវិចារណ៍សម្រាប់ចន្លោះពិន្ទុដែលបានកំណត់",\n                "placeholder": "បញ្ចូលមូលវិចារណ៍"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "ពាក្យប្រើសម្រាប់ប៊ូតុង \\"ពិនិត្យចម្លើយ\\"",\n      "default": "ពិនិត្យចម្លើយ"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "ពាក្យប្រើសម្រាប់ប៊ូតុង \\"សាកម្តងទៀត\\"",\n      "default": "សាកម្តងទៀត"\n    },\n    {\n      "label": "ពាក្យប្រើសម្រាប់ប៊ូតុង \\"បង្ហាញចម្លើយត្រឹមត្រូវ\\"",\n      "default": "បង្ហាញចម្លើយត្រឹមត្រូវ"\n    },\n    {\n      "label": "ពាក្យសម្រាប់តំបន់ទម្លាក់ដែលមានលេខសម្គាល់",\n      "default": "តំបន់ទម្លាក់ @index",\n      "description": "ពាក្យនេះប្រើសម្រាប់មុខងារមធ្យោបាយងាយស្រួល សម្រាប់ឲ្យកុំព្យូទ័រអានលេខសម្គាល់នៃតំបន់ទម្លាក់។ អញ្ញត្តិដែលអាចប្រើបាន: @index"\n    },\n    {\n      "label": "ពាក្យសម្រាប់តំបន់ទម្លាក់ទទេ",\n      "default": "តំបន់ទម្លាក់ @index គឺទទេ។",\n      "description": "ពាក្យនេះប្រើសម្រាប់មុខងារមធ្យោបាយងាយស្រួល សម្រាប់ឲ្យកុំព្យូទ័រអានថាតំបន់ទម្លាក់គឺទទេ។"\n    },\n    {\n      "label": "Contains Drop Zone label",\n      "default": "តំបន់ទម្លាក់ @index មានធាតុអូស @draggable។",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone contains a draggable"\n    },\n    {\n      "label": "Draggable elements label",\n      "default": "@index ចំណោមធាតុអូស @count ។",\n      "description": "Label used for accessibility, where the Read speaker reads that this is a draggable element. Variable available: @index, @count"\n    },\n    {\n      "label": "Label for show tip button",\n      "default": "បង្ហាញគន្លឹះ",\n      "description": "Label used for accessibility, where the Read speaker reads it before the tip is read out"\n    },\n    {\n      "label": "Readspeaker text for correct answer",\n      "default": "ត្រឹមត្រូវ!"\n    },\n    {\n      "label": "Readspeaker text for incorrect answer",\n      "default": "មិនត្រឹមត្រូវ!"\n    },\n    {\n      "label": "Confirmation dialog title that user wants to reset a droppable",\n      "default": "កំណត់ការទម្លាក់ឡើងវិញ"\n    },\n    {\n      "label": "Confirmation dialog description that user wants to reset a droppable",\n      "default": "តើអ្នកពិតជាចង់ធ្វើការកំណត់ឡើងវិញសម្រាប់តំបន់ទម្លាក់នេះមែនទេ?"\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is initiated",\n      "default": "ធាតុអូសត្រូវបានចាប់។"\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is canceled",\n      "default": "បោះបង់ការចាប់"\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that a text is the correct answer",\n      "default": "ចម្លើយត្រឹមត្រូវ:"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "មូលវិចារណ៍"\n    },\n    {\n      "label": "ការកំណត់មុខងារ",\n      "description": "ជម្រើសទាំងនេះនឹងឲ្យអ្នកអាចកំណត់មុខងារផ្សេងៗរបស់កិច្ចការអ្នក។",\n      "fields": [\n        {\n          "label": "អនុញ្ញាត \\"សាកម្តងទៀត\\""\n        },\n        {\n          "label": "បង្ហាញប៊ូតុង \\"បង្ហាញចម្លើយត្រឹមត្រូវ\\""\n        },\n        {\n          "label": "បង្ហាញប៊ូតុង \\"ពិនិត្យចម្លើយ\\""\n        },\n        {\n          "label": "ពិនិត្យចម្លើយភ្លាមៗ"\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "អ្នកទទួលបានពិន្ទុ :num លើ :total"\n    },\n    {\n      "label": "Assistive technology description for \\"Check\\" button",\n      "default": "ពិនិត្យចម្លើយ។ ចម្លើយនឹងត្រូវបានដាក់សម្គាល់ថាត្រឹមត្រូវ មិនត្រឹមត្រូវ ឬមិនបានឆ្លើយ។"\n    },\n    {\n      "label": "Assistive technology description for \\"Show Solution\\" button",\n      "default": "បង្ហាញចម្លើយត្រឹមត្រូវ។ កិច្ចការនឹងត្រូវបានដាក់សម្គាល់ដោយចម្លើយត្រឹមត្រូវរបស់វា។"\n    },\n    {\n      "label": "Assistive technology description for \\"Retry\\" button",\n      "default": "សាកធ្វើកិច្ចការម្តងទៀត។ លុបចម្លើយទាំងអស់ ហើយចាប់ផ្តើមកិច្ចការជាថ្មី។"\n    }\n  ]\n}\n'),
(19, 'ko', '{\n  "semantics": [\n    {\n      "label": "미디어",\n      "fields": [\n        {\n          "label": "유형",\n          "description": "(선택사항) 문제 위에 표시할 미디어."\n        },\n        {\n          "label": "이미지 확대 비활성화"\n        }\n      ]\n    },\n    {\n      "label": "과제 설명",\n      "description": "사용자가 과제를 어떻게 해결해야 하는지 설명하세요.",\n      "default": "단어를 알맞은 박스로 끌어놓으세요."\n    },\n    {\n      "label": "텍스트",\n      "placeholder": "*서울*은 대한민국의 수도이고 *파리* 는 프랑스의 수도이다. 한국이 속한 대륙은 *아시아:동아시아가 속한 대륙* 이다",\n      "important": {\n        "description": "<ul><li>끌어놓을 수 있는 단어는 별표(*)로 알맞은 단어/구 앞, 뒤에 추가된다.</li><li>콜론(:)을 사용하여 팁을 줄 수 있다. 이 때 콜론은 팁 앞에 쓰면 된다.     </li><li>빈자리마다 맞는 단어가 딱 하나 있다.</li><li>과제가 완료될 때 표시할 피드백을 추가할 수 있다. ''\\\\+''를 올바른 답을 위해, ''\\\\-'' 를 오답 피드백을 위해 사용하세요</li></ul>",\n        "example": "H5P 콘텐츠는 *브라우저: 크롬은 어떤 종류의 프로그램인가?*<br /> H5P 콘텐츠는 *상호작용적\\\\+정답입니다! \\\\-오답이네요, 다시해보세요!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "전반적인 피드백",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "기본값"\n            }\n          ],\n          "label": "점수 범위별 사용자 정의 피드백 정의",\n          "description": "\\"Add range\\" (범위 추가) 버튼을 이용해 범위를 추가하세요. 예: 0-20% 분발해야 할 점수, 21-91% 평균점수, 91-100% 훌륭한 점수!",\n          "entity": "범위",\n          "field": {\n            "fields": [\n              {\n                "label": "점수 범위"\n              },\n              {},\n              {\n                "label": "정의된 점수 범위에 대한 피드백",\n                "placeholder": "피드백 작성"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "\\"Check\\" 버튼 텍스트",\n      "default": "정답 확인"\n    },\n    {\n      "label": "\\"Submit\\" 버튼 텍스트",\n      "default": "제출하기"\n    },\n    {\n      "label": "\\"Retry\\" 버튼 텍스트",\n      "default": "재시도"\n    },\n    {\n      "label": " \\"Show Solution\\" 버튼 텍스트",\n      "default": "해답보이기"\n    },\n    {\n      "label": "숫자가 매겨진 드랍 영역 레이블",\n      "default": "드랍 영역 @index.",\n      "description": "접근성에 사용되는 라벨, 자동 읽어주기가 드롭 영역의 색인을 읽는다. 사용 가능한 변수: @index"\n    },\n    {\n      "label": "비어있는 드랍영역 레이블",\n      "default": "드랍영역 @index 가 비어있습니다.",\n      "description": "접근성에 사용되는 라벨, 자동 읽어주기가 비어 있는 드랍영역을 읽을 것입니다."\n    },\n    {\n      "label": "드랍 영역 레이블 포함",\n      "default": "드랍영역 @index 가 끌어놓기 가능한 @draggable 를 포함하고 있습니다.",\n      "description": "접근성에 사용되는 라벨, 자동 읽어주기가 드랍영역이 끌어 놓기 가능한 항목을 포함한다고 읽을 것입니다."\n    },\n    {\n      "label": "끌어놓을 수 있는 요소 레이블",\n      "default": "총 @count 끌어놓기 항목 중 @index .",\n      "description": "접근성에 사용되는 라벨, 자동 읽어주기가 이것이 끌어놓을 수 있는 요소라고 읽을 것입니다. 이용가능한 변수: @index, @count"\n    },\n    {\n      "label": "팁 버튼 레이블",\n      "default": "팁 보이기",\n      "description": "접근성에 사용되는 라벨, 자동 읽어주기가 팁이 읽어지기 전에 읽어줍니다."\n    },\n    {\n      "label": "올바른 답에 대한 자동 읽어주기",\n      "default": "정답!"\n    },\n    {\n      "label": "오답에 대한 자동 읽어주기",\n      "default": "오답입니다."\n    },\n    {\n      "label": "끌어 놓을 수 있는 요소를 초기화하기를 원할 경우 대화창 제목",\n      "default": "끌어놓기 요소 초기화"\n    },\n    {\n      "label": "끌어 놓을 수 있는 요소를 초기화하기를 원할 경우 대화창 확인",\n      "default": "이 드랍 영역을 초기화하기를 원하세요?"\n    },\n    {\n      "label": "접근성에 사용되는 라벨, 자동 읽어주기가 끌기가 시작되었다고 읽어줌",\n      "default": "끌어놓기 항목이 선택되었습니다."\n    },\n    {\n      "label": "접근성에 사용되는 라벨, 자동 읽어주기가 끌기가 취소되었다고 말해줍니다.",\n      "default": "끌기가 취소됨."\n    },\n    {\n      "label": "접근성에 사용되는 라벨, 자동 읽어주기가 정답이라고 말해줍니다.",\n      "default": "정답입니다:"\n    },\n    {\n      "label": "정답/오답에 대한 피드백을 포함하는 패널 머릿말",\n      "default": "피드백"\n    },\n    {\n      "label": "과제가 수행되는 방법 설정",\n      "description": "이 옵션은 과제가 어떻게 수행될 지 환경을 설정합니다.",\n      "fields": [\n        {\n          "label": "\\"Retry\\"(재시도) 버튼 활성화"\n        },\n        {\n          "label": "\\"Show Solution\\" (해답 보기) 버튼 활성화"\n        },\n        {\n          "label": "\\"Check\\" (정답 확인) 버튼 활성화"\n        },\n        {\n          "label": "즉각적인 피드백"\n        }\n      ]\n    },\n    {\n      "label": "자동 읽어주기를 위한 점수 막대의 텍스트 표현",\n      "default": "총 :total 에서 :num 획득"\n    },\n    {\n      "label": "\\"Check\\" 버튼에 대한 보조 기술 설명",\n      "default": "정답을 체크하세요. 답변은 정답, 오답 혹은 미답변으로 표기될 것입니다."\n    },\n    {\n      "label": "\\"Show Solution\\" 버튼에 대한 보조 기술 설명",\n      "default": "해답 보이기. 올바른 해답과 함께 표기될 것입니다."\n    },\n    {\n      "label": "\\"Retry\\" 버튼에 대한 보조 기술 설명",\n      "default": "재시도하세요. 모든 답변을 초기화하고 새로 시도하세요."\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(19, 'lt', '{\n  "semantics": [\n    {\n      "label": "Medija",\n      "fields": [\n        {\n          "label": "Tipas",\n          "description": "Papildoma media po klausimu."\n        },\n        {\n          "label": "Išjungti vaizdo didinimą"\n        }\n      ]\n    },\n    {\n      "label": "Užduoties aprašymas",\n      "description": "Aprašykite, kaip naudotojas turėtų išspręsti užduotį.",\n      "default": "Nutempkite žodžius į teisingas langelius"\n    },\n    {\n      "label": "Tekstas",\n      "placeholder": "*Oslas* yra Norvegijos sostinė, *Stokholmas* yra Švedijos sostinė ir *Kopenhaga* yra Danijos sostinė. Visi miestai randasi *Skandinavijos pusiasalyje, Šiaurinėje Europos* dalyje.",\n      "important": {\n        "description": "<ul><li>Praleisti žodžiai žymimi žvaigždute (*) priekyje ir gale teisingo žodžio/frazės.</li><li>Jūs galite įdėti tekstinį patarimą, naudodami dvitaškį (:) priekyje patarimo.</li><li>Kiekvienai tuščiai vietai yra tik vienas teisingas atsakymas.</li><li>Jūs galite pridėti atsiliepimą, kada užduotis bus užbaigta. Naudokite ''\\\\+'' teigiamam ir ''\\\\-'' neigiamam atsiliepimui.</li></ul>",\n        "example": "H5P content may be edited using a *browser:What type of program is Chrome?*. <br /> H5P content is *interactive\\\\+Correct! \\\\-Incorrect, try again!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reikjavikas* *Helsinkis*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Bendras atsiliepimas",\n      "fields": [\n        {\n          "entity": "diapazonas",\n          "widgets": [\n            {\n              "label": "Numatytasis"\n            }\n          ],\n          "label": "Nustatykite tinkintus atsiliepimus bet kokiam balų intervalui",\n          "description": "Spustelėkite mygtuką „Pridėti diapazoną“, kad pridėtumėte tiek diapazonų, kiek jums reikia. Pavyzdys: 0–20 % blogas balas, 21–91 % vidutinis balas, 91–100 % puikus rezultatas!",\n          "field": {\n            "fields": [\n              {\n                "label": "Balų diapazonas"\n              },\n              {},\n              {\n                "label": "Atsiliepimai apibrėžtam balų diapazonui",\n                "placeholder": "Užpildykite atsiliepimą"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Mygtuko \\"Tikrinti\\" tekstas",\n      "default": "Tikrinti"\n    },\n    {\n      "label": "Tekstas mygtukui „Pateikti“.",\n      "default": "Pateikti"\n    },\n    {\n      "label": "Tekstas mygtukui „Bandyti dar kartą“.",\n      "default": "Bandyti dar kartą"\n    },\n    {\n      "label": "Tekstas mygtukui „Rodyti sprendimą“",\n      "default": "Rodyti sprendimą"\n    },\n    {\n      "label": "Sunumeruotos metimo zonos pavadinimas",\n      "default": "Metimo zona @index.",\n      "description": "Label used for accessibility, where the Read speaker will read the index of a drop zone. Variable available: @index"\n    },\n    {\n      "label": "Tuščios metimo zonos pavadinimas",\n      "default": "Metimo zona @index yra tuščia.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone is empty"\n    },\n    {\n      "label": "Contains Drop Zone label",\n      "default": "Drop Zone @index contains draggable @draggable.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone contains a draggable"\n    },\n    {\n      "label": "Metamų elementų pavadinimas",\n      "default": "@index iš @count metamų elementų.",\n      "description": "Label used for accessibility, where the Read speaker reads that this is a draggable element. Variable available: @index, @count"\n    },\n    {\n      "label": "Mygtuko „Rodyti patarimą“ pavadinimas",\n      "default": "Rodyti patarimą",\n      "description": "Label used for accessibility, where the Read speaker reads it before the tip is read out"\n    },\n    {\n      "label": "Readspeaker text for correct answer",\n      "default": "Teisingai!"\n    },\n    {\n      "label": "Readspeaker text for incorrect answer",\n      "default": "Neteisingai!"\n    },\n    {\n      "label": "Confirmation dialog title that user wants to reset a droppable",\n      "default": "Atstatyti metimą"\n    },\n    {\n      "label": "Confirmation dialog description that user wants to reset a droppable",\n      "default": "Ar tikrai norite iš naujo nustatyti šią metimo zoną?"\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is initiated",\n      "default": "Metamas elementas yra paimtas."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is canceled",\n      "default": "Atšauktas metimas."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that a text is the correct answer",\n      "default": "Teisingas atsakymas:"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "Atsiliepimas"\n    },\n    {\n      "label": "Veikimo nustatymai.",\n      "description": "Šios parinktys leis jums valdyti, kaip veikia užduotis.",\n      "fields": [\n        {\n          "label": "Įjungti „Bandyti dar kartą“"\n        },\n        {\n          "label": "Įjungti „Rodyti sprendimą“ mygtuką"\n        },\n        {\n          "label": "Įjungti „Tikrinti“ mygtuką"\n        },\n        {\n          "label": "Momentinis atsiliepimas"\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "Jūs gavote :num iš :total taškų"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Rodyti sprendimą. Užduotis bus pažymėta teisingu jos sprendimu."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Bandyti atlikti užduotį dar kartą. Iš naujo nustatyti visus atsakymus ir pradėti užduotį iš naujo."\n    }\n  ]\n}\n'),
(19, 'lv', '{\n  "semantics": [\n    {\n      "label": "Multivide",\n      "fields": [\n        {\n          "label": "Tips",\n          "description": "Papildu multimedijs, kuru atspoguļot virs jautājuma."\n        },\n        {\n          "label": "Atspējot attēla tālummaiņu"\n        }\n      ]\n    },\n    {\n      "label": "Uzdevuma apraksts",\n      "description": "Aprakstiet kā lietotājam vajadzētu risināt uzdevumu.",\n      "default": "Velciet vārdus pareizajos lodziņos"\n    },\n    {\n      "label": "Teksts",\n      "placeholder": "*Oslo* ir Norvēģijas galvaspilsēta, *Stokholma* ir Zviedrijas galvaspilsēta un *Kopenhāgena* ir Dānijas galvaspilsēta. Visas pilsētas atrodas *Skandināvijas:Eiropas ziemeļdaļas* pussalā.",\n      "important": {\n        "description": "<ul><li>Velkamie vārdi tiek pievienoti ar zvaigznīti (*) pareizā vārda/frāzes priekšā un aiz tā.</li><li>Variet pievienot teksta padomu, padoma priekšā pievienojot kolu (:). .</li><li>Katram tukšajam laukumam ir tikai viens pareizs vārds.</li><li>Variett pievienot atgriezenisko saiti, kas tiks parādīta, kad uzdevums ir pabeigts. Izmantojiet ''\\\\+'' atgriezeniskajai saitei par pareizu atbildi un ''\\\\-'' atgriezeniskajai saitei par nepareizu atbildi.</li></ul>",\n        "example": "H5P saturu var rediģēt, izmantojot *pārlūkprogrammu:Kāda veida programma ir Chrome?*. <br /> H5P saturs ir *interaktīvs\\\\+Pareizi! \\\\-Nepareizi, mēģiniet vēlreiz!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Kopējā atgriezeniskā saite",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Pēc noklusējuma"\n            }\n          ],\n          "label": "Iestatiet pielāgotu atgriezenisko saiti katram rezultātu diapazonam",\n          "entity": "diapazons",\n          "field": {\n            "fields": [\n              {\n                "label": "Rezultātu diapazons"\n              },\n              {},\n              {\n                "label": "Norādītā diapazona atgriezeniskā saite",\n                "placeholder": "Aizpildiet atgriezenisko saiti"\n              }\n            ]\n          },\n          "description": "Klikšķiniet pogu \\"Pievienot diapazonu\\", lai pievienotu tik diapazonus cik vēlaties. Piemēram, 0-20% Slikts rezultāts, 21-91% Viduvējs rezultāts, 91-100% Lielisks rezultāts!"\n        }\n      ]\n    },\n    {\n      "label": "Pogas \\"Pārbaudīt\\" teksts",\n      "default": "Pārbaudīt"\n    },\n    {\n      "label": "Pogas \\"Iesniegt\\" teksts",\n      "default": "Iesniegt"\n    },\n    {\n      "label": "Pogas \\"Mēģināt vēlreiz\\" teksts",\n      "default": "Mēģināt vēlreiz"\n    },\n    {\n      "label": "Pogas \\"Parādīt risinājumu\\" teksts",\n      "default": "Parādīt risinājumu"\n    },\n    {\n      "label": "Numurētas nomešanas zonas etiķete",\n      "default": "Nomešanas zona @index.",\n      "description": "Pieejamībai izmantotā etiķete, no kura asistīvās tehnoloģijas nolasīs zonas indeksu. Pieejamais mainīgais: @index"\n    },\n    {\n      "label": "Tukšas nomešanas zonas etiķete",\n      "default": "Nomešanas zona @index ir tukša.",\n      "description": "Pieejamībai izmantotā etiķete, no kuras asistīvās tehnoloģijas nolasīs, ka nomešanas zona ir tukša"\n    },\n    {\n      "label": "Satur nomešanas zonu etiķete",\n      "default": "Nomešanas zona @index satur velkamo elementu @draggable.",\n      "description": "Pieejamībai izmantotā etiķete, no kuras asistīvās tehnoloģijas nolasīs, ka nomešanas zona satur velkamo elementu"\n    },\n    {\n      "label": "Velkamo elementu etiķete",\n      "default": "@index no @count velkamajiem elementiem.",\n      "description": "Pieejamībai izmantotā etiķete, no kuras asistīvās tehnoloģijas nolasīs, ka šis ir velkams elements. Pieejami mainīgie: @index, @count"\n    },\n    {\n      "label": "Etiķete pogai Rādīt padomu",\n      "default": "Parādīt padomu",\n      "description": "Pieejamībai izmantotā etiķete, no kuras asistītvās tehnoloģijas nolasa, ka pieejams padoms"\n    },\n    {\n      "label": "Pareizās atbildes atskaņošanas teksts asistīvajām tehnoloģijām",\n      "default": "Pareizi!"\n    },\n    {\n      "label": "Nepareizās atbildes atskaņošanas teksts asistīvajām tehnoloģijām",\n      "default": "Nepareizi!"\n    },\n    {\n      "label": "Apstiprinājuma dialoga nosaukums, kad lietotājs vēlas atiestatīt velkamo elementu",\n      "default": "Atiestatīt nomešanu"\n    },\n    {\n      "default": "Vai tiešām vēlaties atiestatīt šo nomešanas zonu?",\n      "label": "Apstiprinājuma dialoga apraksts, kad lietotājs vēlas atiestatīt velkamo elementu"\n    },\n    {\n      "default": "Velkamais elements ir satverts.",\n      "label": "Pieejamībai izmantotā etiķete, pēc kuras asistīvās tehnoloģijas nosaka, ka uzsākta elementa vilkšana"\n    },\n    {\n      "label": "Pieejamībai izmantotā etiķete, pēc kuras asistīvās tehnoloģijas nosaka, ka elementa vilkšana ir atcelta",\n      "default": "Vilkšana atcelta."\n    },\n    {\n      "label": "Pieejamībai izmantotā etiķete, no kuras asistīvās tehnoloģijas nosaka, ka teksts ir pareizā atbilde",\n      "default": "Pareizā atbilde:"\n    },\n    {\n      "default": "Atgriezeniskā saite",\n      "label": "Paneļa galvene, kurā ir atgriezeniskā saite par pareizām/nepareizām atbildēm"\n    },\n    {\n      "label": "Uzvedības iestatījumi.",\n      "description": "Šie iestatījumi ļaus jums kontrolēt uzdevuma uzvedību.",\n      "fields": [\n        {\n          "label": "Atļaut pogu \\"Mēģināt vēlreiz\\""\n        },\n        {\n          "label": "Atļaut pogu \\"Rādīt risinājumu\\""\n        },\n        {\n          "label": "Atļaut pogu \\"Pārbaudīt\\""\n        },\n        {\n          "label": "Tūlītēja atgriezeniskā saite"\n        }\n      ]\n    },\n    {\n      "default": "Tu saņēmi :num no :total punktiem",\n      "label": "Rezultātu skalas tekstuālais atspoguļojums tiem, kas izmanto asistīvās tehnoloģijas"\n    },\n    {\n      "label": "Pogas \\"Pārbaudīt\\" etiķete asistīvajām tehnoloģijām",\n      "default": "Pārbaudīt atbildes. Atbildes tiks atzīmētas kā pareizas, nepareizas, vai neatbildētas."\n    },\n    {\n      "label": "Asistīvo tehnoloģiju etiķete pogai \\"Rādīt risinājumu\\"",\n      "default": "Rādīt risinājumu. Uzdevums tiks atzīmēts ar tā pareizo risinājumu."\n    },\n    {\n      "label": "Pogas \\"Mēģināt vēlreiz\\" etiķete asistīvajām tehnoloģijām",\n      "default": "Mēģiniet uzdevumu vēlreiz. Dzēst visas iesniegtās atbildes un sākt uzdevumu no sākuma."\n    }\n  ]\n}\n'),
(19, 'mn', '{\n  "semantics": [\n    {\n      "label": "Медиа",\n      "fields": [\n        {\n          "label": "Төрөл",\n          "description": "Асуултын дээр харуулах нэмэлт медиа."\n        },\n        {\n          "label": "Зургийн томруулагчийг идэвхгүй болгох"\n        }\n      ]\n    },\n    {\n      "label": "Ажлын тодорхойлолт",\n      "description": "Хэрэглэгч даалгаврыг хэрхэн шийдвэрлэх ёстойг тайлбарлана уу.",\n      "default": "Үгсийг зөв нүд рүү чирнэ үү"\n    },\n    {\n      "label": "Текст",\n      "placeholder": "*Осло* нь Норвегийн нийслэл, *Стокгольм* нь Шведийн нийслэл, *Копенгаген* нь Данийн нийслэл юм. Бүх хотууд *Скандинав:Европын хойд хэсэг* хойгт байрладаг.",\n      "important": {\n        "description": "<ul><li>Унадаг үгсийг зөв үг/өгүүлбэрийн урд болон ард одоор (*) тэмдэгээр нэмдэг.</li><li>Та текстийн үзүүрийг өмнө нь хоёр цэг (:) ашиглан нэмж болно. зөвлөгөө.</li><li>Хоосон цэг бүрт зөвхөн нэг зөв үг байна.</li><li>Та ажил дууссаны дараа харуулах санал хүсэлтийг нэмж болно. Зөв бол ''\\\\+'', буруу санал хүсэлт байвал ''\\\\-''-г ашиглана уу.</li></ul>",\n        "example": "H5P контентыг *хөтөч: Chrome нь ямар төрлийн програм вэ?* ашиглан засварлаж болно. <br /> H5P контент *интерактив\\\\+Зөв! \\\\-Буруу, дахин оролдоно уу!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "fields": [\n        {\n          "field": {\n            "fields": [\n              {\n                "label": "Онооны хүрээ"\n              },\n              {},\n              {\n                "label": "Тодорхойлогдсон онооны хүрээний санал хүсэлт",\n                "placeholder": "Санал хүсэлтийг бөглөнө үү"\n              }\n            ]\n          },\n          "widgets": [\n            {\n              "label": "Өгөгдмөл"\n            }\n          ],\n          "label": "Аль ч онооны мужид захиалгат санал хүсэлтийг тодорхойлох",\n          "description": "\\"Хүрээ нэмэх\\" товчийг дарж шаардлагатай бол олон муж нэмнэ. Жишээ нь: 0-20% муу оноо, 21-91% дундаж оноо, 91-100% сайн оноо!",\n          "entity": "Хүрээ"\n        }\n      ],\n      "label": "Ерөнхий санал хүсэлт"\n    },\n    {\n      "label": "\\"Шалгах\\" товчлуурын текст",\n      "default": "Шалгах"\n    },\n    {\n      "label": "\\"Илгээх\\" товчлуурын текст",\n      "default": "Илгээх"\n    },\n    {\n      "label": "\\"Дахин оролдох\\" товчлуурын текст",\n      "default": "Дахин оролдоно уу"\n    },\n    {\n      "label": "\\"Шийдэл харуулах\\" товчлуурын текст",\n      "default": "Шийдлийг харуулах"\n    },\n    {\n      "label": "Дугаарласан унах бүсийн шошго",\n      "default": "Унах бүс @index.",\n      "description": "Унших чанга яригч нь уналтын бүсийн индексийг унших боломжтой шошго. Боломжтой хувьсагч: @index"\n    },\n    {\n      "label": "Хоосон Унах бүс шошго",\n      "default": "Унах бүс @index хоосон.",\n      "description": "Унших чанга яригч уналтын бүс хоосон байгааг уншихад хүртээмжтэй болгоход ашигладаг шошго"\n    },\n    {\n      "label": "Унах бүс шошго агуулсан",\n      "default": "Drop Zone @index нь чирж болох @draggable-г агуулдаг.",\n      "description": "Унших чанга яригч нь буулгах бүсэд чирэх боломжтой гэдгийг унших боломжтой шошгыг ашиглах боломжтой"\n    },\n    {\n      "label": "Чирэх боломжтой элементүүдийн шошго",\n      "default": "чирж болох @count -ын @index.",\n      "description": "Унших чанга яригч үүнийг чирэх боломжтой элемент гэж уншдаг шошгыг хүртээмжтэй болгоход ашигладаг. Боломжтой хувьсагч: @index, @count"\n    },\n    {\n      "label": "Зөвлөгөө харуулах товчлуурын шошго",\n      "default": "Зөвлөгөө харуулах",\n      "description": "Унших чанга яригч нь зөвлөмжийг уншихаас өмнө уншдаг шошгыг хүртээмжтэй болгоход ашигладаг"\n    },\n    {\n      "label": "Зөв хариулт өгөхийн тулд илтгэгчийн текстийг уншина уу",\n      "default": "Зөв!"\n    },\n    {\n      "label": "Буруу хариултын төлөө унших илтгэгчийн текст",\n      "default": "Буруу!"\n    },\n    {\n      "label": "Хэрэглэгч уналтанд орохыг дахин тохируулах хүсэлтыг баталгаажуулах харилцах цонхны гарчиг",\n      "default": "Уналтыг дахин тохируулах"\n    },\n    {\n      "label": "Хэрэглэгчийн унагаж болох зүйлийг дахин тохируулахыг хүссэн баталгаажуулалтын харилцах цонхны тайлбар",\n      "default": "Та энэ буулгах бүсийг дахин тохируулахдаа итгэлтэй байна уу?"\n    },\n    {\n      "label": "Унших чанга яригч нь чирж эхэлснийг харуулж байгаа шошгыг хүртээмжтэй болгоход ашигладаг",\n      "default": "Чирэх боломжтой."\n    },\n    {\n      "label": "Унших чанга яригч нь чирэх үйлдлийг цуцалсныг зааж өгөхөд хандалт хийхэд ашигладаг шошго",\n      "default": "Чирэхийг цуцалсан."\n    },\n    {\n      "label": "Унших чанга яригч нь текстийг зөв хариулт болохыг зааж өгөхөд хүртээмжтэй болгоход ашигладаг шошго",\n      "default": "Зөв хариулт:"\n    },\n    {\n      "label": "Зөв/буруу хариултын санал хүсэлтийг агуулсан самбарын толгой хэсэг",\n      "default": "Санал хүсэлт"\n    },\n    {\n      "label": "Зан үйлийн тохиргоо.",\n      "description": "Эдгээр сонголтууд нь даалгавар хэрхэн ажиллахыг хянах боломжийг танд олгоно.",\n      "fields": [\n        {\n          "label": "\\"Дахин оролдох\\"-ыг идэвхжүүлэх"\n        },\n        {\n          "label": "\\"Шийдэл харуулах\\" товчийг идэвхжүүлнэ үү"\n        },\n        {\n          "label": "\\"Шалгах\\" товчийг идэвхжүүлнэ үү"\n        },\n        {\n          "label": "Шуурхай санал хүсэлт"\n        }\n      ]\n    },\n    {\n      "label": "Унших чанга яригч ашигладаг хүмүүст зориулсан онооны самбарын текстэн дүрслэл",\n      "default": "Та нийт :total онооноос :num авсан"\n    },\n    {\n      "label": "\\"Шалгах\\" товчлуурын туслах технологийн шошго",\n      "default": "Хариултуудыг шалгана уу. Хариултуудыг зөв, буруу, хариултгүй гэж тэмдэглэнэ."\n    },\n    {\n      "label": "\\"Шийдэл харуулах\\" товчлуурын туслах технологийн шошго",\n      "default": "Шийдлийг харуул. Даалгаврыг зөв шийдлээр нь тэмдэглэнэ."\n    },\n    {\n      "label": "\\"Дахин оролдох\\" товчлуурын туслах технологийн шошго",\n      "default": "Даалгаврыг дахин оролдоно уу. Бүх хариултыг дахин тохируулаад даалгаврыг дахин эхлүүлнэ үү."\n    }\n  ]\n}\n'),
(19, 'nb', '{\n  "semantics": [\n    {\n      "label": "Medieelement",\n      "fields": [\n        {\n          "label": "Type",\n          "description": "Valgfritt medieelement. Elementet vil bli plassert over spørsmålet."\n        },\n        {\n          "label": "Deaktiver zoomfunksjon."\n        }\n      ]\n    },\n    {\n      "label": "Oppgavebeskrivelse",\n      "description": "Forklar hvordan brukeren skal løse oppgaven.",\n      "default": "Dra ordene inn i de riktige boksene."\n    },\n    {\n      "label": "Tekst",\n      "placeholder": "*Oslo* er hovedstaden i Norge, *Stockholm* er hovedstaden i Sverige, og *København* er hovedstaden i Danmark. Alle byene er lokalisert i *Skandinavia:den nordlige delen av Europa*.",\n      "important": {\n        "description": "<ul><li>Flyttbare ord eller uttrykk markeres med en asterisk (*) foran og etter ordet/uttrykket.</li><li>Du kan også legge til et hint ved å bruke kolon (:). Eksempel: *Skandinavia:den nordlige delen av Europa*</li><li>Det finnes bare ett rett svar for hver tekstboks.</li><li>Det er mulig å legge til ei tilbakemelding som vises når oppgaven er fullført. Bruk ''\\\\+'' for positiv og ''\\\\-'' for negativ tilbakemelding.</li></ul>",\n        "example": "H5P-innhold kan redigeres med en *nettleser:Hva slags program er Chrome?*.<br />H5P-innhold er *interaktivt\\\\+Riktig!\\\\-Feil, prøv igjen*."\n      }\n    },\n    {\n      "label": "Svaralternativer som er feil",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Legg inn ekstra svaralternativer som er feil, for å gjøre oppgaven vanskeligere. Bruk stjerne (*) på samme måten som for korrekte svar i teksten."\n    },\n    {\n      "label": "Tilbakemelding på hele oppgaven",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Forhåndsinnstilling"\n            }\n          ],\n          "label": "Opprett poengområder og legg inn tilbakemeldinger.",\n          "description": "Klikk på knappen \\"Legg til poengområde\\" og legg til så mange poengområder du trenger. Eksempel: 0–40 % Svakt resultat, 41–80 % Gjennomsnittlig resultat, 81–100 % Flott resultat!",\n          "entity": "Område",\n          "field": {\n            "fields": [\n              {\n                "label": "Poengområde"\n              },\n              {},\n              {\n                "label": "Tilbakemelding for definert poengområde",\n                "placeholder": "Skriv inn tilbakemelding."\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Navn på\\"Sjekk\\"-knapp",\n      "default": "Sjekk"\n    },\n    {\n      "label": "Navn på \\"Send inn\\"-knapp",\n      "default": "Send inn"\n    },\n    {\n      "label": "Navn på \\"Prøv igjen\\"-knapp",\n      "default": "Prøv igjen"\n    },\n    {\n      "label": "Navn på \\"Vis svar\\"-knapp",\n      "default": "Vis svar"\n    },\n    {\n      "label": "Merkelapp for nummerert slippsone",\n      "default": "Slippsone @index.",\n      "description": "Merking for tilgjengelighet. Skjermleser leser nummeret på slippsonen. Tilgjengelig variabel: @index"\n    },\n    {\n      "label": "Merkelapp for tom slippsone",\n      "default": "Slippsone @index er tom.",\n      "description": "Merking for tilgjengelighet. Skjermleser leser at slippsonen er tom."\n    },\n    {\n      "label": "Merkelapp: Slippsonen inneholder flyttbart element",\n      "default": "Slippsone @index inneholder flyttbart element @draggable.",\n      "description": "Merkelapp for tilgjengelighet. Skjermleser leser at slippsonen inneholder et flyttbart element."\n    },\n    {\n      "label": "Merkelapp for flyttbare elementer",\n      "default": "@index av @count flyttbare elementer",\n      "description": "Merking for tilgjengelighet. Skjermleser leser at dette er et flyttbart element. Tilgjengelige variabler: @index, @count"\n    },\n    {\n      "label": "Navn på \\"Vis tips\\"-knapp",\n      "default": "Vis tips",\n      "description": "Merking for tilgjengelighet. Skjermleser leser dette før selve tipset blir lest opp."\n    },\n    {\n      "label": "Skjermlesertekst ved riktig svar",\n      "default": "Riktig"\n    },\n    {\n      "label": "Skjermlesertekst ved feil svar",\n      "default": "Feil"\n    },\n    {\n      "label": "Tittel på bekreftelsesdialog om at bruker vil nullstille et flyttbart element",\n      "default": "Nullstill flyttbart element"\n    },\n    {\n      "label": "Tekst i bekreftelsesdialog når bruker vil nullstille et flyttbart element",\n      "default": "Er du sikker på at du vil nullstille dette elementet?"\n    },\n    {\n      "label": "Merkelapp for tilgjengelighet. Skjermleser sier at flytting har startet.",\n      "default": "Flyttbart element er tatt tak i."\n    },\n    {\n      "label": "Merkelapp for tilgjengelighet. Skjermleser sier at flytting er avbrutt.",\n      "default": "Flytting er avbrutt."\n    },\n    {\n      "label": "Merkelapp for tilgjengelighet. Skjermleser sier at svaret er korrekt.",\n      "default": "Riktig svar:"\n    },\n    {\n      "label": "Tittel på avsnittet som gir bruker tilbakemelding om riktige og feil svar",\n      "default": "Tilbakemelding"\n    },\n    {\n      "label": "Oppgaveinnstillinger",\n      "description": "Disse innstillingene lar deg bestemme hvordan oppgaven skal oppføre seg.",\n      "fields": [\n        {\n          "label": "Aktiver \\"Prøv igjen\\"-knapp"\n        },\n        {\n          "label": "Aktiver \\"Vis svar\\"-knapp"\n        },\n        {\n          "label": "Aktiver \\"Sjekk\\"-knapp"\n        },\n        {\n          "label": "Øyeblikkelig tilbakemelding"\n        }\n      ]\n    },\n    {\n      "label": "Tekstalternativ til resultatlinja for skjermleserbrukere",\n      "default": "Du fikk :num av :total poeng."\n    },\n    {\n      "label": "Merkelapp for \\"Sjekk\\"-knapp for assisterende teknologi",\n      "default": "Sjekk svar. Svara blir merket som riktig, feil eller ubesvart."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'nl', '{\n  "semantics": [\n    {\n      "label": "Media",\n      "fields": [\n        {\n          "label": "Type",\n          "description": "Optionele media, die boven de vraag wordt getoond."\n        },\n        {\n          "label": "Beeld zoomen uitschakelen"\n        }\n      ]\n    },\n    {\n      "label": "Taakomschrijving",\n      "description": "Beschrijf hoe de gebruiker de taak moet uitvoeren.",\n      "default": "Sleep de woorden naar de juiste vakken"\n    },\n    {\n      "label": "Tekst",\n      "placeholder": "*Amsterdam* is de hoofdstad van Nederland, *Brussel* is de hoofdstad van België en *Luxemburg* is de hoofdstad van Luxemburg. Alle steden liggen in de *Benelux:afkorting*.",\n      "important": {\n        "description": "<ul><li>Sleepbare woorden worden tussen asterisken (*) geplaatst.</li><li>Je kunt een tip toevoegen door een (:) voor de tiptekst te plaatsen.</li><li>Voor elk leeg veld is er slechts één juist woord van toepassing.</li><li>Je kunt feedback tonen als een opgave is afgerond. Gebruik ''\\\\+'' voor juiste en ''\\\\-'' voor onjuiste antwoorden.</li></ul>",\n        "example": "H5P-inhoud kan bewerkt worden via een *browser:Welk soort programma is Chrome?*. <br /> H5P inhoud is *interactief\\\\+Juist! \\\\-Onjuist, probeer opnieuw!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Algehele feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Standaard"\n            }\n          ],\n          "label": "Definieer aangepaste feedback voor elke scorereeks",\n          "description": "Druk op de \\"Voeg scorereeks\\"-knop om zoveel reeksen toe te voegen als nodig. Voorbeeld: 0-20% Onvoldoende, 21-91% Gemiddelde score, 91-100% Uitstekende score!",\n          "entity": "reeks",\n          "field": {\n            "fields": [\n              {\n                "label": "Scorereeks"\n              },\n              {},\n              {\n                "label": "Feedback voor de gedefinieerde scorereeks",\n                "placeholder": "Vul de feedback in"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Tekst voor \\"Controleer\\"-knop",\n      "default": "Controleer"\n    },\n    {\n      "label": "Tekst voor \\"Verzend\\"-knop",\n      "default": "Verzend"\n    },\n    {\n      "label": "Tekst voor \\"Opnieuw\\"-knop",\n      "default": "Opnieuw"\n    },\n    {\n      "label": "Tekst voor \\"Toon oplossing\\"-knop",\n      "default": "Toon oplossing"\n    },\n    {\n      "label": "Label van het genummerde neerzetgebied",\n      "default": "Neerzetgebied @index.",\n      "description": "Label gebruikt voor toegankelijkheid, waarbij de schermlezer het nummer van het neerzetgebied voorleest. Beschikbare variabele: @index"\n    },\n    {\n      "label": "Label van leeg neerzetgebied",\n      "default": "Neerzetgebied @index is leeg.",\n      "description": "Label gebruikt voor toegankelijkheid, waarbij de schermlezer leest dat het neerzetgebied leeg is"\n    },\n    {\n      "label": "Label neerzetgebied bevat",\n      "default": "Neerzetgebied @index bevat sleepbare @draggable.",\n      "description": "Label gebruikt voor toegankelijkheid, waarbij de schermlezer aangeeft dat het neerzetgebied een sleepbaar onderdeel bevat"\n    },\n    {\n      "label": "Label van sleepbare onderdelen",\n      "default": "@index van @count sleepbare onderdelen.",\n      "description": "Label gebruikt voor toegankelijkheid, waarbij de schermlezer opmerkt dat dit een sleepbaar element is. Beschikbare variabelen: @index, @count"\n    },\n    {\n      "label": "Schermlezer tekst voor juiste antwoord",\n      "default": "Toon tip",\n      "description": "Label gebruikt voor toegankelijkheid, waarbij de voorlezer dit voorleest voordat de tip wordt voorgelezen"\n    },\n    {\n      "label": "Schermlezer tekst voor juiste antwoord",\n      "default": "Juist!"\n    },\n    {\n      "label": "Schermlezer tekst voor onjuiste antwoord",\n      "default": "Onjuist!"\n    },\n    {\n      "label": "Titel van bevestigingsdialoog als gebruiker een sleepbaar onderdeel wil terugzetten",\n      "default": "Terugzetten"\n    },\n    {\n      "label": "Beschrijving voor bevestigingsdialoog waarbij gebruiker een sleepbaar element wil terugzetten",\n      "default": "Weet je zeker dat je dit neerzetgebied wilt terugzetten?"\n    },\n    {\n      "label": "Label gebruikt voor toegankelijkheid, waarbij de schermlezer aangeeft dat het slepen is gestart",\n      "default": "Sleepbaar onderdeel opgepakt."\n    },\n    {\n      "label": "Label gebruikt voor toegankelijkheid, waarbij de schermlezer aangeeft dat het slepen is geannuleerd",\n      "default": "Slepen geannuleerd."\n    },\n    {\n      "label": "Label gebruikt voor toegankelijkheid, waarbij de voorlezer aangeeft dat een tekst het juiste antwoord is",\n      "default": "Juist antwoord:"\n    },\n    {\n      "label": "Koptekst voor het onderdeel dat feedback bevat over juiste/onjuiste antwoorden",\n      "default": "Feedback"\n    },\n    {\n      "label": "Gedragsinstellingen.",\n      "description": "Met deze opties kun je bepalen hoe de taak zich gedraagt.",\n      "fields": [\n        {\n          "label": "Schakel \\"Opnieuw\\" in"\n        },\n        {\n          "label": "Schakel \\"Toon oplossing\\"-knop in"\n        },\n        {\n          "label": "Schakel \\"Controleer\\"-knop in"\n        },\n        {\n          "label": "Geef direct feedback"\n        }\n      ]\n    },\n    {\n      "label": "Tekstuele weergave van de scorebalk voor de gebruikers van de voorlezer",\n      "default": "Je hebt :num out van de :total punten"\n    },\n    {\n      "label": "Ondersteunende technologie label voor \\"Controleer\\"-knop",\n      "default": "Controleer de antwoorden. De antwoorden worden gemarkeerd als correct, incorrect, of niet-beantwoord."\n    },\n    {\n      "label": "Ondersteunende technologie label voor \\"Toon oplossing\\"-knop",\n      "default": "Toon de oplossing. De taak wordt gemarkeerd met de juiste oplossing."\n    },\n    {\n      "label": "Ondersteunende technologie label voor \\"Opnieuw\\"-knop",\n      "default": "Probeer de taak opnieuw. Reset alle antwoorden en start de taak opnieuw."\n    }\n  ]\n}\n'),
(19, 'nn', '{\n  "semantics": [\n    {\n      "label": "Medieelement",\n      "fields": [\n        {\n          "label": "Type",\n          "description": "Valfritt medieelement. Elementet vil bli plassert over spørsmålet."\n        },\n        {\n          "label": "Deaktiver zoomingfunksjon."\n        }\n      ]\n    },\n    {\n      "label": "Oppgåvebeskriving",\n      "description": "Forklar korleis brukaren skal løyse oppgåva.",\n      "default": "Dra orda inn i dei rette boksane"\n    },\n    {\n      "label": "Tekst",\n      "placeholder": "*Oslo* er hovudstaden i Noreg, *Stockholm* er hovudstaden i Sverige og *København* er hovudstaden i Danmark. Alle byane er lokaliserte i *Skandinavia:den nordlege delen av Europa*.",\n      "important": {\n        "description": "<ul><li>Flyttbare ord eller utttrykk markerer du med ein asterisk (*) føre og etter ordet/uttrykket.</li><li>Du kan også legge til eit hint ved å bruke kolon (:). Døme: *Skandinavia:den nordlege delen av Europa*.</li><li>Det finst berre eitt rett svar for kvar tekstboks.</li><li>Du kan legg til ei tilbakemelding som blir vist når oppgåva er fullført. Bruk''\\\\+'' for positiv og ''\\\\-'' for negativ tilbakemelding.</li></ul>",\n        "example": "H5P-innhald kan redigerast med ein *nettlesar:Kva slags program er Chrome?*.<br />H5P-innhald er *interaktivt\\\\+Rett!\\\\-Feil, prøv igjen*"\n      }\n    },\n    {\n      "label": "Feil svaralternativ",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Tilbakemelding på heile oppgåva",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Førehandsinnstilling"\n            }\n          ],\n          "label": "Opprett poengområde og legg inn tilbakemeldingar.",\n          "description": "Klikk på knappen \\"Legg til poengområde\\" og legg til så mange poengområde du treng. Døme: 0–40 % Svakt resultat, 41–80 % Gjennomsnittleg resultat, 81–100 % Flott resultat!",\n          "entity": "Område",\n          "field": {\n            "fields": [\n              {\n                "label": "Poengområde"\n              },\n              {},\n              {\n                "label": "Tilbakemelding for definert poengområde",\n                "placeholder": "Skriv inn tilbakemelding."\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Tekst for \\"Sjekk\\"-knapp",\n      "default": "Sjekk"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Text for \\"Retry\\" button",\n      "default": "Retry"\n    },\n    {\n      "label": "Tekst for \\"Fasit\\" knapp",\n      "default": "Fasit"\n    },\n    {\n      "label": "Nummerert slippsone merkelapp",\n      "default": "Slippsone @index.",\n      "description": "Label used for accessibility, where the Read speaker will read the index of a drop zone. Variable available: @index"\n    },\n    {\n      "label": "Tom slippsone merkelapp",\n      "default": "Slippsone @index er tom.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone is empty"\n    },\n    {\n      "label": "Contains Drop Zone label",\n      "default": "Slippsone @index inneheld dragbar @draggable.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone contains a draggable"\n    },\n    {\n      "label": "Nummerert merkelapp for element som kan dras",\n      "default": "@index av @count dragbare.",\n      "description": "Label used for accessibility, where the Read speaker reads that this is a draggable element. Variable available: @index, @count"\n    },\n    {\n      "label": "Ingen slippsone valg-merkelapp",\n      "default": "Vis tips",\n      "description": "Label used for accessibility, where the Read speaker reads it before the tip is read out"\n    },\n    {\n      "label": "Readspeaker tekst for korrekt svar",\n      "default": "Riktig"\n    },\n    {\n      "label": "Readspeaker tekst for feil svar",\n      "default": "Feil"\n    },\n    {\n      "label": "Bekreftelsesdialogtittel om at brukeren vil nullstille et flyttbart element",\n      "default": "Nullstill flyttbart element"\n    },\n    {\n      "label": "Bekreftelsesdialogbeskrivelse om at brukeren vil nullstille et flyttbart element",\n      "default": "Er du sikker på at du vil nullstille dette elementet?"\n    },\n    {\n      "label": "Merkelapp for universal utforming, når brukeren indikerer at dragning har startet",\n      "default": "Dragbar er gripe."\n    },\n    {\n      "label": "LMerkelapp for universal utforming, når brukeren indikerer at dragnig er avbrutt",\n      "default": "Dragning avbrutt."\n    },\n    {\n      "label": "Merkelapp for korrekt svar",\n      "default": "Svar:"\n    },\n    {\n      "label": "Merkelapp for feil svar",\n      "default": "Tilbakemelding"\n    },\n    {\n      "label": "Innstillinger for oppgave-åtferd",\n      "description": "Disse instillingene lar deg bestemme hvordan oppgavetypen skal oppføre seg.",\n      "fields": [\n        {\n          "label": "Aktiver \\"Prøv igjen\\"-knapp"\n        },\n        {\n          "label": "Aktiver \\"Fasit\\" knapp"\n        },\n        {\n          "label": "Enable \\"Check\\" button"\n        },\n        {\n          "label": "Instant feedback"\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "Du fekk :num av :total poeng"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'pl', '{\n  "semantics": [\n    {\n      "label": "Media",\n      "fields": [\n        {\n          "label": "Typ",\n          "description": "Opcjonalne zdjęcie lub wideo ponad treścią pytania."\n        },\n        {\n          "label": "Zablokuj możliwość powiększania zdjęcia"\n        }\n      ]\n    },\n    {\n      "label": "Opis zadania",\n      "description": "Opisz sposób rozwiązania zadania.",\n      "default": "Przeciągnij słowa w odpowiednie miejsca"\n    },\n    {\n      "label": "Treść",\n      "placeholder": "*Oslo* jest stolicą Norwegii, *Sztokholm* jest stolicą Szwecji, a *Kopenhaga* jest stolicą Danii. Wszystkie te miasta leżą w *Skandynawii:Północnej Europie*.",\n      "important": {\n        "description": "<ul><li>Słowa, które należy przenieść, powinny być oznakowane gwiazdką (*) z obu stron i muszą pasować gramatycznie do zdania.</li><li>Możesz też dodać podpowiedź po dwukropku (:).</li><li>Do każdego pustego miejsca pasuje tylko jeden element przeciągalny.</li><li>Możesz dodać komentarz, który wyświetli się po ukończeniu zadania. Wpisz go po ''\\\\+'' (komentarz do odpowiedzi poprawnej) lub po ''\\\\-'' (komentarz do odpowiedzi błędnej).</li></ul>",\n        "example": "Zasoby H5P można tworzyć w *przeglądarce:Na przykład Google Chrome.*. <br /> Zasoby H5P są *interaktywne\\\\+Dobrze! \\\\-Ależ nie, popraw odpowiedź!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Podsumowanie odpowiedzi",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Domyślne"\n            }\n          ],\n          "label": "Określ własne kryteria oceny dla wybranych zakresów poprawnych odpowiedzi",\n          "description": "Klikając przycisk \\"Dodaj zakres\\" możesz dodać tyle zakresów, ile potrzebujesz. Przykład: 0-20% Słaby wynik, 21-91% Przeciętny wynik, 91-100% Bardzo dobry wynik!",\n          "entity": "zakres",\n          "field": {\n            "fields": [\n              {\n                "label": "Zakres"\n              },\n              {},\n              {\n                "label": "Komunikat dla danego zakresu",\n                "placeholder": "Wprowadź komunikat"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Etykieta przycisku sprawdzania odpowiedzi",\n      "default": "Sprawdź"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Etykieta przycisku ponowienia próby odpowiedzi",\n      "default": "Powtórz"\n    },\n    {\n      "label": "Etykieta przycisku pokazywania poprawnej odpowiedzi",\n      "default": "Pokaż odpowiedź"\n    },\n    {\n      "label": "Etykieta numerowanego pola odpowiedzi",\n      "default": "Pole @index.",\n      "description": "Etykieta używana przez czytniki ekranu. Informuje użytkownika, które pole jest aktywne. Użyj zmiennej @index, aby wstawić numer pola."\n    },\n    {\n      "label": "Etykieta pustego pola odpowiedzi",\n      "default": "Pole @index jest puste.",\n      "description": "Etykieta używana przez czytniki ekranu. Informuje użytkownika, że aktywne pole jest puste."\n    },\n    {\n      "label": "Etykieta niepustego pola odpowiedzi",\n      "default": "Pole @index zawiera element @draggable.",\n      "description": "Etykieta używana przez czytniki ekranu. Informuje użytkownika, że aktywne pole zawiera już element @draggable."\n    },\n    {\n      "label": "Etykieta elementu przeciągalnego",\n      "default": "@index z @count elementów.",\n      "description": "Etykieta używana przez czytniki ekranu. Informuje użytkownika, że aktywny jest element przeciągalny. Możesz użyć zmiennych: @index, @count"\n    },\n    {\n      "label": "Etykieta przycisku podpowiedzi",\n      "default": "Pokaż podpowiedź",\n      "description": "Etykieta używana przez czytniki ekranu. Informuje użytkownika, że zaraz zostanie przeczytana podpowiedź."\n    },\n    {\n      "label": "Komunikat głosowy dla poprawnej odpowiedzi",\n      "default": "Dobrze!"\n    },\n    {\n      "label": "Komunikat głosowy dla błędnej odpowiedzi",\n      "default": "Źle!"\n    },\n    {\n      "label": "Tytuł okienka z potwierdzeniem wyczyszczenia pola odpowiedzi",\n      "default": "Wyczyść pole"\n    },\n    {\n      "label": "Tekst okienka z potwierdzeniem wyczyszczenia pola odpowiedzi",\n      "default": "Czy na pewno wyczyścić to pole?"\n    },\n    {\n      "label": "Etykieta używana przez czytniki ekranu. Informuje użytkownika, że element przeciągalny został podniesiony",\n      "default": "Element podniesiony."\n    },\n    {\n      "label": "Etykieta używana przez czytniki ekranu. Informuje użytkownika, że przeciąganie zostało przerwane.",\n      "default": "Przeciąganie przerwane."\n    },\n    {\n      "label": "Etykieta używana przez czytniki ekranu. Informuje użytkownika, że jaka odpowiedź jest poprawna.",\n      "default": "Poprawna odpowiedź:"\n    },\n    {\n      "label": "Nagłówek sekcji komentarzy do poprawnych i niepoprawnych odpowiedzi.",\n      "default": "Podsumowanie"\n    },\n    {\n      "label": "Ustawienia zachowania",\n      "description": "Te opcje pozwalają określić, jak ma przebiegać zadanie.",\n      "fields": [\n        {\n          "label": "Wyświetl przycisk \\"Powtórz\\""\n        },\n        {\n          "label": "Wyświetl przycisk \\"Pokaż odpowiedź\\""\n        },\n        {\n          "label": "Wyświetl przycisk \\"Sprawdź\\""\n        },\n        {\n          "label": "Natychmiastowy komentarz"\n        }\n      ]\n    },\n    {\n      "label": "Tekstowy odpowiednik paska wyniku dla czytników ekranu",\n      "default": "Masz :num z :total punktów"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'pt', '{\n  "semantics": [\n    {\n      "label": "Mídia",\n      "fields": [\n        {\n          "label": "Tipo",\n          "description": "Mídia opcional para exibir acima da pergunta."\n        },\n        {\n          "label": "Desactivar o zoom da imagem"\n        }\n      ]\n    },\n    {\n      "label": "Descrição da tarefa",\n      "description": "Descreva a forma como o utilizador deve completar a atividade.",\n      "default": "Arraste as palavras para as caixas corretas"\n    },\n    {\n      "label": "Mensagem",\n      "placeholder": "*Oslo* é a capital da Noruega, *Estocolmo* é a capital da Suécia e *Copenhaga* é a capital da Dinamarca. Todas as cidades estão localizadas na península *Escandinava:Norte da Europa*.",\n      "important": {\n        "description": "<ul><li>Adicione as palavras a largar através de um asterisco (*) no início e no fim da palavra/frase correta.</li><li>Adicione uma dica contextual utilizando os dois pontos (:) à frente do texto da dica.</li><li>Para todos os espaços existe apenas uma palavra correta</li><li>Pode adicionar feedback quando o utilizador completar a atividade. Utilize ''\\\\+'' para feedback correto e ''\\\\-'' para feedback incorreto.</li></ul>",\n        "example": "O conteúdo H5P pode ser editado utilizando um *navegador:Qual o tipo de programa é o Chrome?*.<br /> O conteúdo H5P é *interativo\\\\+Correto! \\\\-Incorreto, tente de novo!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Feedback global",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Padrão"\n            }\n          ],\n          "label": "Defina o feedback personalizado para qualquer faixa de pontuação",\n          "description": "Clique em \\"Adicionar faixa\\" e adicione quantas faixas forem necessárias. Exemplo: 0-20% Insuficiente, 21-91% Suficiente, 91-100% Excelente!",\n          "entity": "faixa",\n          "field": {\n            "fields": [\n              {\n                "label": "Faixa de pontuação"\n              },\n              {},\n              {\n                "label": "Feedback para determinada faixa de pontuação",\n                "placeholder": "Preencha o feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texto para o botão \\"Verificar resposta\\"",\n      "default": "Verificar resposta"\n    },\n    {\n      "label": "Texto para o botão \\"Enviar\\"",\n      "default": "Enviar"\n    },\n    {\n      "label": "Texto para o botão \\"Repetir\\"",\n      "default": "Repetir"\n    },\n    {\n      "label": "Texto para o botão \\"Mostrar soluções\\"",\n      "default": "Mostrar solução"\n    },\n    {\n      "label": "Etiqueta para zona de largar numerada",\n      "default": "Zona de largar @index.",\n      "description": "Etiqueta utilizada para acessibilidade, onde o leitor de ecrã lê o índice da zona de largar. Variável disponível: @index"\n    },\n    {\n      "label": "Etiqueta para zona de largar vazia",\n      "default": "Zona de largar @index está vazia.",\n      "description": "Etiqueta utilizada para acessibilidade, onde o leitor de ecrã lê que a zona de largar está vazia"\n    },\n    {\n      "label": "Etiqueta para zona de largar com conteúdos",\n      "default": "Zona de largar @index contém o item @draggable.",\n      "description": "Etiqueta utilizada para acessibilidade, onde o leitor de ecrã lê que a zona de largar contém um elemento"\n    },\n    {\n      "label": "Etiqueta para elementos arrastáveis",\n      "default": "@index de @count elementos.",\n      "description": "Etiqueta utilizada para acessibilidade, onde o leitor de ecrã lê que este é um elemento arrastável. Variáveis disponíveis: @index, @count"\n    },\n    {\n      "label": "Etiqueta para o botão de mostrar dica",\n      "default": "Mostrar dica",\n      "description": "Etiqueta utilizada para acessibilidade, onde o leitor de ecrã lê que existe uma dica antes de a mostrar"\n    },\n    {\n      "label": "Texto do leitor de ecrã para resposta correta",\n      "default": "Correto!"\n    },\n    {\n      "label": "Texto do leitor de ecrã para resposta incorreta",\n      "default": "Incorreto!"\n    },\n    {\n      "label": "Texto da caixa de diálogo de confirmação para reinicio dos elementos",\n      "default": "Repor elemento arrastável"\n    },\n    {\n      "label": "Descrição da caixa de diálogo de confirmação para reinicio dos elementos",\n      "default": "Tem a certeza que pretende repor esta zona de largar ao seu estado original?"\n    },\n    {\n      "label": "Etiqueta utilizada para acessibilidade, onde o leitor de ecrã indica que uma ação de arrasto foi iniciada",\n      "default": "Um elemento foi agarrado."\n    },\n    {\n      "label": "Etiqueta utilizada para acessibilidade, onde o leitor de ecrã indica que o arrastamento foi cancelado",\n      "default": "Arrastamento cancelado."\n    },\n    {\n      "label": "Etiqueta utilizada para acessibilidade, onde o leitor de ecrã indica que o texto é uma resposta correta",\n      "default": "Resposta correta:"\n    },\n    {\n      "label": "Cabeçalho para o painel que contém feedback das respostas corretas/incorretas",\n      "default": "Feedback"\n    },\n    {\n      "label": "Configurações gerais.",\n      "description": "Estas opções permitem controlar o comportamento da atividade.",\n      "fields": [\n        {\n          "label": "Ativar \\"Repetir\\""\n        },\n        {\n          "label": "Ativar botão de \\"Mostrar Solução\\""\n        },\n        {\n          "label": "Ativar botão de \\"Verificar\\""\n        },\n        {\n          "label": "Feedback imediato"\n        }\n      ]\n    },\n    {\n      "label": "Representação textual da barra de pontuação para aqueles que usam leitores de ecrã",\n      "default": "Conseguiu :num pontos de um total de :total"\n    },\n    {\n      "label": "Etiqueta de tecnologia assistiva para o botão \\"Verificar\\"",\n      "default": "Verifique as respostas. As respostas serão marcadas como corretas, incorretas ou sem resposta."\n    },\n    {\n      "label": "Etiqueta de tecnologia assistiva para o botão \\"Mostrar solução\\"",\n      "default": "Mostrar a solução. A atividade será marcada com a respetiva solução correta."\n    },\n    {\n      "label": "Etiqueta de tecnologia assistiva para o botão \\"Repetir\\"",\n      "default": "Repetir a atividade. Apagar todas as respostas e reiniciar a atividade."\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(19, 'pt-br', '{\n  "semantics": [\n    {\n      "label": "Mídia",\n      "fields": [\n        {\n          "label": "Tipo",\n          "description": "Mídia opcional para exibir acima da pergunta."\n        },\n        {\n          "label": "Desativar o zoom da imagem"\n        }\n      ]\n    },\n    {\n      "label": "Descrição da tarefa",\n      "description": "Descreva como o usuário deve resolver a tarefa.",\n      "default": "Arraste as palavras para os campos corretos"\n    },\n    {\n      "label": "Texto",\n      "placeholder": "*Oslo* é a capital da Noruega, *Estocolmo* é a capital da Suécia e *Copenhague* é a capital da Dinamarca. Todas estas cidades estão localizadas na península *Escandinava:Parte norte da Europa*.",\n      "important": {\n        "description": "<ul><li>Palavras arrastáveis são adicionadas com um asterisco(*) na antes e um depois da palavra/frase correta.</li><li>Você pode adicionar uma dica textual usando dois pontos (:) antes da dica.</li><li>Para cada espaço vazio há apenas uma palavra correta.</li><li>Você pode dar feedback para ser exibido quando uma tarefa for completada. Use ''\\\\+'' para feedback correto e ''\\\\-'' para feedback incorreto.</li></ul>",\n        "example": "Conteúdo H5P pode ser editado usando um *navegador:QUe tipo de programa é o Chrome?*. <br /> Conteúdo H5P é *interativo\\\\+Correto! \\\\-Incorreto, tente novamente!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Feedback Geral",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Padrão"\n            }\n          ],\n          "label": "Definir feedback personalizado para qualquer faixa de pontuação",\n          "description": "Clique no botão \\"Adicionar faixa\\" para adicionar quantos intervalos você precisar. Exemplo: 0-20% Pontuação Ruim, 21-91% Pontuação Média, 91-100% Pontuação Ótima!",\n          "entity": "faixa",\n          "field": {\n            "fields": [\n              {\n                "label": "Faixa de Pontuação"\n              },\n              {},\n              {\n                "label": "Feedback para a faixa de pontuação definida",\n                "placeholder": "Preencha o feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texto do botão \\"Verificar \\"",\n      "default": "Verificar"\n    },\n    {\n      "label": "Texto do botão \\"Enviar\\"",\n      "default": "Enviar"\n    },\n    {\n      "label": "Texto para o botão \\"Tentar Novamente\\"",\n      "default": "Tentar Novamente"\n    },\n    {\n      "label": "Texto do botão \\"Mostrar Solução\\"",\n      "default": "Mostrar solução"\n    },\n    {\n      "label": "Rótulo da Zona de soltura numerada",\n      "default": "Zona de Soltura @index.",\n      "description": "Rótulo usado para acessibilidade, o leitor de tela lerá o índice da zona de soltura. Variáveis disponíveis: @index"\n    },\n    {\n      "label": "Rótulo de Zona de Soltura vazia",\n      "default": "A Zona de Soltura @index está vazia.",\n      "description": "Rótulo usado para acessibilidade, o leitor de tela lerá caso a zona de soltura esteja vazia"\n    },\n    {\n      "label": "Rótulo do Conteúdo da Zona de Soltura",\n      "default": "Zona de soltura @index contém o elemento arrastável @draggable.",\n      "description": "Rótulo usado para acessibilidade, onde leitor de tela lerá que a zona de queda contém um elemento arrastável"\n    },\n    {\n      "label": "Rótulo de elementos arrastáveis",\n      "default": "@index de @count elementos arrastáveis.",\n      "description": "Rótulo usado para acessibilidade, o leitor de tela lerá este texto se for um elemento arrastável. Variáveis disponíveis: @index, @count"\n    },\n    {\n      "label": "Rótulo para o botão de Mostrar Dica",\n      "default": "Mostrar dica",\n      "description": "Rótulo usado para acessibilidade, o leitor de tela lerá isto antes da dica ser lida"\n    },\n    {\n      "label": "Texto de resposta correta para leitores de tela",\n      "default": "Correto!"\n    },\n    {\n      "label": "Texto de resposta correta para leitores de tela",\n      "default": "Incorreto!"\n    },\n    {\n      "label": "Título do diálogo de confirmação que o usuário deseja redefinir um elemento arrastável",\n      "default": "Redefinir elemento arrastável"\n    },\n    {\n      "label": "Descrição do diálogo de confirmação que o usuário deseja redefinir um elemento arrastável",\n      "default": "Você tem certeza que deseja redefinir esta zona de soltura?"\n    },\n    {\n      "label": "Rótulo usado para acessibilidade, onde o leitor de tela indicará quando o arrastamento é iniciado",\n      "default": "O elemento arrastável foi agarrado."\n    },\n    {\n      "label": "Rótulo usado para acessibilidade, onde o leitor de tela indica que o arrastamento foi cancelado",\n      "default": "Arrastamento cancelado."\n    },\n    {\n      "label": "Rótulo usado para acessibilidade, onde o leitor de tela indica que um texto é a resposta correta",\n      "default": "Resposta correta:"\n    },\n    {\n      "label": "Cabeçalho para painel contendo feedback para respostas corretas/incorretas",\n      "default": "Feedback"\n    },\n    {\n      "label": "Configurações comportamentais.",\n      "description": "Estas opções permitirão que você controle como a tarefa se comporta.",\n      "fields": [\n        {\n          "label": "Ativar \\"Tentar Novamente\\""\n        },\n        {\n          "label": "Ativar o botão \\"Mostrar Solução\\""\n        },\n        {\n          "label": "Ativar o botão \\"Verificar\\""\n        },\n        {\n          "label": "Feedback instantâneo"\n        }\n      ]\n    },\n    {\n      "label": "Representação textual da barra de pontuação para aqueles que usam leitores de tela",\n      "default": "Você conseguiu :num de :total pontos possíveis"\n    },\n    {\n      "label": "Rótulo de tecnologia de assistência para botão \\"Verificar\\"",\n      "default": "Verifique as respostas. As respostas serão marcadas como corretas, incorretas, ou sem resposta."\n    },\n    {\n      "label": "Rótulo de tecnologia de assistência para o botão \\"Mostrar Solução\\"",\n      "default": "Mostrar a solução. A tarefa será marcada com sua solução correta."\n    },\n    {\n      "label": "Rótulo de tecnologia de assistência para o botão \\"Tentar Novamente\\"",\n      "default": "Tente realizar a tarefa novamente. Reinicialize todas as respostas e recomece."\n    }\n  ]\n}\n'),
(19, 'ro', '{\n  "semantics": [\n    {\n      "label": "Media",\n      "fields": [\n        {\n          "label": "Type",\n          "description": "Optional media to display above the question."\n        },\n        {\n          "label": "Disable image zooming"\n        }\n      ]\n    },\n    {\n      "label": "Task description",\n      "description": "Describe how the user should solve the task.",\n      "default": "Drag the words into the correct boxes"\n    },\n    {\n      "label": "Text",\n      "placeholder": "*Oslo* is the capital of Norway, *Stockholm* is the capital of Sweden and *Copenhagen* is the capital of Denmark. All cities are located in the *Scandinavian:Northern Part of Europe* peninsula.",\n      "important": {\n        "description": "<ul><li>Droppable words are added with an asterisk (*) in front and behind the correct word/phrase.</li><li>You may add a textual tip, using a colon (:) in front of the tip.</li><li>For every empty spot there is only one correct word.</li><li>You may add feedback to be displayed when a task is completed. Use ''\\\\+'' for correct and ''\\\\-'' for incorrect feedback.</li></ul>",\n        "example": "H5P content may be edited using a *browser:What type of program is Chrome?*. <br /> H5P content is *interactive\\\\+Correct! \\\\-Incorrect, try again!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Default"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text for \\"Check\\" button",\n      "default": "Check"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Text for \\"Retry\\" button",\n      "default": "Retry"\n    },\n    {\n      "label": "Text for \\"Show Solution\\" button",\n      "default": "Show solution"\n    },\n    {\n      "label": "Numbered Drop zone label",\n      "default": "Drop Zone @index.",\n      "description": "Label used for accessibility, where the Read speaker will read the index of a drop zone. Variable available: @index"\n    },\n    {\n      "label": "Empty Drop Zone label",\n      "default": "Drop Zone @index is empty.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone is empty"\n    },\n    {\n      "label": "Contains Drop Zone label",\n      "default": "Drop Zone @index contains draggable @draggable.",\n      "description": "Label used for accessibility, where the Read speaker will read that the drop zone contains a draggable"\n    },\n    {\n      "label": "Draggable elements label",\n      "default": "@index of @count draggables.",\n      "description": "Label used for accessibility, where the Read speaker reads that this is a draggable element. Variable available: @index, @count"\n    },\n    {\n      "label": "Label for show tip button",\n      "default": "Show tip",\n      "description": "Label used for accessibility, where the Read speaker reads it before the tip is read out"\n    },\n    {\n      "label": "Readspeaker text for correct answer",\n      "default": "Correct!"\n    },\n    {\n      "label": "Readspeaker text for incorrect answer",\n      "default": "Incorrect!"\n    },\n    {\n      "label": "Confirmation dialog title that user wants to reset a droppable",\n      "default": "Reset drop"\n    },\n    {\n      "label": "Confirmation dialog description that user wants to reset a droppable",\n      "default": "Are you sure you want to reset this drop zone?"\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is initiated",\n      "default": "Draggable is grabbed."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that dragging is canceled",\n      "default": "Cancelled dragging."\n    },\n    {\n      "label": "Label used for accessibility, where the read speaker indicates that a text is the correct answer",\n      "default": "Correct answer:"\n    },\n    {\n      "label": "Header for panel containing feedback for correct/incorrect answers",\n      "default": "Feedback"\n    },\n    {\n      "label": "Behavioural settings.",\n      "description": "These options will let you control how the task behaves.",\n      "fields": [\n        {\n          "label": "Enable \\"Retry\\""\n        },\n        {\n          "label": "Enable \\"Show Solution\\" button"\n        },\n        {\n          "label": "Enable \\"Check\\" button"\n        },\n        {\n          "label": "Instant feedback"\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(19, 'ru', '{\n  "semantics": [\n    {\n      "label": "Медиа",\n      "fields": [\n        {\n          "label": "Тип",\n          "description": "Дополнительное медиа для отображения над вопросом."\n        },\n        {\n          "label": "Отключить масштабирование изображения"\n        }\n      ]\n    },\n    {\n      "label": "Описание задачи",\n      "description": "Опишите, как пользователь должен решить задачу.",\n      "default": "Перетащите слова в правильные поля"\n    },\n    {\n      "label": "Текст",\n      "placeholder": "*Осло* столица Норвегии, *Стокгольм* столица Швеции и *Копенгаген* столица Дании. Все города расположены в *Скандинавии:Северной части Европы*.",\n      "important": {\n        "description": "<ul><li>Пропущенные слова добавляются со звездочкой (*) спереди и сзади правильного слова/фразы.</li><li>Вы можете добавить текстовую подсказку, используя двоеточие (:) перед подсказкой.</li><li>Для каждого пустого места есть только одно правильное слово.</li><li>Вы можете добавить отзыв, который будет отображаться после завершения задачи. Используйте ''\\\\+'' для правильного и ''\\\\-'' для неправильного отзыва.</li></ul>",\n        "example": "H5P content may be edited using a *browser:What type of program is Chrome?*. <br /> H5P content is *interactive\\\\+Верно! \\\\-Неверно, попробуйте еще раз!*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Общий отзыв",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "По умолчанию"\n            }\n          ],\n          "label": "Определите произвольный отзыв для любого диапазона оценок",\n          "description": "Нажмите на кнопку \\"Добавить диапазон\\" чтобы добавить столько диапазонов, сколько вам нужно. Например: 0-20% Плохая оценка, 21-91% Средняя оценка, 91-100% Отличная оценка!",\n          "entity": "диапазон",\n          "field": {\n            "fields": [\n              {\n                "label": "Диапазон баллов"\n              },\n              {},\n              {\n                "label": "Обратная связь для определенного диапазона оценок",\n                "placeholder": "Заполните отзыв"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Текст для кнопки \\"Проверить\\"",\n      "default": "Проверить"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Текст для кнопки \\"Повторить\\"",\n      "default": "Повторить"\n    },\n    {\n      "label": "Текст для кнопки \\"Показать решение\\"",\n      "default": "Показать решение"\n    },\n    {\n      "label": "Пронумерованная надпись области размещения",\n      "default": "Область размещения @index.",\n      "description": "Надпись, используемая для доступности, где озвучка текста прочтет индекс области размещения. Доступная переменная: @index"\n    },\n    {\n      "label": "Надпись пустой области размещения",\n      "default": "Область размещения @index пустая.",\n      "description": "Надпись, используемая для доступности, где озвучка текста прочтет что область размещения пустая."\n    },\n    {\n      "label": "Надпись содержащей области размещения",\n      "default": "Область размещения @index содержит перетаскиваемый @draggable.",\n      "description": "Надпись, используемая для доступности, где озвучка текста прочтет что область размещения содержит перетаскиваемый элемент"\n    },\n    {\n      "label": "Надпись перетаскиваемых элементов",\n      "default": "@index из @count перетаскиваемых.",\n      "description": "Надпись, используемая для доступности, где озвучка текста прочтет что это перетаскиваемый элемент. Доступные переменные: @index, @count"\n    },\n    {\n      "label": "Надпись для кнопки показа подсказки",\n      "default": "Показать подсказку",\n      "description": "Надпись, используемая для доступности, где озвучка текста прочтет это до прочтения подсказки"\n    },\n    {\n      "label": "Озвучка текста для правильного ответа",\n      "default": "Верно!"\n    },\n    {\n      "label": "Озвучка текста для неправильного ответа",\n      "default": "Неверно!"\n    },\n    {\n      "label": "Заголовок диалогового окна подтверждения, что пользователь хочет перезагрузить сброс",\n      "default": "Перезагрузить сброс"\n    },\n    {\n      "label": "Заголовок диалогового окна подтверждения, когда пользователь хочет сбросить размещение элемента",\n      "default": "Вы действительно хотите сбросить эту область размещения?"\n    },\n    {\n      "label": "Надпись, используемая для доступности, где озвучка текста укажет, что перетаскивание начато",\n      "default": "Перетаскиваемый элемент захвачен."\n    },\n    {\n      "label": "Надпись, используемая для доступности, где озвучка текста укажет, что перетаскивание отменено",\n      "default": "Перетаскивание отменено."\n    },\n    {\n      "label": "Надпись, используемая для доступности, где озвучка текста укажет, что получен правильный ответ",\n      "default": "Правильный ответ:"\n    },\n    {\n      "label": "Заголовок панели, содержащей обратную связь для правильных/неправильных ответов",\n      "default": "Обратная связь"\n    },\n    {\n      "label": "Настройки поведения.",\n      "description": "Эти параметры позволят вам контролировать поведение задачи.",\n      "fields": [\n        {\n          "label": "Включить кнопку \\"Повторить\\""\n        },\n        {\n          "label": "Включить кнопку \\"Показать решение\\""\n        },\n        {\n          "label": "Включить кнопку \\"Проверить\\""\n        },\n        {\n          "label": "Мгновенная обратная связь"\n        }\n      ]\n    },\n    {\n      "label": "Текстовое представление оценки для тех, кто использует озвучку текста",\n      "default": "Вы получили :num из :total баллов"\n    },\n    {\n      "label": "Ярлык вспомогательной технологии (озвучки) для кнопки \\"Проверить\\"",\n      "default": "Проверьте ответы. Ответы будут помечены как правильные, неправильные или оставшиеся без ответа."\n    },\n    {\n      "label": "Ярлык вспомогательной технологии (озвучки) для кнопки \\"Показать решение\\"",\n      "default": "Показать решение. Задача будет содержать правильное решение."\n    },\n    {\n      "label": "Ярлык вспомогательной технологии для кнопки \\"Повторить\\"",\n      "default": "Повторить попытку. Сбросить все ответы и запустить задачу заново."\n    }\n  ]\n}\n'),
(19, 'sl', '{\n  "semantics": [\n    {\n      "label": "Mediji",\n      "fields": [\n        {\n          "label": "Tip",\n          "description": "Neobvezna nastavitev dodatnega medija za prikaz nad vprašanjem."\n        },\n        {\n          "label": "Onemogoči povečavo slike"\n        }\n      ]\n    },\n    {\n      "label": "Navodilo udeležencem",\n      "description": "Opis reševanja zadane naloge.",\n      "default": "Povleci besede na pravilna mesta"\n    },\n    {\n      "label": "Besedilo naloge",\n      "placeholder": "Oslo je glavno mesto *Norveške*. Helsinki so glavno mesto *Finske*.",\n      "important": {\n        "description": "<ul><li>Besede za premikanje se označi z zvezdico (*) pred in za pravilno besedo/besedno zvezo.</li><li>Namig za udeležence se od odgovora loči z dvopičjem (:).</li><li>Za vsak prazen okvir je na razpolago le ena pravilna beseda.</li><li>Možno je dodati tudi povratno informacijo, ki se pokaže po zaključku naloge. Dodan zapis ''\\\\+'' pomeni pravilen, ''\\\\-'' pa nepravilen odgovor.</li></ul>",\n        "example": "Za brskanje po spletu lahko uporabimo *spletni brskalnik:Takšen program je na primer Chrome*. Vsebina H5P je *interaktivna\\\\+Pravilno!\\\\-Nepravilno. Poskusi ponovno.*"\n      }\n    },\n    {\n      "label": "Distractors",\n      "placeholder": "*Reykjavík* *Helsinki*",\n      "description": "Enter extra solutions that are wrong as distractors. Use the same asterisk (*) scheme as for the text."\n    },\n    {\n      "label": "Splošna povratna informacija",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Privzeto"\n            }\n          ],\n          "label": "Določi ločeno povratno informacijo za vsak razpon rezultatov",\n          "description": "Kliknite gumb \\"Dodaj razpon\\" za dodajanje dodatnih razponov. Primer: 0-20 % Slab rezultat, 21-91 % Povprečen rezultat, 91-100 % Odličen rezultat!",\n          "entity": "razpon",\n          "field": {\n            "fields": [\n              {\n                "label": "Razpon rezultatov"\n              },\n              {},\n              {\n                "label": "Povratna informacija za definiran razpon rezultatov",\n                "placeholder": "Vnesite povratno informacijo"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Besedilo za gumb \\"Preveri\\"",\n      "default": "Preveri"\n    },\n    {\n      "label": "Text for \\"Submit\\" button",\n      "default": "Submit"\n    },\n    {\n      "label": "Besedilo za gumb \\"Poskusi ponovno\\"",\n      "default": "Poskusi ponovno"\n    },\n    {\n      "label": "Besedilo za gumb \\"Prikaži rešitev\\"",\n      "default": "Prikaži rešitev"\n    },\n    {\n      "label": "Besedilo za oštevilčeno spustno polje",\n      "default": "Spustno polje @index.",\n      "description": "Besedilo, ki ga bralnik zaslona uporabi za razlikovanje spustnih polj. Spremenljivka: @index"\n    },\n    {\n      "label": "Besedilo praznega spustnega polja",\n      "default": "Spustno polje @index je prazno.",\n      "description": "Besedilo, ki ga bralnik zaslona uporabi za prazno spustno polje. Spremenljivka: @index"\n    },\n    {\n      "label": "Besedilo zapolnjenega spustnega polja",\n      "default": "Spustno polje @index vsebuje element @draggable.",\n      "description": "Besedilo, ki ga bralnik zaslona uporabi za povezavo spustnega polja z izbranim elementom."\n    },\n    {\n      "label": "Besedilo elementa za premik",\n      "default": "Element za premik: @index od @count.",\n      "description": "Besedilo, s katerim bralnik zaslona označi element za premikanje. Spremenljivki: @index, @count"\n    },\n    {\n      "label": "Besedilo gumba za prikaz namiga",\n      "default": "Pokaži namig",\n      "description": "Besedilo, ki ga bralnik zaslona uporabi za izražanje dosegljivosti namiga."\n    },\n    {\n      "label": "Besedilo za pravilni odgovor za bralnik zaslona",\n      "default": "Pravilno!"\n    },\n    {\n      "label": "Besedilo za nepravilni odgovor za bralnik zaslona",\n      "default": "Nepravilno!"\n    },\n    {\n      "label": "Naslov potrditvenega okna za ponastavitev spusta elementa",\n      "default": "Ponastavi spust elementa"\n    },\n    {\n      "label": "Besedilo potrditvenega okna za ponastavitev spusta elementa",\n      "default": "Ponastavim spustno polje?"\n    },\n    {\n      "label": "Besedilo, s katerim bralnik zaslona izrazi začetek premika elementa",\n      "default": "Element je na voljo za premik."\n    },\n    {\n      "label": "Besedilo, s katerim bralnik zaslona izrazi preklic premika elementa",\n      "default": "Premik elementa je preklican."\n    },\n    {\n      "label": "Besedilo, s katerim bralnik zaslona označi besedo kot pravilen odgovor",\n      "default": "Pravilen odgovor:"\n    },\n    {\n      "label": "Naslov sporočila povratne informacije o pravilnem/nepravilnem odgovoru",\n      "default": "Povratna informacija"\n    },\n    {\n      "label": "Nastavitve interakcije",\n      "description": "Nastavitve omogočajo nadzor nad interakcijo aktivnosti za udeležence.",\n      "fields": [\n        {\n          "label": "Omogoči gumb \\"Poskusi ponovno\\""\n        },\n        {\n          "label": "Omogoči gumb \\"Prikaži rešitev\\""\n        },\n        {\n          "label": "Omogoči gumb \\"Preveri\\""\n        },\n        {\n          "label": "Sprotno preverjaj odgovore"\n        }\n      ]\n    },\n    {\n      "label": "Besedilo, ki ga bralnik zaslona uporabi za izražanje napredka",\n      "default": "Napredek :num od :total"\n    },\n    {\n      "label": "Assistive technology label for \\"Check\\" button",\n      "default": "Check the answers. The responses will be marked as correct, incorrect, or unanswered."\n    },\n    {\n      "label": "Assistive technology label for \\"Show Solution\\" button",\n      "default": "Show the solution. The task will be marked with its correct solution."\n    },\n    {\n      "label": "Assistive technology label for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
