(21, 'af', '{\n  "semantics": [\n    {\n      "label": "Vraagteks",\n      "description": "Die vraag op grond waarvan die gebruiker ''n keuse sal maak."\n    },\n    {\n      "label": "Keuses",\n      "entity": "keuse",\n      "field": {\n        "fields": [\n          {\n            "label": "Keuseteks",\n            "description": "Die etiket wat vertoon word op die keuseknoppie."\n          },\n          {\n            "label": "Gaan na",\n            "description": "Die teikentyd wat die gebruiker geneem het wanneer die keuse knoppie gedruk word. Voer tydkode in die formaat M:SS in."\n          },\n          {\n            "label": "Indien geskies teks",\n            "description": "''n Opsionele bevestigingsteks wat vertoon word nadat die gebruiker op die keuse-knoppie gedruk het."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Gaan voort knoppie-etiket",\n      "default": "Gaan voort"\n    }\n  ]\n}\n'),
(21, 'ar', '{\n  "semantics": [\n    {\n      "label":"نص السؤال",\n      "description":"السؤال الذي يحدده المستخدم يعتمد على."\n    },\n    {\n      "label":"الخيارات",\n      "entity":"choice",\n      "field":{\n        "fields":[\n          {\n            "label":"نص الخيار",\n            "description":"اللافتة التي سيتم عرضها على زر الخيار."\n          },\n          {\n            "label":"اذهب الى",\n            "description":"الوقت المطلوب الذي سيتم نقل المستخدم إليه عند الضغط على زر الخيار. أدخل رمز الوقت بالشكل M: SS."\n          },\n          {\n            "label":"نص اذا تم الاختيار",\n            "description":"نص التأكيد الاختياري الذي سيتم عرضه بعد أن يقوم المستخدم بالضغط على زر الاختيار."\n          }\n        ]\n      }\n    },\n    {\n      "label":"لافتة زر المتابعة",\n      "default":"Continue"\n    }\n  ]\n}\n'),
(21, 'bg', '{\r\n  "semantics": [\r\n    {\r\n      "label": "Текст на въпроса",\r\n      "description": "Въпросът, според който потребителят ще направи избор."\r\n    },\r\n    {\r\n      "label": "Възможности",\r\n      "entity": "избор",\r\n      "field": {\r\n        "fields": [\r\n          {\r\n            "label": "Текст за избор",\r\n            "description": "Етикетът ще се появи при избор на бутона."\r\n          },\r\n          {\r\n            "label": "Отиди на",\r\n            "description": "Целевото време, през което потребителят ще бъде отнесен при натискане на бутона за избор. Въведете времеви код във формат M: SS."\r\n          },\r\n          {\r\n            "label": "Ако е избран текст",\r\n            "description": "Незадължителен текст за потвърждение, който ще се покаже, след като потребителят е натиснал бутона за избор."\r\n          }\r\n        ]\r\n      }\r\n    },\r\n    {\r\n      "label": "етикет на бутона за продължение",\r\n      "default": "Продължи"\r\n    }\r\n  ]\r\n}\r\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(21, 'bs', '{\n  "semantics": [\n    {\n      "label": "Tekst pitanja",\n      "description": "Pitanje na temelju kojeg će korinik odabrati."\n    },\n    {\n      "label": "Opcije",\n      "entity": "opcija",\n      "field": {\n        "fields": [\n          {\n            "label": "Tekst opcije",\n            "description": "Tekst koji će stajati na dugmetu za opcije."\n          },\n          {\n            "label": "Idi na",\n            "description": "Ciljano vrijeme koje će korisnik koristiti kada klikne na dugme za opcije. Unesite vrijeme u formatu M:SS."\n          },\n          {\n            "label": "Tekst uvjetnog izbora",\n            "description": "Tekst koji će se pojaviti kada korisnik klikne na dugme za opcije. Nije obavezno."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Oznaka za dugme za nastavak",\n      "default": "Nastavi"\n    }\n  ]\n}'),
(21, 'ca', '{\n  "semantics": [\n    {\n      "label": "Text de la pregunta",\n      "description": "Pregunta en què l’usuari es basarà per fer la selecció."\n    },\n    {\n      "label": "Opcions",\n      "entity": "elecció",\n      "field": {\n        "fields": [\n          {\n            "label": "Text del botó de l’opció",\n            "description": "L’etiqueta que es mostrarà al botó de selecció."\n          },\n          {\n            "label": "Ves a",\n            "description": "Temps objectiu en el qual se situarà l’usuari en prémer el botó de selecció. Introduïu el codi de temps en format M:SS."\n          },\n          {\n            "label": "Text per quan es fa la selecció",\n            "description": "Un text de confirmació opcional es mostrarà després que l’usuari hagi premut el botó d’elecció."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Etiqueta del botó de continuar",\n      "default": "Continua"\n    }\n  ]\n}'),
(21, 'cs', '{\n  "semantics": [\n    {\n      "label": "Text otázky",\n      "description": "Otázka, na základě které se uživatel rozhodne."\n    },\n    {\n      "label": "Volby",\n      "entity": "volba",\n      "field": {\n        "fields": [\n          {\n            "label": "Text volby",\n            "description": "Popisek, který se zobrazí na tlačítku volby."\n          },\n          {\n            "label": "Přejít na",\n            "description": "Cílový čas, na který přejde uživatel po stisknutí tlačítka. Zadejte časový kód ve formátu M:SS."\n          },\n          {\n            "label": "Pokud zvolený text",\n            "description": "Volitelný potvrzovací text, který se zobrazí poté, co uživatel stiskne tlačítko volby."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Popisek tlačítka Pokračovat",\n      "default": "Pokračovat"\n    }\n  ]\n}\n'),
(21, 'da', '{\n  "semantics": [\n    {\n      "label": "Question Text",\n      "description": "The question that the user will make a choice based upon."\n    },\n    {\n      "label": "Choices",\n      "entity": "choice",\n      "field": {\n        "fields": [\n          {\n            "label": "Choice Text",\n            "description": "The label that will displayed on the choice button."\n          },\n          {\n            "label": "Go To",\n            "description": "The target time the user will be taken to upon pressing the choice button. Enter timecode in the format M:SS."\n          },\n          {\n            "label": "If Chosen Text",\n            "description": "An optional confirmation text that will be displayed after the user has pressed the choice button."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Continue Button Label",\n      "default": "Continue"\n    }\n  ]\n}'),
(21, 'de', '{\n  "semantics": [\n    {\n      "label": "Fragetext",\n      "description": "Die Frage, zu der der Nutzer eine Entscheidung trifft."\n    },\n    {\n      "label": "Wahlmöglichkeiten",\n      "entity": "Wahlmöglichkeit",\n      "field": {\n        "fields": [\n          {\n            "label": "Text",\n            "description": "Die Beschriftung, die auf dem Button angezeigt wird."\n          },\n          {\n            "label": "Gehe zu",\n            "description": "Die Stelle, zu der das Video springt, wenn der Nutzer den Button drückt. Die Zeitangabe muss im Format M:SS sein."\n          },\n          {\n            "label": "Bestätigungstext",\n            "description": "Ein optionaler Text, der angezeigt wird, nachdem der Nutzer auf diese Wahlmöglichkeit geklickt hat."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Beschriftung des \\"Weiter\\"-Buttons",\n      "default": "Weiter"\n    }\n  ]\n}\n'),
(21, 'el', '{\n  "semantics":[\n    {\n      "label":"Κείμενο ερώτησης",\n      "description":"Η ερώτηση της οποίας την απάντηση θα κληθεί να επιλέξει ο χρήστης."\n    },\n    {\n      "label":"Επιλογές",\n      "entity":"επιλογης",\n      "field":{\n        "fields":[\n          {\n            "label":"Κείμενο επιλογής",\n            "description":"Η ετικέτα που θα εμφανίζεται πάνω στο κουμπί επιλογής."\n          },\n          {\n            "label":"Μετάβαση σε",\n            "description":"Η χρονική στιγμή στην οποία θα μεταφερθεί ο χρήστης μετά το πάτημα του κουμπιού επιλογής. Εισάγετε κωδικοποίηση ώρας σε μορφή M:SS (λεπτά:δευετερόλεπτα)."\n          },\n          {\n            "label":"Κείμενο σε περίπτωση επιλογής",\n            "description":"Ένα προαιρετικό κείμενο επιβεβαίωσης που θα εμφανιστεί αφού ο χρήστης πατήσει το κουμπί επιλογής."\n          }\n        ]\n      }\n    },\n    {\n      "label":"Ετικέτα κουμπιού \\"Συνέχεια\\"",\n      "default":"Συνέχεια"\n    }\n  ]\n}\n'),
(21, 'es', '{\n  "semantics": [\n    {\n      "label": "Texto de la pregunta",\n      "description": "La pregunta sobre la cual el usuario hará una elección."\n    },\n    {\n      "label": "Opciones",\n      "entity": "opción",\n      "field": {\n        "fields": [\n          {\n            "label": "Texto de la Opción",\n            "description": "La etiqueta que se mostrará en el botón de la opción."\n          },\n          {\n            "label": "Ir A",\n            "description": "El punto temporal al que el se llevará al usuario al apretar el botón de la opción. Escribe un código de tiempo con el formato M:SS."\n          },\n          {\n            "label": "Texto si es elegida",\n            "description": "Un texto opcional de confirmación que se mostrará después de que el usuario haya apretado el botón de la opción."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Etiqueta de Botón Continuar",\n      "default": "Continuar"\n    }\n  ]\n}\n'),
(21, 'es-mx', '{\n  "semantics": [\n    {\n      "label": "Texto de Pregunta",\n      "description": "La pregunta sobre de la cual el usuario hará una elección."\n    },\n    {\n      "label": "Opciones",\n      "entity": "opción",\n      "field": {\n        "fields": [\n          {\n            "label": "Texto de la Opción",\n            "description": "La etiqueta que se mostrará en el botón de la opción."\n          },\n          {\n            "label": "Ir A",\n            "description": "El tiempo meta en el cual el usuario será llevado al apretar el botón de la opción. Ingresar código de tiempo en el formato M:SS."\n          },\n          {\n            "label": "Texto Si Elegido",\n            "description": "Un texto opcional de confirmación que será mostrado después de que el usuario haya apretado el botón de la opción."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Etiqueta de Botón Continuar",\n      "default": "Continuar"\n    }\n  ]\n}\n'),
(21, 'et', '{\n  "semantics": [\n    {\n      "label": "Küsimuse tekst",\n      "description": "Küsimus, mille põhjal teeb kasutaja valiku."\n    },\n    {\n      "label": "Valikud",\n      "entity": "valik",\n      "field": {\n        "fields": [\n          {\n            "label": "Valiku tekst",\n            "description": "Silt, mida näidatakse valiku nupul."\n          },\n          {\n            "label": "Mine",\n            "description": "The target time the user will be taken to upon pressing the choice button. Sisesta ajakood formaadis M:SS."\n          },\n          {\n            "label": "Kui valitud tekst",\n            "description": "Valikuline kinnitav tekst, mida näidatakse siis, kui kasutaja on vajutanud Valik-nuppu."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Jätka nupu silt",\n      "default": "Jätka"\n    }\n  ]\n}'),
(21, 'eu', '{\n  "semantics": [\n    {\n      "label": "Galderaren testua",\n      "description": "Galderari erabiltzaileak aukera bat hautatuta erantzungo dio."\n    },\n    {\n      "label": "Aukerak",\n      "entity": "aukera",\n      "field": {\n        "fields": [\n          {\n            "label": "Aukeraren testua",\n            "description": "Aukeratzeko botoian erakutsiko den etiketa."\n          },\n          {\n            "label": "Joan hona",\n            "description": "Erabiltzaileak izango duen denbora sakatzeko aukeraren botoiaT. Sartu denbora fomatu honekin M:SS."\n          },\n          {\n            "label": "Aukeratzen badu testua",\n            "description": "Erabiltzaileak aukeraren botoia sakatu ondoren aukeran ager daitekeen egiaztapen testua."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Jarraitu botoiaren etiketa",\n      "default": "Jarraitu"\n    }\n  ]\n}\n'),
(21, 'fa', '{\n  "semantics": [\n    {\n      "label": "متن سؤال",\n      "description": "سؤالی که بر مبنای آن کاربر یک گزینه را انتخاب می‌کند."\n    },\n    {\n      "label": "گزینه‌ها",\n      "entity": "گزینه",\n      "field": {\n        "fields": [\n          {\n            "label": "متن گزینه",\n            "description": "برچسبی که روی دکمه گزینه نمایش داده خواهد شد."\n          },\n          {\n            "label": "برو به",\n            "description": "زمان هدفی که کاربر با فشردن دکمه گزینه به آن برده خواهد شد. کد زمانی را با فرمت M:SS وارد کنید."\n          },\n          {\n            "label": "متن در صورت انتخاب گزینه",\n            "description": "یک متن تأیید اختیاری که پس از اینکه کاربر دکمه گزینه را فشرد نمایش داده خواهد شد."\n          }\n        ]\n      }\n    },\n    {\n      "label": "برچسب دکمه ادامه",\n      "default": "ادامه"\n    }\n  ]\n}\n'),
(21, 'fi', '{\n  "semantics": [\n    {\n      "label": "Kysymysteksti",\n      "description": "Kysymys jonka pohjalta käyttäjä tekee valinnan"\n    },\n    {\n      "label": "Valinnat",\n      "entity": "Valinta",\n      "field": {\n        "fields": [\n          {\n            "label": "Valinnan teksti",\n            "description": "Tämä teksti esitetään valintapainikkeessa"\n          },\n          {\n            "label": "Siirry",\n            "description": "Siirtää käyttäjän tiettyyn kohtaan aikajanalla kun hän painaa valintapainiketta. Syötä aikakoodi muodossa M:SS."\n          },\n          {\n            "label": "Jos valittu teksti",\n            "description": "Vapaaahetoinen teksti joka näytetään sen jälkeen kun käyttäjä on painanut valintapainiketta."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Jatka painikkeen teksti",\n      "default": "Jatka"\n    }\n  ]\n}\n'),
(21, 'fr', '{\n  "semantics": [\n    {\n      "label": "Texte de la question",\n      "description": "La question sur laquelle l''utilisateur doit se fonder pour faire un choix."\n    },\n    {\n      "label": "Choix",\n      "entity": "Choix",\n      "field": {\n        "fields": [\n          {\n            "label": "Intitulé du choix",\n            "description": "Cet intitulé sera affiché sur le bouton de choix."\n          },\n          {\n            "label": "Aller vers",\n            "description": "Le moment cible vers lequel l''utilisateur sera redirigé en cliquant sur ce bouton de choix. Entrer un horodatage au format M:SS"\n          },\n          {\n            "label": "Texte de confirmation de choix",\n            "description": "Optionnel. Le texte de confirmation apparaît après le clic sur ce bouton de choix."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Titre du bouton \\"Continuer\\"",\n      "default": "Continuer"\n    }\n  ]\n}'),
(21, 'gl', '{\n  "semantics": [\n    {\n      "description": "Pregunta sobre a cal o usuario baseará a súa elección.",\n      "label": "Texto da Pregunta"\n    },\n    {\n      "entity": "opción",\n      "field": {\n        "fields": [\n          {\n            "description": "O texto amosado no botón opción.",\n            "label": "Texto da Opción"\n          },\n          {\n            "description": "O tempo de destino ao que o usuario será levado cando prema o botón da opción. Escribe o código de tempo co formato M:SS.",\n            "label": "Ir A"\n          },\n          {\n            "description": "Un texto de confirmación opcional amosado despois de que o usuario preme o botón da opción.",\n            "label": "Texto Se foi Escollido"\n          }\n        ]\n      },\n      "label": "Opcións"\n    },\n    {\n      "default": "Continuar",\n      "label": "Etiqueta para o Botón Continuar"\n    }\n  ]\n}\n'),
