(21, 'ko', '{\n  "semantics": [\n    {\n      "label": "질문 텍스트",\n      "description": "사용자는 질문에 기반을 두고 선택을 함."\n    },\n    {\n      "label": "선택지",\n      "entity": "선택",\n      "field": {\n        "fields": [\n          {\n            "label": "선택지 텍스트",\n            "description": "선택 버튼에 표시될 라벨."\n          },\n          {\n            "label": "이동",\n            "description": "선택 버튼을 누를 때 사용자에게 걸리는 목표 시간. 시간코드를 M:SS 형식으로 입력하십시오."\n          },\n          {\n            "label": "선택이 된 경우 텍스트",\n            "description": "선택 버튼을 누른 후 표시되는 확인 텍스트(선택사항)"\n          }\n        ]\n      }\n    },\n    {\n      "label": "계속 버튼 레이블",\n      "default": "계속"\n    }\n  ]\n}\n'),
(21, 'lt', '{\n  "semantics": [\n    {\n      "description": "Klausimas, kuriuo remdamasis naudotojas pasirinks.",\n      "label": "Klausimo tekstas"\n    },\n    {\n      "entity": "pasirinkimas",\n      "field": {\n        "fields": [\n          {\n            "description": "Pavadinimas, kuris bus rodomas pasirinkimo mygtuke.",\n            "label": "Pasirinkimo tekstas"\n          },\n          {\n            "description": "Tikslo pasiekimo laikas, kuris vartotojui prasidės, kai paspaus pasirinkimo mygtuką. Įveskite laiko kodą formatu M:SS.",\n            "label": "Eiti į"\n          },\n          {\n            "description": "An optional confirmation text that will be displayed after the user has pressed the choice button.",\n            "label": "If Chosen Text"\n          }\n        ]\n      },\n      "label": "Pasirinkimai"\n    },\n    {\n      "default": "Continue",\n      "label": "Continue Button Label"\n    }\n  ]\n}\n'),
(21, 'lv', '{\n  "semantics": [\n    {\n      "label": "Jautājuma teksts",\n      "description": "Jautājums, uz kura pamata lietotājs izdarīs izvēli."\n    },\n    {\n      "label": "Izvēles",\n      "entity": "izvēle",\n      "field": {\n        "fields": [\n          {\n            "label": "Izvēles teksts",\n            "description": "Etiķete, kas tiks parādīta uz izvēles pogas."\n          },\n          {\n            "label": "Iet uz",\n            "description": "Mērķa laiks uz kuru lietotājs tiks novirzīts pēc izvēles pogas nospiešanas. Ievadiet laika kodu formātā M:SS."\n          },\n          {\n            "label": "Teksts, ja izvēlēts",\n            "description": "Neobligāts apstiprinājuma teksts, kas tiks parādīts pēc tam, kad lietotājs būs nospiedis izvēles pogu."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Turpināt pogas etiķete",\n      "default": "Turpināt"\n    }\n  ]\n}\n'),
(21, 'mn', '{\n  "semantics": [\n    {\n      "description": "Хэрэглэгч сонголтоо хийх асуулт.",\n      "label": "Асуултын текст"\n    },\n    {\n      "entity": "Сонголт",\n      "field": {\n        "fields": [\n          {\n            "description": "Сонгох товчлуур дээр харагдах шошго.",\n            "label": "Сонголт текст"\n          },\n          {\n            "description": "Сонгох товчийг дарахад хэрэглэгч очих зорилтот хугацаа. Цагийн кодыг M:SS форматаар оруулна уу.",\n            "label": "Руу явах"\n          },\n          {\n            "description": "Хэрэглэгч сонгох товчийг дарсны дараа гарч ирэх нэмэлт баталгаажуулах текст.",\n            "label": "Сонгосон текст"\n          }\n        ]\n      },\n      "label": "Сонголтууд"\n    },\n    {\n      "default": "Үргэлжлүүлэх",\n      "label": "Үргэлжлүүлэх товчлуурын шошго"\n    }\n  ]\n}\n'),
(21, 'nb', '{\n  "semantics": [\n    {\n      "label": "Spørsmålstekst",\n      "description": "Spørsmålet som brukeren blir stilt."\n    },\n    {\n      "label": "Alternativer",\n      "entity": "alternativ",\n      "field": {\n        "fields": [\n          {\n            "label": "Alternativ tekst",\n            "description": "Etiketten som vil vises på alternativ knappen."\n          },\n          {\n            "label": "Gå til",\n            "description": "Tidskoden brukeren vil flyttes til når knappen er trykket. Tidskoden må være på formatet M:SS."\n          },\n          {\n            "label": "Valgt tekst",\n            "description": "En valgfri bekreftelsestekst som vises etter brukeren har gjort et valg."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Tekst på fortsett-knapp",\n      "default": "Fortsett"\n    }\n  ]\n}\n'),
(21, 'nl', '{\n  "semantics": [\n    {\n      "label": "Vraagtekst",\n      "description": "De vraag waarop de gebruiker een antwoord moet geven."\n    },\n    {\n      "label": "Keuzes",\n      "entity": "keuze",\n      "field": {\n        "fields": [\n          {\n            "label": "Keuzetekst",\n            "description": "Het label dat wordt getoond op de keuze-knop."\n          },\n          {\n            "label": "Ga naar",\n            "description": "Het doeltijdstip waar naartoe de gebruiker wordt gebracht wanneer op de keuze-knop wordt geklikt. Voer tijdcode in de M:SS-opmaak in."\n          },\n          {\n            "label": "Indien gekozen tekst",\n            "description": "Een optionele bevestigingstekst die wordt getoond nadat de gebruiker op de keuze-knop heeft geklikt."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Label van \\"Doorgaan\\"-knop",\n      "default": "Doorgaan"\n    }\n  ]\n}\n'),
