(21, 'sv', '{\n  "semantics": [\n    {\n      "label": "Frågetext",\n      "description": "Den fråga som användaren ska besvara med ett svarsalternativ."\n    },\n    {\n      "label": "Alternativ",\n      "entity": "alternativ",\n      "field": {\n        "fields": [\n          {\n            "label": "Alternativ",\n            "description": "Etiketten som kommer att visas på alternativ-knappen."\n          },\n          {\n            "label": "Gå till",\n            "description": "Tidskoden som användaren kommer att flyttas till när knappen används. Tidskoden måste vara i formatet M:SS."\n          },\n          {\n            "label": "Om valt-text",\n            "description": "En valfri bekräftelsetext som visas när användaren valt ett svarsalternativ."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Text på fortsätt-knapp",\n      "default": "Fortsätt"\n    }\n  ]\n}\n'),
(21, 'sw', '{\n  "semantics": [\n    {\n      "label": "Maandishi ya Swali",\n      "description": "Swali ambalo mtumiaji atafanya uchaguzi kulingana nalo."\n    },\n    {\n      "label": "Chaguzi",\n      "entity": "chaguo",\n      "field": {\n        "fields": [\n          {\n            "label": "Chaguo la Maandishi",\n            "description": "Lebo ambayo itaonyeshwa kwenye kitufe cha chaguo."\n          },\n          {\n            "label": "Nenda Kwa",\n            "description": "Muda unaolengwa kuchukuliwa na mtumiaji baada ya kubofya kitufe cha chaguo. Weka msimbo wa saa katika umbizo la M:SS."\n          },\n          {\n            "label": "Ikiwa Umechagua Maandishi",\n            "description": "Maandishi ya hiari ya uthibitisho ambayo yataonyeshwa baada ya mtumiaji kubonyeza kitufe cha chaguo."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Endelea Lebo ya Kitufe",\n      "default": "Endelea"\n    }\n  ]\n}\n'),
(21, 'tr', '{\n  "semantics": [\n    {\n      "label": "Question Text",\n      "description": "The question that the user will make a choice based upon."\n    },\n    {\n      "label": "Choices",\n      "entity": "choice",\n      "field": {\n        "fields": [\n          {\n            "label": "Choice Text",\n            "description": "The label that will displayed on the choice button."\n          },\n          {\n            "label": "Go To",\n            "description": "The target time the user will be taken to upon pressing the choice button. Enter timecode in the format M:SS."\n          },\n          {\n            "label": "If Chosen Text",\n            "description": "An optional confirmation text that will be displayed after the user has pressed the choice button."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Continue Button Label",\n      "default": "Continue"\n    }\n  ]\n}'),
(21, 'uk', '{\n  "semantics": [\n    {\n      "label": "Текст питання",\n      "description": "Питання, на основі якого користувач зробить вибір."\n    },\n    {\n      "label": "Вибір",\n      "entity": "вибір",\n      "field": {\n        "fields": [\n          {\n            "label": "Текст вибору",\n            "description": "Напис, який відображатиметься на кнопці вибору."\n          },\n          {\n            "label": "Перейти до",\n            "description": "Цільовий час, на який користувач буде спрямований після натискання кнопки вибору. Введіть таймкод у форматі M:SS."\n          },\n          {\n            "label": "Якщо вибрано текст",\n            "description": "Додатковий текст підтвердження, який відображатиметься після натискання кнопки вибору."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Напис кнопки продовження",\n      "default": "Продовжити"\n    }\n  ]\n}\n'),
(21, 'vi', '{\n  "semantics": [\n    {\n      "label": "Question Text",\n      "description": "The question that the user will make a choice based upon."\n    },\n    {\n      "label": "Choices",\n      "entity": "choice",\n      "field": {\n        "fields": [\n          {\n            "label": "Choice Text",\n            "description": "The label that will displayed on the choice button."\n          },\n          {\n            "label": "Go To",\n            "description": "The target time the user will be taken to upon pressing the choice button. Enter timecode in the format M:SS."\n          },\n          {\n            "label": "If Chosen Text",\n            "description": "An optional confirmation text that will be displayed after the user has pressed the choice button."\n          }\n        ]\n      }\n    },\n    {\n      "label": "Continue Button Label",\n      "default": "Continue"\n    }\n  ]\n}'),
(23, 'af', '{\n  "semantics": [\n    {\n      "label": "Bestemming",\n      "fields": [\n        {\n          "label": "Tipe",\n          "options": [\n            {\n              "label": "Tydkode"\n            },\n            {\n              "label": "Ander bladsy (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Gaan na",\n          "description": "Die teikentyd wat die gebruiker sal gebruik deur op die warmkol te druk. Voer die tydkode in die formaat M:SS in."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Protokol",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(wortel relatief)"\n                },\n                {\n                  "label": "ander"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Beeldmateriaal",\n      "fields": [\n        {\n          "label": "Vorm",\n          "options": [\n            {\n              "label": "Reghoekig"\n            },\n            {\n              "label": "Rond"\n            },\n            {\n              "label": "Afgeronde Reghoek"\n            }\n          ]\n        },\n        {\n          "label": "Agtergrondkleur vir brandpunt"\n        },\n        {\n          "label": "Gebruik aanwysertjie"\n        },\n        {\n          "label": "Voeg knipeffek by",\n          "description": "Opmerking: ''n Knipeffek is altyd in die redigeerder geaktiveer, sodat jy deursigtige brandpunte kan vind"\n        }\n      ]\n    },\n    {\n      "label": "Tekste",\n      "fields": [\n        {\n          "label": "Alternatiewe Teks",\n          "description": "Beskryf die ondewerp wat die brandpunt dek. Word gebruik vir spreeklesers",\n          "placeholder": "''n Appel op ''n tafel"\n        },\n        {\n          "label": "Brandpuntetiket"\n        },\n        {\n          "label": "Wys etiket"\n        },\n        {\n          "label": "Etiketkleur"\n        }\n      ]\n    }\n  ]\n}\n'),
(23, 'ar', '{\n  "semantics": [\n    {\n      "label": "الهدف",\n      "fields": [\n        {\n          "label": "النوع",\n          "options": [\n            {\n              "label": "كود الوقت"\n            },\n            {\n              "label": "صفحة أخرى (URL)"\n            }\n          ]\n        },\n        {\n          "label": "اذهب الى",\n          "description": "الوقت المستهدف الذي سيتم نقل المستخدم إليه عند الضغط على نقطة الاتصال.ادخل كود الوقت بالشكل د:ثاثا ."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "بروتوكول",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(root relative)"\n                },\n                {\n                  "label": "اخرى"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "مرئيات",\n      "fields": [\n        {\n          "label": "شكل",\n          "options": [\n            {\n              "label": "مستطيل الشكل"\n            },\n            {\n              "label": "دائري"\n            },\n            {\n              "label": "مستطيل مستدير الزوايا"\n            }\n          ]\n        },\n        {\n          "label": "لون الخلفية لنقطة الاتصال"\n        },\n        {\n          "label": "استخدام دالة المؤشر"\n        },\n        {\n          "label": "إضافة تأثير وامض",\n          "description": "ملاحظة:التاثير الوامض يكون ممكن دائما في المحرر حتى تتمكن من ايجاد نقاط اتصال شفافة."\n        }\n      ]\n    },\n    {\n      "label": "نصوص",\n      "fields": [\n        {\n          "label": "النص البديل",\n          "description": "وصف الموضوع الذي تغطيه النقطة الساخنة. تستخدم في تقنية تحويل النص الى كلام",\n          "placeholder": "An apple on a table"\n        },\n        {\n          "label": "تسمية نقطة الاتصال"\n        },\n        {\n          "label": "اظهار التسمية"\n        },\n        {\n          "label": "لون التسمية"\n        }\n      ]\n    }\n  ]\n}\n'),
(23, 'bg', '{\r\n  "semantics": [\r\n    {\r\n      "label": "Местоназначение",\r\n      "fields": [\r\n        {\r\n          "label": "Тип",\r\n          "options": [\r\n            {\r\n              "label": "Времеви формат"\r\n            },\r\n            {\r\n              "label": "Друга страница (URL)"\r\n            }\r\n          ]\r\n        },\r\n        {\r\n          "label": "Зареди",\r\n          "description": "Време, след което потребителят ще бъде пренасочен при натискане на активната точка. Въведете времето във формат M:SS."\r\n        },\r\n        {\r\n          "label": "URL",\r\n          "fields": [\r\n            {\r\n              "label": "Протокол",\r\n              "options": [\r\n                {\r\n                  "label": "http://"\r\n                },\r\n                {\r\n                  "label": "https://"\r\n                },\r\n                {\r\n                  "label": "(относително спрямо изходния адрес)"\r\n                },\r\n                {\r\n                  "label": "other"\r\n                }\r\n              ]\r\n            },\r\n            {\r\n              "label": "URL"\r\n            }\r\n          ]\r\n        }\r\n      ]\r\n    },\r\n    {\r\n      "label": "Визуализации",\r\n      "fields": [\r\n        {\r\n          "label": "Форма",\r\n          "options": [\r\n            {\r\n              "label": "Правоъгълна"\r\n            },\r\n            {\r\n              "label": "Кръгла"\r\n            },\r\n            {\r\n              "label": "Заоблен правоъгълник"\r\n            }\r\n          ]\r\n        },\r\n        {\r\n          "label": "Фонов цвят за активната точка"\r\n        },\r\n        {\r\n          "label": "Използване на показалец за курсор"\r\n        },\r\n        {\r\n          "label": "Добавяне на мигащ ефект",\r\n          "description": "Забележка: Мигащият ефект винаги е активен в редактора, за да можете да намерите прозрачните активни точки"\r\n        }\r\n      ]\r\n    },\r\n    {\r\n      "label": "Текстове",\r\n      "fields": [\r\n        {\r\n          "label": "Алтернативен текст",\r\n          "description": "Опишете предмета, който покрива активната точка. Използва се за четци",\r\n          "placeholder": "Ябълка на масата"\r\n        },\r\n        {\r\n          "label": "Етикет за активна точка"\r\n        },\r\n        {\r\n          "label": "Показване на етикета"\r\n        },\r\n        {\r\n          "label": "Цвят на етикета"\r\n        }\r\n      ]\r\n    }\r\n  ]\r\n}'),
(23, 'bs', '{\n  "semantics": [\n    {\n      "label": "Destinacija",\n      "fields": [\n        {\n          "label": "Tip",\n          "options": [\n            {\n              "label": "Kod vremena"\n            },\n            {\n              "label": "Druga stranica (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Idi na",\n          "description": "Ciljano vrijeme koje želi korinik će biti uzeto pritiskom na hotspot.Unesite kod vremena u formatu M:SS."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Protokol",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(u odnosu na korijen)"\n                },\n                {\n                  "label": "ostali"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Vizualna svojstva",\n      "fields": [\n        {\n          "label": "Forma",\n          "options": [\n            {\n              "label": "Pravougaoni"\n            },\n            {\n              "label": "Okrugli"\n            },\n            {\n              "label": "Rounded Rectangle"\n            }\n          ]\n        },\n        {\n          "label": "Boja pozadine za hotpost"\n        },\n        {\n          "label": "Koristi kursor"\n        },\n        {\n          "label": "Dodati efekat blinkanja",\n          "description": "Napomena: Efekat blinkanja je uvijek omogućen u editoru kako bi bili u stanju naći transparentne hotspots."\n        }\n      ]\n    },\n    {\n      "label": "Tekstovi",\n      "fields": [\n        {\n          "label": "Alternative Text",\n          "description": "Describe the subject the hotspot covers. Used for readspeakers",\n          "placeholder": "An apple on a table"\n        },\n        {\n          "label": "Hotspot Label"\n        },\n        {\n          "label": "Show label"\n        },\n        {\n          "label": "Label color"\n        }\n      ]\n    }\n  ]\n}\n'),
(23, 'ca', '{\n  "semantics": [\n    {\n      "label": "Destinació",\n      "fields": [\n        {\n          "label": "Tipus",\n          "options": [\n            {\n              "label": "Codi de temps"\n            },\n            {\n              "label": "Una altra pàgina (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Ves a",\n          "description": "Temps objectiu en el qual se situarà l’usuari en prémer la zona sensible. Introduïu el codi de temps en format M:SS."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Protocol",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(root relative)"\n                },\n                {\n                  "label": "altres"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Elements visuals",\n      "fields": [\n        {\n          "label": "Forma",\n          "options": [\n            {\n              "label": "Rectangular"\n            },\n            {\n              "label": "Circular"\n            },\n            {\n              "label": "Rectangle arrodonit"\n            }\n          ]\n        },\n        {\n          "label": "Color de fons de la zona sensible"\n        },\n        {\n          "label": "Utilitzeu el cursor del punter"\n        },\n        {\n          "label": "Afegeix un efecte de parpelleig",\n          "description": "Nota: l’efecte de parpelleig sempre està activat a l’editor, perquè vegeu les zones sensibles transparents"\n        }\n      ]\n    },\n    {\n      "label": "Textos",\n      "fields": [\n        {\n          "label": "Text alternatiu",\n          "description": "Descriviu el tema de la zona sensible, perquè el puguin utilitzar els altaveus de lectura",\n          "placeholder": "Una poma sobre la taula"\n        },\n        {\n          "label": "Etiqueta de la zona sensible"\n        },\n        {\n          "label": "Mostra l’etiqueta"\n        },\n        {\n          "label": "Color de l’etiqueta"\n        }\n      ]\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(23, 'cs', '{\n  "semantics": [\n    {\n      "label": "Cíl",\n      "fields": [\n        {\n          "label": "Typ",\n          "options": [\n            {\n              "label": "Časový kód"\n            },\n            {\n              "label": "Další stránka (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Jdi na",\n          "description": "Cílový čas, který bude uživatelem po stisknutí aktivního bodu přijat. Zadejte časový kód ve formátu M:SS."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Protokol",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(relativní kořen)"\n                },\n                {\n                  "label": "jiný"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Vizuální",\n      "fields": [\n        {\n          "label": "Tvar",\n          "options": [\n            {\n              "label": "Obdélník"\n            },\n            {\n              "label": "Kruh"\n            },\n            {\n              "label": "Zaoblený obdélník"\n            }\n          ]\n        },\n        {\n          "label": "Barva pozadí pro aktivní body"\n        },\n        {\n          "label": "Použít ukazatel kurzoru"\n        },\n        {\n          "label": "Přidat efekt blikání",\n          "description": "Poznámka: Blikající efekt je v editoru vždy povolen, takže můžete najít průhledné aktivní body"\n        }\n      ]\n    },\n    {\n      "label": "Texty",\n      "fields": [\n        {\n          "label": "Alternativní text",\n          "description": "Popište povrch předmětu aktivních bodů. Používá se pro čtecí zařízení",\n          "placeholder": "Jablko na stole"\n        },\n        {\n          "label": "Popisek aktivních bodů"\n        },\n        {\n          "label": "Popisek zobrazit"\n        },\n        {\n          "label": "Popisek barva"\n        }\n      ]\n    }\n  ]\n}\n'),
(23, 'de', '{\n  "semantics": [\n    {\n      "label": "Ziel",\n      "fields": [\n        {\n          "label": "Typ",\n          "options": [\n            {\n              "label": "Stelle im Video"\n            },\n            {\n              "label": "Andere Seite (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Gehe zu",\n          "description": "Die Stelle, zu der das Video springt, wenn der Nutzer den Hotspot anklickt. Die Zeitangabe muss im Format M:SS sein."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Protokoll",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(relativer Pfad auf aktueller Domain)"\n                },\n                {\n                  "label": "anderes"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Darstellung",\n      "fields": [\n        {\n          "label": "Form",\n          "options": [\n            {\n              "label": "Rechteck"\n            },\n            {\n              "label": "Kreis"\n            },\n            {\n              "label": "Abgerundetes Rechteck"\n            }\n          ]\n        },\n        {\n          "label": "Hintergrundfarbe des Hotspots"\n        },\n        {\n          "label": "Hand-Cursor verwenden"\n        },\n        {\n          "label": "Blinkenden Effekt verwenden",\n          "description": "Hinweis: Dieser Effekt ist im Editor immer aktiv, damit transparente Hotspots auffindbar sind"\n        }\n      ]\n    },\n    {\n      "label": "Texte",\n      "fields": [\n        {\n          "label": "Alternativtext",\n          "description": "Beschreibt inhaltlich, was sich unter dem Hotspot befindet. Für Vorlesewerkzeuge genutzt.",\n          "placeholder": "Ein Apfel auf einem Tisch"\n        },\n        {\n          "label": "Beschriftung des Hotspots"\n        },\n        {\n          "label": "Beschriftung anzeigen"\n        },\n        {\n          "label": "Beschriftungsfarbe"\n        }\n      ]\n    }\n  ]\n}\n'),
(23, 'el', '{\n  "semantics": [\n    {\n      "label": "Προορισμός",\n      "fields": [\n        {\n          "label": "Τύπος",\n          "options": [\n            {\n              "label": "Κωδικοποίηση ώρας"\n            },\n            {\n              "label": "Άλλη σελίδα (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Μετάβαση σε",\n          "description": "Η χρονική στιγμή στην οποία θα μεταφερθεί ο χρήστης μετά το πάτημα του hotspot. Εισάγετε κωδικοποίηση ώρας σε μορφή M:SS (λεπτά:δευτερόλεπτα)."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Πρωτόκολλο",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(rot relativt)"\n                },\n                {\n                  "label": "Άλλο"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Οπτικά στοιχεία",\n      "fields": [\n        {\n          "label": "Σχήμα",\n          "options": [\n            {\n              "label": "Ορθογώνιο"\n            },\n            {\n              "label": "Κυκλικό"\n            },\n            {\n              "label": "Στρογγυλεμένες άκρες"\n            }\n          ]\n        },\n        {\n          "label": "Χρώμα φόντου του hotspot"\n        },\n        {\n          "label": "Χρήση δείκτη"\n        },\n        {\n          "label": "Προσθήκη εφέ που αναβοσβήνει",\n          "description": "Σημείωση: Το εφέ που αναβοσβήνει είναι πάντα ενεργοποιημένο στον επεξεργαστή ώστε να μπορείτε να εντοπίζετε τα διαφανή hotspots."\n        }\n      ]\n    },\n    {\n      "label": "Κείμενα",\n      "fields": [\n        {\n          "label": "Εναλλακτικό κείμενο",\n          "description": "Περιγράψτε το θέμα στο οποίο αναφέρεται το hotspot. Χρησιμοποιείται για ακουστική υποβοήθηση",\n          "placeholder": "Ένα μήλο πάνω σε ένα τραπέζι"\n        },\n        {\n          "label": "Ετικέτα hotspot"\n        },\n        {\n          "label": "Εμφάνιση ετικέτας"\n        },\n        {\n          "label": "Χρώμα ετικέτας"\n        }\n      ]\n    }\n  ]\n}\n'),
(23, 'es', '{\n  "semantics": [\n    {\n      "label": "Destino",\n      "fields": [\n        {\n          "label": "Tipo",\n          "options": [\n            {\n              "label": "Código de Tiempo"\n            },\n            {\n              "label": "Otra página (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Ir A",\n          "description": "El tiempo de destino a donde se llevará al usuario que presione el punto de acceso. Escribe código de tiempo en formato M:SS."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Protocolo",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(relativo a raíz)"\n                },\n                {\n                  "label": "otros"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Efectos visuales",\n      "fields": [\n        {\n          "label": "Forma",\n          "options": [\n            {\n              "label": "Rectangular"\n            },\n            {\n              "label": "Circular"\n            },\n            {\n              "label": "Rectángulo Redondeado"\n            }\n          ]\n        },\n        {\n          "label": "Color de fondo para el punto de acceso"\n        },\n        {\n          "label": "Usar cursor del ratón"\n        },\n        {\n          "label": "Añadir efecto de parpadeo",\n          "description": "Nota: El efecto de parpadeo siempre está habilitado en el editor para que puedas encontrar los puntos de acceso transparentes"\n        }\n      ]\n    },\n    {\n      "label": "Textos",\n      "fields": [\n        {\n          "label": "Texto Alternativo",\n          "descriptio