(23, 'lv', '{\n  "semantics": [\n    {\n      "fields": [\n        {\n          "options": [\n            {\n              "label": "Laika kods"\n            },\n            {\n              "label": "Cita lapa (URL)"\n            }\n          ],\n          "label": "Tips"\n        },\n        {\n          "label": "Iet uz",\n          "description": "Mērķa laiks uz kuru lietotājs tiks novirzīts pēc klikšķa uz aktīvā punkta. Ievadiet laika kodu šādā formātā: M:SS."\n        },\n        {\n          "fields": [\n            {\n              "label": "Protokols",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(relatīvais ceļš)"\n                },\n                {\n                  "label": "cits"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ],\n          "label": "URL"\n        }\n      ],\n      "label": "Mērķa vieta"\n    },\n    {\n      "label": "Izskats",\n      "fields": [\n        {\n          "options": [\n            {\n              "label": "Taisnstūra"\n            },\n            {\n              "label": "Apaļš"\n            },\n            {\n              "label": "Apaļots taisnstūris"\n            }\n          ],\n          "label": "Forma"\n        },\n        {\n          "label": "Aktīvā punkta fona attēls"\n        },\n        {\n          "label": "Izmantot bultiņas kursoru"\n        },\n        {\n          "label": "Pievienot mirgošanas efektu",\n          "description": "Piezīme: Mirgošanas efekts ir vienmēr ieslēgts redaktorā, lai jūs varētu atrast caurspīdīgus aktīvos punktus"\n        }\n      ]\n    },\n    {\n      "fields": [\n        {\n          "placeholder": "Ābols uz galda",\n          "label": "Alternatīvais teksts",\n          "description": "Aprakstiet priekšmetu uz ko attiecas aktīvais punkts. Tiek izmantots asistīvajās tehnoloģijās"\n        },\n        {\n          "label": "Aktīvā punkta birka"\n        },\n        {\n          "label": "Rādīt birku"\n        },\n        {\n          "label": "Birkas krāsa"\n        }\n      ],\n      "label": "Teksti"\n    }\n  ]\n}\n'),
(23, 'mn', '{\n  "semantics": [\n    {\n      "fields": [\n        {\n          "label": "Төрөл",\n          "options": [\n            {\n              "label": "Цагийн код"\n            },\n            {\n              "label": "Өөр хуудас (URL)"\n            }\n          ]\n        },\n        {\n          "description": "Халуун цэг дээр дарахад хэрэглэгч рүү очих зорилтот цаг. Цагийн кодыг M:SS форматаар оруулна уу.",\n          "label": "Руу явах"\n        },\n        {\n          "fields": [\n            {\n              "label": "Протокол",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(үндсэн хамаатан садан)"\n                },\n                {\n                  "label": "бусад"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ],\n          "label": "URL"\n        }\n      ],\n      "label": "Очих газар"\n    },\n    {\n      "label": "Дүрслэл",\n      "fields": [\n        {\n          "options": [\n            {\n              "label": "Тэгш өнцөгт"\n            },\n            {\n              "label": "Тойрог"\n            },\n            {\n              "label": "Бөөрөнхий тэгш өнцөгт"\n            }\n          ],\n          "label": "Хэлбэр"\n        },\n        {\n          "label": "Халуун цэгийн дэвсгэр өнгө"\n        },\n        {\n          "label": "Заагч курсорыг ашиглана уу"\n        },\n        {\n          "description": "Тайлбар: Анивчих эффект нь засварлагч дээр үргэлж идэвхждэг тул та ил тод халуун цэгүүдийг олох боломжтой",\n          "label": "Анивчих эффект нэмнэ үү"\n        }\n      ]\n    },\n    {\n      "fields": [\n        {\n          "label": "Альтернатив текст",\n          "placeholder": "Ширээн дээрх алим",\n          "description": "Халуун цэгийн хамрах сэдвийг тайлбарла. Уншдаг чанга яригчдад ашигладаг"\n        },\n        {\n          "label": "Халуун цэгийн шошго"\n        },\n        {\n          "label": "Шошго харуулах"\n        },\n        {\n          "label": "Шошгоны өнгө"\n        }\n      ],\n      "label": "Текстүүд"\n    }\n  ]\n}\n'),
(23, 'nb', '{\n  "semantics": [\n    {\n      "label": "Endepunkt",\n      "fields": [\n        {\n          "label": "Type",\n          "options": [\n            {\n              "label": "Tidskode"\n            },\n            {\n              "label": "Annen side (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Gå til",\n          "description": "Tidskoden brukeren tas til ved å trykke på hotspot. Tidskoden må være i formatet M:SS."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Protokoll",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(rot relativt)"\n                },\n                {\n                  "label": "andre"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Visuelle egenskaper",\n      "fields": [\n        {\n          "label": "Form",\n          "options": [\n            {\n              "label": "Rektangulær"\n            },\n            {\n              "label": "Sirkulær"\n            },\n            {\n              "label": "Avrundet rektangel"\n            }\n          ]\n        },\n        {\n          "label": "Bakgrunnsfarge for hotspot"\n        },\n        {\n          "label": "Visuell effekt for muse-peker"\n        },\n        {\n          "label": "Vis blinkende effekt",\n          "description": "Blinkende effekt er alltid på i editor så du kan se hvor gjennomsiktige hotspots befinner seg."\n        }\n      ]\n    },\n    {\n      "label": "Tekster",\n      "fields": [\n        {\n          "label": "Alternative Text",\n          "description": "Describe the subject the hotspot covers. Used for readspeakers",\n          "placeholder": "An apple on a table"\n        },\n        {\n          "label": "Hotspot Label"\n        },\n        {\n          "label": "Show label"\n        },\n        {\n          "label": "Label color"\n        }\n      ]\n    }\n  ]\n}\n'),
(23, 'nl', '{\n  "semantics": [\n    {\n      "label": "Bestemming",\n      "fields": [\n        {\n          "label": "Type",\n          "options": [\n            {\n              "label": "Tijdcode"\n            },\n            {\n              "label": "Een andere pagina (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Ga naar",\n          "description": "De doeltijd waar de gebruiker naartoe gaat als hij op de hotspot klikt. Voer de tijdscode in M:SS-formaat in."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Protocol",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(t.o.v. root)"\n                },\n                {\n                  "label": "anders"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Visuele effecten",\n      "fields": [\n        {\n          "label": "Vorm",\n          "options": [\n            {\n              "label": "Rechthoekig"\n            },\n            {\n              "label": "Rond"\n            },\n            {\n              "label": "Afgeronde rechthoek"\n            }\n          ]\n        },\n        {\n          "label": "Achtergrondkleur voor hotspot"\n        },\n        {\n          "label": "Gebruik pijlcursor"\n        },\n        {\n          "label": "Voeg knippereffect toe",\n          "description": "Merk op dat het knippereffect altijd is ingeschakeld in de editor zodat je de transparante hotspots kunt vinden"\n        }\n      ]\n    },\n    {\n      "label": "Teksten",\n      "fields": [\n        {\n          "label": "Alternatieve tekst",\n          "description": "Beschrijf het onderdeel waarop de hotspot is geplaatst. Gebruikt voor schermlezers",\n          "placeholder": "Een appel op een tafel"\n        },\n        {\n          "label": "Label voor hotspot"\n        },\n        {\n          "label": "Toon label"\n        },\n        {\n          "label": "Labelkleur"\n        }\n      ]\n    }\n  ]\n}\n'),
(23, 'pt', '{\n  "semantics": [\n    {\n      "label": "Destino",\n      "fields": [\n        {\n          "label": "Tipo",\n          "options": [\n            {\n              "label": "Tempo"\n            },\n            {\n              "label": "Outra página (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Ir para",\n          "description": "O tempo para o qual o utilizador vai ser deslocado quando clicar no hotspot. O tempo-alvo deve ser indicado no formato M:SS."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Protocolo",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(relativo à raiz)"\n                },\n                {\n                  "label": "outro"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Visuais",\n      "fields": [\n        {\n          "label": "Forma",\n          "options": [\n            {\n              "label": "Retangular"\n            },\n            {\n              "label": "Circular"\n            },\n            {\n              "label": "Retângulo arredondado"\n            }\n          ]\n        },\n        {\n          "label": "Cor de fundo do hotspot"\n        },\n        {\n          "label": "Usar o cursor"\n        },\n        {\n          "label": "Adicionar efeito intermitente",\n          "description": "Nota: O efeito intermitente está sempre ativado no editor sendo assim mais fácil encontrar hotspots transparentes"\n        }\n      ]\n    },\n    {\n      "label": "Textos",\n      "fields": [\n        {\n          "label": "Texto alternativo",\n          "description": "Descrição do assunto relacionado com o hotspot. Utilizado para leitores de ecrã",\n          "placeholder": "Uma maçã em cima de uma mesa"\n        },\n        {\n          "label": "Etiqueta do Hotspot"\n        },\n        {\n          "label": "Mostrar etiqueta"\n        },\n        {\n          "label": "Cor da etiqueta"\n        }\n      ]\n    }\n  ]\n}\n'),
(23, 'pt-br', '{\n  "semantics": [\n    {\n      "label": "Destino",\n      "fields": [\n        {\n          "label": "Tipo",\n          "options": [\n            {\n              "label": "Código de Tempo"\n            },\n            {\n              "label": "Outra página (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Ir para",\n          "description": "O tempo alvo que em o usuário será redirecionado ao pressionar o ponto de acesso (hotspot). Insira o tempo no formato M:SS."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Protocolo",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(raiz relativa)"\n                },\n                {\n                  "label": "outro"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Visuais",\n      "fields": [\n        {\n          "label": "Forma",\n          "options": [\n            {\n              "label": "Retangular"\n            },\n            {\n              "label": "Circular"\n            },\n            {\n              "label": "Retângulo arredondado"\n            }\n          ]\n        },\n        {\n          "label": "Cor do plano de fundo para o ponto de acesso"\n        },\n        {\n          "label": "Usar o cursor"\n        },\n        {\n          "label": "Adicionar efeito piscante",\n          "description": "Nota: O efeito piscante está sempre ativado no editor para que você possa encontrar pontos de acesso transparentes"\n        }\n      ]\n    },\n    {\n      "label": "Textos",\n      "fields": [\n        {\n          "label": "Texto alternativo",\n          "description": "Descreva o assunto de que trata o ponto de acesso. Usado por leitores de tela",\n          "placeholder": "Uma maçã em uma mesa"\n        },\n        {\n          "label": "Rótulo do ponto de acesso"\n        },\n        {\n          "label": "Mostrar rótulo"\n        },\n        {\n          "label": "Cor do rótulo"\n        }\n      ]\n    }\n  ]\n}\n'),
(23, 'ru', '{\n  "semantics": [\n    {\n      "label": "Место назначения",\n      "fields": [\n        {\n          "label": "Тип",\n          "options": [\n            {\n              "label": "Таймкод"\n            },\n            {\n              "label": "Другая страница (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Перейти к",\n          "description": "Целевое время, на которое пользователь будет перенаправлен при нажатии точки доступа. Введите таймкод в формате M:SS."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Протокол",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(относительный путь)"\n                },\n                {\n                  "label": "другой"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Внешний вид",\n      "fields": [\n        {\n          "label": "Фигура",\n          "options": [\n            {\n              "label": "Прямоугольный"\n            },\n            {\n              "label": "Круглый"\n            },\n            {\n              "label": "Прямоугольник с закругленными углами"\n            }\n          ]\n        },\n        {\n          "label": "Фоновый цвет для точки доступа"\n        },\n        {\n          "label": "Использовать указатель курсора"\n        },\n        {\n          "label": "Добавить мигающий эффект",\n          "description": "Примечание. Эффект мигания всегда включен в редакторе, поэтому вы можете найти прозрачные точки доступа."\n        }\n      ]\n    },\n    {\n      "label": "Тексты",\n      "fields": [\n        {\n          "label": "Альтернативный текст",\n          "description": "Опишите предмет, который охватывает точку доступа. Используется для озвучки текста",\n          "placeholder": "An apple on a table"\n        },\n        {\n          "label": "Надпись точки доступа"\n        },\n        {\n          "label": "Показать надпись"\n        },\n        {\n          "label": "Цвет надписи"\n        }\n      ]\n    }\n  ]\n}\n'),
(23, 'sl', '{\n  "semantics": [\n    {\n      "label": "Cilj",\n      "fields": [\n        {\n          "label": "Tip",\n          "options": [\n            {\n              "label": "Čas"\n            },\n            {\n              "label": "Spletna stran (URL)"\n            }\n          ]\n        },\n        {\n          "label": "Pojdi na",\n          "description": "Vnos časa za nadaljevanje ogleda posnetka (v formatu M:SS), na katerega bo udeleženca vodil klik."\n        },\n        {\n          "label": "URL",\n          "fields": [\n            {\n              "label": "Protokol",\n              "options": [\n                {\n                  "label": "http://"\n                },\n                {\n                  "label": "https://"\n                },\n                {\n                  "label": "(korensko sorodna stran)"\n                },\n                {\n                  "label": "drugo"\n                }\n              ]\n            },\n            {\n              "label": "URL"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Vizualna podoba",\n      "fields": [\n        {\n          "label": "Oblika",\n          "options": [\n            {\n              "label": "Pravokotnik"\n            },\n            {\n              "label": "Krog"\n            },\n            {\n              "label": "Zaobljen pravokotnik"\n            }\n          ]\n        },\n        {\n          "label": "Barva ozadja točke"\n        },\n        {\n          "label": "Uporabi miškin kazalec"\n        },\n        {\n          "label": "Dodaj učinek utripanja",\n          "description": "Opomba: učinek utripanja je vedno omogočen v urejevalnem načinu, da se lažje najde prosojne interaktivne točke."\n        }\n      ]\n    },\n    {\n      "label": "Besedilo",\n      "fields": [\n        {\n          "label": "Nadomestno besedilo",\n          "description": "Besedilo opisuje izpostavljeno s točko in služi bralnikom zaslona