(28, 'sr', '{\n  "semantics": [\n    {\n      "label": "Медија",\n      "fields": [\n        {\n          "label": "Тип",\n          "description": "Опциони медији за приказ изнад питања."\n        },\n        {\n          "label": "Онемогући увеличавање слике"\n        }\n      ]\n    },\n    {\n      "label": "Питање"\n    },\n    {\n      "label": "Доступне опције",\n      "entity": "опција",\n      "field": {\n        "label": "Опција",\n        "fields": [\n          {\n            "label": "Медија",\n            "description": "Media to display as a choice."\n          },\n          {\n            "label": "Poster image"\n          },\n          {\n            "label": "Тачно"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Општа повратна информација",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Уобичајено"\n            }\n          ],\n          "label": "Дефинишите прилагођене повратне информације за било који опсег резултата",\n          "description": "Кликните на \\"Додај опсег\\" дугме да додате онолико распона колико вам је потребно. Пример: 0-20% Лош резултат, 21-91% Просечан резултат, 91-100% Одличан резултат!",\n          "entity": "опсег",\n          "field": {\n            "fields": [\n              {\n                "label": "Распон бодова"\n              },\n              {},\n              {\n                "label": "Повратне информације за дефинисани распон бодова",\n                "placeholder": "Попуните повратне информације"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Поставке понашања",\n      "description": "Ове опције ће вам омогућити да контролишете како се задатак понаша.",\n      "fields": [\n        {\n          "label": "Омогући \\"Прикажи поново\\" дугме"\n        },\n        {\n          "label": "Омогући \\"Прикажи решења\\" дугме"\n        },\n        {\n          "label": "Прикажи дијалог за потврду за \\"Провери\\""\n        },\n        {\n          "label": "Прикажи дијалог за потврду за \\"Покушај поново\\""\n        },\n        {\n          "label": "Дајте један поен за цело питање",\n          "description": "Додељује један поен на питање да ли је процентуални резултат већи од пролазног процента."\n        },\n        {\n          "label": "Захтевајте одговор пре него што се решење види"\n        },\n        {\n          "label": "Тип питања",\n          "description": "Одаберите изглед и понашање питања.",\n          "options": [\n            {\n              "label": "Аутоматски"\n            },\n            {\n              "label": "Више избора (Checkboxes)"\n            },\n            {\n              "label": "Један избор (Radio Buttons)"\n            }\n          ]\n        },\n        {\n          "label": "Размера",\n          "description": "Изаберите однос ширине и висине",\n          "options": [\n            {\n              "label": "Аутоматска"\n            },\n            {\n              "label": "16:9"\n            },\n            {\n              "label": "4:3"\n            },\n            {\n              "label": "3:2"\n            },\n            {\n              "label": "1:1"\n            }\n          ]\n        },\n        {\n          "label": "Максималне алтернативе по реду",\n          "description": "Подесите максималан број алтернатива по реду како бисте осигурали да питања изгледају у реду.",\n          "options": [\n            {\n              "label": "1"\n            },\n            {\n              "label": "2"\n            },\n            {\n              "label": "3"\n            },\n            {\n              "label": "4"\n            }\n          ]\n        },\n        {\n          "label": "Проценат пролаза",\n          "description": "Ова поставка често неће имати ефекта. То је проценат укупног резултата потребног за добијање 1 бода када је омогућен један поен за цео задатак и за постизање result.success у xAPI изразима."\n        }\n      ]\n    },\n    {\n      "label": "Кориснички интерфејс",\n      "fields": [\n        {\n          "label": "Текст за \\"Провери\\" дугме",\n          "default": "Провери"\n        },\n        {\n          "label": "Text for \\"Submit\\" button",\n          "default": "Submit"\n        },\n        {\n          "label": "Опис помоћне технологије за \\"Провери\\" дугме",\n          "default": "Проверите одговоре. Одговори ће бити означени као тачни, нетачни или без одговора."\n        },\n        {\n          "label": "Текст за \\"Прикажи решења\\" дугме",\n          "default": "Прикажи решења"\n        },\n        {\n          "label": "Опис помоћне технологије за \\"Прикажи решења\\" дугме",\n          "default": "Покажите решење. Тачне опције ће бити означене."\n        },\n        {\n          "label": "Тачан одговор (није приказано)",\n          "default": "Тачан  одговор"\n        },\n        {\n          "label": "Погрешан одговор (није приказано)",\n          "default": "Погрешан одговор"\n        },\n        {\n          "label": "Опцију је требало проверити",\n          "default": "Требало је проверити"\n        },\n        {\n          "label": "Опцију није требало проверавати",\n          "default": "Није требало проверавати"\n        },\n        {\n          "label": "Текст за \\"Захтева одговор\\" поруку",\n          "default": "Одговорите пре него што погледате решење."\n        },\n        {\n          "label": "Текст за \\"Покушајте поново\\" дугме",\n          "default": "Покушај поново"\n        },\n        {\n          "label": "Опис помоћне технологије за \\"Покушај поново\\" дугме",\n          "default": "Покушајте поново задатак. Ресетујте све одговоре и започните задатак изнова."\n        },\n        {\n          "label": "Ваш резултат",\n          "description": ":num и :total су променљиве и биће замењене одговарајућим вредностима.",\n          "default": "Освојили сте :num од :total поена"\n        },\n        {\n          "label": "Проверите дијалог за потврду",\n          "fields": [\n            {\n              "label": "Текст заглавља",\n              "default": "Готово?"\n            },\n            {\n              "label": "Текст тела",\n              "default": "Јесте ли сигурни да желите да завршите?"\n            },\n            {\n              "label": "Ознака дугмета Откажи",\n              "default": "Откажи"\n            },\n            {\n              "label": "Ознака дугмета за потврду",\n              "default": "Заврши"\n            }\n          ]\n        },\n        {\n          "label": "Дијалог за потврду поновног покушаја",\n          "fields": [\n            {\n              "label": "Текст заглавља",\n              "default": "Покушај поново?"\n            },\n            {\n              "label": "Текст тела",\n              "default": "Да ли сте сигурни да желите да покушате поново?"\n            },\n            {\n              "label": "Ознака дугмета Откажи",\n              "default": "Откажи"\n            },\n            {\n              "label": "Ознака дугмета за потврду",\n              "default": "Покушај поново"\n            }\n          ]\n        },\n        {\n          "label": "Текст ако за слику недостаје алтернативни текст",\n          "default": "Недостаје алтернативни текст."\n        },\n        {\n          "label": "Close modal button label",\n          "default": "Close modal"\n        }\n      ]\n    }\n  ]\n}\n'),
(28, 'sw', '{\n  "semantics": [\n    {\n      "label": "Vyombo vya habari",\n      "fields": [\n        {\n          "label": "Aina",\n          "description": "Vyombo vya habari vya hiari vya kuonyesha juu ya swali."\n        },\n        {\n          "label": "Zima ukuzaji wa picha"\n        }\n      ]\n    },\n    {\n      "label": "Swali"\n    },\n    {\n      "label": "Chaguzi zinazopatikana",\n      "entity": "chaguo",\n      "field": {\n        "label": "Chaguo",\n        "fields": [\n          {\n            "label": "Vyombo vya habari",\n            "description": "Media to display as a choice."\n          },\n          {\n            "label": "Poster image"\n          },\n          {\n            "label": "Sahihi"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Maoni ya Jumla",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Chaguo-msingi"\n            }\n          ],\n          "label": "Bainisha maoni maalum kwa masafa yoyote ya alama",\n          "description": "Bofya kitufe cha \\"Ongeza masafa\\" ili kuongeza masafa mengi unavyohitaji. Mfano: 0-20% Alama mbaya, 21-91% Alama ya Wastani, 91-100% Alama Nzuri!",\n          "entity": "masafa",\n          "field": {\n            "fields": [\n              {\n                "label": "Masafa ya Alama"\n              },\n              {},\n              {\n                "label": "Maoni kwa masafa ya alama yaliyofafanuliwa",\n                "placeholder": "Jaza maoni"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Mipangilio ya tabia",\n      "description": "Chaguzi hizi zitakuwezesha kudhibiti jinsi kazi inavyofanya.",\n      "fields": [\n        {\n          "label": "Washa kitufe cha \\"Jaribu tena\\""\n        },\n        {\n          "label": "Washa kitufe cha \\"Onesha Suluhisho\\""\n        },\n        {\n          "label": "Onyesha mazungumzo ya uthibitisho kwenye \\"Weka alama\\""\n        },\n        {\n          "label": "Onyesha mazungumzo ya uthibitisho kwenye \\"Jaribu tena\\""\n        },\n        {\n          "label": "Toa pointi moja kwa swali zima",\n          "description": "Hutoa pointi moja kwa swali ikiwa alama ya asilimia ni kubwa kuliko asilimia ya ufaulu"\n        },\n        {\n          "label": "Hitaji jibu kabla ya suluhisho kutazamwa"\n        },\n        {\n          "label": "Aina ya Swali",\n          "description": "Chagua mwonekano na tabia ya swali.",\n          "options": [\n            {\n              "label": "Otomatiki"\n            },\n            {\n              "label": "Chaguo nyingi (Visanduku vya kuteua)"\n            },\n            {\n              "label": "Chaguo Moja (Vitufe vya Redio)"\n            }\n          ]\n        },\n        {\n          "label": "Uwiano wa vipengele",\n          "description": "Chagua uwiano wa vipengele vya mbadala",\n          "options": [\n            {\n              "label": "Otomatiki"\n            },\n            {\n              "label": "16:9"\n            },\n            {\n              "label": "4:3"\n            },\n            {\n              "label": "3:2"\n            },\n            {\n              "label": "1:1"\n            }\n          ]\n        },\n        {\n          "label": "Njia mbadala za juu kwa kila safu mlalo",\n          "description": "Weka idadi ya juu ya mbadala kwa kila safu mlalo ili kuhakikisha kuwa maswali yanaonekana sawa.",\n          "options": [\n            {\n              "label": "1"\n            },\n            {\n              "label": "2"\n            },\n            {\n              "label": "3"\n            },\n            {\n              "label": "4"\n            }\n          ]\n        },\n        {\n          "label": "Asilimia ya ufaulu",\n          "description": "Mpangilio huu mara nyingi hautakuwa na athari yoyote. Ni asilimia ya jumla ya alama inayohitajika kwa kupata pointi 1 wakati pointi moja kwa kazi nzima imewashwa, na kwa kupata mafanikio ya matokeo katika taarifa za Kiolesura cha Programu ya Uzoefu."\n        }\n      ]\n    },\n    {\n      "label": "Kiolesura cha mtumiaji",\n      "fields": [\n        {\n          "label": "Maandishi ya kitufe cha \\"Weka alama\\"",\n          "default": "Weka alama"\n        },\n        {\n          "label": "Maandishi ya kitufe cha \\"Wasilisha\\"",\n          "default": "Wasilisha"\n        },\n        {\n          "label": "Maelezo ya teknolojia ya usaidizi kwa kitufe cha \\"Weka alama\\"",\n          "default": "Weka alama majibu. Majibu yatatiwa alama kuwa sahihi, siyo sahihi au haijajibiwa."\n        },\n        {\n          "label": "Maandishi kwa kitufe cha \\"Onyesha suluhisho\\"",\n          "default": "Onyesha suluhisho"\n        },\n        {\n          "label": "Maelezo ya teknolojia ya usaidizi kwa kitufe cha \\"Onyesha Suluhisho\\"",\n          "default": "Onyesha suluhisho hilo. Chaguzi sahihi zitawekwa alama."\n        },\n        {\n          "label": "Jibu Sahihi (halijaonyeshwa)",\n          "default": "Jibu sahihi"\n        },\n        {\n          "label": "Jibu lisilo sahihi (halijaonyeshwa)",\n          "default": "Jibu lisilo sahihi"\n        },\n        {\n          "label": "Chaguo lilipaswa kuwekwa alama",\n          "default": "Lilipaswa kuwekwa alama"\n        },\n        {\n          "label": "Chaguo halikupaswa kuwekwa alama",\n          "default": "Halikupaswa kuwekwa alama"\n        },\n        {\n          "label": "Maandishi ya ujumbe wa \\"Inahitaji jibu\\"",\n          "default": "Tafadhali jibu kabla ya kutazama suluhisho"\n        },\n        {\n          "label": "Maandishi kwa kitufe cha \\"Jaribu tena\\"",\n          "default": "Jaribu tena"\n        },\n        {\n          "label": "Maelezo ya teknolojia ya usaidizi kwa kitufe cha \\"Jaribu tena\\"",\n          "default": "Jaribu tena kazi hiyo. Weka upya majibu yote na uanze kazi tena."\n        },\n        {\n          "label": "Matokeo yako",\n          "description": ":numna :total ni vigezo na vitabadilishwa na thamani yao husika.",\n          "default": "Umepata :num kati ya alama:total"\n        },\n        {\n          "label": "Weka alama mazungumzo ya uthibitisho",\n          "fields": [\n            {\n              "label": "Maandishi ya kichwa",\n              "default": "Umemaliza?"\n            },\n            {\n              "label": "Maandishi ya kiini",\n              "default": "Una uhakika unataka kumaliza?"\n            },\n            {\n              "label": "Ghairi lebo ya kitufe",\n              "default": "Ghairi"\n            },\n            {\n              "label": "Lebo ya kitufe cha kuthibitisha",\n              "default": "Maliza"\n            }\n          ]\n        },\n        {\n          "label": "Jaribu tena mazungumzo ya uthibitisho",\n          "fields": [\n            {\n              "label": "Maandishi ya kichwa",\n              "default": "Jaribu tena?"\n            },\n            {\n              "label": "Maandishi ya kiini",\n              "default": "Una uhakika unataka kujaribu tena?"\n            },\n            {\n              "label": "Ghairi lebo ya kitufe",\n              "default": "Ghairi"\n            },\n            {\n              "label": "Lebo ya kitufe cha kuthibitisha",\n              "default": "Jaribu tena"\n            }\n          ]\n        },\n        {\n          "label": "Maandishi ikiwa maandishi mbadala hayapo kwa picha",\n          "default": "Maandishi mbadala hayapo"\n        },\n        {\n          "label": "Close modal button label",\n          "default": "Close modal"\n        }\n      ]\n    }\n  ]\n}\n'),
(28, 'th', '{\n  "semantics": [\n    {\n      "label": "สื่อ",\n      "fields": [\n        {\n          "label": "ประเภท",\n          "description": "สื่อทางเลือกที่จะแสดงเหนือคำถาม (ถ้ามี)"\n        },\n        {\n          "label": "ปิดฟังก์ชั่นการซูมรูปภาพ"\n        }\n      ]\n    },\n    {\n      "label": "คำถาม"\n    },\n    {\n      "label": "ตัวเลือกที่มีอยู่",\n      "entity": "option",\n      "field": {\n        "label": "ตัวเลือก",\n        "fields": [\n          {\n            "label": "สื่อ",\n            "description": "Media to display as a choice."\n          },\n          {\n            "label": "Poster image"\n          },\n          {\n            "label": "ถูกต้อง"\n          }\n        ]\n      }\n    },\n    {\n      "label": "คำติชมโดยรวม",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "ค่าเริ่มต้น"\n            }\n          ],\n          "label": "กำหนดคำติชมแบบกำหนดเองสำหรับช่วงคะแนนใดๆ",\n          "description": "คลิกที่ปุ่ม \\"เพิ่มช่วง\\" เพื่อเพิ่มช่วงคะแนนตามที่คุณต้องการ เช่น 0-20% คะแนนแย่ 21-91% คะแนนปานกลาง 91-100% คะแนนดีมาก!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "ช่วงคะแนน"\n              },\n              {},\n              {\n                "label": "คำติชมสำหรับช่วงคะแนนที่กำหนด",\n                "placeholder": "ใส่คำติชม"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "การตั้งค่าพฤติกรรม",\n      "description": "ตัวเลือกเหล่านี้จะช่วยคุณควบคุมพฤติกรรมการทำงานของงาน",\n      "fields": [\n        {\n          "label": "เปิดใช้งานปุ่ม \\"ลองอีกครั้ง\\""\n        },\n        {\n          "label": "เปิดใช้งานปุ่ม \\"แสดงคำตอบ\\""\n        },\n        {\n          "label": "แสดงกล่องสนทนายืนยันเมื่อกด \\"ตรวจสอบ\\""\n        },\n        {\n          "label": "แสดงกล่องสนทนายืนยันเมื่อกด \\"ลองอีกครั้ง\\""\n        },\n        {\n          "label": "ให้คะแนน 1 คะแนนสำหรับคำถามทั้งหมด",\n          "description": "ให้คะแนน 1 คะแนนสำหรับคำถามเมื่อร้อยละของคะแนนสูงกว่าร้อยละที่ตั้งค่าไว้ในการผ่าน"\n        },\n        {\n          "label": "ต้องการคำตอบก่อนที่จะดูคำตอบที่ถูกต้อง"\n        },\n        {\n          "label": "ประเภทคำถาม",\n          "description": "เลือกลักษณะและพฤติกรรมของคำถาม",\n          "options": [\n            {\n              "label": "อัตโนมัติ"\n            },\n            {\n              "label": "เลือกหลายตัวเลือก (ช่องเลือก)"\n            },\n            {\n              "label": "เลือกเดียว (ปุ่มวิทยุ)"\n            }\n          ]\n        },\n        {\n          "label": "อัตราส่วนของด้าน",\n          "description": "เลือกอัตราส่วนของตัวเลือกที่แสดง",\n          "options": [\n            {\n              "label": "อัตโนมัติ"\n            },\n            {\n              "label": "16:9"\n            },\n            {\n              "label": "4:3"\n            },\n            {\n              "label": "3:2"\n            },\n            {\n              "label": "1:1"\n            }\n          ]\n        },\n        {\n          "label": "จำนวนตัวเลือกสูงสุดต่อแถว",\n          "description": "ตั้งค่าจำนวนตัวเลือกสูงสุดต่อแถวเพื่อให้คำถามดูถูกต้อง",\n          "options": [\n            {\n              "label": "1"\n            },\n            {\n              "label": "2"\n            },\n            {\n              "label": "3"\n            },\n            {\n              "label": "4"\n            }\n          ]\n        },\n        {\n          "label": "ร้อยละการผ่าน",\n          "description": "การตั้งค่านี้มักจะไม่มีผลใด ๆ กับการให้คะแนนครึ่งหนึ่งสำหรับงานทั้งหมดเมื่อใช้คะแนนการผ่านร้อยละในรายงาน xAPI"\n        }\n      ]\n    },\n    {\n      "label": "อินเตอร์เฟซผู้ใช้",\n      "fields": [\n        {\n          "label": "ข้อความสำหรับปุ่ม \\"ตรวจสอบ\\"",\n          "default": "ตรวจสอบ"\n        },\n        {\n          "label": "ข้อความสำหรับปุ่ม \\"ส่ง\\"",\n          "default": "ส่ง"\n        },\n        {\n          "label": "คำอธิบายเทคโนโลยีช่วยให้เข้าใจได้สำหรับปุ่ม \\"ตรวจสอบ\\"",\n          "default": "ตรวจสอบคำตอบ การตอบรับจะถูกทำเครื่องหมายว่าถูกต้อง ไม่ถูกต้อง หรือไม่ได้ตอบ"\n        },\n        {\n          "label": "ข้อความสำหรับปุ่ม \\"แสดงคำตอบ\\"",\n          "default": "แสดงคำตอบ"\n        },\n        {\n          "label": "คำอธิบายเทคโนโลยีช่วยให้เข้าใจได้สำหรับปุ่ม \\"แสดงคำตอบ\\"",\n          "default": "แสดงคำตอบที่ถูกต้อง"\n        },\n        {\n          "label": "คำตอบที่ถูกต้อง (ไม่แสดง)",\n          "default": "คำตอบที่ถูกต้อง"\n        },\n        {\n          "label": "คำตอบผิด (ไม่แสดง)",\n          "default": "คำตอบผิด"\n        },\n        {\n          "label": "ตัวเลือกควรถูกต้อง",\n          "default": "ควรถูกต้อง"\n        },\n        {\n          "label": "ตัวเลือกไม่ควรถูกต้อง",\n          "default": "ไม่ควรถูกต้อง"\n        },\n        {\n          "label": "ข้อความสำหรับข้อความ \\"ต้องมีคำตอบ\\"",\n          "default": "กรุณาตอบก่อนที่จะดูคำตอบ"\n        },\n        {\n          "label": "ข้อความสำหรับปุ่ม \\"ลองอีกครั้ง\\"",\n          "default": "ลองอีกครั้ง"\n        },\n        {\n          "label": "คำอธิบายเทคโนโลยีช่วยให้เข้าใจได้สำหรับปุ่ม \\"ลองอีกครั้ง\\"",\n          "default": "ลองทำงานอีกครั้งโดยไม่ต้องเริ่มต้นใหม่"\n        },\n        {\n          "label": "ข้อความสำหรับปุ่ม \\"ยกเลิก\\"",\n          "description": ":num and :total are variables and will be replaced by their respective values.",\n          "default": "You got :num out of :total points"\n        },\n        {\n          "label": "Check confirmation dialog",\n          "fields": [\n            {\n              "label": "Header text",\n              "default": "Finish?"\n            },\n            {\n              "label": "Body text",\n              "default": "Are you sure you want to finish?"\n            },\n            {\n              "label": "Cancel button label",\n              "default": "Cancel"\n            },\n            {\n              "label": "Confirm button label",\n              "default": "Finish"\n            }\n          ]\n        },\n        {\n          "label": "Retry confirmation dialog",\n          "fields": [\n            {\n              "label": "Header text",\n              "default": "Retry?"\n            },\n            {\n              "label": "Body text",\n              "default": "Are you sure you wish to retry?"\n            },\n            {\n              "label": "Cancel button label",\n              "default": "Cancel"\n            },\n            {\n              "label": "Confirm button label",\n              "default": "Retry"\n            }\n          ]\n        },\n        {\n          "label": "Text if alt text is missing for an image",\n          "default": "Alt text missing"\n        },\n        {\n          "label": "Close modal button label",\n          "default": "Close modal"\n        }\n      ]\n    }\n  ]\n}\n'),
(28, 'tr', '{\n  "semantics": [\n    {\n      "label": "Medya",\n      "fields": [\n        {\n          "label": "Tip",\n          "description": "Sorunun üzerinde görüntülenecek isteğe bağlı medya."\n        },\n        {\n          "label": "Görüntü yakınlaştırmayı devre dışı bırak"\n        }\n      ]\n    },\n    {\n      "label": "Soru"\n    },\n    {\n      "label": "Mevcut seçenekler",\n      "entity": "seçenek",\n      "field": {\n        "label": "Seçenek",\n        "fields": [\n          {\n            "label": "Medya",\n            "description": "Media to display as a choice."\n          },\n          {\n            "label": "Poster image"\n          },\n          {\n            "label": "Doğru"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Toplam Geribildirim",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Varsayılan"\n            }\n          ],\n          "label": "Herhangi bir puan aralığı için özel geri bildirim tanımlayın",\n          "description": "İstediğiniz kadar aralık eklemek için \\"Aralık ekle\\" düğmesini tıklayın. Örnek: %0-20 Kötü puan, %21-91 Ortalama Puan, %91-100 Büyük Puan!",\n          "entity": "aralık",\n          "field": {\n            "fields": [\n              {\n                "label": "Puan Aralığı"\n              },\n              {},\n              {\n                "label": "Tanımlanmış puan aralığı için geri bildirim",\n                "placeholder": "Geri bildirimi doldurun"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Davranış yarları",\n      "description": "Bu seçenekler görevin nasıl davranması gerektiğini kontrol etmenizi sağlar.",\n      "fields": [\n        {\n          "label": "\\"Yeniden dene\\" düğmesini devreye al"\n        },\n        {\n          "label": "\\"Çözüm göster\\" düğmesini devreye al"\n        },\n        {\n          "label": "\\"Kontrol Et\\" onay iletişim kutusunu göster"\n        },\n        {\n          "label": "\\"Yeniden Dene\\" onay iletişim kutusunu göster"\n        },\n        {\n          "label": "Tüm soru için bir puan verin",\n          "description": "Yüzde puanı, geçme yüzdesinden yüksekse soruya bir puan verir"\n        },\n        {\n          "label": "Çözümü görüntülenmesi için cevap verilmesini zorunlu tut"\n        },\n        {\n          "label": "Soru Türü",\n          "description": "Sorunun görünüş ve davranışını seçin.",\n          "options": [\n            {\n              "label": "Otomatik"\n            },\n            {\n              "label": "Çoktan Seçmeli (Onay kutuları)"\n            },\n            {\n              "label": "Tek Seçim (Radyo Düğmeleri)"\n            }\n          ]\n        },\n        {\n          "label": "En boy oranı",\n          "description": "Alternatiflerin en boy oranını seçin",\n          "options": [\n            {\n              "label": "Otomatik"\n            },\n            {\n              "label": "16:9"\n            },\n            {\n              "label": "4:3"\n            },\n            {\n              "label": "3:2"\n            },\n            {\n              "label": "1:1"\n            }\n          ]\n        },\n        {\n          "label": "Satır başına maksimum seçenek",\n          "description": "Soruların iyi görünmesini sağlamak için satır başına maksimum seçenek sayısını ayarlayın.",\n          "options": [\n            {\n              "label": "1"\n            },\n            {\n              "label": "2"\n            },\n            {\n              "label": "3"\n            },\n            {\n              "label": "4"\n            }\n          ]\n        },\n        {\n          "label": "Geçme notu (%)",\n          "description": "Bu ayarın çoğu zaman herhangi bir etkisi olmaz. Tüm görev için bir puan etkinleştirildiğinde 1 puan almak ve eğitim yönetim sisteminde (Ör: EBA) sonucun başarılı olması için gereken toplam puanın yüzdesidir."\n        }\n      ]\n    },\n    {\n      "label": "Kullanıcı arayüzü",\n      "fields": [\n        {\n          "label": "\\"Kontrol Et\\" düğmesi için metin",\n          "default": "Kontrol Et"\n        },\n        {\n          "label": "Text for \\"Submit\\" button",\n          "default": "Submit"\n        },\n        {\n          "label": "\\"Kontrol Et\\" düğmesi için yardımcı teknoloji açıklaması",\n          "default": "Cevapları kontrol edin. Cevaplar doğru, yanlış veya cevapsız olarak işaretlenecektir."\n        },\n        {\n          "label": "\\"Çözümü göster\\" düğmesi için metin",\n          "default": "Çözümü göster"\n        },\n        {\n          "label": "\\"Çözümü Göster\\" düğmesi için yardımcı teknoloji açıklaması",\n          "default": "Çözümü göster. Doğru seçenekler işaretlenecektir."\n        },\n        {\n          "label": "Doğru Cevap (görüntülenmiyor)",\n          "default": "Doğru cevap"\n        },\n        {\n          "label": "Yanlış Cevap (görüntülenmiyor)",\n          "default": "Yanlış cevap"\n        },\n        {\n          "label": "Seçenek işaretlenmeliydi",\n          "default": "İşaretlenmeliydi"\n        },\n        {\n          "label": "Seçenek işaretlenmemeliydi",\n          "default": "İşaretlenmemeliydi"\n        },\n        {\n          "label": "\\"Cevap gerekiyor\\" mesajı için metin",\n          "default": "Lütfen çözümü görmeden önce cevaplayın"\n        },\n        {\n          "label": "\\"Yeniden Dene\\" düğmesi metni",\n          "default": "Yeniden Dene"\n        },\n        {\n          "label": "\\"Yeniden Dene\\" düğmesi için yardımcı teknoloji açıklaması",\n          "default": "Görevi yeniden deneyin. Tüm yanıtları sıfırlayın ve görevi yeniden başlatın."\n        },\n        {\n          "label": "Sonucun",\n          "description": ":num ve :total değişkenlerdir ve ilgili değerleriyle değiştirilecektir.",\n          "default": ":total puandan :num puan aldın"\n        },\n        {\n          "label": "Onay iletişim kutusunu kontrol edin",\n          "fields": [\n            {\n              "label": "Başlık metni",\n              "default": "Bitir"\n            },\n            {\n              "label": "Gövde metni",\n              "default": "Bitirmek istediğinize emin misiniz?"\n            },\n            {\n              "label": "İptal düğmesi etiketi",\n              "default": "Hayır"\n            },\n            {\n              "label": "Onaylama düğmesi etiketi",\n              "default": "Evet"\n            }\n          ]\n        },\n        {\n          "label": "Yeniden dene iletişim kutusunun kontrolü",\n          "fields": [\n            {\n              "label": "Başlık metni",\n              "default": "Yeniden Dene"\n            },\n            {\n              "label": "Gövde metni",\n              "default": "Yeniden denemek istediğinizden emin misiniz?"\n            },\n            {\n              "label": "İptal düğmesi etiketi",\n              "default": "Hayır"\n            },\n            {\n              "label": "Onaylama düğmesi etiketi",\n              "default": "Evet"\n            }\n          ]\n        },\n        {\n          "label": "Bir resim için alternatif metin eksikse metin",\n          "default": "Alternatif metin eksik"\n        },\n        {\n          "label": "Close modal button label",\n          "default": "Close modal"\n        }\n      ]\n    }\n  ]\n}\n'),
(28, 'uk', '{\n  "semantics": [\n    {\n      "label": "Медіа",\n      "fields": [\n        {\n          "label": "Тип",\n          "description": "Необов''язковий носій для відображення питання."\n        },\n        {\n          "label": "Вимкнути масштабування зображення"\n        }\n      ]\n    },\n    {\n      "label": "Питання"\n    },\n    {\n      "label": "Доступні параметри",\n      "entity": "опція",\n      "field": {\n        "label": "Опція",\n        "fields": [\n          {\n            "label": "Медіа",\n            "description": "Media to display as a choice."\n          },\n          {\n            "label": "Poster image"\n          },\n          {\n            "label": "Правильно"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Загальний зворотний зв''язок",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "За замовчуванням"\n            }\n          ],\n          "label": "Визначити відгук користувача для будь-якого діапазону балів",\n          "description": "Натисніть кнопку \\"Додати діапазон\\", щоб додати стільки діапазонів, скільки вам потрібно. Приклад: 0-20% Погана оцінка, 21-91% Середня оцінка, 91-100% Відмінна оцінка!",\n          "entity": "діапазон",\n          "field": {\n            "fields": [\n              {\n                "label": "Діапазон очок"\n              },\n              {},\n              {\n                "label": "Відгук для певного діапазону балів",\n                "placeholder": "Заповніть відгук"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Налаштування поведінки",\n      "description": "Ці параметри дозволять вам контролювати поведінку завдання.",\n      "fields": [\n        {\n          "label": "Увімкнути кнопку \\"Повторити\\""\n        },\n        {\n          "label": "Включити кнопку \\"Показати рішення\\""\n        },\n        {\n          "label": "Показати діалогове вікно підтвердження під час \\"Перевірки\\""\n        },\n        {\n          "label": "Показати діалогове вікно підтвердження при \\"Повторній спробі\\""\n        },\n        {\n          "label": "Поставте один бал за все питання",\n          "description": "Присуджується один бал за питання, якщо відсоткова оцінка вища, ніж відсоток проходження"\n        },\n        {\n          "label": "Потрібна відповідь перед переглядом рішення"\n        },\n        {\n          "label": "Тип питання",\n          "description": "Виберіть зовнішній вигляд та поведінку питання.",\n          "options": [\n            {\n              "label": "Автоматично"\n            },\n            {\n              "label": "Множинний вибір (прапорці)"\n            },\n            {\n              "label": "Єдиний вибір (радіо-кнопки)"\n            }\n          ]\n        },\n        {\n          "label": "Співвідношення сторін",\n          "description": "Виберіть співвідношення сторін альтернатив",\n          "options": [\n            {\n              "label": "Автоматично"\n            },\n            {\n              "label": "16:9"\n            },\n            {\n              "label": "4:3"\n            },\n            {\n              "label": "3:2"\n            },\n            {\n              "label": "1:1"\n            }\n          ]\n        },\n        {\n          "label": "Максимальна кількість альтернатив у рядку",\n          "description": "Встановіть максимальну кількість варіантів у рядку, щоб питання виглядали правильно.",\n          "options": [\n            {\n              "label": "1"\n            },\n            {\n              "label": "2"\n            },\n            {\n              "label": "3"\n            },\n            {\n              "label": "4"\n            }\n          ]\n        },\n        {\n          "label": "Відсоток проходження",\n          "description": "Це налаштування часто не має жодного ефекту. Це відсоток від загального балу, необхідний для отримання 1 бала, коли включено один бал за все завдання, і для отримання результату. успіх в операторах xAPI."\n        }\n      ]\n    },\n    {\n      "label": "Інтерфейс користувача",\n      "fields": [\n        {\n          "label": "Текст для кнопки \\"Перевірити\\"",\n          "default": "Перевірити"\n        },\n        {\n          "label": "Текст для кнопки \\"Відправити\\"",\n          "default": "Надіслати"\n        },\n        {\n          "label": "Опис допоміжної технології для кнопки \\"Перевірити\\"",\n          "default": "Перевірте відповіді. Відповіді будуть позначені як правильні, неправильні або без відповіді."\n        },\n        {\n          "label": "Текст для кнопки \\"Показати рішення\\"",\n          "default": "Показати рішення"\n        },\n        {\n          "label": "Опис допоміжної технології для кнопки \\"Показати рішення\\"",\n          "default": "Показати рішення. Правильні варіанти будуть позначені."\n        },\n        {\n          "label": "Правильна відповідь (не відображається)",\n          "default": "Правильна відповідь"\n        },\n        {\n          "label": "Неправильна відповідь (не відображається)",\n          "default": "Неправильна відповідь"\n        },\n        {\n          "label": "Опція має бути перевірена",\n          "default": "Повинно бути перевірено"\n        },\n        {\n          "label": "Опція не повинна бути відзначена",\n          "default": "Не повинен був перевірятися"\n        },\n        {\n          "label": "Текст повідомлення \\"Потрібна відповідь\\"",\n          "default": "Будь ласка, дайте відповідь перед переглядом рішення"\n        },\n        {\n          "label": "Текст для кнопки \\"Повторити\\"",\n          "default": "Повторити спробу"\n        },\n        {\n          "label": "Опис допоміжної технології для кнопки \\"Повторити\\"",\n          "default": "Повторіть спробу. Скиньте всі відповіді та запустіть завдання знову."\n        },\n        {\n          "label": "Ваш результат",\n          "description": ":num і :total є змінними і будуть замінені відповідними значеннями.",\n          "default": "Ви отримали :num з :total очок"\n        },\n        {\n          "label": "Діалог підтвердження перевірки",\n          "fields": [\n            {\n              "label": "Текст заголовка",\n              "default": "Готово?"\n            },\n            {\n              "label": "Основний текст",\n              "default": "Ви впевнені, що хочете закінчити?"\n            },\n            {\n              "label": "Назва кнопки \\"Скасувати\\"",\n              "default": "Скасувати"\n            },\n            {\n              "label": "Підтвердити мітку кнопки",\n              "default": "Готово"\n            }\n          ]\n        },\n        {\n          "label": "Повторити діалогове вікно підтвердження",\n          "fields": [\n            {\n              "label": "Текст заголовка",\n              "default": "Повторити спробу?"\n            },\n            {\n              "label": "Основний текст",\n              "default": "Ви впевнені, що хочете повторити спробу?"\n            },\n            {\n              "label": "Назва кнопки \\"Скасувати\\"",\n              "default": "Скасувати"\n            },\n            {\n              "label": "Підтвердити мітку кнопки",\n              "default": "Повторити спробу"\n            }\n          ]\n        },\n        {\n          "label": "Текст, якщо для зображення відсутній текст, що заміщає",\n          "default": "Відсутній альтернативний текст"\n        },\n        {\n          "label": "Close modal button label",\n          "default": "Close modal"\n        }\n      ]\n    }\n  ]\n}\n'),
(28, 'zh-hant', '{\n  "semantics": [\n    {\n      "label": "Media",\n      "fields": [\n        {\n          "label": "Type",\n          "description": "Optional media to display above the question."\n        },\n        {\n          "label": "Disable image zooming"\n        }\n      ]\n    },\n    {\n      "label": "Question"\n    },\n    {\n      "label": "Available options",\n      "entity": "option",\n      "field": {\n        "label": "Option",\n        "fields": [\n          {\n            "label": "Media",\n            "description": "Media to display as a choice."\n          },\n          {\n            "label": "Poster image"\n          },\n          {\n            "label": "Correct"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Default"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Behavioural settings",\n      "description": "These options will let you control how the task behaves.",\n      "fields": [\n        {\n          "label": "Enable \\"Retry\\" button"\n        },\n        {\n          "label": "Enable \\"Show Solution\\" button"\n        },\n        {\n          "label": "Show confirmation dialog on \\"Check\\""\n        },\n        {\n          "label": "Show confirmation dialog on \\"Retry\\""\n        },\n        {\n          "label": "Give one point for the whole question",\n          "description": "Awards one point to the question if the percentage score is higher than the pass percentage"\n        },\n        {\n          "label": "Require answer before the solution can be viewed"\n        },\n        {\n          "label": "Question Type",\n          "description": "Select the look and behaviour of the question.",\n          "options": [\n            {\n              "label": "Automatic"\n            },\n            {\n              "label": "Multiple Choice (Checkboxes)"\n            },\n            {\n              "label": "Single Choice (Radio Buttons)"\n            }\n          ]\n        },\n        {\n          "label": "Aspect ratio",\n          "description": "Select the aspect ratio of the alternatives",\n          "options": [\n            {\n              "label": "Automatic"\n            },\n            {\n              "label": "16:9"\n            },\n            {\n              "label": "4:3"\n            },\n            {\n              "label": "3:2"\n            },\n            {\n              "label": "1:1"\n            }\n          ]\n        },\n        {\n          "label": "Maximum alternatives per row",\n          "description": "Set the maximum number of alternatives per row to ensure the questions look alright.",\n          "options": [\n            {\n              "label": "1"\n            },\n            {\n              "label": "2"\n            },\n            {\n              "label": "3"\n            },\n            {\n              "label": "4"\n            }\n          ]\n        },\n        {\n          "label": "Pass percentage",\n          "description": "This setting often won''t have any effect. It is the percentage of the total score required for getting 1 point when one point for the entire task is enabled, and for getting result.success in xAPI statements."\n        }\n      ]\n    },\n    {\n      "label": "User interface",\n      "fields": [\n        {\n          "label": "Text for \\"Check\\" button",\n          "default": "查看"\n        },\n        {\n          "label": "Text for \\"Submit\\" button",\n          "default": "提交"\n        },\n        {\n          "label": "Assistive technology description for \\"Check\\" button",\n          "default": "查看答案。回答會評為正確、錯誤或未回答。"\n        },\n        {\n          "label": "Text for \\"Show solution\\" button",\n          "default": "顯示解答"\n        },\n        {\n          "label": "Assistive technology description for \\"Show Solution\\" button",\n          "default": "顯示解答。此測試會以正解評分。"\n        },\n        {\n          "label": "Correct Answer (not displayed)",\n          "default": "Correct answer"\n        },\n        {\n          "label": "Wrong Answer (not displayed)",\n          "default": "Wrong answer"\n        },\n        {\n          "label": "Option should have been checked",\n          "default": "Should have been checked"\n        },\n        {\n          "label": "Option should not have been checked",\n          "default": "Should not have been checked"\n        },\n        {\n          "label": "Text for \\"Requires answer\\" message",\n          "default": "Please answer before viewing the solution"\n        },\n        {\n          "label": "Text for \\"Retry\\" button",\n          "default": "重試"\n        },\n        {\n          "label": "Assistive technology description for \\"Retry\\" button",\n          "default": "重新嘗試。重置所有回答，重新開始測試。"\n        },\n        {\n          "label": "Your result",\n          "description": ":num and :total are variables and will be replaced by their respective values.",\n          "default": "You got :num out of :total points"\n        },\n        {\n          "label": "Check confirmation dialog",\n          "fields": [\n            {\n              "label": "Header text",\n              "default": "完成嗎?"\n            },\n            {\n              "label": "Body text",\n              "default": "你確定要完成嗎？"\n            },\n            {\n              "label": "Cancel button label",\n              "default": "取消"\n            },\n            {\n              "label": "Confirm button label",\n              "default": "完成嗎"\n            }\n          ]\n        },\n        {\n          "label": "Retry confirmation dialog",\n          "fields": [\n            {\n              "label": "Header text",\n              "default": "重試?"\n            },\n            {\n              "label": "Body text",\n              "default": "Are you sure you wish to retry?"\n            },\n            {\n              "label": "Cancel button label",\n              "default": "取消"\n            },\n            {\n              "label": "Confirm button label",\n              "default": "重試"\n            }\n          ]\n        },\n        {\n          "label": "Text if alt text is missing for an image",\n          "default": "Alt text missing"\n        },\n        {\n          "label": "Close modal button label",\n          "default": "Close modal"\n        }\n      ]\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(30, 'af', '{\n  "semantics": [\n    {\n      "label": "Vraag of beskrywing"\n    },\n    {\n      "label": "Plekhouer teks",\n      "default": "Begin skryf...",\n      "description": "Teks wat aanvanklik in die invoerveld vertoon word. Sal outomaties verwyder word wanneer die gebruiker begin skryf."\n    },\n    {\n      "label": "Invoer rye",\n      "description": "Bepaal die hoogte van die invoerveld.",\n      "options": [\n        {\n          "label": "1 lyn"\n        },\n        {\n          "label": "2 lyne"\n        },\n        {\n          "label": "3 lyne"\n        },\n        {\n          "label": "10 lyne"\n        }\n      ]\n    }\n  ]\n}\n'),
(30, 'ar', '{\n  "semantics": [\n    {\n      "label": "سؤال أو وصف"\n    },\n    {\n      "label": "النص المؤقت",\n      "default": "Start writing...",\n      "description": "النص الذي سيظهر في البداية في حقل الإدخال. ستتم إزالته تلقائيًا عندما يبدأ المستخدم في الكتابة."\n    },\n    {\n      "label": "ادخال  السطور",\n      "description": "هنا يحدد ارتفاع حقل الادخال.",\n      "options": [\n        {\n          "label": "سطر واحد"\n        },\n        {\n          "label": "سطرين"\n        },\n        {\n          "label": "ثلاثة اسطر"\n        },\n        {\n          "label": "عشرة اسطر"\n        }\n      ]\n    }\n  ]\n}\n'),
(30, 'bg', '{\r\n  "semantics": [\r\n    {\r\n      "label": "Въпрос или описание"\r\n    },\r\n    {\r\n      "label": "Фонов текст в полето",\r\n      "default": "Започнете да пишете...",\r\n      "description": "Текст, който първоначално ще бъде показан в полето за въвеждане. Той ще изчезне автоматично, когато потребителят започне да пише."\r\n    },\r\n    {\r\n      "label": "Брой редове в текстовото поле",\r\n      "description": "Определя височината на текстовото поле.",\r\n      "options": [\r\n        {\r\n          "label": "1 ред"\r\n        },\r\n        {\r\n          "label": "2 реда"\r\n        },\r\n        {\r\n          "label": "3 реда"\r\n        },\r\n        {\r\n          "label": "10 реда"\r\n        }\r\n      ]\r\n    }\r\n  ]\r\n}\r\n'),
(30, 'bs', '{\n  "semantics": [\n    {\n      "label": "Question or description"\n    },\n    {\n      "label": "Placeholder text",\n      "default": "Start writing...",\n      "description": "Text that initially will be shown in the input field. Will be removed automatically when the user starts writing."\n    },\n    {\n      "label": "Input rows",\n      "description": "Determines the height of the input field.",\n      "options": [\n        {\n          "label": "1 line"\n        },\n        {\n          "label": "2 lines"\n        },\n        {\n          "label": "3 lines"\n        },\n        {\n          "label": "10 lines"\n        }\n      ]\n    }\n  ]\n}'),
(30, 'ca', '{\n  "semantics": [\n    {\n      "label": "Pregunta o descripció"\n    },\n    {\n      "label": "Text de l’espai reservat",\n      "default": "Comenceu a escriure...",\n      "description": "Text que inicialment es mostrarà al camp d’entrada. S’eliminarà automàticament quan l’usuari comenci a escriure."\n    },\n    {\n      "label": "Files d’introducció de text",\n      "description": "Determina l’alçada del camp d’introducció de text.",\n      "options": [\n        {\n          "label": "1 línia"\n        },\n        {\n          "label": "2 línies"\n        },\n        {\n          "label": "3 línies"\n        },\n        {\n          "label": "10 línies"\n        }\n      ]\n    }\n  ]\n}'),
(30, 'cs', '{\n  "semantics": [\n    {\n      "label": "Otázka nebo popis"\n    },\n    {\n      "label": "Zástupný text",\n      "default": "Začněte psát...",\n      "description": "Text, který se zpočátku zobrazí ve vstupním poli. Jakmile uživatel začne psát, bude automaticky odstraněn."\n    },\n    {\n      "label": "Vstupní řádky",\n      "description": "Určuje výšku vstupního pole.",\n      "options": [\n        {\n          "label": "1 řádek"\n        },\n        {\n          "label": "2 řádky"\n        },\n        {\n          "label": "3 řádky"\n        },\n        {\n          "label": "10 řádků"\n        }\n      ]\n    }\n  ]\n}\n'),
(30, 'da', '{\n  "semantics": [\n    {\n      "label": "Question or description"\n    },\n    {\n      "label": "Placeholder text",\n      "default": "Start writing...",\n      "description": "Text that initially will be shown in the input field. Will be removed automatically when the user starts writing."\n    },\n    {\n      "label": "Input rows",\n      "description": "Determines the height of the input field.",\n      "options": [\n        {\n          "label": "1 line"\n        },\n        {\n          "label": "2 lines"\n        },\n        {\n          "label": "3 lines"\n        },\n        {\n          "label": "10 lines"\n        }\n      ]\n    }\n  ]\n}'),
(30, 'de', '{\n  "semantics": [\n    {\n      "label": "Frage bzw. Aufgabenbeschreibung"\n    },\n    {\n      "label": "Platzhaltertext",\n      "default": "Schreibe hier hinein...",\n      "description": "Text der anfangs im Eingabefeld angezeigt wird. Wird automatisch entfernt, wenn der Nutzer anfängt zu schreiben."\n    },\n    {\n      "label": "Zeilen",\n      "description": "Bestimmt die Höhe des Eingabefelds.",\n      "options": [\n        {\n          "label": "1 Zeile"\n        },\n        {\n          "label": "2 Zeilen"\n        },\n        {\n          "label": "3 Zeilen"\n        },\n        {\n          "label": "10 Zeilen"\n        }\n      ]\n    }\n  ]\n}\n'),
(30, 'el', '{\n  "semantics": [\n    {\n      "label": "Ερώτηση ή περιγραφή"\n    },\n    {\n      "label": "Κείμενο πεδίου εισαγωγής",\n      "default": "Έναρξη γραψίματος...",\n      "description": "Κείμενο που εμφανίζεται στο πεδίο εισαγωγής. Εξαφανίζεται αυτόματα αμέσως μόλις ο χρήστης ξεκινήσει να γράφει."\n    },\n    {\n      "label": "Γραμμές πεδίου εισαγωγής",\n      "description": "Καθορίζει το ύψος του πεδίου εισαγωγής.",\n      "options": [\n        {\n          "label": "1 γραμμή"\n        },\n        {\n          "label": "2 γραμμές"\n        },\n        {\n          "label": "3 γραμμές"\n        },\n        {\n          "label": "10 γραμμές"\n        }\n      ]\n    }\n  ]\n}\n'),
(30, 'es', '{\n  "semantics": [\n    {\n      "label": "Pregunta o descripción"\n    },\n    {\n      "label": "Texto por defecto",\n      "default": "Empieza a escribir...",\n      "description": "Texto mostrado inicialmente en el campo de entrada. Se eliminará automáticamente cuando el usuario empiece a escribir."\n    },\n    {\n      "label": "Filas de entrada",\n      "description": "Determina la altura del campo de entrada.",\n      "options": [\n        {\n          "label": "1 línea"\n        },\n        {\n          "label": "2 líneas"\n        },\n        {\n          "label": "3 líneas"\n        },\n        {\n          "label": "10 líneas"\n        }\n      ]\n    }\n  ]\n}\n'),
