(31, 'da', '{\n  "semantics": [\n    {\n      "label": "Questionnaire elements",\n      "widgets": [\n        {\n          "label": "Default"\n        }\n      ],\n      "entity": "element",\n      "field": {\n        "label": "Choose library",\n        "fields": [\n          {\n            "label": "Library",\n            "description": "Choose a library"\n          },\n          {\n            "label": "Required field"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Success screen options",\n      "fields": [\n        {\n          "label": "Enable success screen"\n        },\n        {\n          "label": "Add success screen image",\n          "fields": [\n            {\n              "label": "Replace success icon with image"\n            }\n          ]\n        },\n        {\n          "label": "Text to display on submit",\n          "default": "You have completed the questionnaire."\n        }\n      ]\n    },\n    {\n      "label": "UI Elements",\n      "fields": [\n        {\n          "label": "Button labels",\n          "fields": [\n            {\n              "label": "Previous button label",\n              "default": "Back"\n            },\n            {\n              "label": "Continue button label",\n              "default": "Continue"\n            },\n            {\n              "label": "Next button label",\n              "default": "Next"\n            },\n            {\n              "label": "Submit button label",\n              "default": "Submit"\n            }\n          ]\n        },\n        {\n          "label": "Accessibility",\n          "fields": [\n            {\n              "label": "Required message exit button label",\n              "default": "Close error message"\n            },\n            {\n              "label": "Progress bar text",\n              "default": "Question %current of %max",\n              "description": "Used to tell assistive technologies what question it is. Variables: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Required message",\n          "default": "This question requires an answer",\n          "description": "Will display if this field is unanswered and required by a wrapper content type"\n        },\n        {\n          "label": "Required symbol text",\n          "default": "required",\n          "description": "Text that will accompany an asterisk to signal that a question is required"\n        },\n        {\n          "label": "Title for the submit screen",\n          "default": "You successfully answered all of the questions"\n        },\n        {\n          "label": "Subtitle for the submit screen",\n          "default": "Click below to submit your answers"\n        }\n      ]\n    }\n  ]\n}'),
(31, 'de', '{\n  "semantics": [\n    {\n      "label": "Fragen",\n      "widgets": [\n        {\n          "label": "Eingabemaske"\n        }\n      ],\n      "entity": "Frage",\n      "field": {\n        "label": "Wähle einen Fragetyp",\n        "fields": [\n          {\n            "label": "Fragetyp",\n            "description": "Wähle einen Fragetyp"\n          },\n          {\n            "label": "Erforderliches Feld"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Optionen für den Erfolgsbildschirm",\n      "fields": [\n        {\n          "label": "Erfolgsbildschirm aktivieren"\n        },\n        {\n          "label": "Füge ein Bild zum Erfolgsbildschirm hinzu",\n          "fields": [\n            {\n              "label": "Ersetze das Erfolgssymbol mit dem Bild"\n            }\n          ]\n        },\n        {\n          "label": "Text, der nach dem Absenden angezeigt wird",\n          "default": "Du hast alle Fragen erfolgreich beantwortet."\n        }\n      ]\n    },\n    {\n      "label": "Elemente der Benutzeroberfläche",\n      "fields": [\n        {\n          "label": "Button-Beschriftungen",\n          "fields": [\n            {\n              "label": "Beschriftung des \\"Zurück\\"-Buttons",\n              "default": "Zurück"\n            },\n            {\n              "label": "Beschriftung des \\"Weiter\\"-Buttons",\n              "default": "Weiter"\n            },\n            {\n              "label": "Beschriftung des \\"Weiter\\"-Buttons",\n              "default": "Weiter"\n            },\n            {\n              "label": "Beschriftung des \\"Absenden\\"-Buttons",\n              "default": "Absenden"\n            }\n          ]\n        },\n        {\n          "label": "Barrierefreiheit",\n          "fields": [\n            {\n              "label": "Beschriftung des \\"Schließe Fehlermeldung\\"-Buttons",\n              "default": "Schließe Fehlermeldung"\n            },\n            {\n              "label": "Text der Fortschrittsanzeige",\n              "default": "Frage %current von %max",\n              "description": "Text für Vorlesewerkzeuge, der mitteilt, um welche Frage es sich handelt. Mögliche Platzhalter sind %current und %max."\n            }\n          ]\n        },\n        {\n          "label": "Hinweis, dass eine Antwort erforderlich ist",\n          "default": "Diese Frage muss beantwortet werden.",\n          "description": "Wird angezeigt, wenn diese Frage nicht beantwortet wurde, aber benötigt wird."\n        },\n        {\n          "label": "Beschriftung bei Erforderlichkeit",\n          "default": "erforderlich",\n          "description": "Text, der zusätzlich zum Sternchen darauf hinweist, dass eine Antwort erforderlich ist."\n        },\n        {\n          "label": "Überschrift des Einsendebildschirms",\n          "default": "Du hast alle Fragen beantwortet!"\n        },\n        {\n          "label": "Weiterer Texte auf dem Einsendebildschirm",\n          "default": "Klicke unten auf den Button, um deine Antworten einzusenden!"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'el', '{\n  "semantics":[\n    {\n      "label":"Στοιχεία Ερωτηματολογίου",\n      "widgets":[\n        {\n          "label":"Βασικό"\n        }\n      ],\n      "entity":"στοιχειου",\n      "field":{\n        "label":"Επιλογή βιβλιοθήκης",\n        "fields":[\n          {\n            "label":"Βιβλιοθήκη",\n            "description":"Επιλέξτε μια βιβλιοθήκη"\n          },\n          {\n            "label":"Απαιτούμενο πεδίο"\n          }\n        ]\n      }\n    },\n    {\n      "label":"Επιλογές οθόνης επιτυχούς ολοκλήρωσης",\n      "fields":[\n        {\n          "label":"Ενεργοποίηση οθόνης επιτυχούς ολοκλήρωσης "\n        },\n        {\n          "label":"Προσθήκη εικόνας στην οθόνη επιτυχούς ολοκλήρωσης",\n          "fields":[\n            {\n              "label":"Αντικατάσταση εικονιδίου με εικόνα"\n            }\n          ]\n        },\n        {\n          "label":"Κείμενο το οποίο θα εμφανίζεται κατά την υποβολή",\n          "default":"Έχετε συμπληρώσει το ερωτηματολόγιο."\n        }\n      ]\n    },\n    {\n      "label":"Στοιχεία διεπαφής χρήστη",\n      "fields":[\n        {\n          "label":"Ετικέτες κουμπιών",\n          "fields":[\n            {\n              "label":"Ετικέτα κουμπιού \\"Προηγούμενο\\"",\n              "default":"Προηγούμενο"\n            },\n            {\n              "label":"Ετικέτα κουμπιού \\"Συνέχεια\\"",\n              "default":"Συνέχεια"\n            },\n            {\n              "label":"Ετικέτα κουμπιού \\"Επόμενο\\"",\n              "default":"Επόμενο"\n            },\n            {\n              "label":"Ετικέτα κουμπιού \\"Υποβολή\\"",\n              "default":"Υποβολή"\n            }\n          ]\n        },\n        {\n          "label":"Προσβασιμότητα",\n          "fields":[\n            {\n              "label":"Ετικέτα κουμπιού κλεισίματος μηνύματος για απαιτούμενη απάντηση",\n              "default":"Κλείσιμο μηνύματος σφάλματος"\n            },\n            {\n              "label":"Κείμενο μπάρας προόδου",\n              "default":"Ερώτηση %current από %max",\n              "description":"Χρησιμοποιείται για να ενημερώνει τις υποστηρικτικές τεχνολογίες για το ποια ερώτηση πρόκειται. Μεταβλητές: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label":"Μήνυμα για απαιτούμενη απάντηση",\n          "default":"Απαιτείται απάντηση σε αυτή την ερώτηση",\n          "description":"Θα εμφανιστεί αν το πεδίο αυτό δεν έχει απαντηθεί και απαιτείται απάντηση"\n        },\n        {\n          "label":"Κείμενο για σύμβολο απαιτούμενης απάντησης",\n          "default":"Απαιτείται",\n          "description":"Κείμενο που θα συνοδεύει έναν αστερίσκο για να σηματοδοτήσει ότι απαιτείται η απάντηση στην ερώτηση"\n        },\n        {\n          "label":"Τίτλος οθόνης υποβολής",\n          "default":"Έχετε απαντήσει επιτυχώς σε όλες τις ερωτήσεις"\n        },\n        {\n          "label":"Υπότιτλος οθόνης υποβολής",\n          "default":"Κάντε κλικ παρακάτω για να υποβάλετε τις απαντήσεις σας"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'es', '{\n  "semantics": [\n    {\n      "label": "Elementos del cuestionario",\n      "widgets": [\n        {\n          "label": "Por defecto"\n        }\n      ],\n      "entity": "elemento",\n      "field": {\n        "label": "Elegir biblioteca",\n        "fields": [\n          {\n            "label": "Biblioteca",\n            "description": "Elegir una biblioteca"\n          },\n          {\n            "label": "Campo obligatorio"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Opciones de la pantalla de éxito",\n      "fields": [\n        {\n          "label": "Habilitar pantalla de éxito"\n        },\n        {\n          "label": "Añadir imagen a la pantalla de éxito",\n          "fields": [\n            {\n              "label": "Remplazar icono de éxito con imagen"\n            }\n          ]\n        },\n        {\n          "label": "Texto a mostrar al enviar",\n          "default": "Has completado el cuestionario."\n        }\n      ]\n    },\n    {\n      "label": "Elementos de la interfaz de usuario",\n      "fields": [\n        {\n          "label": "Etiquetas de botón",\n          "fields": [\n            {\n              "label": "Etiqueta botón Anterior",\n              "default": "Atrás"\n            },\n            {\n              "label": "Etiqueta botón Continuar",\n              "default": "Continuar"\n            },\n            {\n              "label": "Etiqueta botón Siguiente",\n              "default": "Siguiente"\n            },\n            {\n              "label": "Etiqueta botón Enviar",\n              "default": "Enviar"\n            }\n          ]\n        },\n        {\n          "label": "Accesibilidad",\n          "fields": [\n            {\n              "label": "Etiqueta del botón de salida del mensaje obligatorio",\n              "default": "Mensaje de error al cerrar"\n            },\n            {\n              "label": "Texto de Barra del Progreso",\n              "default": "Pregunta %current de %max",\n              "description": "Usado para decirle a tecnologías de asistencia qué pregunta es. Variables: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Mensaje Obligatorio",\n          "default": "Esta pregunta requiere una respuesta",\n          "description": "Se mostrará si este campo no ha sido contestado y es requerido por un tipo de contenido wrapper"\n        },\n        {\n          "label": "Texto de símbolo Obligatorio",\n          "default": "obligatorio",\n          "description": "Texto que acompañará a un asterisco para señalar que una pregunta es obligatoria"\n        },\n        {\n          "label": "Título para la pantalla para enviar",\n          "default": "Has conseguido contestar todas las preguntas"\n        },\n        {\n          "label": "Subtítulo para la pantalla para envío",\n          "default": "Hacer clic en la parte inferior para enviar tus respuestas"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'es-mx', '{\n  "semantics": [\n    {\n      "label": "Elementos del Questionnaire",\n      "widgets": [\n        {\n          "label": "Predeterminado"\n        }\n      ],\n      "entity": "elemento",\n      "field": {\n        "label": "Elegir biblioteca",\n        "fields": [\n          {\n            "label": "Biblioteca",\n            "description": "Elegir una biblioteca"\n          },\n          {\n            "label": "Campo obligatorio"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Opciones pantalla éxito",\n      "fields": [\n        {\n          "label": "Habilitar pantalla éxito"\n        },\n        {\n          "label": "Añadir imagen pantalla éxito",\n          "fields": [\n            {\n              "label": "Remplazar ícono de éxito con imagen"\n            }\n          ]\n        },\n        {\n          "label": "Texto a mostrar al enviar",\n          "default": "Usted ha completado el questionnaire."\n        }\n      ]\n    },\n    {\n      "label": "Elementos de Interfaz del Usuario",\n      "fields": [\n        {\n          "label": "Etiquetas botón",\n          "fields": [\n            {\n              "label": "Etiqueta botón Anterior",\n              "default": "Regresar"\n            },\n            {\n              "label": "Etiqueta botón Continuar",\n              "default": "Continuar"\n            },\n            {\n              "label": "Etiqueta botón Siguiente",\n              "default": "Siguiente"\n            },\n            {\n              "label": "Etiqueta botón Enviar",\n              "default": "Enviar"\n            }\n          ]\n        },\n        {\n          "label": "Accesibilidad",\n          "fields": [\n            {\n              "label": "Etiqueta botón mensaje salida obligatoria",\n              "default": "Mensaje cerrar error"\n            },\n            {\n              "label": "Texto de Barra del Progreso",\n              "default": "Pregunta %current de %max",\n              "description": "Usado para decirle a tecnologías asistivas cual pregunta es. Variables: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Mensaje Obligatorio",\n          "default": "Esta pregunta requiere una respuesta",\n          "description": "Se mostrará si este campo no es contestado y es requerido por un tipo de contenido envoltorio"\n        },\n        {\n          "label": "Texto de símbolo Obligatorio",\n          "default": "obligatorio",\n          "description": "Texto que acompañará un asterisco para señalar que una pregunta es obligatoria"\n        },\n        {\n          "label": "Título para la pantalla para enviar",\n          "default": "Usted contestó exitosamente todas las preguntas"\n        },\n        {\n          "label": "Subtítulo para la pantalla para envío",\n          "default": "Hacer clic debajo para enviar sus respuestas"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'et', '{\n  "semantics": [\n    {\n      "label": "Küsitluse elemendid",\n      "widgets": [\n        {\n          "label": "Vaikimisi"\n        }\n      ],\n      "entity": "element",\n      "field": {\n        "label": "Vali teek",\n        "fields": [\n          {\n            "label": "Teek",\n            "description": "Vali teek"\n          },\n          {\n            "label": "Nõutud väli"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Edukuva valikud",\n      "fields": [\n        {\n          "label": "Luba edukuva"\n        },\n        {\n          "label": "Lisa edukuva pilt",\n          "fields": [\n            {\n              "label": "Asenda eduikoon pildiga"\n            }\n          ]\n        },\n        {\n          "label": "Tekst, mida näidata esitamisel",\n          "default": "Oled küsitluse täitnud."\n        }\n      ]\n    },\n    {\n      "label": "Kasutajaliidese elemendid",\n      "fields": [\n        {\n          "label": "Nuppude sildid",\n          "fields": [\n            {\n              "label": "Eelmine nupu silt",\n              "default": "Tagasi"\n            },\n            {\n              "label": "Jätka nupu silt",\n              "default": "Jätka"\n            },\n            {\n              "label": "Järgmine nupu silt",\n              "default": "Järgmine"\n            },\n            {\n              "label": "Esita nupu silt",\n              "default": "Esita"\n            }\n          ]\n        },\n        {\n          "label": "Puudega kasutaja",\n          "fields": [\n            {\n              "label": "Nõutud teade, välju nupu silt",\n              "default": "Sulge veateade"\n            },\n            {\n              "label": "Edenemisriba tekst",\n              "default": "Küsimus %current kokku %max küsimusest",\n              "description": "Kasutatakse assisteeriva tehnoloogiaga, et öelda, mis küsimusega on tegu. Muutujad: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Nõutud teade",\n          "default": "See küsimus vajab vastust",\n          "description": "Näidatakse, kui väli on täitmata, kuigi täitmine on nõutud ümbrise sisutüübi poolt"\n        },\n        {\n          "label": "Nõutud sümboli tekst",\n          "default": "nõutud",\n          "description": "Tekst, mis saadab tärni, osutamaks, et küsimus on nõutud"\n        },\n        {\n          "label": "Esita kuva pealkiri",\n          "default": "Oled edukalt vastanud kõigile küsimustele"\n        },\n        {\n          "label": "Esita kuva subtiiter",\n          "default": "Oma vastuste esitamiseks kliki allpool"\n        }\n      ]\n    }\n  ]\n}'),
(31, 'eu', '{\n  "semantics": [\n    {\n      "label": "Galdetegiaren elementuak",\n      "widgets": [\n        {\n          "label": "Lehenetsia"\n        }\n      ],\n      "entity": "elementua",\n      "field": {\n        "label": "Aukeratu liburutegia",\n        "fields": [\n          {\n            "label": "Liburutegia",\n            "description": "Aukeratu liburutegi bat"\n          },\n          {\n            "label": "Beharrezko eremua"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Arrakasta pantailaren aukerak",\n      "fields": [\n        {\n          "label": "Gaitu arrakasta pantaila"\n        },\n        {\n          "label": "Gehitu arrakasta pantailaren irudia",\n          "fields": [\n            {\n              "label": "Jarri irudia arrakasta ikonoaren ordez"\n            }\n          ]\n        },\n        {\n          "label": "Bidalketan erakusteko testua",\n          "default": "Bukatu duzu galdetegia."\n        }\n      ]\n    },\n    {\n      "label": "Interfazearen elementuak",\n      "fields": [\n        {\n          "label": "Botoien etiketak",\n          "fields": [\n            {\n              "label": "Aurrekoa botoiaren etiketa",\n              "default": "Aurrekoa"\n            },\n            {\n              "label": "Jarraitu botoiaren etiketa",\n              "default": "Jarraitu"\n            },\n            {\n              "label": "Hurrengoa botoiaren etiketa",\n              "default": "Hurrengoa"\n            },\n            {\n              "label": "Bidali botoiaren etiketa",\n              "default": "Bidali"\n            }\n          ]\n        },\n        {\n          "label": "Erabilerraztasuna",\n          "fields": [\n            {\n              "label": "Beharrezko mezua irteera botoiaren etiketa",\n              "default": "Itxi errore mezua"\n            },\n            {\n              "label": "Aurrerapen barraren testua",\n              "default": "%max galderetatik %current -garrena",\n              "description": "Laguntza teknologiei uneko galdera zein den adierazteko erabili da. Aldagaiak: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Beharrezko mezua",\n          "default": "Galdera hau erantzun behar da",\n          "description": "Erakutsik du eremu honek ez dauka erantzunik eta eduki motaren paketerentzat ezinbestekoa dela"\n        },\n        {\n          "label": "Beharrezko ikurra testua",\n          "default": "beharrezkoa",\n          "description": "Galdera batek erantzuna eskatzen duela adierazten duen izartxoari laguntzen dion testua"\n        },\n        {\n          "label": "Bidalketa pantailaren izenburua",\n          "default": "Galdera guztiak zuzen erantzun dituzu"\n        },\n        {\n          "label": "Bidalketa pantailaren azpititulua",\n          "default": "Egin klik azpian zure erantzunak bidaltzeko"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'fa', '{\n  "semantics": [\n    {\n      "label": "مؤلفه‌های پرسشنامه",\n      "widgets": [\n        {\n          "label": "پیش‌فرض"\n        }\n      ],\n      "entity": "مؤلفه",\n      "field": {\n        "label": "انتخاب کتابخانه",\n        "fields": [\n          {\n            "label": "کتابخانه",\n            "description": "انتخاب یک کتابخانه"\n          },\n          {\n            "label": "فیلد الزامی"\n          }\n        ]\n      }\n    },\n    {\n      "label": "گزینه‌های صفحه موفقیت",\n      "fields": [\n        {\n          "label": "فعال‌سازی صفحه موفقیت"\n        },\n        {\n          "label": "افزودن تصویر صفحه موفقیت",\n          "fields": [\n            {\n              "label": "جایگزین کردن شمایل موفقیت با تصویر"\n            }\n          ]\n        },\n        {\n          "label": "متن نمایش داده شده در هنگام ارسال",\n          "default": "شما پرسشنامه را تکمیل کردید."\n        }\n      ]\n    },\n    {\n      "label": "مؤلفه‌های UI",\n      "fields": [\n        {\n          "label": "برچسب‌های دکمه",\n          "fields": [\n            {\n              "label": "برچسب دکمه قبلی",\n              "default": "عقب"\n            },\n            {\n              "label": "برچسب دکمه ادامه",\n              "default": "ادامه"\n            },\n            {\n              "label": "برچسب دکمه بعدی",\n              "default": "بعدی"\n            },\n            {\n              "label": "برچسب دکمه ارسال",\n              "default": "ارسال"\n            }\n          ]\n        },\n        {\n          "label": "دسترس‌پذیری",\n          "fields": [\n            {\n              "label": "برچسب دکمه خروج از پیام الزامی",\n              "default": "بستن پیغام خطا"\n            },\n            {\n              "label": "متن نوار پیشروی",\n              "default": "سؤال %current از %max",\n              "description": "مورد استفاده برای اطلاع دادن به فناوری‌های کمکی که کدام سؤال است. متغیرها: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "پیغام الزامی",\n          "default": "پاسخ به این سؤال الزامی است",\n          "description": "در صورتی که فیلد پاسخ داده نشود و برای یک نوع محتوای پوشش‌دهنده الزامی باشد، نمایش داده خواهد شد"\n        },\n        {\n          "label": "متن نماد الزامی",\n          "default": "الزامی",\n          "description": "متنی که یک ستاره به آن ضمیمه می‌شود تا علامت دهد که یک سؤال الزامی است"\n        },\n        {\n          "label": "عنوان برای صفحه ارسال",\n          "default": "شما با موفقیت به همه سؤالات پاسخ دادید"\n        },\n        {\n          "label": "زیرنویس برای صفحه ارسال",\n          "default": "برای ارسال پاسخ‌هایتان در زیر کلیک کنید"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'fi', '{\n  "semantics": [\n    {\n      "label": "Kyselyn osat",\n      "widgets": [\n        {\n          "label": "Oletus"\n        }\n      ],\n      "entity": "osa",\n      "field": {\n        "label": "Valitse tyyppi",\n        "fields": [\n          {\n            "label": "Tyyppi",\n            "description": "Valitse kyselyn tyyppi"\n          },\n          {\n            "label": "Vaadittu kenttä"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Päätösnäkymän valinnat",\n      "fields": [\n        {\n          "label": "Salli päätösnäkymä"\n        },\n        {\n          "label": "Päätösnäkymän kuva",\n          "fields": [\n            {\n              "label": "Vaihda ikonin tilalle kuva"\n            }\n          ]\n        },\n        {\n          "label": "Teksti kyselyn lähdettyä eteenpäin",\n          "default": "Vastaukset lähetetty."\n        }\n      ]\n    },\n    {\n      "label": "Käyttöliittymä",\n      "fields": [\n        {\n          "label": "Painikkeiden tekstit",\n          "fields": [\n            {\n              "label": "Palaa",\n              "default": "Palaa"\n            },\n            {\n              "label": "Jatka",\n              "default": "Jatka"\n            },\n            {\n              "label": "Seuraava",\n              "default": "Seuraava"\n            },\n            {\n              "label": "Lähetä",\n              "default": "Lähetä"\n            }\n          ]\n        },\n        {\n          "label": "Esteettömyys",\n          "fields": [\n            {\n              "label": "Poistuminen virheilmoituksesta",\n              "default": "Sulje virheilmoitus"\n            },\n            {\n              "label": "Edistymistä kuvaava teksti",\n              "default": "Kysymys %current/%max",\n              "description": "Käytetään esteettömyysteknologioissa ilmaisemaan kuluva kysymys. Muuttujat: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Pakollinen kysymys",\n          "default": "Tähän kysymykseen on pakko vastata",\n          "description": "Näytetään jos on jätety vastaamatta ja kysymykseen on pakko vastata kysymystyypin mukaan"\n        },\n        {\n          "label": "Teksti pakollisuutta ilmaisevaan symboliin",\n          "default": "vaaditaan",\n          "description": "Teksti joka näytetään *-merkin yhteydessä, kun kysymykseen on pakko vastata"\n        },\n        {\n          "label": "Kyselyn lähetyssivun otsikko",\n          "default": "Olet onnistuneesti vastannut kaikkiin kysymyksiin"\n        },\n        {\n          "label": "Kyselyn lähetyssivun alaotsikko",\n          "default": "Klikkaa lähettääksesi vastauksesi"\n        }\n      ]\n    }\n  ]\n}'),
(31, 'fr', '{\n  "semantics": [\n    {\n      "label": "Eléments du questionnaire",\n      "widgets": [\n        {\n          "label": "Par défaut"\n        }\n      ],\n      "entity": "Elément",\n      "field": {\n        "label": "Choisir une bibliothèque",\n        "fields": [\n          {\n            "label": "Bibliothèque",\n            "description": "Choisir une bibliothèque"\n          },\n          {\n            "label": "Champ requis"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Ecran en cas de réussite",\n      "fields": [\n        {\n          "label": "Activer l''écran"\n        },\n        {\n          "label": "Ajouter une image à l''écran",\n          "fields": [\n            {\n              "label": "Rempacez l''icône de la réussite avec une image"\n            }\n          ]\n        },\n        {\n          "label": "Texte affiché à l''envoi des réponses",\n          "default": "Vous avez terminé le questionnaire."\n        }\n      ]\n    },\n    {\n      "label": "Apparence",\n      "fields": [\n        {\n          "label": "Etiquettes des boutons",\n          "fields": [\n            {\n              "label": "Etiquette du bouton Précédent",\n              "default": "Précédent"\n            },\n            {\n              "label": "Etiquette du bouton Continuer",\n              "default": "Continuer"\n            },\n            {\n              "label": "Etiquette du bouton Suivant",\n              "default": "Suivant"\n            },\n            {\n              "label": "Etiquette du bouton Envoyer les résultats",\n              "default": "Envoyer les résultats"\n            }\n          ]\n        },\n        {\n          "label": "Accessibilité",\n          "fields": [\n            {\n              "label": "Etiquette du bouton pour fermer le message d''erreur",\n              "default": "Fermer le message d''erreur"\n            },\n            {\n              "label": "Texte de la barre de progression",\n              "default": "Question %current de %max",\n              "description": "Utilisé pour indiquer la question courante aux technologies d''accessibilité. Variables: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Message requis",\n          "default": "Vous devez répondre à cette question",\n          "description": "Ce message s''affiche si la question est sans réponse et la réponse est requise par un conteneur."\n        },\n        {\n          "label": "Texte de symbole requis",\n          "default": "obligatoire",\n          "description": "Texte accompagnant l''astérisque pour expliquer que la question est obligatoire."\n        },\n        {\n          "label": "Titre de l''écran Envoyer les résultats",\n          "default": "Vous avez réussi à répondre à toutes les questions"\n        },\n        {\n          "label": "Sous-titre de l''écran Envoyer les résultats",\n          "default": "Cliquez ci-dessous pour envoyer les résultats"\n        }\n      ]\n    }\n  ]\n}'),
(31, 'gl', '{\n  "semantics": [\n    {\n      "label": "Elementos do cuestionario",\n      "widgets": [\n        {\n          "label": "Por defecto"\n        }\n      ],\n      "entity": "elemento",\n      "field": {\n        "label": "Escoller biblioteca",\n        "fields": [\n          {\n            "label": "Biblioteca",\n            "description": "Escolle unha biblioteca"\n          },\n          {\n            "label": "Campo requirido"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Opcións da pantalla de acerto",\n      "fields": [\n        {\n          "label": "Activar pantalla de acerto"\n        },\n        {\n          "label": "Engadir imaxe de pantalla de acerto",\n          "fields": [\n            {\n              "label": "Substituir o icono de acerto por unha imaxe"\n            }\n          ]\n        },\n        {\n          "label": "Texto amosado ao enviar",\n          "default": "Completaches o cuestionario."\n        }\n      ]\n    },\n    {\n      "label": "Elementos da interface de usuario",\n      "fields": [\n        {\n          "label": "Texto dos botóns",\n          "fields": [\n            {\n              "label": "Texto do botón atrás",\n              "default": "Atrás"\n            },\n            {\n              "label": "Texto do botón continuar",\n              "default": "Continuar"\n            },\n            {\n              "label": "Texto do botón seguinte",\n              "default": "Seguinte"\n            },\n            {\n              "label": "Texto do botón enviar",\n              "default": "Enviar"\n            }\n          ]\n        },\n        {\n          "label": "Accesibilidade",\n          "fields": [\n            {\n              "label": "Texto de mensaxe requirida para o botón de saída",\n              "default": "Mensaxe de erro na saída"\n            },\n            {\n              "label": "Texto para a barra de progreso",\n              "default": "Pregunta %current de %max",\n              "description": "Usada para dicirlle ás tecnoloxías de asistenca que pregunta é. Variables: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Mensaxe de resposta requirida",\n          "default": "Esta pregunta require unha resposta",\n          "description": "Amosarase se este campo non ten resposta e é requirido por un tipo de contido wrapper"\n        },\n        {\n          "label": "Texto de símbolo requirido",\n          "default": "requirido",\n          "description": "Texto que acompaña a un asterisco para indicar que a pregunta é requirida"\n        },\n        {\n          "label": "Título para a xanela de envío",\n          "default": "Respostaches todas as preguntas correctamente"\n        },\n        {\n          "label": "Subtítulo para a xanela de envío",\n          "default": "Preme na parte inferior para enviar as túas respostas"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'he', '{\n  "semantics": [\n    {\n      "label": "רכיבי שאלון",\n      "widgets": [\n        {\n          "label": "ברירת מחדל"\n        }\n      ],\n      "entity": "רכיב",\n      "field": {\n        "label": "יש לבחור ספריה",\n        "fields": [\n          {\n            "label": "ספרייה",\n            "description": "יש לבחור ספרייה"\n          },\n          {\n            "label": "שדה נדרש"\n          }\n        ]\n      }\n    },\n    {\n      "label": "אפשרויות מסך הצלחה",\n      "fields": [\n        {\n          "label": "הפעילו מסך הצלחה"\n        },\n        {\n          "label": "יש להוסיף תמונת מסך הצלחה",\n          "fields": [\n            {\n              "label": "החלפת סמל הצלחה בתמונה"\n            }\n          ]\n        },\n        {\n          "label": "התוכן שיש להציג בעת שליחה",\n          "default": "סיימתם את השאלון."\n        }\n      ]\n    },\n    {\n      "label": "רכיבי ממשק",\n      "fields": [\n        {\n          "label": "תוויות הכפתור",\n          "fields": [\n            {\n              "label": "תווית כפתור הקודם",\n              "default": "חזרה"\n            },\n            {\n              "label": "תווית כפתור המשך",\n              "default": "המשך"\n            },\n            {\n              "label": "תווית כפתור הבא",\n              "default": "הבא"\n            },\n            {\n              "label": "תווית כפתור שליחה",\n              "default": "שליחה"\n            }\n          ]\n        },\n        {\n          "label": "נגישות",\n          "fields": [\n            {\n              "label": "תווית הכרחית לכפתור הודעת יציאה",\n              "default": "סגירת הודעת השגיאה"\n            },\n            {\n              "label": "תיאור סרגל התקדמות",\n              "default": "שאלה %current מתוך %max",\n              "description": "משמש עבור תמיכה טכנולוגית להבנת השאלה. משתנים: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "הודעה הכרחית",\n          "default": "השאלה מחייבת תשובה",\n          "description": "יוצג אם שדה זה לא נענה ונדרש על ידי סוג של תוכן על המשלב רכיב זה בתוכו"\n        },\n        {\n          "label": "סמל תוכן הכרחי",\n          "default": "הכרחי",\n          "description": "תוכן יסומן בכוכבית לציין שהשאלה נדרשת"\n        },\n        {\n          "label": "כותרת עבור מסך שליחה",\n          "default": "עניתם על כל השאלות בהצלחה"\n        },\n        {\n          "label": "כותרת משנה למסך השליחה",\n          "default": "יש להקיש על הכפתור למטה לשליחת התשובה"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'hu', '{\n  "semantics": [\n    {\n      "label": "Questionnaire elements",\n      "widgets": [\n        {\n          "label": "Default"\n        }\n      ],\n      "entity": "element",\n      "field": {\n        "label": "Choose library",\n        "fields": [\n          {\n            "label": "Library",\n            "description": "Choose a library"\n          },\n          {\n            "label": "Required field"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Success screen options",\n      "fields": [\n        {\n          "label": "Enable success screen"\n        },\n        {\n          "label": "Add success screen image",\n          "fields": [\n            {\n              "label": "Replace success icon with image"\n            }\n          ]\n        },\n        {\n          "label": "Text to display on submit",\n          "default": "You have completed the questionnaire."\n        }\n      ]\n    },\n    {\n      "label": "UI Elements",\n      "fields": [\n        {\n          "label": "Button labels",\n          "fields": [\n            {\n              "label": "Previous button label",\n              "default": "Back"\n            },\n            {\n              "label": "Continue button label",\n              "default": "Continue"\n            },\n            {\n              "label": "Next button label",\n              "default": "Next"\n            },\n            {\n              "label": "Submit button label",\n              "default": "Submit"\n            }\n          ]\n        },\n        {\n          "label": "Accessibility",\n          "fields": [\n            {\n              "label": "Required message exit button label",\n              "default": "Close error message"\n            },\n            {\n              "label": "Progress bar text",\n              "default": "Question %current of %max",\n              "description": "Used to tell assistive technologies what question it is. Variables: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Required message",\n          "default": "This question requires an answer",\n          "description": "Will display if this field is unanswered and required by a wrapper content type"\n        },\n        {\n          "label": "Required symbol text",\n          "default": "required",\n          "description": "Text that will accompany an asterisk to signal that a question is required"\n        },\n        {\n          "label": "Title for the submit screen",\n          "default": "You successfully answered all of the questions"\n        },\n        {\n          "label": "Subtitle for the submit screen",\n          "default": "Click below to submit your answers"\n        }\n      ]\n    }\n  ]\n}'),
(31, 'it', '{\n  "semantics": [\n    {\n      "label": "Elementi del questionario",\n      "widgets": [\n        {\n          "label": "Predefinito"\n        }\n      ],\n      "entity": "elemento",\n      "field": {\n        "label": "Scegli libreria",\n        "fields": [\n          {\n            "label": "Libreria",\n            "description": "Scegli una libreria"\n          },\n          {\n            "label": "Campo obbligatorio"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Opzioni della schermata di successo",\n      "fields": [\n        {\n          "label": "Abilita schermata di successo"\n        },\n        {\n          "label": "Aggiungi immagine alla schermata di successo",\n          "fields": [\n            {\n              "label": "Sostituisci l''icona di successo con un''immagine"\n            }\n          ]\n        },\n        {\n          "label": "Testo da mostrare su invio",\n          "default": "Hai completato il questionario"\n        }\n      ]\n    },\n    {\n      "label": "Elementi di UI",\n      "fields": [\n        {\n          "label": "Etichette dei pulsanti",\n          "fields": [\n            {\n              "label": "Etichetta del pulsante Precedente",\n              "default": "Precedente"\n            },\n            {\n              "label": "Etichetta per pulsante Continua",\n              "default": "Continua"\n            },\n            {\n              "label": "Etichetta del pulsante Prossimo",\n              "default": "Prossimo"\n            },\n            {\n              "label": "Etichetta del pulsante Invio",\n              "default": "Invio"\n            }\n          ]\n        },\n        {\n          "label": "Accessibilità",\n          "fields": [\n            {\n              "label": "Etichetta del messaggio obbligatorio per pulsante di uscita",\n              "default": "Messaggio di errore di chiusura"\n            },\n            {\n              "label": "Testo della barra di avanzamento",\n              "default": "Domanda %current di %max",\n              "description": "Usato per comunicare alle tecnologie assistive quale domanda è. Variabili: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Messaggio obbligatorio",\n          "default": "Questa domanda richiede una risposta",\n          "description": "Sarà mostrato se questo campo non contiene risposta ma è richiesto da un tipo di contenuto inglobato"\n        },\n        {\n          "label": "Richiede testo in formato di simbolo",\n          "default": "obbligatorio",\n          "description": "Testo che accompagnerà un asterisco per indicare che una domanda è necessaria"\n        },\n        {\n          "label": "Titolo per la schermata di invio",\n          "default": "Hai risposto positivamente a tutte le domande"\n        },\n        {\n          "label": "Sottotitolo per la schermata di invio",\n          "default": "Clicca qui sotto per inviare le tue risposte"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'ja', '{\n  "semantics": [\n    {\n      "label": "Questionnaire elements",\n      "widgets": [\n        {\n          "label": "Default"\n        }\n      ],\n      "entity": "element",\n      "field": {\n        "label": "Choose library",\n        "fields": [\n          {\n            "label": "Library",\n            "description": "Choose a library"\n          },\n          {\n            "label": "Required field"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Success screen options",\n      "fields": [\n        {\n          "label": "Enable success screen"\n        },\n        {\n          "label": "Add success screen image",\n          "fields": [\n            {\n              "label": "Replace success icon with image"\n            }\n          ]\n        },\n        {\n          "label": "Text to display on submit",\n          "default": "You have completed the questionnaire."\n        }\n      ]\n    },\n    {\n      "label": "UI Elements",\n      "fields": [\n        {\n          "label": "Button labels",\n          "fields": [\n            {\n              "label": "Previous button label",\n              "default": "Back"\n            },\n            {\n              "label": "Continue button label",\n              "default": "Continue"\n            },\n            {\n              "label": "Next button label",\n              "default": "Next"\n            },\n            {\n              "label": "Submit button label",\n              "default": "Submit"\n            }\n          ]\n        },\n        {\n          "label": "Accessibility",\n          "fields": [\n            {\n              "label": "Required message exit button label",\n              "default": "Close error message"\n            },\n            {\n              "label": "Progress bar text",\n              "default": "Question %current of %max",\n              "description": "Used to tell assistive technologies what question it is. Variables: [ %current, %max ]"\n   