(31, 'ka', '{\n  "semantics": [\n    {\n      "label": "კითხვარის ელემენტები",\n      "widgets": [\n        {\n          "label": "სტანდარტული"\n        }\n      ],\n      "entity": "ელემენტი",\n      "field": {\n        "label": "აირჩიეთ ბიბლიოთეკა",\n        "fields": [\n          {\n            "label": "ბიბლიოთეკა",\n            "description": "აირჩიეთ ბიბლიოთეკა"\n          },\n          {\n            "label": "სავალდებულო ველი"\n          }\n        ]\n      }\n    },\n    {\n      "label": "წარმატების ეკრანის პარამეტრები",\n      "fields": [\n        {\n          "label": "წარმატების ეკრანის ჩართვა"\n        },\n        {\n          "label": "დაამატეთ წარმატების ეკრანის სურათი",\n          "fields": [\n            {\n              "label": "შეცვალეთ წარმატების ღილაკი სურათით"\n            }\n          ]\n        },\n        {\n          "label": "გაგზავნაზე გამოსატანი ტექსტი",\n          "default": "თქვენ შეავსეთ კითხვარი."\n        }\n      ]\n    },\n    {\n      "label": "UI ელემენტები",\n      "fields": [\n        {\n          "label": "ღილაკების წარწერები",\n          "fields": [\n            {\n              "label": "უკან დაბრუნების ღილაკის დასახელება",\n              "default": "უკან"\n            },\n            {\n              "label": "გაგრძელების ღილაკის წარწერა",\n              "default": "გაგრძელება"\n            },\n            {\n              "label": "შემდეგი ღილაკის ეტიკეტი",\n              "default": "შემდეგი"\n            },\n            {\n              "label": "წარდგენის ღილაკის წარწერა",\n              "default": "წარდგენა"\n            }\n          ]\n        },\n        {\n          "label": "ხელმისაწვდომობა",\n          "fields": [\n            {\n              "label": "სავალდებულო შეტყობინებიდან გამოსვლის ღილაკის წარწერა",\n              "default": "დახურვის შეცდომის შეტყობინება"\n            },\n            {\n              "label": "პროგრესის ტექსტი",\n              "default": "შეკითხვა %current %max დან",\n              "description": "გამოიყენება დამხმარე ტექნოლოგიების საკარნახებლად, რა კითხვაა. ცვლადები: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "სავალდებულო შეტყობინება",\n          "default": "ეს შეკითხვა მოითხოვს პასუხს",\n          "description": "გამოჩნდება, როცა ეს ველი იქნება პასუხგაუცემელი"\n        },\n        {\n          "label": "აუცილებელი სიმბოლოს ტექსტი",\n          "default": "მოთხოვნილია",\n          "description": "ტექსტი, რომელიც თან ახლავს ვარსკვლავს, რათა მიუთითებდეს, რომ შეკითხვა საჭიროა"\n        },\n        {\n          "label": "სათაური გაგზავნის ეკრანისთვის",\n          "default": "თქვენ წარმატებით უპასუხეთ ყველა კითხვას"\n        },\n        {\n          "label": "სუბტიტრები გაგზავნის ეკრანისთვის",\n          "default": "დააწკაპუნეთ ქვემოთ თქვენი პასუხების გასაგზავნად"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'km', '{\n  "semantics": [\n    {\n      "label": "Questionnaire elements",\n      "widgets": [\n        {\n          "label": "Default"\n        }\n      ],\n      "entity": "element",\n      "field": {\n        "label": "Choose library",\n        "fields": [\n          {\n            "label": "Library",\n            "description": "Choose a library"\n          },\n          {\n            "label": "Required field"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Success screen options",\n      "fields": [\n        {\n          "label": "Enable success screen"\n        },\n        {\n          "label": "Add success screen image",\n          "fields": [\n            {\n              "label": "Replace success icon with image"\n            }\n          ]\n        },\n        {\n          "label": "Text to display on submit",\n          "default": "អ្នកបានបំពេញកម្រងសំណួររួចហើយ។"\n        }\n      ]\n    },\n    {\n      "label": "UI Elements",\n      "fields": [\n        {\n          "label": "Button labels",\n          "fields": [\n            {\n              "label": "Previous button label",\n              "default": "ត្រឡប់"\n            },\n            {\n              "label": "Continue button label",\n              "default": "បន្ត"\n            },\n            {\n              "label": "Next button label",\n              "default": "បន្ទាប់"\n            },\n            {\n              "label": "Submit button label",\n              "default": "ប្រគល់"\n            }\n          ]\n        },\n        {\n          "label": "Accessibility",\n          "fields": [\n            {\n              "label": "Required message exit button label",\n              "default": "បិទសារកំហុស"\n            },\n            {\n              "label": "Progress bar text",\n              "default": "សំណួរទី %current ចំណោម %max",\n              "description": "Used to tell assistive technologies what question it is. Variables: [ %current, %max ]"\n            }\n 