INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(31, 'ko', '{\n  "semantics": [\n    {\n      "label": "설문 요소",\n      "widgets": [\n        {\n          "label": "기본 설정"\n        }\n      ],\n      "entity": "요소",\n      "field": {\n        "label": "라이브러리 선택",\n        "fields": [\n          {\n            "label": "라이브러리",\n            "description": "라이브러리 선택"\n          },\n          {\n            "label": "필수 영역"\n          }\n        ]\n      }\n    },\n    {\n      "label": "성공 화면 옵션",\n      "fields": [\n        {\n          "label": "성공화면 활성화"\n        },\n        {\n          "label": "성공 화면 이미지 추가",\n          "fields": [\n            {\n              "label": "성공 아이콘을 이미지로 바꾸기"\n            }\n          ]\n        },\n        {\n          "label": "제출시 표시할 텍스트",\n          "default": "설문지를 완료하셨습니다."\n        }\n      ]\n    },\n    {\n      "label": "UI 요소",\n      "fields": [\n        {\n          "label": "버튼 레이블",\n          "fields": [\n            {\n              "label": "돌아가기 버튼 레이블",\n              "default": "돌아가기"\n            },\n            {\n              "label": "계속 버튼 레이블",\n              "default": "계속"\n            },\n            {\n              "label": "다음 버튼 레이블",\n              "default": "다음"\n            },\n            {\n              "label": "제출 버튼 레이블",\n              "default": "제출하기"\n            }\n          ]\n        },\n        {\n          "label": "접근성",\n          "fields": [\n            {\n              "label": "필수 메시지 종료 버튼 레이블",\n              "default": "에러 메시지 닫기"\n            },\n            {\n              "label": "진행률 표시줄 텍스트",\n              "default": "총 %max의 현재 %current 질문",\n              "description": "보조 기술에게 그것이 어떤 질문인지 알려주는 데 사용. 변수: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "필수 메시지",\n          "default": "이 설문 응답이 필수임",\n          "description": "이 영역이 응답되지 않고 래퍼 내용 유형에 필요한 경우 표시됨"\n        },\n        {\n          "label": "필수 심벌 텍스트",\n          "default": "필수",\n          "description": "질문이 필요함을 알리는 별표와 함께 제공되는 텍스트"\n        },\n        {\n          "label": "제출 화면 제목",\n          "default": "모든 질문에 성공적으로 답변하셨습니다."\n        },\n        {\n          "label": "제출 화면의 부제목",\n          "default": "답변을 제출하려면 아래를 클릭하십시오."\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'lt', '{\n  "semantics": [\n    {\n      "label": "Klausimyno elementai",\n      "widgets": [\n        {\n          "label": "Numatytasis"\n        }\n      ],\n      "entity": "elementas",\n      "field": {\n        "label": "Pasirinkite biblioteką",\n        "fields": [\n          {\n            "label": "Biblioteka",\n            "description": "Pasirinkite biblioteką"\n          },\n          {\n            "label": "Privalomas laukas"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Sėkmės ekrano parinktys",\n      "fields": [\n        {\n          "label": "Įgalinti sėkmės ekraną"\n        },\n        {\n          "label": "Pridėkite sėkmės ekrano vaizdą",\n          "fields": [\n            {\n              "label": "Pakeisti sėkmės piktogramą vaizdu"\n            }\n          ]\n        },\n        {\n          "label": "Tekstas, kuris bus rodomas pateikiant",\n          "default": "Jūs užpildėte klausimyną."\n        }\n      ]\n    },\n    {\n      "label": "UI elementai",\n      "fields": [\n        {\n          "label": "Mygtukų pavadinimai",\n          "fields": [\n            {\n              "label": "Mygtuko Ankstesnis pavadinimas",\n              "default": "Atgal"\n            },\n            {\n              "label": "Mygtuko Tęsti pavadinimas",\n              "default": "Tęsti"\n            },\n            {\n              "label": "Mygtuko Kitas pavadinimas",\n              "default": "Kitas"\n            },\n            {\n              "label": "Mygtuko Pateikti pavadinimas",\n              "default": "Pateikti"\n            }\n          ]\n        },\n        {\n          "label": "Prieinamumas",\n          "fields": [\n            {\n              "label": "Required message exit button label",\n              "default": "Uždaryti klaidos pranešimą"\n            },\n            {\n              "label": "Pažangos juostos tekstas",\n              "default": "Klausimas %current iš %max",\n              "description": "Used to tell assistive technologies what question it is. Variables: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Reikalingas pranešimas",\n          "default": "Šis klausimas reikalauja atsakymo",\n          "description": "Will display if this field is unanswered and required by a wrapper content type"\n        },\n        {\n          "label": "Required symbol text",\n          "default": "reikalaujama",\n          "description": "Text that will accompany an asterisk to signal that a question is required"\n        },\n        {\n          "label": "Title for the submit screen",\n          "default": "You successfully answered all of the questions"\n        },\n        {\n          "label": "Subtitle for the submit screen",\n          "default": "Click below to submit your answers"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'lv', '{\n  "semantics": [\n    {\n      "widgets": [\n        {\n          "label": "Pēc noklusējuma"\n        }\n      ],\n      "label": "Anketas elementi",\n      "entity": "elements",\n      "field": {\n        "label": "Izvēlieties bibliotēku",\n        "fields": [\n          {\n            "label": "Bibliotēka",\n            "description": "Izvēlieties bibliotēku"\n          },\n          {\n            "label": "Obligāts lauks"\n          }\n        ]\n      }\n    },\n    {\n      "fields": [\n        {\n          "label": "Iespējot veiksmīga rezultāta ekrānu"\n        },\n        {\n          "label": "Pievienot veiksmīga rezultāta ekrāna attēlu",\n          "fields": [\n            {\n              "label": "Aizstāt veiksmīga rezultāta ikonu ar attēlu"\n            }\n          ]\n        },\n        {\n          "label": "Teksts, kas jāparāda iesniegšanas brīdī",\n          "default": "Jūs esat aizpildījis anketu."\n        }\n      ],\n      "label": "Veiksmīga rezultāta ekrāna opcijas"\n    },\n    {\n      "label": "Lietotāja saskarnes elementi",\n      "fields": [\n        {\n          "label": "Pogu etiķetes",\n          "fields": [\n            {\n              "default": "Atpakaļ",\n              "label": "Pogas \\"Atpakaļ\\" etiķete"\n            },\n            {\n              "default": "Turpināt",\n              "label": "Pogas \\"Turpināt\\" etiķete"\n            },\n            {\n              "label": "Pogas \\"Nākamais\\" etiķete",\n              "default": "Nākamais"\n            },\n            {\n              "label": "Pogas \\"Iesniegt\\" etiķete",\n              "default": "Iesniegt"\n            }\n          ]\n        },\n        {\n          "label": "Pieejamība",\n          "fields": [\n            {\n              "label": "Obligātuma ziņas aizvēršanas pogas etiķete",\n              "default": "Aizvērt kļūdas paziņojumu"\n            },\n            {\n              "label": "Progresa joslas teksts",\n              "default": "Jautājums %current no %max",\n              "description": "Izmanto, lai asistīvās tehnoloģijas informētu par jautājumu numuru. Mainīgie: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Ziņa par obligātumu",\n          "default": "Šis jautājums jāatbild obligāti",\n          "description": "Tiks parādīts, ja šis lauks ir neatbildēts un paredzēts kā obligāts"\n        },\n        {\n          "label": "Obligātuma simbola teksts",\n          "default": "obligāts",\n          "description": "Teksts, kas tiks pievienots zvaigznītei, lai norādītu, ka jautājums ir obligāts"\n        },\n        {\n          "label": "Iesniegšanas ekrāna nosaukums",\n          "default": "Jūs veiksmīgi atbildējāt uz visiem jautājumiem"\n        },\n        {\n          "label": "Iesniegšanas ekrāna apakšvirsraksts",\n          "default": "Noklikšķiniet zemāk, lai iesniegtu atbildes"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'mn', '{\n  "semantics": [\n    {\n      "widgets": [\n        {\n          "label": "Өгөгдмөл"\n        }\n      ],\n      "field": {\n        "label": "Номын санг сонгох",\n        "fields": [\n          {\n            "description": "Номын сан сонгоно уу",\n            "label": "Номын сан"\n          },\n          {\n            "label": "шаардлагатай талбар"\n          }\n        ]\n      },\n      "label": "Санал асуулгын элементүүд",\n      "entity": "элемент"\n    },\n    {\n      "label": "Амжилттай дэлгэцийн сонголтууд",\n      "fields": [\n        {\n          "label": "Амжилттай дэлгэцийг идэвхжүүлнэ үү"\n        },\n        {\n          "label": "Амжилттай дэлгэцийн зураг нэмнэ үү",\n          "fields": [\n            {\n              "label": "Амжилтын дүрсийг зургаар солино уу"\n            }\n          ]\n        },\n        {\n          "label": "Илгээхэд харуулах текст",\n          "default": "Та санал асуулгын хуудсыг бөглөсөн байна."\n        }\n      ]\n    },\n    {\n      "label": "UI элементүүд",\n      "fields": [\n        {\n          "fields": [\n            {\n              "label": "Өмнөх товчлуурын шошго",\n              "default": "Буцах"\n            },\n            {\n              "label": "Үргэлжлүүлэх товчлуурын шошго",\n              "default": "Үргэлжлүүлэх"\n            },\n            {\n              "label": "Дараагийн товчлуурын шошго",\n              "default": "Дараачийн"\n            },\n            {\n              "label": "Илгээх товчлуурын шошго",\n              "default": "Илгээх"\n            }\n          ],\n          "label": "Товчлуурын шошго"\n        },\n        {\n          "label": "Хүртээмжтэй байдал",\n          "fields": [\n            {\n              "default": "Алдааны мэдэгдлийг хаах",\n              "label": "Шаардлагатай мессежээс гарах товчлуурын шошго"\n            },\n            {\n              "default": "Асуулт %max-аас %current гүйдэл",\n              "label": "Явцын мөрний текст",\n              "description": "Энэ нь ямар асуулт болохыг туслах технологид хэлэхэд ашигладаг. Хувьсагчид: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Шаардлагатай зурвас",\n          "description": "Хэрэв энэ талбарт хариулт өгөөгүй бөгөөд боодлын контентын төрлөөр шаардлагатай бол харуулах болно",\n          "default": "Энэ асуулт хариултыг шаарддаг"\n        },\n        {\n          "default": "шаардлагатай",\n          "label": "Шаардлагатай тэмдэгтийн текст",\n          "description": "Асуулт шаардлагатай байгааг илтгэх одыг дагалдах текст"\n        },\n        {\n          "label": "Илгээх дэлгэцийн гарчиг",\n          "default": "Та бүх асуултанд амжилттай хариуллаа"\n        },\n        {\n          "label": "Илгээх дэлгэцийн хадмал гарчиг",\n          "default": "Доор дарж хариултаа илгээнэ үү"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'nb', '{\n  "semantics": [\n    {\n      "label": "Spørreskjema",\n      "widgets": [\n        {\n          "label": "Normal verdi"\n        }\n      ],\n      "entity": "Element",\n      "field": {\n        "label": "Velg innholdstype",\n        "fields": [\n          {\n            "label": "Innholdstype",\n            "description": "Velg innholdstype"\n          },\n          {\n            "label": "Nødvendig felt"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Suksess-skjerm alternativer",\n      "fields": [\n        {\n          "label": "Slå på suksess-skjerm"\n        },\n        {\n          "label": "Legg til bilde for suksess-skjerm",\n          "fields": [\n            {\n              "label": "Bytt ut suksess-skjerm ikon med bilde"\n            }\n          ]\n        },\n        {\n          "label": "Tekst ved ferdig innsending",\n          "default": "Du er nå ferdig med spørreskjemaet."\n        }\n      ]\n    },\n    {\n      "label": "Oversettelser av grensesnitt",\n      "fields": [\n        {\n          "label": "Knappe-etiketter",\n          "fields": [\n            {\n              "label": "Forrige knapp etikett",\n              "default": "Forrige"\n            },\n            {\n              "label": "Fortsett knapp etikett",\n              "default": "Fortsett"\n            },\n            {\n              "label": "Neste knapp etikett",\n              "default": "Neste"\n            },\n            {\n              "label": "Send inn etikett",\n              "default": "Send inn"\n            }\n          ]\n        },\n        {\n          "label": "Oversettelser for hjelpemiddelteknologi",\n          "fields": [\n            {\n              "label": "Lukk \\"nødvendig felt tekst\\" knappetikett",\n              "default": "Lukk feilmelding"\n            },\n            {\n              "label": "Framgang tekst",\n              "default": "Spørsmål %current av %max",\n              "description": "Brukes for å fortelle hjelpemiddelteknologier hvilket spørsmål vi er på. Variabler: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Nødvendig spørsmål tekst",\n          "default": "Dette spørsmålet krever et svar",\n          "description": "Vises dersom dette feltet er krevet, men ikke besvart."\n        },\n        {\n          "label": "Nødvendig spørsmål symbol tekst",\n          "default": "nødvendig",\n          "description": "Tekst som vil vises ved siden av asterisk for å vise at spørsmålet er påkrevd."\n        },\n        {\n          "label": "Tittel på innsendingsskjermen",\n          "default": "Du er nå ferdig med å svare på spørsmålene."\n        },\n        {\n          "label": "Hjelpetekst for innsendingsskjermen",\n          "default": "Trykk under for å sende inn dine svar"\n        }\n      ]\n    }\n  ]\n}'),
(31, 'nl', '{\n  "semantics": [\n    {\n      "label": "Enquête onderdelen",\n      "widgets": [\n        {\n          "label": "Standaard"\n        }\n      ],\n      "entity": "onderdeel",\n      "field": {\n        "label": "Kies een bibliotheek",\n        "fields": [\n          {\n            "label": "Bibliotheek",\n            "description": "Kies een bibliotheek"\n          },\n          {\n            "label": "Verplicht veld"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Opties succes-scherm",\n      "fields": [\n        {\n          "label": "Schakel succes-scherm in"\n        },\n        {\n          "label": "Voeg succes-schermafbeelding toe",\n          "fields": [\n            {\n              "label": "Vervang succes-pictogram door een afbeelding"\n            }\n          ]\n        },\n        {\n          "label": "Te tonen tekst voor verzenden",\n          "default": "Je hebt de enquête voltooid."\n        }\n      ]\n    },\n    {\n      "label": "Gebruikersinterface-elementen",\n      "fields": [\n        {\n          "label": "Knoplabels",\n          "fields": [\n            {\n              "label": "Label van \\"Vorige\\"-knop",\n              "default": "Vorige"\n            },\n            {\n              "label": "Label van \\"Doorgaan\\"-knop",\n              "default": "Doorgaan"\n            },\n            {\n              "label": "Label van \\"Volgende\\"-knop",\n              "default": "Volgende"\n            },\n            {\n              "label": "Label van \\"Verzend\\"-knop",\n              "default": "Verzend"\n            }\n          ]\n        },\n        {\n          "label": "Toegankelijkheid",\n          "fields": [\n            {\n              "label": "Label van \\"Foutmelding sluiten\\"-knop",\n              "default": "Foutmelding sluiten"\n            },\n            {\n              "label": "Tekst voortgangsbalk",\n              "default": "Vraag %current van %max",\n              "description": "Gebruikt om ondersteunende technologieën te vertellen welke vraag het is. Variabelen: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Verplicht bericht",\n          "default": "Op deze vraag moet een antwoord worden gegeven",\n          "description": "Wordt getoond als dit veld niet-beantwoord is, maar deze wel verplicht is op basis van het inhoudstype"\n        },\n        {\n          "label": "Tekst bij verplicht-symbool",\n          "default": "verplicht",\n          "description": "De tekst die bij een asterisk hoort om aan te geven dat een vraag verplicht is"\n        },\n        {\n          "label": "Titel voor het verzendscherm",\n          "default": "Je hebt alle vragen met succes beantwoord"\n        },\n        {\n          "label": "Ondertitel voor het verzendscherm",\n          "default": "Klik hieronder om je antwoorden te verzenden"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'nn', '{\n  "semantics": [\n    {\n      "label": "Spørreskjema",\n      "widgets": [\n        {\n          "label": "Normal verdi"\n        }\n      ],\n      "entity": "Element",\n      "field": {\n        "label": "Vel innhaldstype",\n        "fields": [\n          {\n            "label": "Innhaldstype",\n            "description": "Vel innhaldstype"\n          },\n          {\n            "label": "Nødvendig felt"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Suksess-skjerm alternativ",\n      "fields": [\n        {\n          "label": "Slå på suksess-skjerm"\n        },\n        {\n          "label": "Legg til bilete for suksess-skjerm",\n          "fields": [\n            {\n              "label": "Bytt ut suksess-skjerm ikon med bilete"\n            }\n          ]\n        },\n        {\n          "label": "Tekst ved ferdig innsending",\n          "default": "Du er no ferdig med spørreskjemaet."\n        }\n      ]\n    },\n    {\n      "label": "Oversettelser av grensesnitt",\n      "fields": [\n        {\n          "label": "Knappe-etiketter",\n          "fields": [\n            {\n              "label": "Forrige knapp etikett",\n              "default": "Førre"\n            },\n            {\n              "label": "Fortsett knapp etikett",\n              "default": "Hald fram"\n            },\n            {\n              "label": "Neste knapp etikett",\n              "default": "Neste"\n            },\n            {\n              "label": "Send inn etikett",\n              "default": "Send inn"\n            }\n          ]\n        },\n        {\n          "label": "Oversettelser for hjelpemiddelteknologi",\n          "fields": [\n            {\n              "label": "Lukk \\"nødvendig felt tekst\\" knappetikett",\n              "default": "Lukk feilmelding"\n            },\n            {\n              "label": "Framgang tekst",\n              "default": "Spørsmål %current av %max",\n              "description": "Brukes for å fortelle hjelpemiddelteknologier hvilket spørsmål vi er på. Variabler: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Nødvendig spørsmål tekst",\n          "default": "Dette spørsmålet krev eit svar",\n          "description": "Vises dersom dette feltet er krevet, men ikke besvart."\n        },\n        {\n          "label": "Nødvendig spørsmål symbol tekst",\n          "default": "påkravd",\n          "description": "Tekst som vil vises ved siden av asterisk for å vise at spørsmålet er påkrevd."\n        },\n        {\n          "label": "Tittel på innsendingsskjermen",\n          "default": "Du er no ferdig med å svare på spørsmåla."\n        },\n        {\n          "label": "Hjelpetekst for innsendingsskjermen",\n          "default": "Trykk under for å sende inn svara dine"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'pl', '{\n  "semantics": [\n    {\n      "label": "Elementy kwestionariusza",\n      "widgets": [\n        {\n          "label": "Domyślny"\n        }\n      ],\n      "entity": "element",\n      "field": {\n        "label": "Wybierz bibliotekę",\n        "fields": [\n          {\n            "label": "Biblioteka",\n            "description": "Wybierz bibliotekę"\n          },\n          {\n            "label": "Pole wymagane"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Opcje ekranu sukcesu",\n      "fields": [\n        {\n          "label": "Włącz ekran sukcesu"\n        },\n        {\n          "label": "Dodaj obraz ekranu sukcesu",\n          "fields": [\n            {\n              "label": "Zastąp ikonę sukcesu obrazem"\n            }\n          ]\n        },\n        {\n          "label": "Tekst do wyświetlenia przy przesłaniu",\n          "default": "Wypełniłeś/aś kwestionariusz."\n        }\n      ]\n    },\n    {\n      "label": "Elementy UI",\n      "fields": [\n        {\n          "label": "Etykiety przycisków",\n          "fields": [\n            {\n              "label": "Poprzednia etykieta przycisku",\n              "default": "Wróć"\n            },\n            {\n              "label": "Etykieta przycisku Kontynuuj",\n              "default": "Kontynuuj"\n            },\n            {\n              "label": "Etykieta przycisku Następny",\n              "default": "Następny"\n            },\n            {\n              "label": "Etykieta przycisku Prześlij",\n              "default": "Prześlij"\n            }\n          ]\n        },\n        {\n          "label": "Dostępność",\n          "fields": [\n            {\n              "label": "Wymagana etykieta przycisku wyjścia z wiadomości",\n              "default": "Zamknij komunikat o błędzie"\n            },\n            {\n              "label": "Tekst paska postępu",\n              "default": "Pytanie %current z %max",\n              "description": "Służy do informowania technologii wspomagających, jakie to pytanie. Zmienne: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Wymagana wiadomość",\n          "default": "To pytanie wymaga odpowiedzi",\n          "description": "Wyświetli się, jeśli to pole zostanie puste, a jest wymagane przez typ zawartości wrappera"\n        },\n        {\n          "label": "Tekst wymaganego symbolu",\n          "default": "wymagany",\n          "description": "Tekst, który będzie oznaczony gwiazdką, aby zasygnalizować, że pytanie jest wymagane"\n        },\n        {\n          "label": "Tytuł ekranu przesyłania",\n          "default": "Udało Ci się odpowiedzieć na wszystkie pytania"\n        },\n        {\n          "label": "Podtytuł ekranu przesyłania",\n          "default": "Kliknij poniżej, aby przesłać swoje odpowiedzi"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'pt', '{\n  "semantics": [\n    {\n      "label": "Elementos do questionário",\n      "widgets": [\n        {\n          "label": "Padrão"\n        }\n      ],\n      "entity": "elemento",\n      "field": {\n        "label": "Escolher biblioteca",\n        "fields": [\n          {\n            "label": "Biblioteca",\n            "description": "Escolha uma biblioteca"\n          },\n          {\n            "label": "Campo obrigatório"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Opções do ecrã de sucesso",\n      "fields": [\n        {\n          "label": "Ativar ecrã de sucesso"\n        },\n        {\n          "label": "Adicionar imagem do ecrã de sucesso",\n          "fields": [\n            {\n              "label": "Substituir ícone de sucesso por uma imagem"\n            }\n          ]\n        },\n        {\n          "label": "Texto a ser exibido na submissão",\n          "default": "Concluiu o questionário."\n        }\n      ]\n    },\n    {\n      "label": "Elementos de interface",\n      "fields": [\n        {\n          "label": "Etiquetas dos botões",\n          "fields": [\n            {\n              "label": "Etiqueta do botão Anterior",\n              "default": "Voltar"\n            },\n            {\n              "label": "Etiqueta do botão Continuar",\n              "default": "Continuar"\n            },\n            {\n              "label": "Etiqueta do botão Seguinte",\n              "default": "Seguinte"\n            },\n            {\n              "label": "Etiqueta do botão de submissão",\n              "default": "Submeter"\n            }\n          ]\n        },\n        {\n          "label": "Acessibilidade",\n          "fields": [\n            {\n              "label": "Etiqueta do botão de saída da mensagem obrigatória",\n              "default": "Fechar mensagem de erro"\n            },\n            {\n              "label": "Texto da barra de progresso",\n              "default": "Pergunta %current de %max",\n              "description": "Usada para informar as tecnologias de apoio em que pergunta se encontra. Variáveis: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Mensagem obrigatória",\n          "default": "É obrigatório responder a esta pergunta",\n          "description": "Será exibida se o campo de uma pergunta obrigatória não for preenchido"\n        },\n        {\n          "label": "Texto do símbolo de obrigatório",\n          "default": "obrigatório",\n          "description": "Texto que acompanhará o asterisco para informar que a pergunta é obrigatória"\n        },\n        {\n          "label": "Título para o ecrã de submissão",\n          "default": "Respondeu as todas as perguntas com sucesso"\n        },\n        {\n          "label": "Sub-título para o ecrã de submissão",\n          "default": "Clique abaixo para submeter as suas respostas"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'pt-br', '{\n  "semantics": [\n    {\n      "label": "Elementos do questionário",\n      "widgets": [\n        {\n          "label": "Padrão"\n        }\n      ],\n      "entity": "elemento",\n      "field": {\n        "label": "Escolher biblioteca",\n        "fields": [\n          {\n            "label": "Biblioteca",\n            "description": "Escolha uma biblioteca"\n          },\n          {\n            "label": "Campo obrigatório"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Opções da tela de sucesso",\n      "fields": [\n        {\n          "label": "Ativar tela de sucesso"\n        },\n        {\n          "label": "Adicionar imagem da tela de sucesso",\n          "fields": [\n            {\n              "label": "Substituir ícone de sucesso com uma imagem"\n            }\n          ]\n        },\n        {\n          "label": "Texto a ser exibido no envio",\n          "default": "Você completou o questionário."\n        }\n      ]\n    },\n    {\n      "label": "Elementos de interface de usuário",\n      "fields": [\n        {\n          "label": "Rótulos dos botões",\n          "fields": [\n            {\n              "label": "Rótulo do botão Anterior",\n              "default": "Voltar"\n            },\n            {\n              "label": "Rótulo do botão Continuar",\n              "default": "Continuar"\n            },\n            {\n              "label": "Rótulo do botão Próximo",\n              "default": "Próximo"\n            },\n            {\n              "label": "Rótulo do botão Enviar",\n              "default": "Enviar"\n            }\n          ]\n        },\n        {\n          "label": "Acessibilidade",\n          "fields": [\n            {\n              "label": "Rótulo de mensagem obrigatória do botão de saída",\n              "default": "Fechar mensagem de erro"\n            },\n            {\n              "label": "Texto da barra de progresso",\n              "default": "Questão %current de %max",\n              "description": "Usado para dizer às tecnologias de assistência qual é a questão. Variáveis: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Mensagem obrigatória",\n          "default": "Esta questão requer uma resposta",\n          "description": "Será mostrado caso o campo de uma pergunta obrigatória não esteja preenchido"\n        },\n        {\n          "label": "Texto do símbolo de obrigatório",\n          "default": "obrigatório",\n          "description": "Texto que acompanhará o asterisco ao informar que a questão é obrigatória"\n        },\n        {\n          "label": "Título para a tela de envio",\n          "default": "Você respondeu a todas as questões com sucesso"\n        },\n        {\n          "label": "Legenda para a tela de envio",\n          "default": "Clique abaixo para enviar suas respostas"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'ro', '{\n  "semantics": [\n    {\n      "label": "Questionnaire elements",\n      "widgets": [\n        {\n          "label": "Default"\n        }\n      ],\n      "entity": "element",\n      "field": {\n        "label": "Choose library",\n        "fields": [\n          {\n            "label": "Library",\n            "description": "Choose a library"\n          },\n          {\n            "label": "Required field"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Success screen options",\n      "fields": [\n        {\n          "label": "Enable success screen"\n        },\n        {\n          "label": "Add success screen image",\n          "fields": [\n            {\n              "label": "Replace success icon with image"\n            }\n          ]\n        },\n        {\n          "label": "Text to display on submit",\n          "default": "You have completed the questionnaire."\n        }\n      ]\n    },\n    {\n      "label": "UI Elements",\n      "fields": [\n        {\n          "label": "Button labels",\n          "fields": [\n            {\n              "label": "Previous button label",\n              "default": "Back"\n            },\n            {\n              "label": "Continue button label",\n              "default": "Continue"\n            },\n            {\n              "label": "Next button label",\n              "default": "Next"\n            },\n            {\n              "label": "Submit button label",\n              "default": "Submit"\n            }\n          ]\n        },\n        {\n          "label": "Accessibility",\n          "fields": [\n            {\n              "label": "Required message exit button label",\n              "default": "Close error message"\n            },\n            {\n              "label": "Progress bar text",\n              "default": "Question %current of %max",\n              "description": "Used to tell assistive technologies what question it is. Variables: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Required message",\n          "default": "This question requires an answer",\n          "description": "Will display if this field is unanswered and required by a wrapper content type"\n        },\n        {\n          "label": "Required symbol text",\n          "default": "required",\n          "description": "Text that will accompany an asterisk to signal that a question is required"\n        },\n        {\n          "label": "Title for the submit screen",\n          "default": "You successfully answered all of the questions"\n        },\n        {\n          "label": "Subtitle for the submit screen",\n          "default": "Click below to submit your answers"\n        }\n      ]\n    }\n  ]\n}'),
(31, 'ru', '{\n  "semantics": [\n    {\n      "label": "Элементы анкеты",\n      "widgets": [\n        {\n          "label": "По умолчанию"\n        }\n      ],\n      "entity": "элемент",\n      "field": {\n        "label": "Выбрать библиотеку",\n        "fields": [\n          {\n            "label": "Библиотека",\n            "description": "Выбрать библиотеку"\n          },\n          {\n            "label": "Обязательное поле"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Параметры экрана успеха",\n      "fields": [\n        {\n          "label": "Включить экран успеха"\n        },\n        {\n          "label": "Добавить изображение экрана успеха",\n          "fields": [\n            {\n              "label": "Заменить значок успеха на картинке"\n            }\n          ]\n        },\n        {\n          "label": "Текст для отображения при отправке",\n          "default": "Вы заполнили анкету."\n        }\n      ]\n    },\n    {\n      "label": "Элементы пользовательского интерфейса",\n      "fields": [\n        {\n          "label": "Метки кнопок",\n          "fields": [\n            {\n              "label": "Метка кнопки предыдущего шага",\n              "default": "Назад"\n            },\n            {\n              "label": "Метка кнопки продолжения",\n              "default": "Продолжить"\n            },\n            {\n              "label": "Метка кнопки следующего шага",\n              "default": "Дальше"\n            },\n            {\n              "label": "Метка кнопки отправки",\n              "default": "Отправить"\n            }\n          ]\n        },\n        {\n          "label": "Доступность",\n          "fields": [\n            {\n              "label": "Обязательно сообщение кнопки выхода",\n              "default": "Закройте сообщение об ошибке"\n            },\n            {\n              "label": "Текст индикатора прогресса",\n              "default": "Вопрос %current из %max",\n              "description": "Используется, чтобы сообщить вспомогательным технологиям, какой это вопрос. Переменные: [%current, %max]"\n            }\n          ]\n        },\n        {\n          "label": "Обязательное сообщение",\n          "default": "Этот вопрос требует ответа",\n          "description": "Отображается, если это поле не имеет ответа и требуется тип содержимого оболочки"\n        },\n        {\n          "label": "Текст символа \\"Обязательно\\"",\n          "default": "Обязательно",\n          "description": "Текст, сопровождающий звездочку, указывающую на необходимость вопроса"\n        },\n        {\n          "label": "Заголовок экрана отправки",\n          "default": "Вы успешно ответили на все вопросы"\n        },\n        {\n          "label": "Подзаголовок для экрана отправки",\n          "default": "Нажмите ниже, чтобы отправить свои ответы"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'sl', '{\n  "semantics": [\n    {\n      "label": "Elementi vprašalnika",\n      "widgets": [\n        {\n          "label": "Privzeto"\n        }\n      ],\n      "entity": "element",\n      "field": {\n        "label": "Element iz knjižnice",\n        "fields": [\n          {\n            "label": "Knjižnica vprašanj",\n            "description": "Možni tipi vprašanj"\n          },\n          {\n            "label": "Zahtevano polje"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Nastavitve zaslona ob zaključku vprašalnika",\n      "fields": [\n        {\n          "label": "Omogoči zaslon ob zaključku vprašalnika"\n        },\n        {\n          "label": "Dodaj sliko za zaključni zaslon",\n          "fields": [\n            {\n              "label": "Zamenjaj ikono o uspešnem zaključku s sliko po meri"\n            }\n          ]\n        },\n        {\n          "label": "Besedilo za prikaz ob zaključku vprašalnika",\n          "default": "Hvala za sodelovanje."\n        }\n      ]\n    },\n    {\n      "label": "Elementi uporabniškega vmesnika",\n      "fields": [\n        {\n          "label": "Besedila za gumbe",\n          "fields": [\n            {\n              "label": "Besedilo za gumb \\"Nazaj\\"",\n              "default": "Nazaj"\n            },\n            {\n              "label": "Besedilo za gumb \\"Nadaljuj\\"",\n              "default": "Nadaljuj"\n            },\n            {\n              "label": "Besedilo za gumb \\"Naprej\\"",\n              "default": "Naprej"\n            },\n            {\n              "label": "Besedilo za gumb \\"Oddaj\\"",\n              "default": "Oddaj"\n            }\n          ]\n        },\n        {\n          "label": "Bralnik zaslona",\n          "fields": [\n            {\n              "label": "Besedilo za izhod iz okna z opozorilom",\n              "default": "Zapri opozorilo"\n            },\n            {\n              "label": "Besedilo za indikator napredka",\n              "default": "Vprašanje %current od %max",\n              "description": "Bralnikom zaslonov sporoča trenutno stanje ogleda vprašalnika. %current in %max sta spremenljivki."\n            }\n          ]\n        },\n        {\n          "label": "Besedilo za zahtevan odgovor",\n          "default": "To vprašanje zahteva odgovor",\n          "description": "Sporočilo se pokaže ob neodgovorjenem odgovoru, ki zahteva odziv"\n        },\n        {\n          "label": "Besedilo za oznako zahtevanega odgovora",\n          "default": "zahtevano",\n          "description": "Besedilo se prikaže ob vprašanju in ga spremlja simbol *."\n        },\n        {\n          "label": "Naslov zaslona za potrditev odgovorov in oddajo vprašalnika",\n          "default": "Vprašalnik je uspešno izpolnjen!"\n        },\n        {\n          "label": "Podnaslov zaslona za potrditev odgovorov in oddajo vprašalnika",\n          "default": "S klikom na gumb bodo odgovori oddani"\n        }\n      ]\n    }\n  ]\n}\n'),
