INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(31, 'sw', '{\n  "semantics": [\n    {\n      "label": "Vipengele vya dodoso",\n      "widgets": [\n        {\n          "label": "Chaguo-msingi"\n        }\n      ],\n      "entity": "kipengele",\n      "field": {\n        "label": "Chagua maktaba",\n        "fields": [\n          {\n            "label": "Maktaba",\n            "description": "Chagua maktaba"\n          },\n          {\n            "label": "Sehemu inayohitajika"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Chaguzi za skrini ya mafanikio",\n      "fields": [\n        {\n          "label": "Washa skrini ya mafanikio"\n        },\n        {\n          "label": "Ongeza picha ya skrini ya mafanikio",\n          "fields": [\n            {\n              "label": "Badilisha aikoni ya mafanikio na picha"\n            }\n          ]\n        },\n        {\n          "label": "Maandishi ya kuonyesha unapowasilisha",\n          "default": "Umekamilisha hojaji."\n        }\n      ]\n    },\n    {\n      "label": "Vipengele vya kiolesura cha mtumiaji",\n      "fields": [\n        {\n          "label": "Lebo za vitufe",\n          "fields": [\n            {\n              "label": "Lebo ya kitufe kilichotangulia",\n              "default": "Nyuma"\n            },\n            {\n              "label": "Lebo ya kitufe cha endelea",\n              "default": "Endelea"\n            },\n            {\n              "label": "Lebo ya kitufe kinachofuata",\n              "default": "Inayofuata"\n            },\n            {\n              "label": "Lebo ya kitufe cha wasilisha",\n              "default": "Wasilisha"\n            }\n          ]\n        },\n        {\n          "label": "Ufikiaji",\n          "fields": [\n            {\n              "label": "Lebo ya kitufe cha kutoka kwenye ujumbe unaohitajika",\n              "default": "Funga ujumbe wa hitilafu"\n            },\n            {\n              "label": "Maandishi ya upau wa maendeleo",\n              "default": "Swali %currentkati ya%max",\n              "description": "Inatumika kuelezea teknolojia za usaidizi ni swali gani. Vigezo ni: [ %current,%max]"\n            }\n          ]\n        },\n        {\n          "label": "Ujumbe unaohitajika",\n          "default": "Swali hili linahitaji jibu",\n          "description": "Itaonyeshwa ikiwa sehemu hii haijajibiwa na inahitajika na aina ya maudhui ya kishikilia vipengele"\n        },\n        {\n          "label": "Maandishi ya ishara yanayohitajika",\n          "default": "inahitajika",\n          "description": "Maandishi ambayo yataambatana na nyota kuashiria kwamba swali linahitajika"\n        },\n        {\n          "label": "Mada ya skrini ya kuwasilisha",\n          "default": "Umejibu maswali yote kwa mafanikio"\n        },\n        {\n          "label": "Mada ya skrini ya kuwasilisha",\n          "default": "Bofya hapa chini kuwasilisha majibu yako"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'te', '{\n  "semantics": [\n    {\n      "label": "ప్రశ్నాపత్రం అంశాలు",\n      "widgets": [\n        {\n          "label": "డీఫాల్ట్"\n        }\n      ],\n      "entity": "ఎలిమెంట్",\n      "field": {\n        "label": "లైబ్రరీని ఎంచుకోండి",\n        "fields": [\n          {\n            "label": "లైబ్రరీ",\n            "description": "లైబ్రరీని ఎంచుకోండి"\n          },\n          {\n            "label": "ఈ ఫీల్డ్ తప్పనిసరి"\n          }\n        ]\n      }\n    },\n    {\n      "label": "సక్సెస్ స్క్రీన్ ఆప్షన్లు",\n      "fields": [\n        {\n          "label": "సక్సెస్ స్క్రీన్‌ని ఎనేబుల్ చేయండి"\n        },\n        {\n          "label": "సక్సెస్ స్క్రీన్ చిత్రాన్ని జోడించండి",\n          "fields": [\n            {\n              "label": "సక్సెస్ చిహ్నాన్ని చిత్రంతో భర్తీ చేయండి"\n            }\n          ]\n        },\n        {\n          "label": "సబ్ మిట్ చేసినపుడు ప్రదర్శించాల్సిన టెక్స్ట్",\n          "default": "మీరు ప్రశ్నాపత్రాన్ని పూర్తి చేసారు."\n        }\n      ]\n    },\n    {\n      "label": "UI ఎలిమెంట్స్",\n      "fields": [\n        {\n          "label": "బటన్ లేబుల్స్",\n          "fields": [\n            {\n              "label": "మునుపటి బటన్ లేబుల్",\n              "default": "వెనుకకు"\n            },\n            {\n              "label": "బటన్ లేబుల్ కొనసాగించు",\n              "default": "కొనసాగించు /కంటిన్యూ"\n            },\n            {\n              "label": "నెక్స్ట్ బటన్ లేబుల్",\n              "default": "తరువాత"\n            },\n            {\n              "label": "సబ్ మిట్ బటన్ లేబుల్",\n              "default": "సమర్పించు / సబ్ మిట్"\n            }\n          ]\n        },\n        {\n          "label": "యాక్సెసబిలిటీ",\n          "fields": [\n            {\n              "label": "ఎక్జిట్ బటన్ లేబుల్ కై అవసరమైన సందేశం",\n              "default": "ఎర్రర్ సందేశాన్ని క్లోజ్ చేయండి"\n            },\n            {\n              "label": "ప్రోగ్రెస్ బార్ టెక్స్ట్",\n              "default": "ప్రశ్న %current of %max",\n              "description": "ఇది ఏ ప్రశ్న అని అసిస్టివ్ టెక్నాలజీకి చెప్పడానికి ఉపయోగిస్తారు. వేరియబుల్స్: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "అవసరమైన/తప్పనిసరిగా ఇవ్వాల్సిన సందేశం",\n          "default": "ఈ ప్రశ్నకు సమాధానం కావాలి",\n          "description": "ఈ ఫీల్డ్‌కు సమాధానం ఇవ్వబడకపోయినా మరియు ర్యాపర్ కంటెంట్ రకం ద్వారా అవసరమైతే ప్రదర్శించబడుతుంది"\n        },\n        {\n          "label": "అవసరమైన చిహ్నం టెక్స్ట్",\n          "default": "తప్పనిసరి/ అవసరం",\n          "description": "ప్రశ్న అవసరమని సూచించడానికి నక్షత్రం గుర్తు కలిగి ఉంటుంది"\n        },\n        {\n          "label": "సబ్ మిట్ స్క్రీన్ కై శీర్షిక",\n          "default": "మీరు అన్ని ప్రశ్నలకు విజయవంతంగా సమాధానం ఇచ్చారు"\n        },\n        {\n          "label": "సబ్ మిట్ స్క్రీన్ కై సబ్ టైటిల్",\n          "default": "మీ సమాధానాలను సమర్పించడానికి దిగువ క్లిక్ చేయండి"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'th', '{\n  "semantics": [\n    {\n      "label": "ส่วนประกอบของแบบสอบถาม",\n      "widgets": [\n        {\n          "label": "ค่าเริ่มต้น"\n        }\n      ],\n      "entity": "element",\n      "field": {\n        "label": "เลือกห้องสมุด",\n        "fields": [\n          {\n            "label": "ห้องสมุด",\n            "description": "เลือกห้องสมุด"\n          },\n          {\n            "label": "ฟิลด์ที่ต้องการ"\n          }\n        ]\n      }\n    },\n    {\n      "label": "ตัวเลือกหน้าจอสำเร็จ",\n      "fields": [\n        {\n          "label": "เปิดใช้งานหน้าจอสำเร็จ"\n        },\n        {\n          "label": "เพิ่มรูปภาพหน้าจอสำเร็จ",\n          "fields": [\n            {\n              "label": "แทนที่ไอคอนสำเร็จด้วยรูปภาพ"\n            }\n          ]\n        },\n        {\n          "label": "ข้อความที่จะแสดงเมื่อส่ง",\n          "default": "คุณได้ทำแบบสอบถามเสร็จสิ้นแล้ว"\n        }\n      ]\n    },\n    {\n      "label": "องค์ประกอบของ UI",\n      "fields": [\n        {\n          "label": "ปุ่มแท็บ",\n          "fields": [\n            {\n              "label": "ปุ่มก่อนหน้า",\n              "default": "กลับ"\n            },\n            {\n              "label": "ปุ่มต่อไป",\n              "default": "ดำเนินการต่อ"\n            },\n            {\n              "label": "ปุ่มถัดไป",\n              "default": "ถัดไป"\n            },\n            {\n              "label": "ปุ่มส่ง",\n              "default": "ส่ง"\n            }\n          ]\n        },\n        {\n          "label": "การเข้าถึง",\n          "fields": [\n            {\n              "label": "ปุ่มออกข้อความที่ต้องการ",\n              "default": "ปิดข้อความผิดพลาด"\n            },\n            {\n              "label": "ข้อความแถบความคืบหน้า",\n              "default": "คำถาม %current จาก %max",\n              "description": "ใช้เพื่อบอกช่วยให้เทคโนโลยีช่วยเหลือรู้ว่าเป็นคำถามใด แปลงแปลง: [%current, %max]"\n            }\n          ]\n        },\n        {\n          "label": "ข้อความที่ต้องการ",\n          "default": "คำถามนี้ต้องการคำตอบ",\n          "description": "จะแสดงหากฟิลด์นี้ไม่ได้รับการตอบกลับและจำเป็นต้องใช้งานโดยประเภทเนื้อหาของ wrapper"\n        },\n        {\n          "label": "ข้อความสัญลักษณ์ที่ต้องการ",\n          "default": "ต้องการ",\n          "description": "ข้อความที่จะมากับเครื่องหมายดอกจันเพื่อแสดงให้เห็นว่าเป็นคำถามที่ต้องการ"\n        },\n        {\n          "label": "ชื่อหัวข้อสำหรับหน้าส่ง",\n          "default": "คุณตอบคำถามทั้งหมดเรียบร้อยแล้ว"\n        },\n        {\n          "label": "คำบรรยายย่อสำหรับหน้าส่ง",\n          "default": "คลิกด้านล่างเพื่อส่งคำตอบของคุณ"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'tr', '{\n  "semantics": [\n    {\n      "label": "Questionnaire elements",\n      "widgets": [\n        {\n          "label": "Default"\n        }\n      ],\n      "entity": "element",\n      "field": {\n        "label": "Choose library",\n        "fields": [\n          {\n            "label": "Library",\n            "description": "Choose a library"\n          },\n          {\n            "label": "Required field"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Success screen options",\n      "fields": [\n        {\n          "label": "Enable success screen"\n        },\n        {\n          "label": "Add success screen image",\n          "fields": [\n            {\n              "label": "Replace success icon with image"\n            }\n          ]\n        },\n        {\n          "label": "Text to display on submit",\n          "default": "You have completed the questionnaire."\n        }\n      ]\n    },\n    {\n      "label": "UI Elements",\n      "fields": [\n        {\n          "label": "Button labels",\n          "fields": [\n            {\n              "label": "Previous button label",\n              "default": "Back"\n            },\n            {\n              "label": "Continue button label",\n              "default": "Continue"\n            },\n            {\n              "label": "Next button label",\n              "default": "Next"\n            },\n            {\n              "label": "Submit button label",\n              "default": "Submit"\n            }\n          ]\n        },\n        {\n          "label": "Accessibility",\n          "fields": [\n            {\n              "label": "Required message exit button label",\n              "default": "Close error message"\n            },\n            {\n              "label": "Progress bar text",\n              "default": "Question %current of %max",\n              "description": "Used to tell assistive technologies what question it is. Variables: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Required message",\n          "default": "This question requires an answer",\n          "description": "Will display if this field is unanswered and required by a wrapper content type"\n        },\n        {\n          "label": "Required symbol text",\n          "default": "required",\n          "description": "Text that will accompany an asterisk to signal that a question is required"\n        },\n        {\n          "label": "Title for the submit screen",\n          "default": "You successfully answered all of the questions"\n        },\n        {\n          "label": "Subtitle for the submit screen",\n          "default": "Click below to submit your answers"\n        }\n      ]\n    }\n  ]\n}'),
(31, 'uk', '{\n  "semantics": [\n    {\n      "label": "Елементи анкети",\n      "widgets": [\n        {\n          "label": "За замовчуванням"\n        }\n      ],\n      "entity": "елемент",\n      "field": {\n        "label": "Вибрати бібліотеку",\n        "fields": [\n          {\n            "label": "Бібліотека",\n            "description": "Вибрати бібліотеку"\n          },\n          {\n            "label": "Обов''язкове поле"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Параметри екрану успіху",\n      "fields": [\n        {\n          "label": "Увімкнути екран успіху"\n        },\n        {\n          "label": "Додати зображення екрану успіху",\n          "fields": [\n            {\n              "label": "Замінити значок успіху на зображення"\n            }\n          ]\n        },\n        {\n          "label": "Текст для відображення під час надсилання",\n          "default": "Ви заповнили анкету."\n        }\n      ]\n    },\n    {\n      "label": "Елементи інтерфейсу користувача",\n      "fields": [\n        {\n          "label": "Мітки кнопок",\n          "fields": [\n            {\n              "label": "Мітка кнопки попереднього кроку",\n              "default": "Назад"\n            },\n            {\n              "label": "Мітка кнопки продовження",\n              "default": "Продовжити"\n            },\n            {\n              "label": "Мітка кнопки наступного кроку",\n              "default": "Далі"\n            },\n            {\n              "label": "Мітка кнопки розміщення",\n              "default": "Надіслати"\n            }\n          ]\n        },\n        {\n          "label": "Доступність",\n          "fields": [\n            {\n              "label": "Обов''язкове повідомлення кнопки виходу",\n              "default": "Закрийте повідомлення про помилку"\n            },\n            {\n              "label": "Текст індикатора прогресу",\n              "default": "Питання %current з %max",\n              "description": "Використовується, щоб повідомити допоміжним технологіям, яке це питання. Змінні: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Обов''язкове повідомлення",\n          "default": "Це запитання вимагає відповіді",\n          "description": "Відображатиметься, якщо це поле не має відповіді та вимагається типом вмісту оболонки"\n        },\n        {\n          "label": "Обов''язковий текст символу",\n          "default": "Обов''язково",\n          "description": "Текст, який супроводжуватиме зірочку, яка вказуватиме на необхідність запитання"\n        },\n        {\n          "label": "Заголовок екрана надсилання",\n          "default": "Ви успішно відповіли на всі запитання"\n        },\n        {\n          "label": "Підзаголовок для екрана надсилання",\n          "default": "Натисніть нижче, щоб надіслати свої відповіді"\n        }\n      ]\n    }\n  ]\n}\n'),
(31, 'vi', '{\n  "semantics": [\n    {\n      "label": "Questionnaire elements",\n      "widgets": [\n        {\n          "label": "Default"\n        }\n      ],\n      "entity": "element",\n      "field": {\n        "label": "Choose library",\n        "fields": [\n          {\n            "label": "Library",\n            "description": "Choose a library"\n          },\n          {\n            "label": "Required field"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Success screen options",\n      "fields": [\n        {\n          "label": "Enable success screen"\n        },\n        {\n          "label": "Add success screen image",\n          "fields": [\n            {\n              "label": "Replace success icon with image"\n            }\n          ]\n        },\n        {\n          "label": "Text to display on submit",\n          "default": "You have completed the questionnaire."\n        }\n      ]\n    },\n    {\n      "label": "UI Elements",\n      "fields": [\n        {\n          "label": "Button labels",\n          "fields": [\n            {\n              "label": "Previous button label",\n              "default": "Back"\n            },\n            {\n              "label": "Continue button label",\n              "default": "Continue"\n            },\n            {\n              "label": "Next button label",\n              "default": "Next"\n            },\n            {\n              "label": "Submit button label",\n              "default": "Submit"\n            }\n          ]\n        },\n        {\n          "label": "Accessibility",\n          "fields": [\n            {\n              "label": "Required message exit button label",\n              "default": "Close error message"\n            },\n            {\n              "label": "Progress bar text",\n              "default": "Question %current of %max",\n              "description": "Used to tell assistive technologies what question it is. Variables: [ %current, %max ]"\n            }\n          ]\n        },\n        {\n          "label": "Required message",\n          "default": "This question requires an answer",\n          "description": "Will display if this field is unanswered and required by a wrapper content type"\n        },\n        {\n          "label": "Required symbol text",\n          "default": "required",\n          "description": "Text that will accompany an asterisk to signal that a question is required"\n        },\n        {\n          "label": "Title for the submit screen",\n          "default": "You successfully answered all of the questions"\n        },\n        {\n          "label": "Subtitle for the submit screen",\n          "default": "Click below to submit your answers"\n        }\n      ]\n    }\n  ]\n}'),
(31, 'zh', '{\n  "semantics": [\n    {\n      "label": "調查表元件",\n      "widgets": [\n        {\n          "label": "預設"\n        }\n      ],\n      "entity": "元件",\n      "field": {\n        "label": "資源庫",\n        "fields": [\n          {\n            "label": "資源庫",\n            "description": "選擇一個資源庫"\n          },\n          {\n            "label": "必填項目"\n          }\n        ]\n      }\n    },\n    {\n      "label": "成功畫面設置",\n      "fields": [\n        {\n          "label": "啟用成功畫面"\n        },\n        {\n          "label": "添加成功畫面圖片",\n          "fields": [\n            {\n              "label": "用圖片來取代成功圖示"\n            }\n          ]\n        },\n        {\n          "label": "提交後訊息文字",\n          "default": "你已完成調查表！"\n        }\n      ]\n    },\n    {\n      "label": "介面相關設置",\n      "fields": [\n        {\n          "label": "按鈕顯示文字",\n          "fields": [\n            {\n              "label": "上一個按鈕的顯示文字",\n              "default": "上一個"\n            },\n            {\n              "label": "繼續按鈕的顯示文字",\n              "default": "繼續"\n            },\n            {\n              "label": "下一個按鈕的顯示文字",\n              "default": "下一個"\n            },\n            {\n              "label": "提交按鈕的顯示文字",\n              "default": "提交"\n            }\n          ]\n        },\n        {\n          "label": "無障礙設置",\n          "fields": [\n            {\n              "label": "報讀器上關閉錯誤訊息按鈕的文本",\n              "default": "關閉錯誤訊息"\n            },\n            {\n              "label": "報讀器上進度條的文本",\n              "default": "目前在第 %current 題，總共 %max 題",\n              "description": "用於報讀器的輔助文本，非顯示用。"\n            }\n          ]\n        },\n        {\n          "label": "必填項目的顯示訊息",\n          "default": "這個項目為必填，請務必作答。",\n          "description": "如果用戶沒有作答必填項目時會出現的訊息。"\n        },\n        {\n          "label": "必填訊息的符號提醒",\n          "default": "必填",\n          "description": "附有星號的項目，表示需要該項目一定要作答。"\n        },\n        {\n          "label": "提交畫面的標題文字",\n          "default": "您成功回答了所有問題"\n        },\n        {\n          "label": "提交畫面的副標題文字",\n          "default": "點擊下方的按鈕提交你的答案"\n        }\n      ]\n    }\n  ]\n}'),
