(33, 'sr', '{\n  "semantics": [\n    {\n      "label": "Листа питања",\n      "entity": "питање",\n      "widgets": [\n        {\n          "label": "Уобичајено"\n        },\n        {\n          "label": "Текстуални"\n        }\n      ],\n      "field": {\n        "label": "Питање &amp; алтернативе",\n        "fields": [\n          {\n            "label": "Питање"\n          },\n          {\n            "label": "Алтернативе - прва алтернатива је тачна.",\n            "entity": "одговор",\n            "field": {\n              "label": "Алтернативе"\n            }\n          }\n        ]\n      }\n    },\n    {\n      "label": "Укупне повратне информације",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Уобичајено"\n            }\n          ],\n          "label": "Дефинишите прилагођене повратне информације за било који опсег резултата",\n          "description": "Кликните на \\"Додај опсег\\" дугме за додавање онолико опсега колико вам је потребно. Пример: 0-20% Лош резултат, 21-91% Просечан резултат, 91-100% Одличан резултат!",\n          "entity": "опсег",\n          "field": {\n            "fields": [\n              {\n                "label": "Распон резултата"\n              },\n              {},\n              {\n                "label": "Повратне информације за дефинисани опсег резултата",\n                "placeholder": "Попуните повратне информације"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Поставке понашања",\n      "fields": [\n        {\n          "label": "Аутоматски настави",\n          "description": "Automatically go to next question when alternative is selected. This needs to be turned off to make the content fully accessible when using a screen reader."\n        },\n        {\n          "label": "Временско ограничење тачних одговора",\n          "description": "Вредност у милисекундама"\n        },\n        {\n          "label": "Временско ограничење за погрешне одговоре",\n          "description": "Вредност у милисекундама"\n        },\n        {\n          "label": "Омогућите звучне ефекте"\n        },\n        {\n          "label": "Омогући дугме за Повратак"\n        },\n        {\n          "label": "Омогући дугме Прикажи решења"\n        },\n        {\n          "label": "Проценат пролазности",\n          "description": "Проценат укупне оцене потребне за полагање квиза."\n        }\n      ]\n    },\n    {\n      "label": "Локализујте један избор",\n      "fields": [\n        {\n          "label": "Ознака за \\"Следеће\\" дугме",\n          "default": "Следеће питање"\n        },\n        {\n          "label": "Ознака за \\"Прикажи решења\\" дугме",\n          "default": "Прикажи решења"\n        },\n        {\n          "label": "Ознака за \\"Врати\\" дугме",\n          "default": "Покушај поново"\n        },\n        {\n          "label": "Наслов приказа решења",\n          "default": "Решења"\n        },\n        {\n          "label": "Текст из звучника за тачан одговор",\n          "default": "Тачно!"\n        },\n        {\n          "label": "Текст из звучника за погрешан одговор",\n          "default": "Погрешан!"\n        },\n        {\n          "label": "Option should have been selected",\n          "default": "Should have been selected"\n        },\n        {\n          "label": "Option should not have been selected",\n          "default": "Should not have been selected"\n        },\n        {\n          "label": "Ознака за \\"Искључи звук\\" дугме",\n          "default": "Искључи звук"\n        },\n        {\n          "label": "Ознака за \\"Затвори\\" дугме",\n          "default": "Затвори"\n        },\n        {\n          "label": "Текст броја слајда",\n          "description": "Објављује тренутни слајд и укупан број слајдова, променљиве су :num и :total",\n          "default": "Слајд :num од :total"\n        },\n        {\n          "label": "Текстуални приказ бодовне траке за оне који користе читач звука",\n          "default": "ОСвојили сте :num од :total поена"\n        },\n        {\n          "label": "Ознака за број питања на листи решења",\n          "description": "Објављује тренутни индекс питања на листи решења, променљиве су :num",\n          "default": "Питање :num"\n        },\n        {\n          "label": "Опис помоћне технологије за \\"Прикажи решења\\" дугме",\n          "default": "Покажите решење. Задатак ће бити означен својим тачним решењем."\n        },\n        {\n          "label": "Опис помоћне технологије за \\"Врати\\" дугме",\n          "default": "Покушајте поново са задатком. Ресетујте све одговоре и покрените задатак поново."\n        }\n      ]\n    }\n  ]\n}\n'),
(33, 'sv', '{\n  "semantics": [\n    {\n      "label": "Frågelista",\n      "entity": "fråga",\n      "widgets": [\n        {\n          "label": "Standard"\n        },\n        {\n          "label": "Textformat"\n        }\n      ],\n      "field": {\n        "label": "Fråga och svarsalternativ",\n        "fields": [\n          {\n            "label": "Fråga"\n          },\n          {\n            "label": "Svarsalternativ - första ska vara det rätta svaret.",\n            "entity": "svar",\n            "field": {\n              "label": "Svar"\n            }\n          }\n        ]\n      }\n    },\n    {\n      "label": "Övergripande feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Standard"\n            }\n          ],\n          "label": "Ge feedback utifrån poängresultat",\n          "description": "Klicka på \\"Nytt intervall\\"-knappen för att lägga till ett nytt poängintervall där du vill ge speciell feedback. Exempel: 0-20% Underkänt, 21-91% Godkänt, 91-100% Mycket väl godkänt.",\n          "entity": "intervall",\n          "field": {\n            "fields": [\n              {\n                "label": "Poängintervall"\n              },\n              {},\n              {\n                "label": "Feedback för detta intervall",\n                "placeholder": "Skriv in feedback här"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Beteende-inställningar",\n      "fields": [\n        {\n          "label": "Fortsätt automatiskt",\n          "description": "Automatically go to next question when alternative is selected. This needs to be turned off to make the content fully accessible when using a screen reader."\n        },\n        {\n          "label": "Paus efter rätt svar",\n          "description": "Värde i millisekunder. (1000 millisekunder = 1 sekund)."\n        },\n        {\n          "label": "Paus efter fel svar",\n          "description": "Värde i millisekunder. (1000 millisekunder = 1 sekund)."\n        },\n        {\n          "label": "Aktivera ljudeffekter"\n        },\n        {\n          "label": "Aktivera knappen \\"Försök igen\\""\n        },\n        {\n          "label": "Aktivera knappen \\"Visa lösning\\""\n        },\n        {\n          "label": "Krav för godkänt",\n          "description": "Procent av total poäng som krävs för att få godkänt på testet."\n        }\n      ]\n    },\n    {\n      "label": "Ändra texter",\n      "fields": [\n        {\n          "label": "Etikett för knappen \\"Nästa\\"",\n          "default": "Nästa fråga"\n        },\n        {\n          "label": "Etikett för knappen \\"Visa lösning\\"",\n          "default": "Visa lösning"\n        },\n        {\n          "label": "Etikett för knappen \\"Försök igen\\"",\n          "default": "Försök igen"\n        },\n        {\n          "label": "Titel för sidan Visa lösning",\n          "default": "Lösning"\n        },\n        {\n          "label": "Skärmläsartext för korrekt svar",\n          "default": "Rätt svar!"\n        },\n        {\n          "label": "Skärmläsartext för fel svar",\n          "default": "Fel"\n        },\n        {\n          "label": "Alternativ skulle ha valts",\n          "default": "Skulle ha valts"\n        },\n        {\n          "label": "Alternativ skulle inte ha valts",\n          "default": "Skulle inte ha valts"\n        },\n        {\n          "label": "Beskrivning av knappen \\"stäng av ljudet\\"",\n          "default": "Stäng av ljudet för feedback"\n        },\n        {\n          "label": "Beskrivning av knappen \\"Stäng\\"",\n          "default": "Stäng"\n        },\n        {\n          "label": "Sidnummer text",\n          "description": "Visar sidnummer för aktuell sida och totala antalet sidor. Variabler är :num och :total",\n          "default": "Sida :num av :total"\n        },\n        {\n          "label": "Texten som läses upp när poängen presenteras för användare med skärmläsare",\n          "default": "Du fick :num av :total poäng"\n        },\n        {\n          "label": "Etikett för frågans nummer i lösningslistan",\n          "description": "Visar aktuell index över fråga i lösningslistan, variabler är :num",\n          "default": "Fråga :num"\n        },\n        {\n          "label": "Beskrivning för tillgänglighetshjälpmedel för knappen \\"Visa lösning\\"",\n          "default": "Visa lösningen. Uppgiften kommer att markeras med dess rätta lösning."\n        },\n        {\n          "label": "Beskrivning för tillgänglighetshjälpmedel för knappen \\"Försök igen\\"",\n          "default": "Gör nytt försök på uppgiften. Nollställer alla svar och startar om uppgiften."\n        }\n      ]\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(33, 'sw', '{\n  "semantics": [\n    {\n      "label": "Orodha ya maswali",\n      "entity": "swali",\n      "widgets": [\n        {\n          "label": "Chaguo-msingi"\n        },\n        {\n          "label": "Kimaandishi"\n        }\n      ],\n      "field": {\n        "label": "Swali na majibu mbadala",\n        "fields": [\n          {\n            "label": "Swali"\n          },\n          {\n            "label": "Majibu mbadala - mbadala ya kwanza ndiyo sahihi.",\n            "entity": "jibu",\n            "field": {\n              "label": "Mbadala"\n            }\n          }\n        ]\n      }\n    },\n    {\n      "label": "Maoni ya Jumla",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Chaguo-msingi"\n            }\n          ],\n          "label": "Bainisha maoni maalum kwa masafa yoyote ya alama",\n          "description": "Bofya kitufe cha \\"Ongeza masafa\\" ili kuongeza masafa mengi unavyohitaji. Mfano: 0-20% Alama mbaya, 21-91% Alama ya Wastani, 91-100% Alama Nzuri!",\n          "entity": "masafa",\n          "field": {\n            "fields": [\n              {\n                "label": "Masafa ya Alama"\n              },\n              {},\n              {\n                "label": "Maoni kwa masafa ya alama yaliyofafanuliwa",\n                "placeholder": "Jaza maoni"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Mipangilio ya tabia",\n      "fields": [\n        {\n          "label": "Kuendelea kiotomatiki",\n          "description": "Automatically go to next question when alternative is selected. This needs to be turned off to make the content fully accessible when using a screen reader."\n        },\n        {\n          "label": "Muda umeisha wa kusubiri majibu sahihi",\n          "description": "Thamani katika milisekunde"\n        },\n        {\n          "label": "Muda umeisha wa kusubiri majibu yasiyo sahihi",\n          "description": "Thamani katika milisekunde"\n        },\n        {\n          "label": "Washa madhara ya sauti"\n        },\n        {\n          "label": "Washa kitufe cha jaribu tena"\n        },\n        {\n          "label": "Washa kitufe cha kuonyesha suluhisho"\n        },\n        {\n          "label": "Asilimia ya ufaulu",\n          "description": "Asilimia ya alama ya Jumla inayohitajika kwa kupita jaribio."\n        }\n      ]\n    },\n    {\n      "label": "Ujanabishe seti ya chaguo moja",\n      "fields": [\n        {\n          "label": "Lebo ya kitufe cha \\"Inayofuata\\"",\n          "default": "Swali linalofuata"\n        },\n        {\n          "label": "Lebo ya kitufe cha \\"Onyesha suluhisho\\"",\n          "default": "Onyesha suluhisho"\n        },\n        {\n          "label": "Lebo ya kitufe cha \\"Jaribu tena\\"",\n          "default": "Jaribu tena"\n        },\n        {\n          "label": "Mada ya mtazamo wa suluhisho la onyesho",\n          "default": "Orodha ya masuluhisho"\n        },\n        {\n          "label": "Maandishi ya kisoma maandishi kwa jibu sahihi",\n          "default": "Sahihi!"\n        },\n        {\n          "label": "Maandishi ya kisoma maandishi kwa jibu lisilo sahihi",\n          "default": "Siyo sahihi!"\n        },\n        {\n          "label": "Option should have been selected",\n          "default": "Should have been selected"\n        },\n        {\n          "label": "Option should not have been selected",\n          "default": "Should not have been selected"\n        },\n        {\n          "label": "Lebo ya kitufe cha \\"nyamazisha\\", ili kuzima sauti ya maoni",\n          "default": "Nyamazisha sauti ya maoni"\n        },\n        {\n          "label": "Lebo ya kitufe cha \\"Funga\\"",\n          "default": "Funga"\n        },\n        {\n          "label": "Maandishi ya nambari ya slaidi",\n          "description": "Inatangaza slaidi ya sasa na jumla ya idadi ya slaidi, vigezo ni :numna:total",\n          "default": "Slaidi :numkati ya :total"\n        },\n        {\n          "label": "Uwakilishi wa maandishi wa upau wa alama kwa wale wanaotumia kisoma maandishi",\n          "default": "Umepata :num kati ya alama :total"\n        },\n        {\n          "label": "Lebo ya nambari ya swali katika orodha ya masuluhisho",\n          "description": "Inatangaza faharasa ya sasa ya swali katika orodha ya masuluhisho:num vigezo ni",\n          "default": "Swali :num"\n        },\n        {\n          "label": "Maelezo ya teknolojia ya usaidizi kwa kitufe cha \\"Onyesha Suluhisho\\"",\n          "default": "Onyesha suluhisho hilo. Kazi hiyo itawekwa alama na suluhisho lake sahihi."\n        },\n        {\n          "label": "Maelezo ya teknolojia ya usaidizi kwa kitufe cha \\"Jaribu tena\\"",\n          "default": "Jaribu tena kazi hiyo. Weka upya majibu yote na uanze kazi tena."\n        }\n      ]\n    }\n  ]\n}\n'),
(33, 'th', '{\n  "semantics": [\n    {\n      "label": "รายการคำถาม",\n      "entity": "คำถาม",\n      "widgets": [\n        {\n          "label": "ค่าเริ่มต้น"\n        },\n        {\n          "label": "ข้อความ"\n        }\n      ],\n      "field": {\n        "label": "คำถามและตัวเลือก",\n        "fields": [\n          {\n            "label": "คำถาม"\n          },\n          {\n            "label": "ตัวเลือกทางเลือก - ตัวเลือกแรกเป็นคำตอบที่ถูกต้อง",\n            "entity": "คำตอบ",\n            "field": {\n              "label": "ตัวเลือก"\n            }\n          }\n        ]\n      }\n    },\n    {\n      "label": "คำติชมโดยรวม",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "ค่าเริ่มต้น"\n            }\n          ],\n          "label": "กำหนดคำติชมที่กำหนดเองสำหรับช่วงคะแนนใดๆ",\n          "description": "คลิกที่ปุ่ม \\"เพิ่มช่วง\\" เพื่อเพิ่มช่วงที่ต้องการ ตัวอย่าง: 0-20% คะแนนต่ำมาก, 21-91% คะแนนปานกลาง, 91-100% คะแนนดีมาก!",\n          "entity": "ช่วง",\n          "field": {\n            "fields": [\n              {\n                "label": "ช่วงคะแนน"\n              },\n              {},\n              {\n                "label": "คำติชมสำหรับช่วงคะแนนที่กำหนด",\n                "placeholder": "กรอกคำติชม"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "การตั้งค่าพฤติกรรม",\n      "fields": [\n        {\n          "label": "ทำต่อเนื่องอัตโนมัติ",\n          "description": "ไปยังคำถามถัดไปโดยอัตโนมัติเมื่อเลือกตัวเลือก"\n        },\n        {\n          "label": "เวลาหมดเวลาเมื่อตอบถูก",\n          "description": "ค่าเป็นมิลลิวินาที"\n        },\n        {\n          "label": "เวลาหมดเวลาเมื่อตอบผิด",\n          "description": "ค่าเป็นมิลลิวินาที"\n        },\n        {\n          "label": "เปิดใช้เอฟเฟกต์เสียง"\n        },\n        {\n          "label": "เปิดใช้ปุ่มลองใหม่"\n        },\n        {\n          "label": "เปิดใช้ปุ่มแสดงคำตอบ"\n        },\n        {\n          "label": "ร้อยละที่ผ่าน",\n          "description": "ร้อยละของคะแนนรวมที่ต้องการในการผ่านแบบทดสอบ"\n        }\n      ]\n    },\n    {\n      "label": "กำหนดภาษาในชุดเลือกเดียว",\n      "fields": [\n        {\n          "label": "ป้ายกำกับสำหรับปุ่ม \\"ถัดไป\\"",\n          "default": "คำถามถัดไป"\n        },\n        {\n          "label": "ป้ายกำกับสำหรับปุ่ม \\"แสดงคำตอบ\\"",\n          "default": "แสดงคำตอบ"\n        },\n        {\n          "label": "ป้ายกำกับสำหรับปุ่ม \\"ลองใหม่\\"",\n          "default": "ลองใหม่"\n        },\n        {\n          "label": "ชื่อเรื่องสำหรับหน้าต่างแสดงคำตอบ",\n          "default": "รายการคำตอบ"\n        },\n        {\n          "label": "ข้อความสำหรับการอ่านคำตอบที่ถูกต้อง",\n          "default": "ถูกต้อง!"\n        },\n        {\n          "label": "ข้อความสำหรับการอ่านคำตอบที่ไม่ถูกต้อง",\n          "default": "ไม่ถูกต้อง!"\n        },\n        {\n          "label": "ตัวเลือกควรจะต้องถูกเลือก",\n          "default": "ควรจะถูกเลือก"\n        },\n        {\n          "label": "ตัวเลือกไม่ควรจะถูกเลือก",\n          "default": "ไม่ควรจะถูกเลือก"\n        },\n        {\n          "label": "ป้ายกำกับสำหรับปุ่ม \\"ปิดเสียง\\", เพื่อปิดเสียงตอบรับ",\n          "default": "ปิดเสียงตอบรับ"\n        },\n        {\n          "label": "ป้ายกำกับสำหรับปุ่ม \\"ปิด\\"",\n          "default": "ปิด"\n        },\n        {\n          "label": "ข้อความหมายเลขสไลด์",\n          "description": "ประกาศสไลด์ปัจจุบันและจำนวนของสไลด์ทั้งหมด ตัวแปร :num และ :total",\n          "default": "สไลด์ :num จาก :total"\n        },\n        {\n          "label": "การแสดงคะแนนแทนด้วยข้อความสำหรับผู้ใช้ที่ใช้ readspeaker",\n          "default": "คุณได้รับ :num คะแนนจากทั้งหมด :total คะแนน"\n        },\n        {\n          "label": "ป้ายกำกับสำหรับหมายเลขคำถามในรายการคำตอบ",\n          "description": "ประกาศดัชนีคำถามปัจจุบันในรายการคำตอบ ตัวแปร :num",\n          "default": "คำถามที่ :num"\n        },\n        {\n          "label": "คำอธิบายเทคโนโลยีช่วยให้เข้าใจสำหรับปุ่ม \\"แสดงคำตอบ\\"",\n          "default": "แสดงคำตอบ เป็นการทำเครื่องหมายงานด้วยคำตอบที่ถูกต้อง"\n        },\n        {\n          "label": "คำอธิบายเทคโนโลยีช่วยให้เข้าใจสำหรับปุ่ม \\"ลองใหม่\\"",\n          "default": "ลองทำงานใหม่ เริ่มต้นการตอบสนองใหม่ทั้งหมด"\n        }\n      ]\n    }\n  ]\n}\n'),
(33, 'tr', '{\n  "semantics": [\n    {\n      "label": "Soru listesi",\n      "entity": "question",\n      "widgets": [\n        {\n          "label": "Varsayılan"\n        },\n        {\n          "label": "Metinsel"\n        }\n      ],\n      "field": {\n        "label": "Soru &amp; alternatifler",\n        "fields": [\n          {\n            "label": "soru"\n          },\n          {\n            "label": "Alternatifler - ilk alternatif doğru olanıdır.",\n            "entity": "answer",\n            "field": {\n              "label": "Alternatif"\n            }\n          }\n        ]\n      }\n    },\n    {\n      "label": "Toplam geribildirim",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Varsayılan"\n            }\n          ],\n          "label": "Herhangi bir puan aralığı için özel geri bildirim tanımlayın",\n          "description": "İstediğiniz kadar aralık eklemek için \\"Aralık ekle\\" düğmesini tıklayın. Örnek: %0-20 Kötü, %21-91 Ortalama, %91-100 İyi!",\n          "entity": "Aralık",\n          "field": {\n            "fields": [\n              {\n                "label": "Puan Aralığı"\n              },\n              {},\n              {\n                "label": "Tanımlanmış puan aralığı için geri bildirim",\n                "placeholder": "Geri bildirimi doldurun"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Etkinlik Ayarları",\n      "fields": [\n        {\n          "label": "Otomatik devam et",\n          "description": "Automatically go to next question when alternative is selected. This needs to be turned off to make the content fully accessible when using a screen reader."\n        },\n        {\n          "label": "Doğru cevaplarda zaman aşımı",\n          "description": "Milisaniye cinsinden değer"\n        },\n        {\n          "label": "Yanlış cevaplarda zaman aşımı",\n          "description": "Milisaniye cinsinden değer"\n        },\n        {\n          "label": "Ses efektlerini etkinleştir"\n        },\n        {\n          "label": "\\"Yeniden Dene\\" düğmesini etkinleştir"\n        },\n        {\n          "label": "\\"Çözümü Göster\\" düğmesini etkinleştir"\n        },\n        {\n          "label": "Geçiş Yüzdesi",\n          "description": "Quizi geçmek için gerekli toplam puan yüzdesi."\n        }\n      ]\n    },\n    {\n      "label": "Tek seçim soru setinin metinlerini düzenle",\n      "fields": [\n        {\n          "label": "\\"Sonraki\\" düğmesi için etiket",\n          "default": "Sonraki soru"\n        },\n        {\n          "label": "\\"Çözümü göster\\" düğmesi için etiket",\n          "default": "Çözümü göster"\n        },\n        {\n          "label": "\\"Yeniden dene\\" düğmesi için etiket",\n          "default": "Yeniden dene"\n        },\n        {\n          "label": "Çözüm görünümünü göster başlığı",\n          "default": "Çözüm"\n        },\n        {\n          "label": "Doğru cevap için okuyucu metni",\n          "default": "Doğru!"\n        },\n        {\n          "label": "Yanlış cevap için okuyucu metni",\n          "default": "Yanlış!"\n        },\n        {\n          "label": "Option should have been selected",\n          "default": "Should have been selected"\n        },\n        {\n          "label": "Option should not have been selected",\n          "default": "Should not have been selected"\n        },\n        {\n          "label": "Geri bildirim sesini devre dışı bırakmak için \\"sessiz\\" düğmesinin etiketi",\n          "default": "Geri bildirim sesini kapat"\n        },\n        {\n          "label": "\\"Kapat\\" düğmesi için etiket",\n          "default": "Kapat"\n        },\n        {\n          "label": "Slayt numarası metni",\n          "description": "Geçerli slaytı ve toplam slayt sayısını duyurur. :num ve :total yerine ilgili sayılar gelir.",\n          "default": "Slayt: :num / :total"\n        },\n        {\n          "label": "Bir okuyucu kullananlar için puan çubuğunun metinsel gösterimi",\n          "default": ":total puandan :num puan aldınız"\n        },\n        {\n          "label": "Çözüm listesindeki soru numarasının etiketi",\n          "description": "Çözüm listesindeki mevcut soru sırasını duyurur. :num yerine sorunun sırası gelecektir.",\n          "default": "Soru :num"\n        },\n        {\n          "label": "\\"Çözüm Göster\\" düğmesi için yardımcı teknoloji açıklaması",\n          "default": "Çözümü göster. Görev, doğru çözümü ile işaretlenecektir."\n        },\n        {\n          "label": "\\"Yeniden Dene\\" düğmesi için yardımcı teknoloji açıklaması",\n          "default": "Görevi yeniden deneyin. Tüm yanıtları sıfırlayın ve görevi yeniden başlatın."\n        }\n      ]\n    }\n  ]\n}\n'),
(33, 'uk', '{\n  "semantics": [\n    {\n      "label": "Список запитань",\n      "entity": "запитання",\n      "widgets": [\n        {\n          "label": "По умовчанню"\n        },\n        {\n          "label": "Текстовий"\n        }\n      ],\n      "field": {\n        "label": "Запитання і варіанти відповідей",\n        "fields": [\n          {\n            "label": "Запитання"\n          },\n          {\n            "label": "Варіанти відповідей - перший варіант правильний.",\n            "entity": "відповідь",\n            "field": {\n              "label": "Варіант відповіді"\n            }\n          }\n        ]\n      }\n    },\n    {\n      "label": "Загальний відгук",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "По умовчанню"\n            }\n          ],\n          "label": "Визначення відгуків користувача для будь-якого діапазона оцінок",\n          "description": "Натисніть на кнопку \\"Добавити діапазон\\" щоб добавити стільки діапазонів, скільки вам потрібно. Наприклад: 0-20% Погана оцінка, 21-91% Середня оцінка, 91-100% Відмінна оцінка!",\n          "entity": "діапазон",\n          "field": {\n            "fields": [\n              {\n                "label": "Діапазон оцінки"\n              },\n              {},\n              {\n                "label": "Зворотній зв''язок для певного діапазону оцінок",\n                "placeholder": "Заповніть відгук"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Настройки поведінки",\n      "fields": [\n        {\n          "label": "Автопродовження",\n          "description": "Automatically go to next question when alternative is selected. This needs to be turned off to make the content fully accessible when using a screen reader."\n        },\n        {\n          "label": "Тайм-аут на правильні відповіді",\n          "description": "Значення в мілісекундах"\n        },\n        {\n          "label": "Тайм-аут на неправильні відповіді",\n          "description": "Значення в мілісекундах"\n        },\n        {\n          "label": "Включити звукові ефекти"\n        },\n        {\n          "label": "Включити кнопку повтора"\n        },\n        {\n          "label": "Включити кнопку показу відповідей"\n        },\n        {\n          "label": "Прохідний відсоток",\n          "description": "Відсоток від загальної кількості балів, необхідних для проходження теста."\n        }\n      ]\n    },\n    {\n      "label": "Локалізація одиночного вибору",\n      "fields": [\n        {\n          "label": "Надпис для кнопки \\"Наступне\\"",\n          "default": "Наступне запитання"\n        },\n        {\n          "label": "Надпис для кнопки \\"Показати відповіді\\"",\n          "default": "Показати відповіді"\n        },\n        {\n          "label": "Надпис для кнопки \\"Повторити\\"",\n          "default": "Повторити"\n        },\n        {\n          "label": "Назва для показу відповідей",\n          "default": "Список відповідей"\n        },\n        {\n          "label": "Текст озвучки для правильної відповіді",\n          "default": "Правильно!"\n        },\n        {\n          "label": "Текст озвучки для неправильної відповіді",\n          "default": "Неправильно!"\n        },\n        {\n          "label": "Option should have been selected",\n          "default": "Should have been selected"\n        },\n        {\n          "label": "Option should not have been selected",\n          "default": "Should not have been selected"\n        },\n        {\n          "label": "Надпис для кнопки \\"відключити звук\\", щоб відключити звук зворотнього зв''язку",\n          "default": "Відключити звук зворотнього зв''язку"\n        },\n        {\n          "label": "Надпис для кнопки \\"Закрити\\"",\n          "default": "Закрити"\n        },\n        {\n          "label": "Текст номера слайда",\n          "description": "Оголошує поточний слайд і загальну кулькість слайдів, змінні :num і :total",\n          "default": "Слайд :num із :total"\n        },\n        {\n          "label": "Текстове представлення шкали оцінок для тих, хто використовує озвучку тексту",\n          "default": "Ви отримали :num out із :total балів"\n        },\n        {\n          "label": "Позначка для номера питання в списку рішень",\n          "description": "Оголошує індекс поточного запитання в списку рішень, змінними є :num",\n          "default": "Question :num"\n        },\n        {\n          "label": "Опис допоміжної технології для кнопки «Показати рішення».",\n          "default": "Показати рішення. Завдання буде позначено як правильне рішення."\n        },\n        {\n          "label": "Опис допоміжної технології для кнопки «Повторити».",\n          "default": "Повторіть завдання. Скиньте всі відповіді та почніть завдання знову."\n        }\n      ]\n    }\n  ]\n}\n'),
(33, 'zh-cn', '{\n  "semantics": [\n    {\n      "label": "问题列表",\n      "entity": "问题",\n      "widgets": [\n        {\n          "label": "默认"\n        },\n        {\n          "label": "文本"\n        }\n      ],\n      "field": {\n        "label": "问题和选项",\n        "fields": [\n          {\n            "label": "问题"\n          },\n          {\n            "label": "选项 - 第一个为正确选项。",\n            "entity": "答案",\n            "field": {\n              "label": "选项"\n            }\n          }\n        ]\n      }\n    },\n    {\n      "label": "总体反馈",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "默认"\n            }\n          ],\n          "label": "给出任何分数范围的自定义反馈",\n          "description": "点击 \\"添加分数范围\\" 按钮，添加任意分数范围。例如，0-20% 加油啊, 21-91% 继续努力, 91-100% 你真棒!",\n          "entity": "范围",\n          "field": {\n            "fields": [\n              {\n                "label": "分数范围"\n              },\n              {},\n              {\n                "label": "特定分数范围的反馈",\n                "placeholder": "填写反馈"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "行为设置",\n      "fields": [\n        {\n          "label": "自动继续",\n          "description": "Automatically go to next question when alternative is selected. This needs to be turned off to make the content fully accessible when using a screen reader."\n        },\n        {\n          "label": "正确答案超时",\n          "description": "以毫秒为单位的值"\n        },\n        {\n          "label": "错误答案超时",\n          "description": "以毫秒为单位的值"\n        },\n        {\n          "label": "启用音效"\n        },\n        {\n          "label": "启用重试按钮"\n        },\n        {\n          "label": "启用显示答案按钮"\n        },\n        {\n          "label": "及格分数",\n          "description": "考试及格分数。"\n        }\n      ]\n    },\n    {\n      "label": "本地化单选题集",\n      "fields": [\n        {\n          "label": "\\"下一个\\"按钮的标签",\n          "default": "下一题"\n        },\n        {\n          "label": "\\"显示答案\\"按钮的标签",\n          "default": "显示答案"\n        },\n        {\n          "label": "\\"重做\\"按钮的标签",\n          "default": "重做"\n        },\n        {\n          "label": "显示答案视图的标题",\n          "default": "答案列表"\n        },\n        {\n          "label": "答对时的显示文本",\n          "default": "正确！"\n        },\n        {\n          "label": "答错时的显示文本",\n          "default": "错误！"\n        },\n        {\n          "label": "Option should have been selected",\n          "default": "Should have been selected"\n        },\n        {\n          "label": "Option should not have been selected",\n          "default": "Should not have been selected"\n        },\n        {\n          "label": "\\"静音\\"按钮的标签，以关闭反馈声音",\n          "default": "关闭反馈声音"\n        },\n        {\n          "label": "\\"关闭\\"按钮的标签",\n          "default": "关闭"\n        },\n        {\n          "label": "幻灯片编号文字",\n          "description": "显示当前幻灯片编号和幻灯片总数，变量为 :num和 :total",\n          "default": "幻灯片 :num of :total"\n        },\n        {\n          "label": "得分情况的文本描述",\n          "default": "总分 :total 分，您的得分为:num 分。"\n        },\n        {\n          "label": "Label for the question number in the solution list",\n          "description": "Announces current question index in solution list, variables are :num",\n          "default": "Question :num"\n        },\n        {\n          "label": "Assistive technology description for \\"Show Solution\\" button",\n          "default": "Show the solution. The task will be marked with its correct solution."\n        },\n        {\n          "label": "Assistive technology description for \\"Retry\\" button",\n          "default": "Retry the task. Reset all responses and start the task over again."\n        }\n      ]\n    }\n  ]\n}\n'),
(34, 'af', '{\n  "semantics": [\n    {\n      "label": "Inleidende teks",\n      "default": "Kies die regte stelling.",\n      "description": "Dit sal bo-aan die opsomming taak vertoon word."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Verstek"\n        },\n        {\n          "label": "Tekstuele"\n        }\n      ],\n      "label": "Opsomming",\n      "entity": "stellings",\n      "field": {\n        "label": "Stel stellings",\n        "fields": [\n          {\n            "label": "Lys van stellings vir die opsomming - die eerste stelling is reg.",\n            "entity": "stelling",\n            "field": {\n              "label": "Stelling"\n            }\n          },\n          {\n            "label": "Wenk",\n            "fields": [\n              {\n                "label": "Wenk teks"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Algemene terugvoer",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Verstek"\n            }\n          ],\n          "label": "Bepaal verstekterugvoer vir enige reeks tellings",\n          "description": "Kliek op die \\"Voeg reeks by\\" knoppie om so veel as moontlik reekse by te voeg. Byvoorbeeld: 0-20% Swak Punt, 21-91% Gemiddelde Punt, 91-100% Uitstekende Punt!",\n          "entity": "reeks",\n          "field": {\n            "fields": [\n              {\n                "label": "Telling reeks"\n              },\n              {},\n              {\n                "label": "Terugvoer vir gedefinieerde telling reeks",\n                "placeholder": "Vul die terugvoer in"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Teks wat vertoon word bo die aantal stellings wat reg beantwoord is in die opsomming taak.",\n      "default": "Vordering:",\n      "description": "Sal bo-aan die stellings vertoon word: Byvoorbeeld: ''Vordering: 2/5''"\n    },\n    {\n      "label": "Teks wat vertoon word bo-aan die aantal stellings wat verkeerd beantwoord is in die opsomming taak.",\n      "default": "Verkeerde antwoorde:",\n      "description": "Sal bo die stellings vertoon word. Byvoorbeeld: ''Verkeerde antwoord:4''"\n    },\n    {\n      "label": "Opsomming terugvoer opskrif",\n      "default": "Jou uitslag",\n      "description": "Dit sal bo-aan die opsomming taak vertoon word."\n    },\n    {\n      "label": "Spreekleserteks vir regte antwoord",\n      "default": "Reg."\n    },\n    {\n      "label": "Spreekleserteks vir aankondiging van verkeerde antwoord",\n      "default": "Verkeerd! Probeer asb. weer."\n    },\n    {\n      "label": "Spreekleserteks etiket vir verkeerde antwoord",\n      "default": "Verkeerd"\n    },\n    {\n      "label": "Etiketlys van verkeerde antwoorde",\n      "default": "Regte antwoorde."\n    },\n    {\n      "label": "Etiket vir die wys wenk knoppie",\n      "default": "Wys wenk"\n    },\n    {\n      "label": "Tekstuele tentoonstelling van die telkaart vir diegene wat ''n spreekleser gebruik",\n      "description": ":num en :total is spesiale sleutelwoorde wat programmaties opgedateer word",\n      "default": "Jy het :num uit :total punte gekry"\n    },\n    {\n      "label": "Teks gebruik vir spreekleser kommunikasie vordering",\n      "description": ":num en :total is spesiale sleutelwoorde wat programmaties opgedateer word",\n      "default": "Vordering :num van :total"\n    }\n  ]\n}\n'),
(34, 'ar', '{\n  "semantics": [\n    {\n      "label": "مقدمة النص",\n      "default": "Choose the correct statement.",\n      "description": "سيتم عرضها فوق المهمة الموجزة"\n    },\n    {\n      "widgets": [\n        {\n          "label": "افتراضي"\n        },\n        {\n          "label": "النصية"\n        }\n      ],\n      "label": "الملخص",\n      "entity": "البيانات",\n      "field": {\n        "label": "البيانات",\n        "fields": [\n          {\n            "label": "قائمة بيانات للملخص. البيان الأول هو الصحيح",\n            "entity": "بيان",\n            "field": {\n              "label": "بيان"\n            }\n          },\n          {\n            "label": "تلميح",\n            "fields": [\n              {\n                "label": "نص التلميح"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "شفافية خلفية العناصر",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "افتراضي"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "النص المعروض قبل عدد من البيانات حلها في المهمة الموجزة",\n      "default": "Progress:",\n      "description": "سيتم عرضها فوق البيانات. على سبيل المثال: \\"التقدم من: ٢/٥\\""\n    },\n    {\n      "label": "النص المعروض قبل عدد من البيانات خاطئة المحدد في المهمة الموجزة",\n      "default": "Wrong answers:",\n      "description": "سيتم عرض فوق البيانات. مثال: \\"الإجابات خاطئة: ٤\\""\n    },\n    {\n      "label": "راس ملاحظات الملخص",\n      "default": "Your result",\n      "description": "سيتم عرضه فوق ملاحظات الملخص"\n    },\n    {\n      "label": "النص Readspeaker عن الإجابة الصحيحة",\n      "default": "Correct."\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "Label list of correct answers",\n      "default": "Correct answers."\n    },\n    {\n      "label": "Label for the show tip button",\n      "default": "Show tip"\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Text used for readspeakers to communicate progress",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "Progress :num of :total"\n    }\n  ]\n}'),
(34, 'bg', '{\r\n  "semantics": [\r\n    {\r\n      "label": "Уводен текст",\r\n      "default": "Задайте правилното твърдение.",\r\n      "description": "Ще се показва над задачата за резюме."\r\n    },\r\n    {\r\n      "widgets": [\r\n        {\r\n          "label": "По подразбиране"\r\n        },\r\n        {\r\n          "label": "Текстов"\r\n        }\r\n      ],\r\n      "label": "Резюме",\r\n      "entity": "твърдения",\r\n      "field": {\r\n        "label": "Списък от твърдения",\r\n        "fields": [\r\n          {\r\n            "label": "Списък на твърдения за резюме - първото твърдение е вярното.",\r\n            "entity": "твърдение",\r\n            "field": {\r\n              "label": "Твърдение"\r\n            }\r\n          },\r\n          {\r\n            "label": "Подсказка",\r\n            "fields": [\r\n              {\r\n                "label": "Текст на подсказката"\r\n              }\r\n            ]\r\n          }\r\n        ]\r\n      }\r\n    },\r\n    {\r\n      "label": "Обща обратна връзка",\r\n      "fields": [\r\n        {\r\n          "widgets": [\r\n            {\r\n              "label": "По подразбиране"\r\n            }\r\n          ],\r\n          "label": "Персонална обратна връзка за всеки диапазон от точки",\r\n          "description": "Натиснете бутон \\"Добави диапазон\\", за да добавите необходимите полета за диапазони. Пример: 0-20% Слаб резултат, 21-91% Среден резултат, 91-100% Отличен резултат!",\r\n          "entity": "диапазон",\r\n          "field": {\r\n            "fields": [\r\n              {\r\n                "label": "Диапазон на резултата"\r\n              },\r\n              {},\r\n              {\r\n                "label": "Обратна връзка за дефиниран диапазон на резултата",\r\n                "placeholder": "Въведете обратна връзка"\r\n              }\r\n            ]\r\n          }\r\n        }\r\n      ]\r\n    },\r\n    {\r\n      "label": "Текстът ще се показва преди броя използвани твърдения.",\r\n      "default": "Напредък:",\r\n      "description": "Ще се показва под твърденията. Пример: ''Напредък: 2/5''"\r\n    },\r\n    {\r\n      "label": "Текстът ще се показва преди броя посочени грешни твърдения в задачата.",\r\n      "default": "Грешни отговори:",\r\n      "description": "Ще се показва над твърденията. Пример: ''Грешни отговори: 4''"\r\n    },\r\n    {\r\n      "label": "Заглавие",\r\n      "default": "Вашият резултат",\r\n      "description": "Ще се показва над обратната връзка."\r\n    },\r\n    {\r\n      "label": "Readspeaker текст за верен отговор",\r\n      "default": "Вярно."\r\n    },\r\n    {\r\n      "label": "Readspeaker текст за грешен отговор",\r\n      "default": "Грешно! Опитай пак."\r\n    },\r\n    {\r\n      "label": "Readspeaker етикет за грешен отговор",\r\n      "default": "Грешно"\r\n    },\r\n    {\r\n      "label": "Етикет за списък с верни отговори",\r\n      "default": "Верни отговори."\r\n    },\r\n    {\r\n      "label": "Етикет за бутон Покажи подсказка",\r\n      "default": "Покажи подсказка"\r\n    },\r\n    {\r\n      "label": "Текстово представяне на лентата с резултати за тези, които използват readspeaker",\r\n      "description": ":num и :total са специални думи, които се обновяват програмно",\r\n      "default": "Вие имате :num от общо :total точки"\r\n    },\r\n    {\r\n      "label": "Текст за напредъка за тези, които използват readspeaker",\r\n      "description": ":num и :total са специални думи, които се обновяват програмно",\r\n      "default": "Напредък :num от :total"\r\n    }\r\n  ]\r\n}\r\n'),
(34, 'bs', '{\n  "semantics": [\n    {\n      "label": "Introduction text",\n      "default": "Choose the correct statement.",\n      "description": "Will be displayed above the summary task."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Default"\n        },\n        {\n          "label": "Textual"\n        }\n      ],\n      "label": "Summary",\n      "entity": "statements",\n      "field": {\n        "label": "Set of statements",\n        "fields": [\n          {\n            "label": "List of statements for the summary - the first statement is correct.",\n            "entity": "statement",\n            "field": {\n              "label": "Statement"\n            }\n          },\n          {\n            "label": "Tip",\n            "fields": [\n              {\n                "label": "Tip text"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Default"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text displayed before number of statements solved in the summary task.",\n      "default": "Progress:",\n      "description": "Will be displayed above the statements. Example: ''Progress: 2/5''"\n    },\n    {\n      "label": "Tekst koji se prikazuje ispred pogrešnih tvrdnji označenih u Rezime zadatku.",\n      "default": "pogrešni odgovori:",\n      "description": "Biće prikazano iznad tvrdnji. Primjer: ''Pogrešni odgovori: 4''"\n    },\n    {\n      "label": "Zaglavlje feedbacka za Rezime",\n      "default": "Vaš rezultat",\n      "description": "Biće prikazano iznad feedbacka za Rezime."\n    },\n    {\n      "label": "Čitanje teksta za tačan odgovor",\n      "default": "Tačno."\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "Lista tačnih odgovora",\n      "default": "Tačni odgovori."\n    },\n    {\n      "label": "Tekst za dugme Prikazati tip.",\n      "default": "Prikazati tip"\n    },\n    {\n      "label": "Tekstualni prikaz rezultata za one koji koriste čitanje.",\n      "description": ":num i :total su specijalne riječi koje se programski automatiziraju.",\n      "default": "Osvojili ste :num od of :total bodova"\n    },\n    {\n      "label": "Tekst koji se koristi u naredovanju pretvaranja teksta u govor",\n      "description": ":num i :total su specijalne riječi koje se programski ažuriraju",\n      "default": "Napredovanje :num od :total"\n    }\n  ]\n}'),
(34, 'ca', '{\n  "semantics": [\n    {\n      "label": "Text d’introducció",\n      "default": "Selecciona la frase correcta.",\n      "description": "Es mostrarà sobre el resum de la tasca."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Opció predeterminada"\n        },\n        {\n          "label": "Textual"\n        }\n      ],\n      "label": "Resum",\n      "entity": "enunciats",\n      "field": {\n        "label": "Conjunt d’enunciats",\n        "fields": [\n          {\n            "label": "Llista d’afirmacions per al resum; la primera és la correcta.",\n            "entity": "frase",\n            "field": {\n              "label": "Frase"\n            }\n          },\n          {\n            "label": "Pista",\n            "fields": [\n              {\n                "label": "Text de la pista"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Suggeriment general",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Opció predeterminada"\n            }\n          ],\n          "label": "Defineix una valoració per cada rang de puntuació",\n          "description": "Feu clic al botó \\"Afegeix un rang\\" per afegir tants rangs com necessiteu. Exemple: 0-20 % per a puntuació baixa, 21-91 % per a puntuació mitjana, 91-100 % per a puntuació excel·lent",\n          "entity": "rang",\n          "field": {\n            "fields": [\n              {\n                "label": "Rang de puntuació"\n              },\n              {},\n              {\n                "label": "Retroacció per al rang de puntuació definit",\n                "placeholder": "Introduïu el suggeriment"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text que es mostra abans del nombre d’afirmacions resoltes a la tasca de resum.",\n      "default": "Progrés:",\n      "description": "Es mostrarà a sobre de les afirmacions. Exemple: \\"Progrés: 2/5\\""\n    },\n    {\n      "label": "Text que es mostra abans del nombre d’afirmacions incorrectes solucionades a la tasca de resum.",\n      "default": "Respostes incorrectes:",\n      "description": "Es mostrarà a sobre de les afirmacions. Exemple: \\"Respostes incorrectes: 4\\""\n    },\n    {\n      "label": "Títol del resum de suggeriments",\n      "default": "El seu resultat",\n      "description": "Es mostrarà a sobre dels suggeriments de resum."\n    },\n    {\n      "label": "Text de l’altaveu de lectura per a una resposta correcta",\n      "default": "Correcte."\n    },\n    {\n      "label": "Text de l’altaveu de lectura per anunciar una resposta incorrecta",\n      "default": "Incorrecte. Torna-ho a provar."\n    },\n    {\n      "label": "Etiqueta de l’altaveu de lectura per a resposta incorrecta",\n      "default": "Incorrecte"\n    },\n    {\n      "label": "Llista d’etiquetes de respostes correctes",\n      "default": "Respostes correctes."\n    },\n    {\n      "label": "Etiqueta del botó \\"Mostra la pista\\"",\n      "default": "Mostra la pista"\n    },\n    {\n      "label": "Representació textual de la barra de puntuació pera als que utilitzen un altaveu de lectura",\n      "description": ":num i :total són paraules clau especials que s’actualitzen automàticament",\n      "default": "Heu fet :num de :total punts"\n    },\n    {\n      "label": "Text que s’utilitza per comunicar el progrés amb altaveus de lectura",\n      "description": ":num i :total són paraules clau especials que s’actualitzen automàticament",\n      "default": "Progrés :num of :total"\n    }\n  ]\n}\n'),
(34, 'cs', '{\n  "semantics": [\n    {\n      "label": "Úvodní text",\n      "default": "Vyberte správné tvrzení.",\n      "description": "Zobrazí se nad souhrnem úlohy."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Výchozí"\n        },\n        {\n          "label": "Textové"\n        }\n      ],\n      "label": "Souhrn",\n      "entity": "tvrzení",\n      "field": {\n        "label": "Sada tvrzení",\n        "fields": [\n          {\n            "label": "Seznam tvrzení pro shrnutí - první tvrzení je správné.",\n            "entity": "tvrzení",\n            "field": {\n              "label": "Tvrzení"\n            }\n          },\n          {\n            "label": "Nápověda",\n            "fields": [\n              {\n                "label": "Text nápovědy"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Celková zpětná vazba",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Výchozí"\n            }\n          ],\n          "label": "Definujte vlastní zpětnou vazbu pro jakýkoli rozsah skóre",\n          "description": "Klikněte na tlačítko \\"Přidat rozsah\\" pro přidání tolika rozsahů, kolik potřebujete. Například: 0-20% špatný výsledek, 21-91% průměrný výsledek, 91-100% výborný výsledek!",\n          "entity": "rozsah",\n          "field": {\n            "fields": [\n              {\n                "label": "Rozsah skóre"\n              },\n              {},\n              {\n                "label": "Zpětná vazba pro definovaný rozsah skóre",\n                "placeholder": "Vyplňte ve zpětné vazbě"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text zobrazený před počtem příkazů vyřešených v souhrnu úlohy.",\n      "default": "Pokrok:",\n      "description": "Zobrazí se nad výpisy. Příklad: \\"Pokrok: 2/5\\""\n    },\n    {\n      "label": "Text zobrazený před počtem nesprávných příkazů vybraných v souhrnu úlohy.",\n      "default": "Špatné odpovědi:",\n      "description": "Zobrazí se nad výpisy. Příklad: \\"Špatné odpovědi: 4\\""\n    },\n    {\n      "label": "Záhlaví souhrnu zpětné vazby",\n      "default": "Váš výsledek",\n      "description": "Zobrazí se nad souhrnnou zpětnou vazbou."\n    },\n    {\n      "label": "Text pro správnou odpověď",\n      "default": "Správně."\n    },\n    {\n      "label": "Text pro oznámení nesprávné odpovědi",\n      "default": "Chybně! Zkuste znovu."\n    },\n    {\n      "label": "Popisek textu pro nesprávnou odpověď",\n      "default": "Chybně"\n    },\n    {\n      "label": "Popisek seznamu správných odpovědí",\n      "default": "Správné odpovědi."\n    },\n    {\n      "label": "Popisek tlačítka zobrazení tipu",\n      "default": "Zobrazení nápovědy"\n    },\n    {\n      "label": "Textové znázornění výsledkové lišty pro ty, kteří používají čtecí zařízení",\n      "description": ":num a :total jsou speciální klíčová slova, která jsou programově aktualizována",\n      "default": "Získal jste :num ze :total bodů"\n    },\n    {\n      "label": "Text používaný pro čtecí zařízení ke komunikaci o pokroku",\n      "description": ":num a :total jsou speciální klíčová slova, která jsou programově aktualizována",\n      "default": "Pokrok :num z :total"\n    }\n  ]\n}\n'),
(34, 'da', '{\n  "semantics": [\n    {\n      "label": "Introduction text",\n      "default": "Choose the correct statement.",\n      "description": "Will be displayed above the summary task."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Default"\n        },\n        {\n          "label": "Textual"\n        }\n      ],\n      "label": "Resumé",\n      "entity": "statements",\n      "field": {\n        "label": "Set of statements",\n        "fields": [\n          {\n            "label": "List of statements for the summary - the first statement is correct.",\n            "entity": "statement",\n            "field": {\n              "label": "Statement"\n            }\n          },\n          {\n            "label": "Tip",\n            "fields": [\n              {\n                "label": "Tip text"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Default"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text displayed before number of statements solved in the summary task.",\n      "default": "Progress:",\n      "description": "Will be displayed above the statements. Example: ''Progress: 2/5''"\n    },\n    {\n      "label": "Text displayed before number of wrong statements selected in the summary task.",\n      "default": "Wrong answers:",\n      "description": "Will be displayed above the statements. Example: ''Wrong answers: 4''"\n    },\n    {\n      "label": "Summary feedback header",\n      "default": "Your result",\n      "description": "Will be displayed above the summary feedback."\n    },\n    {\n      "label": "Readspeaker text for correct answer",\n      "default": "Correct."\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "Label list of correct answers",\n      "default": "Correct answers."\n    },\n    {\n      "label": "Label for the show tip button",\n      "default": "Show tip"\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Text used for readspeakers to communicate progress",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "Progress :num of :total"\n    }\n  ]\n}');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(34, 'de', '{\n  "semantics": [\n    {\n      "label": "Aufgabenbeschreibung",\n      "default": "Wähle die korrekte Aussage.",\n      "description": "Wird über der Aufgabe angezeigt."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Eingabemaske"\n        },\n        {\n          "label": "In Textfeld eingeben"\n        }\n      ],\n      "label": "Zusammenfassung",\n      "entity": "Aussagen",\n      "field": {\n        "label": "Menge von Aussagen",\n        "fields": [\n          {\n            "label": "Liste von Aussagen für die Zusammenfassung - die erste Aussage ist die richtige.",\n            "entity": "Aussage",\n            "field": {\n              "label": "Aussage"\n            }\n          },\n          {\n            "label": "Tipp",\n            "fields": [\n              {\n                "label": "Tipp-Text"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Gesamtrückmeldung",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Eingabemaske"\n            }\n          ],\n          "label": "Lege Rückmeldungen für einzelne Punktebereiche fest",\n          "description": "Klicke auf den \\"Bereich hinzufügen\\"-Button, um so viele Bereiche hinzuzufügen, wie du brauchst. Beispiel: 0-20% Schlechte Punktzahl, 21-91% Durchschnittliche Punktzahl, 91-100% Großartige Punktzahl!",\n          "entity": "Bereich",\n          "field": {\n            "fields": [\n              {\n                "label": "Punktebereich"\n              },\n              {},\n              {\n                "label": "Rückmeldung für jeweiligen Punktebereich",\n                "placeholder": "Trage die Rückmeldung ein"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text, der vor der Anzahl der richtig gewählten Aussagen angezeigt wird.",\n      "default": "Fortschritt:",\n      "description": "Wird über den Aussagen angezeigt. Beispiel: ''Fortschritt: 2/5''"\n    },\n    {\n      "label": "Text, der vor der Anzahl der falsch gewählten Aussagen angezeigt wird.",\n      "default": "Falsche Antworten:",\n      "description": "Wird über den Aussagen angezeigt. Beispiel: ''Falsche Antworten: 4''"\n    },\n    {\n      "label": "Überschrift der abschließend dargestellten Gesamtpunktzahl",\n      "default": "Dein Ergebnis",\n      "description": "Wird über dem Rückmeldungstext mit der Punktzahl angezeigt."\n    },\n    {\n      "label": "Text, den ein Vorlesewerkzeug bei einer richtigen Antwort vorliest (Barrierefreiheit)",\n      "default": "Richtig."\n    },\n    {\n      "label": "Text, den ein Vorlesewerkzeug bei einer falschen Antwort vorliest (Barrierefreiheit)",\n      "default": "Falsch! Bitte versuche es noch einmal."\n    },\n    {\n      "label": "Bezeichnung einer falschen Antwort für Vorlesewerkzeuge (Barrierefreiheit)",\n      "default": "Falsch"\n    },\n    {\n      "label": "Bezeichnung der Liste richtiger Antworten",\n      "default": "Richtige Antwort(en)."\n    },\n    {\n      "label": "Beschriftung des \\"Tipp anzeigen\\"-Buttons",\n      "default": "Tipp anzeigen"\n    },\n    {\n      "label": "Anzeigetext der Punkteleiste für Vorlesewerkzeuge (Barrierefreiheit)",\n      "description": ":num kann als Platzhalter für die tatsächlich erreichten Punkte verwendet werden, :total für die Maximalpunktzahl",\n      "default": "Du hast :num von :total Punkten erreicht."\n    },\n    {\n      "label": "Text, den Vorlesewerkzeuge nutzen, um den derzeitigen Fortschritt auszugeben",\n      "description": ":num kann als Platzhalter für die tatsächlich erreichten Punkte verwendet werden, :total für die Maximalpunktzahl",\n      "default": "Fortschritt :num von :total"\n    }\n  ]\n}\n'),
(34, 'el', '{\n  "semantics": [\n    {\n      "label": "Εισαγωγικό κείμενο",\n      "default": "Επίλεξε τη σωστή πρόταση.",\n      "description": "Θα εμφανίζεται πάνω από την άσκηση σύνοψης."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Βασικό"\n        },\n        {\n          "label": "Κείμενο"\n        }\n      ],\n      "label": "Περίληψη",\n      "entity": "προτασεων",\n      "field": {\n        "label": "Σύνολο προτάσεων",\n        "fields": [\n          {\n            "label": "Λίστα προτάσεων για τη σύνθεση της σύνοψης - η πρώτη πρόταση είναι η σωστή.",\n            "entity": "προτασης",\n            "field": {\n              "label": "Πρόταση"\n            }\n          },\n          {\n            "label": "Επεξήγηση",\n            "fields": [\n              {\n                "label": "Επεξηγηματικό κείμενο"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Συνολική ανατροφοδότηση",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Βασικό"\n            }\n          ],\n          "label": "Χαρακτηρισμός κάθε κλίμακας βαθμολογίας",\n          "description": "Επιλέξτε το κουμπί \\"Προσθήκη κλίμακας\\" για να προσθέσετε όσες κλίμακες ή διαβαθμίσεις επιθυμείτε. Παράδειγμα: 0-20% Χαμηλή βαθμολογία, 21-91% Μέτρια βαθμολογία, 91-100% Εξαιρετική βαθμολογία!",\n          "entity": "κλιμακας",\n          "field": {\n            "fields": [\n              {\n                "label": "Βαθμολογία"\n              },\n              {},\n              {\n                "label": "Χαρακτηρισμός",\n                "placeholder": "Συμπληρώστε τον χαρακτηρισμό"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Κείμενο που εμφανίζεται πριν από τον αριθμό των σωστών προτάσεων στην άσκηση σύνοψης.",\n      "default": "Πρόοδος:",\n      "description": "Θα εμφανίζεται πάνω από τις προτάσεις. Παράδειγμα: ''Πρόοδος: 2/5''"\n    },\n    {\n      "label": "Κείμενο που εμφανίζεται πριν από τον αριθμό των λάθος προτάσεων στην άσκηση σύνοψης.",\n      "default": "Λάθος απαντήσεις:",\n      "description": "Θα εμφανίζεται πάνω από τις προτάσεις. Παράδειγμα: ''Λάθος απαντήσεις: 4''"\n    },\n    {\n      "label": "Επικεφαλίδα ανατροφοδότησης για τη σύνοψη",\n      "default": "Η βαθμολογία σου",\n      "description": "Θα εμφανίζεται πάνω από την ανατροφοδότηση."\n    },\n    {\n      "label": "Κείμενο ακουστικής υποβοήθησης για τη σωστή απάντηση",\n      "default": "Σωστό."\n    },\n    {\n      "label": "Κείμενο ακουστικής υποβοήθησης για την ανακοίνωση λάθος απάντησης",\n      "default": "Λάθος! Προσπάθησε ξανά."\n    },\n    {\n      "label": "Κείμενο ακουστικής υποβοήθησης για τη λάθος απάντηση",\n      "default": "Λάθος."\n    },\n    {\n      "label": "Ετικέτα λίστας με σωστές απαντήσεις",\n      "default": "Σωστές απαντήσεις."\n    },\n    {\n      "label": "Ετικέτα κουμπιού εμφάνισης επεξήγησης",\n      "default": "Εμφάνιση επεξήγησης"\n    },\n    {\n      "label": "Κειμενική απόδοση της μπάρας βαθμολογίας για όσους χρησιμοποιούν ακουστική υποβοήθηση",\n      "description": "Οι :num, :total είναι μεταβλητές που ενημερώνονται αυτόματα",\n      "default": "Έχεις :num από :total βαθμούς"\n    },\n    {\n      "label": "Το κείμενο χρησιμοποιείται από εφαρμογές ακουστικής υποβοήθησης για να ενημερώσει τον χρήστη για την πρόοδό του",\n      "description": "Οι :num, :total είναι μεταβλητές που ενημερώνονται αυτόματα",\n      "default": "Πρόοδος: :num από :total"\n    }\n  ]\n}\n'),
(34, 'es', '{\n  "semantics": [\n    {\n      "label": "Texto de introducción",\n      "default": "Elige la oración correcta.",\n      "description": "Se mostrará encima de la tarea de resumen."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Por defecto"\n        },\n        {\n          "label": "Textual"\n        }\n      ],\n      "label": "Resumen",\n      "entity": "oraciones",\n      "field": {\n        "label": "Conjunto de oraciones",\n        "fields": [\n          {\n            "label": "Lista de oraciones para el resumen: la primera es la correcta.",\n            "entity": "oración",\n            "field": {\n              "label": "Oración"\n            }\n          },\n          {\n            "label": "Pista",\n            "fields": [\n              {\n                "label": "Texto de la pista"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Retroalimentación Global",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Por defecto"\n            }\n          ],\n          "label": "Definir retroalimentación personalizada para cualquier rango de puntuación",\n          "description": "Haz clic en el botón \\"Añadir rango\\" para añadir los rangos que necesites. Ejemplo: 0-20% Mala puntuación, 21-91% Puntuación Media, 91-100% ¡Puntuación Estupenda!",\n          "entity": "rango",\n          "field": {\n            "fields": [\n              {\n                "label": "Rango de Puntuación"\n              },\n              {},\n              {\n                "label": "Realimentación para el rango de puntuación definido",\n                "placeholder": "Escribe tu retroalimentación"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texto mostrado delante del número de oraciones resueltas en la tarea de resumen.",\n      "default": "Progreso:",\n      "description": "Se mostrará encima de las oraciones. Ejemplo: ''Progreso: 2/5''"\n    },\n    {\n      "label": "Texto mostrado delante de las oraciones incorrectas seleccionadas en la tarea de resumen.",\n      "default": "Respuestas incorrectas:",\n      "description": "Se mostrará encima de las oraciones. Ejemplo: ''Respuestas incorrectas: 4''"\n    },\n    {\n      "label": "Encabezado de retroalimentación del resumen",\n      "default": "Tu resultado",\n      "description": "Se mostrará encima de la retroalimentación del resumen."\n    },\n    {\n      "label": "Texto para lector de pantalla para respuesta correcta",\n      "default": "Correcta."\n    },\n    {\n      "label": "Texto para lector de pantalla para respuesta incorrecta",\n      "default": "¡Incorrecto! Por favor inténtalo otra vez."\n    },\n    {\n      "label": "Texto para lector de pantalla para respuesta incorrecta",\n      "default": "Incorrecto"\n    },\n    {\n      "label": "Lista de etiqueta de respuestas correctas",\n      "default": "Respuestas correctas."\n    },\n    {\n      "label": "Etiqueta para el botón de mostrar pista",\n      "default": "Mostrar pista"\n    },\n    {\n      "label": "Representación textual de la barra de puntuación cuando se usa un lector de pantalla",\n      "description": ":num y :total son palabras clave especiales que se actualizan programáticamente",\n      "default": "Has conseguido :num de un total de :total puntos"\n    },\n    {\n      "label": "Texto utilizado por los lectores de pantalla para comunicar el progreso",\n      "description": ":num y :total son palabras clave especiales actualizadas programáticamente",\n      "default": "Progreso :num de :total"\n    }\n  ]\n}\n'),
(34, 'es-mx', '{\n  "semantics": [\n    {\n      "label": "Texto introductorio",\n      "default": "Elija la oración correcta.",\n      "description": "Será mostrada arriba del trabajo resumido."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Predeterminado"\n        },\n        {\n          "label": "Textual"\n        }\n      ],\n      "label": "Resumen",\n      "entity": "oraciones",\n      "field": {\n        "label": "Conjunto de oraciones",\n        "fields": [\n          {\n            "label": "Lista de oraciones para el resumen - la primera oración es correcta.",\n            "entity": "oración",\n            "field": {\n              "label": "Oración"\n            }\n          },\n          {\n            "label": "Pista",\n            "fields": [\n              {\n                "label": "Texto de la pista"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Retroalimentación Global",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Predeterminado"\n            }\n          ],\n          "label": "Definir retroalimentación personalizada para cualquier rango de puntaje",\n          "description": "Haga clic en el botón \\"Añadir rango\\" para añadir cuantos rangos necesite. Ejemplo: 0-20% Mal puntaje, 21-91% Puntaje Promedio, 91-100% ¡Magnífico Puntaje!",\n          "entity": "rango",\n          "field": {\n            "fields": [\n              {\n                "label": "Rango del Puntaje"\n              },\n              {},\n              {\n                "label": "Retroalimentación para rango de puntaje definido",\n                "placeholder": "Complete la retroalimentación"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texto mostrado antes de varias oraciones resueltas en el trabajo resumido.",\n      "default": "Progreso:",\n      "description": "Será mostrado arriba de las oraciones. Ejemplo: ''Progreso: 2/5''"\n    },\n    {\n      "label": "Texto mostrado antes de varias oraciones incorrectas seleccionadas en el trabajo resumido.",\n      "default": "Respuestas incorrectas:",\n      "description": "Será mostrado arriba de las oraciones. Ejemplo: ''Respuestas incorrectas: 4''"\n    },\n    {\n      "label": "Encabezado de Retroalimentación Resumida",\n      "default": "Su resultado",\n      "description": "Será mostrado arriba de la retroalimentación resumida."\n    },\n    {\n      "label": "Texto de Lector en voz alta para respuesta correcta",\n      "default": "Correcta."\n    },\n    {\n      "label": "Texto de Lector en voz alta para anunciar respuesta incorrecta",\n      "default": "¡Incorrecto! Por favor inténtelo nuevamente."\n    },\n    {\n      "label": "Etiqueta de Lector en voz alta para respuesta incorrecta",\n      "default": "Incorrecto"\n    },\n    {\n      "label": "Lista de etiqueta de respuestas correctas",\n      "default": "Respuestas correctas."\n    },\n    {\n      "label": "Etiqueta para el botón de mostrar pista",\n      "default": "Mostrar pista"\n    },\n    {\n      "label": "Representación textual de la barra de puntaje para aquellos que usan un lector de texto en voz alta",\n      "description": ":num y :total son palabras clave especiales que son actualizadas programáticamente",\n      "default": "Obtuvo :num de un total de :total"\n    },\n    {\n      "label": "Texto usado para Lectores en voz alta para comunicar el progreso",\n      "description": ":num y :total son palabras clave especiales que son actualizadas programáticamente",\n      "default": "Progreso :num de :total"\n    }\n  ]\n}\n'),
(34, 'et', '{\n  "semantics": [\n    {\n      "label": "Tutvustustekst",\n      "default": "Vali õige väide.",\n      "description": "Näidatakse kokkuvõtva ülesande kohal."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Vaikimisi"\n        },\n        {\n          "label": "Tekstiline"\n        }\n      ],\n      "label": "Kokkuvõttev",\n      "entity": "väited",\n      "field": {\n        "label": "Väitekogumik",\n        "fields": [\n          {\n            "label": "Väidete loetelu kokkuvõtte jaoks - esimene väide on õige.",\n            "entity": "väide",\n            "field": {\n              "label": "Väide"\n            }\n          },\n          {\n            "label": "Vihje",\n            "fields": [\n              {\n                "label": "Vihje tekst"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Üldine tagasiside",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Vaikimisi"\n            }\n          ],\n          "label": "Määratle kohandatud tagasiside iga punktisumma vahemiku jaoks",\n          "description": "Vajuta \\"Lisa vahemik\\" nupul, et lisada vajalikud vahemikud. Näide: 0-20% halb tulemus, 21-91% keskmine tulemus, 91-100% suurepärane tulemus!",\n          "entity": "vahemik",\n          "field": {\n            "fields": [\n              {\n                "label": "Punktisumma vahemik"\n              },\n              {},\n              {\n                "label": "Määratletud punktisummavahemiku tagasiside",\n                "placeholder": "Sisesta tagasiside"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Tekst, mida näidatakse enne kokkuvõtvas ülesandes lahendatud väidete arvu.",\n      "default": "Progress:",\n      "description": "Näidatakse väidete ülal. Näiteks: ''Progress: 2/5''"\n    },\n    {\n      "label": "Tekst, mida näidatakse enne kokkuvõtvas ülesandes valitud valede väidete arvu.",\n      "default": "Valesid vastuseid:",\n      "description": "Näidatakse väidete ülal. Näiteks: ''Valesid vastuseid: 4''"\n    },\n    {\n      "label": "Kokkuvõtva tagasiside päis",\n      "default": "Sinu tulemus",\n      "description": "Näidatakse kokkuvõtva tagasiside kohal."\n    },\n    {\n      "label": "Õige vastuse tekstilugeri tekst",\n      "default": "Õige."\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "Õigete vastuste loetelu silt",\n      "default": "Õiged vastused."\n    },\n    {\n      "label": "Näita vihjet nupu silt",\n      "default": "Näita vihjet"\n    },\n    {\n      "label": "Tekstilugeri kasutajaile punktisummariba tekstiline esitamine",\n      "description": ":num ja :total on erilised võtmesõnad, mida programm ise uuendab",\n      "default": "Sa said :num punkti :total punktist"\n    },\n    {\n      "label": "Edenemise teavitustekst tekstilugeri kasutajaile",\n      "description": ":num ja  :total on erilised võtmesõnad, mida programm ise uuendab",\n      "default": "Progress :num punkti kokku :total punktist"\n    }\n  ]\n}'),
(34, 'eu', '{\n  "semantics": [\n    {\n      "label": "Sarrera-testua",\n      "default": "Aukeratu adierazpen egokia.",\n      "description": "Laburpen-zereginaren gainean erakutsiko da."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Lehentsitakoa"\n        },\n        {\n          "label": "Testuala"\n        }\n      ],\n      "label": "Laburpena",\n      "entity": "adierazpenak",\n      "field": {\n        "label": "Adierazpen-multzoa",\n        "fields": [\n          {\n            "label": "Laburpenerako adierazpenen zerrenda – lehen adierazpena zuzena da.",\n            "entity": "adierazpena",\n            "field": {\n              "label": "Adierazpena"\n            }\n          },\n          {\n            "label": "Argibidea",\n            "fields": [\n              {\n                "label": "Argibidearen testua"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Feedback Orokorra",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Lehenetsitakoa"\n            }\n          ],\n          "label": "Zehaztu ezazu edozein puntuazio-tarterako feedback pertsonalizatua",\n          "description": "Egin klik \\"Gehitu tartea\\" botoian behar dituzun tarte guztiak gehitzeko. Adibidez: 0-20% Puntuazio eskasa, 21-91% Batez besteko puntuazioa, 91-100% Puntuazio bikaina!",\n          "entity": "tartea",\n          "field": {\n            "fields": [\n              {\n                "label": "Puntazio-tartea"\n              },\n              {},\n              {\n                "label": "Zehaztutako tartearentzako feedbacka",\n                "placeholder": "Idatzi ezazu feedbacka"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Laburpen-zereginean ebatzitako adierazpen-kopuruaren aurretik erakutsiko den testua.",\n      "default": "Aurrerapena:",\n      "description": "Adierazpenen aurretik erakutsiko da. Adibidez: ''Aurrerapena: 2/5''"\n    },\n    {\n      "label": "Laburpen-zeregineko adierazpen okerren kopuruaren aurretik erakutsiko den testua.",\n      "default": "Erantzun okerrak:",\n      "description": "Adierazpenen aurretik erakutsiko da. Adibidez: ''Erantzun okerrak: 4''"\n    },\n    {\n      "label": "Laburpenaren feedbackaren goiburua",\n      "default": "Zure emaitza",\n      "description": "Laburpenaren feedbacakren aurretik erakutsiko da."\n    },\n    {\n      "label": "Erantzun zuzenetarako irakurgailuaren testua",\n      "default": "Erantzun zuzena."\n    },\n    {\n      "label": "Erantzun okerretarako irakurgailuaren testua",\n      "default": "Okerra! Mesedez berriz saiatu zaitez."\n    },\n    {\n      "label": "Erantzun okerren zerrendarako etiketa",\n      "default": "Erantzun okerra"\n    },\n    {\n      "label": "Erantzun zuzenen zerrendarako etiketa",\n      "default": "Erantzun zuzenak."\n    },\n    {\n      "label": "Argibidea erakusteko botoiarentzako etiketa",\n      "default": "Erakutsi argibidea"\n    },\n    {\n      "label": "Puntuazio barraren testu adierazpena irakurgailua erabiltzen dutenentzat",\n      "description": ":num eta :total programak eguneratzen dituen hitz-gako bereziak dira",\n      "default": ":total puntutik :num puntu lortu duzu"\n    },\n    {\n      "label": "Aurrerapena adierazteko irakurgailuek erabilitako testua",\n      "description": ":num eta :total programak eguneratzen dituen hitz-gako bereziak dira",\n      "default": "Aurrerapena: :total puntutik :num"\n    }\n  ]\n}\n'),
(34, 'fa', '{\n  "semantics": [\n    {\n      "label": "متن مقدمه",\n      "default": "گزاره صحیح را انتخاب کنید.",\n      "description": "بالای فعالیت جمع‌بندی نمایش داده خواهد شد."\n    },\n    {\n      "widgets": [\n        {\n          "label": "پیش‌فرض"\n        },\n        {\n          "label": "متنی"\n        }\n      ],\n      "label": "جمع‌بندی",\n      "entity": "گزاره‌ها",\n      "field": {\n        "label": "مجموعه گزاره‌ها",\n        "fields": [\n          {\n            "label": "لیست گزاره‌ها برای جمع‌بندی - اولین گزاره صحیح است.",\n            "entity": "گزاره",\n            "field": {\n              "label": "گزاره"\n            }\n          },\n          {\n            "label": "نکته",\n            "fields": [\n              {\n                "label": "متن نکته"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "بازخورد کلی",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "پیش‌فرض"\n            }\n          ],\n          "label": "تعریف بازخورد سفارشی برای هر بازه نمره",\n          "description": "برای افزودن هر تعداد بازه که می‌خواهید، رو دکمه \\"افزودن بازه\\" کلیک کنید. مثال: ۰-۲۰٪ نمره بد، ۲۱-۹۱٪ نمره متوسط، ۹۱-۱۰۰٪ نمره عالی!",\n          "entity": "بازه",\n          "field": {\n            "fields": [\n              {\n                "label": "بازه نمره"\n              },\n              {},\n              {\n                "label": "بازخورد بازه نمره تعریف شده",\n                "placeholder": "بازخورد را پر کنید"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "متن نمایش داده شده پیش از تعداد گزاره‌های حل شده در فعالیت جمع‌بندی.",\n      "default": "پیشرفت:",\n      "description": "بالای گزاره‌ها نمایش داده خواهد شد. مثال: پیشرفت: ۲/۵"\n    },\n    {\n      "label": "متن نمایش داده شده پیش از تعداد گزاره‌های غلط انتخاب شده در فعالیت جمع‌بندی.",\n      "default": "پاسخ‌های غلط:",\n      "description": "بالای گزاره‌ها نمایش داده خواهد شد. مثال: پاسخ‌های غلط: ۴"\n    },\n    {\n      "label": "سرصفحه بازخورد جمع‌بندی",\n      "default": "نتیجه شما",\n      "description": "بالای بازخورد جمع‌بندی نمایش داده خواهد شد."\n    },\n    {\n      "label": "متن مبدل متن به گفتار برای پاسخ صحیح",\n      "default": "صحیح."\n    },\n    {\n      "label": "متن مبدل متن به گفتار برای اعلان پاسخ غلط",\n      "default": "غلط! لطفاً دوباره تلاش کنید."\n    },\n    {\n      "label": "برچسب مبدل متن به گفتار برای پاسخ غلط",\n      "default": "غلط"\n    },\n    {\n      "label": "برچسب لیست پاسخ‌های صحیح",\n      "default": "پاسخ‌های صحیح."\n    },\n    {\n      "label": "برچسب دکمه نمایش نکته",\n      "default": "نمایش راهنمایی"\n    },\n    {\n      "label": "بازنمایی متنی نوار نمره برای آنهایی که از مبدل متن به گفتار استفاده می‌کنند",\n      "description": ":num و :total کلمات کلیدی مخصوصی هستند که به صورت برنامه‌ریزی شده به روز می‌شوند",\n      "default": "شما از ‎:total امتیاز، نمره ‎:num را دریافت کردید"\n    },\n    {\n      "label": "متن مورد استفاده مبدل متن به گفتار برای ابلاغ پیشرفت",\n      "description": ":num و :total کلمات کلیدی مخصوصی هستند که به صورت برنامه‌ریزی شده به روز می‌شوند",\n      "default": "پیشرفت :num از :total"\n    }\n  ]\n}\n'),
(34, 'fi', '{\n  "semantics": [\n    {\n      "label": "Tehtävän kuvaus",\n      "default": "Valitse oikea väittämä.",\n      "description": "Näytetään tehtävän yläpuolella."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Oletus"\n        },\n        {\n          "label": "Teksti"\n        }\n      ],\n      "label": "Yhteenveto",\n      "entity": "väittämät",\n      "field": {\n        "label": "Väittämät",\n        "fields": [\n          {\n            "label": "Väittämät - ensimmäinen vaihtoehto on oikein.",\n            "entity": "väittämä",\n            "field": {\n              "label": "Väittämä"\n            }\n          },\n          {\n            "label": "Vihje",\n            "fields": [\n              {\n                "label": "Vihjeteksti"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Yleinen palaute",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Oletus"\n            }\n          ],\n          "label": "Määritä muokattu palaute pisterajojen mukaan.",\n          "description": "Klikkaa \\"Lisää alue\\" painiketta lisätäksesi niin monta pisterajaa kuin tarvit. Esimerkiksi: 0-20% Huono tulos, 21-91% Kelpo tulos, 91-100% Mahtava tulos!",\n          "entity": "alue",\n          "field": {\n            "fields": [\n              {\n                "label": "Pisteraja"\n              },\n              {},\n              {\n                "label": "Palaute määritellylle pisterajalle",\n                "placeholder": "Kirjoita palaute"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Ennen ratkaistujen väittämien lukumäärää näytettävä teksti.",\n      "default": "Edistyminen:",\n      "description": "Näytetään väittämien yläpuolella. Esimerkiksi: ''Edistyminen: 2/5''"\n    },\n    {\n      "label": "Ennen väärin valittujen väittämien lukumäärää näytettävä teksti.",\n      "default": "Vääriä vastauksia:",\n      "description": "Näytetään väittämien yläpuolella. Esimerkiksi: ''Vääriä vastauksia : 4''"\n    },\n    {\n      "label": "Tulossivun otsikko",\n      "default": "Tuloksesi",\n      "description": "Näytetään tehtävän palautteen yläpuolella."\n    },\n    {\n      "label": "Ruudunlukijan palaute oikeasta vastauksesta",\n      "default": "Oikein!"\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "Oikeiden vastauksien listan kuvaus",\n      "default": "Oikeat vastaukset."\n    },\n    {\n      "label": "Näytä vinkki",\n      "default": "Näytä vinkki"\n    },\n    {\n      "label": "Ruuudunlukijan teksti ilmaisemaan pisteitä",\n      "description": "Käytössä muuttujat :num ja :total",\n      "default": "Sinulla on :num/:total pistettä"\n    },\n    {\n      "label": "Ruudunlukijan teksti ilmaisemaan edistymistä",\n      "description": "Käytössä muuttujat :num ja :total",\n      "default": "Edistymisesi :num/:total"\n    }\n  ]\n}'),
(34, 'fr', '{\n  "semantics": [\n    {\n      "label": "Texte d''introduction",\n      "default": "Choisissez l''affirmation exacte.",\n      "description": "Il sera affiché au-dessus de l''activité Résumé."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Par défaut"\n        },\n        {\n          "label": "Texte"\n        }\n      ],\n      "label": "Résumé",\n      "entity": "Affirmations",\n      "field": {\n        "label": "Affirmations",\n        "fields": [\n          {\n            "label": "Liste des affirmations pour le résumé - la première affirmation de la liste est correcte.",\n            "entity": "affirmation",\n            "field": {\n              "label": "affirmation"\n            }\n          },\n          {\n            "label": "Indice",\n            "fields": [\n              {\n                "label": "Indice"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Feedback général",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Par défaut"\n            }\n          ],\n          "label": "Définissez le feedback pour chaque intervalle de score",\n          "description": "Cliquez sur \\"Ajouter Intervalle\\" pour ajouter autant d''intervalles de score que vous le souhaitez. Exemple : 0-20% Mauvais score, 21-91% Score moyen, 91-100% Score excellent!",\n          "entity": "intervalle",\n          "field": {\n            "fields": [\n              {\n                "label": "Intervalle de score"\n              },\n              {},\n              {\n                "label": "Feedback pour l''intervalle de score défini",\n                "placeholder": "Remplir le feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texte affiché avant le nombre d''affirmations correctement sélectionnées dans le résumé.",\n      "default": "Progression :",\n      "description": "Ce sera affiché au-dessus des affirmations. Exemple: ''Progression : 2/5''"\n    },\n    {\n      "label": "Texte affiché au-dessus du nombre d''affirmations sélectionnées par erreur dans le résumé.",\n      "default": "Erreurs :",\n      "description": "Ce sera affiché au-dessus des affirmations. Exemple: ''Erreurs : 4''"\n    },\n    {\n      "label": "Titre de l''appréciation à la fin du résumé",\n      "default": "Votre résultat :",\n      "description": "Ce sera affiché au-dessus de l''appréciation."\n    },\n    {\n      "label": "Texte exprimé par la synthèse vocale en cas de réponse correcte",\n      "default": "Correct."\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "Liste de réponses correctes",\n      "default": "Réponses correctes."\n    },\n    {\n      "label": "Etiquette pour montrer le bouton d''indice",\n      "default": "Montrer l''indice"\n    },\n    {\n      "label": "Représentation textuelle du panneau du score pour les utilisateurs de la synthèse vocale",\n      "description": ":num et :total sont des mots clés mis à jour automatiquement",\n      "default": "Vous avez :num points sur un total de :total"\n    },\n    {\n      "label": "Représentation textuelle utilisée par la synthèse vocale pour communiquer sur l''avancement",\n      "description": ":num et :total sont des mots clés mis à jour automatiquement",\n      "default": "Progression de :num sur :total"\n    }\n  ]\n}\n'),
(34, 'gl', '{\n  "semantics": [\n    {\n      "label": "Texto de introdución",\n      "default": "Escolle a frase correcta.",\n      "description": "Amosarase enriba do tarefa de resumo."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Por defecto"\n        },\n        {\n          "label": "Textual"\n        }\n      ],\n      "label": "Resumo",\n      "entity": "frases",\n      "field": {\n        "label": "Conxunto de frases",\n        "fields": [\n          {\n            "label": "Lista de frases para o resumo - a primeira frase é correcta.",\n            "entity": "frase",\n            "field": {\n              "label": "Frase"\n            }\n          },\n          {\n            "label": "Pista",\n            "fields": [\n              {\n                "label": "Texto da pista"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Retroalimentación xeral",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Por defecto"\n            }\n          ],\n          "label": "Definir comentarios personalizados para calquera rango de puntuación",\n          "description": "Preme o botón \\"Engadir rango\\" para engadir tantos rangos como precises. Exemplo: 0-20% Mala puntuación, 21-91% Puntuación Media, 91-100% Puntuación estupenda!",\n          "entity": "rango",\n          "field": {\n            "fields": [\n              {\n                "label": "Rango de Puntuación"\n              },\n              {},\n              {\n                "label": "Retroalimentación para rango de puntuación definido",\n                "placeholder": "Escribe a túa retroalimentación"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texto amosado antes do número de frases resoltas na tarefa de resumo.",\n      "default": "Progreso:",\n      "description": "Amosarase enriba das frases. Exemplo: ''Progreso: 2/5''"\n    },\n    {\n      "label": "Texto amosado antes do número de frases incorrectas seleccionadas na tarefa de resumo.",\n      "default": "Respostas incorrectas:",\n      "description": "Amosarase enriba das frases. Exemplo: ''Respostas incorrectas: 4''"\n    },\n    {\n      "label": "Cabeceira da retroalimentación do resumo",\n      "default": "O teu resultado",\n      "description": "Amosarase enriba da retroalimentación do resumo."\n    },\n    {\n      "label": "Texto do lector de pantalla para resposta correcta",\n      "default": "Correcto."\n    },\n    {\n      "label": "Texto do lector de pantalla para anunciar unha resposta incorrecta",\n      "default": "Incorrecto! Por favor, proba outra vez."\n    },\n    {\n      "label": "Etiqueta do lector de pantalla para resposta incorreta",\n      "default": "Incorrecto"\n    },\n    {\n      "label": "Etiqueta para a lista de respostas correctas",\n      "default": "Respostas correctas."\n    },\n    {\n      "label": "Etiqueta para amosar o botón da pista",\n      "default": "Amosar pista"\n    },\n    {\n      "label": "Representación textual da barra de puntuación cando se está a usar un lector de pantalla",\n      "description": ":num e :total son palabras chave especiais actualizadas programaticamente",\n      "default": "Conseguiches :num dun total de :total puntos"\n    },\n    {\n      "label": "Texto do lector de pantalla para indicar progreso",\n      "description": ":num e :total son palabras chave especiais actualizadas programaticamente",\n      "default": "Progreso :num de :total"\n    }\n  ]\n}\n'),
(34, 'it', '{\n  "semantics": [\n    {\n      "label": "Testo di introduzione",\n      "default": "Scegli l''affermazione corretta",\n      "description": "Sarà mostrato sopra l''attività di riepilogo"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Predefinito"\n        },\n        {\n          "label": "Testuale"\n        }\n      ],\n      "label": "Riepilogo",\n      "entity": "proposizioni",\n      "field": {\n        "label": "Serie di proposizioni",\n        "fields": [\n          {\n            "label": "Elenco di proposizioni per il sommario - la prima è corretta",\n            "entity": "proposizione",\n            "field": {\n              "label": "Proposizione"\n            }\n          },\n          {\n            "label": "Suggerimento",\n            "fields": [\n              {\n                "label": "Testo del suggerimento"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Feedback generale",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Predefinito"\n            }\n          ],\n          "label": "Specifica un feedback per ogni intervallo di punteggio",\n          "description": "Clicca sul pulsante \\"Aggiungi intervallo\\" per aggiungere gli intervalli che ti servono. Per esempio: 0-20%, Punteggio scarso; 21-90%, Punteggio medio; 91-100% Punteggio ottimo!",\n          "entity": "intervallo",\n          "field": {\n            "fields": [\n              {\n                "label": "Intervallo di punteggio"\n              },\n              {},\n              {\n                "label": "Feedback per un intervallo definito",\n                "placeholder": "Compila il feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Testo mostrato prima del numero di proposizioni risolte nell''attività di riepilogo",\n      "default": "Avanzamento:",\n      "description": "Sarà mostrato sopra le istruzioni. Esempio: ''Avanzamento: 2/5''"\n    },\n    {\n      "label": "Testo mostrato prima del numero di proposizioni sbagliate, selezionato nell''attività di riepilogo",\n      "default": "Risposte sbagliate:",\n      "description": "Sarà mostrato sopra le istruzioni. Esempio: ''Risposte sbagliate: 4''"\n    },\n    {\n      "label": "Intestazione del feedback di riepilogo",\n      "default": "Il tuo risultato",\n      "description": "Sarà mostrato sopra il feedback di riepilogo"\n    },\n    {\n      "label": "Testo del lettore vocale per risposta giusta",\n      "default": "Giusto"\n    },\n    {\n      "label": "Testo del lettore vocale per informare su una risposta sbagliata",\n      "default": "Sbagliato! Prova ancora"\n    },\n    {\n      "label": "Etichetta del lettore vocale per risposta sbagliata",\n      "default": "Sbagliato"\n    },\n    {\n      "label": "Elenco di etichette di risposte giuste",\n      "default": "Risposte giuste"\n    },\n    {\n      "label": "Etichetta per il pulsante \\"Mostra suggerimento\\"",\n      "default": "Mostra suggerimento"\n    },\n    {\n      "label": "Rappresentazione testuale sulla barra del punteggio per chi usa un lettore vocale",\n      "description": ":num e :total sono parole chiavi speciali programmaticamente aggiornate",\n      "default": "Il tuo punteggio è :num su :total"\n    },\n    {\n      "label": "Messaggio usato dai lettori vocali per comunicare l''avanzamento",\n      "description": ":num e :total sono parole chiavi speciali programmaticamente aggiornate",\n      "default": "Avanzamento: :num su :total"\n    }\n  ]\n}\n'),
(34, 'ja', '{\n  "semantics": [\n    {\n      "label": "概要文",\n      "default": "正しい文を選んで下さい。",\n      "description": "サマリータスクの上に表示されます。"\n    },\n    {\n      "widgets": [\n        {\n          "label": "デフォルト"\n        },\n        {\n          "label": "原文"\n        }\n      ],\n      "label": "サマリー",\n      "entity": "文",\n      "field": {\n        "label": "文の集まり",\n        "fields": [\n          {\n            "label": "サマリー用の文のリスト - 最初の文は正解。",\n            "entity": "文",\n            "field": {\n              "label": "文"\n            }\n          },\n          {\n            "label": "ヒント",\n            "fields": [\n              {\n                "label": "ヒントのテキスト"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "全体のフィードバック",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "デフォルト"\n            }\n          ],\n          "label": "ある得点範囲に対して、カスタムフィードバックを定義します。",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "範囲",\n          "field": {\n            "fields": [\n              {\n                "label": "得点範囲"\n              },\n              {},\n              {\n                "label": "定義した得点範囲に対するフィードバック",\n                "placeholder": "フィードバックを記入"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "サマリータスクで解かれた文数の前に表示されるテキスト。",\n      "default": "進行状況:",\n      "description": "文の上に表示されます。例: ''進行状況: 2/5''"\n    },\n    {\n      "label": "サマリータスクで選ばれた、まちがえた文数の前に表示されるテキスト。",\n      "default": "まちがえた答え:",\n      "description": "文の上に表示されます。例: ''まちがえた解答: 4''"\n    },\n    {\n      "label": "サマリーフィードバックの見出し",\n      "default": "あなたの結果",\n      "description": "サマリーフィードバックの上に表示されます。"\n    },\n    {\n      "label": "正解のためのリードスピーカー用テキスト",\n      "default": "正解です。"\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "正解のラベルリスト",\n      "default": "正解です。"\n    },\n    {\n      "label": "Label for the show tip button",\n      "default": "Show tip"\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Text used for readspeakers to communicate progress",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "Progress :num of :total"\n    }\n  ]\n}'),
(34, 'ka', '{\n  "semantics": [\n    {\n      "label": "შესავალი ტექსტი",\n      "default": "აირჩიეთ სწორი განცხადება.",\n      "description": "ნაჩვენები იქნება შემაჯამებელი დავალების ზემოთ."\n    },\n    {\n      "widgets": [\n        {\n          "label": "სტანდარტული"\n        },\n        {\n          "label": "ტექსტური"\n        }\n      ],\n      "label": "შეჯამება",\n      "entity": "განცხადებები",\n      "field": {\n        "label": "განცხადებების ნაკრები",\n        "fields": [\n          {\n            "label": "განცხადებების სია შეჯამებისთვის - პირველი დებულება სწორია.",\n            "entity": "განცხადება",\n            "field": {\n              "label": "განცხადება"\n            }\n          },\n          {\n            "label": "მინიშნება",\n            "fields": [\n              {\n                "label": "მინიშნების ტექსტი"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "საერთო გამოხმაურება",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "სტანდარტული"\n            }\n          ],\n          "label": "განსაზღვრე უკუკავშირი ქულების ნებისმიერი დიაპაზონისთვის",\n          "description": "დააჭირეთ \\"დიაპაზონის დამატება\\" ღილაკს რომ დაამატოთ იმდენი დიაპაზონი, რამდენიც გსურთ. მაგალითად: 0-20% ცუდი შედეგი, 21-91% საშუალო შედეგი, 91-100% კარგი შედეგი!",\n          "entity": "დიაპაზონი",\n          "field": {\n            "fields": [\n              {\n                "label": "ქოლების დიაპაზონი"\n              },\n              {},\n              {\n                "label": "უკუკავშირი განსაზღვრული შეფასების დიაპაზონისთვის",\n                "placeholder": "უკუკავშირის შევსება"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "ტექსტი ნაჩვენებია შემაჯამებელ ამოცანაში ამოხსნილი დებულებების რაოდენობამდე.",\n      "default": "პროგრესი:",\n      "description": "ნაჩვენები იქნება განცხადებების ზემოთ. მაგალითი: ''პროგრესი: 2/5''"\n    },\n    {\n      "label": "ტექსტი ნაჩვენებია შემაჯამებელ ამოცანაში შერჩეული არასწორი განცხადებების რაოდენობამდე.",\n      "default": "არასწორი პასუხები:",\n      "description": "ნაჩვენები იქნება განცხადებების ზემოთ. მაგალითი: „არასწორი პასუხები: 4“"\n    },\n    {\n      "label": "შემაჯამებელი გამოხმაურების სათაური",\n      "default": "შენი შედეგი",\n      "description": "ნაჩვენები იქნება შემაჯამებელი გამოხმაურების ზემოთ."\n    },\n    {\n      "label": "ტექსტის გამხმოვანებლის ტექსტი სწორი პასუხისთვის",\n      "default": "სწორია."\n    },\n    {\n      "label": "ტექსტის გამხმოვანებლის ტექსტი არასწორი პასუხისთვის",\n      "default": "არასწორია! გთხოვთ კიდევ სცადეთ."\n    },\n    {\n      "label": "ტექსტის გამხმოვანებლის ტექსტი არასწორი პასუხისთვის",\n      "default": "შეცდომა"\n    },\n    {\n      "label": "წარწერა სწორი პასუხისთვის",\n      "default": "სწორი პასუხები."\n    },\n    {\n      "label": "წარწერა ღილაკისთვის რჩევის ჩვენება",\n      "default": "მინიშნების ჩვენება"\n    },\n    {\n      "label": "ტექსტის გამომხმოვანებლის მომხმარებლებისთვის ქულების კოლონის ტექსტური რეპრეზენტაცია",\n      "description": ":num და :total არის სპეციალური საკვანძო სიტყვები, რომლებიც განახლდება პროგრამულად",\n      "default": "შენ მიიღე :num :total ქულიდან"\n    },\n    {\n      "label": "ტექსტი, რომელიც გამოიყენება ტექსტის გამხმოვანებლისთვის პროგრესის კომუნიკაციისთვის",\n      "description": ":num და :total არის სპეციალური საკვანძო სიტყვები, რომლებიც განახლდება პროგრამულად",\n      "default": "პროგრესი :num :total -დან"\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(34, 'km', '{\n  "semantics": [\n    {\n      "label": "Introduction text",\n      "default": "Choose the correct statement.",\n      "description": "Will be displayed above the summary task."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Default"\n        },\n        {\n          "label": "Textual"\n        }\n      ],\n      "label": "Summary",\n      "entity": "statements",\n      "field": {\n        "label": "Set of statements",\n        "fields": [\n          {\n            "label": "List of statements for the summary - the first statement is correct.",\n            "entity": "statement",\n            "field": {\n              "label": "Statement"\n            }\n          },\n          {\n            "label": "Tip",\n            "fields": [\n              {\n                "label": "Tip text"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Default"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text displayed before number of statements solved in the summary task.",\n      "default": "វឌ្ឍនភាព:",\n      "description": "Will be displayed above the statements. Example: ''Progress: 2/5''"\n    },\n    {\n      "label": "Text displayed before number of wrong statements selected in the summary task.",\n      "default": "ចម្លើយមិនត្រឹមត្រូវ:",\n      "description": "Will be displayed above the statements. Example: ''Wrong answers: 4''"\n    },\n    {\n      "label": "Summary feedback header",\n      "default": "លទ្ធផលរបស់អ្នក",\n      "description": "Will be displayed above the summary feedback."\n    },\n    {\n      "label": "Readspeaker text for correct answer",\n      "default": "ត្រឹមត្រូវ"\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "មិនត្រឹមត្រូវ! សូមសាកម្តងទៀត។"\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "មិនត្រឹមត្រូវ"\n    },\n    {\n      "label": "Label list of correct answers",\n      "default": "ចម្លើយត្រឹមត្រូវ"\n    },\n    {\n      "label": "Label for the show tip button",\n      "default": "បង្ហាញគន្លឹះ"\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "អ្នកទទួលបានពិន្ទុ :num លើ :total"\n    },\n    {\n      "label": "Text used for readspeakers to communicate progress",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "វឌ្ឍនភាព៖ :num ចំណោម :total"\n    }\n  ]\n}\n'),
(34, 'ko', '{\n  "semantics": [\n    {\n      "label": "소개 텍스트",\n      "default": "올바른 문장을 고르세요.",\n      "description": "요약 과업(task) 위에 표시됨."\n    },\n    {\n      "widgets": [\n        {\n          "label": "기본형식"\n        },\n        {\n          "label": "텍스트형식"\n        }\n      ],\n      "label": "요약",\n      "entity": "문장",\n      "field": {\n        "label": "문장 세트",\n        "fields": [\n          {\n            "label": "요약에 대한 문장 목록 - 첫 번째 문장이 정답입니다.",\n            "entity": "문장",\n            "field": {\n              "label": "문장"\n            }\n          },\n          {\n            "label": "팁",\n            "fields": [\n              {\n                "label": "팁 문장"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "전반적인 피드백",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "기본"\n            }\n          ],\n          "label": "모든 점수 범위에 대한 사용자 지정 피드백 정의",\n          "description": "\\"Add range\\"버튼(범위 추가 버튼) 을 클릭해서 필요한 만큼의 범위를 추가하십시오. 예: 0-20% 낮은 점수, 21-91% 평균 점수, 91-100% 좋은 점수!",\n          "entity": "범위",\n          "field": {\n            "fields": [\n              {\n                "label": "점수 범위"\n              },\n              {},\n              {\n                "label": "정의된 점수 범위에 대한 피드백",\n                "placeholder": "피드백을 작성"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "요약 작업에서 해결된 문장 숫자 앞에 표시되는 텍스트.",\n      "default": "학습진행:",\n      "description": "문장 위에 표시됩니다. 예: ''학습진행: 2/5''"\n    },\n    {\n      "label": "요약 작업에서 틀린 답 숫자 앞에 표시되는 텍스트.",\n      "default": "틀린 답변:",\n      "description": "문장 위에 표시됩니다. 예: ''틀린 답변: 4''"\n    },\n    {\n      "label": "요약 피드백 헤더",\n      "default": "결과",\n      "description": "요약 피드백 위에 표시됩니다."\n    },\n    {\n      "label": "올바른 답에 대해 자동 문장 말하기로 피드백",\n      "default": "정답입니다."\n    },\n    {\n      "label": "틀린 답에 대해 자동 문장 말하기로 피드백",\n      "default": "틀린 답입니다! 다시 해 보세요"\n    },\n    {\n      "label": "틀린 답에 대해 자동 문장 말하기 레이블",\n      "default": "틀린 답입니다."\n    },\n    {\n      "label": "정답에 대한 레이블",\n      "default": "정답입니다."\n    },\n    {\n      "label": "팁 표시 단추의 레이블",\n      "default": "팁 보여주기"\n    },\n    {\n      "label": "자동 문장 읽어주기를 사용하는 사용자의 점수 표시줄 텍스트 표시",\n      "description": ":num 및 :total은 프로그래밍 방식으로 업데이트되는 특수 키워드 입니다.",\n      "default": "총점수 :total points 에서 :num 점을 획득하였습니다."\n    },\n    {\n      "label": "진행 상황을 전달하기 위해 자동 문장 읽어주기에 사용되는 텍스트",\n      "description": ":num 및 :total은 프로그래밍 방식으로 업데이트되는 특수 키워드 입니다.",\n      "default": "학습진행 총점 :total 에서 현재 점수 :num"\n    }\n  ]\n}\n'),
(34, 'lt', '{\n  "semantics": [\n    {\n      "label": "Įvadinis tekstas",\n      "default": "Pasirinkite teisingą teiginį.",\n      "description": "Bus rodomas virš užduoties turinio."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Numatytasis"\n        },\n        {\n          "label": "Tekstinis"\n        }\n      ],\n      "label": "Santrauka",\n      "entity": "teiginiai",\n      "field": {\n        "label": "Teiginių rinkinys",\n        "fields": [\n          {\n            "label": "Santraukos teiginių sąrašas - pirmasis teiginys yra teisingas.",\n            "entity": "teiginys",\n            "field": {\n              "label": "Teiginys"\n            }\n          },\n          {\n            "label": "Patarimas",\n            "fields": [\n              {\n                "label": "Patarimo tekstas"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Bendrieji atsiliepimai",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Numatytasis"\n            }\n          ],\n          "label": "Apibrėžti pasirinktinį atsiliepimą bet kokiam balų intervalui",\n          "description": "Spustelėkite mygtuką \\"Pridėti intervalus\\", kad pridėtumėte tiek intervalų, kiek reikia. Pavyzdys: 0-20% blogas rezultatas, 21-91% vidutinis rezultatas, 91-100% puikus rezultatas!",\n          "entity": "intervalas",\n          "field": {\n            "fields": [\n              {\n                "label": "Balų intervalas"\n              },\n              {},\n              {\n                "label": "Atsiliepimai apibrėžtam balų diapazonui",\n                "placeholder": "Užpildykite atsiliepimą"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Tekstas, rodomas prieš santraukos uždavinio išspręstų teiginių skaičių.",\n      "default": "Progresas:",\n      "description": "Bus rodomas virš teiginių. Pavyzdys: \\"Progresas: 2/5\\""\n    },\n    {\n      "label": "Tekstas, rodomas prieš santraukos užduotyje pasirinktų klaidingų teiginių skaičių.",\n      "default": "Neteisingi atsakymai:",\n      "description": "Bus rodomas virš teiginių. Pavyzdys: \\"Neteisingi atsakymai: 4\\""\n    },\n    {\n      "label": "Santraukos atsiliepimų antraštė",\n      "default": "Jūsų rezultatas",\n      "description": "Bus rodoma virš santraukos atsiliepimų."\n    },\n    {\n      "label": "Skaitomas teisingo atsakymo tekstas",\n      "default": "Teisingai."\n    },\n    {\n      "label": "Skaitomas tekstas neteisingam atsakymui paskelbti",\n      "default": "Neteisingai! Bandykite dar kartą."\n    },\n    {\n      "label": "Skaitomas neteisingo atsakymo tekstas",\n      "default": "Neteisingai"\n    },\n    {\n      "label": "Teisingų atsakymų sąrašo etiketė",\n      "default": "Teisingi atsakymai."\n    },\n    {\n      "label": "Mygtuko \\"Rodyti patarimus\\" etiketė",\n      "default": "Rodyti patarimus"\n    },\n    {\n      "label": "Tekstinis rezultatų juostos atvaizdavimas tiems, kurie naudojasi skaitytuvu",\n      "description": ":num ir :total yra specialūs raktažodžiai, kurie atnaujinami programiškai",\n      "default": "Jūs surinkote :num iš :total taškų"\n    },\n    {\n      "label": "Tekstas pranešantis apie pažangą tiems, kurie naudojasi skaitytuvu",\n      "description": ":num ir :total yra specialūs raktažodžiai, kurie atnaujinami programiškai",\n      "default": "Progresas :num of :total"\n    }\n  ]\n}\n'),
(34, 'lv', '{\n  "semantics": [\n    {\n      "label": "Ievada teksts",\n      "default": "Izvēlieties pareizo apgalvojumu.",\n      "description": "Tiks parādīts virs kopsavilkuma uzdevuma."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Pēc noklusējuma"\n        },\n        {\n          "label": "Teksta"\n        }\n      ],\n      "label": "Kopsavilkums",\n      "entity": "apgalvojumi",\n      "field": {\n        "fields": [\n          {\n            "label": "Apgalvojumu saraksts kopsavilkumam – pirmais apgalvojums ir pareizs.",\n            "entity": "apgalvojums",\n            "field": {\n              "label": "Apgalvojums"\n            }\n          },\n          {\n            "label": "Padoms",\n            "fields": [\n              {\n                "label": "Padoma teksts"\n              }\n            ]\n          }\n        ],\n        "label": "Apgalvojumu kopa"\n      }\n    },\n    {\n      "label": "Kopējā atgriezeniskā saite",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Pēc noklusējuma"\n            }\n          ],\n          "label": "Iestatiet pielāgotu atgriezenisko saiti katram rezultātu diapazonam",\n          "entity": "diapazons",\n          "field": {\n            "fields": [\n              {\n                "label": "Rezultātu diapazons"\n              },\n              {},\n              {\n                "label": "Atgriezeniskā saite noteiktajam rezultātu diapazonam",\n                "placeholder": "Aizpildiet atgriezenisko saiti"\n              }\n            ]\n          },\n          "description": "Klikšķiniet pogu \\"Pievienot diapazonu\\", lai pievienotu tik diapazonus cik vēlaties. Piemēram, 0-20% Slikts rezultāts, 21-91% Viduvējs rezultāts, 91-100% Lielisks rezultāts!"\n        }\n      ]\n    },\n    {\n      "label": "Teksts tiks parādīts pirms kopsavilkuma uzdevumā atrisināto apgalvojumu skaita.",\n      "default": "Progress:",\n      "description": "Tiks parādīts virs apgalvojumiem. Piemērs: ''Progress: 2/5''"\n    },\n    {\n      "default": "Nepareizas atbildes:",\n      "description": "Tiks parādīts virs apgalvojumiem. Piemērs: ''Nepareizas atbildes: 4''",\n      "label": "Teksts tiks parādīts pirms kopsavilkuma uzdevumā neatrisināto apgalvojumu skaita."\n    },\n    {\n      "label": "Kopsavilkuma atgriezeniskās saites galvene",\n      "default": "Tavs rezultāts",\n      "description": "Tiks parādīts virs kopsavilkuma atgriezeniskās saites."\n    },\n    {\n      "default": "Pareizi.",\n      "label": "Pareizās atbildes atskaņošanas teksts asistīvajām tehnoloģijām"\n    },\n    {\n      "label": "Nepareizās atbildes atskaņošanas teksts asistīvajām tehnoloģijām",\n      "default": "Nepareizi! Lūdzu mēģiniet vēlreiz."\n    },\n    {\n      "default": "Nepareizi",\n      "label": "Nepareizās atbildes etiķete asistīvajām tehnoloģijām"\n    },\n    {\n      "label": "Pareizo atbilžu saraksta etiķete",\n      "default": "Pareizās atbildes."\n    },\n    {\n      "label": "Pogas \\"Parādīt padomu\\" birka",\n      "default": "Parādīt padomu"\n    },\n    {\n      "description": ":num un :total ir īpaši atslēgvārdi, kas tiek programmatiski atjaunināti",\n      "default": "Tu saņēmi :num no :total punktiem",\n      "label": "Rezultātu skalas tekstuālais atspoguļojums tiem, kas izmanto asistīvās tehnoloģijas"\n    },\n    {\n      "label": "Teksts, ko izmanto asistīvās tehnoloģijas, lai paziņotu par progresu",\n      "default": "Progress :num no :total",\n      "description": ":num un :total ir īpaši atslēgvārdi, kas tiek programmatiski atjaunināti"\n    }\n  ]\n}\n'),
(34, 'mn', '{\n  "semantics": [\n    {\n      "default": "Зөв мэдэгдлийг сонгоно уу.",\n      "label": "Танилцуулга текст",\n      "description": "Хураангуй даалгавар дээр гарч ирнэ."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Өгөгдмөл"\n        },\n        {\n          "label": "Текст"\n        }\n      ],\n      "label": "Дүгнэлт",\n      "field": {\n        "label": "Мэдэгдэлийн багц",\n        "fields": [\n          {\n            "entity": "мэдэгдэл",\n            "label": "Дүгнэлтэд зориулсан мэдэгдлийн жагсаалт - эхний мэдэгдэл зөв байна.",\n            "field": {\n              "label": "Мэдэгдэл"\n            }\n          },\n          {\n            "label": "Зөвлөгөө",\n            "fields": [\n              {\n                "label": "Зөвлөгөө текст"\n              }\n            ]\n          }\n        ]\n      },\n      "entity": "мэдэгдэл"\n    },\n    {\n      "label": "Ерөнхий санал хүсэлт",\n      "fields": [\n        {\n          "label": "Аль ч онооны хүрээнд захиалгат санал хүсэлтийг тодорхойлох",\n          "entity": "хүрээ",\n          "field": {\n            "fields": [\n              {\n                "label": "Онооны хүрээ"\n              },\n              {},\n              {\n                "label": "Тодорхойлогдсон онооны хүрээний санал хүсэлт",\n                "placeholder": "Санал хүсэлтийг бөглөнө үү"\n              }\n            ]\n          },\n          "widgets": [\n            {\n              "label": "Өгөгдмөл"\n            }\n          ],\n          "description": "\\"Хүрээ нэмэх\\" товчийг дарж шаардлагатай бол олон муж нэмнэ. Жишээ нь: 0-20% муу оноо, 21-91% дундаж оноо, 91-100% сайн оноо!"\n        }\n      ]\n    },\n    {\n      "label": "Хураангуй даалгаварт шийдэгдсэн мэдэгдлийн тооноос өмнө харуулсан текст.",\n      "description": "Мэдэгдэлийн дээр харагдах болно. Жишээ: ''Явц: 2/5''",\n      "default": "Явц:"\n    },\n    {\n      "default": "Буруу хариултууд:",\n      "label": "Хураангуй даалгаварт сонгогдсон буруу мэдэгдлүүдийн тооноос өмнө харуулсан текст.",\n      "description": "Мэдэгдэлийн дээр харагдах болно. Жишээ: ''Буруу хариулт: 4''"\n    },\n    {\n      "label": "Хураангуй санал хүсэлтийн толгой хэсэг",\n      "description": "Хураангуй санал хүсэлтийн дээр харагдах болно.",\n      "default": "Таны үр дүн"\n    },\n    {\n      "default": "Зөв.",\n      "label": "Зөв хариултын талаар унших чанга яригчийн текст"\n    },\n    {\n      "default": "Буруу! Дахин оролдоно уу.",\n      "label": "Буруу хариултыг зарлах унших чанга яригчийн текст"\n    },\n    {\n      "default": "Буруу",\n      "label": "Буруу хариулт унших чанга яригчийн шошго"\n    },\n    {\n      "default": "Зөв хариулт.",\n      "label": "Зөв хариултуудын шошгын жагсаалт"\n    },\n    {\n      "default": "Зөвлөмжийг харуулах",\n      "label": "Зөвлөгөө үзүүлэх товчны шошго"\n    },\n    {\n      "description": ":num ба :total нь программын дагуу шинэчлэгдсэн тусгай түлхүүр үгс юм",\n      "label": "Унших чанга яригч ашигладаг хүмүүст зориулсан онооны самбарын текстэн дүрслэл",\n      "default": "Та нийт :total онооноос :num авсан"\n    },\n    {\n      "label": "Уншигчдад ахиц дэвшил гаргахад ашигладаг текст",\n      "default": "Явц :num / :нийт",\n      "description": ":num ба :total нь программын дагуу шинэчлэгдсэн тусгай түлхүүр үгс юм"\n    }\n  ]\n}\n'),
(34, 'nb', '{\n  "semantics": [\n    {\n      "label": "Introduksjonstekst",\n      "default": "Velg riktig påstand.",\n      "description": "Vil vises øverst i oppsummeringsoppgaven."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Standard"\n        },\n        {\n          "label": "Tekstlig"\n        }\n      ],\n      "label": "Oppsummering",\n      "entity": "påstander",\n      "field": {\n        "label": "Påstander",\n        "fields": [\n          {\n            "label": "Påstander til oppsummeringen - første påstand er riktig.",\n            "entity": "påstand",\n            "field": {\n              "label": "Påstand"\n            }\n          },\n          {\n            "label": "Tips",\n            "fields": [\n              {\n                "label": "Tipstekst"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Samlet tilbakemelding",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Standard"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Tekst som vises før antall påstander som er løst i oppsummeringen.",\n      "default": "Løst:",\n      "description": "Vil vises over påstandene. Eksempel: ''Løst: 2/5''"\n    },\n    {\n      "label": "Tekst som vises før antall feil påstander som er valgt i oppsummeringen.",\n      "default": "Antall feil:",\n      "description": "Vil vises over påstandene. Eksempel: ''Antall feil: 4''"\n    },\n    {\n      "label": "Overskrift over tilbakemelding",\n      "default": "Ditt resultat:",\n      "description": "Vil vises over tilbakemelding på oppsummeringen."\n    },\n    {\n      "label": "Merkelapp for riktig svar",\n      "default": "Rett."\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "Label list of correct answers",\n      "default": "Rett svar"\n    },\n    {\n      "label": "Label for the show tip button",\n      "default": "Vis tips"\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "Du fikk :num av :total points"\n    },\n    {\n      "label": "Text used for readspeakers to communicate progress",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "Progress :num of :total"\n    }\n  ]\n}'),
(34, 'nl', '{\n  "semantics": [\n    {\n      "label": "Inleidende tekst",\n      "default": "Kies de juiste bewering.",\n      "description": "Wordt boven de samenvattingstaak getoond."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Standaard"\n        },\n        {\n          "label": "Tekstueel"\n        }\n      ],\n      "label": "Samenvatting",\n      "entity": "beweringen",\n      "field": {\n        "label": "Reeks van beweringen",\n        "fields": [\n          {\n            "label": "Een lijst van beweringen voor de samenvatting - de eerste bewering is juist.",\n            "entity": "bewering",\n            "field": {\n              "label": "Bewering"\n            }\n          },\n          {\n            "label": "Tip",\n            "fields": [\n              {\n                "label": "Tekst voor tip"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Algehele feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Standaard"\n            }\n          ],\n          "label": "Definieer aangepaste feedback voor elke scorereeks",\n          "description": "Druk op de \\"Voeg scorereeks\\"-knop om zoveel reeksen toe te voegen als nodig. Voorbeeld: 0-20% Onvoldoende, 21-91% Gemiddelde score, 91-100% Uitstekende score!",\n          "entity": "reeks",\n          "field": {\n            "fields": [\n              {\n                "label": "Scorereeks"\n              },\n              {},\n              {\n                "label": "Feedback voor de gedefinieerde scorereeks",\n                "placeholder": "Vul de feedback in"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "De getoonde tekst vóór het aantal opgeloste beweringen van de samenvattingstaak.",\n      "default": "Voortgang:",\n      "description": "Wordt getoond boven de beweringen. Voorbeeld: ''Voortgang: 2/5''"\n    },\n    {\n      "label": "Tekst getoond vóór het aantal onjuiste beweringen van de samenvattingstaak.",\n      "default": "Onjuiste antwoorden:",\n      "description": "Wordt getoond boven de beweringen. Voorbeeld: ''Onjuiste antwoorden: 4''"\n    },\n    {\n      "label": "Koptekst feedback van de samenvatting",\n      "default": "Je resultaat",\n      "description": "Wordt getoond boven de feedback van de samenvatting."\n    },\n    {\n      "label": "Schermlezer tekst voor het juiste antwoord",\n      "default": "Juist."\n    },\n    {\n      "label": "Schermlezer tekst voor informeren over onjuist antwoord",\n      "default": "Onjuist! Probeer het opnieuw."\n    },\n    {\n      "label": "Schermlezer label voor onjuist antwoord",\n      "default": "Onjuist"\n    },\n    {\n      "label": "Label van lijst met juiste antwoorden",\n      "default": "Juiste antwoorden."\n    },\n    {\n      "label": "Label voor \\"Toon tip\\"-knop",\n      "default": "Toon tip"\n    },\n    {\n      "label": "Tekstuele weergave van de scorebalk voor de gebruikers van de schermlezer",\n      "description": ":num en :total zijn speciale trefwoorden die worden bijgewerkt met de echte waarden",\n      "default": "Je hebt :num van de :total punten"\n    },\n    {\n      "label": "De tekst die gebruikt wordt door schermlezers om de voortgang te communiceren",\n      "description": ":num en :total zijn speciale trefwoorden die worden bijgewerkt met de echte waarden",\n      "default": "Voortgang :num van :total"\n    }\n  ]\n}\n'),
