(34, 'pt', '{\n  "semantics": [\n    {\n      "label": "Texto introdutório",\n      "default": "Escolha a afirmação correta.",\n      "description": "Será mostrado acima da tarefa de revisão."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Padrão"\n        },\n        {\n          "label": "Textual"\n        }\n      ],\n      "label": "Resumo",\n      "entity": "afirmações",\n      "field": {\n        "label": "Conjunto de afirmações",\n        "fields": [\n          {\n            "label": "Lista de afirmações para o resumo - a primeira afirmação é a correta.",\n            "entity": "afirmação",\n            "field": {\n              "label": "Afirmação"\n            }\n          },\n          {\n            "label": "Dica",\n            "fields": [\n              {\n                "label": "Texto da dica"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Feedback global",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Padrão"\n            }\n          ],\n          "label": "Defina o feedback personalizado para qualquer faixa de pontuação",\n          "description": "Clique em \\"Adicionar faixa\\" e adicione quantas faixas forem necessárias. Exemplo: 0-20% Insuficiente, 21-91% Suficiente, 91-100% Excelente!",\n          "entity": "faixa",\n          "field": {\n            "fields": [\n              {\n                "label": "Faixa de pontuação"\n              },\n              {},\n              {\n                "label": "Feedback para uma determinada faixa de pontuação",\n                "placeholder": "Preencha o feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texto mostrado antes do número de afirmações resolvidas na atividade de resumo.",\n      "default": "Progresso:",\n      "description": "Será mostrado acima das afirmações. Exemplo: ''Progresso: 2/5''"\n    },\n    {\n      "label": "Texto mostrado antes do número de afirmações erradas selecionadas na atividade de resumo.",\n      "default": "Respostas erradas:",\n      "description": "Será mostrado acima das afirmações. Exemplo: ''Respostas erradas: 4''"\n    },\n    {\n      "label": "Cabeçalho do feedback do resumo",\n      "default": "O seu resultado",\n      "description": "Será mostrado acima do cabeçalho do feedback do resumo."\n    },\n    {\n      "label": "Texto para o leitor de ecrã para resposta correta",\n      "default": "Correto."\n    },\n    {\n      "label": "Texto do leitor de ecrã para anunciar resposta incorreta",\n      "default": "Incorreto! Por favor, tente novamente."\n    },\n    {\n      "label": "Texto do leitor de ecrã para resposta incorreta",\n      "default": "Incorreto"\n    },\n    {\n      "label": "Rótulo da lista de respostas corretas",\n      "default": "Respostas corretas."\n    },\n    {\n      "label": "Rótulo do botão de mostrar dica",\n      "default": "Mostrar dica"\n    },\n    {\n      "label": "Representação textual da barra de pontuação para aqueles que usam leitores de ecrã",\n      "description": ":num e :total são palavras-chave especiais que são atualizadas automaticamente",\n      "default": "Obteve :num de :total pontos"\n    },\n    {\n      "label": "Texto usado por leitores de ecrã para informar progresso",\n      "description": ":num e :total são palavras-chave especiais que são atualizadas automaticamente",\n      "default": "Progresso :num de :total"\n    }\n  ]\n}\n'),
(34, 'pt-br', '{\n  "semantics": [\n    {\n      "label": "Texto de introdução",\n      "default": "Escolha a afirmativa correta.",\n      "description": "Será exibido acima da tarefa de resumo."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Padrão"\n        },\n        {\n          "label": "Texto"\n        }\n      ],\n      "label": "Resumo",\n      "entity": "afirmações",\n      "field": {\n        "label": "Conjunto de afirmativas",\n        "fields": [\n          {\n            "label": "Lista de afirmativas para o resumo - a primeira afirmativa é a correta.",\n            "entity": "afirmativa",\n            "field": {\n              "label": "Afirmativa"\n            }\n          },\n          {\n            "label": "Dica",\n            "fields": [\n              {\n                "label": "Texto da dica"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Feedback Geral",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Padrão"\n            }\n          ],\n          "label": "Defina feedback personalizado para qualquer intervalo de pontuação",\n          "description": "Clique no botão \\"Adicionar faixa\\" para adicionar quantos intervalos você precisar. Exemplo: 0-20% Pontuação Ruim, 21-91% Pontuação Média, 91-100% Pontuação Ótima!",\n          "entity": "faixa",\n          "field": {\n            "fields": [\n              {\n                "label": "Faixa de Pontuação"\n              },\n              {},\n              {\n                "label": "Feedback para a faixa de pontuação definida",\n                "placeholder": "Preencha o feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Texto exibido antes do número de afirmativas resolvidas na tarefa de resumo.",\n      "default": "Progresso:",\n      "description": "Será exibido acima das afirmativas. Exemplo: ''Progresso: 2/5''"\n    },\n    {\n      "label": "Texto exibido antes do número de afirmativas incorretas selecionadas na tarefa de resumo.",\n      "default": "Respostas incorretas:",\n      "description": "Será exibido acima das afirmativas. Exemplo: ''Respostas incorretas: 4''"\n    },\n    {\n      "label": "Cabeçalho do feedback do resumo",\n      "default": "Seu resultado",\n      "description": "Será exibido acima do feedback do resumo."\n    },\n    {\n      "label": "Texto de resposta correta para o leitor de tela",\n      "default": "Correto."\n    },\n    {\n      "label": "Texto do leitor de tela para anunciar resposta incorreta",\n      "default": "Incorreto! Por favor, tente novamente."\n    },\n    {\n      "label": "Texto do leitor de tela para resposta incorreta",\n      "default": "Incorreto"\n    },\n    {\n      "label": "Rótulo da lista de respostas corretas",\n      "default": "Respostas corretas."\n    },\n    {\n      "label": "Rótulo do botão mostrar dica",\n      "default": "Mostrar dica"\n    },\n    {\n      "label": "Representação textual da barra de pontuação para aqueles que usam leitores de tela",\n      "description": ":num e :total são palavras-chave especiais que são atualizadas automaticamente",\n      "default": "Você conseguiu :num de :total pontos possíveis"\n    },\n    {\n      "label": "Texto usado por leitores de tela para informar progresso",\n      "description": ":num e :total são palavras-chave especiais que são atualizadas automaticamente",\n      "default": "Progresso :num de :total"\n    }\n  ]\n}\n'),
(34, 'ru', '{\n  "semantics": [\n    {\n      "label": "Вводный текст",\n      "default": "Выбери верное утверждение.",\n      "description": "Будет отображено над заданием конспекта."\n    },\n    {\n      "widgets": [\n        {\n          "label": "По умолчанию"\n        },\n        {\n          "label": "Текстовой"\n        }\n      ],\n      "label": "Конспект",\n      "entity": "утверждения",\n      "field": {\n        "label": "Определение утверждений",\n        "fields": [\n          {\n            "label": "Список утверждений для конспекта - первое утверждение верное.",\n            "entity": "утверждение",\n            "field": {\n              "label": "утверждение"\n            }\n          },\n          {\n            "label": "Подсказка",\n            "fields": [\n              {\n                "label": "Текст подсказки"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Общая обратная связь",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "По умолчанию"\n            }\n          ],\n          "label": "Определите обычную обратную связь для любого результата",\n          "description": "Нажмите кнопку \\"Добавить диапазон\\" для добавления необходимого количества диапазонов. Пример: 0-20% Низкий результат, 21-91% Средний результат, 91-100% Отличный результат!",\n          "entity": "диапазон",\n          "field": {\n            "fields": [\n              {\n                "label": "Диапазон баллов"\n              },\n              {},\n              {\n                "label": "Обратная связь для определённого промежутка баллов",\n                "placeholder": "Заполните обратную связь"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Текст, отображающийся до утверждения в задании конспекта.",\n      "default": "Прогресс:",\n      "description": "Будет отображаться над утверждениями. Пример: ''Прогресс: 2/5''"\n    },\n    {\n      "label": "Текст, отображающийся перед количеством неправильных утверждений в задании конспекта.",\n      "default": "Неверные ответы:",\n      "description": "Будет отображаться над утверждениями. Пример: ''Неверных ответов: 4''"\n    },\n    {\n      "label": "Заголовок обратной связи конспекта",\n      "default": "Твой результат",\n      "description": "Будет отображаться над обратной связью."\n    },\n    {\n      "label": "Текст ассистирующих технологии для верных ответов",\n      "default": "Верно."\n    },\n    {\n      "label": "Текст ассистирующих технологии для неверных ответов",\n      "default": "Неверно! Пожалуйста, попробуй снова."\n    },\n    {\n      "label": "Заголовок ассистирующих технологии для неверного ответа",\n      "default": "Неверно"\n    },\n    {\n      "label": "Название списка верных ответов",\n      "default": "Верные ответы."\n    },\n    {\n      "label": "Название кнопки для подсказки",\n      "default": "Показать подсказку"\n    },\n    {\n      "label": "Текстовой формат представления результатов для использующих ассистирующии технологии",\n      "description": ":num и :total выделенные ключевые слова, обновлённые программой",\n      "default": "У тебя :num из :total баллов"\n    },\n    {\n      "label": "Текст для использования ассистирующих технологии для отображения прогресса",\n      "description": ":num и :total выделенные ключевые слова, обновлённые программой",\n      "default": "Прогресс :num из :total"\n    }\n  ]\n}\n'),
(34, 'sl', '{\n  "semantics": [\n    {\n      "label": "Uvodni tekst",\n      "default": "Izberite pravilno izjavo.",\n      "description": "Prikazan bo nad nalogo povzetka."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Privzeto"\n        },\n        {\n          "label": "Tekstoven"\n        }\n      ],\n      "label": "Povzetek",\n      "entity": "izjave",\n      "field": {\n        "label": "Niz izjav",\n        "fields": [\n          {\n            "label": "Seznam izjav za povzetek - prva izjava je pravilna.",\n            "entity": "izjava",\n            "field": {\n              "label": "Izjava"\n            }\n          },\n          {\n            "label": "Namig",\n            "fields": [\n              {\n                "label": "Besedilo namiga"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Splošna povratna informacija",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Privzeto"\n            }\n          ],\n          "label": "Določi ločeno povratno informacijo za vsak razpon rezultatov",\n          "description": "Kliknite gumb \\"Dodaj razpon\\" za dodajanje dodatnih razponov. Primer: 0-20 % Slab rezultat, 21-91 % Povprečen rezultat, 91-100 % Odličen rezultat!",\n          "entity": "razpon",\n          "field": {\n            "fields": [\n              {\n                "label": "Razpon rezultatov"\n              },\n              {},\n              {\n                "label": "Povratna informacija za definiran razpon rezultatov",\n                "placeholder": "Vnesite povratno informacijo"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Besedilo, ki se prikaže pred številom rešenih izjav v nalogi povzetka.",\n      "default": "Napredek:",\n      "description": "Prikazano bo nad izjavami. Primer: ''Napredek: 2/5''"\n    },\n    {\n      "label": "Besedilo, ki se prikaže pred številom napačnih izjav v nalogi povzetka.",\n      "default": "Napačni odgovori:",\n      "description": "Prikazano bo nad izjavami. Primer: ''Napačni odgovori: 4''"\n    },\n    {\n      "label": "Glava povzetka povratnih informacij",\n      "default": "Rezultat",\n      "description": "Prikazano bo nad povzetkom povratnih informacij."\n    },\n    {\n      "label": "Besedilo za pravilen odgovor za bralnik zaslona",\n      "default": "Pravilno."\n    },\n    {\n      "label": "Besedilo za nepravilen odgovor za bralnik zaslona",\n      "default": "Nepravilno! Poskusi znova."\n    },\n    {\n      "label": "Besedilo za nepravilen odgovor",\n      "default": "Nepravilno"\n    },\n    {\n      "label": "Oznaka seznama pravilnih odgovorov",\n      "default": "Pravilni odgovori."\n    },\n    {\n      "label": "Oznaka gumba za prikaz namiga",\n      "default": "Pokaži namig"\n    },\n    {\n      "label": "Tekstovni prikaz vrstice z rezultati za uporabnike, ki uporabljajo bralnik zaslona",\n      "description": ":num in :total sta spremenljivki",\n      "default": "Dosežene točke: :num od :total"\n    },\n    {\n      "label": "Besedilo, ki ga bralnik zaslona uporabi za izražanje napredka",\n      "description": ":num in :total sta spremenljivki",\n      "default": "Napredek :num od :total"\n    }\n  ]\n}\n'),
(34, 'sma', '{\n  "semantics": [\n    {\n      "label": "Introduction text",\n      "default": "Choose the correct statement.",\n      "description": "Will be displayed above the summary task."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Default"\n        },\n        {\n          "label": "Textual"\n        }\n      ],\n      "label": "Summary",\n      "entity": "statements",\n      "field": {\n        "label": "Set of statements",\n        "fields": [\n          {\n            "label": "List of statements for the summary - the first statement is correct.",\n            "entity": "statement",\n            "field": {\n              "label": "Statement"\n            }\n          },\n          {\n            "label": "Tip",\n            "fields": [\n              {\n                "label": "Tip text"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Default"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text displayed before number of statements solved in the summary task.",\n      "default": "Progress:",\n      "description": "Will be displayed above the statements. Example: ''Progress: 2/5''"\n    },\n    {\n      "label": "Text displayed before number of wrong statements selected in the summary task.",\n      "default": "Wrong answers:",\n      "description": "Will be displayed above the statements. Example: ''Wrong answers: 4''"\n    },\n    {\n      "label": "Summary feedback header",\n      "default": "Your result",\n      "description": "Will be displayed above the summary feedback."\n    },\n    {\n      "label": "Readspeaker text for correct answer",\n      "default": "Correct."\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "Label list of correct answers",\n      "default": "Correct answers."\n    },\n    {\n      "label": "Label for the show tip button",\n      "default": "Show tip"\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Text used for readspeakers to communicate progress",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "Progress :num of :total"\n    }\n  ]\n}'),
