(34, 'sr', '{\n  "semantics": [\n    {\n      "label": "Уводни текст",\n      "default": "Изаберите тачну тврдњу.",\n      "description": "Биће приказано изнад резиме задатка."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Уобичајено"\n        },\n        {\n          "label": "Текстуални"\n        }\n      ],\n      "label": "Резиме",\n      "entity": "изјаве",\n      "field": {\n        "label": "Скуп изјава",\n        "fields": [\n          {\n            "label": "Листа изјава за резиме - прва изјава је тачна.",\n            "entity": "изјава",\n            "field": {\n              "label": "Изјава"\n            }\n          },\n          {\n            "label": "Савет",\n            "fields": [\n              {\n                "label": "Текст савета"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Укупне повратне информације",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Уобичајено"\n            }\n          ],\n          "label": "Дефинишите прилагођене повратне информације за било који опсег резултата",\n          "description": "Кликните на \\"Додај опсег\\" дугме за додавање онолико опсега колико вам је потребно. Пример: 0-20% Лош резултат, 21-91% Просечан резултат, 91-100% Одличан резултат!",\n          "entity": "опсег",\n          "field": {\n            "fields": [\n              {\n                "label": "Распон резултата"\n              },\n              {},\n              {\n                "label": "Повратне информације за дефинисани опсег резултата",\n                "placeholder": "Попуните повратне информације"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Текст приказан пре броја изјава решених у резимеу задатка.",\n      "default": "Напредак:",\n      "description": "Биће приказано изнад изјава. Пример: ''Напредак: 2/5''"\n    },\n    {\n      "label": "Текст приказан пре броја погрешних изјава изабраних у резимеу задатка.",\n      "default": "Погрешни одговори:",\n      "description": "Биће приказано изнад изјава. Пример: ''Погрешни одговори: 4''"\n    },\n    {\n      "label": "Резиме повратних информација",\n      "default": "Ваш резултат",\n      "description": "Биће приказано изнад резимеа повратних информација."\n    },\n    {\n      "label": "Текст из звучника за тачан одговор",\n      "default": "Тачно."\n    },\n    {\n      "label": "Текст читача за објављивање нетачног одговора",\n      "default": "Погрешно! Покушајте поново."\n    },\n    {\n      "label": "Ознака звучника за нетачан одговор",\n      "default": "Погрешно"\n    },\n    {\n      "label": "Наслов тачних одговора",\n      "default": "Тачни одговори."\n    },\n    {\n      "label": "Наслов за приказ савета",\n      "default": "Прикажи савет"\n    },\n    {\n      "label": "Текстуални приказ бодовне траке за оне који користе читач звука",\n      "description": ":num и :total су посебне кључне речи које се програмски ажурирају",\n      "default": "Освојили сте :num од :total поена"\n    },\n    {\n      "label": "Текст који се користи за звучнике за читање ради комуницирања напретка",\n      "description": ":num и :total су посебне кључне речи које се програмски ажурирају",\n      "default": "Напредак :num од :total"\n    }\n  ]\n}\n'),
(34, 'sv', '{\n  "semantics": [\n    {\n      "label": "Introduktionstext",\n      "default": "Välj det korrekta påståendet.",\n      "description": "Detta kommer visas överst i sammanfattningsuppgift."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Standard"\n        },\n        {\n          "label": "Textuell"\n        }\n      ],\n      "label": "Sammanfattning",\n      "entity": "påståenden",\n      "field": {\n        "label": "Påståenden",\n        "fields": [\n          {\n            "label": "Påståenden till sammanfattningsuppgift - första påståendet är det korrekta.",\n            "entity": "påstående",\n            "field": {\n              "label": "Påstående"\n            }\n          },\n          {\n            "label": "Tips",\n            "fields": [\n              {\n                "label": "Tipstext"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Bakgrundsopacitet på flyttbara element",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Standard"\n            }\n          ],\n          "label": "Definiera anpassad feedback för valfritt poängintervall",\n          "description": "Klicka på knappen \\"Lägg till intervall\\" för att lägga till så många intervall som du behöver. Exempel: 0-20% Underkänt, 21-91% Godkänt, 91-100% Mycket väl godkänt!",\n          "entity": "intervall",\n          "field": {\n            "fields": [\n              {\n                "label": "Poängintervall"\n              },\n              {},\n              {\n                "label": "Feedback för detta intervall",\n                "placeholder": "Skriv in feedback här"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Text som visas före antalet påståenden som är lösta i sammanfattningsuppgiften.",\n      "default": "Löst:",\n      "description": "Kommer visas ovanför påståendena. Exempel: ''Löst: 2/5''"\n    },\n    {\n      "label": "Text som visas före antalet påståenden med fel i sammanfattningsuppgiften.",\n      "default": "Antal fel:",\n      "description": "Kommer visas över påståendena. Exempel: ''Antal fel: 4''"\n    },\n    {\n      "label": "Rubrik över feedback",\n      "default": "Ditt resultat:",\n      "description": "Kommer visas över feedback på sammanfattningsuppgift."\n    },\n    {\n      "label": "Etikett för korrekt svar",\n      "default": "Rätt"\n    },\n    {\n      "label": "Skärmläsartext för felaktigt svar",\n      "default": "Fel. Försök igen."\n    },\n    {\n      "label": "Skärmläsaretikett för felaktigt svar",\n      "default": "Fel"\n    },\n    {\n      "label": "Etikett för lista med korrekta svar",\n      "default": "Rätta svar"\n    },\n    {\n      "label": "Etikett för knapp visa tips",\n      "default": "Visa tips"\n    },\n    {\n      "label": "Texten som läses upp när poängen presenteras för användare med skärmläsare",\n      "description": ":num och :total är variabler som uppdateras automatiskt",\n      "default": "Du fick :num av :total points"\n    },\n    {\n      "label": "Text som används av skärmläsare för att kommunicera om framsteg",\n      "description": ":num och :total är variabler som uppdateras automatiskt",\n      "default": "Framsteg :num av :total"\n    }\n  ]\n}\n'),
(34, 'sw', '{\n  "semantics": [\n    {\n      "label": "Maandishi ya utangulizi",\n      "default": "Chagua kauli sahihi.",\n      "description": "Itaonyeshwa juu ya kazi ya muhtasari."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Chaguo-msingi"\n        },\n        {\n          "label": "Kimaandishi"\n        }\n      ],\n      "label": "Muhtasari",\n      "entity": "kauli",\n      "field": {\n        "label": "Seti ya kauli",\n        "fields": [\n          {\n            "label": "Orodha ya kauli za muhtasari - kauli ya kwanza ni sahihi.",\n            "entity": "kauli",\n            "field": {\n              "label": "Kauli"\n            }\n          },\n          {\n            "label": "Kidokezo",\n            "fields": [\n              {\n                "label": "Maandishi ya kidokezo"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Maoni ya Jumla",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Chaguo-msingi"\n            }\n          ],\n          "label": "Bainisha maoni maalum kwa masafa yoyote ya alama",\n          "description": "Bofya kitufe cha \\"Ongeza masafa\\" ili kuongeza masafa mengi unavyohitaji. Mfano: 0-20% Alama mbaya, 21-91% Alama ya Wastani, 91-100% Alama Nzuri!",\n          "entity": "masafa",\n          "field": {\n            "fields": [\n              {\n                "label": "Masafa ya Alama"\n              },\n              {},\n              {\n                "label": "Maoni kwa masafa ya alama yaliyofafanuliwa",\n                "placeholder": "Jaza maoni"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Maandishi yaliyoonyeshwa kabla ya idadi ya kauli zilizotatuliwa katika kazi ya muhtasari.",\n      "default": "Maendeleo:",\n      "description": "Itaonyeshwa juu yakauli za hapo juui. Mfano: ‘Maendeleo: 2/5''"\n    },\n    {\n      "label": "Maandishi yaliyoonyeshwa kabla ya idadi ya kauli zisizo sahihi zilizochaguliwa katika kazi ya muhtasari.",\n      "default": "Majibu yasiyo sahihi:",\n      "description": "Itaonyeshwa juu yakauli za hapo juui. Mfano: ‘Majibu yasiyo sahihi: 4''"\n    },\n    {\n      "label": "Kichwa cha maoni ya muhtasari",\n      "default": "Matokeo yako",\n      "description": "Yataonyeshwa juu ya kazi ya muhtasari."\n    },\n    {\n      "label": "Maandishi ya kisoma maandishi kwa jibu sahihi",\n      "default": "Sahihi."\n    },\n    {\n      "label": "Maandishi ya kisoma maandishi kwa kutangaza jibu lisilo sahihi",\n      "default": "Siyo sahihi! Tafadhali jaribu tena."\n    },\n    {\n      "label": "Lebo ya kisoma maandishi kwa jibu lisilo sahihi",\n      "default": "Siyo sahihi"\n    },\n    {\n      "label": "Orodha ya lebo ya majibu sahihi",\n      "default": "Majibu sahihi."\n    },\n    {\n      "label": "Lebo ya kitufe cha kidokezi cha onyesho",\n      "default": "Kidokezo cha onyesho"\n    },\n    {\n      "label": "Uwakilishi wa maandishi wa upau wa alama kwa wale wanaotumia kisoma maandishi",\n      "description": ":num na:total ni maneno muhimu maalum ambayo yanasasishwa kwa programu",\n      "default": "Umepata :num kati ya alama:total"\n    },\n    {\n      "label": "Maandishi yanayotumika kwa visoma maandishi kuwasilisha maendeleo",\n      "description": ":num na:total ni maneno muhimu maalum ambayo yanasasishwa kwa programu",\n      "default": "Maendeleo :num kati ya:total"\n    }\n  ]\n}\n'),
(34, 'te', '{\n  "semantics": [\n    {\n      "label": "పరిచయ టెక్స్ట్",\n      "default": "సరైన స్టేట్ మెంట్ ను ఎంచుకోండి.",\n      "description": "సమ్మరీ టాస్క్ పైన ప్రదర్శించబడుతుంది."\n    },\n    {\n      "widgets": [\n        {\n          "label": "డిఫాల్ట్"\n        },\n        {\n          "label": "టెక్స్ట్యువల్"\n        }\n      ],\n      "label": "సమ్మరీ",\n      "entity": "స్టేట్ మెంట్స్",\n      "field": {\n        "label": "స్టేట్ మెంట్స్ సమితి",\n        "fields": [\n          {\n            "label": "సమ్మరీ కై కోసం స్టేట్‌మెంట్‌ల జాబితా - మొదటి స్టేట్‌మెంట్ సరైనది.",\n            "entity": "స్టేట్ మెంట్",\n            "field": {\n              "label": "స్టేట్ మెంట్"\n            }\n          },\n          {\n            "label": "టిప్",\n            "fields": [\n              {\n                "label": "చిట్కా (టిప్) టెక్స్ట్"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "ఓవర్ ఆల్ ఫీడ్ బాక్",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "డీఫాల్ట్"\n            }\n          ],\n          "label": "ఏ స్కోర్ పరిధికైనా అనుకూలమైన ఫీడ్ బ్యాక్ ను డిఫైన్ చెయ్యండి",\n          "description": "మీకు అవసరమైనన్ని పరిధులను జోడించడానికి \\"పరిధిని జోడించు\\" బటన్‌ను క్లిక్ చేయండి. ఉదాహరణ: 0-20% బ్యాడ్ స్కోర్, 21-91% సగటు స్కోర్, 91-100% గొప్ప స్కోర్!",\n          "entity": "పరిధి",\n          "field": {\n            "fields": [\n              {\n                "label": "స్కోర్ పరిధి"\n              },\n              {},\n              {\n                "label": "నిర్వచింపబడిన స్కోర్ పరిధి కై ఫీడ్ బ్యాక్",\n                "placeholder": "ఫీడ్ బ్యాక్ ను ఫిల్ చేయండి"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "సమ్మరీ టాస్క్‌లో స్టేట్‌మెంట్‌ల సంఖ్యకు ముందు ఈ టెక్స్ట్ ప్రదర్శించబడుతుంది.",\n      "default": "ప్రోగ్రెస్:",\n      "description": "స్టేట్‌మెంట్‌ల పైన ప్రదర్శించబడుతుంది. ఉదాహరణ: ''ప్రోగ్రెస్: 2/5''"\n    },\n    {\n      "label": "సమ్మరీ టాస్క్‌లో తప్పు స్టేట్‌మెంట్‌ల సంఖ్యకు ముందు ఈ టెక్స్ట్ ప్రదర్శించబడుతుంది.",\n      "default": "తప్పు సమాధానాలు:",\n      "description": "స్టేట్‌మెంట్‌ల పైన ప్రదర్శించబడుతుంది. ఉదాహరణ: ''తప్పు సమాధానాలు:4''"\n    },\n    {\n      "label": "సమ్మరీ ఫీడ్ బాక్ హెడర్",\n      "default": "మీ ఫలితం",\n      "description": "సమ్మరీ ఫీడ్ బాక్ పైన ప్రదర్శించబడుతుంది."\n    },\n    {\n      "label": "సరైన సమాధానం కోసం స్పీకర్ టెక్స్ట్",\n      "default": "సరైన సమాధానం."\n    },\n    {\n      "label": "తప్పు సమాధానం ప్రకటించినపుడు వచ్చేరీడ్ స్పీకర్ టెక్స్ట్",\n      "default": "సరికాదు! దయచేసి మళ్లీ ప్రయత్నించండి."\n    },\n    {\n      "label": "తప్పు సమాధానం కై రీడ్ స్పీకర్ లేబుల్",\n      "default": "సరికాదు"\n    },\n    {\n      "label": "సరైన సమాధానాల లేబుల్ జాబితా",\n      "default": "సరైన సమాధానాలు."\n    },\n    {\n      "label": "చిట్కా చూపించు బటన్ కోసం లేబుల్",\n      "default": "చిట్కా చూపించు"\n    },\n    {\n      "label": "రీడ్‌స్పీకర్‌ని ఉపయోగించే వారి కోసం స్కోర్ బార్ యొక్క టెక్స్టువల్ రిప్రెజెంటేషన్",\n      "description": ":num మరియు :total అనేవి ప్రోగ్రామాటిక్‌గా అప్‌డేట్ చేయబడిన ప్రత్యేక కీలకపదాలు",\n      "default": "మీరు :మొత్తం పాయింట్లలో :పాయింట్లు పొందారు"\n    },\n    {\n      "label": "ప్రోగ్రెస్ ను కమ్యూనికేట్ చేయడానికి ఉపయోగించే రీడ్‌స్పీకర్‌ల టెక్స్ట్",\n      "description": ":num మరియు :total అనేవి ప్రోగ్రామాటిక్‌గా అప్‌డేట్ చేయబడిన ప్రత్యేక కీలకపదాలు",\n      "default": "ప్రోగ్రెస్: సంఖ్య: మొత్తం"\n    }\n  ]\n}\n'),
(34, 'tr', '{\n  "semantics": [\n    {\n      "label": "Giriş metni",\n      "default": "Doğru ifadeyi seçin.",\n      "description": "Özet aktivitesi üzerinde görüntülenecek."\n    },\n    {\n      "widgets": [\n        {\n          "label": "Varsayılan"\n        },\n        {\n          "label": "Metin"\n        }\n      ],\n      "label": "Özet",\n      "entity": "ifadeler",\n      "field": {\n        "label": "İfadeler grubu",\n        "fields": [\n          {\n            "label": "Özet için ifadeler listesi - birinci ifade doğru.",\n            "entity": "cümle",\n            "field": {\n              "label": "İfade"\n            }\n          },\n          {\n            "label": "İpucu",\n            "fields": [\n              {\n                "label": "İpucu metni"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Overall Feedback",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "Varsayılan"\n            }\n          ],\n          "label": "Define custom feedback for any score range",\n          "description": "Click the \\"Add range\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!",\n          "entity": "range",\n          "field": {\n            "fields": [\n              {\n                "label": "Score Range"\n              },\n              {},\n              {\n                "label": "Feedback for defined score range",\n                "placeholder": "Fill in the feedback"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Özet aktivitesinde çözülen ifadeler sayısından önce görüntülenecek metin.",\n      "default": "İlerleme:",\n      "description": "İfadeler üzerinde görüntülenecek. Örneğin: ''İlerleme: 2/5''"\n    },\n    {\n      "label": "Özet aktivitesinde seçilen yanlış cümle sayısından önce görüntülenen metin.",\n      "default": "Yanlış cevaplar:",\n      "description": "İfadeler üzerinde görüntülenecek. Örneğin: ''Yanlış cevaplar: 4''"\n    },\n    {\n      "label": "Özet geri bildirim başlığı",\n      "default": "Sonuçlarınız",\n      "description": "Özet geri bildiriminin üzerinde görüntülenecek metin."\n    },\n    {\n      "label": "Readspeaker text for correct answer",\n      "default": "Correct."\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "Label list of correct answers",\n      "default": "Correct answers."\n    },\n    {\n      "label": "Label for the show tip button",\n      "default": "Show tip"\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Text used for readspeakers to communicate progress",\n      "description": ":num and :total are special keywords which are programmatically updated",\n      "default": "Progress :num of :total"\n    }\n  ]\n}'),
(34, 'uk', '{\n  "semantics": [\n    {\n      "label": "Введення тексту",\n      "default": "Виберіть правильне твердження.",\n      "description": "Буде відображено над підсумковим завданням."\n    },\n    {\n      "widgets": [\n        {\n          "label": "За умовчанням"\n        },\n        {\n          "label": "Текстовий"\n        }\n      ],\n      "label": "Підсумок",\n      "entity": "твердження",\n      "field": {\n        "label": "Набір тверджень",\n        "fields": [\n          {\n            "label": "Список тверджень для резюме - перше твердження правильне.",\n            "entity": "твердження",\n            "field": {\n              "label": "Твердження"\n            }\n          },\n          {\n            "label": "Підказка",\n            "fields": [\n              {\n                "label": "Текст підказки"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Зворотній зв''язок",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "За умовчанням"\n            }\n          ],\n          "label": "Визначте власні відгуки для будь-якого діапазону балів",\n          "description": "Клацніть кнопку (Додати діапазон), щоб додати стільки діапазонів, скільки вам потрібно. Наприклад: 0-20% поганий бал, 21-91% середній бал, 91-100% чудовий бал!",\n          "entity": "діапазон",\n          "field": {\n            "fields": [\n              {\n                "label": "Діапазон балів"\n              },\n              {},\n              {\n                "label": "Зворотній зв''язок за визначений діапазон балів",\n                "placeholder": "Заповніть відгук"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "Текст відображається перед кількістю тверджень, розв''язаних у підсумковому завданні.",\n      "default": "Прогрес:",\n      "description": "Буде відображено над твердженнями. Приклад: ''Прогрес: 2/5''"\n    },\n    {\n      "label": "Текст відображається перед кількістю неправильних тверджень, вибраних у підсумковому завданні.",\n      "default": "Неправильні відповіді:",\n      "description": "Буде відображено над твердженнями. Приклад: ''Неправильні відповіді: 4''"\n    },\n    {\n      "label": "Заголовок зворотного зв''язку",\n      "default": "Ваш результат",\n      "description": "Буде відображено вище підсумкових відгуків."\n    },\n    {\n      "label": "Текст для оголошення правильної відповіді",\n      "default": "Правильно."\n    },\n    {\n      "label": "Текст для оголошення неправильної відповіді",\n      "default": "Неправильно! Будь ласка спробуйте ще раз."\n    },\n    {\n      "label": "Мітка для неправильної відповіді",\n      "default": "Неправильно"\n    },\n    {\n      "label": "Список міток правильних відповідей",\n      "default": "Правильні відповіді."\n    },\n    {\n      "label": "Мітка для показу кнопки підказки",\n      "default": "Показати підказку"\n    },\n    {\n      "label": "Текстове представлення шкали оцінок для тих, хто використовує динамік",\n      "description": ":num і :total це спеціальні ключові слова, які програмно оновлюються",\n      "default": "Ти маєш :num з :total балів"\n    },\n    {\n      "label": "Текст, який використовує динаміки для повідомлення про прогрес",\n      "description": ":num і :total це спеціальні ключові слова, які програмно оновлюються",\n      "default": "Прогрес :num з :total"\n    }\n  ]\n}\n'),
(34, 'zh-cn', '{\n  "semantics": [\n    {\n      "label": "说明文字",\n      "default": "请选择正确的陈述。",\n      "description": "将显示在‘概要’任务的上方。"\n    },\n    {\n      "widgets": [\n        {\n          "label": "默认"\n        },\n        {\n          "label": "文本"\n        }\n      ],\n      "label": "概要",\n      "entity": "陈述",\n      "field": {\n        "label": "陈述集",\n        "fields": [\n          {\n            "label": "概要陈述列表 - 注意：正确的陈述放在第一行。",\n            "entity": "陈述",\n            "field": {\n              "label": "陈述"\n            }\n          },\n          {\n            "label": "提示",\n            "fields": [\n              {\n                "label": "提示文字"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "总体反馈",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "默认"\n            }\n          ],\n          "label": "为任何分数范围自定义反馈",\n          "description": "单击“添加范围”按钮可根据需要添加任意分数范围。示例：0-20％请加油，21-91％继续努力，91-100％你真棒！",\n          "entity": "范围",\n          "field": {\n            "fields": [\n              {\n                "label": "分数区间"\n              },\n              {},\n              {\n                "label": "自定义区间反馈信息",\n                "placeholder": "输入反馈信息"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "显示进度文本",\n      "default": "进度：",\n      "description": "将显示在陈述的上方。例如：‘进度：2/5’"\n    },\n    {\n      "label": "错误信息文本",\n      "default": "答错：",\n      "description": "将显示在陈述的上方，例如答错：4"\n    },\n    {\n      "label": "反馈信息标题",\n      "default": "你的结果：",\n      "description": "将显示在概要反馈的上方。"\n    },\n    {\n      "label": "回答正确时的反馈文本",\n      "default": "正确！"\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "正确答案的标签列表",\n      "default": "正确答案。"\n    },\n    {\n      "label": "显示提示按钮的标签",\n      "default": "显示提示"\n    },\n    {\n      "label": "得分情况的文本描述",\n      "description": ":num 和:total 是特殊字符，程序会自动进行更新。",\n      "default": "你得到 :num 分，总分 :total 分。"\n    },\n    {\n      "label": "答题进度的文本描述",\n      "description": ":num 和:total 是特殊字符，程序会自动进行更新。",\n      "default": "进度：第 :num 题，共 :total 题。"\n    }\n  ]\n}'),
(34, 'zh-hans', '{\n  "semantics": [\n    {\n      "label": "说明文字",\n      "default": "下列何项叙述正确，请选择。",\n      "description": "会显示在摘要任务的上方。"\n    },\n    {\n      "widgets": [\n        {\n          "label": "视觉模式"\n        },\n        {\n          "label": "文字模式"\n        }\n      ],\n      "label": "摘要",\n      "entity": "叙述",\n      "field": {\n        "label": "叙述集",\n        "fields": [\n          {\n            "label": "摘要叙述的列表-注意第一个要放正确的叙述。",\n            "entity": "叙述",\n            "field": {\n              "label": "叙述"\n            }\n          },\n          {\n            "label": "提示",\n            "fields": [\n              {\n                "label": "提示文字"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "结果回馈",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "预设"\n            }\n          ],\n          "label": "为不同分数区间的用戶分別回馈讯息",\n          "description": "点击「添加范围」按钮，加入你想要的范围，例如 0%-59% 请加油、60%-79% 再努力、80%-100% 太棒了。",\n          "entity": "范围",\n          "field": {\n            "fields": [\n              {\n                "label": "分数区间"\n              },\n              {},\n              {\n                "label": "自订区间回馈讯息",\n                "placeholder": "填入回馈讯息"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "进度前缀文字",\n      "default": "进度：",\n      "description": "在摘要任务已解答数量前显示的文字。例如进度：2/5"\n    },\n    {\n      "label": "错误前缀文字",\n      "default": "答错：",\n      "description": "在摘要任务已解答数量前显示的文字。例如答错：4"\n    },\n    {\n      "label": "回馈讯息标题文字",\n      "default": "你的结果：",\n      "description": "将在结果反馈上方显示。"\n    },\n    {\n      "label": "报读器答对文本",\n      "default": "答对了！"\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "正确答案的文字列表",\n      "default": "正确答案。"\n    },\n    {\n      "label": "显示提示按钮的显示文字",\n      "default": "显示提示"\n    },\n    {\n      "label": "报读器得分条文本",\n      "description": "用于报读器的辅助文本，非显示用。",\n      "default": "你得到 :num 分，总分 :total 分。"\n    },\n    {\n      "label": "报读器进度条文本",\n      "description": "用于报读器的辅助文本，非显示用。",\n      "default": "进度：第 :num 题，共 :total 题。"\n    }\n  ]\n}'),
(34, 'zh-hant', '{\n  "semantics": [\n    {\n      "label": "說明文字",\n      "default": "下列何項敘述正確，請選擇。",\n      "description": "會顯示在摘要任務的上方。"\n    },\n    {\n      "widgets": [\n        {\n          "label": "視覺模式"\n        },\n        {\n          "label": "文字模式"\n        }\n      ],\n      "label": "摘要",\n      "entity": "敘述",\n      "field": {\n        "label": "敘述集",\n        "fields": [\n          {\n            "label": "摘要敘述的列表-注意第一個要放正確的敘述。",\n            "entity": "敘述",\n            "field": {\n              "label": "敘述"\n            }\n          },\n          {\n            "label": "提示",\n            "fields": [\n              {\n                "label": "提示文字"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "結果回饋",\n      "fields": [\n        {\n          "widgets": [\n            {\n              "label": "預設"\n            }\n          ],\n          "label": "為不同分數區間的用戶分別回饋訊息",\n          "description": "點擊「添加範圍」按鈕，加入你想要的範圍，例如 0%-59% 請加油、60%-79% 再努力、80%-100% 太棒了。",\n          "entity": "範圍",\n          "field": {\n            "fields": [\n              {\n                "label": "分數區間"\n              },\n              {},\n              {\n                "label": "自訂區間回饋訊息",\n                "placeholder": "填入回饋訊息"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      "label": "進度前綴文字",\n      "default": "進度：",\n      "description": "在摘要任務已解答數量前顯示的文字。例如進度：2/5"\n    },\n    {\n      "label": "錯誤前綴文字",\n      "default": "答錯：",\n      "description": "在摘要任務已解答數量前顯示的文字。例如答錯：4"\n    },\n    {\n      "label": "回饋訊息標題文字",\n      "default": "你的結果：",\n      "description": "將在結果反饋上方顯示。"\n    },\n    {\n      "label": "報讀器答對文本",\n      "default": "答對了！"\n    },\n    {\n      "label": "Readspeaker text for announcing incorrect answer",\n      "default": "Incorrect! Please try again."\n    },\n    {\n      "label": "Readspeaker label for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "正確答案的文字列表",\n      "default": "正確答案。"\n    },\n    {\n      "label": "顯示提示按鈕的顯示文字",\n      "default": "顯示提示"\n    },\n    {\n      "label": "報讀器得分條文本",\n      "description": "用於報讀器的輔助文本，非顯示用。",\n      "default": "你得到 :num 分，總分 :total 分。"\n    },\n    {\n      "label": "報讀器進度條文本",\n      "description": "用於報讀器的輔助文本，非顯示用。",\n      "default": "進度：第 :num 題，共 :total 題。"\n    }\n  ]\n}'),
