(39, 'sv', '{\n  "semantics": [\n    {\n      "label": "Videokällor",\n      "description": "För att säkerställa att video fungerar i alla olika webbläsare så bör du lägga till källor i både WebM- och MP4-format."\n    },\n    {\n      "label": "Visualisering",\n      "fields": [\n        {\n          "label": "Poster-bild"\n        },\n        {\n          "label": "Anpassa videospelaren så att allt tillgängligt utrymme används",\n          "description": "Om inte angivet, så kommer videospelaren ha samma bildförhållande som själva videon."\n        },\n        {\n          "label": "Visa videospelar-kontroller",\n          "description": "Lägger till kontroller till videospelaren. Gör det möjligt att spela upp, pausa, etc."\n        }\n      ]\n    },\n    {\n      "label": "Uppspelning",\n      "fields": [\n        {\n          "label": "Auto-spela video",\n          "description": "Börja spela videon automatiskt. Kanske inte stöds på mobila enheter."\n        },\n        {\n          "label": "Loopa video",\n          "description": "När videon är slut, starta automatiskt om från början."\n        }\n      ]\n    },\n    {\n      "label": "Video-lokalisering",\n      "fields": [\n        {\n          "label": "Namn",\n          "default": "Video",\n          "description": "Underlättar att identifiera innehåll av denna typ."\n        },\n        {\n          "label": "Laddar",\n          "default": "Videospelare laddar ..."\n        },\n        {\n          "label": "Inga spelare hittades",\n          "default": "Hittade inga videospelare som stödjer angivet videoformat."\n        },\n        {\n          "label": "Inga källor",\n          "default": "Videokällor saknas."\n        },\n        {\n          "label": "Avbruten",\n          "default": "Uppspelning av media har avbrutits."\n        },\n        {\n          "label": "Nätverksfel",\n          "default": "Nätverksfel."\n        },\n        {\n          "label": "Kan inte avkoda videookälla",\n          "default": "Kan inte avkoda videookälla."\n        },\n        {\n          "label": "Format stöds inte",\n          "default": "Videoformat stöds inte."\n        },\n        {\n          "label": "Media krypterat",\n          "default": "Media krypterat."\n        },\n        {\n          "label": "Okänt fel",\n          "default": "Okänt fel."\n        },\n        {\n          "label": "Ogiltigt YouTube ID",\n          "default": "Ogiltigt YouTube ID."\n        },\n        {\n          "label": "Okänt YouTube ID",\n          "default": "Kunde inte hitta video med angivet YouTube ID."\n        },\n        {\n          "label": "Begränsad YouTube video",\n          "default": "Ägaren till denna video tillåter inte inbäddning."\n        }\n      ]\n    },\n    {\n      "label": "Tillgänglighet",\n      "fields": [\n        {\n          "label": "Lägg till videospår",\n          "entity": "Spår",\n          "field": {\n            "label": "Spår",\n            "fields": [\n              {\n                "label": "Etikett för spår"\n              },\n              {\n                "label": "Ange typ, se <a target=\\"_blank\\" href=\\"https://html.spec.whatwg.org/multipage/embedded-content.html#the-track-element\\">HTML living standard</a>",\n                "options": [\n                  {\n                    "label": "Undertexter"\n                  },\n                  {\n                    "label": "Skyltar"\n                  },\n                  {\n                    "label": "Beskrivningar"\n                  },\n                  {\n                    "label": "Kapitel"\n                  }\n                ]\n              },\n              {\n                "label": "Källspråk, måste anges för undertexter",\n                "description": "Måste vara en giltig BCP 47-språktagg. Om typen undertexter är vald, så måste srclang definieras."\n              },\n              {\n                "label": "Spårfil (WebVTT)"\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}\n'),
(39, 'sw', '{\n  "semantics": [\n    {\n      "label": "Vyanzo vya video",\n      "description": "Ili kuhakikisha kuwa video inafanya kazi katika vivinjari vyote unapaswa kuongeza vyanzo vyote vya WebM na MP4 vilivyopangwa."\n    },\n    {\n      "label": "Vielelezo",\n      "fields": [\n        {\n          "label": "Picha ya bango"\n        },\n        {\n          "label": "Weka kichezaji video kutumia nafasi zote zinazopatikana",\n          "description": "Kama hujaweka kichezaji video itakuwa na uwiano sawa kama video yenyewe."\n        },\n        {\n          "label": "Onyesha vidhibiti vya kichezaji video",\n          "description": "Ongeza vidhibiti kwenye kichezaji video. Hii inaruhusu watumiaji kucheza, kusitisha, na kadhalika."\n        }\n      ]\n    },\n    {\n      "label": "Uchezaji",\n      "fields": [\n        {\n          "label": "Cheza video kiotomatiki",\n          "description": "Anza kucheza video kiotomatiki. Huenda isifanye kazi kwenye vifaa vya runuru."\n        },\n        {\n          "label": "Video ya kitanzi",\n          "description": "Anzisha video kiotomatiki tena inapoisha."\n        }\n      ]\n    },\n    {\n      "label": "Ujanibishaji wa video",\n      "fields": [\n        {\n          "label": "Jina",\n          "default": "Video",\n          "description": "Husaidia kutambua maudhui ya aina hii."\n        },\n        {\n          "label": "Kupakia",\n          "default": "Kichezaji cha video kinapakia..."\n        },\n        {\n          "label": "Hakuna vichezaji vilivyopatikana",\n          "default": "Hakuna vichezaji vya video vinavyounga mkono muundo wa video uliopewa."\n        },\n        {\n          "label": "Hakuna vyanzo",\n          "default": "Video inakosa vyanzo."\n        },\n        {\n          "label": "Imeondolewa",\n          "default": "Uchezaji wa vyombo vya habari umeondolewa."\n        },\n        {\n          "label": "Kushindwa kwa mtandao",\n          "default": "Kushindwa kwa mtandao."\n        },\n        {\n          "label": "Haiwezi kusimbua chanzo cha video",\n          "default": "Kushindwa kusimbua vyombo vya habari."\n        },\n        {\n          "label": "Muundo hauungwi mkono",\n          "default": "Umbizo la video haliungwi mkono."\n        },\n        {\n          "label": "Vyombo vya habari vimesimbwa kwa njia fiche",\n          "default": "Vyombo vya habari vimesimbwa kwa njia fiche."\n        },\n        {\n          "label": "Hitilafu isiyojulikana",\n          "default": "Hitilafu isiyojulikana."\n        },\n        {\n          "label": "Kitambulisho batili cha YouTube",\n          "default": "Kitambulisho batili cha YouTube."\n        },\n        {\n          "label": "Kitambulisho cha YouTube kisichojulikana",\n          "default": "Kushindwa kupata video yenye kitambulisho cha YouTube kilichotolewa."\n        },\n        {\n          "label": "Video ya YouTube iliyozuiliwa",\n          "default": "Mmiliki wa video hii hairuhusu kuingizwa."\n        }\n      ]\n    },\n    {\n      "label": "Ufikiaji",\n      "fields": [\n        {\n          "label": "Ongeza wimbo wa video",\n          "entity": "Wimbo",\n          "field": {\n            "label": "Wimbo",\n            "fields": [\n              {\n                "label": "Lebo ya wimbo"\n              },\n              {\n                "label": "Aina ya aina,<a target=\\"_blank\\" href=\\"https://html.spec.whatwg.org/multipage/embedded-content.html#the-track-element\\"> rejelea kiwango cha maisha cha Lugha ya kutunga matini ya mtandao</a>",\n                "options": [\n                  {\n                    "label": "Manukuu"\n                  },\n                  {\n                    "label": "Manukuu"\n                  },\n                  {\n                    "label": "Maelezo"\n                  },\n                  {\n                    "label": "Sura"\n                  }\n                ]\n              },\n              {\n                "label": "Lugha chanzi, lazima ifafanuliwe kwa manukuu",\n                "description": "Lazima iwe ni lebo halali ya lugha ya BCP 47. Ikiwa sifa ya aina imewekwa kwa manukuu, srclang lazima ielezwe."\n              },\n              {\n                "label": "Fuatilia faili (WebVTT)"\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}\n'),
(39, 'tr', '{\n  "semantics": [\n    {\n      "label": "Video kaynakları",\n      "description": "Videonun tüm tarayıcılarda çalışmasını sağlamak için hem WebM hem de MP4 formatlı kaynaklar eklemelisiniz."\n    },\n    {\n      "label": "Görseller",\n      "fields": [\n        {\n          "label": "Poster resmi"\n        },\n        {\n          "label": "Mevcut tüm alanı kullanmak için video oynatıcıyı sığdır",\n          "description": "Ayarlanmazsa, video oynatıcı video ile aynı en boy oranına sahip olacaktır."\n        },\n        {\n          "label": "Video oynatıcı kontrollerini göster",\n          "description": "Video oynatıcıya kontroller ekleyiniz. Bu, kullanıcılara oynatma, duraklatma vb. izinler verir."\n        }\n      ]\n    },\n    {\n      "label": "Oynatma",\n      "fields": [\n        {\n          "label": "Videoyu otomatik oynat",\n          "description": "Videoyu otomatik olarak oynatmaya başlayınız. Mobil cihazlarda çalışmayabilir."\n        },\n        {\n          "label": "Videoyu tekrarla",\n          "description": "Bittiğinde videoyu otomatik olarak yeniden başlatınız."\n        }\n      ]\n    },\n    {\n      "label": "Video bölge ve dil seçenekleri",\n      "fields": [\n        {\n          "label": "İsim",\n          "default": "Video",\n          "description": "Bu türdeki içeriği tanımlamaya yardımcı olur."\n        },\n        {\n          "label": "Yükleniyor",\n          "default": "Video oynatıcı yükleniyor..."\n        },\n        {\n          "label": "Video oynatıcı bulunamadı",\n          "default": "Verilen video biçimini destekleyen hiçbir video oynatıcı bulunamadı."\n        },\n        {\n          "label": "Kaynak yok",\n          "default": "Videonun kaynakları eksik."\n        },\n        {\n          "label": "İptal edildi",\n          "default": "Medya oynatma durduruldu."\n        },\n        {\n          "label": "Ağ hatası",\n          "default": "Ağ hatası."\n        },\n        {\n          "label": "Video kaynağının kodu çözülemiyor",\n          "default": "Medyanın kodu çözülemiyor."\n        },\n        {\n          "label": "Biçim desteklenmiyor",\n          "default": "Video formatı desteklenmiyor."\n        },\n        {\n          "label": "Medya şifrelenmiş",\n          "default": "Medya şifrelenmiş."\n        },\n        {\n          "label": "Bilinmeyen hata",\n          "default": "Bilinmeyen hata."\n        },\n        {\n          "label": "Geçersiz YouTube Kimliği (ID)",\n          "default": "Geçersiz YouTube Kimliği (ID)."\n        },\n        {\n          "label": "Bilinmeyen YouTube Kimliği (ID)",\n          "default": "Verilen YouTube kimliğine (ID) sahip video bulunamadı."\n        },\n        {\n          "label": "Kısıtlanmış YouTube videosu",\n          "default": "Bu videonun sahibi, videonun yerleştirilmesine izin vermiyor."\n        }\n      ]\n    },\n    {\n      "label": "Erişilebilirlik",\n      "fields": [\n        {\n          "label": "Video alt yazısı ekle",\n          "entity": "Alt Yazı",\n          "field": {\n            "label": "Alt Yazı",\n            "fields": [\n              {\n                "label": "Alt Yazı etiketi"\n              },\n              {\n                "label": "Tür yazın, <a target=\\"_blank\\" href=\\"https://html.spec.whatwg.org/multipage/embedded-content.html#the-track-element\\">HTML yaşam standardına</a> bakın",\n                "options": [\n                  {\n                    "label": "Altyazılar"\n                  },\n                  {\n                    "label": "Başlıklar"\n                  },\n                  {\n                    "label": "Açıklamalar"\n                  },\n                  {\n                    "label": "Bölümler"\n                  }\n                ]\n              },\n              {\n                "label": "Kaynak dil, altyazılar için tanımlanmalıdır",\n                "description": "Geçerli bir BCP 47 dil etiketi olmalıdır. Tür niteliği altyazılara ayarlanmışsa, srclang tanımlanmalıdır."\n              },\n              {\n                "label": "İzleme dosyası (WebVTT)"\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}\n'),
(39, 'uk', '{\n  "semantics": [\n    {\n      "label": "Відео джерела",\n      "description": "Щоб відео працювало у всіх браузерах, ви повинні додати вихідні тексти у форматі WebM і MP4."\n    },\n    {\n      "label": "Візуалізація",\n      "fields": [\n        {\n          "label": "Зображення постера"\n        },\n        {\n          "label": "Установіть відеоплеєр, щоб використовувати все доступне місце",\n          "description": "Якщо не встановлено, відеоплеєр матиме таке ж співвідношення сторони, як відео."\n        },\n        {\n          "label": "Показати елементи управління відеоплеєром",\n          "description": "Додайте елементи управління у відеоплеєр. Це дозволяє користувачам відтворювати, приостанавлювати і т.ін."\n        }\n      ]\n    },\n    {\n      "label": "Програвання",\n      "fields": [\n        {\n          "label": "Автопрогравання відео",\n          "description": "Начніть створення відео автоматично. Може не працювати на мобільних пристроях."\n        },\n        {\n          "label": "Зациклювати відео",\n          "description": "Автоматично починати відео знову, коли воно заканчується."\n        }\n      ]\n    },\n    {\n      "label": "Локалізація відео",\n      "fields": [\n        {\n          "label": "Назва",\n          "default": "Відео",\n          "description": "Допомагає ідентифікувати контент цього типу."\n        },\n        {\n          "label": "Завантаження",\n          "default": "Завантаження відеоплеєра..."\n        },\n        {\n          "label": "Не знайдено програвачів",\n          "default": "Не знайдено відеопрогравачів, що підтримують цей формат відео."\n        },\n        {\n          "label": "Немає джерел",\n          "default": "У відео відсутні джерела."\n        },\n        {\n          "label": "Відмінено",\n          "default": "Програвання мультимедіа було припинено."\n        },\n        {\n          "label": "Сбой мережі",\n          "default": "Сбой мережі."\n        },\n        {\n          "label": "Не вдається декодувати джерело відео",\n          "default": "Неможливо декодувати медіа."\n        },\n        {\n          "label": "Формат не підтримується",\n          "default": "Формат відео не підтримується."\n        },\n        {\n          "label": "Медіа зашифровано",\n          "default": "Медіа зашифровано."\n        },\n        {\n          "label": "Невідома помилка",\n          "default": "Невідома помилка."\n        },\n        {\n          "label": "Невірний ідентифікатор YouTube",\n          "default": "Невірний ідентифікатор YouTube."\n        },\n        {\n          "label": "Невідомий ідентифікатор YouTube",\n          "default": "Неможливо знайти відео з указаним ідентифікатором YouTube."\n        },\n        {\n          "label": "Відео з YouTube обмежено",\n          "default": "Власник цього відео не дозволяє його встановлювати."\n        }\n      ]\n    },\n    {\n      "label": "Доступність",\n      "fields": [\n        {\n          "label": "Додати відео трек",\n          "entity": "Трек",\n          "field": {\n            "label": "Трек",\n            "fields": [\n              {\n                "label": "Надпись трека"\n              },\n              {\n                "label": "Введіть тип, зверніться до <a target=\\"_blank\\" href=\\"https://html.spec.whatwg.org/multipage/embedded-content.html#the-track-element\\">стандарт життя HTML</a>",\n                "options": [\n                  {\n                    "label": "Субтитри"\n                  },\n                  {\n                    "label": "Титри"\n                  },\n                  {\n                    "label": "Опис"\n                  },\n                  {\n                    "label": "Розділи"\n                  }\n                ]\n              },\n              {\n                "label": "Вихідна мова має бути визначена для субтитрів",\n                "description": "Повинен бути існуючим мовним тегом BCP 47. Якщо тип атрибута встановлено в субтитрах, мова джерела має бути визначена."\n              },\n              {\n                "label": "Файл трека (WebVTT)"\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}'),
(39, 'vi', '{\n  "semantics": [\n    {\n      "label": "Nguồn video",\n      "description": "Để đảm bảo video phát được trong mọi trình duyệt, bạn nên thêm cả hai nguồn có định dạng WebM và MP4."\n    },\n    {\n      "label": "Visuals",\n      "fields": [\n        {\n          "label": "Poster image"\n        },\n        {\n          "label": "Fit video player to use all available space",\n          "description": "If not set the video player will have the same aspect ratio as the video."\n        },\n        {\n          "label": "Show video player controls",\n          "description": "Add controls to the video player. This allows users to play, pause, etc."\n        }\n      ]\n    },\n    {\n      "label": "Playback",\n      "fields": [\n        {\n          "label": "Tự động phát video",\n          "description": "Tự động phát video. Có thể không hoạt động trên thiết bị di động."\n        },\n        {\n          "label": "Lặp video",\n          "description": "Tự động phát lại video khi hết."\n        }\n      ]\n    },\n    {\n      "label": "Video localization",\n      "fields": [\n        {\n          "label": "Tên",\n          "default": "Video",\n          "description": "Helps identify content of this type."\n        },\n        {\n          "label": "Đang tải",\n          "default": "Đang tải trình phát video..."\n        },\n        {\n          "label": "Không tìm thấy trình phát",\n          "default": "Không tìm thấy trình phát hỗ trợ định dạng video này."\n        },\n        {\n          "label": "Không có nguồn",\n          "default": "Video bị thiếu nguồn."\n        },\n        {\n          "label": "Đã ngừng",\n          "default": "Đã ngừng phát video."\n        },\n        {\n          "label": "Lỗi mạng",\n          "default": "Lỗi mạng."\n        },\n        {\n          "label": "Cannot decode video source",\n          "default": "Unable to decode media."\n        },\n        {\n          "label": "Không hỗ trợ định dạng",\n          "default": "Định dạng của video không được hỗ trợ."\n        },\n        {\n          "label": "Media encrypted",\n          "default": "Media encrypted."\n        },\n        {\n          "label": "Lỗi không xác định",\n          "default": "Lỗi không xác định."\n        },\n        {\n          "label": "ID YouTube không hợp lệ",\n          "default": "ID YouTube không hợp lệ."\n        },\n        {\n          "label": "Không tìm thấy ID YouTube",\n          "default": "Không tìm thấy video nào có ID YouTube này."\n        },\n        {\n          "label": "Video YouTube bị hạn chế",\n          "default": "Người sở hữu video này không cho phép nhúng video này."\n        }\n      ]\n    },\n    {\n      "label": "Accessibility",\n      "fields": [\n        {\n          "label": "Add video track",\n          "entity": "Track",\n          "field": {\n            "label": "Track",\n            "fields": [\n              {\n                "label": "Track label"\n              },\n              {\n                "label": "Type kind, refer to <a target=\\"_blank\\" href=\\"https://html.spec.whatwg.org/multipage/embedded-content.html#the-track-element\\">HTML living standard</a>",\n                "options": [\n                  {\n                    "label": "Phụ đề"\n                  },\n                  {\n                    "label": "Phụ đề"\n                  },\n                  {\n                    "label": "Mô tả"\n                  },\n                  {\n                    "label": "Chương"\n                  }\n                ]\n              },\n              {\n                "label": "Source language, must be defined for subtitles",\n                "description": "Must be a valid BCP 47 language tag. If the kind attribute is set to subtitles, then srclang must be defined."\n              },\n              {\n                "label": "Track file (WebVTT)"\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}\n'),
(39, 'zh-cn', '{\n  "semantics": [\n    {\n      "label": "视频来源",\n      "description": "为确保所有浏览器均可播放，请使用添加WebM和MP4格式的源。"\n    },\n    {\n      "label": "外观",\n      "fields": [\n        {\n          "label": "视频缩图"\n        },\n        {\n          "label": "视频播放器自动调整成最大画面",\n          "description": "如果不勾选，视频会依原始尺寸比例播放。"\n        },\n        {\n          "label": "显示视频播放控制项",\n          "description": "在播放器下显示视频控制项，让用户能够使用播放、暂停等功能。"\n        }\n      ]\n    },\n    {\n      "label": "回放",\n      "fields": [\n        {\n          "label": "视频自动播放",\n          "description": "开始自动播放视频。此功能可能不支持移动设备。"\n        },\n        {\n          "label": "视频循环播放",\n          "description": "在视频播放完后重新播放。"\n        }\n      ]\n    },\n    {\n      "label": "视频本地化",\n      "fields": [\n        {\n          "label": "名称",\n          "default": "视频",\n          "description": "帮助识别这个内容的形式。"\n        },\n        {\n          "label": "正在载入",\n          "default": "视频播放器正在载入…"\n        },\n        {\n          "label": "找不到播放器",\n          "default": "找不到支持此视频格式的播放器。"\n        },\n        {\n          "label": "找不到来源",\n          "default": "找不到视频来源。"\n        },\n        {\n          "label": "中止",\n          "default": "媒体播放已中止。"\n        },\n        {\n          "label": "网络异常",\n          "default": "网络异常。"\n        },\n        {\n          "label": "无法解析媒体",\n          "default": "无法解析媒体。"\n        },\n        {\n          "label": "不支持的格式",\n          "default": "不支持的视频格式"\n        },\n        {\n          "label": "媒体已加密",\n          "default": "媒体已加密。"\n        },\n        {\n          "label": "未知的错误",\n          "default": "未知的错误。"\n        },\n        {\n          "label": "无效的 YouTube ID",\n          "default": "无效的 YouTube ID。"\n        },\n        {\n          "label": "未知的 YouTube ID",\n          "default": "无法找到与这个 YouTube ID 关联的视频。"\n        },\n        {\n          "label": "受限制的 YouTube 视频",\n          "default": "视频的上传者不允许用嵌入的方式观看视频。"\n        }\n      ]\n    },\n    {\n      "label": "无障碍功能",\n      "fields": [\n        {\n          "label": "添加视频字轨",\n          "entity": "字轨",\n          "field": {\n            "label": "字轨",\n            "fields": [\n              {\n                "label": "字轨标签"\n              },\n              {\n                "label": "格式请参考 <a target=\\"_blank\\" href=\\"https://html.spec.whatwg.org/multipage/embedded-content.html#the-track-element\\">HTML 现行标准</a>",\n                "options": [\n                  {\n                    "label": "字幕"\n                  },\n                  {\n                    "label": "标题"\n                  },\n                  {\n                    "label": "描述"\n                  },\n                  {\n                    "label": "章节"\n                  }\n                ]\n              },\n              {\n                "label": "必须为字幕定义源语言",\n                "description": "若字轨是字幕的话，必须要定义。须符合 BCP 47 的语言标记，例如 en 为英文、zh 为中文。"\n              },\n              {\n                "label": "字轨文件（格式为 WebVTT）"\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}\n'),
(39, 'zh-hans', '{\n  "semantics": [\n    {\n      "label": "视频来源",\n      "description": "为确保浏览器都可播放，请使用格式为 WebM 或 MP4 的视频。"\n    },\n    {\n      "label": "外观",\n      "fields": [\n        {\n          "label": "视频缩图"\n        },\n        {\n          "label": "视频播放器自动调整成最大画面",\n          "description": "如果不勾选，视频会依原始尺寸比例播放。"\n        },\n        {\n          "label": "显示视频播放控制项",\n          "description": "在播放器下显示视频控制项，让用户能够使用暂停、静音等功能。"\n        }\n      ]\n    },\n    {\n      "label": "播放",\n      "fields": [\n        {\n          "label": "视频自动播放",\n          "description": "在连接视频后自动播放。在行动装置上可能无效。"\n        },\n        {\n          "label": "影视频循环播放",\n          "description": "在视频播放完后重新播放。"\n        }\n      ]\n    },\n    {\n      "label": "本地化",\n      "fields": [\n        {\n          "label": "形式的名称",\n          "default": "视频",\n          "description": "帮助识别这个内容的形式。"\n        },\n        {\n          "label": "正在载入的显示文字",\n          "default": "视频播放器正在载入…"\n        },\n        {\n          "label": "找不到播放器的显示文字",\n          "default": "找不到支持此视频格式的播放器。"\n        },\n        {\n          "label": "找不到来源的显示文字",\n          "default": "找不到视频来源。"\n        },\n        {\n          "label": "中止的显示文字",\n          "default": "媒体播放已中止。"\n        },\n        {\n          "label": "网络异常的显示文字",\n          "default": "网络异常。"\n        },\n        {\n          "label": "无法解析媒体的显示文字",\n          "default": "无法解析媒体。"\n        },\n        {\n          "label": "不支持的格式的显示文字",\n          "default": "不支持的格式"\n        },\n        {\n          "label": "媒体已加密的显示文字",\n          "default": "媒体已加密。"\n        },\n        {\n          "label": "未知的错误的显示文字",\n          "default": "未知的错误。"\n        },\n        {\n          "label": "无效的 YouTube ID 的显示文字",\n          "default": "无效的 YouTube ID。"\n        },\n        {\n          "label": "未知的 YouTube ID 的显示文字",\n          "default": "无法找到与这个 YouTube ID 关联的视频。"\n        },\n        {\n          "label": "受限制的 YouTube 视频的显示文字",\n          "default": "视频的上传者不允许用嵌入的方式观看视频。"\n        }\n      ]\n    },\n    {\n      "label": "无障碍功能",\n      "fields": [\n        {\n          "label": "添加视频字轨",\n          "entity": "字轨",\n          "field": {\n            "label": "字轨",\n            "fields": [\n              {\n                "label": "字轨的说明文字"\n              },\n              {\n                "label": "格式请参考 <a target=\\"_blank\\" href=\\"https://html.spec.whatwg.org/multipage/embedded-content.html#the-track-element\\">HTML 现况标准</a>",\n                "options": [\n                  {\n                    "label": "字幕"\n                  },\n                  {\n                    "label": "标题"\n                  },\n                  {\n                    "label": "说明"\n                  },\n                  {\n                    "label": "章节"\n                  }\n                ]\n              },\n              {\n                "label": "语言代码",\n                "description": "若字轨是字幕的话，必须要定义。须符合 BCP 47 的语言标记，例如 en 为英文、zh 为中文。"\n              },\n              {\n                "label": "字轨来源（格式为 WebVTT）"\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}\n'),
(39, 'zh-hant', '{\n  "semantics": [\n    {\n      "label": "影片來源",\n      "description": "為確保並同瀏覽器都可播放，請使用格式為 WebM 或 MP4 的影片。"\n    },\n    {\n      "label": "外觀",\n      "fields": [\n        {\n          "label": "影片縮圖"\n        },\n        {\n          "label": "影片播放器自動調整成最大畫面",\n          "description": "如果不勾選，影片會依原始尺寸比例播放。"\n        },\n        {\n          "label": "顯示影片播放控制項",\n          "description": "在播放器下顯示影片控制項，讓用戶能夠使用暫停、靜音等功能。"\n        }\n      ]\n    },\n    {\n      "label": "播放",\n      "fields": [\n        {\n          "label": "影片自動播放",\n          "description": "在連結影片後自動播放。在行動裝置上可能無效。"\n        },\n        {\n          "label": "影片循環播放",\n          "description": "在影片播放完後會重新播放。"\n        }\n      ]\n    },\n    {\n      "label": "本地化",\n      "fields": [\n        {\n          "label": "形式的名稱",\n          "default": "影片",\n          "description": "幫助識別這個內容的形式。"\n        },\n        {\n          "label": "正在載入的顯示文字",\n          "default": "影片播放器正在載入…"\n        },\n        {\n          "label": "找不到播放器的顯示文字",\n          "default": "找不到支援此影片格式的播放器。"\n        },\n        {\n          "label": "找不到來源的顯示文字",\n          "default": "找不到影片來源。"\n        },\n        {\n          "label": "中止的顯示文字",\n          "default": "媒體播放已中止。"\n        },\n        {\n          "label": "網路異常的顯示文字",\n          "default": "網路異常。"\n        },\n        {\n          "label": "無法解析媒體的顯示文字",\n          "default": "無法解析媒體。"\n        },\n        {\n          "label": "不支援的格式的顯示文字",\n          "default": "不支援的格式"\n        },\n        {\n          "label": "媒體已加密的顯示文字",\n          "default": "媒體已加密。"\n        },\n        {\n          "label": "未知的錯誤的顯示文字",\n          "default": "未知的錯誤。"\n        },\n        {\n          "label": "無效的 YouTube ID 的顯示文字",\n          "default": "無效的 YouTube ID。"\n        },\n        {\n          "label": "未知的 YouTube ID 的顯示文字",\n          "default": "無法找到與這個 YouTube ID 關聯的影片。"\n        },\n        {\n          "label": "受限制的 YouTube 影片的顯示文字",\n          "default": "影片的上傳者不允許用嵌入的方式觀看影片。"\n        }\n      ]\n    },\n    {\n      "label": "無障礙功能",\n      "fields": [\n        {\n          "label": "添加影片字軌",\n          "entity": "字軌",\n          "field": {\n            "label": "字軌",\n            "fields": [\n              {\n                "label": "字軌的說明文字"\n              },\n              {\n                "label": "格式請參考 <a target=\\"_blank\\" href=\\"https://html.spec.whatwg.org/multipage/embedded-content.html#the-track-element\\">HTML 現況標準</a>",\n                "options": [\n                  {\n                    "label": "字幕"\n                  },\n                  {\n                    "label": "標題"\n                  },\n                  {\n                    "label": "說明"\n                  },\n                  {\n                    "label": "章節"\n                  }\n                ]\n              },\n              {\n                "label": "語言代碼",\n                "description": "若字軌是字幕的話，必須要定義。需符合 BCP 47 的語言標記，例如 en 為英文、zh 為中文。"\n              },\n              {\n                "label": "字軌來源（格式為 WebVTT）"\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}\n'),
