(42, 'it', '{\n  "libraryStrings": {\n    "exceedsMin": "\\":property\\" supera il valore minimo di:min",\n    "fromBiggerThanTo": "\\"Da\\" deve precedere \\"A\\"",\n    "invalidTime": "\\":property\\" contiene un formato orario non valido"\n  }\n}\n'),
(42, 'ka', '{\n  "libraryStrings": {\n    "exceedsMin": "\\":property\\" აჭარბებს :min-ის მინიმალურ მნიშვნელობას.",\n    "fromBiggerThanTo": "\\"From\\" უნდა იყოს უფრო ადრეული, ვიდრე \\"To\\".",\n    "invalidTime": "\\":property\\" შეიცავს დროის დაუშვებელ ფორმატს."\n  }\n}\n'),
(42, 'ko', '{\n  "libraryStrings": {\n    "exceedsMin": "\\":property\\" (속성)이 최소값 :min 을 초과합니다.",\n    "fromBiggerThanTo": "\\"From\\" 은 \\"To\\" 보다 앞서야 합니다.",\n    "invalidTime": "\\":property\\" (속성)은 유효하지 않은 시간 포맷을 포함하고 있습니다."\n  }\n}\n'),
(42, 'lt', '{\n  "libraryStrings": {\n    "exceedsMin": "\\":property\\" viršija minimalią :min reikšmę.",\n    "fromBiggerThanTo": "„Nuo“ turi būti ankstesnė nei „Iki“.",\n    "invalidTime": "„:property“ yra netinkamas laiko formatas."\n  }\n}\n'),
