": "ამ პარამეტრებით შეგიძლიათ გადააწეროთ სოციალური ქცევის პარამეტრებს.",\n          "fields": [\n            {\n              "label": "აჩვენე ფეისბუქზე გაზიარების ღილაკი"\n            },\n            {\n              "label": "ფეისბუქზე გაზიარების პარამეტრები",\n              "fields": [\n                {\n                  "label": "ფეისბუქზე გაზიარების ბმული",\n                  "default": "@currentpageurl"\n                },\n                {\n                  "label": "ფეისბუქზე გაზიარების ტექსტი",\n                  "default": "მე მივიღე @score ქულა @maxScore დან დავალებაში @currentpageurl."\n                }\n              ]\n            },\n            {\n              "label": "აჩვენე ტვიტერზე გაზიარების ღილაკი"\n            },\n            {\n              "label": "ტვიტრერზე გაზიარების პარამეტრები",\n              "fields": [\n                {\n                  "label": "ტვიტერზე გაზიარების ტექსტი",\n                  "default": "მე მივიღე @score ქულა @maxScore დან დავალებაში @currentpageurl."\n                },\n                {\n                  "label": "ტვიტერზე გაზიარების ბმული",\n                  "default": "@currentpageurl"\n                },\n                {\n                  "label": "ტვიტერზე გაზიარების ჰეშთეგი",\n                  "default": "h5p, კურსი"\n                }\n              ]\n            },\n            {\n              "label": "აჩვენე Google+ გაზიარების ღილაკი"\n            },\n            {\n              "label": "გააზიარე Google-ის ბმულში",\n              "default": "@currentpageurl"\n            }\n          ]\n        }\n      ]\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(56, 'km', '{\n  "semantics": [\n    {\n      "fields": [\n        {\n          "field": {\n            "fields": [\n              {\n                "field": {\n                  "fields": [\n                    {},\n                    {},\n                    {},\n                    {},\n                    {},\n                    {\n                      "label": "មតិ",\n                      "description": "មតិត្រូវបានបង្ហាញនៅពេលដែលគេមើលចម្លើយដែលត្រូវបានណែនាំសម្រាប់ស្លាយទាំងអស់។"\n                    },\n                    {\n                      "label": "បង្ហាញមតិរហូត"\n                    },\n                    {\n                      "label": "កម្រិតថ្លានៃផ្ទៃខាងក្រោយ"\n                    },\n                    {\n                      "label": "បង្ហាញជាប៊ូតុង"\n                    },\n                    {\n                      "label": "ទំហំប៊ូតុង",\n                      "options": [\n                        {\n                          "label": "តូច"\n                        },\n                        {\n                          "label": "ធំ"\n                        }\n                      ]\n                    },\n                    {\n                      "label": "ចំណងជើង"\n                    },\n                    {\n                      "label": "ទៅ",\n                      "options": [\n                        {\n                          "label": "លេខស្លាយជាក់លាក់"\n                        },\n                        {\n                          "label": "ស្លាយបន្ទាប់"\n                        },\n                        {\n                          "label": "ស្លាយមុន"\n                        }\n                      ]\n                    },\n                    {\n                      "label": "លេខស្លាយជាក់លាក់",\n                      "description": "មានប្រសិទ្ធភាពតែនៅពេលដែល ''លេខស្លាយជាក់លាក់'' ត្រូវបានជ្រើសរើស"\n                    },\n                    {\n                      "label": "មើលមិនឃើញ",\n                      "description": "រូបម៉ៅស៍ធម្មតា គ្មានចំណងជើង ហើយមិនអាចប្រើគ្រាប់ចុច tab ទេ។ ប្រយ័ត្ន៖ ជនពិការ ឫអ្នកដែលប្រើតែក្តារចុចនឹងមានបញ្ហាប្រើប្រាស់ធាតុនេះទេ។"\n                    }\n                  ]\n                }\n              },\n              {},\n              {\n                "fields": [\n                  {\n                    "label": "រូបភាព",\n                    "description": "រូបភាពផ្ទៃខាងក្រោយគួរមានសមាមាត្រ 2:1 ដើម្បីកុំឲ្យវាខុសទ្រង់ទ្រាយ។ រូបភាពដែលមានគុណភាពកាន់តែខ្ពស់នឹងបង្ហាញកាន់តែល្អនៅលើអេក្រង់ធំ។"\n                  },\n                  {\n                    "label": "រើសពណ៌"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {},\n        {\n          "label": "បញ្ជីពាក្យគន្លឹះ"\n        },\n        {\n          "label": "បង្ហាញរហូត"\n        },\n        {\n          "label": "លាក់ស្វ័យប្រវត្តិ"\n        },\n        {\n          "label": "កម្រិតថ្លា"\n        },\n        {\n          "fields": [\n            {\n              "label": "រូបភាព",\n              "description": "រូបភាពផ្ទៃខាងក្រោយគួរមានសមាមាត្រ 2:1 ដើម្បីកុំឲ្យវាខុសទ្រង់ទ្រាយ។ រូបភាពដែលមានគុណភាពកាន់តែខ្ពស់នឹងបង្ហាញកាន់តែល្អនៅលើអេក្រង់ធំ។"\n            },\n            {\n              "label": "រើសពណ៌"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Localize",\n      "fields": [\n        {\n          "label": "ពាក្យប្រើសម្រាប់ \\"ស្លាយ (Slide)\\"",\n          "default": "ស្លាយ"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ \\"ពិន្ទុ (Score)\\"",\n          "default": "ពិន្ទុ"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ \\"ពិន្ទុរបស់អ្នក (Your Score)\\"",\n          "default": "ពិន្ទុរបស់អ្នក"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ \\"ពិន្ទុអតិបរមា (Max Score)\\"",\n          "default": "ពិន្ទុអតិបរមា"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ \\"សរុប (Total)\\"",\n          "default": "សរុប"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ \\"ពិន្ទុសរុប (Total Score)\\"",\n          "default": "ពិន្ទុសរុប"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ប៊ូតុង \\"បង្ហាញចម្លើយត្រូវ\\"",\n          "default": "បង្ហាញចម្លើយត្រូវ"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ប៊ូតុង \\"សាកម្តងទៀត\\"",\n          "default": "សាកម្តងទៀត"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ប៊ូតុង \\"នាំចេញអត្ថបទ\\"",\n          "default": "នាំចេញអត្ថបទ"\n        },\n        {\n          "label": "ចំណងជើងសម្រាប់ប៊ូតុង \\"លាក់បញ្ជីពាក្យគន្លឹះ\\"",\n          "default": "លាក់បញ្ជីពាក្យគន្លឹះ"\n        },\n        {\n          "label": "ចំណងជើងសម្រាប់ប៊ូតុង \\"បង្ហាញបញ្ជីពាក្យគន្លឹះ\\"",\n          "default": "បង្ហាញបញ្ជីពាក្យគន្លឹះ"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ \\"ពេញអេក្រង់\\"",\n          "default": "ពេញអេក្រង់"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ «បិទពេញអេក្រង់»",\n          "default": "បិទពេញអេក្រង់"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ «ស្លាយមុន»",\n          "default": "ស្លាយមុន"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ «ស្លាយបន្ទាប់»",\n          "default": "ស្លាយបន្ទាប់"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ «ស្លាយបច្ចុប្បន្ន»",\n          "default": "ស្លាយបច្ចុប្បន្ន"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ «ស្លាយចុងក្រោយ»",\n          "default": "ស្លាយចុងក្រោយ"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ ចាកចេញពីម៉ូត «ចម្លើយត្រឹមត្រូវ»",\n          "default": "ចាកចេញពីម៉ូត «ចម្លើយត្រឹមត្រូវ»"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ ម៉ូត «ចម្លើយត្រឹមត្រូវ»",\n          "default": "ម៉ូត «ចម្លើយត្រឹមត្រូវ»"\n        },\n        {\n          "label": "អត្ថបទសម្រាប់ពេលដែលមានកិច្ចការច្រើនលើទំព័រមួយ",\n          "default": "កិច្ចការច្រើន"\n        },\n        {\n          "label": "អត្ថបទសម្រាប់សារអំពីពិន្ទុ",\n          "default": "អ្នកទទួលបាន:"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ «ចែករំលែកនៅលើហ្វេសប៊ូក»",\n          "default": "ចែករំលែកនៅលើហ្វេសប៊ូក"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ «ចែករំលែកនៅលើធ្វីតធឺរ»",\n          "default": "ចែករំលែកនៅលើធ្វីតធឺរ"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ «ចែករំលែកនៅលើ Google+»",\n          "default": "ចែករំលែកនៅលើ Google+"\n        },\n        {\n          "label": "ចំណងជើងសម្រាប់ស្លាយសង្ខេប",\n          "default": "សង្ខេប"\n        },\n        {\n          "label": "ចំណងជើងសម្រាប់រូបតំណងមតិ",\n          "default": "បង្ហាញមតិ"\n        },\n        {\n          "label": "ចំណងជើងសម្រាប់ប៊ូតុងបោះពុម្ភ",\n          "default": "បោះពុម្ភ"\n        },\n        {\n          "label": "សំណួរក្នុងផ្ទាំងពេលបោះពុម្ភ",\n          "default": "តើអ្នកចង់បោះពុម្ពបទបង្ហាញរបស់អ្នករបៀបណា?"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ប៊ូតុង \\"បោះពុម្ពស្លាយទាំងអស់ (Print all slides)\\"",\n          "default": "បោះពុម្ពស្លាយទាំងអស់"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ប៊ូតុង \\"បោះពុម្ភស្លាយបច្ចុប្បន្ន (Print current slide)\\"",\n          "default": "បោះពុម្ភស្លាយបច្ចុប្បន្ន"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ស្លាយគ្មានចំណងជើង",\n          "default": "គ្មានចំណងជើង"\n        },\n        {\n          "label": "ពាក្យពន្យល់សម្រាប់ការផ្លាស់ទីរវាងស្លាយ",\n          "default": "ប្រើច្នុចព្រួញឆ្វេងស្តាំដើម្បីផ្លាស់ប្តូរស្លាយ។"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ ផ្ទាំងបទបង្ហាញ សម្រាប់បច្ចេកវិទ្យាជំនួយ",\n          "default": "ផ្ទាំងបទបង្ហាញ។ ប្រើច្នុចព្រួញឆ្វេងស្តាំដើម្បីផ្លាស់ប្តូរស្លាយ។"\n        },\n        {\n          "label": "Progressbar label for assistive technologies",\n          "default": "Choose slide to display"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់អន្តរកម្មដែលមិនបានបញ្ចប់",\n          "default": "ស្លាយ «@slideName» មានកិច្ចការអន្តរកម្មដែលមិនបានបញ្ចប់"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់អន្តរកម្មដែលបានបញ្ចប់",\n          "default": "ស្លាយ «@slideName» មានកិច្ចការអន្តរកម្មដែលបានបញ្ចប់"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់របាប់ស្លាយ។ អនុញ្ញាតមាន @index, @total",\n          "default": "ស្លាយ @index ក្នុងចំណោម @total"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ស្លាយដែលមានតែចម្លើយត្រឹមត្រូវ",\n          "default": "ស្លាយ «@slideName» មានតែចម្លើយដែលត្រឹមត្រូវ។"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់ស្លាយណាដែលគ្មានត្រឹមត្រូវ",\n          "default": "ស្លាយ «@slideName» មានចម្លើយមិនត្រឹមត្រូវ។"\n        },\n        {\n          "label": "ពាក្យប្រើសម្រាប់របារបណ្តាញសង្គម",\n          "default": "ចែករំលែកលទ្ធផល"\n        },\n        {\n          "label": "ពាក្យប្រកាសអំពីពិន្ទុ សម្រាប់បច្ចេកវិទ្យាជំនួយ",\n          "default": "អ្នកទទួលបានពិន្ទុ @score លើ @maxScore",\n          "description": "អនុញ្ញាតដែលអាចប្រើបាន @score និង @maxScore"\n        },\n        {\n          "label": "ពាក្យប្រកាសនៅពេលពេញអេក្រង់ត្រូវបានចូលសម្រាប់បច្ចេកវិទ្យាជំនួយ",\n          "default": "បានបើក «ពេញអេក្រង់»"\n        },\n        {\n          "label": "ពាក្យប្រកាសនៅពេលពេញអេក្រង់ត្រូវបានចាកចេញសម្រាប់បច្ចេកវិទ្យាជំនួយ",\n          "default": "បានបិទ «ពេញអេក្រង់»"\n        },\n        {\n          "label": "Header of submit result confirmation dialog",\n          "default": "Submit your answers"\n        },\n        {\n          "label": "Text of submit result confirmation dialog",\n          "default": "This will submit your results, do you want to continue?"\n        },\n        {\n          "label": "Confirmation button of submit result confirmation dialog",\n          "default": "Submit and see results"\n        },\n        {\n          "label": "Slideshow navigation",\n          "default": "Slideshow navigation"\n        },\n        {\n          "label": "Confirm button label",\n          "default": "Confirm"\n        },\n        {\n          "label": "Cancel button label",\n          "default": "Cancel"\n        }\n      ]\n    },\n    {\n      "label": "ការកំណត់មុខងារ",\n      "description": "ជម្រើសទាំងនេះនឹងអនុញ្ញាតឲ្យអ្នកបង្ខំការកំណត់ផ្សេងៗ។",\n      "fields": [\n        {\n          "label": "បើកម៉ូត Active Surface",\n          "description": "Removes navigation controls for the end user. Use Go To Slide to navigate. Summary is not available in this mode."\n        },\n        {\n          "label": "លាក់ស្លាយសង្ខេប",\n          "description": "លាក់ស្លាយសង្ខេប។"\n        },\n        {\n          "label": "បង្ខំប៊ូតុង \\"បង្ហាញចម្លើយត្រឹមត្រូវ\\"",\n          "description": "ជម្រើសនេះកំណត់ថាតើប៊ូតុង \\"បង្ហាញចម្លើយត្រឹមត្រូវ\\" នឹងត្រូវបង្ហាញសម្រាប់សំណួរទាំងអស់ បិទទាំងអស់ ឬ ត្រូវកំណត់សម្រាប់សំណួរមួយៗ ។",\n          "options": [\n            {\n              "label": "បើក"\n            },\n            {\n              "label": "បិទ"\n            }\n          ]\n        },\n        {\n          "label": "បង្ខំប៊ូតុង \\"សាកម្ដងទៀត\\"",\n          "description": "ជម្រើសនេះកំណត់ថាតើប៊ូតុង \\"សាកម្ដងទៀត\\" នឹងត្រូវបង្ហាញសម្រាប់សំណួរទាំងអស់ បិទទាំងអស់ ឬ ត្រូវកំណត់សម្រាប់សំណួរមួយៗ ។",\n          "options": [\n            {\n              "label": "បើក"\n            },\n            {\n              "label": "បិទ"\n            }\n          ]\n        },\n        {\n          "label": "បង្ហាញប៊ូតុង \\"បង្ហាញចម្លើយត្រឹមត្រូវ\\" ក្នុងស្លាយសង្ខេប",\n          "description": "ប្រសិនបើបើក នោះសិស្សនឹងអាចមើលចម្លើយសម្រាប់សំណួរទាំងអស់នៅពេលដែលគេមកដល់ស្លាយសង្ខេប។"\n        },\n        {\n          "label": "បង្ហាញប៊ូតុង \\"សាកម្តងទៀត\\" ក្នុងស្លាយសង្ខេប",\n          "description": "ប្រសិនបើបើក នោះសិស្សនឹងអាចធ្វើសំណួរទាំងអស់ម្តងទៀតនៅពេលដែលគេមកដល់ស្លាយសង្ខេប។ សូមបញ្ជាក់ថាបើទោះជាប៊ូតុងមិនបង្ហាញក័ដោយក៏សិស្សនៅតែអាចធ្វើលំហាត់ម្តងទៀតបានដែរដោយគ្រាប់តែដំណើរការទំព័រឡើងវិញ ។"\n        },\n        {\n          "label": "បើកប៊ូតុងបោះពុម្ភ",\n          "description": "បើកប៊ូតុងបោះពុម្ភ"\n        },\n        {\n          "label": "ការកំណត់សម្រាប់បណ្តាញសង្គម",\n          "description": "ជម្រើសទាំងនេះនឹងឲ្យអ្នកបង្ខំនូវការកំណត់ប