(57, 'mn', '{\n  "semantics": [\n    {\n      "label": "Гарчиг"\n    },\n    {\n      "label": "Төлөв",\n      "description": "Харилцан ярианы картыг харуулах төлөв",\n      "options": [\n        {\n          "label": "Энгийн"\n        },\n        {\n          "label": "Давталт"\n        }\n      ]\n    },\n    {\n      "label": "Даалгаврын тайлбар"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Өгөгдмөл"\n        }\n      ],\n      "label": "Харилцах цонхнууд",\n      "entity": "харилцах цонх",\n      "field": {\n        "label": "Асуулт",\n        "fields": [\n          {\n            "label": "Текст",\n            "description": "Харилцааны эхний хэсэгт зориулсан зөвлөмж"\n          },\n          {\n            "label": "Хариулт",\n            "description": "Харилцааны хоёр дахь хэсэгт зориулсан зөвлөмж"\n          },\n          {\n            "label": "Зураг",\n            "description": "Картын нэмэлт зураг. (Карт зөвхөн зураг, текст эсвэл хоёуланг нь хэрэглэж болно)"\n          },\n          {\n            "label": "Зургийн өөр текст"\n          },\n          {\n            "label": "Аудио файлууд"\n          },\n          {\n            "label": "Зөвлөмж",\n            "fields": [\n              {\n                "label": "Текстийн зөвлөгөө",\n                "description": "Ярилцлагын эхний хэсэгт зориулсан зөвлөгөө"\n              },\n              {\n                "label": "Хариултанд өгөх зөвлөмж",\n                "description": "Харилцааны хоёр дахь хэсэгт зориулсан зөвлөгөө"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Зан үйлийн тохиргоо",\n      "description": "Энэхүү сонголт нь таныг даалгавруудыг удирдах боломжоор хангана.",\n      "fields": [\n        {\n          "label": "\\"Дахин эхлэх\\" товчыг идэвхжүүлэх"\n        },\n        {\n          "label": "Хойшлуулах навигацыг идэвхгүй болгох",\n          "description": "Энэхүү сонголт нь Харилцан ярианы картыг урагш явуулах