(64, 'nl', '{\n  "semantics": [\n    {\n      "label": "Quiz inleiding",\n      "fields": [\n        {\n          "label": "Toon inleiding"\n        },\n        {\n          "label": "Titel",\n          "description": "Deze titel zal boven de inleidende tekst worden getoond."\n        },\n        {\n          "label": "Inleidende tekst",\n          "description": "Deze tekst zal worden getoond voordat de quiz begint."\n        },\n        {\n          "label": "Tekst van \\"Start\\"-knop",\n          "default": "Start quiz"\n        },\n        {\n          "label": "Achtergrondafbeelding",\n          "description": "Een optionele achtergrondafbeelding voor de inleiding."\n        }\n      ]\n    },\n    {\n      "label": "Achtergrondafbeelding",\n      "description": "Een optionele achtergrondafbeelding voor de vragenreeks."\n    },\n    {\n      "label": "Voortgangsindicator",\n      "description": "Stijl van voortgangsindicator van de vragenreeks.",\n      "options": [\n        {\n          "label": "Tekstueel"\n        },\n        {\n          "label": "Punten"\n        }\n      ]\n    },\n    {\n      "label": "Slagingspercentage",\n      "description": "Percentage van totale score dat vereist is om te slagen voor quiz."\n    },\n    {\n      "label": "Vragen",\n      "widgets": [\n        {\n          "label": "Standaard"\n        },\n        {\n          "label": "Tekstueel"\n        }\n      ],\n      "entity": "vraag",\n      "field": {\n        "label": "Type vraag",\n        "description": "Bibliotheek voor deze vraag."\n      }\n    },\n    {\n      "label": "Interface teksten in de quiz",\n      "fields": [\n        {\n          "label": "Tekst van \\"Terug\\"-knop",\n          "default": "Vorige vraag"\n        },\n        {\n          "label": "Tekst van \\"Volgende\\"-knop",\n          "default": "Volgende vraag"\n        },\n        {\n          "label": "Tekst van \\"Afsluiten\\"-knop",\n          "default": "Stoppen"\n        },\n        {\n      