(67, 'zh-hans', '{\n  "semantics": [\n    {\n      "label": "预览",\n      "description": "用拖曳方式可改变平移图片，用键盘上的 + 或 - 键或是按住 Z 键加滑鼠滚轮可放大图片。",\n      "fields": [\n        {\n          "label": "版型",\n          "options": [\n            {\n              "label": "1"\n            },\n            {\n              "label": "1-1"\n            },\n            {\n              "label": "2"\n            },\n            {\n              "label": "2-1"\n            },\n            {\n              "label": "1-2"\n            },\n            {\n              "label": "2-2"\n            },\n            {\n              "label": "3-1"\n            },\n            {\n              "label": "1-3"\n            },\n            {\n              "label": "2-3"\n            },\n            {\n              "label": "3-2"\n            },\n            {\n              "label": "3-3"\n            }\n          ]\n        },\n        {\n          "label": "显示设定",\n          "fields": [\n            {\n              "label": "高度"\n            },\n            {\n              "label": "间距"\n            },\n            {\n              "label": "边框"\n            }\n          ]\n        },\n        {\n          "label": "所有图片",\n          "entity": "修剪",\n          "field": {\n            "label": "图片",\n            "fields": [\n              {\n                "label": "图像"\n              },\n              {\n                "label": "位移",\n                "fields": [\n                  {\n                    "label": "靠上"\n                  },\n                  {\n                    "label": "靠左"\n                  }\n                ]\n              },\n              {\n                "label": "替代文字",\n                "description": "必填，当浏览器无法载入图片时显示的文字，同时也用在报读器。"\n              },\n              {\n                "label": "悬停时文字",\n                "description": "非必填，当使用者悬停在图片时额外显示的文字。"\n              },\n              {\n                "label": "缩放"\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}\n'),
(67, 'zh-hant', '{\n  "semantics": [\n    {\n      "label": "預覽",\n      "description": "用拖曳方式可改變平移圖片，用鍵盤上的 + 或 - 鍵或是按住 Z 鍵加滑鼠滾輪可大圖片。",\n      "fields": [\n        {\n          "label": "版型",\n          "options": [\n            {\n              "label": "1"\n            },\n            {\n              "label": "1-1"\n            },\n            {\n              "label": "2"\n            },\n            {\n              "label": "2-1"\n            },\n            {\n              "label": "1-2"\n            },\n            {\n              "label": "2-2"\n            },\n            {\n              "label": "3-1"\n            },\n            {\n              "label": "1-3"\n            },\n            {\n              "label": "2-3"\n            },\n            {\n              "label": "3-2"\n            },\n            {\n              "label": "3-3"\n            }\n          ]\n        },\n        {\n          "label": "顯示設定",\n          "fields": [\n            {\n              "label": "高度"\n            },\n            {\n              "label": "間距"\n            },\n            {\n              "label": "邊框"\n            }\n          ]\n        },\n        {\n          "label": "所有圖片",\n          "entity": "clip",\n          "field": {\n            "label": "圖片",\n            "fields": [\n              {\n                "label": "圖像"\n              },\n              {\n                "label": "位移",\n                "fields": [\n                  {\n                    "label": "靠上"\n                  },\n                  {\n                    "label": "靠左"\n                  }\n                ]\n              },\n              {\n                "label": "替代文字",\n                "description": "必填，當瀏覽器無法載入圖片時顯示的文字，同時也用在報讀器。"\n              },\n              {\n                "label": "懸停時文字",\n                "description": "非必填，當使用者懸停在圖片時額外顯示的文字。"\n              },\n              {\n                "label": "縮放"\n              }\n            ]\n       