(68, 'af', '{\n  "semantics": [\n    {\n      "label": "Lys van kolominhoud",\n      "entity": "inhoud",\n      "field": {\n        "fields": [\n          {\n            "label": "Inhoud"\n          },\n          {\n            "label": "Skei die inhoud met ''n horisontale liniaal",\n            "options": [\n              {\n                "label": "Outomaties (verstek)"\n              },\n              {\n                "label": "Moet nooit liniaal hierbo gebruik nie"\n              },\n              {\n                "label": "Gebruik altyd die liniaal hierbo"\n              }\n            ]\n          }\n        ]\n      }\n    }\n  ]\n}\n'),
(68, 'ar', '{\n  "semantics": [\n    {\n      "label": "قائمة بمحتوى العمود",\n      "entity": "المحتوى",\n      "field": {\n        "fields": [\n          {\n            "label": "المحتوى"\n          },\n          {\n            "label": "محتوى منفصل مع مسطرة أفقية",\n            "options": [\n              {\n                "label": "اتوماتيكي ( افتراضي )"\n              },\n              {\n                "label": "لا تستخدم ابدا المسطرة اعلاه"\n              },\n              {\n                "label": "استخدم دومًا المسطرة أعلاه"\n              }\n            ]\n          }\n        ]\n      }\n    }\n  ]\n}\n'),
(68, 'bg', '{\r\n  "semantics": [\r\n    {\r\n      "label": "Списък на съдържание Колони",\r\n      "entity": "съдържание",\r\n      "field": {\r\n        "fields": [\r\n          {\r\n            "label": "Съдържание"\r\n          },\r\n          {\r\n            "label": "Разделете съдържанието с хоризонтален линеал",\r\n            "options": [\r\n              {\r\n                "label": "Автоматично (по подразбиране)"\r\n              },\r\n              {\r\n                "label": "Никога не използвайте линеал по-горе"\r\n              },\r\n              {\r\n                "label": "Винаги използвайте линеал по-горе"\r\n              }\r\n            ]\r\n          }\r\n        ]\r\n      }\r\n    }\r\n  ]\r\n}\r\n'),
(68, 'bs', '{\n  "semantics":[\n    {\n      "label":"lista sadržaja stupca",\n      "entity":"sadržaj",\n      "field":{\n        "fields":[\n          {\n            "label":"Sadržaj"\n          },\n          {\n            "label":"Razdvoji sadržaje sa linijom",\n            "options":[\n              {\n                "label":"Automatski (default)"\n              },\n              {\n                "label":"Nikad ne koristi razdvajanje gore"\n              },\n              {\n                "label":"Uvijek koristi razdvajanje gore"\n              }\n            ]\n          }\n        ]\n      }\n    }\n  ]\n}\n'),
(68, 'ca', '{\n  "semantics": [\n    {\n      "label": "Llista del contingut de la columna",\n      "entity": "contingut",\n      "field": {\n        "fields": [\n          {\n            "label": "Contingut"\n          },\n          {\n            "label": "Separa el contingut amb un regle horitzontal",\n            "options": [\n              {\n                "label": "Automàtic (opció predeterminada)"\n              },\n              {\n                "label": "No utilitzis mai el regle de la part superior"\n              },\n              {\n                "label": "Utilitza sempre el regle de la part superior"\n              }\n            ]\n          }\n        ]\n      }\n    }\n  ]\n}\n'),
