(68, 'cy', '{\n  "semantics": [\n    {\n      "label": "Rhestr o Gynnwys y Golofn",\n      "entity": "cynnwys",\n      "field": {\n        "fields": [\n          {\n            "label": "Cynnwys"\n          },\n          {\n            "label": "Gwahanwch gynnwys gyda mesurydd llorweddol",\n            "options": [\n              {\n                "label": "Awtomatig (diofyn)"\n              },\n              {\n                "label": "Byth yn defnyddio mesurydd uwchben"\n              },\n              {\n                "label": "Wastad yn defnyddio mesurydd uwchben"\n              }\n            ]\n          }\n        ]\n      }\n    }\n  ]\n}\n'),
(68, 'da', '{\n  "semantics":[\n    {\n      "label":"List of Column Content",\n      "entity":"content",\n      "field":{\n        "fields":[\n          {\n            "label":"Content"\n          },\n          {\n            "label":"Separate content with a horizontal ruler",\n            "options":[\n              {\n                "label":"Automatic (default)"\n              },\n              {\n                "label":"Never use ruler above"\n              },\n              {\n                "label":"Always use ruler above"\n              }\n            ]\n          }\n        ]\n      }\n    }\n  ]\n}\n'),
