(69, 'et', '{\n  "semantics": [\n    {\n      "label": "Kirjeldus",\n      "description": "Ekspordilehe kirjeldus.",\n      "default": "Sellel lehel saad eksportida oma teksti, eesmärgid ja eesmärkide hindamised."\n    },\n    {\n      "label": "Loo dokument nupu silt",\n      "description": "Tekst, mida näidatakse \\"Loo dokument\\" nupul.",\n      "default": "Loo dokument"\n    },\n    {\n      "label": "Esita nupu silt",\n      "description": "Tekst, mida näidatakse \\"Esita\\" nupul.",\n      "default": "Esita!"\n    },\n    {\n      "label": "Esitamine õnnestus silt",\n      "default": "Sinu raport esitati edukalt!"\n    },\n    {\n      "label": "Vali kogu eksporditav tekst nupu silt",\n      "description": "Tekst, mida näidatakse \\"Vali kogu tekst\\" nupul.",\n      "default": "Vali kogu tekst"\n    },\n    {\n      "label": "Ekspordi tekst nupu silt",\n      "description": "Tekst, mida näidatakse \\"Ekspordi tekst\\" nupul.",\n      "default": "Ekspordi tekst"\n    },\n    {\n      "label": "Abiteksti silt",\n      "description": "Kasutajale täiendava abiteabe näitamise silt.",\n      "default": "Rohkem teavet"\n    },\n    {\n      "label": "Sisesta täiendav abiteave",\n      "description": "Siia saad sisestada kasutajat täiendavalt aitava teabe."\n    },\n    {\n      "label": "Nõutud sisestusväli on tühi",\n      "description": "Veateave, mida näidatakse, kui üks või mitu sisestusvälja on täitmata. @pages asendatakse mõjutatud lehekülgede pealkirjadega.",\n      "default": "Järgmistel lehekülgedel on väljad, mis tuleb täita enne selle dokumendi esitamist või ülevaatamist: @pages"\n    }\n  ]\n}'),
(69, 'eu', '{\n  "semantics": [\n    {\n      "label": "Deskribapena",\n      "description": "Esportazio orriaren deskribapena.",\n      "default": "Orri honetan aukera duzu zure testua, helburuak eta helburuen ebaluazioak esportatzeko."\n    },\n    {\n      "label": "Sortu dokumentu botoiaren etiketa",\n      "description": "Esportazio orriaren \\"Sortu dokumentua\\"-botoian bistaratuko den testua.",\n      "default": "Sortu dokumentua"\n    },\n    {\n      "label": "Bidali testua botoia",\n      "description": "\\"Bidali\\"-botoian bistaratuko den testua.",\n      "default": "Bidali"\n    },\n    {\n      "label": "Bidalketa arrakastatsuaren etiketa",\n      "default": "Zure txostena ongi bidali da!"\n    },\n    {\n      "label": "Hautatu esportatuko den testu osoa botoiaren etiketa",\n      "description": "\\"Hautatu\\"-botoian bistaratuko den testua.",\n      "default": "Hautatu"\n    },\n    {\n      "label": "Esportatu testua botoiaren etiketa",\n      "description": "\\"Esportatu\\"-botoian bistaratuko den testua.",\n      "default": "Esportatu"\n    },\n    {\n      "label": "Laguntzako testuaren etiketa",\n      "description": "Erabiltzailearentzako informazio gehigarria bistaratzeko etiketa.",\n      "default": "Informazio gehiago"\n    },\n    {\n      "label": "Osatu laguntzako informazio gehigarria",\n      "description": "Bertan zeuk osa dezakezu erabiltzailearentzat lagungarria den informazioa."\n    },\n    {\n      "label": "Beharrezkoa izan eta falta den testua",\n      "description": "Eremu bat edo gehiago betetzea falta dela abisatzen duen errore mezua. @pages eragindako orrien izenburuekin ordezkatuko da.",\n      "default": "Hurrengo orriek dokumentu hau berrikusi edo bidaltzeko osatu beharreko eremuak dituzte: @pages"\n    }\n  ]\n}\n'),
(69, 'fi', '{\n  "semantics": [\n    {\n      "label": "Kuvaus",\n      "description": "Kuvaus tai ohje asiakirjan vientiin.",\n      "default": "Tällä sivulla voit viedä kaiken tekstin, tavoitteet ja tavoitearvioinnit yhtenä asiakirjana."\n    },\n    {\n      "label": "Painikkeen Luo asiakirja teksti",\n      "description": "Teksti näytetään \\"Luo asiakirja\\" -painikkeessa.",\n      "default": "Luo asiakirja"\n    },\n    {\n      "label": "Palaute -painikkeen teksti",\n      "description": "Tämä teksti näytetään \\"Submit\\"-painikkeessa.",\n      "default": "Palauta!"\n    },\n    {\n      "label": "Palautus onnistunut teksti",\n      "default": "Sinun raporttisi palautettiin onnistuneesti!"\n    },\n    {\n      "label": "Teksti painikkeelle Valitse teksti",\n      "description": "Teksti näytetään \\"Valitse teksti\\" -painikkeessa.",\n      "default": "Valitse teksti"\n    },\n    {\n      "label": "Teksti painikkeelle Vie teksti",\n      "description": "Teksti näytetään \\"Vie teksti\\" -painikkeessa.",\n      "default": "Vie teksti"\n    },\n    {\n      "label": "Teksti osoittamaan lisätietoa",\n      "description": "Lisätietoa ilmaiseva teksti käyttäjälle.",\n      "default": "Lisää tietoa"\n    },\n    {\n      "label": "Lisätietoteksti",\n      "description": "Tähän voit täyttää tekstiä lisätietona käyttäjälle."\n    },\n    {\n      "label": "Vaadittava kenttä täytettävä",\n      "description": "Virhe näytetään, kun jokin vaadittava kenttä tai kentät on jätetty täyttämättä. @pages muuttuja kertoo näiden sivujen otsikon.",\n      "default": "Seuraavilta sivuilta puuttuu pakollisia tietoja ne tulee täyttää jotta voit tarkastella tai palauttaa dokumentin: @pages"\n    }\n  ]\n}\n'),
(69, 'fr', '{\n  "semantics": [\n    {\n      "label": "Description",\n      "description": "Description pour la page d''exportation.",\n      "default": "Vous pouvez choisir d''exporter le texte, les objectifs et l''évaluation des objectifs."\n    },\n    {\n      "label": "Intitulé du bouton \\"Créer le document\\"",\n      "description": "Texte qui apparaît sur le bouton \\"Créer le document\\".",\n      "default": "Créer le document"\n    },\n    {\n      "label": "Intitulé du bouton \\"Sélectionner tous les textes\\"",\n      "description": "Texte qui apparaît sur le bouton \\"Sélectionner tous les textes\\".",\n      "default": "Sélectionner tous les textes"\n    },\n    {\n      "label": "Intitulé du bouton \\"Exporter le document\\"",\n      "default": "Exporter le document"\n    },\n    {\n      "label": "Titre du bouton \\"En savoir plus\\"",\n      "description": "Texte qui apparaît sur le bouton pour afficher une information complémentaire utile pour l''utilisateur.",\n      "default": "En savoir plus"\n    },\n    {\n      "label": "Complétez l''information supplémentaire utile",\n      "description": "Ici vous pouvez saisir l''information complémentaire utile pour l''utilisateur.",\n      "default": "Export"\n    },\n    {\n      "label": "Texte d''un champ de saisie requis et non renseigné",\n      "description": "Un message d''erreur qui est affiché si un ou plusieurs champs de saisie requis n''ont pas été renseignés par l''utilisateur.",\n      "default": "Un ou plusieurs champs de saisie requis n''ont pas été renseignés."\n    },\n    {\n      "label": "Fill in additional help information",\n      "description": "Here you can fill in additional helpful information for the user."\n    },\n    {\n      "label": "Required input missing text",\n      "description": "An error message which will be displayed if one or more required input fields have not been filled. @pages will be replaced with the titles of affected pages.",\n      "default": "The following pages contain required fields that need to be filled in order to review or submit this document: @pages"\n    }\n  ]\n}'),
(69, 'gl', '{\n  "semantics": [\n    {\n      "description": "Descrición da páxina de exportación.",\n      "label": "Descrición",\n      "default": "Nesta páxina podes optar por exportar o teu texto, obxectivos e avaliacións de obxectivos."\n    },\n    {\n      "label": "Crear etiqueta do botón do documento",\n      "default": "Crear documento",\n      "description": "Texto que se mostrará no botón \\"Crear documento\\"."\n    },\n    {\n      "description": "Texto que se mostrará no botón \\"Enviar\\".",\n      "label": "Botón Enviar texto",\n      "default": "Enviar"\n    },\n    {\n      "label": "Etiqueta de envío correcto",\n      "default": "O teu informe enviouse correctamente!"\n    },\n    {\n      "label": "Etiqueta bo botón de selección de todo o exportable",\n      "default": "Seleccionar",\n      "description": "Texto que se mostrará no botón \\"Seleccionar todo o texto\\"."\n    },\n    {\n      "description": "Texto que se mostrará no botón \\"Exportar texto\\".",\n      "default": "Exportar",\n      "label": "Etiqueta do botón exportar texto"\n    },\n    {\n      "label": "Etiqueta para o texto de axuda",\n      "default": "Máis información",\n      "description": "Etiqueta para amosar ao usuario información adicional útil."\n    },\n    {\n      "description": "Aquí podes aportar información de axuda adicional para o usuario.",\n      "label": "Escribe información de axuda adicional"\n    },\n    {\n      "description": "Unha mensaxe de erro que se mostrará se non se cubriron un ou máis campos de entrada obrigatorios. @pages substituirase polos títulos das páxinas afectadas.",\n      "label": "Falta texto de entrada obrigatoria",\n      "default": "As páxinas seguintes conteñen campos obrigatorios que deben cubrirse para revisar ou enviar este documento: @pages"\n    }\n  ]\n}\n'),
(69, 'he', '{\n  "semantics": [\n    {\n      "label": "תיאור",\n      "description": "תיאור דף הייצוא.",\n      "default": "בעמוד זה ביכולתכם לבחור את תוכן הייצור, המטרות והערכת המטרות."\n    },\n    {\n      "label": "יצירת תווית לחצן מסמך",\n      "description": "תוכן שיוצג על כפתור \\"יצירת מסמך\\".",\n      "default": "יצירת מסמך"\n    },\n    {\n      "label": "תווית כפתור שמירה",\n      "description": "תוכן שיוצג על כפתור \\"יצירת מסמך\\".",\n      "default": "הגשה"\n    },\n    {\n      "label": "תווית הגשה הצליחה",\n      "default": "הדוח שלך נשלח בהצלחה!"\n    },\n    {\n      "label": "בחירת תווית כפתור ייצוא כל התוכן",\n      "description": "תוכן שיוצג על כפתור \\"בחירת הכול\\".",\n      "default": "בחירה"\n    },\n    {\n      "label": "תווית לחצן ייצוא טקסט",\n      "description": "תוכן שיוצג על כפתור \\"ייצוא תוכן\\".",\n      "default": "יצוא"\n    },\n    {\n      "label": "תווית למלל עזרה",\n      "description": "תווית להצגת מידע מועיל נוסף למשתמש.",\n      "default": "מידע נוסף"\n    },\n    {\n      "label": "הזנת מידע עזרה נוסף",\n      "description": "כאן ניתן למלא מידע שימושי נוסף עבור המשתמש."\n    },\n    {\n      "label": "קלט נדרש כאשר חסר תוכן",\n      "description": "הודעת שגיאה שתוצג אם שדה קלט נדרש אחד או יותר לא מולאו. @pages יוחלפו בכותרות של הדפים המושפעים.",\n      "default": "הדפים הבאים מכילים שדות חובה שיש למלא על מנת לעיין או לשלוח מסמך זה: @pages"\n    }\n  ]\n}\n'),
(69, 'hu', '{\n  "semantics": [\n    {\n      "label": "Description",\n      "description": "Description of the export page.",\n      "default": "On this page you can choose to export your text, goals and goals assessments."\n    },\n    {\n      "label": "Create document button label",\n      "description": "Text that will be displayed on the \\"Create document\\"-button.",\n      "default": "Create document"\n    },\n    {\n      "label": "Submit text button",\n      "description": "Text that will be displayed on the \\"Submit\\"-button.",\n      "default": "Submit"\n    },\n    {\n      "label": "Submit success label",\n      "default": "Your report was submitted successfully!"\n    },\n    {\n      "label": "Select all exportable text button label",\n      "description": "Text that will be displayed on the \\"Select all text\\"-button.",\n      "default": "Select"\n    },\n    {\n      "label": "Export text button label",\n      "description": "Text that will be displayed on the \\"Export text\\"-button.",\n      "default": "Export"\n    },\n    {\n      "label": "Label for help text",\n      "description": "Label for showing additional helpful information to the user.",\n      "default": "More information"\n    },\n    {\n      "label": "Fill in additional help information",\n      "description": "Here you can fill in additional helpful information for the user."\n    },\n    {\n      "label": "Required input missing text",\n      "description": "An error message which will be displayed if one or more required input fields have not been filled. @pages will be replaced with the titles of affected pages.",\n      "default": "The following pages contain required fields that need to be filled in order to review or submit this document: @pages"\n    }\n  ]\n}\n'),
(69, 'it', '{\n  "semantics": [\n    {\n      "label": "Descrizione",\n      "description": "Descrizione della pagina di esportazione",\n      "default": "Da questa pagina puoi scegliere di esportare testo, obiettivi e valutazioni degli obiettivi"\n    },\n    {\n      "label": "Crea etichetta per il pulsante del documento",\n      "description": "Testo che sarà mostrato sul pulsante \\"Crea documento\\"",\n      "default": "Crea documento"\n    },\n    {\n      "label": "Pulsante per l''invio del testo",\n      "description": "Testo che sarà mostrato sul pulsante \\"Invio\\"",\n      "default": "Invio"\n    },\n    {\n      "label": "Etichetta di invio riuscito",\n      "default": "Il tuo report è stato inviato con successo!"\n    },\n    {\n      "label": "Etichetta del pulsante per selezionare tutto il testo esportabile",\n      "description": "Testo che sarà mostrato sul pulsante \\"Seleziona tutto il testo\\"",\n      "default": "Seleziona"\n    },\n    {\n      "label": "Etichetta per il pulsante di esportazione del testo",\n      "description": "Testo che sarà mostrato sul pulsante \\"Esporta testo\\"",\n      "default": "Esporta"\n    },\n    {\n      "label": "Etichetta per il testo di aiuto",\n      "description": "Etichetta per mostrare all''apprendente ulteriori informazioni di aiuto",\n      "default": "Ulteriori informazioni"\n    },\n    {\n      "label": "Aggiungi ulteriori informazioni di aiuto",\n      "description": "Qui puoi aggiungere ulteriori informazioni di aiuto per l''apprendente"\n    },\n    {\n      "label": "Input testuale obbligatorio mancante",\n      "description": "Messaggio di errore che sarà visualizzato se uno o più campi di input obbligatori non sono stati compilati. @pages saranno sostituite con i titoli delle pagine interessate",\n      "default": "Le seguenti pagine contengono campi obbligatori che devono essere riempiti per poter esaminare o inviare questo documento: @pages"\n    }\n  ]\n}\n'),
