(71, 'bs', '{\n  "semantics": [\n    {\n      "label": "Opis",\n      "description": "Opis ciljeva na stranici zadataka.",\n      "default": "Ocijenite ciljeve koje ste odabrali na stranici ciljeva."\n    },\n    {\n      "label": "Tekst za slab rejting",\n      "description": "Tekst za najgori rejting.",\n      "default": "Malo naučeno"\n    },\n    {\n      "label": "Tekst za srednji rejting",\n      "description": "Tekst za srednji rejting.",\n      "default": "Osrednje naučeno"\n    },\n    {\n      "label": "Tekst za visok rejting",\n      "description": "Tekst za visok rejting.",\n      "default": "Dobro naučeno"\n    },\n    {\n      "label": "Tekst za nema ciljeva",\n      "description": "Feedback tekst kada nisu postavljeni ciljevi.",\n      "default": "Niste odabrali još nikakve ciljeve."\n    },\n    {\n      "label": "Tekst za pomoć",\n      "description": "Prikazuje dodatnu pomoć korisniku.",\n      "default": "Više informacija"\n    },\n    {\n      "label": "Dopuni sa dodatnim informacijama.",\n      "description": "Ovdje možete dodati informacije koje će korisniku biti od pomoći."\n    },\n    {\n      "label": "Legend header",\n      "default": "Possible ratings:"\n    },\n    {\n      "label": "Goal header",\n      "default": "Goals"\n    },\n    {\n      "label": "Rating header",\n      "default": "Rating"\n    }\n  ]\n}'),
(71, 'ca', '{\n  "semantics": [\n    {\n      "label": "Descripció",\n      "description": "Descripció de la pàgina d’avaluació dels objectius.",\n      "default": "Avalueu els objectius que heu seleccionat a la pàgina d’objectius."\n    },\n    {\n      "label": "Text per a una puntuació baixa",\n      "description": "Text per a la pitjor puntuació.",\n      "default": "He aprés molt poc"\n    },\n    {\n      "label": "Text per a una puntuació mitjana",\n      "description": "Text per a una puntuació mitjana.",\n      "default": "He aprés força"\n    },\n    {\n      "label": "Text per a una puntuació alta",\n      "description": "Text per a una puntuació excel·lent.",\n      "default": "He aprés molt"\n    },\n    {\n      "label": "Text per quan no hi ha cap objectiu",\n      "description": "Text dels suggeriments quan no s’han creat objectius.",\n      "default": "Encara no heu triat cap objectiu."\n    },\n    {\n      "label": "Etiqueta per al text d’ajuda",\n      "description": "Etiqueta per mostra la informació addicional útil per l’usuari.",\n      "default": "Més informació"\n    },\n    {\n      "label": "Omple la informació addicional d’ajuda",\n      "description": "Aquí pots completar la informació addicional útil per l’usuari."\n    },\n    {\n      "label": "Legend header",\n      "default": "Possible ratings:"\n    },\n    {\n      "label": "Goal header",\n      "default": "Goals"\n    },\n    {\n      "label": "Rating header",\n      "default": "Rating"\n    }\n  ]\n}'),
(71, 'cs', '{\n  "semantics": [\n    {\n      "label": "Popis",\n      "description": "Popis stránky pro hodnocení cílů.",\n      "default": "Ohodnoťte cíle, které jste si vybrali na stránce cílů."\n    },\n    {\n      "label": "Text s nízkým hodnocením",\n      "description": "Text pro nejhorší hodnocení.",\n      "default": "Naučeno málo"\n    },\n    {\n      "label": "Text se středním hodnocením",\n      "description": "Text pro střední hodnocení.",\n      "default": "Něco naučeno"\n    },\n    {\n      "label": "Text s vysokým hodnocením",\n      "description": "Text pro skvělé hodnocení.",\n      "default": "Naučeno hodně"\n    },\n    {\n      "label": "Žádný text cílů",\n      "description": "Text zpětné vazby, pokud nebyly vytvořeny žádné cíle.",\n      "default": "Dosud jste si nevybrali žádné cíle."\n    },\n    {\n      "label": "Popisek pro text nápovědy",\n      "description": "Popisek pro zobrazení dalších užitečných informací uživateli.",\n      "default": "Více informací"\n    },\n    {\n      "label": "Vyplnit další informace v nápovědě",\n      "description": "Zde můžete vyplnit další užitečné informace pro uživatele."\n    },\n    {\n      "label": "Hlavička legendy",\n      "default": "Možná hodnocení:"\n    },\n    {\n      "label": "Hlavička cíle",\n      "default": "Cíle"\n    },\n    {\n      "label": "Záhlaví hodnocení",\n      "default": "Hodnocení"\n    }\n  ]\n}\n'),
