(71, 'pt-br', '{\n  "semantics": [\n    {\n      "label": "Descrição",\n      "description": "Descrição da página de avaliação de objetivos.",\n      "default": "Avalie os objetivos que você escolheu na página de objetivos."\n    },\n    {\n      "label": "Texto para avaliação baixa",\n      "description": "Texto para a pior avaliação.",\n      "default": "Pouco aprendido"\n    },\n    {\n      "label": "Texto para avaliação mediana",\n      "description": "Texto para avaliação mediana.",\n      "default": "Aprendeu algo"\n    },\n    {\n      "label": "Texto para avaliação alta",\n      "description": "Texto para avaliação ótima.",\n      "default": "Aprendeu muito"\n    },\n    {\n      "label": "Texto para nenhum objetivo",\n      "description": "Texto de feedback para quando nenhum objetivo tiver sido criado.",\n      "default": "Você ainda não escolheu nenhum objetivo."\n    },\n    {\n      "label": "Texto do rótulo de ajuda",\n      "description": "Rótulo para mostrar informações adicionais úteis ao usuário.",\n      "default": "Mais informação"\n    },\n    {\n      "label": "Preencha as informações adicionais de ajuda",\n      "description": "Aqui você pode inserir informações adicionais úteis para o usuário."\n    },\n    {\n      "label": "Cabeçalho da legenda",\n      "default": "Possíveis avaliações:"\n    },\n    {\n      "label": "Cabeçalho do objetivo",\n      "default": "Objetivos"\n    },\n    {\n      "label": "Cabeçalho de avaliação",\n      "default": "Avaliação"\n    }\n  ]\n}\n'),
(71, 'sl', '{\n  "semantics": [\n    {\n      "label": "Opis",\n      "description": "Navodilo udeležencem za delo na strani za vrednotenje ciljev.",\n      "default": "Ovrednoti dodane cilje."\n    },\n    {\n      "label": "Najnižja ocena cilja",\n      "description": "Besedilo za vrednotenje najnižje ocene.",\n      "default": "Ni doseženo"\n    },\n    {\n      "label": "Srednja ocena cilja",\n      "description": "Besedilo za vrednotenje srednje ocene.",\n      "default": "Delno doseženo"\n    },\n    {\n      "label": "Najvišja ocena cilja",\n      "description": "Besedilo za vrednotenje najvišje ocene.",\n      "default": "Doseženo"\n    },\n    {\n      "label": "Ni ciljev",\n      "description": "Besedilo za povratne informacije udeležencu, ko cilji nisi bili ustvarjeni.",\n      "default": "Ni izbranih ciljev."\n    },\n    {\n      "label": "Naslov za dodatne informacije",\n      "description": "Besedilo se prikaže kot povezava, ki vodi do dodatnih informacij za udeležence.",\n      "default": "Več informacij"\n    },\n    {\n      "label": "Vsebina dodatnih informacij",\n      "description": "Besedilo se udeležencem prikaže v pogovornem oknu."\n    },\n    {\n      "label": "Naslov legende",\n      "default": "Možne ocene:"\n    },\n    {\n      "label": "Naslov stolpca s cilji",\n      "default": "Cilj"\n    },\n    {\n      "label": "Naslov stolpca z ocenami",\n      "default": "Ocena"\n    }\n  ]\n}\n'),
