(71, 'sv', '{\n  "semantics": [\n    {\n      "label": "Beskrivning",\n      "description": "Beskrivning av sidan för målbedömning.",\n      "default": "Bedöm målen som du har valt på målsidan."\n    },\n    {\n      "label": "Text för låg uppfyllelse",\n      "description": "Text för minst uppfyllelse.",\n      "default": "Lärt mig lite"\n    },\n    {\n      "label": "Text för medium uppfyllelse",\n      "description": "Text för medium uppfyllelse.",\n      "default": "Lärt mig något"\n    },\n    {\n      "label": "Text för hög uppfyllelse",\n      "description": "Text för hög uppfyllelse.",\n      "default": "Lärt mig mycket"\n    },\n    {\n      "label": "Text för inga mål",\n      "description": "Feedback-text när inga mål har skapats.",\n      "default": "Du har inte valt några mål ännu."\n    },\n    {\n      "label": "Etikett för hjälptext",\n      "description": "Etikett för hjälpfull information till användaren.",\n      "default": "Mer information"\n    },\n    {\n      "label": "Fyll i hjälpinformation",\n      "description": "Här kan du fylla i hjälpinformation till användaren."\n    },\n    {\n      "label": "Rubrik",\n      "default": "Möjliga nivåer för uppfyllelse:"\n    },\n    {\n      "label": "Rubrik för mål",\n      "default": "Mål"\n    },\n    {\n      "label": "Rubrik för bedömning",\n      "default": "Bedömning"\n    }\n  ]\n}\n'),
(71, 'sw', '{\n  "semantics": [\n    {\n      "label": "Maelezo",\n      "description": "Maelezo ya ukurasa wa tathmini ya malengo.",\n      "default": "Kadiria malengo ambayo umechagua katika ukurasa wa malengo."\n    },\n    {\n      "label": "Maandishi ya alama ya chini",\n      "description": "Maandishi ya ukadiriaji mbaya zaidi.",\n      "default": "Kujifunza kidogo"\n    },\n    {\n      "label": "Maandishi ya ukadiriaji wa wastani",\n      "description": "Maandishi ya ukadiriaji wa kati.",\n      "default": "Kujifunza kitu"\n    },\n    {\n      "label": "Maandishi ya ukadiriaji wa juu",\n      "description": "Maandishi kwa ukadiriaji mzuri.",\n      "default": "Kujifunza mengi"\n    },\n    {\n      "label": "Hakuna maandishi ya malengo",\n      "description": "Maoni ya maandishi wakati hakuna malengo yaliyoundwa.",\n      "default": "Bado hujachagua malengo yoyote."\n    },\n    {\n      "label": "Lebo ya maandishi ya manufaa",\n      "description": "Lebo ya kuonyesha maelezo ya ziada ya manufaa kwa mtumiaji.",\n      "default": "Maelezo zaidi"\n    },\n    {\n      "label": "Jaza maelezo ya ziada ya manufaa",\n      "description": "Hapa unaweza kujaza maelezo ya ziada kwa manufaa ya mtumiaji."\n    },\n    {\n      "label": "Kichwa cha hadithi",\n      "default": "Ukadiriaji unaowezekana:"\n    },\n    {\n      "label": "Kichwa cha lengo",\n      "default": "Malengo"\n    },\n    {\n      "label": "Kichwa cha ukadiriaji",\n      "default": "Ukadiriaji"\n    }\n  ]\n}\n'),
(71, 'tr', '{\n  "semantics": [\n    {\n      "label": "Açıklama",\n      "description": "Hedef değerlendirme sayfasının açıklaması.",\n      "default": "Hedefler sayfasında seçtiğiniz hedefleri puanlayın."\n    },\n    {\n      "label": "Düşük puan metni",\n      "description": "En kötü puan için metin.",\n      "default": "Az bilgi öğrendin"\n    },\n    {\n      "label": "Orta puan metin",\n      "description": "Orta puan için metin.",\n      "default": "Bazı bilgiler öğrendin"\n    },\n    {\n      "label": "Yüksek puan metni",\n      "description": "Yüksek puan için metin.",\n      "default": "Çok bilgi öğrendin"\n    },\n    {\n      "label": "Hedef metni yok",\n      "description": "Hiçbir hedef oluşturulmadığında geri bildirim metni.",\n      "default": "Henüz bir hedef seçmediniz."\n    },\n    {\n      "label": "Yardım metni için etiket",\n      "description": "Kullanıcıya ek yararlı bilgiler gösteren etiket.",\n      "default": "Daha fazla bilgi"\n    },\n    {\n      "label": "Ek yardım bilgilerini doldurun",\n      "description": "Burada, kullanıcı için ek yararlı bilgileri doldurabilirsiniz."\n    },\n    {\n      "label": "Legend header",\n      "default": "Possible ratings:"\n    },\n    {\n      "label": "Goal header",\n      "default": "Goals"\n    },\n    {\n      "label": "Rating header",\n      "default": "Rating"\n    }\n  ]\n}'),
(71, 'zh', '{\n  "semantics": [\n    {\n      "label": "說明文字",\n      "description": "目標評估頁面上顯示說明。",\n      "default": "評估你為你的目標實踐的程度。"\n    },\n    {\n      "label": "低程度的顯示文字",\n      "description": "目標評估頁面上低程度的顯示文字，像是沒有達成、學到很少、很不滿意。",\n      "default": "沒有達成"\n    },\n    {\n      "label": "中程度的顯示文字",\n      "description": "目標評估頁面上中程度的顯示文字，像是部分達成、學到一些、還算滿意。",\n      "default": "部分達成"\n    },\n    {\n      "label": "高程度的顯示文字",\n      "description": "目標評估頁面上高程度的顯示文字，像是完全達成、學到很多、非常滿意。",\n      "default": "完全達成"\n    },\n    {\n      "label": "無目標內容的顯示文字",\n      "description": "當沒有目標被建立時，在目標評估頁面上顯示的文字。",\n      "default": "你尚未添加任何目標。"\n    },\n    {\n      "label": "幫助按鈕的顯示文字",\n      "description": "目標評估頁面上幫助按鈕的顯示文字，若不需要有幫助或是額外資訊，可留空不填。",\n      "default": "幫助"\n    },\n    {\n      "label": "幫助說明文字",\n      "description": "用來告知用戶以協助其瞭解使用方式的說明內容。"\n    },\n    {\n      "label": "Legend header",\n      "default": "Possible ratings:"\n    },\n    {\n      "label": "Goal header",\n      "default": "Goals"\n    },\n    {\n      "label": "Rating header",\n      "default": "Rating"\n    }\n  ]\n}');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(72, 'ar', '{\n  "semantics": [\n    {\n      "label": "الوصف",\n      "description": "وصف صفحة الاهداف.",\n      "default": "Insert the goals that you have chosen to work with."\n    },\n    {\n      "label": "نص تحديد رابط الهدف",\n      "description": "النص الذي سيتم عرضه على الزر لإنشاء هدف جديد.",\n      "default": "Create a new goal"\n    },\n    {\n      "label": "تسمية لهدف محدد من قبل المستخدم",\n      "description": "النص الذي سيتم عرضه كتسميةعلى الهدف الذي تم انشلؤه من قبل المستخدم.",\n      "default": "User defined goal"\n    },\n    {\n      "label": "تحديد الهدف البديل",\n      "description": "النص الذي سيتم عرضه كبديل عند إنشاء هدف جديد.",\n      "default": "Write here..."\n    },\n    {\n      "label": "نص يشير إلى عدد الأهداف التي تمت إضافتها",\n      "default": "Goals added:",\n      "description": "This text will follow after the amount of goals that is currently created, example: ''Goals added: 5'' where ''Goals added:'' is this text."\n    },\n    {\n      "label": "نص زر \\"تحديد الهدف \\".",\n      "default": "Specification"\n    },\n    {\n      "label": "نص زر \\"حذف الهدف\\".",\n      "default": "Remove"\n    },\n    {\n      "label": "تسمية للنص المساعد",\n      "description": "تسمية لعرض معلومات مفيدة إضافية للمستخدم.",\n      "default": "More information"\n    },\n    {\n      "label": "املأ المعلومات المساعدة الإضافية",\n      "description": "هنا يمكنك ملء معلومات مفيدة إضافية للمستخدم."\n    },\n    {\n      "label": "تحديد موقع تأكيد حذف الهدف",\n      "fields": [\n        {\n          "label": "ترويسة",\n          "default": "Confirm deletion"\n        },\n        {\n          "label": "رسالة",\n          "default": "Are you sure you want to delete this goal?"\n        },\n        {\n          "label": "تسمية زر الالغاء",\n          "default": "Cancel"\n        },\n        {\n          "label": "تسمية زر التأكيد",\n          "default": "Confirm"\n        }\n      ]\n    }\n  ]\n}'),
(72, 'bg', '{\r\n  "semantics": [\r\n    {\r\n      "label": "Описание",\r\n      "description": "Описание на страницата с цели.",\r\n      "default": "Въведете целите, с които сте избрали да работите."\r\n    },\r\n    {\r\n      "label": "Задайте текста на връзката на цел",\r\n      "description": "Текст, който ще се показва на бутона за добавяне на нова цел.",\r\n      "default": "Добавяне на нова цел"\r\n    },\r\n    {\r\n      "label": "Етикет за определена от потребителя цел",\r\n      "description": "Текст, който ще се показва като етикет на добавена от потребителя цел.",\r\n      "default": "Цел, зададена от потребителя"\r\n    },\r\n    {\r\n      "label": "Определяне на контейнер с цели",\r\n      "description": "Текст, който ще се показва като контейнер, когато се създава нова цел.",\r\n      "default": "Пишете тук..."\r\n    },\r\n    {\r\n      "label": "Текст, указващ колко цели са добавени",\r\n      "default": "Добавени цели :",\r\n      "description": "Този текст ще следва след като се създаде текущата цел, например: \\"Добавени цели: 5\\", където \\"Добавени цели:\\" е този текст."\r\n    },\r\n    {\r\n      "label": "Текст за \\"Определи цел\\"-бутон",\r\n      "default": "Спецификация"\r\n    },\r\n    {\r\n      "label": "Текст за \\"Премахни цел\\"-бутон",\r\n      "default": "премахни"\r\n    },\r\n    {\r\n      "label": "Етикет на помощните тестове",\r\n      "description": "Етикет, който показва допълнителна полезна инфожрмация за ученика.",\r\n      "default": "Допълнителна информация"\r\n    },\r\n    {\r\n      "label": "Попълнете допълнителна информация в помощ на ученика",\r\n      "description": "Тук можете да въведете допълнителна полезна информация за ученика."\r\n    },\r\n    {\r\n      "label": "Локализиране на потвърждението за изтриване на цели",\r\n      "fields": [\r\n        {\r\n          "label": "Хедър",\r\n          "default": "Потвърдете изтриването"\r\n        },\r\n        {\r\n          "label": "Съобщение",\r\n          "default": "Сигурно ли е, че искате да изтриете тази цел?"\r\n        },\r\n        {\r\n          "label": "Маркиране на бутона за отмяна",\r\n          "default": "Отмени"\r\n        },\r\n        {\r\n          "label": "Маркиране на бутона за потвърждение",\r\n          "default": "Потвърди"\r\n        }\r\n      ]\r\n    }\r\n  ]\r\n}\r\n'),
(72, 'ca', '{\n  "semantics": [\n    {\n      "label": "Descripció",\n      "description": "Descripció de la pàgina d’objectius.",\n      "default": "Introduïu els objectius que hàgiu triat per treballar-hi."\n    },\n    {\n      "label": "Text de l’enllaç de l’objectiu",\n      "description": "Text que es mostrarà al botó per crear un objectiu nou.",\n      "default": "Crea un objectiu nou"\n    },\n    {\n      "label": "Etiqueta per a un objectiu definit per l’usuari",\n      "description": "Text que es mostrarà al botó d’un objectiu creat per l’usuari.",\n      "default": "Objectiu definit per l’usuari"\n    },\n    {\n      "label": "Defineix l’espai reservat de l’objectiu",\n      "description": "Text que es mostrarà com a espai reservat en crear un objectiu nou.",\n      "default": "Escriviu aquí..."\n    },\n    {\n      "label": "Text que indica quants objectius s’han afegit",\n      "default": "S’han afegit objectius:",\n      "description": "Aquest text es mostrarà després del nombre d’objectius que s’ha creat. Per exemple: \\"Objectius afegits: 5\\", en què \\"Objectius afegits:\\" es correspon a aquest text."\n    },\n    {\n      "label": "Text del botó \\"Especifica l’objectiu\\"",\n      "default": "Especificació"\n    },\n    {\n      "label": "Text del botó \\"Suprimeix l’objectiu\\"",\n      "default": "Suprimeix"\n    },\n    {\n      "label": "Etiqueta per al text d’ajuda",\n      "description": "Etiqueta per mostra la informació addicional útil per l’usuari.",\n      "default": "Més informació"\n    },\n    {\n      "label": "Omple la informació addicional d’ajuda",\n      "description": "Aquí podeu completar la informació addicional útil per l’usuari."\n    },\n    {\n      "label": "Localitzeu la confirmació de la supressió d’objectius",\n      "fields": [\n        {\n          "label": "Encapçalament",\n          "default": "Confirma la supressió"\n        },\n        {\n          "label": "Missatge",\n          "default": "Confirmeu que voleu suprimir aquest objectiu?"\n        },\n        {\n          "label": "Etiqueta del botó \\"Cancel·la\\"",\n          "default": "Cancel·la"\n        },\n        {\n          "label": "Etiqueta del botó \\"Confirma\\"",\n          "default": "Confirma"\n        }\n      ]\n    }\n  ]\n}'),
(72, 'cs', '{\n  "semantics": [\n    {\n      "label": "Popis",\n      "description": "Popis stránky cílů.",\n      "default": "Vložte cíle, se kterými jste se rozhodli pracovat."\n    },\n    {\n      "label": "Definujte text odkazu na cíl",\n      "description": "Text, který se zobrazí na tlačítku pro vytvoření nového cíle.",\n      "default": "Vytvořit nový cíl"\n    },\n    {\n      "label": "Popisek pro uživatelem definovaný cíl",\n      "description": "Text, který bude zobrazen jako popisek u cíle vytvořeného uživatelem.",\n      "default": "Uživatelem definovaný cíl"\n    },\n    {\n      "label": "Definujte zástupný symbol cíle",\n      "description": "Text, který se při vytváření nového cíle zobrazí jako zástupný symbol.",\n      "default": "Pište zde..."\n    },\n    {\n      "label": "Text označující, kolik cílů bylo přidáno",\n      "default": "Přidány cíle:",\n      "description": "Tento text bude následovat po množství aktuálně vytvořených cílů, například: \\"Přidány cíle: 5\\", kde \\"Přidány cíle:\\" je tento text."\n    },\n    {\n      "label": "Text pro tlačítko \\"Určit cíl\\"",\n      "default": "Specifikace"\n    },\n    {\n      "label": "Text pro tlačítko \\"Odstranit cíl\\"",\n      "default": "Odstranit"\n    },\n    {\n      "label": "Popisek pro text nápovědy",\n      "description": "Štítek pro zobrazení dalších užitečných informací uživateli.",\n      "default": "Více informací"\n    },\n    {\n      "label": "Vyplňte další informace nápovědy",\n      "description": "Zde můžete vyplnit další užitečné informace pro uživatele."\n    },\n    {\n      "label": "Localizovat potvrzení vymazání cíle",\n      "fields": [\n        {\n          "label": "Záhlaví",\n          "default": "Potvrdit vymazání"\n        },\n        {\n          "label": "Zpráva",\n          "default": "Opravdu chcete tento cíl smazat?"\n        },\n        {\n          "label": "Popisek tlačítka Zrušit",\n          "default": "Zrušit"\n        },\n        {\n          "label": "Popisek tlačítka Potvrdit",\n          "default": "Potvrdit"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'de', '{\n  "semantics": [\n    {\n      "label": "Beschreibung",\n      "description": "Beschreibung der Zielseite.",\n      "default": "Ziele einfügen, mit denen gearbeitet werden soll."\n    },\n    {\n      "label": "Definieren des Ziel-Linktextes",\n      "description": "Text, der auf dem Button angezeigt wird, um ein neues Ziel zu erstellen.",\n      "default": "Ein neues Ziel erstellen"\n    },\n    {\n      "label": "Label für ein Ziel, das vom Benutzer definiert wurde",\n      "description": "Text, der als Label auf einem benutzerdefinierten Ziel angezeigt wird.",\n      "default": "Benutzerdefiniertes Ziel"\n    },\n    {\n      "label": "Zielplatzhalter definieren",\n      "description": "Text, der als Platzhalter angezeigt wird, wenn ein neues Ziel erstellt wird.",\n      "default": "Hier schreiben..."\n    },\n    {\n      "label": "Text, der angibt, wie viele Ziele hinzugefügt wurden",\n      "default": "Hinzugefügte Ziele:",\n      "description": "Dieser Text folgt nach der Anzahl der Ziele, die momentan erstellt werden, Beispiel: ''Hinzugefügte Ziele: 5'' wo es sich bei dem Text ''Hinzugefügte Ziele:'' um diesen Text handelt."\n    },\n    {\n      "label": "Text für den \\"Ziel spezifizieren\\"-Button",\n      "default": "Spezifikation"\n    },\n    {\n      "label": "Text für den \\"Ziel entfernen\\"-Button",\n      "default": "Entfernen"\n    },\n    {\n      "label": "Label für den Hilfetext",\n      "description": "Hinweistext zum Anzeigen zusätzlicher hilfreicher Informationen für den Benutzer.",\n      "default": "Weitere Informationen"\n    },\n    {\n      "label": "Weitere Hilfsinformationen einfügen",\n      "description": "Hier können zusätzliche hilfreiche Informationen für den Benutzer eingegeben werden."\n    },\n    {\n      "label": "Übersetzung des Bestätigungsdialogs für das Löschen von Zielen",\n      "fields": [\n        {\n          "label": "Überschrift",\n          "default": "Löschen bestätigen"\n        },\n        {\n          "label": "Nachricht",\n          "default": "Bist du sicher, dass du dieses Ziel löschen möchtest?"\n        },\n        {\n          "label": "\\"Abbrechen\\"-Button",\n          "default": "Nein, abbrechen"\n        },\n        {\n          "label": "\\"Bestätigen\\"-Button",\n          "default": "Ja"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'el', '  {\n  "semantics": [\n    {\n      "label": "Περιγραφή",\n      "description": "Περιγραφή της σελίδας με τους στόχους.",\n      "default": "Εισάγετε τους στόχους με τους οποίους έχετε επιλέξει να ασχοληθείτε."\n    },\n    {\n      "label": "Ετικέτα κουμπιού για νέο στόχο",\n      "description": "Κείμενο που θα εμφανίζεται στο κουμπί για τη δημιουργία νέου στόχου.",\n      "default": "Νέος στόχος"\n    },\n    {\n      "label": "Ετικέτα για στόχο καθορισμένο από τον χρήστη",\n      "description": "Κείμενο που θα εμφανίζεται ως ετικέτα σε στόχο που έχει δημιουργηθεί από τον χρήστη.",\n      "default": "Στόχος καθορισμένος από τον χρήστη"\n    },\n    {\n      "label": "Βασικό κείμενο ορισμού νέου στόχου",\n      "description": "Βασικό κείμενο που θα εμφανίζεται κατά τη δημιουργία νέου στόχου.",\n      "default": "Συμπληρώστε εδώ..."\n    },\n    {\n      "label": "Κείμενο που δείχνει πόσοι στόχοι έχουν προστεθεί",\n      "default": "Στόχοι που έχουν προστεθεί:",\n      "description": "Αυτό το κείμενο θα συνοδεύεται από τον αριθμό των στόχων που έχουν δημιουργηθεί τη δεδομένη στιγμή, π.χ.: \\"Στόχοι που έχουν προστεθεί: 5\\"  όπου το \\"Στόχοι που έχουν προστεθεί:\\" αντιστοιχεί στο κείμενο που θα συμπληρώσετε σε αυτό το πεδίο."\n    },\n    {\n      "label": "Ετικέτα κουμπιού καθορισμού στόχου",\n      "default": "Καθορισμός"\n    },\n    {\n      "label": "Ετικέτα κουμπιού αφαίρεσης στόχου",\n      "default": "Αφαίρεση"\n    },\n    {\n      "label": "Ετικέτα βοηθητικού κειμένου",\n      "description": "Ετικέτα για την εμφάνιση πρόσθετων χρήσιμων πληροφοριών στον χρήστη.",\n      "default": "Περισσότερες πληροφορίες"\n    },\n    {\n      "label": "Συμπληρώστε πρόσθετες χρήσιμες πληροφορίες",\n      "description": "Εδώ μπορείτε να συμπληρώσετε πρόσθετες χρήσιμες πληροφορίες για τον χρήστη."\n    },\n    {\n      "label": "Προσαρμογή παραθύρου επιβεβαίωσης διαγραφής του στόχου",\n      "fields": [\n        {\n          "label": "Επικεφαλίδα",\n          "default": "Επιβεβαίωση διαγραφής"\n        },\n        {\n          "label": "Μήνυμα",\n          "default": "Είστε σίγουρος ότι θέλετε να διαγράψετε αυτόν τον στόχο;"\n        },\n        {\n          "label": "Ετικέτα κουμπιού ακύρωσης",\n          "default": "Ακύρωση"\n        },\n        {\n          "label": "Ετικέτα κουμπιού επιβεβαίωσης",\n          "default": "Ναι"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'es', '{\n  "semantics": [\n    {\n      "label": "Descripción",\n      "description": "Descripción de la página de objetivos.",\n      "default": "Escribe los objetivos con los que has elegido trabajar."\n    },\n    {\n      "label": "Texto de enlace para definir objetivo",\n      "description": "Texto mostrado en el botón para crear un nuevo objetivo.",\n      "default": "Crear un nuevo objetivo"\n    },\n    {\n      "label": "Etiqueta para un objetivo definido por el usuario",\n      "description": "Texto mostrado como etiqueta en un objetivo creado por el usuario.",\n      "default": "Objetivo definido por el usuario"\n    },\n    {\n      "label": "Definir texto por defecto para objetivos",\n      "description": "Texto mostrado por defecto cuando se crea un nuevo objetivo.",\n      "default": "Escribe aquí..."\n    },\n    {\n      "label": "Texto que indica cuantos objetivos se han añadido",\n      "default": "Objetivos añadidos:",\n      "description": "Texto a que sigue a la cantidad de objetivos creados actualmente, ejemplo: ''Objetivos añadidos: 5'' donde ''Objetivos añadidos:'' es este texto."\n    },\n    {\n      "label": "Texto para botón \\"Especificar objetivo\\"",\n      "default": "Especificación"\n    },\n    {\n      "label": "Texto para botón \\"Eliminar objetivo\\"",\n      "default": "Eliminar"\n    },\n    {\n      "label": "Etiqueta para texto de ayuda",\n      "description": "Etiqueta para mostrar información útil adicional al usuario.",\n      "default": "Más información"\n    },\n    {\n      "label": "Escribe información útil adicional",\n      "description": "Aquí puedes escribir información útil adicional para el usuario."\n    },\n    {\n      "label": "Localizar confirmación de eliminación de objetivo",\n      "fields": [\n        {\n          "label": "Encabezado",\n          "default": "Confirmar eliminación"\n        },\n        {\n          "label": "Mensaje",\n          "default": "¿Seguro que quieres eliminar este objetivo?"\n        },\n        {\n          "label": "Etiqueta botón Cancelar",\n          "default": "Cancelar"\n        },\n        {\n          "label": "Etiqueta botón Confirmar",\n          "default": "Confirmar"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'es-mx', '{\n  "semantics": [\n    {\n      "label": "Descripción",\n      "description": "Descripción de la página de metas.",\n      "default": "Inserte las metas con las que ha elegido trabajar."\n    },\n    {\n      "label": "Texto de enlace para definir meta",\n      "description": "Texto que será mostrado en el botón para crear una nueva meta.",\n      "default": "Crear una nueva meta"\n    },\n    {\n      "label": "Etiqueta para una meta definida por el usuario",\n      "description": "Texto que será mostrado como etiqueta en una meta creada por el usuario.",\n      "default": "Meta definida por el usuario"\n    },\n    {\n      "label": "Definir reemplazable de meta",\n      "description": "Texto que será mostrado como un reemplazable cuando se crea una nueva meta.",\n      "default": "Escriba aquí..."\n    },\n    {\n      "label": "Texto que indica cuantas metas han sido añadidas",\n      "default": "Metas añadidas:",\n      "description": "Este texto seguirá después de la cantidad de metas que están creadas actualmente, ejemplo: ''Metas añadidas: 5'' donde ''Metas añadidas:'' es este texto."\n    },\n    {\n      "label": "Texto para botón \\"Especificar meta\\"",\n      "default": "Especificación"\n    },\n    {\n      "label": "Texto para botón de \\"Eliminar meta\\"",\n      "default": "Eliminar"\n    },\n    {\n      "label": "Etiqueta para texto de ayuda",\n      "description": "Etiqueta para mostrar información útil adicional al usuario.",\n      "default": "Más información"\n    },\n    {\n      "label": "Escriba información útil adicional",\n      "description": "Aquí puede escribir información útil adicional para el usuario."\n    },\n    {\n      "label": "Confirmación de Localizar eliminación de meta",\n      "fields": [\n        {\n          "label": "Encabezado",\n          "default": "Confirmar eliminación"\n        },\n        {\n          "label": "Mensaje",\n          "default": "¿Está seguro de querer eliminar esta meta?"\n        },\n        {\n          "label": "Etiqueta botón Cancelar",\n          "default": "Cancelar"\n        },\n        {\n          "label": "Etiqueta del botón Confirmar",\n          "default": "Confirmar"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'et', '{\n  "semantics": [\n    {\n      "label": "Kirjeldus",\n      "description": "Eesmärkide lehe kirjeldus.",\n      "default": "Aseta eesmärgid väljavalitud eesmärgid."\n    },\n    {\n      "label": "Määratle eesmärk lingi tekst",\n      "description": "Tekst, mida näidatakse uue eesmärgi loomise nupul.",\n      "default": "Loo uus eesmärk"\n    },\n    {\n      "label": "Kasutaja määratletud eesmärgi silt",\n      "description": "Tekst, mida näidatakse kasutaja määratletud eesmärgi sildina.",\n      "default": "Kasutaja määratletud eesmärk"\n    },\n    {\n      "label": "Määratle eesmärk kohahoidja",\n      "description": "Tekst, mida näidatakse kohahoidjana uue eesmärgi loomisel.",\n      "default": "Kirjuta siia..."\n    },\n    {\n      "label": "Tekst, mis osutab, kui mitu eesmärki on lisatud",\n      "default": "Eesmärke lisatud:",\n      "description": "See tekst järgneb peale jooksvalt loodud eesmärkide arvu, näiteks: ''Eesmärke lisatud: 5'' kus ''Eesmärke lisatud:'' on see tekst."\n    },\n    {\n      "label": "\\"Määratle eesmärk\\"-nupu tekst",\n      "default": "Määratle"\n    },\n    {\n      "label": "\\"Eemalda eesmärk\\"-nupu tekst",\n      "default": "Eemalda"\n    },\n    {\n      "label": "Abiteksti silt",\n      "description": "Silt kasutajale täiendava abistava teabe näitamiseks.",\n      "default": "Rohkem teavet"\n    },\n    {\n      "label": "Sisesta täiendav abiteave",\n      "description": "Siia saad sisestada kasutaja jaoks täiendavat abistavat teavet."\n    },\n    {\n      "label": "Kohanda eesmärgi kustutamise kinnitust",\n      "fields": [\n        {\n          "label": "Päis",\n          "default": "Kinnita kustutus"\n        },\n        {\n          "label": "Sõnum",\n          "default": "Kas oled kindel, et tahad selle eesmärgi kustutada?"\n        },\n        {\n          "label": "Katkesta nupu silt",\n          "default": "Ei"\n        },\n        {\n          "label": "Kinnita nupu silt",\n          "default": "Jah"\n        }\n      ]\n    }\n  ]\n}'),
(72, 'eu', '{\n  "semantics": [\n    {\n      "label": "Deskribapena",\n      "description": "Helburuen orriaren deskribapena.",\n      "default": "Lantzeko aukeratu dituzun helburuak sartu."\n    },\n    {\n      "label": "Definitu helburuaren esteka-testua",\n      "description": "Botoian helburu berria sortzeko agertuko den testua.",\n      "default": "Sortu helburu berria"\n    },\n    {\n      "label": "Erabiltzaileak definitu duen helburuarentzako etiketa",\n      "description": "Erabiltzaileak sorturiko helburuan etiketa gisa agertuko den testua.",\n      "default": "Erabiltzaileak definituriko helburua"\n    },\n    {\n      "label": "Definitu helburuaren posizio-markagailua",\n      "description": "Helburu berria sortzean posizio-markagailu gisa agertuko den testua.",\n      "default": "Hemen idatzi..."\n    },\n    {\n      "label": "Zenbat helburu gehitu diren adierazten duen testua",\n      "default": "Gehitutako helburuak:",\n      "description": "Testu hau orain arte sortutako helburuen kopuruaren ondoren agertuko da, adibidez: ''Gehitutako helburuak: 5'' non ''Gehitutako helburuak:'' testu hau da."\n    },\n    {\n      "label": "-rako testua \\"Helburua zehaztu\\"-botoia",\n      "default": "Zehaztapena"\n    },\n    {\n      "label": "-rako testua \\"Helburua ezabatu\\"-botoia",\n      "default": "Kendu"\n    },\n    {\n      "label": "Laguntza-testurako etiketa",\n      "description": "Erabiltzailearentzako informazio gehigarria bistaratzeko etiketa.",\n      "default": "Informazio gehiago"\n    },\n    {\n      "label": "Osatu laguntzako informazio gehigarria",\n      "description": "Bertan zeuk osa dezakezu erabiltzailearentzat lagungarria den informazioa."\n    },\n    {\n      "label": "Bilatu helburuaren ezabaketaren egiaztapena",\n      "fields": [\n        {\n          "label": "Goiburua",\n          "default": "Berretsi ezabaketa"\n        },\n        {\n          "label": "Mezua",\n          "default": "Ziur zaude helburu hau ezabatu nahi duzula?"\n        },\n        {\n          "label": "Utzi botoiaren etiketa",\n          "default": "Utzi"\n        },\n        {\n          "label": "Berretsi botoiaren etiketa",\n          "default": "Berretsi"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'fa', '{\n  "semantics": [\n    {\n      "label": "توصیف",\n      "description": "توصیف صفحه اهداف.",\n      "default": "اهدافی را که برای کار با آنها انتخاب کرده‌اید وارد کنید."\n    },\n    {\n      "label": "متن پیوند تعریف هدف",\n      "description": "متنی که روی دکمه برای ایجاد یک هدف جدید نمایش داده خواهد شد.",\n      "default": "ایجاد یک هدف جدید"\n    },\n    {\n      "label": "برچسب برای یک هدف تعریف شده کاربر",\n      "description": "متنی که به عنوان برچسب بر یک هدف تعریف شده کاربر نمایش داده خواهد شد.",\n      "default": "هدف تعریف شده کاربر"\n    },\n    {\n      "label": "تعریف جاگیرنه هدف",\n      "description": "متنی که به عنوان یک جاگیرنده در هنگام ایجاد یک هدف جدید نمایش داده خواهد شد.",\n      "default": "اینجا بنویس..."\n    },\n    {\n      "label": "متنی که نشان می‌دهد چند هدف افزوده شده‌اند",\n      "default": "اهداف افزوده شده:",\n      "description": "این متن در ادامه تعداد اهدافی که در حال حاضر ایجاد شده‌اند خواهد آمد، مثال: ''اهداف افزوده شده: ۵'' که در آن ''اهداف افزوده شده:'' همین متن است."\n    },\n    {\n      "label": "متن برای دکمه مشخص کردن هدف",\n      "default": "مشخصات"\n    },\n    {\n      "label": "متن برای دکمه حذف هدف",\n      "default": "حذف"\n    },\n    {\n      "label": "برچسب برای متن کمک",\n      "description": "برچسب برای نشان دادن اطلاعات کمکی اضافی به کاربر.",\n      "default": "اطلاعات بیشتر"\n    },\n    {\n      "label": "اطلاعات کمکی اضافی را تکمیل کنید",\n      "description": "در اینجا می‌توانید اطلاعات مفید اضافی را برای کاربر تکمیل کنید."\n    },\n    {\n      "label": "بومی‌سازی تأیید حذف هدف",\n      "fields": [\n        {\n          "label": "سرصفحه",\n          "default": "تأیید حذف"\n        },\n        {\n          "label": "پیام",\n          "default": "آیا اطمینان دارید که می‌خواهید این هدف را حذف کنید؟"\n        },\n        {\n          "label": "برچسب دکمه لغو",\n          "default": "لغو"\n        },\n        {\n          "label": "برچسب دکمه تأیید",\n          "default": "تأیید"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'fi', '{\n  "semantics": [\n    {\n      "label": "Kuvaus",\n      "description": "Kuvaus tai ohje sivulle.",\n      "default": "Lisää tavoitteet, jotka olet päättänyt saavuttaa."\n    },\n    {\n      "label": "Painikkeen Luo tavoite teksti",\n      "description": "Teksti näytetään painikkeessa, jolla luodaan uusi tavoite.",\n      "default": "Luo tavoite"\n    },\n    {\n      "label": "Teksti käyttäjän luomalle tavoitteelle",\n      "description": "Käyttäjän luoman tavoitteen teksti.",\n      "default": "Käyttäjän luoma tavoite"\n    },\n    {\n      "label": "Uuden tavoitteen oletusteksti",\n      "description": "Oletusteksti, joka näkyy kun luodaan uusi tavoite.",\n      "default": "Kirjoita tähän..."\n    },\n    {\n      "label": "Tavoitteiden lukumäärää ilmaiseva teksti",\n      "default": "Tavoitteita:",\n      "description": "Tekstin jälkeen näkyy luotujen tavoitteiden määrä. Esimerkiksi: Tavoitteita: 5."\n    },\n    {\n      "label": "Teksti \\"Määrittele tavoite\\"-painikkeelle",\n      "default": "Määrittele"\n    },\n    {\n      "label": "Teksti \\"Poista tavoite\\"-painikkeelle",\n      "default": "Poista"\n    },\n    {\n      "label": "Teksti osoittamaan lisätietoa",\n      "description": "Lisätietoa ilmaiseva teksti käyttäjälle.",\n      "default": "Lisää tietoa"\n    },\n    {\n      "label": "Lisätietoteksti",\n      "description": "Tähän voit täyttää tekstiä lisätietona käyttäjälle."\n    },\n    {\n      "label": "Tavoitteen poistamisen varmistusruudun tekstit",\n      "fields": [\n        {\n          "label": "Otsikko",\n          "default": "Varmista poisto"\n        },\n        {\n          "label": "Viesti",\n          "default": "Oletko varma, että haluat poistaa tämän tavoitteen?"\n        },\n        {\n          "label": "Painikkeen Peruuta teksti",\n          "default": "Peruuta"\n        },\n        {\n          "label": "Painikkeen Kyllä teksti",\n          "default": "Kyllä"\n        }\n      ]\n    }\n  ]\n}'),
(72, 'fr', '{\n  "semantics": [\n    {\n      "label": "Description",\n      "description": "Description des objectifs de la page.",\n      "default": "Entrez les objectifs sur lesquels vous avez choisis de travailler."\n    },\n    {\n      "label": "Définir le texte du lien vers un objectif",\n      "description": "Texte qui apparaît sur le bouton pour créer un nouvel objectif.",\n      "default": "Créer un nouvel objectif"\n    },\n    {\n      "label": "Intitulé pour un objectif créé par l''utilisateur",\n      "description": "Texte qui sera utilisé comme intitulé d''un objectif créé par l''utilisateur.",\n      "default": "Objectif créé par l''utilisateur"\n    },\n    {\n      "label": "Définissez le texte initial de l''objectif",\n      "description": "Texte qui apparaît lors de la création d''un nouvel objectif.",\n      "default": "Ecrivez ici..."\n    },\n    {\n      "label": "Texte qui indique combien d''objectifs ont été ajoutés",\n      "default": "objectifs ajoutés :",\n      "description": "Ce texte va afficher le nombre d''objectifs créés, par exemple : ''objectifs ajoutés : 5'' où ''Objectifs ajoutés :'' est ce texte."\n    },\n    {\n      "label": "Texte pour le bouton \\"Préciser l''objectif\\"",\n      "default": "Préciser"\n    },\n    {\n      "label": "Texte pour le bouton \\"Supprimer l''objectif\\"",\n      "default": "Supprimer"\n    },\n    {\n      "label": "Titre pour le texte d''aide",\n      "description": "Titre pour afficher à l''utilisateur une information complémentaire utile.",\n      "default": "En savoir plus"\n    },\n    {\n      "label": "Complétez l''information complémentaire utile",\n      "description": "Ici vous pouvez saisir l''information complémentaire utile pour l''utilisateur."\n    },\n    {\n      "label": "Localisez la confirmation pour supprimer un objectif",\n      "fields": [\n        {\n          "label": "En-tête",\n          "default": "Confirmer la suppression"\n        },\n        {\n          "label": "Message",\n          "default": "Etes-vous sûr de vouloir supprimer cet objectif ?"\n        },\n        {\n          "label": "Titre du bouton d''annulation",\n          "default": "Annuler"\n        },\n        {\n          "label": "Titre du bouton de confirmation",\n          "default": "Confirmer"\n        }\n      ]\n    }\n  ]\n}'),
(72, 'gl', '{\n  "semantics": [\n    {\n      "label": "Descrición",\n      "description": "Descrición da páxina de obxectivos.",\n      "default": "Insire os obxectivos cos que escolliches traballar."\n    },\n    {\n      "label": "Define o texto da ligazón do obxectivo",\n      "description": "Texto que se amosará no botón para crear un novo obxectivo.",\n      "default": "Crea un novo obxectivo"\n    },\n    {\n      "label": "Etiqueta para un obxectivo definido polo usuario",\n      "description": "Texto que se mostrará como etiqueta nun obxectivo creado polo usuario.",\n      "default": "Obxectivo definido polo usuario"\n    },\n    {\n      "label": "Definir texto por defecto do obxectivo",\n      "description": "Texto que se amosará por defecto ao crear un novo obxectivo.",\n      "default": "Escribe aquí..."\n    },\n    {\n      "label": "Texto que indica cantos obxectivos se engadiron",\n      "default": "Obxectivos engadidos:",\n      "description": "Este texto aparecerá antes da cantidade de obxectivos que se crearon ata agora, exemplo: ''Obxectivos engadidos: 5'' onde ''Obxectivos engadidos:'' é este texto."\n    },\n    {\n      "label": "Texto para o botón \\"Especificar obxectivo\\"",\n      "default": "Especificación"\n    },\n    {\n      "label": "Texto para o botón \\"Eliminar obxectivo\\"",\n      "default": "Eliminar"\n    },\n    {\n      "label": "Etiqueta para o texto de axuda",\n      "description": "Etiqueta para amosar ao usuario información adicional útil.",\n      "default": "Máis información"\n    },\n    {\n      "label": "Engade información de axuda adicional",\n      "description": "Aquí podes aportar información de axuda adicional para o usuario."\n    },\n    {\n      "label": "Localizar a confirmación da eliminación de obxectivo",\n      "fields": [\n        {\n          "label": "Cabeceira",\n          "default": "Confirmar a eliminación"\n        },\n        {\n          "label": "Mensaxe",\n          "default": "Seguro que queres eliminar este obxectivo?"\n        },\n        {\n          "label": "Etiqueta do botón Cancelar",\n          "default": "Cancelar"\n        },\n        {\n          "label": "Etiqueta para o botón confirmar",\n          "default": "Confirmar"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'it', '{\n  "semantics": [\n    {\n      "label": "Descrizione",\n      "description": "Descrizione della pagina degli obiettivi",\n      "default": "Inserisci gli obiettivi su cui hai scelto di lavorare"\n    },\n    {\n      "label": "Definisci il testo del collegamento all''obiettivo",\n      "description": "Testo che sarà mostrato sul pulsante per creare un nuovo obiettivo",\n      "default": "Crea un nuovo obiettivo"\n    },\n    {\n      "label": "Etichetta per un obiettivo definito dall''apprendente",\n      "description": "Testo che sarà mostrato come etichetta su un obiettivo creato da un apprendente",\n      "default": "Obiettivo definito dall''apprendente"\n    },\n    {\n      "label": "Definisci un segnaposto per l''obiettivo",\n      "description": "Testo che sarà mostrato come segnaposto quando si crea un nuovo obiettivo",\n      "default": "Scrivi qui..."\n    },\n    {\n      "label": "Testo che indica quanti obiettivi sono stati aggiunti",\n      "default": "Obiettivi aggiunti:",\n      "description": "A questo testo farà seguito la quantità di obiettivi attualmente creati. Per esempio: in \\"Obiettivi aggiunti: 5\\", \\"Obiettivi aggiunti:\\" è questo testo"\n    },\n    {\n      "label": "Testo per il pulsante \\"Specifica obiettivo\\"",\n      "default": "Specificazione"\n    },\n    {\n      "label": "Testo per il pulsante \\"Rimuovi obiettivo\\"",\n      "default": "Rimuovi"\n    },\n    {\n      "label": "Etichetta per il testo di aiuto",\n      "description": "Etichetta per mostrare ulteriori informazioni di aiuto all''apprendente",\n      "default": "Ulteriori informazioni"\n    },\n    {\n      "label": "Aggiungi ulteriori informazioni di aiuto",\n      "description": "Qui puoi aggiungere ulteriori informazioni di aiuto per l''apprendente"\n    },\n    {\n      "label": "Localizza la conferma della cancellazione dell''obiettivo",\n      "fields": [\n        {\n          "label": "Intestazione",\n          "default": "Conferma cancellazione"\n        },\n        {\n          "label": "Messaggio",\n          "default": "Sei sicuro di voler cancellare questo obiettivo?"\n        },\n        {\n          "label": "Etichetta del pulsante di cancellazione",\n          "default": "Annulla"\n        },\n        {\n          "label": "Etichetta del pulsante di conferma",\n          "default": "Conferma"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'ka', '{\n  "semantics": [\n    {\n      "description": "მიზნების გვერდის აღწერა.",\n      "default": "შეიყვანეთ მიზნები, რომლებიც აირჩიეთ სამუშაოდ.",\n      "label": "აღწერა"\n    },\n    {\n      "label": "განსაზღვრეთ მიზნის ბმულის ტექსტი",\n      "description": "ტექსტი, რომელიც გამოჩნდება ღილაკზე ახალი მიზნის შესაქმნელად.",\n      "default": "შექმენით ახალი მიზანი"\n    },\n    {\n      "label": "წარწერა მომხმარებლის მიერ განსაზღვრული მიზნისთვის",\n      "description": "ტექსტი, რომელიც გამოჩნდება მომხმარებლის მიერ შექმნილ მიზანზე წარწერის სახით.",\n      "default": "მომხმარებლის მიერ განსაზღვრული მიზანი"\n    },\n    {\n      "label": "განსაზღვრეთ მიზნის ადგილი",\n      "description": "ტექსტი, რომელიც გამოჩნდება შემავსებლად ახალი მიზნის შექმნისას.",\n      "default": "დაწერეთ აქ..."\n    },\n    {\n      "label": "ტექსტი, რომელშიც მითითებულია რამდენი მიზანია დამატებული",\n      "default": "დამატებული მიზნები:",\n      "description": "ეს ტექსტი მოჰყვება ამჟამად შექმნილი მიზნების რაოდენობას, მაგალითად: „დამატებული მიზნები: 5“, სადაც „დამატებული მიზნები:“ არის ეს ტექსტი."\n    },\n    {\n      "label": "ტექსტი \\"მიზნის განსაზღვრის\\"-ღილაკისთვის",\n      "default": "სპეციფიკაცია"\n    },\n    {\n      "label": "ტექსტი \\"მიზნის წაშლა\\"-ღილაკისთვის",\n      "default": "წაშლა"\n    },\n    {\n      "label": "წარწერა დამხმარე ტექსტისთვის",\n      "description": "წარწერა მომხმარებლისთვის დამატებითი დამხმარე ინფორმაციის ჩვენებისთვის.",\n      "default": "დამატებითი ინფორმაცია"\n    },\n    {\n      "label": "შეავსეთ დამატებითი საცნობარო ინფორმაცია",\n      "description": "აქ შეგიძლიათ შეიტანოთ დამატებითი დამხმარე ინფორმაცია მომხმარებლისთვის."\n    },\n    {\n      "label": "მიზნის წაშლის დადასტურების ლოკალიზაცია",\n      "fields": [\n        {\n          "label": "სათაური",\n          "default": "დაადასტურეთ წაშლა"\n        },\n        {\n          "label": "შეტყობინება",\n          "default": "დარწმუნებული ხართ, რომ გსურთ ამ მიზნის წაშლა?"\n        },\n        {\n          "label": "გაუქმების ღილაკის წარწერა",\n          "default": "გაუქმება"\n        },\n        {\n          "label": "დადასტურების ღილაკის წარწერა",\n          "default": "დადასტურება"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'km', '{\n  "semantics": [\n    {\n      "label": "Description",\n      "description": "Description of the goals page.",\n      "default": "បញ្ចូលគោលដៅដែលអ្នកចង់ទទួលបាន"\n    },\n    {\n      "label": "Define goal link text",\n      "description": "Text that will be displayed on the button for creating a new goal.",\n      "default": "បង្កើតគោលដៅថ្មីមួយ"\n    },\n    {\n      "label": "Label for a user defined goal",\n      "description": "Text that will be displayed as label on a user created goal.",\n      "default": "គោលដៅដែលបានកំណត់ដោយអ្នកប្រើ"\n    },\n    {\n      "label": "Define goal placeholder",\n      "description": "Text that will be displayed as a placeholder when creating a new goal.",\n      "default": "សរសេរទីនេះ..."\n    },\n    {\n      "label": "Text indicating how many goals has been added",\n      "default": "គោលដៅដែលបានបន្ថែម:",\n      "description": "This text will follow after the amount of goals that is currently created, example: ''Goals added: 5'' where ''Goals added:'' is this text."\n    },\n    {\n      "label": "Text for \\"Specify goal\\"-button",\n      "default": "ការបញ្ជាក់"\n    },\n    {\n      "label": "Text for \\"Remove goal\\"-button",\n      "default": "ដកចេញ"\n    },\n    {\n      "label": "Label for help text",\n      "description": "Label for showing additional helpful information to the user.",\n      "default": "ព័ត៌មានបន្ថែម"\n    },\n    {\n      "label": "Fill in additional help information",\n      "description": "Here you can fill in additional helpful information for the user."\n    },\n    {\n      "label": "Localize goal deletion confirmation",\n      "fields": [\n        {\n          "label": "Header",\n          "default": "អះអាងពីការលុប"\n        },\n        {\n          "label": "Message",\n          "default": "តើអ្នកពិតជាចង់លុបគោលដៅនេះមែនទេ?"\n        },\n        {\n          "label": "Cancel button label",\n          "default": "បោះបង់"\n        },\n        {\n          "label": "Confirm button label",\n          "default": "យល់ព្រម"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'ko', '{\n  "semantics": [\n    {\n      "label": "설명",\n      "description": "목표 설명 페이지",\n      "default": "설정한 목표를 삽입하십시오."\n    },\n    {\n      "label": "목표 정의 링크 텍스트",\n      "description": "새로운 목표를 만들기 위한 버튼에 표시될 텍스트.",\n      "default": "새 목표 만들기"\n    },\n    {\n      "label": "사용자 정의 목표를 위한 라벨",\n      "description": "사용자가 작성한 목표에 라벨로 표시될 텍스트.",\n      "default": "사용자 정의 목표"\n    },\n    {\n      "label": "목표 정의 자리 표시자",\n      "description": "새로운 목표를 작성할 때 자리 표시자로 표시될 텍스트.",\n      "default": "여기에 쓰기..."\n    },\n    {\n      "label": "목표가 몇 개 추가되었는지 나타내는 텍스트",\n      "default": "추가된 목표:",\n      "description": "이 텍스트는 현재 생성된 목표의 양 다음에 따라올 것이다. 예: ''추가된 목표: 5''. 여기서 ''추가된 목표:''가 텍스트임."\n    },\n    {\n      "label": "\\"Specify goal\\" (목표 상세화) 버튼 텍스트",\n      "default": "목표 상세화"\n    },\n    {\n      "label": "\\"Remove goal\\" (목표 제거) 버튼 텍스트",\n      "default": "제거"\n    },\n    {\n      "label": "도움말 텍스트",\n      "description": "사용자에게 유용한 정보를 추가적으로 보여주기 위한 라벨.",\n      "default": "추가 정보"\n    },\n    {\n      "label": "추가 도움말 정보 입력",\n      "description": "여기에 사용자를 위한 추가 유용한 정보를 기입할 수 있다."\n    },\n    {\n      "label": "목표 삭제 확인 맞춤형 설정",\n      "fields": [\n        {\n          "label": "머릿말",\n          "default": "삭제 확인"\n        },\n        {\n          "label": "메시지",\n          "default": "이 목표를 삭제하시겠습니까?"\n        },\n        {\n          "label": "취소 버튼 레이블",\n          "default": "취소"\n        },\n        {\n          "label": "확인 버튼 레이블",\n          "default": "확인"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'lt', '{\n  "semantics": [\n    {\n      "label": "Aprašymas",\n      "description": "Tikslų puslapio aprašymas.",\n      "default": "Įterpkite tikslus, kuriuos pasirinkote vykdyti."\n    },\n    {\n      "label": "Nurodykite tikslo nuorodos tekstą",\n      "description": "Tekstas, kuris bus rodomas ant mygtuko, norint sukurti naują tikslą.",\n      "default": "Sukurti naują tikslą"\n    },\n    {\n      "label": "Naudotojo pasirinkto tikslo pavadinimas",\n      "description": "Tekstas, kuris bus rodomas kaip pavadinimas ant naudotojo sukurto tikslo.",\n      "default": "Naudotojo nustatytas tikslas"\n    },\n    {\n      "label": "Nustatykite tikslo saugojimo vietą",\n      "description": "Tekstas, kuris bus rodomas kaip saugojimo vieta kuriant naują tikslą.",\n      "default": "Rašyti čia..."\n    },\n    {\n      "label": "Tekstas rodo kiek tikslų buvo pridėta",\n      "default": "Tikslai pridėti:",\n      "description": "Šis tekstas bus po šiuo metu sukurtų tikslų skaičiaus, pvz.: „Pridėti tikslai: 5“, kur „Pridėti tikslai:“ yra šis tekstas."\n    },\n    {\n      "label": "Mygtuko „Apibūdinkite tikslą“ tekstas",\n      "default": "Specifikacija"\n    },\n    {\n      "label": "Tekstas \\"Pašalinti tikslą\\" mygtukui",\n      "default": "Pašalinti"\n    },\n    {\n      "label": "Pagalbos teksto pavadinimas",\n      "description": "Papildomos naudingos informacijos rodymo naudotojui pavadinimas.",\n      "default": "Daugiau informacijos"\n    },\n    {\n      "label": "Įveskite papildomą pagalbos informaciją",\n      "description": "Čia galite įrašyti papildomą naudingą informaciją naudotojui."\n    },\n    {\n      "label": "Lokalizuoti tikslo ištrynimo patvirtinimą",\n      "fields": [\n        {\n          "label": "Antraštė",\n          "default": "Patvirtinkite ištrynimą"\n        },\n        {\n          "label": "Žinutė",\n          "default": "Ar jūs įsitikinę, kad norite ištrinti tikslą?"\n        },\n        {\n          "label": "Atšaukti mygtuko pavadinimas",\n          "default": "Atšaukti"\n        },\n        {\n          "label": "Patvirtinti mygtuko pavadinimas",\n          "default": "Patvirtinti"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'lv', '{\n  "semantics": [\n    {\n      "description": "Mērķu lapas apraksts.",\n      "label": "Apraksts",\n      "default": "Ievietojiet mērķus, pie kuriem esat izvēlējies strādāt."\n    },\n    {\n      "label": "Iestatiet mērķa saites tekstu",\n      "default": "Izveidot jaunu mērķi",\n      "description": "Teksts, kas tiks parādīts uz jauna mērķa izveides pogas."\n    },\n    {\n      "label": "Lietotāja definētā mērķa etiķete",\n      "description": "Teksts, kas tiks parādīts kā etiķete lietotāja izveidotajam mērķim.",\n      "default": "Lietotāja definēts mērķis"\n    },\n    {\n      "label": "Iestatiet mērķa vietturi",\n      "default": "Raksti šeit...",\n      "description": "Teksts, kas tiks parādīts kā vietturis, veidojot jaunu mērķi."\n    },\n    {\n      "label": "Teksts, kas norāda, cik mērķi ir pievienoti",\n      "default": "Pievienotie mērķi:",\n      "description": "Šis teksts tiks atspoguļots pirms šobrīd izveidoto mērķu skaita, piemēram: ''Pievienotie mērķi: 5'', kur ''Pievienotie mērķi:'' ir šis teksts."\n    },\n    {\n      "default": "Precizēšana",\n      "label": "Teksts pogai \\"Precizēt mērķi\\""\n    },\n    {\n      "label": "Teksts pogai \\"Noņemt mērķi\\"",\n      "default": "Noņemt"\n    },\n    {\n      "label": "Palīdzības teksta etiķete",\n      "description": "Etiķete papildus palīdzības teksta atspoguļošanai lietotājam.",\n      "default": "Papildus informācija"\n    },\n    {\n      "label": "Aizpildiet papildus palīdzības informāciju",\n      "description": "Šeit varat ievadīt lietotājam noderīgu papildu informāciju."\n    },\n    {\n      "label": "Lokalizēt mērķa dzēšanas apstiprinājumu",\n      "fields": [\n        {\n          "label": "Galvene",\n          "default": "Apstipriniet dzēšanu"\n        },\n        {\n          "label": "Ziņa",\n          "default": "Vai esat pārliecināts, ka vēlaties dzēst šo mērķi?"\n        },\n        {\n          "label": "Atcelšanas pogas etiķete",\n          "default": "Atcelt"\n        },\n        {\n          "label": "Apstiprinājuma pogas etiķete",\n          "default": "Apstiprināt"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'mn', '{\n  "semantics": [\n    {\n      "description": "Зорилго хуудасны тайлбар.",\n      "label": "Тодорхойлолт",\n      "default": "Хамтран ажиллахаар сонгосон зорилгоо оруулна уу."\n    },\n    {\n      "label": "Зорилго холбоосын текстийг тодорхойлох",\n      "default": "Шинэ зорилго бий болго",\n      "description": "Шинэ зорилго үүсгэх товчлуур дээр гарч ирэх текст."\n    },\n    {\n      "description": "Хэрэглэгчийн үүсгэсэн зорилго дээр шошго хэлбэрээр харагдах текст.",\n      "label": "Хэрэглэгчийн тодорхойлсон зорилгын шошго",\n      "default": "Хэрэглэгчийн тодорхойлсон зорилго"\n    },\n    {\n      "label": "Зорилго орлуулагчийг тодорхойлох",\n      "default": "Энд бичээрэй...",\n      "description": "Шинэ зорилго үүсгэх үед орлуулагчаар харагдах текст."\n    },\n    {\n      "default": "Нэмсэн зорилго:",\n      "label": "Хэдэн зорилго нэмэгдсэнийг харуулсан текст",\n      "description": "Энэ текст нь одоо үүсгэгдсэн зорилгын хэмжээг дагаж мөрдөх болно, жишээ нь: ''Нэмэгдсэн зорилго: 5'' энд ''Нэмэгдсэн зорилго:'' нь энэ текст юм."\n    },\n    {\n      "label": "\\"Зорилго зааж өгөх\\" товчлуурын текст",\n      "default": "Тодорхойлолт"\n    },\n    {\n      "label": "\\"Зорилго арилгах\\" товчийг бичнэ үү",\n      "default": "Устгах"\n    },\n    {\n      "label": "Тусламжийн текстийн шошго",\n      "default": "Нэмэлт мэдээлэл",\n      "description": "Хэрэглэгчдэд хэрэгтэй нэмэлт мэдээллийг харуулах шошго."\n    },\n    {\n      "description": "Энд та хэрэглэгчдэд хэрэгтэй нэмэлт мэдээллийг бөглөж болно.",\n      "label": "Тусламжийн нэмэлт мэдээллийг бөглөнө үү"\n    },\n    {\n      "fields": [\n        {\n          "label": "Толгой хэсэг",\n          "default": "Устгасныг баталгаажуулна уу"\n        },\n        {\n          "label": "Захиа",\n          "default": "Та энэ зорилгыг устгахдаа итгэлтэй байна уу?"\n        },\n        {\n          "label": "Цуцлах товчлуурын шошго",\n          "default": "Цуцлах"\n        },\n        {\n          "label": "Баталгаажуулах товчлуурын шошго",\n          "default": "Баталгаажуулах"\n        }\n      ],\n      "label": "Зорилго устгах баталгаажуулалтыг нутагшуулах"\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(72, 'nb', '{\n  "semantics": [\n    {\n      "label": "Beskrivelse av siden",\n      "description": "Beskriv aktivitetene brukeren skal gjennomføre på målsiden.",\n      "default": "Opprett målene du har valgt å jobbe med."\n    },\n    {\n      "label": "Tekst for \\"Skriv eget mål\\"-knapp",\n      "description": "Tekst som vil vises på \\"Skriv eget mål\\"-knapp.",\n      "default": "Skriv eget mål"\n    },\n    {\n      "label": "Tekst for brukerdefinert mål",\n      "description": "Tekst som vil vises som merkelapp på et brukerdefinert mål.",\n      "default": "Brukerdefinert mål"\n    },\n    {\n      "label": "Tekst for tomme mål",\n      "description": "Tekst som vil vises i tomme mål.",\n      "default": "Skriv her..."\n    },\n    {\n      "label": "Tekst som beskriver hvor mange mål som har blitt lagt til",\n      "default": "Mål lagt til:",\n      "description": "Denne teksten vil følge etter antall mål som er lagt til. Til eksempel: ''Mål lagt til: 5'' hvor ''Mål lagt til:'' er denne teksten."\n    },\n    {\n      "label": "Tekst for \\"Konkretiser mål\\"-knapp",\n      "default": "Konkretiser"\n    },\n    {\n      "label": "Tekst for \\"Slett mål\\"-knapp",\n      "default": "Slett"\n    },\n    {\n      "label": "Tekst for \\"Hjelpetekst\\"-knapp",\n      "description": "Tekst som vil vises på \\"HjelpeTekst\\"-knapp som vil vises tilleggsinformasjon til brukeren.",\n      "default": "Mer informasjon"\n    },\n    {\n      "label": "Fyll inn tilleggs-informasjon om utførelse til brukeren",\n      "description": "Her kan du fylle inn ekstra nyttig informasjon om hvordan brukeren skal bruke denne siden."\n    },\n    {\n      "label": "Localize goal deletion confirmation",\n      "fields": [\n        {\n          "label": "Header",\n          "default": "Bekreft sletting"\n        },\n        {\n          "label": "Message",\n          "default": "Sikker på at du vil slette målet?"\n        },\n        {\n          "label": "Cancel button label",\n          "default": "Avbryt"\n        },\n        {\n          "label": "Confirm button label",\n          "default": "Bekreft"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'nl', '{\n  "semantics": [\n    {\n      "label": "Beschrijving",\n      "description": "Omschrijving van de doelstellingenpagina.",\n      "default": "Beschrijf de doelen die je hebt gekozen om mee aan de slag te gaan."\n    },\n    {\n      "label": "Definieer de doelstellings-linktekst",\n      "description": "Deze tekst wordt getoond op de knop om een nieuwe doelstelling te maken.",\n      "default": "Maak een nieuwe doelstelling"\n    },\n    {\n      "label": "Label van een door de gebruiker gedefinieerde doelstelling",\n      "description": "Deze tekst wordt getoond als label op een door de gebruiker gedefinieerde doelstelling.",\n      "default": "Door de gebruiker gedefinieerde doelstelling"\n    },\n    {\n      "label": "Definieer doelstelling tijdelijke tekst",\n      "description": "Deze tekst wordt getoond als tijdelijke tekst wanneer er een nieuwe doelstelling wordt gedefinieerd.",\n      "default": "Schrijf hier..."\n    },\n    {\n      "label": "Tekst om aan te geven hoeveel doelstellingen er zijn toegevoegd",\n      "default": "Toegevoegde doelstellingen:",\n      "description": "Deze tekst volgt nadat het aantal doelstellingen is gemaakt, voorbeeld: ''Toegevoegde doelstellingen: 5'' waar ''Toegevoegde doestellingen:'' deze tekst is."\n    },\n    {\n      "label": "Tekst voor \\"Omschrijving doelstelling\\"-knop",\n      "default": "Omschrijving"\n    },\n    {\n      "label": "Tekst voor \\"Verwijder doelstelling\\"-knop",\n      "default": "Verwijder"\n    },\n    {\n      "label": "Label voor helptekst",\n      "description": "Label om aanvullende nuttige informatie aan de gebruiker te tonen.",\n      "default": "Meer informatie"\n    },\n    {\n      "label": "Vul aanvullende help informatie in",\n      "description": "Hier kun je aanvullende nuttige informatie invullen voor de gebruiker."\n    },\n    {\n      "label": "Lokaliseer verwijdering doelstelling bevestiging",\n      "fields": [\n        {\n          "label": "Koptekst",\n          "default": "Bevestig verwijdering"\n        },\n        {\n          "label": "Bericht",\n          "default": "Weet je zeker dat je deze doelstelling wilt verwijderen?"\n        },\n        {\n          "label": "Label van \\"Annuleer\\"-knop",\n          "default": "Annuleer"\n        },\n        {\n          "label": "Label van \\"Bevestig\\"-knop",\n          "default": "Bevestig"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'nn', '{\n  "semantics": [\n    {\n      "label": "Skildring av sida",\n      "description": "Skildre aktivitetane brukaren skal gjennomføre på målsida.",\n      "default": "Opprett måla du har valt å jobbe med."\n    },\n    {\n      "label": "Tekst for \\"Skriv eige mål\\"-knapp",\n      "description": "Tekst som vil visast på \\"Skriv eige mål\\"-knapp.",\n      "default": "Skriv eige mål"\n    },\n    {\n      "label": "Tekst for brukardefinert mål",\n      "description": "Tekst som vil visast som merkelapp på eit brukardefinert mål.",\n      "default": "Brukardefinert mål"\n    },\n    {\n      "label": "Tekst for tomme mål",\n      "description": "Tekst som vil visast i tomme mål.",\n      "default": "Skriv her..."\n    },\n    {\n      "label": "Tekst som skildrer kor mange mål som har blitt lagt til",\n      "default": "Mål lagt til:",\n      "description": "Denne teksten vil følgje etter antall mål som er lagt til. Til dømes: ''Mål lagt til: 5'' hvor ''Mål lagt til:'' er denne teksten."\n    },\n    {\n      "label": "Tekst for \\"Konkretiser mål\\"-knapp",\n      "default": "Konkretiser"\n    },\n    {\n      "label": "Tekst for \\"Slett mål\\"-knapp",\n      "default": "Slett"\n    },\n    {\n      "label": "Tekst for \\"Hjelpetekst\\"-knapp",\n      "description": "Tekst som vil visast på \\"HjelpeTekst\\"-knapp som vil visa tilleggsinformasjon til brukaren.",\n      "default": "Meir informasjon"\n    },\n    {\n      "label": "Fyll inn tilleggsinformasjon om utføring til brukaren",\n      "description": "Her kan du fylla inn ekstra nyttig informasjon om korleis brukaren skal bruke denne sida."\n    },\n    {\n      "label": "Localize goal deletion confirmation",\n      "fields": [\n        {\n          "label": "Header",\n          "default": "Bekreft sletting"\n        },\n        {\n          "label": "Message",\n          "default": "Sikker på at du vil slette målet?"\n        },\n        {\n          "label": "Cancel button label",\n          "default": "Avbryt"\n        },\n        {\n          "label": "Confirm button label",\n          "default": "Bekreft"\n        }\n      ]\n    }\n  ]\n}\n'),
(72, 'pt', '{\n  "semantics": [\n    {\n      "label": "Descrição",\n      "description": "Descrição da página de objetivos.",\n      "default": "Insira os objetivos que você escolheu trabalhar."\n    },\n    {\n      "label": "Texto link de Definição de objetivo",\n      "description": "Texto que será exibido no botão de criação de novos objetivos.",\n      "default": "Criar um novo objetivo"\n    },\n    {\n      "label": "Rótulo para um objetivo definido pelo usuário",\n      "description": "Texto que será exibido como rótulo para um objetivo definido pelo usuário.",\n      "default": "Objetivo definido pelo usuário"\n    },\n    {\n      "label": "Placeholder de definir objetivo",\n      "description": "Texto que será exibido como placeholder quando um novo objetivo estiver sendo criado.",\n      "default": "Escreva aqui..."\n    },\n    {\n      "label": "Texto indicando quantos objetivos foram adicionados",\n      "default": "Objetivos adicionados:",\n      "description": "Este texto será seguido pelo número de objetivos criados atualmente, exemplo: ''Objetivos adicionados: 5'' onde ''Objetivos adicionados:'' é este texto."\n    },\n    {\n      "label": "Texto para botão \\"Especificar objetivo\\"",\n      "default": "Especificação"\n    },\n    {\n      "label": "Texto para botão \\"Remover objetivo\\"",\n      "default": "Remover"\n    },\n    {\n      "label": "Rótulo para texto de ajuda",\n      "description": "Rótulo para mostrar informações úteis adicionais ao usuário.",\n      "default": "Mais informações"\n    },\n    {\n      "label": "Preencha com informações adicionais",\n      "description": "Aqui você pode preencher as informações úteis adicionais para o usuário."\n    },\n    {\n      "label": "Localização de confirmação de eliminação de objetivo",\n      "fields": [\n        {\n          "label": "Cabeçalho",\n          "default": "Confirmar exclusão"\n        },\n        {\n          "label": "Mensagem",\n          "default": "Você tem certeza