(73, 'lt', '{\n  "semantics": [\n    {\n      "label": "Plotis",\n      "description": "iFrame plotis su CSS suderinamu formatu. Numatytasis: „500 piks.“"\n    },\n    {\n      "label": "Minimalus plotis",\n      "description": "Minimalus iFrame plotis su CSS suderinamu formatu. Numatytasis: „300 piks.“"\n    },\n    {\n      "label": "Aukštis",\n      "description": "iFrame aukštis su CSS suderinamu formatu. Numatytasis: „500 piks.“"\n    },\n    {\n      "label": "Šaltinis",\n      "description": "URI į išorinį dokumentą arba kelias į dokumentą, rastą H5P viduje (skiltyje /turinyje)"\n    },\n    {\n      "label": "Palaikomas dydžio keitimas",\n      "description": "Jei įjungta, bus rodomas viso ekrano mygtukas, o H5P dydis bus pakeistas, kad atitiktų aplinką"\n    }\n  ]\n}\n'),
(73, 'lv', '{\n  "semantics": [\n    {\n      "label": "Platums",\n      "description": "iFrame platums ar CSS saderīgā formātā. Pēc noklusējuma: \\"500px\\""\n    },\n    {\n      "label": "Minimālais platums",\n      "description": "Minimālais iFrame augstums ar CSS saderīgā formātā. Pēc noklusējuma: \\"300px\\""\n    },\n    {\n      "label": "Augstums",\n      "description": "iFrame augstums ar CSS saderīgā formātā. Pēc noklusējuma: \\"500px\\""\n    },\n    {\n      "label": "Avots",\n      "description": "URI uz ārējo dokumentu vai ceļš uz dokumentu, kas atrodams H5P (sadaļā /content)"\n    },\n    {\n      "label": "Izmēra maiņa tiek atbalstīta",\n      "description": "Ja iespējots, tiks parādīta pilnekrāna poga un H5P izmērs tiks mainīts, lai atbilstu tā apkārtnei"\n    }\n  ]\n}\n'),
(73, 'mn', '{\n  "semantics": [\n    {\n      "label": "Өргөн",\n      "description": "CSS форматад тохирох айФрэймийн өргөн. Өгөгдсөн: \\"500px\\""\n    },\n    {\n      "label": "Хамгийн бага өргөн",\n      "description": "CSS форматад тохирох айФрэймийн хамгийн бага өргөн. Өгөгдсөн: \\"300px\\""\n    },\n    {\n      "label": "Өндөр",\n      "description": "CSS форматад тохирох айФрэймийн өндөр. Өгөгдсөн: \\"500px\\""\n    },\n    {\n      "label": "Эх сурвалж",\n      "description": "URI-аас Гадаад эх сурвалж руу, эсвэл H5P контентын байршил руу (доор /контент)"\n    },\n    {\n      "label": "Хэмжээг өөрчлөх боломжтой",\n      "description": "Идэвхжүүлснээр дэлгэц томруулах товчлуур харагдах ба H5P-ийн хэмжээ дэлгэцнээс хамааран өөрчлөгдөнө"\n    }\n  ]\n}\n'),
(73, 'nb', '{\n  "semantics": [\n    {\n      "label": "Bredde",\n      "description": "Bredden av din iFrame i CSS format. Normal verdi: \\"500px\\""\n    },\n    {\n      "label": "Minimum bredde",\n      "description": "Minste bredden din iFrame vil minskes til i CSS. Normal verdi: \\"300px\\""\n    },\n    {\n      "label": "Høyde",\n      "description": "Høyden av din iFrame i CSS format. Normal verdi: \\"500px\\""\n    },\n    {\n      "label": "Kilde",\n      "description": "URI til eksternt dokument, eller adresse til dokument i H5P (i /content mappen)"\n    },\n    {\n      "label": "Slå på dynamisk størrelse",\n      "description": "Ved å slå på dette alternativet vil fullskjermsknapp vises og innholdet vil skalere til å bruke så mye plass som det kan"\n    }\n  ]\n}\n'),
(73, 'nl', '{\n  "semantics": [\n    {\n      "label": "Breedte",\n      "description": "De breedte van het iFrame in CSS-conforme opmaak. Standaard: \\"500px\\""\n    },\n    {\n      "label": "Minimale breedte",\n      "description": "Minimale breedte van het iFrame in CSS-conforme opmaak. Standaard: \\"300px\\""\n    },\n    {\n      "label": "Hoogte",\n      "description": "Hoogte van het iFrame in CSS-conforme opmaak. Standaard: \\"500px\\""\n    },\n    {\n      "label": "Bron",\n      "description": "URL naar het externe document of het pad naar het document in H5P (onder /content)"\n    },\n    {\n      "label": "Ondersteund aanpassen van de grootte",\n      "description": "Indien geactiveerd, wordt de knop ''Volledig scherm'' getoond en zal H5P zich aanpassen aan de grootte van de beschikbare omgeving"\n    }\n  ]\n}\n'),
(73, 'pt', '{\n  "semantics": [\n    {\n      "label": "Largura",\n      "description": "Largura do iFrame conforme formato do CSS. Valor por omissão: \\"500px\\""\n    },\n    {\n      "label": "Largura mínima",\n      "description": "Largura mínima do iFrame conforme formato do CSS. Valor por omissão: \\"300px\\""\n    },\n    {\n      "label": "Altura",\n      "description": "Altura do iFrame conforme formato do CSS. Valor por omissão: \\"500px\\""\n    },\n    {\n      "label": "Fonte/URL",\n      "description": "URI/Link para documento externo, ou caminho para o documento dentro do conteúdo H5P"\n    },\n    {\n      "label": "Permitir redimensionamento",\n      "description": "Se ativado, o botão de Ecrã completo será exibido e o H5P será redimensionado para se ajustar ao ambiente."\n    }\n  ]\n}\n'),
(73, 'pt-br', '{\n  "semantics": [\n    {\n      "label": "Largura",\n      "description": "Largura do iFrame em formato compatível com o CSS. Padrão: \\"500px\\""\n    },\n    {\n      "label": "Largura mínima",\n      "description": "Largura mínima do iFrame no formato compatível com o CSS. Padrão: \\"300px\\""\n    },\n    {\n      "label": "Altura",\n      "description": "Altura do iFrame em formato compatível com o CSS. Padrão: \\"500px\\""\n    },\n    {\n      "label": "Fonte",\n      "description": "URI para documento externo, ou caminho para documento encontrado dentro do H5P (sob /content)"\n    },\n    {\n      "label": "Redimensionar suportado",\n      "description": "Se ativado, o botão de tela cheia será exibido, e o H5P será redimensionado para se ajustar ao seu ambiente"\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(73, 'ru', '{\n  "semantics": [\n    {\n      "label": "Ширина",\n      "description": "Ширина iFrame в соответствии с форматом CSS. По умолчанию: \\"500px\\""\n    },\n    {\n      "label": "Минимальная ширина",\n      "description": "Минимальная ширина iFrame в соответствии с форматом CSS. По умолчанию: \\"300px\\""\n    },\n    {\n      "label": "Высота",\n      "description": "Высота iFrame в соответствии с форматом CSS. По умолчанию: \\"500px\\""\n    },\n    {\n      "label": "Источник",\n      "description": "URI первоначального документа или источник документа в H5P (under /content)"\n    },\n    {\n      "label": "Изменение размера разрешено",\n      "description": "Если разрешено, то отобразиться кнопка полноэкранного режима и H5P будет определён по размеру рамки."\n    }\n  ]\n}\n'),
(73, 'sl', '{\n  "semantics": [\n    {\n      "label": "Širina",\n      "description": "Širina okvirja (iFrame) v obliki CSS. Privzeto: \\"500px\\""\n    },\n    {\n      "label": "Najmanjša širina",\n      "description": "Najmanjša dovoljena širina okvirja (iFrame) v obliki CSS. Privzeto: \\"300px\\""\n    },\n    {\n      "label": "Višina",\n      "description": "Višina okvirja (iFrame) v obliki CSS. Privzeto: \\"500px\\""\n    },\n    {\n      "label": "Vir",\n      "description": "Spletna povezava (URL) do zunanjega vira."\n    },\n    {\n      "label": "Omogoči spremembo velikosti",\n      "description": "Vsebina se prilagaja širini okna, na voljo pa je tudi gumb za vklop celozaslonskega načina."\n    }\n  ]\n}\n'),
(73, 'sma', '{\n  "semantics": [\n    {\n      "label": "Width",\n      "description": "Width of iFrame in CSS compliant format. Default: \\"500px\\""\n    },\n    {\n      "label": "Minimum width",\n      "description": "Minimum width of iFrame in CSS compliant format. Default: \\"300px\\""\n    },\n    {\n      "label": "Height",\n      "description": "Height of iFrame in CSS compliant format. Default: \\"500px\\""\n    },\n    {\n      "label": "Source",\n      "description": "URI to external document, or path to document found inside H5P (under /content)"\n    },\n    {\n      "label": "Resize supported",\n      "description": "If enabled, fullscreen button will be displayed, and H5P will be resized to fit it''s surroundings"\n    }\n  ]\n}'),
(73, 'sme', '{\n  "semantics": [\n    {\n      "label": "Width",\n      "description": "Width of iFrame in CSS compliant format. Default: \\"500px\\""\n    },\n    {\n      "label": "Minimum width",\n      "description": "Minimum width of iFrame in CSS compliant format. Default: \\"300px\\""\n    },\n    {\n      "label": "Height",\n      "description": "Height of iFrame in CSS compliant format. Default: \\"500px\\""\n    },\n    {\n      "label": "Source",\n      "description": "URI to external document, or path to document found inside H5P (under /content)"\n    },\n    {\n      "label": "Resize supported",\n      "description": "If enabled, fullscreen button will be displayed, and H5P will be resized to fit it''s surroundings"\n    }\n  ]\n}'),
(73, 'smj', '{\n  "semantics": [\n    {\n      "label": "Width",\n      "description": "Width of iFrame in CSS compliant format. Default: \\"500px\\""\n    },\n    {\n      "label": "Minimum width",\n      "description": "Minimum width of iFrame in CSS compliant format. Default: \\"300px\\""\n    },\n    {\n      "label": "Height",\n      "description": "Height of iFrame in CSS compliant format. Default: \\"500px\\""\n    },\n    {\n      "label": "Source",\n      "description": "URI to external document, or path to document found inside H5P (under /content)"\n    },\n    {\n      "label": "Resize supported",\n      "description": "If enabled, fullscreen button will be displayed, and H5P will be resized to fit it''s surroundings"\n    }\n  ]\n}'),
(73, 'sv', '{\n  "semantics": [\n    {\n      "label": "Bredd",\n      "description": "Bredden av din iFrame i CSS format. NormalT värde: \\"500px\\""\n    },\n    {\n      "label": "Minimum bredd",\n      "description": "Minsta bredden som din iFrame kan minskas till i CSS. Normalt verdi: \\"300px\\""\n    },\n    {\n      "label": "Höjd",\n      "description": "Höjden av din iFrame i CSS format. Normalt värde: \\"500px\\""\n    },\n    {\n      "label": "Källa",\n      "description": "URI till externt dokument, eller adress til dokument i H5P (i /content mappen)"\n    },\n    {\n      "label": "Aktivera dynamisk storlek",\n      "description": "Genom att aktivera detta så kommer fullskärmsknapp att visas och innehållet skalas till att använda så mycket plats som möjligt"\n    }\n  ]\n}\n'),
(73, 'sw', '{\n  "semantics": [\n    {\n      "label": "Upana",\n      "description": "Upana wa ukurasa wa wavuti ndani ya ukurasa mama katika umbizo linalotii Laha za Mitindo ya Kuporomoka. Chaguo-msingi: \\"500 pikseli\\""\n    },\n    {\n      "label": "Upana wa chini",\n      "description": "Upana wa chini wa ukurasa wa wavuti ndani ya ukurasa mama (iFrame) katika umbizo linalotii Laha za Mitindo ya Kuporomoka. Chaguo-msingi: \\"300 pikseli (px)\\""\n    },\n    {\n      "label": "Urefu",\n      "description": "Urefu wa ukurasa wa wavuti ndani ya ukurasa mama (iFrame) katika umbizo linalotii Laha za Mitindo ya Kuporomoka. Chaguo-msingi: \\"500 pikseli\\""\n    },\n    {\n      "label": "Chanzo",\n      "description": "Kitambulisho cha Rasilimali Sawa (URI) hadi waraka wa nje, au njia ya waraka inayopatikana ndani ya Kifurushi cha H5P (chini ya/maudhui)"\n    },\n    {\n      "label": "Kubadilisha ukubwa kunakoungwa mkono",\n      "description": "Ikiwashwa, kitufe cha skrini nzima kitaonyeshwa, na Kifurushi cha H5P kitabadilishwa ukubwa wake ili kilingane na mazingira yake"\n    }\n  ]\n}\n'),
(74, 'af', '{\n  "semantics": [\n    {\n      "label": "Beeldbrandpunt vraagredigeerder",\n      "fields": [\n        {\n          "label": "Agtergrondprent",\n          "fields": [\n            {\n              "label": "Agtergrond prent",\n              "description": "Kies ''n prent om te gebruik as agtergrond vir die beeldbrandpunt vraag."\n            }\n          ]\n        },\n        {\n          "label": "Brandpunte",\n          "description": "Sleep en laat die gewenste figuur van die werkbalk af om ''n nuwe brandpunt te skep. Dubbelklik om ''n bestaande brandpunt te wysig. Sleep die brandpunt om dit te skuif. Trek die grootte van die grootte in die onderste regterhoek om die grootte te verander.",\n          "fields": [\n            {\n              "label": "Taakomskrywing",\n              "description": "Instruksies vir die gebruiker."\n            },\n            {\n              "label": "Brandpunt",\n              "entity": "Brandpunt",\n              "field": {\n                "label": "Brandpunt",\n                "fields": [\n                  {\n                    "label": "gebruikerInstellings",\n                    "fields": [\n                      {\n                        "label": "Reg",\n                        "description": "Daar kan verskeie regte brandpunte wees. Die gebruiker kry egter regte/verkeerde terugvoer onmiddellik na die eerste klik."\n                      },\n                      {\n                        "label": "Terugvoer"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "berekendeInstellings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Terugvoer indien die gebruiker ''n leë plek kies:",\n              "placeholder": "Jy het geen brandpunte gevind nie, probeer weer!"\n            },\n            {\n              "label": "Wys terugvoer as ''n opspringer"\n            },\n            {\n              "label": "Lokalisasie",\n              "fields": [\n                {\n                  "label": "Probeer weer knoppie teks",\n                  "default": "Probeer weer"\n                },\n                {\n                  "label": "Sluit knoppieteks",\n                  "default": "Sluit"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Tekstuele tentoonstelling van die telkaart vir diegene wat ''n spreekleser gebruik",\n      "default": "Jy het :num uit :total punte gekry"\n    },\n    {\n      "label": "Hulptegnologieteks beskrywing vir \\"Probeer weer\\" knoppie",\n      "default": "Probeer die taak weer. Herstel alle antwoorde en begin die taak van nuuts af."\n    }\n  ]\n}\n'),
(74, 'ar', '{\n  "semantics": [\n    {\n      "label": "Image Hotspot Question Editor",\n      "fields": [\n        {\n          "label": "صورة الخلفية",\n          "fields": [\n            {\n              "label": "صورة الخلفية",\n              "description": "اختر صورة لاستخدامها كخلفية لسؤال النقطة المركزية للصورة."\n            }\n          ]\n        },\n        {\n          "label": "نقطة ساخنة",\n          "description": "سحب وافلات الشكل المطلوب من شريط الأدوات لإنشاء نقطة فعالة جديدة. انقر نقرًا مزدوجًا لتحرير نقطة فعالة موجودة. اسحب النقطة الفعالة لتحريكها. اسحب معالج تغيير الحجم في الزاوية اليمنى السفلى لتغيير الحجم.",\n          "fields": [\n            {\n              "label": "وصف المهمة",\n              "description": "تعليمات للمستخدم."\n            },\n            {\n              "label": "نقطة فعالة",\n              "entity": "Hotspot",\n              "field": {\n                "label": "نقطة فعالة",\n                "fields": [\n                  {\n                    "label": "اعدادات المستخدم",\n                    "fields": [\n                      {\n                        "label": "صحيح",\n                        "description": "يمكن أن يكون هناك العديد من النقاط الفعالة الصحيحة. ومع ذلك ، يحصل المستخدم على تعليقات صحيحة / غير صحيحة فورًا بعد النقرة الأولى."\n                      },\n                      {\n                        "label": "تعليق"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "الإعدادات المحسوبة"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "رد الفعل إذا اختار المستخدم بقعة فارغة:",\n              "placeholder": "You didn''t locate any hotspots, try again!"\n            },\n            {\n              "label": "إظهار التعليقات كقائمة منبثقة"\n            },\n            {\n              "label": "التمركز",\n              "fields": [\n                {\n                  "label": "نص زر اعادة المحاولة",\n                  "default": "Retry"\n                },\n                {\n                  "label": "نص زر الاغلاق",\n                  "default": "Close"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "تمثيل نصي لشريط النتيجة لأولئك الذين يستخدمون تقنية تحويل النص الى كلام ",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Assistive technology description for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n'),
(74, 'bg', '{\n  "semantics": [\n    {\n      "label": "Редактор за въпроси по изображение с активни точки",\n      "fields": [\n        {\n          "label": "Фоново изображение",\n          "fields": [\n            {\n              "label": "Фоново изображение",\n              "description": "Изберете изображение, което да използвате като фон, за въпроси по изображение с активни точки."\n            }\n          ]\n        },\n        {\n          "label": "Активни зони",\n          "description": "Плъзнете и пуснете желаната фигура от лентата с инструменти, за да създадете нова активна точка. Кликнете два пъти, за да редактирате съществуваща активна точка. Плъзнете активната точка, за да я преместите. Издърпайте манипулатора за преоразмеряване в долния десен ъгъл, за да промените размера.",\n          "fields": [\n            {\n              "label": "Описание на задачата",\n              "description": "Инструкции за потребителя"\n            },\n            {\n              "label": "Активна точка",\n              "entity": "Активна точка",\n              "field": {\n                "label": "Активна точка",\n                "fields": [\n                  {\n                    "label": "userSettings",\n                    "fields": [\n                      {\n                        "label": "Правилно",\n                        "description": "Може да има няколко правилни активни точки. Въпреки това, потребителят получава правилна / неправилна обратна връзка веднага след първото кликване."\n                      },\n                      {\n                        "label": "Обратна връзка"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "computedSettings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Обратна връзка, ако потребителят избере празно място:",\n              "placeholder": "Не намерихте никакви активни точки, опитайте отново!"\n            },\n            {\n              "label": "Покажете обратната връзка като изскачащ прозорец"\n            },\n            {\n              "label": "Превод и локализация",\n              "fields": [\n                {\n                  "label": "Текст за бутона за повторение",\n                  "default": "Повтори"\n                },\n                {\n                  "label": "Текст за бутона за затваряне",\n                  "default": "Затвори"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Текстово представяне на лентата с резултати за тези, които използват екранен четец",\n      "default": "Ти получи :num от общо :total точки"\n    },\n    {\n      "label": "Описание за помощни технологии бутон \\"Опитай пак\\" ",\n      "default": "Опитай задачата отново. Изчистване на всички отговори и започване на задачата отначало."\n    }\n  ]\n}\n'),
(74, 'bs', '{\n  "semantics": [\n    {\n      "label": "Image Hotspot Question Editor",\n      "fields": [\n        {\n          "label": "Background image",\n          "fields": [\n            {\n              "label": "Background image",\n              "description": "Select an image to use as background for the image hotspot question."\n            }\n          ]\n        },\n        {\n          "label": "Hotspots",\n          "description": "Drag and drop the desired figure from the toolbar to create a new hotspot. Double-click to edit an existing hotspot. Drag the hotspot to move it. Pull the resize handler in the lower right corner to resize.",\n          "fields": [\n            {\n              "label": "Task description",\n              "description": "Instructions to the user."\n            },\n            {\n              "label": "Hotspot",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Hotspot",\n                "fields": [\n                  {\n                    "label": "userSettings",\n                    "fields": [\n                      {\n                        "label": "Correct",\n                        "description": "There can be multiple correct hotspots. However, the user gets correct/incorrect feedback immediately after first click."\n                      },\n                      {\n                        "label": "Feedback"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "computedSettings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Feedback if the user selects an empty spot:",\n              "placeholder": "You didn''t locate any hotspots, try again!"\n            },\n            {\n              "label": "Show feedback as a popup"\n            },\n            {\n              "label": "Localization",\n              "fields": [\n                {\n                  "label": "Retry button text",\n                  "default": "Retry"\n                },\n                {\n                  "label": "Close button text",\n                  "default": "Close"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Assistive technology description for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}'),
(74, 'ca', '{\n  "semantics": [\n    {\n      "label": "Editor de preguntes relacionades amb les zones sensibles de la imatge",\n      "fields": [\n        {\n          "label": "Imatge de fons",\n          "fields": [\n            {\n              "label": "Imatge de fons",\n              "description": "Seleccioneu una imatge per utilitzar-la com a fons de la pregunta relacionada amb les zones sensibles de la imatge."\n            }\n          ]\n        },\n        {\n          "label": "Zones sensibles",\n          "description": "Arrossegueu i deixeu anar la figura desitjada de la barra d’eines per crear una zona sensible. Feu doble clic per editar una zona sensible existent. Arrossegueu la zona sensible per moure-la. Estireu el punter de l’extrem inferior dret per canviar-ne la mida.",\n          "fields": [\n            {\n              "label": "Descripció de la tasca",\n              "description": "Instruccions per a l’usuari."\n            },\n            {\n              "label": "Zona sensible",\n              "entity": "Zona sensible",\n              "field": {\n                "label": "Zona sensible",\n                "fields": [\n                  {\n                    "label": "userSettings",\n                    "fields": [\n                      {\n                        "label": "Correcte",\n                        "description": "Hi pot haver diverses zones sensibles correctes. Tanmateix, s’indica a l’usuari si la resposta és correcta o incorrecta després de fer-hi clic per primera vegada."\n                      },\n                      {\n                        "label": "Retroacció"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "computedSettings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Retroacció si l’usuari selecciona un lloc buit:",\n              "placeholder": "No heu localitzat cap zona sensible; torneu-ho a provar!"\n            },\n            {\n              "label": "Mostra els suggeriments com a contingut emergent"\n            },\n            {\n              "label": "Localització",\n              "fields": [\n                {\n                  "label": "Text del botó \\"Torna-ho a provar\\"",\n                  "default": "Torna-ho a provar"\n                },\n                {\n                  "label": "Text del botó de tancar",\n                  "default": "Tanca"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Representació textual de la barra de puntuació pera als que utilitzen un altaveu de lectura",\n      "default": "Heu fet :num de :total punts"\n    },\n    {\n      "label": "Descripció de la tecnologia d’assistència per al botó \\"Torna-ho a provar\\"",\n      "default": "Intenta de nou la tasca. Reajusta totes les respostes i comença la tasca de nou."\n    }\n  ]\n}\n'),
(74, 'cs', '{\n  "semantics": [\n    {\n      "label": "Editor otázek aktivních bodů",\n      "fields": [\n        {\n          "label": "Obrázek na pozadí",\n          "fields": [\n            {\n              "label": "Obrázek na pozadí",\n              "description": "Vyberte obrázek, který chcete použít jako pozadí pro otázku aktivního bodu obrázku."\n            }\n          ]\n        },\n        {\n          "label": "Aktivní body",\n          "description": "Přetažením požadované položky z panelu nástrojů vytvořte nový aktivní bod. Poklepáním upravte existující aktivní bod. Přetažením aktivního bodu jej přesuňte. Chcete-li změnit velikost, zatáhněte za bod změny velikosti v pravém dolním rohu.",\n          "fields": [\n            {\n              "label": "Popis úlohy",\n              "description": "Pokyny pro uživatele."\n            },\n            {\n              "label": "Aktivní bod",\n              "entity": "Aktivní bod",\n              "field": {\n                "label": "Aktivní bod",\n                "fields": [\n                  {\n                    "label": "userSettings",\n                    "fields": [\n                      {\n                        "label": "Správně",\n                        "description": "Může existovat více správných aktivních bodů. Uživatel však dostane správnou/nesprávnou zpětnou vazbu ihned po prvním kliknutí."\n                      },\n                      {\n                        "label": "Zpětná vazba"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "computedSettings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Zpětná vazba, pokud uživatel vybere prázdné místo:",\n              "placeholder": "Nenalezli jste žádné aktivní body, zkuste to znovu!"\n            },\n            {\n              "label": "Zobrazit zpětnou vazbu jako vyskakovací okno"\n            },\n            {\n              "label": "Lokalizace",\n              "fields": [\n                {\n                  "label": "Text opakovacího tlačítka",\n                  "default": "Opakovat"\n                },\n                {\n                  "label": "Text tlačítka zavřít",\n                  "default": "Zavřít"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Textové znázornění výsledkové lišty pro ty, kteří používají čtecí zařízení",\n      "default": "Získal jste :num ze :total bodů"\n    },\n    {\n      "label": "Popisek podpůrné technologie pro tlačítko \\"Opakovat\\"",\n      "default": "Zopakovat úkol. Resetovat všechny odpovědi a spustit úlohu znovu."\n    }\n  ]\n}\n'),
(74, 'cy', '{\n  "semantics": [\n    {\n      "label": "Golygydd Cwestiwn Delwedd â Chlicbwyntiau",\n      "fields": [\n        {\n          "label": "Delwedd gefndir",\n          "fields": [\n            {\n              "label": "Delwedd gefndir",\n              "description": "Dewiswch ddelwedd i''w defnyddio fel cefndir ar gyfer y cwestiwn ''delwedd â chlicbwyntiau''."\n            }\n          ]\n        },\n        {\n          "label": "Clicbwyntiau",\n          "description": "Llusgwch a gollwng y ffigur oddi ar y bar offer i greu clicbwynt newydd. Clic-dwbl i olygu clicbwynt sydd eisoes yn bodoli. Llusgwch y clicbwynt i''w symud. Ailfeintiwch gan dynnu''r ddolen ailfeintio yn y cornel gwaelod ar y chwith.",\n          "fields": [\n            {\n              "label": "Disgrifiad y dasg",\n              "description": "Canllawiau i''r defnyddiwr."\n            },\n            {\n              "label": "Clicbwynt",\n              "entity": "Clicbwynt",\n              "field": {\n                "label": "Clicbwynt",\n                "fields": [\n                  {\n                    "label": "Gosodiadau (Defnyddiwr)",\n                    "fields": [\n                      {\n                        "label": "Cywir",\n                        "description": "Mae sawl clicbwynt cywir. Er, caiff y defnyddiwr adborth cywir/anghywir yn syth ar ôl y clic cyntaf."\n                      },\n                      {\n                        "label": "Adborth"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Gosodiadau (Cyfrifianedig)"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Adborth os ydy defnyddiwr yn dewis pwynt gwag:",\n              "placeholder": "Methoch chi ddarganfod unrhyw glicbwyntiau, ceisiwch eto!"\n            },\n            {\n              "label": "Dangos adborth fel popup"\n            },\n            {\n              "label": "Lleoleiddiad",\n              "fields": [\n                {\n                  "label": "Testun botwm ailgeisio",\n                  "default": "Ailgeisio"\n                },\n                {\n                  "label": "Testun botwm cau",\n                  "default": "Cau"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Cynrychioliad testun o''r bar sgorio ar gyfer y rheiny sy''n defnyddio darllenydd",\n      "default": "Enilloch chi :num allan o :total pwynt"\n    },\n    {\n      "label": "Disgrifiad technoleg cynorthwyol ar gyfer botwm \\"Ailgeisio\\"",\n      "default": "Ailgeisio"\n    }\n  ]\n}\n'),
(74, 'da', '{\n  "semantics": [\n    {\n      "label": "Image Hotspot Question Editor",\n      "fields": [\n        {\n          "label": "Background image",\n          "fields": [\n            {\n              "label": "Background image",\n              "description": "Select an image to use as background for the image hotspot question."\n            }\n          ]\n        },\n        {\n          "label": "Hotspots",\n          "description": "Drag and drop the desired figure from the toolbar to create a new hotspot. Double-click to edit an existing hotspot. Drag the hotspot to move it. Pull the resize handler in the lower right corner to resize.",\n          "fields": [\n            {\n              "label": "Task description",\n              "description": "Instructions to the user."\n            },\n            {\n              "label": "Hotspot",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Hotspot",\n                "fields": [\n                  {\n                    "label": "userSettings",\n                    "fields": [\n                      {\n                        "label": "Correct",\n                        "description": "There can be multiple correct hotspots. However, the user gets correct/incorrect feedback immediately after first click."\n                      },\n                      {\n                        "label": "Feedback"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "computedSettings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Feedback if the user selects an empty spot:",\n              "placeholder": "Du fandt ingen hotspots. Prøv igen."\n            },\n            {\n              "label": "Show feedback as a popup"\n            },\n            {\n              "label": "Localization",\n              "fields": [\n                {\n                  "label": "Retry button text",\n                  "default": "Retry"\n                },\n                {\n                  "label": "Close button text",\n                  "default": "Close"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "Du fik :num ud af :total point."\n    },\n    {\n      "label": "Assistive technology description for \\"Retry\\" button",\n      "default": "Prøv igen. Dette fjerner alle svar og starter opgaven forfra. "\n    }\n  ]\n}'),
(74, 'de', '{\n  "semantics": [\n    {\n      "label": "Editor für Hotspot-Bilder-Aufgaben",\n      "fields": [\n        {\n          "label": "Hintergrundbild",\n          "fields": [\n            {\n              "label": "Hintergrundbild",\n              "description": "Wähle ein Bild als Hintergrundbild für die Hotspot-Bilder-Aufgabe."\n            }\n          ]\n        },\n        {\n          "label": "Hotspots",\n          "description": "Ziehe die gewünschte Form aus der Werkzeugleiste, um einen Hotspot zu erstellen. Per Doppelklick kannst du existierende Hotspots bearbeiten. Hotspots können durch Ziehen verschoben werden. Die Größe lässt sich verändern, indem du an den Ecken des Rahmens ziehst.",\n          "fields": [\n            {\n              "label": "Aufgabenbeschreibung",\n              "description": "Anweisungen für den Nutzer"\n            },\n            {\n              "label": "Hotspot",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Hotspot",\n                "fields": [\n                  {\n                    "label": "Nutzereinstellungen",\n                    "fields": [\n                      {\n                        "label": "Korrekt",\n                        "description": "Es kann mehrere richtige Hotspots geben. Der Nutzer bekommt jedoch unmittelbar nach dem ersten Klick die Rückmeldung, ob der Hotspot richtig oder falsch ist."\n                      },\n                      {\n                        "label": "Rückmeldung"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Berechnete Einstellungen"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Rückmeldung, wenn der Nutzer eine nicht besetzte Stelle anklickt:",\n              "placeholder": "Du hast keinen Hotspot getroffen. Versuch es noch einmal!"\n            },\n            {\n              "label": "Rückmeldung als Popup anzeigen"\n            },\n            {\n              "label": "Bezeichnungen und Beschriftungen",\n              "fields": [\n                {\n                  "label": "Beschriftung des \\"Wiederholen\\"-Buttons",\n                  "default": "Wiederholen"\n                },\n                {\n                  "label": "Beschriftung des \\"Schließen\\"-Buttons",\n                  "default": "Schließen"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Text der Punkteleiste für Vorlesewerkzeuge (Barrierefreiheit)",\n      "default": "Du hast :num von :total Punkten erreicht."\n    },\n    {\n      "label": "Beschreibung des \\"Wiederholen\\"-Buttons (für Hilfsmittel zur Barrierefreiheit)",\n      "default": "Die Aufgabe wiederholen. Alle Versuche werden zurückgesetzt und die Aufgabe wird erneut gestartet."\n    }\n  ]\n}\n'),
(74, 'el', '{\n  "semantics": [\n    {\n      "label": "Επεξεργαστής για Image Hotspot Question",\n      "fields": [\n        {\n          "label": "Εικόνα φόντου",\n          "fields": [\n            {\n              "label": "Εικόνα φόντου",\n              "description": "Επιλέξτε μια εικόνα που θα χρησιμοποιηθεί ως φόντο στην ερώτηση."\n            }\n          ]\n        },\n        {\n          "label": "Hotspots",\n          "description": "Σύρετε και αποθέστε το επιθυμητό σχήμα από τη γραμμή εργαλείων για να δημιουργήσετε ένα νέο hotspot. Κάντε διπλό κλικ για να επεξεργαστείτε ένα υπάρχον hotspot. Σύρετε το hotspot για να το μετακινήσετε. Τραβήξτε τη λαβή αλλαγής μεγέθους στην κάτω δεξιά γωνία για αλλαγή μεγέθους.",\n          "fields": [\n            {\n              "label": "Περιγραφή άσκησης",\n              "description": "Οδηγίες προς τον χρήστη."\n            },\n            {\n              "label": "Hotspot",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Hotspot",\n                "fields": [\n                  {\n                    "label": "Ρυθμίσεις χρήστη",\n                    "fields": [\n                      {\n                        "label": "Σωστό",\n                        "description": "Μπορούν να υπάρχουν πολλαπλά σωστά hotspots. Ωστόσο, ο χρήστης λαμβάνει ανατροφοδότηση για τη σωστή/λάθος απάντηση αμέσως μετά το πρώτο κλικ."\n                      },\n                      {\n                        "label": "Ανατροφοδότηση"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Ρυθμίσεις συστήματος"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Ανατροφοδότηση αν ο χρήστης επιλέξει ένα κενό σημείο:",\n              "placeholder": "Δεν εντόπισες κανένα hotspot, προσπάθησε ξανά!"\n            },\n            {\n              "label": "Εμφάνιση ανατροφοδότησης στο σημείο."\n            },\n            {\n              "label": "Προσαρμογή",\n              "fields": [\n                {\n                  "label": "Ετικέτα κουμπιού νέας προσπάθειας",\n                  "default": "Επανάληψη"\n                },\n                {\n                  "label": "Ετικέτα κουμπιού κλεισίματος",\n                  "default": "Κλείσιμο"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Κειμενική απόδοση της μπάρας βαθμολογίας για όσους χρησιμοποιούν ακουστική υποβοήθηση",\n      "default": "Έχεις :num από :total βαθμούς"\n    },\n    {\n      "label": "Περιγραφή υποστηρικτικής τεχνολογίας για το κουμπί \\"Επανάληψη\\"",\n      "default": "Επαναλάβετε την εργασία. Επαναφέρετε όλες τις απαντήσεις και ξεκινήστε την εργασία από την αρχή."\n    }\n  ]\n}\n'),
(74, 'es', '{\n  "semantics": [\n    {\n      "label": "Editor de Imágenes de Pregunta de Puntos Clave",\n      "fields": [\n        {\n          "label": "Imagen de fondo",\n          "fields": [\n            {\n              "label": "Imagen de fondo",\n              "description": "Seleccione una imagen para usar como fondo de la pregunta de puntos clave en imagen."\n            }\n          ]\n        },\n        {\n          "label": "Puntos clave",\n          "description": "Arrastra y suelta la figura deseada desde la barra de herramientas para crear un nuevo punto clave. Haz doble clic para editar un punto existente. Arrastra el punto para moverlo. Tira del asa de redimensión en la esquina inferior derecha para cambiar el tamaño.",\n          "fields": [\n            {\n              "label": "Descripción de la tarea",\n              "description": "Instrucciones para el usuario."\n            },\n            {\n              "label": "Punto Clave",\n              "entity": "Punto Clave",\n              "field": {\n                "label": "Punto Clave",\n                "fields": [\n                  {\n                    "label": "Ajustes de Usuario",\n                    "fields": [\n                      {\n                        "label": "Correcto",\n                        "description": "Puede haber múltiples puntos clave correctos. Sin embargo, el usuario recibe retroalimentación de correcto/incorrecto inmediatamente después del primer clic."\n                      },\n                      {\n                        "label": "Retroalimentación"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Configuración Calculada"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Retroalimentación si el usuario selecciona un lugar vacío:",\n              "placeholder": "¡No has encontrado ningún punto clave, inténtalo de nuevo!"\n            },\n            {\n              "label": "Mostrar retroalimentación en una ventana emergente"\n            },\n            {\n              "label": "Localización",\n              "fields": [\n                {\n                  "label": "Texto botón Intentar de nuevo",\n                  "default": "Intentar de nuevo"\n                },\n                {\n                  "label": "Texto del botón Cerrar",\n                  "default": "Cerrar"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Representación textual de la barra de puntuación cuando se usa un lector de pantalla",\n      "default": "Has obtenido :num de un total de :total puntos"\n    },\n    {\n      "label": "Descripción para las tecnologías de asistencia del botón \\"Intentar de nuevo\\"",\n      "default": "Vuelve a intentar la tarea. Borra todas tus respuestas y empieza de nuevo."\n    }\n  ]\n}\n'),
(74, 'es-mx', '{\n  "semantics": [\n    {\n      "label": "Editor de Imagen de Pregunta Hotspot",\n      "fields": [\n        {\n          "label": "Imagen de fondo",\n          "fields": [\n            {\n              "label": "Imagen de fondo",\n              "description": "Seleccione una imagen para usar como fondo de la pregunta hotspot de imagen."\n            }\n          ]\n        },\n        {\n          "label": "Hotspots",\n          "description": "Arrastre y suelte la figura deseada desde la barra de herramientas para crear un nuevo hotspot. Haga doble clic para editar un hotspot existente. Arrastra el hotspot para moverlo. Tire del controlador de cambio de tamaño en la esquina inferior derecha para cambiar el tamaño.",\n          "fields": [\n            {\n              "label": "Descripción del trabajo",\n              "description": "Instrucciones para el usuario."\n            },\n            {\n              "label": "Hotspot",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Hotspot",\n                "fields": [\n                  {\n                    "label": "AjustesdelUsuario",\n                    "fields": [\n                      {\n                        "label": "Correcto",\n                        "description": "Puede haber múltiples hotspots correctos. Sin embargo, el usuario recibe retroalimentación de correcto/incorrecto inmediatamente después del primer clic."\n                      },\n                      {\n                        "label": "Retroalimentación"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "AjustesComputados"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Retroalimentación si el usuario selecciona un lugar vacío:",\n              "placeholder": "¡No ha encontrado ningún hotspot, inténtelo de nuevo!"\n            },\n            {\n              "label": "Mostrar retroalimentación en una ventana emergente"\n            },\n            {\n              "label": "Adaptación local",\n              "fields": [\n                {\n                  "label": "Texto del botón Reintentar",\n                  "default": "Reintentar"\n                },\n                {\n                  "label": "Texto del botón Cerrar",\n                  "default": "Cerrar"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Representación textual de la barra de puntaje para aquellos que usan un lector de texto en voz alta",\n      "default": "Obtuvo :num de un total de :total puntos"\n    },\n    {\n      "label": "Descripción de tecnología asistiva para botón \\"Reintentar\\"",\n      "default": "Reintentar el trabajo. Reiniciar todas las respuestas e iniciar el trabajo de nuevo."\n    }\n  ]\n}\n'),
(74, 'et', '{\n  "semantics": [\n    {\n      "label": "Pildi tulipunkti redaktor",\n      "fields": [\n        {\n          "label": "Taustapilt",\n          "fields": [\n            {\n              "label": "Taustapilt",\n              "description": "Vali pildi tulipunkti küsimuse taustapilt."\n            }\n          ]\n        },\n        {\n          "label": "Tulipunktid",\n          "description": "Lohista soovitud kujund tööriistaribalt uue tulipunkti loomiseks. Olemasoleva tulipunkti töötlemiseks topelt-kliki sellel. Tulipunkti liigutamiseks lohista seda. Suuruse muutmiseks tõmba sanga paremal all nurgas.",\n          "fields": [\n            {\n              "label": "Ülesande kirjeldus",\n              "description": "Juhised kasutajale."\n            },\n            {\n              "label": "Tulipunkt",\n              "entity": "Tulipunkt",\n              "field": {\n                "label": "Tulipunkt",\n                "fields": [\n                  {\n                    "label": "Kasutajaseaded",\n                    "fields": [\n                      {\n                        "label": "Õige",\n                        "description": "Õigeid tulipunkte võib olla mitmeid. Kasutaja saab siiski õige/vale tagasiside kohe peale esimest klikki."\n                      },\n                      {\n                        "label": "Tagasiside"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "computedSettings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Tagasiside, kui kasutaja valib tühja koha:",\n              "placeholder": "Sa ei valinud ühtegi tulipunkti, proovi uuesti!"\n            },\n            {\n              "label": "Näita tagasisidet hüpikaknana"\n            },\n            {\n              "label": "Kohandamine",\n              "fields": [\n                {\n                  "label": "Proovi uuesti nupu tekst",\n                  "default": "Proovi uuesti"\n                },\n                {\n                  "label": "Sulge nupu tekst",\n                  "default": "Sulge"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Punktisumma riba tekstiline esitamine neile, kes kasutavad tekstilugerit",\n      "default": "Sa said :num punkti :total punktist"\n    },\n    {\n      "label": "Assistive technology description for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}'),
(74, 'eu', '{\n  "semantics": [\n    {\n      "label": "Leku berodun irudien galderen editorea",\n      "fields": [\n        {\n          "label": "Atzeko planoko irudia",\n          "fields": [\n            {\n              "label": "Atzeko planoko irudia",\n              "description": "Hautatu leku berodun irudien galderen atzeko planoko irudirako."\n            }\n          ]\n        },\n        {\n          "label": "Leku beroak",\n          "description": "Arrastatu eta jaregin tresna barratik nahi duzun irudia leku bero berri bat sortzeko. Klik bikoitza egin dagoen leku bero bat editatzeko. Arrastatu leku beroa tokiz aldatzeko. Tamaina aldatzeko tiratu beheko eskuineko izkinako kontrolatzailetik.",\n          "fields": [\n            {\n              "label": "Zereginaren deskribapena",\n              "description": "Erabiltzailearentzako jarraibideak."\n            },\n            {\n              "label": "Leku beroa",\n              "entity": "Leku beroa",\n              "field": {\n                "label": "Leku beroa",\n                "fields": [\n                  {\n                    "label": "erabiltzaile-ezarpenak",\n                    "fields": [\n                      {\n                        "label": "Zuzena",\n                        "description": "Baliteke leku bero ugari izatea. Hala ere, erabiltzaileak zuzena/okerra feedbacka lehenengo klik egin eta instantean lortzen du."\n                      },\n                      {\n                        "label": "Feedbacka"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Ezarpen konputatuak"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Erabiltzaileak leku huts bat hautatzen duenean agertzen den feedbacka:",\n              "placeholder": "Ez duzu leku bero bakar bat ere kokatu, saiatu berriro!"\n            },\n            {\n              "label": "Erakutsi feedbacka popup moduan"\n            },\n            {\n              "label": "Kokapena",\n              "fields": [\n                {\n                  "label": "Saiatu berriro botoiaren testua",\n                  "default": "Saiatu berriro"\n                },\n                {\n                  "label": "Itxi botoiaren testua",\n                  "default": "Itxi"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Puntuazio barraren testu adierazpena irakurgailua erabiltzen dutenentzat",\n      "default": ":total puntutik :num puntu lortu duzu"\n    },\n    {\n      "label": "\\"Saiatu berriro\\" botoiaren laguntza-teknologientzako etiketa",\n      "default": "Zeregina berriz egiten saiatu. Berrabiarazi erantzun guztiak eta hasi zeregina berriz."\n    }\n  ]\n}\n'),
(74, 'fi', '{\n  "semantics": [\n    {\n      "label": "Hotspot-tehtävän kysymyseditori",\n      "fields": [\n        {\n          "label": "Taustakuva",\n          "fields": [\n            {\n              "label": "Taustakuva",\n              "description": "Valitse tehtävälle taustakuva."\n            }\n          ]\n        },\n        {\n          "label": "Hotspotit",\n          "description": "Raahaa ja pudota haluttu kuvio työkalupalkista hotspotiksi. Tuplaklikkaa olemassaolevaa hotspotia muokataksesi sitä. Raahaa hotspotia siirtääksesi sitä. Vedä sitä oikeasta alakulmasta muuttaaksesi sen kokoa.",\n          "fields": [\n            {\n              "label": "Tehtävän ohje",\n              "description": "Ohje tekijälle, tehtävän alustus."\n            },\n            {\n              "label": "Hotspot",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Hotspot",\n                "fields": [\n                  {\n                    "label": "Asetukset",\n                    "fields": [\n                      {\n                        "label": "Oikea valinta",\n                        "description": "Tehtävässä voi usea hotspot olla oikea valinta. Kuitenkin, käyttäjä saa oikein/väärin -palautteen heti ensimmäisen klikkauksen jälkeen."\n                      },\n                      {\n                        "label": "Palaute"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Lasketut asetukset"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Palaute, kun käyttäjä ei löydä hotspotia:",\n              "placeholder": "Et löytänyt mitään; yritä uudelleen!"\n            },\n            {\n              "label": "Näytä palaute pop up -ikkunana"\n            },\n            {\n              "label": "Lokalisointi",\n              "fields": [\n                {\n                  "label": "Yritä uudelleen painikkeen teksti",\n                  "default": "Retry"\n                },\n                {\n                  "label": "Sulje painikkeen teksti",\n                  "default": "Sulje"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Tekstimuotoinen esitys pistepalkista ruudunlukijalle",\n      "default": "Sait :num pistettä :total pisteestä"\n    },\n    {\n      "label": "Assistive technology description for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}'),
(74, 'fr', '{\n  "semantics": [\n    {\n      "label": "Editeur de questions de l''image interactive",\n      "fields": [\n        {\n          "label": "Image d''arrière-plan",\n          "fields": [\n            {\n              "label": "Image d''arrière-plan",\n              "description": "Sélectionner une image à utiliser comme fond pour la question de la zone réactive de l''image."\n            }\n          ]\n        },\n        {\n          "label": "Zones sensibles",\n          "description": "Sélectionnez la forme de votre choix pour votre zone sensible, redimensionnez-la en l''étirant et placez-la au bon endroit.",\n          "fields": [\n            {\n              "label": "Consigne",\n              "description": "Consigne pour l''utilisateur."\n            },\n            {\n              "label": "Zone sensible",\n              "entity": "Zone sensible",\n              "field": {\n                "label": "Zone sensible",\n                "fields": [\n                  {\n                    "label": "Réglages manuels",\n                    "fields": [\n                      {\n                        "label": "Correct",\n                        "description": "Il peut y avoir plusieurs zones sensibles à trouver. Toutefois, l''utilisateur est averti de la justesse ou non de sa réponse immédiatement après son premier clic."\n                      },\n                      {\n                        "label": "Commentaire de retour"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Réglages calculés automatiquement"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Commentaire si l''utilisateur sélectionne une zone vide :",\n              "placeholder": "Vous n''avez rien trouvé, faîtes un nouvel essai !"\n            },\n            {\n              "label": "Afficher un feedback sur la zone"\n            },\n            {\n              "label": "Localisation",\n              "fields": [\n                {\n                  "label": "Texte du bouton Réessayez",\n                  "default": "Réessayez"\n                },\n                {\n                  "label": "Texte du bouton Fermer",\n                  "default": "Fermer"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Représentation textuelle du panneau du score pour les utilisateurs de la synthèse vocale",\n      "default": "Vous avez :num points sur un total de :total"\n    },\n    {\n      "label": "Assistive technology description for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(74, 'gl', '{\n  "semantics": [\n    {\n      "label": "Editor de Preguntas de Puntos Chave en Imaxes",\n      "fields": [\n        {\n          "label": "Imaxe de fondo",\n          "fields": [\n            {\n              "label": "Imaxe de fondo",\n              "description": "Selecciona unha imaxe para usala como fondo da pregunta de puntos chave en imaxes."\n            }\n          ]\n        },\n        {\n          "label": "Puntos chave",\n          "description": "Arrastra e solta a figura desexada da barra de ferramentas para crear un novo punto chave. Preme dúas veces nun punto chave existente para editalo. Arrastra un punto chave para movelo. Tira da asa de redimensión na esquina inferior dereita para redimensionalo.",\n          "fields": [\n            {\n              "label": "Descrición da tarefa",\n              "description": "Instrucións para o usuario."\n            },\n            {\n              "label": "Punto chave",\n              "entity": "Punto chave",\n              "field": {\n                "label": "Punto chave",\n                "fields": [\n                  {\n                    "label": "Configuación de usuario",\n                    "fields": [\n                      {\n                        "label": "Correcto",\n                        "description": "Pode haber múltiples puntos correctos. Non obstante, o usuario recibe información sobre a corrección ou incorrección do punto inmediatemente despois de premer nel por primeira vez."\n                      },\n                      {\n                        "label": "Retroalimentación"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Configuración rexistrada"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Retroalimentación cando o usuario escolle un punto baleiro:",\n              "placeholder": "Non atopaches ningún punto chave, proba outra vez!"\n            },\n            {\n              "label": "Amosar retroalimentación como xanela emerxente"\n            },\n            {\n              "label": "Adaptación local",\n              "fields": [\n                {\n                  "label": "Texto para o botón reintentar",\n                  "default": "Reintentar"\n                },\n                {\n                  "label": "Texto para o botón pechar",\n                  "default": "Pechar"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Representación textual da barra de puntuación cando se usa un lector de pantalla",\n      "default": "Conseguiches :num puntos de :total"\n    },\n    {\n      "label": "Descrición para as tecnoloxías de asistencia do botón \\"Reintentar\\"",\n      "default": "Reintenta a tarefa. Borra todas as respostas e empeza a tarefa de novo."\n    }\n  ]\n}\n'),
(74, 'he', '{\n  "semantics": [\n    {\n      "label": "עריכת נקודות חמות בשאלות תמונה",\n      "fields": [\n        {\n          "label": "תמונת רקע",\n          "fields": [\n            {\n              "label": "תמונת רקע",\n              "description": "בחירת תמונה שתשמש כרקע לשאלת הנקודה החמה של התמונה."\n            }\n          ]\n        },\n        {\n          "label": "נקודות־חמות",\n          "description": "גרור ושחרר את הסמל הרצוי מסרגל הכלים כדי ליצור נקודה חמה חדשה. לחץ פעמיים כדי לערוך נקודה חמה קיימת. גרור את הנקודה החמה כדי להזיז אותה. משוך את המטפל בשינוי הגודל בפינה הימנית התחתונה כדי לשנות את הגודל.",\n          "fields": [\n            {\n              "label": "תיאור משימה",\n              "description": "הוראות למשתמש."\n            },\n            {\n              "label": "נקודה־חמה",\n              "entity": "נקודה־חמה",\n              "field": {\n                "label": "נקודה־חמה",\n                "fields": [\n                  {\n                    "label": "userSettings",\n                    "fields": [\n                      {\n                        "label": "נכון",\n                        "description": "יכולים להיות מספר נקודות חמות נכונות. עם זאת, המשתמש מקבל משוב נכון/שגוי מיד לאחר הקליק הראשון."\n                      },\n                      {\n                        "label": "משוב"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "computedSettings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "משוב אם המשתמש בוחר מקום ריק:",\n              "placeholder": "לא נמצאו נקודות חמות, נסה שוב!"\n            },\n            {\n              "label": "הצגת משוב בתבנית קופצת"\n            },\n            {\n              "label": "תרגום",\n              "fields": [\n                {\n                  "label": "תוית כפתור ניסיון חוזר",\n                  "default": "נסו שוב"\n                },\n                {\n                  "label": "תוית כפתור סגירה",\n                  "default": "סגירה"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "תצוגה חזותית של סרגל ניקוד למי שמשתמש בתוכנת הקראה",\n      "default": "התקבלו :num מתוך :total נקודות"\n    },\n    {\n      "label": "תיאור טכנולוגיה מסייעת עבור כפתור \\"נסה שוב\\"",\n      "default": "נסו את המשימה שוב. אפסו את כל ניסיונות המענה והתחילו את המשימה מחדש."\n    }\n  ]\n}\n'),
(74, 'hu', '{\n  "semantics": [\n    {\n      "label": "Image Hotspot Question Editor",\n      "fields": [\n        {\n          "label": "Background image",\n          "fields": [\n            {\n              "label": "Background image",\n              "description": "Select an image to use as background for the image hotspot question."\n            }\n          ]\n        },\n        {\n          "label": "Hotspots",\n          "description": "Drag and drop the desired figure from the toolbar to create a new hotspot. Double-click to edit an existing hotspot. Drag the hotspot to move it. Pull the resize handler in the lower right corner to resize.",\n          "fields": [\n            {\n              "label": "Task description",\n              "description": "Instructions to the user."\n            },\n            {\n              "label": "Hotspot",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Hotspot",\n                "fields": [\n                  {\n                    "label": "userSettings",\n                    "fields": [\n                      {\n                        "label": "Correct",\n                        "description": "There can be multiple correct hotspots. However, the user gets correct/incorrect feedback immediately after first click."\n                      },\n                      {\n                        "label": "Feedback"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "computedSettings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Feedback if the user selects an empty spot:",\n              "placeholder": "You didn''t locate any hotspots, try again!"\n            },\n            {\n              "label": "Show feedback as a popup"\n            },\n            {\n              "label": "Localization",\n              "fields": [\n                {\n                  "label": "Retry button text",\n                  "default": "Retry"\n                },\n                {\n                  "label": "Close button text",\n                  "default": "Close"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Assistive technology description for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}'),
(74, 'it', '{\n  "semantics": [\n    {\n      "label": "Editor delle domande di Image Hotspot",\n      "fields": [\n        {\n          "label": "Immagine di sfondo",\n          "fields": [\n            {\n              "label": "Immagine di sfondo",\n              "description": "Seleziona un''immagine da usare come sfondo per la domanda di Image Hotspot"\n            }\n          ]\n        },\n        {\n          "label": "Hotspot",\n          "description": "Trascina e rilascia la figura desiderata dalla barra degli strumenti per creare un nuovo hotspot. Fai doppio clic per modificare un hotspot esistente. Trascina l''hotspot per spostarlo. Tira il punto nell''angolo basso a destra per ridimensionarlo",\n          "fields": [\n            {\n              "label": "Descrizione del compito",\n              "description": "Istruzioni per l''apprendente"\n            },\n            {\n              "label": "Hotspot",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Hotspot",\n                "fields": [\n                  {\n                    "label": "Impostazioni utente",\n                    "fields": [\n                      {\n                        "label": "Corretto",\n                        "description": "Ci possono essere più hotspot corretti. Tuttavia, l''utente ottiene un feedback corretto/sbagliato subito dopo il primo clic"\n                      },\n                      {\n                        "label": "Feedback"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Impostazioni calcolate"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Feedback se l''utente seleziona una zona vuota:",\n              "placeholder": "Non hai individuato nessun hotspot. Riprova!"\n            },\n            {\n              "label": "Mostra il feedback come popup"\n            },\n            {\n              "label": "Localizzazione",\n              "fields": [\n                {\n                  "label": "Testo del pulsante \\"Riprova\\"",\n                  "default": "Riprova"\n                },\n                {\n                  "label": "Testo del pulsante \\"Chiudi\\"",\n                  "default": "Chiudi"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Rappresentazione testuale sulla barra del punteggio per chi usa un lettore vocale",\n      "default": "Il tuo punteggio è :num su :total"\n    },\n    {\n      "label": "Descrizione della tecnologia assistiva per il pulsante \\"Riprova\\"",\n      "default": "Riprova l''esercizio. Risetta tutte le risposte e inizia di nuovo l''esercizio."\n    }\n  ]\n}\n'),
(74, 'ja', '{\n  "semantics": [\n    {\n      "label": "Image Hotspot Question Editor",\n      "fields": [\n        {\n          "label": "Background image",\n          "fields": [\n            {\n              "label": "Background image",\n              "description": "Select an image to use as background for the image hotspot question."\n            }\n          ]\n        },\n        {\n          "label": "Hotspots",\n          "description": "Drag and drop the desired figure from the toolbar to create a new hotspot. Double-click to edit an existing hotspot. Drag the hotspot to move it. Pull the resize handler in the lower right corner to resize.",\n          "fields": [\n            {\n              "label": "Task description",\n              "description": "Instructions to the user."\n            },\n            {\n              "label": "Hotspot",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Hotspot",\n                "fields": [\n                  {\n                    "label": "userSettings",\n                    "fields": [\n                      {\n                        "label": "Correct",\n                        "description": "There can be multiple correct hotspots. However, the user gets correct/incorrect feedback immediately after first click."\n                      },\n                      {\n                        "label": "Feedback"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "computedSettings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Feedback if the user selects an empty spot:",\n              "placeholder": "You didn''t locate any hotspots, try again!"\n            },\n            {\n              "label": "Show feedback as a popup"\n            },\n            {\n              "label": "Localization",\n              "fields": [\n                {\n                  "label": "Retry button text",\n                  "default": "Retry"\n                },\n                {\n                  "label": "Close button text",\n                  "default": "Close"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Textual representation of the score bar for those using a readspeaker",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "Assistive technology description for \\"Retry\\" button",\n      "default": "Retry the task. Reset all responses and start the task over again."\n    }\n  ]\n}'),
(74, 'ka', '{\n  "semantics": [\n    {\n      "label": "გამოსახულების ცხელი წერტილის შეკითხვის რედაქტორი",\n      "fields": [\n        {\n          "label": "ფონური სურათი",\n          "fields": [\n            {\n              "label": "ფონური სურათი",\n              "description": "აირჩიეთ გამოსახულება გამოსახულების ცხელი წერტილის კითხვის ფონად გამოსაყენებლად."\n            }\n          ]\n        },\n        {\n          "label": "ცხელი წერტილები",\n          "description": "გადაიტანეთ და ჩამოაგდეთ სასურველი ფიგურა ხელსაწყოთა ზოლიდან ახალი ცხელი წერტილის შესაქმნელად. ორჯერ დააწკაპუნეთ არსებული ცხელი წერტილის რედაქტირებისთვის. გადაიტანეთ ცხელი წერტილი მის გადასატანად. ზომის შესაცვლელად გაიყვანეთ ზომის შეცვლის დამმუშავებელი ქვედა მარჯვენა კუთხეში.",\n          "fields": [\n            {\n              "label": "ამოცანის აღწერა",\n              "description": "ინსტრუქციები მომხმარებლისთვის."\n            },\n            {\n              "label": "ცხელი წერტილი",\n              "entity": "ცხელი წერტილი",\n              "field": {\n                "label": "ცხელი წერტილი",\n                "fields": [\n                  {\n                    "label": "მომხმარებლის პარამეტრები",\n                    "fields": [\n                      {\n                        "label": "სწორია",\n                        "description": "შეიძლება არსებობდეს მრავალი სწორი ცხელი წერტილი. თუმცა, მომხმარებელი იღებს სწორ/არასწორ გამოხმაურებას პირველი დაწკაპუნებისთანავე."\n                      },\n                      {\n                        "label": "უკუკავშირი"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "დათვლილი პარამეტრები"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "გამოხმაურება, თუ მომხმარებელი აირჩევს ცარიელ ადგილს:",\n              "placeholder": "თქვენ ვერ იპოვნეთ ცხელ წერტილები, სცადეთ ხელახლა!"\n            },\n            {\n              "label": "გამოხმაურების ჩვენება ამომხტარ ფანჯარაში"\n            },\n            {\n              "label": "ლოკალიზაცია",\n              "fields": [\n                {\n                  "label": "წარწერა თავიდან ცდის ღილაკისთვის",\n                  "default": "თავიდან ცდა"\n                },\n                {\n                  "label": "დახურვის ღილაკის ტექსტი",\n                  "default": "დახურვა"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "ტექსტის გამომხმოვანებლის მომხმარებლებისთვის ქულების კოლონის ტექსტური რეპრეზენტაცია",\n      "default": "თქვენ მიიღეთ :num :total ქულიდან"\n    },\n    {\n      "label": "დამხმარე ტექნოლოგიის აღწერა \\"თავიდან ცდის\\" ღილაკისთვის",\n      "default": "თავიდან სცადეთ დავალება. წაშალე ყველა პასუხი და თავიდან სცადე დავალების შესრულება."\n    }\n  ]\n}\n'),
