(74, 'sr', '{\n  "semantics": [\n    {\n      "label": "Image Hotspot Question Editor",\n      "fields": [\n        {\n          "label": "Позадинска слика",\n          "fields": [\n            {\n              "label": "Позадинска слика",\n              "description": "Изаберите слику коју ћете користити као позадину за питање."\n            }\n          ]\n        },\n        {\n          "label": "Вруће тачке",\n          "description": "Drag and drop the desired figure from the toolbar to create a new hotspot. Double-click to edit an existing hotspot. Drag the hotspot to move it. Pull the resize handler in the lower right corner to resize.",\n          "fields": [\n            {\n              "label": "Task description",\n              "description": "Instructions to the user."\n            },\n            {\n              "label": "Врућа тачка",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Врућа тачка",\n                "fields": [\n                  {\n                    "label": "userSettings",\n                    "fields": [\n                      {\n                        "label": "Тачно",\n                        "description": "Може бити више тачних врућих тачака. Међутим, корисник добија тачне / нетачне повратне информације одмах након првог клика."\n                      },\n                      {\n                        "label": "Повратна информација"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "computedSettings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Повратне информације ако корисник изабере празно место:",\n              "placeholder": "Нисте пронашли ниједну врућу тачку, покушајте поново!"\n            },\n            {\n              "label": "Прикажите повратне информације као искачући прозор"\n            },\n            {\n              "label": "Локализација",\n              "fields": [\n                {\n                  "label": "Текст за Врати дугме",\n                  "default": "Врати"\n                },\n                {\n                  "label": "Текст за Затвори дугме",\n                  "default": "Затвори"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Текстуални приказ бодовне траке за оне који користе читач звука",\n      "default": "Освојили сте :num од :total поена"\n    },\n    {\n      "label": "Опис помоћне технологије за \\"Врати\\" дугме",\n      "default": "Покушајте поново са задатком. Ресетујте све одговоре и покрените задатак поново."\n    }\n  ]\n}\n'),
(74, 'sv', '{\n  "semantics": [\n    {\n      "label": "Fråge-redigerare för hotspot-bild",\n      "fields": [\n        {\n          "label": "Bakgrundsbild",\n          "fields": [\n            {\n              "label": "Bakgrundsbild",\n              "description": "Välj en bild att använda som bakgrundsbild för hotspot-frågan."\n            }\n          ]\n        },\n        {\n          "label": "Hotspots",\n          "description": "Drag och släpp den önskade figuren från verktygsfältet för att skapa en ny hotspot. Dubbelklicka för att redigera en befintlig hotspot. Drag en hotspot för att flytta den. Dra i nedre högre hörnet på en hotspot för att ändra storlek.",\n          "fields": [\n            {\n              "label": "Beskrivning av uppgift",\n              "description": "Instruktioner till användaren."\n            },\n            {\n              "label": "Hotspot",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Hotspot",\n                "fields": [\n                  {\n                    "label": "Användarinställningar",\n                    "fields": [\n                      {\n                        "label": "Korrekt",\n                        "description": "Det kan finnas flera korrekta hotspots. Användaren får omedelbar feedback om det var korrekt eller ej efter första klicket."\n                      },\n                      {\n                        "label": "Feedback"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Beräknade inställningar"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Feedback om användaren väljer ett tomt målfält:",\n              "placeholder": "Du träffade inga hotspots, försök igen!"\n            },\n            {\n              "label": "Visa feedback som popup"\n            },\n            {\n              "label": "Lokalisering",\n              "fields": [\n                {\n                  "label": "Text för knappe \\"försök igen\\"",\n                  "default": "Försök igen"\n                },\n                {\n                  "label": "Text för stäng-knapp",\n                  "default": "Stäng"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Hur poängfältet beskrivs för användare med skärmläsare.",\n      "default": "Du fick :num av :total poäng"\n    },\n    {\n      "label": "Hur knappen \\"Försök igen\\" beskrivs för tillgänglighetshjälpmedel",\n      "default": "Försök igen med uppgiften. Nollställer alla svar och börjar om med uppgiften."\n    }\n  ]\n}\n'),
(74, 'sw', '{\n  "semantics": [\n    {\n      "label": "Mhariri wa Swali la Eneo lenye Mtandao",\n      "fields": [\n        {\n          "label": "Picha ya mandharinyuma",\n          "fields": [\n            {\n              "label": "Picha ya mandharinyuma",\n              "description": "Chagua picha ya kutumia kama mandharinyuma kwa picha ya swali la eneo lenye mtandao."\n            }\n          ]\n        },\n        {\n          "label": "Maeneo yenye mtandao",\n          "description": "Buruta na udondoshe kielelezo unachotaka kutoka kwa upau wa zana ili kuunda eneo lenye mtandao jipya. Bofya mara mbili ili kuhariri eneo lenye mtandao lililopo. Buruta eneo hilo lenye mtandao ili ulihamishe. Vuta kipete cha ukubwa kwenye kona ya chini ya kulia ili kubadilisha ukubwa.",\n          "fields": [\n            {\n              "label": "Maelezo ya kazi",\n              "description": "Maelekezo kwa mtumiaji."\n            },\n            {\n              "label": "Eneo lenye mtandao",\n              "entity": "Eneo lenye mtandao",\n              "field": {\n                "label": "Eneo lenye mtandao",\n                "fields": [\n                  {\n                    "label": "Mipangilio ya mtumiaji",\n                    "fields": [\n                      {\n                        "label": "Sahihi",\n                        "description": "Kunaweza kuwa na maeneo mengi sahihi yenye mtandao. Hata hivyo, mtumiaji anapata maoni sahihi/yasiyo sahihi mara baada ya kubofya mara ya kwanza."\n                      },\n                      {\n                        "label": "Maoni"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Mipangilio iliyokokotwa"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Maoni ikiwa mtumiaji atachagua sehemu tupu:",\n              "placeholder": "Hukupata maeneo yoyote yenye mtandao, jaribu tena!"\n            },\n            {\n              "label": "Onyesha maoni kama kiibukizi"\n            },\n            {\n              "label": "Ujanibishaji",\n              "fields": [\n                {\n                  "label": "Maandishi ya kitufe cha kujaribu tena",\n                  "default": "Jaribu tena"\n                },\n                {\n                  "label": "Funga maandishi ya kitufe",\n                  "default": "Funga"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Uwakilishi wa maandishi wa upau wa alama kwa wale wanaotumia kisoma maandishi",\n      "default": "Umepata :num kati ya alama:total"\n    },\n    {\n      "label": "Maelezo ya teknolojia ya usaidizi kwa kitufe cha \\"Jaribu tena\\"",\n      "default": "Jaribu tena kazi hiyo. Weka upya majibu yote na uanze kazi tena."\n    }\n  ]\n}\n'),
(74, 'tr', '{\n  "semantics": [\n    {\n      "label": "Görüntü Etkin Nokta Soru Düzenleyici",\n      "fields": [\n        {\n          "label": "Arkaplan resmi",\n          "fields": [\n            {\n              "label": "Arkaplan resmi",\n              "description": "Resim etkin noktası sorusu için arka plan olarak kullanmak üzere bir resim seçin."\n            }\n          ]\n        },\n        {\n          "label": "Hotspots",\n          "description": "Yeni bir etkin nokta oluşturmak için araç çubuğundan istediğiniz şekli sürükleyip bırakın. Mevcut bir etkin noktayı düzenlemek için çift tıklayın. Taşımak için etkin noktayı sürükleyin. Yeniden boyutlandırmak için sağ alt köşedeki yeniden boyutlandırma işleyicisini çekin.",\n          "fields": [\n            {\n              "label": "Görev tanımı",\n              "description": "Kullanıcı için talimatlar."\n            },\n            {\n              "label": "Hotspot",\n              "entity": "Hotspot",\n              "field": {\n                "label": "Hotspot",\n                "fields": [\n                  {\n                    "label": "userSettings",\n                    "fields": [\n                      {\n                        "label": "Doğru",\n                        "description": "Birden fazla doğru etkin nokta olabilir. Ancak kullanıcı ilk tıklamadan hemen sonra doğru/yanlış geri bildirim alır."\n                      },\n                      {\n                        "label": "Geribildirim"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "computedSettings"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Kullanıcı boş bir yer seçerse geri bildirim:",\n              "placeholder": "You didn''t locate any hotspots, try again!"\n            },\n            {\n              "label": "Geri bildirimi açılır pencere olarak göster"\n            },\n            {\n              "label": "Yerelleştirme",\n              "fields": [\n                {\n                  "label": "Yeniden dene düğmesi metni",\n                  "default": "Yeniden dene"\n                },\n                {\n                  "label": "Düğme metnini kapat",\n                  "default": "Kapat"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Okuma hoparlörü kullananlar için puan çubuğunun metinsel gösterimi",\n      "default": "You got :num out of :total points"\n    },\n    {\n      "label": "\\"Tekrar Dene\\" düğmesi için yardımcı teknoloji açıklaması",\n      "default": "Görevi yeniden deneyin. Tüm yanıtları sıfırlayın ve görevi yeniden başlatın."\n    }\n  ]\n}\n'),
(74, 'uk', '{\n  "semantics": [\n    {\n      "label": "Редактор питань точок доступу зображення",\n      "fields": [\n        {\n          "label": "Фонове зображення",\n          "fields": [\n            {\n              "label": "Фонове зображення",\n              "description": "Виберіть зображення для використання в якості фона точок доступу зображення."\n            }\n          ]\n        },\n        {\n          "label": "Активні точки",\n          "description": "Щоб створити нову точку доступу, перетягніть потрібну фігуру з панелі інструментів. Натисніть двічі, щоб змінити існуючу точку доступу. Перетягніть точку доступу, щоб перемістити її. Щоб змінити розмір, потягніть обробник зміни розміру в нижньому правому куті.",\n          "fields": [\n            {\n              "label": "Опис завдання",\n              "description": "Інструкції для користувача."\n            },\n            {\n              "label": "Точка доступу",\n              "entity": "Точка доступу",\n              "field": {\n                "label": "Точка доступу",\n                "fields": [\n                  {\n                    "label": "Налаштування користувача",\n                    "fields": [\n                      {\n                        "label": "Правильно",\n                        "description": "Можливо кілька правильних точок доступу. Тим не менш, користувач отримує відгук правильно/неправильно відразу після першого натискання."\n                      },\n                      {\n                        "label": "Відгук"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Розраховані параметри"\n                  }\n                ]\n              }\n            },\n            {\n              "label": "Зворотній зв''язок, якщо користувач вибирає порожнє місце:",\n              "placeholder": "Ви не знайшли жодних точок доступу, спробуйте ще раз!"\n            },\n            {\n              "label": "Показати відгук як спливаюче вікно"\n            },\n            {\n              "label": "Локалізація",\n              "fields": [\n                {\n                  "label": "Текст кнопки повтору",\n                  "default": "Повторити"\n                },\n                {\n                  "label": "Текст кнопки закриття",\n                  "default": "Закрити"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Текстове представлення шкали балів для тих, хто використовує озвучення тексту",\n      "default": "Ви отримали :num з :total балів"\n    },\n    {\n      "label": "Опис кнопки \\"Повторити\\" (для інструментів спеціальних можливостей)",\n      "default": "Повторіть завдання. Скиньте всі відповіді та почніть завдання знову."\n    }\n  ]\n}'),
