(80, 'lt', '{\n  "semantics": [\n    {\n      "description": "Aprašymas, ką naudotojas turi įvesti.",\n      "label": "Įvesties lauko aprašymas"\n    },\n    {\n      "description": "Vietos rezervavimo tekstas naudotojui.",\n      "label": "Vietos rezervavimo tekstas"\n    },\n    {\n      "description": "Maksimalus teksto simbolių skaičius.",\n      "label": "Maksimalus teksto ilgis"\n    },\n    {\n      "description": "Įvesties lauko dydis eilučių skaičiumi, kurį jis apims.",\n      "options": [\n        {\n          "label": "1 eilutė"\n        },\n        {\n          "label": "3 eilutės"\n        },\n        {\n          "label": "10 eilučių"\n        }\n      ],\n      "label": "Įvesties lauko dydis"\n    },\n    {\n      "label": "Privalomas laukas",\n      "description": "Pažymėkite, jei norite, kad šis laukas būtų privalomas, naudotojas turi atsakyti į visus privalomus laukus, kad galėtų eksportuoti dokumentą."\n    },\n    {\n      "label": "Likę simboliai",\n      "description": "Pranešimas likusiems simboliams. Galite naudoti @chars, kurie bus pakeisti atitinkamu skaičiumi.",\n      "default": "Likę simboliai: @chars"\n    }\n  ]\n}\n'),
