(80, 'sv', '{\n  "semantics": [\n    {\n      "label": "Beskrivning av inmatningsfält",\n      "description": "Beskrivning av vad användaren ska mata in."\n    },\n    {\n      "label": "Text för platshållare",\n      "description": "En platshållartext för användaren."\n    },\n    {\n      "label": "Max textlängd",\n      "description": "Max antal tecken för texten."\n    },\n    {\n      "label": "Storlek på fält",\n      "description": "Fältets storlek, i antal rader text.",\n      "options": [\n        {\n          "label": "1 rad"\n        },\n        {\n          "label": "3 rader"\n        },\n        {\n          "label": "10 rader"\n        }\n      ]\n    },\n    {\n      "label": "Obligatoriska fält",\n      "description": "Bocka i för att göra detta fält obligatoriskt, användaren måste svara på alla obligagoriska fält för att exportera till ett dokument."\n    },\n    {\n      "label": "Återstående tecken",\n      "default": "Återstående tecken: @chars",\n      "description": "Meddelande om återstående tecken. Du kan använda @chars som kommer att ersättas av korrekt siffra."\n    }\n  ]\n}\n'),
(80, 'sw', '{\n  "semantics": [\n    {\n      "label": "Maelezo ya eneo la ingizo",\n      "description": "Maelezo ya kile ambacho mtumiaji anapaswa kuingiza."\n    },\n    {\n      "label": "Maandishi ya kishika nafasi",\n      "description": "Maandishi ya kishika nafasi kwa mtumiaji."\n    },\n    {\n      "label": "Urefu wa juu wa maandishi",\n      "description": "Idadi ya juu ya herufi kwa maandishi."\n    },\n    {\n      "label": "Kiwango cha eneo la ingizo",\n      "description": "Ukubwa wa sehemu ya kuingiza kwa idadi ya mistari itakayofunika.",\n      "options": [\n        {\n          "label": "mstari 1"\n        },\n        {\n          "label": "mistari 3"\n        },\n        {\n          "label": "mistari 10"\n        }\n      ]\n    },\n    {\n      "label": "Sehemu inayohitajika",\n      "description": "Weka alama ili kufanya sehemu hii kuhitajika, mtumiaji lazima ajibu maeneo yote yanayohitajika ili kuweza kupakua na kutuma waraka."\n    },\n    {\n      "label": "Herufi zilizobaki",\n      "default": "Herufi zilizobaki:@chars",\n      "description": "Ujumbe kwa herufi zilizosalia. Unaweza kutumia@charsambayo itabadilishwa na nambari inayolingana."\n    }\n  ]\n}\n'),
(80, 'tr', '{\n  "semantics": [\n    {\n      "label": "Giriş alanının açıklaması",\n      "description": "Kullanıcının ne girmesi gerektiğinin açıklaması."\n    },\n    {\n      "label": "Yer tutucu metin",\n      "description": "Kullanıcı için bir yer tutucu metin."\n    },\n    {\n      "label": "Maksimum metin uzunluğu",\n      "description": "Metin için maksimum karakter sayısı."\n    },\n    {\n      "label": "Giriş alanı boyutu",\n      "description": "Girdi alanının kapsayacağı satır sayısı cinsinden boyutu.",\n      "options": [\n        {\n          "label": "1 satır"\n        },\n        {\n          "label": "3 satır"\n        },\n        {\n          "label": "10 satır"\n        }\n      ]\n    },\n    {\n      "label": "Gerekli alan",\n      "description": "Bu alanı zorunlu kılmak için işaretleyin, kullanıcının bir belgeyi dışa aktarabilmesi için tüm gerekli alanları yanıtlaması gerekir."\n    },\n    {\n      "label": "Kalan karakterler",\n      "default": "Kalan karakterler: @chars",\n      "description": "Kalan karakterler için mesaj. İlgili numara ile değiştirilecek ifade için  @chars kullanabilirsiniz."\n    }\n  ]\n}\n'),
(80, 'uk', '{\n  "semantics": [\n    {\n      "label": "Опис поля введення",\n      "description": "Опис того, що користувач має ввести."\n    },\n    {\n      "label": "Текст заповнювача",\n      "description": "Текст наповнювача для користувача."\n    },\n    {\n      "label": "Максимальна довжина тексту",\n      "description": "Максимальна кількість символів для тексту."\n    },\n    {\n      "label": "Розмір поля введення",\n      "description": "Розмір поля введення у кількості рядків, що його охоплюватиме.",\n      "options": [\n        {\n          "label": "1 рядок"\n        },\n        {\n          "label": "3 рядка"\n        },\n        {\n          "label": "10 рядків"\n        }\n      ]\n    },\n    {\n      "label": "Обов''язкове поле",\n      "description": "Позначте, щоб зробити це поле обов''язковим, користувач повинен відповісти на всі обов''язкові поля, щоб мати можливість експортувати документ."\n    },\n    {\n      "label": "Залишилось знаків",\n      "default": "Залишилось знаків: @chars",\n      "description": "Повідомлення для знаків, що залишилися. Ви можете використовувати @chars, який буде замінений на відповідне число."\n    }\n  ]\n}\n'),
