(88, 'ca', '{\n  "semantics": [\n    {\n      "label": "Descripció de la tasca"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Opció predeterminada"\n        }\n      ],\n      "label": "Targetes",\n      "entity": "fitxa",\n      "field": {\n        "label": "Fitxa",\n        "fields": [\n          {\n            "label": "Pregunta",\n            "description": "Pregunta textual opcional per a la targeta. (La targeta pot incloure només una imatge, només text o una combinació d’imatge i text.)"\n          },\n          {\n            "label": "Resposta",\n            "description": "Resposta (solució) per a la targeta. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Imatge",\n            "description": "Imatge opcional de la fitxa. (La fitxa pot utilitzar només una imatge, només un text o ambdues)"\n          },\n          {\n            "label": "Text alternatiu per a la imatge"\n          },\n          {\n            "label": "Pista",\n            "fields": [\n              {\n                "label": "Text del consell"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Text del progrés",\n      "default": "Fitxa @card de @total",\n      "description": "Text de progrés, variables disponibles: @card i @total. Exemple: \\"Targeta @card de @total\\""\n    },\n    {\n      "label": "Text del botó següent",\n      "default": "Següent"\n    },\n    {\n      "label": "Text del botó anterior",\n      "default": "Anterior"\n    },\n    {\n      "label": "Text del botó \\"Comprova les respostes\\"",\n      "default": "Verifica"\n    },\n    {\n      "label": "Requereix l’entrada de dades per part de l’usuari abans que es pugui visualitzar la solució"\n    },\n    {\n      "label": "Text per al camp d’entrada de la resposta",\n      "default": "La teva resposta"\n    },\n    {\n      "label": "Text per a resposta correcta",\n      "default": "Correcte"\n    },\n    {\n      "label": "Text per a resposta incorrecta",\n      "default": "Incorrecte"\n    },\n    {\n      "label": "Mostra el text de la solució",\n      "default": "Resposta correcta"\n    },\n    {\n      "label": "Text per al títol de resultats",\n      "default": "Resultats"\n    },\n    {\n      "label": "Text per al nombre de respostes correctes",\n      "default": "@score de @total correcte",\n      "description": "Text de resultats, variables disponibles: @score i @total. Exemple: \\"Correctes: @score\\" de \\"@total\\""\n    },\n    {\n      "label": "Text per mostrar els resultats",\n      "default": "Mostra els resultats"\n    },\n    {\n      "label": "Text per a l’etiqueta de resposta curta",\n      "default": "A:"\n    },\n    {\n      "label": "Text del botó \\"Torna-ho a provar\\"",\n      "default": "Torna-ho a provar"\n    },\n    {\n      "label": "Distingeix entre majúscules i minúscules",\n      "description": "Comprova que l’entrada de text de l’usuari sigui exactament igual que la resposta."\n    },\n    {\n      "label": "Text incorrecte per a les tecnologies d’assistència",\n      "default": "Resposta incorrecta. La resposta correcta es @answer",\n      "description": "Text que s’anunciarà a les tecnologies d’assistència. S’utilitza @answer com a variable."\n    },\n    {\n      "label": "Correct feedback text for assistive technologies",\n      "default": "@answer is correct.",\n      "description": "Text that will be announced to assistive technologies when a card is answered correctly. Use @answer as variable."\n    },\n    {\n      "label": "Canvi de targeta per a les tecnologies d’assistència",\n      "default": "Pàgina @current de @total",\n      "description": "Text que s’anunciarà a les tecnologies d’assistència en navegar per les targetes. S’utilitza @current i @total com a variables."\n    },\n    {\n      "label": "Randomize cards",\n      "description": "Enable to randomize the order of cards on display."\n    }\n  ]\n}\n'),
(88, 'cs', '{\n  "semantics": [\n    {\n      "label": "Popis úlohy"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Výchozí"\n        }\n      ],\n      "label": "Karty",\n      "entity": "karta",\n      "field": {\n        "label": "Karta",\n        "fields": [\n          {\n            "label": "Otázka",\n            "description": "Volitelná textová otázka pro kartu. (Karta může používat pouze obrázek, pouze text nebo obojí)"\n          },\n          {\n            "label": "Odpověď",\n            "description": "Odpověď (řešení) pro kartu. Použijte symbol / k rozdělení alternativních řešení. Použijte \\\\/ pokud by mělo řešení obsahovat /."\n          },\n          {\n            "label": "Obrázek",\n            "description": "Volitelný obrázek pro kartu. (Karta může používat pouze obrázek, pouze text nebo obojí)"\n          },\n          {\n            "label": "Alternativní text pro obrázek"\n          },\n          {\n            "label": "Nápověda",\n            "fields": [\n              {\n                "label": "Text nápovědy"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Text pokroku",\n      "default": "Karet @card z @total",\n      "description": "Text pokroku, dostupné proměnné: @card a @total. Příklad: ''Card @card of @total''"\n    },\n    {\n      "label": "Text pro tlačítko další",\n      "default": "Další"\n    },\n    {\n      "label": "Text pro tlačítko předchozí",\n      "default": "Předchozí"\n    },\n    {\n      "label": "Text pro tlačítko kontrola odpovědi",\n      "default": "Zkontrolovat"\n    },\n    {\n      "label": "Před zobrazením řešení je třeba zadat vstup uživatele"\n    },\n    {\n      "label": "Text pro pole pro zadání odpovědi",\n      "default": "Vaše odpověď"\n    },\n    {\n      "label": "Text pro správnou odpověď",\n      "default": "Správně"\n    },\n    {\n      "label": "Text pro nesprávnou odpověď",\n      "default": "Nesprávně"\n    },\n    {\