(88, 'da', '{\n  "semantics": [\n    {\n      "label": "Task description"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Default"\n        }\n      ],\n      "label": "Cards",\n      "entity": "card",\n      "field": {\n        "label": "Card",\n        "fields": [\n          {\n            "label": "Question",\n            "description": "Optional textual question for the card. (The card may use just an image, just a text or both)"\n          },\n          {\n            "label": "Answer",\n            "description": "Answer (solution) for the card. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Image",\n            "description": "Optional image for the card. (The card may use just an image, just a text or both)"\n          },\n          {\n            "label": "Alternative text for image"\n          },\n          {\n            "label": "Tip",\n            "fields": [\n              {\n                "label": "Tip text"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Progress text",\n      "default": "Kort @card ud af @total ",\n      "description": "Progress text, variables available: @card and @total. Example: ''Card @card of @total''"\n    },\n    {\n      "label": "Text for the next button",\n      "default": "Næste"\n    },\n    {\n      "label": "Text for the previous button",\n      "default": "Forrige"\n    },\n    {\n      "label": "Text for the check answers button",\n      "default": "Tjek"\n    },\n    {\n      "label": "Require user input before the solution can be viewed"\n    },\n    {\n      "label": "Text for the answer input field",\n      "default": "Dit svar"\n    },\n    {\n      "label": "Text for correct answer",\n      "default": "Rigtigt"\n    },\n    {\n      "label": "Text for incorrect answer",\n      "default": "Forkert"\n    },\n    {\n      "label": "Show solution text",\n      "default": "Rigtigt svar:"\n    },\n    {\n      "label": "Text for results title",\n      "default": "Results"\n    },\n    {\n      "label": "Text for number of correct",\n      "default": "@score ud af @total rigtige",\n      "description": "Result text, variables available: @score and @total. Example: ''@score of @total correct''"\n    },\n    {\n      "label": "Text for show results",\n      "default": "Vis resultat"\n    },\n    {\n      "label": "Text for short answer label",\n      "default": "A:"\n    },\n    {\n      "label": "Text for \\"retry\\" button",\n      "default": "Prøv igen"\n    },\n    {\n      "label": "Case sensitive",\n      "description": "Makes sure the user input has to be exactly the same as the answer."\n    },\n    {\n      "label": "Incorrect text for assistive technologies",\n      "default": "Forkert svar. Det rigtige svar var @answer",\n      "description": "Text that will be announced to assistive technologies. Use @answer as variable."\n    },\n    {\n      "label": "Correct feedback text for assistive technologies",\n      "default": "@answer er rigtigt",\n      "description": "Text that will be announced to assistive technologies when a card is answered correctly. Use @answer as variable."\n    },\n    {\n      "label": "Card change for assistive technologies",\n      "default": "Side @current ud af @total",\n      "description": "Text that will be announced to assistive technologies when navigating between cards. Use @current and @total as variables."\n    },\n    {\n      "label": "Bland kort",\n      "description": "Aktivér for at få en tilfældig rækkefølge i visningen af kortene."\n    }\n  ]\n}\n'),
(88, 'de', '{\n  "semantics": [\n    {\n      "label": "Aufgabenbeschreibung"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Eingabemaske"\n        }\n      ],\n      "label": "Karten",\n      "entity": "Karte",\n      "field": {\n        "label": "Karte",\n        "fields": [\n          {\n            "label": "Frage",\n            "description": "Optionaler Fragetext für die Karte. (Es ist nur ein Text, nur ein Bild oder beides möglich)"\n          },\n          {\n            "label": "Antwort",\n            "description": "Antwort (Lösung) für die Karte. Benutze einen Schrägstrich /, um alternative Lösungen voneinander abzugrenzen. Benutze \\\\/, falls eine Lösung ein / enthalten muss."\n          },\n          {\n            "label": "Bild",\n            "description": "Optionales Bild für die Karte. (Es ist nur ein Text, nur ein Bild oder beides möglich)"\n          },\n          {\n            "label": "Alternativtext für das Bild"\n          },\n          {\n            "label": "Tipp",\n            "fields": [\n              {\n                "label": "Tipp-Text"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Text der Fortschrittsanzeige",\n      "default": "Karte @card von @total",\n      "description": "Verfügbare Platzhalter: @card und @total. Beispiel: ''Karte @card von @total''"\n    },\n    {\n      "label": "Beschriftung des \\"Weiter\\"-Buttons",\n      "default": "Weiter"\n    },\n    {\n      "label": "Beschriftung des \\"Zurück\\"-Buttons",\n      "default": "Zurück"\n    },\n    {\n      "label": "Beschriftung des \\"Überprüfen\\"-Buttons",\n      "default": "Überprüfen"\n    },\n    {\n      "label": "Lösung kann erst angezeigt werden, wenn eine Antwort eingegeben wurde"\n    },\n    {\n      "label": "Platzhalter im Antwort-Eingabefeld",\n      "default": "Deine Antwort"\n    },\n    {\n      "label": "Beschriftung für \\"Richtige Antwort\\"",\n      "default": "Richtig"\n    },\n    {\n      "label": "Beschriftung für \\"Falsche Antwort\\"",\n      "default": "Falsch"\n    },\n    {\n      "label": "Beschriftung der Lösung",\n      "default": "Richtige Antwort(en)"\n    },\n    {\n      "label": "Überschrift der Ergebnisseite",\n      "default": "Ergebnisse"\n    },\n    {\n      "label": "Text, der angibt, wie viele Karten richtig waren",\n      "default": "@score von @total richtig",\n      "description": "Verfügbare Platzhalter: @score und @total. Beispiel: ''@score von @total richtig''"\n    },\n    {\n      "label": "Beschriftung des \\"Ergebnisse anzeigen\\"-Buttons",\n      "default": "Ergebnisse anzeigen"\n    },\n    {\n      "label": "Kurzform von \\"Antwort\\"",\n      "default": "A:"\n    },\n    {\n      "label": "Beschriftung des \\"Wiederholen\\"-Buttons",\n      "default": "Wiederholen"\n    },\n    {\n      "label": "Auf Groß-/Kleinschreibung achten",\n      "description": "Stellt sicher, dass die Lösung exakt der Vorgabe entspricht."\n    },\n    {\n      "label": "Bezeichnung einer falschen Antwort für Vorlesewerkzeuge",\n      "default": "Falsche Antwort. Die richtige Antwort ist @answer",\n      "description": "Text, der von Vorlesewerkzeugen vorgelesen wird (Barrierefreiheit). Verwende @answer als Platzhalter."\n    },\n    {\n      "label": "Bezeichnung einer richtigen Antwort für Vorlesewerkzeuge",\n      "default": "@answer ist richtig.",\n      "description": "Text, der durch Vorlesewerkzeuge (Barrierefreiheit) vorgelesen wird, wenn eine Karte richtig beantwortet wird. Nutze @answer als Platzhalter."\n    },\n    {\n      "label": "Text zum Kartenwechsel für Vorlesewerkzeuge",\n      "default": "Karte @current von @total",\n      "description": "Text, der von Vorlesewerkzeugen vorgelesen wird, wenn zwischen Karten gewechselt wird (Barrierefreiheit). Verwende @current und @total als Platzhalter."\n    },\n    {\n      "label": "Karten mischen",\n      "description": "Anwählen, um die Karten zufällig anzuordnen."\n    }\n  ]\n}\n'),
(88, 'el', '{\n  "semantics": [\n    {\n      "label": "Περιγραφή άσκησης"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Βασικό"\n        }\n      ],\n      "label": "Κάρτες",\n      "entity": "καρτας",\n      "field": {\n        "label": "Κάρτα",\n        "fields": [\n          {\n            "label": "Ερώτηση",\n            "description": "Κείμενο ερώτησης για την κάρτα. Η κάρτα μπορεί να έχει μόνο εικόνα, μόνο κείμενο ή και τα δύο (προαιρετικό)"\n          },\n          {\n            "label": "Απάντηση",\n            "description": "Προαιρετική. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Εικόνα",\n            "description": "Εικόνα για την κάρτα. Η κάρτα μπορεί να έχει μόνο εικόνα, μόνο κείμενο ή και τα δύο (προαιρετικό)"\n          },\n          {\n            "label": "Εναλλακτικό κείμενο για την εικόνα"\n          },\n          {\n            "label": "Επεξήγηση",\n            "fields": [\n              {\n                "label": "Επεξηγηματικό κείμενο"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Κείμενο προόδου",\n      "default": "Κάρτα @card από @total",\n      "description": "Κείμενο προόδου, διαθέσιμες μεταβλητές: @card και @total. Παράδειγμα: ''Κάρτα @card από @total''"\n    },\n    {\n      "label": "Ετικέτα κουμπιού μετάβασης στην επόμενη κάρτα",\n      "default": "Επόμενη"\n    },\n    {\n      "label": "Ετικέτα κουμπιού μετάβασης στην προηγούμενη κάρτα",\n      "default": "Προηγούμενη"\n    },\n    {\n      "label": "Ετικέτα κουμπιού ελέγχου απαντήσεων",\n      "default": "Έλεγχος"\n    },\n    {\n      "label": "Απαιτείται καταχώριση απάντησης πριν την εμφάνιση της λύσης"\n    },\n    {\n      "label": "Κείμενο για το πεδίο εισαγωγής απάντησης",\n      "default": "Η απάντησή σου"\n    },\n    {\n      "label": "Κείμενο για σωστή απάντηση",\n      "default": "Σωστό"\n    },\n    {\n      "label": "Κείμενο για λάθος απάντηση",\n      "default": "Λάθος"\n    },\n    {\n      "label": "Κείμενο εμφάνισης λύσης",\n      "default": "Σωστή απάντηση"\n    },\n    {\n      "label": "Κείμενο τίτλου αποτελεσμάτων",\n      "default": "Αποτελέσματα"\n    },\n    {\n      "label": "Κείμενο για αριθμό σωστών απαντήσεων",\n      "default": "@score σωστά από @total",\n      "description": "Κείμενο αποτελεσμάτων, διαθέσιμες μεταβλητές: @score και @total. Παράδειγμα: ''@score σωστά από @total''"\n    },\n    {\n      "label": "Κείμενο εμφάνισης αποτελεσμάτων",\n      "default": "Αποτελέσματα"\n    },\n    {\n      "label": "Κείμενο ετικέτας σύντομης απάντησης",\n      "default": "A:"\n    },\n    {\n      "label": "Κείμενο νέας προσπάθειας",\n      "default": "Επανάληψη"\n    },\n    {\n      "label": "Διάκριση πεζών-κεφαλαίων",\n      "description": "Το κείμενο που εισάγει ο χρήστης πρέπει να είναι ακριβώς το ίδιο (πεζά-κεφαλαία) με την απάντηση."\n    },\n    {\n      "label": "Κείμενο λάθος απάντησης για υποστηρικτικές τεχνολογίες",\n      "default": "Λάθος απάντηση. Σωστή απάντηση η @answer",\n      "description": "Κείμενο που θα χρησιμοποιηθεί από υποστηρικτικές τεχνολογίες. Χρησιμοποιήστε τη μεταβλητή @answer."\n    },\n    {\n      "label": "Κείμενο σωστής απάντησης για υποστηρικτικές τεχνολογίες",\n      "default": "Η απάντηση @answer είναι σωστή.",\n      "description": "Κείμενο που θα χρησιμοποιηθεί από υποστηρικτικές τεχνολογίες όταν μια κάρτα απαντηθεί σωστά. Χρησιμοποιήστε τη μεταβλητή @answer."\n    },\n    {\n      "label": "Κείμενο τρέχουσας κάρτας για υποστηρικτικές τεχνολογίες",\n      "default": "Κάρτα @current από @total",\n      "description": "Κείμενο που θα χρησιμοποιηθεί από υποστηρικτικές τεχνολογίες κατά την πλοήγηση μεταξύ των καρτών. Χρησιμοποιήστε τις μεταβλητές @current, @total."\n    },\n    {\n      "label": "Τυχαιοποίηση καρτών",\n      "description": "Ενεργοποίηση για τυχαία ταξινόμηση της σειράς των καρτών που εμφανίζονται."\n    }\n  ]\n}\n'),
(88, 'es', '{\n  "semantics": [\n    {\n      "label": "Descripción de la tarea"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Por defecto"\n        }\n      ],\n      "label": "Cartas",\n      "entity": "carta",\n      "field": {\n        "label": "Carta",\n        "fields": [\n          {\n            "label": "Pregunta",\n            "description": "Pregunta opcional de texto para la carta. (La carta puede usar sólo una imagen, sólo un texto o ambos)"\n          },\n          {\n            "label": "Respuesta",\n            "description": "Respuesta (solución) para la carta. Use un símbolo de barra / para dividir soluciones alternas. Use \\\\/ si una solución debería de contener una /."\n          },\n          {\n            "label": "Imagen",\n            "description": "Imagen opcional para la carta. (La carta puede usar sólo una imagen, sólo un texto o ambos)"\n          },\n          {\n            "label": "Texto alternativo para la imagen"\n          },\n          {\n            "label": "Pista",\n            "fields": [\n              {\n                "label": "Texto de pista"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Texto de Progreso",\n      "default": "Carta @card de @total",\n      "description": "Texto de Progreso, variables disponibles: @card y @total. Ejemplo: ''Carta @card de @total''"\n    },\n    {\n      "label": "Texto para el botón Siguiente",\n      "default": "Siguiente"\n    },\n    {\n      "label": "Texto para el botón Anterior",\n      "default": "Anterior"\n    },\n    {\n      "label": "Texto para el botón Revisar respuestas",\n      "default": "Comprobar"\n    },\n    {\n      "label": "Requerir entrada del usuario antes de poder ver la solución"\n    },\n    {\n      "label": "Texto para el campo de ingreso de respuesta",\n      "default": "Tu respuesta"\n    },\n    {\n      "label": "Texto para respuesta correcta",\n      "default": "Correcta"\n    },\n    {\n      "label": "Texto para respuesta incorrecta",\n      "default": "Incorrecta"\n    },\n    {\n      "label": "Mostrar texto de solución",\n      "default": "Respuesta(s) correcta(s)"\n    },\n    {\n      "label": "Texto de título para resultados",\n      "default": "Resultados"\n    },\n    {\n      "label": "Texto para número de aciertos",\n      "default": "@score de @total correctos",\n      "description": "Texto de resultados, variables disponibles: @score y @total. Ejemplo: ''@score de @total correctos''"\n    },\n    {\n      "label": "Texto para mostrar resultados",\n      "default": "Mostrar resultados"\n    },\n    {\n      "label": "Texto para etiqueta de respuesta corta",\n      "default": "A:"\n    },\n    {\n      "label": "Texto para botón \\"intentar de nuevo\\"",\n      "default": "Intentar de nuevo"\n    },\n    {\n      "label": "Diferenciar entre MAYÚSCULAS/minúsculas",\n      "description": "Se asegura de que la entrada del usuario tenga que ser exactamente la misma que la respuesta."\n    },\n    {\n      "label": "Texto de respuesta incorrecta para tecnologías de asistencia",\n      "default": "Respuesta incorrecta. La respuesta correcta era @answer",\n      "description": "Texto anunciado a las tecnologías de asistencia. Usa @answer como variable."\n    },\n    {\n      "label": "Texto de retroalimentación para correcto para tecnologías de asistencia",\n      "default": "@answer es correcta.",\n      "description": "Texto anunciado a las tecnologías de asistencia cuando se contesta una tarjeta correctamente. Usa @answer como variable."\n    },\n    {\n      "label": "Cambio de tarjeta para tecnologías de asistencia",\n      "default": "Página @current de @total",\n      "description": "Texto anunciado a las tecnologías de asistencia al navegar entre cartas. Usa @current y @total como variables."\n    },\n    {\n      "label": "Barajar cartas",\n      "description": "Habilitar para barajar el orden de preguntas mostradas."\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(88, 'es-mx', '{\n  "semantics": [\n    {\n      "label": "Descripción del trabajo"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Predeterminado"\n        }\n      ],\n      "label": "Cartas",\n      "entity": "carta",\n      "field": {\n        "label": "Carta",\n        "fields": [\n          {\n            "label": "Pregunta",\n            "description": "Pregunta opcional de texto para la carta. (La carta podría usar solamente una imagen, solo un texto o ambos)"\n          },\n          {\n            "label": "Respuesta",\n            "description": "Respuesta (solución) para la carta. Use un símbolo de barra / para dividir soluciones alternas. Use \\\\/ si una solución debería de contener una /."\n          },\n          {\n            "label": "Imagen",\n            "description": "Imagen opcional para la carta. (La carta podría usar solamente una imagen, solo un texto o ambos)"\n          },\n          {\n            "label": "Texto alternativo para la imagen"\n          },\n          {\n            "label": "Pista",\n            "fields": [\n              {\n                "label": "Texto de pista"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Texto para Progreso",\n      "default": "Carta @card de @total",\n      "description": "Texto del Progreso, variables disponibles: @card y @total. Ejemplo: ''Carta @card de @total''"\n    },\n    {\n      "label": "Texto para el botón Siguiente",\n      "default": "Siguiente"\n    },\n    {\n      "label": "Texto para el botón Anterior",\n      "default": "Anterior"\n    },\n    {\n      "label": "Texto para el botón Comprobar respuestas",\n      "default": "Comprobar"\n    },\n    {\n      "label": "Requerir entrada del usuario antes que la solución pueda ser vista"\n    },\n    {\n      "label": "Texto para el campo de ingreso de respuesta",\n      "default": "Su respuesta"\n    },\n    {\n      "label": "Texto para respuesta correcta",\n      "default": "Correcto"\n    },\n    {\n      "label": "Texto para respuesta incorrecta",\n      "default": "Incorrecta"\n    },\n    {\n      "label": "Texto de Mostrar solución",\n      "default": "Respuesta correcta"\n    },\n    {\n      "label": "Separador de soluciones alternas",\n      "default": "o"\n    },\n    {\n      "label": "Texto para título de resultados",\n      "default": "Resultados",\n      "description": "Texto de Resultados, variables disponibles: @score y @total. Ejemplo: ''@score de @total correctos''"\n    },\n    {\n      "label": "Texto para número de aciertos",\n      "default": "@score de @total correctos"\n    },\n    {\n      "label": "Texto para mostrar resultados",\n      "default": "Mostrar resultados"\n    },\n    {\n      "label": "Texto para etiqueta de respuesta corta",\n      "default": "A:"\n    },\n    {\n      "label": "Texto para botón \\"reintentar\\"",\n      "description": "Asegurarse que la entrada del usuario tenga que ser exactamente la misma que la respuesta."\n    },\n    {\n      "label": "MAYÚSCULAS/minúsculas si importan",\n      "default": "Respuesta incorrecta. La respuesta correcta era @answer",\n      "description": "Asegurarse que la entrada del usuario tenga que ser exactamente la misma que la respuesta."\n    },\n    {\n      "label": "Texto de respuesta incorrecta para tecnologías de asistencia",\n      "default": "Respuesta incorrecta. La respuesta correcta era @answer",\n      "description": "Texto que será anunciado a tecnologías de asistencia. Use @answer como variable."\n    },\n    {\n      "label": "Texto de retroalimentación para correcto para tecnologías de asistencia",\n      "default": "@answer es correcta.",\n      "description": "Texto anunciado a las tecnologías de asistencia cuando se contesta una tarjeta correctamente. Usa @answer como variable."\n    },\n    {\n      "label": "Cambio de tarjeta para tecnologías de asistencia",\n      "description": "Texto anunciado a las tecnologías de asistencia al navegar entre cartas. Usa @current y @total como variables."\n    }\n  ]\n}\n'),
(88, 'et', '{\n  "semantics": [\n    {\n      "label": "Ülesande kirjeldus"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Vaikimisi"\n        }\n      ],\n      "label": "Kaardid",\n      "entity": "kaart",\n      "field": {\n        "label": "Kaart",\n        "fields": [\n          {\n            "label": "Küsimus",\n            "description": "Valikuline tekstiküsimus kaardile. (Kaart võib kasutada vaid pilti, vaid teksti või mõlemat)"\n          },\n          {\n            "label": "Vastus",\n            "description": "Vastus (lahendus) kaardile. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Pilt",\n            "description": "Valikuline pilt kaardile. (Kaart võib kasutada vaid pilti, vaid teksti või mõlemat)"\n          },\n          {\n            "label": "Alternative text for image"\n          },\n          {\n            "label": "Vihje",\n            "fields": [\n              {\n                "label": "Vihje tekst"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Edasijõudmise tekst",\n      "default": "Kaart @card / @total",\n      "description": "Edasijõudmise tekst, kasutatavad muutujad on: @card ja @total. Näiteks: ''Kaart @card / @total''"\n    },\n    {\n      "label": "Järgmine nupu tekst",\n      "default": "Järgmine"\n    },\n    {\n      "label": "Eelmine nupu tekst",\n      "default": "Eelmine"\n    },\n    {\n      "label": "Vastuste kontrolli nupu tekst",\n      "default": "Kontrolli"\n    },\n    {\n      "label": "Nõua kasutaja sisendit enne, kui lahendust saab vaadata"\n    },\n    {\n      "label": "Vastuse sisestamisvälja tekst",\n      "default": "Sinu vastus"\n    },\n    {\n      "label": "Õige vastuse tekst",\n      "default": "Õige"\n    },\n    {\n      "label": "Vale vastuse tekst",\n      "default": "Vale"\n    },\n    {\n      "label": "Lahenduse näitamise tekst",\n      "default": "Õige vastus"\n    },\n    {\n      "label": "Tulemuste pealkirja tekst",\n      "default": "Tulemused"\n    },\n    {\n      "label": "Õigete vastuste arvu tekst",\n      "default": "@score / @total õiget vastust",\n      "description": "Tulemuste tekst, kasutatavad muutujad: @score ja @total. Näiteks: ''@score / @total õiget''"\n    },\n    {\n      "label": "Tulemuste näitamise tekst",\n      "default": "Näita tulemusi"\n    },\n    {\n      "label": "Lühikese vastusesildi tekst",\n      "default": "A:"\n    },\n    {\n      "label": "\\"Proovi uuesti\\" nupu tekst",\n      "default": "Proovi uuesti"\n    },\n    {\n      "label": "Tõstutundlik",\n      "description": "Kontrollib, et kasutaja sisend oleks täpselt sama, mis vastus (suur-/väiketähed)."\n    },\n    {\n      "label": "Incorrect text for assistive technologies",\n      "default": "Incorrect answer. Correct answer was @answer",\n      "description": "Text that will be announced to assistive technologies. Use @answer as variable."\n    },\n    {\n      "label": "Correct feedback text for assistive technologies",\n      "default": "@answer is correct.",\n      "description": "Text that will be announced to assistive technologies when a card is answered correctly. Use @answer as variable."\n    },\n    {\n      "label": "Card change for assistive technologies",\n      "default": "Page @current of @total",\n      "description": "Text that will be announced to assistive technologies when navigating between cards. Use @current and @total as variables."\n    },\n    {\n      "label": "Randomize cards",\n      "description": "Enable to randomize the order of cards on display."\n    }\n  ]\n}\n'),
(88, 'eu', '{\n  "semantics": [\n    {\n      "label": "Lanaren deskribapena"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Lehentsitakoa"\n        }\n      ],\n      "label": "Txartelak",\n      "entity": "txartela",\n      "field": {\n        "label": "Txartela",\n        "fields": [\n          {\n            "label": "Galdera",\n            "description": "Txartelarentzako aukerazko testu-galdera. (Txartelak soilik irudia, soilik testua edo erabili ditzake)"\n          },\n          {\n            "label": "Erantzuna",\n            "description": "Erantzuna. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Irudia",\n            "description": "Aukerako irudia (txartelak izango du bakarrik irudia, bakarrik testua edo biak)"\n          },\n          {\n            "label": "Irudiaren ordezko testua"\n          },\n          {\n            "label": "Argibidea",\n            "fields": [\n              {\n                "label": "Argibidearen testua"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Aurrerapenaren testua",\n      "default": "@card / @total txartela",\n      "description": "Aurrerapenaren testua, erabiltzen diren aldagaiak: @card eta @total. Adibidea: ''@card / @total txartela''"\n    },\n    {\n      "label": "Hurrengoa botoiaren testua",\n      "default": "Hurrengoa"\n    },\n    {\n      "label": "Aurrekoa botoiaren testua",\n      "default": "Aurrekoa"\n    },\n    {\n      "label": "\\"Egiaztatu\\" botoiarentzako testua",\n      "default": "Egiaztatu"\n    },\n    {\n      "label": "Aldez aurretik erabiltzaileak sartu behar du erantzun bat"\n    },\n    {\n      "label": "Erantzuna sartzeko eremuaren testua",\n      "default": "Zure erantzuna"\n    },\n    {\n      "label": "Erantzun zuzenerako testua",\n      "default": "Erantzun zuzena"\n    },\n    {\n      "label": "Erantzun okerraren testua",\n      "default": "Erantzun okerra"\n    },\n    {\n      "label": "Erakutsi erantzun zuzena testua",\n      "default": "Erantzun zuzena(k)"\n    },\n    {\n      "label": "Emaitzen tituluaren testua",\n      "default": "Emaitzak"\n    },\n    {\n      "label": "Erantzun zuzenen kopuruaren testua",\n      "default": "@score / @total zuzenak",\n      "description": "Erantzun zuzenen testua, erabiltzen dituen aldagaiak: @score eta @total. Adibidea: ''@score / @total zuzenak''"\n    },\n    {\n      "label": "Bistaratu emaitzak testua",\n      "default": "Bistaratu emaitzak"\n    },\n    {\n      "label": "Erantzun laburraren etiketaren testua",\n      "default": "Erantzuna:"\n    },\n    {\n      "label": "\\"Saiatu berriro\\" botoiarentzako testua",\n      "default": "Saiatu berriro"\n    },\n    {\n      "label": "Bereizi maiuskulak eta minuskulak",\n      "description": "Ezartzen du erabiltzailearen sarrera izan behar duela erantzunaren berdina."\n    },\n    {\n      "label": "Erantzun okerrarentzako testua laguntzarako teknologientzat",\n      "default": "Erantzun okerra. Erantzun zuzena @answer zen",\n      "description": "Laguntzarako teknologietan erabiliko den testua. Erabili @answer aldagai gisa."\n    },\n    {\n      "label": "Erantzun zuzenerako feedbackaren testua laguntza teknologietarako",\n      "default": "@answer zuzena da.",\n      "description": "Txartel bati modu zuzenean erantzunez gero laguntza teknologientzako iragarriko den testua. @answer aldagi gisa erabili dezakezu."\n    },\n    {\n      "label": "Txartel aldaketa laguntzarako teknologientzat",\n      "default": "@current. orria, @total guztira",\n      "description": "Laguntzarako teknologietan txartel artean nabigatzean erabiliko den testua. Erabili @current eta @total aldagai gisa."\n    },\n    {\n      "label": "Ausazko txartelak",\n      "description": "Gaitu pantailako txartelen ordena ausazkoa izatea."\n    }\n  ]\n}\n'),
(88, 'fi', '{\n  "semantics": [\n    {\n      "label": "Tehtävänkuvaus"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Oletus"\n        }\n      ],\n      "label": "Kortit",\n      "entity": "kortti",\n      "field": {\n        "label": "Kortti",\n        "fields": [\n          {\n            "label": "Kysymys",\n            "description": "Kortin kysymysteksti, ei pakollinen kenttä. (kortti voi sisältää pelkän kuvan, pelkän tekstin tai sisältää kuvan ja tekstin)"\n          },\n          {\n            "label": "Vastaus",\n            "description": "Vastaus (ei pakollinen kenttä). Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Kuva",\n            "description": "Kortin kuva (ei pakollinen kenttä) Kortti voi sisältää pelkän kuvan, pelkän tekstin tai sisältää kuvan ja tekstin"\n          },\n          {\n            "label": "Alternative text for image"\n          },\n          {\n            "label": "Vihje",\n            "fields": [\n              {\n                "label": "Vihjeteksti"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Etenemisteksti",\n      "default": "Kortti @card / @total",\n      "description": "Etenemisteksti, käytettävissä olevat muuttujat @card ja @total Esimerkiksi: ''Kortti @card / @total''"\n    },\n    {\n      "label": "Seuraava-painikkeen teksti",\n      "default": "Seuraava"\n    },\n    {\n      "label": "Takaisin-painikkeen teksti",\n      "default": "Takaisin"\n    },\n    {\n      "label": "Tarkista vastaukset -painikkeen teksti",\n      "default": "Tarkista vastaukset"\n    },\n    {\n      "label": "Vaadi käyttäjältä vastaus ennen kuin ratkaisu näytetään."\n    },\n    {\n      "label": "Vastauskentän teksti",\n      "default": "Vastauksesi"\n    },\n    {\n      "label": "Oikean vastauksen teksti",\n      "default": "Oikein"\n    },\n    {\n      "label": "Väärän vastauksen teksti",\n      "default": "Väärin"\n    },\n    {\n      "label": "Näytä vastaukset teksti",\n      "default": "Oikea vastaus"\n    },\n    {\n      "label": "Tulokset otsikko",\n      "default": "Tulokset"\n    },\n    {\n      "label": "Teksti oikein saaduille vastauksille",\n      "default": "@score / @total oikein",\n      "description": "tulosteksti, käytettävissä olevat muuttujat: @score ja @total. Esimerkki: ''@score / @total oikein''"\n    },\n    {\n      "label": "Näytä tulokset teksti",\n      "default": "Näytä tulokset"\n    },\n    {\n      "label": "Lyhyen vastauksen teksti",\n      "default": "A:"\n    },\n    {\n      "label": "Teksti \\"retry\\" painikkeelle",\n      "default": "Yritä uudelleen"\n    },\n    {\n      "label": "merkkikokoriippuvainen",\n      "description": "Määrittää tuleeko vastauksen olla identtinen määritellyn vastauksen mukaisesti (eli isot ja pienet kirjaimet huomioidaan jne.)"\n    },\n    {\n      "label": "Incorrect text for assistive technologies",\n      "default": "Incorrect answer. Correct answer was @answer",\n      "description": "Text that will be announced to assistive technologies. Use @answer as variable."\n    },\n    {\n      "label": "Correct feedback text for assistive technologies",\n      "default": "@answer is correct.",\n      "description": "Text that will be announced to assistive technologies when a card is answered correctly. Use @answer as variable."\n    },\n    {\n      "label": "Card change for assistive technologies",\n      "default": "Page @current of @total",\n      "description": "Text that will be announced to assistive technologies when navigating between cards. Use @current and @total as variables."\n    },\n    {\n      "label": "Sekoita kortit",\n      "description": "Tällä valinnalla voit satunnaistaa korttien esiintymisjärjestyksen."\n    }\n  ]\n}\n'),
(88, 'fr', '{\n  "semantics": [\n    {\n      "label": "Consigne"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Par défaut"\n        }\n      ],\n      "label": "Cartes",\n      "entity": "carte",\n      "field": {\n        "label": "Carte",\n        "fields": [\n          {\n            "label": "Question",\n            "description": "Question facultative pour la carte. (La carte peut contenir une image seule, un texte seul ou les deux combinés)"\n          },\n          {\n            "label": "Réponse",\n            "description": "Réponse (solution) pour la carte. Utiliser une barre oblique / pour séparer les solutions alternatives. Utilisez \\\\/ si une solution doit contenir un /."\n          },\n          {\n            "label": "Image",\n            "description": "Image facultative pour la carte. (La carte peut contenir une image seule, un texte seul ou les deux combinés)"\n          },\n          {\n            "label": "Texte alternatif pour l''image"\n          },\n          {\n            "label": "Indice",\n            "fields": [\n              {\n                "label": "Texte de l''indice"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Texte de progression",\n      "default": "Carte @card sur @total",\n      "description": "Texte de progression, variables possibles : @card et @total. (Exemple : ''Carte @card sur @total'')"\n    },\n    {\n      "label": "Texte pour le bouton \\"Suivant\\"",\n      "default": "Suivant"\n    },\n    {\n      "label": "Texte pour le bouton \\"Précédent\\"",\n      "default": "Précédent"\n    },\n    {\n      "label": "Texte pour le bouton \\"Vérifier\\"",\n      "default": "Vérifier"\n    },\n    {\n      "label": "Obliger l''utilisateur à entrer une réponse avant de pouvoir afficher la correction"\n    },\n    {\n      "label": "Texte pour le champ de saisie de la réponse",\n      "default": "Votre réponse"\n    },\n    {\n      "label": "Texte pour la bonne réponse",\n      "default": "Réponse exacte"\n    },\n    {\n      "label": "Texte pour une mauvaise réponse",\n      "default": "Réponse inexacte"\n    },\n    {\n      "label": "Afficher le texte de la solution",\n      "default": "Réponse(s) correcte(s)"\n    },\n    {\n      "label": "Texte pour l''intitulé des résultats",\n      "default": "Résultats"\n    },\n    {\n      "label": "Texte pour le nombre de bonnes réponses",\n      "default": "@score réponses correctes sur un total de @total",\n      "description": "Texte des résultats, variables disponibles: @score et @total. Exemple: ''@score réponses correctes sur un total de @total''"\n    },\n    {\n      "label": "Texte pour montrer les résultats",\n      "default": "Montrer les résultats"\n    },\n    {\n      "label": "Texte pour l''intitulé de réponse courte",\n      "default": "R :"\n    },\n    {\n      "label": "Texte pour le bouton \\"Recommencer\\"",\n      "default": "Recommencer"\n    },\n    {\n      "label": "Sensible à la casse",\n      "description": "Impose que la saisie de l''utilisateur soit strictement identique à la réponse attendue."\n    },\n    {\n      "label": "Texte de réponse incorrecte pour les outils d''accessibilité",\n      "default": "Réponse incorrecte. La réponse correcte était @answer",\n      "description": "Texte qui sera annoncé aux outils d''accessibilité. Utilisez @réponse comme variable."\n    },\n    {\n      "label": "Feedback de réponse correcte pour les outils d''accessibilité",\n      "default": "@answer est correct.",\n      "description": "Texte qui sera annoncé aux outils d''accessibilité lorsqu''une réponse correcte est donnée. Utilisez @réponse comme variable."\n    },\n    {\n      "label": "Changement de carte pour les outils d''accessibilité",\n      "default": "Page @current de @total",\n      "description": "Texte qui sera annoncé aux outils d''accessibilité lors de la navigation entre les cartes. Utilisez @current et @total comme variables."\n    },\n    {\n      "label": "Mélanger les cartes",\n      "description": "Activer l''affichage des réponses dans un ordre aléatoire."\n    }\n  ]\n}\n'),
(88, 'gl', '{\n  "semantics": [\n    {\n      "label": "Descrición da tarefa"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Por defecto"\n        }\n      ],\n      "label": "Tarxetas",\n      "entity": "tarxeta",\n      "field": {\n        "label": "Tarxeta",\n        "fields": [\n          {\n            "label": "Pregunta",\n            "description": "Pregunta de texto opcional para a tarxeta. (A tarxeta pode usar só unha imaxe, só texto ou ambos)"\n          },\n          {\n            "label": "Resposta",\n            "description": "Resposta (solución) para a tarxeta. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Imaxe",\n            "description": "Imaxe opcional para a tarxeta. (A tarxeta pode usar só unha imaxe, só texto ou ambos)"\n          },\n          {\n            "label": "Texto alternativo para a imaxe"\n          },\n          {\n            "label": "Pista",\n            "fields": [\n              {\n                "label": "Texto da pista"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Texto de progreso",\n      "default": "Tarxeta @card de @total",\n      "description": "Texto de progreso; variables dispoñibles: @card e @total. Exemplo: ''Tarxeta @card de @total''"\n    },\n    {\n      "label": "Texto para o botón seguinte",\n      "default": "Seguinte"\n    },\n    {\n      "label": "Texto para o botón anterior",\n      "default": "Anterior"\n    },\n    {\n      "label": "Texto para o botón comprobar respostas",\n      "default": "Comprobar"\n    },\n    {\n      "label": "Requerir resposta do usuario antes de que poida ver a solución"\n    },\n    {\n      "label": "Texto para o campo de resposta",\n      "default": "A túa resposta"\n    },\n    {\n      "label": "Texto para resposta correcta",\n      "default": "Correcto"\n    },\n    {\n      "label": "Texto para resposta incorrecta",\n      "default": "Incorrecta"\n    },\n    {\n      "label": "Texto para amosar a solución",\n      "default": "Resposta(s) correcta(s)"\n    },\n    {\n      "label": "Texto para o título dos resultados",\n      "default": "Resultados"\n    },\n    {\n      "label": "Texto para número de respostas correctas",\n      "default": "@score de @total son correctas",\n      "description": "Texto para resultados, variables dispoñibles: @score e @total. Exemplo: ''@score de @total son correctas''"\n    },\n    {\n      "label": "Texto para amosar resultados",\n      "default": "Amosar resultados"\n    },\n    {\n      "label": "Texto para etiqueta de resposta curta",\n      "default": "R:"\n    },\n    {\n      "label": "Texto para o botón \\"reintentar\\"",\n      "default": "Reintentar"\n    },\n    {\n      "label": "Diferencia entre maiúsculas e minúsculas",\n      "description": "Fai que o texto introducido polo usuario teña que ser exactamente igual que a resposta."\n    },\n    {\n      "label": "Texto de resposta incorrecta para tecnoloxías de asistencia",\n      "default": "Resposta incorrecta. A resposta correcta era @answer",\n      "description": "O texto pasarase ás tecnoloxías de asistencia. Usa @answer como variable."\n    },\n    {\n      "label": "Texto de retroalimentación de resposta correcta para as tecnoloxías de asistencia",\n      "default": "@answer é correcta.",\n      "description": "Texto que se anunciará ás tecnoloxías de asistencia cando o usuario responde a unha tarxeta correctamente. Usa @answer como variable."\n    },\n    {\n      "label": "Cambio de tarxeta para as tecnoloxías de asistencia",\n      "default": "Páxina @current de @total",\n      "description": "O texto pasarase ás tecnoloxías de asistencia cando se navegue entre tarxetas. Usa @current e @total como variables."\n    },\n    {\n      "label": "Facer aleatorias as tarxetas",\n      "description": "Activar para facer aleatoria a orde das tarxetas amosadas."\n    }\n  ]\n}\n'),
(88, 'he', '{\n  "semantics": [\n    {\n      "label": "תיאור משימה"\n    },\n    {\n      "widgets": [\n        {\n          "label": "ברירת מחדל"\n        }\n      ],\n      "label": "כרטיסים",\n      "entity": "כרטיס",\n      "field": {\n        "label": "כרטיס",\n        "fields": [\n          {\n            "label": "שאלה",\n            "description": "שאלה טקסטואלית אופציונלית לכרטיס. (הכרטיס עשוי להשתמש רק בתמונה, רק בטקסט או בשניהם)"\n          },\n          {\n            "label": "תשובה",\n            "description": "תשובה (פתרון) לכרטיס. השתמש בסמל צינור / לפצל פתרונות חלופיים. השתמש ב-\\\\/ אם פתרון צריך להכיל /."\n          },\n          {\n            "label": "תמונה",\n            "description": "תמונה אופציונלית לכרטיס. (הכרטיס עשוי להשתמש רק בתמונה, רק בטקסט או בשניהם)"\n          },\n          {\n            "label": "טקסט חלופי לתמונה"\n          },\n          {\n            "label": "עצה",\n            "fields": [\n              {\n                "label": "תוכן העצה"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "טקסט התקדמות",\n      "default": "כרטיס @card מתוך @total",\n      "description": "תוית התקדמות, משתנים זמינים: @card ו-@total. דוגמה: ''כרטיס @card של @total"\n    },\n    {\n      "label": "טקסט לכפתור הבא",\n      "default": "הבא"\n    },\n    {\n      "label": "טקסט לכפתור הקודם",\n      "default": "הקודם"\n    },\n    {\n      "label": "טקסט לכפתור בדיקת התשובות",\n      "default": "בדיקה"\n    },\n    {\n      "label": "דרושת תגובת משתמש לפני שניתן יהיה לצפות בפתרון"\n    },\n    {\n      "label": "טקסט עבור שדה הקלט של התשובה",\n      "default": "תשובתך"\n    },\n    {\n      "label": "טקסט לתשובה הנכונה",\n      "default": "נכון"\n    },\n    {\n      "label": "טקסט לתשובה לא נכונה",\n      "default": "שגוי"\n    },\n    {\n      "label": "הראה טקסט לתשובה",\n      "default": "תשובות נכונות"\n    },\n    {\n      "label": "טקסט לכותרת התוצאות",\n      "default": "תוצאות"\n    },\n    {\n      "label": "טקסט למספר הנכונות",\n      "default": "@score מתוך @total נכונים",\n      "description": "טקסט תוצאה, משתנים זמינים: @score ו-@total. דוגמה: ''@score של @total הנכונות''"\n    },\n    {\n      "label": "טקסט לתוצאות המופע",\n      "default": "תצוגת תוצאות"\n    },\n    {\n      "label": "טקסט עבור תווית תשובות קצרות",\n      "default": "A:"\n    },\n    {\n      "label": "טקסט עבור כפתור \\"נסה שוב\\".",\n      "default": "ניסיון חוזר"\n    },\n    {\n      "label": "התאמה לאותיות גדולות/קנות באנגלית",\n      "description": "מוודא שתשובת המשתמש חייבת להיות זהה בדיוק לתשובה."\n    },\n    {\n      "label": "תוכן לא נכון עבור טכנולוגיות מסייעות",\n      "default": "תשובה לא נכונה. התשובה הנכונה הייתה anwser@",\n      "description": "תוכן יוקרא בקול לטכנולוגיות מסייעות. השתמשו ב- answer@ כמשתנה."\n    },\n    {\n      "label": "טקסט משוב נכון עבור טכנולוגיות מסייעות",\n      "default": "@answer תשובה נכונה.",\n      "description": "טקסט שיוכרז לטכנולוגיות מסייעות כאשר כרטיס יענה נכון. השתמש ב-@answer כמשתנה."\n    },\n    {\n      "label": "החלפת כרטיס עבור טכנולוגיות מסייעות",\n      "default": "דף current@ מתוך total@",\n      "description": "תוכן שיוקרא לטכנולוגיות מסייעות בעת ניווט בין כרטיסים. השתמשו ב- current@ ו- total@ כמשתנים."\n    },\n    {\n      "label": "כרטיסים אקראיים",\n      "description": "אפשר להפוך את סדר הקלפים המוצגים באופן אקראי."\n    }\n  ]\n}\n'),
(88, 'hu', '{\n  "semantics": [\n    {\n      "label": "Task description"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Default"\n        }\n      ],\n      "label": "Cards",\n      "entity": "card",\n      "field": {\n        "label": "Card",\n        "fields": [\n          {\n            "label": "Question",\n            "description": "Optional textual question for the card. (The card may use just an image, just a text or both)"\n          },\n          {\n            "label": "Answer",\n            "description": "Answer (solution) for the card. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Image",\n            "description": "Optional image for the card. (The card may use just an image, just a text or both)"\n          },\n          {\n            "label": "Alternative text for image"\n          },\n          {\n            "label": "Tip",\n            "fields": [\n              {\n                "label": "Tip text"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Progress text",\n      "default": "Card @card of @total",\n      "description": "Progress text, variables available: @card and @total. Example: ''Card @card of @total''"\n    },\n    {\n      "label": "Text for the next button",\n      "default": "Next"\n    },\n    {\n      "label": "Text for the previous button",\n      "default": "Previous"\n    },\n    {\n      "label": "Text for the check answers button",\n      "default": "Check"\n    },\n    {\n      "label": "Require user input before the solution can be viewed"\n    },\n    {\n      "label": "Text for the answer input field",\n      "default": "Your answer"\n    },\n    {\n      "label": "Text for correct answer",\n      "default": "Correct"\n    },\n    {\n      "label": "Text for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "Show solution text",\n      "default": "Correct answer(s)"\n    },\n    {\n      "label": "Text for results title",\n      "default": "Results"\n    },\n    {\n      "label": "Text for number of correct",\n      "default": "@score of @total correct",\n      "description": "Result text, variables available: @score and @total. Example: ''@score of @total correct''"\n    },\n    {\n      "label": "Text for show results",\n      "default": "Show results"\n    },\n    {\n      "label": "Text for short answer label",\n      "default": "A:"\n    },\n    {\n      "label": "Text for \\"retry\\" button",\n      "default": "Retry"\n    },\n    {\n      "label": "Case sensitive",\n      "description": "Makes sure the user input has to be exactly the same as the answer."\n    },\n    {\n      "label": "Incorrect text for assistive technologies",\n      "default": "Incorrect answer. Correct answer was @answer",\n      "description": "Text that will be announced to assistive technologies. Use @answer as variable."\n    },\n    {\n      "label": "Correct feedback text for assistive technologies",\n      "default": "@answer is correct.",\n      "description": "Text that will be announced to assistive technologies when a card is answered correctly. Use @answer as variable."\n    },\n    {\n      "label": "Card change for assistive technologies",\n      "default": "Page @current of @total",\n      "description": "Text that will be announced to assistive technologies when navigating between cards. Use @current and @total as variables."\n    },\n    {\n      "label": "Randomize cards",\n      "description": "Enable to randomize the order of cards on display."\n    }\n  ]\n}\n'),
(88, 'it', '{\n  "semantics": [\n    {\n      "label": "Descrizione del compito"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Predefinito"\n        }\n      ],\n      "label": "Schede",\n      "entity": "scheda",\n      "field": {\n        "label": "Scheda",\n        "fields": [\n          {\n            "label": "Domanda",\n            "description": "Domanda testuale facoltativa per la scheda (la scheda può utilizzare solo un''immagine, solo un testo o entrambi)"\n          },\n          {\n            "label": "Risposta",\n            "description": "Risposta (soluzione) facoltativa per la scheda Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Immagine",\n            "description": "Immagine facoltativa per la scheda (la scheda può utilizzare solo un''immagine, solo un testo o entrambi)"\n          },\n          {\n            "label": "Testo alternativo per l''immagine"\n          },\n          {\n            "label": "Suggerimento",\n            "fields": [\n              {\n                "label": "Testo del suggerimento"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Testo di avanzamento",\n      "default": "Scheda @card di @total",\n      "description": "Testo di avanzamento, variabili disponibili: @card e @total. Esempio: ''Scheda @card di @total''"\n    },\n    {\n      "label": "Testo per il pulsante \\"Prossima\\"",\n      "default": "Prossima"\n    },\n    {\n      "label": "Testo per il pulsante \\"Precedente\\"",\n      "default": "Precedente"\n    },\n    {\n      "label": "Testo per il pulsante \\"Verifica\\"",\n      "default": "Verifica"\n    },\n    {\n      "label": "Richiedere l''immissione dei dati all''utente prima che la soluzione sia visualizzata"\n    },\n    {\n      "label": "Messaggio della casella di testo per la risposta",\n      "default": "La tua risposta"\n    },\n    {\n      "label": "Messaggio per risposta giusta",\n      "default": "Giusto"\n    },\n    {\n      "label": "Messaggio per risposta sbagliata",\n      "default": "Sbagliato"\n    },\n    {\n      "label": "Mostra il testo della soluzione",\n      "default": "Risposta giusta"\n    },\n    {\n      "label": "Titolo del messaggio per i risultati",\n      "default": "Risultati"\n    },\n    {\n      "label": "Messaggio per il numero di risposte giuste",\n      "default": "@score su @total giuste",\n      "description": "Messaggio del risultato, variabili disponibili: @score e @total. Esempio: ''@score su @total giuste''"\n    },\n    {\n      "label": "Messaggio per mostrare i risultati",\n      "default": "Mostra i risultati"\n    },\n    {\n      "label": "Testo per l''etichetta della risposta breve",\n      "default": "A:"\n    },\n    {\n      "label": "Testo per il pulsante \\"Riprova\\"",\n      "default": "Riprova"\n    },\n    {\n      "label": "Tieni conto di maiuscole e minuscole",\n      "description": "Accertati che il testo immesso dall''utente sia identico alla risposta attesa"\n    },\n    {\n      "label": "Testo sbagliato per le tecnologie assistive",\n      "default": "Risposta sbagliata. La risposta giusta era @answer",\n      "description": "Testo per le tecnologie assistive. Usa @answer come variabile"\n    },\n    {\n      "label": "Correct feedback text for assistive technologies",\n      "default": "@answer is correct.",\n      "description": "Text that will be announced to assistive technologies when a card is answered correctly. Use @answer as variable."\n    },\n    {\n      "label": "Cambio scheda per le tecnologie assistive",\n      "default": "Pagina @current di @total",\n      "description": "Testo per le tecnologie assistive durante la navigazione tra schede. Usa @current e @total come variabili"\n    },\n    {\n      "label": "Randomize cards",\n      "description": "Enable to randomize the order of cards on display."\n    }\n  ]\n}\n'),
