(88, 'nl', '{\n  "semantics": [\n    {\n      "label": "Taakomschrijving"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Standaard"\n        }\n      ],\n      "label": "Kaarten",\n      "entity": "kaart",\n      "field": {\n        "label": "Kaart",\n        "fields": [\n          {\n            "label": "Vraag",\n            "description": "De optionele vraag voorop de kaart. (De kaart kan voorzien worden van een afbeelding en/of tekst)"\n          },\n          {\n            "label": "Antwoord",\n            "description": "Het optionele antwoord (oplossing) achterop de kaart. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Afbeelding",\n            "description": "De optionele afbeelding voorop de kaart. (De kaart kan voorzien worden van een afbeelding en/of tekst)"\n          },\n          {\n            "label": "Alternatieve tekst voor afbeelding"\n          },\n          {\n            "label": "Tip",\n            "fields": [\n              {\n                "label": "Tekst voor tip"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Voortgangstekst",\n      "default": "Kaart @card van @total",\n      "description": "Voortgangstekst, beschikbare variabelen: @card en @total. Voorbeeld: ''Kaart @card van @total''"\n    },\n    {\n      "label": "Tekst voor \\"Volgende\\"-knop",\n      "default": "Volgende"\n    },\n    {\n      "label": "Tekst voor \\"Vorige\\"-knop",\n      "default": "Vorige"\n    },\n    {\n      "label": "Tekst voor \\"Controleer\\"-knop",\n      "default": "Controleer"\n    },\n    {\n      "label": "Gebruikersinvoer is vereist, voordat de oplossing kan worden bekeken"\n    },\n    {\n      "label": "Tekst voor het antwoord invoerveld",\n      "default": "Je antwoord"\n    },\n    {\n      "label": "Tekst voor juist antwoord",\n      "default": "Juist"\n    },\n    {\n    