(88, 'ro', '{\n  "semantics": [\n    {\n      "label": "Task description"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Default"\n        }\n      ],\n      "label": "Cards",\n      "entity": "card",\n      "field": {\n        "label": "Card",\n        "fields": [\n          {\n            "label": "Question",\n            "description": "Optional textual question for the card. (The card may use just an image, just a text or both)"\n          },\n          {\n            "label": "Answer",\n            "description": "Answer (solution) for the card. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Image",\n            "description": "Optional image for the card. (The card may use just an image, just a text or both)"\n          },\n          {\n            "label": "Alternative text for image"\n          },\n          {\n            "label": "Tip",\n            "fields": [\n              {\n                "label": "Tip text"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Progress text",\n      "default": "Card @card of @total",\n      "description": "Progress text, variables available: @card and @total. Example: ''Card @card of @total''"\n    },\n    {\n      "label": "Text for the next button",\n      "default": "Next"\n    },\n    {\n      "label": "Text for the previous button",\n      "default": "Previous"\n    },\n    {\n      "label": "Text for the check answers button",\n      "default": "Check"\n    },\n    {\n      "label": "Require user input before the solution can be viewed"\n    },\n    {\n      "label": "Text for the answer input field",\n      "default": "Your answer"\n    },\n    {\n      "label": "Text for correct answer",\n      "default": "Correct"\n    },\n    {\n      "label": "Text for incorrect answer",\n      "default": "Incorrect"\n    },\n    {\n      "label": "Show solution text",\n      "default": "Correct answer(s)"\n    },\n    {\n      "label": "Text for results title",\n      "default": "Results"\n    },\n    {\n      "label": "Text for number of correct",\n      "default": "@score of @total correct",\n      "description": "Result text, variables available: @score and @total. Example: ''@score of @total correct''"\n    },\n    {\n      "label": "Text for show results",\n      "default": "Show results"\n    },\n    {\n      "label": "Text for short answer label",\n      "default": "A:"\n    },\n    {\n      "label": "Text for \\"retry\\" button",\n      "default": "Retry"\n    },\n    {\n      "label": "Case sensitive",\n      "description": "Makes sure the user input has to be exactly the same as the answer."\n    },\n    {\n      "label": "Incorrect text for assistive technologies",\n      "default": "Incorrect answer. Correct answer was @answer",\n      "description": "Text that will be announced to assistive technologies. Use @answer as variable."\n    },\n    {\n      "label": "Correct feedback text for assistive technologies",\n      "default": "@answer is correct.",\n      "description": "Text that will be announced to assistive technologies when a card is answered correctly. Use @answer as variable."\n    },\n    {\n      "label": "Card change for assistive technologies",\n      "default": "Page @current of @total",\n      "description": "Text that will be announced to assistive technologies when navigating between cards. Use @current and @total as variables."\n    },\n    {\n      "label": "Randomize cards",\n      "description": "Enable to randomize the order of cards on display."\n    }\n  ]\n}\n'),
(88, 'ru', '{\n  "semantics": [\n    {\n      "label": "Описание задачи"\n    },\n    {\n      "widgets": [\n        {\n          "label": "По умолчанию"\n        }\n      ],\n      "label": "Карточки",\n      "entity": "карточка",\n      "field": {\n        "label": "Карточка",\n        "fields": [\n          {\n            "label": "Вопрос",\n            "description": "Необязательный вопрос для карточки. (Можно использовать только изображение, только текст или оба одновременно)"\n          },\n          {\n            "label": "Ответ",\n            "description": "Ответ или решение для карточки. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Изображение",\n            "description": "Необязательное изображение для карточки. (Можно использовать только изображение, только текст или оба одновременно)"\n          },\n          {\n            "label": "Альтернативный текст вместо изображения"\n          },\n          {\n            "label": "Подсказка",\n            "fields": [\n              {\n                "label": "Текст подсказки"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Текст прогресса",\n      "default": "Карточка @card их @total",\n      "description": "Текст прогресса, доступные переменные: @card и @total. Пример: ''Карточка @card из @total''"\n    },\n    {\n      "label": "Текст для кнопки Дальше",\n      "default": "Дальше"\n    },\n    {\n      "label": "Текст для кнопки Назад",\n      "default": "Назад "\n    },\n    {\n      "label": "Текст для кнопки Проверить решение",\n      "default": "Проверить"\n    },\n    {\n      "label": "Требовать ввод пользователя до того, как решение может быть показано"\n    },\n    {\n      "label": "Текст для поля ответа",\n      "default": "Ответ"\n    },\n    {\n      "label": "Текст для правильного ответа",\n      "default": "Правильно"\n    },\n    {\n      "label": "Текст для неправильного ответа",\n      "default": "Неправильно"\n    },\n    {\n      "label": "Текст показать решение",\n      "default": "показать решение"\n    },\n    {\n      "label": "Текст для заголовка результатов",\n      "default": "Результат"\n    },\n    {\n      "label": "Текст для количества правильных ответов",\n      "default": "Правильно @score из @total",\n      "description": "Текст результатов, доступные переменные: @score и @total. Пример: ''@score из @total правильно''"\n    },\n    {\n      "label": "Текст для открытия результатов",\n      "default": "Показать результат"\n    },\n    {\n      "label": "Текст для ярлыка краткого ответа",\n      "default": "A:"\n    },\n    {\n      "label": "Текст для кнопки \\"повторить\\" ",\n      "default": "повторить"\n    },\n    {\n      "label": "Чувствительность",\n      "description": "Требует, чтобы ввод пользователя в точности совпадал с ответом."\n    },\n    {\n      "label": "Текст неправильного ответа для ассистирующих технологии",\n      "default": "Неправильный ответ. Правильным ответом является @answer",\n      "description": "Текст, объявляемый ассистирующими технологиями. Использовать @answer в качестве переменной."\n    },\n    {\n      "label": "Correct feedback text for assistive technologies",\n      "default": "@answer is correct.",\n      "description": "Text that will be announced to assistive technologies when a card is answered correctly. Use @answer as variable."\n    },\n    {\n      "label": "Смена карточки для ассистирующих технологии",\n      "default": "Карточка @current из @total",\n      "description": "Текст, объявляемый ассистирующими технологиями при смене карточек. Использовать @current и @total в качестве переменных."\n    },\n    {\n      "label": "Randomize cards",\n      "description": "Enable to randomize the order of cards on display."\n    }\n  ]\n}\n'),
(88, 'sl', '{\n  "semantics": [\n    {\n      "label": "Navodilo udeležencem"\n    },\n    {\n      "widgets": [\n        {\n          "label": "Privzeto"\n        }\n      ],\n      "label": "Kartice",\n      "entity": "kartica",\n      "field": {\n        "label": "Kartica",\n        "fields": [\n          {\n            "label": "Vprašanje",\n            "description": "Neobvezno vprašanje za kartico. Na kartici je lahko samo slika, samo besedilo ali oboje."\n          },\n          {\n            "label": "Odgovor",\n            "description": "Odgovor na vprašanje. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /."\n          },\n          {\n            "label": "Slika",\n            "description": "Neobvezna slika za kartico. Na kartici je lahko samo slika, samo besedilo ali oboje."\n          },\n          {\n            "label": "Nadomestno besedilo za sliko"\n          },\n          {\n            "label": "Namig",\n            "fields": [\n              {\n                "label": "Besedilo namiga"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "label": "Besedilo napredka",\n      "default": "Kartica @card od @total",\n      "description": "Spremenljivki v besedilu napredka sta @card in @total."\n    },\n    {\n      "label": "Besedilo za gumb \\"Naprej\\"",\n      "default": "Naprej"\n    },\n    {\n      "label": "Besedilo za gumb \\"Nazaj\\"",\n      "default": "Nazaj"\n    },\n    {\n      "label": "Besedilo za gumb \\"Preveri\\"",\n      "default": "Preveri"\n    },\n    {\n      "label": "Pred ogledom rešitve je potrebno podati vse odgovore"\n    },\n    {\n      "label": "Besedilo za polje za vnos odgovorov",\n      "default": "Odgovor na vprašanje"\n    },\n    {\n      "label": "Besedilo za pravilen odgovor",\n      "default": "Pravilen odgovor"\n    },\n    {\n      "label": "Besedilo za nepravilen odgovor",\n      "default": "Nepravilen odgovor"\n    },\n    {\n      "label": "Besedilo za prikaz rešitve",\n      "default": "Prikaži rešitev"\n    },\n    {\n      "label": "Besedilo za naslov rezultatov",\n      "default": "Rezultati"\n    },\n    {\n      "label": "Besedilo za število pravilnih",\n      "default": "Pravilnih @score od @total",\n      "description": "Spremenljivki sta @score in @total."\n    },\n    {\n      "label": "Besedilo za prikaz rezultatov",\n      "default": "Prikaz rezultatov"\n    },\n    {\n      "label": "Besedilo za oznako kratkega odgovora",\n      "default": "A:"\n    },\n    {\n      "label": "Besedilo za gumb \\"Poskusi ponovno\\"",\n      "default": "Poskusi ponovno"\n    },\n    {\n      "label": "Loči velike/male črke",\n      "description": "Razlikuje med zapisom v velikih ali malih tiskanih črkah."\n    },\n    {\n      "label": "Besedilo za nepravilen odgovor za bralnike zaslona",\n      "default": "Nepravilen odgovor. Pravilen odgovor bi bil @answer",\n      "description": "@answer je spremenljivka."\n    },\n    {\n      "label": "Besedilo za pravilen odgovor za bralnike zaslona",\n      "default": "@answer je pravilen odgovor.",\n      "description": "@answer je spremenljivka."\n    },\n    {\n      "label": "Sprememba statusa pri obračanju kartice za bralnike zaslona",\n      "default": "Stran @current od @total",\n      "description": "@current in @total sta spremenljivki."\n    },\n    {\n      "label": "Randomize cards",\n      "description": "Enable to randomize the order of cards on display."\n    }\n  ]\n}\n');
