(90, 'af', '{\n  "semantics": [\n    {\n      "label": "Prente",\n      "field": {\n        "label": "Prent skyfie",\n        "fields": [\n          {\n            "label": "Prent Skyfie"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Beeldverhouding",\n      "description": "Met outomaties word ''n vaste beeldverhouding bedoel wat outomaties bepaal word op grond van die prente",\n      "options": [\n        {\n          "label": "Outomaties"\n        },\n        {\n          "label": "Pasgemaak"\n        },\n        {\n          "label": "Nie vasgestel nie"\n        }\n      ]\n    },\n    {\n      "label": "Beeldverhouding instellings",\n      "fields": [\n        {\n          "label": "Beeldverhouding wydte",\n          "description": "Indien jy 4 hier en 3 vir die hoogte gebruik, is die beeldverhouding 4:3"\n        },\n        {\n          "label": "Beeldverhouding hoogte",\n          "description": "As jy hier 3 en 4 vir die breedte gebruik, is die beeldverhouding 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Beeldskyfie toeganklikheid",\n      "fields": [\n        {\n          "label": "Etiket vir volgende skyfie knoppies",\n          "default": "Volgende Prent",\n          "description": "Hierdie word slegs vir spreeklesers gebruik. Dit sal nie vertoon word nie."\n        },\n        {\n          "label": "Etiket vir vorige skyfie knoppie",\n          "default": "Vorige Prent",\n          "description": "Hierdie word slegs vir spreeklesers gebruik. Dit sal nie vertoon word nie."\n        },\n        {\n          "label": "Etiket vir skyfieknoppie",\n          "default": "Gaan na prent %slide",\n          "description": "Hierdie word slegs vir spreeklesers gebruik. Dit sal nie vertoon word nie. %slide is ''n veranderlike en sal vervang word deur ''n prentnommer."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'ar', '{\n  "semantics": [\n    {\n      "label": "صور",\n      "field": {\n        "label": "شريحة صور",\n        "fields": [\n          {\n            "label": "شريحة صور"\n          }\n        ]\n      }\n    },\n    {\n      "label": "أبعاد النسبة",\n      "description": "تلقائي يعني أبعاد النسبة الثابتة والتي تحدد حسب الصور",\n      "options": [\n        {\n          "label": "آلي"\n        },\n        {\n          "label": "عرف"\n        },\n        {\n          "label": "غير ثابت"\n        }\n      ]\n    },\n    {\n      "label": "إعدادات أبعاد النسبة",\n      "fields": [\n        {\n          "label": "عرض أبعاد النسبة",\n          "description": "إذا كنت تستخدم 4 هنا، و 3 لارتفاع أبعاد النسبة فسيكون 4:3"\n        },\n        {\n          "label": "ارتفاع أبعاد النسبة",\n          "description": "إذا كنت تستخدم 3 هنا، و 4 لعرض أبعاد النسبة فسيكون 4:3"\n        }\n      ]\n    },\n    {\n      "label": "إمكانية الوصول لشريط تمرير الصور",\n      "fields": [\n        {\n          "label": "التسمية لأزرار الشريحة التالية",\n          "default": "الصورة التالية",\n          "description": "تستخدم هذه فقط لبرامج read-speakers. لن تعرض."\n        },\n        {\n          "label": "التسمية لأزرار الشريحة السابقة",\n          "default": "الصورة السابقة",\n          "description": "تستخدم هذه فقط لبرامج read-speakers. لن تعرض."\n        },\n        {\n          "label": "التسمية لأزرار الشريحة",\n          "default": "انتقل للصورة %slide",\n          "description": "تستخدم هذه فقط لبرامج read-speakers. لن تُعرض. %slide متغير وسيُستبدل برقم الصورة."\n        }\n      ]\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(90, 'bg', '{\r\n  "semantics": [\r\n    {\r\n      "label": "Изображения",\r\n      "field": {\r\n        "label": "Слайд с изображение",\r\n        "fields": [\r\n          {\r\n            "label": "Слайд с изображение"\r\n          }\r\n        ]\r\n      }\r\n    },\r\n    {\r\n      "label": "Съотношение на аспектите",\r\n      "description": "Автоматично означава, че фиксираното съотношение на аспекта се определя автоматично на база на размера на отделните изображения",\r\n      "options": [\r\n        {\r\n          "label": "Автоматично"\r\n        },\r\n        {\r\n          "label": "Персонализирано"\r\n        },\r\n        {\r\n          "label": "Без корекция"\r\n        }\r\n      ]\r\n    },\r\n    {\r\n      "label": "Настройки на съотношението на аспекта",\r\n      "fields": [\r\n        {\r\n          "label": "Ширина на съотношението на аспекта",\r\n          "description": "Ако тук използвате 4 и 3 за височина, съотношението на страните ще бъде 4:3"\r\n        },\r\n        {\r\n          "label": "Височина на съотношението на аспекта",\r\n          "description": "Ако тук използвате 3 и 4 за ширина, съотношението на страните ще бъде 4:3"\r\n        }\r\n      ]\r\n    },\r\n    {\r\n      "label": "Достъпност на слайдера с изображения",\r\n      "fields": [\r\n        {\r\n          "label": "Етикет за бутоните за следващ слайд",\r\n          "default": "Следващо изображение",\r\n          "description": "Това се използва единствено от четците на глас. Няма да се показва на екрана."\r\n        },\r\n        {\r\n          "label": "Етикет за бутоните за предишен слайд",\r\n          "default": "Предишно изображение",\r\n          "description": "Това се използва единствено от четците на глас. Няма да се показва на екрана."\r\n        },\r\n        {\r\n          "label": "Етикет за бутоните за слайд",\r\n          "default": "Към изображение %slide",\r\n          "description": "Това се използва единствено от четците на глас. Няма да се показва на екрана. %slide е променлива, която ще бъде заместена с номера на изображението."\r\n        }\r\n      ]\r\n    }\r\n  ]\r\n}\r\n'),
(90, 'ca', '{\n  "semantics": [\n    {\n      "label": "Imatges",\n      "field": {\n        "label": "Diapositiva d’imatge",\n        "fields": [\n          {\n            "label": "Diapositiva d’imatge"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Relació d’aspecte",\n      "description": "\\"Automàtica\\" fa referència a una relació d’aspecte fixa que es determina automàticament en funció de les imatges",\n      "options": [\n        {\n          "label": "Automàtic"\n        },\n        {\n          "label": "Personalitzar"\n        },\n        {\n          "label": "No fixa"\n        }\n      ]\n    },\n    {\n      "label": "Arranjament de la relació d’aspecte",\n      "fields": [\n        {\n          "label": "Amplada de la relació d’aspecte",\n          "description": "Si utilitzeu 3 aquí, i 4 per a l’amplada, la relació d’aspecte serà 4:3"\n        },\n        {\n          "label": "Alçada de la relació d’aspecte",\n          "description": "Si utilitzeu 3 aquí, i 4 per a l’amplada, la relació d’aspecte serà 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Accessibilitat del control lliscant de la imatge",\n      "fields": [\n        {\n          "label": "Etiqueta del botó de diapositiva següent",\n          "default": "Imatge següent",\n          "description": "Només s’utilitza per a altaveus de lectura. No es mostrarà."\n        },\n        {\n          "label": "Etiqueta del botó de diapositiva anterior",\n          "default": "Imatge anterior",\n          "description": "Només s’utilitza per a altaveus de lectura. No es mostrarà."\n        },\n        {\n          "label": "Etiqueta per als botons lliscants",\n          "default": "Ves a la imatge %slide",\n          "description": "Només s’utilitza per a altaveus de lectura. No es mostrarà. %slide és una variable que se substituirà pel número de la imatge."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'cs', '{\n  "semantics": [\n    {\n      "label": "Obrázky",\n      "field": {\n        "label": "Presentace obrázků",\n        "fields": [\n          {\n            "label": "Presentace obrázků"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Poměr stran",\n      "description": "Automaticky znamená fixní poměr stran automaticky určený na základě obrázků",\n      "options": [\n        {\n          "label": "Automaticky"\n        },\n        {\n          "label": "Vlastní"\n        },\n        {\n          "label": "Nenastaveno"\n        }\n      ]\n    },\n    {\n      "label": "Nastavení poměru stran",\n      "fields": [\n        {\n          "label": "Šířka poměru stran",\n          "description": "Pokud použijete zde 4 a 3 pro výšku, bude poměr stran 4: 3"\n        },\n        {\n          "label": "Výška poměru stran",\n          "description": "Pokud zde použijete 3 a 4 pro šířku, bude poměr stran 4: 3"\n        }\n      ]\n    },\n    {\n      "label": "Přístupnost presentace obrázků",\n      "fields": [\n        {\n          "label": "Popisek tlačítka pro další snímek",\n          "default": "Další obrázek",\n          "description": "Používá se pouze pro rčtecí zařízení. Nezobrazí se."\n        },\n        {\n          "label": "Popisek tlačítka pro předchozí snímek",\n          "default": "Předchozí obrázek",\n          "description": "Používá se pouze pro rčtecí zařízení. Nezobrazí se."\n        },\n        {\n          "label": "Popisek pro posuvná tlačítka",\n          "default": "Přejdi na obrázek %slide",\n          "description": "Používá se pouze pro rčtecí zařízení. Nezobrazí se. %slide je proměnná a bude nahrazena číslem obrázku."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'de', '{\n  "semantics": [\n    {\n      "label": "Bilder",\n      "field": {\n        "label": "Bild",\n        "fields": [\n          {\n            "label": "Bild"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Seitenverhältnis",\n      "description": "Automatisch bedeutet, dass ein festes Seitenverhältnis genutzt wird, das automatisch anhand der Bilder bestimmt wird",\n      "options": [\n        {\n          "label": "Automatisch"\n        },\n        {\n          "label": "Benutzerdefiniert"\n        },\n        {\n          "label": "Nicht festgelegt"\n        }\n      ]\n    },\n    {\n      "label": "Einstellungen zum Seitenverhältnis",\n      "fields": [\n        {\n          "label": "Relative Breite",\n          "description": "Wenn Du hier 4 und für die Höhe 3 verwendest, beträgt das Seitenverhältnis 4:3"\n        },\n        {\n          "label": "Relative Höhe",\n          "description": "Wenn du hier 3 und für die Breite 4 verwendest, beträgt das Seitenverhältnis 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Barrierefreiheit des Image-Sliders",\n      "fields": [\n        {\n          "label": "Beschriftung des \\"Nächtes Bild\\"-Buttons",\n          "default": "Nächstes Bild",\n          "description": "Dies wird nur für Vorlesewerkzeuge verwendet. Es wird nicht angezeigt."\n        },\n        {\n          "label": "Beschriftung des \\"Vorheriges Bild\\"-Buttons",\n          "default": "Vorheriges Bild",\n          "description": "Dies wird nur für Vorlesewerkzeuge verwendet. Es wird nicht angezeigt."\n        },\n        {\n          "label": "Beschriftung der Buttons für die Direktnavigation zu Bildern",\n          "default": "Gehe zu Bild %slide",\n          "description": "Dies wird nur für Vorlesewerkzeuge verwendet. Es wird nicht angezeigt. %slide ist ein Platzhalter und wird durch die Bild-Nummer ersetzt."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'el', '{\n  "semantics":[\n    {\n    "label": "Εικόνες",\n    "field": {\n      "label": "Διαφάνεια εικόνας",\n      "fields": [\n        {\n          "label": "Διαφάνεια εικόνας"\n        }\n      ]\n    }\n  },\n  {\n    "label": "Αναλογία διαστάσεων",\n    "description": "Η επιλογή \\"αυτόματη\\" σημαίνει ότι η αναλογία διαστάσεων καθορίζεται αυτόματα με βάση τις εικόνες.",\n    "options": [\n      {\n        "label": "Αυτόματη"\n      },\n      {\n        "label": "Προσαρμοσμένη"\n      },\n      {\n        "label": "Μη καθορισμένη"\n      }\n    ]\n  },\n  {\n    "label": "Ρυθμίσεις αναλογίας διαστάσεων",\n    "fields": [\n      {\n        "label": "Πλάτος αναλογίας",\n        "description": "Εάν ορίσετε 4 σε αυτό το πεδίο και 3 στο ύψος η αναλογία θα είναι 4:3"\n      },\n      {\n        "label": "Ύψος αναλογίας",\n        "description": "Εάν ορίσετε 3 σε αυτό το πεδίο και 4 στο πλάτος η αναλογία θα είναι 4:3"\n      }\n    ]\n  },\n  {\n    "label": "Ρυθμίσεις Προσβασιμότητας",\n    "fields": [\n      {\n        "label": "Ετικέτα κουμπιού μετάβασης στην επόμενη διαφάνεια",\n        "default": "Επόμενη εικόνα",\n        "description": "Αυτό το κείμενο χρησιμοποιείται μόνο για ακουστική υποβοήθηση. Δεν θα εμφανίζεται."\n      },\n      {\n        "label": "Ετικέτα κουμπιού μετάβασης στην προηγούμενη διαφάνεια",\n        "default": "Προηγούμενη εικόνα",\n        "description": "Αυτό το κείμενο χρησιμοποιείται μόνο για ακουστική υποβοήθηση. Δεν θα εμφανίζεται."\n      },\n      {\n        "label": "Ετικέτα κουμπιού μετάβασης σε συγκεκριμένη διαφάνεια",\n        "default": "Μετάβαση στην εικόνα %slide",\n        "description": "Αυτό το κείμενο χρησιμοποιείται μόνο για ακουστική υποβοήθηση. Δεν θα εμφανίζεται. To %slide αποτελεί μια μεταβλητή που θα αντικατασταθεί από τον αριθμό της εικόνας."\n      }\n    ]\n  }\n]\n}\n'),
(90, 'es', '{\n  "semantics": [\n    {\n      "label": "Imágenes",\n      "field": {\n        "label": "Pase de diapositivas",\n        "fields": [\n          {\n            "label": "Pase de diapositivas"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Proporción de aspecto",\n      "description": "Automático significa proporción de aspecto fija, determinada automáticamente y basada en las imágenes",\n      "options": [\n        {\n          "label": "Automática"\n        },\n        {\n          "label": "Personalizada"\n        },\n        {\n          "label": "No fija"\n        }\n      ]\n    },\n    {\n      "label": "Configuración de Proporción de aspecto",\n      "fields": [\n        {\n          "label": "Anchura de proporción de aspecto",\n          "description": "Si usas 4 aquí, y 3 para la altura, la proporción de aspecto será de 4:3"\n        },\n        {\n          "label": "Altura de proporción de aspecto",\n          "description": "Si usas 3 aquí, y 4 para el ancho, la proporción de aspecto será de be 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Accesibilidad del pase de diapositivas",\n      "fields": [\n        {\n          "label": "Etiqueta para botones de Imagen Siguiente",\n          "default": "Imagen Siguiente",\n          "description": "Usado solamente para lectores de pantalla. No se mostrará."\n        },\n        {\n          "label": "Etiqueta para botones Imagen anterior",\n          "default": "Imagen Anterior",\n          "description": "Usado solamente para lectores de pantalla. No se mostrará."\n        },\n        {\n          "label": "Etiqueta para botones de diapositiva",\n          "default": "Ir a la imagen %slide",\n          "description": "Usado solamente para lectores de pantalla. No se mostrará. %slide es una variable y será reemplazada por el número de la imagen."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'es-mx', '{\n  "semantics": [\n    {\n      "label": "Imágenes",\n      "field": {\n        "label": "Página con Imagen",\n        "fields": [\n          {\n            "label": "Página con Imagen"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Proporción de aspecto",\n      "description": "Automático significa proporción de aspecto fija determinada automáticamente basada en las imágenes",\n      "options": [\n        {\n          "label": "Automática"\n        },\n        {\n          "label": "Personalizada"\n        },\n        {\n          "label": "No fija"\n        }\n      ]\n    },\n    {\n      "label": "Configuraciones de Proporción de Aspecto",\n      "fields": [\n        {\n          "label": "Ancho de proporción de aspecto",\n          "description": "Si usa 4 aquí, y 3 para la altura, la proporción de aspecto será de 4:3"\n        },\n        {\n          "label": "Altura de proporción de aspecto",\n          "description": "Si usa 3 aquí, y 4 para el ancho, la proporción de aspecto será de be 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Accesibilidad de deslizador de imagen",\n      "fields": [\n        {\n          "label": "Etiqueta para botones de Imagen Siguiente",\n          "default": "Imagen Siguiente",\n          "description": "Esto es usado solamente para Lectores de texto en voz alta. No será mostrado."\n        },\n        {\n          "label": "Etiqueta para botones Imagen anterior",\n          "default": "Imagen Anterior",\n          "description": "Esto es usado solamente para Lectores de texto en voz alta. No será mostrado."\n        },\n        {\n          "label": "Etiqueta para botones de página",\n          "default": "Ir a la imagen %slide",\n          "description": "Esto es usado solamente para Lectores de texto en voz alta. No será mostrado. %slide es una variable y será remplazado con el número de la imagen."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'et', '{\n  "semantics": [\n    {\n      "label": "Pildid",\n      "field": {\n        "label": "Pildislaid",\n        "fields": [\n          {\n            "label": "Pildislaid"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Kuvasuhe",\n      "description": "Automaatne tähendab fikseeritud automaatset kuvasuhet piltide põhjal",\n      "options": [\n        {\n          "label": "Automaatne"\n        },\n        {\n          "label": "Kohandatud"\n        },\n        {\n          "label": "Pole fikseeritud"\n        }\n      ]\n    },\n    {\n      "label": "Kuvasuhte seadmed",\n      "fields": [\n        {\n          "label": "Kuvasuhte laius",\n          "description": "Kui sa paned siia 4 ja kõrguseks 3, siis kuvasuhe on 4:3"\n        },\n        {\n          "label": "Kuvasuhte kõrgus",\n          "description": "Kui sa paned siia 3 ja laiuseks 4, siis kuvasuhe on 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Pildiliuguri ligipääsetavus",\n      "fields": [\n        {\n          "label": "Silt järgmine slaid nuppudele",\n          "default": "Järgmine pilt",\n          "description": "Seda kasutavad ainult lugerid. Seda ei näidata ekraanil."\n        },\n        {\n          "label": "Silt eelmine slaid nuppudele",\n          "default": "Eelmine pilt",\n          "description": "Seda kasutavad ainult lugerid. Seda ei näidata ekraanil."\n        },\n        {\n          "label": "Silt slaidi nuppudele",\n          "default": "Mine pildile %slide",\n          "description": "Seda kasutavad ainult lugerid. Seda ei näidata ekraanil. %slide on muutuja, mis asendatakse pildi numbriga."\n        }\n      ]\n    }\n  ]\n}'),
(90, 'eu', '{\n  "semantics": [\n    {\n      "label": "Irudiak",\n      "field": {\n        "label": "Irudien Aurkezpena",\n        "fields": [\n          {\n            "label": "Irudien Aurkezpena"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Itxura-proportzioa",\n      "description": "Automatikoa aukeratuta irudietan oinarritutako itxura-proportzioa automatikoki zehaztuko da",\n      "options": [\n        {\n          "label": "Automatikoa"\n        },\n        {\n          "label": "Pertsonalizatua"\n        },\n        {\n          "label": "Lotu gabea"\n        }\n      ]\n    },\n    {\n      "label": "Itxura-proportzioaren Ezarpenak",\n      "fields": [\n        {\n          "label": "Itxura-proportzioaren zabalera",\n          "description": "Hemen 4 eta altueran 3 jartzen baduzu itxura-proportzioa 4:3 izango da"\n        },\n        {\n          "label": "Itxura-proportzioaren altuera",\n          "description": "Hemen 3 eta zabaleran 4 jartzen baduzu itxura-proportzioa 4:3 izango da"\n        }\n      ]\n    },\n    {\n      "label": "Irudien Aurkezpenaren Eskuragarritasuna",\n      "fields": [\n        {\n          "label": "Hurrengo diapositibaren botoiarentzako etiketa",\n          "default": "Hurrengo Irudia",\n          "description": "Hau soilik irakurgailu-bozgorailuentzako erabiltzen da. Ez da erakutsiko."\n        },\n        {\n          "label": "Aurreko diapositibaren botoiarentzako etiketa",\n          "default": "Aurreko Irudia",\n          "description": "Hau soilik irakurgailu-bozgorailuentzako erabiltzen da. Ez da erakutsiko."\n        },\n        {\n          "label": "Diapositiba-botoientzako etiketa",\n          "default": "Joan %slide irudira",\n          "description": "Hau soilik irakurgailu-bozgorailuentzako erabiltzen da. Ez da erakutsiko. %slide aldagai bat da eta irudiaren zenbakiarekin ordezkatuko da."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'fi', '{\n  "semantics": [\n    {\n      "label": "Kuvat",\n      "field": {\n        "label": "Liukuvat kuvat",\n        "fields": [\n          {\n            "label": "Liukuvat kuvat"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Kuvasuhde",\n      "description": "Automaattinen tarkoittaa kiinteää kuvasuhdetta joka määritetään automaattisesti kuvatiedoston perusteella",\n      "options": [\n        {\n          "label": "Automaattinen"\n        },\n        {\n          "label": "Räätälöity"\n        },\n        {\n          "label": "Ei kiinteää kuvasuhdetta"\n        }\n      ]\n    },\n    {\n      "label": "Kuvasuhdeasetukset",\n      "fields": [\n        {\n          "label": "Kuvasuhteen leveys",\n          "description": "Jos käytät tässä arvoa 4 ja korkeudelle arvoa 3 niin kuvasuhteeksi muodostuu 4:3"\n        },\n        {\n          "label": "Kuvasuhteen korkeus",\n          "description": "Jos käytät tässä arvoa 3 ja korkeudelle arvoa 4 niin kuvasuhteeksi muodostuu 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Liukuvien kuvien esteettömyysasetukset",\n      "fields": [\n        {\n          "label": "Teksti seuraavaan diaan vievälle painikkeelle",\n          "default": "Seuraava kuva",\n          "description": "Tätä käytetään ruudunlukijoille, sitä ei näytetä itse esityksessä."\n        },\n        {\n          "label": "Teksti edelliselle dialle vievälle painikkeelle",\n          "default": "Edellinen kuva",\n          "description": "Tätä käytetään ruudunlukijoille, sitä ei näytetä itse esityksessä."\n        },\n        {\n          "label": "Teksti slide-navigointipainikkeille",\n          "default": "Siirry kuvaan %slide",\n          "description": "Tätä käytetään ruudunlukijoille, sitä ei näytetä itse esityksessä. Muuttuja %slide korvataan kuvan sivunumerolla."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'fr', '{\n  "semantics": [\n    {\n      "label": "Images",\n      "field": {\n        "label": "Diapositive",\n        "fields": [\n          {\n            "label": "Diapositive"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Ratio de l''affichage",\n      "description": "Indiquez : \\"Automatique\\" pour un ratio d''affichage déterminé par celui des images de l''album nécessitant la plus grande hauteur d''affichage, \\"Personnalisé\\" pour fixer un ratio de votre choix pour tout l''album, et \\"Variable\\" pour un ratio qui s''adaptera à celui de chaque image de l''album.",\n      "options": [\n        {\n          "label": "Automatique"\n        },\n        {\n          "label": "Personnalisé"\n        },\n        {\n          "label": "Variable"\n        }\n      ]\n    },\n    {\n      "label": "Paramétrages du ratio de l''affichage",\n      "fields": [\n        {\n          "label": "Ratio en largeur de l''affichage :",\n          "description": "Si vous indiquez 4 ici, et 3 pour la hauteur, le ratio de l''affichage de l''album qui en résultera sera de quatre-tiers : 4:3."\n        },\n        {\n          "label": "Ratio en hauteur de l''affichage :",\n          "description": "Si vous indiquez 3 ici, et 4 pour la largeur, le ratio de l''affichage de l''album qui en résultera sera de quatre-tiers : 4:3."\n        }\n      ]\n    },\n    {\n      "label": "Paramètres d''accessibilité de l''album d''images",\n      "fields": [\n        {\n          "label": "Libellé du bouton image suivante",\n          "default": "Image suivante",\n          "description": "Cette mention n''apparaîtra pas à l''écran et ne sera employée que par les outils d''accessibilité améliorée par synthèse vocale."\n        },\n        {\n          "label": "Libellé du bouton image précédente",\n          "default": "Image précédente",\n          "description": "Cette mention n''apparaîtra pas à l''écran et ne sera employée que par les outils d''accessibilité améliorée par synthèse vocale."\n        },\n        {\n          "label": "Libellé pour le bouton des diapositives",\n          "default": "Aller à l''image numéro %slide",\n          "description": "Cette mention n''apparaîtra pas à l''écran et ne sera employée que par les outils d''accessibilité améliorée par synthèse vocale. La mention %slide est un texte générique auquel se substituera le numéro effectif dans l''album de l''image affichée à ce moment-là."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'gl', '{\n  "semantics": [\n    {\n      "label": "Imaxes",\n      "field": {\n        "label": "Pase de Dipositivas",\n        "fields": [\n          {\n            "label": "Pase de Diapositivas"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Relación de aspecto",\n      "description": "Automático significa relación de aspecto fixo determinado automaticamente a partir das imaxes",\n      "options": [\n        {\n          "label": "Automático"\n        },\n        {\n          "label": "Personalizado"\n        },\n        {\n          "label": "Non fixado"\n        }\n      ]\n    },\n    {\n      "label": "Configuración da relación de aspecto",\n      "fields": [\n        {\n          "label": "Anchura da relación de aspecto",\n          "description": "Se usas 4 aquí e 3 para a altura, a relación de aspecto será 4:3"\n        },\n        {\n          "label": "Altura da relación de aspecto",\n          "description": "Se usas 3 aquí e 4 para a anchura, a relación de aspecto será 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Accesibilidade do pase de diapositivas",\n      "fields": [\n        {\n          "label": "Etiqueta para os botóns de diapositiva seguinte",\n          "default": "Imaxe Seguinte",\n          "description": "Só usado para os lectores de pantalla. Non se amosará ao usuario."\n        },\n        {\n          "label": "Etiqueta para os botóns de diapositiva anterior",\n          "default": "Imaxe Anterior",\n          "description": "Só usado para os lectores de pantalla. Non se amosará ao usuario."\n        },\n        {\n          "label": "Etiqueta para os botóns de diapositiva",\n          "default": "Ir á Imaxe %slide",\n          "description": "Só usado para os lectores de pantalla. Non se amosará ao usuario. %slide é a variable e substituirase polo número da imaxe."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'it', '{\n  "semantics": [\n    {\n      "label": "Immagini",\n      "field": {\n        "label": "Image Slide",\n        "fields": [\n          {\n            "label": "Image Slide"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Proporzioni",\n      "description": "Automatico significa proporzioni fisse determinate automaticamente in base alle immagini",\n      "options": [\n        {\n          "label": "Automatico"\n        },\n        {\n          "label": "Personalizzato"\n        },\n        {\n          "label": "Non fisso"\n        }\n      ]\n    },\n    {\n      "label": "Impostazione delle proporzioni",\n      "fields": [\n        {\n          "label": "Larghezza delle proporzioni",\n          "description": "Se usi 4 qui e 3 per l''altezza, la proporzione sarà 4:3"\n        },\n        {\n          "label": "Altezza delle proporzioni",\n          "description": "Se usi 3 qui e 4 per la larghezza, la proporzione sarà 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Accessibilità dello slider dell''immagine",\n      "fields": [\n        {\n          "label": "Etichetta dei pulsanti per la prossima slide",\n          "default": "Prossima immagine",\n          "description": "Questo è usato soltanto per lettori vocali. Non sarà visualizzato"\n        },\n        {\n          "label": "Etichetta dei pulsanti per la slide precedente",\n          "default": "Immagine precedente",\n          "description": "Questo è usato soltanto per lettori vocali. Non sarà visualizzato"\n        },\n        {\n          "label": "Etichetta dei pulsanti per le slide",\n          "default": "Vai all''immagine %slide",\n          "description": "Questo è usato soltanto per i lettori vocali. Non sarà visualizzato. %slide è una variabile e sarà sostituita dal numero dell''immagine"\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'ka', '{\n  "semantics": [\n    {\n      "label": "სურათები",\n      "field": {\n        "label": "სურათის სლაიდი",\n        "fields": [\n          {\n            "label": "სურათის სლაიდი"\n          }\n        ]\n      }\n    },\n    {\n      "label": "ასპექტის თანაფარდობა",\n      "description": "ავტომატური ნიშნავს ფიქსირებული ასპექტის თანაფარდობას ავტომატურად განსაზღვრული სურათების საფუძველზე",\n      "options": [\n        {\n          "label": "ავტომატური"\n        },\n        {\n          "label": "არასტანდარტული"\n        },\n        {\n          "label": "მოსაგვარებელი"\n        }\n      ]\n    },\n    {\n      "label": "ასპექტის თანაფარდობის პარამეტრები",\n      "fields": [\n        {\n          "label": "ასპექტის თანაფარდობის სიგანე",\n          "description": "თუ აქ იყენებთ 4-ს და სიმაღლისთვის 3-ს, ასპექტის თანაფარდობა იქნება 4:3"\n        },\n        {\n          "label": "ასპექტის თანაფარდობის სიმაღლე",\n          "description": "თუ აქ იყენებთ 3-ს და სიგანისთვის 4-ს, ასპექტის თანაფარდობა იქნება 4:3"\n        }\n      ]\n    },\n    {\n      "label": "სურათის სლაიდერის ხელმისაწვდომობა",\n      "fields": [\n        {\n          "label": "შემდეგი სლაიდის ღილაკის წარწერა",\n          "default": "შემდეგი სურათი",\n          "description": "ეს გამოიყენება მხოლოდ ტექსტის გამხმოვანებლისთვის. არ გამოჩნდება."\n        },\n        {\n          "label": "წინა სლაიდის ღილაკების წარწერა",\n          "default": "წინა სურათი",\n          "description": "ეს გამოიყენება მხოლოდ ტექსტის გამხმოვანებლისთვის. არ გამოჩნდება."\n        },\n        {\n          "label": "სლაიდის ღილაკების წარწერა",\n          "default": "გადადი სურათზე %slide",\n          "description": "მხოლოდ ტექსტის გამხმოვანებლისთვის. არ გამოჩნდება. %slide არის ცვლადი და ჩანაცვლდება სურათის ნომრით."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'ko', '{\n  "semantics": [\n    {\n      "label": "이미지",\n      "field": {\n        "label": "이미지 슬라이드",\n        "fields": [\n          {\n            "label": "이미지 슬라이드"\n          }\n        ]\n      }\n    },\n    {\n      "label": "가로 세로 비율",\n      "description": "자동설정은 이미지를 기반으로 자동으로 결정되는 가로 세로 비율을 의미합니다.",\n      "options": [\n        {\n          "label": "자동설정"\n        },\n        {\n          "label": "사용자 지정"\n        },\n        {\n          "label": "고정되지 않음"\n        }\n      ]\n    },\n    {\n      "label": "가로 세로 비율 설정",\n      "fields": [\n        {\n          "label": "너비 설정",\n          "description": "여기서 4로 설정하고 높이를 3으로 하는 경우 가로 세로 비율은 4:3이 됩니다."\n        },\n        {\n          "label": "높이 설정",\n          "description": "여기서 3으로 설정하고 너비를 3으로 하는 경우 가로 세로 비율은 4:3이 됩니다."\n        }\n      ]\n    },\n    {\n      "label": "이미지 슬라이더 접근성",\n      "fields": [\n        {\n          "label": "다음 슬라이드 버튼에 대한 라벨",\n          "default": "다음 이미지",\n          "description": "이것은 읽기 스피커에만 사용됩니다. 표시되지 않습니다."\n        },\n        {\n          "label": "이전 슬라이드 버튼에 대한 라벨",\n          "default": "이전 이미지",\n          "description": "이것은 읽기 스피커에만 사용됩니다. 표시되지 않습니다."\n        },\n        {\n          "label": "슬라이드 버튼의 라벨",\n          "default": "이미지 %slide 로 이동",\n          "description": "이것은 읽기 스피커에만 사용됩니다. 표시되지 않습니다. %slide는 변수이므로 이미지 번호로 바뀝니다."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'lt', '{\n  "semantics": [\n    {\n      "label": "Paveikslai",\n      "field": {\n        "label": "Paveiksliuko skaidrė",\n        "fields": [\n          {\n            "label": "Paveiksliuko skaidrė"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Kraštinių santykis",\n      "description": "Automatinis reiškia fiksuotą kraštinių santykį, kuris automatiškai nustatomas pagal paveikslus",\n      "options": [\n        {\n          "label": "Automatinis"\n        },\n        {\n          "label": "Pasirenkamas"\n        },\n        {\n          "label": "Nefiksuotas"\n        }\n      ]\n    },\n    {\n      "label": "Kraštinių santykio nustatymai",\n      "fields": [\n        {\n          "label": "Plotis",\n          "description": "Jei čia naudosite 4, o aukščiui – 3, kraštinių santykis bus 4:3"\n        },\n        {\n          "label": "Aukštis",\n          "description": "Jei čia naudosite 3, o pločiui – 4, formato santykis bus 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Paveiksliukų slinktuko pritaikomumas",\n      "fields": [\n        {\n          "label": "Kitos skaidrės mygtuko pavadinimas",\n          "default": "Kitas paveikslas",\n          "description": "Tai naudojama tik įgarsinant tekstą. Tai nebus rodoma."\n        },\n        {\n          "label": "Ankstesnės skaidrės mygtuko pavadinimas",\n          "default": "Ankstesnis paveikslas",\n          "description": "Tai naudojama tik teksto įgarsinimui. Tai nebus rodoma."\n        },\n        {\n          "label": "Skaidrės mygtuko pavadinimas",\n          "default": "Pereiti prie %slide skaidrės",\n          "description": "Tai naudojama tik teksto įgarsinimui. Tai nebus rodoma. %slide yra kintamasis ir bus pakeistas paveikslo numeriu."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'lv', '{\n  "semantics": [\n    {\n      "label": "Attēli",\n      "field": {\n        "label": "Attēla slaids",\n        "fields": [\n          {\n            "label": "Attēla slaids"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Malu attiecība",\n      "description": "Automātiski nozīmē fiksētu malu attiecību, kas tiek automātiski noteikta, pamatojoties uz attēliem",\n      "options": [\n        {\n          "label": "Automātiski"\n        },\n        {\n          "label": "Pielāgots"\n        },\n        {\n          "label": "Nav nemainīgs"\n        }\n      ]\n    },\n    {\n      "label": "Malu attiecību iestatījumi",\n      "fields": [\n        {\n          "label": "Malu attiecības platums",\n          "description": "Ja šeit izmantojat 4 un augstumam 3, malu attiecība būs 4:3"\n        },\n        {\n          "label": "Malu attiecības augstums",\n          "description": "Ja šeit izmantojat 3 un platumam 4, malu attiecība būs 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Attēlu slīdņa pieejamība",\n      "fields": [\n        {\n          "default": "Nākamais attēls",\n          "description": "Tiek izmantots tikai ekrāna lasītājiem. Netiks atspoguļots.",\n          "label": "Nākamā slaida pogu etiķete"\n        },\n        {\n          "label": "Iepriekšējā slaida pogu etiķete",\n          "default": "Iepriekšējais attēls",\n          "description": "Tiek izmantots tikai ekrāna lasītājiem. Netiks atspoguļots."\n        },\n        {\n          "label": "Slaidu pogu etiķete",\n          "default": "Dodieties uz attēlu %slide",\n          "description": "To izmanto tikai ekrāna lasītājiem. Tas netiks parādīts. %slide ir mainīgais un tiks aizstāts ar attēla numuru."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'mn', '{\n  "semantics": [\n    {\n      "field": {\n        "label": "Зургийн слайд",\n        "fields": [\n          {\n            "label": "Зургийн слайд"\n          }\n        ]\n      },\n      "label": "Зургууд"\n    },\n    {\n      "label": "Хэсгийн харьцаа",\n      "options": [\n        {\n          "label": "Автомат"\n        },\n        {\n          "label": "Захиалгат"\n        },\n        {\n          "label": "Засагдаагүй"\n        }\n      ],\n      "description": "Автомат гэдэг нь зураг дээр тулгуурлан автоматаар тодорхойлогддог тогтмол харьцааг хэлнэ"\n    },\n    {\n      "fields": [\n        {\n          "label": "Харьцааны өргөн",\n          "description": "Хэрэв та энд 4, өндрийн хувьд 3-ыг ашиглавал харьцаа 4:3 болно"\n        },\n        {\n          "label": "Харьцааны өндөр",\n          "description": "Хэрэв та энд 3-ыг, өргөний хувьд 4-ийг ашиглавал харьцаа 4:3 болно"\n        }\n      ],\n      "label": "Харьцааны тохиргоо"\n    },\n    {\n      "label": "Зургийн слайдерт хандах боломжтой",\n      "fields": [\n        {\n          "default": "Дараагийн зураг",\n          "label": "Дараагийн слайдын товчлууруудын шошго",\n          "description": "Үүнийг зөвхөн уншдаг чанга яригчдад ашигладаг. Энэ нь харагдахгүй."\n        },\n        {\n          "label": "Өмнөх слайдын товчлууруудын шошго",\n          "description": "Үүнийг зөвхөн уншдаг чанга яригчдад ашигладаг. Энэ нь харагдахгүй.",\n          "default": "Өмнөх зураг"\n        },\n        {\n          "default": "Зураг %slide руу очно уу",\n          "label": "Слайд товчлууруудын шошго",\n          "description": "Үүнийг зөвхөн уншдаг чанга яригчдад ашигладаг. Энэ нь харагдахгүй. %slide нь хувьсагч бөгөөд зургийн дугаараар солигдох болно."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'nb', '{\n  "semantics": [\n    {\n      "label": "Bilder",\n      "field": {\n        "label": "Bilde slide",\n        "fields": [\n          {\n            "label": "Bilde slide"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Aspect ratio",\n      "description": "Automatic means fixed aspect ratio automatically determined based on the images",\n      "options": [\n        {\n          "label": "Automatic"\n        },\n        {\n          "label": "Custom"\n        },\n        {\n          "label": "Not fixed"\n        }\n      ]\n    },\n    {\n      "label": "Aspect Ratio Settings",\n      "fields": [\n        {\n          "label": "Aspect ratio width",\n          "description": "If you use 4 here, and 3 for the height the aspect ratio will be 4:3"\n        },\n        {\n          "label": "Aspect ratio height",\n          "description": "If you use 3 here, and 4 for the width the aspect ratio will be 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Image slider accessibility",\n      "fields": [\n        {\n          "label": "Label for next slide buttons",\n          "default": "Next Image",\n          "description": "This is only used for read-speakers. It won''t be displayed."\n        },\n        {\n          "label": "Label for previous slide buttons",\n          "default": "Previous Image",\n          "description": "This is only used for read-speakers. It won''t be displayed."\n        },\n        {\n          "label": "Label for slide buttons",\n          "default": "Go to image %slide",\n          "description": "This is only used for read-speakers. It won''t be displayed. %slide is a variable and will be replaced with the image number."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'nl', '{\n  "semantics": [\n    {\n      "label": "Afbeeldingen",\n      "field": {\n        "label": "Afbeeldingsdia",\n        "fields": [\n          {\n            "label": "Afbeeldingsdia"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Beeldverhouding",\n      "description": "Automatisch betekent een vaste beeldverhouding die vanzelf wordt bepaald op basis van de beelden",\n      "options": [\n        {\n          "label": "Automatisch"\n        },\n        {\n          "label": "Aangepast"\n        },\n        {\n          "label": "Niet gefixeerd"\n        }\n      ]\n    },\n    {\n      "label": "Instellingen beeldverhouding",\n      "fields": [\n        {\n          "label": "De breedte van de beeldverhouding",\n          "description": "Als je hier 4 en 3 voor de hoogte gebruikt, dan is de beeldverhouding 4:3"\n        },\n        {\n          "label": "De hoogte van de beeldverhouding",\n          "description": "Als je hier 3 en 4 voor de breedte gebruikt, dan is de beeldverhouding 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Toegankelijkheid van afbeeldingsschuifregelaar",\n      "fields": [\n        {\n          "label": "Label voor \\"Volgende dia\\"-knoppen",\n          "default": "Volgende afbeelding",\n          "description": "Dit wordt alleen gebruikt voor schermlezers. Het wordt niet getoond."\n        },\n        {\n          "label": "Label voor \\"Vorige dia\\"-knoppen",\n          "default": "Vorige afbeelding",\n          "description": "Dit wordt alleen gebruikt voor schermlezers. Het wordt niet getoond."\n        },\n        {\n          "label": "Label voor \\"Dia\\"-knoppen",\n          "default": "Ga naar afbeelding %slide",\n          "description": "Dit wordt alleen gebruikt voor schermlezers. Het wordt niet getoond. %slide is een variabele en zal worden vervangen door het afbeeldingsnummer."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'nn', '{\n  "semantics": [\n    {\n      "label": "Images",\n      "field": {\n        "fields": [\n          {\n            "label": "Image Slide"\n          }\n        ],\n        "label": "Image Slide"\n      }\n    },\n    {\n      "options": [\n        {\n          "label": "Automatic"\n        },\n        {\n          "label": "Custom"\n        },\n        {\n          "label": "Not fixed"\n        }\n      ],\n      "label": "Aspect ratio",\n      "description": "Automatic means fixed aspect ratio automatically determined based on the images"\n    },\n    {\n      "label": "Aspect Ratio Settings",\n      "fields": [\n        {\n          "label": "Aspect ratio width",\n          "description": "If you use 4 here, and 3 for the height the aspect ratio will be 4:3"\n        },\n        {\n          "label": "Aspect ratio height",\n          "description": "If you use 3 here, and 4 for the width the aspect ratio will be 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Image slider accessibility",\n      "fields": [\n        {\n          "default": "Next Image",\n          "description": "This is only used for read-speakers. It won''t be displayed.",\n          "label": "Label for next slide buttons"\n        },\n        {\n          "label": "Label for previous slide buttons",\n          "default": "Previous Image",\n          "description": "This is only used for read-speakers. It won''t be displayed."\n        },\n        {\n          "label": "Label for slide buttons",\n          "default": "Go to image %slide",\n          "description": "This is only used for read-speakers. It won''t be displayed. %slide is a variable and will be replaced with the image number."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'pl', '{\n  "semantics": [\n    {\n      "label": "Obrazy",\n      "field": {\n        "label": "Slajd z obrazem",\n        "fields": [\n          {\n            "label": "Slajd z obrazem"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Współczynnik proporcji",\n      "description": "Automatyczny oznacza stały współczynnik proporcji automatycznie określany na podstawie obrazów",\n      "options": [\n        {\n          "label": "Automatyczny"\n        },\n        {\n          "label": "Niestandardowy"\n        },\n        {\n          "label": "Nie określony"\n        }\n      ]\n    },\n    {\n      "label": "Ustawienia współczynnika proporcji",\n      "fields": [\n        {\n          "label": "Szerokość współczynnika proporcji",\n          "description": "Jeśli użyjesz tu 4, a dla wysokości 3, to współczynnik wyniesie 4:3"\n        },\n        {\n          "label": "Wysokość współczynnika proporcji",\n          "description": "Jeśli wpiszesz tu 3, a dla szerokości 4, to współczynnik wyniesie 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Dostępność slidera",\n      "fields": [\n        {\n          "label": "Etykieta przycisku Dalej",\n          "default": "Dalej",\n          "description": "Wyłącznie dla czytników. Tekst nie zostanie wyświetlony."\n        },\n        {\n          "label": "Etykieta przycisku Wstecz",\n          "default": "Wstecz",\n          "description": "Wyłącznie dla czytników. Tekst nie zostanie wyświetlony."\n        },\n        {\n          "label": "Etykieta dla przycisków slajdów",\n          "default": "Idź do obrazu %slide",\n          "description": "Wyłącznie dla czytników. Tekst nie zostanie wyświetlony. %slide jest zmienną i zostanie zastąpiony numerem obrazu."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'pt', '{\n  "semantics": [\n    {\n      "label": "Imagens",\n      "field": {\n        "label": "Slides",\n        "fields": [\n          {\n            "label": "Slides"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Proporção",\n      "description": "Automático significa proporção fixa determinada automaticamente com base nas imagens",\n      "options": [\n        {\n          "label": "Automático"\n        },\n        {\n          "label": "Personalizado"\n        },\n        {\n          "label": "Variável"\n        }\n      ]\n    },\n    {\n      "label": "Configurações da proporção do ecrã",\n      "fields": [\n        {\n          "label": "Largura",\n          "description": "Se usar 4 aqui e 3 para a altura, a proporção será de 4:3"\n        },\n        {\n          "label": "Altura",\n          "description": "Se usar 3 aqui e 4 para a largura, a proporção será de 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Acessibilidade do controlo deslizante de imagem",\n      "fields": [\n        {\n          "label": "Etiqueta para os botões de próxima imagem",\n          "default": "Imagem seguinte",\n          "description": "É usado apenas para altifalantes de leitura. Não será mostrado."\n        },\n        {\n          "label": "Etiqueta para os botões de imagem anterior",\n          "default": "Imagem anterior",\n          "description": "É usado apenas para altifalantes de leitura. Não será mostrado."\n        },\n        {\n          "label": "Etiqueta para os botões de escolha de imagem",\n          "default": "Ir para a imagem %slide",\n          "description": "É usado apenas para altifalantes de leitura. Não será mostrado. %slide é uma variável e será substituída pelo número da imagem."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'pt-br', '{\n  "semantics": [\n    {\n      "label": "Imagens",\n      "field": {\n        "label": "Slide de Imagem",\n        "fields": [\n          {\n            "label": "Slide de Imagem"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Relação de aspecto",\n      "description": "Automático significa relação de aspecto fixa determinada automaticamente com base nas imagens",\n      "options": [\n        {\n          "label": "Automático"\n        },\n        {\n          "label": "Personalizado"\n        },\n        {\n          "label": "Não fixado"\n        }\n      ]\n    },\n    {\n      "label": "Ajustes da relação de aspecto",\n      "fields": [\n        {\n          "label": "Largura da relação de aspecto",\n          "description": "Se você usar 4 aqui, e 3 para a altura a relação de aspecto será 4:3"\n        },\n        {\n          "label": "Altura da relação de aspecto",\n          "description": "Se você usar 3 aqui, e 4 para a largura a relação de aspecto será de 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Acessibilidade do controle deslizante de imagem",\n      "fields": [\n        {\n          "label": "Rótulo para o botão \\"Próximo Slide\\"",\n          "default": "Próxima Imagem",\n          "description": "Isto só é usado para leitores de tela. Não será exibido."\n        },\n        {\n          "label": "Rótulo do botão \\"Slide Anterior\\"",\n          "default": "Imagem Anterior",\n          "description": "Isto só é usado para leitores de tela. Não será exibido."\n        },\n        {\n          "label": "Rótulo dos botões Slide",\n          "default": "Ir para a imagem %slide",\n          "description": "Isto só é usado para leitores de tela. Não será exibido. O %slide é uma variável e será substituído pelo número da imagem."\n        }\n      ]\n    }\n  ]\n}\n'),
(90, 'ru', '{\n  "semantics": [\n    {\n      "label": "Изображения",\n      "field": {\n        "label": "Слайд изображения",\n        "fields": [\n          {\n            "label": "Слайд изображения"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Соотношение сторон",\n      "description": "Автоматическое значит фиксированное соотношение сторон основываясь на изображении",\n      "options": [\n        {\n          "label": "Автоматическое"\n        },\n        {\n          "label": "Обычное"\n        },\n        {\n          "label": "Не фиксированное"\n        }\n      ]\n    },\n    {\n      "label": "Настройки соотношения сторон",\n      "fields": [\n        {\n          "label": "Ширина",\n          "description": "При значении 4 на этом месте и значении 3 для высоты соотношение сторон будет 4:3"\n        },\n        {\n          "label": "Высота",\n          "description": "При значении 3 на этом месте и значении 4 для ширины соотношение сторон будет 4:3"\n        }\n      ]\n    },\n    {\n      "label": "Доступность к слайдеру изображения",\n      "fields": [\n        {\n          "label": "Ярлыки для кнопок следующих слайдов",\n          "default": "Следующее изображение",\n          "description": "Используется только для ассистирующих технологии. Не будет отображено."\n        },\n        {\n          "label": "Ярлык для кнопки прошлого слайда",\n          "default": "Прошлое изображение",\n          "description": "Используется только для ассистирующих технологии. Не будет отображено."\n        },\n        {\n          "label": "Ярлык для кнопки слайда",\n          "default": "Перейти на слайд %slide",\n          "description": "Используется только для ассистирующих технологии. Не будет отображено. %slide это переменная и будет заменена номером слайда."\n        }\n      ]\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(90, 'sl', '{\n  "semantics": [\n    {\n      "label": "Slike",\n      "field": {\n        "label": "Slikovni drsnik",\n        "fields": [\n          {\n            "label": "Slikovni drsnik"\n          }\n        ]\n      }\n    },\n    {\n      "label": "Razmerje",\n      "description": "Samodejno pomeni fiksno razmerje stranic, ki se samodejno določi na podlagi slik. Po meri omogoča lasten vnos razmerja.",\n      "options": [\n        {\n          "label": "Samodejno"\n        },\n        {\n          "label": "Po meri"\n        },\n        {\n          "label": "Spremenljivo"\n        }\n      ]\n    },\n    {\n      "label": "Nastavitev razmerja po meri",\n      "fields": [\n        {\n          "label": "Širina stranice",\n          "description": "Pri razmerju stranic 4:3 se pod širino vnese 4."\n        },\n        {\n          "label": "Višina stranice",\n          "description": "Pri razmerju stranic 4:3 se pod višino vnese 3."\n        }\n      ]\n    },\n    {\n      "label": "Dostopnost slikovnega drsnika",\n      "fields": [\n        {\n          "label": "Besedilo gumba za ogled nasledje slike",\n          "default": "Naslednja slika",\n          "description": "Besedilo služi bralnikom zaslonov in ne bo prikazano."\n        },\n        {\n          "label": "Besedilo gumba za ogled prejšnje slike",\n          "default": "Prejšnja slika",\n          "description": "Besedilo služi bralnikom zaslonov in ne bo prikazano."\n        },\n        {\n          "label": "Besedilo za gumbe drsnika slik",\n          "default": "Prikaži sliko %slide",\n          "description": "Besedilo služi bralnikom zaslonov in ne bo prikazano. %slide je spremenljivka."\n        }\n      ]\n    }\n  ]\n}\n'),
