(95, 'eu', '{\n  "semantics": [\n    {\n      "label": "Branchig Scenario Editorea (Egoera Adarkatuak)",\n      "fields": [\n        {\n          "label": "Izenburua"\n        },\n        {\n          "label": "Hasierako pantaila",\n          "fields": [\n            {\n              "label": "Ikastaroaren izenburua",\n              "placeholder": "Zure ikastaroaren izenburua"\n            },\n            {\n              "label": "Ikastaroaren xehetasunak",\n              "placeholder": "Ikastaroaren xehetasunak"\n            },\n            {\n              "label": "Ikastaroaren irudia"\n            },\n            {\n              "label": "Irudiaren ordezko testua"\n            }\n          ]\n        },\n        {\n          "label": "Amaierako pantailen zerrenda",\n          "field": {\n            "label": "Amaierako pantaila",\n            "fields": [\n              {\n                "label": "Izenburua"\n              },\n              {\n                "label": "Testua"\n              },\n              {\n                "label": "Irudia"\n              },\n              {\n                "label": "Kalifikazioa",\n                "description": "Lehenetsitako eszenatokiaren amaierara heltzen diren erabiltzaileen kalifikazioa LMS, LRS edo H5Ptik kalifikazioak jasotzen dituen konektatuta dagoen beste edozein zerbitzura bidaliko da."\n              },\n              {\n                "label": "Edukiaren IDa"\n              }\n            ]\n          }\n        },\n        {\n          "label": "Egoera adarkatuen edukien zerrenda",\n          "entity": "edukia",\n          "field": {\n            "fields": [\n              {},\n              {\n                "label": "Erakutsi edukiaren izenburua bistan",\n                "description": "Hautatzen bada, erabiltzaileak edukiaren izenburua ikusiko du eduki honen gaineko goiko barran."\n              },\n              {\n                "label": "Ekiteko botoiaren testua (gehienezko luzera: 50 karaktere)",\n                "default": "Ekin"\n              },\n              {\n                "label": "Gainidazteak behar du edukia amaituta",\n                "options": [\n                  {\n                    "label": "Erabili jokabidearen ezarpena"\n                  },\n                  {\n                    "label": "Gaituta"\n                  },\n                  {\n                    "label": "Desgaituta"\n                  }\n                ],\n                "description": "Gainidatzi ezarpen pertsonalak edukia amaitzea eskatzeko \\"Ekin\\" botoia aktibatu aurretik. Ez du inolako eraginik izango edukiak ez badu adierazten \\"amaitu\\" den ala ez, adibidez, irudiak edo ikastaroen aurkezpenak diapositiba bakarrarekin."\n              },\n              {},\n              {\n                "label": "Iritzia",\n                "fields": [\n                  {\n                    "label": "Iritziaren izenburua"\n                  },\n                  {\n                    "label": "Iritziaren testua"\n                  },\n                  {\n                    "label": "Iritziaren irudia"\n                  },\n                  {\n                    "label": "Eszenatoki honen puntuazioa",\n                    "description": "Puntuazioa eszenatoki honetara iristen diren erabiltzaileentzat H5P-ren puntuazioak jasotzen dituen edozein LMS, LRS edo konektatutako beste edozein zerbitzura bidaliko da."\n                  }\n                ]\n              },\n              {\n                "label": "Nabigatu atzera",\n                "description": "Horri esker, erabiltzaileak atzera egin eta aurreko edukia/galdera eszenatokian ikusteko aukera izango du.",\n                "options": [\n                  {\n                    "label": "Erabili jokabidearen ezarpena"\n                  },\n                  {\n                    "label": "Gaituta"\n                  },\n                  {\n                    "label": "Desgaituta"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {\n          "label": "Kalifikazioaren aukerak",\n          "fields": [\n            {\n              "label": "Kalifikazioaren aukerak",\n              "description": "Aukeratu kalifikazio-mota.",\n              "options": [\n                {\n                  "label": "Estatikoki zehaztu eszenatoki bakoitzaren amaierako kalifikazioa"\n                },\n                {\n                  "label": "Dinamikoki kalkulatu kalifikazioa erabiltzaileen erantzunen arabera"\n                },\n                {\n                  "label": "Kalifikaziorik ez"\n                }\n              ]\n            },\n            {\n              "label": "Sartu Eszenatoki Adarkatuaren interakzioen puntuazioak",\n              "description": "Aukeratuz gero, Bideo Interaktiboetako instantzien puntuazioak lortutako guztirako puntuaziora gehituko dira. Ez bada aukeratzen, soilik eduki-elementuen feedback-ataletan, galdera adarkatuen eta eszenatoki-amaieratan zehaztutako puntuazioak hartuko dira kontuan."\n            }\n          ]\n        },\n        {\n          "label": "Portaeraren ezarpenak",\n          "fields": [\n            {\n              "label": "Nabigatu atzera",\n              "description": "Honi esker, erabiltzaileak atzera egin eta aurreko edukia/galdera eszenatokian ikusteko aukera izango du. Eduki mailan baliogabetu daiteke."\n            },\n            {\n              "label": "Ikusi behar da",\n              "description": "Ikusleei bideoa, bideo interaktiboa eta ikastaroaren aurkezpena osatzeko eskatzen die eszenatokiarekin jarraitu aurretik. Eduki mailan baliogabetu daiteke."\n            },\n            {\n              "label": "Ausazkotu Adarkatze Galderak",\n              "description": "Adarkatze galderak ausazko ordenan erakutsiko dira."\n            }\n          ]\n        },\n        {\n          "label": "Kokapena",\n          "fields": [\n            {\n              "label": "Hasiera-pantailako botoiaren testua",\n              "default": "Hasi ikastaroa"\n            },\n            {\n              "label": "Amaiera-pantailako botoiaren testua",\n              "default": "Berriz hasi ikastaroa"\n            },\n            {\n              "label": "Liburutegi-pantaila bakoitzean atzera botoiaren eta adarkatutako galderen testua",\n              "default": "Atzera"\n            },\n            {\n              "label": "Liburutegiko pantailetako desgaitutako botoiaren testua",\n              "default": "Uneko modulua osatzea eskatu"\n            },\n            {\n              "label": "Bideo bat berriro erreproduzitzeko erabilitako botoiaren testua",\n              "default": "Berriz erreproduzitu bideoa"\n            },\n            {\n              "label": "Puntuazioaren etiketa pantaila amaieran",\n              "default": "Zure puntuazioa:"\n            },\n            {\n              "label": "Aria etiketa pantaila osoko botoiarentzat",\n              "default": "Pantaila osoa"\n            }\n          ]\n        }\n      ]\n    }\n  ]\n}\n');
INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(95, 'fa', '{\n  "semantics": [\n    {\n      "label": "ویرایشگر سناریو منشعب",\n      "fields": [\n        {\n          "label": "عنوان"\n        },\n        {\n          "label": "صفحه شروع",\n          "fields": [\n            {\n              "label": "عنوان صفحه شروع",\n              "placeholder": "عنوان درس شما"\n            },\n            {\n              "label": "زیرعنوان صفحه شروع",\n              "placeholder": "جزئیات درباره درس"\n            },\n            {\n              "label": "تصویر صفحه شروع"\n            },\n            {\n              "label": "Image alternative text"\n            }\n          ]\n        },\n        {\n          "label": "لیست صفحات پایان",\n          "field": {\n            "label": "صفحه پایان",\n            "fields": [\n              {\n                "label": "عنوان"\n              },\n              {\n                "label": "متن"\n              },\n              {\n                "label": "تصویر"\n              },\n              {\n                "label": "نمره",\n                "description": "نمره به هر LMS، LRS یا هر خدمات متصل دیگری که نمرات را برای کاربرانی که به سناریوی پیش‌فرض پایانی می‌رسند، از H5P دریافت می‌کند، ارسال خواهد شد"\n              },\n              {\n                "label": "شناسه محتوا"\n              }\n            ]\n          }\n        },\n        {\n          "label": "لیست محتوای سناریو منشعب",\n          "entity": "محتوا",\n          "field": {\n            "fields": [\n              {},\n              {\n                "description": "If selected, the user will see the content title in the top bar above this content.",\n                "label": "Show content title in view"\n              },\n              {\n                "label": "Text for the proceed button (max length: 50 characters)",\n                "default": "Proceed"\n              },\n              {\n                "label": "Override require content finished",\n                "description": "Override the individual settings for requiring the content to be finished before activating the \\"Proceed\\" button. Will not have any effect if the content doesn''t indicate if it was \\"finished\\", e.g. images or course presentations with just one slide.",\n                "options": [\n                  {\n                    "label": "Use behavioural setting"\n                  },\n                  {\n                    "label": "Enabled"\n                  },\n                  {\n                    "label": "Disabled"\n                  }\n                ]\n              },\n              {},\n              {\n                "label": "Feedback",\n                "fields": [\n                  {\n                    "label": "Feedback title"\n                  },\n                  {\n                    "label": "Feedback text"\n                  },\n                  {\n                    "label": "Feedback image"\n                  },\n                  {\n                    "label": "Score for this scenario",\n                    "description": "The score will be sent to any LMS, LRS or any other connected service that receives scores from H5P for users who reach this scenario."\n                  }\n                ]\n              },\n              {\n                "label": "Navigate back",\n                "description": "This will allow the user to go back and see the previous content/question in the scenario.",\n                "options": [\n                  {\n                    "label": "Use behavioural setting"\n                  },\n                  {\n                    "label": "Enabled"\n                  },\n                  {\n                    "label": "Disabled"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {\n          "label": "گزینه‌های نمره‌دهی",\n          "fields": [\n            {\n              "label": "گزینه‌های نمره‌دهی",\n              "description": "انتخاب نوع نمره‌دهی",\n              "options": [\n                {\n                  "label": "تنظیم ثابت نمره برای هر سناریو پایانی"\n                },\n                {\n                  "label": "محاسبه پویای نمره برای پاسخ‌های کاربر"\n                },\n                {\n                  "label": "بدون نمره‌دهی"\n                }\n              ]\n            },\n            {\n              "label": "شامل نمره تعامل‌ها در سناریو منشعب",\n              "description": "در صورت انتخاب، به عنوان مثال نمرات ویدئوهای تعاملی به نمره کل افزوده خواهد شد. در صورت عدم انتخاب، فقط نمرات مشخص شده در بخش‌های بازخورد برای موارد محتوا، سؤالات منشعب و سناریو‌های پایانی حساب خواهد شد."\n            }\n          ]\n        },\n        {\n          "label": "تنظیمات عملکرد",\n          "fields": [\n            {\n              "label": "حذف و جایگزین کردن بازگشت به عقب",\n              "description": "حذف و جایگزین کردن تنظیمات شخصی برای فعال‌سازی بازگشت به عقب"\n            },\n            {\n              "label": "حذف و جایگزین کردن لزوم به پایان رسیدن محتوا",\n              "description": "حذف و جایگزین کردن تنظیمات شخصی برای لزوم به پایان رسیدن محتوا پیش از فعال‌سازی دکمه ادامه. اگر محتوا به پایان رسیدن را نشان ندهد، اثری نخواهد داشت، برای مثال تصاویر یا ارائه‌های درسی شامل فقط یک اسلاید."\n            },\n            {\n              "label": "Randomize Branching Questions",\n              "description": "Branching questions will be displayed in random order"\n            }\n          ]\n        },\n        {\n          "label": "بومی‌سازی",\n          "fields": [\n            {\n              "label": "متن دکمه روی صفحه شروع",\n              "default": "شروع درس"\n            },\n            {\n              "label": "متن دکمه روی صفحه پایان",\n              "default": "شروع مجدد درس"\n            },\n            {\n              "label": "متن دکمه قبلی روی هر یک از صفحات کتابخانه و سؤالات منشعب",\n              "default": "قبلی"\n            },\n            {\n              "label": "Text for the disabled button on the library screens",\n              "default": "Require to complete the current module"\n            },\n            {\n              "label": "متن دکمه مورد استفاده برای بازپخش یک ویدئو",\n              "default": "بازپخش ویدئو"\n            },\n            {\n              "label": "برچسب نمره روی صفحه پایان",\n              "default": "نمره شما:"\n            },\n            {\n              "label": "برچسب آریا برای دکمه تمام‌صفحه",\n              "default": "تمام‌صفحه"\n            }\n          ]\n        }\n      ]\n    }\n  ]\n}\n'),
(95, 'fi', '{\n  "semantics": [\n    {\n      "label": "Haarautuva skenaario",\n      "fields": [\n        {\n          "label": "Otsikko"\n        },\n        {\n          "label": "Aloitusruutu",\n          "fields": [\n            {\n              "label": "Aloitusruudun otsikko",\n              "placeholder": "Kurssisi otsikko"\n            },\n            {\n              "label": "Aloitusruudun teksti",\n              "placeholder": "Kurssin kuvaus"\n            },\n            {\n              "label": "Aloitusruudun kuva"\n            },\n            {\n              "label": "Image alternative text"\n            }\n          ]\n        },\n        {\n          "label": "Lista haaranpäätteistä",\n          "field": {\n            "label": "Haaranpääte",\n            "fields": [\n              {\n                "label": "Otsikko"\n              },\n              {\n                "label": "Teksti"\n              },\n              {\n                "label": "Kuva"\n              },\n              {\n                "label": "Pisteet",\n                "description": "Pisteet lähetetään LSM, LRS tai muille yhdistetyille palveluille (jotka pystyvät ottamaan arvosanatiedon vastaan H5P:n Haarautuvalta skenaariolta) Pisteet lähetetään silloin, kun käyttäjä saavuttaa haaranpäätteen."\n              },\n              {\n                "label": "Aineiston ID"\n              }\n            ]\n          }\n        },\n        {\n          "label": "Lista Haarautuvan skenaarion sisällöstä",\n          "entity": "sisältö",\n          "field": {\n            "fields": [\n              {},\n              {\n                "label": "Show content title in view",\n                "description": "If selected, the user will see the content title in the top bar above this content."\n              },\n              {\n                "label": "Text for the proceed button (max length: 50 characters)",\n                "default": "Proceed"\n              },\n              {\n                "label": "Override require content finished",\n                "description": "Override the individual settings for requiring the content to be finished before activating the \\"Proceed\\" button. Will not have any effect if the content doesn''t indicate if it was \\"finished\\", e.g. images or course presentations with just one slide.",\n                "options": [\n                  {\n                    "label": "Use behavioural setting"\n                  },\n                  {\n                    "label": "Enabled"\n                  },\n                  {\n                    "label": "Disabled"\n                  }\n                ]\n              },\n              {},\n              {\n                "label": "Feedback",\n                "fields": [\n                  {\n                    "label": "Feedback title"\n                  },\n                  {\n                    "label": "Feedback text"\n                  },\n                  {\n                    "label": "Feedback image"\n                  },\n                  {\n                    "label": "Score for this scenario",\n                    "description": "The score will be sent to any LMS, LRS or any other connected service that receives scores from H5P for users who reach this scenario."\n                  }\n                ]\n              },\n              {\n                "label": "Navigate back",\n                "description": "This will allow the user to go back and see the previous content/question in the scenario.",\n                "options": [\n                  {\n                    "label": "Use behavioural setting"\n                  },\n                  {\n                    "label": "Enabled"\n                  },\n                  {\n                    "label": "Disabled"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {\n          "label": "Pisteytyksen asetukset",\n          "fields": [\n            {\n              "label": "Pisteytyksen asetukset",\n              "description": "Valitse pisteytystyyppi",\n              "options": [\n                {\n                  "label": "Määritän itse haaranpäätteiden pisteytyksen"\n                },\n                {\n                  "label": "Automaattinen pisteytys käyttäjän vastausten perusteella"\n                },\n                {\n                  "label": "Ei pisteytystä"\n                }\n              ]\n            },\n            {\n              "label": "Ota mukaan pisteet Haarautuvan skenaarion vuorovaikutteisista osioista",\n              "description": "Jos valittuna, niin esimerkiksi Interaktiivisten videoiden pisteet lisätään kokonaispistemäärään. Jos ei valittuna, kokonaispistemäärään lasketaan vain sisältökohteiden, haarautuvien kysymysten ja haaranpäätteiden palauteosioissa määritetyt pisteet."\n            }\n          ]\n        },\n        {\n          "label": "Käyttäytymisasetukset",\n          "fields": [\n            {\n              "label": "Yliaja taaksepäin navigointi",\n              "description": "Yliaja yksittäiset asetukset taaksepäin navigoinnin sallimiseksi"\n            },\n            {\n              "label": "Yliaja sisällön loppuun pääsemisen vaatimus",\n              "description": "Yliaja yksittäiset asetukset sisällön loppuun pääsemisen vaatimisesta ennen \\"Jatka\\" -painikkeen aktivoitumista. Tällä ei ole vaikutusta, jos sisällössä ei määritellä milloin se on \\"valmis\\", esim. kuvat tai yhden sivun diaesitys."\n            },\n            {\n              "label": "Randomize Branching Questions",\n              "description": "Branching questions will be displayed in random order"\n            }\n          ]\n        },\n        {\n          "label": "Lokalisointi",\n          "fields": [\n            {\n              "label": "Aloitusruudun painikkeen teksti",\n              "default": "Aloita kurssi"\n            },\n            {\n              "label": "Lopetusruudun painikkeen teksti",\n              "default": "Aloita uudelleen alusta"\n            },\n            {\n              "label": "Aineistotyyppien ja haarautuvien kysymysten paluupainikkeen teksti",\n              "default": "Paluu"\n            },\n            {\n              "label": "Text for the disabled button on the library screens",\n              "default": "Require to complete the current module"\n            },\n            {\n              "label": "Painikkeen, jolla toistetaan video uudelleen, teksti",\n              "default": "Toista video uudelleen"\n            },\n            {\n              "label": "Loppunäkymän pisteiden teksti",\n              "default": "Pisteesi:"\n            },\n            {\n              "label": "Koko näytön painikkeen teksti",\n              "default": "Koko näyttö"\n            }\n          ]\n        }\n      ]\n    }\n  ]\n}\n'),
(95, 'fr', '{\n  "semantics": [\n    {\n      "label": "Éditeur de scénario",\n      "fields": [\n        {\n          "label": "Titre"\n        },\n        {\n          "label": "Écran de départ",\n          "fields": [\n            {\n              "label": "Titre de l’écran d''accueil",\n              "placeholder": "Titre de votre cours"\n            },\n            {\n              "label": "Sous-titre de l’écran d''accueil",\n              "placeholder": "Informations sur votre cours"\n            },\n            {\n              "label": "Image de l’écran d''accueil"\n            },\n            {\n              "label": "Texte alternatif pour l''image"\n            }\n          ]\n        },\n        {\n          "label": "Liste des écrans de fin",\n          "field": {\n            "label": "Écran de fin",\n            "fields": [\n              {\n                "label": "Titre"\n              },\n              {\n                "label": "Texte"\n              },\n              {\n                "label": "Image"\n              },\n              {\n                "label": "Score",\n                "description": "Le score sera envoyé à tout LMS, LRS ou tout autre service qui reçoit des résultats depuis H5P pour des utilisateurs qui atteignent le scénario de fin par défaut"\n              },\n              {\n                "label": "Identifiant du contenu"\n              }\n            ]\n          }\n        },\n        {\n          "label": "Liste de contenus de scénario de branchement",\n          "entity": "contenu",\n          "field": {\n            "fields": [\n              {},\n              {\n                "label": "Voir le titre du contenu dans la vue",\n                "description": "Si sélectionné, l''utilisateur verra le titre du contenu dans la barre supérieure en haut de ce contenu"\n              },\n              {\n                "label": "Text for the proceed button (max length: 50 characters)",\n                "default": "Proceed"\n              },\n              {\n                "label": "Identifiant de contenu suivant (les écrans de fin sont définis par des nombres négatifs)",\n                "description": "Contourner les options personnelles exigeant la complétion du contenu avant d’activer le bouton « Continuer ». N’aura aucun effet si le contenu n’indique pas de complétion (des images ou une présentation de cours comprenant une seule diapo, par exemple).",\n                "options": [\n                  {\n                    "label": "Use behavioural setting"\n                  },\n                  {\n                    "label": "Enabled"\n                  },\n                  {\n                    "label": "Disabled"\n                  }\n                ]\n              },\n	      {},\n              {\n                "label": "Feedback",\n                "fields": [\n                  {\n                    "label": "Feedback title"\n                  },\n                  {\n                    "label": "Feedback text"\n                  },\n                  {\n                    "label": "Feedback image"\n                  },\n                  {\n                    "label": "Score for this scenario",\n                    "description": "The score will be sent to any LMS, LRS or any other connected service that receives scores from H5P for users who reach this scenario."\n                  }\n                ]\n              },\n              {\n                "label": "Navigate back",\n                "description": "This will allow the user to go back and see the previous content/question in the scenario.",\n                "options": [\n                  {\n                    "label": "Use behavioural setting"\n                  },\n                  {\n                    "label": "Enabled"\n                  },\n                  {\n                    "label": "Disabled"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {\n          "label": "Options de notation",\n          "fields": [\n            {\n              "label": "Options de notation",\n              "description": "Sélectionner le type de notation",\n              "options": [\n                {\n                  "label": "Définir de façon statique le score pour chaque scénario de fin"\n                },\n                {\n                  "label": "Calculer dynamiquement le score à partir des réponses de l''utilisateur"\n                },\n                {\n                  "label": "Pas de notation"\n                }\n              ]\n            },\n            {\n              "label": "Inclure la notation des interactions à l’intérieur du scénario à embranchements",\n              "description": "La notation d’autres activités  (de vidéos interactives, par exemple) sera ajoutée à la notation finale obtenue. Si cette option n’est pas sélectionnée, les notations spécifiées dans les sections de feedbacks des éléments de contenus, des questions de branchement et des scénarios finaux seront comptabilisées."\n            }\n          ]\n        },\n        {\n          "label": "Options comportementales",\n          "fields": [\n            {\n              "label": "Contourner la navigation vers l’arrière",\n              "description": "Contourner les paramètres individuels pour activer la navigation vers l''arrière"\n            },\n            {\n              "label": "Contourner la nécessité de terminer le contenu",\n              "description": "Contourner les paramètres individuels exigeant que le contenu soit complété avant d''activer la touche « Continuer ». N''aura aucun effet si le contenu n''indique pas qu''il a été « fini », p.ex. des images ou des diaporamas avec une seule diapositive."\n            },\n            {\n              "label": "Randomize Branching Questions",\n              "description": "Branching questions will be displayed in random order"\n            }\n          ]\n        },\n        {\n          "label": "Localisation",\n          "fields": [\n            {\n              "label": "Texte pour le bouton de l''écran de départ",\n              "default": "Commencer le cours"\n            },\n            {\n              "label": "Texte pour le bouton de l''écran de fin",\n              "default": "Recommencer le cours"\n            },\n            {\n              "label": "Texte pour le bouton de chaque écran de la bibliothèque",\n              "default": "Revenir en arrière"\n            },\n            {\n              "label": "Text for the disabled button on the library screens",\n              "default": "Require to complete the current module"\n            },\n            {\n              "label": "Libellé du bouton pour jouer la vidéo de nouveau",\n              "default": "Jouer la vidéo de nouveau"\n            },\n            {\n              "label": "Étiquette de la notation de l''écran de fin",\n              "default": "Votre note:"\n            },\n            {\n              "label": "Étiquette Aria pour le bouton de plein écran",\n              "default": "Plein écran"\n            }\n          ]\n        }\n      ]\n    }\n  ]\n}\n'),
(95, 'gl', '{\n  "semantics": [\n    {\n      "label": "Editor de escenarios ramificados",\n      "fields": [\n        {\n          "label": "Título"\n        },\n        {\n          "label": "Pantalla de inicio",\n          "fields": [\n            {\n              "label": "Título do curso",\n              "placeholder": "Título para o teu curso"\n            },\n            {\n              "label": "Detalles do curso",\n              "placeholder": "Detalles sobre o curso"\n            },\n            {\n              "label": "Imaxe do curso"\n            },\n            {\n              "label": "Texto alternativo da imaxe"\n            }\n          ]\n        },\n        {\n          "label": "Lista de pantallas finais",\n          "field": {\n            "label": "Pantalla final",\n            "fields": [\n              {\n                "label": "Título"\n              },\n              {\n                "label": "Texto"\n              },\n              {\n                "label": "Imaxe"\n              },\n              {\n                "label": "Puntuación",\n                "description": "A puntuación enviarase a calquera LMS, LRS ou a calquera outro servizo que reciba puntuación do H5P para os usuarios que cheguen á pantalla final por defecto."\n              },\n              {\n                "label": "ID do contido"\n              }\n            ]\n          }\n        },\n        {\n          "label": "Lista do contido do escenario ramificado",\n          "entity": "contido",\n          "field": {\n            "fields": [\n              {},\n              {\n                "label": "Amosar o título do contido na vista",\n                "description": "Se se selecciona, o usuario verá o título do contido na barra de contido na parte superior."\n              },\n              {\n                "label": "Texto para o botón Continuar (lonxitude máxima: 50 caracteres)",\n                "default": "Continuar"\n              },\n              {\n                "label": "Anular requirimento de rematado de contido",\n                "options": [\n                  {\n                    "label": "Usar a configuración do comportamento"\n                  },\n                  {\n                    "label": "Activado"\n                  },\n                  {\n                    "label": "Desactivado"\n                  }\n                ],\n                "description": "Anula a configuración individual para esixir que o contido estea rematado antes de activar o botón \\"Continuar\\". Non terá ningún efecto se o contido non indica se estaba \\"acabado\\", por exemplo, imaxes ou presentacións de cursos cunha soa diapositiva."\n              },\n              {},\n              {\n                "label": "Retroalimentación",\n                "fields": [\n                  {\n                    "label": "Título da retroalimentación"\n                  },\n                  {\n                    "label": "Texto de retroalimentación"\n                  },\n                  {\n                    "label": "Imaxe da retroalimentación"\n                  },\n                  {\n                    "label": "Puntuación para este escenario",\n                    "description": "A puntuación enviarase a calquera LMS, LRS ou calquera outro servizo conectado que reciba puntuacións de H5P para os usuarios que cheguen a este escenario."\n                  }\n                ]\n              },\n              {\n                "label": "Navegar cara atrás",\n                "description": "Permite que o usuario volva atrás e vexa a pregunta ou contido anterior do escenario.",\n                "options": [\n                  {\n                    "label": "Usar a configuración do comportamento"\n                  },\n                  {\n                    "label": "Activado"\n                  },\n                  {\n                    "label": "Desactivado"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {\n          "label": "Opcións de puntuación",\n          "fields": [\n            {\n              "label": "Opcións de puntuación",\n              "description": "Selecciona o tipo de puntuación.",\n              "options": [\n                {\n                  "label": "Aplicar puntuación estática para cada pantalla final"\n                },\n                {\n                  "label": "Calcular a puntuación dinamicamente a partir das respostas do usuario"\n                },\n                {\n                  "label": "Sen puntuación"\n                }\n              ]\n            },\n            {\n              "label": "Incluir as puntuacións das interaccións dentro do Escenario Ramificado",\n              "description": "Se se activa, engadiranse as puntuacións do Vídeo Interactivo á puntuación total obtida. En caso contrario, só contarán as puntuacións especificadas nas seccións de retroalimentación dos elementos de contido, preguntas ramificadas e escenarios finais."\n            }\n          ]\n        },\n        {\n          "label": "Configuración de comportamento",\n          "fields": [\n            {\n              "label": "Navegar cara atrás",\n              "description": "Isto permitirá ao usuario volver atrás e ver o contido/pregunta anterior no escenario. Pódese anular a nivel de contido."\n            },\n            {\n              "label": "Vista obrigatoria",\n              "description": "Insta aos espectadores a completar o vídeo, o vídeo interactivo e a presentación do curso antes de continuar co escenario. Pódese anular a nivel de contido."\n            },\n            {\n              "label": "Preguntas de ramificación aleatorias",\n              "description": "As preguntas de ramificación mostraranse en orde aleatoria."\n            }\n          ]\n        },\n        {\n          "label": "Localización",\n          "fields": [\n            {\n              "label": "Texto para o botón na pantalla inicial",\n              "default": "Empezar o curso"\n            },\n            {\n              "label": "Texto para o botón na pantalla final",\n              "default": "Reiniciar o curso"\n            },\n            {\n              "label": "Texto para o botón atrás en cada pantalla da biblioteca e pregunta ramificada",\n              "default": "Atrás"\n            },\n            {\n              "label": "Texto para o botón desactivado nas pantallas da biblioteca",\n              "default": "Requirido para completar o módulo actual"\n            },\n            {\n              "label": "Texto para o botón usado para volver a reproducir o vídeo",\n              "default": "Volver a reproducir o vídeo"\n            },\n            {\n              "label": "Etiqueta para a puntuación na pantalla final",\n              "default": "A túa puntuación:"\n            },\n            {\n              "label": "Etiqueta Aria para botón de pantalla completa",\n              "default": "Pantalla completa"\n            }\n          ]\n        }\n      ]\n    }\n  ]\n}\n'),
(95, 'he', '{\n  "semantics": [\n    {\n      "label": "עורך תרחישי הסתעפות",\n      "fields": [\n        {\n          "label": "כותרת"\n        },\n        {\n          "label": "מסך התחלה",\n          "fields": [\n            {\n              "label": "כותרת של מסך התחלה",\n              "placeholder": "כותרת ללומדה"\n            },\n            {\n              "label": "פרטי הלומדה",\n              "placeholder": "מידע אודות הקורס"\n            },\n            {\n              "label": "תמונת הקורס"\n            },\n            {\n              "label": "מידע חלופי על התמונה"\n            }\n          ]\n        },\n        {\n          "label": "רשימה של מסכי סיום",\n          "field": {\n            "label": "מסך סיום",\n            "fields": [\n              {\n                "label": "כותרת"\n              },\n              {\n                "label": "טקסט"\n              },\n              {\n                "label": "תמונה"\n              },\n              {\n                "label": "ציון",\n                "description": "הציון יישלח לLMS, LRS או כל שירות שיכול לקבל ציונים מH5P של משתמשים המגיעים לתרחיש הסיום כברירת מחדל."\n              },\n              {\n                "label": "מזהה תוכן"\n              }\n            ]\n          }\n        },\n        {\n          "label": "רשימת תוכן של תרחישים מסתעפים",\n          "entity": "תוכן",\n          "field": {\n            "fields": [\n              {},\n              {\n                "label": "הצג את כותרת התוכן בתצוגה",\n                "description": "אם נבחר, המשתמש יראה את כותרת התוכן בסרגל העליון המופיע מעל תוכן זה."\n              },\n              {\n                "label": "טקסט עבור כפתור ההמשך (אורך מקסימלי: 50 תווים)",\n                "default": "להמשיך"\n              },\n              {\n                "label": "Override require content finished",\n                "description": "Override the individual settings for requiring the content to be finished before activating the \\"Proceed\\" button. Will not have any effect if the content doesn''t indicate if it was \\"finished\\", e.g. images or course presentations with just one slide.",\n                "options": [\n                  {\n                    "label": "השתמש בהגדרת התנהגות"\n                  },\n                  {\n                    "label": "פעיל"\n                  },\n                  {\n                    "label": "כבוי"\n                  }\n                ]\n              },\n              {},\n              {\n                "label": "משוב",\n                "fields": [\n                  {\n                    "label": "כותרת משוב"\n                  },\n                  {\n                    "label": "משוב"\n                  },\n                  {\n                    "label": "תמונת משוב"\n                  },\n                  {\n                    "label": "ציון עבור תרחיש זה",\n                    "description": "הציון יישלח לLMS, LRS או אמצעים אחרים שיכולים להתחבר לשירות שמקבל ציונים מH5P, למשתמשים שלוקחים חלק בתרחיש זה."\n                  }\n                ]\n              },\n              {\n                "label": "נווט אחורה",\n                "description": "זה יאפשר למשתמש לנווט אחורה ולראות תוכן או שאלות הנוגעים לתרחיש.",\n                "options": [\n                  {\n                    "label": "השתמש בנתונים התנהגותיים"\n                  },\n                  {\n                    "label": "הופעל"\n                  },\n                  {\n                    "label": "לא הופעל"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {\n          "label": "אפשרויות ניקוד",\n          "fields": [\n            {\n              "label": "אפשרויות ניקוד",\n              "description": "בחירת אופן ניקוד.",\n              "options": [\n                {\n                  "label": "מתן ציונים באופן סטטיסטי לכל תרחישי סיום"\n                },\n                {\n                  "label": "מחשב באופן דינמי ציונים מתשובות המשתמש"\n                },\n                {\n                  "label": "אין ניקוד"\n                }\n              ]\n            },\n            {\n              "label": "שילוב ניקוד מאינטרקציות שנלקחות מתרחיש הסתעפות",\n              "description": "אם נבחר ציון מוידאו אינטראקטיבי למשל, הוא יוזן לציון הכולל שהושג. אם לא נבחר ציונים המצוינים בחלק המשוב של פרטי התוכן, שאלות מסתעפות ותרחישי סיום ייחשבו."\n            }\n          ]\n        },\n        {\n          "label": "הגדרות התנהגות",\n          "fields": [\n            {\n              "label": "נווט אחורה",\n              "description": "זה יאפשר למשתמש לנווט אחורה ולראות את התוכן או השאלה שהוצגו בתרחיש הקודם. ניתן לעקוף זאת ברמת התוכן."\n            },\n            {\n              "label": "נדרש לראות",\n              "description": "דורש מהצופים להשלים צפיה בסרטון, סרטונים אינטראקטיבים והקורס הנחוצים לפני המשך התהליך בתרחישים. ניתן לעקוף זאת בשלב התוכן."\n            },\n            {\n              "label": "תרחישים אקראיים לשאלות",\n              "description": "שאלות התרחישים יוצגו בסדר אקראי."\n            }\n          ]\n        },\n        {\n          "label": "תרגום מקומי",\n          "fields": [\n            {\n              "label": "טקסט עבור הכפתור במסך הפתיחה",\n              "default": "התחלת הלומדה"\n            },\n            {\n              "label": "טקסט לכפתור במסך הסיום",\n              "default": "התחלה מחדש של הלומדה"\n            },\n            {\n              "label": "טקסט לגב הכפתור של כל מסכי הספריה ושאלות ההסתעפות",\n              "default": "אחורה"\n            },\n            {\n              "label": "טקסט עבור הכפתור ההשבתה במסכי הספרייה",\n              "default": "דרישה להשלים את המודול הנוכחי"\n            },\n            {\n              "label": "טקסט עבור הכפתור המשמש להפעלה חוזרת של סרטון",\n              "default": "תצוגה מחדש של הסרטון"\n            },\n            {\n              "label": "תווית לציון במסך הסיום",\n              "default": "הציון שלך:"\n            },\n            {\n              "label": "תווית ARIA עבור כפתור מסך מלא",\n              "default": "מסך מלא"\n            }\n          ]\n        }\n      ]\n    }\n  ]\n}\n'),
(95, 'it', '{\n  "semantics": [\n    {\n      "label": "Editor di Branching Scenario",\n      "fields": [\n        {\n          "label": "Titolo"\n        },\n        {\n          "label": "Schermata di inizio",\n          "fields": [\n            {\n              "label": "Titolo della schermata di inizio",\n              "placeholder": "Titolo del corso"\n            },\n            {\n              "label": "Sottotitolo della schermata di inizio",\n              "placeholder": "Dettagli del corso"\n            },\n            {\n              "label": "Immagine della schermata di inizio"\n            },\n            {\n              "label": "Image alternative text"\n            }\n          ]\n        },\n        {\n          "label": "Lista delle schermate finali",\n          "field": {\n            "label": "Schermata finale",\n            "fields": [\n              {\n                "label": "Titolo"\n              },\n              {\n                "label": "Testo"\n              },\n              {\n                "label": "Immagine"\n              },\n              {\n                "label": "Punteggio",\n                "description": "Il punteggio sarà inviato a ogni LMS, LRS o a ogni altro servizio collegato che riceva punteggi da H5P per utenti che raggiungano lo scenario finale predefinito"\n              },\n              {\n                "label": "ID del contenuto"\n              }\n            ]\n          }\n        },\n        {\n          "label": "Lista dei contenuti del Branching Scenario",\n          "entity": "contenuto",\n          "field": {\n            "fields": [\n              {},\n              {\n                "label": "Mostra il titolo del contenuto nella visualizzazione",\n                "description": "Se selezionato, l''utente vedrà il titolo del contenuto nella barra sopra questo contenuto"\n              },\n              {\n                "label": "Text for the proceed button (max length: 50 characters)",\n                "default": "Proceed"\n              },\n              {\n                "label": "Override require content finished",\n                "description": "Override the individual settings for requiring the content to be finished before activating the \\"Proceed\\" button. Will not have any effect if the content doesn''t indicate if it was \\"finished\\", e.g. images or course presentations with just one slide.",\n                "options": [\n                  {\n                    "label": "Use behavioural setting"\n                  },\n                  {\n                    "label": "Enabled"\n                  },\n                  {\n                    "label": "Disabled"\n                  }\n                ]\n              },\n              {},\n              {\n                "label": "Feedback",\n                "fields": [\n                  {\n                    "label": "Feedback title"\n                  },\n                  {\n                    "label": "Feedback text"\n                  },\n                  {\n                    "label": "Feedback image"\n                  },\n                  {\n                    "label": "Score for this scenario",\n                    "description": "The score will be sent to any LMS, LRS or any other connected service that receives scores from H5P for users who reach this scenario."\n                  }\n                ]\n              },\n              {\n                "label": "Navigate back",\n                "description": "This will allow the user to go back and see the previous content/question in the scenario.",\n                "options": [\n                  {\n                    "label": "Use behavioural setting"\n                  },\n                  {\n                    "label": "Enabled"\n                  },\n                  {\n                    "label": "Disabled"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {\n          "label": "Opzioni di punteggio",\n          "fields": [\n            {\n              "label": "Opzioni di punteggio",\n              "description": "Scegli il tipo di punteggio",\n              "options": [\n                {\n                  "label": "Imposta statisticamente un punteggio per ogni finale di scenario"\n                },\n                {\n                  "label": "Calcola dinamicamente il punteggio in base alle risposte dell''utente"\n                },\n                {\n                  "label": "Nessun punteggio"\n                }\n              ]\n            },\n            {\n              "label": "Include scores from interactions within the Branching Scenario",\n              "description": "If chosen scores from for instance Interactive Videos will be added to the total score obtained. If not chosen only scores specified in the feedback sections of the content items, branching questions and end scenarios will count."\n            }\n          ]\n        },\n        {\n          "label": "Impostazioni esecuzione",\n          "fields": [\n            {\n              "label": "Override require content finished",\n              "description": "Override the individual settings for requiring the content to be finished before activating the \\"Proceed\\" button. Will not have any effect if the content doesn''t indicate if it was \\"finished\\", e.g. images or course presentations with just one slide."\n            },\n            {\n              "label": "Required to watch",\n              "description": "Urges viewers to complete the Video, Interactive Vdeo and Course Presentation before proceeding with the scenario. This can be overridden on a content level"\n            },\n            {\n              "label": "Randomize Branching Questions",\n              "description": "Branching questions will be displayed in random order"\n            }\n          ]\n        },\n        {\n          "label": "Localizzazione",\n          "fields": [\n            {\n              "label": "Testo per il pulsante sulla schermata di inizio",\n              "default": "Inizia il corso"\n            },\n            {\n              "label": "Testo per il pulsante sulla schermata finale",\n              "default": "Riavvia il corso"\n            },\n            {\n              "label": "Testo per il pulsante su ognuna delle schermate della libreria",\n              "default": "Procedi"\n            },\n            {\n              "label": "Text for the disabled button on the library screens",\n              "default": "Require to complete the current module"\n            },\n            {\n              "label": "Etichetta per il punteggio sulla schermata finale",\n              "default": "Il tuo punteggio:"\n            },\n            {\n              "label": "Label for score on the end screen",\n              "default": "Your score:"\n            },\n            {\n              "label": "Aria label for fullscreen button",\n              "default": "Fullscreen"\n            }\n          ]\n        }\n      ]\n    }\n  ]\n}\n'),
(95, 'ka', '{\n  "semantics": [\n    {\n      "fields": [\n        {\n          "label": "სათაური"\n        },\n        {\n          "label": "საწყისი გვერდი",\n          "fields": [\n            {\n              "label": "კურსის სათაური",\n              "placeholder": "სათაური თქვენი კურსისთვის"\n            },\n            {\n              "label": "კურსის დეტალები",\n              "placeholder": "დეტალები კურსის შესახებ"\n            },\n            {\n              "label": "კურსის სურათი"\n            },\n            {\n              "label": "სურათის ალტერნატიული ტექსტი"\n            }\n          ]\n        },\n        {\n          "label": "დასასრულის გვერდების ჩამონათვალი",\n          "field": {\n            "label": "დასასრულის გვერდი",\n            "fields": [\n              {\n                "label": "სათაური"\n              },\n              {\n                "label": "ტექსტი"\n              },\n              {\n                "label": "სურათი"\n              },\n              {\n                "label": "ქულა",\n                "description": "ქულა გაიგზავნება ნებისმიერ LMS-ში."\n              },\n              {\n                "label": "კონტენტის ID"\n              }\n            ]\n          }\n        },\n        {\n          "entity": "კონტენტი",\n          "field": {\n            "fields": [\n              {},\n              {\n                "label": "აჩვენე კონტენტის სათაური ხედვაში",\n                "description": "თუ მოინიშნება, მომხმარებელი დაინახავს კონტენტის სათაურს ზედა პანელში."\n              },\n              {\n                "label": "\\"გაგრძელების\\" ღილაკის ტექსტი (მაქსიმუმი სიგრძე: 50 სიმბოლო)",\n                "default": "გაგრძელება"\n              },\n              {\n                "options": [\n                  {\n                    "label": "გამოიყენე ქცევის პარამეტრები"\n                  },\n                  {\n                    "label": "დაშვებული"\n                  },\n                  {\n                    "label": "გამორთული"\n                  }\n                ],\n                "label": "გადააწერე კონტენტის დასრულების მოთხოვნა",\n                "description": "გადააწერე ინდივიდუალურ პარამეტრებს, რომლებიც მოითხოვენ კონტენტის დასრულებას, სანამ \\"გაგრძელების\\" ღილაკი გააქტიურდება."\n              },\n              {},\n              {\n                "label": "უკუკავშირი",\n                "fields": [\n                  {\n                    "label": "უკუკავშირის სათაური"\n                  },\n                  {\n                    "label": "უკუკავშირის ტექსტი"\n                  },\n                  {\n                    "label": "უკუკავშირის სურათი"\n                  },\n                  {\n                    "label": "ამ სცენარის ქულა",\n                    "description": "ქულა გიგზავნება ნებისმიერ LMS-ში."\n                  }\n                ]\n              },\n              {\n                "label": "წადი უკან",\n                "description": "ეს შესაძლებლობას მისცემს მომხმარებელს, რომ წავიდეს უკან და ნახოს ამ სცენარის წინა კონტენტი/შეკითხვა.",\n                "options": [\n                  {\n                    "label": "გამოიყენე ქცევის პარამეტრი"\n                  },\n                  {\n                    "label": "გააქტიურებული"\n                  },\n                  {\n                    "label": "გამორთული"\n                  }\n                ]\n              }\n            ]\n          },\n          "label": "განშტოების სცენარის კონტენტის ჩამონათვალი"\n        },\n        {\n          "fields": [\n            {\n              "options": [\n                {\n                  "label": "სტატიკურად დააყენე ქულა ყველა სცენარის ბოლოს"\n                },\n                {\n                  "label": "დინამიურად გამოთვალე ქულა მომხმარებლის პასუხებიდან"\n                },\n                {\n                  "label": "ქულების გარეშე"\n                }\n              ],\n              "label": "ქულების პარამეტრები",\n              "description": "ამოირჩიე ქულების ტიპი."\n            },\n            {\n              "label": "გაითვალისწინე ინტერაქციის ქულები განშტოების სცენარში",\n              "description": "თუ ამორჩეულია, მაშინ, მაგალითად, ინტერაქტიული ვიდეოს ქულები დაემატება მთლიან ქულას."\n            }\n          ],\n          "label": "ქულების პარამეტრები"\n        },\n        {\n          "label": "ქცევის პარამეტრები",\n          "fields": [\n            {\n              "label": "წადი უკან",\n              "description": "ეს შესაძლებლობას მისცემს მომხმარებელს, წავიდეს უკან და ნახოს ამ სცენარის წინა კონტენტი/შეკითხვა."\n            },\n            {\n              "label": "მოითხოვება ნახვა",\n              "description": "აიძულებს მომხმარებლებს, ვიდეოს, ინტერაქტიული ვიდეოს და კურსის პრეზენტაციის დასრულებას, სანამ გააგრძელებს სცენარს."\n            },\n            {\n              "label": "აურიე განშტოების შეკითხვები",\n              "description": "განშტოების შეკითხვები გამოჩნდება შემთხვევითი რიგითობით."\n            }\n          ]\n        },\n        {\n          "label": "ლოკალიზაცია",\n          "fields": [\n            {\n              "label": "საწყისი გვერდის ღილაკის ტექსტი",\n              "default": "დაიწყე კურსი"\n            },\n            {\n              "label": "ბოლო გვერდის ღილაკის ტექსტი",\n              "default": "კურსის თავიდან დაწყება"\n            },\n            {\n              "default": "უკან",\n              "label": "უკან წასვლის ღილაკის ტექსტი თითოეული ბიბლიოთეკის გვერდის და განშტოების შეკითხვისთვის"\n            },\n            {\n              "label": "გამორთული ღილაკის ტექსტი ბიბლიოთეკის გვერდებისთვის",\n              "default": "მოითხოვე მიმდინარე მოდულის დასრულება"\n            },\n            {\n              "label": "ვიდეოს თავიდან ჩართვის ღილაკის ტექსტი",\n              "default": "ვიდეოს თავიდან ჩართვა"\n            },\n            {\n              "label": "ბოლო გვერდზე მოცემული ქულის წარწერა",\n              "default": "შენი ქულაა:"\n            },\n            {\n              "label": "არეალის წარწერა მთლიანი გვერდის ღილაკისთვის",\n              "default": "მთლიანი გვერდი"\n            }\n          ]\n        }\n      ],\n      "label": "განშტოების სცენარის რედაქტორი"\n    }\n  ]\n}\n');
