(95, 'pt-br', '{\n  "semantics": [\n    {\n      "label": "Editor do Cenário de Ramificação",\n      "fields": [\n        {\n          "label": "Título"\n        },\n        {\n          "label": "Tela inicial",\n          "fields": [\n            {\n              "label": "Título da tela inicial",\n              "placeholder": "Título para o seu curso"\n            },\n            {\n              "label": "Subtítulo da tela inicial",\n              "placeholder": "Detalhes sobre o curso"\n            },\n            {\n              "label": "Imagem da tela inicial"\n            },\n            {\n              "label": "Texto alternativo da imagem"\n            }\n          ]\n        },\n        {\n          "label": "Lista das telas finais",\n          "field": {\n            "label": "Tela Final",\n            "fields": [\n              {\n                "label": "Título"\n              },\n              {\n                "label": "Texto"\n              },\n              {\n                "label": "Imagem"\n              },\n              {\n                "label": "Pontuação",\n                "description": "A pontuação será enviada para qualquer LMS, LRS ou qualquer outro serviço conectado que receba pontuação do H5P para usuários que atinjam o cenário final padrão"\n              },\n              {\n                "label": "ID do Conteúdo"\n              }\n            ]\n          }\n        },\n        {\n          "label": "Lista dos conteúdos dos cenários de ramificação",\n          "entity": "conteúdo",\n          "field": {\n            "fields": [\n              {},\n              {\n                "label": "Mostrar o título do conteúdo visualizado",\n                "description": "Se selecionado, o usuário verá o título do conteúdo na barra superior acima deste conteúdo"\n              },\n              {\n                "label": "Text for the proceed button (max length: 50 characters)",\n                "default": "Proceed"\n             