(96, 'fr', '{\n  "semantics": [\n    {\n      "fields": [\n        {\n          "field": {\n            "fields": [\n              {\n                "field": {\n                  "fields": [\n                    {},\n                    {},\n                    {},\n                    {},\n                    {},\n                    {\n                      "label": "Commentaires",\n                      "description": "Les commentaires sont affichés pour aider les utilisateurs lors de la présentation."\n                    },\n                    {\n                      "label": "Toujours afficher les commentaires"\n                    },\n                    {\n                      "label": "Opacité"\n                    },\n                    {\n                      "label": "Afficher sous forme de bouton"\n                    },\n                    {\n                      "label": "La taille de bouton",\n                      "options": [\n                        {\n                          "label": "Petite"\n                        },\n                        {\n                          "label": "Grande"\n                        }\n                      ]\n                    },\n                    {\n                      "label": "Titre"\n                    },\n                    {\n                      "label": "Aller vers",\n                      "options": [\n                        {\n                          "label": "Le numéro de diapositive spécifique"\n                        },\n                        {\n                          "label": "Diapositive suivante"\n                        },\n                        {\n                          "label": "Diapositive précédente"\n                        }\n                      ]\n                    },\n                    {\n                      "label": "Aller à la diapositive",\n                      "description": "N''est applicable que si le bouton ''Le numéro de diapositive spécifique'' est sélectionné"\n                    },\n                    {\n                      "label": "Invisible",\n                      "description": "Curseur par défaut, pas de titre, pas d''onglets. Attention : Les utilisateurs ayant des handicaps ou ceux qui n''utilisent que le clavier auront des difficultés à réaliser cette activité."\n                    }\n                  ]\n                }\n              },\n              {},\n              {\n                "fields": [\n                  {\n                    "label": "Image",\n                    "description": "Pour que l''image d''arrière-plan ne soit pas déformée, elle doit avoir un ratio largeur/hauteur de 2 pour 1. Les images en haute résolution offrent un meilleur rendu sur les grands écrans."\n                  },\n                  {\n                    "label": "Sélectionnez une couleur"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {},\n        {\n          "label": "Liste des mots-clés"\n        },\n        {\n          "label": "Toujours l''afficher"\n        },\n        {\n          "label": "La cacher automatiquement"\n        },\n        {\n          "label": "Opacité"\n        },\n        {\n          "fields": [\n            {\n              "label": "Image d''arrière-plan",\n              "description": "Pour que l''image d''arrière-plan ne soit pas déformée, elle doit avoir un ratio largeur/hauteur de 2 pour 1. Les images en haute résolution offrent un meilleur rendu sur les grands écrans."\n            },\n            {\n              "label": "Sélectionnez une couleur"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Options générales",\n      "fields": [\n        {\n          "label": "Traduction pour \\"Diapositive\\"",\n          "default": "Diapositive"\n        },\n        {\n          "label": "Traduction pour \\"Score\\"",\n          "default": "Score"\n        },\n        {\n  