INSERT INTO `wpcu_h5p_libraries_languages` VALUES
(97, 'lv', '{\n  "semantics": [\n    {\n      "label": "Interaktīvā video redaktors",\n      "fields": [\n        {\n          "label": "Augšupielādēt/iegult video",\n          "fields": [\n            {\n              "label": "Video pievienošana",\n              "description": "Noklikšķiniet zemāk, lai pievienotu videoklipu, ko vēlaties izmantot savā interaktīvajā video. Varat pievienot video saiti vai augšupielādēt video failus. Ir iespējams pievienot vairākas video versijas ar atšķirīgu kvalitāti. Lai nodrošinātu maksimālu atbalstu pārlūkprogrammās, pievienojiet vismaz versiju webm un mp4 formātos."\n            },\n            {\n              "label": "Sākuma ekrāna opcijas (netiek atbalstītas YouTube videoklipiem)",\n              "fields": [\n                {\n                  "label": "Šī interaktīvā videoklipa nosaukums",\n                  "default": "Interaktīvais video",\n                  "description": "Tiek izmantots apkopojumos, statistikā utt."\n                },\n                {\n                  "label": "Paslēpt nosaukumu video sākuma ekrānā"\n                },\n                {\n                  "label": "Īss apraksts (neobligāts)",\n                  "description": "Neobligāti. Parādiet īsu apraksta tekstu video sākuma ekrānā. Nedarbojas YouTube videoklipiem."\n                },\n                {\n                  "label": "Afišas attēls",\n                  "description": "Attēls tiek parādīts, pirms lietotājs palaiž video. Nedarbojas YouTube videoklipiem."\n                }\n              ]\n            },\n            {\n              "label": "Teksta celiņi (YouTube videoklipiem netiek atbalstīti)",\n              "fields": [\n                {\n                  "label": "Pieejamie teksta celiņi",\n                  "entity": "Celiņš",\n                  "field": {\n                    "label": "Celiņš",\n                    "fields": [\n                      {\n                        "label": "Celiņa etiķete",\n                        "description": "Tiek izmantots, ja piedāvājat vairākus celiņus un lietotājam ir jāizvēlas celiņš. Piemēram, “subtitri spāņu valodā” varētu būt spāņu valodas subtitru celiņa etiķete.",\n                        "default": "Subtitri"\n                      },\n                      {\n                        "label": "Teksta celiņa veids",\n                        "options": [\n                          {\n                            "label": "Subtitri"\n                          },\n                          {\n                            "label": "Titri"\n                          },\n                          {\n                            "label": "Apraksti"\n                          }\n                        ]\n                      },\n                      {\n                        "label": "Subtitriem jānorāda avota valoda",\n                        "default": "en",\n                        "description": "Jābūt derīgai BCP 47 valodas birkai. Ja atlasītā teksta celiņa veids ir ''Subtitri'', jādefinē celiņa avota valoda."\n                      },\n                      {\n                        "label": "Celiņa avots (WebVTT fails)"\n                      }\n                    ]\n                  }\n                },\n                {\n                  "label": "Noklusējuma teksta celiņš",\n                  "description": "Ja atstāts tukšs vai neatbilst nevienam teksta celiņam, pirmais teksta celiņš tiks izmantots kā noklusējuma celiņš."\n                }\n              ]\n            }\n          ]\n        },\n        {\n          "label": "Pievienot mijiedarbības",\n          "fields": [\n            {\n              "field": {\n                "fields": [\n                  {\n                    "label": "Parādīšanas laiks"\n                  },\n                  {\n                    "label": "Pauzēt video"\n                  },\n                  {\n                    "label": "Parādīt kā",\n                    "description": "<b>Poga</b> ir sakļauta mijiedarbība, kas lietotājam ir jānospiež, lai to atvērtu. <b>Afiša</b> ir paplašināta mijiedarbība, kas tiek parādīta tieši video priekšplānā",\n                    "options": [\n                      {\n                        "label": "Poga"\n                      },\n                      {\n                        "label": "Afiša"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Mazos ekrānos pārvērst par pogu"\n                  },\n                  {\n                    "label": "Etiķete",\n                    "description": "Etiķete kas tiek rādīta blakus mijiedarbības ikonai."\n                  },\n                  {},\n                  {},\n                  {},\n                  {},\n                  {},\n                  {},\n                  {\n                    "label": "Adaptivitāte",\n                    "fields": [\n                      {\n                        "label": "Rīcība ja viss pareizi",\n                        "fields": [\n                          {\n                            "label": "Doties uz",\n                            "description": "Ievadiet laika kodu formātā M:SS"\n                          },\n                          {\n                            "label": "Ļaut lietotājam atteikties un turpināt"\n                          },\n                          {\n                            "label": "Ziņa"\n                          },\n                          {\n                            "label": "Etiķete meklēšanas pogai"\n                          }\n                        ]\n                      },\n                      {\n                        "label": "Rīcība ja nepareizi",\n                        "fields": [\n                          {\n                            "label": "Doties uz",\n                            "description": "Ievadiet laika kodu formātā M:SS"\n                          },\n                          {\n                            "label": "Ļaut lietotājam atteikties un turpināt"\n                          },\n                          {\n                            "label": "Ziņa"\n                          },\n                          {\n                            "label": "Meklēšanas pogas etiķete"\n                          }\n                        ]\n                      },\n                      {\n                        "label": "Pirms turpināt, pieprasīt pilnu punktu skaitu par uzdevumu",\n                        "description": "For best functionality this option should be used in conjunction with the \\"Disable navigation forward in a video\\" option of Interactive Video."\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Noformējums",\n                    "fields": [\n                      {\n                        "label": "Fona krāsa",\n                        "default": "rgb(255, 255, 255)"\n                      },\n                      {\n                        "label": "Rāmīša ēnojums",\n                        "description": "Pievieno smalku ēnu ap mijiedarbību. Iespējams, vēlēsieties to atspējot mijiedarbībām ar caurspīdīgu fonu"\n                      }\n                    ]\n                  },\n                  {\n                    "label": "Pēc klikšķa doties uz",\n                    "fields": [\n                      {\n                        "label": "Tips",\n                        "options": [\n                          {\n                            "label": "Laika kods"\n                          },\n                          {\n                            "label": "Cita lapa (URL)"\n                          }\n                        ]\n                      },\n                      {\n                        "label": "Iet uz",\n                        "description": "Mērķa laiks uz kuru lietotājs tiks novirzīts pēc klikšķa uz aktīvā punkta. Ievadiet laika kodu šādā formātā: M:SS."\n                      },\n                      {\n                        "label": "URL",\n                        "fields": [\n                          {\n                            "label": "Protokols",\n                            "options": [\n                              {\n                                "label": "http://"\n                              },\n                              {\n                                "label": "https://"\n                              },\n                              {\n                                "label": "(relatīvais ceļš)"\n                              },\n                              {\n                                "label": "cits"\n                              }\n                            ]\n                          },\n                          {\n                            "label": "URL"\n                          }\n                        ]\n                      },\n                      {\n                        "label": "Vizualizēt",\n                        "description": "Parādiet, ka mijiedarbība ir klikšķināma, pievienojot apmali un ikonu"\n                      }\n                    ]\n                  }\n                ]\n              }\n            },\n            {},\n            {}\n          ]\n        },\n        {\n          "label": "Kopsavilkuma uzdevums",\n          "fields": [\n            {},\n            {\n              "label": "Parādīt plkst",\n              "description": "Sekunžu skaits pirms videoklipa beigām."\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Uzvedības iestatījumi",\n      "fields": [\n        {\n          "label": "Sākt video no",\n          "description": "Ievadiet laika kodu formātā M:SS"\n        },\n        {\n          "label": "Video automātiskā atskaņošana",\n          "description": "Sākt automātiski atskaņot videoklipu"\n        },\n        {\n          "l