(104, 'sw', '{\n  "semantics": [\n    {\n      "label": "Mhariri wa Picha Tatu",\n      "fields": [\n        {\n          "label": "Maonyesho",\n          "entity": "Onyesho",\n          "field": {\n            "fields": [\n              {\n                "label": "Aina ya onyesho",\n                "options": [\n                  {\n                    "label": "Picha ya 360"\n                  },\n                  {\n                    "label": "Picha mgando"\n                  }\n                ]\n              },\n              {\n                "label": "Onyesha kitufe cha \\"Nyuma\\"",\n                "description": "Onyesha kitufe cha kurejea kwenye onyesho lako la awali"\n              },\n              {},\n              {\n                "label": "Mada ya Onyesho",\n                "description": "Hutumika kutambua onyesho"\n              },\n              {\n                "label": "Mandharinyuma ya onyesho"\n              },\n              {\n                "label": "Maelezo ya onyesho",\n                "description": "Maandishi yanayoweza kuelezea onyesho kwa mtumiaji wa mwisho"\n              },\n              {},\n              {\n                "field": {\n                  "fields": [\n                    {\n                      "label": "Lebo",\n                      "description": "Ikiachwa wazi hakuna lebo itakayoonyeshwa na tutajaribu kutumia sehemu ya mada kwa visoma skrini"\n                    },\n                    {\n                      "label": "Mipangilio ya Lebo",\n                      "fields": [\n                        {\n                          "label": "Sehemu ya lebo",\n                          "description": "Chagua mahali ambapo lebo inapaswa kuonekana",\n                          "options": [\n                            {\n                              "label": "Tumia mpangilio wa kitabia"\n                            },\n                            {\n                              "label": "Imepangiliwa kulia"\n                            },\n                            {\n                              "label": "Imepangiliwa kushoto"\n                            },\n                            {\n                              "label": "Imepangiliwa juu"\n                            },\n                            {\n                              "label": "Imepangiliwa chini"\n                            }\n                          ]\n                        },\n                        {\n                          "label": "Lebo ya Kuonyesha",\n                          "description": "Ikiwa imefichwa - lebo zitaonyesha tu kwenye kiteuzi",\n                          "options": [\n                            {\n                              "label": "Tumia mpangilio wa kitabia"\n                            },\n                            {\n                              "label": "Onyesha"\n                            },\n                            {\n                              "label": "Ficha"\n                            }\n                          ]\n                        }\n                      ]\n                    },\n                    {},\n                    {}\n                  ]\n                }\n              },\n              {\n                "label": "Mtindo wa kitufe",\n                "description": "Amua jinsi gani vitufe vinavyoelekeza kwenye eneo hili vinapaswa kuonekana. Kwa maonyesho ambayo ni mgando na hayaelekezi kwenye maonyesho mapya, tunapendekeza kitufe cha “Maelezo zaidi”.",\n                "options": [\n                  {\n                    "label": "Onyesho jipya (mshale)"\n                  },\n                  {\n                    "label": "Maelezo zaidi (jumlisha)"\n                  }\n                ]\n              },\n              {\n                "label": "Wimbo wa Sauti",\n                "description": "Ongeza wimbo wa sauti ambao ni maalumu kwa onyesho hili."\n              }\n            ]\n          }\n        },\n        {},\n        {\n          "label": "Wimbo wa sauti"\n        }\n      ]\n    },\n    {\n      "label": "Mipangilio ya kitabia",\n      "description": "Chaguzi hizi zitakuwezesha kudhibiti jinsi ulimwengu unavyofanya.",\n      "fields": [\n        {\n          "label": "Sauti ya Kimataifa",\n          "description": "Ongeza wimbo wa sauti uliopo kwa maonyesho yote kwa chaguo-msingi."\n        },\n        {\n          "label": "Ubora wa uwasilishaji wa onyesho",\n          "description": "Chagua kiasi cha upana na urefu wa sehemu zinazotumika kuwasilisha onyesho. Hii huathiri kiwango cha ubora wa tukio moja kwa moja, jaribu kuongeza ubora iwapo onyesho linaonekana “kuzuia” au “mawimbi” yanaonekana ndani ya onyesho. Kumbuka kuwa uwasilishaji wa ubora wa juu huchukua muda zaidi kufungua.",\n          "options": [\n            {\n              "label": "Ubora wa Juu (128x128)"\n            },\n            {\n              "label": "Ubora wa Wastani (64x64)"\n            },\n            {\n              "label": "Ubora wa Chini (16x16)"\n            }\n          ]\n        },\n        {\n          "label": "Mipangilio ya lebo",\n          "fields": [\n            {\n              "label": "Sehemu ya lebo",\n              "description": "Nafasi ya chaguo-msingi ya lebo. Nafasi inaweza kubatilishwa kwa kila mwingiliano",\n              "options": [\n                {\n                  "label": "Imepangiliwa kulia"\n                },\n                {\n                  "label": "Imepangiliwa kushoto"\n                },\n                {\n                  "label": "Imepangiliwa juu"\n                },\n                {\n                  "label": "Imepangiliwa chini"\n                }\n              ]\n            },\n            {\n              "label": "Lebo za Kuonyesha",\n              "description": "Ikiwa haijawekwa alama - lebo zitaonyesha tu kwenye juu ya kiteuzi"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      "label": "Janibisha",\n      "fields": [\n        {\n          "label": "Lebo ya Aria ya aina ya maudhui",\n          "default": "Ziara ya Mtandaoni"\n        },\n        {\n          "label": "Lebo ya kucheza sauti",\n          "default": "Cheza Wimbo wa Sauti"\n        },\n        {\n          "label": "Lebo ya kusitisha sauti",\n          "default": "Sitisha Wimbo wa Sauti"\n        },\n        {\n          "label": "Mada ya mazungumzo ya onyesho",\n          "default": "Maelezo ya onyesho"\n        },\n        {\n          "label": "Lebo ya kitufe cha kuweka kamera upya",\n          "default": "Weka Kamera Upya"\n        },\n        {\n          "label": "Lebo ya kitufe cha kuwasilisha mazungumzo",\n          "default": "Wasilisha Mazungumzo"\n        },\n        {\n          "label": "Lebo ya kitufe cha kufunga mazungumzo",\n          "default": "Funga Mazungumzo"\n        },\n        {\n          "label": "Lebo ya Aria ya kitufe cha lebo ya kupanua",\n          "default": "Panua lebo ya kuona"\n        },\n        {\n          "label": "Lebo ya wakati picha ya mandharinyuma inapakia katika onyesho la 360",\n          "default": "Inapakia picha ya mandharinyuma..."\n        },\n        {\n          "label": "Lebo ya wakati hakuna maudhui",\n          "default": "Hakuna maudhui"\n        }\n      ]\n    }\n  ]\n}\n');
