(1919, 1, '2026-02-01 08:48:01', '2026-02-01 08:48:01', '', 'MTTI-Privacy-Policy', '', 'inherit', 'open', 'closed', '', 'mtti-privacy-policy', '', '', '2026-02-01 08:48:01', '2026-02-01 08:48:01', '', 0, 'https://masomoteletraining.co.ke/wp-content/uploads/2026/02/MTTI-Privacy-Policy.docx', 0, 'attachment', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 0),
(1920, 1, '2026-02-01 14:12:12', '0000-00-00 00:00:00', 'Thank you for reading this post, don''t forget to subscribe!', 'Display a message after the 1st paragraph of posts', '', 'draft', 'closed', 'closed', '', '', '', '', '2026-02-01 14:12:12', '0000-00-00 00:00:00', '', 0, 'https://masomoteletraining.co.ke/?post_type=wpcode&p=1920', 0, 'wpcode', '', 0),
(1921, 1, '2026-02-01 14:12:13', '0000-00-00 00:00:00', 'add_action(''admin_init'', function () {\r\n    // Redirect any user trying to access comments page\r\n    global $pagenow;\r\n    \r\n    if ($pagenow === ''edit-comments.php'') {\r\n        wp_safe_redirect(admin_url());\r\n        exit;\r\n    }\r\n\r\n    // Remove comments metabox from dashboard\r\n    remove_meta_box(''dashboard_recent_comments'', ''dashboard'', ''normal'');\r\n\r\n    // Disable support for comments and trackbacks in post types\r\n    foreach (get_post_types() as $post_type) {\r\n        if (post_type_supports($post_type, ''comments'')) {\r\n            remove_post_type_support($post_type, ''comments'');\r\n            remove_post_type_support($post_type, ''trackbacks'');\r\n        }\r\n    }\r\n});\r\n\r\n// Close comments on the front-end\r\nadd_filter(''comments_open'', ''__return_false'', 20, 2);\r\nadd_filter(''pings_open'', ''__return_false'', 20, 2);\r\n\r\n// Hide existing comments\r\nadd_filter(''comments_array'', ''__return_empty_array'', 10, 2);\r\n\r\n// Remove comments page in menu\r\nadd_action(''admin_menu'', function () {\r\n    remove_menu_page(''edit-comments.php'');\r\n});\r\n\r\n// Remove comments links from admin bar\r\nadd_action(''init'', function () {\r\n    if (is_admin_bar_showing()) {\r\n        remove_action(''admin_bar_menu'', ''wp_admin_bar_comments_menu'', 60);\r\n    }\r\n});', 'Completely Disable Comments', '', 'draft', 'closed', 'closed', '', '', '', '', '2026-02-01 14:12:13', '0000-00-00 00:00:00', '', 0, 'https://masomoteletraining.co.ke/?post_type=wpcode&p=1921', 0, 'wpcode', '', 0),
(1922, 1, '2026-02-01 14:57:42', '2026-02-01 14:57:42', '<!-- MTTI Chatbot Widget -->\r\n<!-- Add this code just before </body> tag in your WordPress theme -->\r\n\r\n<style>\r\n/* MTTI Chatbot Styles */\r\n#mtti-chat-widget {\r\n    position: fixed;\r\n    bottom: 20px;\r\n    right: 20px;\r\n    z-index: 9999;\r\n    font-family: ''Segoe UI'', Tahoma, Geneva, Verdana, sans-serif;\r\n}\r\n\r\n#mtti-chat-button {\r\n    width: 60px;\r\n    height: 60px;\r\n    border-radius: 50%;\r\n    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);\r\n    border: none;\r\n    cursor: pointer;\r\n    box-shadow: 0 4px 20px rgba(0,0,0,0.3);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    transition: transform 0.3s, box-shadow 0.3s;\r\n}\r\n\r\n#mtti-chat-button:hover {\r\n    transform: scale(1.1);\r\n    box-shadow: 0 6px 25px rgba(0,0,0,0.4);\r\n}\r\n\r\n#mtti-chat-button svg {\r\n    width: 30px;\r\n    height: 30px;\r\n    fill: #00d4ff;\r\n}\r\n\r\n#mtti-chat-button.has-notification::after {\r\n    content: ''1'';\r\n    position: absolute;\r\n    top: -5px;\r\n    right: -5px;\r\n    background: #ff4757;\r\n    color: white;\r\n    width: 22px;\r\n    height: 22px;\r\n    border-radius: 50%;\r\n    font-size: 12px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-weight: bold;\r\n}\r\n\r\n#mtti-chat-box {\r\n    display: none;\r\n    position: absolute;\r\n    bottom: 70px;\r\n    right: 0;\r\n    width: 350px;\r\n    height: 500px;\r\n    background: white;\r\n    border-radius: 16px;\r\n    box-shadow: 0 10px 40px rgba(0,0,0,0.2);\r\n    overflow: hidden;\r\n    flex-direction: column;\r\n}\r\n\r\n#mtti-chat-box.open {\r\n    display: flex;\r\n}\r\n\r\n#mtti-chat-header {\r\n    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);\r\n    color: white;\r\n    padding: 15px;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 10px;\r\n}\r\n\r\n#mtti-chat-header img {\r\n    width: 40px;\r\n    height: 40px;\r\n    border-radius: 50%;\r\n    background: #00d4ff;\r\n}\r\n\r\n#mtti-chat-header-info h4 {\r\n    margin: 0;\r\n    font-size: 14px;\r\n}\r\n\r\n#mtti-chat-header-info p {\r\n    margin: 0;\r\n    font-size: 11px;\r\n    color: #8892b0;\r\n}\r\n\r\n#mtti-chat-close {\r\n    margin-left: auto;\r\n    background: none;\r\n    border: none;\r\n    color: white;\r\n    font-size: 24px;\r\n    cursor: pointer;\r\n    padding: 0;\r\n    line-height: 1;\r\n}\r\n\r\n#mtti-chat-messages {\r\n    flex: 1;\r\n    overflow-y: auto;\r\n    padding: 15px;\r\n    background: #f8f9fa;\r\n}\r\n\r\n.mtti-message {\r\n    margin-bottom: 12px;\r\n    display: flex;\r\n    flex-direction: column;\r\n}\r\n\r\n.mtti-message.bot {\r\n    align-items: flex-start;\r\n}\r\n\r\n.mtti-message.user {\r\n    align-items: flex-end;\r\n}\r\n\r\n.mtti-message-bubble {\r\n    max-width: 80%;\r\n    padding: 10px 14px;\r\n    border-radius: 16px;\r\n    font-size: 14px;\r\n    line-height: 1.4;\r\n}\r\n\r\n.mtti-message.bot .mtti-message-bubble {\r\n    background: white;\r\n    color: #333;\r\n    border: 1px solid #e0e0e0;\r\n    border-bottom-left-radius: 4px;\r\n}\r\n\r\n.mtti-message.user .mtti-message-bubble {\r\n    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);\r\n    color: white;\r\n    border-bottom-right-radius: 4px;\r\n}\r\n\r\n#mtti-chat-options {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    gap: 8px;\r\n    padding: 10px 15px;\r\n    background: #f8f9fa;\r\n    border-top: 1px solid #e0e0e0;\r\n}\r\n\r\n.mtti-option-btn {\r\n    background: white;\r\n    border: 2px solid #00d4ff;\r\n    color: #1a1a2e;\r\n    padding: 8px 14px;\r\n    border-radius: 20px;\r\n    font-size: 13px;\r\n    cursor: pointer;\r\n    transition: all 0.3s;\r\n}\r\n\r\n.mtti-option-btn:hover {\r\n    background: #00d4ff;\r\n    color: white;\r\n}\r\n\r\n#mtti-chat-input-area {\r\n    display: flex;\r\n    padding: 10px;\r\n    background: white;\r\n    border-top: 1px solid #e0e0e0;\r\n}\r\n\r\n#mtti-chat-input {\r\n    flex: 1;\r\n    border: 1px solid #e0e0e0;\r\n    border-radius: 20px;\r\n    padding: 10px 15px;\r\n    font-size: 14px;\r\n    outline: none;\r\n}\r\n\r\n#mtti-chat-input:focus {\r\n    border-color: #00d4ff;\r\n}\r\n\r\n#mtti-chat-send {\r\n    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);\r\n    border: none;\r\n    color: #00d4ff;\r\n    width: 40px;\r\n    height: 40px;\r\n    border-radius: 50%;\r\n    margin-left: 8px;\r\n    cursor: pointer;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n}\r\n\r\n#mtti-chat-send:hover {\r\n    opacity: 0.9;\r\n}\r\n\r\n.mtti-typing {\r\n    display: flex;\r\n    gap: 4px;\r\n    padding: 10px 14px;\r\n}\r\n\r\n.mtti-typing span {\r\n    width: 8px;\r\n    height: 8px;\r\n    background: #8892b0;\r\n    border-radius: 50%;\r\n    animation: typing 1s infinite;\r\n}\r\n\r\n.mtti-typing span:nth-child(2) { animation-delay: 0.2s; }\r\n.mtti-typing span:nth-child(3) { animation-delay: 0.4s; }\r\n\r\n@keyframes typing {\r\n    0%, 100% { opacity: 0.3; transform: scale(0.8); }\r\n    50% { opacity: 1; transform: scale(1); }\r\n}\r\n\r\n/* Mobile responsive */\r\n@media (max-width: 480px) {\r\n    #mtti-chat-box {\r\n        width: 100%;\r\n        height: 100%;\r\n        bottom: 0;\r\n        right: 0;\r\n        border-radius: 0;\r\n    }\r\n    \r\n    #mtti-chat-widget {\r\n        bottom: 10px;\r\n        right: 10px;\r\n    }\r\n}\r\n</style>\r\n\r\n<div id="mtti-chat-widget">\r\n    <!-- Chat Button -->\r\n    <button id="mtti-chat-button" class="has-notification" onclick="toggleMTTIChat()">\r\n        <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">\r\n            <path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm0 14H6l-2 2V4h16v12z"/>\r\n        </svg>\r\n    </button>\r\n    \r\n    <!-- Chat Box -->\r\n    <div id="mtti-chat-box">\r\n        <div id="mtti-chat-header">\r\n            <div style="width:40px;height:40px;border-radius:50%;background:#00d4ff;display:flex;align-items:center;justify-content:center;font-size:20px;">🎓</div>\r\n            <div id="mtti-chat-header-info">\r\n                <h4>MTTI Admissions</h4>\r\n                <p>🟢 Online | Typically replies instantly</p>\r\n            </div>\r\n            <button id="mtti-chat-close" onclick="toggleMTTIChat()">×</button>\r\n        </div>\r\n        \r\n        <div id="mtti-chat-messages"></div>\r\n        \r\n        <div id="mtti-chat-options"></div>\r\n        \r\n        <div id="mtti-chat-input-area">\r\n            <input type="text" id="mtti-chat-input" placeholder="Type your message..." onkeypress="handleMTTIKeyPress(event)">\r\n            <button id="mtti-chat-send" onclick="sendMTTIMessage()">\r\n                <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">\r\n                    <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/>\r\n                </svg>\r\n            </button>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n// MTTI Chatbot Configuration\r\nconst MTTI_CONFIG = {\r\n    courses: [\r\n        { name: ''Computer Applications'', duration: ''1 month'', fee: ''KES 4,500'' },\r\n        { name: ''Web Development'', duration: ''2 months'', fee: ''KES 12,000'' },\r\n        { name: ''Graphic Design'', duration: ''2 months'', fee: ''KES 15,000'' },\r\n        { name: ''Digital Marketing'', duration: ''2 months'', fee: ''KES 10,000'' },\r\n        { name: ''Cybersecurity'', duration: ''2 months'', fee: ''KES 15,000'' },\r\n        { name: ''Computer  Repair'', duration: ''2 month'', fee: ''KES 8,000'' },\r\n        { name: ''CCTV Installation'', duration: ''2 month'', fee: ''KES 18,000'' }\r\n		{ name: ''CCTV Video Editing'', duration: ''2 month'', fee: ''KES 15,000'' }\r\n		{ name: ''Graphic Design'', duration: ''2 month'', fee: ''KES 12,000'' }\r\n		{ name: ''Computer Essentails'', duration: ''2 weeks'', fee: ''KES 1,500'' }\r\n		{ name: ''German langauage'', duration: ''2 month Per Module'', fee: ''KES 24,000'' }\r\n		{ name: ''Nursing Assistant'', duration: ''6 month'', fee: ''KES 60,000'' }\r\n		{ name: ''Care Giver'', duration: ''3 month'', fee: ''KES 30,000'' }\r\n    ],\r\n    contact: {\r\n        phone: ''0712464936'',\r\n        email: ''info@masomoteletraining.co.ke'',\r\n        location: ''Sagaas Center, 4th Floor, Eldoret'',\r\n        website: ''masomoteletraining.co.ke''\r\n    },\r\n    whatsapp: ''https://wa.me/254712464936''\r\n};\r\n\r\nlet chatState = ''welcome'';\r\nlet userData = { name: '''', phone: '''', email: '''', course: '''' };\r\n\r\n// Initialize chat\r\nfunction initMTTIChat() {\r\n    setTimeout(() => {\r\n        addBotMessage("👋 Hello! Welcome to Masomotele Technical Training Institute!");\r\n        setTimeout(() => {\r\n            addBotMessage("I''m here to help you find the perfect course and get you enrolled. What would you like to know?");\r\n            showOptions([\r\n                { text: ''📚 View Courses'', action: ''courses'' },\r\n                { text: ''💰 Fees & Duration'', action: ''fees'' },\r\n                { text: ''📍 Location'', action: ''location'' },\r\n                { text: ''✍️ Apply Now'', action: ''apply'' }\r\n            ]);\r\n        }, 1000);\r\n    }, 500);\r\n}\r\n\r\n// Toggle chat open/close\r\nfunction toggleMTTIChat() {\r\n    const chatBox = document.getElementById(''mtti-chat-box'');\r\n    const chatButton = document.getElementById(''mtti-chat-button'');\r\n    \r\n    if (chatBox.classList.contains(''open'')) {\r\n        chatBox.classList.remove(''open'');\r\n    } else {\r\n        chatBox.classList.add(''open'');\r\n        chatButton.classList.remove(''has-notification'');\r\n        \r\n        // Initialize chat if first time\r\n        if (document.getElementById(''mtti-chat-messages'').children.length === 0) {\r\n            initMTTIChat();\r\n        }\r\n    }\r\n}\r\n\r\n// Add bot message\r\nfunction addBotMessage(text) {\r\n    const messagesDiv = document.getElementById(''mtti-chat-messages'');\r\n    const messageDiv = document.createElement(''div'');\r\n    messageDiv.className = ''mtti-message bot'';\r\n    messageDiv.innerHTML = `<div class="mtti-message-bubble">${text}</div>`;\r\n    messagesDiv.appendChild(messageDiv);\r\n    messagesDiv.scrollTop = messagesDiv.scrollHeight;\r\n}\r\n\r\n// Add user message\r\nfunction addUserMessage(text) {\r\n    const messagesDiv = document.getElementById(''mtti-chat-messages'');\r\n    const messageDiv = document.createElement(''div'');\r\n    messageDiv.className = ''mtti-message user'';\r\n    messageDiv.innerHTML = `<div class="mtti-message-bubble">${text}</div>`;\r\n    messagesDiv.appendChild(messageDiv);\r\n    messagesDiv.scrollTop = messagesDiv.scrollHeight;\r\n}\r\n\r\n// Show typing indicator\r\nfunction showTyping() {\r\n    const messagesDiv = document.getElementById(''mtti-chat-messages'');\r\n    const typingDiv = document.createElement(''div'');\r\n    typingDiv.className = ''mtti-message bot'';\r\n    typingDiv.id = ''mtti-typing'';\r\n    typingDiv.innerHTML = `<div class="mtti-message-bubble mtti-typing"><span></span><span></span><span></span></div>`;\r\n    messagesDiv.appendChild(typingDiv);\r\n    messagesDiv.scrollTop = messagesDiv.scrollHeight;\r\n}\r\n\r\n// Hide typing indicator\r\nfunction hideTyping() {\r\n    const typing = document.getElementById(''mtti-typing'');\r\n    if (typing) typing.remove();\r\n}\r\n\r\n// Show option buttons\r\nfunction showOptions(options) {\r\n    const optionsDiv = document.getElementById(''mtti-chat-options'');\r\n    optionsDiv.innerHTML = '''';\r\n    options.forEach(opt => {\r\n        const btn = document.createElement(''button'');\r\n        btn.className = ''mtti-option-btn'';\r\n        btn.textContent = opt.text;\r\n        btn.onclick = () => handleOption(opt.action, opt.text);\r\n        optionsDiv.appendChild(btn);\r\n    });\r\n}\r\n\r\n// Clear options\r\nfunction clearOptions() {\r\n    document.getElementById(''mtti-chat-options'').innerHTML = '''';\r\n}\r\n\r\n// Handle option click\r\nfunction handleOption(action, text) {\r\n    addUserMessage(text);\r\n    clearOptions();\r\n    showTyping();\r\n    \r\n    setTimeout(() => {\r\n        hideTyping();\r\n        \r\n        switch(action) {\r\n            case ''courses'':\r\n                showCourses();\r\n                break;\r\n            case ''fees'':\r\n                showFees();\r\n                break;\r\n            case ''location'':\r\n                showLocation();\r\n                break;\r\n            case ''apply'':\r\n                startApplication();\r\n                break;\r\n            case ''course_select'':\r\n                userData.course = text;\r\n                askName();\r\n                break;\r\n            case ''confirm_yes'':\r\n                submitApplication();\r\n                break;\r\n            case ''confirm_no'':\r\n                startApplication();\r\n                break;\r\n            case ''more_info'':\r\n                showMoreOptions();\r\n                break;\r\n            default:\r\n                handleCourseSelect(action);\r\n        }\r\n    }, 800);\r\n}\r\n\r\n// Show courses\r\nfunction showCourses() {\r\n    let courseList = "📚 <strong>Our Courses:</strong><br><br>";\r\n    MTTI_CONFIG.courses.forEach((c, i) => {\r\n        courseList += `${i+1}. <strong>${c.name}</strong><br>   ⏱️ ${c.duration} | 💰 ${c.fee}<br><br>`;\r\n    });\r\n    addBotMessage(courseList);\r\n    \r\n    setTimeout(() => {\r\n        addBotMessage("Which course interests you? 👇");\r\n        showOptions([\r\n            ...MTTI_CONFIG.courses.slice(0, 4).map(c => ({ text: c.name, action: ''course_select'' })),\r\n            { text: ''📋 More Courses'', action: ''more_courses'' }\r\n        ]);\r\n    }, 500);\r\n}\r\n\r\n// Show fees\r\nfunction showFees() {\r\n    let feeList = "💰 <strong>Course Fees & Duration:</strong><br><br>";\r\n    MTTI_CONFIG.courses.forEach(c => {\r\n        feeList += `• <strong>${c.name}</strong>: ${c.fee} (${c.duration})<br>`;\r\n    });\r\n    feeList += "<br>✅ Flexible payment plans available!";\r\n    addBotMessage(feeList);\r\n    showOptions([\r\n        { text: ''✍️ Apply Now'', action: ''apply'' },\r\n        { text: ''📍 Location'', action: ''location'' },\r\n        { text: ''💬 Talk to Admissions'', action: ''contact'' }\r\n    ]);\r\n}\r\n\r\n// Show location\r\nfunction showLocation() {\r\n    addBotMessage(`📍 <strong>Our Location:</strong><br><br>\r\n        🏢 ${MTTI_CONFIG.contact.location}<br><br>\r\n        📞 Phone: <a href="tel:${MTTI_CONFIG.contact.phone}">${MTTI_CONFIG.contact.phone}</a><br>\r\n        ✉️ Email: ${MTTI_CONFIG.contact.email}<br>\r\n        🌐 Website: ${MTTI_CONFIG.contact.website}<br><br>\r\n        <a href="${MTTI_CONFIG.whatsapp}" target="_blank" style="color:#25d366;font-weight:bold;">💬 WhatsApp Us Now!</a>`);\r\n    showOptions([\r\n        { text: ''✍️ Apply Now'', action: ''apply'' },\r\n        { text: ''📚 View Courses'', action: ''courses'' }\r\n    ]);\r\n}\r\n\r\n// Start application process\r\nfunction startApplication() {\r\n    chatState = ''select_course'';\r\n    addBotMessage("Great! Let''s get you enrolled! 🎉<br><br>First, which course would you like to apply for?");\r\n    showOptions(MTTI_CONFIG.courses.map(c => ({ text: c.name, action: ''course_select'' })));\r\n}\r\n\r\n// Ask for name\r\nfunction askName() {\r\n    chatState = ''ask_name'';\r\n    addBotMessage(`Excellent choice! <strong>${userData.course}</strong> is very popular! 👍<br><br>What''s your full name?`);\r\n    clearOptions();\r\n}\r\n\r\n// Ask for phone\r\nfunction askPhone() {\r\n    chatState = ''ask_phone'';\r\n    addBotMessage(`Nice to meet you, <strong>${userData.name}</strong>! 😊<br><br>What''s your phone number? (We''ll WhatsApp you the enrollment details)`);\r\n}\r\n\r\n// Ask for email\r\nfunction askEmail() {\r\n    chatState = ''ask_email'';\r\n    addBotMessage("Almost done! What''s your email address? (Optional - type ''skip'' to skip)");\r\n}\r\n\r\n// Confirm application\r\nfunction confirmApplication() {\r\n    chatState = ''confirm'';\r\n    addBotMessage(`📋 <strong>Please confirm your details:</strong><br><br>\r\n        👤 Name: ${userData.name}<br>\r\n        📞 Phone: ${userData.phone}<br>\r\n        ✉️ Email: ${userData.email || ''Not provided''}<br>\r\n        📚 Course: ${userData.course}<br><br>\r\n        Is this correct?`);\r\n    showOptions([\r\n        { text: ''✅ Yes, Submit'', action: ''confirm_yes'' },\r\n        { text: ''❌ No, Start Over'', action: ''confirm_no'' }\r\n    ]);\r\n}\r\n\r\n// Submit application\r\nfunction submitApplication() {\r\n    addBotMessage("🎉 <strong>Application Submitted Successfully!</strong><br><br>Thank you for choosing MTTI!<br><br>Our admissions team will contact you within 24 hours via WhatsApp or phone call.<br><br>📞 Or call us now: <a href=''tel:0712464936''>0712 464 936</a>");\r\n    \r\n    // Send to Google Sheets via webhook (you''ll need to set this up)\r\n    sendToWebhook(userData);\r\n    \r\n    setTimeout(() => {\r\n        addBotMessage(`💬 Want faster response? <a href="${MTTI_CONFIG.whatsapp}?text=Hi! I just applied for ${userData.course}. My name is ${userData.name}." target="_blank" style="color:#25d366;font-weight:bold;">WhatsApp us now!</a>`);\r\n        showOptions([\r\n            { text: ''📚 View More Courses'', action: ''courses'' },\r\n            { text: ''📍 Get Directions'', action: ''location'' }\r\n        ]);\r\n    }, 1000);\r\n    \r\n    chatState = ''complete'';\r\n}\r\n\r\n// Send to webhook (Google Sheets/Make.com)\r\nfunction sendToWebhook(data) {\r\n    // Replace with your Make.com webhook URL\r\n    const webhookURL = ''YOUR_MAKE_WEBHOOK_URL_HERE'';\r\n    \r\n    if (webhookURL !== ''YOUR_MAKE_WEBHOOK_URL_HERE'') {\r\n        fetch(webhookURL, {\r\n            method: ''POST'',\r\n            headers: { ''Content-Type'': ''application/json'' },\r\n            body: JSON.stringify({\r\n                name: data.name,\r\n                phone: data.phone,\r\n                email: data.email,\r\n                course: data.course,\r\n                source: ''Website Chatbot'',\r\n                timestamp: new Date().toISOString()\r\n            })\r\n        }).catch(err => console.log(''Webhook error:'', err));\r\n    }\r\n    \r\n    // Also log to console for testing\r\n    console.log(''MTTI Lead:'', data);\r\n}\r\n\r\n// Handle text input\r\nfunction sendMTTIMessage() {\r\n    const input = document.getElementById(''mtti-chat-input'');\r\n    const message = input.value.trim();\r\n    \r\n    if (!message) return;\r\n    \r\n    addUserMessage(message);\r\n    input.value = '''';\r\n    showTyping();\r\n    \r\n    setTimeout(() => {\r\n        hideTyping();\r\n        processMessage(message);\r\n    }, 800);\r\n}\r\n\r\n// Process user message based on state\r\nfunction processMessage(message) {\r\n    switch(chatState) {\r\n        case ''ask_name'':\r\n            userData.name = message;\r\n            askPhone();\r\n            break;\r\n        case ''ask_phone'':\r\n            if (validatePhone(message)) {\r\n                userData.phone = message;\r\n                askEmail();\r\n            } else {\r\n                addBotMessage("Please enter a valid Kenyan phone number (e.g., 0712345678)");\r\n            }\r\n            break;\r\n        case ''ask_email'':\r\n            if (message.toLowerCase() === ''skip'') {\r\n                userData.email = '''';\r\n            } else {\r\n                userData.email = message;\r\n            }\r\n            confirmApplication();\r\n            break;\r\n        default:\r\n            handleGeneralMessage(message);\r\n    }\r\n}\r\n\r\n// Handle general messages\r\nfunction handleGeneralMessage(message) {\r\n    const lowerMsg = message.toLowerCase();\r\n    \r\n    if (lowerMsg.includes(''course'') || lowerMsg.includes(''learn'') || lowerMsg.includes(''study'')) {\r\n        showCourses();\r\n    } else if (lowerMsg.includes(''fee'') || lowerMsg.includes(''cost'') || lowerMsg.includes(''price'') || lowerMsg.includes(''pay'')) {\r\n        showFees();\r\n    } else if (lowerMsg.includes(''where'') || lowerMsg.includes(''location'') || lowerMsg.includes(''address'') || lowerMsg.includes(''direction'')) {\r\n        showLocation();\r\n    } else if (lowerMsg.includes(''apply'') || lowerMsg.includes(''enroll'') || lowerMsg.includes(''register'') || lowerMsg.includes(''join'')) {\r\n        startApplication();\r\n    } else if (lowerMsg.includes(''hello'') || lowerMsg.includes(''hi'') || lowerMsg.includes(''hey'')) {\r\n        addBotMessage("Hello! 👋 How can I help you today?");\r\n        showOptions([\r\n            { text: ''📚 View Courses'', action: ''courses'' },\r\n            { text: ''💰 Fees & Duration'', action: ''fees'' },\r\n            { text: ''✍️ Apply Now'', action: ''apply'' }\r\n        ]);\r\n    } else if (lowerMsg.includes(''web'')) {\r\n        showCourseDetail(''Web Development'');\r\n    } else if (lowerMsg.includes(''graphic'') || lowerMsg.includes(''design'')) {\r\n        showCourseDetail(''Graphic Design'');\r\n    } else if (lowerMsg.includes(''computer'')) {\r\n        showCourseDetail(''Computer Applications'');\r\n    } else if (lowerMsg.includes(''cyber'') || lowerMsg.includes(''security'')) {\r\n        showCourseDetail(''Cybersecurity'');\r\n    } else if (lowerMsg.includes(''cctv'')) {\r\n        showCourseDetail(''CCTV Installation'');\r\n    } else if (lowerMsg.includes(''phone'') || lowerMsg.includes(''mobile'') || lowerMsg.includes(''repair'')) {\r\n        showCourseDetail(''Mobile Phone Repair'');\r\n    } else if (lowerMsg.includes(''marketing'') || lowerMsg.includes(''digital'')) {\r\n        showCourseDetail(''Digital Marketing'');\r\n    } else {\r\n        addBotMessage("I''d be happy to help! Here are some things I can assist with:");\r\n        showOptions([\r\n            { text: ''📚 View Courses'', action: ''courses'' },\r\n            { text: ''💰 Fees & Duration'', action: ''fees'' },\r\n            { text: ''📍 Location'', action: ''location'' },\r\n            { text: ''✍️ Apply Now'', action: ''apply'' }\r\n        ]);\r\n    }\r\n}\r\n\r\n// Show specific course detail\r\nfunction showCourseDetail(courseName) {\r\n    const course = MTTI_CONFIG.courses.find(c => c.name === courseName);\r\n    if (course) {\r\n        addBotMessage(`📚 <strong>${course.name}</strong><br><br>\r\n            ⏱️ Duration: ${course.duration}<br>\r\n            💰 Fee: ${course.fee}<br><br>\r\n            ✅ Practical hands-on training<br>\r\n            ✅ Industry-ready skills<br>\r\n            ✅ Job placement assistance<br><br>\r\n            Would you like to apply?`);\r\n        userData.course = courseName;\r\n        showOptions([\r\n            { text: ''✍️ Apply Now'', action: ''apply'' },\r\n            { text: ''📚 Other Courses'', action: ''courses'' },\r\n            { text: ''💬 Talk to Admissions'', action: ''contact'' }\r\n        ]);\r\n    }\r\n}\r\n\r\n// Validate phone number\r\nfunction validatePhone(phone) {\r\n    const cleaned = phone.replace(/\\D/g, '''');\r\n    return cleaned.length >= 9 && cleaned.length <= 12;\r\n}\r\n\r\n// Handle enter key\r\nfunction handleMTTIKeyPress(event) {\r\n    if (event.key === ''Enter'') {\r\n        sendMTTIMessage();\r\n    }\r\n}\r\n\r\n// Show more options\r\nfunction showMoreOptions() {\r\n    showOptions([\r\n        { text: ''📚 View Courses'', action: ''courses'' },\r\n        { text: ''💰 Fees & Duration'', action: ''fees'' },\r\n        { text: ''📍 Location'', action: ''location'' },\r\n        { text: ''✍️ Apply Now'', action: ''apply'' }\r\n    ]);\r\n}\r\n\r\n// Auto-open chat after 5 seconds (optional)\r\nsetTimeout(() => {\r\n    const chatBox = document.getElementById(''mtti-chat-box'');\r\n    if (!chatBox.classList.contains(''open'')) {\r\n        // Uncomment below to auto-open\r\n        // toggleMTTIChat();\r\n    }\r\n}, 5000);\r\n</script>\r\n', 'MTTI Chatbot', '', 'trash', 'closed', 'closed', '', 'untitled-snippet__trashed', '', '', '2026-02-01 15:14:04', '2026-02-01 15:14:04', '', 0, 'https://masomoteletraining.co.ke/?post_type=wpcode&#038;p=1922', 0, 'wpcode', '', 0),
