(1943, 1, '2026-02-02 14:00:52', '2026-02-02 14:00:52', '<!DOCTYPE html>\r\n<html lang="en">\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\r\n    <title>Learn Graphic Design in 8 Weeks | M.T.T.I Eldoret - TVETA Accredited</title>\r\n    <meta name="description" content="Corel Draw, Canva & brand design in just 8 weeks. TVETA certified, hands-on training. Start earning KES 50,000+/month as a designer. Enroll now!">\r\n    \r\n    <!-- Open Graph for Social Sharing -->\r\n    <meta property="og:title" content="Learn Graphic Design in 8 Weeks | M.T.T.I Eldoret">\r\n    <meta property="og:description" content="Corel Draw & Canva. Start earning as a freelance designer. TVETA certified. Only KES 12,000.">\r\n    <meta property="og:image" content="https://masomoteletraining.co.ke/wp-content/uploads/2026/02/graphic-design-og.jpg">\r\n    <meta property="og:url" content="https://masomoteletraining.co.ke/graphic-design/">\r\n    <meta property="og:type" content="website">\r\n    \r\n    <!-- Google Analytics with UTM Tracking -->\r\n    <script async src="https://www.googletagmanager.com/gtag/js?id=G-8ZEH42CBVL"></script>\r\n    <script>\r\n      window.dataLayer = window.dataLayer || [];\r\n      function gtag(){dataLayer.push(arguments);}\r\n      gtag(''js'', new Date());\r\n      gtag(''config'', ''G-8ZEH42CBVL'');\r\n      \r\n      // UTM Parameter Tracking\r\n      function getUTMParams() {\r\n        var params = new URLSearchParams(window.location.search);\r\n        return {\r\n          utm_source: params.get(''utm_source'') || ''direct'',\r\n          utm_medium: params.get(''utm_medium'') || ''none'',\r\n          utm_campaign: params.get(''utm_campaign'') || ''none'',\r\n          utm_content: params.get(''utm_content'') || ''none'',\r\n          utm_term: params.get(''utm_term'') || ''none'',\r\n          landing_page: ''graphic-design''\r\n        };\r\n      }\r\n      \r\n      var utmData = getUTMParams();\r\n      sessionStorage.setItem(''mtti_utm'', JSON.stringify(utmData));\r\n      console.log(''📊 Landing Page UTM:'', utmData);\r\n      \r\n      function trackEvent(category, action, label) {\r\n        gtag(''event'', action, {\r\n          ''event_category'': category,\r\n          ''event_label'': label,\r\n          ''utm_source'': utmData.utm_source,\r\n          ''utm_campaign'': utmData.utm_campaign\r\n        });\r\n      }\r\n    </script>\r\n    \r\n    <!-- Meta Pixel (Facebook & Instagram) -->\r\n    <script>\r\n      !function(f,b,e,v,n,t,s)\r\n      {if(f.fbq)return;n=f.fbq=function(){n.callMethod?\r\n      n.callMethod.apply(n,arguments):n.queue.push(arguments)};\r\n      if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version=''2.0'';\r\n      n.queue=[];t=b.createElement(e);t.async=!0;\r\n      t.src=v;s=b.getElementsByTagName(e)[0];\r\n      s.parentNode.insertBefore(t,s)}(window, document,''script'',\r\n      ''https://connect.facebook.net/en_US/fbevents.js'');\r\n      fbq(''init'', ''893318556963600'');\r\n      fbq(''track'', ''PageView'');\r\n      fbq(''track'', ''ViewContent'', {\r\n        content_name: ''Graphic Design Course'',\r\n        content_category: ''landing_page'',\r\n        value: 12000,\r\n        currency: ''KES''\r\n      });\r\n    </script>\r\n    \r\n    <link rel="preconnect" href="https://fonts.googleapis.com">\r\n    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">\r\n    \r\n    <style>\r\n        :root {\r\n            --primary-green: #2E7D32;\r\n            --dark-green: #1B5E20;\r\n            --light-green: #4CAF50;\r\n            --accent-orange: #FF9800;\r\n            --dark-orange: #F57C00;\r\n            --creative-purple: #7B1FA2;\r\n            --creative-pink: #E91E63;\r\n            --white: #ffffff;\r\n            --off-white: #f8f9fa;\r\n            --dark: #1a1a2e;\r\n            --gray: #666;\r\n        }\r\n        \r\n        * { margin: 0; padding: 0; box-sizing: border-box; }\r\n        \r\n        body {\r\n            font-family: ''Poppins'', sans-serif;\r\n            line-height: 1.7;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        /* ===== MINIMAL HEADER ===== */\r\n        .lp-header {\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n            padding: 15px 30px;\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n        }\r\n        \r\n        .lp-logo {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            text-decoration: none;\r\n        }\r\n        \r\n        .lp-logo-icon {\r\n            width: 45px;\r\n            height: 45px;\r\n            background: var(--accent-orange);\r\n            border-radius: 10px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            font-weight: 800;\r\n            font-size: 1rem;\r\n            color: white;\r\n        }\r\n        \r\n        .lp-logo-text {\r\n            color: white;\r\n            font-size: 1.2rem;\r\n            font-weight: 700;\r\n        }\r\n        \r\n        .lp-phone {\r\n            color: white;\r\n            text-decoration: none;\r\n            font-weight: 600;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n        }\r\n        \r\n        /* ===== HERO SECTION ===== */\r\n        .lp-hero {\r\n            background: linear-gradient(135deg, var(--creative-purple) 0%, var(--creative-pink) 50%, var(--dark-orange) 100%);\r\n            padding: 60px 30px 80px;\r\n            text-align: center;\r\n            color: white;\r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        .lp-hero::before {\r\n            content: '''';\r\n  