(1946, 1, '2026-02-02 14:02:45', '2026-02-02 14:02:45', '<!DOCTYPE html>\r\n<html lang="en">\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\r\n    <title>Learn Graphic Design in 8 Weeks | M.T.T.I Eldoret - TVETA Accredited</title>\r\n    <meta name="description" content="Corel Draw, Canva & brand design in just 8 weeks. TVETA certified, hands-on training. Start earning KES 50,000+/month as a designer. Enroll now!">\r\n    \r\n    <!-- Open Graph for Social Sharing -->\r\n    <meta property="og:title" content="Learn Graphic Design in 8 Weeks | M.T.T.I Eldoret">\r\n    <meta property="og:description" content="Corel Draw & Canva. Start earning as a freelance designer. TVETA certified. Only KES 12,000.">\r\n    <meta property="og:image" content="https://masomoteletraining.co.ke/wp-content/uploads/2026/02/graphic-design-og.jpg">\r\n    <meta property="og:url" content="https://masomoteletraining.co.ke/graphic-design/">\r\n    <meta property="og:type" content="website">\r\n    \r\n    <!-- Google Analytics with UTM Tracking -->\r\n    <script async src="https://www.googletagmanager.com/gtag/js?id=G-8ZEH42CBVL"></script>\r\n    <script>\r\n      window.dataLayer = window.dataLayer || [];\r\n      function gtag(){dataLayer.push(arguments);}\r\n      gtag(''js'', new Date());\r\n      gtag(''config'', ''G-8ZEH42CBVL'');\r\n      \r\n      // UTM Parameter Tracking\r\n      function getUTMParams() {\r\n        var params = new URLSearchParams(window.location.search);\r\n        return {\r\n          utm_source: params.get(''utm_source'') || ''direct'',\r\n          utm_medium: params.get(''utm_medium'') || ''none'',\r\n          utm_campaign: params.get(''utm_campaign'') || ''none'',\r\n          utm_content: params.get(''utm_content'') || ''none'',\r\n          utm_term: params.get(''utm_term'') || ''none'',\r\n          landing_page: ''graphic-design''\r\n        };\r\n      }\r\n      \r\n      var utmData = getUTMParams();\r\n      sessionStorage.setItem(''mtti_utm'', JSON.stringify(utmData));\r\n      console.log(''📊 Landing Page UTM:'', utmData);\r\n      \r\n      function trackEvent(category, action, label) {\r\n        gtag(''event'', action, {\r\n          ''event_category'': category,\r\n          ''event_label'': label,\r\n          ''utm_source'': utmData.utm_source,\r\n          ''utm_campaign'': utmData.utm_campaign\r\n        });\r\n      }\r\n    </script>\r\n    \r\n    <!-- Meta Pixel (Facebook & Instagram) -->\r\n    <script>\r\n      !function(f,b,e,v,n,t,s)\r\n      {if(f.fbq)return;n=f.fbq=function(){n.callMethod?\r\n      n.callMethod.apply(n,arguments):n.queue.push(arguments)};\r\n      if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version=''2.0'';\r\n      n.queue=[];t=b.createElement(e);t.async=!0;\r\n      t.src=v;s=b.getElementsByTagName(e)[0];\r\n      s.parentNode.insertBefore(t,s)}(window, document,''script'',\r\n      ''https://connect.facebook.net/en_US/fbevents.js'');\r\n      fbq(''init'', ''893318556963600'');\r\n      fbq(''track'', ''PageView'');\r\n      fbq(''track'', ''ViewContent'', {\r\n        content_name: ''Graphic Design Course'',\r\n        content_category: ''landing_page'',\r\n        value: 12000,\r\n        currency: ''KES''\r\n      });\r\n    </script>\r\n    \r\n    <link rel="preconnect" href="https://fonts.googleapis.com">\r\n    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">\r\n    \r\n    <style>\r\n        :root {\r\n            --primary-green: #2E7D32;\r\n            --dark-green: #1B5E20;\r\n            --light-green: #4CAF50;\r\n            --accent-orange: #FF9800;\r\n            --dark-orange: #F57C00;\r\n            --creative-purple: #7B1FA2;\r\n            --creative-pink: #E91E63;\r\n            --white: #ffffff;\r\n            --off-white: #f8f9fa;\r\n            --dark: #1a1a2e;\r\n            --gray: #666;\r\n        }\r\n        \r\n        * { margin: 0; padding: 0; box-sizing: border-box; }\r\n        \r\n        body {\r\n            font-family: ''Poppins'', sans-serif;\r\n            line-height: 1.7;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        /* ===== MINIMAL HEADER ===== */\r\n        .lp-header {\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n            padding: 15px 30px;\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n        }\r\n        \r\n        .lp-logo {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            text-decoration: none;\r\n        }\r\n        \r\n        .lp-logo-icon {\r\n            width: 45px;\r\n            height: 45px;\r\n            background: var(--accent-orange);\r\n            border-radius: 10px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            font-weight: 800;\r\n            font-size: 1rem;\r\n            color: white;\r\n        }\r\n        \r\n        .lp-logo-text {\r\n            color: white;\r\n            font-size: 1.2rem;\r\n            font-weight: 700;\r\n        }\r\n        \r\n        .lp-phone {\r\n            color: white;\r\n            text-decoration: none;\r\n            font-weight: 600;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n        }\r\n        \r\n        /* ===== HERO SECTION ===== */\r\n        .lp-hero {\r\n            background: linear-gradient(135deg, var(--creative-purple) 0%, var(--creative-pink) 50%, var(--dark-orange) 100%);\r\n            padding: 60px 30px 80px;\r\n            text-align: center;\r\n            color: white;\r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        .lp-hero::before {\r\n            content: '''';\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            right: 0;\r\n            bottom: 0;\r\n            background: url("data:image/svg+xml,%3Csvg width=''60'' height=''60'' viewBox=''0 0 60 60'' xmlns=''http://www.w3.org/2000/svg''%3E%3Cg fill=''none'' fill-rule=''evenodd''%3E%3Cg fill=''%23ffffff'' fill-opacity=''0.05''%3E%3Cpath d=''M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z''/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");\r\n        }\r\n        \r\n        .lp-hero-content {\r\n            position: relative;\r\n            z-index: 1;\r\n            max-width: 800px;\r\n            margin: 0 auto;\r\n        }\r\n        \r\n        .lp-badge {\r\n            display: inline-block;\r\n            background: var(--accent-orange);\r\n            padding: 8px 20px;\r\n            border-radius: 50px;\r\n            font-size: 0.9rem;\r\n            font-weight: 600;\r\n            margin-bottom: 25px;\r\n        }\r\n        \r\n        .lp-hero h1 {\r\n            font-size: 2.8rem;\r\n            font-weight: 800;\r\n            margin-bottom: 20px;\r\n            line-height: 1.2;\r\n        }\r\n        \r\n        .lp-hero h1 span {\r\n            color: var(--accent-orange);\r\n        }\r\n        \r\n        .lp-hero p {\r\n            font-size: 1.2rem;\r\n            opacity: 0.95;\r\n            margin-bottom: 30px;\r\n            max-width: 600px;\r\n            margin-left: auto;\r\n            margin-right: auto;\r\n        }\r\n        \r\n        .lp-highlights {\r\n            display: flex;\r\n            justify-content: center;\r\n            gap: 30px;\r\n            flex-wrap: wrap;\r\n            margin-top: 30px;\r\n        }\r\n        \r\n        .lp-highlight {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            background: rgba(255,255,255,0.15);\r\n            padding: 12px 20px;\r\n            border-radius: 50px;\r\n        }\r\n        \r\n        .lp-highlight-icon {\r\n            font-size: 1.3rem;\r\n        }\r\n        \r\n        /* ===== SOCIAL PROOF BAR ===== */\r\n        .lp-social-proof {\r\n            background: white;\r\n            padding: 20px 30px;\r\n            display: flex;\r\n            justify-content: center;\r\n            gap: 40px;\r\n            flex-wrap: wrap;\r\n            box-shadow: 0 4px 20px rgba(0,0,0,0.1);\r\n        }\r\n        \r\n        .lp-proof-item {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            font-size: 0.95rem;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        .lp-proof-item strong {\r\n            color: var(--creative-purple);\r\n        }\r\n        \r\n        /* ===== VIDEO SECTION ===== */\r\n        .lp-video-section {\r\n            padding: 60px 30px;\r\n            background: linear-gradient(135deg, #fce4ec, #f3e5f5);\r\n        }\r\n        \r\n        .lp-video-container {\r\n            max-width: 800px;\r\n            margin: 0 auto;\r\n        }\r\n        \r\n        .lp-video-header {\r\n            text-align: center;\r\n            margin-bottom: 30px;\r\n        }\r\n        \r\n        .lp-video-header h2 {\r\n            font-size: 1.8rem;\r\n            color: var(--dark);\r\n            margin-bottom: 10px;\r\n        }\r\n        \r\n        .lp-video-header h2 span {\r\n            color: var(--creative-purple);\r\n        }\r\n        \r\n        .lp-video-wrapper {\r\n            position: relative;\r\n            border-radius: 20px;\r\n            overflow: hidden;\r\n            box-shadow: 0 20px 60px rgba(123, 31, 162, 0.3);\r\n        }\r\n        \r\n        .lp-video {\r\n            width: 100%;\r\n            display: block;\r\n        }\r\n        \r\n        .lp-video-overlay {\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            right: 0;\r\n            bottom: 0;\r\n            background: linear-gradient(135deg, rgba(123, 31, 162, 0.6), rgba(233, 30, 99, 0.6));\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: center;\r\n            justify-content: center;\r\n            cursor: pointer;\r\n            transition: background 0.3s;\r\n            gap: 15px;\r\n        }\r\n        \r\n        .lp-video-overlay:hover {\r\n            background: linear-gradient(135deg, rgba(123, 31, 162, 0.4), rgba(233, 30, 99, 0.4));\r\n        }\r\n        \r\n        .lp-video-overlay.hidden {\r\n            opacity: 0;\r\n            pointer-events: none;\r\n        }\r\n        \r\n        .lp-play-btn {\r\n            width: 80px;\r\n            height: 80px;\r\n            background: var(--accent-orange);\r\n            border-radius: 50%;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            box-shadow: 0 10px 40px rgba(255,152,0,0.5);\r\n            transition: transform 0.3s;\r\n        }\r\n        \r\n        .lp-play-btn:hover {\r\n            transform: scale(1.1);\r\n        }\r\n        \r\n        .lp-play-btn svg {\r\n            width: 30px;\r\n            height: 30px;\r\n            fill: white;\r\n            margin-left: 5px;\r\n        }\r\n        \r\n        .lp-video-label {\r\n            color: white;\r\n            font-weight: 600;\r\n            font-size: 1.1rem;\r\n            text-shadow: 0 2px 10px rgba(0,0,0,0.3);\r\n        }\r\n        \r\n        /* ===== EARNINGS SECTION ===== */\r\n        .lp-earnings {\r\n            padding: 60px 30px;\r\n            background: white;\r\n        }\r\n        \r\n        .lp-earnings-container {\r\n            max-width: 900px;\r\n            margin: 0 auto;\r\n            text-align: center;\r\n        }\r\n        \r\n        .lp-earnings h2 {\r\n            font-size: 2rem;\r\n            margin-bottom: 40px;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        .lp-earnings h2 span {\r\n            color: var(--creative-purple);\r\n        }\r\n        \r\n        .lp-earnings-grid {\r\n            display: grid;\r\n            grid-template-columns: repeat(3, 1fr);\r\n            gap: 25px;\r\n        }\r\n        \r\n        .lp-earning-card {\r\n            background: linear-gradient(135deg, #f3e5f5, #fce4ec);\r\n            padding: 30px 20px;\r\n            border-radius: 20px;\r\n            transition: transform 0.3s;\r\n        }\r\n        \r\n        .lp-earning-card:hover {\r\n            transform: translateY(-5px);\r\n        }\r\n        \r\n        .lp-earning-icon {\r\n            font-size: 2.5rem;\r\n            margin-bottom: 15px;\r\n        }\r\n        \r\n        .lp-earning-title {\r\n            font-weight: 700;\r\n            color: var(--dark);\r\n            margin-bottom: 8px;\r\n        }\r\n        \r\n        .lp-earning-price {\r\n            font-size: 1.4rem;\r\n            font-weight: 800;\r\n            color: var(--creative-purple);\r\n            margin-bottom: 5px;\r\n        }\r\n        \r\n        .lp-earning-note {\r\n            font-size: 0.85rem;\r\n            color: var(--gray);\r\n        }\r\n        \r\n        /* ===== FORM SECTION ===== */\r\n        .lp-form-section {\r\n            padding: 60px 30px;\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n        }\r\n        \r\n        .lp-form-container {\r\n            max-width: 500px;\r\n            margin: 0 auto;\r\n        }\r\n        \r\n        .lp-form-card {\r\n            background: white;\r\n            border-radius: 24px;\r\n            overflow: hidden;\r\n            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);\r\n        }\r\n        \r\n        .lp-form-header {\r\n            background: linear-gradient(135deg, var(--accent-orange), var(--dark-orange));\r\n 