(1951, 1, '2026-02-02 22:28:51', '2026-02-02 22:28:51', '<!DOCTYPE html>\r\n<html lang="en">\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\r\n    <title>Learn Graphic Design in 8 Weeks | M.T.T.I Eldoret - TVETA Accredited</title>\r\n    <meta name="description" content="Corel Draw, Canva & brand design in just 8 weeks. TVETA certified, hands-on training. Start earning KES 50,000+/month as a designer. Enroll now!">\r\n    \r\n    <!-- Open Graph for Social Sharing -->\r\n    <meta property="og:title" content="Learn Graphic Design in 8 Weeks | M.T.T.I Eldoret">\r\n    <meta property="og:description" content="Corel Draw & Canva. Start earning as a freelance designer. TVETA certified. Only KES 12,000.">\r\n    <meta property="og:image" content="https://masomoteletraining.co.ke/wp-content/uploads/2026/02/graphic-design-og.jpg">\r\n    <meta property="og:url" content="https://masomoteletraining.co.ke/graphic-design/">\r\n    <meta property="og:type" content="website">\r\n    \r\n    <!-- Google Analytics with UTM Tracking -->\r\n    <script async src="https://www.googletagmanager.com/gtag/js?id=G-8ZEH42CBVL"></script>\r\n    <script>\r\n      window.dataLayer = window.dataLayer || [];\r\n      function gtag(){dataLayer.push(arguments);}\r\n      gtag(''js'', new Date());\r\n      gtag(''config'', ''G-8ZEH42CBVL'');\r\n      \r\n      // UTM Parameter Tracking\r\n      function getUTMParams() {\r\n        var params = new URLSearchParams(window.location.search);\r\n        return {\r\n          utm_source: params.get(''utm_source'') || ''direct'',\r\n          utm_medium: params.get(''utm_medium'') || ''none'',\r\n          utm_campaign: params.get(''utm_campaign'') || ''none'',\r\n          utm_content: params.get(''utm_content'') || ''none'',\r\n          utm_term: params.get(''utm_term'') || ''none'',\r\n          landing_page: ''graphic-design''\r\n        };\r\n      }\r\n      \r\n      var utmData = getUTMParams();\r\n      sessionStorage.setItem(''mtti_utm'', JSON.stringify(utmData));\r\n      console.log(''📊 Landing Page UTM:'', utmData);\r\n      \r\n      function trackEvent(category, action, label) {\r\n        gtag(''event'', action, {\r\n          ''event_category'': category,\r\n          ''event_label'': label,\r\n          ''utm_source'': utmData.utm_source,\r\n          ''utm_campaign'': utmData.utm_campaign\r\n        });\r\n      }\r\n    </script>\r\n    \r\n    <!-- Meta Pixel (Facebook & Instagram) -->\r\n    <script>\r\n      !function(f,b,e,v,n,t,s)\r\n      {if(f.fbq)return;n=f.fbq=function(){n.callMethod?\r\n      n.callMethod.apply(n,arguments):n.queue.push(arguments)};\r\n      if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version=''2.0'';\r\n      n.queue=[];t=b.createElement(e);t.async=!0;\r\n      t.src=v;s=b.getElementsByTagName(e)[0];\r\n      s.parentNode.insertBefore(t,s)}(window, document,''script'',\r\n      ''https://connect.facebook.net/en_US/fbevents.js'');\r\n      fbq(''init'', ''893318556963600'');\r\n      fbq(''track'', ''PageView'');\r\n      fbq(''track'', ''ViewContent'', {\r\n        content_name: ''Graphic Design Course'',\r\n        content_category: ''landing_page'',\r\n        value: 12000,\r\n        currency: ''KES''\r\n      });\r\n    </script>\r\n    \r\n    <link rel="preconnect" href="https://fonts.googleapis.com">\r\n    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">\r\n    \r\n    <style>\r\n        :root {\r\n            --primary-green: #2E7D32;\r\n            --dark-green: #1B5E20;\r\n            --light-green: #4CAF50;\r\n            --accent-orange: #FF9800;\r\n            --dark-orange: #F57C00;\r\n            --creative-purple: #7B1FA2;\r\n            --creative-pink: #E91E63;\r\n            --white: #ffffff;\r\n            --off-white: #f8f9fa;\r\n            --dark: #1a1a2e;\r\n            --gray: #666;\r\n        }\r\n        \r\n        * { margin: 0; padding: 0; box-sizing: border-box; }\r\n        \r\n        body {\r\n            font-family: ''Poppins'', sans-serif;\r\n            line-height: 1.7;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        /* ===== MINIMAL HEADER ===== */\r\n        .lp-header {\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n            padding: 15px 30px;\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n        }\r\n        \r\n        .lp-logo {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            text-decoration: none;\r\n        }\r\n        \r\n        .lp-logo-icon {\r\n            width: 45px;\r\n            height: 45px;\r\n            background: var(--accent-orange);\r\n            border-radius: 10px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            font-weight: 800;\r\n            font-size: 1rem;\r\n            color: white;\r\n        }\r\n        \r\n        .lp-logo-text {\r\n            color: white;\r\n            font-size: 1.2rem;\r\n            font-weight: 700;\r\n        }\r\n        \r\n        .lp-phone {\r\n            color: white;\r\n            text-decoration: none;\r\n            font-weight: 600;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n        }\r\n        \r\n        /* ===== HERO SECTION ===== */\r\n        .lp-hero {\r\n            background: linear-gradient(135deg, var(--creative-purple) 0%, var(--creative-pink) 50%, var(--dark-orange) 100%);\r\n            padding: 60px 30px 80px;\r\n            text-align: center;\r\n            color: white;\r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        .lp-hero::before {\r\n            content: '''';\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            right: 0;\r\n            bottom: 0;\r\n            background: url("data:image/svg+xml,%3Csvg width=''60'' height=''60'' viewBox=''0 0 60 60'' xmlns=''http://www.w3.org/2000/svg''%3E%3Cg fill=''none'' fill-rule=''evenodd''%3E%3Cg fill=''%23ffffff'' fill-opacity=''0.05''%3E%3Cpath d=''M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z''/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");\r\n        }\r\n        \r\n        .lp-hero-content {\r\n            position: relative;\r\n            z-index: 1;\r\n            max-width: 800px;\r\n            margin: 0 auto;\r\n        }\r\n        \r\n        .lp-badge {\r\n            display: inline-block;\r\n            background: var(--accent-orange);\r\n            padding: 8px 20px;\r\n            border-radius: 50px;\r\n            font-size: 0.9rem;\r\n            font-weight: 600;\r\n            margin-bottom: 25px;\r\n        }\r\n        \r\n        .lp-hero h1 {\r\n            font-size: 2.8rem;\r\n            font-weight: 800;\r\n            margin-bottom: 20px;\r\n            line-height: 1.2;\r\n        }\r\n        \r\n        .lp-hero h1 span {\r\n            color: var(--accent-orange);\r\n        }\r\n        \r\n        .lp-hero p {\r\n            font-size: 1.2rem;\r\n            opacity: 0.95;\r\n            margin-bottom: 30px;\r\n            max-width: 600px;\r\n            margin-left: auto;\r\n            margin-right: auto;\r\n        }\r\n        \r\n        .lp-highlights {\r\n            display: flex;\r\n            justify-content: center;\r\n            gap: 30px;\r\n            flex-wrap: wrap;\r\n            margin-top: 30px;\r\n        }\r\n        \r\n        .lp-highlight {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            background: rgba(255,255,255,0.15);\r\n            padding: 12px 20px;\r\n            border-radius: 50px;\r\n        }\r\n        \r\n        .lp-highlight-icon {\r\n            font-size: 1.3rem;\r\n        }\r\n        \r\n        /* ===== SOCIAL PROOF BAR ===== */\r\n        .lp-social-proof {\r\n            background: white;\r\n            padding: 20px 30px;\r\n            display: flex;\r\n            justify-content: center;\r\n            gap: 40px;\r\n            flex-wrap: wrap;\r\n            box-shadow: 0 4px 20px rgba(0,0,0,0.1);\r\n        }\r\n        \r\n        .lp-proof-item {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            font-size: 0.95rem;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        .lp-proof-item strong {\r\n            color: var(--creative-purple);\r\n        }\r\n        \r\n        /* ===== VIDEO SECTION ===== */\r\n        .lp-video-section {\r\n            padding: 60px 30px;\r\n            background: linear-gradient(135deg, #fce4ec, #f3e5f5);\r\n        }\r\n        \r\n        .lp-video-container {\r\n            max-width: 800px;\r\n            margin: 0 auto;\r\n        }\r\n        \r\n        .lp-video-header {\r\n            text-align: center;\r\n            margin-bottom: 30px;\r\n        }\r\n        \r\n        .lp-video-header h2 {\r\n            font-size: 1.8rem;\r\n            color: var(--dark);\r\n            margin-bottom: 10px;\r\n        }\r\n        \r\n        .lp-video-header h2 span {\r\n            color: var(--creative-purple);\r\n        }\r\n        \r\n        .lp-video-wrapper {\r\n            position: relative;\r\n            border-radius: 20px;\r\n            overflow: hidden;\r\n            box-shadow: 0 20px 60px rgba(123, 31, 162, 0.3);\r\n        }\r\n        \r\n        .lp-video {\r\n            width: 100%;\r\n            display: block;\r\n        }\r\n        \r\n        .lp-video-overlay {\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            right: 0;\r\n            bottom: 0;\r\n            background: linear-gradient(135deg, rgba(123, 31, 162, 0.6), rgba(233, 30, 99, 0.6));\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: center;\r\n            justify-content: center;\r\n            cursor: pointer;\r\n            transition: background 0.3s;\r\n            gap: 15px;\r\n        }\r\n        \r\n        .lp-video-overlay:hover {\r\n            background: linear-gradient(135deg, rgba(123, 31, 162, 0.4), rgba(233, 30, 99, 0.4));\r\n        }\r\n        \r\n        .lp-video-overlay.hidden {\r\n            opacity: 0;\r\n            pointer-events: none;\r\n        }\r\n        \r\n        .lp-play-btn {\r\n            width: 80px;\r\n            height: 80px;\r\n            background: var(--accent-orange);\r\n            border-radius: 50%;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            box-shadow: 0 10px 40px rgba(255,152,0,0.5);\r\n            transition: transform 0.3s;\r\n        }\r\n        \r\n        .lp-play-btn:hover {\r\n            transform: scale(1.1);\r\n        }\r\n        \r\n        .lp-play-btn svg {\r\n            width: 30px;\r\n            height: 30px;\r\n            fill: white;\r\n            margin-left: 5px;\r\n        }\r\n        \r\n        .lp-video-label {\r\n            color: white;\r\n            font-weight: 600;\r\n            font-size: 1.1rem;\r\n            text-shadow: 0 2px 10px rgba(0,0,0,0.3);\r\n        }\r\n        \r\n        /* ===== EARNINGS SECTION ===== */\r\n        .lp-earnings {\r\n            padding: 60px 30px;\r\n            background: white;\r\n        }\r\n        \r\n        .lp-earnings-container {\r\n            max-width: 900px;\r\n            margin: 0 auto;\r\n            text-align: center;\r\n        }\r\n        \r\n        .lp-earnings h2 {\r\n            font-size: 2rem;\r\n            margin-bottom: 40px;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        .lp-earnings h2 span {\r\n            color: var(--creative-purple);\r\n        }\r\n        \r\n        .lp-earnings-grid {\r\n            display: grid;\r\n            grid-template-columns: repeat(3, 1fr);\r\n            gap: 25px;\r\n        }\r\n        \r\n        .lp-earning-card {\r\n            background: linear-gradient(135deg, #f3e5f5, #fce4ec);\r\n            padding: 30px 20px;\r\n            border-radius: 20px;\r\n            transition: transform 0.3s;\r\n        }\r\n        \r\n        .lp-earning-card:hover {\r\n            transform: translateY(-5px);\r\n        }\r\n        \r\n        .lp-earning-icon {\r\n            font-size: 2.5rem;\r\n            margin-bottom: 15px;\r\n        }\r\n        \r\n        .lp-earning-title {\r\n            font-weight: 700;\r\n            color: var(--dark);\r\n            margin-bottom: 8px;\r\n        }\r\n        \r\n        .lp-earning-price {\r\n            font-size: 1.4rem;\r\n            font-weight: 800;\r\n            color: var(--creative-purple);\r\n            margin-bottom: 5px;\r\n        }\r\n        \r\n        .lp-earning-note {\r\n            font-size: 0.85rem;\r\n            color: var(--gray);\r\n        }\r\n        \r\n        /* ===== FORM SECTION ===== */\r\n        .lp-form-section {\r\n            padding: 60px 30px;\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n        }\r\n        \r\n        .lp-form-container {\r\n            max-width: 500px;\r\n            margin: 0 auto;\r\n        }\r\n        \r\n        .lp-form-card {\r\n            background: white;\r\n            border-radius: 24px;\r\n            overflow: hidden;\r\n            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);\r\n        }\r\n        \r\n        .lp-form-header {\r\n            background: linear-gradient(135deg, var(--accent-orange), var(--dark-orange));\r\n            padding: 30px;\r\n            text-align: center;\r\n            color: white;\r\n        }\r\n        \r\n        .lp-form-header h2 {\r\n            font-size: 1.6rem;\r\n            margin-bottom: 8px;\r\n        }\r\n        \r\n        .lp-form-header p {\r\n            opacity: 0.95;\r\n        }\r\n        \r\n        .lp-form {\r\n            padding: 35px;\r\n            display: flex;\r\n            flex-direction: column;\r\n            gap: 18px;\r\n        }\r\n        \r\n        .lp-form input,\r\n        .lp-form select {\r\n            padding: 16px 20px;\r\n            border: 2px solid #e0e0e0;\r\n            border-radius: 12px;\r\n            font-size: 1rem;\r\n            font-family: inherit;\r\n            transition: all 0.3s;\r\n        }\r\n        \r\n        .lp-form input:focus,\r\n        .lp-form select:focus {\r\n            outline: none;\r\n            border-color: var(--creative-purple);\r\n            box-shadow: 0 0 0 4px rgba(123, 31, 162, 0.1);\r\n        }\r\n        \r\n        .lp-form button {\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n            color: white;\r\n            border: none;\r\n            padding: 18px;\r\n            border-radius: 12px;\r\n            font-size: 1.1rem;\r\n            font-weight: 700;\r\n            cursor: pointer;\r\n            transition: all 0.3s;\r\n        }\r\n        \r\n        .lp-form button:hover {\r\n            transform: translateY(-3px);\r\n            box-shadow: 0 12px 35px rgba(123, 31, 162, 0.4);\r\n        }\r\n        \r\n        .lp-form-footer {\r\n            text-align: center;\r\n            padding: 0 35px 25px;\r\n            color: var(--gray);\r\n            font-size: 0.85rem;\r\n        }\r\n        \r\n        .lp-form-or {\r\n            text-align: center;\r\n            padding: 10px 35px;\r\n            color: var(--gray);\r\n            font-size: 0.9rem;\r\n        }\r\n        \r\n        .lp-whatsapp-btn {\r\n            display: block;\r\n            margin: 0 35px 25px;\r\n            background: #25D366;\r\n            color: white;\r\n            text-decoration: none;\r\n            padding: 16px;\r\n            border-radius: 12px;\r\n            text-align: center;\r\n            font-weight: 600;\r\n            font-size: 1rem;\r\n            transition: background 0.3s;\r\n        }\r\n        \r\n        .lp-whatsapp-btn:hover {\r\n            background: #128C7E;\r\n        }\r\n        \r\n        .lp-success {\r\n            display: none;\r\n            text-align: center;\r\n            padding: 50px 35px;\r\n        }\r\n        \r\n        .lp-success.show {\r\n            display: block;\r\n        }\r\n        \r\n        .lp-success-icon {\r\n            font-size: 4rem;\r\n            margin-bottom: 20px;\r\n        }\r\n        \r\n        .lp-success h3 {\r\n            color: var(--creative-purple);\r\n            margin-bottom: 10px;\r\n        }\r\n        \r\n        /* ===== CURRICULUM SECTION ===== */\r\n        .lp-curriculum {\r\n            padding: 70px 30px;\r\n            background: var(--off-white);\r\n        }\r\n        \r\n        .lp-curriculum-container {\r\n            max-width: 900px;\r\n            margin: 0 auto;\r\n        }\r\n        \r\n        .lp-curriculum h2 {\r\n            text-align: center;\r\n            font-size: 2rem;\r\n            margin-bottom: 40px;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        .lp-curriculum h2 span {\r\n            color: var(--creative-purple);\r\n        }\r\n        \r\n        .lp-curriculum-grid {\r\n            display: grid;\r\n            grid-template-columns: repeat(2, 1fr);\r\n            gap: 25px;\r\n        }\r\n        \r\n        .lp-curriculum-item {\r\n            display: flex;\r\n            gap: 15px;\r\n            padding: 25px;\r\n            background: white;\r\n            border-radius: 16px;\r\n            box-shadow: 0 5px 20px rgba(0,0,0,0.05);\r\n            transition: all 0.3s;\r\n            border-left: 4px solid var(--creative-purple);\r\n        }\r\n        \r\n        .lp-curriculum-item:hover {\r\n            transform: translateY(-5px);\r\n            box-shadow: 0 10px 30px rgba(123, 31, 162, 0.15);\r\n        }\r\n        \r\n        .lp-curriculum-week {\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n            color: white;\r\n            width: 50px;\r\n            height: 50px;\r\n            border-radius: 12px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            font-weight: 700;\r\n            flex-shrink: 0;\r\n        }\r\n        \r\n        .lp-curriculum-content h4 {\r\n            font-size: 1.1rem;\r\n            margin-bottom: 5px;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        .lp-curriculum-content p {\r\n            color: var(--gray);\r\n            font-size: 0.9rem;\r\n        }\r\n        \r\n        /* ===== TESTIMONIAL ===== */\r\n        .lp-testimonial {\r\n            padding: 60px 30px;\r\n            background: white;\r\n        }\r\n        \r\n        .lp-testimonial-container {\r\n            max-width: 700px;\r\n            margin: 0 auto;\r\n            text-align: center;\r\n        }\r\n        \r\n        .lp-testimonial-quote {\r\n            font-size: 1.2rem;\r\n            font-style: italic;\r\n            color: var(--dark);\r\n            margin-bottom: 25px;\r\n            position: relative;\r\n            padding: 0 20px;\r\n        }\r\n        \r\n        .lp-testimonial-quote::before {\r\n            content: ''"'';\r\n            font-size: 4rem;\r\n            color: var(--creative-purple);\r\n            opacity: 0.3;\r\n            position: absolute;\r\n            top: -20px;\r\n            left: 0;\r\n        }\r\n        \r\n        .lp-testimonial-author {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            gap: 15px;\r\n        }\r\n        \r\n        .lp-testimonial-avatar {\r\n            width: 60px;\r\n            height: 60px;\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n            border-radius: 50%;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            color: white;\r\n            font-weight: 700;\r\n        }\r\n        \r\n        .lp-testimonial-info h4 {\r\n            color: var(--dark);\r\n            margin-bottom: 2px;\r\n        }\r\n        \r\n        .lp-testimonial-info span {\r\n            color: var(--gray);\r\n            font-size: 0.9rem;\r\n        }\r\n        \r\n        /* ===== FAQ SECTION ===== */\r\n        .lp-faq {\r\n            padding: 60px 30px;\r\n            background: linear-gradient(135deg, #f3e5f5, #fce4ec);\r\n        }\r\n        \r\n        .lp-faq-container {\r\n            max-width: 700px;\r\n            margin: 0 auto;\r\n        }\r\n        \r\n        .lp-faq h2 {\r\n            text-align: center;\r\n            font-size: 1.8rem;\r\n            margin-bottom: 30px;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        .lp-faq-item {\r\n            background: white;\r\n            border-radius: 12px;\r\n            margin-bottom: 15px;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        .lp-faq-question {\r\n            padding: 20px;\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n            cursor: pointer;\r\n            font-weight: 600;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        .lp-faq-icon {\r\n            width: 28px;\r\n            height: 28px;\r\n            background: var(--creative-purple);\r\n            border-radius: 50%;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            color: white;\r\n            font-size: 1.2rem;\r\n            transition: transform 0.3s;\r\n        }\r\n        \r\n        .lp-faq-item.active .lp-faq-icon {\r\n            transform: rotate(45deg);\r\n        }\r\n        \r\n        .lp-faq-answer {\r\n            max-height: 0;\r\n            overflow: hidden;\r\n            transition: max-height 0.3s;\r\n        }\r\n        \r\n        .lp-faq-item.active .lp-faq-answer {\r\n            max-height: 200px;\r\n        }\r\n        \r\n        .lp-faq-answer p {\r\n            padding: 0 20px 20px;\r\n            color: var(--gray);\r\n        }\r\n        \r\n        /* ===== URGENCY BAR ===== */\r\n        .lp-urgency {\r\n            background: var(--accent-orange);\r\n            color: white;\r\n            text-align: center;\r\n            padding: 15px 30px;\r\n            font-weight: 600;\r\n        }\r\n        \r\n        .lp-urgency span {\r\n            background: rgba(255,255,255,0.2);\r\n            padding: 5px 12px;\r\n            border-radius: 20px;\r\n            margin-left: 10px;\r\n        }\r\n        \r\n        /* ===== FOOTER CTA ===== */\r\n        .lp-footer-cta {\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n            padding: 50px 30px;\r\n            text-align: center;\r\n            color: white;\r\n        }\r\n        \r\n        .lp-footer-cta h3 {\r\n            font-size: 1.8rem;\r\n            margin-bottom: 20px;\r\n        }\r\n        \r\n        .lp-footer-cta-buttons {\r\n            display: flex;\r\n            justify-content: center;\r\n            gap: 15px;\r\n            flex-wrap: wrap;\r\n        }\r\n        \r\n        .lp-btn {\r\n            display: inline-flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            padding: 16px 30px;\r\n            border-radius: 50px;\r\n            font-weight: 600;\r\n            font-size: 1rem;\r\n            text-decoration: none;\r\n            transition: all 0.3s;\r\n        }\r\n        \r\n        .lp-btn-primary {\r\n            background: var(--accent-orange);\r\n            color: white;\r\n        }\r\n        \r\n        .lp-btn-primary:hover {\r\n            transform: translateY(-3px);\r\n            box-shadow: 0 10px 30px rgba(255, 152, 0, 0.4);\r\n        }\r\n        \r\n        .lp-btn-outline {\r\n            background: transparent;\r\n            color: white;\r\n            border: 2px solid white;\r\n        }\r\n        \r\n        .lp-btn-outline:hover {\r\n            background: white;\r\n            color: var(--creative-purple);\r\n        }\r\n        \r\n        /* ===== FOOTER ===== */\r\n        .lp-footer {\r\n            background: var(--dark);\r\n            color: rgba(255,255,255,0.7);\r\n            text-align: center;\r\n            padding: 25px;\r\n            font-size: 0.9rem;\r\n        }\r\n        \r\n        /* ===== STICKY MOBILE CTA ===== */\r\n        .lp-sticky-cta {\r\n            display: none;\r\n            position: fixed;\r\n            bottom: 0;\r\n            left: 0;\r\n            right: 0;\r\n            background: #25D366;\r\n            padding: 15px 20px;\r\n            z-index: 1000;\r\n            box-shadow: 0 -4px 20px rgba(0,0,0,0.2);\r\n        }\r\n        \r\n        .lp-sticky-cta a {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            gap: 10px;\r\n            color: white;\r\n            text-decoration: none;\r\n            font-weight: 600;\r\n            font-size: 1rem;\r\n        }\r\n        \r\n        /* ===== RESPONSIVE ===== */\r\n        @media (max-width: 768px) {\r\n            .lp-hero h1 { font-size: 2rem; }\r\n            .lp-hero p { font-size: 1rem; }\r\n            .lp-highlights { gap: 15px; }\r\n            .lp-highlight { padding: 10px 15px; font-size: 0.9rem; }\r\n            .lp-earnings-grid { grid-template-columns: 1fr; }\r\n            .lp-curriculum-grid { grid-template-columns: 1fr; }\r\n            .lp-social-proof { gap: 20px; }\r\n            .lp-sticky-cta { display: block; }\r\n            body { padding-bottom: 70px; }\r\n            .lp-phone { display: none; }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <!-- Minimal Header -->\r\n    <header class="lp-header">\r\n        <a href="/" class="lp-logo">\r\n            <div class="lp-logo-icon">MT</div>\r\n            <div class="lp-logo-text">M.T.T.I</div>\r\n        </a>\r\n        <a href="tel:+254712464936" class="lp-phone">\r\n            📞 +254 712 464 936\r\n        </a>\r\n    </header>\r\n    \r\n    <!-- Urgency Bar -->\r\n    <div class="lp-urgency">\r\n        🔥 February Intake Now Open! <span>Only 12 Slots Left</span>\r\n    </div>\r\n    \r\n    <!-- Hero Section -->\r\n    <section class="lp-hero">\r\n        <div class="lp-hero-content">\r\n            <div class="lp-badge">🎓 TVETA Accredited</div>\r\n            <h1>Become a <span>Graphic Designer</span> in Just 8 Weeks</h1>\r\n            <p>Master Photoshop, Illustrator & brand design. Start earning KES 30,000 - 100,000/month as a freelancer or get employed.</p>\r\n            \r\n            <div class="lp-highlights">\r\n                <div class="lp-highlight">\r\n                    <span class="lp-highlight-icon">⏱️</span>\r\n                    <span>8 Weeks</span>\r\n                </div>\r\n                <div class="lp-highlight">\r\n                    <span class="lp-highlight-icon">💰</span>\r\n                    <span>KES 12,000</span>\r\n                </div>\r\n                <div class="lp-highlight">\r\n                    <span class="lp-highlight-icon">💼</span>\r\n                    <span>Portfolio Included</span>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n    \r\n    <!-- Social Proof Bar -->\r\n    <section class="lp-social-proof">\r\n        <div class="lp-proof-item">\r\n            <span>🎓</span>\r\n            <span><strong>50+</strong> Designers Trained</span>\r\n        </div>\r\n        <div class="lp-proof-item">\r\n            <span>💼</span>\r\n            <span><strong>85%</strong> Now Earning</span>\r\n        </div>\r\n        <div class="lp-proof-item">\r\n            <span>⭐</span>\r\n            <span><strong>4.9/5</strong> Student Rating</span>\r\n        </div>\r\n    </section>\r\n    \r\n    <!-- Video Section -->\r\n    <section class="lp-video-section">\r\n        <div class="lp-video-container">\r\n            <div class="lp-video-header">\r\n                <h2>Watch: What You''ll <span>Learn</span></h2>\r\n            </div>\r\n            <div class="lp-video-wrapper">\r\n                <video class="lp-video" id="lpVideo" poster="" muted playsinline preload="metadata">\r\n                    <source src="https://masomoteletraining.co.ke/wp-content/uploads/2026/02/Web-English.mp4" type="video/mp4">\r\n                </video>\r\n                <div class="lp-video-overlay" id="lpVideoOverlay" onclick="playLPVideo()">\r\n                    <div class="lp-play-btn">\r\n                        <svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>\r\n                    </div>\r\n                    <span class="lp-video-label">▶ Watch Course Preview</span>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n    \r\n    <!-- Earnings Potential Section -->\r\n    <section class="lp-earnings">\r\n        <div class="lp-earnings-container">\r\n            <h2>Start <span>Earning</span> With These Skills</h2>\r\n            \r\n            <div class="lp-earnings-grid">\r\n                <div class="lp-earning-card">\r\n                    <div class="lp-earning-icon">🎨</div>\r\n                    <div class="lp-earning-title">Logo Design</div>\r\n                    <div class="lp-earning-price">KES 3,000 - 15,000</div>\r\n                    <div class="lp-earning-note">per logo</div>\r\n                </div>\r\n                <div class="lp-earning-card">\r\n                    <div class="lp-earning-icon">📱</div>\r\n                    <div class="lp-earning-title">Social Media Graphics</div>\r\n                    <div class="lp-earning-price">KES 500 - 2,000</div>\r\n                    <div class="lp-earning-note">per post</div>\r\n                </div>\r\n                <div class="lp-earning-card">\r\n                    <div class="lp-earning-icon">🏢</div>\r\n                    <div class="lp-earning-title">Brand Identity</div>\r\n                    <div class="lp-earning-price">KES 20,000 - 50,000</div>\r\n                    <div class="lp-earning-note">per project</div>\r\n                </div>\r\n                <div class="lp-earning-card">\r\n                    <div class="lp-earning-icon">📄</div>\r\n                    <div class="lp-earning-title">Flyers & Posters</div>\r\n                    <div class="lp-earning-price">KES 1,000 - 5,000</div>\r\n                    <div class="lp-earning-note">per design</div>\r\n                </div>\r\n                <div class="lp-earning-card">\r\n                    <div class="lp-earning-icon">👔</div>\r\n                    <div class="lp-earning-title">Business Cards</div>\r\n                    <div class="lp-earning-price">KES 1,500 - 3,000</div>\r\n                    <div class="lp-earning-note">per design</div>\r\n                </div>\r\n                <div class="lp-earning-card">\r\n                    <div class="lp-earning-icon">📦</div>\r\n                    <div class="lp-earning-title">Packaging Design</div>\r\n                    <div class="lp-earning-price">KES 10,000 - 30,000</div>\r\n                    <div class="lp-earning-note">per project</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n    \r\n    <!-- Lead Capture Form -->\r\n    <section class="lp-form-section" id="enroll">\r\n        <div class="lp-form-container">\r\n            <div class="lp-form-card">\r\n                <div class="lp-form-header">\r\n                    <h2>🎁 Get 10% OFF Today!</h2>\r\n                    <p>Fill the form & we''ll call you within 24 hours</p>\r\n                </div>\r\n                \r\n                <form class="lp-form" id="lpForm" onsubmit="submitLPForm(event)">\r\n                    <input type="text" name="name" placeholder="Your Full Name" required>\r\n                    <input type="tel" name="phone" placeholder="Phone Number (07XX XXX XXX)" required>\r\n                    <input type="text" name="location" placeholder="Your Town/Area">\r\n                    <input type="hidden" name="course" value="Graphic Design">\r\n                    <button type="submit">🎨 Start My Design Career</button>\r\n                </form>\r\n                \r\n                <div class="lp-form-or">— OR —</div>\r\n                \r\n                <a href="https://wa.me/254712464936?text=Hello%20M.T.T.I,%20I''m%20interested%20in%20the%20Graphic%20Design%20course.%20Please%20send%20me%20more%20information." \r\n                   class="lp-whatsapp-btn" target="_blank" onclick="trackWhatsAppClick()">\r\n                    💬 Chat on WhatsApp Now\r\n                </a>\r\n                \r\n                <div class="lp-form-footer">\r\n                    🔒 We respect your privacy. No spam, ever.\r\n                </div>\r\n                \r\n                <div class="lp-success" id="lpSuccess">\r\n                    <div class="lp-success-icon">🎉</div>\r\n                    <h3>Thank You!</h3>\r\n                    <p>We''ll call you within 24 hours to discuss your enrollment and discount.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n    \r\n    <!-- Curriculum Section -->\r\n    <section class="lp-curriculum">\r\n        <div class="lp-curriculum-container">\r\n            <h2>What You''ll <span>Learn</span> (8 Weeks)</h2>\r\n            \r\n            <div class="lp-curriculum-grid">\r\n                <div class="lp-curriculum-item">\r\n                    <div class="lp-curriculum-week">1-2</div>\r\n                    <div class="lp-curriculum-content">\r\n                        <h4>Adobe Photoshop Mastery</h4>\r\n                        <p>Photo editing, manipulation, retouching, and social media graphics</p>\r\n                    </div>\r\n                </div>\r\n                <div class="lp-curriculum-item">\r\n                    <div class="lp-curriculum-week">3-4</div>\r\n                    <div class="lp-curriculum-content">\r\n                        <h4>Adobe Illustrator</h4>\r\n                        <p>Vector graphics, logo design, illustrations, and scalable artwork</p>\r\n                    </div>\r\n                </div>\r\n                <div class="lp-curriculum-item">\r\n                    <div class="lp-curriculum-week">5-6</div>\r\n                    <div class="lp-curriculum-content">\r\n                        <h4>Brand Identity Design</h4>\r\n                        <p>Creating complete brand packages: logos, colors, typography, guidelines</p>\r\n                    </div>\r\n                </div>\r\n                <div class="lp-curriculum-item">\r\n                    <div class="lp-curriculum-week">7-8</div>\r\n                    <div class="lp-curriculum-content">\r\n                        <h4>Portfolio & Business</h4>\r\n                        <p>Build your portfolio, pricing strategies, finding clients, freelancing tips</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n    \r\n    <!-- Testimonial -->\r\n    <section class="lp-testimonial">\r\n        <div class="lp-testimonial-container">\r\n            <p class="lp-testimonial-quote">\r\n                I joined MTTI with zero design experience. After 8 weeks, I designed my first logo for a real client and got paid KES 5,000! Now I have a steady stream of clients from social media. This course changed my life.\r\n            </p>\r\n            <div class="lp-testimonial-author">\r\n                <div class="lp-testimonial-avatar">AM</div>\r\n                <div class="lp-testimonial-info">\r\n                    <h4>Ann Muthoni</h4>\r\n                    <span>Graphic Design Graduate, Now Freelancer</span>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n    \r\n    <!-- FAQ Section -->\r\n    <section class="lp-faq">\r\n        <div class="lp-faq-container">\r\n            <h2>Common Questions</h2>\r\n            \r\n            <div class="lp-faq-item">\r\n                <div class="lp-faq-question" onclick="toggleFAQ(this)">\r\n                    <span>Do I need any design experience?</span>\r\n                    <div class="lp-faq-icon">+</div>\r\n                </div>\r\n                <div class="lp-faq-answer">\r\n                    <p>No! We start from zero. Many of our successful graduates had never used Photoshop before joining.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class="lp-faq-item">\r\n                <div class="lp-faq-question" onclick="toggleFAQ(this)">\r\n                    <span>Do I need my own laptop?</span>\r\n                    <div class="lp-faq-icon">+</div>\r\n                </div>\r\n                <div class="lp-faq-answer">\r\n                    <p>No! We provide all computers with Adobe software installed. Just come ready to learn.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class="lp-faq-item">\r\n                <div class="lp-faq-question" onclick="toggleFAQ(this)">\r\n                    <span>Can I pay in installments?</span>\r\n                    <div class="lp-faq-icon">+</div>\r\n                </div>\r\n                <div class="lp-faq-answer">\r\n                    <p>Yes! Pay a deposit to start, then complete the balance in weekly or monthly installments.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class="lp-faq-item">\r\n                <div class="lp-faq-question" onclick="toggleFAQ(this)">\r\n                    <span>Will I get a certificate?</span>\r\n                    <div class="lp-faq-icon">+</div>\r\n                </div>\r\n                <div class="lp-faq-answer">\r\n                    <p>Yes! You''ll receive a TVETA-accredited certificate recognized by employers across Kenya.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n    \r\n    <!-- Footer CTA -->\r\n    <section class="lp-footer-cta">\r\n        <h3>Ready to Become a Graphic Designer?</h3>\r\n        <div class="lp-footer-cta-buttons">\r\n            <a href="#enroll" class="lp-btn lp-btn-primary">\r\n                🎨 Enroll Now - Get 10% OFF\r\n            </a>\r\n            <a href="tel:+254712464936" class="lp-btn lp-btn-outline">\r\n                📞 Call Us\r\n            </a>\r\n        </div>\r\n    </section>\r\n    \r\n    <!-- Footer -->\r\n    <footer class="lp-footer">\r\n        <p>© 2026 Masomotele Technical Training Institute | Sagaas Center, 4th Floor, Eldoret</p>\r\n    </footer>\r\n    \r\n    <!-- Sticky Mobile CTA -->\r\n    <div class="lp-sticky-cta">\r\n        <a href="https://wa.me/254712464936?text=Hello%20M.T.T.I,%20I''m%20interested%20in%20the%20Graphic%20Design%20course.%20Please%20send%20me%20more%20information." target="_blank">\r\n            💬 Chat on WhatsApp - Graphic Design\r\n        </a>\r\n    </div>\r\n    \r\n    <!-- JavaScript -->\r\n    <script>\r\n        // Video Player\r\n        function playLPVideo() {\r\n            var video = document.getElementById(''lpVideo'');\r\n            var overlay = document.getElementById(''lpVideoOverlay'');\r\n            video.muted = false;\r\n            video.play();\r\n            overlay.classList.add(''hidden'');\r\n            video.addEventListener(''ended'', function() {\r\n                overlay.classList.remove(''hidden'');\r\n            });\r\n            \r\n            trackEvent(''Video'', ''play'', ''graphic_design_preview'');\r\n        }\r\n        \r\n        // FAQ Toggle\r\n        function toggleFAQ(element) {\r\n            var item = element.parentElement;\r\n            var isActive = item.classList.contains(''active'');\r\n            \r\n            document.querySelectorAll(''.lp-faq-item'').forEach(function(faq) {\r\n                faq.classList.remove(''active'');\r\n            });\r\n            \r\n            if (!isActive) {\r\n                item.classList.add(''active'');\r\n            }\r\n        }\r\n        \r\n        // Form Submission\r\n        function submitLPForm(e) {\r\n            e.preventDefault();\r\n            var form = e.target;\r\n            var data = {\r\n                name: form.name.value,\r\n                phone: form.phone.value,\r\n                location: form.location.value,\r\n                course: form.course.value,\r\n                source: ''landing_page'',\r\n                utm: JSON.parse(sessionStorage.getItem(''mtti_utm'') || ''{}''),\r\n                timestamp: new Date().toISOString(),\r\n                page: ''/graphic-design''\r\n            };\r\n            \r\n            // Track conversion\r\n            trackEvent(''Lead'', ''captured'', ''graphic_design_landing'');\r\n            if (typeof fbq === ''function'') {\r\n                fbq(''track'', ''Lead'', { \r\n                    content_name: ''Graphic Design'',\r\n                    content_category: ''landing_page'',\r\n                    value: 12000,\r\n                    currency: ''KES''\r\n                });\r\n            }\r\n            \r\n            // Send to backend\r\n            sendToSheet(data);\r\n            \r\n            // Show success\r\n            form.style.display = ''none'';\r\n            document.querySelector(''.lp-form-or'').style.display = ''none'';\r\n            document.querySelector(''.lp-whatsapp-btn'').style.display = ''none'';\r\n            document.getElementById(''lpSuccess'').classList.add(''show'');\r\n        }\r\n        \r\n        // Send to Google Sheets\r\n        function sendToSheet(data) {\r\n            console.log(''📝 Lead captured:'', data);\r\n            \r\n            // Store locally as backup\r\n            var leads = JSON.parse(localStorage.getItem(''mtti_leads'') || ''[]'');\r\n            leads.push(data);\r\n            localStorage.setItem(''mtti_leads'', JSON.stringify(leads));\r\n            \r\n            // Replace with your Google Apps Script Web App URL\r\n            var sheetURL = ''https://script.google.com/macros/s/YOUR_SCRIPT_ID/exec'';\r\n            \r\n            fetch(sheetURL, {\r\n                method: ''POST'',\r\n                mode: ''no-cors'',\r\n                headers: { ''Content-Type'': ''application/json'' },\r\n                body: JSON.stringify(data)\r\n            }).catch(function(err) {\r\n                console.log(''Sheet submission queued'');\r\n            });\r\n        }\r\n        \r\n        // Track WhatsApp clicks\r\n        function trackWhatsAppClick() {\r\n            trackEvent(''WhatsApp'', ''click'', ''graphic_design_landing'');\r\n            if (typeof fbq === ''function'') {\r\n                fbq(''track'', ''Contact'', { content_name: ''Graphic Design'' });\r\n            }\r\n        }\r\n        \r\n        // Smooth scroll to form\r\n        document.querySelectorAll(''a[href="#enroll"]'').forEach(function(link) {\r\n            link.addEventListener(''click'', function(e) {\r\n                e.preventDefault();\r\n                document.querySelector(''.lp-form-section'').scrollIntoView({ behavior: ''smooth'' });\r\n            });\r\n        });\r\n    </script>\r\n</body>\r\n</html>\r\n', 'Graphic Design', '', 'trash', 'closed', 'closed', '', 'graphic-design-4__trashed-3', '', '', '2026-02-02 22:32:29', '2026-02-02 22:32:29', '', 0, 'https://masomoteletraining.co.ke/?page_id=1951', 0, 'page', '', 0),
(1952, 1, '2026-02-02 22:28:51', '2026-02-02 22:28:51', '<!DOCTYPE html>\r\n<html lang="en">\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\r\n    <title>Learn Graphic Design in 8 Weeks | M.T.T.I Eldoret - TVETA Accredited</title>\r\n    <meta name="description" content="Corel Draw, Canva & brand design in just 8 weeks. TVETA certified, hands-on training. Start earning KES 50,000+/month as a designer. Enroll now!">\r\n    \r\n    <!-- Open Graph for Social Sharing -->\r\n    <meta property="og:title" content="Learn Graphic Design in 8 Weeks | M.T.T.I Eldoret">\r\n    <meta property="og:description" content="Corel Draw & Canva. Start earning as a freelance designer. TVETA certified. Only KES 12,000.">\r\n    <meta property="og:image" content="https://masomoteletraining.co.ke/wp-content/uploads/2026/02/graphic-design-og.jpg">\r\n    <meta property="og:url" content="https://masomoteletraining.co.ke/graphic-design/">\r\n    <meta property="og:type" content="website">\r\n    \r\n    <!-- Google Analytics with UTM Tracking -->\r\n    <script async src="https://www.googletagmanager.com/gtag/js?id=G-8ZEH42CBVL"></script>\r\n    <script>\r\n      window.dataLayer = window.dataLayer || [];\r\n      function gtag(){dataLayer.push(arguments);}\r\n      gtag(''js'', new Date());\r\n      gtag(''config'', ''G-8ZEH42CBVL'');\r\n      \r\n      // UTM Parameter Tracking\r\n      function getUTMParams() {\r\n        var params = new URLSearchParams(window.location.search);\r\n        return {\r\n          utm_source: params.get(''utm_source'') || ''direct'',\r\n          utm_medium: params.get(''utm_medium'') || ''none'',\r\n          utm_campaign: params.get(''utm_campaign'') || ''none'',\r\n          utm_content: params.get(''utm_content'') || ''none'',\r\n          utm_term: params.get(''utm_term'') || ''none'',\r\n          landing_page: ''graphic-design''\r\n        };\r\n      }\r\n      \r\n      var utmData = getUTMParams();\r\n      sessionStorage.setItem(''mtti_utm'', JSON.stringify(utmData));\r\n      console.log(''📊 Landing Page UTM:'', utmData);\r\n      \r\n      function trackEvent(category, action, label) {\r\n        gtag(''event'', action, {\r\n          ''event_category'': category,\r\n          ''event_label'': label,\r\n          ''utm_source'': utmData.utm_source,\r\n          ''utm_campaign'': utmData.utm_campaign\r\n        });\r\n      }\r\n    </script>\r\n    \r\n    <!-- Meta Pixel (Facebook & Instagram) -->\r\n    <script>\r\n      !function(f,b,e,v,n,t,s)\r\n      {if(f.fbq)return;n=f.fbq=function(){n.callMethod?\r\n      n.callMethod.apply(n,arguments):n.queue.push(arguments)};\r\n      if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version=''2.0'';\r\n      n.queue=[];t=b.createElement(e);t.async=!0;\r\n      t.src=v;s=b.getElementsByTagName(e)[0];\r\n      s.parentNode.insertBefore(t,s)}(window, document,''script'',\r\n      ''https://connect.facebook.net/en_US/fbevents.js'');\r\n      fbq(''init'', ''893318556963600'');\r\n      fbq(''track'', ''PageView'');\r\n      fbq(''track'', ''ViewContent'', {\r\n        content_name: ''Graphic Design Course'',\r\n        content_category: ''landing_page'',\r\n        value: 12000,\r\n        currency: ''KES''\r\n      });\r\n    </script>\r\n    \r\n    <link rel="preconnect" href="https://fonts.googleapis.com">\r\n    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">\r\n    \r\n    <style>\r\n        :root {\r\n            --primary-green: #2E7D32;\r\n            --dark-green: #1B5E20;\r\n            --light-green: #4CAF50;\r\n            --accent-orange: #FF9800;\r\n            --dark-orange: #F57C00;\r\n            --creative-purple: #7B1FA2;\r\n            --creative-pink: #E91E63;\r\n            --white: #ffffff;\r\n            --off-white: #f8f9fa;\r\n            --dark: #1a1a2e;\r\n            --gray: #666;\r\n        }\r\n        \r\n        * { margin: 0; padding: 0; box-sizing: border-box; }\r\n        \r\n        body {\r\n            font-family: ''Poppins'', sans-serif;\r\n            line-height: 1.7;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        /* ===== MINIMAL HEADER ===== */\r\n        .lp-header {\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n            padding: 15px 30px;\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n        }\r\n        \r\n        .lp-logo {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            text-decoration: none;\r\n        }\r\n        \r\n        .lp-logo-icon {\r\n            width: 45px;\r\n            height: 45px;\r\n            background: var(--accent-orange);\r\n            border-radius: 10px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            font-weight: 800;\r\n            font-size: 1rem;\r\n            color: white;\r\n        }\r\n        \r\n        .lp-logo-text {\r\n            color: white;\r\n            font-size: 1.2rem;\r\n            font-weight: 700;\r\n        }\r\n        \r\n        .lp-phone {\r\n            color: white;\r\n            text-decoration: none;\r\n            font-weight: 600;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n        }\r\n        \r\n        /* ===== HERO SECTION ===== */\r\n        .lp-hero {\r\n            background: linear-gradient(135deg, var(--creative-purple) 0%, var(--creative-pink) 50%, var(--dark-orange) 100%);\r\n            padding: 60px 30px 80px;\r\n            text-align: center;\r\n            color: white;\r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        .lp-hero::before {\r\n            content: '''';\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            right: 0;\r\n            bottom: 0;\r\n            background: url("data:image/svg+xml,%3Csvg width=''60'' height=''60'' viewBox=''0 0 60 60'' xmlns=''http://www.w3.org/2000/svg''%3E%3Cg fill=''none'' fill-rule=''evenodd''%3E%3Cg fill=''%23ffffff'' fill-opacity=''0.05''%3E%3Cpath d=''M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z''/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");\r\n        }\r\n        \r\n        .lp-hero-content {\r\n            position: relative;\r\n            z-index: 1;\r\n            max-width: 800px;\r\n            margin: 0 auto;\r\n        }\r\n        \r\n        .lp-badge {\r\n            display: inline-block;\r\n            background: var(--accent-orange);\r\n            padding: 8px 20px;\r\n            border-radius: 50px;\r\n            font-size: 0.9rem;\r\n            font-weight: 600;\r\n            margin-bottom: 25px;\r\n        }\r\n        \r\n        .lp-hero h1 {\r\n            font-size: 2.8rem;\r\n            font-weight: 800;\r\n            margin-bottom: 20px;\r\n            line-height: 1.2;\r\n        }\r\n        \r\n        .lp-hero h1 span {\r\n            color: var(--accent-orange);\r\n        }\r\n        \r\n        .lp-hero p {\r\n            font-size: 1.2rem;\r\n            opacity: 0.95;\r\n            margin-bottom: 30px;\r\n            max-width: 600px;\r\n            margin-left: auto;\r\n            margin-right: auto;\r\n        }\r\n        \r\n        .lp-highlights {\r\n            display: flex;\r\n            justify-content: center;\r\n            gap: 30px;\r\n            flex-wrap: wrap;\r\n            margin-top: 30px;\r\n        }\r\n        \r\n        .lp-highlight {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            background: rgba(255,255,255,0.15);\r\n            padding: 12px 20px;\r\n            border-radius: 50px;\r\n        }\r\n        \r\n        .lp-highlight-icon {\r\n            font-size: 1.3rem;\r\n        }\r\n        \r\n        /* ===== SOCIAL PROOF BAR ===== */\r\n        .lp-social-proof {\r\n            background: white;\r\n            padding: 20px 30px;\r\n            display: flex;\r\n            justify-content: center;\r\n            gap: 40px;\r\n            flex-wrap: wrap;\r\n            box-shadow: 0 4px 20px rgba(0,0,0,0.1);\r\n        }\r\n        \r\n        .lp-proof-item {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            font-size: 0.95rem;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        .lp-proof-item strong {\r\n            color: var(--creative-purple);\r\n        }\r\n        \r\n        /* ===== VIDEO SECTION ===== */\r\n        .lp-video-section {\r\n            padding: 60px 30px;\r\n            background: linear-gradient(135deg, #fce4ec, #f3e5f5);\r\n        }\r\n        \r\n        .lp-video-container {\r\n            max-width: 800px;\r\n            margin: 0 auto;\r\n        }\r\n        \r\n        .lp-video-header {\r\n            text-align: center;\r\n            margin-bottom: 30px;\r\n        }\r\n        \r\n        .lp-video-header h2 {\r\n            font-size: 1.8rem;\r\n            color: var(--dark);\r\n            margin-bottom: 10px;\r\n        }\r\n        \r\n        .lp-video-header h2 span {\r\n            color: var(--creative-purple);\r\n        }\r\n        \r\n        .lp-video-wrapper {\r\n            position: relative;\r\n            border-radius: 20px;\r\n            overflow: hidden;\r\n            box-shadow: 0 20px 60px rgba(123, 31, 162, 0.3);\r\n        }\r\n        \r\n        .lp-video {\r\n            width: 100%;\r\n            display: block;\r\n        }\r\n        \r\n        .lp-video-overlay {\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            right: 0;\r\n            bottom: 0;\r\n            background: linear-gradient(135deg, rgba(123, 31, 162, 0.6), rgba(233, 30, 99, 0.6));\r\n            display: flex;\r\n            flex-direction: column;\r\n            align-items: center;\r\n            justify-content: center;\r\n            cursor: pointer;\r\n            transition: background 0.3s;\r\n            gap: 15px;\r\n        }\r\n        \r\n        .lp-video-overlay:hover {\r\n            background: linear-gradient(135deg, rgba(123, 31, 162, 0.4), rgba(233, 30, 99, 0.4));\r\n        }\r\n        \r\n        .lp-video-overlay.hidden {\r\n            opacity: 0;\r\n            pointer-events: none;\r\n        }\r\n        \r\n        .lp-play-btn {\r\n            width: 80px;\r\n            height: 80px;\r\n            background: var(--accent-orange);\r\n            border-radius: 50%;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            box-shadow: 0 10px 40px rgba(255,152,0,0.5);\r\n            transition: transform 0.3s;\r\n        }\r\n        \r\n        .lp-play-btn:hover {\r\n            transform: scale(1.1);\r\n        }\r\n        \r\n        .lp-play-btn svg {\r\n            width: 30px;\r\n            height: 30px;\r\n            fill: white;\r\n            margin-left: 5px;\r\n        }\r\n        \r\n        .lp-video-label {\r\n            color: white;\r\n            font-weight: 600;\r\n            font-size: 1.1rem;\r\n            text-shadow: 0 2px 10px rgba(0,0,0,0.3);\r\n        }\r\n        \r\n        /* ===== EARNINGS SECTION ===== */\r\n        .lp-earnings {\r\n            padding: 60px 30px;\r\n            background: white;\r\n        }\r\n        \r\n        .lp-earnings-container {\r\n            max-width: 900px;\r\n            margin: 0 auto;\r\n            text-align: center;\r\n        }\r\n        \r\n        .lp-earnings h2 {\r\n            font-size: 2rem;\r\n            margin-bottom: 40px;\r\n            color: var(--dark);\r\n        }\r\n        \r\n        .lp-earnings h2 span {\r\n            color: var(--creative-purple);\r\n        }\r\n        \r\n        .lp-earnings-grid {\r\n            display: grid;\r\n            grid-template-columns: repeat(3, 1fr);\r\n            gap: 25px;\r\n        }\r\n        \r\n        .lp-earning-card {\r\n            background: linear-gradient(135deg, #f3e5f5, #fce4ec);\r\n            padding: 30px 20px;\r\n            border-radius: 20px;\r\n            transition: transform 0.3s;\r\n        }\r\n        \r\n        .lp-earning-card:hover {\r\n            transform: translateY(-5px);\r\n        }\r\n        \r\n        .lp-earning-icon {\r\n            font-size: 2.5rem;\r\n            margin-bottom: 15px;\r\n        }\r\n        \r\n        .lp-earning-title {\r\n            font-weight: 700;\r\n            color: var(--dark);\r\n            margin-bottom: 8px;\r\n        }\r\n        \r\n        .lp-earning-price {\r\n            font-size: 1.4rem;\r\n            font-weight: 800;\r\n            color: var(--creative-purple);\r\n            margin-bottom: 5px;\r\n        }\r\n        \r\n        .lp-earning-note {\r\n            font-size: 0.85rem;\r\n            color: var(--gray);\r\n        }\r\n        \r\n        /* ===== FORM SECTION ===== */\r\n        .lp-form-section {\r\n            padding: 60px 30px;\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n        }\r\n        \r\n        .lp-form-container {\r\n            max-width: 500px;\r\n            margin: 0 auto;\r\n        }\r\n        \r\n        .lp-form-card {\r\n            background: white;\r\n            border-radius: 24px;\r\n            overflow: hidden;\r\n            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);\r\n        }\r\n        \r\n        .lp-form-header {\r\n            background: linear-gradient(135deg, var(--accent-orange), var(--dark-orange));\r\n 