er-radius: 50%;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            color: white;\r\n            font-size: 1.2rem;\r\n            transition: transform 0.3s;\r\n        }\r\n        \r\n        .lp-faq-item.active .lp-faq-icon {\r\n            transform: rotate(45deg);\r\n        }\r\n        \r\n        .lp-faq-answer {\r\n            max-height: 0;\r\n            overflow: hidden;\r\n            transition: max-height 0.3s;\r\n        }\r\n        \r\n        .lp-faq-item.active .lp-faq-answer {\r\n            max-height: 200px;\r\n        }\r\n        \r\n        .lp-faq-answer p {\r\n            padding: 0 20px 20px;\r\n            color: var(--gray);\r\n        }\r\n        \r\n        /* ===== URGENCY BAR ===== */\r\n        .lp-urgency {\r\n            background: var(--accent-orange);\r\n            color: white;\r\n            text-align: center;\r\n            padding: 15px 30px;\r\n            font-weight: 600;\r\n        }\r\n        \r\n        .lp-urgency span {\r\n            background: rgba(255,255,255,0.2);\r\n            padding: 5px 12px;\r\n            border-radius: 20px;\r\n            margin-left: 10px;\r\n        }\r\n        \r\n        /* ===== FOOTER CTA ===== */\r\n        .lp-footer-cta {\r\n            background: linear-gradient(135deg, var(--creative-purple), var(--creative-pink));\r\n            padding: 50px 30px;\r\n            text-align: center;\r\n            color: white;\r\n        }\r\n        \r\n        .lp-footer-cta h3 {\r\n            font-size: 1.8rem;\r\n            margin-bottom: 20px;\r\n        }\r\n        \r\n        .lp-footer-cta-buttons {\r\n            display: flex;\r\n            justify-content: center;\r\n            gap: 15px;\r\n            flex-wrap: wrap;\r\n        }\r\n        \r\n        .lp-btn {\r\n            display: inline-flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            padding: 16px 30px;\