(41, 'Annual Function', 'The Annual Function will feature academic awards, cultural performances, and prize distribution ceremony for outstanding students.', NULL, '2025-12-20', 1, 2, NULL, '2025-09-22 16:53:10', '2025-09-22 16:53:10'),
(42, 'Art and Craft Exhibition', 'An exhibition of student artwork and craftwork. Students will display paintings, sculptures, handicrafts, and other creative works.', NULL, '2026-02-02', 1, 2, NULL, '2025-09-22 16:53:10', '2025-09-22 16:53:10'),
(43, 'Quiz Competition', 'An inter-class quiz competition covering various subjects including general knowledge, science, mathematics, and literature.', NULL, '2026-01-23', 1, 2, NULL, '2025-09-22 16:53:10', '2025-09-22 16:53:10'),
(44, 'Annual Function', 'The Annual Function will feature academic awards, cultural performances, and prize distribution ceremony for outstanding students.', NULL, '2026-03-12', 1, 2, NULL, '2025-09-22 16:53:10', '2025-09-22 16:53:10'),
(45, 'Career Guidance Seminar', 'A seminar on career guidance for senior students, featuring guest speakers from various professions sharing their experiences and advice.', NULL, '2026-01-05', 1, 2, NULL, '2025-09-22 16:53:10', '2025-09-22 16:53:10'),
(46, 'Cultural Program', 'A cultural program featuring dance, music, drama, and other performing arts. Students will present traditional and contemporary performances.', NULL, '2025-10-26', 1, 2, NULL, '2025-09-22 16:53:10', '2025-09-22 16:53:10'),
