INSERT INTO `wpcu_wlsm_notices` VALUES
(38, 'Identity Card Renewal', NULL, NULL, 'none', 1, 2, NULL, '2025-08-09 06:32:28', NULL, 'Students who have lost their identity cards or need renewal must apply at the administrative office with required documents and fee. New cards will be issued within 7 working days.', NULL),
(39, 'Library New Books Arrival', NULL, NULL, 'none', 1, 2, NULL, '2025-08-13 15:29:32', NULL, 'The school library has received new books in various subjects. Students are encouraged to visit the library and issue books for their academic and general reading.', NULL),
(40, 'Identity Card Renewal', NULL, NULL, 'none', 1, 2, NULL, '2025-08-21 05:46:00', NULL, 'Students who have lost their identity cards or need renewal must apply at the administrative office with required documents and fee. New cards will be issued within 7 working days.', NULL),
(41, 'Health and Safety Guidelines', NULL, NULL, 'attachment', 1, 2, NULL, '2025-06-25 09:51:26', NULL, 'In view of the current health situation, all students and staff are requested to follow the safety guidelines. Hand sanitizers are available throughout the campus.', NULL),
(42, 'Library New Books Arrival', NULL, NULL, 'none', 1, 2, NULL, '2025-09-29 00:24:37', NULL, 'The school library has received new books in various subjects. Students are encouraged to visit the library and issue books for their academic and general reading.', NULL),
(43, 'Health and Safety Guidelines', NULL, NULL, 'attachment', 1, 2, NULL, '2025-09-29 10:56:22', NULL, 'In view of the current health situation, all students and staff are requested to follow the safety guidelines. Hand sanitizers are available throughout the campus.', NULL),
(44, 'Identity Card Renewal', NULL, NULL, 'none', 1, 2, NULL, '2025-07-29 05:53:03', NULL, 'Students who have lost their identity cards or need renewal must apply at the administrative office with required documents and fee. New cards will be issued within 7 working days.', NULL),
(45, 'Bus Route Modification', NULL, NULL, 'attachment', 1, 2, NULL, '2025-09-05 19:04:44', NULL, 'Due to road construction work, Bus Route #3 will be temporarily modified from October 18, 2025. New pickup and drop points are listed in the attached schedule.', NULL),
(46, 'Educational Trip to Science Museum', NULL, NULL, 'attachment', 1, 2, NULL, '2025-08-28 09:57:50', NULL, 'An educational trip to the Science Museum has been organized for grades 8-10 on October 12, 2025. Interested students should register with their class teachers and submit the consent form.', NULL),
(47, 'Educational Trip to Science Museum', NULL, NULL, 'attachment', 1, 2, NULL, '2025-07-22 17:04:14', NULL, 'An educational trip to the Science Museum has been organized for grades 8-10 on October 13, 2025. Interested students should register with their class teachers and submit the consent form.', NULL),
(48, 'Annual Sports Day', NULL, 'https://school-portal.example.com/payments', 'url', 1, 2, NULL, '2025-10-11 07:19:40', NULL, 'The Annual Sports Day will be celebrated on September 30, 2025 at the school playground. All students are required to participate in various sporting events. Participation forms must be submitted by September 30, 2025.', NULL),
(49, 'Educational Trip to Science Museum', NULL, NULL, 'attachment', 1, 2, NULL, '2025-09-13 10:36:00', NULL, 'An educational trip to the Science Museum has been organized for grades 8-10 on October 2, 2025. Interested students should register with their class teachers and submit the consent form.', NULL),
(50, 'Science Project Exhibition', NULL, NULL, 'attachment', 1, 2, NULL, '2025-07-22 03:27:07', NULL, 'The annual Science Project Exhibition will be held on October 5, 2025. All students from grades 6-12 are encouraged to participate. Registration forms are available at the school office.', NULL),
(51, 'Identity Card Renewal', NULL, NULL, 'none', 1, 2, NULL, '2025-06-24 03:49:27', NULL, 'Students who have lost their identity cards or need renewal must apply at the administrative office with required documents and fee. New cards will be issued within 7 working days.', NULL),
(52, 'Inter-School Competition', NULL, 'https://school-portal.example.com/payments', 'url', 1, 2, NULL, '2025-09-05 00:17:07', NULL, 'Our school will participate in the Inter-School Academic Competition on October 8, 2025. Selected students will represent the school. Coaching sessions will be conducted in the coming weeks.', NULL),
(53, 'Library New Books Arrival', NULL, NULL, 'none', 1, 2, NULL, '2025-08-14 08:53:52', NULL, 'The school library has received new books in various subjects. Students are encouraged to visit the library and issue books for their academic and general reading.', NULL),
(54, 'Parent-Teacher Meeting', NULL, 'https://school-portal.example.com/forms', 'url', 1, 2, NULL, '2025-07-29 14:31:13', NULL, 'We are pleased to invite all parents for the Parent-Teacher Meeting scheduled on October 5, 2025. This is an important opportunity to discuss your child''s academic progress and performance. Please confirm your attendance.', NULL),
(55, 'Email', NULL, '', '', 1, 3, 1, '2025-09-28 06:39:11', NULL, 'All learners must have an email', 'a:3:{s:7:"classes";a:1:{i:0;s:1:"5";}s:8:"sections";a:0:{}s:8:"students";a:0:{}}'),
(56, 'MTTI', NULL, '', '', 1, 3, 1, '2025-10-05 07:16:07', NULL, 'Welcome to MTTI', 'a:3:{s:7:"classes";a:3:{i:0;s:1:"3";i:1;s:2:"30";i:2;s:2:"34";}s:8:"sections";a:0:{}s:8:"students";a:0:{}}');
